INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-denizhan-arici-aaln9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'beni sevebilme ihtimalindi

hayatı yaşanabilir kılan

seni sevebilmekti

beni özel yapan

ve seni kıskanmaktı belki

başımı belalara sokan

seni dile dökerdim

kurda kuşa semaya

anlatabilseydim eğer

seni avazım çıktığınca bağırırdım

denize dağa volkana 

haykırabilseydim eğer

seni her yere yazardım

dünyadaki tüm yüreklere

kalem olabilseydim eğer

seni hemen unuturdum

içimdeki adama

söz geçirebilseydim eğer

işte aşk böyle birşeydi

insana unuttururdu kendini

hayır sevmek tamda bu değildi

bu tam bir delilikti

yok öpüşmek aşk değildi

belki en tutkulu hevesti

üşümek zemheri değildi

üşümek gözlerini görememekti', 'beni sevebilme ihtimalindi hayatı yaşanabilir kılan seni sevebilmekti beni özel yapan ve seni kıskanmaktı belki başımı belalara sokan seni d...', ARRAY['Türk Edebiyatı','Şiir','Denizhan Arıcı']::text[], 8.5, '{"poet":"Denizhan Arıcı","poet_slug":"denizhan-arici","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-sevmek-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-erdal-tufenk-q0v6x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç geceler sensiz yattım,

Ne zaman gülecek benim bahtım,

Resmin bana ben resmine baktım,

Bugün yine hasrete hüzün kattım

      

                Gözlerim buğulu bayram arefesi,

                Yine kaderimde sensizlik tarifesi,

                Kulaklarımda çınlar çocukca sesi,

                Sen olmadan hayat boş,yalan gerisi.

Yanında olmak isterdim takat yok dizlerimde,

Haram oldu uyku gözlerimde,

Her anımda seni özlerim de,

Dualarım seninle,sen varsın her sözümde', 'Kaç geceler sensiz yattım, Ne zaman gülecek benim bahtım, Resmin bana ben resmine baktım, Bugün yine hasrete hüzün kattım                   ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Tüfenk']::text[], 8.5, '{"poet":"Erdal Tüfenk","poet_slug":"erdal-tufenk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/huzun-146-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunda Öldüm', 'yoklugunda-oldum-gul-yazganarikan-kwwb0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben ölmezdim de, 

Senin gözlerin vurdu beni,

Bilemedim nasıl vuruldum, 

Bir gözlerin oldum, gözlerim sen oldun

Bilemedim nasıl vuruldum,

Ben ölmezdim de,

Senin sözlerin vurdu beni,

En zehirli yılanların,

Karadulların, zehrine eşti sözlerin,

Felçliydim, dilsizdim, yatalaktım, 

Sana öyle tutsaktım,

Ben ölmezdim de,

Yokluğun öldürdü beni,

Ne gözlerinin açtığı yaralar,

Ne felç eden sözlerin,

Gidişin var ya ardına bakmadan,

Vefasız gidişin,

Adım adım, gittin... 

Yavaş yavaş

Adım adım öldüm,

Belki dönersin diye

Kaç kez dirildim, kaç kez gömüldüm...

Dönmedin,

Ben ölmezdim dönseydin...

Yokluğun öldürdü beni...', 'Ben ölmezdim de,  Senin gözlerin vurdu beni, Bilemedim nasıl vuruldum,  Bir gözlerin oldum, gözlerim sen oldun Bilemedim nasıl vuruldum, Ben...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yoklugunda-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir'' i Yakarken', 'i-zmir-i-yakarken-yuksel-kasim-rk7hq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hüzün hep vardı

Şehirden kaçıp giderken.

Yanarken şehir seninle birlikte

Olasılık kalmamıştı dönmeye dair,

Olsaydı yakmazdım onu da seni de…

Hüzün hep vardı

En güzel gözlerle gülerken

Yanında yörende,

En sevindiğin hariç en üzüldüğünde

Yüksel hep vardı

Çekip gittiğinde de…

Hüzün hep vardı

En sevilen yağmur yağarken bile,

Islanabilirdik

Belki demeyeceğim

Ama keşkeler değil mi

Acının ve

En çok hüznün sebebi

Son otobüse dek

Bekledim gelişini

Özetiydi sanki yaşantımın

Sen hep gittin

Şehir hep yandı

Hep şehir yandı

4 Kasım 2000

İzmir

Yüksel Kasım', 'Hüzün hep vardı Şehirden kaçıp giderken. Yanarken şehir seninle birlikte Olasılık kalmamıştı dönmeye dair, Olsaydı yakmazdım onu da seni de…...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Kasım']::text[], 8.5, '{"poet":"Yüksel Kasım","poet_slug":"yuksel-kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/izmir-i-yakarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtınalar içindeyim', 'firtinalar-icindeyim-ahmet-unal-cam-qps91', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fırtınalar içindeyim, 

fırtınalar içinde

Ceylan gözlü yarimle ben,

       Çankırı kentinde

Bir gün sormasam halini, 

çok büyük kabahat.

Yakar şu gönlümü de, 

hata bulmaz kendinde.', 'Fırtınalar içindeyim,  fırtınalar içinde Ceylan gözlü yarimle ben,        Çankırı kentinde Bir gün sormasam halini,  çok büyük kabahat. Yaka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/firtinalar-icindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencerelerde bir çocuk 31-01-2006', 'pencerelerde-bir-cocuk-31-01-2006-ahmet-unal-cam-jdw1x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sizin hiç anneniz

“döneceğim” diyerek

bırakıp gitti mi

bir kapıda, kış gününde? 

Beklediniz mi günlerce,

beklediniz mi senelerce 

           pencerelerde? 

Ve bir gün 

     okumayı öğrenip te 

Kapıdaki yazıyı okudunuz mu

Hece hece, kelime kelime; 

“Çocuk Esirgeme”



http://www.geocities.com/unalcam', 'Sizin hiç anneniz “döneceğim” diyerek bırakıp gitti mi bir kapıda, kış gününde?  Beklediniz mi günlerce, beklediniz mi senelerce            ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/pencerelerde-bir-cocuk-31-01-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Oldum', 'yok-oldum-yuksel-kasim-fh48t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duvar oldum

Anlatıp durdun sen

Durdu ama kum saati

Hayret? yağdırmadım yağmuru bu kez

Kanatmadı ellerimi dikenler

Kanadım

Duvar oldum

Kanadım kırıldı

Acıdım çok

Çok canım yandı

Feryat oldum, figan oldum

Doldum bir damla daha

Taştım taştım…

Su oldum

Taştım

Yağarken üstüme kinler

Sanki kimse yokmuş

Tek benmişim gibi

Yalnız oldum

Varlığım yokluğunla karıştı

Yok oldum.

12 Kasım 2000

İzmir

Yüksel Kasım', 'Duvar oldum Anlatıp durdun sen Durdu ama kum saati Hayret? yağdırmadım yağmuru bu kez Kanatmadı ellerimi dikenler Kanadım Duvar oldum Kanadı...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Kasım']::text[], 8.5, '{"poet":"Yüksel Kasım","poet_slug":"yuksel-kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yok-oldum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
