INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavinin Kara-kızı', 'mavinin-kara-kizi-tulay-sustam-zpx82', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'tükürsem

deniz kirlenecek

en iyisi

bir kaşık su da boğulmak

deniz bırak beni

hiç olmadığın kadar mavi kal', 'tükürsem deniz kirlenecek en iyisi bir kaşık su da boğulmak deniz bırak beni hiç olmadığın kadar mavi kal...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mavinin-kara-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Ayağa Kalk', 'sair-ayaga-kalk-sahin-erturk-ugghk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimleri yutmadı bu kara toprak

Gönlün bir çağlayan,gözlerin ırmak

Vakit geç oldu,ağlamayı bırak

Yetsin çektiğin,ŞAİR ayağa kalk

Sevmek sana inan çok yakışıyor

Haydi Şair şimdi,atağa kalk,kalk

(31.01.2006-Yeni)', 'Kimleri yutmadı bu kara toprak Gönlün bir çağlayan,gözlerin ırmak Vakit geç oldu,ağlamayı bırak Yetsin çektiğin,ŞAİR ayağa kalk Sevmek sana ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sair-ayaga-kalk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum seni', 'ozluyorum-seni-erdal-tufenk-gpcmv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecelerim hem soğuk hem serseri,

Biliyorum gelmez öalenen günler geri,

Hasretin eyledi beni bir kemik bir deri,

Hatırlarmısın canım buluştuğumuz ilk yeri

           Heyacan sarmıştı her yanımızı,

           Sevdalara salmıştık kanımızı,

           Ben sen oldum sende ben,

           Birbirimize adamıştık canımızı.

Deli yaşadık günlerimizi,

Hasretle sabah ettik gecelerimizi,

Geceler günleri günler geceleri kovaladı,

Beraber yaşadık sevinçlerimizi, dertlerimizi.

            Şimdi hasretim sana, inan birtanem

            Biliyorum ki sende hasretsin bana,

            Hayat kaderlerimizi birleştirdi ama,

            Hiç sansımız olmadı gurbetten yana.', 'Gecelerim hem soğuk hem serseri, Biliyorum gelmez öalenen günler geri, Hasretin eyledi beni bir kemik bir deri, Hatırlarmısın canım buluştuğ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Tüfenk']::text[], 8.5, '{"poet":"Erdal Tüfenk","poet_slug":"erdal-tufenk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozluyorum-seni-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstatistik Şanslılık /AŞK', 'i-statistik-sanslilik-ask-sevinc-kavuk-yj75o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlam zenginliğinden ötürü filizofların baş tacı! 

Yoğun çağrışımlarıyla felsefik düşünmenin tarihinde yer eden ama tanımlanmaya pek de yanaşmayan kutsanmış sözcüklerden biri; 

kimilerinde insanın olmazsa olmaz „değer“leri vazgeçilmez 

„erdem“lerinden biriyken, kimilerince sakınılması gereken 

bir „tutku“ yada sağatılması gereken bir „hastalık“…

Çok zaman da yine olsa olsa bir şeyin, Tanrı, Sevgili´nin, 

Ben´in vb. iyiliğini isteme

yalın bir biçimde karşılıklı bir ilişki olduğu da.. 

Bir de bunun ötesinde ayrı ayrı aşk biçimleri var ki; 

Erotik, romantik, platonik aşk, dost-evlat, yurt-doğa, güzel-iyi aşkı,

Tanrı-insanlık aşkı, erdem-hakikat aşkı vb.

Aşk anlayışı ve kavrayışı çağdan çağa

kültürden kültüre devinimler göstermiş... 

Her insan yaşamının ZENGİNLİGİ ve GÜÇ kaynağı, aynı zamanda erdemli bir yaşam önünde engel olabildi…diye gelişmeye yüz tutan düşüncelerden dolayı sağladığı güzelliği ve gücü koruyacak yaklaşımlar deneli.. 

batı felsefesinde

Islam felsefesinde aşk üstüne

Tasavvuf öğretisinin daha da bir öne çıktığı,

neredeyse tümünü aşk anlayışına dayandırdığı

Allahın varlığı, birliği, “varlığın birliği”de,

Yani yaratılanla yaratanın bir oluşu öğretisiyle

Islam gizemciliği denilmiş buna sözde 

ama gizil hazine hadisine dayandırılı aslı işte…

Allah evreni gizil hazine iken tanınmayı

yani gizini açmayı istediği için 

ya da güzelliğini DOYA  DOYA seyretmeyi arzuladığı için yaratmış… 

Ne mükemmel bir Felsefe! Bu tasavvuf anlayışında var olan! 

varoluş nedeni “bilgi” ve “sevgi” evrende “saltık güzellik” olan

Allahın güzelliklerini yansıtan bir ayna…

Güzele aşık olan insan evrende yansımasını bulan

Allahın saltık güzelliğine aşık olma bu aslı.. 

Gerçek aşka götürecek geçici aşk bir köprü işlevi…

Allahın güzelliklerinden yalnızca bir tanesine

bir güzele gönlünü kaptırma…mutasavvıflarca

kendi benini yoksamaya ve sevgiliyi yüceltmeye deneyimleri

bir önhazırlık niteliğinde…

Allahın birliğine inanma (tevhid)       için

Bu duygu olgunlaşıp evrilmeye başlayınca da

(işte burasına ben mest oluyorum)    

kişi tek bir güzelden tek tek güzellere

tek tek güzellerden de o güzelliğe

yani gerçek aşamasına geçer

İslam dini bu yüzden işte tam anlamıyla bir „AŞK DİNİ “….””””””

31.01.2006.....04.20 Salı

Atasının halkına, halkının atasına taşıdıkları islam aşkıyla yücelen 

Ki, kim kurban olmaz doya doya bu Millet Birliği´ne, söyle! 

Ne çok istatistik şanslılıklar bunlar! 

(Aşk´ı dile alacağım diye belki, bu Aşk Besmelem olsun...kitaplardan anladığım kadarıyla derledim!)', 'Anlam zenginliğinden ötürü filizofların baş tacı!  Yoğun çağrışımlarıyla felsefik düşünmenin tarihinde yer eden ama tanımlanmaya pek de yana...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/istatistik-sanslilik-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Sana Kalabilir', 'dunya-sana-kalabilir-sahin-erturk-9lfja', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geleceksen

Acele et

Kır zincirlerini

Hemen bugün gel

Yarın güzelim

İnan bana yarın

Dünya sadece

Sana kalabilir? 

(31.01.2006-Yeni)', 'Geleceksen Acele et Kır zincirlerini Hemen bugün gel Yarın güzelim İnan bana yarın Dünya sadece Sana kalabilir?  (31.01.2006-Yeni)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dunya-sana-kalabilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayılı Gün', 'sayili-gun-hakan-yasar-sp316', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(Mahpushanede yatanlarçin) 

Gözlerin sanki göktaşı

Soluk soluğa

Düşer dünyama.

İnce ince eski bir yara

Kanar sonra.

Bakma,

Bakma öyle karanlık

Kara kara düşlere bırakma.

Aydınlığımın sayıldı günleri

Sus artık! 

Bırak dolansın yeryüzünü güneş

Ağlama; 

Bir çizgi daha çektim duvara.', '(Mahpushanede yatanlarçin)  Gözlerin sanki göktaşı Soluk soluğa Düşer dünyama. İnce ince eski bir yara Kanar sonra. Bakma, Bakma öyle karanl...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yaşar']::text[], 8.5, '{"poet":"Hakan Yaşar","poet_slug":"hakan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sayili-gun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-zeki-altas-oiknb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bu sevdanın acısını,

an be an yüreğimde yaşarım.

Sarı örtülü o küçük masada,

hala seni bekliyorum,

ama yoksun,

yoksun işte…

Biliyormusun! 

Yıldız düşmüş gözlerine düşerim,

Ellerimi uzatıp ellerine düşerim.

Bir bardak çayda kaybolur,

Sarı örtülü o küçük masada,

Boşluğa düşerim.

Seni beklerim,

ama yoksun,

yoksun işte…

Şimdi bir hüzünlü şarkının bestesindeyim.

Sevdamız çakılı beynime.

Şarkımız çalar,

eşlik ederiz.

Ardından yeminler ederiz.

Sarı örtülü o küçük masada, 

Seni dinlerim.

Ama yoksun,

yoksun işte…

Bir tutam gül vardı.

Seni seyrettim durdum.

Sarı örtülü o küçük masada,

solmayın diye yalvardım.

Fırtınalar esti gönlümde.

Seni aradım maziden,

ama yoksun,

yoksun işte…

Şimdi boynu bükük haldeyim.

Mahsun mahsun bakarım.

Etrafımda cıvıl cıvıl cocuklar,

Sarı örtülü o küçük masada,

Oyunlar oynamaktalar.

Sana bakındım durdum.

Ahh kızım yoksun,

Yoksun işte,

Yoksun işte…', 'Ben bu sevdanın acısını, an be an yüreğimde yaşarım. Sarı örtülü o küçük masada, hala seni bekliyorum, ama yoksun, yoksun işte… Biliyormusun...', ARRAY['Türk Edebiyatı','Şiir','Zeki Altaş']::text[], 8.5, '{"poet":"Zeki Altaş","poet_slug":"zeki-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yoksun-135-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
