INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yüreğime Gömdüm (resimli)', 'seni-yuregime-gomdum-resimli-gulnaz-gulfigan-hcyx4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gömdüm seni

duygularımın en köreldiği bir anda

yüreğimde bir mezar yaptım sana

gözyaşlarım, acılarım, hüznüm

kazma ile kürek oldu sanki

vurdu vurdu vurdu yüreğime

ellerimle kazıdım derinlikleri

tırnaklarım kanarcasına

rüzgarlar savurmayacak

yağmurlar ıslatmayacak toprağını

ne bir mezar taşı diktim 

ne de çiçek getirecekler üstüne

kimseler görmeyecek, bilmeyecek

çünkü yüreğime gömdüm seni

hissedeceksin belki zaman zaman

gözyaslarım aktığında yüreğime

işte bilki o an

seni ziyaret edişimdir…

Gülfigan 24.06.03.', 'Gömdüm seni duygularımın en köreldiği bir anda yüreğimde bir mezar yaptım sana gözyaşlarım, acılarım, hüznüm kazma ile kürek oldu sanki vurd...', ARRAY['Türk Edebiyatı','Şiir','Gulnaz Gulfıgan']::text[], 8.5, '{"poet":"Gulnaz Gulfıgan","poet_slug":"gulnaz-gulfigan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-yuregime-gomdum-resimli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanet', 'lanet-polat-sarigul-jwxpx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hangi günahlarımız temize çıkarır bizi

bilinmeyen bütün dillerde tarif edilir mi yitirilmişlik

ölüm, bilinmeyen bir kavgadır aslında

kanlı ve belleksiz bir boşluk

bir ufuk çizgisidir

soluk alışların

kaptanlar açık denizlerde ölür

ve korsanların lanetidir mutluluk

şarap çelik tadında kuşanmış öfkesini

hangi zamanın boşluklarına açılmış ellerin

ellerin, ellerin kutsal sunaklarda

kurbandır çocuklar

öldü çocuklar......', 'hangi günahlarımız temize çıkarır bizi bilinmeyen bütün dillerde tarif edilir mi yitirilmişlik ölüm, bilinmeyen bir kavgadır aslında kanlı v...', ARRAY['Türk Edebiyatı','Şiir','Polat Sarıgül']::text[], 8.5, '{"poet":"Polat Sarıgül","poet_slug":"polat-sarigul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/lanet-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çİçekti sevgim', 'ci-cekti-sevgim-baki-ceylan-0bygg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamansız yağar kar

İnadına direnir 

Güneşi bekler

Dalında bir çiçek

Bulutlar izin vermez

Isınamaz..

Meyve olup tadına varamaz.

Çekip alır,

Soğuk toprak.

Artık ne aşk

Nede 

Gelse de mevsim yaz

Onu uyandıramaz,

Derin

Uykusundan.

/2006/01/30gece03', 'Zamansız yağar kar İnadına direnir  Güneşi bekler Dalında bir çiçek Bulutlar izin vermez Isınamaz.. Meyve olup tadına varamaz. Çekip alır, S...', ARRAY['Türk Edebiyatı','Şiir','Baki Ceylan']::text[], 8.5, '{"poet":"Baki Ceylan","poet_slug":"baki-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cicekti-sevgim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün günüm', 'huzun-gunum-erdal-tufenk-cdlda', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '06.01,2006 cuma günü,

Gönlüme ektin hüzün gülü,

Neyledin sevgilim beni,

Bir yarım sağ bir yarım ölü.

         Mutluluk senin hakkın daima gülsün yüzün,

         Sen baharın çocuğusun ben ise güzün,

         Dertlerden kederlerden uzak kalasın,

         Benim hakkım sevgilim hüzün.

Tabağımda zehir oldu akşam yemeği,

Ben sana verdim bu canı.bunca emeği,

Ben sevdim seni yine seveceğimde,

Yeteri sen mutlu ol iyilik meleği.

          Bugün eridim,güneşi gören kar gibi,

          Bugün ağladım,sevdiğinden ayrılan yar gibi,

          Bugün soldum,yaprak döken sonbahar gibi,', '06.01,2006 cuma günü, Gönlüme ektin hüzün gülü, Neyledin sevgilim beni, Bir yarım sağ bir yarım ölü.          Mutluluk senin hakkın daima gü...', ARRAY['Türk Edebiyatı','Şiir','Erdal Tüfenk']::text[], 8.5, '{"poet":"Erdal Tüfenk","poet_slug":"erdal-tufenk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/huzun-gunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldım Ben Bana Yine', 'kaldim-ben-bana-yine-aynur-sultan-qnc32', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'haftalar sonra geldi oturup bir kucak öteme 

oysa kucaklamaktı isteğim yapamadım

ellerini uzattı ellerime

uzattım ellerimi

tutamadım

sonra ne oldu bilemem 

şu şakaklarimda bir ağrı gitmez dedi

dokun biraz dinsin acı

istedim hiç dinmesin acı ellerim hep orada kalsın

olmadı ne acısını dindirdim ne acımı 

geldiği gibi gitti

geçici ağrılarıyla ağriilarımla kaldım ben bana yine', 'haftalar sonra geldi oturup bir kucak öteme  oysa kucaklamaktı isteğim yapamadım ellerini uzattı ellerime uzattım ellerimi tutamadım sonra n...', ARRAY['Türk Edebiyatı','Şiir','Aynur Sultan']::text[], 8.5, '{"poet":"Aynur Sultan","poet_slug":"aynur-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaldim-ben-bana-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk', 'terk-polat-sarigul-vhs8b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün kendini terk eder karanlığa

üçer beşer terk edilir sokaklar

kedilerin ve evsizlerin avuçlarında kalır gün

işte böyle bir zamandı

ağlamaklı tutunurken yaşamın yelkovanına

kırılıverir göz pınarların

haydi ne duruyorsun

ağlasana

ağla

beni de sürükle sularına

ölümüne olsun bu gece her şey

ölümüne', 'Gün kendini terk eder karanlığa üçer beşer terk edilir sokaklar kedilerin ve evsizlerin avuçlarında kalır gün işte böyle bir zamandı ağlamak...', ARRAY['Türk Edebiyatı','Şiir','Polat Sarıgül']::text[], 8.5, '{"poet":"Polat Sarıgül","poet_slug":"polat-sarigul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/terk-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehitler Ölmez', 'sehitler-olmez-mehmet-akif-tiryaki-9sxkb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nurun ala nur olduğu günlerde, 

Oğlum Allahuekber Dağı''nda askerde. 

Şarapneller parçalanır siperde, 

Kandil dağlarında gece sessiz. 

Tutulmuş nefesler, etraf kimsesiz, o yok, 

Ama beraberim, şafakla başlayacak ertesi günüm. 

Oğlumdan mektup gelmezse üzülürüm. 

Bir şiir yazmış geçende annesine, 

Ben ölürsem diye başlamış, 

Dizelerden birisine, 

Canmı dayanır bunun böylesine. 

Göstermedim köroğluna mektubu, 

Sakladım ceketimin sol iç cebine. 

Okudum şehidimin teslim merasiminde 

Annesinin feryatları içinde.', 'Nurun ala nur olduğu günlerde,  Oğlum Allahuekber Dağı''nda askerde.  Şarapneller parçalanır siperde,  Kandil dağlarında gece sessiz.  Tutulm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sehitler-olmez-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Düşer Yerlere Bir gün', 'ask-duser-yerlere-bir-gun-ahmet-beltekin-qz393', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç yaşamadım hayatımı,

Kalp atışlarımda uzadı gölgeler.

Bir resme sıkıştırdım, yaşanmış ne varsa,

Yeniden artarken kalbimin telâşı.

Geçmiş mevsimlerin üstünü sonbahar örtse de,

Öldüremez, benim yaşamak inadımı…

Geçmişin bütün hüzünleri içimde saklı,

Mutluluk adına ne varsa, yalnız bana yasaklı.

Ateşin düştüğü yerdir kalbim,

Yanar senelerdir, içinde bulunduğun yerim…

Gün gelir tozlanır zamanlar,

Ve zaman geçince eskir insanlar…

Bir gün çıkar karşıma,

Hatıralarımı yaşadığım o eski sokaklar,

Hasret kokar kaldırımlar, acı eşlik eder aşkıma.

Hep sana söyler, o şehirde şarkılarını dudaklar,

Gözlerim anlatır seni, her akşam gözyaşlarıma…

Hiç yaşamadım hayatımı,

Hep acılar demlendi, ömrümün her karesinde.

Bir boşlukta sürdürüyorum yolculuğumu,

Mutluluk vaat edilen baharın her zerresinde,

Yeniden tazeliyorum umudumu,

Çünkü biliyorum, bir gün aşk düşer yerlere…

Kendini zamana verir de fark etmez insan,

Oysa zaman alır seneleri, bellidir yüzlerde kalan.

Damağımızda tadı kalan her şey, yalanlarla dolu,

Gitmek istese de gidemez insan, geldiği yolu.

İnmezler yolcular boşluğa, yolculuk bitmeden,

Sevdası geride kalanlar hatırlanmaz.

Aşk yerlere düşer bir gün, anla artık, seneler gitmeden…', 'Hiç yaşamadım hayatımı, Kalp atışlarımda uzadı gölgeler. Bir resme sıkıştırdım, yaşanmış ne varsa, Yeniden artarken kalbimin telâşı. Geçmiş ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ask-duser-yerlere-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
