INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Bunu Düşünür Dualar Ederim', 'hep-bunu-dusunur-dualar-ederim-yusuf-onder-bahceci-bw2kf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yârimin gözlerinde yaşlar olmasın,

Beni düşünsün ama güller solmasın,

Allah''ım benden evvel toprak olmasın,

Hep bunu düşünürüm, dualar ederim.

Ayrılık hasretiyle sakın  ha ağlamasın,

Ben onu çok severim aman yanmasın,

Bir kere ellere kandı tekrar kanmasın,

Hep bunu düşünürüm, dualar ederim.

Birgün karşılaşırsak onunla bir yerde,

Elim ayağıma dolaşır, kalbim teklerde,

Nasıl derim ona seni çok sevdim be,

Hep bunu düşünür, dualar ederim ben....', 'Yârimin gözlerinde yaşlar olmasın, Beni düşünsün ama güller solmasın, Allah''ım benden evvel toprak olmasın, Hep bunu düşünürüm, dualar ederi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hep-bunu-dusunur-dualar-ederim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün ve O', 'birgun-ve-o-polat-sarigul-h0034', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün

Bütün yokoluşların

Bir kelebek

Zaman çok uzun kanatlarımda

Ölüm ise çok yakın tiktaklarında

Haydi yapraklarını sür yanaklarıma

Gölgeni düşür naif parmaklarıma

Aksın yeşil kınası damarlarıma

Haydi bana bir masal anlat 

Bilmediğim...

Gözlerime çiğ insin, serin

Rahatça uyumalıyım

Dingin

Başka dünyaların şarkıları okumalı dudaklarım

Ben birgün kelebeğiyim

Kocaman ömrüm

Birgün', 'Bugün Bütün yokoluşların Bir kelebek Zaman çok uzun kanatlarımda Ölüm ise çok yakın tiktaklarında Haydi yapraklarını sür yanaklarıma Gölgeni...', ARRAY['Türk Edebiyatı','Şiir','Polat Sarıgül']::text[], 8.5, '{"poet":"Polat Sarıgül","poet_slug":"polat-sarigul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birgun-ve-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem...', 'bilmem-halil-hasoglu-nirbu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KARACOĞLAN`A SELAM OLSUN! 

BİLMEM.....

Şafakta bir yıldız akıp gidiyor.

Sap bana; desem mi, sap demesem mi? 

Yüreğimde şimşek çakıp gidiyor.

Çarp beni; desem mi, çarp demesem mi? 

Bir güzel kalbimi yakıp duruyor.

Cilveli nazları takıp duruyor.

Simâsı mehtaba râkıp duruyor.

Bilmem; kal desem mi, kal demesem mi? 

İnce belikleri sarkmış gidiyor.

Zülüfleri yana yıkmış gidiyor.

Şavkı vurmuş aya, çekmiş gidiyor.

Bilmem; dur desem mi, dur demesem mi? 

Bakışları sanki güneş ışığı.

Deliye döndürür; ozan, aşığı. 

Saf altına lâyık kapı eşiği.

Bilmem; yap desem mi, yap demesem mi? 

İkide bir of çekerim derinden.

Başım döner bahar tüten terinden.

İçim titrer gözlerinin ferinden.

Bilmem; yak desem mi, yak demesem mi? 

Bağına bülbüller konar, şakışır.

Beyaz güller buram buram kokuşur.

Ak gerdana zümrüt, elmas yakışır.

Bilmem; tak desem mi, tak demesem mi? 

Kemeri kavramış kıvrak belini.

İbrişimden örmüş ipek tülünü.

Kelebekler konan saçın telini.

Bilmem; ör desem mi, ör demesem mi? 

Hiçbir tad kalmadı ekmek aşımda.

Duramam yerimde, aklım peşinde.

Çıkmaz hayâlimden, gördüm düşümde.

Bilmem; uyansam mı uyanmasam mı? 

Endamı çevirmiş dörtbir yanımı.

Kışın bile kaynatıyor kanımı.

Bakışları, alır gibi canımı.

Bilmem; el etsem mi, el etmesem mi? 

Kızıl elma gibi ala şakaklar.

Balı aratmıyor kibar dudaklar.

Kalemi çatlatır, nârin parmaklar.

Bilmem; sar desem mi, sar demesem mi? 

Melek yüzlü, nezîh, şirin endamı.

Çılgına çevirir, yiğit adamı.

Sevgisi bırakmaz iki yakamı.

Bilmem; yâr desemmi, yâr demesem mi? 

Vurursa kalbimden, bir güzel vursun.

Cefâsı, ömrümü kasıp, kavursun.

Gelirse ecelim, elinden olsun.

Bilmem; çağırsam mı, çağırmasam mı? 

Benden selam olsun tüm eşe dosta.

Kapıldım güzele, sînem hep yasta.

Düştüm yataklara, derdinden hasta.

Bilmem; dirilsem mi, dirilmesem mi? 

Kederli der; bırak, gidesi dursun.

Gönül istiyor ki; gelsin, taht kursun.

Karacoğlan, atam; huyum kurusun.

Bilmem; uslansam mı, uslanmasam mı? 

Kederli©Almanya, Şubat 1972 -31.01.2006', 'KARACOĞLAN`A SELAM OLSUN!  BİLMEM..... Şafakta bir yıldız akıp gidiyor. Sap bana; desem mi, sap demesem mi?  Yüreğimde şimşek çakıp gidiyor....', ARRAY['Türk Edebiyatı','Şiir','Halil Hasoğlu']::text[], 8.5, '{"poet":"Halil Hasoğlu","poet_slug":"halil-hasoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/bilmem-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum', 'yorgunum-guzin-eye-dundar-dwi2j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmurda nar ağaçları ağlıyor

gönülde yalnızlığım 

ince ellerimde tutkunun 

ağır halkası var 

yorgunum 

ellerimde sıcaklığı

gözlerimde yar 

biliyorum

sağanak gelecek 

ilk su gölünü 

bırakacak gözlerime 

dökmeden kurak toprağıma 

varabilsem 

ölesiye özledim sevdiklerimi 

görebilsem 

ıslak taşlarına kordonun 

ela gözlerini çizdim 

en güzelini evrenin 

İnce ellerim 

tutkunun ağır halkası var 

Yalnızım...', 'Yağmurda nar ağaçları ağlıyor gönülde yalnızlığım  ince ellerimde tutkunun  ağır halkası var  yorgunum  ellerimde sıcaklığı gözlerimde yar  ...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yorgunum-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamana sitem', 'zamana-sitem-kemal-eyupoglu-mc2vf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasıl uğraştım seninle

Ve ne çok yordun beni ey zaman

Yaşa ve gül diyerek

Önüme serdiğin yarınlarına

Ayak uydurabilmek için

Bu günden,ne adımlar attım

Ne menziller aştım

Ey zaman.

Çıkmaz bir sokağa düşürdüğünde beni

Zil çaldırdın saatlerine

Ve gücüm yetmeyince

Akrebine,yelkovanına

Küsmedim kaderime

Ama sana küstüm

Ve hayatıma küstüm

Ey zaman.

Sanki,senin umurundaydı

Benim küsüşüm

Sen,farkına bile varmadın dargınlığımın

Yine tel tel dökmeye devam ettin saçlarımı

Yüzümü kapladın kırışıklıklarınla

Gözüme gözlük,elime baston verdin

Ey zaman.

Her günün çivi oldu tabutuma

Ve yıkılmamı

Ve dört tahtaya sığınmamı bekledin

Gözlerini dört açarak

Dört gözle

Alacağın olsun ey zaman.', 'Nasıl uğraştım seninle Ve ne çok yordun beni ey zaman Yaşa ve gül diyerek Önüme serdiğin yarınlarına Ayak uydurabilmek için Bu günden,ne adı...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/zamana-sitem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Yüreğim', 'yorgun-yuregim-aynur-avci-ke0e7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir yorgunluk var

Altından kalkamadığım

Susup sabretsem nafile

İzi kalmış bir defa

Acıyla yoğrulmuş yıllarım

Ömür son bulsa da birgün

Anılar anlatır gün gün

Öykü olur ya da masal

Dalga dalga yayılır sensizliğe...', 'Yüreğimde bir yorgunluk var Altından kalkamadığım Susup sabretsem nafile İzi kalmış bir defa Acıyla yoğrulmuş yıllarım Ömür son bulsa da bir...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yorgun-yuregim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirpiklerim Bıraktı', 'kirpiklerim-birakti-aycan-kose-is7fc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“Oysa ben kalbimi yağmurla bölüp

Yarısını sana vermiştim.”

Henüz gözyaşlarım kirlenmemişken

Ve gözlerime direnmemişken

Çıkardım seni

Düğmeleri kopmuş tenimden

……………………

Bende kimse kalmadı

Yüreğimde tek kaldım şimdi.

“İnan bana üzgünüm,

Kalmadı 

Bende bir damla yağmur

Bana seni açıklayan.”

Bütün şiirler ve şairler sağanak yağıyor

İsimsiz bir gülüşün fotoğrafına.

Bin yağmur kirpiklerime asılı kaldı

Bir bulut ise gözlerime

Kirpiklerim bıraktı

Gözlerim çoktan hazır

Hadi sevgili, hadi

Sen de bırak beni

Bu şehir de ıslansın

“Evet, bu şehir de  ıslandı; denizler akşam oldu,

Yosun tuttu kıyıya vurdu sabahlar.”

02/07/2000', '“Oysa ben kalbimi yağmurla bölüp Yarısını sana vermiştim.” Henüz gözyaşlarım kirlenmemişken Ve gözlerime direnmemişken Çıkardım seni Düğmele...', ARRAY['Türk Edebiyatı','Şiir','Aycan Köse']::text[], 8.5, '{"poet":"Aycan Köse","poet_slug":"aycan-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kirpiklerim-birakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-suleyman-demir-cwiy2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir çiçek ol toz pembe,ortasında ölümün! 

ab-ı hayat ol bana damla damla çağla gel! 

nar-ı ızdırap ile soldu ömrü gülümün,

uzun olsun bahardan,yepyeni bir çağla gel.

gönlümün denizinde dalgalanmıyor sular! 

kıyıya vurdu sevdam olta ile ağla gel! 

belki de çoraklaşan gönül yurdumu sular,

bir kenarda sessizce hıçkırarak ağla gel.

ebedi dayanmaya elbet yetecek gücüm,

istersen doruk ile bayır ile dağla gel! 

öyle bir geliş gel ki,sende kalmasın öcüm,

beni mahkum ettiğin gözlerini dağla gel.', 'bir çiçek ol toz pembe,ortasında ölümün!  ab-ı hayat ol bana damla damla çağla gel!  nar-ı ızdırap ile soldu ömrü gülümün, uzun olsun bahard...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Demir']::text[], 8.5, '{"poet":"Süleyman Demir","poet_slug":"suleyman-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-264-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esaret', 'esaret-ahmet-beltekin-75khh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gün herkes,her şeyi unutuyor,

Bazen ıslansa da,uzağa dalan gözleri.

Bir hayâl alemi,beni aynalarda tutuyor,

Kırılıp dökülse de parça parça gizleri…

Gece bulutlardan sıyrılıp inerken şehre,

Gölgeler çekilip gider,perdeleri kapalı evlere.

Bir gün düşer herkes hayâl taşıyan o nehre,

Ve esir olur insan ayrılık,hasret gibi devlere,

Gece bulutlardan sıyrılıp inerken şehre…..', 'Her gün herkes,her şeyi unutuyor, Bazen ıslansa da,uzağa dalan gözleri. Bir hayâl alemi,beni aynalarda tutuyor, Kırılıp dökülse de parça par...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Beltekin']::text[], 8.5, '{"poet":"Ahmet Beltekin","poet_slug":"ahmet-beltekin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/esaret-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An gelir', 'an-gelir-i-lyas-genc-ghut2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'An gelir ateş düşer dağlara

Dağlarımızdaki karlar erir

Sellere karışır körpecik fidanlar

Ümitlerimiz ırmaklarda  kayboluverir

An gelir ayrılık karışır rüzgarlara

Bir yaprak misali koparır gönlünden 

Alıp gider beni bilenmeyen uzaklara

An gelir özlem duyarsın

Geçmişte yaşadığımız  yıllara.

Yıldızları söndürürler birer, birer

Sevdamız  teslim olur karanlığa

An gelir şiirlerim okunur

Her mısrası bir hançer gibi

Yüreğine sokulur

Keşkeler arasında için bükülür

Yasaklı sevdam sende son bulur.

An gelir bu sevdamız da unutulur

Aşıklar şiirlerimizde huzuru bulur

Ölüm gelir senide, beni de alıp götürür…..

Ve an gelir toprağa düşer ölüm

Gözlerinden iki damla yaş süzülür

Tabutum musalla taşı üzerine konur

O gün selalar  benim için okunur.

Bütün şiirlerim de ihtilal olur

Mısralarım başlar  ağlamaya

Sahipsiz kalır sevdam....Ve sen 

Gelirsin benimle beraber sonsuzluğa…', 'An gelir ateş düşer dağlara Dağlarımızdaki karlar erir Sellere karışır körpecik fidanlar Ümitlerimiz ırmaklarda  kayboluverir An gelir ayrıl...', ARRAY['Türk Edebiyatı','Şiir','İlyas Genç']::text[], 8.5, '{"poet":"İlyas Genç","poet_slug":"i-lyas-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/an-gelir-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekar lojmanı', 'bekar-lojmani-nevzat-ozkan-rjly6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'oruca gebe sahurlarda,

nişanlısına

aşk mektubu yerine

ilahiler yazar,

ekinde yine ilahiler gönderirdi,

tarsuslu oda arkadaşı.

akşamları dışarıda yer,

yemekten sonra,

yanımızda kömürlü semaver

üstünde demlik,

porsuk çayı kenarında  demli  çay içerdik.

iş dönüşü zil zurna

sarhoş olur,

bisikleti ile sürünerek içeri kadar girer,

çekinmeden ortalığa işerdi

fabrikanın yarı deli postası Muzaffer..

hafta sonu,

bekarlar dağılırdı,

kimi istasyona 

kimi otogara doğru.

odalar boşalır 

yalnız kalırdı

bekar lojmanı.', 'oruca gebe sahurlarda, nişanlısına aşk mektubu yerine ilahiler yazar, ekinde yine ilahiler gönderirdi, tarsuslu oda arkadaşı. akşamları dışa...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bekar-lojmani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman/Ayrılık Şiiri', 'zaman-ayrilik-siiri-ali-gencay-0w943', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu şarkı sana

Sonlanmamış hayallerin

Yitirilmiş umutlarınla

Kulağına fısıldayacak rüzgar

Belki arayacaksın rüyalarında

Ne kadar çok istesen de

Çıkmayacak papatya fallarında

Saat, her saat başı vurduğunda

Beni unutma

Geçmişe bir bak, hatırla

Bir bahar günü hisarcık yolunda

Ulu çınar, küçük şadırvan altında

Tutulmuş iki yürektik biz

Demlenmiş çay tadında

Kimilerine göre zır deliyiz

Haklıda olsalar esasında

Unut tüm söylenenleri

Beni unutma

Koynumda bulduğum sarı saçlar

Sımsıcak güneşe eş bakışlar

Gözlerinde hareli ela

Dudaklarında kıpraşan sevda

Dinmez, dinmeyecek

İçinde akan hayat/derya

İşte gidiyorsun çeşm_i afet

Beni unutma

Sen vazgeç sevdandan

Ama benim sevdama dokunma

Sen sus, istersen 

Hiç konuşma

Ben konuşurum kalemle/kağıtta

İstersen bana aldırma

Zaten göz yaşlarım dokunmaz

Dokunmayacak parmak uçlarına

Yine, her o şarkı çaldığında

Beni unutma

Ne ilk, ne son şiirim sana

Olurya kalemim kırılırsa satır ortasında

Bil ki ölüm dayanmıştır kapıma

Affet beni kadınım, bağışla

Mevsim hazan olduğunda

Çiçekler açıp bahar uyanırsa

Yine saat, her saat başını vurduğunda

Beni unutma', 'Bu şarkı sana Sonlanmamış hayallerin Yitirilmiş umutlarınla Kulağına fısıldayacak rüzgar Belki arayacaksın rüyalarında Ne kadar çok istesen ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/zaman-ayrilik-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta -2-', 'usta-2-cengiz-kurt-2-28gzd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yolumu kaybettim, çıkmazlardayım

Dünyam ekseninde dönmüyor USTA

Çözümsüz dertlerin girdabındayım

Kalp ağrım bir türlü dinmiyor USTA

Sarmış etrafımı diri ölüler

Bana “deli” diyor, asıl deliler

Artılar, eksiler, çarpı, bölüler

Sevgimi tarife yetmiyor USTA

Gün olur her şeye güler geçerim

Gün olur her şeyden nefret ederim

Gün olur sonsuza uçmak isterim

Bir günüm günümü tutmuyor USTA

Her zaman sarhoşum, hep döner başım

Islaktır gözlerim, dinmez gözyaşım

Seni düşünmektir artık tek işim

Aklım başka şeye yetmiyor USTA

Cengiz Kurt

05.06.200, eryaman', 'Yolumu kaybettim, çıkmazlardayım Dünyam ekseninde dönmüyor USTA Çözümsüz dertlerin girdabındayım Kalp ağrım bir türlü dinmiyor USTA Sarmış e...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kurt 2']::text[], 8.5, '{"poet":"Cengiz Kurt 2","poet_slug":"cengiz-kurt-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/usta-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Adamı', 'ask-adami-ali-i-hsan-ozturk-vpbcv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşanan büyük aşklara kıyas

Bir sevdanın ürünüydü o

Dünyaya merhaba deyişiyle

Tüm insanlar sarmaş dolaş

Mutluluğa uçtular

Kelebekler gibi

Çapkın bakışları ve

Göz süzüşlerine isnat

İnsanlık adına sanını koydular

Aşk Adamı.', 'Yaşanan büyük aşklara kıyas Bir sevdanın ürünüydü o Dünyaya merhaba deyişiyle Tüm insanlar sarmaş dolaş Mutluluğa uçtular Kelebekler gibi Ça...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Öztürk']::text[], 8.5, '{"poet":"Ali İhsan Öztürk","poet_slug":"ali-i-hsan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-adami-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoktan Küserdim', 'coktan-kuserdim-yusuf-onder-bahceci-5d0m3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O beni sevmese onu düşünemezdim,

O beni sevmeseydi ben bilemezdim,

Böyle güzel mısralar ben dizemezdim,

O beni sevmese çoktan küserdim.

İyi biliyorum çok seviyor, seviyor beni,

Yazdığım şiirlerin hepsini okuyor hemi, 

Kendini suçlu sanıyor sormuyor beni,

O beni sevmese çoktan küserdim.

İçimde hep bir ümit bahar gelecek,

Bir gün beni görürse bayram edecek,

Belki çok sevinecek, belki gülecek,

O beni sevmese çoktan küserdim.', 'O beni sevmese onu düşünemezdim, O beni sevmeseydi ben bilemezdim, Böyle güzel mısralar ben dizemezdim, O beni sevmese çoktan küserdim. İyi ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/coktan-kuserdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Oyunu', 'hayat-oyunu-aynur-avci-ti7po', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç dört nisan geçti

Kaç yirmi eylül

Yıllar uzadıkça zaman da

Acıların adımı büyüdü

İçin için ağlıyorum

Roller yer değiştirdikçe

Perdeler hep kapalı

Gece de uykular uzadı

Gündüze sabah doğmuyor

İsyan etsem de kadere

Oyun çoktan bitti

    Sah ne de...', 'Kaç dört nisan geçti Kaç yirmi eylül Yıllar uzadıkça zaman da Acıların adımı büyüdü İçin için ağlıyorum Roller yer değiştirdikçe Perdeler he...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-oyunu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Psikuş', 'psikus-seckin-tok-9lz99', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kuş açtı seyir defterini

sandığının en dip köşesinde

                       bir ağlama sesi...

                       gökyüzünü tutuşturma niyeti gibi bir şey

                       geçiyor gibiydi içinden...

kuş, gözünde rutubet -öyle parlarken-

sohbet etmek için

kendini davet etti...

                       kim bilir

                       belki bir özür

                       -bir barış teklifi-...

kuş ağaç gölgesinde sabahlamak üzereyken tam

bir çift aşık göz fark etti

                       kızın gözleri pırıl pırıl

                       adam hasta

                       peş peşe sevişmelere...

kuş en tepesinden başlayıp

içindeki aleve verdi

‘aşıklar ağacı’nı...

                       kendi geldiğinde gece üstü

                       yuvasız bir kuş buldu tenhada

                       ve aşıklar el ele

                       üşüyordu

                       sokak lambasının altında...

31.01.2006

16.03', 'kuş açtı seyir defterini sandığının en dip köşesinde                        bir ağlama sesi...                        gökyüzünü tutuşturma n...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Tok']::text[], 8.5, '{"poet":"Seçkin Tok","poet_slug":"seckin-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/psikus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabret', 'sabret-aynur-avci-0tnvv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Denizi tepeden seyrettim

Hız motorları aşk gibi

Bikinili kızlar revaçta

Kaptan köşkünde mutlu

Sanki tualin yansıması

Yine akşam erken oldu

Ay geceye vurdu

Sevgililer yosun kokuyor

Masaları donatmış garson

Mest olmuş müzikle insanlar

Kadehler hava da

Eller sevgide birleşmiş

Yine sensiz sabah oluyor...', 'Denizi tepeden seyrettim Hız motorları aşk gibi Bikinili kızlar revaçta Kaptan köşkünde mutlu Sanki tualin yansıması Yine akşam erken oldu A...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sabret-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat Sokağı', 'vuslat-sokagi-aynur-avci-vnkdg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen bir başka alemsin

Daldan dala gezersin

Her aklına geldiğin de

Vuslat sokağında beklersin

Sen bir başka alemsin

Kendi dünyanda yaşarsın

Her aklına geldiğin de

vuslat sokağın da beklersin..', 'Sen bir başka alemsin Daldan dala gezersin Her aklına geldiğin de Vuslat sokağında beklersin Sen bir başka alemsin Kendi dünyanda yaşarsın H...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vuslat-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut sevdiğim', 'unut-sevdigim-i-lyas-genc-haa0q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unut…unut sevdiğim unut her şeyi 

Okumaya başladığın Bu satırları,

Ve akıttığım bu son gözyaşları mı unut..

Unut sevdiğim….

Sana sevgilim diye hitap ettiğim tüm kelimeleri

Seni seviyorum diye başladığım bütün cümleleri 

Ve adına bestelediğim tüm şarkıları,şiirleri unut..

Unut sevdiğim…

El ele yürüdüğümüz caddeleri,parkları

Çoğu zaman şaşırıp geri döndüğümüz çıkmaz sokakları

Ve her defasında bize yeşil yanan trafik lambalarını unut…

Unut sevdiğim…

Gölgesinde seviştiğimiz çam ağaçlarını

Gözyaşlarıyla büyüttüğümüz hercai menekşeleri

Ve aşkımızın simgesi pembe papatyaları unut

Unut sevdiğim..

Seni seviyorumlarla doldurup gönderdiğim mektupları

Noktalar, virgüller koyup öylesine attığım mesajları

Ve hiç olmadık yerde gelen cevapsız çağrıları unut

Unut sevdiğim..

Aşk yuvamız haline gelen sardunya bahçelerini

Bize her zaman hüzün dağıtan gece sefalarını 

Ve Bizim için güneşe direnen sedir yapraklarını unut

Unut sevdiğim….

Unut dediğim veya diyemediğim ne varsa unut

Tek bir şeyi unutma..bu yürek seni hiç unutmayacak..', 'Unut…unut sevdiğim unut her şeyi  Okumaya başladığın Bu satırları, Ve akıttığım bu son gözyaşları mı unut.. Unut sevdiğim…. Sana sevgilim di...', ARRAY['Türk Edebiyatı','Şiir','İlyas Genç']::text[], 8.5, '{"poet":"İlyas Genç","poet_slug":"i-lyas-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/unut-sevdigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Sapanca', 'elveda-sapanca-mehmet-akif-tiryaki-liddb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İdam mahkumlarının üç dileği yerine getirilirmiş,

Bu son olacak, Sapanca şiirleri ile sizi baymayacağım ama

Medyatörden ricam son Sapanca şiirim yayımlansın dileğim. 

Bu son şiirimi de okuyacaksınız sanırım.

Artık şiirlerim Sapanca ile başlamayacak,

Birdaha sonbaharda yapraklar aklımda dolaşmayacak

Mazide yazdığım şiirler dans edecek sokakta,

Yıldızlar şarkı söyleyecek karanlıkta Datça''da terasta.

Kartepe yazmayacağım inanın birdaha,

Aslında severim sahanda iki yumutra,

Kuş gribi çıktı çıkalı onuda efendi gibi yiyemiyoruz ya

Aklımı başıma alıp,  başka şeyler yazacağım belki,

Belki de yazmayacağım hiçbirşey kimbilir ki? 

Son şiirimde Sapanca Sapanca Sapanca diye 

Üç kere söylemeliyim..(!) 

Mecalim yok artık dinlenmeliyim

Bir yer bulup çekip gideyim.

Nereye mi bilmem ama......Geçerken Sapanca''ya da 

Merhaba demeden edemeyeceğim.

Elveda Sapanca,

Elveda mocivert taclı gelin elveda...', 'İdam mahkumlarının üç dileği yerine getirilirmiş, Bu son olacak, Sapanca şiirleri ile sizi baymayacağım ama Medyatörden ricam son Sapanca şi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/elveda-sapanca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılbaşı', 'yilbasi-aynur-avci-m4744', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'LeoTheMaster

Senede bir gece kutlanır yılbaşı 

Boş masada, boş tabaklar 

Tutulmayan çatal bıçaklar 

Senede gece,

Gecede ben  yapayalnız.

Uçan kuşlarımın her biri ayrı mutlulukta 

Aynı masada yalnız ben

Kor alevi yüreğimde 

Sönmeyen mum ışığı ve 

Kutlama sesleri

Yad edilen anılar,anılar 

Senede bir gece 

Gecede ben yapayalnız...', 'LeoTheMaster Senede bir gece kutlanır yılbaşı  Boş masada, boş tabaklar  Tutulmayan çatal bıçaklar  Senede gece, Gecede ben  yapayalnız. Uça...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yilbasi-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Çocuk Olmak', 'bugun-cocuk-olmak-omer-osman-avci-qgrt8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dışarıda

Lapa lapa kar yağıyor

Doğa 

Güne neşe ile uyanıyor

Bugün gündemimde 

Ne haber başlıkları olsun

Ne de geçim sıkıntısı 

Hatta! 

O`nu bile unutmalıyım...

Haydi çocuk! 

Bana çocukluğunu ver

Bugün ben çocuk olmalıyım...

Önce şu sapanı boynuma takıp

Kendimi emniyete almalıyım

Hep karavana atarım ya her neyse…

Kuş vuracağım diyerek

Arkadaşlarıma hava atmalıyım...

Matematiğim yine zayıf

Hal ve gidişim orta

Türkçe''m de iyi olsun

Aman! ...

Karnemin de ne önemi var

Tatilin tadını çıkarmalıyım...

Kardan adam yapmalıyız 

Havucu ben bulmalıyım

Kömürü evden ben getirmeliyim

En çok ben yorulmalıyım

Yine en çok başkaları sahiplensinler

Ben seyirci kalmalıyım...

Karda kaymalıyım

En çok ben düşmeliyim

Evde yine en çok dayağı ben yiyip

Kaygısızca, zırıl-zırıl ağlamalıyım

Kurt gibi acıkmalıyım

Şu gelen annem olmalı

Eteğine sıkıca yapışıp

Yiyecek istemeliyim...

Yok! … Yok...

Olmadı çocuk, olmadı…

İşte bu hiç olmadı

Lütfen çocukluğunu geri al

Oyunu kuralına göre oynamalıyım

Benim annem, hiç olmamıştı ki...', 'Dışarıda Lapa lapa kar yağıyor Doğa  Güne neşe ile uyanıyor Bugün gündemimde  Ne haber başlıkları olsun Ne de geçim sıkıntısı  Hatta!  O`nu ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Osman Avcı']::text[], 8.5, '{"poet":"Ömer Osman Avcı","poet_slug":"omer-osman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bugun-cocuk-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne oldu bize böyle,', 'ne-oldu-bize-boyle-erdal-gul-dy87a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni her an görmeden, artık duramıyorum,

Elim yare varmadan, artık doyamıyorum,

Yalvarıyorum sana,artık ayamıyorum,

Ne oldu bana böyle, sensiz olamıyorum,

Ayrılık katar oldu, her biri binbir dizi,

Bu sevda zahiri, kahretti ikimizi,

Duysun artık o felek,ağlayan sesimizi,

Ne oldu bize böyle, gözyaşı boğdu bizi..', 'Seni her an görmeden, artık duramıyorum, Elim yare varmadan, artık doyamıyorum, Yalvarıyorum sana,artık ayamıyorum, Ne oldu bana böyle, sens...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gül']::text[], 8.5, '{"poet":"Erdal Gül","poet_slug":"erdal-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-oldu-bize-boyle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular', 'duygular-sebnem-sengun-uf7kw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duygularımı kaleme aldığımda

Yanlız seni yazmak isterim

Sevgimi söylemek istesem

Yanlız sana söylerim

Aşkımı dele getirirsem

Senin dinlemeni dilerim

Kimi seviyorsun diye sorsan

Seni seviyorum derim', 'Duygularımı kaleme aldığımda Yanlız seni yazmak isterim Sevgimi söylemek istesem Yanlız sana söylerim Aşkımı dele getirirsem Senin dinlemeni...', ARRAY['Türk Edebiyatı','Şiir','Şebnem Şengün']::text[], 8.5, '{"poet":"Şebnem Şengün","poet_slug":"sebnem-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/duygular-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rah/İM/ANne', 'rah-i-m-anne-orkun-isik-f51nv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rah

Bilemediğim çehreler düşüyor suretinden

Kadınsı bir çilenin ahı yükseliyor teninden

Sessiz zaman, çizikler atıyor bahtsız alnına

Ve ç/oğullaştırıyor hayatı kendi nur etinden…

İm

Aramam beni resimlerde ben sen’den izim

Ç/ağlarsın bana kendini sen, ben denizim

Dalgalar saçlarını tarar tarihlerce, ey kadın

Ki, sen olmasaydın soluk kalacaktı benzim…

Rahîm''ce üfürüldük, rahim''den düştük alem''e

Gerildik Bayrak gibi anmak için rabbi alem''e

Muhammed yüzüne yazıldık topraktan sahneye

Mürekkep olduk şahitsiz kadın denen kalem''e', 'Rah Bilemediğim çehreler düşüyor suretinden Kadınsı bir çilenin ahı yükseliyor teninden Sessiz zaman, çizikler atıyor bahtsız alnına Ve ç/oğ...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/rah-im-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer Günü', 'sevgililer-gunu-aynur-avci-v1qyj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimşekler çaktı gönlümde

Sevginin özü kaldı bende

Bir gül verdin elime

Bir ömür tuttum elimde

Soldurmadım seni benliğimde

Kokladım her nefesimde

Sevgililer gününde

Sevgimi yolluyordum yüreğine

Boş yüreğime doldun

Bende çok mutlu oldum

Yalnızlığımı bir an unuttum

Çığlık attım dört bir yana coştum

Sevgililer gününde

Sevgimi hisset yüreğinde..', 'Şimşekler çaktı gönlümde Sevginin özü kaldı bende Bir gül verdin elime Bir ömür tuttum elimde Soldurmadım seni benliğimde Kokladım her nefes...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgililer-gunu-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralar', 'hatiralar-sebnem-sengun-1nkl0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dalgaların sesini dinliyorum

Her dalga kalbimden bir hüzünü siliyor

Rüzgarın sesini dinliyorum

Beni uzak diyarlara sürüklüyor

Yağmurun sesini dinliyorum

Aşkımız bittiğinde akan göz yaşlarımı hatırlatıyor', 'Dalgaların sesini dinliyorum Her dalga kalbimden bir hüzünü siliyor Rüzgarın sesini dinliyorum Beni uzak diyarlara sürüklüyor Yağmurun sesin...', ARRAY['Türk Edebiyatı','Şiir','Şebnem Şengün']::text[], 8.5, '{"poet":"Şebnem Şengün","poet_slug":"sebnem-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hatiralar-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fitne Fesatlar Ayırdı Bizi', 'fitne-fesatlar-ayirdi-bizi-yusuf-onder-bahceci-mt3mx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu nasıl iştir Gülüm anlayamadım,

Benden ayrıldın sen ağlayamadım,

Ardından öylece ben baka kaldım,

Fitne, fesat, hasetler ayırdı bizi.

Ben senden ayrılalı çok yıllar geçti,

Geçti ama sorsana nasıl da geçti,

Kalbimde sevdayı sanki orak biçti,

Fitne, fesat, hasetler ayırdı bizi.

Yıllar oldu kalbimde duruyor sevgin,

Geceler boyu ağlarım elimde resmin,

Yalan söyleyemem ki yoktur adresin,

Fitne, fesat, hasetler ayırdı bizi....', 'Bu nasıl iştir Gülüm anlayamadım, Benden ayrıldın sen ağlayamadım, Ardından öylece ben baka kaldım, Fitne, fesat, hasetler ayırdı bizi. Ben ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fitne-fesatlar-ayirdi-bizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-arif-emrah-toyoglu-4tria', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dün gece rüyamda uykuya dalmışım

uyanınca tekrar uyuya kalmışım.....', 'dün gece rüyamda uykuya dalmışım uyanınca tekrar uyuya kalmışım........', ARRAY['Türk Edebiyatı','Şiir','Arif Emrah Toyoğlu']::text[], 8.5, '{"poet":"Arif Emrah Toyoğlu","poet_slug":"arif-emrah-toyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/nerdesin-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim Keskin', 'memleketim-keskin-mesut-ozturk-lapm5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Feryatlarım kayıp olmuş, Denek dağından,

Aşıkları şarap içmiş, üzüm bağından,

Anam bana katmer açmış, tereyağından,

Memleketim Adı Keskin çıkmaz bağrımdan.

Düğünleri bir başkadır, neşesi başka,

Sokakları insanı getirir aşka,

Selamsızı saygızı olmaz asla,

Hasretinden kavruldum canım Keskin`im!', 'Feryatlarım kayıp olmuş, Denek dağından, Aşıkları şarap içmiş, üzüm bağından, Anam bana katmer açmış, tereyağından, Memleketim Adı Keskin çı...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/memleketim-keskin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fatma ya', 'fatma-ya-i-brahim-kilinc-v7496', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Methetsem; dostudur, meth eder, derler

Dilimde varmaz ki ona atmaya

İyi kız, iyi dost, iyi bir ana 

Bilmem ki ne yazsam dostum Fatma''ya

Yeni tanışmıştık kocası asker

Evinden çıkmadan yolunu bekler

Birbirine aşık o genç yürekler

Ne yazsam bilmem ki dostum Fatma''ya

Yüksek tahsil görür şimdi kızları

Gönlümüzde vardır derin izleri

Kulağımda çınlar güzel sözleri 

Ne yazsam bilmem ki dostum Fatma''ya

Eşinin mertliği, dostluğu ayrı

Böyle dosttan gönül vazgeçmez gayrı

Şerrini görmedik, dokunur hayrı

Ne yazsam bilmem ki dostum Fatma''ya', 'Methetsem; dostudur, meth eder, derler Dilimde varmaz ki ona atmaya İyi kız, iyi dost, iyi bir ana  Bilmem ki ne yazsam dostum Fatma''ya Yeni...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fatma-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorarım', 'sorarim-osman-taspinar-taquv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün bıçak altında kurbanım

Yok bir günden bir güne

gelipte soranım.

Musalla taşına konduğumda yarın

Kader kurbanıydı deyiverin.

Şen,şakrak olduğuma bakmayın

Beni bir yılan gibi sokmayın

Bir gün göçüp gidersem kanmayın

Size öbür dünyada hesap sorarım.

Ben mi istedim,bu hayatı

ben mi özledim? 

Çarklar böyle dönsün diye

ben mi söyledim? 

Kırılmadıysa ruhlardaki zincirler

Ben mi çözmedim? 

Ben mi kilitledim?', 'Bugün bıçak altında kurbanım Yok bir günden bir güne gelipte soranım. Musalla taşına konduğumda yarın Kader kurbanıydı deyiverin. Şen,şakrak...', ARRAY['Türk Edebiyatı','Şiir','Osman Taşpınar']::text[], 8.5, '{"poet":"Osman Taşpınar","poet_slug":"osman-taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sorarim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Almancı!', 'almanci-mesut-ozturk-tqcnj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ezdiler, bezdirdiler beni yaşamdan,

Kırıpta kopardılar, sıcak yuvamdam,

Yalanla dolanla soğuttular,vatandan,

Hakkım sana haram ey! Almancı! 

Kendi dilini bilmezsen,

Baba sözü dinlemezsen,

Atan kimdir söylemezsen,

yanlız kalırsın Almancı! 

Özünü kaybedip modern olmaya bakma! 

Sen sen ol, atalarını bir kenara atma! 

O güzelim gencecik geleceğini yakma! 

Kendine gel, Aklını topla Almancı! 

Kredi ile hava atmak için alınan maldan,

Mandalaşmak uğruna çıkılacak yoldan,

Seni kapmak için uzanacak koldan,

Kendini ısrarla savun ve koru almancı!', 'Ezdiler, bezdirdiler beni yaşamdan, Kırıpta kopardılar, sıcak yuvamdam, Yalanla dolanla soğuttular,vatandan, Hakkım sana haram ey! Almancı! ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/almanci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anımsamalar/1', 'animsamalar-1-yavuz-dogan-j3iq2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutmadım unutmam,ne Elif''tim ne Lâm''dım

Üstüne binbir anlam yıkılandım sadece.

Ne aşkı emreylemiş ne bitirmiş kelâmdım

En yanlış adreslere çıkılandım sadece.

Unutmadım yankısız feryad-ı figân iken

Sevdayı umut bilmiş muratsız bir can iken

İki nefes arası yaşanmış bir an iken

Alnına kör bir kurşun sıkılandım sadece.

Unutmadım kabustu rüya diye gördüğün

Lanetlenmiş bir andı sefa diye sürdüğün

Turnalar göç ederken, leş kargaları düğün

Boyun büküp çarmıha çakılandım sadece.

Unutmadım sararmış bir hazan gülüydün sen

Yüreğime gömülmüş mezarsız ölüydün sen

Su içtim tövbe bozdum,Kerbela çölüydün sen

Bense ömre sürgünü farz kılandım sadece.

Unutmadım koparken hem kolum hem kanadım

Hem için için sustum hem içime kanadım

Tövbe olsun ne haddim ne İbrahim’di adım

Güllerin ortasında yakılandım sadece.', 'Unutmadım unutmam,ne Elif''tim ne Lâm''dım Üstüne binbir anlam yıkılandım sadece. Ne aşkı emreylemiş ne bitirmiş kelâmdım En yanlış adreslere ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Doğan']::text[], 8.5, '{"poet":"Yavuz Doğan","poet_slug":"yavuz-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/animsamalar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi ve Sen', 'mavi-ve-sen-sezgin-cetin-t6j0w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavilere doyamadım dediğinde

Koptu film…

Hangi mavinin tonunda yaşanabilir ki 

Senin dalgaların

Sarar gibi kollarıma sığmıyor

Seni arzulamalarım.

Hiçbir yük senin kadar ağır değildi.

Sen koskoca bir derya,

Ve sana doyamamışlığım ise hala yüreğimde.

Hayal meyal dalgalarında yıkıldı 

Kumdan kalelerim

Kovamı da küreğimi de bana geri ver

Geri ver, sende kalmış yalnızlığım

Unutma 

Seni derya yapan, 

Sana akan gözyaşlarım', 'Mavilere doyamadım dediğinde Koptu film… Hangi mavinin tonunda yaşanabilir ki  Senin dalgaların Sarar gibi kollarıma sığmıyor Seni arzulamal...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Çetin']::text[], 8.5, '{"poet":"Sezgin Çetin","poet_slug":"sezgin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mavi-ve-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Ne Yazar Söylesene', 'simdi-ne-yazar-soylesene-yusuf-onder-bahceci-qxa70', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya''da gözün açık olanlar sevdiğin alır,

Bizim gibi utangaç olanlarda şiirler yazar,

Şimdi sana en güzel şiirleri ben yazsam,

Bilki Gökyüzünde gezen Güneşi versem,

Ay bedir olmuştur inan sen gibi desem,

Şimdi ne yazar, ne yazar söylesene sen.

Güzel gözlerin benziyor ceylana desem,

Saçları ipek mi acep sorsam öğrensem,

Cândan öte sevdiğim de yanımda yoksa,

Her gece mehtaba çıkıp, çıkıp ağlasam,

Sana yüzler değil, binlerce şiir yazsam,

Söylesene şimdi sen yaban ellerde isen,

Şimdi ne yazar, ne yazar söylesene sen...', 'Dünya''da gözün açık olanlar sevdiğin alır, Bizim gibi utangaç olanlarda şiirler yazar, Şimdi sana en güzel şiirleri ben yazsam, Bilki Gökyüz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/simdi-ne-yazar-soylesene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Karanfil Hakkı İçin', 'karanfil-hakki-i-cin-ahmet-turan-altunsu-bw031', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir güzel gülümsese,

erir içimde yağım,

başımda kavak yeli; 

yere basmaz ayağım…

elimde demet demet

karanfille beklerken,

çökse de bir nedamet

bilirim, vakit erken…

“ya sev ya terk et” demem...

gönül bu neme lâzım? ..

asla diyet ödemem; 

izin vermez alazım! ..

donmak mı, varsın olsun,

al karanfil çözülür...

dön, kalıver, son olsun; 

aşk eren dil çözülür…

haydi artık naz etme,

lal olmasın şu dilin,

sakın itiraz etme,

hakkı var karanfilin! ..

............31.01.2006 / Güdül / Ankara

.................Ahmet Turan Altunsu', 'bir güzel gülümsese, erir içimde yağım, başımda kavak yeli;  yere basmaz ayağım… elimde demet demet karanfille beklerken, çökse de bir nedam...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/karanfil-hakki-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tak Sepeti Koluna...', 'tak-sepeti-koluna-halide-selcan-karagul-00l51', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'tak sepeti koluna... 

Bir gün biri çıktı karşıma 

Talip oldu mütevazi hayatıma 

Kimdir nedir anla(ma)  dımda 

İyice araştırıp sorsamda 

İyi güzel mükemmele yakın olsada 

Nedense hiç uymadı bana 

Elektrik neyim derler ya 

Titreşim yaparmış iki cins arasında 

Öyle birşey olmadı aramızda 

Nedense kanım kaynamadı ona 

Yüreğime dur desem mantığımı kullansamda 

Elektrik almadı kalbim olmaz diyor ona 

Eksisiyle artısıyla 

Önce koydum terazinin darasına 

Ağır basıyor eksiler, artının darasına 

Eninde sonunda cevap vermek gerek ama 

Henüz bir karar çık(a)  madıki ortaya

Fazla oyalanmadan bir karar vermeli koymalı nokta 

Elektrik al(a)  madım kusura bakma 

Üzgünüm ama 

Gitmeli herkes kendi yoluna 

Hadi güle güle sana,

'' Tak sepeti koluna ''... 

..................... 

28.12.2005', 'tak sepeti koluna...  Bir gün biri çıktı karşıma  Talip oldu mütevazi hayatıma  Kimdir nedir anla(ma)  dımda  İyice araştırıp sorsamda  İyi ...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tak-sepeti-koluna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttur', 'unuttur-erdal-tohumcu-i29do', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'UNUTTUR..O..UMUTTUR

Yak sevdanın ateşini

 bu kıvılcım yetmez ki

Aynalara hapsolmuş yangın bizimkisi,

 dokunamam ki

Göhsume bastırsam,

 sarılıp sarmalasam,

içine dalsam,

 içinde kalsam

Mum gibi yansam,

 mum gibi harcansam

Unutulmuş bir sevdayı yaşayamamki

Rüzgara bıraktım seni,

kıymetimi bil, emi

Unut her şeyi  kurulacak düşleri 

Yazılacak öykuleri

Geçmişi, geleceği

Susuz açan çiçeği,uykusuz kaldığım geceyi

Kalan bir sen olmalısın yeryüzünde  birde...kim? ............,se

Yeniden filizlenen çiçekler 

Hanımelleri Sanalıktan uzak dünyalar içinede bulmak

Ellerine dokunmak,yureğne bakmak

Zamansız bir öyku belki yaşanacak

Esince ruzgarlar saçına vuracak

Nedensiz bir akşamda bulmak seni 

Nedenleri belki bende gizli belki…..

Sanalıktan uzak dünyalar içinede bulmak

Ellerine dokunmak,yureğne bakmak

Zamansız bir öyku belki yaşanacak

Esince ruzgarlar saçına vuracak

Nedensiz bir akşamda bulmak seni 

Nedenleri belki bende gizli belki…..

Sanalıktan uzak dünyalar içinede bulmak

Ellerine dokunmak,yureğne bakmak

Zamansız bir öyku belki yaşanacak

Esince ruzgarlar saçına vuracak

Nedensiz bir akşamda bulmak seni 

Nedenleri belki bende gizli belki…..

Sanalıktan uzak dünyalar içinede bulmak

Ellerine dokunmak,yureğne bakmak

Zamansız bir öyku belki yaşanacak

Esince ruzgarlar saçına vuracak

Nedensiz bir akşamda bulmak seni 

Nedenleri belki bende gizli belki…..

Ve gerisi

Yağmurun sesi

Bulutun nefesi

Çığlıklar kalmalı arkamızda 

birde inlemeler 

Doğa hayat bulmalı 

güneş batıdan doğmalı

Öykumuz katmersiz olmalı

Sevdamız sonsuzda kalmalı

Ve gerisi yağmurun sesi

 bulutun nefesi

Bu sevda bitmez ……ki

Gerçi sevdalarla işimiz olmadı 

Taşbaskısı plaklar kulanıldından beri

Erit beni 

   Tüket bedenimi 

Paylaş sevgimi

Ben sensiz yaşamamki

Bu öyku böyle bitmez ki

Plaklar bir yana taşıda koy ortaya

Durduramaz ki 

Unutamaz ki

Plakları kırmalı taşıda atmalı

Uykuyu unutmalı 

Bu gece depremler vurmalı

Çığlıklar ve inlemeler arasında

İki beden bir olmalı

Bu turku bitmez ki

Yağmuru durduramaz ki

Bulutu savuramazki

Bulut yağmurun 

Yağmur bulutunun

Selleri,delileri,elleri

Bulut yağmurun 

Yağmur bulutunun 

Öykuleri 

Hikayeleri

Sevişmeleri bitmez ki

  Kolaysa al beni  sıkıysa 

Sımsıkı elleri

Bırakma beni

Ve her şeyden ötesi, keşkeleri

Başını koysaydı göhsümü yarsaydı

9 yıl geç tanımış 900 km uzaktaymış

zamansız sarkaçlar altında 

sımsıkı elleri neyi beklerki

yaşanamayacak bir öyku bizimkisi

ruhumun karahip incisi

klavyemin bilmecesi

AŞKIM AŞKIN YANIYOR

SENİ İSTİYOR

YAĞMURU BEKLİYOR

BULUTU EKLİYOR

BÜTÜN VÜCÜDÜMA DOKUN

UNUTTUR…………………………………………………….UMUTTUR….', 'UNUTTUR..O..UMUTTUR Yak sevdanın ateşini  bu kıvılcım yetmez ki Aynalara hapsolmuş yangın bizimkisi,  dokunamam ki Göhsume bastırsam,  sarıl...', ARRAY['Türk Edebiyatı','Şiir','Erdal Tohumcu']::text[], 8.5, '{"poet":"Erdal Tohumcu","poet_slug":"erdal-tohumcu","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/unuttur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Floş Royal', 'flos-royal-mehme-arslan-iodp8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tükürükle temizlenen ayakkabılar

denli parlak yaşamımda

fırçada kalan cilalarla

parlatılmış hayallerim

mahalle arkadaşlarının

bi saat bile sürmeyen küslüklüklerinde

birbirine duydukları kadar kinim

aynaya her baktığımda

biraz daha genişleyen alnıma

uydurduğum bahanelerim

ve avurtlarımda

gamze olamayacak kadar büyük

çöküntülerim var

sıra sende

aç da görelim

nasılmış elindeki kartlar

31/01/2006', 'tükürükle temizlenen ayakkabılar denli parlak yaşamımda fırçada kalan cilalarla parlatılmış hayallerim mahalle arkadaşlarının bi saat bile s...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/flos-royal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunları biliyorsun', 'bunlari-biliyorsun-erdal-tohumcu-yxg1f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bunları biliyorsun

Biliyorsun bunlarıda

Sonbaharda dökulen yaprakları ve güzü,beyaza burunuşu

Geçen arda arda geçen bir şeyler var yanımızdan

Sesiz sedasız kalyoncular kürek çekiyor

Bunları biliyorsun,,,……..durduramıyorsun

Soğuk….., içimi acıtacak kadar…soğuk,

Soğuk……canını yakacak kadar …,soğuk

Ayazdan kalan bir esinti bırakıyorsun

Bunları biliyorsun………………. yinede……………….,

Nedemeli,şimdi

 mevsimlerin sesizliği ardına gizlenen,yaralı kuş

Uçmak mı istiyorsun uç, bana doğru uç, buraya doğru

Kabarta kabarta dalgaları

Vurdura vurdura kanatlarını

Bilipte yapamadığın çok şey var

Kanat çırpmak,önüne bakmak,buraya varmak

Bunları biliyorsun………..yinede………………,

Sen bunca aydınlıkta gözlerini kapıyorsun

İlede yamaçtan aşağı gitmek,ucurumu görmeden

Boşlukta yürümek istiyorsun 

Yürü yamaçtan yükarı bayıra yanaş soluklan

Başka bir yamaç ara uçurumu olmayan

Bunları biliyorsun…..yinede……….

Bunca aydınlıkta kendini boşluğa bırakıyorsun

Neden bekliyorsun

 korkularını karabasan yapıp,yatağına alıyorsun

sonra umut umut diye haykırıyorsun

kırık aynalar bırakıyorsun

sönen mumlar

unutulmuş türküler

sen kendine hiçmi acımıyorsun 

sonrada bunları biliyorum diyorsun

hak etmedim diyorsun ki

hakını kendin veriyorsun

Sözsuz sevdalar vardır bazılarımızın bilmediği

Onları bakışlarda bulacaksın

Dokunuşlarda

Yıldızlarda

Gecenin tam ortasında

İsimsiz tlf larda

Sigaranın dumanında

Saçımızın akında,kalanında

Ve bunları biliyorum diyorsun

Bilipte yapmadığımız çok şey var bu dünyada

Unutmakmı istiyorsun,unut

Beni de unut 

onuda

uykunda sayıkladığın bir kabus bil onu

beni ne istersen öyle

unut

benim düşüncelerimi de biliyorsun

değer verdiğini hissetiriyorsun

sarkaçları salıyorsun

zamanı geri alıyorsun 

geçmişten utanma

gelecekte tekrarlama ki

demeye kalmadan

bunları biliyorum diyorsun

bildiğin gibi ol 

olduğun gibi bilme

sana aşık olabilirdim seni seve bilirdim

bir tlf tuşuna takılı kalmasaydım

bir tekrarın içine dalmasaydım

Soğukluğunu tatmasaydım

Sesiz sedasız gitmemimi istiyorsun

Yamaçlar senin olsun

Bayırlar uçurumlar

Dağlar, uçsuz bucaksız sevdalar

Söylenmeyen türküler

Tual in kasım mı

Sana ayırdığım

Dizeleri

Verebileceğim, ne varsa 

Bir elvedanın ardından', 'Bunları biliyorsun Biliyorsun bunlarıda Sonbaharda dökulen yaprakları ve güzü,beyaza burunuşu Geçen arda arda geçen bir şeyler var yanımızda...', ARRAY['Türk Edebiyatı','Şiir','Erdal Tohumcu']::text[], 8.5, '{"poet":"Erdal Tohumcu","poet_slug":"erdal-tohumcu","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/bunlari-biliyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm!', 'gulum-mesut-ozturk-haumu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yollara yol dağlara dağ demedim,

Eksikliğini hissettikçe inan hiç gülmedim,

Senin üstüne başka birini, zaten sevmedim,

Sen benim birtanem, canımsın be Gülüm! 

Bana Dünya`nın en zengini ol deseler,

Alemdeki bütün imkanları verseler,

Mutlu olmak için al herşey senin deseler,

Senin bir damla gözyaşına değişmem be Gülüm! 

Hey sevenler! Birbirine gönlünü verenler! 

Bakın gözlerinizin içine mutluluğu hissedin,

Ayrılık olmadan aşkınıza sıcaklığınızı verin,

Benim sana kalbimi verdiğim gibi be Gülüm! 

Seni seviyorum, gönlümün sultanı,

Sana aşığım, hayatımın baharı,

Herzaman sen olacaksın, kalbimin yarı,

Sen olmazsan ne yapayım bu hayatı? 

Sana ihtiyacım var be Gülüm! 

Seni böyle gördüm ya Dünyam yıkıldı,

Çektiğin acıları yaşadım Gülüm! 

Meğer sana neler etmişler? 

Saçının bir teline kurbanım be Gülüm! 

Sevgini yitirmedin, Saygısız asla olmadın,

Attın haklı olsanda içine attın,

Acıyı yaşadın, Mutluluğu yaşattın,

Ben senin sabrına hayranım be Gülüm! 

Sana olan hasretimi kitaba yazdım,

Aşkımı ömür boyu kalbime kazdım,

Sen olmazsan zaten yapamazdım,

Gözünün bebeğine Hasretim be Gülüm! 

Senle olup seninle yaşamak,

Seni sevip, senin Dünyanda olmak,

Sana aşkmı verip kalbinde kalmak,

Mutlulukları seninle paylaşmak,

Uğrunadır bütün amacım Gülüm!', 'Yollara yol dağlara dağ demedim, Eksikliğini hissettikçe inan hiç gülmedim, Senin üstüne başka birini, zaten sevmedim, Sen benim birtanem, c...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gulum-179-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*On Oniki Nöbeti', 'on-oniki-nobeti-huseyin-sonmez-l036e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyorum beni düşünüyorsun,

Elini başının arasına almış

Camın kenarına oturmuş

Beni düşünüyorsun...

Dışarda hoyratça esen

Rüzgâra,

Savrularak yağan

Kara bakarak

Belki gelecekten korkarak

Beni düşünüyorsun.

Gözlerinden ağır ağır

Yaşlar süzülüyor

O pembe yanaklarına.

O alev gibi yanan dudaklarına

Bir ateş düşmüş

Beni düşünüyorsun.

Biliyor musun ben nerdeyim? 

Bir tepenin ardında kederdeyim.

Ellerim üşüyor Leylâ''m ellerim

Tüfek buz gibi,

Yüreğim titriyor,

Korkudan değil 

Soğuktan,

Donup kalmaktan.

On oniki nöbeti biterse

Senin resmine bakarak,

Bir de sigara yakarak

Belki bir sıcak çay içerim.

Dün yine dağlara çıktık

Karlı dağlara,

Oradan sana seslendim

Sesimi  duydun mu? 

Ben çok sesler duydum Leylâ''m

Çok sesler...

Tüfek sesleri,mermi sesleri,

Mayın sesleri...

Hiçbirisi senin sesin gibi

Değildi.

Karakola yine bomba attılar.

Allah''tan

Kimseye bir şey olmadı.

Sadece Hasan Çavuş yaralandı.

Bir iki cam kırıldı o kadar...

Şimdi camın kenarından ayrıl,

Ağlama artık benim için

Kırmızı elbiseni giyin,

Alt kata in

Kendine bir çay demle

Yaşanmaz böyle

Elemle...

Eline bir kitap al,

Ruhunu enginlere sal

Bırak beni düşünme

Sen kendinle kal.

İki ay 

Çabuk geçer

Leylâ''m

Çabuk geçer

Kader yepyeni 

Bir sayfa açar

Üzülme...

Yine beraber baş başa

Çayımızı yudumlarız.

Benim  nöbetim bitmek üzere

İçeriye gireceğim.

Karşımda seni hayal ederek

Çayımı içeceğim.

Bir ses duydum Leylâ''m

Bir ses! 

Senin sesin değil bu! 

İçimi ısıtan kurşun sesi

Sanki Azrail''in nefesi! 

Ah! Vuruldum Leylâ''m

Vurdular beni.

Korkma sadece yaralıyım

İçeriye götürüyorlar beni,

Söz verdim resmine bakarak

Bir de sigara yakarak

Çayımı yudumlayacağım

Leylâ''m

Çayımı yudumlayacağım

Leylâ''m

Çayımı yudumlayacağım....', 'Biliyorum beni düşünüyorsun, Elini başının arasına almış Camın kenarına oturmuş Beni düşünüyorsun... Dışarda hoyratça esen Rüzgâra, Savrular...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/on-oniki-nobeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesabını Soramadım Soramıyorum', 'hesabini-soramadim-soramiyorum-yusuf-onder-bahceci-lftdo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevdim güzelim engel oldular,

Balık oltası gibi hep çengel oldular,

Bilki beni bu kalleşler yere vurdular,

Hesabını soramadım, soramıyorum.

Ben avcı değildim, balıkçı değildim,

Sade seni sevdim gönlümü verdim,

Bunlar kalleş imişler ben bilemedim,

Hesabını soramadım, soramıyorum.

Hesabını nasıl sorayım akrabamdır,

Akrabam mı yoksa bir hasım mıdır,

İnsanların hepsi de kısım, kısımdır,

Hesabını soramadım, soramıyorum.

Yorgan gitti güzelim kavga da bitti,

Olan bizim sevdamıza oldu da gitti,

Bu kalleşler edeceğini sonunda etti,

Hesabını soramadım, soramıyorum....', 'Seni sevdim güzelim engel oldular, Balık oltası gibi hep çengel oldular, Bilki beni bu kalleşler yere vurdular, Hesabını soramadım, soramıyo...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hesabini-soramadim-soramiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli yürek', 'deli-yurek-durdu-mehmet-dalkanat-1ajrg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir el..

Kabil''in kanlı eli...

Uzanıyor ciğerimin içine...

Yahudanın yarılan bedeninden,

Bağırsaklar dökülüyor,

Ruhuma.

Ruh coğrafyam ''ala delma''

Kamçılarla pişmiş sırtlarda,

taşınan taşlar.

Ve o taşlarla örülen vahşi piramitler.

Tıkanıyorlar ağzıma.

Sel sel oluyor.

Çığlık yüklü terler.

Fışkırıyor tenimden terler.

Ashab-ı uhdud.

Kahrolası Ashab-ı uhdud.

Cehennemi bir kanal açıyor.

Deli yüreğimde.

Mancınıkta İbrahim.

Atılıyor nemrudun ateşiyle.

Yanan kalbime.

Ben günahkar kent Babilim.

Yıkım bendedir.

Kudüsüm.

Onbeşbin çarmıh

Üzerimdedir.

Doluyum.

Taşıyorum.

Siyah üzüm tanesi

Köleler...

Ağzı toprak kokan

Plepler...

Ülkesizler...

Evsizler...

''Ruhsuz'' denen dişiler..

Ve çıplak bırakılmış erkekler...

Ve eli nasırlı tüm proloterler...

Sonsuz bir kuyruk.

Bir feryadın dudağında,

Ağır ağır yol alan kuyruk.

Yol içime...

Mahşeri kalabalık.

Kalabalık içimde..

İçim mahşer...

Kundakta yatan bebeğin,

Sessizliğine düşen,

Kılıçların gölgesi.

Yeryüzü melekleri çocukların.

O çocukların,

Korkuya esir düşen,

Prangalı gözleri.

Seni lime lime eder.

Asit gölüne düşmüşçesine,

Parçalar.

Deli yüreğim.', 'Bir el.. Kabil''in kanlı eli... Uzanıyor ciğerimin içine... Yahudanın yarılan bedeninden, Bağırsaklar dökülüyor, Ruhuma. Ruh coğrafyam ''ala d...', ARRAY['Türk Edebiyatı','Şiir','Durdu Mehmet Dalkanat']::text[], 8.5, '{"poet":"Durdu Mehmet Dalkanat","poet_slug":"durdu-mehmet-dalkanat","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/deli-yurek-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı!', 'yabanci-mesut-ozturk-ra77k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyorum şimdi sen, onu düşünüyorsun,

O sana çok uzak, bunu iyi biliyorsun,

Kendine soruyor ve neden hep ben diyorsun? 

Ama şuna inan onun tarafından seviliyorsun,

Hey tatlılar tatlısı, o seni seviyor,

Oda seninle mutlu olmak istiyor,

Yüzde yüz şuanda seni hayal ediyor,

Mesut size sesleniyor ve hep sevin diyor.

Sus dilim, söyleme dur diyorsun artık,

Ellerim, yazma bırak diyorsun artık,

Gözlerim ağlama, sevdiğim var diyorsun artık,

Şimdi anlıyorum aşıksın geç kaldım artık.

Ben yaban ellerde bir yabancı,

Bazı sözlerim geliyordur yalancı,

Tek dileğim mutlu ve güçlü ol,

Sana seslenir işte böyle bu yabancı!', 'Biliyorum şimdi sen, onu düşünüyorsun, O sana çok uzak, bunu iyi biliyorsun, Kendine soruyor ve neden hep ben diyorsun?  Ama şuna inan onun ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yabanci-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ıma Dualar Eder Ağlarım', 'allah-ima-dualar-eder-aglarim-yusuf-onder-bahceci-1wkqe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vallahi benim için Yaratmış Rabbim,

Kalbimden bilirim ben bilirim Rahim,

Senden ayrıyım ben Allah''ım Kerim,

Allah''ıma dualar eder, eder ağlarım.

Benim sevdamı daim Allah''ım bilir,

Beni kendi Yaratmıştır kendisi bilir,

Önder Rabbisi için binler cân verir,

Allah''ıma dualar eder, eder ağlarım.

Cennet, mennet istemem ki o bilsin,

Alemleri Yaratan, Rahman''dır ismin,

Allah''ım nasıl severim bunu bilirsin,

Allah''ıma dualar eder, eder ağlarım.

Allah''ım bu kalbimden alma imanım,

Sen sevmişsen beni olmaz figanım,

Sevdiğimdir benim derde dermanım,

Allah''ıma dualar eder, eder ağlarım....', 'Vallahi benim için Yaratmış Rabbim, Kalbimden bilirim ben bilirim Rahim, Senden ayrıyım ben Allah''ım Kerim, Allah''ıma dualar eder, eder ağla...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/allah-ima-dualar-eder-aglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genç!', 'genc-mesut-ozturk-s3w64', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son model araba ve aksesuar,

Geniş tekeri çelikten cantı var,

Gaza bastığımda herkes bana bakar,

vaybe yerle arasında bir parmak var.

Elbisem son moda kimsede yok,

ayakkabım adidas bende para çok,

Hergün et yerim o yüzden karnım tok,

Ben çok zenginim kıskananım çok.

Tere yağlı ekmek ve balın yanında,

Salamsız sosizsiz olmaz kahvaltım,

Umurumda değil Dünya herşeyim var,

fakir çoksa banane. Nedir benim günahım? 

Param olması mı?', 'Son model araba ve aksesuar, Geniş tekeri çelikten cantı var, Gaza bastığımda herkes bana bakar, vaybe yerle arasında bir parmak var. Elbise...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/genc-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutku', 'tutku-nilgun-acar-zvywy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen

bir bardak su

yaşama tutkusu

içtikçe doyamadığım

bir türlü kanamadığım

Sen

nefes nefes hava

dağılmış hücrelerime

canıma can katan

beni ben yapan

Sen

güneş güneş gözlerimde

bitimsiz güç ellerimde

erişilmeyeni çekip aldığım

kader duvarlarını aştığım

Sen

dayanılmaz arzu bedende

kanıma giren şeytan

benliğimi ateş ateş yakan

çılgın coşku yüreğimde

Sen

şiir şiir doyumsuz ruhumda

yedi renk gökkuşağı gönlümde

kutsal ezgi dudaklarımda

aşk diz çöküp taptığım önünde

Sen

yağmur yağmur bereket

kavuşuldukça dinmeyen hasret

tanrının bağışladığı hayat

özgürlüğe çırpınan kanat', 'Sen bir bardak su yaşama tutkusu içtikçe doyamadığım bir türlü kanamadığım Sen nefes nefes hava dağılmış hücrelerime canıma can katan beni b...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Acar']::text[], 8.5, '{"poet":"Nilgün Acar","poet_slug":"nilgun-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tutku-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözümü söylerim', 'sozumu-soylerim-fatma-guven-jxl99', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söz ola beri gele,meclis kurula.

Söz ola aymazı ayan eyleye.

Sinesine çekipte oturan bir köşeye,

Zamanı gelince derdini dile getire.

Sırtım pek, bileğim pek,özüm pek.

Kaya gibi sert,yerince yüreğim ipek.

Oynamayı bilmeyipte meydana çıkan köçek,

Ne anlarsın sevgiden,bağlılıktan dönek.

Sözü söyler isem sinemden söylerim.

Bana da rağbet yok ise bu diyardan giderim.

Kah ağlar, kah da mevlama gönerim.

Bu sözlerim yalan ise Hak''kıma ne derim?', 'Söz ola beri gele,meclis kurula. Söz ola aymazı ayan eyleye. Sinesine çekipte oturan bir köşeye, Zamanı gelince derdini dile getire. Sırtım ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sozumu-soylerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* * Bırakmasa * *', 'birakmasa-tuba-celik-zkqje', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbin son durağıdır tüm yolculuklarımın

Ayaklarım ıslak gelirim sana, ellerim soğuk

Dudaklarıma pamuk şekeri sunar dudakların,

İnciler döker sana içimdeki çocuk.

Rastladığım en beyaz limansın desem,

Tarifsiz mucizelerle kollarına gelsem,

Aşkın matem olsa da ayrılmak ne mümkün! 

Nasılsa ezberledim, sensizlikte de var ''sen''.

Yıldızlar mı düşmüş gözlerine sevdiğim? 

Işıksız günlerim için ruhuma at bir dikiş

Layık değil ikimize de bu sınırlı vakitler,

Doğuştan hastadır hep yokluğunda günlerim.

Ilık nefesin öpsün beni, günlerce, gecelerce,

Zor biliyorum ama bırakmasa hiç ellerin.', 'Kalbin son durağıdır tüm yolculuklarımın Ayaklarım ıslak gelirim sana, ellerim soğuk Dudaklarıma pamuk şekeri sunar dudakların, İnciler döke...', ARRAY['Türk Edebiyatı','Şiir','Tuba Çelik']::text[], 8.5, '{"poet":"Tuba Çelik","poet_slug":"tuba-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/birakmasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok ki!', 'yok-ki-mesut-ozturk-3v8r7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sus bilmiyorsun konuşma! Derdin ne olduğunu? 

Nerden anlayacaksın? Sende kalp yok ki.

Dur dinleme! Bilemezsin aşkın ne olduğunu? 

Anlayamazsın! çünkü sende vicdan yok ki! 

Sen hiç ölümüne sevdin mi? 

Bir canan uğruna hayatını verdin mi? 

Anlayış göstererek kenara çekildin mi? 

Hayır çünkü sende yürek yok ki! 

insanlık nedir bilir misin? 

Sevgi ve aşkın hesabını verir misin? 

Sana dağlardan geç desem gelir misin? 

Hayır çünkü sende mertlik yok ki! 

yazıklar olsun sana verdiğim emeklere,

Kahırlar olsun gösterdiğim ilgiye,

Mahvoldum sevgilim birtanem diye diye,

Al aşkını başına çal çünkü sende ahlak yok ki!', 'Sus bilmiyorsun konuşma! Derdin ne olduğunu?  Nerden anlayacaksın? Sende kalp yok ki. Dur dinleme! Bilemezsin aşkın ne olduğunu?  Anlayamazs...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yok-ki-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın', 'kadin-mustafa-erol-lbqhw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kadın 

Başlara taçsın, gönüllere ilaç. 

Sen bil ki, hayatın özüsün kadın. 

Herkes sana hasrettir ve de muhtaç. 

Sen bil ki, hayatın özüsün Kadın 

Kız kardeşsin, evlerimize direk. 

Eşsin, senin için çarpar her yürek. 

Anasın, bir başka söze ne gerek? 

Sen bil ki, hayatın özüsün Kadın 

İçindeysen güzeldir, hayal ve düş, 

Senin yokluğun bil, bin ölüme eş. 

Kıskanır inan, seni gökte güneş. 

Sen bil ki, hayatın özüsün Kadın 

Değil; elmas, yakut ve de altına, 

Değişilmezsin sen, dünya tahtına. 

Serilmiş cennet, ayağın altına. 

Sen bil ki, hayatın özüsün Kadın.

Hazreti Âdem için, Havva sensin.

Kendini bilen için, deva sensin.

Dağ sensin, deniz sensin, ova sensin.

Sen bil ki, hayatın özüsün Kadın.

Mustafa Erol

Manavgat İlçe Milli Eğtim Şube  Müdürü', 'Kadın  Başlara taçsın, gönüllere ilaç.  Sen bil ki, hayatın özüsün kadın.  Herkes sana hasrettir ve de muhtaç.  Sen bil ki, hayatın özüsün K...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Erol']::text[], 8.5, '{"poet":"Mustafa Erol","poet_slug":"mustafa-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kadin-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kul yaralıydı (O anki duygularım)', 'kul-yaraliydi-o-anki-duygularim-tuncay-akdeniz-c29qc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Haber salamadım seven canlara

Kesildi hatlarım tel yaralıydı

Neşeyle girmiştim yeni yıllara

Ömür bitti sandım yıl yaralıydı

Hasta yatağına koymuştum başı

Acı dertler oldu can arkadaşı

Unuttu sanmayın dostu kardeşi

Konuşamaz oldum dil yaralıydı

Dostların sevgisi dünyaya değer

Son şiirim olsun ölürsem eğer

Dinmedi acılar sızlıyor ciğer

Kırıldı kanadım kol yaralıydı 

Ecel konmuş sandım can odağıma

Dolu yağdı yamacıma dağıma

Ayrılık rüzgarı esti bağıma

Döküldü yaprağım dal yaralıydı

Alnıma yazılmış silinmez yazı

Değişmiş bende yaşamın tarzı

Hakka teslim ettim bendeki özü

Hasta yatağında kul yaralıydı

Tüm dostlara selam olsun buradan

Sağlık sıhhat versin size yaradan

Haberim olmadı yazdan bahardan

Solmuştu bahçemde gül yaralıydı

On bir yıldır dinmez yürekte sızı

Sabır edenlerin gülermiş yüzü

Bu Tuncay ölmeden unutmaz sizi

Yazmadı kalemim el yaralıydı 

15.01.2006', 'Haber salamadım seven canlara Kesildi hatlarım tel yaralıydı Neşeyle girmiştim yeni yıllara Ömür bitti sandım yıl yaralıydı Hasta yatağına k...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kul-yaraliydi-o-anki-duygularim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri Var!', 'biri-var-mesut-ozturk-cq33b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne durumda hangi ortamda bulunursak bulunalım,

Herkesin bir ortak noktası vardır.

Hepimizin hayatını mahveden,

Hepimize yaşama sevinci veren,

Biri vardır.

İşte o biri varya? bizlerin ortak noktasıdır.

Her insanın bir amacı, hayali birde tutkusu vardır.

O tutku varya? Bizlerin ortak noktasıdır.

herkes birşeylere özlem duyar,

Hasret çeker, işte bu bizlerin ortak noktasıdır.

Biri var, hayatımı mahveden,

Biri var Dünyamı şenlendiren,

Biri var herşeyi zehir eden,

Biri var bize yaşama sevinci veren,

işte o biri varya? Hepimizin biri.', 'Ne durumda hangi ortamda bulunursak bulunalım, Herkesin bir ortak noktası vardır. Hepimizin hayatını mahveden, Hepimize yaşama sevinci veren...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biri-var-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Dokunuşlar', 'beyaz-dokunuslar-bekir-mutlu-gokcesu-5xk8e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Girdabındayım...

Ekin sarısı bir devinim 

Kesiyor nefesimi...

Azcık soluk, azcık can? 

Yosun kokusunda bahar...

Kışı da andırıyor dokunuşlar...

Su alıyor kayık 

Ayaklarım ıslanıyor, üşümüyorum

Su alıyor kayık

Batmayacak kadar...

Maviye karışmak istiyorum oysa

Olmuyor içime dokunuyor

Beyaz dokunuşlar...

Kırmızıdan yoksun bir paletin

Körkütük ayık armonisinde

Rengimi kaybediyorum

Girdabındayım...', 'Girdabındayım... Ekin sarısı bir devinim  Kesiyor nefesimi... Azcık soluk, azcık can?  Yosun kokusunda bahar... Kışı da andırıyor dokunuşlar...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beyaz-dokunuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecnun oldum', 'mecnun-oldum-gulali-olmez-uuhfc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yitik gecelerin sarhoşuyum ben

Leyla nın Aslı nın berdoşuyum ben

Umudunu yitirmişlerin kardeşiyim ben 

Bana gel elini bana ver

Bana gel gülünü bana ver 

Yolunu kaybetmişlerin yoldaşıyım ben

Azrail kapıda gülüm can bedende

Sokaklara hüzün yağar sen gidende

Dağlara sitem ederim özlediğimde

Bana gel elini bana ver

Bana gel gülünü bana ver

Başka bir el olmadıki hiç ellerimde

            31.01.2006', 'Yitik gecelerin sarhoşuyum ben Leyla nın Aslı nın berdoşuyum ben Umudunu yitirmişlerin kardeşiyim ben  Bana gel elini bana ver Bana gel gülü...', ARRAY['Türk Edebiyatı','Şiir','Gülali Ölmez']::text[], 8.5, '{"poet":"Gülali Ölmez","poet_slug":"gulali-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mecnun-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir Gönül Senden Çektiğim Yeter!', 'nedir-gonul-senden-cektigim-yeter-hadi-onal-1og4j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yük ağır, yel deli, dal mı dayanır

Akıntı çok güçlü, sal mı dayanır

Dur durak bilmezsin, hal mı dayanır

Nedir gönül senden çektiğim, yeter! 

Her güzele âşık, her güle mecnun

Dağıtır bol kese, sanırsın Karun

Rest çeker akıla, isteği kanun

Nedir gönül senden çektiğim, yeter! 

Gün oldu sıkıldın, durmadın estin

Daldan dala kondun, alındın, küstün

Yerlerde sürüttün nefesim kestin

Nedir gönül senden çektiğim, yeter! 

Günün ortasında bakarım gece

Çözene aşk olsun; sırsız bilmece

Nazın çile bana, işven işkence 

Nedir gönül senden çektiğim, yeter! 

Hem incittin canı hem de ağlattın

Kaybolan benimi, bensiz arattın

Yanıyorum dedim, sen oda attın

Nedir gönül senden çektiğim, yeter! 

Eskidi zamanlar, kaç oldu sene

Ben ömrümü verdim, doymadın yine

Uslan artık uslan, otur köşene

Nedir gönül senden çektiğim, yeter! 

Hadi, tamam dedi; sen efelendin

Akılı, mantığı, nizamı yendin

Artık dermanım yok; ilaç mı? Kendin

Nedir gönül senden çektiğim, yeter!', 'Yük ağır, yel deli, dal mı dayanır Akıntı çok güçlü, sal mı dayanır Dur durak bilmezsin, hal mı dayanır Nedir gönül senden çektiğim, yeter! ...', ARRAY['Türk Edebiyatı','Şiir','Hadi Önal']::text[], 8.5, '{"poet":"Hadi Önal","poet_slug":"hadi-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nedir-gonul-senden-cektigim-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Dünya', 'merhaba-dunya-nilgun-acar-m0y3b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben insanım doğanın en güzel süsü

usumdan doğdu binlerce yıllık uygarlık

ve avuçlarımda sonsuz bir gelecek

çözülürken zamanın yumağı usul usul

çözdüm sayısız gizi düşe kalka

mevsimlere umut ektim ürünüm ışık

adım sevgi evren benimle güzel

kanatları kopuk bir kuş olsam da

koşarım yüreğimle direnirim acılara

dalgaların köpüklerinde çiçeklenir yaşama sevincim

ve akar parmakuçlarımdan apak sayfalara

bir bebeğin ilk çığlığından merhaba dünya', 'Ben insanım doğanın en güzel süsü usumdan doğdu binlerce yıllık uygarlık ve avuçlarımda sonsuz bir gelecek çözülürken zamanın yumağı usul us...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Acar']::text[], 8.5, '{"poet":"Nilgün Acar","poet_slug":"nilgun-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/merhaba-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyetim.', 'cumhuriyetim-kadir-kaya-3hwfq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçmişi bilirsek yaşanmaz acı,

Çalışır, üretir anayla, bacı,

Demokrasi  takar özgürlük tacı,

Halkımızla coşar Cumhuriyetim.

Ülkemde her yere uzanır elim,

Duru türkçemizi konuşur dilim,

Çağı yakaladık, gelişti bilim,

Hayallerden taşar Cumhuriyetim.

Uzaya  uyduyla attık okları,

Ülke refahında sildik yokları,

Yurdumda eşittir insan hakları,

Aydınlığa koşar Cumhuriyetim.

Doğruluk, adalet buluşur özde,

Yaşanan mutluluk okunur yüzde,

Hakimiyet mutlak halkındır bizde,

Gönüllerde yaşar Cumhuriyetim.

Mustafa Kemal’im umut gülümüz,

Karanlıkta oldu ışık yolumuz,

Kadirim, gençlerdir hazır balımız,

Engelleri aşar Cumhuriyeti.', 'Geçmişi bilirsek yaşanmaz acı, Çalışır, üretir anayla, bacı, Demokrasi  takar özgürlük tacı, Halkımızla coşar Cumhuriyetim. Ülkemde her yere...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cumhuriyetim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feyzi Halıcı', 'feyzi-halici-kadir-kaya-ks0zf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kültürde, sanatta asırlık ocak,

Hala ilk gün gibi yüreği sıcak,

Birliğe sevgiyle açıyor kucak,

Sabırın gölüdür Feyzi Halıcı.

Mesnevi, tasavvuf farklı bir etap,

Candan vazgeçerken  canana hitap,

Tek bir dörtlüğünden yazılır kitap,

Sevginin selidir Feyzi Halıcı.

Aşıklara bayram oldu sesleri,

Mevlana’ya hizmet gönül süsleri,

Nice eserlerde coşar hisleri,

Sevdanın gülüdür Feyzi Halıcı.

Yıllarca meçliste okundu adı,

Cihana tanıttı lezzeti, tadı,

Vefayla sürmeli mutluluk yadı,

Dostluğun elidir Feyzi Halıcı.

Çağın hocasını sevdiğim doğru,

Ruhumda başlarsa açlıktan ağrı,

Gönüle şifadır dergimiz Çağrı,

Duygunun yelidir Feyzi Halıcı.

Onunla sevdim ben Pere Palası,

Tertemiz hayatı, yaşar ihlası,

Duamdır, Cennet olsun silası,

Muhabbet yoludur Feyzi Halıcı.', 'Kültürde, sanatta asırlık ocak, Hala ilk gün gibi yüreği sıcak, Birliğe sevgiyle açıyor kucak, Sabırın gölüdür Feyzi Halıcı. Mesnevi, tasavv...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/feyzi-halici-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevildiğimi', 'sevildigimi-sevinc-kavuk-firqr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hem ne çok sevdiğimi 

Sevişmek istediğimi de

…….gökkuşağı sonsuzluğunda

…….doludizgin hırçın bir rüzgârla

.........kuru yapraklar gibi savrulan

........ çöl kumları hararetiyle

Başarısında bulacağım

Sevildiğimi! 

31.01.2006

Salı 19.30', 'Hem ne çok sevdiğimi  Sevişmek istediğimi de …….gökkuşağı sonsuzluğunda …….doludizgin hırçın bir rüzgârla .........kuru yapraklar gibi savru...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevildigimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kandil Işığı Kanar Duvarda', 'bir-kandil-isigi-kanar-duvarda-durmus-kaya-o8idu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakışların kanıma üşüşünce

Sen aklıma usul usul düşünce

Kimse bilmez sessiz ağladığımı! 

Ateşlere düşen damlalar gibi

Esriyip esriyip çağladığımı! 

Güneşin batışı ayın doğuşu

Bir kanlı kılıçtır göğsüme giren

O hatıralarla.. hatıralarla! …

Bütün kaldırımlar perondur şimdi

Hemence kalkacak sanki o tren! 

Yüreğim gelincik açan bir tarla

Ve bütün bakışlar Neron’dur şimdi! 

Kimse bilmez sessiz ağladığımı

Sen aklıma usul usul düşünce

Gurbetin kimsesiz sokaklarında

Bakışların kanıma üşüşünce

Adımlarım ağır çekim tedirgin

Gözlerim camlarda yüzün var gibi

Ümitle ışıldar ve söner birden

Damlalar kor olur şakaklarımda

Nisan toprağına yağan kar gibi! 

Göğsüm kafesinde çırpınır durur 

Binlerce yaralı turnaya bedel! 

Diktiğim çiçeğin toprağı kurur

Aramız bir karış sanki güneşle

O gece nerde ey, bin ay’a bedel? 

Neden bu saatler zamansız vurur? 

Gece var içimde bir bahar gibi 

Gece var, içinde ben buhar gibi

Devlerin nefesi ensemde solur

Bir kandil ışığı kanar duvarda

Ve bütün gurbetler hep benim olur! 

Kimse bilmez sessiz ağladığımı

Ey toprak ana ey vefalı diyar

Üstündeki tozlar kadar hiç kimse

Hey! Yar kucağına uzanan yollar

Sıla benim yurdum, gülü gülümse

Yılan gibi kıvrıl ip gibi bükül

O gönül çehrenle bana gülümse

Al benisi esriyince o güzel

Hilal kaşlarını çatmıştır yine

Ahu gözlü dudu dilli o güzel

Gece yıldızlarla yatmıştır yine

Ey kandil titreme artık sızımdan

Ağıt dökülse de dertli sazımdan!', 'Bakışların kanıma üşüşünce Sen aklıma usul usul düşünce Kimse bilmez sessiz ağladığımı!  Ateşlere düşen damlalar gibi Esriyip esriyip çağlad...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Kaya']::text[], 8.5, '{"poet":"Durmuş Kaya","poet_slug":"durmus-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bir-kandil-isigi-kanar-duvarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersem', 'gidersem-levent-kapisiz-4oaql', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gülücük istiyorum senden

Sonsuzluk duygusundan izler taşıyan

Yolun bittiği ve herkesin gittiği yere

Apansız ve sorgusuz

Yürüyemeden ele ele gidersem bir gün

Sen bazen yağmur,bazen karsın

Apansız yağarsın hasret olup

Sen bulutlar dolusu yağ toprağıma

Yürüyemeden el ele gidersem bir gün

Yalnız duramam ben

Korkarım sessizlikten

Hele hele de sensizlikten

Sen gece yıldız ol

Yürüyemeden el ele gidersem bir gün

Gecenin gölgesi düştüğünde tan yerine

An gelir gözlerin gelir aklıma

An gelir sözlerin çınlar kulaklarımda

Can gelir toprağa düşen bedenime

Sen gelirsin  hatrıma

Yürüyemeden el ele gidersem bir gün

Sevdiğim Allah’a ol emanet

Ederde bu benden bana ihanet

Koklayamadan gidersem seni

Gülleri deremezsem bırakalım mahşere

Yürüyemeden el ele gidersem bir gün', 'Bir gülücük istiyorum senden Sonsuzluk duygusundan izler taşıyan Yolun bittiği ve herkesin gittiği yere Apansız ve sorgusuz Yürüyemeden ele ...', ARRAY['Türk Edebiyatı','Şiir','Levent Kapısız']::text[], 8.5, '{"poet":"Levent Kapısız","poet_slug":"levent-kapisiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gidersem-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimiz', 'i-kimiz-mustafa-yigit-fzvud', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Külkedisi misali tanımıştım 

Yaktı kül eyledi kalbimi 

Günlerce aradım dağda bayırda 

Prens,prenses misali, kavuştuk 

Yeni bir çağ atladık ikimiz 

Kalbimi alıp,kalbine koydu

Can verdi,her nefesinde 

Bedel ödedik birlikte 

Savaştık,sevdamız için

Geleceğe,ışık tuttuk ikimiz 

Aynı kan dolaştı damarlarımızda 

Çimlendirdik,her damlasını 

Can oldu.

Bir fidan gibi büyüdü

Umut verdi yarınlara. 

Bir vücutta,hayat bulduk ikimiz.

               Kasım-1984/Adana', 'Külkedisi misali tanımıştım  Yaktı kül eyledi kalbimi  Günlerce aradım dağda bayırda  Prens,prenses misali, kavuştuk  Yeni bir çağ atladık i...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yiğit']::text[], 8.5, '{"poet":"Mustafa Yiğit","poet_slug":"mustafa-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ikimiz-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buldum Sevdamda Seni...', 'buldum-sevdamda-seni-halide-selcan-karagul-eu45d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BULDUM SEVDAMDA SENİ…



Seni bildim bileli

Seviyorum ben seni

Neredesin sevgili

Özlüyorum ben seni..



Gece rüyalarımda

Gündüz hülyalarımda

Gönlümün baharında

Görüyorum hep seni..



Her şey seninle güzel

Seviyorum bir güzel

İçimdeki tek güzel

Biliyorum ben seni..



Seni sevdim seveli

Oldum Mecnun misali

Leyla’m derken Mevla’mı

Buldum sevdamda seni…



22.06.2000', 'BULDUM SEVDAMDA SENİ… Seni bildim bileli Seviyorum ben seni Neredesin sevgili Özlüyorum ben seni.. Gece rüyalarımda Gündüz hülyalarımda Gönl...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/buldum-sevdamda-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlaşılmayan Aşklar', 'anlasilmayan-asklar-ali-i-hsan-erdogan-m1wld', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bunalımın baş gösterdiği bir zamanda

Sevgisini kayıp etti bu beden acımasızca

Nedenini sende biliyorsun ki güzelim

Benimkisi sadece bir yar ve onunla sevda

Sinirliliğimin ve psikopatlığımın anısına

Puslu ve bulantılı soğuk gecelere inat

Kin kusuyorum bana yaptığın haksızlığa

Ve lanet ediyorum sana verdiğim zamana

Lütfen delirmişim gibi öyle bakma bana

Sadece üşüyorum soğuk ve hırçın halimle 

Düşüncelerim anlamsız ve yüreğimde saklı

Ölüm ve yaşam, çizgide yürümek sanki 

Geleceğimi beklemekle geçmişimi tükettim 

Sessizliğime ve masumluğuma şükrettim

Karanlık da bir mum misali sanki bittim

Gölgesiyle git diyor usulca, nereye mum

Beynimin ücralarındaki karanlık hayata mı?

Sıkmalıyım gözüm kapalı, yüreğim buruk

Soğuk ve paslı mermiyi acımasızca hayata

Ve akmalı kan, sade, durgun ve sıcak haliyle

Vakitsizce ve an ki yoğunlaşıyor duygularım

Duyuyor musun beni sana haykırıyorum 

Senin için mi bunlar inanma, inanmıyorum 

Ben seni sevmedim ki bunu anlatıyorum

Bendeki kendime olan kinim ve nefretim

Hep kavuşmayı dileyip, kavuşamama isteğim

Yada yalnızlığımı parçalayıp atamama halim

Ağır bir köpek karanlığından sonra göreceksin

Benliğini,terk edilmişliğini ve zavallı halini

Ve sen düşüneceksin ben ne yaptım diye

Anlamayacaksın kendini, kayıp ettiklerini

Yalnızlığını ve kan kokulu hayalet yüzünü

Ağlayarak ve üzülerek geri dönmez zaman

Geride kalanlar sadece kötü ve mağlup anılar

Ve yaşanmadan ölen masum, sefil duygular

Yeter artık bendeki kan ve ruh bitmek üzere

Bu yazdığım yazılar son halimi anlatacak sana

Bilinmek istense de bilinmesi gerekenleri

Bilmediğimi bilerek bilinmezliğe gidecekler

Sevgileri artık yarınlara bırakıyorum 

Çekingen, tutuk, saygılı ve gözlerim kapalı

Anlaşılmayan aşklar yüzünden belki de 

Kalbimi dolduran duygular kalbimde kalıyor

Yüreğim ve mantığım sana bu kadar yakınken

Kollarım ve gözlerim neden bu kadar uzaktı

Anlamadım…Yada bilmiyorum                                                                                            

                                                                

                                                         a.i.e', 'Bunalımın baş gösterdiği bir zamanda Sevgisini kayıp etti bu beden acımasızca Nedenini sende biliyorsun ki güzelim Benimkisi sadece bir yar ...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Erdoğan']::text[], 8.5, '{"poet":"Ali İhsan Erdoğan","poet_slug":"ali-i-hsan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/anlasilmayan-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül yarası', 'gonul-yarasi-halide-selcan-karagul-zm6l0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül yarası, sadece aşkla mı olur sanırsınız? 

Dost sözü yaralar, canınızın yandığını hissedersiniz

Geceler kabusunuz olur, uykusuz sabahlarsınız... 

Elinizdekileri kaybetme duygusuyla boğulacak gibi olursunuz... 

Dostluklarınızı sorgular, ilişkilerinizi tartarsınız... 

Yüreklerde temel atmış bir sevginin 

Yerinden sökülüp atılmasını bu kadar kolay mı sanırsınız? 

05.05.2005', 'Gönül yarası, sadece aşkla mı olur sanırsınız?  Dost sözü yaralar, canınızın yandığını hissedersiniz Geceler kabusunuz olur, uykusuz sabahla...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gonul-yarasi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarışta', 'yarista-guler-ilgaz-9w6ya', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Armuda piş

Tazıya tut diyen cehalet

Ağzını açıp ta

Tavşana kaç diyen bilgelik

...................................................

Başını kuma gömüp te

Zamanı kurtardığını sanan

Bir pula harcayan cehalet

Gözünü kapayıp ta

Kör taklidi yaptığını bile bile

Götüremeyeceği zenginliği

Tazıya satan bilgelik

.....................................................

Yarışta şimdi

İki kutup ta

İki saltanat sürmekte

Ağızlarına düşeni sindirmekte

........................................................

Gözlemciyse pür dikkat

Bir armuda bir ağıza

Bir tavşana bir tazıya bakmakta

Nefesini tutmuş

Öylecesine

Bir görebilse bir bilebilse

Ah bir beni ah bir beni

Bir farkedebilse demekte', 'Armuda piş Tazıya tut diyen cehalet Ağzını açıp ta Tavşana kaç diyen bilgelik ................................................... Başını kum...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yarista-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralı Yarim', 'yarali-yarim-ahmet-sefer-kocer-c6ku9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hemi eşim oldun hem de yoldaşım

Gül kokan sinesi yaralı yarim

İçtiğim suyumsun yediğim aşım

Dertleri peş peşe sıralı yarim

Daha girmemiştin yirmi yaşına

Birlikte gitmiştik dağlar başına

İrengin benzemiş hilal kaşına

Tecellisi, bahtı karalı yarim', 'Hemi eşim oldun hem de yoldaşım Gül kokan sinesi yaralı yarim İçtiğim suyumsun yediğim aşım Dertleri peş peşe sıralı yarim Daha girmemiştin ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sefer Kocer']::text[], 8.5, '{"poet":"Ahmet Sefer Kocer","poet_slug":"ahmet-sefer-kocer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yarali-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurtma', 'ucurtma-guler-ilgaz-q0rxn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgiye sordum

NESİN SEN? 

Dedi ki.................

Elindeki uçurtmayım BEN

İster uçalım birlikte

İçelim yudum yudum cenneti

İster bırak beni

Yaşa cehennemini', 'Sevgiye sordum NESİN SEN?  Dedi ki................. Elindeki uçurtmayım BEN İster uçalım birlikte İçelim yudum yudum cenneti İster bırak ben...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ucurtma-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Diye Diye', 'gel-diye-diye-necati-keceli-wvc5q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bırakıp gittin ya, ararım seni

    Sevgime dere ol, gel diye diye

    Düşer seraplara. sorarım seni

    Derdime çare ol, gel diye diye  

      

    Sensizlik vuruyor, içime darbe

    Felekle girerim şiddetli harbe

    Sabah ezanıyla, düşersin kalbe

    İçime Cemre ol, gel diye diye

    Rüyama düşersin, uykular şaşkın

    Sönmüyor ateşin, bitmiyor aşkın 

    Özlemin büyüyor sel gibi taşkın

    Dünyama töre ol, gel diye diye

    Her sabah doğarsın benim özüme

    Sözüm geçmez olur kendi sözüme

    Aynada bakarsın her gün yüzüme 

    Beynimde üre ol, gel diye diye

    Nakış nakış kalbe işledim seni

    Beynimin rafına, fişledim seni

    Yıllarca hayalde düşledim seni

    Kalbimde yöre ol, gel diye diye

    Necati KEÇELİ

    ADNA', 'Bırakıp gittin ya, ararım seni     Sevgime dere ol, gel diye diye     Düşer seraplara. sorarım seni     Derdime çare ol, gel diye diye      ...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gel-diye-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykirmak', 'haykirmak-sezen-akoluk-bs363', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haykırmak istiyorum.

Hayata bagırmak istiyorum.

Haksızlıklara nara atmak istiyorum.

Gördügüm igrenclikleri söylemek istiyorum.

Hayatın çok berbat hale geldiğine  kusmak istiyorum.

Bunca igrencliklere ragmen, halen dimdik ayakta olduğumu 

H A Y K I R M A K   İS T İY O R U M! ! !', 'Haykırmak istiyorum. Hayata bagırmak istiyorum. Haksızlıklara nara atmak istiyorum. Gördügüm igrenclikleri söylemek istiyorum. Hayatın çok b...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/haykirmak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üsüyen Geceler', 'usuyen-geceler-sezen-akoluk-laabx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzandım yatağıma.

Aklıma yine sen geldin.

hangi bir gecede 

aklıma gelmedin ki? 

Kendimi sorgulamaktayım.

Ama cevap hep ayni kaldı. 

Hiç değişmedi.

„Hiç bir geceyi“

seni düşünmeden edemedim.

Denemedim de.

Geceler sensiz,

geceler soğuk,

geceler çok daha karanlık,

sen gideli.

Gecenin anlamı kalmadı,

gündüzleri bile

geceymiş gibi yaşıyorum.

Sensiz, soğuk ve karanlık!', 'Uzandım yatağıma. Aklıma yine sen geldin. hangi bir gecede  aklıma gelmedin ki?  Kendimi sorgulamaktayım. Ama cevap hep ayni kaldı.  Hiç değ...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/usuyen-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkum; Sensizlik', 'korkum-sensizlik-sezen-akoluk-8235m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Haftalar sonra girdim odama.

Yorganım hasret,

Yastığım aşk,

Yastigim özlem kokuyordu.

Uyuyamadım.

Gözümü yummadım.

Zaten sen gideli,

ne zaman uyuyabildim ki? 

Gözümde bir gram uyku kalmadı,

ÇÜNKÜ; 

Korkuyorum.

Korkuyorum ruhun yanımdan gider diye.

Camları  açmıyorum,

Odamdaki kokun uçacak diye.

Korkuyorum çünkü.

Sensizlikten korkuyorum.

Nefes bile alıp vermek zor geliyor.

Korkuyorum; nefesim karışacak diye.

Ah insanlığı yaratan Rabbim,

Mecburmuyum bu korkularla yaşamaya? 

Ama bu korkular bile

tatlı geliyor.

Çünkü içinde sen varsın.

Benim için “ölümsüz” olan SEN varsin.

…', 'Haftalar sonra girdim odama. Yorganım hasret, Yastığım aşk, Yastigim özlem kokuyordu. Uyuyamadım. Gözümü yummadım. Zaten sen gideli, ne zama...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/korkum-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznün...', 'huznun-dilan-tan-n0tli', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşlanacak bir omuz aradı yaşlı gözlerim, sıcak ve sevgi dolu bir omuz…

Unuturdum  her derdimi, güneş doğana,  ayrılık vakti gelene  kadar, tekrar buluşmak ümidiyle…

Ağlardım sessizce omuzlarında görmemezliği gelirdin susardın sormazdın, sessizce yüreğimi dinlerdin bilirdim…Ağlardım…

Uyurdum omuzlarında hıçkırık sesleri bölerdi kabus uykularımı dünümü, acılarımı, 

daha çok sokulurdum  korkan çocuk gibi, sen de ağlardın gözyaşlarını saklardın yüreğinde, utanırdın… bilmezliğe  gelirdim…

Korkardım ayrılık vakti yaklaşınca, bir daha görecek miyim diye.

İstemezdim ayrılmayı ama mecburdum avuturdum gönlümü yarın yine burda, hep burda diye…

Sen hiç benim değildin başka yüreklerdeydin çalmıştım sevgini bilmem kimin kalbinden...

Ağlardım sen görmemezliğe gelirdin...

Sen de ağlardın hissederdim gözyaşlarını yüreğimde,

Saklardım gözyaşlarını gözlerimde… Ellerin ellerimde  susardım bu büyü bozulmasın diye …

Hüznündü hep benle kalacak olan...

Sen hiç benim değildin başka yüreklerdeydin çalmıştım sevgini bilmem kimin kalbinden...

Gözyaşlarını başka yüreklerden çalmadığını söyle usulca kırgın yüreğime...', 'Yaşlanacak bir omuz aradı yaşlı gözlerim, sıcak ve sevgi dolu bir omuz… Unuturdum  her derdimi, güneş doğana,  ayrılık vakti gelene  kadar, ...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/huznun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Durun Benden', 'uzak-durun-benden-sezen-akoluk-29h4e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küsen insanlar

Tarafta yapanlar

Yaşlıları yok sayanlar

Uzak durun benden

İki yüzlü olanlar

Yalanla yuva yapanlar

Sahtekarlığı tanıyanlar

Uzak durun benden

Kendilerini beğenenler

Kendini üstün görenler

Kem dili küfürü övenler

Uzak durun benden

Akoluk çeşmesi akıyor

Testiler boy boy doluyor

Sezenim güller soluyor

Uzak durun benden', 'Küsen insanlar Tarafta yapanlar Yaşlıları yok sayanlar Uzak durun benden İki yüzlü olanlar Yalanla yuva yapanlar Sahtekarlığı tanıyanlar Uza...', ARRAY['Türk Edebiyatı','Şiir','Sezen Akoluk']::text[], 8.5, '{"poet":"Sezen Akoluk","poet_slug":"sezen-akoluk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzak-durun-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine Bakmayı Özledim...', 'gozlerine-bakmayi-ozledim-dilan-tan-5yy5b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerine bakmayı özledim.

Gözlerine baktığımda kaybolmayı özledim.

Seni gördüğüm anda kendimden geçtiğim anı özledim.

Ellerini dokunmak isteyipde dokunamadığımdaki çaresizliğimi özledim.', 'Gözlerine bakmayı özledim. Gözlerine baktığımda kaybolmayı özledim. Seni gördüğüm anda kendimden geçtiğim anı özledim. Ellerini dokunmak ist...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozlerine-bakmayi-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Korkmuyorum', 'artik-korkmuyorum-salim-erben-5mn4f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bıraktığın uçurumlarda yalnızlığa

Düşmekten kendimi alamadım 

Öksüz kaldım sevdadan yoksun

Düşlerime insafsızca saldırdılar

Yüreğimi sızlatarak

Yarım kalan günden artan saatleri

Geceleyin mum ışığında aratırlar

Korkmuyorum artık

Karanlıkta göremezsem seni

İsyanım yalnızlığımla amansız 

Bir yarışta 

Bu yarışı kaybetmekten

Korkmuyorum

Sancılı yüreğim umutlu 

Koynunda ki gül bahçesinden 

Gelen kokulara tutsak nefesim 

Fısıldayacak aşkı kulaklarına

Çılgınca koşacağım gelmek için 

Kanatlanıp uçacağım uçurumlardan 

Çıldıracağım mutluluktan 

Atılacağım ölümüne kollarına

Kararlıyım bir daha hiç ayrılmamaya zalım

 Salim Erben', 'Bıraktığın uçurumlarda yalnızlığa Düşmekten kendimi alamadım  Öksüz kaldım sevdadan yoksun Düşlerime insafsızca saldırdılar Yüreğimi sızlata...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/artik-korkmuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımını Kaybetmiş Bir Gidişin Hikâyesi Bu,', 'adimini-kaybetmis-bir-gidisin-hik-yesi-bu-humeyra-yilmaz-tnya0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşı yetmişin, başı kambur bedeninin üzerinde,

geçmişe doymuş, geleceği yalandan dua dilinde ve alışkanlıklarını dilenmekte.

Utancını gözlerine, gözlerini toprağa dikmiş filizlenmesini beklemekte.

Sağ eliyle, orada olduğundan bile emin olmadığı kalbini tutmakta.

Dizine yaslı sol dirseği, göğe açılmış avucunda ki boşluğu tutmaktan yorgun.

Karnı tok ama akşamki açlığını bastırmak için yalvarmakta…

Güneş gibi batıyor önceler, akşam özentili karanlık kucaklıyor sonraları…

—Biz kimdik? 

diyor kızarmış balık yosun yeşili marula dönüp…

Marul biraz kıvırcık birazda ıslak, alaycı bir deniz kıvamında gülüyor balığa

Balık üzgün! 

Marul; 

—Yan geldin yatıyorsun tabakta tadını çıkar, şu keyfi yüreğinden büyük adam senin tadını çıkarmadan önce diyor…

Balık daha bir kızarıyor durduğu yerde, marulun yenmeye alışmış ama taze tavırlarından sonra…

Balığın kaderine sinmiş soğan kokusu, taze ekmeğin hamurumsu tanıda karışmadan, tüketilmiş korkular zincirinden koparılmış bir halkayı, kadının parmağına takıyor keyfi yüreğinden büyük adam...

Kendi parmağında ise ödenmemiş hesaplardan artırarak satın aldığı dişlisi bozuk bir gülüş…

Kadın adama alık alık bakıyor, adam aynı alıklıkla balığa…

Balık marula dönüp,

—Nerdeyiz biz 

Diyor

Marul, balığın cahilliğinden sıkılmış olsa gerek, karşı masadaki limonla mayhoşlaşıyor…

Balık daha bir yüksek sesle soruyor

—Sana söylüyorum, nerdeyiz biz? 

Marul, bir an balığın limon tadı vermeye başladığını düşünüyor, ardından hangisine haksızlık ettiğinin bilincine varmaya çalışırken, balık telaşla tekrar soruyor

—Nerdeyiz biz? 

Marul kararını vermiş görünüyor ki, alaycı tavrının beline yenmeye alışmış edasını bağlayıp 

—Denizde

diyor…

_Bu nasıl deniz

 diyor balık, kızgın ve kızarmış bir halde

Marul,

—Deniz işte, diyor bildiğin deniz…

Balık marulla arasındaki kültür farkından bihaber sorucuklar çıkartıyor ağzından baloncuk yerine…

Marul arkasını dönüp mırıldanıyor

—Tanrım bu balığın soruları yenmekten çok daha kötü…

Balık “bilmemek değil öğrenmemek ayıp sözünü benimseyen bir ısrarla,

kendisini yiyen insanoğlunun atalarına saygı babında devam ediyor…

—Ben denizden geldim bana denizi mi öğretiyorsun? 

—Orası senin denizindi, burası da onların

 diyor marul ve devam ediyor

— Siz onları yiyorsunuz onlarda sizi ne var bunda büyütecek? 

Balık şaşkın…

Marul yeşil…

Kadın yalnız…

Keyfi yüreğinden büyük adam tok…

Garson telaşlı…

Aşk kırgın…

Sevgi yorgun…

Yalnızlık cesur…

Azılı yanlışlar hayatı öldürmeye devam etmekte yazıyor alınlarda büyük puntolarla…

Köşelere atılmış yazıların cümleleri kırık, kelimeleri kan içinde…

Kışa saklıyoruz baharı bozulmasın diye ama, kış bozuluyor bu duruma…

“Yanlış zamanda yanlış yerde olduğunda yalnız olmuyormuş insan,

 yanlış zamanda yanlış yerde olan diğer insanların kalabalığında yalnız hissediyormuş kendini sadece”

Bir deli söylemişti bunu delirmeden önce doktora! ! ! 

Ayaklarımın ölçüsünü alıyor yollar çünkü yeni adımlar diktireceğim kendime

Anladım ki kaybedilince anlaşılıyormuş hiçbir şeyin değeri…

Belki bir akşam önünden geçerim keyfi yüreğinden büyük adamın oturduğu boşluğun…

Belki beni yemeğe davet ederler ve balık kızartır bize, parmağında tüketilmiş korkular zincirinden koparılmış bir halkayı taşıyan yalnız kadın, yanına da biraz kıvırcık birazda ıslak marul koyar…

Balık cesur…

Marul yeşil…

Kadın silik…

Keyfi yüreğinden büyük adam tok…

Ben pişman…', 'Yaşı yetmişin, başı kambur bedeninin üzerinde, geçmişe doymuş, geleceği yalandan dua dilinde ve alışkanlıklarını dilenmekte. Utancını gözler...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/adimini-kaybetmis-bir-gidisin-hikayesi-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yaprak Düşerse', 'bir-yaprak-duserse-gokhan-yazici-93c37', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yaprak düşerse ağır ağır,

Bil ki o gün, ben yaşamıyorum.

Bir sonbahar günü rüzgar esince,

Bir yaprak düşünce ağır ağır.

Bir ışık parlarsa yanağında,

Gözünden bir damla süzülünce,

Sevgi yaprakları bil ki kurumuş,

Bir yaprak düşünce ağır ağır.

Sonbaharda ağaçlar ağlıyor,

Hepsi hüzün dolu; bizim gibi.

Biten hikayemizi anlatıyor,

Daldan düşen bir yaprak, ağır ağır.

Sonbaharda rüzgarlar esiyor,

Yaprakları taşıyor uzaklara.

Rüzgara yapraklar karşı koymuyor,

Anılar savruluyor, sağa sola.

Bir yaprak düşerse ağır ağır,

Bil ki yaz mevsimi artık bitti.

Biten yazla bir aşk beraber gitti,

Bir yaprak düşerse ağır ağır.

Bir acı tebessüm dudaklarda,

Eğik başlar önde, suçlu gibi.

Sonbaharda bil ki hep böyle olur,

Yapraklar düşer hep, ağır ağır.', 'Bir yaprak düşerse ağır ağır, Bil ki o gün, ben yaşamıyorum. Bir sonbahar günü rüzgar esince, Bir yaprak düşünce ağır ağır. Bir ışık parlars...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Yazıcı']::text[], 8.5, '{"poet":"Gökhan Yazıcı","poet_slug":"gokhan-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-yaprak-duserse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Yeniden', 'yine-yeniden-mesut-akinci-xzf9l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle yeniden diyebilmek ne zor şimdi

Yeniden aşık olmak yeniden sevebilmek

Ve seni tekrar görmek yeniden 

Başlayabilmek eski günlerdeki gibi yeniden

Seni bilmem ama o kadar zor ki

Yeniden diyebilmek yine yeniden...

Sen benim aşkımdın, candan sevdiğim

Sen benimdin benim, gönül verdiğim...

Şimdi ne kadar zor, sana gördüğüm

Düşleri anlatmak sana yeniden

Seni görünceye kadar yeniden,

Herşey ne kadar da farklıydı inan 

Seni görünce herşey  neden? ? ? 

Bu kadar değişti yine yeniden

Sanki ben o ben değilim inan

Kalbim alev aldı, yanıyor bu can

Gönlüm şimdi eskisinden daha bi candan

Seni istemekte yine yeniden

Şimdi ben diyorum gel buluşalım

Yeniden başlayalım herşeye baştan

Artık sensiz dayanamaz bu gönül inan

Gel yeniden diyelim  yine yeniden

Bakarsın değişir herşey yeniden

Devam ederiz yine kaldığı yerden

Sen gel yeter beklerim inan 

Bir ömür ben seni yine yeniden.....

Yeniden derdimi açtın yeniden

Daha çok kanattın içimi dünden

Ben seni o gördüğüm günden beri

Yakalandım derde yine yeniden...

Yeniden aşık olmak sana yeniden

İnan aldı beni benden yeniden

Seni Seviyorum demek isterdim 

Sana tekrar dönüp yine yeniden

Yine diyorum ki sana yeniden

Seni Seviyorum yine yeniden

Sensiz olmadım dayanamadım

Geriye döneceğim yine yeniden

İstersen kabul et istemezsen red

Ya sev beni yada et benden  nefret 

Bilki bu can seni bir ömür elbet 

Sevdi ve sevecek yine yeniden... 

                                yine yeniden...', 'Seninle yeniden diyebilmek ne zor şimdi Yeniden aşık olmak yeniden sevebilmek Ve seni tekrar görmek yeniden  Başlayabilmek eski günlerdeki g...', ARRAY['Türk Edebiyatı','Şiir','Mesut Akıncı']::text[], 8.5, '{"poet":"Mesut Akıncı","poet_slug":"mesut-akinci","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/yine-yeniden-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimdesin', 'duslerimdesin-mustafa-alpaydin-9ojvo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu can feda olsun senin uğrunda 

Derbeder gezerim ben yokluğunda 

Başımı yastığa koyduğum anda 

İnan ki her gece düşlerimdesin 

Beklerim geceyi bitmez gündüzüm 

Başka güzelleri görmez ki gözüm 

Virane gönlümü sarsa da hüznüm 

İnan ki her gece düşlerimdesin

Duygularımdasın hislerimdesin 

Gündüz hayalimde özelimdesin 

Sen bende yaşarsın yüreğimdesin 

İnan ki her gece düşlerimdesin.', 'Bu can feda olsun senin uğrunda  Derbeder gezerim ben yokluğunda  Başımı yastığa koyduğum anda  İnan ki her gece düşlerimdesin  Beklerim gec...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duslerimdesin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanmı Diyorsun', 'i-nsanmi-diyorsun-seyfet-bozcali-vu29i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çıkar için ezer geçer,İnsanları mahveder,

Çevresine kin kusana, sen insanmı diyorsun? 

Arkada enkaz bırakır,bakmadan çeker gider,

Savunmasızı ezene sen insanmı diyorsun? ...

Ülkelere savaş açıp,Bonbaları dökene,

Çoluk çocuk ayırmadan,kesip,kırıp biçene,

Geride ağlar bırakıp,kanlı yaş akıtana,

Haksız yere öldürene,sen insanmı diyorsun? ..

Devletten yana görünüp,devletini soyana,

Yetim hakkını gasbedip,Midesine koyana,

Haramlara helel diyip,fetva verip yiyene,

Mazlumun hakkın yiyene,sen insanmı diyorsun? ...

          31.01.2006', 'Çıkar için ezer geçer,İnsanları mahveder, Çevresine kin kusana, sen insanmı diyorsun?  Arkada enkaz bırakır,bakmadan çeker gider, Savunmasız...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/insanmi-diyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mal (''ın,Hal) Beyanı...', 'mal-in-hal-beyani-omer-sirakaya-le6e8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yirmi beş davarım, üçyüz koyunum 

Pazarlar, satarım benim yetkim var

Birliğe düşmanım, ırksa; sorunum

İçimde Türklüğe; dinmez kinim var! 

Çaldım soydum zengin ettim kendimi

Halka dediğimin yaptım tersini

Telekom,Tüpraş’ın  sattım hepsini

İçimde Türklüğe; dinmez kinim var! 

Cümlesini satsam gram üzülmem,

Bayrağın tanımam,Atasın sevmem

Satmazsam Kıbrıs’ı rahat edemem

İçimde Türklüğe; dinmez kinim var! 

Sorumsuz olmak da büyük nimetmiş

Çıkardım,kurtuldum,sıkan gömlekmiş.

Papaz’ın cüppesi,ne rahat şeymiş

İçimde Türklüğe; dinmez kinim var! 

Söylerim yalanı günaha girmem

Malımın mülkümün hesabın vermem.

Bildiğim tek şey var; Türkleri sevmem

İçimde Türklüğe; dinmez kinim var!', 'Yirmi beş davarım, üçyüz koyunum  Pazarlar, satarım benim yetkim var Birliğe düşmanım, ırksa; sorunum İçimde Türklüğe; dinmez kinim var!  Ça...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sırakaya']::text[], 8.5, '{"poet":"Ömer Sırakaya","poet_slug":"omer-sirakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mal-in-hal-beyani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümden Ötesi Varmı?', 'olumden-otesi-varmi-seyfet-bozcali-d5mw5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölümden ötesi var mı diyorlar,

Ötedeki yaşamı bilmiyorlar! 

Bu cümleyi sinirle söylüyorlar,

Şeytanın sinsiliğini hiç görmüyorlar.

Ölmek yeni bir hayatın başlangıcıdır.

O hayatı inançlılar iyi bilir,

Ahirette Dünya''da kazanılır,

Götürecekleri azığı hep düşünür...

              30.10.2000', 'Ölümden ötesi var mı diyorlar, Ötedeki yaşamı bilmiyorlar!  Bu cümleyi sinirle söylüyorlar, Şeytanın sinsiliğini hiç görmüyorlar. Ölmek yeni...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olumden-otesi-varmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Coşku', 'cosku-neslihan-uzel-oa13z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seher vakti uyandım bugün

İçimde alaca  bir sevinç

Aldım sepetimi

Güneşin kızıllığından topladım biraz

Çocuksu neşeyi kattım içine

Çiğ düşmüş yaprakları,ıslak çimleri, 

Rüzgarın uçurduğu  huzurlu serini 

Doldurdum içine

Sonsuzluk duygusunu gördüm bembeyaz martının süzülüşünde.

Altın sarısı yaprakların çıtırtısını duydum.

Papatyalar gülümsüyordu,

Dağ laleleri kırmızı bir sevinç içinde.

Uzak dağlar, pembe bulutlarla sevişiyordu

Dilimde çilek tadı, yüzümde tebessüm

Bıraktım kendimi akşamın çöken karanlığına 

Yıldızlara tutundum

Bir yanımda rüzgar, bir yanımda bulut

Mutluluk oldum', 'Seher vakti uyandım bugün İçimde alaca  bir sevinç Aldım sepetimi Güneşin kızıllığından topladım biraz Çocuksu neşeyi kattım içine Çiğ düşmü...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Üzel']::text[], 8.5, '{"poet":"Neslihan Üzel","poet_slug":"neslihan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cosku-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç bir yer', 'hic-bir-yer-demir-mutlugil-n6pbd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hiç bir yere doğru gidiyordum

sen hiç bir yerdeydin.

ne desem, ne söylesem yalandı

yalan doluyordu gözlerime,

yalancı güneşlerden

.......göremiyordum.

unutulmuştu güneşim 

batası zamanlarda

....batamıyordu

yorgundu,güçsüz,çaresiz

denizlere yaslamıştı bir yanını

ne kadar tutabilirdi bilinmez

içerisinde ki aydınlığını

yağılmamış yağmurların sıkıntısındaydım

gökyüzüm bulut telaşında

hangi dünleri adımlıyordum,

hangi yarınların arayışında

sen hiç bir yerdeydin,

hiç bir yere doğru gidiyordum', 'hiç bir yere doğru gidiyordum sen hiç bir yerdeydin. ne desem, ne söylesem yalandı yalan doluyordu gözlerime, yalancı güneşlerden .......gör...', ARRAY['Türk Edebiyatı','Şiir','Demir Mutlugil']::text[], 8.5, '{"poet":"Demir Mutlugil","poet_slug":"demir-mutlugil","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hic-bir-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşledim', 'dusledim-ethem-turan-lcsop', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kır çiçeklerinden kumral saçına 

Taç yapmayı düşledim 

Saçlarının  güzelliğini örtmesin diye

Lale sümbül bezedim 

Kar yüzüne gölgem  leke olmasın diye

Hep önünde eğildim 

Sana nazar değer diye 

Alnına kara leke ekledim

Bahçende çağlayan olup 

Akıp gitmeyi düşledim

Gecemi gündüzümü

Beni benden eden gönlümü 

Seninle eyledim

Gece uykularımı düşünle 

Ömrümün kalanını  seninle düşledim 

Solup gidersin diye 

Soğuğu ırak eyledim

Benim için öyle değerlisin ki 

Kıymetinden sana elimi

Değdiremedim.', 'Kır çiçeklerinden kumral saçına  Taç yapmayı düşledim  Saçlarının  güzelliğini örtmesin diye Lale sümbül bezedim  Kar yüzüne gölgem  leke ol...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dusledim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şirk Batağına Dalma', 'sirk-batagina-dalma-seyfet-bozcali-5krro', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey oğul dinle beni,Sakın boş yere gülme,

Gülme kalbi öldürür,Ölü bir kalple kalma.

Gönlün zikirle doldur,Yalan sözlere kanma,

İmanını güçlü kıl,şirk batağına dalma...

Yeme yetim malını,mazlumun ahın alma,

Öksüzlere yardım et,hayırdan geri kalma,

İftiradan uzak ol,sakın fitneci olma,

Erdemli bir kişi ol,şirk batağına dalma...

Namazlara dikkat et,aman gaflete dalma,

Dinini iyi öğren,sapık fikire kanma,

Bütün şerlerden sakın,nefsine esir olma,

Kur''an-ı hep rehber bil,şirk batağına dalma...

Git Resulün izinden,yolun aydınlık olsun,

İbadetin aksatma,kalbin nurlarla dolsun,

Seyfet der tut sözümü,emeğim helal olsun,

Dünya tuzakla dolu,şirk batağına dalma...

         31.01.2006', 'Ey oğul dinle beni,Sakın boş yere gülme, Gülme kalbi öldürür,Ölü bir kalple kalma. Gönlün zikirle doldur,Yalan sözlere kanma, İmanını güçlü ...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sirk-batagina-dalma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülme Gamlı Gönül.', 'uzulme-gamli-gonul-seyfet-bozcali-rgfsx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üzülme gamlı gönül,

Bir gün gelir gülürsün.

Üzüldüyün şeylerin,

Yanlışlığın bilirsin..

Güvenme hiç varına,

Ümit var mı yarına,

Rahman''ın kararına,

Mecbur boyun eğersin...

Emirleri yaparsan,

Hakkı hakim kılarsan,

Bolca sevap alırsan,

O zaman sevinirsin...

22.10.2003', 'Üzülme gamlı gönül, Bir gün gelir gülürsün. Üzüldüyün şeylerin, Yanlışlığın bilirsin.. Güvenme hiç varına, Ümit var mı yarına, Rahman''ın kar...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uzulme-gamli-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi gördüğüm gün', 'gunesi-gordugum-gun-ali-rauf-tankal-9ywxk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneşi gördüğüm gün öldüm,

Sonbaharın ilk ayının ilk günü.

Onu ulaşılmaz gördüm içimde,

Çok büyüktü, çok uzaktı ve çok parlaktı.

Güneşi gördüğüm gün öldüm,

İçime sindire sindire sevdim onu.

Resmini işledim, beynime,

Nefesini işledim ciğerlerime. 

Güneşi gördüğüm gün öldüm,

Ulaşılmazdı benim olana dek,

Bana geldi, ve ruhumu aldı bedenimden,

Çok güzeldi biliyormusun çok güzeldi. 

Güneşi gördüğüm gün öldüm,

Sesi hiç gitmedi kulaklarımdan,

Dokunuşları 18 yaşındaydı ama.

50 yaşında bir adam arıyordu yazılarında. 

Güneşi gördüğüm gün öldüm,

Artık benden uzaklaşmaya çalışıyor.

Beni seviyor ve bana katılaşıyor,

Sevgime savgisi değiyor kanayarak. 

Güneşi gördüğüm gün öldüm,

Onu severken hissettim bunu,

Işıkları sıcacık ve salkım saçaktı,

Altın gibi parlıyordu gözlerimde. 

Güneşi gördüğüm gün öldüm,

Öldüm ve yine öldüm defalarca, durmadan.

Hasretim oldu, hasreti oldum.

Ben zaten onu gördüğüm gün öldüm', 'Güneşi gördüğüm gün öldüm, Sonbaharın ilk ayının ilk günü. Onu ulaşılmaz gördüm içimde, Çok büyüktü, çok uzaktı ve çok parlaktı. Güneşi görd...', ARRAY['Türk Edebiyatı','Şiir','Ali Rauf Tankal']::text[], 8.5, '{"poet":"Ali Rauf Tankal","poet_slug":"ali-rauf-tankal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gunesi-gordugum-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Kadın', 'koca-kadin-ali-rauf-tankal-ysz0s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum koca kadın, boşlukta da olsa düşlerim.

Sokaklarda da sürünsem yırtık pantalonla, 

Derme çatma kulübede olmasa hayalimizdeki,

Yanlızlığımızda olmasa eskisi gibi,

Gerçekleşmeyeceklerini bilsemde,

Seni seviyorum koca kadın, 

Boşver söyleme bana eskilerden, yenilerden de söyleme.

Gerçekleri görmemezlikten geldik, düşlerimizin içinde,

İki kere ölemem asla, senin gibi, 

Çekmemiştik bu korkunç acıları, sancıları hayallermizde,

Biteceği gün, ölüm geldiğinde  tık demeli zaman, 

Boş ver be  koca kadınım aldırma sen bana,

Umursama sakın, puslanan hayallerimizi.

Seni yinede çok, pek çok seviyorum,

Boşlukta da kalsa düşlerim.', 'Seni seviyorum koca kadın, boşlukta da olsa düşlerim. Sokaklarda da sürünsem yırtık pantalonla,  Derme çatma kulübede olmasa hayalimizdeki, ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rauf Tankal']::text[], 8.5, '{"poet":"Ali Rauf Tankal","poet_slug":"ali-rauf-tankal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/koca-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G ve Z', 'g-ve-z-rahim-tas-n3nth', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'G ve Z 

Sesler ınga embriyolarının 

Mama olup doğmasıyla 

Söze dönüşür 

Büyür bedenimiz gibi, 

Olgunlaşır 

Namluya dönüşür ağız 

Tetiklenir dil 

Kurşun olup saplanır hedefe sözler 

Ya da saçma gibi dağılır 

Yaralar 

Doldurur kabını bazen 

Musluktan akarcasına 

Islatır ya da her yanı 

Fıskiyeden çıkarcasına

Söylenemeyen sözlerdir sırlar 

Duman gibi 

Üflenirse kirlenir çevre 

Nefesler kesilir 

Üflenmezse boğar 

Yaşam gibi sözler de biter 

Kaynağı yürek 

Şarjörü akıl ise 

Ölümsüzdür sözler…

31.1.2006



Rahim TAŞ', 'G ve Z  Sesler ınga embriyolarının  Mama olup doğmasıyla  Söze dönüşür  Büyür bedenimiz gibi,  Olgunlaşır  Namluya dönüşür ağız  Tetiklenir ...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/g-ve-z-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevgim', 'benim-sevgim-ali-rauf-tankal-5hw7y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim sevgim ağlatır,

Benim sevgim kahreder,

Benim sevgim yıpratır,

Benim sevgim yorar,

Benin sevgim çok ağırdır,

Benim sevgim çok büyüktür,

Benim sevgim çok kutsaldır,

Benim sevgim çok saftır,ve

Benim sevgim çok temizdir

Bu sevgi ancak senindir aşkım.', 'Benim sevgim ağlatır, Benim sevgim kahreder, Benim sevgim yıpratır, Benim sevgim yorar, Benin sevgim çok ağırdır, Benim sevgim çok büyüktür,...', ARRAY['Türk Edebiyatı','Şiir','Ali Rauf Tankal']::text[], 8.5, '{"poet":"Ali Rauf Tankal","poet_slug":"ali-rauf-tankal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/benim-sevgim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-ali-rauf-tankal-6ajoo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seviyorum seni,

Herşeyimle seviyorum,

Seni beni sevdiğinden daha fazla, 

Seviyorum seni.

Benliğim gibi, ruhum gibi,

Canım gibi seviyorum  seni.

Korkarak seviyorum birazda,

Kaybetmekten, uykularım kaçıyor,

Sürükleniyorum boşlukta bazen.

İşte böyle seviyorum seni.

Her zaman yanımda taşıyorum,

Duygularını, hislerini ve sesini.

Kuvvetini hissediyorum sevginin.

Ben işte böyle seviyorum seni.

Su olup akıyorsun bazen,

Bazen de ateş olup yakıyorsun yüreğimi.

El oluyorsun yüzümde bazen,

Bazen de müziğin kulaklarımda.

İşte ben seni böyle seviyorum.', 'Seviyorum seni, Herşeyimle seviyorum, Seni beni sevdiğinden daha fazla,  Seviyorum seni. Benliğim gibi, ruhum gibi, Canım gibi seviyorum  se...', ARRAY['Türk Edebiyatı','Şiir','Ali Rauf Tankal']::text[], 8.5, '{"poet":"Ali Rauf Tankal","poet_slug":"ali-rauf-tankal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-seviyorum-332-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış a', 'baris-a-nizami-sunguroglu-0r3em', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güz yağmurları mı esti gönlüne? 

Apansız birden bire.,

Ağladı,

Ağladı herkes.

Ağladım günlerce.

Barıştı yaptıkların.

Barıştı,

Söyleyip yazdıkların.

Barıştı notadaki nameler.

Barıştı yüzündeki haleler.

Sevgin sarmıştı yüreğimi.

Sevgin sarmıştı yüreğimizi.

Özümdü konuşup yazdıkların.

Özümdü söyleyip çaldıkların.

Özümdü giyinip taktıkların.

Öze öz yaşadın, öz toprağında

Veda ettin sessizce

Bir şubat akşamında.

08/02/1999

Nizami Sunguroğlu //// Hollanda

Barış manço hayranlarına ithaf olunur.', 'Güz yağmurları mı esti gönlüne?  Apansız birden bire., Ağladı, Ağladı herkes. Ağladım günlerce. Barıştı yaptıkların. Barıştı, Söyleyip yazdı...', ARRAY['Türk Edebiyatı','Şiir','Nizami Sunguroğlu']::text[], 8.5, '{"poet":"Nizami Sunguroğlu","poet_slug":"nizami-sunguroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/baris-a-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinin karası / postaya verilmemiş mektup...', 'gozlerinin-karasi-postaya-verilmemis-mektup-zafer-zengin-etnika-0xny8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.

su topluyor gözlerim ‘kirpik batar ‘ kaş yanar bir zamanda

sana okuyorum yazılı kaynakları ’ ad oluyor dinleyişin

sana dalıyorum ‘ birden çıkıp içinden ‘yüzümde suları temizliyorum

yüzüm kuruyor ‘tepemden gelen ışığın adı ‘sensin 

ayan olmuş

sızı görünmüş

gurbet yanında

ekmek aklında

dönmedin bağrıma

sızılı yıllardan sonra

anlat

gurbet uzak mı hala

ya gözlerinin karası

uzaksın ya ellerim kurumuyor’ kuruduğunu sanıp ağlıyor 

gözümden biliyorum yaşları ‘oysa senden geliyor 

kopuyorum ‘neden ağlar diye dalıyorum ‘ ne çok susuyorum

gitmişsinde farkına bile varmıyorum ‘ayak parmaklarım oyalıyor beni

atıyorum ‘sağ ayak parmaklarımı ‘soldakilerin üzerine 

sonra yer değiştiriyorum. ‘ kaç etti bilmiyorum ‘neden saymadım ki diye 

kendime kızıyorum ‘ söndürüyorum iki parmağımın arasında ‘ parmağımı

hissedemiyorum parmağımla ‘ pişmanlık kokuyor ‘yanan derimin ‘

yarılmış derimin altında ‘sonra sızıya bağlanıyorum’ acıyor

o türkü bilinmiyordu

söylediler dinlediler

yüreklerini yola koyunca

turnaları bildiler

aşsız susuz 

ne aştılar ne düştüler

dil elde ağız lal 

kalem olup yazmayınca

bir kez konuştular

duyduk

çatlamış dudağıyla

ter emerken

su

sana kırdık ellerimizi  ‘demişsin ki ‘siz yazdıkça kanıyorum  ‘ömrüm gidiyor

kısa zamanda  ‘nasıl çalınıyorsa bir ney ‘ona dalıp ‘kendimden vazgeçiyorum

demişsin sonra; ‘bunun adı ney biri anlatsa  ‘ demişler; sonra çalınır ney 

iç hiçe karışınca  ‘ağlama anlamak  ‘anlaşılmamak ağlatır yoksa

bir omuzda yoksa yanında ‘bağır içinden  ‘bir de haykır sesinden ‘anlatır işte varlığın

bir de su iç ‘madem ki türkü söyler dilin ‘dilinin etrafında ağzın ‘ağzın kenarında dudağın

akşam üstü hele ‘ güneş gölgeye gidende ‘ su iç..ak kendine ‘ sizi kendime sevdim de

kimler duyulmadı yazılarda

lahitlerin üstünde

tiyatro girişlerinde

tapınak ve yazıtlarda

meydanlarında yıkık şehirlerin

kurulmuş mekteplerin sırtında

hasret diye yazılmış mektuplarda

kimler duyulmadı yazılınca ayrılığa

bir kez daha konuştular

mektup



şu gittiğin iş değil ‘ekmeksiz aşsız kaldık buralarda ‘zor olmazdı belki ‘şu yalnızlık

olmasa  ‘sen gidince buralardan ‘bize bakan kalmadı  ‘içimiz karardı ‘sabahımız 

olmadı ‘kapalı perdelerden bildik ‘ortalarından deldik ‘ne ışığı ‘ne seni gördük ‘senden sonra

bizde bizden göçtük  ‘bahanemiz kalmadı ağlamaya ‘ellerimizi sardık boynumuza

sen diye sarıldık aynamıza  ‘öyle bakma  ‘dönmedin daha ‘ meraktayız ‘gözlerin burada mı ha’la. Bak saklıyor ha’laları sonlara.

dönecek misin

asla

sen gel sen

dönsen

gam yüküyle söylenecekler

görünce unutulacak

gel…

21 05 2005

.', '. su topluyor gözlerim ‘kirpik batar ‘ kaş yanar bir zamanda sana okuyorum yazılı kaynakları ’ ad oluyor dinleyişin sana dalıyorum ‘ birden ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/gozlerinin-karasi-postaya-verilmemis-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acgözlüsün', 'acgozlusun-seyfet-bozcali-o2rew', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçükten tanırım seni,

o zamandan aç gözlüsün.

Aklın almış Dünya malı,

onun için hiç doymazsın..

İçinde kazanma hırsı,

Gözün görmez oğlu,kızı,

Sevindirdin mi öksüzü,

Zaten onu hiç bilmezsin..

Hiç ölüm gelmez aklına,

Şükrünü eda etmezsin,

Gel diye ezan okunur,

Bir gün camiye gitmezsin..

En sonunda öleceksin,

Tecelliği göreceksin,

Dar gabire gireceksin,

Mal,serveti göreceksin..

             31.01.2006', 'Küçükten tanırım seni, o zamandan aç gözlüsün. Aklın almış Dünya malı, onun için hiç doymazsın.. İçinde kazanma hırsı, Gözün görmez oğlu,kız...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/acgozlusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Çağırmak', 'hayal-cagirmak-umut-engin-deniz-kox7q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayal Çağırmak

Neslihan’a

Şimdi seni düşünüyorum.

Mektup yazsam, adresin yok.

Telefon açsam, numaran yok.

Daha da kötüsü:

Mutlu musun?

Pişman mısın?

Haberim yok!

Seni — sensiz yaşıyorum.

Bir masanın etrafında

hayal çağırıyorum.

Yalnız değilim.

Tek başımayım.

31.01.2006 

UNLBBCN

Umut Engin Deniz', 'Hayal Çağırmak Neslihan’a Şimdi seni düşünüyorum. Mektup yazsam, adresin yok. Telefon açsam, numaran yok. Daha da kötüsü: Mutlu musun? Pişma...', ARRAY['Türk Edebiyatı','Şiir','Umut Engin Deniz']::text[], 8.5, '{"poet":"Umut Engin Deniz","poet_slug":"umut-engin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/avuntu-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi', 'mavi-neslihan-uzel-xvv4o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Isındı ellerim sanki.

Kelebekler  doluştu yüreğime derken.

Ağlanası bir aşkın yamacında

Kapıları açamadım...

Sonbahar oldum

Yüreğimi kapatarak.

Bugün yapraklarım sararmış,gördüm...

Bir daha yeşermeyecek.

Anladıkça üşüdü ellerim.

Mavi mavi sevmek isterken ben

Renkler küsmüş bana,  gördüm

ve ağladım için için 

Bu gün  mavi mavi öldüm.', 'Isındı ellerim sanki. Kelebekler  doluştu yüreğime derken. Ağlanası bir aşkın yamacında Kapıları açamadım... Sonbahar oldum Yüreğimi kapatar...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Üzel']::text[], 8.5, '{"poet":"Neslihan Üzel","poet_slug":"neslihan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mavi-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Gönül!', 'ey-gonul-nazife-abayli-3vyxw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En güzel dizelerimi yazacaktım senin için,

En güzel şiirim olmalıydı sana yazdığım,

Ama öylesine eritiyor ki bu sevda beni,

Dayanamayacağım...

..........................

Uyku girmiyor gözlerime tam kırksekiz saattir.

Acıkmadığımdan,susamadığımdan belli,

Özlemimden döktüğüm yaşlardan belli,

İçin için eriyorum,titrememden belli,

Buna dayanabilir misin ey deli gönlüm? 

Yanmamıştın,ağlamamıştın ne vakittir! ! 

...........................

Sonbahar da yeşerir mi dersin fidanlar,

Yeniden canlanır mı dersin papatyalar,

Türküler gelir mi dile yanık yanık,

Hasretinden usanıp kavuşur mu sevdalılar? 

Çalar mı yeniden gümbür gümbür davullar,

Alından öpülerek kalkar mı acaba duvaklar? 

............................

Ey gönül! 

Bilirim Seymenoğlu''dur yakıp kavuran seni..

O''nun sevdası almış aklını,sarmış sineni,

Nice günler var önünde,sabret,sustur dilini,

Gelecektir elbet  sonraki bahara,

Biçerenin çaresizlikler kapatmış yolunu...', 'En güzel dizelerimi yazacaktım senin için, En güzel şiirim olmalıydı sana yazdığım, Ama öylesine eritiyor ki bu sevda beni, Dayanamayacağım....', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ey-gonul-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nevbahar', 'nevbahar-mehmet-sukru-bas-6kn72', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne bahar geldi ömrüme, ne de sen,

Kaf dağında kaldınız öyle.

Bir ömür sizleri bekleyip durdum,

Alev alev gönlümde yandınız öyle.

Bahar bahar dedim kış oldu mevsim,

Buz tuttu gönlümde sevgin hayalin.

Ömür rüzğar gibi gelipte geçti,

Peki, sen hala niye gelmedin? 

Ömür bitiyor cananım yazık değil mi? 

Ne olurdu bahar olup gelseydin? 

Asla inanmadın, sevdiğimi bilmedin,

Türlü cefan geldi, gene de sen gelmedin

Görmedin gönlümde yanan ateşi,

Hasretine bir damla, suyu serpmedin.

Yıllar rüzgâr oldu esip de geçti, 

Beklediğim sendin, sen de gelmedin.

Korkum odur gelsen de beni bulaman, 

Zamansız tedavi olmaz ki derman.

Ayrılık acısı göğsümde ferman,

Bir gün bile ne haldeyim görmedin.', 'Ne bahar geldi ömrüme, ne de sen, Kaf dağında kaldınız öyle. Bir ömür sizleri bekleyip durdum, Alev alev gönlümde yandınız öyle. Bahar bahar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nevbahar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban olayım', 'kurban-olayim-nedim-akgun-6j7xn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnmisin cinmisin bilemedimki,

Sana bir türlü doyamadımki,

Aklımdasın her zaman atamadımki,

Atamadığım sevgiye kurban olayım.

Aşkınla eridim kül oldum yeter,

Bilmem ki bu sevda ne zaman biter,

Yaşadığım mutluluk benimle gider,

O güzel aşklara kurban olayım.

Adını ezberledim binlerce defa,

Çektirme güzelim dünyada cefa,

Beklerim senden azıcık vefa,

O güzel duyguna kurban olayım.

Sevgi mukaddestir ölmez derler,

Bu aşk şerbetini içen bizler,

Birlikte başbaşa ettiğimiz yeminler,

O güzel yeminlere kurban olayım.

Bizim bu dünyada aşkımız ölmez,

Bu aşkın sırrını kimseler bilmez,

Zevk ve sefa ile bu iş yürümez,

O aşkın sırrına kurban olayım.

Tanrı şahidimdir duyar sesimizi,

Yalvardım durdum ayırma ikimizi,

Alır götürür bir gün bu cismimizi

Bu kaderi yazana kurban olayım', 'İnmisin cinmisin bilemedimki, Sana bir türlü doyamadımki, Aklımdasın her zaman atamadımki, Atamadığım sevgiye kurban olayım. Aşkınla eridim ...', ARRAY['Türk Edebiyatı','Şiir','Nedim Akgün']::text[], 8.5, '{"poet":"Nedim Akgün","poet_slug":"nedim-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kurban-olayim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-mustafa-nihat-agacikoglu-d9z9j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1

EYLÜL

ve hayat bir şarkının

nağmelerinde 

eylül oldu

bir şiirin mısralarında

eylül umuda adanmış kız

eylül bir şiirin dokuduğu aşk

eylül iki kalbin tek duayla dileği

eylül henüz yaşanmamış zamanın adı

eylül doğmadan adı konulmuş dünya güzeli

eylül aşkı efsaneleştiren bir annenin meyvesi

eylül şiirden adama adak

eylül gözden gönülden sakınılan

eylül duasını bekleyene sunulan çocuk

eylül sonbahar rüzgarlarında yağan yağmur

eylül baharın son tazeliğinde açan sarı çiçek

eylül sevginin tenindeki koku

eylül içimize bırakılan aşkın anlamı

eylül aşkın ışıyan ısıtan ağaran yüzü

eylül sevda şarkımızın bitmeyen nakaratı

eylül; aşka başlarken sevgilinin kalbinde

yani tam kalbinin aşka çoğalan,aşka çoğalan, aşka çoğalan

ve sevgilinin dudaklarından dökülen aşka çoğalan

bir masalla doğarak hayata

başladı

2

eylül fırtınasında tutunduk aşkımıza

kalbimizin çelikten elleriyle

tutunduk aşka

aşk eylülde mi başladı

yoksa eylülle mi başladı

bilmeden kalbimizle 

ama kalbimizi bilerek başladı

aşk

eylül bir adamın

yıllar öncesinde ki özlemiydi

adı sanı konulmamış

şekli şemali yapılmamış

yolculuğu henüz başlamamış özlemiydi 

bir adamın

bir adam yıllar önce

şiirine katarak aşkı

ve an be an şiirinden damıtarak

ufkuna koymuştu kızını

ve tabii kalbine

umuduna birde

ve bir kız

narin güzel ve neşe bir kız

kalbini yaşamayı hüner sayan bir kız

aşkı bekleyen

aşka beklenen bir kız

elleri gözleri dudakları

kalbi

şiir olan bir kız

şiirden adamın

özlemine ufuk olan

bir kız

3

bir eylül ayında aşka bakarak

eylül dedi beklenenin adını

eylül dedi 

aşka saklanan özlemin adını

ve eylül koydu umudun aşkla bilinen adını

şiir kız

eylül mavi bir rüyanın

gökyüzünden akan maviliğindeydi

denizleri kıskandıran maviliğinde

puslu bir camın arkasında saklı

masumiyeti bakan aklıydı aşkın

duada  büyüyen saflığı

dualarda dillenen adıydı

eylül

bir su damlası eylül

şiir kızın rüyalarına damlayan

beyaz elleriyle tutup

anne sadakatiyle

denizlere yürüyen

bir su damlası

ah eylül

hiçbir çocuğun adı doğmadan konmamıştır

ve bu kadar özlemle beklenip

şiiri yazılmamıştır

hiçbir çocuğa doğmadan

gözlerinin rengi söylenmemiştir

ah eylül

sen 

ah sen

yok musun kalbimizde

4

eylül

aşkın vazgeçilmezi

vazgeçilemeyen aşkın

hasretle çoğalan temennisi

gelmen için kalbimize beklendin

gelmek için daha ne kadar bekleneceksin

ah eylül sen aşkla gelensin

aşkla geleceksin

en güzel kelimeden

eylül

dur koşma düşeceksin

çıkma oraya 

babanın kitaplarını düşüreceksin

dur eylül

annen sana 

dur demişse dur

annen sana esirgeyen duadır

annen sana beyazlığı akan iyilik

seni kuşatan merhamettir eylül

şiir anneni üzme eylül

eylül

bak bu şiir

sen şiirden dünyaya geldin

en güzel kelimelerinle geldin kızım

bak eylül bu kaf dağında ki dev

yani baban

5

eylül

sen bir anka kuşusun

kaf dağı ve anka

ve peri kızı şiir annen

biz bir aşk masalının

kahramanlarıyız

hadi uyu eylül

uyu ve büyü

aşkımız kadar büyü eylül

ve yine bir şiirle gel

bir şiirle sev

anneni ve babanı

kızım

eylül hilalin ışıktan kollarıyla sarmaladığı-aşkın gözleriyle bakarak aşkın elleriyle dokunarak-aşkın sesiyle söylediği

bir ninni

şiirden kızın

aşkla dilediği temenni

….ve eylül uyudu

uykusunda dünya güzeli annesini

ve şiirini söyleyen babasını gördü

eylül

annesinin gözlerinde babasının sözlerini

babasının kalbinde annesine söylenecek sözleri gördü

eylül gelmek için sabırsızlandı

uyanmak için 

doğmak için sabırsızlandı

aşka sabırsızlandı

şiir kız

29 ocak 2006', '1 EYLÜL ve hayat bir şarkının nağmelerinde  eylül oldu bir şiirin mısralarında eylül umuda adanmış kız eylül bir şiirin dokuduğu aşk eylül i...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Nihat Ağacıkoğlu']::text[], 8.5, '{"poet":"Mustafa Nihat Ağacıkoğlu","poet_slug":"mustafa-nihat-agacikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":146,"source_url":"https://www.antoloji.com/eylul-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan', 'nisan-ethem-turan-xa8j7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine Nisan yaklaşıyor 

Hüzün ve keder içindeyim

Ilık yağmurun özlemi 

Sıcak duygular içindeyim

Kaldırım taşlarının  ve parkların 

Hatta oturulan bankların 

Salkım söğüt ağaçların 

Türkülerini dinler gibiyim

Yine Nisan yaklaşıyor 

Ilık esen aşk rüzgarının

Sevgililere mırıldanışını 

Havada uçuşan polenlerin

Çığlıklarını duyar gibiyim

Yine Nisan yaklaşıyor

Çok beter haldeyim

Sensiz yağmurun acısını

Ilık rüzgarın şarkısını 

Bizim için uçuşan polenlerin ahını 

Sensiz yaşar gibiyim

Yine Nisan yaklaşıyor

Bulutların seni özlediğinden çok 

Özlüyorum seni 

Yokluğun 

Yıldırımın yakıcılığından daha derin

Yakıyor içimi 

Yine Nisan yaklaşıyor

Eskiden olduğu gibi 

Yine deliler gibi seviyorum seni', 'Yine Nisan yaklaşıyor  Hüzün ve keder içindeyim Ilık yağmurun özlemi  Sıcak duygular içindeyim Kaldırım taşlarının  ve parkların  Hatta otur...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nisan-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulümün Sonu Yoktur', 'zulumun-sonu-yoktur-seyfet-bozcali-nwvos', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zülümün sonu olsa,zalimler çoğalırdı.

Fakir yoksul korunmaz,hepsi heder olurdu.

Mazlumlar ağlar iken,zorba olan gülerdi,

Tükenen bir mum gibi,zulümün sonu yoktur...

İbrahim Peygamberi kimler ateşe attı? 

O ateşi su edip,nasıl katında tuttu? 

Fravun zalimini nasıl denizler yuttu? 

Nasıl Haktan Hak varsa,zulümün sonu yoktur..

Son peygamberimizi ne hakla taşladılar,

Mekke''den Medine''ye hicrete zorladılar,

Kabe''ye dönüşünde,biat edip  yalvardılar,

Yoktan var eden  diyor,zulümün sonu yoktur,.

                30.05.2003', 'Zülümün sonu olsa,zalimler çoğalırdı. Fakir yoksul korunmaz,hepsi heder olurdu. Mazlumlar ağlar iken,zorba olan gülerdi, Tükenen bir mum gib...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zulumun-sonu-yoktur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulunmamış Sevgili', 'bulunmamis-sevgili-i-hsan-kurt-uidcn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bulunmamış sevgiliyi aradım

Hep hasreti yaşadı damarlarımdaki kan

Hasreti sardı duygularımdaki volkan

Çocukluk sevgilerinde kaldım

Çocukluğumdakileri bulamadım.

Bulunmamış sevgiliyi aradım

Çırağım dedim,

Ustamı bulamadım

Kızgın çekiçler indi yüreğime

Yüreğimi çeviremediler demire.

Bulunmamış sevgiliyi aradım

Bir seccadenin motiflerinden geçip

Bin gözle baktım

Bir yürekte bin yürek

Bire binleri yaktım.

Bulunmamış sevgiliyi aradım

Umudun içinde hissederek

Umut gibi yakın sandım

Ellerimi uzattım, ellerimi uzattım

Yakınlara da kavuşamadım.

(Bir Yüreğin Türküleri''nden)', 'Bulunmamış sevgiliyi aradım Hep hasreti yaşadı damarlarımdaki kan Hasreti sardı duygularımdaki volkan Çocukluk sevgilerinde kaldım Çocukluğu...', ARRAY['Türk Edebiyatı','Şiir','İhsan Kurt']::text[], 8.5, '{"poet":"İhsan Kurt","poet_slug":"i-hsan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bulunmamis-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tembele Sor', 'tembele-sor-ali-cengiz-turan-q9uxq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Açılmış ağazlar bekliyor,el yürürken emekliyor,

Kahvelerde pinikliyor borçlarını bakkala sor.

Gündüz gece belli değil,sanki bekar evli değil,

Tembelliğe alışanın borçlarını esnafa sor.

Yaşam demiş yemiş içmiş,tarla deyip ekip yatmış,

Gölgelerde keyif çatmış,akıp giden zamana sor.

Kader kader inler durur,şanssızlığını savunur,

Akıp giden servetini kluplerde zarlara sor.

Boş işlerle ömrü geçer,gece gündüz hergün içer,

Uykusunda ömrü geçen akıp giden zamana sor.

Tembelliğini savunur,elin varlığınla avunur,

Yarışlarda en geride uzun uzun yollara sor.

Düzinece çocuk yapar,zevklerine gurur katar,

Yemek ekmek yetmeyice,feryadını zamlara sor.

Bal ile kaymağı düşünür,güneşli havada ısınır,

Ömrünü geceye döndüren şafak vakti güneşe sor.! ! ! !', 'Açılmış ağazlar bekliyor,el yürürken emekliyor, Kahvelerde pinikliyor borçlarını bakkala sor. Gündüz gece belli değil,sanki bekar evli değil...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tembele-sor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte Yaşam Kırıntıları', 'sahte-yasam-kirintilari-atilla-guler-baywb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çok şey sunuldu insanlara...büyüleyici...masallar gibi

belirli şartlar altında hep

hep günahtı nedense/güzel olan her şey

büyüdü günahlar/yok oldu cennet

şeytan mı çeldi aklımızı

biz mi günaha daha yakın bulduk kendimizi

tövbeler edildi korkuyla

neye yarar/bunca güzelliği tattıktan sonra

en büyük günah nedir

kim bilebilir ki

sana göre/senin işlemediğin en büyüğüyken

onun için/onun tatmadığı günah öyle değil midir

nereye bu koşuş böyle...niye...kime

aklında seni çelen/en zayıf dürtülerin

sonu neye varır

günahsız yaşamında/günahlara boğulmuş yüzerken

yalan bir yaşamdan çok...gerçek bir ben

aldatma olmadan/sahte yaşam kırıntılarından uzak

kolay değil/çepeçevre sarılmışken

aldattığın

______hep s e n oldukça...

	16.05.2003', 'çok şey sunuldu insanlara...büyüleyici...masallar gibi belirli şartlar altında hep hep günahtı nedense/güzel olan her şey büyüdü günahlar/yo...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sahte-yasam-kirintilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemezsiniz', 'bilemezsiniz-ayse-gul-ix0lq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir nehir akar

yüzünün deltasından

bir yanı acı

bir yanı tatlı

ve

karışır zamana

hayata

sizlere...

Ne kadar

sizsiz çağladığını

^ ^ ^ ^ ^ ^ ^ ^ ^ ^ ^ ^ ^  b i l e m e z s i n i z... 

006/İst.A.G.Nisan_ca', 'Bir nehir akar yüzünün deltasından bir yanı acı bir yanı tatlı ve karışır zamana hayata sizlere... Ne kadar sizsiz çağladığını ^ ^ ^ ^ ^ ^ ^...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Gül']::text[], 8.5, '{"poet":"Ayşe Gül","poet_slug":"ayse-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilemezsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz Telafisinde', 'soz-telafisinde-yasemin-sezer-tulgar-a6k1b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'doğur beni 

gecenin gözlerine 

bürüneceğim güne

___ölü sansınlar seyri

akla tadı

nar içine

tohumlanacağım güne

___çoğalacağım bil

soy hoyratlığını dilime

dilimle bensizliğinin ağısını

____beyaz olsun çekirdeği

        söz telafisinde

kırp perdesini 

gözümün ninnisinde

uyur bebeği 

annesinin sesiyle

____rahminde bin ömre gebe 

31.01.06', 'doğur beni  gecenin gözlerine  bürüneceğim güne ___ölü sansınlar seyri akla tadı nar içine tohumlanacağım güne ___çoğalacağım bil soy hoyrat...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/soz-telafisinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasipsiz Sevda', 'nasipsiz-sevda-sair-guner-wsiwm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasipsiz bir sevda yer bitirir beni başımda

Önce benli sonra senli

Ya ben geç kaldım ya sen yoruldun

Halatı sıkı sıkı tutmakla

İkimizde geç anladık

Sen halatı boşuna tuttuğunu

Ben konduğum çiçeklerin yapay olduğunu

Ne çare 

Nasipsiz bir sevda, yer bitirir beni başımda', 'Nasipsiz bir sevda yer bitirir beni başımda Önce benli sonra senli Ya ben geç kaldım ya sen yoruldun Halatı sıkı sıkı tutmakla İkimizde geç ...', ARRAY['Türk Edebiyatı','Şiir','Şair Güner']::text[], 8.5, '{"poet":"Şair Güner","poet_slug":"sair-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nasipsiz-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Yolların Vedası', 'uzak-yollarin-vedasi-ceyhun-karatas-ttrku', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir uzak kıtaya gideceğim

Sesin ulaşmadan daha kıyıya

Balıkları terkedeceğim

Yırtık yelkenli bir tekneyle

Sen görmeden geçeceğim

Adı bilindik kıtaları

Kanatlarında olacağım martıların

Yeni yetme çocukların avuçlarında

Sanırım dönmeyeceğim

Bekleme beni o dağın yamaçlarında

Bir uzak kıtaya gideceğim

Bir uzak dünyaya

Çığlığın dolaşırken sarp kayalıkları

Ben unutmuş olacağım ayrılıkları

Çığlığını duymam artık

Selamını almam

Mektuplar yazma artık hüzünlü

Artık istesem de ağlayamam

Daha açılmamışken şehrin dükkanları

Daha en erkenciler uyanmadan

Kapıcılar çalmamışken kapıları

Ben ulaşmış olurum uzak diyarlara

Boşuna bekleme yolları

Sanırım yolum düştü

Dönüşü olmayan yolculuklara

Yeniden düştüğümde yollara

Belki çok uzak kalacak bu ülkeye sesim

Ama duyulacak yine de

Rüzgarları dinlemeyi unutma

Kulağın uzaklarda olsun

Senin için de bir veda olacak sözlerimde

Yanıbaşında olmayacağım belki

Bayram kartları atmayacağım

Gözlerin beni arayacak her mutlu günde

Ama kulağın tetikte olsun

Sana sesleneceğim çok uzaktan

Cevap beklemeyecek

Birşey istemeyeceğim

Düşlerinde biriktirdiğin sevgiler sende kalsın

Elin başkalarının elinde

Sadece sesini ver bana

Sesim yankısını bulsun sesinde

Sadece dikkatini ver bana

Sesim yeniden cümlelere dönüşsün bilincinde', 'Bir uzak kıtaya gideceğim Sesin ulaşmadan daha kıyıya Balıkları terkedeceğim Yırtık yelkenli bir tekneyle Sen görmeden geçeceğim Adı bilindi...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Karataş']::text[], 8.5, '{"poet":"Ceyhun Karataş","poet_slug":"ceyhun-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/uzak-yollarin-vedasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değer miydin', 'deger-miydin-ali-kalafat-ziwfc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Küçük bir kasabanın köhne

Bir o kadar da eski kütüphanesini araştırıyorlarmış

Her kitabı ayrı ayrı inceleyecek

Her kitabı ayrı ayrı kaydedeceklermiş

Hepsini kontrol etmişler 

Ama rafların en sonunda 

Bir kitap dikkatlerini çekmiş 

Sayfaları hafif nemlenmiş

İçindeki yazılar silinmiş

Bir ayda bin kez okunmuş

Sonra bir daha da el sürülmemiş

Kitap

Bir adetmiş

Birinci sayı 

Birinci baskı 

Bininci kez okunmuş

Bir daha okunacak durumda degilmiş 

Acaba yazarı kimmiş

Çözülememiş

Okuyanın ismi hep aynıymış

Zatı-ali beni andırır

Hoş ya ismide tutarmış

Beni bulup  sormuşlar 

Söylememişim

Seni sormuşlar 

Bilememişim

Resmini göstermişler

Seçememişim

Sonradan ögrenmişler 

Kitabı benim okuduğumu

Kitabı okuyunca  viran 

Resmini gösterince deli olduğumu

Şimdi başımda konuşup duruyorlar

Bir şeyler anlat diyorlar ama 

Ne anlacagımı bilmiyorlar

Kitap neden elimde eskimiş 

Kitapta kimden bahsediyorlar

Sürekli bunu soruyorlar

İçinde ne yazdıgı bilmek istiyorlar

Bilseler onlarda deli olacaklar

Kitap elimde eskidi

Ama sayfalarını tavandan sızan yagmur ıslattı 

Ondan okunmaz durumda idi

Seni tanıdıktan sonra

Tüm yaşantımdan silindim 

Senden sonra  buhar oldum eridim

Bulut olup rüzgarlarla seviştim

Yagmur olup gökyünzünden tavana 

Tavandan raflara 

Raflardan kitabına eriştim

Kısaca ben senin içine yerleştim

Seni anlatan her cümlenle bütünleştim

Şimdi soruyorlar bana

Deger miydi bu kadar sevmeye 

Deger miydi delirmeye

Deger miydi aklını yitirmeye

Ben verecek cevap bulamadım 

SEN SÖYLESENE

DEGER MİYDİN? ? ?', 'Küçük bir kasabanın köhne Bir o kadar da eski kütüphanesini araştırıyorlarmış Her kitabı ayrı ayrı inceleyecek Her kitabı ayrı ayrı kaydedec...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalafat']::text[], 8.5, '{"poet":"Ali Kalafat","poet_slug":"ali-kalafat","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/deger-miydin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedi', 'kedi-ayca-yesim-bkj3j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşerken kedi merdivenden

Ben de peşisıra	

İçine sevgiler burulmuş

Korkusu gözlerinde kedinin

Kader gibi

Kader gibi hani

Beni uçurumlara iter ya gözlerin 

Karşı koyulmaz asla, geri dönülmez

Ve ne derse odur ya gözlerin

İtiraz edilmez

Duam oldu benim bu yüzden

İçine sevgiler burulmuş

Korkusu gözlerimde kedinin

Sana getirdim

“Öpersin gözlerimden”', 'Düşerken kedi merdivenden Ben de peşisıra	 İçine sevgiler burulmuş Korkusu gözlerinde kedinin Kader gibi Kader gibi hani Beni uçurumlara ite...', ARRAY['Türk Edebiyatı','Şiir','Ayça Yeşim']::text[], 8.5, '{"poet":"Ayça Yeşim","poet_slug":"ayca-yesim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kedi-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengarenk', 'rengarenk-reyhan-tataroglu-hfhkl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kaypak bir zemin

                                    üzerindeydi demin

                                    ne çabuk sağlam bastı...

                                    anladım ki bukalemun', 'kaypak bir zemin                                     üzerindeydi demin                                     ne çabuk sağlam bastı...         ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rengarenk-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sezgi', 'sezgi-ali-cengiz-turan-nbffb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben dünyayım dünya benim 

  Yıldırımlar yaratan sözlerim.

  Ağlatmayın üzmeyin beni

  Gözyaşlarıma tufan derim.

  Yıldızlarla beraber gülerim,

  Aya güneşe merhaba derim.

  Ağlatmayın üzmeyin beni,

  Zamansız kendimi kurban ederim.', 'Ben dünyayım dünya benim    Yıldırımlar yaratan sözlerim.   Ağlatmayın üzmeyin beni   Gözyaşlarıma tufan derim.   Yıldızlarla beraber güleri...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sezgi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua...', 'dua-dilan-tan-xbt51', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu garip gönlümde hep özlemeliyim,

Yanmalıyım özleminle acı çekmeliyim.

Sevdana inat o çok korktuğum yükseklerden dağların en yüksek tepesinden bakacağım aşağılara ve korkmayacağım

Geceler korkutmayacak beni

Kabuslar uyandırmayacak artık en derin uykulardan

Soğuk mezar taşları ürkütmeyecek bedenimi

Özlemler bir taş olup düşmeyecek yüreğime

Yüzümdeki çizgileri seveceğim artık,

Saçıma düşen her beyaz telde asılmayacak yüzüm

Doğum günlerimde saklamayacağım yaşımı utanmayacağım mumlardan

Ağlamayacağım hüzünlü notalarda

Ağlasamda saklayacağım gözyaşlarımı mendilin arkasına

Bebeklere gülümseyeceğim annelerine

Yaşlılara özlemle bakacağım onlara benzeyeceğim diye

Eski resimlere bakacağım

Kahkalarımın yerini tebessümler almış olacak

Anı defterlerimi karıştıracağım

Bir zamanlar kalbim kadar tertemiz olan

Şimdi eski ve saramış

Kurumuş bir gül bulacağım o sarı sayfalar arasında

Ne zaman geldiği hatırlayacağım o gülün

Aynı gurur ve utanç gözyaşlarımla

Sevdamı da  kurutmuşum o sayfalarda

Gençliğim sıkışmış 1 ve 5.sayfalar arasında

Gözyaşlarım dağıtmış cümlelerimin mürekkebini

O günkü parfümüm kokuyor küfle karışık

Özlediğim renk kalacaksın hafızamda

Özlediğim ve bulamadığım koku

Sensiz geçen her saniyenin bitmesi için dualar edeceğim

Senle geçen saniyelerin hayali  hiç bitmesin diye dualar edeceğim….', 'Şu garip gönlümde hep özlemeliyim, Yanmalıyım özleminle acı çekmeliyim. Sevdana inat o çok korktuğum yükseklerden dağların en yüksek tepesin...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dua-149-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün kelimeleri', 'huzun-kelimeleri-elazigli-mustafa-kaya-n9w8y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yorulmadı deniz

ben tükendim

çarpa çarpa dalgalar

bir sahilden diğerine atıldım

kendime dargınım

geciktim gecelere

ay küstü

yıldızlar döküldü

şafak gecikti

ısıtmadı güneş..

bir deniz başında

şimdi

ağlamak istiyorum

hem toprak saçıp başıma

hem kaybolup göklerde 

ve unutmak,

zapt edemediğim  acıları

hüzün kelimelerinde.

ve,

sığındığım,

kar yamaçlı dağlarda..

Mustafa kaya

01.02.2006 / tuzla', 'yorulmadı deniz ben tükendim çarpa çarpa dalgalar bir sahilden diğerine atıldım kendime dargınım geciktim gecelere ay küstü yıldızlar döküld...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/huzun-kelimeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsancıklar', 'i-nsanciklar-abdullah-gencay-c9sg7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Satarken  ruhlarını ve bedenlerini

Yalakalıklar ve menfaatler için

İnsanlığın ayıplar listesine

İnsancıklar, olarak geçer isimleri

İnek kadar  da bile olamaz; insancıklar! 

İnsan,  ineği besler; 

Fazla yem için yalakalık yapmaz

Verebileceği kadar süt verir

Ya köpekler; 

hiç duymadım! 

İyi besledi  diye sahibine, 

Daha çok sadakatlık   yapsın

Onlar ette, ekmekte yese aynıdır

Yalakalık,   insancıklarındır', 'Satarken  ruhlarını ve bedenlerini Yalakalıklar ve menfaatler için İnsanlığın ayıplar listesine İnsancıklar, olarak geçer isimleri İnek kada...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/insanciklar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülke Kimin?', 'ulke-kimin-ali-cengiz-turan-rgc3b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben insanım insan,

     Canlılığa saygı duyan.

     Milli duygu sömürgüsüne,

     Karşı olan karşı duran.

     Milli duygu vatan aşkı bizim,

     En önde savaşmak zorlukla yarışmak,

     Tehlike anında kale olmak,

     Horlanmak azarlanmak bizim.

     Türkiye sizin yatlar katlar sizin,

     En güzel yaşam eylenceden eylenceye koşan,

     Ülkenin bütün kaynaklarını yağmalayan,

     Bu ülke kimin? Sizin mi? Bizim mi? 

     Biz savaşan siz savaştıran,

     Siz sömüren biz sömürülen,

     Biz ezilen ekmeği elinden alınan,

     Siz ezen ezmeyede devam eden.

     Biz bu ülkede sizi yaşatmak içinmi varız? 

     Öyleyse yokuz.

     Bundan sonra çalışın yiyin,

     Çünkü sizi sırtımızdan atıyoruz.', 'Ben insanım insan,      Canlılığa saygı duyan.      Milli duygu sömürgüsüne,      Karşı olan karşı duran.      Milli duygu vatan aşkı bizim,...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ulke-kimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sondan Başlamak', 'sondan-baslamak-ali-cengiz-turan-dtz0w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel günler için güzel günleri verdim

   Dünyanın nefesine nefesimi ekledim.

   Yaşadığım günleri yaşamadan geçsemde 

   Geleceğe yön için varlığıma söz verdim.', 'Güzel günler için güzel günleri verdim    Dünyanın nefesine nefesimi ekledim.    Yaşadığım günleri yaşamadan geçsemde     Geleceğe yön için ...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sondan-baslamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluk', 'sonsuzluk-ali-cengiz-turan-47s3e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acı duymadan ölmek öldüğünü bilmemek

   Örtü olan zamanın içine girmek

   Toprağın kokusuna sarılmak

   Doğan güneşle ayı,masmavi dünyayı

   Görmemek görmemek görmemek

   Sonsuz karanlığa alışmak

   Nerelere gitmek neler yapmak

   Sonsuzluğun derinliğinde kaybolmak

   Kaybolduğunu bilmemek bilmemek

   Nasıl yaşadığının farkına varmamak.', 'Acı duymadan ölmek öldüğünü bilmemek    Örtü olan zamanın içine girmek    Toprağın kokusuna sarılmak    Doğan güneşle ayı,masmavi dünyayı   ...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sonsuzluk-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Ayrımı', 'yol-ayrimi-tibet-avci-hzys5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bukadarmıydı

Bittimi yani öylesine

''''Dost kalalım ölesiye''''

Ben seni hangi yarısında kaybettim hayatımın

Seni kendimde bulduğumdamı

Yoksa  kendimi sende kaybettiğimdemi

Nasıl bir hayattı ki seninki

Beraber yaşıyorken aynı hayatı

Seni böylesine zorladığından

Haberim bile olmadı

Biz değilmişiz meğer o aşıklar

''''Sen ve ben'''' iz çünkü

Seninle yaşadığımız aynı hayat değil

Aynı yol değilmiş yürüdüğümüz

Bir noktada kesişmiş sadece kalplerimiz

Ben niye beceremiyorum öyleyse 

Yol ayrımlarında çekip gitmeyi

Niye hep o yoldan gitmek ister kalbim

Kendi yolu yokmuş gibi

Yol ayrımlarında yitirdim kalbimi

Kalbim başka bir yola girdi

Aklım başka

Bense kalakaldım yol ayrımında', 'Bukadarmıydı Bittimi yani öylesine ''''Dost kalalım ölesiye'''' Ben seni hangi yarısında kaybettim hayatımın Seni kendimde bulduğumdamı Yoksa  k...', ARRAY['Türk Edebiyatı','Şiir','Tibet Avcı']::text[], 8.5, '{"poet":"Tibet Avcı","poet_slug":"tibet-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yol-ayrimi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetim duruşlu ben', 'yetim-duruslu-ben-elazigli-mustafa-kaya-w43om', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ömrüm geçiyor.

hangi bahanelere başvursam

kaskatı kesiliyorum.

yangın yerlerine dönüyor

ruhum.

günlerime

güneş vurmuyor.

yetim insanlara benziyor

duruşum.

yorgun düştüm.

binlerce düşünce topladım

kendime.

elim

ayağım

dilim dolanıyor.

ayazlarda kalmış

bedenim.

kırıldı mutluluklarım

toprağa yayıldı

yarınlarım

çaresizim,

çiçek açan kırlardan

habersizim

taşlara başımı çaldım

bir  ceviz ağacının dibinde.

Mustafa kaya

01.02.2006 /  sarıyer', 'ömrüm geçiyor. hangi bahanelere başvursam kaskatı kesiliyorum. yangın yerlerine dönüyor ruhum. günlerime güneş vurmuyor. yetim insanlara ben...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yetim-duruslu-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geride Kalanlar', 'geride-kalanlar-turhan-toy-u2wwz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık hiçbir şey eskisi gibi olmayacak 

Kutupların soğuğu gibi sesim 

Yüreğini yakacak

Ruhunu kavuracak

Yıllardır sahnelenen oyunun 

Son rötuşları yapılırken 

Sahte gülücük ve sözlerine 

Bir daha kanmayacak 

Sana açılan tüm kapıları kapayacağım 

Artık hiçbir şey eskisi gibi olmayacak 

Nerede baharlara açılan gök 

Külüm rüzgârlarda uçuşurken 

Düşümü döşüme gömdüm 

Tırnaklarınla eşelediğin yüreğimi 

Al senin olsun sök 

Ne kalmış ki elimde kederli bir ömürden 

Sayabiliyorsan say dök 

Bir zaman aralığından geçtik 

Kibrit çöpünün alazlanması kadar 

Belki daha da kısa bir zaman seçtik 

Zaman zerre kadar uzağımızda durmuş

Nefesi ensemizde 

Artık hiçbir şey eskisi gibi olmayacak 

Yüreğimin yangınına yangısına yöneldim 

Tüm kapılarımı beni gözetene açtım 

Sevene sevdama ölüyken diriltene 

Nereye bakarsam gördüğüm aşkıma kaçtım 

Artık sen ne yaparsan yap kendine 

Ben tüm ışığımı aynama saçtım 

Ey yüreğimin kuşu gir kafesine 

Kavuşmak yakındır sevgiliye', 'Artık hiçbir şey eskisi gibi olmayacak  Kutupların soğuğu gibi sesim  Yüreğini yakacak Ruhunu kavuracak Yıllardır sahnelenen oyunun  Son röt...', ARRAY['Türk Edebiyatı','Şiir','Turhan Toy']::text[], 8.5, '{"poet":"Turhan Toy","poet_slug":"turhan-toy","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/geride-kalanlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'I) şık..', 'i-sik-reyhan-tataroglu-pcmm4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'parmak ucumdun

                                   gösterdiğim her yerde

                                   işaret ederken...

                                   söndü bütün ışıklar

                                   açıldı perde

                                   görmez oldu göz gözü

                                   seyre daldı seni

                                   ışık nerde ışık nerde', 'parmak ucumdun                                    gösterdiğim her yerde                                    işaret ederken...                ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/i-sik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş...', 'serzenis-dilan-tan-dbux9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SERZENİŞ

....

ey can..! 

Bahar terkedilmişliğindeyken yapraklar, avuçlarımda biriktirdiğim sevgi sözcükleri dipsiz ayrılıkların sonbaharında solarken; 

Karanlığa yazdığım şiirleri dinlemelisin rüzgarlarda yüreğimde tortulanmış çığlıkları ve pimi çekilmiş öfkelerimi de.

Sen bütün bunları simyanla damitip ask etmelisin.

Yine bir sabah karanlığa açarken pencerelerimi,

güvercinlerle gelmeli gözlerin,

Işığın gelmeli.

Gözlerinden uzanmalıyım bengisu pınarlarına; 

İçmeliyim...

Hayat bulmalıyım...

Umut tohumlarım yeşermeli yeniden,

Seherleri yeni günün şarkısıyla raksetmeli kuşlar..

Ve ben hazan yaprakları toplamalıyım  ayaklar altından.

Ey can...! 

Bir gün bir hazan rüzgarı, kuru bir yaprak uzatırsa avuçlarına; 

Umarsız bir tavırla ayaklar altına terk etme onu.

Kim bilir hangi aşığın yüreğindeki umudun solgunluğunu taşıyor omuzlarında,

Kim bilir benden bir şeyler getirmiştir belki de sana.

Hazana aldırma ey can...! 

Dedim ya! 

RÜZGARLARI DİNLE....! 

Y.A

Rüzgarları Dinledim...

Bu satırları yazan güzel insanın kıymetini bilemedim hala o rüzgarlardayım, Biliyorum dön desem dönmeyeceğini...

Biliyorum başka iklimlerde başka yüreklerdesin seziyorum...

Ama hala hala...

Yanlış belki yalan belki umut var yüreğimde...

Bilsen yüreğimi çektiğim acıları beni affedersin,ama sen beni hiç affetmedin ve birgün ansızın çektin gittin…….

Eğer beni özlersen yüreğine bak, eğer sesimi duymak  istersen

rüzgarlardayım dinle ağlıyorum...

Hazan yapraklarıyla dans ediyor pişman geçmişim...

Ve ben bu güzel yüreğin kıymetini bilemedim...

Bekleyeceğim sabırla....

Sensizlik durağında karşılaşmak ümidiyle bekleyeceğim seni...

Dün kaybetmiş gibiyim seni,

Sana olan sevdam milat doldurdu...

D.T', 'SERZENİŞ .... ey can..!  Bahar terkedilmişliğindeyken yapraklar, avuçlarımda biriktirdiğim sevgi sözcükleri dipsiz ayrılıkların sonbaharında...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/serzenis-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin ve ellerin', 'sesin-ve-ellerin-abdullah-gencay-pcu7z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mehtaba karşı,  balkondayım

Ne sohbetin var ne ellerin

Ansızın  esen,  rüzgara

İrkilen , çaresizliğe yenilen

Bitkin,  yorgun  bedenim

Sessizliği bozan tek şey

Sensizliğin    feryadı

Görünen sadece  birkaç yıldız

Onlarda hüzünlü, üzgün 

Kapattım gözlerimi

Var olduğunu hayal ederek 

Başladım sohbete 

Yokluğunu anlattım  dakikalarca

Döktüm içimde ne varsa eteklerine

Açıtım gözlerimi,   yine hüsran                  

Yine daldım geceye 

Düşünürken acaba bir ışık var mı diye

O an yıldız dile geldi

Olumsuz dedi !  

Kaydı o da karanlığa  düştü', 'Mehtaba karşı,  balkondayım Ne sohbetin var ne ellerin Ansızın  esen,  rüzgara İrkilen , çaresizliğe yenilen Bitkin,  yorgun  bedenim Sessiz...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sesin-ve-ellerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dediler', 'dediler-gulsen-agir-omasz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unut geçmişi dediler

Sil acıları seni yediler

Arkana bakma yürü

Gelecek ilerde dediler.

İnsanın yüzü başında

Neden öndedir dediler

Çünkü geçmiş arkada

Gelecek öndedir dediler.

Acıları bırak ardında

Seni bekliyor yarınlar

Taşıma bırak kalsınlar

Terk et geçmişi dediler.', 'Unut geçmişi dediler Sil acıları seni yediler Arkana bakma yürü Gelecek ilerde dediler. İnsanın yüzü başında Neden öndedir dediler Çünkü geç...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Ağır']::text[], 8.5, '{"poet":"Gülşen Ağır","poet_slug":"gulsen-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dediler-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uç Uç Böceği 2', 'uc-uc-bocegi-2-i-rfan-kaban-zc1hy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecedir,karanlıklar mevzi

Çaresizlik başa kalkmış,eline geçirmiş liderliği

Daha koyu bir karanlık seçersin

El yordamı çareler üretmek için şimdi mevzidesin 

Gecedir

Adam akıllı aldatır adamı

Gecedir

İnsanın beyninde olanca korkusuyla şekillenir

Gecedir

Gölgeler düşer,gerçek gölgelenir

Gecedir

ve,

Saflar belirlenmelidir…

batarsın kar,çıkarsın çıvgın

soğuk buz kesmiş

ne ay ışığı

ne gökte bir yıldız var

yürek pür telaş çarpar

sesini duyarsın yürek atışlarının

canın yüreğinde tutar

yüreğin atmaz da tekmil canın atar

yine de

ne güzel bir şeydir canım

şu yaşamak heyecanın

geceyle dans tutmuş bir yaman tipi

arada sesler

yakınların sesleri…

öyle! 

öyle gibi…

diyor ki sesler; 

gecenin çekilecek ipi

dayan ha dayan…

heves yükseliyor

direnmek ruhu öteki ruhlara galebe çalıyor

gecenin suyu kaynadı kaynayacak diyor

akıl yatıyor...

bu bizimki bir titrek üşümek ki sorma! 

Ondandır çekinmeden sokulup giriyoruz seslerin koynuna

Kolay değil dayanmak canım

Dayanmak kolay iş değil

Bu İstanbul şehrinin nemli soğuğuna

Akıl yorgun

Çağların yükünü yüklenmiş de

Pestili çıkmış

Kaç hain tuzaktan sıyırmış da

Yine köşeye sıkışmış

Akıl yorgun,uzansın istiyor

Şaşırmış kar beyazı düş kuruyor

Akıl yatıyor....

Gecenin suyu kaynadı kaynayacak

Şunun şurasında ne kaldı diyor akıl; 

Ha desen sabah olacak.

göz gözü görmez

her iş deneme yanılma

sesler gelir girer koluna

sürükler götürür adamı

tatlı gelir uçar gibi gitmek

lezzetine uykunun yenilmek

öteden beri böyledir; akıl yatar

öteden beri böyledir,

gün müjdeleyen rüzgarlar aşk kokar

ısınmak istersin,ısınırım dersin,denersin

bulutların bütün şimşeklerini

yorgan üstüne yorgan çekersin

ta uzaklar görür seni

göremezsin bir santim bile ilerini

can atarsın

sevdaya uçurur sevgin,bakmaz beyaz körlüğüne

can atarsın

sevgilinin dudağına konduracağı

o tatlı aşk öpücüğüne

tenine değen sevgili teni girmiş kanına

ısınırsın

ısınırsın

sanırsın bir yıldızla çarpışmışsın

bir olmuş evrende hacminiz

gün ışımış yerdesiniz

buzlar çözülür

katılığını giderir ısı hayatın

yumuşatır

kıvamına getirir yaşamı

ve 

umut yeşerir

kurarsın

soyunmalı sevgili

toprak tez bahara giyinmeli

aylar işlemeli

sevgilinin memelerine süt inmeli

sevgili ışık ışınıdır,sıcak

bıraksa kendini

oracıkta bahar aşk olacak...

sen,

işte sensin

tıpkı kitaplarda yazan 

daha ne diyebilir ki zaman

sensin

aradığın güzelliğin yolunda fena çiğnenmişsin

gerçeklere küsmen yorulmuşluğun

bir ömür yetmez sevdaların peşinden koşmuşluğun

filiz açmış bahar bir sana görünür

o gidenler gibisin

aydınlıklar yokluğuna bürünür...

ta öteden beri bizi böyle tez can

böyle deli

gün muştulayan rüzgarlar ederdi

kaç sökmez şafak ikizdi 

tıpkıydı birbirine benzerdi

kaç sökmez şafak ikizdi

inandırırdı ve sökmezdi

uç- uç böceği gençliğimizdir

sökmez şafaklarda gurur

uç- uç böceği gençliğimizdir

karanlık gecelerde fener  durur.

1984', 'Gecedir,karanlıklar mevzi Çaresizlik başa kalkmış,eline geçirmiş liderliği Daha koyu bir karanlık seçersin El yordamı çareler üretmek için ş...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kaban']::text[], 8.5, '{"poet":"İrfan Kaban","poet_slug":"i-rfan-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":114,"source_url":"https://www.antoloji.com/uc-uc-bocegi-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk yıl', 'kirk-yil-reyhan-tataroglu-2x5wd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'oysa çok metetmiştim onu

                         elindeki tepside

                         köpüklü fincan kahveleri vardı

                         yavaşca eğildi,baktı ama görmedi

                         gözleri,gitti bir daha gelmedi

                         halbuki beni çok iyi tanıyordu

                         rezil olmuştum herkese

                         bir anlam verememiştim buna

                         dayanamadım birden kalktım 

                         gittim yanına,döndü gayri ihtiyari

                         ''''evet''''dedi,uzattım elimdekini

                         yavaşça aldı,doldu gözleri

                         başını omuzuma dayadı

                         ağladı ağladı...hanımım...hanımım...

                         derken,üstü cebinde kaldı

                         rahmetlik mahmure hanım

                         gerçekten iyi bir hanımdı', 'oysa çok metetmiştim onu                          elindeki tepside                          köpüklü fincan kahveleri vardı                  ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kirk-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Cananım Gelsin (Türkü)', 'cananim-gelsin-turku-umut-gul-aa85p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllardır bekledim yolunu senin

Ağlama sevdiğim gülsün gözlerin

Dokunman ne olur yaram çok derin

Yaramı sarmaya cananım gelsin

Gülmedim sevdiğim yalan dünyada

Hasretin yazılmış benim alnıma

Girersem toprağa  doymadan sana

Cenneti neyleyim cananım gelsin

Hasretin içimde dağlardan beter

Yarimin kokusu burnumda tüter

Gün gelir bu ömür ömürde biter

Mezarım kazmaya cananım gelsin

Umut gülüm der ki sitemim dosta

Andıkça maziyi kalırım yasta

Doktorlar neylesin yüreğim hasta

Derdimin dermanı cananım gelsin', 'Yıllardır bekledim yolunu senin Ağlama sevdiğim gülsün gözlerin Dokunman ne olur yaram çok derin Yaramı sarmaya cananım gelsin Gülmedim sevd...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cananim-gelsin-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duraktaki Mısralar', 'duraktaki-misralar-nail-oruc-2xv7e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belki bugün değil ama yarına; 

Yazılacak neçe şiirler var senin için.

Ceplerinde işlenmemiş betimlemelerle,

Sırasını bekler şimdi mısralar kol kola vermiş.

Kimisi  gözlerine karalar çalacak,

Kimisi saçlarına örgüler çekecek,

Belki ben değil ama; 

Son mısralar  tutup yüreğinden 

Seni bana getirecek', 'Belki bugün değil ama yarına;  Yazılacak neçe şiirler var senin için. Ceplerinde işlenmemiş betimlemelerle, Sırasını bekler şimdi mısralar k...', ARRAY['Türk Edebiyatı','Şiir','Nail Oruç']::text[], 8.5, '{"poet":"Nail Oruç","poet_slug":"nail-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/duraktaki-misralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen haklısın', 'sen-haklisin-abdullah-gencay-be09x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haklısın...

Bütün sözlerinde

Hakkımda ki,  düşüncelerinde

Kendi pencerenden baktığında

Haklısın...

Yaşanmışları,  silsen de 

İzi kalır, 

Kötü anı olarak

Haklısın...

Ama;

Kendini benim yerime koy

İşte  bu  insan,  Nihayet ! 

Diyeceğinle, 

Karşılaşırsan bir gün

Sessiz bir yerde,  gözlerini kapa

Düşün,  ancak o zaman 

Beni anlarsın

Haklısın…

Ama şimdi, daha sonra

Beni haklı bulacaksın !', 'Haklısın... Bütün sözlerinde Hakkımda ki,  düşüncelerinde Kendi pencerenden baktığında Haklısın... Yaşanmışları,  silsen de  İzi kalır,  Köt...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-haklisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi Aynı Trende Benle Beraber (Rüya) -1-2-3-4', 'hepsi-ayni-trende-benle-beraber-ruya-1-2-3-4-eyup-selahattin-dalkiran-69c2n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gördüklerim ne güzeldi 

Hepsi bir arada birlikte yolculukta 

Ben  neden aralarındaydım ki? 

Nazım Hikmet Ran

Oturmuş kompartmanda konuşuyordu diğer şairlerle

Gelmişten,geçmişten bahsediyorlardı

Beni gördü Nazım Hikmet Ran 

Hey evlat Gelsene

Şu elindeki kitaba bir bakalım

Senin şiirlerinmi bunlar? 

Evet dedim

Baktı baktı mavi gözleri ile

Vay be vay dedi

Aynı memleket özlemi

Aynı sevgi özlemi Vay be vay

Aynı sarhoşluk

Sordu bana Nazım Hikmet Ran

Türkiye ile Rusyanın arası nasıl

Eh şimdilik idare eder bir sorun çıkmazsa politikalarla.

Şimdide doğal gazı kesiyorlar yavaş,yavaş

ABD’ye taraf Olduğumuz için 

Ayrıca İran’da doğal gazımızı kesti

Bilmem nerede gözetliyoruz  diye onları

ABD ile topraklarına saldırmayalım diye.

Yakında ekonomik kesintilerde yapmaya başlarlar Nazım abi dedim

Belli diyor eskiden olduğu gibi

Herşey ekonomi politikle ilğili

Soruyor,şairler,devrimciler, halen tutuklanıyormu

Hemde nasıl diyorum

Kimi hapise kimi sürgüne

Vay be diyor vay be.

Vatanımı özledim evlat biliyormusun? 

Yukarıdakilere söyleyin benim mezarımı

Alsınlar memleketime.

İnsanlarımı,havasını,kokusunu

Vapur seslerini

El ele yürüyen sevgilileri

Acı çekenleri,emekçilerimi Çanakalede şehit düşenleri,

Vatanı için ölenleri,şiirlerimi özledim

Yurdumda kalayım

Gidin söyleyin onlara

Yada elele verin başlatın bir kampanya olsun bitsin

Alın beni yurduma,koynunda yaşayayım.

Hey Veli can yoldaşım ölümüne dostum baksana bir bana

Orhan Vel Kanık Pencereden dışarı bakıyordu o ara

Hey dedi bırak dışarıya bakmayı herşey aynı  yolda

Yıllardır gidiyoruz,ben azmı baktım sevgilimi göreyim diye 

Orhan Veli Kanık arkasını döndü baktı

Suratına baktım kafası bandajlıydı

Eliyle tutuyordu belli başı ağırıyordu 

Veli bak aramızda genç bir şairimiz var

Hepimizi nasılda anlatıyor al bir bak kitabına

Orhan Veli kanık Nazımın elinden aldı kitabı.

Baktı baktı baktı

Sonra bana baktı

Sordu birden Ankarada Halen belediyenin 

Açtığı Çukurlar varmı? 

Hemde Alasından içine düştümmü zor çıkarırlar adamı

Güldüler bok çukuru desene diye

Peki İstanbul nasıl? 

Oda ankara gibi her yer delik deşik parça pinçik

Tutturmuşlar marmara ray diye insanlar geçmez oldu Üsküdarda

Yolları hep böldüler ne yaptıkları mechul

Hepsi para peşinde

Şimdi sakalılar var belediyelerde,yukarılarda

Gülüyor Orhan veli Kanık

Nazım Duyuyormusun? 

Şimdi sen olsan orada seni yine içeri tıkarlar vallahi

Kafasını salıyor veli abiye bakarak Nazım abi

O ara Nazım abi seslendi sevecen sesi ile Ümit diye

Uyuyan Ümit Yaşar oğuzcan’a

Ümit kalk sevgiler delisi kalk kalkta

Aramızdaki yürekli şairimizi gör

Yarı uyanık yarı uykulu

Ne var Nazım abi

Bak aramızda bizim yüreğimizi taşıyan bir şair var

Al bak kitabına 

Ümit abi kitabı alarak baktı

Yahu beni anlatıyor sanki bu kitap

Diyor ki ordan Nazım abi

Tabii anlatacak ama bir şeylerden korkuyor

Bak şair arkadasim korkma yürekli ol doğruları yansıt,bakıyorum yüzlerine

Hapise düşsende,sürgüne gitsende,kurşuna dizilsende korkma

Veya bir pust tarafından vurulsanda.

Ümit abi sordu bana

Evlat sen hiç parise gittinmi? 

Suratına baktım,nerde  emekli maaşımla

Kıt kanaat geçiniyoruz  nasıl gidelim ki

Ama Parisli gele biliyor biz gidemeyiz

Bize yasak çünkü para yok

Hüzünlü bir gözle bakarak kitaba tekrar bakmaya başladı

Bana Bir Şarkı Söyle İsimli şiirini mırıldanıyordu

Kitabıma bakarken

Özledim sesini ne olur konuş 

Bir gül açtır zamanların ötesinden 

Karanlıklar içindeyim, kapkarayım bugün gel 

Gök mavisinden, deniz mavisinden 

Bana bir şarkı söyle 

İçimde bir şey kımıldıyor 

Gözlerim kan çanağı, yorgunum, uykusuzum 

Bir baksana ne haldeyim deli divane 

Yaralıyım, çaresizim umutsuzum.

Müsadenizle bir siğara yakacağım trenin koridorunda

Müsade senin dediler,ama gördüklerim daha farklı oldu

Kimler yok ki trende aman Allahım

Necip Fazıl,Can Yücel,Yahya kemal,Ahmet Arif,

Faruk Nafiz,Ahmet Muhip,Bedri Rahmi,Mehmet Akif

Behçet Necatigil,Cemal sürreya,Ahmet Hamdi,Neyzen Tevfik

Pir sultan,Aşık veysel daha bir yığın şair abilerimiz

Siğaramı yakamadım onları gördukçe.

Bir şaşkınlıktı aldı beni Benim ne işim var aralarında diye

Yoksa bendemi öldüm dedim kendi kendime.

Hey evlat 

Efendim.... Oktay Rıfat ordamı? oralardaysa

Söyle Yoldaş Nazım çağırıyor seni de dedi

Baktım Rıfat abide orda yanına gittim

Rıfat abi seni Nazım abi seni çağırıyor yanına

Yüzüme baktı Sen kimsin? 

Burda ne arıyorsun? Vallahi burda buldum kendimi

Bende bilmiyorum sebebini,gel bakalım dedi

Siğara elimde yanmadan Kompartmana girdik

Siğaranı içtinmi? hayır dedim 

 neden? 

İçemedim ki bütün büyük şairleri birarada görmekten

Yakmaya bile fırsatım olmadı Nazım abi.

Nazım abi birden kalktı ellerini omuzuma koydu

Hey millet bakın bu arkadaş geleceğin şairidir

Hepsi birden baktı koridordan geçenler durup durup

Bakıyorlar içeri hoş geldin diyerek bende bir ter bir ter

Allahım diyorum nedir bu hikmetin neler geldi başıma

Bendemi öldüm acaba bir korkudur aldı benliğimi

Can Yücel suratıma baktı Kompartman kapısında

Nazım Abi bu arkadaş kim? 

Geleceğin şairi Can bizlerin ümidini yüreğinde taşıyan

İlerici sairimiz,gerçek milliyetçimiz,gerçek halkcımız

Diğer şairler gibi gerçekçi.

Dur bakalım dedi Nazım abiye

Evlat söyle bakalım benim bir şiirimi.

Soğuk harp bitti 

Sıcak savaşlar başladı 

Memleketim de bir içsavaş halinde 

Memleketim bir içkanamada

Döğüşelim barış içi değil mi? 

Evet 

Bak gördünmü Can fazla söze gerek yok

Nasılda anlattı ülkemizin durumunu 

Değilmi can döğüşelim barış için  isimli şiirinle

O zaman güzel yazmışsın öyle,şimdiki zamana uygun

Necip Fazıl içeri bakarak Nazım abi  Mehmet Akif Nerede? 

Ne oldu ki Hiç Ya onun bir şiiri varya ülkemiz için Yazdığı

E ne olmuş şiirini okuması için arıyoruz

Ne gerek var aha burda yeni bir Şairimiz var o Okusun

Olur Dedi Yan Taraftaki Kompartmana geçtik,

Orada Yahya Kemal,Ahmet Muhip,Bedri Rahmi,

Faruk Nafiz,Behçet Necatiğil,Cemal Süreyya oturmuşlardı

Beni görünce hepsi ayağa kalktı,sordular kim bu arkadaş

Necip dediler? 

Nazım abi gönderdi bu yeni arkadaşı aramıza

Mehmet abinin şiirini okusun diye.

Birde kitabını verdi Nazım abi bakasınız diye

Necip abi haydi evlat oku bakalım istiklal marşımızı tam olarak.

Titreyen Dudaklarımla başladım okumaya

Korkma, sönmez bu şafaklarda yüzen al sancak; 

Sönmeden yurdumun üstünde tüten en son ocak. 

O benim milletimin yıldızıdır parlayacak; 

O benimdir, o benim milletimindir ancak. 

Çatma, kurban olayım çehreni ey nazlı hilal! 

Kahraman ırkıma bir gül! Ne bu şiddet bu celal? 

Sana olmaz dökülen kanlarımız sonra helal, 

Hakkıdır, Hak''ka tapan, milletimin istiklal! 

Ben ezelden beridir hür yaşadım, hür yaşarım. 

Hangi çılgın bana zincir vuracakmış? Şaşarım; 

Kükremiş sel gibiyim, bendimi çiğner aşarım; 

Yırtarım dağları, enginlere sığmam, taşarım. 

Garbın afakını sarmışsa çelik zırhlı duvar, 

Benim iman dolu göğsüm gibi serhaddim var. 

Ulusum,korkma! Nasıl böyle bir imanı boğar. 

''Medeniyyet! '' dediğin tek dişi kalmış canavar? 

Arkadaş! Yurduma alçakları uğratma sakın! 

Siper et gövdeni, dursun bu hayasızca akın. 

Doğacaktır sana vaadettiği günler Hak''kın; 

Kimbilir, belki yarın, belki yarından da yakın. 

Bastığın yerleri ''toprak'' diyerek geçme, tanı! 

Düşün, altında binlerce kefensiz yatanı. 

Sen şehit oğlusun, incitme, yazıktır atanı; 

Verme, dünyaları alsan da bu cennet vatanı. 

Kim bu cennet vatanın uğruna olmaz ki feda? 

Şüheda fışkıracak toprağı sıksan, şüheda! 

Canı, cananı, bütün varımı alsın da Hüda, 

Etmesin tek vatanımdan beni dünyada cüda. 

Ruhumun senden, ilahi şudur ancak emeli; 

Değmesin mabedimin göğsüne na-mahrem eli! 

Bu ezanlar ki şahadetleri dinin temeli, 

Ebedi yurdumun üstünde benim inlemeli 

O zaman vecd ile bin secde eder varsa taşım; 

Her cerihamdan, ilahi, boşanıp kanlı yaşım, 

Fışkırır ruh-i mücerret gibi yerden naşım; 

O zaman yükselerek arşa değer belki başım! 

Dalgalan sen de şafaklar gibi ey şanlı hilal; 

Olsun artık dökülen kanlarımın hepsi helal! 

Ebediyyen sana yok, ırkıma yok izmihlal. 

Hakkıdır, hür yaşamış bayrağımın hürriyet; 

Hakkıdır, Hak''ka tapan milletimin istiklal! 

Bittiği zaman hepsi birden sarılmaya basladılar

Kiminin gözü yaşlı kimi hüzünlü olarak.

Kompartman kapısından içeri Mehmet Akif abi baktı.

Kim bu benim şiirimi okuyan? kişi diye seslendi

Hepsi birden nerdesin be abi seni arıyoruz bi zamandır

Biraz dolaştım diğer şair arkadaşlarla günü ahval ettik

Bak senin medarı iftiharın olacak genç bir şair var aramızda

Biraz önce senin istiklal adlı şiirini okudu

İçimiz yandı ülkemize hasret diye

O ara Mehmet Akif abi peki dedi benim çok sevdiğim

Bir şiirim var onu okuyabilirmisin? nedir dedim

Müslümanlık Nerde? 

Biliyorum dedim okuda dinleyeyim dedi.

Müslümanlık Nerde 

Müslümanlik nerde! Bizden geçmis insanlik bile... 

Adem aldatmaksa maksad, aldanan yok, nafile! 

Kaç hakiki müslüman gördümse, hep makberdedir; 

Müslümanlik, bilmem amma, galiba göklerdedir; 

Istemem, dursun o payansiz mefahir bir yana... 

Gösterin ecdada az çok benziyen kan bana! 

Isterim sizlerde görmek irkinizdan yadigar, 

Çok degil, ancak Necip evlada layik tek siar. 

Varsa sayet, söyleyin, bir parçacik insafiniz: 

Böyle kansiz miydi -hasa- kahraman ecdadiniz? 

Böyle düsmüs müydü herkes ayrilik sevdasina? 

Benzeyip sirazesiz bir mushafin eczasina, 

Hiç görülmüs müydü olsun kayd-i vahdet tarumar? 

Böyle olmus muydu millet canevinden rahnedar? 

Böyle açliktan bogazlar miydi kardes kardesi? 

Böyle adet miydi bi-perva, yemek insan lesi? 

Irzimizdir çignenen, evladimizdir dogranan... 

Hey sikilmaz, aglamazsan, bari gülmekten utan! ... 

''His'' denen devletliden olsaydi halkin behresi: 

Payitahtindan bugün tasmazdi sarhos naresi! 

Kurd uzaklardan bakar, dalgin görürmüs merkebi. 

Saldirirmis ansizin yaydan bosanmis ok gibi. 

Lakin, ask olsun ki, aldirmaz otlarmis esek, 

Sanki tavsanmis gelen, yahut kiliksiz köstebek! 

Kâr sayarmis bir tutam ot fazla olsun yutmayi... 

Hasmi, derken, çullanirmis yutmadan son lokmayi! ... 

Bu hakikattir bu, sasmaz, bildigin usluba sok: 

Halimiz merkeple kurdun ayni, asla farki yok. 

Burnumuzdan tuttu düsman; biz bogaz kaydindayiz; 

Bir bakin: hala mi hala ihtiras ardindayiz! 

Saygisizlik elverir... Bir parça olsun arlanin: 

Vakti çoktan geldi, hem geçmektedir arlanmanin! 

Davranin haykirmadan nakus-u izmihaliniz... 

Öyle bir buhrana sapmistir ki, zira, halimiz: 

Zevke dalmak söyle dursun, vaktiniz yok mateme! 

Davranin zira gülünç olduk bütün bir aleme, 

Beklesirken gökte yüz binlerce ervah, intikam; 

Yerde kalmis, na''sa benzer kavm icin durmak haram! ... 

Kahraman ecdadinizdan sizde bir kan yok mudur? 

Yoksa, istikbalinizden korkulur, pek korkulur.

Aferin evlat aferin 

Hiç korkmasın işte gerçek kahraman

Cemal Süreyya abi ordan seslenerek

Mehmet abi senin sanlı şiirinle ülke ayakta durmakta

Her okunuş korku salmakta emperyalistlere,vurgunculara.

O ara bir saz sesi gelmekte idi biraz ötede

Kulaka kabartım bu dedim bu Aşık Veyselin türküsü

Dedim kendi kendime söyleyeni merak ettim

Gittim baktım Aşık Veysel Şatır söylüyor,sazını çalarak

Allah birdir Peygamber Hak 

Rabbül alemindir mutlak 

Senlik benlik nedir bırak 

Söyleyim geldi sırası 

Kürtü Türkü ne Çerkezi 

Hep Ademin oğlu kızı 

Beraberce şehit gazi 

Yanlış var mı ve neresi 

Kurana bak İncile bak 

Dört kitabın dördü de hak 

Hakir görüp ırk ayırmak 

Hakikatte yüz karası 

Binbir ismin birinden tut 

Senlik benlik nedir sil at 

Tuttuğun yola doğru git 

Yoldan çıkıp olma asi 

Yezit nedir, ne kızılbaş 

Değil miyiz hep bir kardaş 

Bizi yakar bizim ataş 

Söndürmektir tek çaresi 

Kişi ne çeker dilinden 

Hem belinden, hem elinden 

Hayır ve şer emelinden 

Hakikat bunun burası 

Şu alemi yaratan bir 

Odur külli şeye Kadir 

Alevi Sünnilik nedir 

Menfaattir varvarası 

Cümle canlı hep topraktan 

Var olmuştur emir Haktan 

Rahmet dile sen Allahtan 

Tükenmez rahmet deryası 

Veysel sapma sağa sola 

Sen Allahtan birlik dile 

İkilikten gelir bela 

Dava insanlık davası…

Veysel abiyi dinlerken Nazım abi bana sesleniyordu

Yoldaş yoldaş gel diye hemen yanına gittim

Bak yoldaş burdaki arkadaşlar seni imtihan edecekler

Eğer dediklerini yaparsan sana şairler üstü nişan verecekler

Olur dedim 

Söyle bakalım 

Ülkeni Seviyormusun? 

Seviyorum

İçindeki şairleri kim olursa olsun severmisin

Severim

Düşmanın olsadamı? evet

Ülkeni yıkmaya kalksa müsaade edermisin? 

Hayır

Neden? 

O zaman onu gerçek düşman görürüm

Suratına istiklal marşımı okurum anlasın diye

Ezilen emekçinin hakkını nasıl alırsın? 

Sendikayla devrimci sendikayla

Köylünün hakkını nasıl alırsın? 

Gerçek devrimci köylü kooperatifler ile ürünlerini

Değerlendirip haklarını korurum

Emeklinin hakkını Yapacağımız Toplu sözleşmeler ile

Diş diş ile Hükümetle. Mücadele edip alırım zaman içinde

Kadın haklarına ne yaparsın? 

Onların hayata geçmesi için elimden geleni yaparım

Her çeşit yolla.

İçeriye düşmüş aydın ve şairler için? 

Onlar için meydanda olan yasaların değiştirilmesi için

Komiteler kurar komiteler ile 

Mücadele derdim serbest bırakılsın diye.

Melih abi çık dışarı bir siğara iç öyle gel dedi

Peki dedim

Dışarı çıktım baktım pirsultan abdal orda durmuş düşünüyor

Yanına gittim  baktım mırıldanıyordu şiirini

Bana medet senden olur efendim 

Aşılmaz dağların dost ardında kaldım 

Eller dosta doğru çeker göçünü 

Elsiz viranede çöllerde kaldım 

Sana derim sana ey kaşı kare 

Artıyor eksilmez dost sinemde yare 

Bir aşinam yok ki halımı sora 

Yalanlı dolanlı dillerde kaldım 

Sabahtan sabahtan semah tutarım 

Dosta kadar gider oy benim katarım 

Baykuş gibi viranede öterim 

Gel gör ne perişan hallerde kaldım 

Pir Sultan Abdalım ben de gülmedim 

Aradım derdime dost derman bulmadım 

Yol nereden gelir gider bilmedim 

Kesildi kervanım bellerde kaldım.

Oradan Pirsultan Abdal’a birde bana  bakıyordu

Yahya kemal yavaş yavaş yanımıza geldi

Kimsin? diye sordu bana ben Eyüp selahattin Dalkıran

Bir garip şairim,burda ne arıyorsun? 

Bilmem bir anda burda buldum kendimi

Kimlerle tanıştın? kimler yokki 

Halen şaşkınım inanın dedim

Güldü 

Kimin yanındaydın şimdi? 

Faruk abinin yanındaydım 

orda mehmet abinin iki iki şirini okudum onlara

Kimlere? Cemal Süreyya abi,Bedri rahmi,Faruk Nafiz,

Behçet Necti,Mehmet akif abiler iledim

Hımmm Anladım.

Hadi Nazim abinin kompartmanı gidelim

Tamam dedim Yürümeye başlamıştık ki

Bir koşuşturma başladı trenin arkasına doğru

Koşun koşun diye bağırıyorlardı şairler birbirlerine

Durdurup kime sorduysam ne oluyor diye

Kimse cevap vermiyordu.

Koridor tıklım tıklım doldu önden gelenler ile

Zıplayıp ileri bakıyorlardı, merak bu ya bende başladım zıplayıp 

zıplayıp bakmaya çalışıyordum

Geliyor geliyor diye bağırıyorlardı..

Baktım Nazım abi yanımda bitti.

Gel evlat senle bir konuşalım

Gelen kim? Dedim

Öğrenirsin her gelen şair için koşuşurlar bizim şairler

Yeni haberler duysunlar diye geldikleri yerleri  özledikler yeri sorarlar,

Şaire,şairi bıktırana kadar haberlerin en incesinden,

En kalınına kadar öğrenmek isterler

Peki beni niye karşılamadılar? dedim

Güldü Nazım abi

Sen daha ölmedin ki

Senin beynin şu anda bizlerle.

Birden bir gümbürtü koptu

Pencereye baktık,başka bir tren hızla geçiyordu

Ne treni? bu Nazım abi

mavi gözleri ile bana bakarak tebessüm etti.

Siyaset treni, siyaset trenimi burdadamı siyaset var

Başladı kahkahalarla gülmeye

Bir gümbürtü daha koptu ötki pencereye baktım

 Bir tren daha geçiyordu,Bu ne treni? dedim Diktatörler treni

Şaşkın şaşkın suratına baktıkça ben baktıkça o gülüyordu

Bak dedi evlat beklemedeyiz her gelen yolcu mutlaka

Kendi trenine binecek ve o gün geldiğinde bölük bölük

Gireceğiz sorguya ama sana ne mutlu ki yüreğin temiz

Halkın için, vatanın için, ezilen emekçi için koyvermişsin ortaya

Kendini her dürüstlük,haksızlık adına sen korkma,

senin yerin iyiler  treni olacak.

Bir gümbürtü daha koptu bir tren daha geçiyordu

Bu ne treni? dedim Nazım abi

Bana ciddi ciddi bakarak askeri tren dedi

Şaşkınlık üstüne şaşkınlık yaşıyordum her nedense

Bak evlat dedi bu tren var bu trenin uzunluğunu görüyormusun

Günler sürer burdan geçip gitmesi için o kadar uzun ki

Sorma gitsin ama bir özelliği var ki hepsi diğer trenlerde olduğu gibi

Kategorize edilmiştir iyiden kötüye

Nazım abi Hitler hangi trende? ne yapacaksın? 

Sordum işte,Siyaset treninde evlat

Oraya gitme imkanı varmı var tabi ama herşeyin bir sırası var 

Bekleyeceksin uygun bir zamanda gideceğiz oralara

Ama bir şey varki o trenlerde her şey çok karışık

Gördüklerin karşında tüylerin diken diken olacaktır orda

Bazen acıyacak bazende daha çok yapın diyeceksin

Çünkü sen şairsin yüreğin dayanmaz bu gördüklerine

Kendi kendime başladım düşünmeye

Demekki öldüğümüzdede işler karışık olacak bu yerlerde

Dışarıdan sesler halen devam etmekteydi koridarlar tıklım tıklım

Neyzen Tevfik birden kompartmanın kapısında beliri verdi

Nazım Nazım  kim geliyor biliyormusun? diye sesleniyordu

Kim? dedi Nazım abi

Atilla İlhan Atilla İlhan senin yüzünden hapislere düşen çoçuk

Gelsin bakalım yiğidimiz kuçaklayalım hoş geldin diye.

Ha evlat seni hitlerin bulunduğu trene sokup onu sana gösterirsem 

Ne yapacaksın? 

Onun ümüğünü sıkacağım.

Bak evlat zaten ölmüş serefiz sen onun ümüğünü sıkamazsın

Ancak ona öyle bir bakmalısın ki kendi halinde yaşayan 

Ruhu dahi korksun bakışlarından her kötüye öyle bakmalı

Bakmalısında sadece bizim ülkenimiz için değil sana gerçekten dost olan

Halkların kardeşliğine yardımcı olacaksın bakışlarınla hem öyle bir bakmalısın ki hepsinin ödü kopsun ruhlarının içinde yalnızca senle gerçekten kardeşçe

Can olmuş halklara güzel ve sefkatli bakacaksın.

Nazım abi askeri trende kimler var anlatırmısın yok anlatmakla olmaz 

Görmelisin,göreceksinde.

Yüksek sesle Bağırıyorlardı Atilla Atila Çok Yaşa diye 

Gelip kompartmanın kapısı önünde durdular Nazım abiye bakıyordu

Atilla abi,Nazım abi ellerini arkaşında birleştirmiş suratına bakıyordu

Atilla ilhanın birden kollarını açtı gel dedi gel Halkların adamı gel

Gel devrimcilerin hası gel gel bir seni koklayayım hasretim,yoldaşım

Beni bir ağlamaktı aldı karşılarında Atilla İlhan Kim bu? ağlayan arkadaş diye 

Soruyordu Nazım abiye

Geleceğin medarı iftiharı diyor Atilla İlhan abiye

Dışarı çıktım bir siğara yaktım derinden öyle bir çektim ki

Ciğerlerim Yandı öksürdüm durdum.

O ara Atilla İlhan Nazım abiye şirini okuyordu

bana bir şimşek çak 

ortalık fena karanlık 

yüreğim örtülüyor 

ağır bir dalgınlığa genişliyorum 

durmadan değişen o mevsimde 

dağlarda kalın 

omuz omuza bulutlar 

çok fena kalabalık 

ellerim çıplak 

bana bir şimşek çak 

kötü bir tuzaktayım 

bilmem ne yapsak 

aklımda fikrimde onlar 

yaşlı ve genç 

erkek ve kadın 

korkularıma tutsak 

bana bir şimşek çak 

içim içime sığmıyor artık 

vahim bir çağrışımdan 

daha vahimine atlamaktayım 

bana bir şimşek çak 

belki fena halde 

yanılmaktayım 

o ince kız çocuğu 

gün doğmadan her sabah 

bir hapisaneden bir nezarethaneye 

kelepçeli götürülüyor 

dudakları titrek 

gözlerinde buğu 

bilmem ki nasıl anlatayım 

bağışlanmaz suçu dünyayı sevmek 

bir de o 

adını bile bilmediği 

kıvırcık saçlı''devrimci''öğrenciyi 

fakülte kapısında vurulmuş 

yağmurun altında 

çıplak 

bana bir şimşek çak 

çok yanlış anlaşılmaktayım 

hesabım yanlış bir mahkemede görülüyor 

içimdeki zemberek 

boşandı boşanacak 

yaşamak mı gerek 

yoksa unutmak mı 

şaşırmaktayım 

galiyef yoldaş ne olacak 

galiyef yoldaş sibirya sürgünü 

sanki yalın bir bıçak 

kayarak 

bir kırlangıç hızıyla 

bulutların arasından 

karanlığın böğrüne saplanacak 

galiyef yoldaş ne olacak 

galiyef yoldaş sibirya sürgünü 

elinde bir mektup eski yazıyla 

artık yüzünü bile unuttuğu 

karısından 

burnunda sadece kokusu var 

ilkbahar kadar müşfik 

sonbahar kadar yumuşak 

galiyef yoldaş ne olacak 

avrasyada hala mazlumların uğultusu 

kısa bozkır atlarının nallarından 

gizli kıvılcımlar ki etrafa saçılıyor 

azadlık mermileridir 

çekirdekleri çelik 

cehennem gibi sıcak 

bana bir şimşek çak 

sala veriliyor görünmez minarelerden 

İzmir de istirdat ı yaşamaktayım 

bir yangın soluğu sokak içlerinden 

kordonboyunda muzaffer atlılar 

fahrettin paşanın süvarisi 

bana bir şimşek çak 

yolumu aydınlatacak 

gazi''nin gözlerinden 

mavi bir şimşek 

kuva-yı milliye mavisi 

aynı emaneti taşımaktayım 

''hürriyet ve istiklal benim karakterimdir'' 

çünkü hain sinsi ve korkak 

aynı düşmana karşı 

savaşmaktayım', 'Gördüklerim ne güzeldi  Hepsi bir arada birlikte yolculukta  Ben  neden aralarındaydım ki?  Nazım Hikmet Ran Oturmuş kompartmanda konuşuyord...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":531,"source_url":"https://www.antoloji.com/hepsi-ayni-trende-benle-beraber-ruya-1-2-3-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Dört Ayrılıktır', 'bir-ask-dort-ayriliktir-yusuf-degirmenci-j70x2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kınsız bir yürek taşırdım, 

cezasını düşünmediğim paylaşımlara

kıpık gözlü bakarlardı, 

korkmaz, ürkmezdim, 

geceye sığınmış hainlerden

öteden beri,

ötücü kuşların seslerini işitirdim

her gelişin, yeni seslerin kanatlanmasıydı

aniden bir öpücük kondururdum

kuşların sıkıntısı, övgüsüne boğardı aşkı

hiç soru sormadan gözlerine bakmak isterdim

kaç kıyıcı el tanıdık seninle ey sevgili,

bu sahipsiz görünümlü sokakların tozunda

kıymetini bildik mi, 

yarınlara karanfil kokusunu taşıyan kuşların? 

her gece, 

ayı gösteren parmaklarımızın gücü,

koparıp almasını bilirken karanlıktan,

boğulan gülücükleri,

suratımıza hapşıran rüzgarın arsızlığında,

kaç defa seviştik karanlığı yırtarak! 

çivi çiviyi söker derler ama

kin sokamam ayrılıklarımın yakınına

aldatmadım seni, ve ötekileri…

olduğun gibi sevdim

sevilmeyi de öyle bekledim, 

düşüncelerimden ihaneti uzaklaştırarak

ahh güzel kadınlarım…

bir aşk dört ayrılıktır; 

gezinerek yenisine çoğalmalarda.

Lozan, 27 01 2006', 'Kınsız bir yürek taşırdım,  cezasını düşünmediğim paylaşımlara kıpık gözlü bakarlardı,  korkmaz, ürkmezdim,  geceye sığınmış hainlerden öted...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Değirmenci']::text[], 8.5, '{"poet":"Yusuf Değirmenci","poet_slug":"yusuf-degirmenci","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-ask-dort-ayriliktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alma sakın', 'alma-sakin-abdullah-gencay-bpbzg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Susmuşken  gecenin  ortasında,   her şey

Donarım   sensizliğin   soğuğunda

Düşünürüm     geçmiş     zamanı

Dalarım  karanlığa  izin  almadan  ağır ağır

Takip  ederim  aheste  çekilen  küreklerle

Gecenin   içindeki   sessizliği

Zaman  zaman  buğulanır  gözlerim

Titrek,  ürkek   yüreğime   inat

Gelecekmişsin,   diye  haber   gelir

Yorgunum,  kırılır  kolum kanadım

Yeniden  sarmak  değil,  görmektir   amacım

Sen,    sende    kalsın

Dokunma...! 

Bende  kalanı  alma  sakın', 'Susmuşken  gecenin  ortasında,   her şey Donarım   sensizliğin   soğuğunda Düşünürüm     geçmiş     zamanı Dalarım  karanlığa  izin  almadan...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/alma-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Et kutusu', 'et-kutusu-abdulvahap-ates-gylog', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'içim dökülse yere

dertsize dert bulaşır

şu küçük et kutusu

dünyayı nasıl taşır', 'içim dökülse yere dertsize dert bulaşır şu küçük et kutusu dünyayı nasıl taşır...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/et-kutusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimin Ceplerinde Gökkuşağı', 'yuregimin-ceplerinde-gokkusagi-kamil-aydemir-ra6gg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sararak kafkasların kokusuna

karadeniz’den yakamoz getirdim sana

heder olan yıllarını veremem ama

sevgi tarlası yüreğimi koymaya hazırım avucuna

uzak sevmelerden hasrettir payıma düşen

bunun için

seven yüreğim perişan

gözlerin gecenin karanlığını yırtan

           en parlak yıldız

az sonra hasret dalgalarının yutacağı

ve duyarsız toplumun kısa sürede unutacağı

ıssız bir adayım ben sensiz

hayat ertelenmeye gelmez kalbimin çiçeği

yüreğinle elele verdik biz

yönümüz sevgi

yarınlarımız mutluluk

benim için yüreğine sevgiler doku

inan ki yer vermedim hüzüne

yaslan mavi gökyüzüne

sana yazdığım aşk mektuplarını oku

senin saflığın gibi beyaz

benim sevgim gibi kırmızı

güllerin yaprağından

hatırlar mısın beni

geçerken sevda türkülerinin yanından

bulunca sol yanını dindi içimde yağan yağmur

yüreğimin ceplerinde gökkuşağı

gökkuşağının her renginden 

sana olan sevgim salkar hayata

binde gel şiirimin dizelerinde saklı beyaz ata

bir bilsen nasıl acıtırsın beni

acılarıma iliştikçe yırtılır günlerin etekleri

günlerin yırtık eteklerinden dökülür çocukların sevinçleri

beni suçlu tutamasın yüreğinin yarasından

ne gülüşünü çaldım serçe yavrusunun gagasından

ne de martının çığlıklarında saklambaç oynadım

aşkı da hiç ağlatmadım

ağlatmadım hiç bir çocuğu çiçeği

oysa şimdi

seni sevdiğim için sensizliğe sürgünüm

gecenin arsız ayazında üşüyorum

gülüşlerini ört üstüme

yalnızlığımın çukuruna düştüm düşüyorum

ne olursun sevginle tut yüreğimden

idam  mahkümünün özgürlüğüne kavuşması gibi

sabaha varayım

varayım da dudaklarının kıvrımından bir öpücük alayım

ve hayta hayatın inadına

sana ertelediğin düşlerini

aradığın mutlulukları vereyim', 'sararak kafkasların kokusuna karadeniz’den yakamoz getirdim sana heder olan yıllarını veremem ama sevgi tarlası yüreğimi koymaya hazırım avu...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/yuregimin-ceplerinde-gokkusagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncinmiş Aşklar Şiiri', 'i-ncinmis-asklar-siiri-yusuf-degirmenci-zswc9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir özlem şiiri adın

dünden, yarınıma beste

ne zaman mırıldansam,

karşımda gülen gözlerin…

hercai yaprağındaydı öpüşlerin

dokunuşunla baş kaldıran baharımdın

kaç gün oldu saymadım 

sırtlayarak hırsını, 

ardına bakmadan uzaklaştın

düşündüm de! 

ayrılık neden kolay bu şiirde? 

el ele gezerdik hırçınlığın bağrında 

soluklanırdık her menekşe bahçesinde

yanaklarında bir buse gülüşürdü

bakardın yüzüme sıcacık yüreğinle

ve seni seviyorum derdin 

oyy bir de canım demen yok muydu? 

ölürdüm,

dudaklarının arasından soluduğum nefesle

gittin ardı sıra bilinmez duygularda

kayıbına ağlıyor harıl harıl çiçekler

ahh şu hain ayrılıklar

nasıl da doğuruyor yalnızlıklar

şimdi soruyorum sana

hangi bahçenin menekşeleri soldu dersin? 

artık kolay değil arkandan bağırmak

gitti mi gider aşk,

yakalayamazsın derdin

unutmak da kolay değil ya 

alışır mı insan! 

yarın, 

kimbilir belki de bugün

hadi gel, 

mırıldan kulağıma diyebilecek miyim? 

sevgilim, 

aşkı ne zaman yalanlardan sıyıracağız? 

Lozan, 09 07 2005', 'Bir özlem şiiri adın dünden, yarınıma beste ne zaman mırıldansam, karşımda gülen gözlerin… hercai yaprağındaydı öpüşlerin dokunuşunla baş ka...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Değirmenci']::text[], 8.5, '{"poet":"Yusuf Değirmenci","poet_slug":"yusuf-degirmenci","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/incinmis-asklar-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık', 'i-nsanlik-abdullah-gencay-bjcke', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsanları menfaatler kelepçelemiş

Zindanları, ihanetle kardeş

Sözleri yalanla sözleşmiş, çirkinleşmiş

Akıl ve mantık  verilen tek,  canlıya

İnsanlık soğumuş, çürümüş

Güzel olana   bile,  şüphe girmiş

Eldekini   kaybetmemek için 

İnsan insanı  kullanırken ne acı 

Hikayelerde, romanlarda kalmış

Dürüstlük, anlayış ve adalet

Eskiden meydanlarda satılan insanlık 

Bu çağda sinsice, adı konmadan yaşanır olmuş', 'İnsanları menfaatler kelepçelemiş Zindanları, ihanetle kardeş Sözleri yalanla sözleşmiş, çirkinleşmiş Akıl ve mantık  verilen tek,  canlıya ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insanlik-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık unutamam', 'artik-unutamam-abdullah-gencay-n7bfe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dokunmasaydım beyaz bulut gibi yüreğine

Belki o zaman dolu yağmazdı üzerime

Benden sana  kalan,

Kötü dediğin, ben ve bir avuç anı

Bozulmuş siyah geceler belki de

Senden bana kalan beynime kare kare

Nakış gibi  işlenmiş  sözlerin ve gözlerin

Birde,   bıraktığın güzel kokun

Sana sonsuz teşekkür ederim

Ama, keşke hiç görmeseydim  seni

Dokunmasaydım ellerine, yüzüne

Dertleşmeseydim saatlerce

Ne kadar rahat olurdum kim bilir

Belki,  zevk alırdım yaşamaktan

Acı biber gibisin,  baktığında güzel

Dokunduğun da acısı ellerini, yüzünü yakan

Yeşerecek toprağın gönlüne göre olsun

Sen büyüdükçe unutacaksın ! 

Ben büyüdüm artık unutamam', 'Dokunmasaydım beyaz bulut gibi yüreğine Belki o zaman dolu yağmazdı üzerime Benden sana  kalan, Kötü dediğin, ben ve bir avuç anı Bozulmuş s...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/artik-unutamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli olan aşkımız....', 'gizli-olan-askimiz-ercan-akbay-xl4l1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gizli olan aşkımız

   Artık dillere düştü

   Böyle miydi yazımız

   Kader bize de küstü..

   Bizi bizden aldılar

   Kuşlar hüzünle öttü

   Bir sevdayı yıktılar

   Kader bize de küstü..

   Yasak olan aşkımız

   Kalbimiz de hep tüttü

   Çıkmadı hiç rüyamız

   Kader bize de küstü...

                 6.6.1992

                 İsmail Demirkıran tarafından -BUSELİK-

                 makamında bestelenmiştir.

                 T.R.T  Repertuarındadır.', 'Gizli olan aşkımız    Artık dillere düştü    Böyle miydi yazımız    Kader bize de küstü..    Bizi bizden aldılar    Kuşlar hüzünle öttü    B...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gizli-olan-askimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalabalıkta yalnızlık', 'kalabalikta-yalnizlik-abdullah-gencay-iv8z8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendimi kafesler içine aldım

Buzdan, duvarlar ördüm çepeçevre

Bağlandım geceye ve sessizliğe

Gün batımında aradım huzuru

Dağda tek başına olmaya,  gerek yok

Kalabalıkta tekim, tek başına, kendi içinde

Kaplumbağa misali kendi kabuğunda

Dolunayda, ararım ben  yalnızlığı

Dökülmüyor göz yaşlarım mehtapta bile

Kuruyan pınarlar akmıyor, içim kan ağlasa da

Geriye, eskiye dönülmüyor,  çizgiden sonra

Kendimi, kendim attım dipsiz kuyuya

İstesem de çıkaramıyorum, tek başıma', 'Kendimi kafesler içine aldım Buzdan, duvarlar ördüm çepeçevre Bağlandım geceye ve sessizliğe Gün batımında aradım huzuru Dağda tek başına ol...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gençay']::text[], 8.5, '{"poet":"Abdullah Gençay","poet_slug":"abdullah-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kalabalikta-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki çift soru', 'i-ki-cift-soru-derya-penbe-zrvsn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uykusuz gecelere mahkûm olmuş gözlerim

Sabahlarayakındır sorgu dolu gecelerim; 

Pencere köşesinde bir elimde sigaram, yanı başımda soğuk çayım.

Başucunda yalnızlığımla sana seslenirim bilinmedik uzaklara; 

Sende benim gibi sorgusuz gecelerin özleminde olanlardan mısın, bu gece? 

Yapayalnız tek başına kendini sorgulayanlardan mısın? derken! 

Söylenirim kendi kendime! 

Ey fani dünya neler geldi geçti senden,

Bir asır değil bin asır yaşandı sende.

Nehirler, hazanlar, yıldızlar, ay şahit oldu sırlarına; 

Gün geldi kaç kışın ardından bahar getirdin! 

Sardın sarmaladın yaralarını, yinede sakladın emanetlerini! 

İnsanoğlu ise emeklerine ihanetlerle ve sahtekârlıkla cevap vermedi mi? 

Bir birimizi atmadık mı? Kurtlar sofrasına! 

İşte ben her gecenin sonunda bu soruları sordum kendime.

En kötüsü de içimizdeki güzellikleri tamamen yok etmedik mi? 

Hiç bir sebep yokken neydi, bizleri bu kadar çaresizliğe iten sebeb neydi? 

Bizler rabbimin en özel kulları iken tomurcuklar kadar bile mücadele

verebildik mi? 

Ve biz seninle var olduk seninle de yok olmayacak mıyız? 

Sadece şimdilik erken ayrılanlar kucağında uyumayacak mı? 

Değer mi bu kadar kırmaya, kırılmaya? 

Bu yalan dediğimiz dünyanın oyunlarında kumar oynamaya? 

Ben her gece kendime bu soruları sorarken! 

Şimdi sıra sormayanlar sorsun kendilerine, kalplerindeki pasları silmek için! 

Ne zaman kendimi sorgusuz, huzurlu gecelere mahkûm, bırakırsam! 

O geceler içinde yazacağım sorgusuz gecelere umutlarla dolu şiirlerimi anlatacağım; 

Şimdi affedin bu uslu bazende  yaramaz kızı......

                                                                       31 şubat 2006 

                                                                             00:10', 'Uykusuz gecelere mahkûm olmuş gözlerim Sabahlarayakındır sorgu dolu gecelerim;  Pencere köşesinde bir elimde sigaram, yanı başımda soğuk çay...', ARRAY['Türk Edebiyatı','Şiir','Derya Penbe']::text[], 8.5, '{"poet":"Derya Penbe","poet_slug":"derya-penbe","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/iki-cift-soru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ayrılık Ki Sonu Yok', 'bir-ayrilik-ki-sonu-yok-sultan-i-nan-3aibp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'düşüyorum her çırpınışta beynin başka uçurumlarına 

katıyorum her kuşku sonrası büyüyen ura yenisini 

sel olup yürüyor damarlarımdan rahmime çığlık çığlık 

acılar döllüyor şimdi ayrılığın spermlerini 

atıyorum hasreti vurur gibi 

vuruyorum aşkı ortasından alnın 

boğuyorum bir yudumluk alkol kusmalarımda küfürle 

beynimin olur olmaz kurgularında 

gemiyim....... batıyorum apansız 

yahut yıldız....... 

çatladı çatlayacak 

şahdamarıma elle 

yürü özsuyuma 

tut beni 

tut.. 

kayıyorum gözlerinden yerlere 

kuslar konuyor kuşlar havalanıyor gönlümün bahcelerinden 

ben dalsız yaprak gibi duruyorum

sen yanmış orman gibi bakıyorsun yüzüme 

ey kaçamak bakışlarda yüzüme dolan sevinç 

neden alnıma hep dolambaçlı eser bu serinlik 

neden şak diye yapışmaz 

bütün hesaplarda bozulası oyun 

sabah oldu 

ayılıyorum 

artık gitt 

gecem ağır 

gecem sonsuz 

gecede kahır 

sabahlarımda bile bağır bağır 

uyanıyorum

BENBAHAR1111', 'düşüyorum her çırpınışta beynin başka uçurumlarına  katıyorum her kuşku sonrası büyüyen ura yenisini  sel olup yürüyor damarlarımdan rahmime...', ARRAY['Türk Edebiyatı','Şiir','Sultan İnan']::text[], 8.5, '{"poet":"Sultan İnan","poet_slug":"sultan-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-ayrilik-ki-sonu-yok-e-o-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonki', 'sonki-ali-cengiz-turan-21hgs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Amansız yarış,hedefe varış sonki! 

Dünya dönüyor,giden gelmiyor....

Zaman beşik olmuş,rüzgar ninni söylüyor.

İnsanlar bu dünyada mışıl mışıl uyuyor,

Uyanış Sonki.

Gelenleri görüyoruz,gidenleri görüyoruz,

Yine de inatla uyuyoruz,

Uyanış Sonki.

Hayat uykusu,insanların tutkusu,

Yıllar geçiyor,hayat bitiyor,

Hedefe varış Sonki...! ! ! ! !', 'Amansız yarış,hedefe varış sonki!  Dünya dönüyor,giden gelmiyor.... Zaman beşik olmuş,rüzgar ninni söylüyor. İnsanlar bu dünyada mışıl mışıl...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sonki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derlerse Ki Seni Unutmuş', 'derlerse-ki-seni-unutmus-umran-aldic-4fvoe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Derlerse ki seni unutmuş.

Yarından umutluymuş.

Aradığı aslında,  buymuş.

Sakın inanma.

Derlerse ki hep ağlıyormuş,

Gözleri yaş doluymuş.

Anılarla avunuyormuş.

Hiç kuşkulanma.', 'Derlerse ki seni unutmuş. Yarından umutluymuş. Aradığı aslında,  buymuş. Sakın inanma. Derlerse ki hep ağlıyormuş, Gözleri yaş doluymuş. Anı...', ARRAY['Türk Edebiyatı','Şiir','Ümran Aldıç']::text[], 8.5, '{"poet":"Ümran Aldıç","poet_slug":"umran-aldic","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/derlerse-ki-seni-unutmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Osman Bey', 'osman-bey-metin-onal-mengusoglu-299q8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kadar mutlusunuz şimdi kimbilir

ada''da üç aylık evinizin geniş balkonu

bir yandan denize bakar karanlık, sakin

müzikal bir hışırtı içinde sadece.

bir yandan kalabalık gökyüzüne açılır

insan ruhunu pervasız kılan uçsuzluğa.

anımsayın,

gökyüzü yerden daha tenhadır artık

öyle günlere geldikki düşünmek bile

mekanikleşti.

madeni pürüzlere benzedi insan sesleri.

dün sağanak bir facia iken zeytinburnu''nda 

hatırlayın,

kadıköy

olağanüstü bir yazgünü yaşamıştı azabiçinde

bizim küçük kentimizde osman bey oysa

faytonları daha yeni kaldırdı belediye

ama sokakları dolduran kısrak kokusu

hala asidik sarhoşluğuyla

birer il yarasıdır yüzlerinde insanımızın.

kirazlar yüz tutmuşsa kurtlanmaya

başlamıştır kaysılar yarılmaya şekerden.

babam 

söylemiştim size

demiryollarından emekli eski bir memur

sabah namazında uyanır

okşar uyuyan torunlarının saçlarını

ak sakalından sızarken abdest suları

the ekonomist''i okumamıştır hayatında

fizibilite raporlarından da yoktur haberi

hakkından gelmeyi bilmiştir ama

küçücük bütçesiyle 

yedi çocuklu bir ailenin

kendi namusu ve yağıyla kavrulmasının.

kimsenin malında gözü olmadan

tok gözlü büyütmüştür çocuklarını.

osman bey

işte ben

sessizliğimi kimi zaman

budapeşte''de gördüğünüz

şarklı heykele benzetebilirsiniz

yahut venedik''te kırık bir sandalda

taze istiridyeler satan ihtiyara

heybetim oysa saklıdır içimde

modern asfaltlara tahammülsüz

çıplak dağları gibi anadolu''nun

yazları kayalar yuvarlayarak

kışları çığlar devirip

tarifsiz heyelanlarla sarsarız yolcuları

hepten meziyyetsiz değiliz; anlatabilsem

ah, bir anlatabilsem osman bey,

paradan puldan yana yoksulluğumuzu

hadi tevekkülle karşılayalım

fikirde ferasette ustalığımız

taa inkılaplardan bu yana

gömülüp kalmıştır can damarımızda.

çoğu zincirli bu gün insanların belki

çoğu köle...

ama onların bileklerinde

biraz zorlayınca kırılacak

görülebilen demir parçalerı var

bizim boyunlarımızda oysa

en gizli kuvvetleriyle zulmün

görünmez esaret kelepçeleri

farkedilmez prangalar

dualarında

rahat döşek ölümü isterdi anam

o günden bu yana osman bey

buldum bazı yenilgilerimizin kaynağını

bu asyalı tevekkülün

bu şarkkarı korkunun temelinde

sizin azıcık itibar ettiğiniz mistisizim var.

batılı zaten, anlıyorum

yaşamında materyalist 

hülyalarında mistiktir.

bizimkilerse size

tersinden benzemeğe çalıimışlar anlaşılan

yahut böyle olmasını siz istediniz.

bilmiyorum osman bey bilmiyorum

öyle derinden bir fesat tohumu ekilmiş ki arza

ne sizin diazemle rahatlattığınız ömür

ne asyalının afyonkeş felsefesi

yüzünü güldürüyor evrenin

dünyanın çivisi kopmuş, derler ya

bu işin dimağında bir bozukluk var.

boşaltıp beynimizin cürufatını

unutalım ezbere bildiğimiz kelimeleri

fiyatları ayarlayan borsadan

faizin nirengi noktasında dikilen gökdelenlere

tabiatı yasaklayan şehirden

adım başına fucur fışkıran çarşılara kadar

herşeyimizi

bütün eski bildiklerimizi unutalım

kısacası

insana benzetmek için papağanlaştırılmış dünyamızı

osman bey osman bey

yalnız ellerimiz kalsın açıkta

sımsıkı tutuşalım el ele

dilimizde tek marş, besmele

kur''an''dan başlayalım.', 'Ne kadar mutlusunuz şimdi kimbilir ada''da üç aylık evinizin geniş balkonu bir yandan denize bakar karanlık, sakin müzikal bir hışırtı içinde...', ARRAY['Türk Edebiyatı','Şiir','Metin Önal Mengüşoğlu']::text[], 8.5, '{"poet":"Metin Önal Mengüşoğlu","poet_slug":"metin-onal-mengusoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":100,"source_url":"https://www.antoloji.com/osman-bey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin?', 'nerdesin-umran-aldic-ouxqw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fırtınalar kopuyor yüreğimde 

Nerdesin? 

Çığlık çığlığa bağırıyor çıkmayan sesim

Nerdesin? 

Kurudu sanmıştım yüreğim

Çağlayanlar akıyormuş farketmedim

Günbe gün taşımışım içimde

Nerdesin? 

Sıtma tutmuş gibi bütün vucudum

Hasretin le derbeder kavrulmuşum.

Sensizliğin dikenli yollarında kaybolmuşum.

Nerdesin? 

Duyarmısın? bağırsam, ağlasam,

Yalvarsam,  gel desem.....gelsen...

Olabilir mi? dönermiyiz o günlere? 

Nerdesin? 

Olmaz ki olamaz ki 

Ne sen eski sen, ne ben eski ben.

Kapatmışım gönül hapishaneme

İşte böyle,  özleyince deliler gibi

Sorarım kendi kendime

Nerdesin?', 'Fırtınalar kopuyor yüreğimde  Nerdesin?  Çığlık çığlığa bağırıyor çıkmayan sesim Nerdesin?  Kurudu sanmıştım yüreğim Çağlayanlar akıyormuş f...', ARRAY['Türk Edebiyatı','Şiir','Ümran Aldıç']::text[], 8.5, '{"poet":"Ümran Aldıç","poet_slug":"umran-aldic","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/nerdesin-148-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla''ma', 'leyla-ma-hasan-dogan-ulj61', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kovuldun bu gönülden.

Çalma kapısını bir daha,

Bakma penceresinden,

Kapalı kalacak ebedi sabaha.', 'Kovuldun bu gönülden. Çalma kapısını bir daha, Bakma penceresinden, Kapalı kalacak ebedi sabaha....', ARRAY['Türk Edebiyatı','Şiir','Hasan Doğan']::text[], 8.5, '{"poet":"Hasan Doğan","poet_slug":"hasan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/leyla-ma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ha! gayret...', 'ha-gayret-reyhan-tataroglu-dkwm1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'her zaman ki mekanımdan çıktım

              yine saat sabahın beşi, sallanırken...

              üç beş kedi köpek paylaşamıyorlardı bir leşi

              paylaşmak ne güzel,paylaşmamak ise ortada

              ben ise tam ortasında,orta yerinde

              hızlı hızlı ayak sesleri duyar oldum

              güzlerimi açamıyorum ama kulaklarım irkildi

              birden bir karartı önüme dikildi

             ''''yardım edeyim mi beyefendi''''dedi

              bu kimdi,beyefendi kimdi,nerden çıktı şimdi

              itiraza kalmadı mecalim

              bu merette bazen çok zalim oluyor be çok zalim

              yine dayandı bir omuza,aaah! halim,aaah! halim 

              yudu yüzümü küçük bir şadırvanda

              benim aklım hala mekandaki loş tavanda...

              ortalığı sardı bir nida, bir feryat

              yine aynı ses,yine aynı ses heyhat! 

              kulağımı deldi geçti,yüreğimi yardı

              bana seslenen bu ses en son ayardı

              izin aldı benden karartı,geçti safına

              yine ortada kaldım,yalnızlığın insafına

              birgün bende iki omuzu omuzlar mıyım derken...

              eskiden kalma beleşçiler,leşçiler birikti etrafıma', 'her zaman ki mekanımdan çıktım               yine saat sabahın beşi, sallanırken...               üç beş kedi köpek paylaşamıyorlardı bir le...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ha-gayret-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kenzi Mahfidir', 'bir-kenzi-mahfidir-mesut-yokus-j8nhp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kenzi mahfidir 

Sevdan yüreğimde

Eller uzanmamış,

Gözler değmemiş,

Sözler söylenmemiş.

Hayal suret dolaşır durur

Mahzeninde kalbimin.

Bakışlarında

Ne huzur, ne gurur

Değmeyin ağlıyordur.

-umutsuz vaka-

ne fiyaka, ne caka

gözlerinin içine baka baka 

siz gidin 

o kalıyordur………

                       Mesut Yokuş -2001-', 'Bir kenzi mahfidir  Sevdan yüreğimde Eller uzanmamış, Gözler değmemiş, Sözler söylenmemiş. Hayal suret dolaşır durur Mahzeninde kalbimin. Ba...', ARRAY['Türk Edebiyatı','Şiir','Mesut Yokuş']::text[], 8.5, '{"poet":"Mesut Yokuş","poet_slug":"mesut-yokus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-kenzi-mahfidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darağacı', 'daragaci-mesut-yokus-xql40', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dalında kurumuş sarı yaprak gibi 

Durmuş,solmuşum kader ağacında 

Ömrümü noktalayacak yeli

Bekliyorum zaman kıskacında 

Ne ilaçlar yarama melhem,

Ne gülüşler gönlüme meltem

Ömrümü bohçama koyup gelsem

Kavuşsam sana ölüm miracında

Elini bırakmak istemiyor elim

Şaşkına uğramış aklı selimim 

Aşkına pürsürur olup teslim

Bıraksam resmimi dar ağacında 

                                    -1998-', 'Dalında kurumuş sarı yaprak gibi  Durmuş,solmuşum kader ağacında  Ömrümü noktalayacak yeli Bekliyorum zaman kıskacında  Ne ilaçlar yarama me...', ARRAY['Türk Edebiyatı','Şiir','Mesut Yokuş']::text[], 8.5, '{"poet":"Mesut Yokuş","poet_slug":"mesut-yokus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/daragaci-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi İstanbul', 'simdi-i-stanbul-murat-sinan-ayhan-m598r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi İstanbul''a yaşlı gözlerle bakıyorum

Umursamıyorum artık karanlığın ardından gelen güneşi

Ve dalıp gitmiyorum uzaklara

Giden sevgilinin ardından

Şimdi İstanbula yaşlı gözlerle bakıyorum 

Unutamıyorum yaşanmamış yaşamlarda kalan anıları

Ve gençliğimi arıyorum her satırda

Yok oluşumu düşünüp 

Var olmaya çalışıyorum', 'Şimdi İstanbul''a yaşlı gözlerle bakıyorum Umursamıyorum artık karanlığın ardından gelen güneşi Ve dalıp gitmiyorum uzaklara Giden sevgilinin...', ARRAY['Türk Edebiyatı','Şiir','Murat Sinan Ayhan']::text[], 8.5, '{"poet":"Murat Sinan Ayhan","poet_slug":"murat-sinan-ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/simdi-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölsem de çok ana doğurur beni', 'olsem-de-cok-ana-dogurur-beni-i-lhami-arslantas-3z14r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimine altınım, kimine pulum,

kimi ateşlerde kavurur beni.

Kimine libasım, kimine çulum, 

Kimi talaz gibi savurur beni.

Acıyım, feryadım arşa ererim,

Halılara desen olup girerim,

Koyun olup kuzum diye melerim,

Kimi şişe takıp evirir beni.

Dünyanın çarkına düşünce serim,

Acı feryat ile bühtan ederim,

Ben insan içinde ararken yerim,

Kimi yarı yoldan çevirir beni.

Ben ozanım canı halka adadım,

Her haklı davada önde bir adım,

Ozan diyarından İlhami adım,

Ölsem de çok ana doğurur beni,', 'Kimine altınım, kimine pulum, kimi ateşlerde kavurur beni. Kimine libasım, kimine çulum,  Kimi talaz gibi savurur beni. Acıyım, feryadım arş...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olsem-de-cok-ana-dogurur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Güle Güle', 'git-gule-gule-sevinc-kavuk-un1e7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu son kararım diyorsun 

-Öyle veya böyle- Geçmiş olsun ikimize

Karara saygı duyarım düşmem peşine

Kararsızlığı bürünmek hiç benden bekleme 

Git güle güle! Ve kal gönlünce! 

Olacaksa zaman, kader, beden nedeniyle de 

Her sabah bu bir veda ihtimali

Sükuta boğar içimi, doğallığıyla da oluşan çırpınışı

Sessizce arkadaş ederim 

Çaresizlikte de saygıyla sabrım, metanetim, sevgimi

Ya o başlayacak hasretimi ne yapacağım peki? 

Sen aldırma buna, yolun açık, mekanın cennet olsun...

Git güle güle! Diyeceğim rahmet dileyerek... 

01.02.2006

Çarşamba 03.30', 'Bu son kararım diyorsun  -Öyle veya böyle- Geçmiş olsun ikimize Karara saygı duyarım düşmem peşine Kararsızlığı bürünmek hiç benden bekleme ...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/git-gule-gule-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsinden zevk alır seven gönüller', 'hepsinden-zevk-alir-seven-gonuller-halil-colak-x9rbm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönül sazı düşmesinde elinden

Sevenin sevdiği düşmez dilinden

Yılın oniki ay dört mevsiminden

Hepsinden zevk alır seven gönüller

Halil Çolak 1.2.2006 Ankara', 'Gönül sazı düşmesinde elinden Sevenin sevdiği düşmez dilinden Yılın oniki ay dört mevsiminden Hepsinden zevk alır seven gönüller Halil Çolak...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hepsinden-zevk-alir-seven-gonuller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek Olmalı', 'melek-olmali-mehmet-sait-akkus-u1jxp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni benden sorsalar

Nasıl biri deseler

Adresini isteseler

Vermem bile dövseler

Oturup şöyle derim

Akıllı biri derim

İyi birisi derim

Kendini taşır derim

Bence melek olmalı

Adı melek konmalı

Onun merhamet eli

Tutulup öpülmeli

Onun gibi bulunmaz

Pazarlarda satılmaz

Para ile alınmaz

Kıymeti hiç sorulmaz

Dost delisi gönülden

Sever daim yürekten

Yeri gelir erkekten

Korkulur bu yürekten

Sevimli ve sevecen

Onu görmüştüm geçen

Görsen hemen öpecen

Bak dene istiyorsan

Arada bir kızınca

Şöyle bir yan bakınca

Hele fırça atınca

Olur bu kadar anca

Onun ile el ele

Varmak lazım güzele

Bu günden ta ezele

Kalmaz artık mesele

Pamuk gibi yüreği

Demir gibi bileği

Allahtan tek dileği

Bağıslasın alemi', 'Seni benden sorsalar Nasıl biri deseler Adresini isteseler Vermem bile dövseler Oturup şöyle derim Akıllı biri derim İyi birisi derim Kendin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/melek-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyi Seven Bilir', 'sevmeyi-seven-bilir-derin-oger-23u5h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'birşeyler karalayıp elveda desem

seni sevmeyi seven kalbim küser

acı bir duman bürür bakışlarımı

yaş gözü boğar göle nilüfer küser

yalnız güneşle gülmez bahçeler

dün sararan yaprak bugün dala küser

değişir mevsimler yırtılır yıllar

yüze hüzün sokulur gülüş dudağa küser

bir hışım karşıma geçer vedalar

içim cız eder zehre zemberek küser

varsın nasip hayal meyal hatırlasın beni

birgün yorgun ciğerlerime hava küser', 'birşeyler karalayıp elveda desem seni sevmeyi seven kalbim küser acı bir duman bürür bakışlarımı yaş gözü boğar göle nilüfer küser yalnız gü...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmeyi-seven-bilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz akşamlar beni hüzün’e boğuyor', 'sensiz-aksamlar-beni-huzun-e-boguyor-halil-colak-mxlwi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensiz akşamlar beni  hüzün’e boğuyor

Andıkça seni yüreğimde için,için yanıyor

Her yerde gözlerimde  sevdiğim seni arıyor

Gönül bahçemde sensiz güllerimde soluyor 

Halil Çolak 1.2.2006 Ankara', 'Sensiz akşamlar beni  hüzün’e boğuyor Andıkça seni yüreğimde için,için yanıyor Her yerde gözlerimde  sevdiğim seni arıyor Gönül bahçemde sen...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sensiz-aksamlar-beni-huzun-e-boguyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana ne', 'bana-ne-mikdat-bal-u0iti', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya yeşil güzelmiş

Sefasından bana ne

Sadakati ezelmiş

Vefasından bana ne

Dünyaya göz açarken

Gördüm onu kaçarken

Yalan ümit saçarken

Safasından bana ne

Hem döner hem döndürür

Ne ocaklar söndürür

Akılsızı kandırır

Kafasından bana ne

Bağrında tutar bizi

Sonunda yutar bizi

Kendine katar bizi

Çefasından bana ne

Mikdat’ın ters tarzları

Anlaşılmaz arzları

Riyakarın farzları

İfasından bana ne', 'Dünya yeşil güzelmiş Sefasından bana ne Sadakati ezelmiş Vefasından bana ne Dünyaya göz açarken Gördüm onu kaçarken Yalan ümit saçarken Safa...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bana-ne-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haylaz Kız…', 'haylaz-kiz-zulfikar-yapar-kaleli-ollvv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Kutlu sevda olsa başta tacınız

Bu sebepten eksilmese acınız

Deseler ki, sana büyük suçunuz

Bu sevgiyi yaylar mısın? Haylaz kız! 

Açık ağız, kalkık burun, çekik göz

Pervasız dil, boru boğaz, hoyrat söz

Ağız söyler, kulak duymaz, her yer düz

Yanıldım mı? Söyler misin? Haylaz kız! 

Essah sayar, bir kez etsen şakanı

İstesen de bırakmıyor yakanı

Akrep değil, örümceğin sokanı

Artık beni eyler misin? Haylaz kız! 

Bu sevgiyi oldur olmaz aklına

Bir canı incitmek gelmez aklına

Aradığı nedir bilmez aklına

Her geleni paylar mısın? Haylaz kız! 

Hüzün bizim ekmeğimiz, aşımız

Sonbaharda, zemheride yaşımız

Bu sebepten iyi gitmez işimiz

Hâlâ beni saylar mısın? Haylaz kız! 

Saylar mısın? = Seçer misin?', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Kutlu sevda olsa başta tacınız Bu sebepten eksilmese acınız Deseler ki, sana büyük suçunu...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/haylaz-kiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün', 'bir-gun-tulay-i-cen-1c2lc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidersem bir gün  bu hayattan,

Sebebim sensin.

Hayatın anlamını bilmeden,

Baharı görmeden  gidersem,

Sebebim  sensin.

Şehrin  ışıkları  yandığında 

tek, tek,,

Gözlerim  hala karanlıkta,

Senden gelicek ışığı  bekler,

İçimdeki  yaraya  ilaçsın diye

yollarını  bekler  oldum,

Hastane  odası ilac kokuyor,

Hastalar  derman  bekliyor..

İçimdeki dermansız  yaraya,

Bir sen.

derman olursun.

Bilmedim senin  yaranın ilacı yok..

Bilmedim.

Hoşca kal  demeden  gitmek  varmıydı..

Bir ışık beklerken  karartın  dünyamı.

Doğmadan  güneş üzerime  gidersem

Bu dünyadan,bilki sebebi  sensin...

Anlamadın  beni,

anlamak  istemedin.

Bulutlarını gözyaşı  olan yağmur bile,

Göz yaşlarımla yarışamaz.

Hoşca kal demek  kolaydı

O an....

Düşünmeden  söylen...

Sana uğurlar olsun  demedim, demiyeceğim.

Sen kanayan  yaramı  dermansız  bıraktın

Hoşca kal demek  kolay...

Hemde  cok kolay....

21/10/2000', 'Gidersem bir gün  bu hayattan, Sebebim sensin. Hayatın anlamını bilmeden, Baharı görmeden  gidersem, Sebebim  sensin. Şehrin  ışıkları  yand...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-gun-149-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Reyhânî - Katre Kitabından', 'asik-reyh-n-katre-kitabindan-omer-ekinci-micingirt-74bz0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yılların yükünü almış sırtına

Soluyor dermansız Âşık Reyhanî

Sözü okyanustur sazı fırtına

Mevsimi amansız Âşık Reyhanî	

Bakışı depremdir duruşu çile 

Besteleri rüya sazı nafile

Özlemiş Zeynel i saz geldi dile

Gülleri çemensiz Âşık Reyhanî

Gözyaşı sürükler şiir seslenir

Hanımı mahsundur üstad hislenir

Sus hanım diyerek saza yaslanır 

Yatıyor gümansız Âşık Reyhanî 

Ölmek yaman diyor yaban ellerde

Acısı depreşmiş gezer dillerde

Merhamet mevt olmuş zalim ellerde 

Yaşıyor harmansız Âşık Reyhanî

Nerede Micingirt nerede vefa 

Reyhanî dermansız vallah bu defa 

Gülüşü ıstırap susuşu cefa

Bacası dumansız Âşık Reyhanî', 'Yılların yükünü almış sırtına Soluyor dermansız Âşık Reyhanî Sözü okyanustur sazı fırtına Mevsimi amansız Âşık Reyhanî	 Bakışı depremdir dur...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asik-reyhani-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahlara', 'sabahlara-guner-kurt-a5kvo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyandım gecenin zifir karanlığında	

Düşledim yine seni	

Olmaz sabahlara dek	

Deymesin eteklerime bir tutam kar	

Henüz erken 	

Sevdanın sabahlarındayım	

Kaçtım kaçabildiğimçe dertlerden	

Yine koşuyorum senin için			

Tuttum tutacağım mutluluğa dek			

Bakma soluk soluğa kaldığıma			

Yorulan benim			

Gönlüm o kar yağmaz sabahlarda', 'Uyandım gecenin zifir karanlığında	 Düşledim yine seni	 Olmaz sabahlara dek	 Deymesin eteklerime bir tutam kar	 Henüz erken 	 Sevdanın sabah...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sabahlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şampiyon', 'sampiyon-sumer-kucuk-zy3xj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Su  yok  sel  yok

Ama  ben  boğuluyorum

Bu  insanlar  var  ya 

Kardeşim

Bana  yüzmeyi  de  öğrettiler

Şimdi  şampiyonum', 'Su  yok  sel  yok Ama  ben  boğuluyorum Bu  insanlar  var  ya  Kardeşim Bana  yüzmeyi  de  öğrettiler Şimdi  şampiyonum...', ARRAY['Türk Edebiyatı','Şiir','Sümer Küçük']::text[], 8.5, '{"poet":"Sümer Küçük","poet_slug":"sumer-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sampiyon-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Mevsim', 'yalanci-mevsim-guner-kurt-09b5y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne gönül kaldı	

Nede bir zaman	

Her şey anlamsız	

Her şey yalan	

Benim olacaktın	

Aşımı paylaşan	

Bu o mevsim değil	

Yalancı mevsim		

Dünya ne kadar		

Yalanmış yalan		

Yıkılma gönlüm		

Yıkılma sende		

Mutluluk yolunda		

Koşan bulunur		

Vazgeçme gönlüm		

Vazgeçme sende		

Yalancı mevsimde birgün		

Bir gün gerçek olur', 'Ne gönül kaldı	 Nede bir zaman	 Her şey anlamsız	 Her şey yalan	 Benim olacaktın	 Aşımı paylaşan	 Bu o mevsim değil	 Yalancı mevsim		 Dünya ...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yalanci-mevsim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağım', 'bayragim-i-brahim-pataz-6f8sd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökler kucak açmış, yükselsin diye,

Soylu bir milletiz, şanımız senle.

Varlığınla, güvendedir Türkiye,

Geçmişimiz senle, günümüz senle.

   Kara günde, biz gölgende buluştuk,

   Azdan, çoktan, varımızı bölüştük,

   Candan önce, istiklale çalıştık,

   Dünyaya destandır, ünümüz senle.

Nöbet tuttuk, ilk akşamdan sabaha,

Düşmanlar geldikçe, kovduk bir daha,

Şehit olduk, can kavuştu ALLAH’a,

Semaya yükseldi, kanımız senle.

   Allah hür yaratmış, övmüş peygamber,

   Bize kutsal, vatan, bayrak ana, yar,

   Senden yoksun kalmak, ölümden de zor,

   Onurumuz senle, canımız, senle.

Zulmü, haksızlığı, taşla kovmuşuz,

Adaleti, özgürlüğü, sevmişiz,

Karanlığı, senin ile savmışız,

Aydınlık, ufkumuz, önümüz senle.

   Türkoğlu! Bayrağın değerin anla,

   Çok şehit boyadı, tertemiz kanla,

   ELEMİ:Duamdır, işim yok kinle,

   Sonsuza dek sürsün, sonumuz senle.

İbrahim PATAZ

           31/01/2006 ADANA.', 'Gökler kucak açmış, yükselsin diye, Soylu bir milletiz, şanımız senle. Varlığınla, güvendedir Türkiye, Geçmişimiz senle, günümüz senle.    K...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Pataz']::text[], 8.5, '{"poet":"İbrahim Pataz","poet_slug":"i-brahim-pataz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bayragim-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-guner-kurt-beiqr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Solacak bir sevdamıydı	

Bitecek bir aşkmıydı söyle	

Kahreder sensizlik beni böyle	

Dudaklarıma ismin mühürlendi	

Her gece böyle	

Ağırmadan saçlar	

Yıkılmadan bedenler	

Ayrılmazdık hani		

Dünyadan göç etsek bile		

Biz ayrıldık		

Ne oldu bize böyle		

Dize getirirdik hani her şeyi		

Dize gelen biz olduk		

Solacak bir sevdamıydı		

Bitecek bir aşkmıydı söyle', 'Solacak bir sevdamıydı	 Bitecek bir aşkmıydı söyle	 Kahreder sensizlik beni böyle	 Dudaklarıma ismin mühürlendi	 Her gece böyle	 Ağırmadan s...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hani-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tesbih Dilekçe', 'bir-tesbih-dilekce-mustafa-benkli-o5unu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birisi Diyanet`in Münâcâtlar kitabında, birisi Ümraniye Belediyesinin şiir yarışmasında ve Şiir Sitemizde de kayda geçmiş, otuzu da doğrudan Sitemizde kaydolmuş, bu şekilde kayıt sayısı otuzüç olacak bu ürünümle ortaya çıkan (33)   rakamı bana tesbihi tedâi ettirip, o da bana teslimiyeti hatırlattı ve bir teslimiyet dilekçesi adı aklıma geldi, ifadeye dökülürken otuzüçlük üç sıra halinde nazma sokmaya çalıştığım `doksandokuz`luk üçlü dizi olan eserimin adı da böylec

`Bir Tesbih Dilekçe` olarak HUZUR`a çıktı efendim...

-------------

Ne olur Cehenneminde de olsam incitmezsin bilirim, sen bilirsin gelemem reddetme gel mutlak bana

Ateşinin hararetinden dona kaldığım, buzumu çözmeye ancak yettiği demde dokunmadan `nâr`a

Bularak her aşkta seni; serinleten gönlüne sığındım ateşten, aşkınla heran hazır oldum toprağa', 'Birisi Diyanet`in Münâcâtlar kitabında, birisi Ümraniye Belediyesinin şiir yarışmasında ve Şiir Sitemizde de kayda geçmiş, otuzu da doğrudan...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-tesbih-dilekce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşleme', 'besleme-oguzkan-bolukbasi-2owam', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1.

Yani bir heyecan

Çelişkili zamanların heyecanı

Sanki ilk kez olmuş gibi aşk

Kar yağıyor

Donmak elde değil

İçim sıcak

Martılar kahvaltı yapacak bir şeyler arıyorlar

Deniz üstü köpüksüz

Pürüzsüz bir cilde değen soğuk beni öpüyor

Beyaz bir örtü kenti örtüyor boydan boya

Şimdi sarılmak zamanı doya doya çünkü hararete ihtiyacım var

2.

Kırmızı damlı evlerin bacalarına ne olduysa o oldu her şeye

Değişti

Kömürler doğal gaza dönüştü

Gecekondular gündüzlere konmaya başladı

Namussuz ne varsa namusluları taşladı

3.

Karnım ağrıyor anne

Okula gitmeyeceğim

Öğrettikleri işe yaramıyor

Hayatın müfredatı okulunkine uymuyor

Hiçbir şey bu kadar koymuyor anne

4.

Sahiden ölüm mü yaşamın sonu

O zaman nedir  en önemli konu

Daha önceden ölmek amacıyla 

Bu kadar zamanı heba ettiğimiz ve insanı

Aklımın almadığı her ne varsa bana aklım yapıyor

5.

Tarih beni tekerrür ettirir mi

Ettirmeyen tarihi anlamak neyedir', '1. Yani bir heyecan Çelişkili zamanların heyecanı Sanki ilk kez olmuş gibi aşk Kar yağıyor Donmak elde değil İçim sıcak Martılar kahvaltı ya...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/besleme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaylalar', 'yaylalar-mahmut-demirci-7tt3u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahar vakti yaylaların çimeni

Mevsimine göre serin yaylalar

Mor menekşe boynun bükmüş laleler

Her türden çiçeğin şirin yaylalar

Türlü türlü bir çok barın elası

Gezer elbet güzellerin sonası

Çok sevdiğim Camuşlu''nun yaylası

Bizleri şad eyler varın yaylalar

Katar katar göçlerimiz çekilir

Derin derelerden suyun dökülür

Seyrangâh manzaran ordan bakılır

Çiçekler üstünde arın yaylalar

Bir garip MAHMUT''um söyle bunları

Gözeleri çamı sütlü pınarı

Ganireş''i Aladağ''ı hanları

Yazılıtaş tarih yerin yaylalar', 'Bahar vakti yaylaların çimeni Mevsimine göre serin yaylalar Mor menekşe boynun bükmüş laleler Her türden çiçeğin şirin yaylalar Türlü türlü ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Demirci']::text[], 8.5, '{"poet":"Mahmut Demirci","poet_slug":"mahmut-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaylalar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Çocuğu', 'sokak-cocugu-enver-herguler-ygvls', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha gücüme erişmeden

Her şey benim olsun diyen

Tam ağzıma götürüp

Karnımı doyuracak lokmayı

Vurup elimden aldı bir el

Hırkamı da dahil, o da yetmedi.

Sonra bölüştük şehirleri

Ondan beridir ki üstleri onların

Köprü altları,duvar dipleri

Ve gölgelerin tümü benim oldu.

Mevsimler gelir geçer

Lakin kış belimi epey büker

Maharet ister sıcacık yuvaların

Buğulanmış camlarına bakarak

Uzaktan ısınmak.

Diplerdeyim

Düşecek bir yerim daha yok ki

Korkmuyorum

Kaç kez selvi köyden geçti yolum

Kaç kez bilemiyorum...

Elim yağlı ve kirli idi

Biri tuttu ise de anında kayıverdi

Düşerken tek varlığım gölgelerime tutundum

Onlar benimdir kimse elimden alamaz

Dünyanın gölgesi de mutlak benimdir.

Hele ki ona kimse sahip çıkamaz.', 'Daha gücüme erişmeden Her şey benim olsun diyen Tam ağzıma götürüp Karnımı doyuracak lokmayı Vurup elimden aldı bir el Hırkamı da dahil, o d...', ARRAY['Türk Edebiyatı','Şiir','Enver Hergüler']::text[], 8.5, '{"poet":"Enver Hergüler","poet_slug":"enver-herguler","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sokak-cocugu-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basak Tarlasındakı Gelıncık', 'basak-tarlasindaki-gelincik-filiz-yildirim-87m6i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Basak tarlasındakı gelıncık

Yalnız senı bekleyen 

Ne bekledıgını bılmeden 

Yasama devam eden gelıncık

Belkı gunes olup kavuracak

Belkı yagmur olup ıslatacak

Belkı ruzgar olup savuracak

Belkıde askınla gozlerınden 

Dokulen iki damla yasla 

yasatacaksın...', 'Basak tarlasındakı gelıncık Yalnız senı bekleyen  Ne bekledıgını bılmeden  Yasama devam eden gelıncık Belkı gunes olup kavuracak Belkı yagmu...', ARRAY['Türk Edebiyatı','Şiir','Filiz Yıldırım']::text[], 8.5, '{"poet":"Filiz Yıldırım","poet_slug":"filiz-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/basak-tarlasindaki-gelincik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Sevdiğim', 'elveda-sevdigim-ali-seymen-991x5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ELVEDA SEVDİĞİM

Bir gün karşılaşacağız biliyorum, sensiz geçen günlere nasıl hasretsem bil ki o kadarda nefret ediyorum senden. İçinde hep senin olduğun hayaller kurdum, biliyordum hiç biri gerçek olmayacaktı. Ama bendeki umutsuz bir bekleyişti işte.Nasıl anlatsam sana, hani insan yağmurlu bir günde sevgilisiyle birlikte ıslanarak yüremek ister ya, hani hayatının sonuna kadar sevdiğinle beraber olmak istersin ya, benim sana hissettiklerimde bunlar gibi, farklı bir şey değil işte ama olmassa olmuyor, sanki hayat kavuşmamamız için yemin etmiş. Beni sabahlara kadar uykusuz bırakan, hayata yeter artık canımı alda kurtulayım dedirten şey ne biliyormusun, hem sana bu kadar yakın olmak hem de  bi o kadar uzak olmak. Elimi uzatsam tutarmıydın seni seviyorum desem bende seni seviyorum dermiydin bana. Bence artık bunların hiçbir önemi yok, ben alıştım artık sensizliğe, insan sevdiği için bir defa ölür ben senin için her gün öldüm. Elveda sevdiğim,  yine hasretine yenik düştüm…SEYMEN', 'ELVEDA SEVDİĞİM Bir gün karşılaşacağız biliyorum, sensiz geçen günlere nasıl hasretsem bil ki o kadarda nefret ediyorum senden. İçinde hep s...', ARRAY['Türk Edebiyatı','Şiir','Ali Seymen']::text[], 8.5, '{"poet":"Ali Seymen","poet_slug":"ali-seymen","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/elveda-sevdigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alevlenir Durur Sevda Ateşim', 'alevlenir-durur-sevda-atesim-huseyin-erdogan-7u2fk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu şehirde

senin bir tebessümünle

iklimler değişir birdenbire

mevsimler yeşillenir şenlenir

kırlar bahçeler renklenir

kar lapa lapa yağarken bile

sen gülümseyince

henüz yere düşmeden erir

bir saat olsa da

sensiz kalamam soluk alamam

hele bu bir güne çıkarsa

vallahi buna katlanamam 

düşlerimde olsa da 

bir tek gece bile

bil ki yokluğuna dayanamam

inan ki sensiz yaşayamam

sen uzaklarda olsan da

benden yana her bakışında

güneş doğar benim de dünyama

ısınır yüreğim sıcacık olur bedenim

alevlenir durur sevda ateşim

kendimi çöllerde hissederim

ben senin sevdanla yanarım 

aşkın uğrunda ölüme de varım

seninle bir tek geceye bile razıyım

hatta bunun için sevgili şiirim

kalan ömrümü vermeye hazırım

                              01.02.2006

                           Hüseyin Erdoğan', 'bu şehirde senin bir tebessümünle iklimler değişir birdenbire mevsimler yeşillenir şenlenir kırlar bahçeler renklenir kar lapa lapa yağarken...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/alevlenir-durur-sevda-atesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen olmayınca', 'sen-olmayinca-aynur-avci-g4d6j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalan öpüşün çığlık olsa da

Mangalda ateşin sönse de

Külleri savrulsa da etrafa

Sevginden üşüsem de dönemem

Anıların yükünü taşıyamam artık

Yalnızlığımda sen olmayınca...', 'Yalan öpüşün çığlık olsa da Mangalda ateşin sönse de Külleri savrulsa da etrafa Sevginden üşüsem de dönemem Anıların yükünü taşıyamam artık ...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-olmayinca-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Gelirdim', 'sana-gelirdim-cesim-der-97thm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağlar yol vermeyip engel olsalar

Elime koluma kilit vursalar

Çukurlar açsalar hendek kazsalar

Seller gibi coşar sana gelirdim

Gökyüzünü sarsa kara bulutlar

Tükenmiş olsa da bütün umutlar

Mezarım üstünde bitsede otlar

Kefenim sırtımda sana gelirdim

Mecnun Leyla''sını arar çöllerde

Kerem Aslı''sını buldu küllerde

Tahir''in Zühre''nin aşkı dillerde

Bir damla umutla sana gelirdim

CESİM der bilirsin yaşanmaz sensiz

Sende yaşarmısın Sevdiğim  bensiz

Ömrümü veririm sana bedelsiz

Dilenci olurda sana gelirdim', 'Dağlar yol vermeyip engel olsalar Elime koluma kilit vursalar Çukurlar açsalar hendek kazsalar Seller gibi coşar sana gelirdim Gökyüzünü sar...', ARRAY['Türk Edebiyatı','Şiir','Cesim Der']::text[], 8.5, '{"poet":"Cesim Der","poet_slug":"cesim-der","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-gelirdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatı', 'anlati-mehmet-akif-tiryaki-d0bam', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gölde bir sandal,

Dağda ağaçlar vardı.

Lakin vakit çok dar,

Zaman bir seyirlik kadardı.

Üstelik mevsim de bahardı

Telaşla geçiyordu günlerim

Temaşa için zaman dardı.', 'Gölde bir sandal, Dağda ağaçlar vardı. Lakin vakit çok dar, Zaman bir seyirlik kadardı. Üstelik mevsim de bahardı Telaşla geçiyordu günlerim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/anlati-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasana', 'anlasana-ahmetnecat-ucur-d470g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben,sana,seni

Neden,niye,niçin

Nasıl ve ne kadar

Sevdiğimi,sevdalandığımı

Aşık olduğumu

Anlatamadım mı? 

Anlatamıyacakmıyım? 

Ölenekadar

Ve sen halâ,ısrarla

Anlamayacakmısın,

Beni öldürene kadar! 

Yaşıyorum ya aşkınla

Yaşayamasam da seninle

Aşkımın sesini dinle

Ahımla inim,inim inle!', 'Ben,sana,seni Neden,niye,niçin Nasıl ve ne kadar Sevdiğimi,sevdalandığımı Aşık olduğumu Anlatamadım mı?  Anlatamıyacakmıyım?  Ölenekadar Ve ...', ARRAY['Türk Edebiyatı','Şiir','Ahmetnecat Ucur']::text[], 8.5, '{"poet":"Ahmetnecat Ucur","poet_slug":"ahmetnecat-ucur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/anlasana-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırsat Avaresi', 'firsat-avaresi-aynur-avci-n5u1k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen fırsat avaresi,

Yalan yürek anası

Ana mukaddes varlık

Yuvasında bir melek

Sence bu ne demek

Yaşamadan bilemezsin elbet.

Sen fırsat avaresi

Yalan yürek anası

Kandık yalan sözlerine

Sevgiyi tattırmadın öksüzlere

Ana demeyi özlemiştik oysa

Geceler bitmedi,bacamız tütmedi

Kabus oldun evimize

Sen ana olamadın bize.

Sen fırsat avaresi

Yalan yürek anası..', 'Sen fırsat avaresi, Yalan yürek anası Ana mukaddes varlık Yuvasında bir melek Sence bu ne demek Yaşamadan bilemezsin elbet. Sen fırsat avare...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/firsat-avaresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Anısı', 'kar-anisi-mehmet-akif-tiryaki-pgecs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yollar soğuk, buzlu ve kaygandı.

Günlerden de salıydı.

Otobüste bir an kendinden geçti,

Durağı kaçırdı, evden uzaklaştı

Telaşla ayağı kaydı yere yapıştı

Eve geldi üst kata çıktı,

Beni neden otobüste uyandırmadın 

Diye komşusuna çıkıştı, şakalaştı.

Ben onu da yapmadım ya karda,

Dükkan ile ev arasında gittim geldim,

Bir de orayı gördüm arada.

Orası neresi mi? 

Boşver... anlatmayayım,

Sormayın gerisini,

Daha önce çok bahsetmiştim

Dağını, tepesini,

Siz anlayın artık gerisini.', 'Yollar soğuk, buzlu ve kaygandı. Günlerden de salıydı. Otobüste bir an kendinden geçti, Durağı kaçırdı, evden uzaklaştı Telaşla ayağı kaydı ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kar-anisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farz et ki Bir Hiç(t)   im', 'farz-et-ki-bir-hic-t-im-omer-osman-avci-mtawn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sevda masalıydı, 

Bizim aşkımız 

Sayfaları, eksik okunan... 

Trajik bir oyundu, 

Perdeleri eksik oynanan, 

Sahneleri hiç alkışlanmayan... 

Farz et ki, 

Beni hiç sevmedin. 

Farz et ki, 

Beni hiç tanımadın. 

Farz et ki, 

Ben bu oyunda yoktum… 

Yok! Yok! ! Yok! ! ! 

Hiç gözlerine bakarak, 

Şiirler yazmadım. 

Hiç ellerini tutmadım, 

Hiç dudaklarından öpmedim, 

Hiç hasretle sarılmadım, 

Hiç nefesini koklamadım... 

Farz et ki; 

Ben bir hiç’tim! 

Yaşamak gibi, 

Yalan dünya gibi, 

Bir hiç işte. 

Sadece bir hiç! 

Unut! 

Unut gitsin. 

Unut gitsin be...', 'Bir sevda masalıydı,  Bizim aşkımız  Sayfaları, eksik okunan...  Trajik bir oyundu,  Perdeleri eksik oynanan,  Sahneleri hiç alkışlanmayan.....', ARRAY['Türk Edebiyatı','Şiir','Ömer Osman Avcı']::text[], 8.5, '{"poet":"Ömer Osman Avcı","poet_slug":"omer-osman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/farz-et-ki-bir-hic-t-im-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tiyatrocular Ve Halk', 'tiyatrocular-ve-halk-mehmet-akif-tiryaki-ymm3l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İtler dalaşıyor sokakta,

Keyifle izliyor birileri

Yalıda, konakta.

Nasıl tepki uyandırıyor bu halkta

Yemeği yokki onun tabakta

Soğana muhtaç oldu,

Bu iktidarda, öz vatanında

Onun gözü ekmeğin yanındaki katıkta

Tiyatro oynuyorlar ortalıkta.', 'İtler dalaşıyor sokakta, Keyifle izliyor birileri Yalıda, konakta. Nasıl tepki uyandırıyor bu halkta Yemeği yokki onun tabakta Soğana muhtaç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tiyatrocular-ve-halk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkana bakmadan', 'arkana-bakmadan-aynur-avci-vwq1n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaşıkla oynattın

Kadehinde inlettin

Kalbimi yaktın

Arkana bakmadan

Çekip de gittin

Çağladın durdun

Sözlerinle avundum

Aşkınla savundum

Gecende uyudum

Arkana bakmadan

Çekip de gittin..', 'Kaşıkla oynattın Kadehinde inlettin Kalbimi yaktın Arkana bakmadan Çekip de gittin Çağladın durdun Sözlerinle avundum Aşkınla savundum Gecen...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/arkana-bakmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnlesin', 'i-nlesin-mehmet-akif-tiryaki-aoytl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Değişmedi hiçbirşey onsekiz yirmi senedir,

Onlar bizim vücudumuzda kenedir,

Koparıp yok edemiyoruz, aciziz,

Hadi birimiz neyse, hepimiz kerizmiyiz? 

Bizi de alıştırdılar ne kötü argoya

Haftada bir verir olduk mal kargoya,

Kartlar ailelerde korkulu rüya

Tedavi olacaktı her vatandaş ücretsiz güya,

Bırak bu işleri zaman doldu,

Hadi git yat gözüm görmesin,

Dini siyasete alet edenler sürünsün inlesin

Vatandaş kendine gelsin beni dinlesin

Vatanına sahip ol ey halk uyuma,

Leke getirmem ben asla soyuma.', 'Değişmedi hiçbirşey onsekiz yirmi senedir, Onlar bizim vücudumuzda kenedir, Koparıp yok edemiyoruz, aciziz, Hadi birimiz neyse, hepimiz keri...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/inlesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun', 'yoklugun-levent-kapisiz-5w8vr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yokluğun benzemiyor diğer yokluklara

Yemek bulunur acıksan

Veya bir dilim ekmek bulur her gariban

Ama sen yoksan gözlerin yoksa

Her şeye alışırda bu can

Senin yokluğuna asla

Seni görmem için gözlerimi kapatmam yetmiyor

Yokluğu bir gölge peşimi bırakmıyor

Gündüz güneşim gece karanlığım

Kimsecikler bu canı anlamıyor

Kimse yerini alamıyor

Yokluğun bezemiyor diğer yokluklara', 'Yokluğun benzemiyor diğer yokluklara Yemek bulunur acıksan Veya bir dilim ekmek bulur her gariban Ama sen yoksan gözlerin yoksa Her şeye alı...', ARRAY['Türk Edebiyatı','Şiir','Levent Kapısız']::text[], 8.5, '{"poet":"Levent Kapısız","poet_slug":"levent-kapisiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yoklugun-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve İnsan', 'ask-ve-i-nsan-aynur-avci-2ki5b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşklar çoktur

Ama aşktan hiç

Dost yoktur

Aşk sandığın eller

Elimde uzun kalmadı

İnsanlar hep yalandı

Söyle gerçek aşkı

Bulan var mı?', 'Aşklar çoktur Ama aşktan hiç Dost yoktur Aşk sandığın eller Elimde uzun kalmadı İnsanlar hep yalandı Söyle gerçek aşkı Bulan var mı?...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-ve-insan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turnalar', 'turnalar-aynur-avci-t6jfe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Turnalar geçer selamsız

Aylar yıllar sevgisiz

Her gün yol gözlerim habersiz

Turnalar sonbahar oldu mu

Harmanlar havada savruldu mu

Yıllar sevgiye döndü mü

Hasret yolu bittimi

Haber edin turnalar

Yarim geri geldi mi

Turnalar   turnalar...', 'Turnalar geçer selamsız Aylar yıllar sevgisiz Her gün yol gözlerim habersiz Turnalar sonbahar oldu mu Harmanlar havada savruldu mu Yıllar se...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/turnalar-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Yol Hikayesi (raylar ve İnsanlar)', 'kisa-yol-hikayesi-raylar-ve-i-nsanlar-omer-osman-avci-o0hiq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnanmayın dostlar

Ne yaşanır

İkinci bahar

Ne de

Hayat kırkında başlar

Gerçek olan şu ki

Yıllar bir su misali,

Hep saman altından

Akar...

Cahit sıtkı:

__yaş otuz beş,

Yolun yarısı demiş

Anlayamıyorum

Ya, yol çok kısa

Ya da, yaşam treni hızlı

İşte şurada 

Altmış-yetmiş metre ileride

Son durak

Bu durakta

İsteseler de

İstemeseler de     

Tüm yolcular inecek

Ve…

İnenler

Bir daha da bu trene binemeyecek …', 'İnanmayın dostlar Ne yaşanır İkinci bahar Ne de Hayat kırkında başlar Gerçek olan şu ki Yıllar bir su misali, Hep saman altından Akar... Cah...', ARRAY['Türk Edebiyatı','Şiir','Ömer Osman Avcı']::text[], 8.5, '{"poet":"Ömer Osman Avcı","poet_slug":"omer-osman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kisa-yol-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehit Askerim', 'sehit-askerim-aynur-avci-6izbj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tek yürektik seninle

Mermi sırtında

Mayınlı yolları aştın

Ulaştın hedefine

Kavuştun topuna tüfeğine

Aşıktın sen vatanına

Barut kokan,son nefesinde

Ayın yıldızın dalgalanacak daima

Mavinin özgürlüğünde

Sen rahat uyu şehidim

Toprak bedeninde..', 'Tek yürektik seninle Mermi sırtında Mayınlı yolları aştın Ulaştın hedefine Kavuştun topuna tüfeğine Aşıktın sen vatanına Barut kokan,son nef...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sehit-askerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '- Durma öyle...-', 'durma-oyle-oner-kaciran-fm4v2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Değiştir yıldızların yerini

ayın yerini

Korkma güneşten 

aç gözlerini

Bir su damlası ol

saçıl maviye

gökkuşağına boya renklerini

Uç bir kuş kanadında 

rüzgara karşı

takıl bulutların peşine

Fırtına ol, meltem ol 

danset başaklarla

nedensiz aşık ol delicesine

Yağmur ol, 

düş sevdiklerinin üstüne

Azgın bir nehir ol 

ak akabildiğin yere

Durma öyle

karış toprağa çoğal

sevda ol,aşk ol

aç çiçeklerini

aşk dolu yüreklere

Seni sevdiğini düşün

herkesin

Çekinme

kandır kendini

sevginin olduğu yerdesin

Sil at

hayatından mutsuzluk veren

herşeyi

Birgün

anlıyacaksın nasıl olsa 

vakit dolduğunda

Sevmek yanlışsa

doğruyu yapmak 

kimin umurunda..

30.01.2006 Dionisos

Düş gönüllere,

Aşık olmanın ve aşkı yaşamanın çok çeşidi vardır.', 'Değiştir yıldızların yerini ayın yerini Korkma güneşten  aç gözlerini Bir su damlası ol saçıl maviye gökkuşağına boya renklerini Uç bir kuş ...', ARRAY['Türk Edebiyatı','Şiir','Öner Kaçıran']::text[], 8.5, '{"poet":"Öner Kaçıran","poet_slug":"oner-kaciran","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/durma-oyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-mim-ahmir-rengi-gb532', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk eyledi garibanı çöllerde susuz

Ne sitem var haline, baharlar sonsuz', 'Aşk eyledi garibanı çöllerde susuz Ne sitem var haline, baharlar sonsuz...', ARRAY['Türk Edebiyatı','Şiir','Mim Ahmir Rengi']::text[], 8.5, '{"poet":"Mim Ahmir Rengi","poet_slug":"mim-ahmir-rengi","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ask-529-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikayet', 'sikayet-cemil-aygen-5q8ii', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birini kovdum başımdan

ÖTEKİ diğerinin Hakkını istedi

Hani laf anlatamadım

Zaman geçiyor..Be...

Dur...Dur..

Sabir Nedir Bilmezmisin

Bak ben onunla büyüdüm

Hani o taşını çatlattığım Sabırla

Kovulmuş iki duygu da

Israrlı

Yaşamımın Tüm istemezükleriyle Karşımdalar

Ne sevgimi avutabildim

Ne de Fukaralığımı

İkisi de dikleniyor

Kalkıp dikilip ayağa

Kaçmaya Başladım

Ve sonunda

Herikisinden de...Herkesten Kaçtım

Yalnızlığımıda yanıma alıp

Çok uzaklardayım

Kurtuldum Sanıyordum da

Değil

Olduğum yerde dönüp duruyormuşum...', 'Birini kovdum başımdan ÖTEKİ diğerinin Hakkını istedi Hani laf anlatamadım Zaman geçiyor..Be... Dur...Dur.. Sabir Nedir Bilmezmisin Bak ben ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sikayet-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Verin Dağlar', 'gul-verin-daglar-cengiz-ozkan-4wmfg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok gezdim dolaştım; hepsi bir rüya, 

Yaş erdi kemale, yol verin dağlar. 

Ne güzeller gördüm, bir ceylan var ya, 

Doyulmaz cemale, kol verin dağlar 

Çayların serindir, düze akıyor, 

Boldur nimetlerin, güneş yakıyor, 

Açmıştır ağzını, sana bakıyor, 

Aç gezen arıya, bal verin dağlar

Yar sevdası başa, büyük bir çile

Bahar gelir lale, sümbül gül ile

Bülbül perişandır, bana şans dile

Derde dayanmaya, hal verin dağlar

Gelinlik çağında kızlar geçtiler

Susayip çayından, sular içtiler

Cengiz özkan''a da, kısmet biçtiler

Nişan düğün vardır, gül verin dağlar', 'Çok gezdim dolaştım; hepsi bir rüya,  Yaş erdi kemale, yol verin dağlar.  Ne güzeller gördüm, bir ceylan var ya,  Doyulmaz cemale, kol verin...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Özkan']::text[], 8.5, '{"poet":"Cengiz Özkan","poet_slug":"cengiz-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gul-verin-daglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Benim Gibi Seven', 'seni-benim-gibi-seven-yusuf-onder-bahceci-h8i0o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni benim gibi seven,

Seven varsa beri gelsin,

Senin için cânı veren,

Veren varsa beri gelsin.

Seni sevdim oldun elin,

Belki yeni, yeni bildin,

Eyvah, eyvah sevmiş dedin,

Seven varsa beri gelsin.

Senin için yandım güzel,

Şu kalbimde sevgin özel,

Eşin yok Dünya''da güzel,

Seven varsa beri gelsin.

Senden başka sevmedim,

Çok sevmişim bilmedim,

Yazım kara gülmedim,

Seven varsa beri gelsin....', 'Seni benim gibi seven, Seven varsa beri gelsin, Senin için cânı veren, Veren varsa beri gelsin. Seni sevdim oldun elin, Belki yeni, yeni bil...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-benim-gibi-seven-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuzbeş Yıllık Dostum', 'otuzbes-yillik-dostum-i-brahim-halil-demir-e6bis', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dur gitme hemen! 

Sor halimi, bir türlü iyileşmeyen yaralarımı…

Anlatsana! 

Sen otuz beş yıllık arkadaşım,

Sen can ciğer sırdaşım,

Sen iyi ve kötü bir çok anılarımı paylaştığım…

Yoksa bu şehrin keşmekeşliği,

Dostlukların yapaylığı,

Seni de mi küstürdü? 

Ah ah çeke-çeke bir hal oldum,

Sen, yeni susmuş konuşmuyor,

Ben ise konuşmayalı yıllar oldu..

Gel seninle sessiz ve sakin bir yerde,

Deminde duygu kokan çayları içelim..

Gel seninle eski dostlukları özlemle yad edelim,

İster hüngür-hüngür ağlayalım,

İster patavatsızca kahkahalar atalım…

Ama çok ta dikkatli olalım! 

Zira bu tür gülüşlere alışık olmadım ki,

Şahadet şerbetini içen atalarımız

Bu tür hayasız gülüşlerimizi duyarlarsa,

Sızlar  kemikleri…

Sonra helal etmezler haklarını,

Gel otuz beş yıllık aynı duyguları paylaştığımız 

Aziz şerefli, harama tevessül etmeyen, dostum! 

Silkelenip kendimize gelelim…

Namusların ortalıkta olduğu,

Bu acımasız gaddar canavar devasa şehirlerde…

Yoksa seni de mi değiştirdiler? 

Şimdi deme sakın kusuruma bakma diye,

“İşlerimin yoğunluğundan,

Zamanın yetmezliğinden,

Maddi sıkıntılardan dolayı arayıp ta soramadım”

Yo hayır sakın bunları söylemeye kalkışma! 

Yalan söylemek rol yapmak

Yakışmaz sana da, bana da; 

Belli ki sende uymuşsun düzenin kırık çarkına

Ama çok üzüldüm bu haline! 

Unutmadan şunu da söyleyeyim,

Sakın ha içi boş “Nasılsın, görüşelim“

Cümlesini ya kullanma,

Ya da görüşebilmek için hiç bir fedakarlıktan kaçınma…

Çünkü geçenlerde böyle bir olay yaşadım.

Saatlerce etkisinde kaldım.

Otuz beş yıllık arkadaşım,

Şayet bu düzene uymuşluğunu devam ettirirsen,

Yüreğimin en güzel yerindeki saf dostluğunu gömer,

Sanki tanımadım seni,

Sanki kırk beş yıllık ömrümün otuz beş yılını,

Senle geçirmedim deyip avuturum bak kendimi…

Ben eski dostuma özlem duyar,

Ve ben hileye uymamış,

Kitabında yapmacıklık olmayan,

Ve yemeyip  yediren, dostunu yarı yolda koymayan,

Ahde vefalı her türlü nimetlere rağmen

Atalarının kemiklerini sızlatmayan

Güzellikleri ve sıkıntıları paylaşan 

Dostumu arıyorum…! 

01/02/2006', 'Dur gitme hemen!  Sor halimi, bir türlü iyileşmeyen yaralarımı… Anlatsana!  Sen otuz beş yıllık arkadaşım, Sen can ciğer sırdaşım, Sen iyi v...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/otuzbes-yillik-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Seven Benim Hâlimden Anla', 'gercek-seven-benim-h-limden-anla-yusuf-onder-bahceci-pufuz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gerçekten seversen bilki ayrılık olur,

Gerçek sevenlerde hep burukluk olur,

Gerçek seven cân verir, cânını bulur,

Gerçek seven benim, hâlimden anla.

Seni ilk gördüğümde sevdim bunu bil,

Gözlerinde yaşlar varsa durmadan sil,

Sana güller veremedim cân verdim bil,

Gerçek seven benim, hâlimden anla.

Bu şiirler böyle güzelim sürüp gidecek,

Eğer şiir yoksa sevdamı kimler bilecek,

Önder birgün ölecek, belki gülmeyecek,

Gerçek seven benim, hâlimden anla.....', 'Gerçekten seversen bilki ayrılık olur, Gerçek sevenlerde hep burukluk olur, Gerçek seven cân verir, cânını bulur, Gerçek seven benim, hâlimd...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gercek-seven-benim-halimden-anla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kederin sustuğu an''a', 'kederin-sustugu-an-a-evren-dalgic-kyvd9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ellerinden,

mavi bir gökyüzü,

verse düşlerimi,

yağmur gibi üzerime.

takvimleri sığdırsa hep seninle; 

hep gözlerinle olan günlere..

nefes almam olsa seninle,

kaçsak gitsek bilinmeyen yerlere.

ellerin salıncak olsa,

sallansam çocuk gibi hiç durmadan,

başımı döndürse gözlerin,

ılığını hissetsem çektiğin havanın,

olsan da yanımda; 

çıtı çıkmaza o sitemli ağzımın.

özlediğim gibi özlemesem bu ayrılıkları,

tadı yok ki sensizlikte canımın.

kaçışlarım destansı inan ki bu kabusta,

karşıma çıkan her hüzünde; 

bir köşeden yavaşca kayboluşta.

sararsa da tenim; 

bu kaçışlarım hep sürecek,

umudunu katık yapmış bana; 

bu sanki oyun gibi gelecek.

ellerinden tutacağım elbet bir gün; 

bu hüzzam şarkısı elbet bitecek.

Bir gün döneceksin bu zavallı şehre; 

kederim susacak, şiirler gülecek.

(Ankara 2005)', 'ellerinden, mavi bir gökyüzü, verse düşlerimi, yağmur gibi üzerime. takvimleri sığdırsa hep seninle;  hep gözlerinle olan günlere.. nefes al...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kederin-sustugu-an-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Kızın Hikayesi 16', 'deli-kizin-hikayesi-16-can-ozcan-ozkan-2bk3k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaprakların intihar ettiği bir vakitte

Sessizce sokulan ayrılık

Havadan önce bıraktı kar soğuğunu

Birbirimizi ısıttığımız koynumuza...

Gül kokusunda solunan nefesler

Kim bilir kaç paket tütün soluyacak

Özlemle geçecek her saniyenin saniyesinde

Bahar gözlerini yanında götürsen de

Yüreğimin heybesine koydum onlardan

Bana kalan bakışlardan bir demet

Teninin sıcaklığını avuçlarımda nefesimle

Isıtıp bedenime saracağım

Her gecenin gündüze kenet attığı vakitte

	Özlemle kal

		Yüreğim...

Her geçen günün ay ışığı tebessümün kadar

Aydınlık ve Mutluluk versin 

		Özlem kalacağım

			Yüreğine...

Ha! 

Unutma! 

Beni değil...

Her gecenin karanlığını yırtan

Gökteki tebessümüne bakmayı

			Unutma! 

Çünkü 

Benim Bakışlarım

Gecenin aydınlığında olacak

Ve bakışlarımız orda

			Buluşacak...

Ve biliyorsun badem gözlüm

Güzellikleri doğuran bahar yağmurları değil

Yağmurlara ilham olan 

Sevdanın göz yaşlarıdır...', 'Yaprakların intihar ettiği bir vakitte Sessizce sokulan ayrılık Havadan önce bıraktı kar soğuğunu Birbirimizi ısıttığımız koynumuza... Gül k...', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/deli-kizin-hikayesi-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek Mutluluğu', 'beklemek-mutlulugu-ayhan-isin-b2p3y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'her gün seni bekledim

gözlerini, sözlerini,

mutluluğu

bir gün beni sevgiyle kucaklamanı,

seni seviyorum demeni

sensiz olmuyor demeni

mutluluk nedir ki benim için? 

senden bir esinti! 

alıştım artık küçük mutluluklara,

bir tatlı tebessüm,

gönülden iki sözcük,

ışıl ışıl bir bakış,

bir öpücük dünyalara bedel,

sen dünyalara bedel

artık anlamalısın,

duygular tükenmeden beni! 

her gün seni bekledim,

bana geri dönmeni,

seni seviyorum demeni,

MUTLULUĞU! 

01-02-2006', 'her gün seni bekledim gözlerini, sözlerini, mutluluğu bir gün beni sevgiyle kucaklamanı, seni seviyorum demeni sensiz olmuyor demeni mutlulu...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Işın']::text[], 8.5, '{"poet":"Ayhan Işın","poet_slug":"ayhan-isin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/beklemek-mutlulugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Kızın Hikayesi 17', 'deli-kizin-hikayesi-17-can-ozcan-ozkan-29vdx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün Batımında

Gözlerime Doğan Gözler Senindi...

Usulca Esen Rüzgar Nefesim

Dolanıyor El Değmemiş Bedenlerin

Kutsal Mabedinde...

Sonra

Kapanıyor Gün Batımıyla Gözler

Başlıyor Bedenlerde Irmak Irmak

Akan Sözler

Yetmiyor Zaman İnadına

Bitmiyor Çalınan Şarkımızda

Tenler Dansı 

Sırım Sıklam Akşamlara Kavuşuyor 

Bitmesin Diyerek Son Buseler Alınıyor

Gözlerden Bir Çift Yaş Salınıyor

Yürek Buruk Ayrılık Vaktine Ağlıyor

Gitme Gönlüm Busesini Verdiğim

Ağzımdan Bu Sözler Sana Akıyor

Sar Beni Sıcaklığını Verdiğin Teninle

Öp Beni Uzaktan Nefesinle

Akşamları Gözlerimi Kapadım Seninle

Yar Kaç Sabah Yarıldı Yüreğimde

Şimdi Çığlık Çığlığa Bekliyor 

Bedenimde Açılan Güller

Senden Dökülecek Bir Damla Suyu', 'Gün Batımında Gözlerime Doğan Gözler Senindi... Usulca Esen Rüzgar Nefesim Dolanıyor El Değmemiş Bedenlerin Kutsal Mabedinde... Sonra Kapanı...', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/deli-kizin-hikayesi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Kızın Hikayesi 18', 'deli-kizin-hikayesi-18-can-ozcan-ozkan-wbv1z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mum Alevinin Işığında

Kadehlerde Sabahın İlk Çayı

Ve Yazılan İlk Satırlarda

Sen Çıkıyorsun Yüreğime

Bir Çocuk Sevincinde

Ateşi Mum Işığıyla Yarışırcasına

Derince Çekilen Bir Siğara Dumanı

Sana Getiriyor Beni

Avucunda Atan Küçük Bir Yürekle

Hoşgeldin Canım

Sabahıma

Hoşgeldin Canım

Dünyama

Gül Kokunda..', 'Mum Alevinin Işığında Kadehlerde Sabahın İlk Çayı Ve Yazılan İlk Satırlarda Sen Çıkıyorsun Yüreğime Bir Çocuk Sevincinde Ateşi Mum Işığıyla ...', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/deli-kizin-hikayesi-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Kızın Hikayesi 19', 'deli-kizin-hikayesi-19-can-ozcan-ozkan-dp7hg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün Rüzgar Kokunu Yüklemeden Gelmiş

Usul Usul Saçlarımı Okşamaya 

Bedenim Sensizlik Orucunda Halsiz

Gözler Olduğu Yerde Yaşlı Bakıyor Dünyaya

Dünya Kederlenmiş Gözlerime Bensiz Bakıyor

Yanağından Aldığım Tomurcuk Buseler

Sensiz Açmıyor Yüreğimde

Gül Kokunu Yükle Bana Ki

Tomurcuklar Bilsin

Senin Bende Olduğunu...', 'Bugün Rüzgar Kokunu Yüklemeden Gelmiş Usul Usul Saçlarımı Okşamaya  Bedenim Sensizlik Orucunda Halsiz Gözler Olduğu Yerde Yaşlı Bakıyor Düny...', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/deli-kizin-hikayesi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nar Kokulu Kadınım', 'nar-kokulu-kadinim-gul-yazganarikan-m3q0c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nasıl sevmem ki seni,

Büyüsün sen, gülümsün,

Ruhumda yaz esintisi,

Bitmeyen bir ömürsün...

Gözlerin birer damla,

Okyanuslar ötesi,

Ruhun ayaz, ruhun yaz

Aşk hanımefendisi,

Yoncam, bağım, bahçem,

Ben sana bağlanmışım,

 Takılıp gönül teline, hep orada kalmışım.

Güfteci sen, besteci sen,

Ne dilersen çal, içinde çalgıyım ben...

Kışım, yazım, baharım,

solgun gülüm,

Öksüz çiğdemim,

Ben seni nasıl sevmem

Sen ki burcu burcu aşksın...

Sen ki göğün en derinini, okyanusun gizini

Gözlerine almışsın...

Kavurur bakışların, değmeye görsün...

Sana böyle bir aşkla bakan her kim olursa! ! ! ! 

İsterim ki ölümü gözlerinde görsün...

Sen nar kokulu kadınım,

Bir benim ömrümsün...

Sen benim, solgun gülümsün...', 'Nasıl sevmem ki seni, Büyüsün sen, gülümsün, Ruhumda yaz esintisi, Bitmeyen bir ömürsün... Gözlerin birer damla, Okyanuslar ötesi, Ruhun aya...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/nar-kokulu-kadinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu da Geçer', 'bu-da-gecer-aysin-ulug-oowu0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dur dedim kendime

Dur geçer bu da geçer

Unutursun yarın olur

Yeni gün gelir

Yeni aylar

Yeni mevsimler

Yeni yıllar

Bu da geçer unutursun

Yaşamak için buna mecbursun

Sabah baktım aynaya

Ama her sabah ki gibi değil

Derinden baktım bu defa

Bir yabancı gibi

Yüzümü incelemeye çalışan bir yabancı

Çizgilerim

Gözümün içindeki izler

Dur geçer dediğim her şey

Unutursun dediklerim

Gidenler, gelenler, dönenler dönmeyenler

Babam, yitip gidenler, dostlarım

Geri gelmez çocukluğum

Ankara sokakları, ayaz yürüyüşler

Yeni günler yeni aylar yeni mevsimler 

Yeni yıllar geçmiş

Unutmuşum bu da o da her şey geçmiş

Ve bu izler

Çizgilerim

Gözlerimin içi

Yüreğime döndü ayna

Ruhum ağlıyordu

Sabah fark ettim

Her şey yerli yerinde

Unutulmamış, geçer gibi yapmış

Sinsice içime sinmiş

Derinlere değil yüreğime yerleşmiş

Ama günler

Yeni aylar, mevsimler, kaç yeni yıl gelmiş

Geçmiş

Çekildim aynanın önünden

Bir bardak su aldım oturdum koltuğa

Dur dedim kendime

Bir nefeslik ömür değil mi zaten

Ne bekledin hayattan

Bu da geçer

Bu da geçer…', 'Dur dedim kendime Dur geçer bu da geçer Unutursun yarın olur Yeni gün gelir Yeni aylar Yeni mevsimler Yeni yıllar Bu da geçer unutursun Yaşa...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bu-da-gecer-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Sevdik Sevildik ki', 'oyle-sevdik-sevildik-ki-zeliha-ural-so1dr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaderdi bizleri birleştiren aynı yolda

Bir çınardı erişilmezim

bir rüyamıydı aradığım

Öyle sevdik sevildik ki

Harset ettik doğan güne

Umut ektik hep yarına

Can dedik o cana

Öyle sevdik sevildik ki

Her günde ah ettik

Hem aradık hem solduk

bizler yandık kor olduk

Öyle sevdik sevildik ki

Verirdik can için canı

Canlar canın içi

Bu kaderdi  deyil kimsenin suçu

Öyle sevdik sevildik ki

Ekilenler sabır taşı

Ağulardır onun aşı

Dört duvardır sırdaşı

Öyle sevdik sevildik ki

Doluya koysa almaz

Dertler dolu hiç boşalmaz

Sabır küpü hiç taşmaz 

Öyle sevdik sevildik ki

Adı güldü gülmedi

Gül dalını görmedi

Figanı hep gülistandı

Öyle sevdik sevildik ki

Adımı versem sana 

Desinler sevdalıydı sana

Sensizlik sensin sevdam

Öyle sevdik sevildik ki

Ölüm karku vermez bana 

Ben yanarım  o sevdama

Can dedim hep o cana

Öyle sevdik sevildik ki

Hep yalnızım yalnızlığında

Seni ararım Leylam

Fark etmiyor adın....

Öyle sevdik sevildik ki', 'Kaderdi bizleri birleştiren aynı yolda Bir çınardı erişilmezim bir rüyamıydı aradığım Öyle sevdik sevildik ki Harset ettik doğan güne Umut e...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Ural']::text[], 8.5, '{"poet":"Zeliha Ural","poet_slug":"zeliha-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/oyle-sevdik-sevildik-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelişin Bahar Gözlerinde Cemre', 'gelisin-bahar-gozlerinde-cemre-vedat-koparan-gxer0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yaralı  yalnızlıklar yarasa karanlıklarda 

dar vakitlerin aceleci kızıl başlı kuşları

gül deren alınlara yazılmayan acılarda

zamanın akışında al uyanışa yanışlardı

kanlı bir tarihin kanayan yalnızlıklarında 

gençliğimiz dar geçitlerde boğuldu kırıldı

beyaz günlerin düşü kan kızıl şafaklarda

bahardı gözlerinde cemre düşüren sıcağı 

kuytularda kuşlar çağıldar vurulurdu sevda

gelişin etekleri uçuşan ulu bir dağ yangını 

zaman geldi geçti biz bize kaldı acılarımızla

doğanın uyanışında gözlerinde cemre vardı

sen baharsın gelirsin aşkla gün uyanışında

Vedat Koparan 30.01.2006', 'yaralı  yalnızlıklar yarasa karanlıklarda  dar vakitlerin aceleci kızıl başlı kuşları gül deren alınlara yazılmayan acılarda zamanın akışınd...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gelisin-bahar-gozlerinde-cemre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-gul-yazganarikan-hkh2o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kollarındayım, öpüyorsun beni,

Kokluyorsun

Öyle bir çekiyorsun ki içine

Bir beden oluyoruz seninle...

Özlemişsin, özlemişim

Yanıp tutuşmaktayız....

Gözlerin gözlerim,

Dudakların, dudaklarım

Yüreğin, yüreğim

Nefesin, nefesim olmuş

Bitmeyen sevişlerin, 

Sonsuz okşamalarında ruhumuz...

Ayrılığın açtığı, derin yaralar var göğsümüzde

Kurumuş kanlar tenimizde,

Okşadıkça ellerimiz sevgiyle

Ne kan ne yara kalıyor bedenimizde,

Bir rüyanın koynunda seninleyim yine

Her gece, 

Senin oluyorum...

Her gece

Benim oluyorsun...

Her sabah

Rüya kabus oluyor,

Kahrolası sabahlar,

Sen girince koynuma 

İnsafsızca doğuyor.

Rüyamı çekip alıyor elimden...

Ertesi gece yine seninim ben...

Yine benimsin

Rüya da olsa

Gel...

Gelmelisin...

Yaralar içindeyim, kanlar içindeyim.

Oysa gece 

Ne kan ne yara kalmıştı bedenimizde...

Seviştikçe...', 'Kollarındayım, öpüyorsun beni, Kokluyorsun Öyle bir çekiyorsun ki içine Bir beden oluyoruz seninle... Özlemişsin, özlemişim Yanıp tutuşmakta...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/seninle-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçindeki Sesi Dinle', 'i-cindeki-sesi-dinle-sahin-erturk-1lfw6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşlerini erteleme

İçindeki sesi dinle

Arzularına gem vurma

Dudağını uzat bana

(0102.2006-Yeni)', 'Düşlerini erteleme İçindeki sesi dinle Arzularına gem vurma Dudağını uzat bana (0102.2006-Yeni)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/icindeki-sesi-dinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biricik sevdiğimsin', 'biricik-sevdigimsin-asuman-cetinkaya-auqy6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evliliğimzin ilk üç ayında eşim metin çetinkaya ile her gün güneşin doğuşunu Batışını beraber izler gece gök yüzünü seyir ederdik. doktorların ebedi anne Olamıcem raporunu verdikleri gün güneşin doğuşunu yanlız seyrettiğimde Eşime izafeten  bu şiiri yazdım.

Mavi gökyüzüm

Eşsiz güneşim

Tulu olmuyor

İlk aşkım sensiz

Nurum sevdim çaresiz

Çok karanlık olsada 

Elbet doğacak güneş

Tanrım anlıma yazmış

İlk olarak seni eş

Nasıl olsa benimsin

Kahrolsun ömrüm gitsin

Aşkım sende başladı 

Yinede sende bitsin

Allah şahidim olsun biricik sevdiğimsin', 'Evliliğimzin ilk üç ayında eşim metin çetinkaya ile her gün güneşin doğuşunu Batışını beraber izler gece gök yüzünü seyir ederdik. doktorlar...', ARRAY['Türk Edebiyatı','Şiir','Asuman Çetinkaya']::text[], 8.5, '{"poet":"Asuman Çetinkaya","poet_slug":"asuman-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biricik-sevdigimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Kırmızı,Yar Beyaz', 'kar-kirmizi-yar-beyaz-handan-gul-z7b54', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün dördüncü yas

Uludağ da kar var yüreğimde har

Ne yar dindirebildi bu alevi ne de kar

Bugün dördüncü yas yüreğimde kan

Yar eflatun; yangınlarda derunum

Ne tabib durdurabildi ne de dur dedi yar

Bugün dördüncü yas bugün dördüncü kar

Dört nevbahar geçti dört sonbahar

Hasret bıçak sırtında ismailim tekrar...

Ellerişm cebimde eteklerimde kar

Kar kırmızı yüreğimde kan

Bugün dördüncü yas eridi karlar

Toprak coştu; hala çiseliyor yardan kalanlar', 'Bugün dördüncü yas Uludağ da kar var yüreğimde har Ne yar dindirebildi bu alevi ne de kar Bugün dördüncü yas yüreğimde kan Yar eflatun; yang...', ARRAY['Türk Edebiyatı','Şiir','Handan Gül']::text[], 8.5, '{"poet":"Handan Gül","poet_slug":"handan-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kar-kirmizi-yar-beyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muradım Ol', 'muradim-ol-handan-ceylan-t78p4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şarabın tadında sen 

İçiyorum yudum yudum,

Sigaramın dumanında sen,

Nefes nefes çekiyorum. 

Gördüğüm rüyalarda sen, 

Uyanmak istemediğim,

Yaşamımın tek arzusu sen

Vazgeçemediğim,

Alınyazım, kolum kanadım,

Sevdiğim ol, hayalim, gerçeğim,

Muradım, serzenişim, yüreğim ol.

Daima seveceğim, daima seninim...

Aksaz/Marmaris 01/02/2006', 'Şarabın tadında sen  İçiyorum yudum yudum, Sigaramın dumanında sen, Nefes nefes çekiyorum.  Gördüğüm rüyalarda sen,  Uyanmak istemediğim, Ya...', ARRAY['Türk Edebiyatı','Şiir','Handan Ceylan']::text[], 8.5, '{"poet":"Handan Ceylan","poet_slug":"handan-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/muradim-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönlüm', 'deli-gonlum-mustafa-bilgili-hjo9l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sana dememişmiydim ey deli gönlüm,

O sana hiçbir zaman yar olmaz diye,

Çok yükseklerden uçtun çılgınca,

Şimdi de çek cezasını bakalım,

O çok yükseklerde açan bir dağ çiçeği,

Sense zavallı bir bahçıvansın,

O yemesi haram olan bir meyveyse,

Sen kendini Adem’mi zannettin,

Yaktın beni ey deli divane gönlüm,

Dermansız dertlere düçar ettin,

Erittin yüreğimi kor ateşlerde,

Dostuma,düşmanıma rezil ettin,

Nedir bu çektiğim senin elinden,

Ey deli divane,arsız gönlüm,

Uslan artık yoruldum ardınca koşmaktan,

O bir güneş gibi,ay gibi çok yücelerde,

Sense okyanusların dibinde bir tutam yosunsun,

Gitme artık peşinden o bir hayaldir,

Koşma artık yoruldum,dur ne olursun.

                                                                  19.11.1996', 'Ben sana dememişmiydim ey deli gönlüm, O sana hiçbir zaman yar olmaz diye, Çok yükseklerden uçtun çılgınca, Şimdi de çek cezasını bakalım, O...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deli-gonlum-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-mehmet-salih-seyhan-txz8z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Taş değil bu sevdam

Ne Batman sokakları gibi küfürlü

Ne Cudi kadar yaşlı

Ne de Fırat kadar asi

Bir çiçek misalidir sevdam 

Körpecik bir balık kadar özgür

Bir mahkum gibi tutsak yüreğindeki ummanda

Ne kayıkçının sesine

Ne kürek seslerine gelmez

Gökyüzündeki yıldızların

Ve elimdeki cigaramın mahkumudur sevdam

Bir romandır, ama

Ne Dostoyevski`nin ‘Suç ve Ceza’sı

Ne Flaubert’in ‘Madam Boyary’si

Ne de Ahmet Haşim’in ‘Melankoliğ’i

Bir gecedir sevdam

Yıldızlar gibi yalnız

Yalnızlıklar kadar gerçek.

www.seyhanlar.com.tr.tc', 'Taş değil bu sevdam Ne Batman sokakları gibi küfürlü Ne Cudi kadar yaşlı Ne de Fırat kadar asi Bir çiçek misalidir sevdam  Körpecik bir balı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Salih Seyhan']::text[], 8.5, '{"poet":"Mehmet Salih Seyhan","poet_slug":"mehmet-salih-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevdam-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkış Tüneli', 'cikis-tuneli-mehmet-salih-seyhan-u8xo8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kılcal umutlar aranır

Bazen

Varmak için 

çıkış tüneline...

Bazıları kurtulur

bazıları sizlere ömür! ! !', 'Kılcal umutlar aranır Bazen Varmak için  çıkış tüneline... Bazıları kurtulur bazıları sizlere ömür! ! !...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Salih Seyhan']::text[], 8.5, '{"poet":"Mehmet Salih Seyhan","poet_slug":"mehmet-salih-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cikis-tuneli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memu zin Aşkına! ...', 'memu-zin-askina-mehmet-salih-seyhan-0p2mu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kör bilmecelerin sokağında ağıtlar yakan

Ve ölümlü dünyanın ölümsüz acılarıyla boğulan

Sen miydin...

İbrahim Sadri’nin ‘Adam Gibi’sinde ağlayan

Bedirhan Gökçe’nin ‘Sokak Çocuğu’ ndaki insan

Hani Ankaları görüyor musun ırakta

Hani Kafdağları gibi esrarlı

Hayaller gibi imkansız imkanlar içinde

Bin bir sitemle

Sevgiyle...

Ve bin bir ölümcül isyanlarla giderler ya meçhule

İşte öylesine giden benim yar

Dünyanın döndüğünü bilende benim

Seni sevende,

Gökkuşağının renklerinde

Beyazı seçip sana verende

Kördüğümün çözümü için dolaşan bin bir el kadar

Her yeni asırda doğan, bir sonrakide,ölen benim

Ölüp dirilmekten bıkmadım

Yorulmadım sırtımdaki ağırlıktan

Meyhaneci Mısto’da cinnetler geçiren

Devirdiğim kadehler gibi saygınlığımı

deviren de benim.

Yokluğunun acısındayım şimdi

Üstelik üşüyorum üşüdüğümün farkına varmadan

Yağmurun Nisana,

Gündüzün geceye,

Gecenin karanlığa sevdası gibi bağlıyım sana

Senin özlemindeyim yar

Zeytin siyahı gözlerine,

Esmer ellerine

Şiirler türküler okumanın hasretindeyim

Ve ölüm orucundayım,

Üstelik oruçlu günlerimin sayısını unutmuş

Yıldızların karanlığında hapsolmuş bir haldeyim

Sen ise duyarsız diyarlardasın yine

Yani uzaklardasın

Yani giriş kapısı olmayan

Yani ölümsüz

Yani insansız insanlar alemindesin

Şimdi

Gelsen diyorum benim bile inanmadığım bir umutla

Şimdi gelsende

Tutsak olduğum yıldızların karanlığını yırtsam

Donlu zamanım donmuş buzlarımı çözsem diyorum

Sana el değmemiş bir gökyüzü sunsam

Bir gül kopartsam bahardan uzatsam sana koklasan

Bir ceylan getirsem dağlardan

Gözleriyle bana baksan

Hani gelsende

Memu Zin aşkina gelsende

Ölüm orucumu bozsam diyorum.', 'Kör bilmecelerin sokağında ağıtlar yakan Ve ölümlü dünyanın ölümsüz acılarıyla boğulan Sen miydin... İbrahim Sadri’nin ‘Adam Gibi’sinde ağla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Salih Seyhan']::text[], 8.5, '{"poet":"Mehmet Salih Seyhan","poet_slug":"mehmet-salih-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/memu-zin-askina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdiki Kurtlar Acaip Olmuş', 'simdiki-kurtlar-acaip-olmus-yusuf-onder-bahceci-16bbt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilirsin eskiden Kurtlar hep ehildi,

Ne köylere inerdi, ne adam yerdi,

Hep dağlarda gezer, avı beklerdi,

Şimdiki Kurtlar da bir acaip olmuş.

Bilki eskiden Kurtlar böyle değildi,

Sürü ile gezer ve karşıdan gelirdi,

Köylülerin sürülerine hiç girmezdi,

Şimdiki Kurtlar da bir acaip olmuş.

Kurdu çok severim bil âsildir âsil,

Ne Kurtlar bilirim asırlar ve nesil,

Ey Yüce Milletim gözyaşlarını sil,

Şimdiki Kurtlar da bir acaip olmuş.

Benim bir Kurt''um var aslan gibidir,

Çakalları bir boğar, kaplan gibidir,

İnsanlara zarar vermez ahu gibidir,

Şimdiki Kurtlar da bir acaip olmuş.', 'Bilirsin eskiden Kurtlar hep ehildi, Ne köylere inerdi, ne adam yerdi, Hep dağlarda gezer, avı beklerdi, Şimdiki Kurtlar da bir acaip olmuş....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/simdiki-kurtlar-acaip-olmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-cemil-aygen-jsllj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günlük yaşıyorum

Ekmek Yemek Ne bulursam 

Onu yiyiyorum

Temiz hava arıyorum arada bir

Deniz kenarında nefesleniyorum

Elimde kağıt kalem..Yazıyorum

Aklıma ne geliyorsa

Aslında şiir yazmak iyi geliyor

Rahatça herşeyi çekiştiriyorum

Ne gördüysem..Ne yaşadıysam

Özgürce, sıkılmadan yazıyorum

Hele okuyanı bulursam

Mutlu da oluyorum

Aklıma içmek geliyor...Ekseri akşamları

Gün ışığıyla alakası yok

Sakin kafa..Şarap..rakı.. votka

İhtiyaçtan

Ne bulursam içiyorum

Buralardan gideceğim..Hani sıkıldım

55 senedir buralarda sürtüyorum

Bir değişiklik zamanı geldi

Git artık diyorum..Git kendi kendime

Gideceğim gitmesine de

Beni götürecek birini bulsam diyorum

Yoksa o köşede gizlenmiş Bekleyen 

Biri var...Azrail biliyorum

Sakın ses etmeyin

Zamandan da ondan da gizleniyorum

Ne kadar geç görürse

Yaşadığım kendime KAR  biliyorum....', 'Günlük yaşıyorum Ekmek Yemek Ne bulursam  Onu yiyiyorum Temiz hava arıyorum arada bir Deniz kenarında nefesleniyorum Elimde kağıt kalem..Yaz...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yasamak-200-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmamış Aşklar', 'yasanmamis-asklar-turan-tuncer-7fzya', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'YAŞANMAMIŞ   AŞKLAR

Gözlerimde yangınlar çıkar

Ben ağlıyamam

Gözlerimde her bakış

Bir liman kapısı

Ayrılıklar yaşanır

Kavuşmalar hiç olmaz

Yüreğim; 

Eski aşkların atıldığı

Divane gönüller mezarlığı

Aşkların,

Mezar taşı da olmaz

Dudaklarım! 

Özü alınmış çiçek

Arkana bakma boşuna

Yıkılmadık,

                   Kırılmadık 

Hiç bir şey bırakmadın

Kasırgalardan,

Geriye bir şey kalmaz

Elimde kırık bir plak

Bitmemiş bir şiir

Kırık dökük bir hikaye

Öyle sandığın gibi

Pişmanda değilim

Yaşanmamış aşkların

Anıları olmaz

07-09-2005/İst

Alkadraz_Kuşcusu', 'YAŞANMAMIŞ   AŞKLAR Gözlerimde yangınlar çıkar Ben ağlıyamam Gözlerimde her bakış Bir liman kapısı Ayrılıklar yaşanır Kavuşmalar hiç olmaz Y...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yasanmamis-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığı Sevmek', 'karanligi-sevmek-turan-tuncer-pkztg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KARANLIĞI   SEVMEK

Karanlıkta aynaya baktınmı hiç? 

Gözlerindeki ışığı, umudu

Kendini gördünmü? 

Dört duvarda 

Rüzgarı hissettinmi teninde

Yada

        Uzağındaki denizin tuzunu

Hiç 

     Güneşle uyandınmı 

Teninde miskin sıcağı

Bir zemheri ayazında

Umudunu katık ettinmi? 

Dokuz şiddeti 

Yürek depremlerinde

                                  Hayallerine

Hiç kendine bakarken 

Sevdiğini gördünmü

Gözlerindeki güneşte

Karanlığı sevdiğin oldumu

Hiç

Karanlık gecedir

                            Gece kavuşmaktır,

Aydınlık sabah

Sabahlar ayrılıktır 

                              Dedinmi? 

20-11-2005/İst

Alkadraz_Kuşcusu', 'KARANLIĞI   SEVMEK Karanlıkta aynaya baktınmı hiç?  Gözlerindeki ışığı, umudu Kendini gördünmü?  Dört duvarda  Rüzgarı hissettinmi teninde Y...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/karanligi-sevmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İblisin Çocukları', 'i-blisin-cocuklari-turan-tuncer-24v9g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İBLİSİN ÇOCUKLARI

Hiç 

Ama hiç! ! 

Yenilmeyeceksin 

Senin; 

Kaybettiğini söyleyecekler

Karşılarında,

Direndiğin kabus karaların

Yenilgiyi 

Asla kabul etmeyeceksin

Sana 

Her zaman bir yol olacak,

Çıkmak için aydınlığa

Unutma! 

Sana karşı olanlar

Karşıysa aydınlığa 

Bütün yolları 

Bütün adımları

Karanlığa giden yoladır.

Ve; 

Onlar

Karanlığa yürümezler

Aydınlıklara 

Karanlıkları taşırlar

Çünkü onlar 

İblisin çocuklarıdırlar.

27 Ocak 2006 /İst

Alkadraz_Kuşcusu', 'İBLİSİN ÇOCUKLARI Hiç  Ama hiç! !  Yenilmeyeceksin  Senin;  Kaybettiğini söyleyecekler Karşılarında, Direndiğin kabus karaların Yenilgiyi  A...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/iblisin-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Dost', 'can-dost-turan-tuncer-c5vn1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'CAN DOST

Biraz 

''MEGOLOMAN''lık'' yapayım 

Bari dedim.

Umarım kızmazsınız bana! 

Diyeceksinizki,

Şimdi nereden çıktı? 

Bu ''MEGOLOMAN''lıkta''

EEE şişinmek ve böbürlenmek,

Mağrurlanmak değilmi işimiz dedim! 

Ve aldım sazı elime.

Baktım ki etrafımda 

Bir sürü boş nefes

Mağduriyet, masumiyet

Zaman kaybı

Zorbalık bir başka meziyet..

Küfür ve hakaret 

Bilekte altın bilezik,

Fitne, fesat çıkarmak

Mertebesi yaşamın

Şeytanı bile baştan çıkartmak

Mesleği olmuş adamların..

Ama bunca olumsuzluğun içinde

Bir şey var ki 

Nasıl çekmesin dikkatimi? 

Özde olmasada! 

Başka baksada içinde insanlara

Gururumdur! ! ! ! ! ! ! ! ! 

''Can'' demeyi 

''Dost'' demeyi

''Can Dost'' demeyi 

Aşılayabilmişim 

Çevremdeki, bazılarına

EEE yazmak 

Söylemekten kolay da olsa

Farketmez 

Olsun! 

Ben bunu yazanların

Bir gün! 

Bu sözün samimiyetine kapılacaklarına

Ve bu sözün hakkını vereceklerine 

İnanıyorum! 

İnanıyorum çünkü

''Can Dost'' 

Demenin büyüsüne inanıyorum

28 Ocak 2006 /İst

Alkadraz_Kuşcusu', 'CAN DOST Biraz  ''MEGOLOMAN''lık'' yapayım  Bari dedim. Umarım kızmazsınız bana!  Diyeceksinizki, Şimdi nereden çıktı?  Bu ''MEGOLOMAN''lıkta'' EE...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/can-dost-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamızın Akortu', 'sevdamizin-akortu-murat-demir-231xk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonunda sevdamızın akortu bozuldu bak

Ayrılığın türküsü bizede yazıldı bak

Söğütlerin altında bir mezar kazıldı bak

Yeminimin yerine geldiğini bil diye

Madem oldu olacak birkaç saniye durda

Adam gibi vedalaş başucumda oturda

Birde birkaç damla yaş benim için son turda

Düşür hatırım için yalanmış değil diye

Sanma ki bundan böyle çalacak gönül sazım

Sanma ki dünkü gibi çıkacaktır avazım

Ömür kalemim bitti yazılırken son yazım

Zamansız ayrılığın altında eğil diye

Hayatında bir defa bir iyilik yap bana

Ne olursun dönüpte deme bu nasıl mana

Sana bir iz bıraktım sana onurdan yana

 Eski hatıraları satır satır sil diye.', 'Sonunda sevdamızın akortu bozuldu bak Ayrılığın türküsü bizede yazıldı bak Söğütlerin altında bir mezar kazıldı bak Yeminimin yerine geldiği...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdamizin-akortu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Aşk Olsun', 'adi-ask-olsun-turan-tuncer-xufmr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ADI AŞK OLSUN

Önce bir tek şeyi sev

Adını koyma

Önemide yok

Ama

       Sevmeyi öğren

                               Önemsemeyi

Bak! 

Arkası gelecek

Islak kaldırımlarda

Üşümekten korkup

Geceyi yakarak  ısınan çocuğu

İç içe girmiş kalabalıkların 

                                       Yalnızlığını

Sofraya tok oturup

Aç kalkan insanları

Baktığında adını okuyacağı

Kimliği olmayan 

Yalnızlığı seveceksin

Ama 

Tüm bunlardan önce

Kendini seveceksin

                                 Yaşamı

Adını koyma

                   Her hangi bir şeyi sev

Sevmeyi sev

Bu bir kadın 

Yada 

         Bir erkek olsun

ADI AŞK OLSUN

09-08-2005/İst

Alkadraz_Kuşcusu', 'ADI AŞK OLSUN Önce bir tek şeyi sev Adını koyma Önemide yok Ama        Sevmeyi öğren                                Önemsemeyi Bak!  Arkası ...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/adi-ask-olsun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiirler Senin İçin', 'bu-siirler-senin-i-cin-yusuf-onder-bahceci-skotb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu şiirler senin için, senin için diyorum,

Şiirlerimi iyi okusan seviyorum diyorum,

Daha ötesi yok ki senin için ölüyorum,

Bu şiirler senin için, senin için diyorum.

Şiirlerimde hep gözyaşı, hasret, gurbet,

Şiirlerimde yok bırakıpda gidene nefret,

Sevdan şu gözlerimi kör etmiş inan et,

Bu şiirler senin için, senin için diyorum.

Benim bu şiirlerim hep, seni anlatır seni,

Şiirlerimde söylerim sana diyemediğimi,

Şiirlerimden anlasana sana ne dediğimi,

Bu şiirler senin için, senin için diyorum.....', 'Bu şiirler senin için, senin için diyorum, Şiirlerimi iyi okusan seviyorum diyorum, Daha ötesi yok ki senin için ölüyorum, Bu şiirler senin ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-siirler-senin-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçları Deniz Kokulum', 'saclari-deniz-kokulum-turan-tuncer-caw42', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SAÇLARI DENİZ KOKULUM

Önceleri 

Topaçlarım vardı

Başları kabaralı

Misketlerim vardı

Rengarenk

Bütün çocuklar kapmak için yarışır

Balonlarım vardı

Biraz sıkınca patlayan

Uçurtmalarım vardı

Uçurtma bayramlarında

Sonra birde baktım büyümüşüm

Kavgalar bitmiş ''misket, topaç'' üstüne

Bu seferde 

Konakladı yollarım

Garip otel odalarına

                                Yalnızlığımla

Gide gide bitiremediğim yollarım

Ayrılık oldu

                    Hasret oldu

Henüz sevdiğimi bile söyleyemediğim

                                                                Sana

Tek kişilik odalarda

Çok kişilik yalnızlıklar

Ayrılıklar

               Yaşadım

Yaşamak sayılırsa

Yolları sevmiyorum

Tabelası 

Senin olmadığın 

Şehirleri gösterdiğinde

Çevirdiğim çemberler

Teker olmuşlar

                        Uzun yollara

Kilometre taşları 

                         Ayrılıkları haykırıyor

Gül''ler, Nergiz''ler artık güzel kokmuyor

İçinde ayrılık var,

                             Hasret var

Denizler eskisi gibi mavi değil

Çimenler yeşil

Üstüne ayrılık yağmış

                                   Hasret yağmış

Solmuşta bütün renkleri hayatın

Her şey siyah beyaz

Neredesin? 

Saçları deniz kokulum

Boyaların 

Elinde gel de

Boyayalım hayatı

                         

04-08-2005/İst

Alkadraz_Kuşcusu', 'SAÇLARI DENİZ KOKULUM Önceleri  Topaçlarım vardı Başları kabaralı Misketlerim vardı Rengarenk Bütün çocuklar kapmak için yarışır Balonlarım ...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/saclari-deniz-kokulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Bir Öykü', 'i-simsiz-bir-oyku-turan-tuncer-ajlhf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İSİMSİZ BİR ÖYKÜ

En gözde kızıydın 

                           Ana''nın

Masmavi gözlerin ile

Kuğu gibi zariftin

Salkım saçak,

Ebem kuşağı saçların

Boynuna bir gerdanlık 

Az geldi dediler

Öz evlatların yetmedi

Kucağına sığmayacak kadar

Yeni evlatlıklar verdiler

Sapkın evlatlarının 

Tecavüzüne uğradın

Ve,

Sen şimdi bir ensest''sin

Önce konuşmalarını bozdular

Sonra

Sırası ile

Gözlerinin rengi

Saçların.

Ahlakın artık hak getire

Ah İstanbul! 

Sana kimler aşık olmadı

                                    Tarihte

Şimdi üçüncü sınıf 

Bir orospusun

Güzelliğin 

Gölgelenmiş,

Cehaletin salyalarında

Ama hakkını yememek lazım

Hala aşıkların var

Olacakta

Uğrunda

Cinayetler işleyecek kadar

02-12-2005/İst

Alkadraz_Kuşcusu', 'İSİMSİZ BİR ÖYKÜ En gözde kızıydın                             Ana''nın Masmavi gözlerin ile Kuğu gibi zariftin Salkım saçak, Ebem kuşağı saç...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/isimsiz-bir-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim ki Şiir değil', 'benim-ki-siir-degil-turan-tuncer-h1bse', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BENİMKİ   ŞİİR   DEĞİL

Dokunma yüreğime

Tenime dokunma

Bırak yaşanmışlıkların günahı 

Üstümde kalsın

Susarsam 

Kıyametler kopacak

Yorgun yüreğimde

Bırak, bedenimi 

Yansın kendi ateşinde

Yaşamak 

Nefes almaktan öte

Hissetmektir acıyı

Konuşurken 

Yada yazaken

Kelimelerin kifayetsiz 

Ve 

Çaresiz kaldığı an.

Ruhun teslimiyeti olur da

Yusuf''un sabrını ararsın

Kör kuyularda çaresiz

Ben; 

Çareyi 

Kendisinde buldum

Çaresizliklerin

Benim ki şiir değil 

Hayata dokunuş

Bütün yarım aşkları

Gönül tezgahında

İlmek ilmek dokuyuş

05-01-2005/İst

Alkadraz_Kuşcusu', 'BENİMKİ   ŞİİR   DEĞİL Dokunma yüreğime Tenime dokunma Bırak yaşanmışlıkların günahı  Üstümde kalsın Susarsam  Kıyametler kopacak Yorgun yür...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/benim-ki-siir-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terle Karışık Kanlar', 'terle-karisik-kanlar-ali-cengiz-turan-579xr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş çalışan bedenlerin terleriyle doğuyor,

Kararmış tenlerden çıkan ulusumuzun temelini görüyorum.

O an şehit kanları geliyor aklıma,

Terle karışmış kanlar...

Temeli kanlarıyla atılan bu vatan için,

Bu terler azdır diyorum..', 'Güneş çalışan bedenlerin terleriyle doğuyor, Kararmış tenlerden çıkan ulusumuzun temelini görüyorum. O an şehit kanları geliyor aklıma, Terl...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/terle-karisik-kanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Efendiler', 'siz-efendiler-ali-cengiz-turan-gzxux', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yemyeşil ovalarımızı,verimli topraklarımızı,

Beton yığınları yaptınız.

Siz efendiler daha meyva vermemiş,gölgesi belirlenmemiş

Fidanlarımızın üstüne ölü toprağı attınız.

Kurunun içinde yaşta yanar dediniz,

Yaktınız efendiler yaktınız.

Sonra kenara çekilip ellerinizi ovuşturup,

Purolarınızı yaktınız,

Yaktınınız efendiler yaktınız....', 'Yemyeşil ovalarımızı,verimli topraklarımızı, Beton yığınları yaptınız. Siz efendiler daha meyva vermemiş,gölgesi belirlenmemiş Fidanlarımızı...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/siz-efendiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyir...', 'seyir-sila-nur-koken-g1rik', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Med-cezir olsa adın,

ben kıyıda

gelişini seyrederken

görsem gidişini

ve başlasam beklemeye 

dönüşünü…

27 Ocak 2006', 'Med-cezir olsa adın, ben kıyıda gelişini seyrederken görsem gidişini ve başlasam beklemeye  dönüşünü… 27 Ocak 2006...', ARRAY['Türk Edebiyatı','Şiir','Sıla Nur Köken']::text[], 8.5, '{"poet":"Sıla Nur Köken","poet_slug":"sila-nur-koken","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/seyir-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Çağrı', 'son-cagri-ali-cengiz-turan-lb7qz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabır ülkem geliyoruz,

Işık ışık geliyoruz,dalga dalga geliyoruz.

Işık saçan güneş gibi,ciğerlerde hava gibi,

Gönüllerde sevgi gibi 

Sabır ülkem geliyoruz.

Bereket yağmurları gibi 

Kızgın çöllere geliyoruz.

Alev alev yanıyorlar,

Alevlere geliyoruz.

Bereket yağmurları gibi,

Üstünüze yağacağız.', 'Sabır ülkem geliyoruz, Işık ışık geliyoruz,dalga dalga geliyoruz. Işık saçan güneş gibi,ciğerlerde hava gibi, Gönüllerde sevgi gibi  Sabır ü...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/son-cagri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Şey mi İstiyorum Acaba?', 'cok-sey-mi-i-stiyorum-acaba-ali-cengiz-turan-rtkcn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göğe merdiven dayayıp,

                            yıldızları toplamak istiyorum.

Bulutlardan yorgan yapıp

                            İçinde uyumak istiyorum.

Yıldırımları kızdırıp şimşekleri

                            çaktırmak istiyorum.

Bulutları ağlatıp 

                            yangınları söndürmek istiyorum.

Ya yağmurlar bitecek yada 

                            yüreğimde yangınlar.

Çok şey mi istiyorum acaba? ..........', 'Göğe merdiven dayayıp,                             yıldızları toplamak istiyorum. Bulutlardan yorgan yapıp                             İçind...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cok-sey-mi-istiyorum-acaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamımda Sakladıklarımın Arasındasın', 'yasamimda-sakladiklarimin-arasindasin-zeliha-bicer-kh519', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '__Gidiyorum yine bu şehirden

    Ayaklarım geri geri____

Ahh bu şarkı ahh 

Sezen''i kendimizle bütünleştirdiğimiz

Bakışlarındaki o çaresizliği 

Yüreğini nasıl bırakıp gittiğini anımsıyorum

Otobüs camlarında bıraktığın ellerinin sıcaklığını

Tutmuşsun gibi hissettiğim

Yosun tutmuş şimdi sevdamız

Uzaklarda duyduğum şarkılardasın

Ne zaman körfeze gitsem

Salacak''ta ne zaman gün batımını izlesem

Yüreğim sana kadeh kaldırır 

Yaşamda sakladıklarımın arasındasın.', '__Gidiyorum yine bu şehirden     Ayaklarım geri geri____ Ahh bu şarkı ahh  Sezen''i kendimizle bütünleştirdiğimiz Bakışlarındaki o çaresizliğ...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasamimda-sakladiklarimin-arasindasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Denizi', 'ask-denizi-timur-i-likan-v4528', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derdine ben dermân olmaya geldim

Sımsıcak kalbine dolmaya geldim

Sevdâmı kalbine koymaya geldim

Sıcacık gönlüne dolmaya geldim

Yoktur yârdan başka benim hiç kimsem

Yârimle ağlasam, yârimle gülsem

Kalan ömrümü hep senle geçirsem

Seninle işitsem,  seninle görsem

Dünyâya bir daha gelmek olsaydı

Yüreğim sevginle, senle dolsaydı

Kederler, hüzünler bir bir solsaydı

Kalbim de kalbinle hep bir olsaydı

Sensiz gülmez benim bu nârin yüzüm

Tepeler dağ olur dikleşir düzüm

Topak topak olur dilimde sözüm

Köstebeğe döner kör olur gözüm

Yolumuz bir bizim ayrılmayalım

Dertlerden dertlere savrulmayalım

Yalnızlık ateşinde kavrulmayalım

Aşk denizinde hiç durulmayalım

(1 Şubat 2006/ İstanbul)', 'Derdine ben dermân olmaya geldim Sımsıcak kalbine dolmaya geldim Sevdâmı kalbine koymaya geldim Sıcacık gönlüne dolmaya geldim Yoktur yârdan...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-denizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedensiz Görünen Sevinçlerim Var', 'nedensiz-gorunen-sevinclerim-var-zeliha-bicer-xy4w6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gün yerimde duramıyorum

Balonlar gibiyim uçuyorum 

Nedensiz görünen sevinçlerim var

Nedeni sen olan hayat adımlarımda

Yaşamımda sen varken

Nedensiz olur mu benim 

Sevdalarım özlemlerim..', 'Bu gün yerimde duramıyorum Balonlar gibiyim uçuyorum  Nedensiz görünen sevinçlerim var Nedeni sen olan hayat adımlarımda Yaşamımda sen varke...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nedensiz-gorunen-sevinclerim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlamadan Bitti mi?', 'baslamadan-bitti-mi-ali-cengiz-turan-6tdra', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başlamadan bitti mi? 

Başlamadı ki bitsin.

Bedenin yaşaması,canlının yaşaması.

Beyinler nerde,düşünen beyinler....

Yaşadığını bilen beyinler nerde? 

Dünyayı sarıyorum kollarımın içinde,

Daralıyor.sıkılıyor benden kurtulmak istiyor.

Havasız kalmış gibi hızlı hızlı soluyor.

Sanki yutacak gibi 

durmadan yutkunuyor.

Sonsuzluk bende deyip durmadan kabarıyor.

Canlılar olmasaydı dünya da olmazdı.

Bir türlü anlamıyor.........', 'Başlamadan bitti mi?  Başlamadı ki bitsin. Bedenin yaşaması,canlının yaşaması. Beyinler nerde,düşünen beyinler.... Yaşadığını bilen beyinler...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/baslamadan-bitti-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve ben, Seni özlemeye devam ediyorum..,', 've-ben-seni-ozlemeye-devam-ediyorum-mehmet-emin-yesilmen-baf0s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir düşlerimdesin, birde içimde.

Başkada hiçbir yerde...,

Akşamın karanlığına benziyordu,

Bazen nefessiz kalıyordum,

Bazende göremiyor gibi yürüyemiyordum..,

Mevsimler geçti, sonbahardayız.

Kızıllığı saçını, sadeliği içini hatırlatıyor..,

Ve ben, seni özlemeye devam ediyorum..,', 'Bir düşlerimdesin, birde içimde. Başkada hiçbir yerde..., Akşamın karanlığına benziyordu, Bazen nefessiz kalıyordum, Bazende göremiyor gibi ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ve-ben-seni-ozlemeye-devam-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-zeliha-bicer-5u5z9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen, içinde birikir binlerce hüzün

Bazen, güneşe ulaşmak çok kolay gelir

Bazen, mutluluk küçük bir çocuk elindedir

Bazen, karanlıklarca yalnızsındır..', 'Bazen, içinde birikir binlerce hüzün Bazen, güneşe ulaşmak çok kolay gelir Bazen, mutluluk küçük bir çocuk elindedir Bazen, karanlıklarca ya...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bazen-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşları İçinde Seni Aradım', 'gozyaslari-i-cinde-seni-aradim-yusuf-onder-bahceci-uriqm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllarca yollara baktım da baktım,

Sadece yollar olsa dağlara çıktım,

Hiç kimse duymadan ağıtlar yaktım,

Ben gözyaşları içinde seni aradım.

Aşılmaz denen dağları nasıl aşayım,

Gel demezsen bana nasıl koşayım,

Dünya''yı boş verdim aşkla çoşayım,

Ben gözyaşları içinde seni aradım.

Önüme serseler Gülüm çalı ve diken,

Bana sökmez Gülüm boynumu büken,

Sana gelirim ben seni hayal ederken,

Ben gözyaşları içinde seni ararım.....', 'Yıllarca yollara baktım da baktım, Sadece yollar olsa dağlara çıktım, Hiç kimse duymadan ağıtlar yaktım, Ben gözyaşları içinde seni aradım. ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozyaslari-icinde-seni-aradim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esma Risalesi', 'esma-risalesi-hikmet-uzun-rbtai', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Meçnunda aşksın, Leylada kendine koymuşsun bellik,

Yusuf-u Kenansın, Bağ-ı İrem,memba-ı güzellik,

Gerçi Zat-ı Sübhanına sıfatın perdedir amma,

Bir ateş-i suzan, bir hüsn-ü afet olduğun belli.

Her kime lutfun erişse,hesapsız ihsan edersin,

Kahrın tutsa bir,cümleyi hak ile yeksan edersin,

Gerçi Zat-ı Sübhanına sıfatın perdedir amma,

Dostuna dost,hasmına bir felaket olduğun belli.

Evvel,Ahir sensin,fena erişmez Veçh-i Bakine,

Zeval ile malül akıl,yetişmez Zat-ı Pakine,

Gerçi Zat-ı Sübhanına sıfatın perdedir amma,

Varis-i Mutlak, her şeye nihayet olduğun belli,

                      Şiirin tamamı değildir.', 'Meçnunda aşksın, Leylada kendine koymuşsun bellik, Yusuf-u Kenansın, Bağ-ı İrem,memba-ı güzellik, Gerçi Zat-ı Sübhanına sıfatın perdedir amm...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Uzun']::text[], 8.5, '{"poet":"Hikmet Uzun","poet_slug":"hikmet-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/esma-risalesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Başkan oldum Patagonya Fırtınaspor’a yardım yaptım', 'nasil-baskan-oldum-patagonya-firtinaspor-a-yardim-yaptim-omer-alpdogan-do8w0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl Başkan oldum

Patagonya Fırtınaspor’a yardım yaptım 

Muz Cumhuriyeti’nde mutlu bir yaşamım vardı.. Ne güzel köyümde uzun eşek oynuyordum arkadaşlarımla.. Misket en sevdiğim oyundu.. İyi de oynardım.. Mahalledeki çocuklar elime su dökemezdi.. İyi çevirirdim yukarıda Allah var.. O zamanlar YÖK olsaydı kesin bana profesörlük ünvanını verirdi.. Misket Prof. Dr.u.. Ne güzel çocukluğumu yaşıyordum.. Anam kolumdan tuttu; haydi okula, dedi.. Şimdilerde kızlar için söylenen bu söz o zamanlar biz erkekler için söylenirdi.. Binbir zahmetle okudum. Ailem, Onassis’in akrabası olmadığından durumu pek iyi değildi.. Kendi kendimize zor yetiyorduk.. O güç şartlarda okuyup adam olayım diye çok emek harcadılar. Yemeyip yedirdiler. Giymeyip giydirdiler. İyi ki zorlamışlar. Okuyup adam oldum.. Ormancı olamadım ama profesör bile oldum. Okumak tek başına karın doyurmuyor. Millet ekmek parası için Almanyalara giderken, benim payıma da Patagonya düştü. Bekle beni gurbet, deyip yollara düştüm. Çok çalıştım, Allah da yardım etti bir yerlere geldim. Hem de iyi yerlere geldim. Baktım Allah yürü ya kulum diyor, fırsat bu fırsat dedim ve siyasete soyundum.. Siyasete soyundum ama parti yöneticiliği beni pek sarmazdı.. Ne öyle onun bunun, önüne çıkanın derdiyle uğraş.. Halbuki ben milletime hizmet etmeye aşık birisiydim.. Edersem aziz milletime hizmet ederdim.. O amaçla bir kaç yere girişim yaptım.. Genel müdür olup milletime hizmet edeyim dedim ama kısmet değilmiş.. Yerel seçimler önümde yeni ufuklar açtı. Millete hizmetin tek genel müdürlükle olmayacağını anlattı. Niye belediye başkanı olmayayım, dedim. O da bir hizmet yolu.. Hizmet için önce bir parti bulmak lazımdı. Bir kısmıyla üniversite sıralarından tanıştığım çocuklar o sıralar yeni bir parti kurmuştu, Griparti diye.. İşte o partiyi hizmet açısından en uygun parti buldum.. Hem şansım da yüksek olur. Arkadaşlarım diğer adayları ekarte etmeme de yardım ederler.. Bu halisane duygular içerisinde başvurumu yaptım. Ana belediye başkanlığını istedim. Diğer taliplilere baktığımda en şanslı aday olduğumu gördüm. Bunların hepsini geçer, rüzgarımla hasta ederdim. Sandıktan çıkmam garantiydi.. Ama, adaylar açıklandığında şok oldum. Patagonya’nın takım değiştirir gibi parti değiştirmesiyle ünlü belediyecisi Ana Belediyesi adayı gösterilmişti. Ben ise Oğul Belediyesi’nin başkan adaylığıyla yetinmek zorunda kaldım. Hayatımın en şanssız gününü yaşamıştım.. Allah bir daha böyle bir gün yaşatmasın. Lakin görev verilmişti bir kere, çalışmak lazım. Seçimi kazanmak için üç belediye başkan adayı birlikte çalışmamız gerekiyordu. Bunu sağlama almanın en güzel yolu kelepçeydi.. Hemen iki kelepçe buldum. Ben ve Oğulluk Belediye Başkan adayı Ömer, transfer rekortmeni Ana Belediyesi başkan adayımızı ortaya aldık. Bir bileğinden ben kendime, diğerinden Oğulluk Ömer kendi bileğine kelepçeledi.. Artık ayrılmaz üçlü olmuştuk. Bir arada çalışmaktan hiç kimsenin kaçınmasının mümkünü kalmamıştı. Seçim günü çok heyecanlıydım.. Nereden bilirdim çekeceğim heyecanın yanında çektiğimin devede kulak kalacağını.. Sandıklar açılıp oylar sayılmaya başladı ya. Heyecandan neredeyse kalpten ölecek hale geldim. Sandıklarda bizim Rekortmen ile Oğulluk Ömer açık ara önde gidiyorlardı. Onlar için her şey çok iyiydi.. Ancak benim durum fenaydı. Ahali Partisi’nin adayı Saldıray meydanlar yetmezmiş gibi sandıkta da saldırıp duruyordu. aynı adı gibi saldırgan çıkmıştı. Başkanlık tehlikeli görünüyordu.. İşte o sıralarda ölüp ölüp dirildim.. Artık ümidi kesmeye başlamıştım. Ne olduysa o anda oldu.. Sanki sihirli bir el yardım etmiş, sandıktaki oyları değiştirmişti. Artık her sandıktan ben çıkıyordum. Gecenin ilerleyen saatlerinde kazanan ben oldum. En yakın rakibim Saldıray’ı sonunda yenmiştim. Kaybetme ihtimalinin yarattığı kalp çarpıntıları bitmiş, bu defa da yerini sevinç gözyaşları almıştı. Gözyaşlarıma hakim olamıyordum bir türlü. Alllah’tan hanım ne olur ne olmaz diyerek eve beş on kutu mendil ve havlu stok etmişti. Bir kaç saat içerisinde hepsini bitirdim. Mendil havlular biterken ben de bitmiştim.  Sonra koltuğa yığılıp kaldım. Biraz kendime gelip, ayağa kalkacak gücü kendimde bulunca abdest aldım iki rekat şükür namazı kıldım. Bana başkanlığı kazandırdığı için Allah’ıma hamd ettim. Nihayet aziz milletime hizmet etme şansı bulmuştum.. Belediye’nin rutin işlerini çabuk hallettim.  Millet hizmet görsün düşüncesiyle spora el atmaya karar verdim. Hizmet bölgemde iki takım vardı: Patagonyaspor A.Ş. ve Patagonya Fırtınaspor. Bir de benim takım vardı Oğul Belediyespor diye ancak, hesaba alınacak takım değildi. Önceleri Patagonyaspor’u düşündüm hizmet için. Ancak bir sorun vardı. Şirket olan bu takım mensubu olduğum Griparti ile kavgalı bir ailenin malıydı. Dolayısıyla onlara yardım etmem demek partimle kavga etmem demekti. Genel Başkanım şiiri ve şarkıyı, türküyü çok severdi. Hele Hani benim Recebim Recebim sarı lira vereceğim şarkısını söylerken kendinden geçer, siz de dinlemeye doyamazdınız.  O kadar tevatür söylerdi. Lakin, hoşuna gitmeyen işler yapanları da asla unutmaz ve affetmezdi. Patagonyaspor’a yardım etmem demek intihar etmek demekti. Genel Başkanım Recebim türküsünü söylerken kellemi uçuruverir, kimsenin de ruhu duymazdı. Daha hizmete yeni başlamış biri olarak bunu göze alamazdım. Patagonyaspor’a yardım işini gündemimden çıkardım. Rotayı Patagonya Fırtınaspor’a çevirdim mecburen. O sıralarda Patagonya Fırtınaspor yönetiminde bizim Apo’nun yakın arkadaşları vardı. O münasebetle hepsini ben de tanıyordum. Cevval çocuklardı. İleride bana lazım olabilecek tiplerdi. Zaten takımın hesap kitap işlerine bakan dostumun dostu, dolayısıyla benim de arkadaşım olan zatın mesleği muhasebeydi. Neyse hem onlara yardım olsun, hem biz hizmet etmiş olalım diye biraz bişeyler verdik. Gün oldu devran döndü. Patagonya Fırtınaspor’a Ana Belediyesi Başkanı Rekortmen Başkan bir yönetim oluşturdu. Bu arada benimle Rekortmen Başkan arasında başlayan rekabet kızıştığı için Patagonya Fırtınaspor’a yardım etme şansımız da kalmamış oldu.. Allah’tan tam bu sıralarda Yeni Patagonyaspor kurulması çalışmaları gündeme geldi. Ağırlığı o yöne vermeye başladım. Ancak, bu sırada bir munafık çıktı, eski defterleri karıştırmaya başladı. Tuttu, meclis toplantısında başka konu kalmamış gibi Patagonya Fırtınaspor’a ne kadar para verdin diye sordu. Ne deyim ben şimdi.. Böyle soru mu sorulur demedim tabii. Bunun yerine, Ben Oğul Belediye Başkanı olarak Patagonya Fırtınaspor’a 70 bin Recep Lirası yardım ettim dedim. Vay sen misin diyen.. Patagonya Fırtınaspor Başkanı Adem Acar’la zaten aramız bozuktu, koskoca Vali araya girerek zor düzeltmiştik, daha doğrusu ilişkilerimizi dondurmuştuk.  Adem fırsatı kaçırmadı. Hemen Patagonya Fırtınaspor’un muhabese kayıtlarına göre Oğul Belediye Başkanı bize 10 Recep Lirası yardım etmiş, onu da iade etmek istiyoruz diyerek golünü attı.. Beklemediğim anda golü yemiştim.. Hem de gol pasını ben vermiştim. Çok zoruma gitti. Hemen karşı atak hazırlığına başladım. Başladım başlamasına da pas atacak arkadaş bulamadım. Sağa sola bakarken, bizim Apo’nun can dostu ile munasebeci arkadaş imdadıma koştular. Evet, biz şahidik, Başkanımız 10 bin Recep Lirası değil 70 bin Recep lirası verdi dediler. Ama biz kayıda 10 bin’lik kısmını geçtik. Gerisini dostumuz Apo’nun adına kaydettik. Üstelik başkanımız bir de bir deplasman masrafımız olan 10 bin Recep Lirasını karşıladı dediler. Rahatlamıştı. Dostlarımın sayesinde gol atabilecektim.. Amma, memleket münafıktan geçilmiyor ki.. Hemen birileri çıkıp, Patagonya Fırtınaspor’un defterleri ortada. Sen de verdiğini söylediğin 70 bin Recep Lirasına ait makbuz filan gibi belgelerini açıkla diye tutturdular. Kaleye giden şutumu kestiler.. Hala da tuturmuşlar, ille de belge, diyorlar.. Ama ben yılmam arkadaş. Mutlaka bir formül bulacağım. Patagonya Fırtınaspor ağlarına golümü atacağım. Sonra da golü Rekortmen Başkan ile Patagonya Fırtınaspor Başkanı Adem Acar’a armağan edeceğim.. Atamam diye bir ihtimali asla aklıma getirmiyorum.. Çünkü atamazsam ben hasta olurum.. Yataklara düşerim.. Ölürüm.. Ölmemek için atmam lazım.. Hatta kendi kendimi motive etmeye bile başladım. Her gece formamı giyip nehir kenarına gidiyorum. Başlıyorum bağırmaya: Atacağım başka yolu yok. Havaya da girdim sayılır. İş şimdi Allah’ın seçimlerde yaptığı gibi yardım yapmasına kaldı. O yardımı da arkama alınca görün beni siz! .. 

10/09/2005

Adana', 'Nasıl Başkan oldum Patagonya Fırtınaspor’a yardım yaptım  Muz Cumhuriyeti’nde mutlu bir yaşamım vardı.. Ne güzel köyümde uzun eşek oynuyordu...', ARRAY['Türk Edebiyatı','Şiir','Ömer Alpdoğan']::text[], 8.5, '{"poet":"Ömer Alpdoğan","poet_slug":"omer-alpdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nasil-baskan-oldum-patagonya-firtinaspor-a-yardim-yaptim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedin', 'dedin-esat-erbil-hvf39', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen bana vefa dedin,

Sürelim safa dedin,

Alamı keyfe saldın,

Benimçin cefa dedin.

Sen bana ölme dedin,

Gül gibi solma dedin,

Yad ellri topladın,

Dostlara kalma dedin.

Sen bana bezen dedin,

Boyak sür düzen dedin,

Elinde bir mum oldum,

Üreğim ezen dedin.

Sen bana canım dedin,

Damarda kanım dedin,

Bir od başıma açtın,

Közünde yanım dedin.

Sen bana harap dedin,

İç acı şerap dedin,

Gönlüm tutan umudu,

Uzaktı serap dedin.', 'Sen bana vefa dedin, Sürelim safa dedin, Alamı keyfe saldın, Benimçin cefa dedin. Sen bana ölme dedin, Gül gibi solma dedin, Yad ellri topla...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dedin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamazsın', 'anlayamazsin-mustafa-dogan-4-niy2y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ANLAYAMAZSIN

Anlayamazsın senide yakmadıysa,

Kalbimi yakan o sevda  korlarını,

Bütün bedenimi tutuşturan ateşi,

Gözlerinden  kalbime akıttığın o,

Lav seli aşk ateşini anlayamazsın.

-

Beynimin her hücresine yerleşen,

Kalbimin atışlarını hep koşuşturan,

Bakışlarımı  gözlerinde buluşturan,

Sana ırmaklar gibi akan,o sevgimi,

Sevemediysen, beni anlayamazsın.

-

Zamanı hatırlamayıp o bilemeyişimi,

Senden,hayalinden o kopamayışımı,

Diğer bir yarımın da,o sen oluşunu,

Bendeki tüm yolların sana varışını,

Sevmedinse benim gibi anlamazsın.', 'ANLAYAMAZSIN Anlayamazsın senide yakmadıysa, Kalbimi yakan o sevda  korlarını, Bütün bedenimi tutuşturan ateşi, Gözlerinden  kalbime akıttığ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan 4']::text[], 8.5, '{"poet":"Mustafa Doğan 4","poet_slug":"mustafa-dogan-4","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anlayamazsin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okuyucusu Olmayan Mektup *2*', 'okuyucusu-olmayan-mektup-2-tulay-sustam-aab3e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman seni anlatmaya çalışsam; 

Parmaklarım, kalemimin arkasına saklanır. Suç işlemiş çocuk gibi uzun bir süre susar. (Hayâlin dolaşır beyaz sayfalarda...)   Dağ gibi kalemimin arkasında titrer parmaklarım. Sevdanın ateşiyle kendine gelir. İliklerine kadar aşkınla dolar. Mürekkebin son damlasına kadar seni yazıp durur. 

Ne zaman gözlerini anlatmaya çalışsam; 

Nefesim kesilir, susarım sevdana... Bilirim! ... Bir gözbebeğinden diğerine kayıp giden yıldızım. Ve unutamam gözlerine vuran tek ışık olduğumu. Ne beni, ne de kendini karanlıkta bırakmamak adına birkez olsun 

kapatmazsın gözlerini. Kurur aşkın pınarı, akıp gitmez sevdaya... 

Bir şelâlenin koynuna düşmüş bir taş gibi yerinde ağırlaşır sana sevdam. Senin için yaktığım ateşin mavisinde, taş kesilen yüreğim kum tanesi misali binbir parçaya bölünür. Her birinin adı; adı konulmamış her şey olur. Yokluğunda her biri yüreğimi onikiden vurur. 

Ne zaman ellerini anlatmaya çalışsam; 

Nisan yağmurunu özleyen ağustos böceği olurum. Neye dokunsam, yitirir anlamını hislerim. Duygudan yoksun, duygusuz olurum. 

Ellerin dokunmaya görsün! ... 

Bir volkanın ortasına düşmüş, bir yağmur damlası gibi hissederim kendimi. ''''''Suda yanan ateş'''''' misali eriyip, buhar olurum. Avuç içinde büyürüm. Göz yaşında filizlenir tenim. Ellerinde gül olurum, yokluğun dikenimdir. Sende açar, sende solarım... 

Ne zaman dudağını anlatmaya çalışsam; 

Her gün güneşle sevişmiş gibi olurum. Yaramaz bir çocuk gibi iki dudağının arasında köşe kapmaca oynarım. Yorulduğumda; dudak kıvrımlarının arasına kıvrılıp uyurum. 

Kulağıma adın fısıldandığı günden beri adını taşıyor ve seninle yaşıyorum. 

Ey Sevdiğim! ... 

Ben; sen kokarım, sense AŞK...', 'Ne zaman seni anlatmaya çalışsam;  Parmaklarım, kalemimin arkasına saklanır. Suç işlemiş çocuk gibi uzun bir süre susar. (Hayâlin dolaşır be...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/okuyucusu-olmayan-mektup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Sevildim', 'sevdim-sevildim-esat-erbil-qt99l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vefa görsettim vefasız yara,

Sevda ne demek o, gülizara,

Yolumdan geçmem çeseler dara,

Sevdim sevildim aldandım eyvah.

Fanı dünyada gülmedim inan,

Gözümün yaşın silmedim inan,

Yar vefasızsın bilmedim inan,

Sevdim sevildim aldandım eyvah.

Aşkı bilmezdin öğrettim sana,

Gönlümü verdim güzel canana,

Ne zalim oldun yar kıydın bana,

Sevdim sevildim aldandım eyvah.

Sadaket nedir? Sevenler bilsin,

Aşık suç yapsa ona aff kılsın,

Teseli veren göz yaşım silsin,

Sevdim sevildim aldandım eyvah.', 'Vefa görsettim vefasız yara, Sevda ne demek o, gülizara, Yolumdan geçmem çeseler dara, Sevdim sevildim aldandım eyvah. Fanı dünyada gülmedim...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdim-sevildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Günümde', 'var-gunumde-esat-erbil-0hwsd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Var günümde yanım aldın,

Gece gündüz bizde kaldın,

Yoksul oldum unutuldum,

Başkasına neden daldın? 

     Sana inanmam git vefasız git,

     Aşkımı kinlettin sevdamı unut.

Ben sevmedim aşkım ölsün,

Gül açmadan yazık solsun,

Gençliğimin bahçesinde,

Yabancılar bize gülsün,

     Sana inanmam git vefasız git,

     Aşkımı kinlettin sevdamı unut.

Ayrılığa bade içtim,

Yalğuzluğa kömlek biçtim,

Sen vefasız hem de nankör,

Bu aşkımdan birden geçtim,

     Sana inanmam git vefasız git,

     Aşkımı kinlettin sevdamı unut.', 'Var günümde yanım aldın, Gece gündüz bizde kaldın, Yoksul oldum unutuldum, Başkasına neden daldın?       Sana inanmam git vefasız git,      ...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/var-gunumde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-esat-erbil-5gbwp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin ezdi beni,

Öldüren nazdı beni,

Kaş çiprigin ok etti,

Oklara düzdü beni,

   Aklım aldı sözlerin,

   Evim yıkan gözlerin.

Gözlerin rengi kara,

Gonlumde açtı yara,

O, günden seni sevdim,

Ögrendim ahu zara,

      Aklım aldı sözlerin,

      Evim yıkan gözlerin.

Gözlerin görmez gözüm,

Kar etmez sana sözüm,

Aşkın fikrım kör etti,

Unutmuşam ben özüm,

      Aklım aldı sözlerin,

      Evim yıkan gözlerin.', 'Gözlerin ezdi beni, Öldüren nazdı beni, Kaş çiprigin ok etti, Oklara düzdü beni,    Aklım aldı sözlerin,    Evim yıkan gözlerin. Gözlerin re...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gozlerin-219-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde ?', 'nerde-ahmet-unal-cam-x9ou9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonsuz karanlıktayım

      gözlerin nerde? 

Dipsiz kuyulardayım

      ellerin nerde? 

Hani baharda gelirdin,

Hani beni çok severdin,

Hani yeminler ederdin,

      sözlerin nerde? 

Nasılda hayrandım sana,

Dört mevsim gibiydin bana,

Hepten kış oldun,baksana,

      baharın nerde?', 'Sonsuz karanlıktayım       gözlerin nerde?  Dipsiz kuyulardayım       ellerin nerde?  Hani baharda gelirdin, Hani beni çok severdin, Hani ye...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerde-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Penceremin Kenarında', 'penceremin-kenarinda-ahmet-unal-cam-1d43c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen otururum

  penceremin kenarına

  seyrederim,gelip geçenleri

  oynayan çocukları seyrederim

Bazen dayanamam

  koşar oynarım,çocukların içinde

  bazen yaramazlık yaparım,mızırım

 ...hiçbiri bilmez.

Bazen dalıp giderim,uzaklara

  aşarım ufukları

  sahillere ulaşırım

  atarım kendimi kumsallara,

  kapar gözümü,denizi dinlerim,

  haykırırım hırçın dalgalara.

  Başıboş bir kayık bulurum,

  açılırım engin denizlere

 ...kimseler görmez.

Bazen,küçük birkuş konar pencereme

  gözgöze geliriz,gülümseriz

  bana masallar anlatır,ayaküstü

  bir şarkı söyler,

  sonra,acelesi varmış gibi

  uçar gider...halimi bilmez.', 'Bazen otururum   penceremin kenarına   seyrederim,gelip geçenleri   oynayan çocukları seyrederim Bazen dayanamam   koşar oynarım,çocukların ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/penceremin-kenarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'P e m b e l i m', 'p-e-m-b-e-l-i-m-ahmet-unal-cam-r9fs8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Durakta mısın,otobüste mi

Yoksa,henüz yürüyor musun

Hacettepeden aşağı? 

Yine yüzünde var mı? 

O,dalgın,o hüzünlü hâl

Yine bir arkadaşını görünce

  hafifçe gülümsüyor musun? 

 ...hâlâ seni sevdiğimi

  biliyor musun? 

     *     *     *

Demetevler durağı

Yine kalabalıktır herhalde.

Kimbilir kaç otobüs bekledin.

Doğru söyle,

  hiç aradı mı beni gözlerin

Mahzun duran serserilerde.

     *     *     *

Sen de oturuyor musun

  pencerenin kenarına,

  seyrediyor musun,

  kuşları,ağaçları.

Hüzünleniyor musun? 

  akşamları...

     *     *     *

öyle bir gurbetteyim ki

  sen yoksun.

Bu şehirde rüzğarlar eser

  senin kokunu getirmez.

Kızlar dolaşır caddelerinde

  hiçbiri sana benzemez.

İçim burkulur,baktıklarımda

  seni göremedikçe.

Birikir birikir,kaçar

  yaşlar gözlerimde.', 'Durakta mısın,otobüste mi Yoksa,henüz yürüyor musun Hacettepeden aşağı?  Yine yüzünde var mı?  O,dalgın,o hüzünlü hâl Yine bir arkadaşını gö...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/p-e-m-b-e-l-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(Bosna Şiirleri) Sessiz Olun Müslümanlar Uyuyor', 'bosna-siirleri-sessiz-olun-muslumanlar-uyuyor-ahmet-unal-cam-yib45', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gün hava açık,

      güneş yakıyor

   İnsanlar günlük telaşında,

   Caddelerden akıyor,

      bir o yana,bir bu yana

Bir çocuk gülümseyerek bakıyor! ..

Bosna''da insanlar ölüyor! ..

       *         *         *

   Enflasyon aldı başını gidiyor,

     doğu yine kan gölü

   Meclis tatile çıkıyor! ..

   Haberler aynı; ''-..kadar kişi öldü.''

İçimde bir ateş,beni yakıyor,

Bosna''da insanlar ölüyor! ..

       *         *         *

   Karabağ elden gitti-gidiyor,

   Azerbaycan''da iktidar kavgası,

   Afganlılar birbirini vuruyor,

   Radyolarda ''KASAP'' havası...

Müslümanlar hala uyuyor,

Bosna''da insanlar ölüyor! ..', 'Bu gün hava açık,       güneş yakıyor    İnsanlar günlük telaşında,    Caddelerden akıyor,       bir o yana,bir bu yana Bir çocuk gülümseyer...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bosna-siirleri-sessiz-olun-muslumanlar-uyuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Bırakma...', 'beni-birakma-i-brahim-ethem-bingul-s816k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlamıyorum, bu ne yangındır böyle

Nasıl yaşanır kalpte bu ateşle

Korlara yatırılmış sanki yüreğim

Uykularım haram, küskünüm düşlere...

Biliyorum, zalim zaman gebe

Vuslat ermez saatlere

Bir kalemim bir de göz yaşlarım şahit

Aşkımın tertemiz seyrine...

Taşıyamazsan eğer kor sevdamı sinende

Haber ver, kıyamam bulurum bir çare 

Ama an gelir biterse gücüm, dermanım

Sen beni bırakma çaresiz koma bu yerde...

www.iebingul.com', 'Anlamıyorum, bu ne yangındır böyle Nasıl yaşanır kalpte bu ateşle Korlara yatırılmış sanki yüreğim Uykularım haram, küskünüm düşlere... Bili...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beni-birakma-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşmak', 'kavusmak-esat-erbil-mt5pf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim cananımsan sevgili yarım,

Gözünün vurğunu olmuşum hasta,

Yolun bekliyerek dünyada varım,

Gönlümü şad eyle bırakma yasta.

Bülbül saynadıkça açılır güller,

Aşkımız bir destan konuşur diller,

Gel gir tek dünyama açıktı yollar,

Sana gül topladım deste be deste.

Sevgilim yolunu bekliyen oldum,

Şişe gibi her an boşalıp doldum,

Açılan gül iyken aşkında soldum,

Gel beri cananım asta ahasta.

Söyleyin bekletme güzel bizleri,

Çok ağlattin yeter güldür yüzleri,

Kurun dost yığnağı düzün sözleri,

Çağırsınlar tatlı şarkıyla beste.', 'Benim cananımsan sevgili yarım, Gözünün vurğunu olmuşum hasta, Yolun bekliyerek dünyada varım, Gönlümü şad eyle bırakma yasta. Bülbül saynad...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kavusmak-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığın Korkusudur Aydınlık', 'karanligin-korkusudur-aydinlik-figen-aydogmus-xlcqu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aydınlık arayan ürkütücü karanlık

Asırlardır koşturdun.

Asırlardır omzunda simsiyah bir gökyüzüyle

Savaştın

Artık yoruldun.

Bilki aydınlık senin kavgan

Sen aydınlıkta kaybolursun

Senin dostun geceler

Sen gecelerde huzur bulursun

F.A. 01.02.2006', 'Aydınlık arayan ürkütücü karanlık Asırlardır koşturdun. Asırlardır omzunda simsiyah bir gökyüzüyle Savaştın Artık yoruldun. Bilki aydınlık s...', ARRAY['Türk Edebiyatı','Şiir','Figen Aydoğmuş']::text[], 8.5, '{"poet":"Figen Aydoğmuş","poet_slug":"figen-aydogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/karanligin-korkusudur-aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Gönüle Yeter', 'soyle-gonule-yeter-esat-erbil-3g2uf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söyle gönüle yeter meyli canan etmesin,

Vefasız bir dilbere canın kurban etmesin,

Yar yanağında behar açılmış renk renk güller,

Allahım gülüstanda yağmur tofan etmesin.

Dilber sevdası güneş açar gönül düğünün,

Yeri gönlüm sarayı oyan buyan etmesin,

Aşkı aldı aklımı kast eder öldürmeye,

Tenbih eyle kaşlara başka bir kan etmesin.

Dediler Mecnün aşık ben iysem ondan beter,

Hayatım aydınlıkta birde zindan etmesin,

Sevda şerabın içip (Esat)   behoşla sermest,

Sakısız nola halim yeter hicran etmesin.', 'Söyle gönüle yeter meyli canan etmesin, Vefasız bir dilbere canın kurban etmesin, Yar yanağında behar açılmış renk renk güller, Allahım gülü...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soyle-gonule-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat kel başıma Kakıyor şimdi', 'hayat-kel-basima-kakiyor-simdi-kemal-eyupoglu-xbede', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Varımı yoğumu boşa harcadım

Yokluğa ulaştım,hep adım adım

Birde baktım tamam olmuş saatım

Zaman nehir olmuş akıyor şimdi.

Ne gündüzüm gündüz,ne gecem gece

Mutluluk dilimde üçlü bir hece

Hayat çözülmeyen zorlu bilmece

Beni bilinmeze takıyor şimdi.

Dertler,hayatımın celladı olmuş

Nedendir? çileye ölgün göz yumuş

Bahçeler perişan,güller kurumuş

Bülbül dertli dertli şakıyor şimdi.

Neşeyi kaybetmiş o eski yıllar

Kurumuş çiçekler,kırılmış dallar

Bir avuç kül olmuş bende anılar

Mazi küllerimi yakıyor şimdi.

Bir servi altıdır,gidenin yeri

Artık ben değilim zamanın eri

Yaptığım ettiğim bütün işleri

Hayat,kel başıma kakıyor şimdi.', 'Varımı yoğumu boşa harcadım Yokluğa ulaştım,hep adım adım Birde baktım tamam olmuş saatım Zaman nehir olmuş akıyor şimdi. Ne gündüzüm gündüz...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayat-kel-basima-kakiyor-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkün Kızları', 'turkun-kizlari-esat-erbil-eng73', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağları yüksek havası serin,

Kızları utanç sevdası derin,

Mesut olursun ger alsan birin,

Ne güzel şirin Erbil kızları.

Badam doludur tarlası bağı,

Kızları çiftçi elde orağı,

Kaşları çatma pembe yanağı,

Ne güzel şirin Antep kızları.

Geceyle gündüz safanı sürer,

Kızı şer satar yolunda durar,

Yüz gönül yapar gahte bir kırar,

Ne güzel şirin Kerkük kızları.

Çok serin olur havası dağın,

Eritir inan yürekler yağın,

Boyağ istemez kiraz dudağın,

Ne güzel şirin İzmir kızları.

Saçları uzun gerdeni benli,

Sevdası bela gözleri kanlı,

Babası Sırtlı annesi Vanlı,

Ne güzel şirin Bitlis kızları.

Giyişi renkli hinna ayağlı,

Başında yazma sırma boyağlı,

Geziye çıkar her kim adağlı,

Ne güzel şirin Mardın kızları.

Doğru aşıkın yürdü yuvası,

Her yeri gezdi seçtı Sivası,

Kızın alırsan dertler devası,

Ne güzel şirin Urfa kızları.', 'Dağları yüksek havası serin, Kızları utanç sevdası derin, Mesut olursun ger alsan birin, Ne güzel şirin Erbil kızları. Badam doludur tarlası...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/turkun-kizlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne geçti eline yalnızlıklardan başka', 'ne-gecti-eline-yalnizliklardan-baska-kemal-eyupoglu-fkfml', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar ne çok şendin

				Bende seninle şendim

				Yıllar yılları kovalarken

				Ne mutluluk kaldı senden

				Ne bir eser neşenden.

				Şimdi sormam gerek

				Bırakıp da giderek

				Ne geçti eline

				Yalnızlıklardan başka.

				Bugün sen yaşarken tükenmişliği

				Bana yaşatırken yalnızlıkları

				Ve emanet ederken bana

				Bir ayna ve saçımdaki akları

				Şimdi sormam gerek

				Bırakıp da giderek

				Ne geçti eline

				Yalnızlıklardan başka.', 'Bir zamanlar ne çok şendin 				Bende seninle şendim 				Yıllar yılları kovalarken 				Ne mutluluk kaldı senden 				Ne bir eser neşenden. 			...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-gecti-eline-yalnizliklardan-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Günü', 'bayram-gunu-esat-erbil-0l3gn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne mutlu bayram geldi,

Kalplere neşe saldı,

Gam cefanı unuttuk,

Her kes keyfine daldı.

Erbil''de bayram hoştur,

Düşmanlık sonu boştur,

Kardeşçe mutluluktan,

Gönüller sevgi coştur.

Küsülenler barışır,

Dost dostuna kavuşur,

Ezelden efendilik, 

He bizlere yakışır.

Tophane, Tekiye, Saray,

Karşında Teyrava say,

Sabah nemazdan sonra,

Başlar bizde yeni ay.

Küçük, büyük bezenir,

Süslenip te düzenir,

Evde bayram gününde,

Sohbetimiz uzanır.

Baba bayramlık böler,

Nene, bacılar güler,

Bir yetim güldürüncek,

Gönül sevinçten dolar.

Aşıklar çıkar çöle,

Sarmaşıllar kol kola,

Yar yara kavuşunca,

Rebi mübarek ola.

Bayramnız kutlu olsun,

Günler umutlu olsun,

Gönlüne gam yükleme,

Yüzünüz mutlu olsun.', 'Ne mutlu bayram geldi, Kalplere neşe saldı, Gam cefanı unuttuk, Her kes keyfine daldı. Erbil''de bayram hoştur, Düşmanlık sonu boştur, Kardeş...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bayram-gunu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben seviyordum, sense gidiyordun..,', 'ben-seviyordum-sense-gidiyordun-mehmet-emin-yesilmen-jl44g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(1) 

Günah olmasaydı hiç dururmuydu şarap kadehte.

Bu deli günün kahrında,

Bu isyancıl düşüncelerde,

Ve de bu öfkeli bakışlarımla.

Masumca haykırış..,

(2) 

Kör gecelerde aradım seni,

Zamanın yetmediği mekanlarda aradım,

Bulamadım kalbine giden sesi,

Yol almak istedikçe, yol uzadı,

Bulmak istedikçe, kayboluyordu

Sonu gelmeyen bir uçurum misali,

Hep düşüş vardı..,

(3) 

Seslenen ağızlar yabancılaştıkça,

Bir çocuk daha ölürdü sokakta..,

Dilenciye para verdim,

Günahlardan arınıyoruz diye,

Ama günah olmadım.

Seni sevdim,

Düş kurardık beraber,

Hepside kırmızı oluyordu ve esmere boyardık..,

Nede güzeldi değil mi? 

(4) 

...Ve olmuyordu.

Üçüncü kişiler katletti biliyorum.

Kıskançlık düşmandan beter,

Dost bile gitti.

Sen habersizdin, bense yaralıydım.

Ben seviyordum, sense gidiyordun..,

Ateşler köz, toprak çamur, yüreğim izdiham..,

Haberimi bir satırlarım aldı,

Bir de anılarım..,', '(1)  Günah olmasaydı hiç dururmuydu şarap kadehte. Bu deli günün kahrında, Bu isyancıl düşüncelerde, Ve de bu öfkeli bakışlarımla. Masumca h...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ben-seviyordum-sense-gidiyordun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölme', 'olme-esat-erbil-vpqms', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlatma... Yeter

Sil göz yaşların,

Sana yazıktır 

İçin için ağlamak.

Bir bak gözlerimin içine 

Bütün gizlenen 

Özlemlerimi anlarsın.

Ben sensiz... Yaşayabilmem

Çünkü

Sen...

Benden...

Bir parça olmuşsun.

Ne olur beni yanlız bırakma 

Sensiz ölürüm! 

Gitme o, bir 

Dünyaya

Daha doğrusu 

Bensiz ölme

Benide götür yalnız bırakma

Ne olur gitsen!', 'Ağlatma... Yeter Sil göz yaşların, Sana yazıktır  İçin için ağlamak. Bir bak gözlerimin içine  Bütün gizlenen  Özlemlerimi anlarsın. Ben sen...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaktı Sevdan', 'yakti-sevdan-volkan-i-ncel-q8vqb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gitmeden Telaşı Düştü Gönlüme

Yaktın Beni Yar

Yüreğimi Tutarken Ellerim Kanadı

Gel Yaramı Sar

Bıçakmıydı Sapladığın Kalbime

Yoksa Gidiyorum Deyişinmi Böyle Hoyrat  Delice

Hangi Vicdanlı Yürek Ayırabilirki Yavrusunu Anadan

Kim Saklar Aşkını Aşkından

Nasıl Gider İnsan Devirdiği Bardağı Kaldırmadan

Veya Toplamaz Kırılan Parçaları

Hiç Çıkılırmı Dağılmış Bir Yatak Toplanmadan Odadan

Atılırmı Orta Yere Sevişmenin İzleri

Gece Bile Uykuya Dalmışken Kentinde

Gidilirmi Sevda Boynu Bükükken

Kim Kıyar Taze Bir Fidanı Kırmaya

Sevgiyle Beslenirken Kökleri

Kim Söndürür Yanan Ateşi

Közlendirir Bir Odun Atmaz Altına

İnilirmi Bir Dağdan Karanlıkta Tek Başına

Bırakılırmı Zirvenin Keyfi

Sakladım Gözyaşım Düştü Kalbime

Yıktın Beni Yar

Buz Kesti Bedenim Kırıldı Ümitlerim

Isıt Beni Yar.', 'Gitmeden Telaşı Düştü Gönlüme Yaktın Beni Yar Yüreğimi Tutarken Ellerim Kanadı Gel Yaramı Sar Bıçakmıydı Sapladığın Kalbime Yoksa Gidiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yakti-sevdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-volkan-i-ncel-hg0b0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir,iki,üç,dört öğren dedin

                                                         Altı,yedi öğretmenim

