INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmeyen', 'gelmeyen-nurdan-elver-727og', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elem kokuyordu yalnızlıklarım ilgisizliklerde

Beklenen gelmiyordu.

Oluk oluk kana bulanıyordu gözlerim

Ağlatan gelmiyordu.

Aşk yağıyordu lapa lapa yüreklere

Üşüten gelmiyordu.

Karanlık gündüzlere teslimdim düşüncelerde

Sen gelmiyordun.

Ve çünkü sen gelmeyensin.', 'Elem kokuyordu yalnızlıklarım ilgisizliklerde Beklenen gelmiyordu. Oluk oluk kana bulanıyordu gözlerim Ağlatan gelmiyordu. Aşk yağıyordu lap...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gelmeyen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komşu komşunun...', 'komsu-komsunun-reyhan-tataroglu-8o4gv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sevdiklerini gördüm çok sevindim 

                                        hepsini kendime komşu edindim

                                        sevinçten öleceğim neden mi...

                                        sevdiklerinin sevdiği bir evdim', 'sevdiklerini gördüm çok sevindim                                          hepsini kendime komşu edindim                                     ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/komsu-komsunun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudunu Yitirme', 'umudunu-yitirme-sacide-yaylaz-dx7ai', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnız kalırda bir gün,

  

Özlem dolu,hasret dolu,

Bir yürekle beklersen,

Ha geldi ha gelecek diye 

Yüreğin sıkışır, daralırsa,

Saatler gecmezse,

Umudunu yitiriyorsan,

Sonbaharın rüzgarında,

Savruluyorsa düşüncelerin,

Bir kuşku,sardıysa bedenine,

Seni esir alıyorsa eğer,

Gelmiyorsa beklediğin,

Benim gibi düşle hayal et,

Umudunu yitirme, 

Gelecektir beklediğin....', 'Yalnız kalırda bir gün,    Özlem dolu,hasret dolu, Bir yürekle beklersen, Ha geldi ha gelecek diye  Yüreğin sıkışır, daralırsa, Saatler gecm...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/umudunu-yitirme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tavan arası', 'tavan-arasi-reyhan-tataroglu-h3ff7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sadece nefesin yetti

                                yaşatmaya 

                                şimdi rahatça gidebilirim

                                yatmaya

                                sevdiğini duyunca birden

                                tavana vurdu aklım

                                seni seviyorum

                                ey! 

                                adı bende saklım...', 'sadece nefesin yetti                                 yaşatmaya                                  şimdi rahatça gidebilirim                   ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tavan-arasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerim de Öyle Acizler Yokluğunda', 'siirlerim-de-oyle-acizler-yoklugunda-gul-yazganarikan-8wddb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yolun yolumdur,

Acın, acı’m...

Sevincin, kanattır ruhuma,

Yokluğun yokluktur...

Tüm denizleri ucuca eklesem

Yokluğun etmez...

Uçurumları üst üste koysam 

O uçurumlar ki, yokluğunu tarife yetmez...

Dümdüz bir ovanın ortasında,

Yalnız bir ağaç görsem

O ben olurum... 

Rüzgar vurdukça dallarına

Kendime dokunurum...

Üşürüm...

Bir çöl ortasında

Sensiz kum fırtınasında

O ben olurum...

Savunmasız savrulurum...

Gözlerim görmez benim,

Dilim söylemez senden başka

Kul ne kadar acizce, yüce rabbin yanında,

Şiirlerim de öyle acizler yokluğunda....', 'Yolun yolumdur, Acın, acı’m... Sevincin, kanattır ruhuma, Yokluğun yokluktur... Tüm denizleri ucuca eklesem Yokluğun etmez... Uçurumları üst...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/siirlerim-de-oyle-acizler-yoklugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta Kara Bir Nokta...', 'karanlikta-kara-bir-nokta-ulvi-ziya-2k3sh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Târih denen şu kitap...kaç sayfadan ibâret? ...

Sıksan; sızan kanlardan,acep kaç göl oluşur? ...

İnsanlığın târihi,baştan sona bir vahşet! ...

Başlangıcı,sonu hep gider kanla buluşur...

İlim:aydınlık demek; ferahlık ve rahatlık...

İnsanı sarmalayıp,yücelere götürmek...

Şeytanlaşmış olanlar çıkarırlar fesatlık

Amaç: cennet yolunu uçurumda bitirmek...

İyiyi ve güzeli,faydalıyı bularak

Canlının hizmetine sunmak içindir ilim...

Rabbın kânunlarına her an bağlı kalarak

Nîmetlere ulaşıp,kanmak içindir ilim...

İnsan şeytan birleşip,sınırları çok aştı...

Keşif ve îcatlarda Yaratan''la savaştı...

Zavallı insanoğlu,zavallı cüz''î akıl; 

Patlayan çekirdekten,gönül gözü kamaştı...

Şimdi kördür,sağırdır; uçtuğu yeri bilmez...

Vicdan onu terketti,bir daha geri gelmez...

Eritip ve çürütüp yok etmeyi öğrendi; 

Mikrop saldı dünyâya,artık hiç yüzü gülmez...

Hidrojen bombasını,atom bombasına kat...

Kimyâsal,biyolojik,daha nice bomba at...

Canlıyı yok et kâfir,sırıt,seyret uzaktan; 

Olmayan vicdanınla,için huzurlu,rahat...

Çalışıp,çabalayıp,sarfedip çokca gayret

Gün be gün daha vahşî olan insana,hayret! ...

Güyâ; yönü ışığa,medeniyete doğru

Eylemi:kahır,ölüm ve zulümden ibâret...

Kurtul ey insanoğlu kurduğun bu tuzaktan...

Hep kan,vahşet ve ölüm; bıktın mı yaşamaktan? ...

Uyma kâfir şeytana,kötülüğü emreder; 

Kötülüğe izin yok,icâzet gelmez HAKK''tan...

Târih denen kitaplar...kaç sayfadan ibâret? ...

Sıksan; sızan kanlardan belki tûfân oluşur...

İnsanlık mâcerâsı baştan sona bir vahşet! ...

Başlangıcı sonu hep gider kanla buluşur...', 'Târih denen şu kitap...kaç sayfadan ibâret? ... Sıksan; sızan kanlardan,acep kaç göl oluşur? ... İnsanlığın târihi,baştan sona bir vahşet! ....', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/karanlikta-kara-bir-nokta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hırçın...', 'hircin-avni-aydin-9tp0o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anlamı yok sözlerin, gitmekte kararlıysan bu gece...

ne farkeder ki, hislerimi bilmen? 

ve neden hala bekliyorsun? madem gitmekse isteğin...

ve madem bitmesiyse sözlerin...

kolay mı sanıyorsun susmayı? konuşmamayı...

gideceksin yine de... eminim...

gitme diyecek sanma ama...

gözlerime bakmayı dene bir kere...

engin deniz misali dışarısı senin için.

atılmak istiyorsun dalgalarına hırçın denizinin...

ve ben, limanında hayatın dinlenen kaptan...

sonsuza kadar değildi bu bekleyiş...

sen gidiyorsun bir ucuna ve ben hemen ardından....

karşılaşmayacağız bir daha,

karşılaşmayacağız...

kendine iyi bak denmez ama...

iyi bak işte...', 'anlamı yok sözlerin, gitmekte kararlıysan bu gece... ne farkeder ki, hislerimi bilmen?  ve neden hala bekliyorsun? madem gitmekse isteğin......', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hircin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer…..I', 'rubailer-i-sevinc-kavuk-17apd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sevgiyi tükettiğini anlamadıysa

bu bal çanağı da afiyeti mi olacak? 

Düşlere sığdırılan bir aşk´ı-rüya ki

Günler bile aydın, onun uğruna...

Şubat 2006', 'sevgiyi tükettiğini anlamadıysa bu bal çanağı da afiyeti mi olacak?  Düşlere sığdırılan bir aşk´ı-rüya ki Günler bile aydın, onun uğruna... ...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubailer-i-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni K aybetmek', 'seni-k-aybetmek-i-zzet-orgen-17prc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlıktan ürken bir çocuk gibi

En büyük korkumdur seni kaybetmek

Yalnızca seninle dolu bu kalbi

ikiye bölmektir seni kaybetmek

Sensiz bu hayatın tadı olur mu

Seven sevdiğinden ayrı durur mu

Azrail bendeki beni bulur mu

Ölmeden ölmektir seni kaybetmek

Aldığım her nefes zehrolur bana

Nasıl dayanırım ben yokluğuna

Gözümü kırpmadan kıyarım cana

Beni kaybetmektir seni kaybetmek

              ................

İki şeyden hiç korkmuyorum,

Bir ölümden bir de seni sevmekten...

iki şeyden çok korkuyorum,

Bir Allah''tan birde seni kaybetmekten...', 'Karanlıktan ürken bir çocuk gibi En büyük korkumdur seni kaybetmek Yalnızca seninle dolu bu kalbi ikiye bölmektir seni kaybetmek Sensiz bu h...', ARRAY['Türk Edebiyatı','Şiir','İzzet Örgen']::text[], 8.5, '{"poet":"İzzet Örgen","poet_slug":"i-zzet-orgen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-k-aybetmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''tan Korkmaz Bu Utanmazlar', 'allah-tan-korkmaz-bu-utanmazlar-yusuf-onder-bahceci-2am5k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya malı için kalpler kıranlar,

Üç beş kuruş için yalan kuranlar,

Kâlplerinde olur binbir planlar,

Allah''tan korkmaz bu utanmazlar.

Derim her tarafın aslan olsa da,

Gökyüzünde uçan şahin olsa da,

Dünya malı için hep rezil olsa da,

Allah''tan korkmaz bu utanmazlar.

Senin derdinden dertlere düştüm,

Herkese küstüm de yollara düştüm,

Evel böyle değildim nasılda düştüm,

Allah''tan korkmaz bu utanmazlar.

Ben seni her yerde arar gezerim,

Derdim çoktur benim yürek ezerim,

Yıllar ne çabuk da geçti nasıl ederim,

Allah''tan korkmaz bu utanmazlar....', 'Dünya malı için kalpler kıranlar, Üç beş kuruş için yalan kuranlar, Kâlplerinde olur binbir planlar, Allah''tan korkmaz bu utanmazlar. Derim ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/allah-tan-korkmaz-bu-utanmazlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk’ü Kürd’ü Tev Bırane	Türk’ü Kürd’ü Hep Kardeştir', 'turk-u-kurd-u-tev-birane-turk-u-kurd-u-hep-kardestir-abdurrahman-tepe-iqp7r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hemı dünyayıra dêjım		Tüm dünyaya haykırırım

Türk’ü  Kürdü têv bırane		Türk’ü Kürd’ü hep kardeştir

Hetanê  hetayı bêjim		Sonsuza dek diyeceğim

Türk’ü  Kürdü tev bırane		Türk’ü Kürd’ü hep kardeştir

Em eslı xuda Kürdine		Bizim aslımız Kürd’dür

Dayü babina merdine		Anadan babadan merdaneyiz

Ehlakı me hemidine		Üstün bir ahlakımız var

Türk’ü  Kürdü tev bırane		Türk’ü Kürd’ü hep kardeştir

Türk’ü bağ kurmanc bostanın	Türk’ü bağdır Kürd bostandır

Hımı gülün him rıhanın		Hem güldür hem reyhandır

Hımı canin hım cananın		Hem candır hem canandır

Türk’ü  Kürdü tev bırane		Türk’ü Kürd’ü hep kardeştir

		

Velatı me pırrı xuşe		Vatanımız çok şirindir

İnsan me   zefi geşe		İnsanları hep güleçtir

Dıle düjmin bu ve dêşe		Düşmanın ağrısı bundandır

Türk’ü  Kürdü tev bırane		Türk’ü Kürd’ü hep kardeştir

Yek bedenin nabın cuda		Bir bedendir ayrılmazlar

Qesem dıkım navê huda		Allah adına yemin ederim

Ruhı mın vanara feda		Ruhum onlara fedadır

Türk’ü u Kürdü tev bırane		Türk’ü Kürd’ü hep kardeştir

SAMİHİ ver xerameke		SAMİHİ gel yıkıcı olma

Dini me yek Qulba yeke		Dinimiz bir kıblemiz bir

Dergahı xıra me veke		Bir hayır kapısı açıver

Türk’ü u Kürdü tev bırane		Türk’ü Kürd’ü hep kardeştir', 'Hemı dünyayıra dêjım		Tüm dünyaya haykırırım Türk’ü  Kürdü têv bırane		Türk’ü Kürd’ü hep kardeştir Hetanê  hetayı bêjim		Sonsuza dek diyeceğ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/turk-u-kurd-u-tev-birane-turk-u-kurd-u-hep-kardestir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katlanırım Sanma Ben Yokluğuna', 'katlanirim-sanma-ben-yokluguna-i-zzet-orgen-fe13u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Katlanırım sanma ben yokluğuna

Kendimden daha çok bağlıyım sana

İki ihtimal var, inan ki bana

Sensiz ya ölürüm ya da ölürüm

Sensin hayatımın aşkı dediğim

Canımdan daha çok değer verdiğim

Başka çıkar yolum yok ki sevdiğim

Sensiz ya ölürüm ya da ölürüm

Dört yanım dert dolar dört yanım çile

Yokluğunu anmak kolay mı dile

Belki ecelimle belki elimle

Sensiz ya ölürüm ya da ölürüm', 'Katlanırım sanma ben yokluğuna Kendimden daha çok bağlıyım sana İki ihtimal var, inan ki bana Sensiz ya ölürüm ya da ölürüm Sensin hayatımın...', ARRAY['Türk Edebiyatı','Şiir','İzzet Örgen']::text[], 8.5, '{"poet":"İzzet Örgen","poet_slug":"i-zzet-orgen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/katlanirim-sanma-ben-yokluguna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıbet', 'akibet-ali-kaybal-m27um', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Asil gönlüm, gezen her güzele boyun eğmez,

Güzelliğin olmasa, nazın çekmeye gelmez,

Aşkı hakikatle baş göğe değermiş derler,

Diz bükülür yerinden, yere düşmeye gelmez.

Dermani dertlenir de, hasrete boyun eğmez,

Dillerde dolaşır adı, gizlemeye gelmez,

Sevenler vuslatla erişir, kavuşur derler,

Diliyorum adını, kahır etmeye gelmez.', 'Asil gönlüm, gezen her güzele boyun eğmez, Güzelliğin olmasa, nazın çekmeye gelmez, Aşkı hakikatle baş göğe değermiş derler, Diz bükülür yer...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/akibet-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alın Yazın', 'alin-yazin-ali-kaybal-w5jsn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yakınsın ayna gibi,

Dokun, parmaklarımın ucuna,

Derinsin mana gibi,

Anlaşılmaz yorum yapıldığında,

Gömülü kalırsın, sırların arasına,

Alamam avuçlarımın ortasına,

İhtiyacın olursa eğer, anka kuşuna,

Kapıyı her çalışta, ben çıkacağım karşına,

Yedi kat göğe erer, aşkıma direnme boşuna,

Yalnız, benimle olmak yazılır alın yazına.

Yakınsın kan gibi,

Dolaşırsın damarlarımda,

Uzaksın hayat gibi,

Kalp atışlarım durduğunda,

Gömülü kalırsın toprağın altında,

Alamam avuçlarımın ortasına,

İhtiyacın olursa eğer, fatiha okunuşuna,

Sualine cevap verir her dokunuşuna,

Yedi kat yerin dibi olsa, gideceğim boşuna,

Yalnız, benimle dolaş yazılır alın yazına.

Yakınsın güneş gibi,

Sıcaklığın hissedilir sırtımda,

Uzaksın ışık gibi,

Deniz feneri olduğunda,

Sıkışır kalırsın, duvarların arasında,

Alamam avuçlarımın ortasına,

İhtiyacın olursa eğer, kutup yıldızına,

Birlikte rota tutarız, denizin ortasına,

Yedi fersah mesafe olsa, sığınırım aşkına,

Yalnız, ben yelken açmış olurum alın yazına.', 'Yakınsın ayna gibi, Dokun, parmaklarımın ucuna, Derinsin mana gibi, Anlaşılmaz yorum yapıldığında, Gömülü kalırsın, sırların arasına, Alamam...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/alin-yazin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeridir Yeri', 'yeridir-yeri-hulya-mizrak-58aob', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yarimin gözleri iridir iri

Anası ölmüyor diridir diri

Talibin çoğaldı canım sıkıyor

Seni kaçırmanın yeridir yeri

Özledim sarayım gel beri beri

Benden başkasından kaç geri geri

Anan zenginlere kucak açıyor

Seni kaçırmanın yeridir yeri

Yarim mert sözünün eridir eri

Helal yer alnının teridir teri

Anan fakir diye vermedi bana

Seni kaçırmanın yeridir yeri

Yarim bu canımın canıdır canı

Seni böyle seven hanidir hani

Seni bu zamana vallah komazdım

Evin Jandarmanın yanıdır yanı', 'Yarimin gözleri iridir iri Anası ölmüyor diridir diri Talibin çoğaldı canım sıkıyor Seni kaçırmanın yeridir yeri Özledim sarayım gel beri be...', ARRAY['Türk Edebiyatı','Şiir','Hülya Mızrak']::text[], 8.5, '{"poet":"Hülya Mızrak","poet_slug":"hulya-mizrak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeridir-yeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek', 'bebek-koksal-akar-bm2kf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Savrulsun umutsuz bu yolda cismin,

İstersen büyüme hiç, sonsuza dek

Öksüz kal doğmadan, konmasın ismin,

Kanatsız, duygusuz, hissiz kelebek…

Kalıver hiçliğin derinliğinde,

Hep yaşa, hiç ölme, hür benliğinde.

Issız dünyaların serinliğinde,

Hep uyu hep uyu, büyüme bebek…

Uyanma uykudan, gelmesin bahar,

Yalnızız bu yerde yüreğin kadar. 

Şimdi gönüllerde bitmez telaş var,

Birazdan herkesler sana gelecek.', 'Savrulsun umutsuz bu yolda cismin, İstersen büyüme hiç, sonsuza dek Öksüz kal doğmadan, konmasın ismin, Kanatsız, duygusuz, hissiz kelebek… ...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bebek-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyledikleri Sanki Umurumdamı', 'soyledikleri-sanki-umurumdami-yusuf-onder-bahceci-cs89y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gerçek sevenlere deli diyorlar,

Alay ediyorlar da  deli diyorlar,

Sevdiğin güzelse ne söylüyorlar,

Söyledikleri sanki umurumdamı.

Seni severken sevdiğim derken,

Ayrılık nasıl oldu böyle erkenden,

Aramızda ki yollar hep uzar iken,

Söyledikleri sanki umurumdamı.

Ben seni alacağım sıkı durursan,

İçimde hep sıkıntı mesut olursam,

Gözlerimde yaşlar beni bulursan,

Söyledikleri sanki umurumdamı.

Ne dersem diyeyim inanmıyorlar,

Seni öyle sevdim güvenmiyorlar,

Adamın işi gücü de şiir diyorlar,

Söyledikleri sanki umurumdamı...', 'Gerçek sevenlere deli diyorlar, Alay ediyorlar da  deli diyorlar, Sevdiğin güzelse ne söylüyorlar, Söyledikleri sanki umurumdamı. Seni sever...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soyledikleri-sanki-umurumdami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tavla mı Atsam', 'tavla-mi-atsam-i-zzet-orgen-cuh52', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ruhum daralıyor sen yoksun diye

Ne fayda eder ki feleğe çatsam

Canım sıkılıyor hem ölesiye

Acep hayalinle tavla mı atsam 

Sanki dünya bomboş cehennem dibi

Sensiz yaşamaya nasıl katlansam

Öyle yalnızım ki ölüler gibi

Acep sensizlikle tavla mı atsam

Beklerim ben seni ölene kadar

Gönlümün pasını silene kadar

Sevgilim sen çıkıp gelene kadar

Acep Azrail''le tavla mı atsam', 'Ruhum daralıyor sen yoksun diye Ne fayda eder ki feleğe çatsam Canım sıkılıyor hem ölesiye Acep hayalinle tavla mı atsam  Sanki dünya bomboş...', ARRAY['Türk Edebiyatı','Şiir','İzzet Örgen']::text[], 8.5, '{"poet":"İzzet Örgen","poet_slug":"i-zzet-orgen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tavla-mi-atsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer…..II', 'rubailer-ii-sevinc-kavuk-mqq1v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Berrak Alp´lerin hür havasını

Çıplak bir toprağın ihtirasını

Uyanılacak bir zaaf ihtiyacını

Gizleyen mi yâr idi umar-ı sızı 

Subat 2006', 'Berrak Alp´lerin hür havasını Çıplak bir toprağın ihtirasını Uyanılacak bir zaaf ihtiyacını Gizleyen mi yâr idi umar-ı sızı  Subat 2006...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubailer-ii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oynamak İstemem Yalnızlıkları', 'oynamak-i-stemem-yalnizliklari-i-zzet-orgen-5bnib', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni bırakıp ta gitma sevgilim

Oynamak istemem yalnızlıklları

Halimi perişan etme sevgilim

Oynamak istemem yalnızlıkları

Sensizlik en güzel başrolde olsa

Yüreğim elinden ödülde alsa

Şu koskoca dünya seyrime dalsa

Oynamak istemem yalnızlıkları

Bu sensiz ilk gecem  çıkmaz sabaha

Mavi gökyüzümü çalma siyaha

Ben seni sevmeye doymadım daha

Oynamak istemem yalnızlıkları', 'Beni bırakıp ta gitma sevgilim Oynamak istemem yalnızlıklları Halimi perişan etme sevgilim Oynamak istemem yalnızlıkları Sensizlik en güzel ...', ARRAY['Türk Edebiyatı','Şiir','İzzet Örgen']::text[], 8.5, '{"poet":"İzzet Örgen","poet_slug":"i-zzet-orgen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oynamak-istemem-yalnizliklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek yeterli mi bilmem', 'sevmek-yeterli-mi-bilmem-orhan-kutlu-rv2oh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilemezsin senin için 

İçimden geçen duygularımı

Hala bir pınar gibi

Sevgilerim içimde.

Ve gün geçtikçe taşacak

Bir sel olacak sanırım.

Her an her yerde

Seni arayan gözlerimde.

Belki bilmektesin

Anlamaktasın düşüncelerimi,

Belki sende benim gibi sevmektesin çılgınca.

Belki de farkındasın her şeyin

Tüm hissedilenlerin

Varlığının huzurla doldurması gibi gecelerimi.

Bazen aklından geçer 

Artık eskisi gibi değilsin diye,

Sanırsın bir oyundu

Tüm sana olan davranışlarım.

Ben tüm olanlara karşı

Kayıtsız dururken

Sana anlatmaya yetmez duygumu

Senin olan bakışlarım.

Bilki değişmedim

Hep sevginle doluyum.

Tek korkum her zaman kaybolması

İçindeki coşkunun

Ve bir pişmanlık duygusu 

Yerleşmesi gözlerine,

Sonra sarması benliğini

Mutsuzluk gibi bir kuşkunun.

Bendeki suskunluk

Dile getiremeyişimdir kabuslarımı,

Hepsinin bir hayal ürünü

Olduğunu bilmeme rağmen.

Yine de bir gün bitecek gibi

Bitmesini istemediğim oyunun

Bekliyorum pusuda sevgi ve umut

Henüz taptaze dururken.

Kimse koparamaz yeşerttiğim

Papatyamı gönlümden.

Bilsinler ki onun varlığında

Hayat bulur varlığım.

Bilsinler ki Azrail nasıl 

Vazgeçemezse ölümden,

Daha derin benim

Papatyama bağlılığım.

Sakın yılma hayat kavgalarından

Hepsi gelir geçer,

Sen bana sarıl

Ben sana hiç bir şey bizi yıkmasın.

Seninle güçlüyüm

Sen oldukça atar kalbim, akar kanım,

Sev beni, hep sev

Gönlün asla bıkmasın.

Yakında çok yakında

Her şey daha güzel olacak bekle,

Bilmiyorum mutlu olacakmısın

Seni çılgın gibi sevmekle.', 'Bilemezsin senin için  İçimden geçen duygularımı Hala bir pınar gibi Sevgilerim içimde. Ve gün geçtikçe taşacak Bir sel olacak sanırım. Her ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/sevmek-yeterli-mi-bilmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlar Azalmasa', 'umutlar-azalmasa-adnan-yesiltas-8esjd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar birbirine benziyor

Aylar,

Haftalar,

Günleri bırak...

Ufaldı menzildeki saltanat

Azaldım

Kanat kanat...

Yürümeden aşındı yollar

Yıllar birbirine benzedi.

Ayları,

Haftaları,

Günleri bırak...

Hayatlar birbirine.

Ömürler birbirine

Elimizde bir şey kalmasa da,

Bari umutlar azalmasa.', 'Yıllar birbirine benziyor Aylar, Haftalar, Günleri bırak... Ufaldı menzildeki saltanat Azaldım Kanat kanat... Yürümeden aşındı yollar Yıllar...', ARRAY['Türk Edebiyatı','Şiir','Adnan Yeşiltaş']::text[], 8.5, '{"poet":"Adnan Yeşiltaş","poet_slug":"adnan-yesiltas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umutlar-azalmasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ım Bana Yeter', 'allah-im-bana-yeter-yusuf-onder-bahceci-f0ap3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya malı için rezil rüsvay olamam,

Allah''ı bulmuşum ben onu bırakmam,

Kusura bakmasınlar ondan ayrılmam,

Allah''ım bana yeter ne güzel vekil.

Ben Allah''ın aşkıyla yanar, dönerim,

Adıyla beraber Peygamber derim,

Kalbimdedir ikisi de böyle söylerim,

Allah''ım bana yeter ne güzel vekil.

Benim şiirlerim hep böyle karışıkdır,

Gönül onu sever bunu bil ona aşıktır,

Başka güzel görmez Allah''a aşıktır,

Allah''ım bana yeter ne güzel vekil.

O beni seviyorsa kimse sevmesin,

Bana Kulum desin başka demesin,

İsterse Dünya''da birşey vermesin,

Allah''ım bana yeter ne güzel vekil....', 'Dünya malı için rezil rüsvay olamam, Allah''ı bulmuşum ben onu bırakmam, Kusura bakmasınlar ondan ayrılmam, Allah''ım bana yeter ne güzel veki...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/allah-im-bana-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Te leyli Huu te leyli şan', 'te-leyli-huu-te-leyli-san-ali-riza-unal-dz1my', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Te leyli Huu te leyli şan

1-Bu sahnı cihan,eftal-i hu,te Leyli,te leyli,te leyli ya,

Te leyli,te leyli te leyli Hay, te leyli,te leyli,te leyli Hu,

2 Ya Kahrı külhan ya mesnedi şan.te leyli,te leyli,te leyli şan,te leyli,te leyli.te leyli şan,te leyli,te leyli te leyli şan,

3-Bu bahrı umman,ef’âl-i Hu,te leyli,te leyli te leyli ya,

Te leyli,te leyli te leyli Hay, te leyli,te leyli,te leyli Huu,

4-Ya cêmali can ya neşve-i şan,te leyli te leyli te leyli şan,te leyli,te leyli,te leyli şan te leyli te leyli te leyli şan

5-Bu methi senâ,kevn-i sefa,te leyli,te leyli te leyli ya,

Te leyli,te leyli te leyli Hay, te leyli,te leyli,te leyli Hu,

6-Ya sırat-ı mütâkim Ya meşrebi şan,te leyli,te leyli,te leyli şan,te leyli,te leyli,te leyli şan,te leyli,te leyli te leyli şan,

7-Bu abdi fenâ,beynehûma,te leyli te leyli te leyli ya

Te leyli,te leyli te leyli Hay, te leyli,te leyli,te leyli Hu,

8-Ya mahbubu civan ya cilve-i şan,te leyli,te leyli,te leyli şan,te leyli,te leyli te leyli şan,te leyli,te leyli,te leyli şan..

---      Nakarat    ---

9-Ya leyli şan,ya Suphan,te leyli,te leyli,te leyli,te leyli Hu

Te leyli,te leyli te leyli hu, te leyli,te leyli,te leyli Hu,

10-Ya leyli şan,Ya gufran,te leyli,te leyli,te leyli şan,

Te leyli,te leyli,te leyli şan,te leyli,te leyli,te leyli şan.

-------------------------------------

Bu bir   tasavvufun (vufudur) . Güfte ve bestedir,

Lûfu ilâhi ile Bir hal-i zuhurat üzere hazırlanmıştır

Ehli Arifana ve İnşaAllah tüm insanlığa o Muhammedi

Güzellik musiki  eşliğinde Hazreti Allahın izni ile sunulacaktır her şey zaman-ı ilâhiye rehindir 

suphan Allah  Ya zuhuru cêmâl Ya zuhuru cêlâl.

            Taklidinden Allaha sığınırım.

 Bu   eserin  lûgâtçesi

1  :  te  :   baştan  başa,

2  :  sahnı :  meydan  sahne  gösteri yeri,

3  :  Cihan :  Dünya, kainat, alem,

4  :  Leyli   :   Leylâ (yani leylayı yaratan  güzel Halık) 

5  :  Hu      :  ( o )    Hazreti Allah.

6  :  Eftâl   : teveccüh edilmesi  gereken şey en üstün

      şey  seçenek  gerektiğinde  tercih edimes gereken,

7  :  Ef al  :  fiil, hareket.

8  :  Mesned : dayanacak yer, nokta, makam                   mertebe,destek.

9  :  Şan :   ün, şöhret.

10 :  medh : birisinin iyi vasıflarını söylemek,övmek.

11 :  Sena  : medh ile tarif etmek,medh edip övmek,

12 : kevn :hudus,varlık,var olmak,vucut,alem,kainat,mevcudiyet.

13 :  sefa : neşe ve muhabbet. Sürmek.

14  :  meşreb : Huy,yaratılış,adet, ahlak,gidiş,içmek içilecek yer,feth etmek,manevi haz ve feyz alınınan yer.

15 :  neşve  ( nişve, nüşve)  sevinç,keyif, büyümek,

ve yetişmek,koklamak,rayıha,bir şeyi tekralamak,met ve sarhoş olmak,iyice duyup vakıf olamak.

16 : abdi  :  kul olmak,kul olduğunu bilerek din-i tevhit üzere  ibadet ve tatta bulunmak,

17  :  fena : bekanın zıddı, yok olma,yokluk,geçiçici dünya.dünyadan geçip gitme,kendi varlığından geçmek,kötü.devamlı olmayan,

18  :  beynehûma: ikisi Arasında.

19  : Cilve : Esama-i ilâhinin tecellisi* tecelli, güzellere yakışır duruş ve davranış,diberane haraket,

naz ve edâ,hoşa giden görünüş.

20  Ya Suphan,Hazreti Allahın ,her türlü eksiklikten beri,

uzak. Münezzeh ismi,

21  :  Ya Gufran  :Cenab-ı Hakkın günahları örtmasi,af etmesi.

22  :  ya:ey,hey,

23   :  Hay :  Hazrati Allahın hayat  veren   diri  tutan dirilten   ismi.

Manâ-ı  açıklaması.

1-	bu kainat bu alem  meydanında teveccüh ede bildiğim  ilgi duyduğum  sevdiğim nefesim hep o Leylâ,yani Mevlâ,

 baştanl başa ya Leyla baştan başa hayat veren Leyla baştan başa o mevla

dayanacak yerim tutunucak yerim senin yanın senin şanın ey leylam ey mevlam,

2	: bu deryadan ummana  o leylanın o mevlanın fiiller hareketleri icrada faliyette.

Baştan başa Ya Leyla baştan başa hay Leyla baştan başa o Mevla.

3	Neşve-i şan:sevincim,keyfim,neşem muhabbetim aşkım şevkim senin şanınla,

Ta baştan başa senin şanın baştan başa Leyla

Baştan başa Mevla baştan başa şan.

4 : neşem,sevincim keyfim  idrakim sensin senin şanınla   ben bu hasletlerin bu hallerin  vakıfı  sarhoşuyum senin vasıflarını görmede senin sıfatlarını övmedeyim ey baştan başa leyla  baştan başa ey leyla baştan başa Leyla.

5	 :meşrebim,huyum yaratılışım sığınacak yerim

tununacak yerim, zatına meftun feth olunduğum,ey manevi nazım feyz  aldığım,baştan başa,Leyla baştan başa Leyla,baştan  başa,sanı büyük Leyla

baştan başa,baştan başa,baştan başa Leyla.

6  : bu kulun  senin  zatında yok oldu, beynehûma beni  ikilikten koru iki arada kalmaktan sana sığınırım.

ey şanı yüce mevla her eksiklikten noksandan münezzeh   olan yüce Allahım   baştan başa  sensin baştan başa sensin,baştan başa sensin.

7    :   ey hayatın  yegâne  sahibi ey benim hayat verenim baştan başa sensin,baştan başa leylasın,baştan başa mevlasın.

8    : Ey şanı yüce mevla ey günahları örten af eden

Allahım

baştan başa Leyla,baştan başa Leyla baştan başa Leyla.   Not  : anlayana bu kadarı yeter artar  anlamayana   daha fazla açıklama haramdır zarar verir.  Vesselam. Udi bestekâr:  Ali Rıza Ünal..', 'Te leyli Huu te leyli şan 1-Bu sahnı cihan,eftal-i hu,te Leyli,te leyli,te leyli ya, Te leyli,te leyli te leyli Hay, te leyli,te leyli,te le...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/te-leyli-huu-te-leyli-san-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-orhan-kutlu-ra7to', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerinde gördüm aşkın izini,

Hani senin için yalandı sevmek.

At artık kalbinden sefil mazini

Yorgun gönüllere nimettir sevmek.

Acıyla dolsada gençlik yılların, 

Dayanma gücüdür gönüle sevmek,

Günahkar bir kulu olsan Tanrı''nın

İbadet gibidir aşk ile sevmek.

Yalnızlık ateşi yaksada seni,

Susuz gönüllere yağmurdur sevmek.

Ayrılık belası yıksada seni

Çile dünyasında sabırdır sevmek.', 'Gözlerinde gördüm aşkın izini, Hani senin için yalandı sevmek. At artık kalbinden sefil mazini Yorgun gönüllere nimettir sevmek. Acıyla dols...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmek-142-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydınlatma', 'aydinlatma-sevinc-kavuk-f49pb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seksüel aydınlatma; 

Kendi merakını kendin gider olarak

Mastürbasyonluğun hijiyenlik konumunda

Gençleri sadece başarısız bırakan katı kalbin işlevidir.

Seksi anlayarak yaşamasına dur, kızları sünnet vahşetine devam...

Sabah ayıklığı sadece bir eski sarhoşluktur.

Zerafet budalası bir kadının aynası ama olmalı.

Zerafet budalası bir erkek kendi kendinin aynası.

Geç bakıldıkça her ayna yararsız kalır ama…

Bedeni yıpratmama mantığı yok ama…yazık…

Seksin şeffaflığı daha nice konuşulmalı.

Tıp derki cinsiyet hormonları

Erkekte sperm kadında yumurta gelişmesini 

Tetikleyip üretimini kontrol eder

Bir de kadında estrojen ve progesteron 

Erkekte testosteron gibi hormonlarmış da.

Cinsiyet hoşnutsuzluğu

Cinsel kişiliği ile ilişkili olarak yaşadığı

Ruhsal rahatsızlık anatomik özellikler 

Biyolojik cinsiyetleriyle ruhsal cinsiyetleri arasındaki

Uyumsuzluk duygusu…

Cerrahi, hormonal, kişisel, davranışsal, hukuki islemlerle 

Cinsiyet kazandırılır hatta.

Her bir cinse özgü sabit, basit özellikler

Ve davranış yapılar diye cinsiyet şemasını genişçe

Antropoloji de bol bol inceler

Erkek veya kadın olmanın ne anlama geldiğine üstelik

Bilgiler, inançlar, metaforlar, beklentiler, kurallar gibi

Oluşturdukları bilişsel bu şemada.....

02.02.2006.....Perşembe 16.00', 'Seksüel aydınlatma;  Kendi merakını kendin gider olarak Mastürbasyonluğun hijiyenlik konumunda Gençleri sadece başarısız bırakan katı kalbin...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aydinlatma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü gözler', 'huzunlu-gozler-orhan-kutlu-t8d1c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerime bak,

Ne görüyorsan söyle bana

Ne görüyorsan söyle.

Anlat bana

Ne anladıysan gözlerimden.

Onlar hislerimi benden iyi anlatırlar,

Benim gibi sıkılgan değiller

Ben onlar gibi her şeyi açık söyleyemem.

Bak gözlerime,

Mutlulukda var hüzünde.

Sen yanımdaysan

Mutluluktan güler onlar,

Senin yanında

Seni uzaktan sevmek

Zorunda olduğu için

Devamlı hüzün içindeler.

Ve hep öyle hüzünlü kalacaklar.

Bak gözlerime

Onlar

Aşkımı benden iyi anlatacaklar.', 'Gözlerime bak, Ne görüyorsan söyle bana Ne görüyorsan söyle. Anlat bana Ne anladıysan gözlerimden. Onlar hislerimi benden iyi anlatırlar, Be...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/huzunlu-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram eyledi', 'haram-eyledi-i-brahim-kilinc-315tp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çöllerde dolaştım Mecnun''u gördüm

Cümle aşıklara selâm eyledi

Amasya ilinde Ferhat''ı buldum

Aşka dair birkaç kelâm eyledi

Aslı''nın hasreti yakmış Kerem''i

Aşk getirmiş yeryüzüne veremi

Sevda mı üstündür dedim töre mi

O boynunu büktü kerem eyledi

Yusuf Züleyha''yı gördüm düşümde

Anlattı dinledim kırklı yaşımda

Dedim bir sevda da benim başımda

O da gönlü böyle viran eyledi

Ben onları onlar, beni dinledi

Bendeki aşk ile hepsi inledi

İbrahim sevdayı şimdi anladı

Artık gönle aşkı haram eyledi', 'Çöllerde dolaştım Mecnun''u gördüm Cümle aşıklara selâm eyledi Amasya ilinde Ferhat''ı buldum Aşka dair birkaç kelâm eyledi Aslı''nın hasreti y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haram-eyledi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin olmadan önce', 'ellerin-olmadan-once-orhan-kutlu-ehjxi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen ellerin olmadan önce

Hançer vurmadan yüreğime,

Kör etmeden gözlerimi,

Gönlümü dağlamadan kor ateşlerle

Dudaklarımdan öp beni.

Sen ellerin olmadan önce,

Tükenmeden umutlarım,

Sensiz yaşanacaksa yarınlarım,

Yaşasın diye anılarım,

Yanaklarımdan öp beni.

Sen ellerin olmadan önce,

Bir başkasını görünce,

Kimse almasın diye yerini,

Görmemesi için kimseyi,

Gözlerimden öp beni.

Sen ellerin olmadan önce,

Sakın ardına bakma.

Sodom ve gomorayı görürsün.

Git istediğin hayatı yaşa.

Hadi gitde unut beni.', 'Sen ellerin olmadan önce Hançer vurmadan yüreğime, Kör etmeden gözlerimi, Gönlümü dağlamadan kor ateşlerle Dudaklarımdan öp beni. Sen elleri...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ellerin-olmadan-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir ömür böyle geçer mi?', 'bir-omur-boyle-gecer-mi-nur-demirciler-k1v4d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bunları sadece senin için  yazıyorum,

Sen kendini biliyorsun...

Bir gönül ki bende, sadece 

Beklemede...

Her yanı yalan, her yanı yasaklarla dolu,

Gerçek aşkı beklemede...

Bir ömür böyle geçer mi? 

Diyorum,

Ama inan ki ben de bilmiyorum.

kulağım hep bir sesin,

gözlerim tek bir hayalin esiri,

gönüllü  tutsak herbiri,

ömrümden ömür çalan sevdanın peşi sıra,

koştuğum yollar yorgun,

gözler yorgun, gönlüm yorgun.....

Bugün senin doğum günün, 

Ama ben yine yanında değilim,

aramak istedim seni,

sesini duymak, 

sevdiğimi söylemek,

ama yapamadım işte,

yapamadım yine.

Neler hayal ettim oysa ki.

Bir bardak demli çayı

Yudumlarken birlikte,

Gözlerinde silip hasreti,

Göğsünde uyuyup, uyanmak, 

gülmek, ağlamak...

Aslında tek derdim belkide,

Sevdanın yollarında kendimi unutmak...

05/08//1996

İstanbul', 'Bunları sadece senin için  yazıyorum, Sen kendini biliyorsun... Bir gönül ki bende, sadece  Beklemede... Her yanı yalan, her yanı yasaklarla...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-omur-boyle-gecer-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçünçü Sayfadaki Kadın', 'ucuncu-sayfadaki-kadin-kadir-alanli-szky2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçiyor önümden,hayallerimin kadını

Tenim alev alev, içimde sevda yangını

Önemli değil, bilmesemde adını

Ben sadece, o kadını sevdim

Uzaklara gidiyordu onun treni

Çakır gözleri, uzaklara dalıyordu

Belki beni, hiç görmüyordu

Sevda yazılmış bir roman tutuyordu narin elleri

Sevdaya ait kısa bir romandı

Sonraları bende okudum o romanı

Bir pazar sabahı gazetenin birinde gördüm resmini

Resminin altında okudum bilmediğim ismini 

O artık birkaç sutunluk bi haberdi

Kucakladmış Boğaz köprüsünden atlayarak 

Marmaranın mavisini

                     _Ve hiç bilmediği ölüm meleğini_

Şu resimdeki kadın  dostum benim hayalerimin kadını...', 'Geçiyor önümden,hayallerimin kadını Tenim alev alev, içimde sevda yangını Önemli değil, bilmesemde adını Ben sadece, o kadını sevdim Uzaklar...', ARRAY['Türk Edebiyatı','Şiir','Kadir Alanlı']::text[], 8.5, '{"poet":"Kadir Alanlı","poet_slug":"kadir-alanli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ucuncu-sayfadaki-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısır döngü', 'kisir-dongu-orhan-kutlu-u9g3z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman mı benden ilerde

Ben mi zamanın gerisindeyim.

Her şey akıp gidiyor avuçlarımdan,

Ben zamanın neresindeyim.

Gün doğar aydınlanır,

Gece olur kararır her yer.

Geçen günden başka

Ne kalır elimizde.

O soluk veya canlı hatıralarmı

Ayakta tutan bizi,

Yoksa bilinmeyen sürprizimi

Gelecek günlerin.

Ayaklarım sürüyor beni

Bir o yana bir bu yana

Bilmeden hangi yöne gittiğimi,

Ne düşündüğümü

Ne yaptığımı.

Günden güne ezikliği çoğalıyor içimde

Eridiğini hissettiğim lanet hayatın.

Kısa metrajlı film gibi bitişini

Bir şey anlayamadan sevdasından

Vefasız yar gibi gidişini.

Varlıla yokluk arasındaki çizgimi

Her şeyin sonu veya başlangıcı.

Nasıl başladı bu zulmedici oyun

Şartlar eşit değil taraf tutuyor hakem

Kimi gülerken

Ağladığını görüyorsun kimilerinin.', 'Zaman mı benden ilerde Ben mi zamanın gerisindeyim. Her şey akıp gidiyor avuçlarımdan, Ben zamanın neresindeyim. Gün doğar aydınlanır, Gece ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kisir-dongu-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Kalbim, Durma Söyle!', 'soyle-kalbim-durma-soyle-caglar-asik-2b696', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her nefesimi, alırken

Allah de kalbim, Allah de.

&

Her nefesimi, verirken

Allah de kalbim, Allah de.

&

Hak aşkıyla kor, yanarken

Allah de kalbim, Allah de.

&

Son sözümü, söylerken

Allah de kalbim, Allah de.

&

Ruhum çıkıp, giderken

Allah de kalbim, Allah de.

&

Ölmeden ölüp, yaşarken

Allah de kalbim, Allah de.

&

Bu hor benlikten, geçerken

Allah de kalbim, Allah de.

&

Rızaya ermek, isterken

Allah de kalbim, Allah de.

&

Gözler durmayıp, akarken

Allah de kalbim, Allah de.

&

Özüm çağlayıp, gürlerken

Allah de kalbim, Allah de.

&

Dille söylemek, yetmezken

Allah de kalbim, Allah de.

&

Hasret ateşi, yakarken

Allah de kalbim, Allah de.

&

Binlerce perde, açarken

Allah de kalbim, Allah de.

&

Her an Hak Rahmet, ederken

Allah de kalbim, Allah de.

&

Azaptan korkup, terlerken

Allah de kalbim, Allah de.

&

Şefaat umup, isterken

Allah de kalbim, Allah de.

&

Her an çağrılmak, hep varken

Allah de kalbim, Allah de.

&

Kabirde sorgu, beklerken

Allah de kalbim, Allah de.

&

Hak gün mahşer, yakınken

Allah de kalbim, Allah de.

&

Gizlenmek mümkün, değilken

Allah de kalbim, Allah de.

&

Mahşerde hesap, verirken

Allah de kalbim, Allah de.

&

Sonsuzda gazap, hep varken

Allah de kalbim, Allah de.

&

Sonsuzda huzur, hep varken

Allah de kalbim, Allah de.

&

Hiç durma söyle, coşarken

Allah de kalbim, Allah de.

&

Allah de kalbim, Allah de.

Allah de kalbim, Allah de.

&

İstanbul – 02.02.2006 - Tür: İlahi - Hece: 8

Çağlar Aşık – Söyle Kalbim, Durma Söyle!', 'Her nefesimi, alırken Allah de kalbim, Allah de. & Her nefesimi, verirken Allah de kalbim, Allah de. & Hak aşkıyla kor, yanarken Allah de ka...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/soyle-kalbim-durma-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İçin Neler Verirsin', 'benim-i-cin-neler-verirsin-yusuf-onder-bahceci-0wdj9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben ne yaptığımı iyi bilirim,

Sen ne yaptığını nasıl bilirsin,

Ben senin için cânlar veririm,

Sen benim için neler verirsin.

Bir cânım vardır uğruna güzel,

Kimseleri sevmedim hepsi el,

Yollara çıkıp ta salınan güzel,

Sen benim için neler verirsin.

Aman Allah''ım gözleri güzel,

Sade gözler mi sözleri güzel,

Salınarak gezer öldürür güzel,

Sen benim için neler verirsin.

Seni nerden gördüm güzelim,

Söylermisin şimdi nasıl edelim,

Seni bırakıp ben nere gideyim,

Sen benim için neler verirsin.....', 'Ben ne yaptığımı iyi bilirim, Sen ne yaptığını nasıl bilirsin, Ben senin için cânlar veririm, Sen benim için neler verirsin. Bir cânım vardı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-icin-neler-verirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayacaksın', 'anlayacaksin-orhan-kutlu-ejgp1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tel tel beyazlaşmaya başladığında saçların,

Gözlerinin altına yerleştiğinde

Mor  halkalar

Ve eğilmeye başladığında bulutlardaki başın

Ne demek istediğimi anlayacaksın.

Anlayacaksın ne demek istediğimi,

Bir ayak sesi aramaya

Başladığında kulakların.

Yalnızlık bir kara yılan gibi

Çöreklendiğinde yüreğine.

Ve sıklaşınca ölümü arzuladığın zamanlar

Ne demek istediğimi anlayacaksın.

Bir bir gözlerinin önünde canlanınca anılar,

Damarlarından çekildiğini

Hissettiğinde tüm kanının,

Umut yerine kabus getirdiğini

Gördükçe yarınlarının

Ne demek istediğimi anlayacaksın.

Korkarım geç olacak anladığında bazı şeyleri,

Bir pişmanlık ateşi yakarken

Tüm hücrelerini,

Elini tutacak bir el,

Sığınacak bir kucak aradığında,

Başını koyacak bir diz

Gözlerini silecek bir mendil bulamadığında

Ne demek istediğimi

Bir kez daha anlayacaksın.', 'Tel tel beyazlaşmaya başladığında saçların, Gözlerinin altına yerleştiğinde Mor  halkalar Ve eğilmeye başladığında bulutlardaki başın Ne dem...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/anlayacaksin-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir çocuk görsem', 'bir-cocuk-gorsem-orhan-kutlu-co8sy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir damla yaş görsem

Bİr çocuğun gözlerinde,

Anlarım

Mutluluk yeryüzüne henüz inmemiş.

Bir çocuk görsem,

Elinde sandığı ''boyayalım abi'' diyen.

Anlarım

Adalet yeryüzüne daha gelmemiş.

Bir çocuk görsem

Açlıktan ölmüş bir yerlerde.

Anlarım

Merhamet dünyaya ulaşmamış.

Bir çocuk görsem

Hedef olmuş kurşunlara cephelerde

Anlarım

Sevgi yüreklere daha yerleşmemiş.

Çocuklar ağlarsa,

Çocuklar ölürse,

Dünya ne işe yarar o zaman.', 'Bir damla yaş görsem Bİr çocuğun gözlerinde, Anlarım Mutluluk yeryüzüne henüz inmemiş. Bir çocuk görsem, Elinde sandığı ''boyayalım abi'' diye...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-cocuk-gorsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Bir Abin Var!', 'senin-bir-abin-var-mesut-ozturk-9w1di', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaralar bağlayan, güzel yüzünün,

Üzülmekten ağlayan, zeytin gözünün,

Toplumda dinlenen, tatlı sözünün,

Gururunu taşıyan bir Abin var.

Zorluklarla boğuşsamda,

Hasta olup sararsamda,

Kanser gibi morarsamda,

Arkanda kükreyen bir abin var! 

Seninle ağlayan seninle gülen,

Mutlu olman için dualar eden,

Gurbette heran hasretin çeken,

Seni düşünen ve seven bir abin var! 

Acıyı çekmek kolay, ayrılıklar olmasa,

Arada gülmek kolay, aşka isyan olmasa,

Arayıp bulmak kolay,aptallıklar olmasa,

Herşeye inan dostum seninde bir Abin var!', 'Yaralar bağlayan, güzel yüzünün, Üzülmekten ağlayan, zeytin gözünün, Toplumda dinlenen, tatlı sözünün, Gururunu taşıyan bir Abin var. Zorluk...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-bir-abin-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezberimdesin', 'ezberimdesin-reyhan-tataroglu-gsp2s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kitap gibi birşey seni okumak

                   heyecan vermediğin yerde bırakabilirim

                   sadece fihristine de bakabilirim

                   bir imla dahi yapsan hata 

                   çatır çatır yakabilirim', 'kitap gibi birşey seni okumak                    heyecan vermediğin yerde bırakabilirim                    sadece fihristine de bakabilirim ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ezberimdesin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar', 'yillar-mehmet-ayhan-gunaydin-m0r8p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'YILLAR

Yazık! bir su misali hızla akıyor yıllar.

Elimize kalansa, yalınız hatıralar.

M. Ayhan Günaydın

2 Ocak 2006

Ankara', 'YILLAR Yazık! bir su misali hızla akıyor yıllar. Elimize kalansa, yalınız hatıralar. M. Ayhan Günaydın 2 Ocak 2006 Ankara...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yillar-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rulet (Ey Hayat)', 'rulet-ey-hayat-metin-yuksek-p4hak', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eskimiş askerlik anıları gibi

Sıktı canımı bu hayat.

Tozlu rüzgarların kirpik acısı gibi,

Battı gözlerime,battı lanetler.

Prangaları bu dertlerin

Nefres borumda paslandı.

Yaprakları döküldü ümitlerimin

Yeşilliklerim şiirlerimde kaldı.

Beraberimde taşıdıklarımın aşkları

Depresyon ağaçlarında sallandı.

Ey hayat,gel son kez daha vur,

Alnımın çatında bir ruhum kaldı..! 

Çıldırmış duyguların boş şarjörüne

Tek bir kurşun gibi koydum hayatımı.

Ey hayat,cesaretin varsa gel rulete,

Ya sen vur ya ben vurayım hayatımı.', 'Eskimiş askerlik anıları gibi Sıktı canımı bu hayat. Tozlu rüzgarların kirpik acısı gibi, Battı gözlerime,battı lanetler. Prangaları bu dert...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/rulet-ey-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiir Gerçek Olacak - 2', 'bu-siir-gercek-olacak-2-metin-yuksek-xo0q7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün gelecek,

Korktuğumuz dert bataklıklarını kurutacağız.

Kurtulacağız ey sevgili balçık ayrılıklardan.

Bir gün gelecek kavuşacağız.

Bir gün gelecek ey sevgili,

Hasret türkülerinin acı notalarını duymayacağız.

El ele,göz göze,kalp kalbe oturup

Kendi şarkımızı yazacağız.

Bir gün gelecek ey sevgili,

Sen ve ben bir şarkı olacağız.

Hülyalarımızın dalgalarından

Islanmış koyların üzerine

''Seni seviyorum.'' yazacağız.

Bir gün gelecek ey sevgilim,

Bu hülyalarımızı gerçeklere yazacağız.

Bir gün gelecek ey can,

Güvercinler uçuracağız Kaf Dağı''na

Ayaklarına mektuplar bağlayarak.

Bir güngelecek,

O güvercinler bize cevap getirecek

Kanatlar çırparak...

Bir gün gelecek ey sevgili,

Ben senin kollarında öleceğim,

Sen de benim kollarımda.

Mutluluktan,huzurdan...

Kum saatleri bizim için hiç ters dönmeyecek.

Rüzgarı ters esmeyecek evlilik şanslarının.

Korkacağız tabi zaman zaman,

Ama dudaklarını biz uçuklatacağız korkuların.

Ölümsüzlüğünün sırrını bulacağız kadim huzurların.

Ruhlarını ellerinden alacağız kapkara acıların.

Sen ve ben el ele vereceğiz,

Aşk''ın ebediyetine gideceğiz yarınlarımızın.

Bir gün gelecek,

Kelepçelerini çözeceğiz mahkum mutluluklarımızın.

O kelepçelerle

Özgürlüğümüzü bağlayacağız alınyazımızın.

O gün gelecek sevgili,

Hiç canın sıkılmasın...

Yanında ben yoksam,

Bu benim suçum değil,senin de...

Sakın asi olma kadere bizi ayırdı diye! 

İsyan etme sakın ona! 

Çünkü bizi birleştirecek,

Bizi evlendirecek,

Bizi mutlu edecek kader,aynı kader! 

Kar taneleri gibi eriyecek yüreklerimiz ellerimizde.

Bir polen gibi uçuşacak bakışlarımız gözlerimizde.

Bir güneş doğacak her zamanki gecenin üstüne,

Ama bu güneş can bulacak ışıksız bedenimizde.

Bu şiiri okurken ey sevgili,

Elini yüreğinin üstüne koy n''olursun! 

Kapat gözlerini,

Beni düşün,

Beni iste yanına...

Ama öyle boş boş değil,

Allah''a yakarırcasına..!', 'Bir gün gelecek, Korktuğumuz dert bataklıklarını kurutacağız. Kurtulacağız ey sevgili balçık ayrılıklardan. Bir gün gelecek kavuşacağız. Bir...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/bu-siir-gercek-olacak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutların Uç Noktası', 'umutlarin-uc-noktasi-metin-yuksek-xrijo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sigara dumanı kıvamında şimdi zaman.

Nihayetini bulmuş göz yaşları ellerimde; 

Artık göz yaşı değil gözlerimden akan..! 

Sancılı geceleri şimdi uykusuzluklarımın.

Kocaman bir boşluk taşıyorum hayallerimde; 

Doldurmak için uç noktasındayım umutlarımın..! 

Yeni filizlenmiş ayrılık ağacının çiçeklerinden,

İçime kadar işleyen zehir gibi bir koku.

Ellerimde tohumlar taşıyorum aşk çiçeklerinden,

Kalbimin topraklarında açmaz diye bir korku.

Sessizliğin evinden yükseliyor şimdi çığlıklar,

Sessizliğin kalbine adını çaktığımdan beri.

Yokluğun vuruyor iki şakağının ortasından aşkımı,

Ama bekliyor sessizce kavuşacağımız günleri.', 'Sigara dumanı kıvamında şimdi zaman. Nihayetini bulmuş göz yaşları ellerimde;  Artık göz yaşı değil gözlerimden akan..!  Sancılı geceleri şi...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/umutlarin-uc-noktasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerin Sahile Vurduğu Gece', 'siirlerin-sahile-vurdugu-gece-metin-yuksek-7dtcs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlığı sokaklara kusturacak bakışlarımla,

Gök yüzünün siyah ceketinin iç cebine

Işık tohumları ektim bu gece...

Bu gece en hasretli gece şimdi bana,

Bu gece şiirlerin sahile vurduğu gece...

Yokluğunda daralıyor tüm sevinçlerim.

Sensizliği tarif edecek hiç bir kavram,

Hiç birşey yok hayatımda.

Tarifsiz bir sızı sensizlik! 

Hoş tarifi olsa ne olurdu ki,

Ben yine de ağlardım..! 

Bir bütünün içinde paramparça herşey.

Darmadağın duygular içinde

Seni düşünüp toparlanmaya çalışıyorum.

Olmuyor be kelebeğim,

Dayanamayıp ağlıyorum..! 

Bu ağlama göz yaşı değil,

Mendille silinmez bu ağlama.

Bu ağlama en hüzünlü türkü,

En dertli ağıt bu ağlama.

Yokluğunun bestesini çalıyor şimdilerde

Yüreğimin tellerindeki bağlama...

Bu gece en hasretli gece bana şimdi,

Bu gece şiirlerin sahile vurduğu gece...', 'Yalnızlığı sokaklara kusturacak bakışlarımla, Gök yüzünün siyah ceketinin iç cebine Işık tohumları ektim bu gece... Bu gece en hasretli gece...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/siirlerin-sahile-vurdugu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosun Tutan Kirpikler', 'yosun-tutan-kirpikler-metin-yuksek-jaw57', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir mum ışığı gibi sarılmış odama hasretin,

Ne bir sedâ ne de bir nûr sohbetçi bu gece bana.

Ellerimde kırık ayrılıkların faturası

Ve bir sinir krizi de ruhumu ele geçirmiş sanki! 

Sazları kırılasıca arbeks müzikler

Hiç girmediği kadar girdi bu gece içime.

Bayılttığım özlemlerimin ayılacakları tuttu birden,

Baktılar ki gelen giden yok özlenen yerden

Onlar da terk etti bu gece beni...

Bir yılan gibi çöreklenmiş içime hasretin,

Ne bir şiir ne de bir anı sohbetçi bu gece bana.

Gözlerimde bir manzara var hayalen; 

Güzel gözlü bir kız çocuğu kadar şirin,

Işığın dans ettiği su kadar zarif,

Yaprağına su damlamış gül kadar narin...

Yokluğunda avutmaya çalıştıkça hayallerle kendimi,

Gerçekler cellat oldu bana her gece...

Islak gözlerim yosun tutturunca kirpiklerimi,

Mendiller diken oldu bana her gece...', 'Bir mum ışığı gibi sarılmış odama hasretin, Ne bir sedâ ne de bir nûr sohbetçi bu gece bana. Ellerimde kırık ayrılıkların faturası Ve bir si...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yosun-tutan-kirpikler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gidince...', 'sen-gidince-metin-yuksek-c9tjs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...Sen gidince,

durdu rüzgar...

Kırgınım şimdi yollara,

Kızgınım da.

Seni benden alıp götüren

Şu hasretin tam ortasına

Kazık çakasım var..! 

Kafiyesizim; 

Şiir yazamayacak kadar! 

Hasretin öyle ağır ki bebeğim,

Taşınacak gibi değil sahtekar!', '...Sen gidince, durdu rüzgar... Kırgınım şimdi yollara, Kızgınım da. Seni benden alıp götüren Şu hasretin tam ortasına Kazık çakasım var..! ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-gidince-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Adam', 'yagmur-adam-metin-yuksek-scimx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tutunmuş sallanıyorum bulutlarda,

Yalnızlığın mecburiyet caddesine

Damla damla yağıyorum.

Bu arada türkü çığırıyorum; 

Bulutlardan düşen yalnız adamın türküsünü...

Kaldırım taşlarına adımlarımı tapulamışım sanki,

Bu sokağın adı mühür gibi işlemiş aklıma.

Sen gitsen de bu sokaklardan ciğ tanem,

Ben seni gezdirmeye devam ediyorum inadına.', 'Tutunmuş sallanıyorum bulutlarda, Yalnızlığın mecburiyet caddesine Damla damla yağıyorum. Bu arada türkü çığırıyorum;  Bulutlardan düşen yal...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yagmur-adam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorumsuz!', 'sorumsuz-mesut-ozturk-4h6y4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duymuyorsun biliyorum bağırsamda, 

Hissetmiyorsun sevgilim diye haykırsamda, 

Sevgin bitmiş ardından senelerce koşsamda, 

Unuttuğunu itiraf et de umutlanmayayım ben. 

Ne yapacakın sorumluluk bilmeyen bu herifi, 

Kart basmaktan baska yokki marifeti, 

Para bilmez tutum bilmez geri zekalı

Sana layık olmak için bir fırın ekmek lazım. 

Baba olmuş evlat kıymeti bilmez, 

Verdigi sözler hep yalan sözüne güvenilmez, 

Seni yarı  yolda bırakan bu salağa, 

Kapıyı göstersende kimse günaha girmez. 

Kızmıyorum sana beni sevmiyorsun diye, 

Umudu kesilmiş iflah olmayan bu öküze, 

Değer verme sakın, at bu salağı denize, 

Sana layık olamadım adım çıktı zaten kerize.', 'Duymuyorsun biliyorum bağırsamda,  Hissetmiyorsun sevgilim diye haykırsamda,  Sevgin bitmiş ardından senelerce koşsamda,  Unuttuğunu itiraf ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sorumsuz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En güzel yolculuktu', 'en-guzel-yolculuktu-nazan-i-zmirli-b97q0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gün.....................  yorgunluğunu

unuturken  akşamın  koynunda

hasretin.................... düşmüştü

al  al   yanaklarıma...................

yüreğim  en  güzel yolculuk da

dualar  ediyorum   mırıl    mırıl

avazım   çıktığı   kadar 

sesleniyorum   tanrıya

kavuştur   beni  sevdama

bastıkça  basıyorum  gaza

pedaller  uçuyor  tabanlarımda

yüreğim   çırpınıyor

vadiye  özgürce   uzanan  nehrin

çağlayan   dalgalarında

yollar   uzadıkça   uzuyor

kıvrım   kıvrım   kıvranıyor

bedenimden   farksız

dağların   eteklerinde

limon  çiçekleri 

ferahlığında

yeşiller  fışkırmış   taşlarda

seninle  gelen  baharlarla

akşam  alacası  griye  dönüştürürken

vadiyi,  dağları,  kayaları, ormanları

zirvelerde   parça  parça   karları

korkuyla   karışık 

sevdamı    kutsuyorum

cesur   yüreğimle 

en  güzel   yolcu  ve   yolculuk diye......

akşamın   nemi

çınarların   esintisi 

kokunu   taşıyordu

çekiyordu  zor dik yollar

gizemine     kavuşmanın

an   an   endişe 

titretiyordu   içimi

sıtmalı  gibi

ateşler  sarıyor  bedenimi

virajlara   girip  çıktıkça  yükselen 

ardıçların   büyülü    fısıltısı

bir  adım  bir  adım  daha  ileri

ay   ışığı    üzerindeydi

siluetini  gördüm  heybetli

açmıştın  kollarını

belli! 

sen de  özlemiştin  beni

en uzun

en  zor

en  güzel  yolculuktu

yüreğimin  götürdüğü 

beni sevdama

gece  ıssız, sessiz, yıldızsız  olsada

buz  tutsada  parmak uçlarımız,  burnumuz

nefes almak....................

huzurun  en  güzel  adıydı

yanında............................

en  güzel  yolculuk 

sana  varan  yollarda

02.02.2006-antalya', 'gün.....................  yorgunluğunu unuturken  akşamın  koynunda hasretin.................... düşmüştü al  al   yanaklarıma.................', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/en-guzel-yolculuktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Çok Özledim', 'seni-cok-ozledim-metin-yuksek-z0i82', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Açtı gözünü papatya,uyandı rüzgar.

Esiyor şimdi de yalnız tepe,

Ve işte günaydın diyor güneş...

Ne güzel bir dünya diyorum kendi kendime.

Tebessüm konuyor uykulu yüzüme.

Pencereleri açar açmaz çam kokusu...

Güzel bir kahvaltıda sıra şimdi.

Allah ne verdiyse; 

Peynir,zeytin,kızarmış ekmek...

Rüyamda bizi görüp uyanınca,

Sabahlar bu kadar güzel oluyormuş demek...

Vakit öğle şimdi...

Bu güzel başlayan gün bir madalyonsa eğer,

Yavaş yavaş arka yüzünü göstermeye başlıyor! 

Yüzümdeki tebessüm kanatlanmaya hazır,

Ne kadar çabalasam da çiçeğim,

Yokluğun sevinçlerime hançerler batırır..! 

Olmuyor sevdiğim sensiz olmuyor işte! 

Kendimi kandırmayı başarsam bile,

Özlemin yokluğunu

Bir tokat gibi yüzüme,

Bir bıçak gibi yüreğime,

Bir kurşun gibi aklıma vuruyor..! 

Seni çok özledim çiçeğim,

Halâ senli kanım kalbime akıyor..!', 'Açtı gözünü papatya,uyandı rüzgar. Esiyor şimdi de yalnız tepe, Ve işte günaydın diyor güneş... Ne güzel bir dünya diyorum kendi kendime. Te...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-cok-ozledim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-metin-yuksek-w4ild', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İner aşkın sırları,

Bütün yücelikleriyle göklerden.

Sızlar ellerim ellerin yok diye...

''Neden? '' diye sorgulayacakken tam ayrılığımızı,

Aşk lugatından ''neden'' i çıkardılar..! 

Lanet olsun tam vaktini buldular...', 'İner aşkın sırları, Bütün yücelikleriyle göklerden. Sızlar ellerim ellerin yok diye... ''Neden? '' diye sorgulayacakken tam ayrılığımızı, Aşk ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/neden-216-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-metin-yuksek-7362t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buraların toprağına gurbet yağar,

Toprağında filizlenir efkar.

Ey gözüne kurban olduğum yar,

Al da beni buralardan kurtar.

(Öğretmen olarak atandığım mezradaki ilk gecemin anısına...25/09/02)', 'Buraların toprağına gurbet yağar, Toprağında filizlenir efkar. Ey gözüne kurban olduğum yar, Al da beni buralardan kurtar. (Öğretmen olarak ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yar-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda!', 'elveda-mesut-ozturk-gh16s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitmek istiyorum buralardan sakince,

Acaba benide arayan olur mu? 

Kaybolmak istiyorum inceden inceden,

Acaba benide özleyen olur mu? 

Yaşım 30, hayatta 30 gün gülemedim,

30 yılda sevgilimi biran olsun sevemedim,

Bırakıpta ortalarda yavaş yavaş ölemedim,

Yarın gitsem beni soran olur mu? 

Ne yaptıysam gözünüze giremedim,

Ne ettiysem kadir kıymet bilemedim,

Seni sevdim canım gülüm diyemedim,

Bugün ölsem ağlayanım olur mu? 

Sevdiklerim dinleyin; Sizlere sesleniyorum,

işte şimdi hayatınızdan çekiliyorum,

Zaman geldi ben buradan gidiyorum.

Elveda dostum diyen olur mu?', 'Gitmek istiyorum buralardan sakince, Acaba benide arayan olur mu?  Kaybolmak istiyorum inceden inceden, Acaba benide özleyen olur mu?  Yaşım...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/elveda-203-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ata sözleri', 'ata-sozleri-salih-yilmazgil-ngdxf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İyilik et ki, iyilik mi bulasın,

Yoksa; 

Besle de kargayı,

Gözünü mü oysun? 

''Acele işe şeytan karışır''

Derken biri,

Üsküdarı geçivermiş, atı alan.

İyi adam sözünün üstüne gelirse de,

Sen sopayı kap,

İti anınca.

Işıldarmı demir işledikçe? 

Lezzetlenirmi şarap yıllandıkça? 

Bunları da iyisimi,

Fahişelere sorun.

Danışan dağlar aşmış,

Ya bildiğini okuyan...

Muradına ulaşmış.

Hele danışan düşünmeden,

Atanın dediğine,

Ayakları dolaşmış eteğine.', 'İyilik et ki, iyilik mi bulasın, Yoksa;  Besle de kargayı, Gözünü mü oysun?  ''Acele işe şeytan karışır'' Derken biri, Üsküdarı geçivermiş, at...', ARRAY['Türk Edebiyatı','Şiir','Salih Yılmazgil']::text[], 8.5, '{"poet":"Salih Yılmazgil","poet_slug":"salih-yilmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ata-sozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cavap Bekler!', 'cavap-bekler-mesut-ozturk-1213k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlayan gözler, titreyen eller,

Her zaman Mevla`dan bir cevap bekler.

Tutmayan diller, şevkli gönüller,

Duası için Mevla`dan bir cevap bekler.

Derdin büyüğü göllerde yüzen martısıyla.

Kaderin acısı ovada otlanan kuzusuyla,

Yanan seneler kalpteki Mevla aşkıyla,

Kabulü için Mevla`dan bir cevap bekler.

Keremiyle ovalarda, Ferhatıyla dağlarda,

Yunusuyla çöllerde, Bayramıyla bağlarda,

Aşk ile şevk ile inanın bağrında,

Yaraların gitmesi, Mevla`dan bir cevap bekler.

Akan şelalelerde, söylenen dileklerde,

Yanan bağırlarla, kan ağlayan gözlerde,

Ağızda Allah, kıvranan gönüllerde,

Kavuşmak için Mevla`dan bir cevap bekler.', 'Ağlayan gözler, titreyen eller, Her zaman Mevla`dan bir cevap bekler. Tutmayan diller, şevkli gönüller, Duası için Mevla`dan bir cevap bekle...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cavap-bekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözün Özü', 'sozun-ozu-sadik-altinkaynak-62hmh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sözün Özü

Sözün en makbulü kısa  olandır

Çok söz ya hatalı ya da yalandır

Kişi ister binlerce söz söylesin

Önemli olan akılda kalandır

Bir sözü kalıcı kılan tekrardır

Hani denir ya “Et-tekraru ahsen”

Yani tekrarda güzellikler vardır

Velev kâne -meğer olsa- yüz seksen

Alimi söyleten derin ilmidir

Cahilse ukalalıktan konuşur

Alim kişi usul erkân yol bilir

Cahilin dilinin perdesi yoktur

Sohbet etmek istersen mert ile et

Namerdin sözünün faydası yoktur

Merdin dostluğunda olmaz ihanet

Namerdin ölçüsü kaydası yoktur

                        Sadık ALTINKAYNAK', 'Sözün Özü Sözün en makbulü kısa  olandır Çok söz ya hatalı ya da yalandır Kişi ister binlerce söz söylesin Önemli olan akılda kalandır Bir s...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sozun-ozu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziranda Terketme', 'haziranda-terketme-mehmet-kahraman-crwlq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'HAZİRANDA TERKETME

Menekşeler ağlamasın

Dökülmesin yapraklar sen giderken

Dalgalar dövünmesin

Deniz kumsalına küsmesin

Yeniden uyansın yorgun kuşlar

Ağaçlar yeniden baharı beklesin

Güller solmasın zamansız

Daha vakit erken

Kardelenler cemreyi beklesin

Hiç olmazsa  bahar gelsin

Sen benden giderken

……………

Mum alevine dönmesin umutlarımız

Gece çekilmez bir karanlık olmasın

Soğuk gecelerde ısıt ruhumu

Kırık bir ezgi kalsın geriye

Hiç bestelenmemiş,bestelenmeyecek olsun

Ayaz vurmasın yağmur gülünü

Bahar gelmeden solmasın

Umutlarım haziran gelmeden bitmesin

……………

Kuş sesiyle uyansın sabahlar

Rotasını kaybetmiş turnalar

Cıvıl cıvıl bir şarkı bestelesinler

Kır çiçekleri yine hüzünle devinsinler

Fesleğenler kokunu kıskansın ne çıkar

Kokunu alıp götürmesin rüzgar

Gözlerinle bir resim çiz gözbebeklerime

Gözlerimde izi kalsın

Sen benden giderken

Gözlerin gözlerimi terk etmesin

Düşlerle bulutlara karışıp

Gök kubbeye bir sevda yazalım

Adı aşk, soyadı umut olsun

Hüzünlerim  yine gözyaşı olsun

Mevsimler bir bir akıp gitse de

Ne olur beni haziranda terketme….

         Mehmet  KAHRAMAN', 'HAZİRANDA TERKETME Menekşeler ağlamasın Dökülmesin yapraklar sen giderken Dalgalar dövünmesin Deniz kumsalına küsmesin Yeniden uyansın yorgu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kahraman']::text[], 8.5, '{"poet":"Mehmet Kahraman","poet_slug":"mehmet-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/haziranda-terketme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göç Hüzünleri', 'goc-huzunleri-mehmet-kahraman-mlw69', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GÖÇ  HÜZÜNLERİ

Yolcusuz yollar bilirim

Sonsuzluğun bittiği yerde başlayan

Ruhtan ruha giden yollar

İnce bir hüzünle kıvrılır 

Şehir yine örtünür geceyi

Vakit ölüm uykusunda 

Kırlangıç ormanlarına gitti ay

Mehtapsız gece ne karanlık

Hasretin gurbeti soğuk üşütür

Üşür güneşini yitiren bahar

Zor sevda göçüdür bu sürgün

Dil suskun,kalp küskün

Bırakma beni vefalı dostum hüzün

Bu acıyı nasıl anlatmalı tek hecede

Hangi yalnızlık sığınak bulur gecede

Kaç umut dayanır sabaha

Kaç yıldız kayar sevdasına

Kaç ömür düşer göç yollarına

…………

Özlemin soğuk düşü üşütür

Üşür göç yollarında unutulan anka kuşu

Ay tutulur,vakit yorulur,söz çırpınır

Göç yolları ince bir hüzünle kıvrılır

Buruk bir veda dayanır kapımıza

Hüzzam makamında çarpar

Okyanus dalgası gibi kalbimiz

Yağmur gülünün sancısı gibi

Tedirgin saat ibresi gibi ürkek

İki satır arası şiir gibi

Bilinmez bir göç hüznüdür

Kalpten kalbe gidişin adı

……………

Karanlıklar boğsa da geceyi

Yıldızların tuvaline çizdim mutluluğu

Karanlıklarda parlayan mavi yıldızdın

Samanyolu şöleninde sen vardın

Gelincik dokunuşunda ellerin

Kırlangıç senfonisi gülüşün

Baktıkça açan gül yüzün

Baharın çiçek açması bu sürgün

Kalp ağrılarımın sebebi ey sevgili

Dar geçitleri sarp dağları 

İnceden kıvrılan yolları

Mecnun olup aşarım senin için

   

Mehmet  KAHRAMAN', 'GÖÇ  HÜZÜNLERİ Yolcusuz yollar bilirim Sonsuzluğun bittiği yerde başlayan Ruhtan ruha giden yollar İnce bir hüzünle kıvrılır  Şehir yine ört...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kahraman']::text[], 8.5, '{"poet":"Mehmet Kahraman","poet_slug":"mehmet-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/goc-huzunleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Kokusunda Kaybetmek', 'gul-kokusunda-kaybetmek-mehmet-kahraman-tdcse', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GÜL  KOKUSUNDA KAYBETMEK

Yükü ağırdır sevginin

Rüzgar ıslığı umuttur gecede

Türküler hüzün söylerken

Mızrap tellerimize vurur inceden

Hayatın kıyısına düşeriz bazen

Demir atmalı köhne limanlara

Ellerinden tutar gibi sevgilinin

Sığınmalı yaban bir yalnızlığa

………………

Uzaklık ve yollar kesişir

Kaybetmenin gizemli öyküsünde

Kimileri cebindeki varlığını

Kimileri sıcacık yuvalarını

Kimileri umutlarını,düşlerini,aşklarını

Kaybetmek yorgun düşürür insanı

Hayat yorgunudur kaybedenler bilirim 

…………………

Ayrılıklar kavuşmaktır belki

Yollara ansızın düşen trenler gibi

Bir otobüs camından sevgilinin

El sallayarak son kez bakışı gibi

Belki seher vakti bir damla gözyaşı

Belki ardıç kuşunun son kez kanat çırpışı

Bu sözler  kaybetmenin hüzünlü şiiri

Gölgelerin karanlıklarda kayboluşu gibi

Şehrin dar  sokaklarında kaybettik

Umutlarımızı ve sevgilerimizi

……………………

Kalıcı insanların  yerini, 

Gelip geçen  insanlar almış

Etrafımızı sanal kalabalıklar kuşatmış

Duygusal doyumsuzluk  sunulmuş

Kin ve nefretler  yağdırılmış

Bir sevgisizlik  yaşıyoruz derinden

Mahrum kaldı insanlık sevgiden

……………………

Oysa gülün kokusunda bulmuştuk

Umudu,aşkı ve sevgiyi

Sevgi tohumu kalbe düşerdi eskiden

Bire bin verecekti  umutlarımız

Yağmur yağar gökkuşağıyla dönerdik

Bir daha yaşanmayan resimler çizerdik

Arka sokaklarda telaşsız dolaşırdık

Gözlerin ışıltısını  yorumlardık

Her goncaya bir sevda yazardık

Oysa biz sevgimizi hiç satmadık

Mehmet  KAHRAMAN', 'GÜL  KOKUSUNDA KAYBETMEK Yükü ağırdır sevginin Rüzgar ıslığı umuttur gecede Türküler hüzün söylerken Mızrap tellerimize vurur inceden Hayatı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kahraman']::text[], 8.5, '{"poet":"Mehmet Kahraman","poet_slug":"mehmet-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/gul-kokusunda-kaybetmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Dua', 'beyaz-dua-derin-oger-w0yn8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dünya denen şu gezegen

yaprağıma ışığını damlatırken

ben papatyayaydım sen yediveren

mevsim mi başkaydı

mutluluğu ve sevinciyle dağ tepe deprem

mantığımı parmak uçlarımda gezdiren

benzerin mi yoktu

ampullerin ışığı sen yanardın rengi çınar

ince belli bardaklara sen dolardın koyu kırmızı çay

sendin dağlardan yüksek

kanat çırpıp kıyısına sığındığım gökyüzü

saçlarımı tarayan rüzgâr avuçlarımı ısıtan güneş 

aktın dünyanın öbür yanına

şarkılarda kirpiklerimi kavuran mısra 

romanlarda gözyaşı sen doldun gözlerime

suçlu bizim mevsimimizdi

ay büyürken  yıldızları söndürdü

madımak ebegümeci ne varsa toprağımda öldü

sustu sevda içime çömeldi

içim ise karlara özenen yanardağ

dudaklarımdaki beyaz bir dua ya  al sürer..', 'dünya denen şu gezegen yaprağıma ışığını damlatırken ben papatyayaydım sen yediveren mevsim mi başkaydı mutluluğu ve sevinciyle dağ tepe dep...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/beyaz-dua-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Ben!', 'yine-ben-mesut-ozturk-hrfvy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anası varken, ana sıcaklığını özleyen ben,

Babası varken, yetimliğin acısını çeken ben

Kardeşleri varken, Dünyada yanlız kalan ben.

Sevgilisi varken, sevmeyi, sevilmeyi, arayan ben.

Yavruları varken, Evlatlarım tiye ağlayan ben.

Dost tekmesi yeyipte, geride kalan yine ben.

Boşverdim artık gülmeyi, sevmeyi ve yaşamayı,

Neler çekmişim sanki onlara tasa mı? 

Gidilen bir yol, yaşanan gerçekler var,

Anladım artık bu Dünya bana gerçekten dar,

Aradım sordum gidemedim gidecek bir diyar,

Herkese elveda! Başaramıyorum benden bu kadar.', 'Anası varken, ana sıcaklığını özleyen ben, Babası varken, yetimliğin acısını çeken ben Kardeşleri varken, Dünyada yanlız kalan ben. Sevgilis...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yine-ben-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Tanrısal Bir Dokunuş..', 'ask-tanrisal-bir-dokunus-senol-alaca-gec4p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aşk tanrısal bir dokunuş, 

bir kayboluş hikayesidir kendi sokaklarında; 

onca iyi bildiğin yada bildiğini sandığın......

çoğunlukla kendinsindir dönüp dolaşıp sonunda vardığın.

yalnız olduğunu düşünsende 

davetsiz bir hayal getirmişsindir peşinde

her şiirde, şarkıda can bulan...

ve çok sevmiş olmanın getirisi olan o hayal gitmeyecektir bir daha

ne fayda kovsan....

aşk tanrısal bir dokunuş, 

sevginin bir tecellisidir kainat''da.

kimi bir hayaldir dikilir karşında

kimi bir serçe kanadındadır, 

kimi çisil çisil yağan yağmurda

hani ıslanırken altında kendini mutlu hissettiğin.....

işte bu yüzden dünyanın bir tanesidir sevgilin 

işte bu yüzden daha bir güzeldir baharlar,kışlar 

bu yüzden üşümezsin sevdiğini beklerken, elinde çiçekler

ve üstüne lapa lapa yağıyorken karlar...

canını verirsin de bakmaya doyamadığın gözlerine 

dünyaları verseler değişmezsin bir tek gülüşüne. 

değişebiliyorsan zaten paraya pula

vah sana  vahlar sana...

bir tebessümle uyanırsın yatağından yeni güne

sebebini bilmediğin

tanrının eli değip geçmiştir de yüreğinin bir köşesine

asıl budur farketmediğin.....

ama nasıl olur bilinmez bir gün aşk gider 

bazen düşersin ardı sıra yollara 

bazen koşacak gücün yoktur peşine de 

sadece ve öylece bakakalırsın gidişine..... 

bazen onun hatasıdır bazen senin 

bazen herikinizin bazense hiçkimsenin

işte bu ''son''dur.

iyisimi sorularada gerek yoktur

zaten tanrı bile bırakıp gitmiştir seni kaderine.

isyan edersin sevdiğine seveceğine bugününe yarınına....

oysa hiç düşünmezsin  sevgi vardır her hücrende 

hatta atomunda

sevgi ve aşk vardır evrenin varoluşun da

ve varoluş başladığı gibi son bulacaktır ''yaradan'' da

o ''yaradan''ki

sana kendini hatırlatmış 

varoluşun sırrını anlatmıştır bir ölümlünün gözlerinde.

ve yolu göstermiştir özüne çıkacağın yolculuğunda

belki sen bilememişsindir bu hediyenin değerini belki o

belki herikiniz (BENCE)   belkide hepimiz.....

işte budur eksiğimiz,

işte bu yüzden hep bir parça eksiğiz....

kendimizi sevmekten başlayarak çıkmalı yola

ve el ele yürümeliyiz 

omuz omuza

çoğala çoğala..

bir bakmışsın ifade edilemiyoruz.ne binle, ne milyonla

hep beraberiz...... 

hiç kesmedim ümidimi gelecek o günler

sevgiyi, aşkı gerçek anlamıyla öğreneceğimiz...

işte o vakit bölünemeyiz 

ne sekizden dörde, ne dörtten ikiye.

şimdi özüne dön ve yer aç yüreğinde sevgiye....

şunu asla unutma

varoluş sevgidir  temelinde

aşk tanrının dokunuşu yüreğinde...

ve yine işte bu yüzdendir 

sevgi,aşk alınıp verilebilecek en özel hediyedir.', 'aşk tanrısal bir dokunuş,  bir kayboluş hikayesidir kendi sokaklarında;  onca iyi bildiğin yada bildiğini sandığın...... çoğunlukla kendinsi...', ARRAY['Türk Edebiyatı','Şiir','Şenol Alaca']::text[], 8.5, '{"poet":"Şenol Alaca","poet_slug":"senol-alaca","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/ask-tanrisal-bir-dokunus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüz Çeviriyorum', 'yuz-ceviriyorum-erdogan-ergin-hcihk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'içim burkuluyor

içimden tüm yuttuklarım

tek tek dökülüveriyor

en kızdığım anda

onca içe atmalar boşuna

boşuna düşüncelerimi saklayışım

aç ağzını yum gözünü

ne geliyorsa aklına

iki kere düşün bir kere de söyle gitsin

kırılacaksa kırılsın insanlar

ne var yani

daha mı değerli benden? 

içimdeki hislerden

yüz çeviriyorum

beni üç kuruşluk sevenlere

laf cambazlığı ile övenlere

kem sözlerini ekmeğime doğrayanlara

ben de yok, size bakacak surat

al kalemini, sil defterinden, at', 'içim burkuluyor içimden tüm yuttuklarım tek tek dökülüveriyor en kızdığım anda onca içe atmalar boşuna boşuna düşüncelerimi saklayışım aç ağ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yuz-ceviriyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atılmışım Ben', 'atilmisim-ben-fatih-donmez-slo5u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayalin görünür her an odada

Hasretin yakıyor uzak sılada

Sanarsın evimi ıssız bir ada

Köşeden köşeye atılmışım ben

Sen gittin gideli dinmiyor acım

Dertlerle beraber başımda tacım

Yastalar halime üç tane bacım

Acılar içine atılmışım ben

Yaşlandım yüzümün her yanı çizik

Zorladım düzelmez artık bu fizik

Yerlere vurdular eziğim ezik

Rüyadan seraba atılmışım ben

Acılar yüzüme çizik ekleken

Kalbimle birlikte bende teklerken

Gözümde yaşlarla seni beklerken

Aylara, yıllara atılmışım ben

Sessiz Ölüm', 'Hayalin görünür her an odada Hasretin yakıyor uzak sılada Sanarsın evimi ıssız bir ada Köşeden köşeye atılmışım ben Sen gittin gideli dinmiy...', ARRAY['Türk Edebiyatı','Şiir','Fatih Dönmez']::text[], 8.5, '{"poet":"Fatih Dönmez","poet_slug":"fatih-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/atilmisim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülçin', 'gulcin-tarik-yasin-p9vse', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ümitlerin içimde hayallerin umut dolu olsa da hep kaldı! ! ! ! 	

Lanet olsun bu güzelliğe inan ben bunu mu isterdim! ! ! ! 

Çaresiz kaldım inan ki elimde değil di seni benden alan bu şeytandı! ! ! ! 

İnan seni sevdiğime pişman değilim hep sevdiğime kaldı! ! ! ! 

Nefret beslemedim adına hep kaldı ama sonunda seni benden aldılar ama hep içimde kaldı! ! ! ! 



                                                                                Tarık yasin Özdemir

                                                                                                       

Hep adı kaldı ama kendisi evlendi ama şimdi bir evlat bekliyor…………..

Daha ne yapayım ben demir attım yalnızlığa çıkarsan çıkmaz çünkü elimden alan arzu……

Oda beni seviyordu ama bilmezdi ki benim onu sevmediğimi elimden aldı gitti……

Arzu evlendi sonra veya önce GÜLÇİN yani AŞKIMI DA aldı gitti elini bile tutmadım daha..

Ama ne oldu ikisi de evlendi bense her gece 24.00’de 1 geçe yalnızlığa itiliyordum…

Hala itiliyorum en aradığımda telefonu bile açtığında bana dedi Tarık kim dedi sonra beni…

Tanıyınca cız etti numaramı nasıl aklında kaldı dedi bende kalbimde dedim hadi canım…

Dedi ama oysa ki en acı olan onun evlendiğini söylediğinde oldu birde dedi ki bir….

Bir kızım mı desem veya oğlum hatırlamıyorum çünkü artık mutluydu ama…..

En acısı ikisi de evlenmisti artık ne yaparım ben bunu duyunca…

Dedim ki inşallah mutlu olursun sonra kapattım…………………….

Ama şunu bilmez bir tek benim kaldı gene de sensizliğe hazırım…

Nerelere gidiyim bilmiyorum ama inanıyorum ki ben o boşansa da benim onu tekrar ne….

Olursa olsun onu kabul ederim işte bunu bilmez….

Ama hiç öpüp beni sarmadı bir kere bile olsun ellerimi ellerine deymedi…………

Sessiz kaldım bunları yazdığımı bilse benim onu sevdiğime hala inkar ederdi…………

                                                                                      Güneş doğmadı ama hep battı

                      Artık doğmuyor ki çükü demir attım ama o demir hep bende kaldı çeken olmadı

     Çünkü  okyanusun derinlilerinden kim asılacaktı…. 

Anılar bitmedi hep kaldı kalıyor ama boşa beklemişim ne oldu hayal ve eseri kaldı o gitti…..

  	 	Ben kaldım ortada bunu hala anlamıyorsa benim ümitlerim nerde kaldı…..

Çıkaran olmadı hep kaldı adı aklımda artık nereye gitsem adı Gülçin insanlara bakıyorum....

Ama unutamıyorum çünkü her gece 1 geçiyordu ama gün daha doğmadı ki gelsin aradan tam bu yıl 5 yıl doluyor……………….

                        BeNi uNuTmA……….', 'Ümitlerin içimde hayallerin umut dolu olsa da hep kaldı! ! ! ! 	 Lanet olsun bu güzelliğe inan ben bunu mu isterdim! ! ! !  Çaresiz kaldım i...', ARRAY['Türk Edebiyatı','Şiir','Tarık Yasin']::text[], 8.5, '{"poet":"Tarık Yasin","poet_slug":"tarik-yasin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gulcin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-hasan-tahsin-azatli-4rvup', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün biter, hayat devam eder,

Varolmanın coşkusu sarar 

Seni umarsızca

Arzular içten içe sonsuzluğu

Başkalaşımın anlamsızlığı

Seni de alır götürür

Buradan çok uzaklara

Kendinden ve geçmişten

Ne arkana bakarsın ne önüne

Anı yaşamaya devam ederken

Gün gelir habersizce

Hayat biter gün bitmeden', 'Gün biter, hayat devam eder, Varolmanın coşkusu sarar  Seni umarsızca Arzular içten içe sonsuzluğu Başkalaşımın anlamsızlığı Seni de alır gö...', ARRAY['Türk Edebiyatı','Şiir','Hasan Tahsin Azatlı']::text[], 8.5, '{"poet":"Hasan Tahsin Azatlı","poet_slug":"hasan-tahsin-azatli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-298-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil ki..', 'bil-ki-senol-alaca-ui9y1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yüreğim bir deli okyanus bugünlerde 

kimi dingin sakin

fırtınalar kopuyor kimi zaman

işte o an 

bilki seni düşünüyorum

yüreğimde çalıyor orkestra bugünlerde

hüzün ve neşe iç içe tüm seslerde

kimi nabzımın atış ritminde kimi bir gitar eşliğinde

bizim şarkımız dökülüyorsa dudaklarımdan 

işte o an 

bilki seni düşünüyorum

yüreğim bir ressamın tuvali bugünlerde

beyaz senli zamanları söylesede 

siyah yokluğuna sitemde

biraz dudağının kırmızısı biraz gözlerinin yeşili çıkıveriyorsa fırçamdan

işte o an 

bilki seni düşünüyorum

yüreğime koca bir evreni sığdırdım bugünlerde

yıldızlar yanıp sönmekte

içlerinden biri kayıp giderken umarsızca gökyüzünde

tuttuğum dilek başkası değilse adından 

işte o an

bilki seni düşünüyorum

bütün insanları bir başka seviyorum bugünlerde

bir çocuğun tebessümündesin

yaşsın ağlayan bir diğerinin gözlerinde 

herşeydesin herkeste ve heryerde

senden bir parça taşıyor sanki herinsan 

itiraf ediyorum işte nihayetinde 

farketmiyor artık zaman ve mekan 

bilki seni düşünüyor

bilki seni istiyor 

bilki seni seviyorum

hemde herAN', 'yüreğim bir deli okyanus bugünlerde  kimi dingin sakin fırtınalar kopuyor kimi zaman işte o an  bilki seni düşünüyorum yüreğimde çalıyor ork...', ARRAY['Türk Edebiyatı','Şiir','Şenol Alaca']::text[], 8.5, '{"poet":"Şenol Alaca","poet_slug":"senol-alaca","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bil-ki-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fakih', 'fakih-reyhan-tataroglu-vnejx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yol uzun 

                                mevzuu upuzun 

                                azığın aşk

                                ile çıkındaki tuzun', 'yol uzun                                  mevzuu upuzun                                  azığın aşk                                 ile çıkı...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/fakih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Aşkımı', 'ben-askimi-necati-keceli-yijv8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbimdeki aşkın sevgin bitmiyor

   Ben nasıl anlatsam, sana aşkımı

   Harfler kelimeler, buna yetmiyor

   Ben nasıl anlatsam, sana aşkımı

   Aşkınla kanadı kırık bir kuşum

   Yaşam kaynağımdır, hayalim düşüm

   Tatlı bir sevdaya kalmıştır başım

   Ben nasıl anlatsam, sana aşkımı

   Gözlerinden bakış gider derine

   Ateş düşer kalbin, orta yerine

   Bağlanır kalırım, aşkın şer’ine

   Ben nasıl anlatsam, sana aşkımı 

   Uzaktan bakarım, saçın teline

   Yüreğim yanıyor, değsem eline 

   Sürüklenip gittim sevda yeline

   Ben nasıl anlatsam, sana aşkımı

   Yüzlerim kızarır, gülücük atsam

   Ellerim titriyor, elini tutsam

   Sabahlar olmuyor rüyasız yatsam

   Ben nasıl anlatsam, sana aşkımı

   Kalbimi para pul, mutlu etmiyor

   Hayalin beni terk, edip gitmiyor

   Gözlerine baksam, içim titriyor

   Ben nasıl anlatsam, sana aşkımı

   Necati KEÇELİ

   ADANA', 'Kalbimdeki aşkın sevgin bitmiyor    Ben nasıl anlatsam, sana aşkımı    Harfler kelimeler, buna yetmiyor    Ben nasıl anlatsam, sana aşkımı  ...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-askimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç ve gece', 'agac-ve-gece-levent-i-skenderoglu-81i1e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ruhum sarmaş dolaş 

Ruhuna, ince

Dudakların hayalim 

Gözlerin düşüm

En nazik yerinden 

Kopsun bir yıldız 

Aşkıma şahit olsun 

Ağaç ve gece', 'Ruhum sarmaş dolaş  Ruhuna, ince Dudakların hayalim  Gözlerin düşüm En nazik yerinden  Kopsun bir yıldız  Aşkıma şahit olsun  Ağaç ve gece...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/agac-ve-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Kafalı', 'geri-kafali-asik-turhani-092um', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alımlı bir hatun geldi evime

Saçları örülüydü geride

Dedim buda nedir mübarek günde

Dedi sen anlamazsın geri kafalı

Küpe takar gezer kulağında

Pantolonun kemeri inmiş kıçına

Allık sürüştürmüş yanaklarına

Sosyete böyledir ey geri kafalı

Uğradım sosyete mahallesine

Dedim erkek takarmı kulağa küpe

Dediler o hıyar durur kuaförde

Zamane böyledir ey geri kafalı

Turhani''em zamaneye sordum

Sonra cevabı onlarda buldum

Dediler özentidir bu durum

Hala bana der durur geri kafalı

akdenizin parlayan yıldızı Aşık Turhani-ANTALYA', 'Alımlı bir hatun geldi evime Saçları örülüydü geride Dedim buda nedir mübarek günde Dedi sen anlamazsın geri kafalı Küpe takar gezer kulağın...', ARRAY['Türk Edebiyatı','Şiir','Aşık Turhani']::text[], 8.5, '{"poet":"Aşık Turhani","poet_slug":"asik-turhani","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/geri-kafali-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niçin', 'nicin-mehmet-rizaoglu-inclh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şiir yaptım,uyurken ölenler için

Uyurken okunmuyorsa,boş verin, geçin', 'Bir şiir yaptım,uyurken ölenler için Uyurken okunmuyorsa,boş verin, geçin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Rızaoğlu']::text[], 8.5, '{"poet":"Mehmet Rızaoğlu","poet_slug":"mehmet-rizaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/nicin-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-mesut-yokus-ujw77', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak! Diyorum, göremezsin

Gözlerin çok uzaklarda 

Çağırıyorum, seslenmezsin

Hıçkırığım kayıp sokaklarda

Annem, haykır duan gelsin

Bitsin elem, solsun matem

Kucakla, sarsın sıcak nefesin

Üşüyorum acımaz sağnaklarda

Mesut Yokuş

-1998-', 'Bak! Diyorum, göremezsin Gözlerin çok uzaklarda  Çağırıyorum, seslenmezsin Hıçkırığım kayıp sokaklarda Annem, haykır duan gelsin Bitsin elem...', ARRAY['Türk Edebiyatı','Şiir','Mesut Yokuş']::text[], 8.5, '{"poet":"Mesut Yokuş","poet_slug":"mesut-yokus","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anne-195-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenlerin Ardından', 'gidenlerin-ardindan-erkan-kocak-d65i2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapattım da gözlerimi

Yürürken sırtıma atlaman geldi gözlerimin önüne

El şakalarımız, göğsüme başını yaslayıp hayal kurmaların

Sonra servise binip gitmen geldi de gözümün önüne 

Utandım birden yanağımda beliren tebessümden

Nasılda eğdi başımı önüme hüznün

Neden sen gidince önce ellerin geliyor aklıma

Sonra eşlik ediyor saçlarının yokluğu boğazımdaki düğüme

Yanağımdaki damla özletiyor dudaklarını

Şimdi öpsene boynunun sol tarafından benim için

Ama önce mutlaka saçlarını topla sağ elimle

Gözlerime bakmayı unutma sakın

Mektup yaz diyorsun bana sitemle

Bana sevgini yaz, mutluluğu sevdanı yaz diyorsun

Nasıl sığdırayım birtanem

Dünyalara sığdıramadığım sevgimi küçücük bir zarfın içine

Nasıl kıyıp da hapsedeyim sıradan bir kelimeye

Gözlerini düşünürken duyduğum huzuru

Peki kalbimi koysam zarfın bir köşesine

Oturup da seğredermisin kendini aynaya bakar gibi', 'Kapattım da gözlerimi Yürürken sırtıma atlaman geldi gözlerimin önüne El şakalarımız, göğsüme başını yaslayıp hayal kurmaların Sonra servise...', ARRAY['Türk Edebiyatı','Şiir','Erkan Koçak']::text[], 8.5, '{"poet":"Erkan Koçak","poet_slug":"erkan-kocak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidenlerin-ardindan-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir güzelce gelirsin', 'bir-guzelce-gelirsin-sevket-yucel-whrbq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabah şarkılarının kıvraklığında

Ak kanatlı umutlarla gelirsin

Limon çiçeklerine dönüşür günler

Unutulur silahların adı

Geçmiş zamanların bir yerinde

Yapraklarında sözlüklerin

Süzülür durursun turnalar gibi

Uygarlığın en sevilen yollarından

Barışlarla gelirsin

Yaylalara sökün eder keklikler,.

Güneşle toprağın sevilerinde

Bir duman olursun ipince

Sen uçar sen uçarsın sevdiğim

Yaz gülüşü kirazlarla gelirsin

Söğüt gölgeleri düşer sulara

Taşların üstünde oğlaklar oynar

Savrulur dağlarda uzun saçların

Menekşeler sümbüllerle gelirsin', 'Sabah şarkılarının kıvraklığında Ak kanatlı umutlarla gelirsin Limon çiçeklerine dönüşür günler Unutulur silahların adı Geçmiş zamanların bi...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-guzelce-gelirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Vitesi Yok Hayatın', 'geri-vitesi-yok-hayatin-muzaffer-cura-kgg0p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi mi dünyan? 

yoksa toz pembe mi? 

bilmiyorum.

bir sorular yumağı kafan.

Gözlerinde,

güzel günlere gebe bu gülümseyiş.

En güzel davetiye gözlerin,

gözlerini okuyabilen insana..

Sen ki; bir ayağı sürekli frende

bir şoför gibisin....

Boş ver be gülüm..

Geri vitesi yok hayatın.

Salıver yüreğini,

o yapar gereğini...', 'Mavi mi dünyan?  yoksa toz pembe mi?  bilmiyorum. bir sorular yumağı kafan. Gözlerinde, güzel günlere gebe bu gülümseyiş. En güzel davetiye ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Cura']::text[], 8.5, '{"poet":"Muzaffer Cura","poet_slug":"muzaffer-cura","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/geri-vitesi-yok-hayatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bela', 'bela-cafer-yilmaz-vudw0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yerdemisin, göktemisin? 

Kırk kapılı yerdemisin? 

Bir gün olsa gelse sesin...

Hay Allah belanı versin..! 

Ele avuç avuç verdin.

Bizemiydi cimriliğin? 

Nedir bana duyduğun kin? 

Hay Allah belanı versin..! 

Bunca yıldır körebeydim.

Hayat boyu ebeledin.

En sonunda ben tükendim.

Hay Allah belanı versin..! 

Kara kışa mahkum ettin.

Ele güne mahcup ettin.

Sonunda da verem ettin.

Hay Allah belanı versin..! 

Bir sel gibi akıp gittin.

Volkan gibi yakıp gittin.

Ve nihayet toprak ettin.

Hay Allah belanı versin..!', 'Yerdemisin, göktemisin?  Kırk kapılı yerdemisin?  Bir gün olsa gelse sesin... Hay Allah belanı versin..!  Ele avuç avuç verdin. Bizemiydi ci...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bela-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzellikler satıyorum ben', 'guzellikler-satiyorum-ben-sevket-yucel-sfion', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ücretsiz bir satış yerim var benim

Bilseniz ne kadar zengin

Ama içinde hiçbir eşya yok satılacak

Güzellikler satıyorum ben yalnız

Görüşmeyi dilerseniz benimle

Adresim sevgi mahallesi

Sokağım dostluk

Ararsanız orada bulursunuz beni

Bana gelirseniz birgün

Konuğum olursunuz

Söyleşiriz beyaz beyaz

Siz bende olursunuz, ben sizde

Sevda kadehli sözcüklerimle

Şiirler sunarım size.', 'Ücretsiz bir satış yerim var benim Bilseniz ne kadar zengin Ama içinde hiçbir eşya yok satılacak Güzellikler satıyorum ben yalnız Görüşmeyi ...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/guzellikler-satiyorum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şudur istediğim sizden', 'sudur-istedigim-sizden-sevket-yucel-85fox', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sizler dostluk yüklü, sevecen ve incesiniz

Kuşlar da sever sizi ağaçlar da

Çok sıkıldım size geldim işte

Bana bir gülüş verir misiniz

Öderim güldüğümde

Bir acı ki içimdeki

Eksik kalıyorum nereye gitsem

Şu kısacık yaşamda öksüz kalmış sevinçlerim

Bana biraz sevinç verir misiniz borca

Öderim sevindiğimde.', 'Sizler dostluk yüklü, sevecen ve incesiniz Kuşlar da sever sizi ağaçlar da Çok sıkıldım size geldim işte Bana bir gülüş verir misiniz Öderim...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sudur-istedigim-sizden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar', 'anilar-sevket-yucel-44lns', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah, bu anılar

Ne kadar kapasam da kapılarını

Ne kapı dinliyorlar ne pencere

Süzülüp geliyorlar yılların gerisinden

Anılar ki

Kimi mavi, kimi beyaz

Kimi sarı, kimi siyah

Mavilerle beyazları çekiyorum yanıma

Gidin diyorum sarılarla siyahlara

Giderler mi hiç

Yıllar sisli, yıllar duman duman

Ne sisi dinliyorlar anılar ne de yılları

Ah, bu anılar

Öylesine sayısız, öylesine çeşitli

Birike birike geliyorlar

Çoçukluğumdan beri

Anılar çoçuk, anılar genç, anılar yaşlı

Acılarla, sevinçlerle, hüzünlerle yüklüdürler.', 'Ah, bu anılar Ne kadar kapasam da kapılarını Ne kapı dinliyorlar ne pencere Süzülüp geliyorlar yılların gerisinden Anılar ki Kimi mavi, kimi...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anilar-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erken Bahar Badem Ağacı', 'erken-bahar-badem-agaci-metin-soydeveli-1gwck', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevda dediğin bir badem ağacı

Her an damarlarında doğum sancısı

Açar çiçeklerini erkenden

Aldanır en ufak sıcak bir bakışa

Verir müjdeyi sevdalara erkenden 

Bazen yeni yılın ilk gününe varmadan

Bilmez, bu uyanışlar erkendir sevdaya

Sürüp gitmez  ılık ılık sevda günleri

Aldanır, dayanamaz, duyarlıdır sühunete

Buzda olsa bile

Sevda ile çağla, ikisi de sabırsız  erkenci

Sevda  renginde çiçekleri, beyaz, pembe

Aşkın zamanı belli değil, 

Her an patlamaya hazır tomurcuk

Henüz geçmedi  Kocakarı Soğukları

Hoyrat poyrazlar, ardından  gelecektir zemheri 

Açarız ağaç ağaç, dal dal, çiçek çiçek

Poyraz yangını nedir bilmeden

Kavrulup gideceğiz, düşeceğiz dallardan

Çağla olamadan içeklerimiz, gün görmeden

Hayallerimiz de pembe, düşlerimiz de

Hadi o duyumsadı sıcaklığı

Anlayamadım ne buldum sende

Düşürdünüz bizi soğuğunuzun tuzağına

Mecalimiz kalmadı, düştü çiçeklerimiz hepsi yerde

Biliyordum bu erken hevesti

Erken uyanıştı sevdaya 

Tutunamadı düşlerimiz, hayallerimiz de

Dallarına sıkı sıkı; pembe pembe

Estirdin sert poyrazları zalimce

Düştü çiçeklerimiz, şimdi hepsi yerde

Ah tutunabilseydik, kalabilseydik dalda

Verecektik mevsimin ilk meyvesini, çağla', 'Sevda dediğin bir badem ağacı Her an damarlarında doğum sancısı Açar çiçeklerini erkenden Aldanır en ufak sıcak bir bakışa Verir müjdeyi sev...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/erken-bahar-badem-agaci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgu', 'sorgu-turgay-soyuguzel-3wdo7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni sormayın bana.

Kendimi tanımıyorum.

Kim oldğumu öğrenince.

Terkedeceğim bu şehri.

Bu yorgun bedeni.

Sürgün aşklar yaşamışım ben.

Ayrılıklar ve acılar.

Ama hiçbir acı sonsuza kadar değildir.

Ve bu acı elbet birgün  bitecek..', 'Beni sormayın bana. Kendimi tanımıyorum. Kim oldğumu öğrenince. Terkedeceğim bu şehri. Bu yorgun bedeni. Sürgün aşklar yaşamışım ben. Ayrılı...', ARRAY['Türk Edebiyatı','Şiir','Turgay Soyugüzel']::text[], 8.5, '{"poet":"Turgay Soyugüzel","poet_slug":"turgay-soyuguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sorgu-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teknoloji', 'teknoloji-cemal-simsek-38hgh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne engeller aştık aşk uğruna,

El ele,gönül gönüle

Koşuyorduk sevda yollarında

Karışmışken çoluk çocuğa,

Nerden esti bu hazin rüzgar

Neden

Neden bu kırgınlıklar,

Küsmeler,darılmalar.

Böylemi olmalıydı sonunda

Yazık değilmi bunca uğraşa

Gün be gün eriyip giden

Aşkımıza,sevdamıza.

Akşam işten dönüşümde

Biterdi tüm yorgunluğum

Başımı göğsüne dayayınca

Suçlamıyorum ne seni ne kendimi

Bir sorun varsa ortada

Beraber çözerdik aşkımızla.

Şimdi neden toplanamıyoruz

Bir masada,bir sofrada

Sen bir yanda,Ben bir yanda,

Çocuklarımız her bir yanda.

Bir yanda televizyon binlerce kanal

Bir yanda internet dolaş dolaşabildiğin kadar

Tutuşamıyoruz el ele,

Oturamıyoruz diz dize,

Anlaşamıyoruz,konuşamıyoruz bile,

Bir stres ki sorma her birimizde.

Yetmiyor üretimimiz,

Gelişen teknolojiye.

Gel dönüp bakalım geçmişe,

Küçük bir radyo aldığımda eve,

Sevinç le fırlamıştık ikimizde.

Teknoloji durmuyor be gülüm...

Her gün ileri gitmekte

Televizyon,İnternet,cep telefonu

Gün be gün eskimekte.

Hadi ver elini bir geceliğine

Kapatalım tv.yi,girmeyelim internete,

Çayımızı demleyelim sobanın üstünde

Mum ışığında yiyelim yemeğimizi

Konuşalım biraz havadan,su dan

Birazda aşk''tan,sevgi den sevda dan.

Koyalım ortaya bir sorun varsa,

Çözülmeyecek düğüm yoktur konuştukça.

Ama diyorsan  eller giderken aya,

Biz neden kalalım yaya

Haydi koş bilğisayara,

Bende televizyon başına

Yalnız şunu unutma be gülüm

Teknoloji verdiği kadar alıyor,

Aşk''ımızdan sevdamızdan........', 'Ne engeller aştık aşk uğruna, El ele,gönül gönüle Koşuyorduk sevda yollarında Karışmışken çoluk çocuğa, Nerden esti bu hazin rüzgar Neden Ne...', ARRAY['Türk Edebiyatı','Şiir','Cemal Şimşek']::text[], 8.5, '{"poet":"Cemal Şimşek","poet_slug":"cemal-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/teknoloji-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Kendimi Dinledim Yine', 'bugun-kendimi-dinledim-yine-gokhan-yazici-qf2oc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çektiğin dertlerine kılınmadı karar,

Hıçkırıkların boğazında kaldı boğum boğum.

Yoldaki dikenler ayağını yarar,

Acıdan inliyorsun, tıkanıyor soluğun.

Bugün kendimi dinledim yine, hicran doluyum.

Aydınlık hayallerin ufkun ardında,

Yürüyüşün bitmeyecek, acıların dinmeyecek.

Dağların zirveleri bulutların üstünde,

Tırmanacaksın yukarıya, azmin sönmeyecek.

Köy camisinden okunan sela, sana değil devam et.

Sana düşman yüzlere çarpabilirisin,

O sıkışık halinde kimse el uzatmaz.

Yalancı süslere sakın  aldanma,

Mahpusta kimse feryadını duymaz.

Annen bile duymaz, baban ise çoktan öldü.

Göreceksin güneş balçıkla sıvanmaz,

Çıkacaktır ortaya gerçek saadetin.

Döktüğün ter sana onur verecek,

Tükenmesin kuvvetin, mutlu yarınlar senin. 

Çek kılıcı be oğlum, savur fesat üstüne,

Bugün kendimi dinledim yine, gelme üstüme üstüme.', 'Çektiğin dertlerine kılınmadı karar, Hıçkırıkların boğazında kaldı boğum boğum. Yoldaki dikenler ayağını yarar, Acıdan inliyorsun, tıkanıyor...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Yazıcı']::text[], 8.5, '{"poet":"Gökhan Yazıcı","poet_slug":"gokhan-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bugun-kendimi-dinledim-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özledim', 'seni-ozledim-atilla-guler-w46ww', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kurumuş bir ağacın gövdesinden çıktım

aç göğsünü

al

içine

dokun yumuşacık

alev alsın saçlarım

parmak uçlarında gezinen şehvet

minik kelebekler kondursun dudaklarıma

susuzluğum dinsin pınarlarında

alazlansın yatağında güneş

yangınlara düşsün yüreğim

dilim

damağım

duyumsamalarım...

soyun! 

çırılçıplak

seni giyineyim

yık en bakir yerlerimi

yak

ellerinle

yok et

hiç acıma

uzansın önümde hiç bilmediğim yollar

kaybolayım

çığlıklarım ses bulamasın

hasretim boşalsın gözlerimden

üstüme sinsin kokun 

nefesini katayım nefesime

kıvrılıp kucağında

konuşma

dokun

seni özledim...', 'kurumuş bir ağacın gövdesinden çıktım aç göğsünü al içine dokun yumuşacık alev alsın saçlarım parmak uçlarında gezinen şehvet minik kelebekl...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/seni-ozledim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklardan Mektup Var...', 'uzaklardan-mektup-var-cafer-yilmaz-he89e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gelibolu''ya.....

dev orkinosum vardı benim.

gün batımında 

aynı yer,

aynı saat...

'' merhaba hayat..! ''

yaşamın adı vardı, tadı vardı...

şimdi orada olmak vardı.

rüzgarlar eserdi bazen hırçın,

ben hep o günlerde hırçın.

dalgalarım vardı,

kıyıları kıymazcasına döven,

bir bana kıyamazlardı,

bir balıklarıma...

balıklarım da vardı ufak tefek.

tanıştık hepsiyle,

tanırdım hepsini tek tek...

gidenlerim de oldu benim,

gelenlerim de...

gidip gidip gelenlerim vardı benim.

iskeleden kalkan gemilerim vardı.

benden bir şeyler götüren hep...

martılarım vardı etrafında

'' hey..! siz nereye gidiyorsunuz? ..''

el salladıklarım da vardı,

el sallayanlarımda...

dostlarım vardı,

şimdi orada olmak vardı...

en yalın halim,

en yalın günlerim,

güllerim vardı benim..

deniz kadar derinliklerim

hava kadar açıklıklarım vardı.

bazen kaçıklıklarım vardı benim.

bilinmezlerim vardı,

bilmediğim, çözemediklerim,

bilinmediğim, çözülemediğim günlerim...

bazen en cesur halim vardı

'' merhaba sevdiklerim..! ''

korkakça suskunluklarım

sonu uçurumlarım...

bir ben doğardım Marmara''dan her sabah

bir ben batardım Ege''den.

ayaklarım yere hiç değmeden.

kızıl halim vardı deniz üstünde...

hem yanlızlığımın

hem çoğul halimin şehriydi o...

öyle delicesine sevdiğim günlerim,

nefret edercesine küstüklerim...

denizlerim, balıklarım...

rüzgarlarım,kumsallarım...

ve bütün dostlarım...

hepsi orada kaldı...

şimdi

orada olmak vardı...

                          25-01-2000', 'Gelibolu''ya..... dev orkinosum vardı benim. gün batımında  aynı yer, aynı saat... '' merhaba hayat..! '' yaşamın adı vardı, tadı vardı... şimd...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/uzaklardan-mektup-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğe Gittim', 'sensizlige-gittim-guzin-eye-dundar-upice', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'değiştim kaçıncı kez kimbilir 

hayatın anlamını sildim

saçlarımda rüzgar 

dağlara gömüldüm. 

sevda  biriktirdim 

saydam gözelerinden 

kendime sakladım 

kaç yüz ağladı ötelerde 

senin için

ne diller dokundu 

suskunluğuma 

renklerden öyküler çaldım

tutku ektim gizli bahçelere 

ağaç  kabuklarından

heykeller yaptım

sevgiye benzesin diye

ölü güz adımlarını  şiirlere ilikledim

kızıl sarı yapraklarla 

düştü gözlerim

ben sensizliğe gittim 

üşüdüm... bilmedin..', 'değiştim kaçıncı kez kimbilir  hayatın anlamını sildim saçlarımda rüzgar  dağlara gömüldüm.  sevda  biriktirdim  saydam gözelerinden  kendim...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sensizlige-gittim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaranamayan Adam', 'yaranamayan-adam-emin-nadir-vk4kr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kur''an dedim,kelam dedim.

İnana selam dedim.

Bundan gayrı yalan dedim.

Yobaz dedin attın beni.

Oku dedim,ilim dedim.

Araştırın bilin dedim.

Gerisini silin dedim.

Dinsiz dedin,yaktın beni.

Ülkem dedim,millet dedim.

Cumhuriyet,bayrak dedim.

Vatan kutsal toprak dedim.

Faşist dedin,sattın beni.

Arkadaşça,dostça dedim.

Hepsi değil,hakça dedim.

İnsanı tut,hoşça dedim.

Moskova''ya sürdün beni.', 'Kur''an dedim,kelam dedim. İnana selam dedim. Bundan gayrı yalan dedim. Yobaz dedin attın beni. Oku dedim,ilim dedim. Araştırın bilin dedim. ...', ARRAY['Türk Edebiyatı','Şiir','Emin Nadir']::text[], 8.5, '{"poet":"Emin Nadir","poet_slug":"emin-nadir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaranamayan-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görüntü', 'goruntu-ali-cengiz-turan-gx1pp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arada bir aklıma gelir gelir bakarım,

Vücudumun üstünde konaklamış başıma.

Görüntüm yabancı görüntü yabancı,

Beyhuda geçen yıllar, zamanıma yanarım.

Lazım olduğu zaman ellerimi ararım,

Yaptığı işlerden hoşnut değiller demek.

Kalem tuttuğu zaman sanki secde ederler,

Kalemi yıllar önce bıraktığıma yanarım...

Aklıma ayaklarım yokuş çıkarken gelir,

Ayağımın olduğunu o zaman farkederim.

Emanet vücudumu taşıyor yıllar boyu,

Ecel gününe kadar benimle ömür boyu...', 'Arada bir aklıma gelir gelir bakarım, Vücudumun üstünde konaklamış başıma. Görüntüm yabancı görüntü yabancı, Beyhuda geçen yıllar, zamanıma ...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/goruntu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Güne Geldik', 'bu-gune-geldik-cafer-yilmaz-9vb5q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül derdin nedir, hele bir söyle? 

Varmıdır bir kinin, hele benimle? 

At sineği gibi girdin içime

Vızlaya vızlaya bu güne geldik...

Kimi gösterdiysen aldım getirdim.

Aç kalktım sofradan sana yedirdim.

Bir kez olsun bir kez, yeter demedin.

Sızlaya sızlaya bu güne geldik...

İş lafa geldi mi mangal gibisin.

Nerde güzel görsen çakal gibisin.

Doyma özürlüsün, kangal gibisin.

Havlaya havlaya bu güne geldik...

Hiç gülmedim inan senin yüzünden.

Yangınlar söndürdüm yaktın közünden.

Eksik etmedin ki yaşı gözümden.

Zırlaya zırlaya bu güne geldik...

Gördüğün papatya, menekşe senin.

Gücün yetse inan lalezar senin.

Gülden de betermiş dikenin senin.

Kanaya kanaya bu güne geldik...

Girdiğin hanede beş dakka otur.

Kalmamış anladım sende hiç onur.

Onursuz insana yalak çok olur.

Yalaya yalaya bu güne geldik...

Beni bırak hele kendinle savaş.

Yaş kemale erdi birazcık yavaş.

Çözüldü dizlerim yokum arkadaş..! 

Oflaya puflaya bu güne geldik...

Kaç kapıdan geçtik kaç yol tükettik? 

Hırsız gibi girip, alıp iç ettik.

Be vicdansız gönül..! Yari kaybettik.

Ahlaya vahlaya bu güne geldik...

Mezarın bulsam durmam gömerim.

Kimseyi istemem kendim eşerim.

Üstüne kaç kat toprak dökerim.

Zorlaya zorlaya bu güne geldik...

                                      27-03-2002', 'Gönül derdin nedir, hele bir söyle?  Varmıdır bir kinin, hele benimle?  At sineği gibi girdin içime Vızlaya vızlaya bu güne geldik... Kimi g...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bu-gune-geldik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ş i i r y a z ı n...', 's-i-i-r-y-a-z-i-n-zafer-zengin-etnika-h20vs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.

çevirip duruyorlar

dönüyorum

akşamdan kalmış güvercinlerle

başım ağrıyor ucumda

çıkarıyor sonra

bakıyor

anlıyorum açılmışım

kesiklerim görünmüyor

ne zaman soyunsam

yaralanmıyorum

tazeyim

temizleniyorum arada bir

elin ucunda ter

el ucunda kir

yazabilirim

ferman dersiniz

senet sepet

kümülatif toplamlar

çarpma kırmalar

bölüp toplamalar

resimleri de dişim karalar

ısırırım bir kadını

yan yatmış kalçasından

sevişirim oynadıkça üstünde

öyle yakınım ona

olmasam olmayacak sonra

kendim yazardım

ellerim olsa

az işim var

birazdan gelirim

kim bilir

kimleri deşeceğim

kılıcıda ben bilerim

kalem olmasam

gölgemde serinlerdim

şiir yazın benle

biraz dinleneyim

18 07 2005

.', '. çevirip duruyorlar dönüyorum akşamdan kalmış güvercinlerle başım ağrıyor ucumda çıkarıyor sonra bakıyor anlıyorum açılmışım kesiklerim gör...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/s-i-i-r-y-a-z-i-n-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlişki', 'i-liski-reyhan-tataroglu-vr2f0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'haya olmasaydı

                                  gece gündüzü örtermiydi

                                  yüz verseydi gül 

                                  bülbül hiç ötermiydi', 'haya olmasaydı                                   gece gündüzü örtermiydi                                   yüz verseydi gül                 ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iliski-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimle Savaş', 'kendimle-savas-ali-cengiz-turan-mqa7j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beynimi dinledim hayaller verdi,

Kalbimi dinledin güzeller sevdi.

İradem kendini kapıp koyverdi,

Savaşmadan yenilen esirmiyim ben? 

Beynim savaş meydanı devamlı kıvılcımlar,

İrade ordularım devamlı hücumdalar,

Nefs denen tehlikeli düşmanları,

Bin sefer mağlup etsem,bin sefer pusudalar.', 'Beynimi dinledim hayaller verdi, Kalbimi dinledin güzeller sevdi. İradem kendini kapıp koyverdi, Savaşmadan yenilen esirmiyim ben?  Beynim s...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kendimle-savas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-yalcin-isik-ww8p6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbime girdin sen bir gün sessizce

Beynime kazıdım seni düşünmeden

Seviyorum seni dedin, ben de dedim

Hayatım oldun sen benim her şeyinle

Planlar yaptık, hayaller kurduk geleceğe

Sözler verdik yalan yok diye

Konuşacaktık her şeyi bütün açıklığıyla

Ama yıllar değiştirdi bir şeyleri

Sildi içimizden ne varsa, her şeyi

Hep fedakarlık ettim dedin senin için

Hiç düşünmedin benim fedakarlıklarımı

Hep gururluyum dedin, ödün vermedin

Anlamadın bende ki yıkılan gururu

Dağlardaki kurtlar kadar gururluydum

Ama bir tek senin yanında köpek oldum.', 'Kalbime girdin sen bir gün sessizce Beynime kazıdım seni düşünmeden Seviyorum seni dedin, ben de dedim Hayatım oldun sen benim her şeyinle P...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Işık']::text[], 8.5, '{"poet":"Yalçın Işık","poet_slug":"yalcin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sitem-226-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Günah', 'buyuk-gunah-guzin-eye-dundar-d0s61', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölü cümleler çıkardım cam kafeslerden

kelebekler düştü ateşe

Adem suç üstü yakalanmış

incir yaprağında

günahından bile asırlarca uzaktım.

görmeseydim kadim ağacı 

bu günahı ölesiye unutacaktım….', 'Ölü cümleler çıkardım cam kafeslerden kelebekler düştü ateşe Adem suç üstü yakalanmış incir yaprağında günahından bile asırlarca uzaktım. gö...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/buyuk-gunah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesur Beylere', 'cesur-beylere-ali-cengiz-turan-zxea9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşin bozulur sus,suyun kesilir sus,

Neme lazım bizimle,sanamı kalmış kiminle,

Vaktini bekle sus,

Aylığı bekle sus,

Dalkavuklar seninle.

Cesurluk yapma sus,

Göze batma sus,

Rüşvet almış sus,

Rüşvet vermiş sus,

Saygınlık zenginlik seninle,

Deniz,otel seninle,

Yatlar,katlar seninle,,,

Herşeye susssssssssssssssssssss.......................! ! ! ! ! ! ! ! !', 'İşin bozulur sus,suyun kesilir sus, Neme lazım bizimle,sanamı kalmış kiminle, Vaktini bekle sus, Aylığı bekle sus, Dalkavuklar seninle. Cesu...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cesur-beylere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitti Giden...', 'gitti-giden-cafer-yilmaz-vliq7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', ''' çabuk ol. '' dedi.

iskeleden kalkan gemi.

'' kalkmak üzereyim. ''

radyoda,

astımlılar dışarı çıkmasın diyordu bayan.

hava ağır mı ağır.

omuzlarıma çökmüş.

kendimi zor taşıyorum oysa

ve de duygularımı...

'' çabuk ol. '' dedi.

iskeleden kalkan gemi.

'' kalkmak üzereyim. ''

ne gereği vardı oysa,

ondan bundan konuşmanın.

tam zamanıydı,

ömrünün tam zamanıydı üstelik.

hani söz vermiştin aynada kendine bu sabah? 

'' konuşacağım,

her şeyi konuşacağım...''

ne güzel hazırdı da her şey,

sana ne oğlum,

çınarın yaşından,

yerde seken serçe kuşundan...

çarşaf gibi denizi de buldunuz ya,

taş sektirmenin zamanımıydı? 

oysa ömrünün en güzel gününü sektirdin

deniz üstünde...

'' çabuk ol. '' dedi.

iskeleden kalkan gemi.

'' kalkmak üzereyim. ''

sabah ezanıyla çıktın yola.

kaç otobüs değiştirdin bu sıcakta.

dalgındın yanlış otobüse bindin.

geri geldin,

baştan bir daha...

bu kadar zormu konuşmak oğlum? ! ! 

tutacaksın kollarından,

gözlerinin içine bakacaksın.

ellerini de tuttunmu

yolun yarısı gitti zaten.

gerisi kolay be oğlum,

diyeceğin tek şey 

'' seni seviyorum...''

'' çabuk ol. '' dedi.

iskeleden kalkan gemi.

'' kalkmak üzereyim. ''

şimdi bu sıcakta aynı yolu teptirme bana.

akşamı düşün,

aynanın karşısına geçip

suratına savuracağın küfürleri.

uyuyamayacağın geceleri.

bu kadarda zor değil 

'' seni seviyorum '' demek..! 

suç değil.

günah değil.

ayıp değil...

'' çabuk ol. '' dedi.

iskeleden kalkan gemi.

'' kalkmak üzereyim. ''

kaçırdığım ilk gemi değilsin ki...

az önce kaçırdım ömrümün gemisini.

gideceksen git kardeşim,

alıştım... ben gelmeyeceğim...

                                        15-06-1999', ''' çabuk ol. '' dedi. iskeleden kalkan gemi. '' kalkmak üzereyim. '' radyoda, astımlılar dışarı çıkmasın diyordu bayan. hava ağır mı ağır. omuzl...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/gitti-giden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır çiçeği', 'kir-cicegi-levent-i-skenderoglu-8jsk4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Varlığın hayat kadar değerli

Sen hayat kadar güzel

Umut kadar tazesin

Ama gözlerin

Bulutlar kadar derin

Martılar kadar çığırtkan

Kır çiçeği kadar ürkek

Kır çiçeği kadar özel', 'Varlığın hayat kadar değerli Sen hayat kadar güzel Umut kadar tazesin Ama gözlerin Bulutlar kadar derin Martılar kadar çığırtkan Kır çiçeği ...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kir-cicegi-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Yağınca Şehre', 'kar-yaginca-sehre-ufuk-bayraktar-x7kfm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'şehir beyazlarını giymiş

örtmüş çöplerinin üzerini

taze gelin gibi

süzülmekte...

ağaçlar da havaya girmiş

sanki birer fener 

o kuru dallar

yanar döner...

bir kaç gün sonra

erirken o karlar

akacak makyajın

yüzünden,

eskisinden de çirkin olcaksın.', 'şehir beyazlarını giymiş örtmüş çöplerinin üzerini taze gelin gibi süzülmekte... ağaçlar da havaya girmiş sanki birer fener  o kuru dallar y...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kar-yaginca-sehre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlik', 'genclik-ali-cengiz-turan-1t16m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ateşli kanınızla coşun siz büyük gençlik,

Yılları mutlulukla aşın siz güzel gençlik,

Sizin şarkınız olsun sevgi olan şarkılar,

Mutluluk yollaını aşın siz büyük gençlik.

Dallarınız meyvalı,başağınız bol olsun,

Kalplerinizde sevgi düşmanlara kor olsun.

Ektiğiniz fidanlar aşılansın sevgiyle,

Sevgiden doysun zaman güzel nesiller gelsin.....', 'Ateşli kanınızla coşun siz büyük gençlik, Yılları mutlulukla aşın siz güzel gençlik, Sizin şarkınız olsun sevgi olan şarkılar, Mutluluk yoll...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/genclik-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Taşıyan', 'sevgi-tasiyan-ali-cengiz-turan-t1s7o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi taşıyan rüzgarlar,

Artık hüzün taşıyorlar.

Güllerin rengi donuk,

Tomurcuklar açmıyor.

Sevgiler lekelenmiş,

 duygular törpülenmiş

Açmak için bekleyen 

Çiçekler yok edilmiş.

Ümit veren şarkılar,

Şimdi hüsran veriyor.

Sevgi taşıyan rüzgarlar 

Şimdi hüzün taşıyor......! ! ! ! ! ! ! ! ! !', 'Sevgi taşıyan rüzgarlar, Artık hüzün taşıyorlar. Güllerin rengi donuk, Tomurcuklar açmıyor. Sevgiler lekelenmiş,  duygular törpülenmiş Açmak...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgi-tasiyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde doğdu', 'yuregimde-dogdu-ejder-kose-lc5f3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin yüreğimde doğdu bir güneş gibi

Isıttı kışlar yaşayan yüreğime, bahar getirdi

Taptaze açan güller misali,

Sözlerin yaraladı yüreğimi param parça etti

Kanamayan sevdayı kanattı, sevda yaşları akıttı gözlerimden

Bana sevmeyi öğretti', 'Gözlerin yüreğimde doğdu bir güneş gibi Isıttı kışlar yaşayan yüreğime, bahar getirdi Taptaze açan güller misali, Sözlerin yaraladı yüreğimi...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yuregimde-dogdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kederlerim', 'kederlerim-zeliha-bicer-cpp45', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kar kış ayaz boran aklına ne geliyorsa tüm fırtınalar

Yüreğimde harmanlaşmış senden öte değiller

Sesinin kırıklığı,benim umarsızlığım,

Belki yaşamın zorlukları, anlaşamadığımızdan yaşamla

Hırcınlığım var bu aralar,kırılmışsın bana, farkındayım

Oysa nefesimsin derken ben sana,yaşam nefes aldırmıyor

Aldırmazken nefessiz kalışlarımda,sen sırt çevirme

Sensizliğim öyle koyuyor ki bana bunca dertlerde

Yapma ne olur yapma,sensiz sessiz bırakma

Bırakma beni böyle kederlerde.', 'Kar kış ayaz boran aklına ne geliyorsa tüm fırtınalar Yüreğimde harmanlaşmış senden öte değiller Sesinin kırıklığı,benim umarsızlığım, Belki...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kederlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçliğe Seranet', 'hiclige-seranet-ali-cengiz-turan-an8x4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimde yangınlar volkanlara eşdeğer,

Yanıyor,yanıyor,yanıyorum.

Düşüncelerim yıldırımları geçer,

Sanıyom,sanıyom,sanıyorum.....

Hasrete hasretim arıyorum,

Herşeyim var,hiçbirşeyim yok,

Devamlı büyüyen hiçlik ateşini,

Soluyor,soluyor,soluyorum.

Dünyanın ayakları çorapsız ayakkabısız,

Görüyor,görüyor,görüyorum.

Anlayanlara,anlamayanlara sesleniyorum,

Ayaklar kangren oluyor,çöküyorum.......', 'Yüreğimde yangınlar volkanlara eşdeğer, Yanıyor,yanıyor,yanıyorum. Düşüncelerim yıldırımları geçer, Sanıyom,sanıyom,sanıyorum..... Hasrete h...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hiclige-seranet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ateşi', 'ask-atesi-ejder-kose-tserx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin aşka çağıran; deli bir rüzgar

Baktıkça yüreğimde ki koru alevlendiren.

Yüreğim sönmeyen bir alev almış,

Rüzgarınla her saniye alevlenen.

Yaktı kor etti yüreğimi gözlerin

Gözlerin cehennemin diğer adıymış

Kaçmak ne mümkün, yaşarken

Yanmakmış kaderi yüreğimin..', 'Gözlerin aşka çağıran; deli bir rüzgar Baktıkça yüreğimde ki koru alevlendiren. Yüreğim sönmeyen bir alev almış, Rüzgarınla her saniye alevl...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-atesi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanırım', 'utanirim-ejder-kose-bg4ak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilir misin neden gözlerine müptelayım,

Çünkü, rengini gecelerden almış.

Bilir misin neden olmasın isterim gündüzler

Çünkü gözyaşlarımı akıtamam ağlayamam; utanırım! 

Ne zaman yalnızlığa boğulsam, yüreğimin sesini dinlesem

Yürekten bir dost eli arasam, ey dost! 

Felekler şu an olduğu gibi; yağmur yağdırır kirpiklerime,

Dökemem avuçlarıma, akıtamam ağlayamam; utanırım!', 'Bilir misin neden gözlerine müptelayım, Çünkü, rengini gecelerden almış. Bilir misin neden olmasın isterim gündüzler Çünkü gözyaşlarımı akıt...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/utanirim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni sensizde severim', 'seni-sensizde-severim-ejder-kose-iwqgg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gelme artık istemem sevgilim, seni sensizde severim

Şahittir gözyaşlarım sensizliğe Seni nasıl sevdiğime 

Şahittir gökyüzü, avuç açıp da Allah’a seni dilendiğime

Gelme artık istemem seni sensizde severim…

Senin olsun güzel yüzün, senin olsun al her şeyim

Nerden bilirdim melek yüzünün altında şeytan yattığını

Mahkum ettin beni sensizliğe yalancı sözlerine 

Gelme artık istemem seni sensizde severim…

Nerden bilirdim seninle acının derdin ortasına düşeceğimi

Nerden bilirdim her kelimede bin ah edeceğimi

Baş başa bırak beni derdimle ahım la acınla

Gelme artık istemem seni sensizde severim…', 'Gelme artık istemem sevgilim, seni sensizde severim Şahittir gözyaşlarım sensizliğe Seni nasıl sevdiğime  Şahittir gökyüzü, avuç açıp da All...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-sensizde-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaslandım Dikenlere', 'yaslandim-dikenlere-emre-saricicek-5unvb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özendim bitmeyen, çıkarsız sevgilere.

Dilendim aşk için, yıkılan yüreklere.

Seslendim gönlümü, sunduğum çiçeklere

Yaslandım, acı ile keder ile dikenlere.

Yaşarken avunduğum, binbir gece masalı.

Giderken, beni sen değil. Hiçkimse anlamadı.

Susarken gözlerimle, anlatmıştım herşeyi.

Ölürken bare bırak. Vereyim son nefesimi.', 'Özendim bitmeyen, çıkarsız sevgilere. Dilendim aşk için, yıkılan yüreklere. Seslendim gönlümü, sunduğum çiçeklere Yaslandım, acı ile keder i...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yaslandim-dikenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-ali-cengiz-turan-3kd76', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güller açarken güzel,

Güneş doğarken güzel,

Yağmur yağarken güzel,

Kalpler severken güzel.

Taşlaşmış gönüllerde,

Paslanmış fikirlerde,

Robotlaşmış nesilde

Sevgi aşısı güzel.

Ağaç meyvasıyla var,

Sevgi fedakarlıklarla,

Yaşam gerçeklerini,

Doğruluklar tamamlar.

Güzellik kaş göze değil,

Dış görünüş hiç değil,

Çiçek bahçesi gibi,

Ruhu açmışsa güzel.', 'Güller açarken güzel, Güneş doğarken güzel, Yağmur yağarken güzel, Kalpler severken güzel. Taşlaşmış gönüllerde, Paslanmış fikirlerde, Robot...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzel-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Alfabesi Yasaklıdır', 'askin-alfabesi-yasaklidir-dilek-ozdemir-2pei7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çığlığın ölü olduğu iklimde

aşkın alfabesi yasaklıdır şimdi

Yasaktır soğuk kış günlerinde

güneş olmak, ve hatta

güneşe “günaydın” demek 

içindeki bahar kıpırtılarına yelken açmak

ve buğulu camlara kalp resmi çizmek

yasaktır.

Yağmur altında sırılsıklam şarkı söylemek

gözlerle anlaşmak, susarak konuşmak

delice koşmak rüzgara karşı

sarılmak ve hatta ellerine dokunmak

yasaktır.

Denizin, yağmurun ve gözyaşının sudan,

gökyüzü, ay ve yıldızların ders kitaplarından gayrı

bütün anlamları silinmiştir

ve artık tanık sayılmayacaklardır aşka

rüzgarlar ten kokusunu taşımayacak,

gözler çiçeklere karışmayacaktır	

ve saçların gül kokması 

yasaktır.

Atmayacak yüreğin kendinden başkası için

hatta uzakta bir yerde, sesli sessiz  bir vahşette 

“anne” diyemeden ölen bebelere

ya“nüfus planlaması” deyip güleceksin,

ya da “Allah aldı” deyip unutacaksın

düğümlenmeyecek lokmaların boğazında,

yasaktır.

Yüreklerin kapısı kilitlenip açılmayacak

anahtarı dipsiz kuyulara atılacaktır 

zenginliği paradan başka bir şey saymak

ve zenginlikten gayrı bir şey için savaşmak

yasaktır.

“Depremler değil

asıl titreten yurdumun toprağını

karanlık yüzlü binalardan fışkıran

çalıntı seslerin tınısı

kanla yazılan bir destanla umut kokan ülkemin 

sırtından vurulmasının hazinliği” demek

yasaktır.

Karnının en içine otursa kaskatı bir düğüm

kaşıktaki çorban çamur

çorbadaki tuzun zehir olsa

taş olsa ekmeğinin arasındaki katığın

içinde “a”, “ş”, “k” harfleri geçen bütün kelimeler

yasaktır.

Çığlığın ölü olduğu iklimde

aşkın alfabesi yasaklıdır şimdi.', 'Çığlığın ölü olduğu iklimde aşkın alfabesi yasaklıdır şimdi Yasaktır soğuk kış günlerinde güneş olmak, ve hatta güneşe “günaydın” demek  içi...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/askin-alfabesi-yasaklidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni arıyorum', 'seni-ariyorum-ejder-kose-59o0a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni arıyorum, türkülerde

Seni arıyorum, her sevgi sözcüğünün içinde

Seni seviyorum sensiz olsam da yine

Seni arıyorum bütün yeşil gözlerde.

Artık bir mecnunum, ateşinle yanan ferhatım

Senden başkasını görmeyen bir kör,

Çöllerdeyim dağlardayım

Yeşil gözlüm seni aramaktayım..', 'Seni arıyorum, türkülerde Seni arıyorum, her sevgi sözcüğünün içinde Seni seviyorum sensiz olsam da yine Seni arıyorum bütün yeşil gözlerde....', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-ariyorum-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim sevgilim', 'sensizim-sevgilim-ejder-kose-iy5cu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık sevemiyorum kimseyi, aşk nedir unuttum,

Aşk sendin, sevgi sendin, ümit etme sendin.

Artık ne sevgim; ne ümidim var

Çünkü sen yoksun sensizim.

Haram oldu artık bana sevmek suç oldu

Sensizim sevgilim suçluyum günahkarım

Gülmek yalan oldu; sevmek hayal

Çünkü sensiz biçareyim sevgilim..

Unut demişsin yazdığın son satırlarında

Artık ben sensiz, sen bensiz kal demişsin 

Hiç düşünmemişsin halim ne olur sensiz

Seni benden, beni yaşamdan etmişsin…', 'Artık sevemiyorum kimseyi, aşk nedir unuttum, Aşk sendin, sevgi sendin, ümit etme sendin. Artık ne sevgim; ne ümidim var Çünkü sen yoksun se...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizim-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemedim', 'bilemedim-ejder-kose-u96cr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırmızı dülbenti’nin nuru düşmüş yüzüne,

Bir anda bilemedim bağlandım sana.

Aşk ateşi kandil gibi yandı gönlümde,

Bir anda çözemedim bağlandım sana.

Kevser ırmağı gibi kokan saçlarına bağlandım,

Cennet hurisi gibi bakışına dolandım 

bilemedim işte bir anda melek gülüşüne aldandım.

Bir anda çözemedim nur yüzlüm,  bağlandım sana…', 'Kırmızı dülbenti’nin nuru düşmüş yüzüne, Bir anda bilemedim bağlandım sana. Aşk ateşi kandil gibi yandı gönlümde, Bir anda çözemedim bağland...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilemedim-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak', 'birak-ejder-kose-4pn4n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bırak, dokunma saçlarıma; dağınık kalsın

Bırak, karışma sakallarıma uzasın,

Bırak, silme yaşları yüreğe aksın,

Bırak, bedbaht şair, yalızlığa, çileye SEVDALANSIN. 

Kimi anlar vardır bitmesin diye; yaşanmak istenmez.

Kimi sevdalar vardır dilde destan; bu anlara sığmaz

Kimi dostluklar vardır; bu anlarda lazım, çağlarda aranmaz,

Bırak bedbaht şairi bu anların hasretiyle YAŞASI', 'Bırak, dokunma saçlarıma; dağınık kalsın Bırak, karışma sakallarıma uzasın, Bırak, silme yaşları yüreğe aksın, Bırak, bedbaht şair, yalızlığ...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/birak-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Bıraktım', 'sana-biraktim-ali-kemal-i-cen-pd75a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollları sana bıraktım

Yalnızlıklar yeter bana

Güzleri sana bıraktım

İlkbaharda elbet açar sevdam

Hayırsızlığı sana bıraktım

Kalbimdeki ateş yeter bana

Soysuzluğu sana bıraktım 

Göz yaşlarım karışır elbet denizlere

Zülmü sana bıraktım

İşkenceler  yakar bedenimi

Ölümüsana bıraktım

Dağların arkasındaki şafak  yeter bana

Yaşadıklarımı sana bıraktım

Ey Anadolu sen yeter bana

12-04-2002', 'Yollları sana bıraktım Yalnızlıklar yeter bana Güzleri sana bıraktım İlkbaharda elbet açar sevdam Hayırsızlığı sana bıraktım Kalbimdeki ateş...', ARRAY['Türk Edebiyatı','Şiir','Ali Kemal İçen']::text[], 8.5, '{"poet":"Ali Kemal İçen","poet_slug":"ali-kemal-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sana-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıg düşmüş', 'cig-dusmus-ejder-kose-hm36n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sırdaşım oldu karanlık g eceler,

Dertdaşım oldu esrarlı uykuya dalan dehlizler

Kaderiymiş yalnızlık, bedbaht şairin

Adresi olmuş dertler, çileler, ümitsizlikler

Çığ düşmüş yanan yüreğime karanlık gecelerde,

Sevilememiş bedbaht şair; körpe yüreklerde

Çığdan da betermiş, unutulmak aciz bedenimde

Bırak tanınmasın bedbaht şair; vefasız gözlerde..!', 'Sırdaşım oldu karanlık g eceler, Dertdaşım oldu esrarlı uykuya dalan dehlizler Kaderiymiş yalnızlık, bedbaht şairin Adresi olmuş dertler, çi...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cig-dusmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-ejder-kose-g8yce', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne Güzeldi Ellerini Tutabilmek Meleğim

İlkbahar Rüzgğarının Tadını Gözlerinde Yaşayabilmek

Ne Güzeldi Her Nefeste Varlığını Hissetmek

Şimdi Yoksun Ne Hallerdeyim Gel De Gör Güzel Meleğim…! 

Sen Yoksun Dökülüyor Şimdi Gözümden Hasret-İ Baran Katresi

Sen Yoksun Yanıyor Şimdi Yüreğim Nar-I Hicranla

Gel Bir Nisan Yağmuru Ol Şu Bahr-I Çilede

Islat Yanan Yüreğimi Gözyaşlarınla Bir Sadef Misali…!', 'Ne Güzeldi Ellerini Tutabilmek Meleğim İlkbahar Rüzgğarının Tadını Gözlerinde Yaşayabilmek Ne Güzeldi Her Nefeste Varlığını Hissetmek Şimdi ...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yoksun-136-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yankı', 'yanki-ali-cengiz-turan-zhd2j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fikrin aydın olup anlatamazsan,

Aydın olan fikrini yansıtamazsan,

Hükmeden çoğunluk senin fikrinse,

Dört duvar arasında dönen yankıdır.

Fikir ayrılıkları menfaat ise,

Bilinçsiz itaat cahillik ise,

Menfaat yolları körlenmedikçe,

Birlerin,yüzlerin fikri yankıdır..', 'Fikrin aydın olup anlatamazsan, Aydın olan fikrini yansıtamazsan, Hükmeden çoğunluk senin fikrinse, Dört duvar arasında dönen yankıdır. Fiki...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yanki-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanmışsın', 'yalanmissin-ejder-kose-7lzou', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninle sevdaya inanmıştım meleğim

Anladım ki dünya gibi sende yalanmışsın

Esirgedin yüreğinden bir sevgi sözünü

Sende kaderim gibi göz yaşıyla bırakmışsın..

Vurulmuştum melekleri kıskandıran nur yüzüne

Çocuklar gibi inanmıştım, yalan gülüşüne

Sana meleğim, yarenim her şeyimsin demiştim

Sende feleğin cilvesi gibi çileliymişsin..', 'Seninle sevdaya inanmıştım meleğim Anladım ki dünya gibi sende yalanmışsın Esirgedin yüreğinden bir sevgi sözünü Sende kaderim gibi göz yaşı...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalanmissin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çevir Gidişini', 'cevir-gidisini-ali-cengiz-turan-6e0z0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çevir gidişini yokuşa doğru,

Seninle yürüyen zaman yorulsun.

Hızına güç katki aşılsın yokuş,

Bulanmış zamanda ömür yorulsun.

Geçmiş zamanı doldur ruhuna,

Nehir gibi akan zaman durulsun.

Geçmişin özlemi hayallerinde,

Canlanıp canlanıp önünde dursun..! ! ! ! !', 'Çevir gidişini yokuşa doğru, Seninle yürüyen zaman yorulsun. Hızına güç katki aşılsın yokuş, Bulanmış zamanda ömür yorulsun. Geçmiş zamanı d...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cevir-gidisini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizler Çağlar oldu yüreğimde', 'denizler-caglar-oldu-yuregimde-ejder-kose-vbcvn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Firar etti yaşlar gözlerimden bak yine,

Bırak boğulsun hıçkırıklar, sevda seline

Bırak kıskansın okyanuslar, sevdamın derinliğini

Gel de gör denizler çağlar oldu yüreğimde! 

Şimdi yoksun sevdalım, hasretin kaldı geride,

Bak bedbaht şairin ağlıyor çocuklar gibi sensizliğe

Boğazıma takılan hıçkırıklar kaldı, titreyen sesimde

Gel de gör denizler çağlar oldu yüreğimde! 

Sevdalım, ümitsizliğe sallanır oldu eller, peşin sıra

Bak çaresizliğe doğuyor her şafakta güneşler,

Bak yoldaşım oldu gülünden ayrılan bülbüller,

Gel de gör denizler çağlar oldu yüreğimde! 

Sevdalım, bülbül gülüne kanasın,her ah ta

Mecnunlar, Ferhatlar ağlasın her sevda da

Bırak dualar ağlasın peşin sıra her şafakta,

Gel de gör denizler çağlar oldu yüreğim', 'Firar etti yaşlar gözlerimden bak yine, Bırak boğulsun hıçkırıklar, sevda seline Bırak kıskansın okyanuslar, sevdamın derinliğini Gel de gör...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/denizler-caglar-oldu-yuregimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözün karası gecelerde avundum', 'gozun-karasi-gecelerde-avundum-ejder-kose-5woq2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamak isterdim, deniz gözün mavilerde,

Ama vefayı karanlıklarda buldum.

Bedbahtlıkmış yazgım, utanırdım ağlamaya,

Gözün karası gecelerde avundum…

Seni çok seviyordum ya, sensiz sevmekten yoruldum

Artık uykulara küsüm, seni hayallerde bile unuttum.

Bedbahtlıkmış alın yazgım, korkardım sensizlikten,

Gözün karası gecelerde avundum…', 'Yaşamak isterdim, deniz gözün mavilerde, Ama vefayı karanlıklarda buldum. Bedbahtlıkmış yazgım, utanırdım ağlamaya, Gözün karası gecelerde a...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gozun-karasi-gecelerde-avundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hz. OSMAN (RA)', 'hz-osman-ra-abdullah-yasar-erdogan-250dk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Aşere-i Mübeşşere’nin üçüncüsü) 

        Hz.  OSMAN  (RA)

Altı sene sonra doğdu Fil Vakası’ndan,

Ticareti devraldı tacir babasından,

Raşid Halifelerin üçüncüsü Osman,

Cennetle müjdelenen güzel Hz. Osman’ım,

O’nun adı: Osman bin Affân, bin Ebil-As,

Bin Ümeyye bin Abdi’ş-Şems bin Abdi Menaf,

El- Kureşi el- Emevi, üçüncü sultan.

İlk iman edenlerden olan Hz. Osman’ım.

Hz. Osman’ın annesi Arva, Kuryez kızı,

Arva’nın annesi Abdullamuttalib’in kızı,

Büyükannesi, Hz. Muhammed’in halası,

İki nur sahibi olmuştur, Hz. Osman’ım.

O güzel Osman ki, Mekke’de çok sevilir,

Künyesi; Ebû Abdullah denilmektedir,

O’na “Ebû Amr” ve “Ebû Leyla” de denir,

Cennetle müjdelenen güzel Hz. Osman’ım.,

Ceddi Abdi Menaf’ta Resûlle birleşir,

Ümeyye oğulları ailesindedir,

Annesi; Erva binti Abdi Şems’tir,

Cennetle müjdelenen güzel Hz. Osman’ım.

O’nun çocukluk arkadaşı Ebû Bekir,

O’nun isteğiyle İslâm’ı seçmiştir,

Hz. Osman, Aşere-i Mübeşşere’dendir,

İlk iman edenlerden olan Hz. Osman’ım.

O’nun iman ettiğini amcası duymuş,

Amcası Hakem bin Ebil-As’da putçuymuş,

Osman’ı bağlayıp loş bir odaya koymuş,

İlk iman edenlerden olan Hz. Osman’ım.

“Asla geriye dönmem” demiş güzel Osman,

Hakem bin Ebil-As inatla der “Bırakmam”,

Osman’ın sevdası vazgeçirmiş inattan,

Davasına pek sadık olan Hz. Osman’ım.

Muhammed kızı Rukiyye ile evlendi,

Habeşistan’a ilk hicret edenlerdendi,

“Mekkeliler iman etti” denince geldi,

Cennetle müjdelenen güzel Hz. Osman’ım.

O tekrar Habeşistan’a hicret etmişti,

Bir zaman sonra da Mekke’ye tekrar geldi,

Mü’minlerle birlikte Medine’ye gitti. 

İki nur sahibi olmuştur, Hz. Osman’ım.

Evs bin Sabit’te Hz. Osman’ı konuk etti,

Bundan dolayı Hassan, O’nu çok severdi,

Hassan ki; Evs bin Sabit’in öz kardeşiydi,

İlk iman edenlerden olan Hz. Osman’ım.

Medine hicretinin altıncı yılında,

Abdullah vefat etti, Rukiyye’de olma,

Osman çok üzüldü, Muhammed torununa,

Cennetle müjdelenen güzel Hz. Osman’ım,

Abdullah altı yaşında o zamanlar,

Horoz gözünü çizmişti, azdı yaralar,

Ölümü Rukiyye’nin gönlünü paralar,

İlk iman edenlerden olan Hz. Osman’ım.

Bedir savaşı başlarken Rukiyye hasta,

Rasûlullah izin vermedi Hz. Osman’a,

O Rukiyye, tez kavuştu Rabb-i Rahman’a,

Cennetle müjdelenen güzel Hz. Osman’ım.

Bedir sonrası O’na ganimetten pay var,

Resûl O’nu, Ümmü Gülsüm ile nikahlar,

Muhammed’le Osman beraber, ayrılmazlar,

Davasına pek sadık olan Hz. Osman’ım.

Hicri dokuz yılında Ümmü Gülsüm öldü,

O güzel çehreli Osman, hüzne büründü,

Osman’a “İki nur sahibi-Zi’n-Nureyn” dendi,

İki nur sahibi olmuştur, Hz. Osman’ım.

Resûl; “Kırk kızım olsa Osman’a veririm,”

Düşünmeden kızlarımla evlendiririm,

Ben, Zatü’r-Rika’da savaştayken, vekilim.”

Cennetle müjdelenen güzel Hz. Osman’ım.

İlk hanımı Rukiyye, sonra Ümmü Gülsüm,

Genç yaşta onları bağrına aldı ölüm,

Resûlün iki kızında yaşadı hüzün,

Meleklerin haya duyduğu Hz. Osman’ım.

Fahite Binti Gazvan’la etti izdivaç,

Abdullah El- Asgar’da doğdu bu hanımdan,

Abdullah’ta çocuk yaşta koptu hayattan,

Şayan-ı hâya bilinen Hz. Osman’ım.

Ümmü Amr Binti Cündüb, dördüncü eşidir,

Amr, Halid, Ebban ve Ömer’in annesidir,

O, Hz. Osman’a dört erkek çocuk vermiştir,

Utanma hissinin bendesi Hz. Osman’ım.

Fatıma Binti’l Velid El-Mahzumiyye eşi,

Said, Velid ve Ümmü Said’in annesi,

O Hz. Osman’a üç tane evlat vermişti.

Gönlü büyük, eli açık Hz. Osman’ım.

Ümmü’l- Benin Binti Uyayna bin Hson eşi,

Doğarken ölen Abdülmelik’in annesi,

O, Hz. Osman’a bir tane evlat vermişti,

Meleklerin haya duyduğu Hz. Osman’ım.

Ramle binti Şeybe bin Rabi’a eşidir,

Ümmü Ebban ve Ümmü Amr’ın annesidir,

Ramle’nin hiç erkek çocuğu olmamıştır,

İki nur sahibi olmuştur, Hz. Osman’ım.

Naile Binti’l-Farafisa son eşidir,

Naile, Meryem adlı kızının annesidir,

O’na Meryem’üs-Suğra (Küçük Meryem)  denir.

Meleklerin haya duyduğu Hz. Osman’ım.

O’nun sekiz  hanımla evlenmişliği var,

Osman; şehit olmadan önce üç eşi var,

Ümmü’l-Benin, Fahite, ve Naile’dir bunlar,

Cennetle müjdelenen güzel Hz. Osman’ım.

İslam’ı seçmeden de saygı duyulandı,

İslâm’a girerken otuz dört yaşındaydı,

Hz. Ebû Bekir di onun can arkadaşı,

İki nur sahibi olmuştur, Hz. Osman’ım.

Mekke’ye Umre için kafile yola çıktı,

Müşrikler onları Mekke’ye yaklaştırmadı,

Osman Hudeybiye de elçi görevi yaptı,

İlk iman edenlerden olan Hz. Osman’ım.

Resûl dedi; “Git müşriklere söyle şunu,

Kâbe’yi ziyarete geldik bilsin bunu,

Kurban kesip döneceğiz, açsınlar yolu,

Davasına pek sadık olan Hz. Osman’ım.

İlk elçi Hıraş bin Umeyye el-Kâ’bi’dir,

Müşrikler Hıraş’ı öldürmek istemiştir,

Hz. Osman’ı göndermezler, esir etmiştir.

Cennetle müjdelenen güzel Hz. Osman’ım.

“Osman öldürüldü” haberleri yayılmış,

Muhammed, Mü’minleri bey’at’a çağırmış,

Bu davet “Bey’atu’r-Rıdvan” diye anılmış,

İlk iman edenlerden olan Hz. Osman’ım.

Muhammed, Allah adına yeminde bulunmuş,

Sol elini sağ elinin üzerine koymuş,

“Osman, Allah ve Resûlü için öldü” demiş.

Davasına pek sadık olan Hz. Osman’ım.

Müşrikler Resûlün niyetini anladı,

Bu bey’at üzerine korkuya kapıldı,

Kendi aralarında çareler aradı,

İki nur sahibi olmuştur, Hz. Osman’ım.

Müşrikler Osman’a şartları söylediler,

“İstersen sen Kâbe’yi tavaf et” dediler,

Osman; “Resûl, tavaf etmeden ben etmem,” der,

Davasına pek sadık olan Hz. Osman’ım.

O döndü dostları içine selametle,

Cahiller “Kâbe’yi tavaf etti” der O’na,

Resûl: “Biz tavaf etmeden, etmez,” demekte.

Cennetle müjdelenen güzel Hz. Osman’ım.

Medine’de Muhammed’le hep beraberdi,

O, ashabın en zenginlerinden biriydi,

Savaşa giden askeri o giydirirdi.

Şayan-ı hâya bilinen Hz. Osman’ım.

Tebük  Seferi öncesi orduya bağış,

Ebu Bekir’le Osman arasında yarış,

Osman dokuz elli atı yaptı bağış,

Gönlü büyük, eli açık Hz. Osman’ım.

Hz. Muhammed dedi: “Ben Osman’dan razıyım,

Sende güzel Osman’dan razı ol Allah’ım.”

Malını Hakk yolda harcamakta mülayim,

Meleklerin haya duyduğu Hz. Osman’ım.

O’nun yaptıklarından dolayı  yok günah,

O’na cennetini vermiş Hazret-i Allah,

Daim; “Hakk doğrunun yardımcısıdır Billah,”

Cennetle müjdelenen güzel Hz. Osman’ım.

Hz. Osman, veda haccında Resûl yanında,

Destek Ebû Bekir’e Halife olanda,

Ömer’e bey’at etti, ahitname onda,

İki nur sahibi olmuştur, Hz. Osman’ım.

Ebû Bekir döneminde birinci katip,

Hz. Ömer’de de aynı katipliğe talip,

Hz. Osman ki, belagatı güzel bir hatip,

Cennetle müjdelenen güzel Hz. Osman’ım.

Ömer, Hz. Muhammed yanına kaldırıldı,

Cenaze namazını Sahayb kıldırmıştı,

Halife seçimi için şura toplatıldı.

Ebû Bekir’in, Ömer’in dostu, Osman’ım.

Mikdad bin Amr şura başkanı atanmıştı,

Müsevvir bin Mahrama evinde toplantı,

Ömer vasiyetiyle altı kişi buradaydı,

Davasına pek sadık olan Hz. Osman’ım.

Ebu Talha El-Ensari evi korur,

Ömer vasiyeti içeride okunur,

Adaylıktan ilk çekilen Osman olur,

Cennetle müjdelenen güzel Hz. Osman’ım.

Herkes fikrini açıklar halifelik için,

Hz. Ali der “Resûlün akrabasıyım geçin,

Hz. Osman’ı layık görüyorum O’nu seçin.”

Gönlü büyük, eli açık Hz. Osman’ım.

Hz. Osman der: “Hz. Ali bu işe uygundur”

İki yiğit arasında karar çok zordur,

Hz. Osman, halifeliğe uygun bulunur,

Meleklerin haya duyduğu Hz. Osman’ım.

O evde Hz. Osman’a herkes bey’at etti,

Bütün halk Osman’a bey’at yeminindeydi,

O Muhammed’e uyacağına yemin etti,

Şayan-ı hâya bilinen Hz. Osman’ım.

Sahabede olmadı siyasi rekabet,

Onlar hep yapardı Allah yoluna davet,

Gözetilmiş olurdu böylece adalet,

Davasına pek sadık olan Hz. Osman’ım.

Ömer otoritesi huzur teminiydi,

Hz. Osman, güzel hıza aynen devam dedi,

Ermenistan, Afrika, Kıbrıs fethedildi.

İki nur sahibi olmuştur, Hz. Osman’ım.

İran’da çıkan ayaklanma bastırıldı,

İdari kadroda değişiklik yapıldı,

Ömer vasiyetiyle valiler kalmıştı,

Meleklerin haya duyduğu Hz. Osman’ım.

Senesi dolunca hemen atar valileri,

Mekke’ye; Nabi bin Abdilharis El-Huza’i,

Taif’e de; Süfyân bin Abdullah Es-Sakafi,

İlk iman edenlerden olan Hz. Osman’ım.

Cened’e; Abdullah bin Ebi Rabi’a Mahzumi,

Kûfe’ye: El-Muğıra bin Şa’be Es-Sakafi,

Muaviye bin Ebi Süfyân’da Şam valisi,

İki nur sahibi olmuştur, Hz. Osman’ım.

Ya’la bin Münebbih, olur Sana valisi,

Osman bin Ebi’l-As’da Bahreyn’in valisi,

Basra valisi ise; Ebû Musa El-Eş’ari

Davasına pek sadık olan Hz. Osman’ım.

Homs’a Umeyr bin Saad, vali yapılmıştır,

Mısır’a ise; Amr bin El-As atanmıştır,

Valilere Ahireti hatırlatmıştır.

Davasına pek sadık olan Hz. Osman’ım.

Ömer geleneği fetihlerle devam eder,

Muaviye Bizans’a doğru sefere gider,

Ammuriye (Ankara’ya)  dayanmıştır asker,

Gönlü büyük, eli açık Hz. Osman’ım.

Anadolu’ya pek çok sahabe gelmiştir,

O, Ubabe bin Es-Samit, Halid Biz Zeyd’tir,

Zeyd; Eyüp Sultan diye de bildiğimizdir,

Meleklerin haya duyduğu Hz. Osman’ım.

Ebu Zer El-Ensari, Anadolu’ya gelir,

Şeddad bin Evs’de aynı kafile içindedir,

Hz. Osman emriyle onlarda fethe gelmiştir,

Utanma hissinin bendesi Hz. Osman’ım.

Kûfe valisi Muğire’yi azletmişti,

Sa’d bin  Ebi Vakkas’ı vali tayin etti,

O da, Peygamberin dostlarından biriydi,

Şayan-ı hâya bilinen Hz. Osman’ım.

Mısırlılar vali değişimine isyan etti,

Bizans Heraklios’tan yardım istedi,

Ordu sırlarını da ispiyon etmişlerdi,

Davasına pek sadık olan Hz. Osman’ım.

Bizanslılar İskenderiye’yi istilada,

Huzursuzluklarda başlamıştı Kıpti halkta,

Amr bin El-As tekrar vali atandı Mısır’a

Meleklerin haya duyduğu Hz. Osman’ım.

Bizans yenildi ve Manuel öldürüldü,

Deylem üzerinde de sefere yüründü,

Rey halkıyla tekrar antlaşma ön gürüldü,

Cennetle müjdelenen güzel Hz. Osman’ım.

Sa’d bin Ebi Vakkas azlini istemişti, 

Beytü’l-Mal’e borcunu ödeyememişti,

Yerine kardeşi Velid bin Ukte geldi.

İlk iman edenlerden olan Hz. Osman’ım.

Velid, beş sene Kûfe valisi olmuştur,

Sabah namazında o Velid, çok sarhoştur,

İki rekatı, dört rekat diye kıldırmıştır,

Davasına pek sadık olan Hz. Osman’ım.

Hz. Osman, Velid’in bu halini duymuştu,

Ali’ye ceza için emir buyurmuştu,

Abdullah bin Cafer, onu kırbaçlamıştı.

Cennetle müjdelenen güzel Hz. Osman’ım.

Velid bin Ukte azledilmişti görevden,

Hak istemiş Sa’d bin El-As bin Ümeyye’den,

Vakkas, özür diler Ümmet-i Muhammed’ten,

İki nur sahibi olmuştur, Hz. Osman’ım.

Büyük sahabeler Medine dışındalar,

Fitnecilerde bundan cesaret almışlar,

Hz. Osman’a sinsice plan hazırlamışlar,

Cennetle müjdelenen güzel Hz. Osman’ım.

O, Sana Yahudi’si Abdullah bin Sebe,

Atıyordu İslâm dünyasına ilk fitne,

Ona uyar cahil Araplar ve göçebe,

Şayan-ı hâya bilinen Hz. Osman’ım.

Abdullah bin Sebe, zihin bulandırmakta,

İslâm’a yeni girenleri kandırmakta,

Yalanında Hz. Ali adını anmakta,

İlk iman edenlerden olan Hz. Osman’ım.

Kulaktan kulağa çoğalır dedikodu,

Osman, ashabı istihbarata gönderdi,

“Öğrenin Müslümanlar ne düşünür” dedi.

Davasına pek sadık olan Hz. Osman’ım.

Hicri otuz beşte Mısır’dan heyet gelir,

Kargaşa çıkarmak niyetleri bellidir,

Hz. Osman onları Medine’ye getirtir,

Cennetle müjdelenen güzel Hz. Osman’ım.

Nasihat, vaazla Osman onları över,

Onlara Allah yolunu nasihat eder,

Bu heyet “artık ikna olduk” deyip gider,

İki nur sahibi olmuştur, Hz. Osman’ım.

Ne var ki, art niyet beyne yuva kurmuş,

Mısırdaki isyana bunlar neden olmuş,

Hacc niyetiyle de tekrar yola koyulmuş,

Gönlü büyük, eli açık Hz. Osman’ım.

Fitne başı; El-Gafıki bin Harb El-Ka’ki,

Yahudi Abdullah bin Sebe’de gelmişti,

Sözde de Hz. Ali’nin destekçileriydi,

Meleklerin haya duyduğu Hz. Osman’ım.

Kûfe fitneciler başı; Amr bin El-Asam,

Zeyd bin Savhan El-Abdi’de olmuş onlardan,

Katılmış ona, Harkus bin Zübeyr Basra’dan,

Utanma hissinin bendesi Hz. Osman’ım.

Medine dışında konaklar fitne toplumu,

Hz. Osman gönderir Allah’ın Ali kulunu,

Hz. Ali’de ashaptan bir heyet oluşturdu,

Şayan-ı hâya bilinen Hz. Osman’ım.

Hz. Ali onlara hitaben hakkı konuşur,

Kararlı bir halde Hicret Yurdu’nu savunur,

Fitneciler ki, söz verip dönüşe koyulur,

Meleklerin haya duyduğu Hz. Osman’ım.

Hz. Ali Medine’ye dana dönmemişti,

Fitneciler ondan önce gelip yerleşti,

Hz. Ali onları görünce hiddetlendi,

Cennetle müjdelenen güzel Hz. Osman’ım.

Onlar sahte bir mektup çıkarıp verdiler,

“Bu emri valiye siz göndermişsiniz” der,

“İşte bizim öldürülme emrimiz” derler.

İki nur sahibi olmuştur, Hz. Osman’ım.

Fitneci hz. Osman’ın evini gözetler,

O’nu hep adım adım da takip eder,

Osman ile Cuma Namazı’na giderler,

Cennetle müjdelenen güzel Hz. Osman’ım.

Cuma çıkışı Osman onlara hitapta,

Hakim bin Cebele, Osman’a laf atmakta,

Onu destekliyor Muhammed bin Kutayra,

Şayan-ı hâya bilinen Hz. Osman’ım.

Fitneciler kargaşa çıkarmış orada,

Atılan taş değişmişti o güzel Osman’a,

Osman “Dokunmayın” der arkadaşlarına,

Meleklerin haya duyduğu Hz. Osman’ım.

Ali’nin oğlu Hasan, saldırmak istemiş,

Ashap da kılıçlarını kınından çekmiş,

Halife Osman onlara izin vermemiş,

Gönlü büyük, hiçte kızmayan Hz. Osman’ım.

Asiler, Medine’yi işgalde sınırsız,

Amaç Hz. Osman’ı evde bırakmak yalnız,

O der “Hicret Yurdu’nda kan akıtmayınız”

Cennetle müjdelenen güzel Hz. Osman’ım.

Sahabe çare arar bu çıkmaz duruma,

Koruma görevi verir oğullarına,

Hz. Osman “Silah kullanmayın” der onlara,

İki nur sahibi olmuştur, Hz. Osman’ım.

Büyük komutanlarda duyar bu olayı,

Ordu bile korumaya koşar Osman’ı,

Korkuya düşürür ordu, fitne başını,

Gönlü büyük, eli açık Hz. Osman’ım.

Osman okumakta iken yüce Kur’ân’ı,

Engelleyemezler dışarıda azgınları,

Evi kuşatmıştır hainlerin yangını,

Meleklerin haya duyduğu Hz. Osman’ım.

Azgınlar bastı Halife Osman’ın evini,

Başta fitneci, El- Gafıki bin Harb El-Kâ’ki,

Hz. Osman’a demirle vurarak şehit etmişti

Cennetle müjdelenen güzel Hz. Osman’ım.

Osman hanımı Naile koşar yardıma,

Kutayra bin Hamran ki, engel olur buna,

Kılıçla kıyar o güzelin parmağına,

Utanma hissinin bendesi Hz. Osman’ım.

Hz. Osman’ın evi ve Beytü’l-Mal yağmalanır,

Hakk Kelamı Kur’ân osman kanıyla kanlanır,

Osman ise Allah nazarında aklanmıştır,

Cennetle müjdelenen güzel Hz. Osman’ım.

Hicri otuz beş yılında öldü Osman,

Şehit edildiğinde seksen beş yaşında,

Hacc mevsiminde Medine’de esmiş tufan,

Allah rızası sana olsun Hz. Osman’ım.

Kur’ân’ı iniş sırasına göre dizmiş,

Kureyş okuyuşunu da ilke edinmiş,

Ona “Hazreti Osman Mushafı” denilmiş,

Şayan-ı hâya bilinen Hz. Osman’ım.

Bu nüshalardan yedi adet çoğaltılmış,

Önemli olan merkezlere dağıtılmış,

Buna uymayanlarda hep sahte sayılmış,

Meleklerin haya duyduğu Hz. Osman’ım.

Resûlden her ashabına bir sıfat geçmiş,

Hz. Osman’da haya güneşi tecelli etmiş,

Haya sırrı mümessili O’na verilmiş.

Şayan-ı hâya bilinen Hz. Osman’ım.

İlk iman edenlerden olan Hz. Osman’ım.

İki nur sahibi olmuştur, Hz. Osman’ım.

Cennetle müjdelenen güzel Hz. Osman’ım.

Gönlü büyük, eli açık Hz. Osman’ım.

Meleklerin haya duyduğu Hz. Osman’ım.

Utanma hissinin bendesi Hz. Osman’ım.

Şayan-ı hâya bilinen Hz. Osman’ım.

Davasına pek sadık olan Hz. Osman’ım.

Gönlü büyük, hiçte kızmayan Hz. Osman’ım.

Aciz kaldım Allah’ım, güzelleri tarifte,

Minnettâr kaldım Sana hep Şükran-ı nimette,

Osman gibi sadakat ver bize ibadette,

Resûlün şefaatine nail et Allah’ım.

Işık eyle onları Sana ulaşmada,

Rehber et yaşantımızın her damlasında,

Aklandır bizi İlâhi nur deryasında,

Resûlün şefaatine nail et Allah’ım.

Hulefâ-i Raşidin: Hz. Peygamberin koymuş olduğu hakkaniyet ve gerçek adalete dayalı siyasi idare sistemi. Raşid, dürüst, doğru yolda olan, rüştüne ermiş, halifeler demektir ki bunlar; Hz. Ebû Bekir, Hz. Ömer, Hz. Omsan ve Hz. Ali’dir. Bu dört halife 30 yıla yakın İslâm alemi için bir ışık olmuştur. Onların dönemine doğru halifelik dönemi denmiştir.

 Peygamberin Medine hicretinden başlayıp Hz. Ali’nin şehit edilmesine kadar süren kırk yıl İslâm’ın en güzel yılı ve idare edildiği dönemdir. Bu dönem tek örnektir. 

Şair: Abdullah Yaşar Erdoğan', '(Aşere-i Mübeşşere’nin üçüncüsü)          Hz.  OSMAN  (RA) Altı sene sonra doğdu Fil Vakası’ndan, Ticareti devraldı tacir babasından, Raşid ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":390,"source_url":"https://www.antoloji.com/hz-osman-ra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar', 'anilar-mehmet-lutfu-aydin-7oxbe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Binlerce sisli anı, yaşar beynimde yorgun

Yalnızlığımın hüznü, mutlu bu mutsuz canda

Hayallerim kaskatı, ıslak koynunda morgun

Yatar sevdana muhtaç, sensiz bu sonsuz handa', 'Binlerce sisli anı, yaşar beynimde yorgun Yalnızlığımın hüznü, mutlu bu mutsuz canda Hayallerim kaskatı, ıslak koynunda morgun Yatar sevdana...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/anilar-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAkılacak Mektuplar 14', 'yakilacak-mektuplar-14-mehmet-tas-b4s3b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalmadı beklemeye tahammülüm. Yıldızsız gecelerde sensizliğe söylenen şarkılar bile dilsiz. Tadı kalmadı sensizliğe yorumlu rüyaların. Gelmeyeceksin artık biliyorum. Biliyorum vakit çok geç. Kaç tren sensiz geçti bu istasyondan. Kaç gemi bekledim gözlerim ufuk çizgisinde asılı. Hasret yorgunuyum ey sevgili. Dudaklarımda eski bir türkünün solgun bir parçası kalmış. Şimdi o türküyü söylüyorum başı dumanlı, ardıç kokulu dağlara. Göçmen kuşlar da gitti. Yağmur da taşımaz bulutlar. Sana nasıl iletirim çaresizliğimi.

Kalmadı beklemeye tahammülüm. Zaman çare olmuyor yalnızlığıma. Bir üveyik kuşu uçsa uzaktan, bir kelebek konsa bir çiçeğe içimde bir şeyler uyanır. Baharsı gülüşlerin gelir aklıma.

Serde erkeklik var ya, ağlasa da bütün hasret çekenler, ben ağlayamam. Bir çoban çeşmesine anlatırım sensizliğimi. Bir dağ kırlangıcına. Ağlamak isteyip de ağlayamamak zehir olur da işler içime.

Kalmadı beklemeye tahammülüm. Ya sen gel ey sevgili ya da ölüm…', 'Kalmadı beklemeye tahammülüm. Yıldızsız gecelerde sensizliğe söylenen şarkılar bile dilsiz. Tadı kalmadı sensizliğe yorumlu rüyaların. Gelme...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yakilacak-mektuplar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'His', 'his-umut-engin-deniz-pw0gw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun zamandır sesini duymuyorum.

Duymak,

görmek gibi olmuyor.

Kaç zamandır yüzünü görmüyorum.

Görmek,

dokunmak gibi olmuyor.

Dokunmak,

koklamak gibi olmuyor.

Koklamak,

sarılmak gibi olmuyor.

Sarılmak, 

öpüşmek gibi olmuyor.

Duymayı, görmeyi, dokunmayı,

koklamayı, sarılmayı, öpüşmeyi...

Seni özledim.

Seni, çok özledim.', 'Uzun zamandır sesini duymuyorum. Duymak, görmek gibi olmuyor. Kaç zamandır yüzünü görmüyorum. Görmek, dokunmak gibi olmuyor. Dokunmak, kokla...', ARRAY['Türk Edebiyatı','Şiir','Umut Engin Deniz']::text[], 8.5, '{"poet":"Umut Engin Deniz","poet_slug":"umut-engin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nostalji-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Çanağı Gözlerim', 'kan-canagi-gozlerim-mehmet-lutfu-aydin-jmbtr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülmek? 

Unuttuğum sözcük 

Kahkaha? 

O da ne? 

Ölümsüz tanığıyım ölümlerin

Yaşatırken ölüleri içimde

Hangi ölüm daha korkunçtur ki, beklemekten ölümü? 

Dalga dalga ölümler fır dönüyor çevremde

Ana, baba, kardeş, dost çırpınırken girdabında beynimin

Kara delik açlığında yutulur birer birer

Dönmüşken kabristana beynimin kıvrımları

Nasıl gülerim? 

Nasıl? 

Kurgulanmış ölümler yağıyor insanlığın üstüne 

Zengin sofralarına meze isterik kahkahalar 

Adı konmamış bebeklerin kuruyan dudaklarında ölüm

Açlığın pençesinden kurtuluşun umudu 

Akbabalar bekleyişte sabırla 

Suskun globalist patronlar 

Gözler kör, kulaklar sağır, katılaşmış duygular

Saplanır yüreğime hançerimsi ağıtlar

Her dakika, her saniye

Binlerce masum insan buluşmakta ecelle

Ölümün adı konmuş, taşınmış manşetlere:

“Savaş kurbanları”

“Barış” utancından firarda

Kızıl renge boyanmış, göğün ıslak mavisi

Ölülerin koynunda barış ararken umut

Kan çanağı gözlerim dona kalır çaresiz

Kelimeler kifayetsiz dilimde

Yasaklanmış yüreğime gülüşler', 'Gülmek?  Unuttuğum sözcük  Kahkaha?  O da ne?  Ölümsüz tanığıyım ölümlerin Yaşatırken ölüleri içimde Hangi ölüm daha korkunçtur ki, beklemek...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kan-canagi-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-ali-kemal-i-cen-qfm5i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boşvermek kolay olsa

Çoktan boşverirdim

Melekler bile isyan eder

Şu garip halime

Yoruldum hasret bahçelerinde

Sensiz geçen gecede

Sevilmenin ne olduğunu 

Bilmeden ölmek istemem

Sana yüreğimi açmışım

Gel demişim,soframa buyur demişim

Genç mevsimler geçti yıllar geçti

Bir sen yoktun birde sevdan

Şimdi tek dileğim tanrımdan 

Alsın şu garip canı dünyadaki

Cehennemden,tutsaklıktan esaretten

Sana olan maphusluktan

21-12-2001', 'Boşvermek kolay olsa Çoktan boşverirdim Melekler bile isyan eder Şu garip halime Yoruldum hasret bahçelerinde Sensiz geçen gecede Sevilmenin...', ARRAY['Türk Edebiyatı','Şiir','Ali Kemal İçen']::text[], 8.5, '{"poet":"Ali Kemal İçen","poet_slug":"ali-kemal-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isyan-138-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amiral battı', 'amiral-batti-reyhan-tataroglu-6qshb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hayaliydi pembe gemi

                            tutmuştu mandal yelkeni

                            o kadar emindi kendinden

                            fark etmedi dibe çekeni

                            hala ufka bakıyordu

                            bir sigara yakıyordu

                            ıslandıkça ayakları

                            o kendini bırakıyordu

                            göründü birden kara

                            sevindi bağıra çağıra

                            son sözüydü''''karam aman aman''''

                            akıldan fukara', 'hayaliydi pembe gemi                             tutmuştu mandal yelkeni                             o kadar emindi kendinden               ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/amiral-batti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti', 'bitti-orhan-yildiz-dwlvj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzun yolların

kısa türküsü

Aklıma düştün

gece yarısı

yol bitti

gece bitti

ve sen bittin', 'Uzun yolların kısa türküsü Aklıma düştün gece yarısı yol bitti gece bitti ve sen bittin...', ARRAY['Türk Edebiyatı','Şiir','Orhan Yıldız']::text[], 8.5, '{"poet":"Orhan Yıldız","poet_slug":"orhan-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bitti-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Arama Bürosu', 'kayip-arama-burosu-muammer-erturan-iwwu9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok ararsın bu günleri 

derlerdi de 

kırılırdım gülmekten... 

Çocukluk mevsimiydi mevsim 

çok şeyler beklediğim günler yani 

''büyümekten''... 

İ''sinden haberim yok ya henüz 

ihanetin, ibneliğin... 

Çok ararsın bu günleri 

hey gidi gençlik hey! .. 

Dediklerinde 

gülüp geçtim gene... 

Cephaneliğe dönmüşken 

ülken ve dünya 

çocuklar bile öldürülüyorken 

kirli savaşlarda 

ve isyan sesleri yükseliyorken 

fabrikalarda

tarlalarda 

meydanlarda 

sömürüye ve savaşa karşı 

ve zoruna gidiyorken 

postal kakofonisiyle uyanmalar 

hesap sorar adamdan 

o deli kan

katılmazsan kavgaya... 

Çok ararsın bu günleri

elin ayağın tutuyorken henüz... 

Demezler mi hâlâ... 

El insaf! .. 

Yarım asra çeyrek kala 

hâlâ aynı hikâye... 

İşin kötüsü gülemiyorum da artık

anlatamıyorum da, 

Kayıp Arama Bürosu 

olmadığımı 

ve olmayacağimı asla... 

(''97)', 'Çok ararsın bu günleri  derlerdi de  kırılırdım gülmekten...  Çocukluk mevsimiydi mevsim  çok şeyler beklediğim günler yani  ''büyümekten''......', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kayip-arama-burosu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes huzur bulduğu yere gitsin', 'herkes-huzur-buldugu-yere-gitsin-muhsin-yener-a3kl6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“Herkes huzur bulduğu yere gitsin” dediler…

Ben sustum.

Çünkü huzur,

herkese aynı kapıyı açmazdı.

Ben de

şehitlerimizin huzuruna geldim…

Toprağın altında değil,

göğün en ağır yerinde

bekleyen o sessiz bakışlara.

Bir rüzgâr değdi yüzüme,

adı vatan oldu.

Bir taş konuştı içimde,

adı sabır oldu.

Ey Rabbim…

Bizi

vatansız bırakma,

bayraksız bırakma,

dilimizi sensiz bırakma,

Muhammed’siz bırakma…

Çünkü biz;

adımızı şehadetten alan

bir tarihin çocuklarıyız.

Bir düşme anında değil

bir diriliş anında varız biz.

Karanlığa eğilmek için değil,

karanlığı yarmak için doğduk.

Ve bilirim:

Bir milletin duası

kılıcından keskindir.

O yüzden ben

sessizce değil,

içimden haykırarak geldim

şehitlerin huzuruna…

Çünkü bazı gelişler vardır;

insanı değil,

insanlığı ayağa kaldırır.', '“Herkes huzur bulduğu yere gitsin” dediler… Ben sustum. Çünkü huzur, herkese aynı kapıyı açmazdı. Ben de şehitlerimizin huzuruna geldim… Top...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mutlu-ol-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum Yalan Olacak', 'biliyorum-yalan-olacak-mesut-yokus-7w044', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyorum yalan olacak

Gözlerin,ellerin ve sesin

Hatta şimdi bilmem nerdesin

Gönül evimden başka yerde yaşadın mı

Sardı mı başka gönülleri ye’sin

Bırak şafaksız bahtlara

Ufuksuz ümit yelleri essin

Kessin sensiz,aşksız her bağı

Şimdi ötelerin,ötedekilerin çağı

Kalmasa da senden hiçbir şey

Sürdüğünü sansın her şey

2004', 'Biliyorum yalan olacak Gözlerin,ellerin ve sesin Hatta şimdi bilmem nerdesin Gönül evimden başka yerde yaşadın mı Sardı mı başka gönülleri y...', ARRAY['Türk Edebiyatı','Şiir','Mesut Yokuş']::text[], 8.5, '{"poet":"Mesut Yokuş","poet_slug":"mesut-yokus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biliyorum-yalan-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-hasan-dogan-fp75d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensizlik sonsuz bir gece,

Yağarken karlar hatıralarımıza,

Gözlerimde hala vurduğun kelepçe,

Ya herkes sana benziyor ya da sen herkese.

Her saniye bulmaca çözmekte aklım,

Firar edecek gibi,

Sensizliğin sebebini çözemezse.

Ve ben dualar ediyorum Rabbime,

Bir anlam vermeyelim,

Sensizliğime, sessizliğine…', 'Sensizlik sonsuz bir gece, Yağarken karlar hatıralarımıza, Gözlerimde hala vurduğun kelepçe, Ya herkes sana benziyor ya da sen herkese. Her ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Doğan']::text[], 8.5, '{"poet":"Hasan Doğan","poet_slug":"hasan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensizlik-241-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişin …', 'gidisin-hasan-dogan-9hdgm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidişin …

Medeniyetten kovulmuş bir kral terzisi misali,

Dolanırken sensiz başı eğik sokaklarda,

Ne kadar benziyorduk taşlarla birbirimize,

İnsanlar tarafından ezilmek, önemsenmemek kaydıyla,

Müsaade ediliyordu varlığımıza.', 'Gidişin … Medeniyetten kovulmuş bir kral terzisi misali, Dolanırken sensiz başı eğik sokaklarda, Ne kadar benziyorduk taşlarla birbirimize, ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Doğan']::text[], 8.5, '{"poet":"Hasan Doğan","poet_slug":"hasan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gidisin-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-ethem-turan-4uq9m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sen 

Mutluluğum 

Kederim

Aşkım 

Sevgim 

Yüreğimdeki ateşim 

Heyecanım 

Hayat zevkim 

Baharım,kışım, yazım, güzüm

Yaşama sevincim

Ömrümün gülü 

İçtiğim sigaramda katran 

Ahşap masamda tahta kurum 

Kıldığım namazda duam 

Gözümde yaşım 

Dilimde ismin

Damarımda kanım 

Belleğimde siman 

Bir ben 

Yıkılmış viran 

Uğrunda olmuş perişan 

Yolunda   yolcun 

Kapında kölen

Mahpusunda  esirin 

Gönül bahçende diken 

İsmini heceleyen taleben

Anlıyorsun değil mi 

Seviyorum seni ben', 'Bir sen  Mutluluğum  Kederim Aşkım  Sevgim  Yüreğimdeki ateşim  Heyecanım  Hayat zevkim  Baharım,kışım, yazım, güzüm Yaşama sevincim Ömrümün...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-ve-ben-169-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldükten sonra', 'oldukten-sonra-mikdat-bal-5rsdd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir garip yaşarsın garip ölürsün

Kahraman olursun öldükten sonra

Öldüğünde birden meşhur olursun

Bir roman olursun öldükten sonra

Yanından geçmezdi dost sandıkların

Ters idi onlara inadıkların

Şimdi taranıyor boş sandıkların

Taranan olursun öldükten sonra

Oğlum yesin deyi  lokma yutmazdın 

Sert yatak içinde rahat yatmazdın

Dostlar unuturken sen unutmazdın

Bir canan olursun öldükten sonra

Bir kalem almaya yetmezdi gücün

Bakkaldı manavdı en büyük öcün

    Her zaman borçluydun bitmezdi suçun

Ne yaman olursun öldükten sonra

Bir selam verseydin alan olmazdı

Sözlerinde senin yalan olmazdı

   Dostlardan kapını çalan olmazdı

Aranan olursun öldükten sonra

Mikdat''ım giderim bana ne sizden

Bir gun gelirsiniz gittiğim izden

Ben gittikten sonra çıkarın gözden

Bir yalan olursun öldükten sonra', 'Bir garip yaşarsın garip ölürsün Kahraman olursun öldükten sonra Öldüğünde birden meşhur olursun Bir roman olursun öldükten sonra Yanından g...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/oldukten-sonra-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesekağıdı', 'kesekagidi-reyhan-tataroglu-bac20', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tıkış tıkış  ettim yüreğimi

                                   abur cubur şeylerle

                                   daldırdım içine küreğimi

                                   karıştırdım hey heylerle

                                   küçük bir yer aradım aşkı koyacak

                                   ne bilirdim ki kürek dibini oyacak

                                   patlak verdi birden boşaldı yüreğim

                                   kim yedirdi bunları...

                                   süpürge ver süpüreyim

                                   ne cıvıkmış bu yürek taşımadı aşkı

                                   ciddiye hiç gelemedi

                                   aşk pazarından kaçtı', 'tıkış tıkış  ettim yüreğimi                                    abur cubur şeylerle                                    daldırdım içine küreği...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kesekagidi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Doğmak İstiyorum', 'sana-dogmak-i-stiyorum-ali-cengiz-turan-5xewf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgi akan pınarlardan

  Aşk  fışkıran kurnalardan 

  Güneş gibi yukarlardan

  Sevgi yaymak istiyorum

  Sana doğmak istiyorum.

  Buhar olsam yeryüzünde 

  Buharlaşsam yeryüzünde.

  Bulutlara karışıpta

  Yağmur olmak istiyorum

  Sana yağmak istiyorum.

          Ali Cengiz Turan', 'Sevgi akan pınarlardan   Aşk  fışkıran kurnalardan    Güneş gibi yukarlardan   Sevgi yaymak istiyorum   Sana doğmak istiyorum.   Buhar olsam...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sana-dogmak-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Analizi', 'askin-analizi-gokay-ciftcioglu-hc166', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Amansız ve zamansız bir yolculuğun ilk durağında rastlıyordum sana 

Dönüş bileti cebimde, bir aşkın zaman kavramını yitirişini beraber izliyorduk

Çok sevildiğimi ne ben biliyordum o zamanlar

Ne de sen bu kadar çok sevileceğini tahmin edebiliyordun.

Susarak ve susayarak anı biriktiriyorduk yaşanmayan anlardan

Şimdi “senin beklediğini bilsem bu kadar gecikir miydim” diye soruyorum

Beklediğini biliyordum oysa, 

Senin benim bir gün geleceğimi bildiğin gibi.

Gülüyorduk, ağlıyorduk,sanıyorduk ve birbirimizi tanıyorduk

Eskiyorduk, eskitiyorduk,soruyorduk, anlatıyorduk ve seviyorduk

Oysa şimdi görüyoruz, duyuyoruz; geçiyoruz, unutuyoruz

Topladıklarımızı birer birer ön bahçeye gömüyoruz.

Uğurluyorduk birbirimizi tekrar görüşmek umuduyla,

Şimdi o görüşmeleri görmezden geliyoruz.

Esiyorduk, yağıyorduk, ısıtıyorduk, yakıyorduk hatta

Şimdi, sönen bir ateşten geriye kalan külleri bile sahiplenemiyoruz.

Neydi bizim birbirimizden istediğimiz, senin benden benim senden

Acıyan hatıraları kuytu bir köşeden izleyip unutulmalarını beklemek,

Yaşanmayan her anın bir gün silinip kaybolacağını düşünmek,

O çok sevdiğimiz karşılaşmalarla bir gün karşılaşamaz olmak

bizi mutlu edecek mi? 

Yıllar senden uzakta geçecek… 

Sen hep böyle uzaktan geçeceksin…', 'Amansız ve zamansız bir yolculuğun ilk durağında rastlıyordum sana  Dönüş bileti cebimde, bir aşkın zaman kavramını yitirişini beraber izliy...', ARRAY['Türk Edebiyatı','Şiir','Gökay Çiftçioğlu']::text[], 8.5, '{"poet":"Gökay Çiftçioğlu","poet_slug":"gokay-ciftcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/askin-analizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz olmasanız', 'siz-olmasaniz-levent-i-skenderoglu-x80o7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'siz olmasanız 

yani bir okuyan

 anlayan ve dinleyen 

şiirler neyi yazacak? 

bir milattır yazılan her okunduğunda 

minnet şiirlerden yana 

aşk sizden yana 

umut sizden yana', 'siz olmasanız  yani bir okuyan  anlayan ve dinleyen  şiirler neyi yazacak?  bir milattır yazılan her okunduğunda  minnet şiirlerden yana  aş...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siz-olmasaniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Üzgün', 'omur-uzgun-gokay-ciftcioglu-jbsgv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ömür üzgün

boynu bükük,

yıllar sürgün

çaresiz…

ömür üzgün,

yaşanacaklar bir köşede,

-artık yaşanamayacaklar-

çaresiz…

ömür üzgün

ve eksik

sensiz

çaresiz…

ömür üzgün

-gözlerin yalan-

çare yok…

çare var aslında

çare sensin.', 'ömür üzgün boynu bükük, yıllar sürgün çaresiz… ömür üzgün, yaşanacaklar bir köşede, -artık yaşanamayacaklar- çaresiz… ömür üzgün ve eksik se...', ARRAY['Türk Edebiyatı','Şiir','Gökay Çiftçioğlu']::text[], 8.5, '{"poet":"Gökay Çiftçioğlu","poet_slug":"gokay-ciftcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/omur-uzgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-gokay-ciftcioglu-635rm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'özlemin rengi mavi olmalı

çünkü sen karşıma çıkan

ilk mavi önlüklü özlemdin.

bu yüzden ben

senden sonra kimi sevsem

onu hep özledim.', 'özlemin rengi mavi olmalı çünkü sen karşıma çıkan ilk mavi önlüklü özlemdin. bu yüzden ben senden sonra kimi sevsem onu hep özledim....', ARRAY['Türk Edebiyatı','Şiir','Gökay Çiftçioğlu']::text[], 8.5, '{"poet":"Gökay Çiftçioğlu","poet_slug":"gokay-ciftcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ozlem-308-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seveceksin', 'seveceksin-ali-cengiz-turan-t5kr2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgilerin en büyüğü gerçek sevgi...

                                      neyi seveceksin? 

                                      kimi seveceksin? 

Güneşte yanmayı mı? 

Gölgede solmayı mı? 

,                                    doğanı seveceksin,

                                     canlıyı seveceksin...

Yeşillikler içinde

Kurağı seveceksin.

                                    sevmeyi bilmesende,

                                    bilmeyi seveceksin...

Canlıyım,insanım diyebilmen için

Canlılığa ait ne varsa seveceksin..

                                   İNSANSAN ŞAYET...........! ! ! ! ! ! ! ! !', 'Sevgilerin en büyüğü gerçek sevgi...                                       neyi seveceksin?                                        kimi seve...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seveceksin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstesen de Gidemezsin', 'i-stesen-de-gidemezsin-mustafa-alpaydin-vzcwz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İz bırakır hatıralar maziyi yok edemezsin 

Benim içim kan ağlarken bilirim ki gülemezsin 

Gururuna yenilirsin kalacağım diyemezsin 

Gönlün razı olmaz buna istesen de gidemezsin. 

Dalga gibi vurur sevdan vurgun yemiş yüreğime 

Rüzgar olur sert esersin hüzün yüklersin gönlüme 

İçerimde yaşıyorsun merhemsin sen dertlerime 

Gönlün razı olmaz buna istesen de gidemezsin. 

Sensizliğe dayanamam gittiğinde göreceksin 

Kara haber tez duyulur kalsaymışım diyeceksin 

Yüreğime taht kurmuşsun nasıl veda edeceksin 

Gönlün razı olmaz buna istesen de gidemezsin.', 'İz bırakır hatıralar maziyi yok edemezsin  Benim içim kan ağlarken bilirim ki gülemezsin  Gururuna yenilirsin kalacağım diyemezsin  Gönlün r...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alpaydın']::text[], 8.5, '{"poet":"Mustafa Alpaydın","poet_slug":"mustafa-alpaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istesen-de-gidemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkıyorsa Yüreğin! ..', 'sikiyorsa-yuregin-ali-orhan-gunaydin-gv0jy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğin sıkıyorsa eğer..

Sevgime karşılık ver..

Yoksa... ya  sus! 

ya da çek git! 

Artık bir rahat ver...

Benim sevgim ki...

ancak! ölüme kadar sürer...', 'Yüreğin sıkıyorsa eğer.. Sevgime karşılık ver.. Yoksa... ya  sus!  ya da çek git!  Artık bir rahat ver... Benim sevgim ki... ancak! ölüme ka...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sikiyorsa-yuregin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durma Git', 'durma-git-senol-alaca-6cho4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şimdi hasret yağmurlarındayım

şimdi yalnızlar gar''ındayım

şimdi akan gözyaşlarındayım

şimdi ak! düş artık gözlerimden

     

        durma git! yağmurlar başlamadan

        durma git! son trende kalkmadan

        gözyaşım daha henüz akmadan

        durma git! sakın el sallamadan

şimdi gözlerindi baktığım

şimdi tenindi kokladığım

şimdi sen dolu rüyalarım 

şimdi çık! git artık düşlerimden

          durma git! gözlerime bakmadan

          durma git! hayatı paylaşmadan

          iyice kokuna alışmadan

          alda git! sevdanı sol yanımdan 

sevdana yazılmış bu yürek 

uzun ayrılıklara ne gerek 

bir anlık yokluğun ölüm bana

gitme dur! bir tanem anlasana......', 'şimdi hasret yağmurlarındayım şimdi yalnızlar gar''ındayım şimdi akan gözyaşlarındayım şimdi ak! düş artık gözlerimden               durma gi...', ARRAY['Türk Edebiyatı','Şiir','Şenol Alaca']::text[], 8.5, '{"poet":"Şenol Alaca","poet_slug":"senol-alaca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/durma-git-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek İstek', 'tek-i-stek-gokay-ciftcioglu-kvwyu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu doğum günümde ben 

o iki karşılama töreninden birine gidememiş olmayı çok isterdim', 'Bu doğum günümde ben  o iki karşılama töreninden birine gidememiş olmayı çok isterdim...', ARRAY['Türk Edebiyatı','Şiir','Gökay Çiftçioğlu']::text[], 8.5, '{"poet":"Gökay Çiftçioğlu","poet_slug":"gokay-ciftcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/tek-istek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç', 'hic-ali-cengiz-turan-6jwvr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç bağırdı Ben büyüyüm ben büyüyüm,

Hiçin etrafı çevrilmişti yankı yaptı,

Büyüksün büyüksün.

Hiç sınırları zorluyor etrafını dahada dolduruyordu,

Bağırıyor,bağırıyor benden büyük varmı,

Hiçin hiçliği aklına gelmiyor,

Durmadan yiyor yediriyor.

Hazırlar dayanmıyor yavaş yavaş bitiyor.

Hiç bağırıyor bağırıyor,

Ses gelmiyor.

Hiç sonunda hiçliğini anlıyor,

O günleri yeniden yaşamak için,

Yalnızlık içinde yankılarla,çıkardığı sesle avunuyor.

HİÇ KENDİNE GELİYOR', 'Hiç bağırdı Ben büyüyüm ben büyüyüm, Hiçin etrafı çevrilmişti yankı yaptı, Büyüksün büyüksün. Hiç sınırları zorluyor etrafını dahada dolduru...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hic-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'His Nefis Ve Gönül', 'his-nefis-ve-gonul-mustafa-benkli-wmlxm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hisler; nefse göre mi? 

Yoksa, gönle göre mi? 

Onunla insan yaşar! ...

Nefse göreyse hisler,

Ön plânda nefisler; 

Plâna göre yaşar...

Gönle göreyse hisler,

Hisler gönülü besler; 

Ve kana kana yaşar! ...

Zamanı geçtiğinde,

O ana geldiğinde; 

O anı gönül yaşar...

Gönüller müştâk ise,

Bedenler köstek ise; 

Gönülle, gönül yaşar...

Teni gönlüyle yuyan,

Zannı umursamayan

gönlünce insan yaşar! ...', 'Hisler; nefse göre mi?  Yoksa, gönle göre mi?  Onunla insan yaşar! ... Nefse göreyse hisler, Ön plânda nefisler;  Plâna göre yaşar... Gönle ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/his-nefis-ve-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-sidika-seylan-1pqyt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün gelip elveda

Merhaba dostluğumuza 

diyeceğini biliyordum.

Buna rağmen

Sana gönlümün yüce köşelerinden

Sevgimi verdim

Yüreğimin derinliklerinden sımsıcak 

Aşk sundum.

Biliyordum

Bir gün yollarımızın ayrılacağını 

Buna rağmen

Sana gönül bahçemdeki 

Mutluluk meyvelerini yedirdim

Biliyordum

Bir gün el sallayıp

Arkana bakmadan gideceğini 

Buna rağmen

Senden bir can istedim

Senin bir parçan ben de kalsın diye 

Verdin de gittin.', 'Bir gün gelip elveda Merhaba dostluğumuza  diyeceğini biliyordum. Buna rağmen Sana gönlümün yüce köşelerinden Sevgimi verdim Yüreğimin derin...', ARRAY['Türk Edebiyatı','Şiir','Sıdıka Seylan']::text[], 8.5, '{"poet":"Sıdıka Seylan","poet_slug":"sidika-seylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/elveda-204-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamam kí', 'anlatamam-k-ramazan-ates-6lpae', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsanlara saygı vardır,

Benim güzel kültürümde.

Yaşlılara hürmet vardır,

Benim güzel kültürümde.

Müsadesiz konuşulmaz,

Saygısızca danışılmaz.

Her bir işe karışılmaz,

Benim güzel kültürümde.

Önce selam, kelam sonra.

Muhabbetse alçak tonda.

Ne bağırma ne çağırma,

Benim güzel kültürümde.

Konuşanı dinliyorsun,

Hiç araya girmiyorsun,

Hududunu biliyorsun,

Benim güzel kültürümde.

Hal hatırın sorar önce,

Derdini paylaşır senle.

Çare arar, üzülürde,

Benim güzel kültürümde.

Aç olanı o gözetir,

Öksüz yetim sevindirir,

Kendi giymez giyindirir.

Benim güzel kültürümde.

Düğün, dernek, toy kurarda,

Eğlencede, bayramında,

Gönül almak ilk sırada.

Benim güzel kültürümde.

Sevgi bütün için başı,

Ahlak onun öz gardaşı.

Adaletsiz olmaz işi,

Benim güzel kültürümde.

Hak yarattı bunu bilir,

Verdiği sözünde durur.

Eli açık gönlü boldur,

Benim güzel kültürümde.

Ramazan Ateş/Enschede-2.2.2006', 'İnsanlara saygı vardır, Benim güzel kültürümde. Yaşlılara hürmet vardır, Benim güzel kültürümde. Müsadesiz konuşulmaz, Saygısızca danışılmaz...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/anlatamam-ki-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avrupa', 'avrupa-sevinc-kavuk-mk1hh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fransa ve Britanya arasında olan en iyi şey denizdir.

Avrupada devletler arası organize edilen; 

Suça itme ve kapitalistliktir.

__________________________artı

Hem tabii birlikte oturmak gibidir; 

Herkes ev bütçesine uzanabiliyor.

Ve küçük olan

çöpü aşağı

indiriyor.

Tarih: Son sürat

Saat: Son derleme bu türde

____Yine de verili bir söz değil... olabilir de daha....', 'Fransa ve Britanya arasında olan en iyi şey denizdir. Avrupada devletler arası organize edilen;  Suça itme ve kapitalistliktir. ____________...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/avrupa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mahşer Gecesinde', 'bir-mahser-gecesinde-durmus-kaya-mz1ex', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '•	

Sen elifler sultanı bense bir eğri odun

Sana yakışmam için ocağına at beni! 

Gönlündeki listede tek benim adım olsun

Ulaştırsın menzile taktığın kanat beni! 

İçimdeki göklerin ayını sende gördüm! 

Sen benimle yaşarken neden boynumbükülür

Neden allı turnalar uçarken ben ölürüm? 

Gülersin gözlerinden menekşeler dökülür

Yüzünde gonca güller açarken ben ölürüm! 

Bana saplanan okun yayını sende gördüm! 

Kanım kaynayıversin sevgili toprağına

Bir mahşer gecesinde mecnunlara kat beni! 

Şu sevdalı soluğum külüngtür Kafdağına

Benim şirinim görse kıskanır Ferhad beni! 

Bin yıllık susuzluğun suyunu sende gördüm! 

Bu cinnet çarşısına çok uzak bir masalsın

Karlı dağlarca dirim durgun sularca ölüm! 

Dünyanın incisini istemem alan alsın

Benim düş karanfilim, elifim, gonca gülüm! 

İçimdeki göklerin ayını sende gördüm!', '•	 Sen elifler sultanı bense bir eğri odun Sana yakışmam için ocağına at beni!  Gönlündeki listede tek benim adım olsun Ulaştırsın menzile t...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Kaya']::text[], 8.5, '{"poet":"Durmuş Kaya","poet_slug":"durmus-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-mahser-gecesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarlı Tepe', 'ruzgarli-tepe-ali-cengiz-turan-pvxrl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani o rüzgarlı tepe vardıya sevgilim,

Birbirimizin oluşuna ay şahidimiz olmuştu.

Hani o bulutlara yakın sandığımız tepe,

Zamanı unutmuştukta güneş üstümüze doğmuştu.....', 'Hani o rüzgarlı tepe vardıya sevgilim, Birbirimizin oluşuna ay şahidimiz olmuştu. Hani o bulutlara yakın sandığımız tepe, Zamanı unutmuştukt...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ruzgarli-tepe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazdım', 'yazdim-kamer-taskin-rlh86', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bahardan,

Neşeden,

Aşktan 

Acıdan, 

Ayrılıktan,

Kalemi bulduktan sonra,

Bilmediğim sözcüklerle, 

Yazdım.', 'Bahardan, Neşeden, Aşktan  Acıdan,  Ayrılıktan, Kalemi bulduktan sonra, Bilmediğim sözcüklerle,  Yazdım....', ARRAY['Türk Edebiyatı','Şiir','Kamer Taşkın']::text[], 8.5, '{"poet":"Kamer Taşkın","poet_slug":"kamer-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yazdim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* MaKaS *', 'makas-mine-ozdemirtas-0knno', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yılların ardı sıra

boy ipliğim ilmik kaçırsa da

siz yine de

enine dikmeyi sürdürün hayatımı

sürfile yapar gibi

bastıra bastıra

İpiniz düğümlenip

iğnenize dolanırsa 

Benden size izin

Tereddütsüz başvurabilirsiniz

Makasa.

01/şubat/2006', 'Yılların ardı sıra boy ipliğim ilmik kaçırsa da siz yine de enine dikmeyi sürdürün hayatımı sürfile yapar gibi bastıra bastıra İpiniz düğüml...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/makas-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcum', 'yolcum-sidika-seylan-v1egy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saçları ak pak olmuş yolcum

Nereden gelir nereye gidersin

Yüzündeki derin çizgiler

Belli ki uzun yollardan gelirsin

Saçının her beyaz teli 

Kimbilir ne tecrübeler getirir

Yorğunluğu, çileyi, yılgınlığı mı 

Yoksa 

Hayatının meyvalarını mı getirir

Yüreğinin acıları 

Yağmurun cama vurduğu gibi

Yüzene vurur

Saçları ak pak olmuş yolcum

Gözlerindeki derin bakışlar 

İçimi deler

Anlarım ki

Sen de bir asırlık roman var

Ak pak olmuş yolcum

Sana iyi yolculuklar 

Yolun geçmişinden geleceğine nurla dolsun.', 'Saçları ak pak olmuş yolcum Nereden gelir nereye gidersin Yüzündeki derin çizgiler Belli ki uzun yollardan gelirsin Saçının her beyaz teli  ...', ARRAY['Türk Edebiyatı','Şiir','Sıdıka Seylan']::text[], 8.5, '{"poet":"Sıdıka Seylan","poet_slug":"sidika-seylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yolcum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne ve Yavru', 'anne-ve-yavru-ali-cengiz-turan-zauz2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anne sütüne alışmıştı,

Gözlerini anne sütüyle açmıştı,

Elem bir kaza,acı bir çığlık,

Annesinden ayırmıştı.

Sütlere alışamıyordu,

Süt annelere bile,

Bir koku arıyordu sütte,

Anne kokusu,

Bir türlü bulamayacağı anne kokusu.

Yıılar onu da anne yaptı.

Yavrusuna emdirdiği süte,

ANNE KOKUSU KATIYORDU......', 'Anne sütüne alışmıştı, Gözlerini anne sütüyle açmıştı, Elem bir kaza,acı bir çığlık, Annesinden ayırmıştı. Sütlere alışamıyordu, Süt anneler...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anne-ve-yavru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çılgınlığımız intihardı', 'cilginligimiz-intihardi-yahya-akbulut-uy1xu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yansıtamadım ne kem aynalara

Nne de buluştuğumuz sarnıçlara

Derinleştiğinde çılgınlığımızı.

Susuyordu kelepçeli dudaklarım.

Gülüşünde bedenimi gözlerin yakardı

Kuşlar bile oysa yüzümden anlardı! 

Kimseyi görmüyordu gözümüz

Ne başı vardı hikayemizin, ne sonu

Dev bir süngerdi içimizde yadsıdığımız

Günbegün eğlenceye benzettiğimiz....

Kurulmuştu saatimiz, varlığımız ihtiyardı

Avuntudan derinleşen çılgınlığımız intihardı...

03.02.2006 / Çorlu

www.yahyaakbulut.com', 'Yansıtamadım ne kem aynalara Nne de buluştuğumuz sarnıçlara Derinleştiğinde çılgınlığımızı. Susuyordu kelepçeli dudaklarım. Gülüşünde bedeni...', ARRAY['Türk Edebiyatı','Şiir','Yahya Akbulut']::text[], 8.5, '{"poet":"Yahya Akbulut","poet_slug":"yahya-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cilginligimiz-intihardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmenin Yaşı Yoktur/dörtlük', 'sevmenin-yasi-yoktur-dortluk-dilek-hokkaomeroglu-51nlc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaş ilerleyince inceden sızı düşer

Gözler bakmayı,eller tutmayı özler

Yürekte sızı kalır,yürekte yar odu

Bahardır ömrün sonu,sevmenin yaşı yoktur', 'Yaş ilerleyince inceden sızı düşer Gözler bakmayı,eller tutmayı özler Yürekte sızı kalır,yürekte yar odu Bahardır ömrün sonu,sevmenin yaşı y...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevmenin-yasi-yoktur-dortluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gözlüm', 'yagmur-gozlum-omer-kucukkaya-1k2lj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yağmur gözlüm merhaba...

bugün yine bir yorgunluk var üzerinde...

sanki bana olan sevdan tütüyor avuçlarının üşümüşlüğünden,

ve sanki sımsıkı sarılmak istiyorsun bana...

tutamıyor olsan bile ellerimi,

bilki gözlerim yüreğini gözetlemekte...

duyamıyor olsan bile sesimi

bilki rüzgar sana sevgimi getirmekte...

ben seni yağmur gözlüm diye sevdim..

ben seni gök gözlüm diye sevdim..

ben seni benim ol diye sevdim..

nerden bilirdim sensiz yok olacağımı...

duygularımın satır aralarında kayboluşu sırasında gördüm seni,

ve öylesine tutuldumki gözlerine...

taki o an gelinceye kadar anlayamadım senin bana olan büyük aşkını,

ta ki ben giderken uzaklara boynuma sarılıp gözyaşı dökene kadar....

03.02.2006  saat 00:08', 'yağmur gözlüm merhaba... bugün yine bir yorgunluk var üzerinde... sanki bana olan sevdan tütüyor avuçlarının üşümüşlüğünden, ve sanki sımsık...', ARRAY['Türk Edebiyatı','Şiir','Ömer Küçükkaya']::text[], 8.5, '{"poet":"Ömer Küçükkaya","poet_slug":"omer-kucukkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yagmur-gozlum-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Suç Sonbaharın', 'butun-suc-sonbaharin-melih-coskun-dgkas', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Böyle olmak istemezdim 

Hep hüzünden bahseden 

Güleç yüzlü bir çocuk gibi 

Gülümseyerek bakan acıyan yanlarına

Bu keder bana 

Armağanıdır düşen sarı yaprakların 

Belki hiç çıkmayacak bir doğum lekesi 

Belki ağır bir yük sırtıma yüklenmiş 

Onun içindir kendimi

Hayatın hamalı belleyişim

Belki sadece aşktan söz edebilirdim sana 

Kendi güzel günlerimden 

Evimin bütün odalarına girdiğinden güneşin

Sadece kendi sıradan kederlerimi anlatabilirdim sana 

Bireyin kurtuluşunu falan... 

Böyle olmak istemezdim ben de 

İnan bana 

Bütün suç sonbaharın...

2004', 'Böyle olmak istemezdim  Hep hüzünden bahseden  Güleç yüzlü bir çocuk gibi  Gülümseyerek bakan acıyan yanlarına Bu keder bana  Armağanıdır dü...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/butun-suc-sonbaharin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seslenişim Sana 5', 'seslenisim-sana-5-zeliha-bicer-wb6az', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yazmalarında nokta koyma,söyle hadi söyle anlatamadıklarını

Ben sensiz geçen günlerin gecelerin acısını

Boşver boşver densede onca olanlara

Ben yine seni severim sana gelirim

Değmez belki ben,benim demelerim,

Ama sana gelmelerim hiç boş olmadı 

Olmadığı kadar yüreğimle sana geldim

Ben seni severken değmez mi? 

Sen beni severken değmez mi? 

 O değildi yazmak istediğim

Değmezlere dair

Seni seviyorum, sevmem diyemem

Gözüm yaşında saklı sevdaların çoğu zaman

Hasretlerin martılarımda yüklü geldiklerinde

Ben seni sevdim sevmiyorum diyemem.', 'Yazmalarında nokta koyma,söyle hadi söyle anlatamadıklarını Ben sensiz geçen günlerin gecelerin acısını Boşver boşver densede onca olanlara ...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seslenisim-sana-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyleyim', 'neyleyim-i-brahim-kilinc-i62aw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaz imiş, kış imiş, sonbahar imiş

Beden harda, gönül darda, neyleyim

Çiçekler açılmış, ilkbahar gelmiş

Beden harda, gönül darda, neyleyim

Geceler, gündüzler, aylar karıştı

Dereler, tepeler, çaylar karıştı

Düğünler, dernekler, toylar karıştı

Beden harda, gönül darda, neyleyim

Yağmur olmuş, çamur olmuş, kar olmuş

İsmini yad etmek bize ar olmuş

Sanki dünya senin için var olmuş

Beden harda, gönül darda, neyleyim

Sevda sana gündüz, bana gecedir

Senden hayli engin, benden yücedir

Sanırım çözülmez bir bilmecedir

Beden harda, gönül darda, neyleyim', 'Yaz imiş, kış imiş, sonbahar imiş Beden harda, gönül darda, neyleyim Çiçekler açılmış, ilkbahar gelmiş Beden harda, gönül darda, neyleyim Ge...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neyleyim-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlana''yı Gezerken', 'mevlana-yi-gezerken-durmus-kaya-gejg8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllarca mezarda kalmış gibiydim,

Gel! dedin, gelişim sana Mevlana! ...

Hasreti soyundum vuslatı giydim

Dol! dedin, doluşum sana Mevlana! ...

Gönlümüz düşmüşken binbir sırattan

Sesin kopup geldi yedinci kattan

Rüzgarlara binip bengi kanattan

Sal! dedin, salışım sana Mevlana! ...

Nurdan bir mahşere sundun özümü

Açtım ellerimi yumdum gözümü

Benliğime doğru döndüm yüzümü

Dal! dedin, dalışım sana Mevlana! ...

Ulu çınarlarca kut ırladığım

Kanımı döktüğüm ıtırladığım

Şol Bezm-i El-est’ten hatırladığım

Ol! dedin, oluşum sana Mevlana! ...', 'Yıllarca mezarda kalmış gibiydim, Gel! dedin, gelişim sana Mevlana! ... Hasreti soyundum vuslatı giydim Dol! dedin, doluşum sana Mevlana! .....', ARRAY['Türk Edebiyatı','Şiir','Durmuş Kaya']::text[], 8.5, '{"poet":"Durmuş Kaya","poet_slug":"durmus-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mevlana-yi-gezerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamsın', 'sevdamsin-dilek-hokkaomeroglu-j9r1r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '__________Sevdanın öyküsü sana

Ayrılığın acı oku bana

Bir yudum şarap sana

Bir  kadeh gözyaşı bana

_________Sen gül sevdam

Ben ağlarım sılada...

Sen gel sevdam...

Ben ölürüm yolunda

_______Sen yaşa sevdam

Sana kalan aşk

Bana kalan ayrılıklarla...

Güneş doğsun pencerene

Karanlık pusu kursun yüreğime

Dikenler acıtsın canımı...

__________Yeter ki

Sen gül ben ölürüm yolunda

________Ben ağlarım sevdam sen yaşadıkca...

Değmez mi? 

_________Sevdam ölümüne sana...', '__________Sevdanın öyküsü sana Ayrılığın acı oku bana Bir yudum şarap sana Bir  kadeh gözyaşı bana _________Sen gül sevdam Ben ağlarım sılad...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevdamsin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saol Azrailim', 'saol-azrailim-omer-kucukkaya-broik', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'günaydın sevgilim....

şu an saat 00:28

ve günlerden 03 şubat

yıl ise 2006...

ve sen hoş ve loş yatağında yatarken,

ben bu satırları yazıyorum sana,

belki de şuan uyanmış beni arıyorsundur yatağında...

ama yokum, bahçedeyim...

sen o kadar masum uyurken öpemedim seni,

beni affet masumluğunu bozamadığım için..

sabahın ışıklarına daha çok varken

dışarısı soğuk ve puslu! 

düşünüyorumda ilk günümüzü,

sadece gülüyorum

biraz ıslanmak 

bana hiç iyi gelmiyormuş aslında...

sen o kadar sıcakken uzak dur kaloriferlerden ve sobalardan...

ne bileyim sana tekrar aşık olmak zor gelir yüreğime...

hele umut varken

irem i hayal ederken daha zor gelir...

sen nerden çıktın karşıma? 

kimsin? 

yoksa 

anladım sen benim azrailimsin...

evet azrailim olmalısın...

yoksa neden beni başkasının öldürmesine izin vermiyorsunki? 

yada başkalarının beni yok etmesine

beni ezmelerine...

evet başka yolu yok oda melek değilmi zaten..

anladım sen en son benim canımı alacaksın..

bu dünyadan beraber gideceğiz

beraber gelmemiş olsak bile....

saol meleğim azrailim herşeyim,

sen benim yarı açık dem çekmiş çay keyfim...

yorgunluğum yüreğim yürekliliğim

saol benim herşeyim....', 'günaydın sevgilim.... şu an saat 00:28 ve günlerden 03 şubat yıl ise 2006... ve sen hoş ve loş yatağında yatarken, ben bu satırları yazıyoru...', ARRAY['Türk Edebiyatı','Şiir','Ömer Küçükkaya']::text[], 8.5, '{"poet":"Ömer Küçükkaya","poet_slug":"omer-kucukkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/saol-azrailim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cezir', 'cezir-aysenur-yazici-vmho0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle bir cezir başlamış ki insanoğlunda,

çekilmedik yeri kalmamış merhametin,

..huzurun, insaniyetin...

Kabuk altında kanar bırakılmış

Açlık, endişe, ürkütülmüş tîn...

kasık kaşınması için sevişir olmuşlar,

aşk yok, içinde erimek yok aîdiyetin...

can çekişen her melek nefsini sınar,

tırmalayan her şeytan ömürlere kasıt! 

hatırla...yola çıkarken neydi niyetin? 

akçe için her şey mübah! 

kıran girmiş edebe,

ehemmiyeti artık yok mahremiyetin...

Çalan çırpan dolaşır, 

katil azraile dalaşır,

paslanmıştır artık ederi izzetin...

MEDdi başlattı çarpıtılmış medeniyetin,

cezir ile eksiliyor ışığından  sâfiyetin,

...bilhassa aşk,... aşk yok artık,

....keşke kıymetini bilseydin...

         02.02.2006

         Romanya 

         (19:20) 

      Andrea and', 'Öyle bir cezir başlamış ki insanoğlunda, çekilmedik yeri kalmamış merhametin, ..huzurun, insaniyetin... Kabuk altında kanar bırakılmış Açlık...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cezir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öykü3', 'oyku3-levent-i-skenderoglu-ghwg9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir serçe konmuşsa yüreğine

Ürkütmeden sev onu

Köprülerin altından 

Çok sular akmışsa

Ve biz köprünün

Üzerindeysek

Mutluluk deli atların sırtında

Rüzgara koşuyorsa

Sarı yapraklar

Hasretle bekliyorsa bizi

Ayrılık uzak dağlarda kalmışsa

Sel olup akalım kırmızıya

Damarlarımızdan yürüyüp giden

Kulağımızda çınlayan

Kayalara 

Kıyılara yazılan

Sevgiyse

Ya yağmur 

Anlıyorsa bizi…….

………………..

………………..

……………', 'Bir serçe konmuşsa yüreğine Ürkütmeden sev onu Köprülerin altından  Çok sular akmışsa Ve biz köprünün Üzerindeysek Mutluluk deli atların sır...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/oyku3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız seninle', 'yalniz-seninle-orhan-kutlu-upgmc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinde okumak isterdim hayatı 

Bir çocuk gibi tutup ellerinden 

Yürümek isterdim güvenle 

Sevginin yollarından. 

Gelmek isterdim peşinden 

Gölgen olup 

Nereye gitmek istersen. 

Ama yalnız seninle.', 'Gözlerinde okumak isterdim hayatı  Bir çocuk gibi tutup ellerinden  Yürümek isterdim güvenle  Sevginin yollarından.  Gelmek isterdim peşinde...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalniz-seninle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama Hiç Unutmadım ki', 'ama-hic-unutmadim-ki-birsen-ates-69szr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'geldin 

yüreğimde gelincikler açtı 

umarsız bekleyişlerim 

son bulmuştu karabasanlarım 

inanmıştım sözlerine 

farklıydın yüreğimde 

yanındaydım tüm saflığımla 

sıcacık güneşim olmuştu 

gülüşlerim 

geldin 

geceler boyu seni düşünür oldum 

yokluğunda uykularım bölündü 

ben seni bu kadar severken 

beni bırakıp sensiz 

gittin ağlayan yarınlarıma 

ben senin için yaşarken 

sen benden daha çok 

ölümü sevdin 

ölümü 

huzur içinde uyu 

bu gün senin doğum günün 

ben seni hiç 

ama hiç unutmadım 

03.02.06', 'geldin  yüreğimde gelincikler açtı  umarsız bekleyişlerim  son bulmuştu karabasanlarım  inanmıştım sözlerine  farklıydın yüreğimde  yanınday...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ama-hic-unutmadim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurur', 'gurur-orhan-kutlu-iutic', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kara kedimi geçti aramızdan, 

Sen bana küs ben sana küs. 

Sebep ne buna 

Suçlu kim. 

Kim geri adım atacak 

Yüzü gülerek; 

Merhaba 

Nasılsın diyecek. 

Kim daha çok severse 

Bence o söyleyecek. 

Suçsuz bile olsa.', 'Kara kedimi geçti aramızdan,  Sen bana küs ben sana küs.  Sebep ne buna  Suçlu kim.  Kim geri adım atacak  Yüzü gülerek;  Merhaba  Nasılsın ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gurur-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evren', 'evren-ali-cengiz-turan-tzezb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Donmuş bir kış günü evren yıldız kaynıyordu,

Her yıldız gelinlik giymiş dünyada,

Varlığını kanıtlarcasına kendi resmini kazıyordu.

Ayak seslerim ayak seslerimi çağırıyordu.

Yürüdüm,yürüdüm......

Yürüdükçe ve düşündükçe,

Evrenin içinde KAYBOLDUM! ! ! ! ! ......', 'Donmuş bir kış günü evren yıldız kaynıyordu, Her yıldız gelinlik giymiş dünyada, Varlığını kanıtlarcasına kendi resmini kazıyordu. Ayak sesl...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/evren-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nöbet Sevginin', 'nobet-sevginin-ali-cengiz-turan-8g3hs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kirlenmiş doğa gibi kötülüklerin,

Sardığı dünyamızda nöbet sevginin.

Ölümün sardığı cesetlerinin,

Feryadından bıktık nöbet sevginin....

Fidanlar kesildi ağaç olmadan,

Köküne,çevresine meyve sunmadan,

Bütün güzelliklere hayret doymadan,

Hasret kaldık sevgiye nöbet sevginin.

Nefretler kötülere kötülüklere,

Mücadele verelim tüm güzelliklere,

Sevgiyle bakmayan bütün gözlerin,

Bakışından bıktık NÖBET SEVGİNİN...! ! ! ! ! ! ! !', 'Kirlenmiş doğa gibi kötülüklerin, Sardığı dünyamızda nöbet sevginin. Ölümün sardığı cesetlerinin, Feryadından bıktık nöbet sevginin.... Fida...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nobet-sevginin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün baksam ki gelmişsin', 'bir-gun-baksam-ki-gelmissin-sinan-aydindag-c85hx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '02.Şubat.2006

Bir gün baksam ki gelmişsin

Hasretine özlemine son vermişsin

Bak şimdi gözlerime içi gülüyor, içim gülüyor

Yüzyılların vermiş olduğu yaralardan sonra

İçim içime sığmıyor, sevginle dolup

Seninle taşıyor

Bir gün baksam ki gelmişsin

Dudaklarında bir buket buse getirmişsin

Gözlerinle gözlerimi süzerken canım

Birden yaralarıma merhem oluvermişsin

Bir gün baksam ki gelmişsin...

Bir gün bir gün mutlaka geleceksin

Gördüğüm bu düşlere son verip

Sıcak evimize beyaz gelinliğinle gireceksin

Hiç ayrılmamak dileğiyle....', '02.Şubat.2006 Bir gün baksam ki gelmişsin Hasretine özlemine son vermişsin Bak şimdi gözlerime içi gülüyor, içim gülüyor Yüzyılların vermiş ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gun-baksam-ki-gelmissin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-levent-i-skenderoglu-92st4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstesem de

 Bitmeyecek bir rüyadayım.

Uyansam ağlarım diye

Yorganın altından başımı 

Hiç çıkarasım gelmiyor.....', 'İstesem de  Bitmeyecek bir rüyadayım. Uyansam ağlarım diye Yorganın altından başımı  Hiç çıkarasım gelmiyor........', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ruya-234-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birikir Gözyaşların Yanağımda', 'birikir-gozyaslarin-yanagimda-okan-savci-p65ta', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurduğum düşleri

Bozmakla meşgulsün…

Olsun,

Ben yine yazarım! 

Masumiyetini dizerim elbet

Sahipsiz kalmış uyaklarına…

Sonra

Bu kentte gece olur

Ağlayışını kimse görmese de

Birikir göz-yaşların yanağımda...

Öğretmensin şimdi

Şehirlerde büyümüş o kız çocuğu

Yakında gelin olacak

Ağlayarak gittiği kasabaya! 

Sizin oraya 

Fena bastırdı kış..

Gazetelerden okuyorum.

Artık sen de

Üşümeyi öğrendin.

Bunu

İçimi ürperten 

Sıcacık bir hasretten anlıyorum…', 'Kurduğum düşleri Bozmakla meşgulsün… Olsun, Ben yine yazarım!  Masumiyetini dizerim elbet Sahipsiz kalmış uyaklarına… Sonra Bu kentte gece o...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/birikir-gozyaslarin-yanagimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırımlarında Hüznü Kalmıştır Bu Adamın', 'kaldirimlarinda-huznu-kalmistir-bu-adamin-okan-savci-ybcr5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yazmadım

Hiçbir şehrin

Hiçbir duvarına adını....

Çünkü 

Şehirler değil sevgili

Şiirler tutuyor aşkın kaydını...

Ama yine de 

Bir vapur var 

İstanbul’da adını taşıyan..

Çoktan silinmiş olsa da 

Sokağından ayak izim

Kaldırımlarında hüznü kalmıştır bu adamın...

Bir vuslat alacağım var Ankara’dan

Kalsın öylece..

Sonuçta

Hala kavuruyor

Avuç içlerimi parmakların

Sensiz değilim ki ben? 

Düşlerimde hükmü yok,

Ardından devirdiğim yılların..', 'Yazmadım Hiçbir şehrin Hiçbir duvarına adını.... Çünkü  Şehirler değil sevgili Şiirler tutuyor aşkın kaydını... Ama yine de  Bir vapur var  ...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kaldirimlarinda-huznu-kalmistir-bu-adamin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlamanın Eylemsizliği', 'suclamanin-eylemsizligi-orbay-eken-4nxsk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Suçlayın

Karanlığın ardından

doğan güneşi

Yıldırımları, tufanları

Sizin gidemediğiniz

yerlere gidenleri

Anlayamadıklarınızı

Gözlerinizi, kulaklarınızı

Yazamadıklarınızı

Anılarınızı

Bilemediklerinizi

Bırakıp gidenleri

Ölenleri

Nedenleri

...kaderinizi...

Haydi suçlayın

kendinizi...', 'Suçlayın Karanlığın ardından doğan güneşi Yıldırımları, tufanları Sizin gidemediğiniz yerlere gidenleri Anlayamadıklarınızı Gözlerinizi, kul...', ARRAY['Türk Edebiyatı','Şiir','Orbay Eken']::text[], 8.5, '{"poet":"Orbay Eken","poet_slug":"orbay-eken","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/suclamanin-eylemsizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimi Öpsem Gamzeleri Kanıyor', 'kimi-opsem-gamzeleri-kaniyor-okan-savci-iwl73', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi 

Başkasının yanağında

Parmak uçlarından 

Ellerime bulaşan kırgınlık...

Kimi öpsem 

Sanki gamzeleri kanıyor.

Herkeste biraz sen var anlayacağın

Bir parça da yalnızlık…

Baktığım son gözlerin bebeğinde

Hep sendin ağlayan! 

Ve ben 

Kime dokunduysam son hikayelerde,

Sabahında 

Terk edilmiş gözlerle uyandım uykudan…

Kahvaltımı hazırlayıp gitti birisi..

Diğeri aynaya

Daha doğrusu yalnızlığıma

Rujuyla şiirler ekledi..

Anladım ki; 

Yüzünden öte 

Güneş yokmuş karanlığıma..', 'Şimdi  Başkasının yanağında Parmak uçlarından  Ellerime bulaşan kırgınlık... Kimi öpsem  Sanki gamzeleri kanıyor. Herkeste biraz sen var anl...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kimi-opsem-gamzeleri-kaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncinmesin Dudakların Yanağımda', 'i-ncinmesin-dudaklarin-yanagimda-okan-savci-ac5os', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sokağındayım...

Hala aklım

Ömrümde açtığı uçurumda 

Gülüşünün..

Perdelerde gölgen gezinmez oldu

Tadı da kalmadı senden sonra

Gençliğime uzanan herhangi bir öpüşün...

Sen çoktan öğretmen çıktın...

Ve bir sabah gittin

Yıllar önce geldiğin umutlarla! 

İçine bir hiçliği yükledin.

Ama bir mana ararsan şayet 

Bilesin ben varım

Naftalin kokan bavullarda...

Burası Bursa,

Biliyorsun...

Ve ara sıra 

Girişinde seni beklerim

Şehre-küstü istasyonunun..

İnsanlar iş güç derdinde 

Yalnız aylak olan benim

Mesaim geç başladığından ötürü 

O saatlerde..

Şimdilerde uslandım..

Kısa tutuyorum geceleri.

Ve

Beni taşımıyor artık meyhaneye ayaklarım..

Kendime bir kale kurdum sevgili.

Orada sen varsın.

Diplomanı alıp da terk ettiğin evi

Düşlerime kiraladım...

Bir hazan daha bitmek üzere 

Nerdesin? 

Düşüşümün üzerinden yıllar geçti,

Sokağına uzanan bayırda...

Ve artık sakal bırakmıyorum

Olur ya? 

Döner gelirsin

İncinmesin dudakların yanağımda...', 'Sokağındayım... Hala aklım Ömrümde açtığı uçurumda  Gülüşünün.. Perdelerde gölgen gezinmez oldu Tadı da kalmadı senden sonra Gençliğime uzan...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/incinmesin-dudaklarin-yanagimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter', 'yeter-mehmet-can-zi2y1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinde kalsın bırak gözyaşın..

Akmasın yerlere  yeter, akmasın..

Dayanamam hüzün kokan  sesine..

Kimseler  başka gözlerle bakmasın.

Akmasın gözyaşın..

Yeter..

Akmasın..', 'Gözlerinde kalsın bırak gözyaşın.. Akmasın yerlere  yeter, akmasın.. Dayanamam hüzün kokan  sesine.. Kimseler  başka gözlerle bakmasın. Akma...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yeter-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıları Bilenler(Aydan Bakış)', 'acilari-bilenler-aydan-bakis-ali-cengiz-turan-3bx1e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünyayı doyuranlar aya gidiyor,

Aydaki açlara yardım yapmaya.

Tok olan dünyalılar aya gidiyor,

Dünyadaki açlara aydan bakmaya......

Süper olan devletler aya gidiyor,

Hayatsız dünyaya hayat katmaya.

Acıları bilenler aya gidiyor,

20. asıra imza atmaya....

Dünyanın süperleri aya gidiyor,

Aydaki hastalara ilaç olmaya.

Bir dünya arıyorlar dünyadan büyük,

Gelecek nesillere dünya kurmaya....

Bir yaşam arıyorlar ömürden uzun,

Ömür kısa değildir yaşamdır küçük.

Bir dünya arıyorlar dünyadan büyük,

Dünya küçük değildir beyindir büyük...! ! ! ! 

Dünyada yaşıyorsak açları biliyorsak,

İnsanları görerek açlığa terk ediyorsak,

Uzanan elleri geri çeviriyorsak,

Ayı veyahut merihi fethetmek neymişki........! ! ! ! ! ! ! ! ! ! ! ! !', 'Dünyayı doyuranlar aya gidiyor, Aydaki açlara yardım yapmaya. Tok olan dünyalılar aya gidiyor, Dünyadaki açlara aydan bakmaya...... Süper ol...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/acilari-bilenler-aydan-bakis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakmaz…', 'birakmaz-mehmet-can-bahtx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanılmamak elde değil ki..

Bu tatlılık, aklı başta bırakmaz..

Gideceği yere götürür seni

Bu güzellik seni canlı bırakmaz..

Ya  mezarda gömülürsün vurulup..

Ya kıskanır öldürürsün.. durulup..

Sonra düşünürsün, tahta kurulup..

Bu cilveler sende huzur bırakmaz..

Bırakmaz..

Bırakmaz…', 'Yanılmamak elde değil ki.. Bu tatlılık, aklı başta bırakmaz.. Gideceği yere götürür seni Bu güzellik seni canlı bırakmaz.. Ya  mezarda gömül...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/birakmaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlığa Sesleniş', 'i-nsanliga-seslenis-ali-cengiz-turan-1u7v9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlayan Afrikalının gözyaşı selimidir? 

Parça parça dökülen kararmış tenimidir? 

Dünyaya açık bekler senin ellerinmidir? 

Yanan afrikalılar,solan afrikalılar....

Kararmış bedenlerden uzanan eller,

Dünya içinde mutsuz,ağlayan gözler,

Yavrusuna sarılmış yardım beklerler,

Yanan Afrikalılar,solan afrikalılar....', 'Ağlayan Afrikalının gözyaşı selimidir?  Parça parça dökülen kararmış tenimidir?  Dünyaya açık bekler senin ellerinmidir?  Yanan afrikalılar,...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/insanliga-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk deryasına dalan', 'ask-deryasina-dalan-mikdat-bal-t0dzx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece vakti gökyüzü, yıldızlarla süslenir 

Sevdayı çeken bilir, bakar, bakar hislenir 

Gönül gözü saf, duru duygularla beslenir 

Öyle bir meşrep bulur, içen kendinden geçer 

Aşk deryasına dalan, abıhayatı içer 

Ufuklara süzülüp, için, için kavrulur 

Aşk deryasına akar büklüm, büklüm kıvrılır 

Sevda yeli eser de yaprak gibi savrulur 

Kendi iradesiyle ne mekân ne yer seçer

Aşk deryasına dalan, abıhayatı içer

Gönlü gülistan olur bülbül konar dallara 

Lâlezar bahçesinde bürünerek allara 

Kavuşmak duygusuyla düşer uzun yollara 

Âdeta meczup olur başka boyuta göçer 

Aşk deryasına dalan, abıhayatı içer

Ozan Mikdadi', 'Gece vakti gökyüzü, yıldızlarla süslenir  Sevdayı çeken bilir, bakar, bakar hislenir  Gönül gözü saf, duru duygularla beslenir  Öyle bir meş...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-deryasina-dalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk', 'bosluk-ali-cengiz-turan-4h14k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünya içinde,dünya kurarım, 

Hayallerimle villalar yaparım, 

Dünyayı istediğim renklere boyarım. 

Öyle olurumki bazen yaşadığım dünyaya şaşarım, 

Canlılığa ait bişeyler ararım. 

Yaşanmış yaşanacak zamanı sorar,ararım, 

Hayallarimle cennet bahçelerine dalarım. 

Dünya içinde dünya kurar iki dünyayıda ararım, 

Dünyalara sığmadığım olur bazen. 

Küçük gelir dünyalar bana, 

Yeni yeni dünyalar ararım kendime. 

Ruhumdan lav gibi fışkırır güzellikler, 

Dünyaya yaymak için dünya ararım. 

Öyle olurum ki bazen, 

Dünyada dünyayı ararım. 

Canlılığa ait birşeyler ararım...! ! ! ! ! !', 'Dünya içinde,dünya kurarım,  Hayallerimle villalar yaparım,  Dünyayı istediğim renklere boyarım.  Öyle olurumki bazen yaşadığım dünyaya şaşa...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bosluk-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-ali-cengiz-turan-3ioix', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yarışma açacağım Konusu yok, 

Başlangacı sonu yok.Faydası hiç yok.. 

Bir yarışma açacağım şaşacaksınız... 

Yüzde on düşünen ülkede 

yüzde doksan reyting alacağım. 

Bir yarışma açacağım; 

Bekleyin görün... 

Yüzde onu düşünüyor ve üretiyorsa 

Yüzde doksanın içinde onları boğacağım 

Bir yarışma açacağım. 

Bu ülkeyi oynatacağım. 

Sorumsuz insanları mutlu yapacağım. 

Yüzde on düşünenleri ülke içinde çıldırtacağım 

ve bu ülkede en büyük kötülüğü..... 

Düşünmeyenlere yapacağım...! ! ! !', 'Bir yarışma açacağım Konusu yok,  Başlangacı sonu yok.Faydası hiç yok..  Bir yarışma açacağım şaşacaksınız...  Yüzde on düşünen ülkede  yüzd...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/serzenis-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Perisi Grubuna Dörtlük', 'siir-perisi-grubuna-dortluk-zeliha-bicer-s78tz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir Perisi Grubuna yazdığım..

Ne yarenlik edenler, ne dost bildiklerimiz

Can acıdı yaşım aktı gel dediklerimiz

Anlamaz,duymaz seni,sevgiden bihaberler

Böyle vurdum duymaza bir çift sözün olmalı', 'Şiir Perisi Grubuna yazdığım.. Ne yarenlik edenler, ne dost bildiklerimiz Can acıdı yaşım aktı gel dediklerimiz Anlamaz,duymaz seni,sevgiden...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/siir-perisi-grubuna-dortluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onur Annelere Kutlu Olsun', 'onur-annelere-kutlu-olsun-sevinc-kavuk-5c967', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mehmetçikler, Gaziler! 

Hem kötülüğün, hem kötülükler arasında

Bağımsızlık karakterinin

Bedelini ödeyen eşsiz gönüllüler! 

Gönüllü ve iyiler olarak kişiliğinizi

Bu çifte görevlerle varlığınızı

Yüreğimde ibret dolu anıyorum.

Yeryüzü varoldukça (inşallah!)      

Canını alnının ortasında taşıyan

Vatan ve birliğimizle

Sizler adına öncelikle 

Alınları öpülesi 

Onur annelere kutlu olsun!', 'Mehmetçikler, Gaziler!  Hem kötülüğün, hem kötülükler arasında Bağımsızlık karakterinin Bedelini ödeyen eşsiz gönüllüler!  Gönüllü ve iyiler...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/onur-annelere-kutlu-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Düştü Yüreğime', 'ay-dustu-yuregime-birsen-ates-9na3r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu gece açtı içimde

yine hüzün çiçekleri

ay düştü yüreğime

yakamoz oldum denizde 

oturdum sahile şiirler yazdım

ayaz tutmuş gecede

gelince bir martı 

bıraktım şiirleri

üşümüş koynuma aldım 

ağladı çığlık çığlığa

yine yağıyor mu 

yağmurlar gözlerimde

iyileşmemiş ki hala ruhum

kabuğu kalktı kanıyor

ben bu gece

inandığım her şeye 

yüreğimde ki 

sahte düşlere bile

ölüm gelse gülerim

bu gece açtı içimde

yine hüzün çiçekleri

03.02.06', 'bu gece açtı içimde yine hüzün çiçekleri ay düştü yüreğime yakamoz oldum denizde  oturdum sahile şiirler yazdım ayaz tutmuş gecede gelince b...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ay-dustu-yuregime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce gelin', 'i-nce-gelin-i-lhami-arslantas-fvwbd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnce gelin suya gider allanır

Elma yemiş al yanağı ballanır

Siyah perçem ak göğsüne  sallanır

Ne olaydım ona yaren olaydım

…………..Olaydım da muradımı alaydım

Keklik gibi yürüyüşü, boyunda

Gözüm kaldı gelir iken suyunda

Bir eşi yok bu gelinin soyunda

Ne olaydım ona yaren olaydım

…………….Olaydım da muradımı alaydım

Taze gelin ak teninde halı var

Mevla vermiş tatlı tatlı dili var

Kemer takmış bir incecik beli var

Ne olaydım ona yaren olaydım

…………….Olaydım da muradımı alaydım

Çok met etsem yalan derler sözüme

Bir ömürdü yüz sürseydim yüzüne

Can dayanmaz işvesine nazına

Ne olaydım ona yaren olaydım

……………Olaydım da muradımı alaydım

 Der İlhami herkes duysun sözümü

 Ona versem onda kalan gözümü

 Yare  vermez ben taşırdım közümü

 Ne olaydım ona yaren olaydım

……………Olaydım da muradımı alaydım', 'İnce gelin suya gider allanır Elma yemiş al yanağı ballanır Siyah perçem ak göğsüne  sallanır Ne olaydım ona yaren olaydım …………..Olaydım da ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ince-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığıntı Yüreğim', 'siginti-yuregim-hatice-guler-lursz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hüzün ayyuka çıktığında

Sığıntı yüreğimin tek tesellisi

Gönül evine sığınmak.

Vuslat ateşi sardığında

Avuçlarımda sevda ateşi

Sevdiğimin can nefesi

Can kafesimin tek neşesi

Sığıntı yüreğim...

Gönül kapısında sabahladı

Ve...

Sessiz,sedasız,sensiz

Hüzünleriyle çekip gitti...', 'Hüzün ayyuka çıktığında Sığıntı yüreğimin tek tesellisi Gönül evine sığınmak. Vuslat ateşi sardığında Avuçlarımda sevda ateşi Sevdiğimin can...', ARRAY['Türk Edebiyatı','Şiir','Hatice Güler']::text[], 8.5, '{"poet":"Hatice Güler","poet_slug":"hatice-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siginti-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülbahar.', 'gulbahar-i-lhami-arslantas-zpy1x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eğer bana bir vefalı yar isen,

Al gönlümü senin olsun Gülbahar.

Yüreğimi soğutacak kar isen,

Çal gönlümü senin olsun Gülbahar.

Kader diye yazıp namı sanımı,

Seher ile uyan uyar canımı,

Sevgi ol da dolaş deli kanımı,

Kal gönlümü senin olsun Gülbahar.

Bilirim ki bilmek senin inadın,

Şimdiye dek sınadınsa sınadın,

Aşk adına açı ver gel kanadın,

Dal gönlümü senin olsun Gülbahar. 

Ben de bir aşk encamının seliyim,

Ondandır ki aşk uğruna deliyim,

Sen baharsın bende bahar gülüyüm,

Çel gönlümü senin olsun gülbahar.

Der ilhami budur benim dileğim,

Yüreğim var tutmasa da bileğim,

Dünyam senin ekseninde meleğim,

Bil gönlümü senin olsun gül bahar.', 'Eğer bana bir vefalı yar isen, Al gönlümü senin olsun Gülbahar. Yüreğimi soğutacak kar isen, Çal gönlümü senin olsun Gülbahar. Kader diye ya...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gulbahar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlediğim', 'dusledigim-birsen-ates-dd3yw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu gece ellerini aradım 

birde içimi ısıtan gülüşlerini 

yine kayboldum şiirlerde 

en iyi sen bilirsin 

sabahlarken gece sessizce 

gözüm uykuda derininden 

karıştırdım şarkıları 

yine seni söylüyor 

acıtıyor 

en derinden uzaklığın 

şimdi sana 

sıkı sıkı sarılmak vardı 

bu gece ellerini aradım 

birde küçük bir kedi gibi 

kıvrılıp uyumak yanında 

uyanmaktı her sabah huzurla 

düşlediğim 

03.02.06', 'bu gece ellerini aradım  birde içimi ısıtan gülüşlerini  yine kayboldum şiirlerde  en iyi sen bilirsin  sabahlarken gece sessizce  gözüm uyk...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dusledigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni soluklarımdan kovuyorum...', 'seni-soluklarimdan-kovuyorum-nevin-kalafatoglu-61m4e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'orta yerindeyim gecenin

gecenin üstü geçmiş

gecenin altı gelecekmiş

sabaha bir şiir kaldı bir ben

bir  güneş

gecenin sesini soluyorum

denizin rengine  çok var

yıldızlardan az biraz

aydan hilal kırptım

ufkun çizgisi bir hayal

gözlerim beyaz

seni soluklarımdan kovuyorum...

3.2.2006

SİDE', 'orta yerindeyim gecenin gecenin üstü geçmiş gecenin altı gelecekmiş sabaha bir şiir kaldı bir ben bir  güneş gecenin sesini soluyorum denizi...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-soluklarimdan-kovuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Türlü Gelemiyorum', 'bir-turlu-gelemiyorum-birsen-ates-3x7pa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kızacaksın biliyorum

yine sabahladım

içim acıyor bu gece

uyursam da düşlerim 

umutlarım zemheride açtığım 

kardelen gibiydi 

bir günlük düştü mutluluğum

kısacık

bir kelebeğin ömrü kadardı

hüzünlerim

ne gelgitler yaşıyorum

serçe ürkekliğinde yüreğimin

dilimde aşka dair sözlerin

ve ben hiç susmuyorum

yüreğime düştüğünden beri

konuşuyorum

korkularım var

uzaklaştıramadığım

uzattıkça uzatıyorum

bir türlü gelemiyorum

kızacaksın biliyorum

ama ben bu gece

herkes uyurken

çığlık çığlığa

şarkımızı söyledim

03.02.06', 'kızacaksın biliyorum yine sabahladım içim acıyor bu gece uyursam da düşlerim  umutlarım zemheride açtığım  kardelen gibiydi  bir günlük düşt...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-turlu-gelemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yurdum', 'yurdum-gultekin-toga-qcqji', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayalinle yaşıyorum yetmiyor,

Özlemim dorukta dağ oldu Yurdum..

Aşkın bir dogdu ki,daha batmıyor,

Gönül gergefim de tığ oldu Yurdum..

Sende kaldı  sende benim baharım,

Esen rüzgarlardan seni koklarım,

Hiç küllenmez hatıralar yoklarım,

Ateşin ömrüme dağıldı Yurdum..

Ömür tükense de seni unutmam,

Senden başkasına gönlümü katmam,

Canımı koyarım aşkını satmam,

 Başım yalnız Hakk´´a eğildi Yurdum..

Solmayan çiçeğim,batmayan günüm,

Bugunum,yarınım geçmişim dünüm,

Yürek toprağımda yeşeren gülüm,

Sevgin zaman ile coğaldı Yurdum..

Ara yerde engeller var bırakmaz,

Bu yüzden gözümü yaşlar bırakmaz,

Sentezi´yi hasret haşlar bırakmaz,

Sensiz aylar sanki cağ oldu Yurdum..', 'Hayalinle yaşıyorum yetmiyor, Özlemim dorukta dağ oldu Yurdum.. Aşkın bir dogdu ki,daha batmıyor, Gönül gergefim de tığ oldu Yurdum.. Sende ...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yurdum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Titreyen Kalp', 'titreyen-kalp-gultekin-toga-hucjp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bülbül avaz eder aşkla,

Gülde kalbim titrer benim..

Derviş niyaz eder aşkla,

Dilde kalbim titrer benim..

Hasret ateşi yanınca,

Vuslattır çaresi anca,

Dosttan tarafa dönünce,

Yolda kalbim titrer benim..

Gariplerin ağladığı,

An sırtıma sarar dağı,

Gözlerinden çağladıgı,

Selde kalbim titrer benim..

Mum erirken aydınlatır,

Göz yaşı iç ferahlatır,

Hüseyin´i hatırlatır,

Çölde kalbim titrer benim..

Duygularla dolu dolu,

Gonca verir,ilham gülü,

Muhabbete gider yolu,

Telde kalbim titrer benim.

Sentezi kal hep özünle,

Bir ömür yan aşk közünle,

Gözlerim bakar hüzünle,

Külde kalbim titrer benim..', 'Bülbül avaz eder aşkla, Gülde kalbim titrer benim.. Derviş niyaz eder aşkla, Dilde kalbim titrer benim.. Hasret ateşi yanınca, Vuslattır çar...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/titreyen-kalp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Once insanlik', 'once-insanlik-ulya-erkman-1pgcd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gunesli bir yaz gunu 

Donuyordum eve

Biraz ileride garip bir manzara

Carpti gozume

Yasli bir kadin surukluyordu 

Nefes nefese

Yuvarlanmis sarilmis bir haliyi

Anlasilan evine

Kostum hemen yardim etmek

Istedim

Rumca konustu bana ne dedigini 

Bilemedim

Zarari yoktu tuttum haliyi obur ucundan

Yuklendim

Dinlenmek istedi biraz

Bende bekledim

Yakindik artik apartman kapisina

Torbalar kutularla yuklu genc bir kadin

Yanasti yanimiza

Tesekkur ederim dedi 

Anneme yardiminiza

Gelmezmisiniz bize yorgunluk kahvesi 

Yudumlamaga

Oturdum bir koltuga davetine peki

Diyerek

Buyrun dedi kopuklu kahve bir bardak su 

getirerek

Ictik kahvelerimizi bir taraftan da 

Sohpet ederek

Devam etsin dostlugumuz dedi genc kadin

Ayrildim onlardan peki diyerek

Ben yasli bir Rum kadinina degil 

Bir insana yardim etmistim

Onlar da bir Turku degil insanligi once gelen

Bir insani misafir etmislerdi', 'Gunesli bir yaz gunu  Donuyordum eve Biraz ileride garip bir manzara Carpti gozume Yasli bir kadin surukluyordu  Nefes nefese Yuvarlanmis sa...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/once-insanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıymeti yok sözünün', 'kiymeti-yok-sozunun-mikdat-bal-89vjg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kıymeti yok sözünün

Ne de güzel yüzünün

Kaşlarının gözünün

Karasına Bakan yok

Kim var halkı dinlesin

Kim bu zulmü önlesin

Halk derdinden inlesin

Yarasına Bakan yok! 

Yokki elde avuçta

Adam oldu havuç da

Artık torpil revaçta

Sırasına Bakan yok! 

Meydan ona kalırsa

Halkı ahmak bulursa

Rüşvet veren olursa

Kurasına Bakan yok! 

Gaz kesilir tezek yak

Yeter ki arama hak

İstersen ye ister bak

Kirasına Bakan yok

Kara bulut afakta

Soba yanmaz mutfakta

Halk isyanda sokakta

Narasına Bakan yok

Millet şaşırdı yönü

Yükseliyor ses tonu

Ne olur bunun sonu

Orasına Bakan yok

Bu dert nasıl çekile! 

Zamlar gelir ek ile

Para gider çek ile

Tuğrasına Bakan yok

Bakın nasıl Aktılar! 

Mazot benzin döktüler

Sıra ile yaktılar

Çırasına Bakan yok

Sözü bitti Mikdat’ın

Hazır ne varsa satın

Eserleri ecdadın

Mirasına Bakan yok', 'Kıymeti yok sözünün Ne de güzel yüzünün Kaşlarının gözünün Karasına Bakan yok Kim var halkı dinlesin Kim bu zulmü önlesin Halk derdinden inl...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kiymeti-yok-sozunun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer…..III', 'rubailer-iii-sevinc-kavuk-gcemx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sağlıklı bir alt yapı ise ve yücelmek mi hep insanlığa? 

Elbet rahim doğallığında başından gelişerek topuğa 

Yüce düşünceleri sahiplen alt yapılarında güçlen diye

Engin ve zengin bir duyguyu çağrıştıran gerçek işte! 

Şubat  2006', 'Sağlıklı bir alt yapı ise ve yücelmek mi hep insanlığa?  Elbet rahim doğallığında başından gelişerek topuğa  Yüce düşünceleri sahiplen alt y...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubailer-iii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damlaya Damlaya ''Gol'' Olur', 'damlaya-damlaya-gol-olur-ekrem-sama-g8jjh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni düşündürüyor kaç günden beri.

Yok canım, görememişler bu günleri...

Söylemişler kapatıp da gözlerini.

Ataları düşündüm... Şu sözlerini:

''Damlaya damlaya göl olur'' muş yani,

Nerede gölümüz, ortada yok, hani? 

Şu KİT ler, BİT ler, PİYANGO lar, TEKEL ler,

Ekmek teknemizde, cebimizde eller,

Seksen yıldır, toplanır vergiler, harçlar,

Yine de bitmiyor bu açıklar borçlar...

Dahası var, her sene borçlanıyorlar,

Düşmana, namerde milyarlarca dolar...

Borç faizleri geçmiş milli geliri,

Yok bunları açıklayan bilge biri...

Damla ne ki, çağlayan gibi akıyor,

Arkadaş, düşündükçe aklım çıkıyor...

Hani damladan göl, bir bakın şuraya? 

Bırakın gölü, oluşmalıydı derya...

Memur işçi açtır, emekli çırpınır,

Devlet faiz ödemek için yırtınır.

Borçlar, faizler ödedikçe artıyor,

Anlayın, burada bir gerçek yatıyor.

Tutmuş canavarlar tabanı tamamen,

Bir damla düşse, kapışıyorlar hemen.

Açıklanmıştı tüm batıklar, geçen yıl,

Beşyüz milyar dolarmış, süre seksen yıl...

Doymak bilmez, kara delikten de beter,

Seksen yıldır, damlayanları içerler.

Bizden elli kat zengin olmuşlar şimdi, 

Aynı ülkeler dün kat be kat fakirdi...

Her seçilen geliyor canavarıyla,

Bize uğraşmak kalıyor borçlarıyla...

Ey ata! Ettiğini ettin sen sağol! 

Nokta farkıyla attın bize büyük ''gol''! 

(İstanbul:23.01.2005)', 'Beni düşündürüyor kaç günden beri. Yok canım, görememişler bu günleri... Söylemişler kapatıp da gözlerini. Ataları düşündüm... Şu sözlerini:...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/damlaya-damlaya-gol-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer…..IV', 'rubailer-iv-sevinc-kavuk-dr0x9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeryüzü varolalı, kıymet kaybetmedik şey yaşanmadı amma 

Sözün kıymeti olmadığı henüz hiç bilinmedi, hiç söylenmedi

Laf bolluğu, halk yoğunluğu narası ola ki bir çare bula amma 

sözün kıymeti olmadığı henüz hiç okunmadı, hiç duyan olmadı

Şubat  2006 

Söz kıymetlidir! Hiç Kaybolmaz. 

Söz kıymeti değeriyle biçilir. Hiç eşitlenmez.

Her koyun kendi bacağından asılır. 

Sırtından geçindiğinin yüzünden dökülensin sen denilen...)', 'Yeryüzü varolalı, kıymet kaybetmedik şey yaşanmadı amma  Sözün kıymeti olmadığı henüz hiç bilinmedi, hiç söylenmedi Laf bolluğu, halk yoğunl...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/rubailer-iv-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç Böyle Değildin', 'sen-hic-boyle-degildin-alper-kuruk-4bxyy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen hiç böyle değildin hâline sen de şaştın

Ben sana yaklaştıkça sen hep yabancılaştın.

Sen hiç böyle değildin ne oldu şimdi sana? 

Güven,huzur verirdin gülümserken insana.

Sen hiç böyle değildin dolaşırdın şen-şakrak

Sevgiler aktarırdın sevgi ile bakarak.

Sen hiç böyle değildin eski hâlin gibi ol

Ben kahrolsam,yok olsam,eski neş''enle sağol...', 'Sen hiç böyle değildin hâline sen de şaştın Ben sana yaklaştıkça sen hep yabancılaştın. Sen hiç böyle değildin ne oldu şimdi sana?  Güven,hu...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-hic-boyle-degildin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gösterge', 'gosterge-alper-kuruk-2rua8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen söyleme ben tahmin edeyim geçmişini

Nelerle o günlerden bugüne gelişini.

Geleceği görmeye göze büyük engel var

İnsan hatalarını geçmişe bakıp anlar.

Bir anlamda geçmişin geleceğin demektir

Hata ve günahları bu,tekrar etmemektir.

Gününü yaşıyorken geçmişini de yaşa

Ergeç yaşanacaktır,yazılan gelir başa.

Günümü gün edeyim diyenlerse aldanır

Senin gibi herbiri böyle sevensiz kalır...', 'Sen söyleme ben tahmin edeyim geçmişini Nelerle o günlerden bugüne gelişini. Geleceği görmeye göze büyük engel var İnsan hatalarını geçmişe ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gosterge-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıkta bir gece', 'yalnizlikta-bir-gece-sevket-yucel-u8d4v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecemin tam ortası

Balkondayım yalnızlığımla

Yıldızlara bakıyorum

Yıldızlar uzak, sessiz

Sonra dönüyorum kendime

Ah diyorum

Bir sevgilim olsaydı bu saatlerde

Benim gibi yıldızlara bakan

Gece, usuldan bir esinti

Ey benim deli gönlüm

Bir türlü sığmıyor kendine

Gece ve ben, gökyüzünde yıldızlar', 'Gecemin tam ortası Balkondayım yalnızlığımla Yıldızlara bakıyorum Yıldızlar uzak, sessiz Sonra dönüyorum kendime Ah diyorum Bir sevgilim ols...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizlikta-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden seviyorum seni', 'neden-seviyorum-seni-sevket-yucel-3c3nb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gülümserken narçiçeği rengi

Birer güvercin konduruyorsun ellerimin üstüne

Yeşil yeşil bakıyorlar bana, mavi mavi

Sen konuşurken incecikten

Nişanlanıyor sözcükler

Sonra bir düğün, bir şenlik

Sen bakarken 

Türküleniyor gözlerin

İşte ben o anda, esrikleşiyorum birden

Sen sunarken sevgilere kendini

Ben daha güzel oluyorum, daha anlamlı

Kelebekler öpüşüyor içimde

Sen şarkı söylerken

Dans ediyor duvardaki perdeler

Portakal rengine dönüyor sesin

İşte tam o dakikalarda

Bembeyaz bir yolculuğa çıkıyorum ben.', 'Sen gülümserken narçiçeği rengi Birer güvercin konduruyorsun ellerimin üstüne Yeşil yeşil bakıyorlar bana, mavi mavi Sen konuşurken incecikt...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/neden-seviyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki sen', 'bendeki-sen-sevket-yucel-qfwn4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sözcüklerin var ya senin sözcüklerin

Biraz yeşil, biraz mavi, biraz pembe

Alıp götürüyorlar beni

Çocukluğumda gezdiğim bahçelere

Senin sesin

Sanki kavun, sanki gülen menekşe

Sesin, gökkuşağı renginde

Ellerin senin

Ellerinde ip atlıyor çocuklar

Bakışlarında gömlek değiştiriyor dünya

Bir de gülüşlerin var ya hani

Beni sana götüren

Sanki temmuzlu bir gün

Çubuğundan sarkan üzüm

Dalında kızaran şeftali

Hani bir de

Çağdaşlığın var ya senin

Dostluklara, güzellere akan

Gözlerinin göğünde

Sevdalara uçuyor ak kanatlı kuşlar.', 'Sözcüklerin var ya senin sözcüklerin Biraz yeşil, biraz mavi, biraz pembe Alıp götürüyorlar beni Çocukluğumda gezdiğim bahçelere Senin sesin...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bendeki-sen-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni güzellere yaz', 'beni-guzellere-yaz-sevket-yucel-uo88d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaz beni

Beni kendine yaz

Yaz gibi yaz, ilkyaz gibi

Temmuzdaki yaylalara yaz beni

Gülüşen otlara, çam kokularına

Bilebilsen, bunu nasıl özledim

Yaz beni

Haksızlığın boğulduğu günlere

Sevinçlere, sevdalara, barışlara yaz

Sıkıntaya yazma beni

Bana kendini uzat, bana bir özlü dünya

Beni dostluklara, güzellere yaz.', 'Yaz beni Beni kendine yaz Yaz gibi yaz, ilkyaz gibi Temmuzdaki yaylalara yaz beni Gülüşen otlara, çam kokularına Bilebilsen, bunu nasıl özle...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beni-guzellere-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek çiçek sözcüklerle gel', 'cicek-cicek-sozcuklerle-gel-sevket-yucel-wayc0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana gelirsen birgün

Birer karanfil tak günlerimin göğüslerine

Öyle gel

Benimle söyleşmek istersen

Genişlet kendini alabildiğince

Biraz deniz ol, biraz gökyüzü

Bana öyle gel ki ışıklanayım

Sen bende ben ol, ben sende sen olayım

Bana bahar gibi gel, kış gibi değil

Kelebekler kondur düşüncelerine

Gelmek istiyorsan eğer

Leylak leylak gel, sümbül sümbül

Sesinin dallarında öpüşen kuşlar olsun

Hem yıldızla beni, hem de güneşle

Beni kanatlandır sevgilerinle.', 'Bana gelirsen birgün Birer karanfil tak günlerimin göğüslerine Öyle gel Benimle söyleşmek istersen Genişlet kendini alabildiğince Biraz deni...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cicek-cicek-sozcuklerle-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönder bana', 'gonder-bana-sevket-yucel-urdeg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgilerin güneşini gönder bana

Üşüdüm, ısınayım biraz

Sarardım, yeşereyim

Bir de umut çiçeklerinden

		bir demet sun ellerime

Bir cümle gönder bana, öylesine sıcacık

İçinde güzeller konuşsun

Okuyunca büngüldesin yüreğim

Bir sevda postala bana

Sevdalı kuşlarla

Bir de çoçuk gülüşlerini koy içine o mektubun

Aldığımda dağıtırım onları bir bir

Bütün insanlara

Yaşanır olsun diye dünyamız.', 'Sevgilerin güneşini gönder bana Üşüdüm, ısınayım biraz Sarardım, yeşereyim Bir de umut çiçeklerinden 		bir demet sun ellerime Bir cümle gönd...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gonder-bana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne zaman görsem', 'ne-zaman-gorsem-sevket-yucel-i17gw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zaman çıksa karşıma

Serçeler sevişirdi yüzünün bahçesinde

Sözlerinin içinde büngül büngüldü günler

Ne zaman görsem yüzünü

Bir sevince uzatırdı bakışı

Öyle taze ışıklı

Öyle ince ki öyle

Yonca gözlü yeşillerin içinden

Ne zaman dursa karşımda

Beyaz beyaz ötüşürdü günlerim

Gökyüzü bir kelebeğe dönerdi

Bir sümbülü andırırdı yeryüzü

İçimde başlardı düğünler

Ne zaman otursak yanyana

Kanatlanır gözlerinde uçardım

Sanırdım ki bir kırmızı karanfil

Döne döne akışırdı sesinden.', 'Ne zaman çıksa karşıma Serçeler sevişirdi yüzünün bahçesinde Sözlerinin içinde büngül büngüldü günler Ne zaman görsem yüzünü Bir sevince uza...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-zaman-gorsem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrı değil bir olalım seninle', 'ayri-degil-bir-olalim-seninle-sevket-yucel-5xd7d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen bir yaklaş bana

Ben sana iki

Öldür içindeki öfkeyi, kini

Güzelliğin ömrü uzun, çirkinliğin ki kısa

Gel şu dünyamızı kirletmeyelim

Sen bir kiraz sun bana

Ben sana iki

Bak işte gökyüzü bir mavi türkü

Yeryüzünde nice canlı, nice renkler

Bir sarı kuş dokunuyor kemanına işte şimdi

Arılarsa bal alıyor çiçeklerden

Bir böcektir doğuyor gün doğarken

Gün batarken ölüyor o böcek

Bizimse ömrümüz ne kadar ki

Sen bir gel bana

Ben sana iki

Sen gelmezsen bana

Ben gitmezsem eğer sana

Yaşamın ne tadı kalır ki

Seninle birlikte

Bir dostluk bahçesinden dünyaya bakabilmek için

Ben çok giderim sana, daha çok giderim, daha çok

Sevgiler taşırım sana, sevinçler, güzellikler

Sen de bana biraz yaklaş yeter ki.', 'Sen bir yaklaş bana Ben sana iki Öldür içindeki öfkeyi, kini Güzelliğin ömrü uzun, çirkinliğin ki kısa Gel şu dünyamızı kirletmeyelim Sen bi...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ayri-degil-bir-olalim-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz', 'soz-sevket-yucel-exlgy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle buzlu sözler var ki

Üşütür, dondurur sizi

Öyle sıcak sözler var ki

İçinizi bahar eyler

Öyle acı sözler var ki

Göğsünüze giren hançer

Öyle tatlı sözler var ki

Koklanası güle benzer.', 'Öyle buzlu sözler var ki Üşütür, dondurur sizi Öyle sıcak sözler var ki İçinizi bahar eyler Öyle acı sözler var ki Göğsünüze giren hançer Öy...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/soz-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-sevket-yucel-6qy40', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günler küçük kuşlardır

Uçar uçar giderler

Geride bizden kalanlar

Sisler içinde bir düş

Yıllar bir yelin ucunda

Durmadan sürüklenen

Yıl da biziz, gün de biz

Acılar, sevinçler, hüzünlerle.', 'Günler küçük kuşlardır Uçar uçar giderler Geride bizden kalanlar Sisler içinde bir düş Yıllar bir yelin ucunda Durmadan sürüklenen Yıl da bi...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dus-157-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle anne', 'soyle-anne-sevket-yucel-0h6ar', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sordu çocuk

Sevgi kuş mudur anne

Hangi daldan dala uçar 

Eğil kulağıma söyle

Şöyle cevap verdi anne

Kuştur oğul, hoştur sevgi

Alır içine dünyayı

Beyaz beyaz kanat çırpar

Sordu çocuk

Bilgi gök müdür anne

Aşar mı dağlardan öte

Nerelere kadar gider

Şöyle cevap verdi anne

Bilgi gökyüzüdür oğul

Sığmaz çember içine

Uzar sonsuza doğru

Sordu çocuk 

Dünya çiçek midir anne

Kimler bıçak yapar onu

Nedir bunca silahlar

Şöyle cevap verdi anne

Dünya çiçektir oğul, sevmesini bilene

Düşmanlık bıçak yapar her ne varsa güzeli

Bu yüzden çoğalır silahlar.', 'Sordu çocuk Sevgi kuş mudur anne Hangi daldan dala uçar  Eğil kulağıma söyle Şöyle cevap verdi anne Kuştur oğul, hoştur sevgi Alır içine dün...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/soyle-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimişliğiniz', 'eskimisliginiz-sevket-yucel-pbodj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül açmıyor içimizde ışıksızlığınızdan

Kendinize gidiyorsunuz siz

Onca güzel yollar varken

Ne çok yama vurulmuş düşüncelerinize

Biraz daha paslanıyorsunuz hergün

Nereye varılır ki bu gidişle

Siz

Yalnız bencilliğinize saklıyorsunuz gülüşlerinizi

Yapraklarınız dökülmüş

Dallarınız da kurumuş üstelik

Terk etmiş incelikler sizi

Tilkiler geziyor beyninizde

Kayalara dönmüş sevgileriniz

Biliyorum, bir güzele gidilmez sizinle

Hangi yanınızdan baksak sıkıntı

Yıllar yılı usandık eskimişliğinizden.', 'Gül açmıyor içimizde ışıksızlığınızdan Kendinize gidiyorsunuz siz Onca güzel yollar varken Ne çok yama vurulmuş düşüncelerinize Biraz daha p...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eskimisliginiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman denen tren', 'zaman-denen-tren-sevket-yucel-0rduk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alıp götürüyor beni

Zaman denen bir tren

Nice tünellerden geçerek

Yaşam gerçek midir yoksa bir düş mü

Düşündükçe korkuyorum kendimden

Şu dünya sahnesinde

Her ne yaptıysam eksik

Ne etsem doyurmuyor beni

Bilmem ki nereye gitsem

Yoruldum çok sevmekten.', 'Alıp götürüyor beni Zaman denen bir tren Nice tünellerden geçerek Yaşam gerçek midir yoksa bir düş mü Düşündükçe korkuyorum kendimden Şu dün...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zaman-denen-tren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isıt beni ışıkla', 'isit-beni-isikla-sevket-yucel-8oqjg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaklaş bana kiraz gibi yaz gibi

Isıtsın içimi sevgi güneşin

Sıcak gel, değiştir, yenile beni

Buralarda eskimekten usandım

Sona erdir şu uzayan kışımı

Haziran ol günlerimin dalında

Nice güzellere sevdala beni

Isıt beni üşümekten usandım.', 'Yaklaş bana kiraz gibi yaz gibi Isıtsın içimi sevgi güneşin Sıcak gel, değiştir, yenile beni Buralarda eskimekten usandım Sona erdir şu uzay...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/isit-beni-isikla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevince karışan acı', 'sevince-karisan-aci-sevket-yucel-nmogd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuşlar gibi kanat çırpıyor anılar

Sonra gidip konuyorlar bir kavağın ucuna

Günlerse bir masal anlatıyor bize

Biraz önce şuralarda gezinenler sizler miydiniz

Bir şeyler alan, bir şeyler götüren

Her yer bir ayrılık nereye baksam

Bir sevinci kovalıyor bir acı

Yokuşlarda, düzlüklerde

Şu uzayan sokaklarda durmadan

Zamansa akıp gidiyor içinden saniyelerin

Bizse bir yerlere varmak istiyoruz tutkularla

Gel gör ki kavuşunca başlıyor bir eksiklik

Savrulup gidiyor bir şeyler

Hepsi birer düş oluyor zamanla', 'Kuşlar gibi kanat çırpıyor anılar Sonra gidip konuyorlar bir kavağın ucuna Günlerse bir masal anlatıyor bize Biraz önce şuralarda gezinenler...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevince-karisan-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak sevgilerle güzel', 'yasamak-sevgilerle-guzel-sevket-yucel-78cpa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu dünyanın al yeşil bağrında

Kırılmış bir kanadı sevincimizin

Gülüşlerimiz dudaklarımızda yaralı

Yapraklara türküler söyletirken bir küçücük esinti

Üstümüzde dansederken bulutlar

İşte yıllar

Savrulup gidiyor bir söğüt yaprağı gibi

Gerilerde bir boşluk

Neylersin, anılar yaşlı

Anılar ki uzaklarda birer karınca yuvası

Yaşamak böyle değil ben bilirsem eğer

Sıkışıp kalırken sıkıntının tünellerinde

Yaşamak, bir sevinci dudağından öperken

Yaşamak, bir gülüşü birlikte okşamakla

Sevda yüklü günlerle güzel', 'Şu dünyanın al yeşil bağrında Kırılmış bir kanadı sevincimizin Gülüşlerimiz dudaklarımızda yaralı Yapraklara türküler söyletirken bir küçücü...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasamak-sevgilerle-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meğer neleriniz varmış sizin', 'meger-neleriniz-varmis-sizin-sevket-yucel-i35m8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siz çok eskisiniz, yaralıyorsunuz günlerimizi

Siz hep üşütüyorsunuz ısıtmanız gerekirken

Bakmayı bilmeyenler bahar sanıyor sizi

Sizi beyaz görüyorlar artarken siyahlığınız

Siz çok paslısınız, çok yanlış

Bir de kuraksınız, üstelik bir de karanlık

Siz çok  kirlisiniz, siz çok bencil

Bakıyorum, kül düşmüş düşüncelerinize', 'Siz çok eskisiniz, yaralıyorsunuz günlerimizi Siz hep üşütüyorsunuz ısıtmanız gerekirken Bakmayı bilmeyenler bahar sanıyor sizi Sizi beyaz g...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/meger-neleriniz-varmis-sizin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuz Ayı Neymiş Böyle', 'temmuz-ayi-neymis-boyle-yusuf-onder-bahceci-7q0u3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni Temmuz ayında gördüm,

Seni Temmuz ayında sevdim,

Temmuz ayında da doğdum,

Bu Temmuz ayı neyimiş böyle.

Temmuz ayını çok seviyordum,

Her Temmuz''u iple çekiyordum,

Temmuz''da koşarak geliyordum,

Bu Temmuz ayı neyimiş böyle.

Bir Temmuz ayında yıktılar beni,

Bir Temmuz ayında sattılar beni,

Bir Temmuz ayında nettiler seni,

Bu Temmuz ayı neyimiş böyle.

Her Temmuz gelince üzülüyorum,

Seni düşünüyor, hep düşünüyorum,

Onu defterden sildim deliriyorum,

Bu Temmuz ayı da neyimiş böyle.', 'Seni Temmuz ayında gördüm, Seni Temmuz ayında sevdim, Temmuz ayında da doğdum, Bu Temmuz ayı neyimiş böyle. Temmuz ayını çok seviyordum, Her...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/temmuz-ayi-neymis-boyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile', 'cile-sevket-yucel-0x1j8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şudur çoğunlukla yaşamımız bizim

Az ışık, az beyin, çok tuzak ve kandırmaca

Bencillik, bağnazlık, daha niceleri

Bir insan olarak

Toplamayı düzgün yaparsanız eğer

Bin kişi etmiyor bir kişi

İşte bu yüzdendir çekilen çile', 'Şudur çoğunlukla yaşamımız bizim Az ışık, az beyin, çok tuzak ve kandırmaca Bencillik, bağnazlık, daha niceleri Bir insan olarak Toplamayı d...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cile-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilen yutulan günler', 'yenilen-yutulan-gunler-sevket-yucel-pzziv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gördüm ki

Yakınınızdan bile geçmiyor incelikler

Yaralanmış sevgilerimiz hep sizin yüzünüzden

Sesinizde ne bir dostluk ne bir çiçek

Ne kadar anlamsız yerleriniz varmış meğer sizin

Nerenizden baksak uçurum

Usandık yıllardır o bozuk yerlerinizden

Salt kendinize dönüksünüz siz

Sıralanmış bakışlarınızda yalanlar

Köşeleriniz bozuk, açılarınız dar

Bir uzun çölsünüz hangi yanınızdan baksak

Görüntünüz bulutlara benziyor, ama kısır

Bahçeniz bahçe değil, bal vermiyor kovanınız

Sahi siz kimsiniz, neredesiniz

Hem çok yüzlüsünüz, hem çok değişken

Yaz gününde buz tutuyor sözcükleriniz', 'Gördüm ki Yakınınızdan bile geçmiyor incelikler Yaralanmış sevgilerimiz hep sizin yüzünüzden Sesinizde ne bir dostluk ne bir çiçek Ne kadar ...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yenilen-yutulan-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamet-"siz hiç ay aşığında ağladınız mı"  Kitabından', 'kiyamet-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-pvf2w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '”Ne zaman kopacak ” dedi kıyamet

Senin kıyametin son nefesindir 

Sana ne kardeşim kopar kıyamet

Ölüm yakın sana ve de kesindir

Günah tarlasında isyan yıllarca

Harca bakalım sen fütursuz harca

Deccal gelir deyip bekle aylarca

Azrâil gelince son nefesindir

Düşün kıyameti yaslan imâna 

Bu ne perişanlık gadretme cana 

Sarıl istiğfara sarıl Kuran’a 

Ümit soluğundur tevbe sesindir', '”Ne zaman kopacak ” dedi kıyamet Senin kıyametin son nefesindir  Sana ne kardeşim kopar kıyamet Ölüm yakın sana ve de kesindir Günah tarlası...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiyamet-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmıyorum', 'i-nanmiyorum-yusuf-onder-bahceci-aw95m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana şunu söyleyim ki güzelim,

İnanmıyorum beni sevmediğine,

İnanmıyorum gönül vermediğine,

İnanmıyorum, inanmıyorum.

Şunu bil Halam Anneni kandırdı,

Annen de bilmeden seni kandırdı,

Sende onlara uyup beni kandırdın,

İnanmıyorum, inanmıyorum.

Halbuki ne kadar çok seviyordum,

Seni seni hep seni hayal ediyordum,

Sende benim gözlerime gülüyordun,

İnanmıyorum, inanmıyorum.

Sıkıştır bakayım bir onları sıkıştır hele,

Belki de sana hâla yalan söylerler de,

Onlar ne derse desin inanmıyorum be,

İnanmıyorum, inanmıyorum...', 'Sana şunu söyleyim ki güzelim, İnanmıyorum beni sevmediğine, İnanmıyorum gönül vermediğine, İnanmıyorum, inanmıyorum. Şunu bil Halam Anneni ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/inanmiyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Aşk''a İhanet Affedilmez *', 'ask-a-i-hanet-affedilmez-i-brahim-dikmen-2-ivfqu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Diz çöksen / önümde

Ayaklarıma / kapansan

Göz yaşın / sel olsa

Yalvarıp / ağlasan

Seni / affetmeyeceğim

Bin bir özür / dilesen.

03/02/2006', 'Diz çöksen / önümde Ayaklarıma / kapansan Göz yaşın / sel olsa Yalvarıp / ağlasan Seni / affetmeyeceğim Bin bir özür / dilesen. 03/02/2006...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-a-ihanet-affedilmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gevl Sevdam Güneş Açalım', 'gevl-sevdam-gunes-acalim-kamil-soylemez-k3rc2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üstüme,üstüme geliyor,kara bulutlar				

Ey sevdiğim,gel beni sen kurtar				

Saçlarımı sarmış,kırağı gibi aklar				

Dişlerimde acı, bir içim sancısı var				

Gözlerimde uykusuz geceler açar				

Sırtımda  yokluğun yumurta küfesi 				

Azıcık hızlı adımlasam kırılacaklar				

Şişgin bir özlem bağrımda 				

Sus derim gönül sus,susmaz arzular 				

İçim acıtıp,pare pare parçalar				

Çalkantılı bir derin mavi				

Bir çöl çöp,gibi bir hal var 				

İstanbul sokaklarında sevgilim 				

Bir ahşaptır uzun yıllar				

Sallım söğüt gibi sancılarım var				

Ey sevgili,haydi sen beni prangala, sar				

Bak toprak gülümsüyor				

Ay gülümsüyor, sensizliğime				

Gelirmi gelmezmi bilmemde başka çile				

Tuzaklar yakındır bilirim,sensizliğin çilesiyle				

Ver elini gidelim senin ile özlemin göz bebeyine			

Güneş açalım,mutluluk çemberi gözlerimizde				

Dönen varmı ki 	

Gidipte gelen geriye', 'Üstüme,üstüme geliyor,kara bulutlar				 Ey sevdiğim,gel beni sen kurtar				 Saçlarımı sarmış,kırağı gibi aklar				 Dişlerimde acı, bir içim ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gevl-sevdam-gunes-acalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesabım Kalmasın Mahşer Gününe', 'hesabim-kalmasin-mahser-gunune-salih-erdem-k19vi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir oyuna dalmış küçük çocuğum

Zamanla harmanım ver hevesime

Nihayete kalmış soluk soluğum

Busende dermanım sür nefesime

Feryadım taşınca gönül gözüme

Zül sayar devranım bakar yüzüme

Hayalin düşünce fikir düzüme

Sığmıyor kervanım dar kafesine

Kimseler yormasın garip dillerim 

Diline sarmasın harap hâllerim

Hâlimi sormasın serap çöllerim

Kadim dost “cânânım” sır sislerime

Yazık ki hâlimi boştan yormuşum

Gönlünde dilinde baştan hormuşum

Rüzgârın yelinde taştan kormuşum

Duvarsız kermenim vur köslerine

Kalmadı muradım dünya tahtına

Kalbimi kapadım kabir altına

Vicdanı dayadım cebri kastına

Sıratta erkânım kör nefisime

Erdemoğlu onur beşer kalemin 

Kusurunu sardın beher âlemin

Özünün nârıdır mahşer elemin

Alacağın varsa Kevser kademin

Hesaba fermanım sor hislerine 

04.05.2005 16:30

16.11.2005 22:40 AYDIN', 'Bir oyuna dalmış küçük çocuğum Zamanla harmanım ver hevesime Nihayete kalmış soluk soluğum Busende dermanım sür nefesime Feryadım taşınca gö...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hesabim-kalmasin-mahser-gunune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* K i m e N e *', 'k-i-m-e-n-e-i-brahim-dikmen-2-hdh9r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'B e n! 

D u y g u   y ü k l ü 

S e v d a   y ü k l ü 

Ş a i r i m.

T ü r k ü   k o k a r 

S e v d a   k o k a r

Ş i i r   l e r i m.

A ş k! 

M a h r e m i m  d i r

S ö y l e y e m e m

T e r c ü m a n ı m   o l d u

Y ı l l a r d ı r 

S a t ı r l a r a

D ö k t ü k  l e r i m.

K i m e  n e! 

Y ü r e k   b e n i m 

S e v d a   b e n i m 

L a k i n! 

İ n s a n ı m   s o n u ç t a 

E l b e t   b e n d e 

S e v e'' c e ğ i m.

03/02/2006', 'B e n!  D u y g u   y ü k l ü  S e v d a   y ü k l ü  Ş a i r i m. T ü r k ü   k o k a r  S e v d a   k o k a r Ş i i r   l e r i m. A ş k! ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/k-i-m-e-n-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Yıldızım Benim', 'ay-yildizim-benim-yusuf-onder-bahceci-ejyot', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay Yıldızım benim sen her şeyimsin,

Gerçek söylüyorum benim cânımsın,

Nazlı nazlı dalgalanırsın da göklerde,

Ay Yıldızım benim sen her şeyimsin.

Sana bakmaya hiç doyamam ki ben,

Dünyalar verseler seni değişmem ben,

Sen ki şehitlerimin kanısın bilirim hem,

Ay Yıldızım benim sen her şeyimsin.

Sana baktıkça gözlerime yaşlar doluyor,

Senin için bil ne Mehmetler şehit oluyor,

Şehit Anaları gece gündüz dualar ediyor,

Ay Yıldızım benim sen her şeyimsin.

Biz Ay yıldızın uğruna ne cânlar verdik,

Bütün Dünya bir oldu hakkından geldik,

O bayrakların en güzeli böylece bildik,

Ay Yıldızım benim sen her şeyimsin,', 'Ay Yıldızım benim sen her şeyimsin, Gerçek söylüyorum benim cânımsın, Nazlı nazlı dalgalanırsın da göklerde, Ay Yıldızım benim sen her şeyim...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ay-yildizim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce Allah', 'yuce-allah-i-brahim-pataz-1p2u3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu evreni, kainatı,

Yaradandır, Yüce Allah.

Canlı, cansız, mahlukatı,

Var edendir, Yüce Allah.

Denizi, gölleri, dağı

Bütün iriyi ufağı

Gözle görülmez, bir çoğu,

Kör edendir, Yüce Allah.

Gökleri, güneşe, aya,

Yerleri, toprağa, suya,

Yaprakları, fabrikaya,

Yer edendir, Yüce Allah.

Sayılar yetmez yaşına,

Olanlar, O’na, aşina,

Suları, dağın başına,

Kar edendir,Yüce Allah.

O’na inanırız bizler,

Görmüyor, yetersiz, gözler,

Her madde de, bir şey gizler,

Sır edendir, Yüce Allah.

ELEMİ,  O’na kul ola,

Huzuru, Allah’la bula,

Bu kadarı, geldi dile,

Der edendir,Yüce Allah.

İbrahim PATAZ

     02.02.2006 ADANA', 'Bu evreni, kainatı, Yaradandır, Yüce Allah. Canlı, cansız, mahlukatı, Var edendir, Yüce Allah. Denizi, gölleri, dağı Bütün iriyi ufağı Gözle...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Pataz']::text[], 8.5, '{"poet":"İbrahim Pataz","poet_slug":"i-brahim-pataz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yuce-allah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karar Veren Kim', 'karar-veren-kim-enver-herguler-la3ft', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şehir uğultusunu yırtan sirenler

Çalar acı acı.

Bir can daha yollarda pek acil.

Açılır ikiz olan hastahane kapıları

Biri çıkarken bir diğeri giren tabibler

Hem de kaç tane.

Hortum oksijen neşter

Kul yapısı göstergeler.

Kan ter içinde kalınır

Elden gelen yapılaır

Ve şimdi son karar beklenir.

Onu da bir başkası değil

Sadece ve sadece yaradan verir.', 'Şehir uğultusunu yırtan sirenler Çalar acı acı. Bir can daha yollarda pek acil. Açılır ikiz olan hastahane kapıları Biri çıkarken bir diğeri...', ARRAY['Türk Edebiyatı','Şiir','Enver Hergüler']::text[], 8.5, '{"poet":"Enver Hergüler","poet_slug":"enver-herguler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karar-veren-kim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancılı uyku', 'sancili-uyku-elazigli-mustafa-kaya-3lbl4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uykular aradım

yatağımın sancılarına

sarılarak.



Mustafa kaya

03.02.2006 / istanbul', 'uykular aradım yatağımın sancılarına sarılarak. Mustafa kaya 03.02.2006 / istanbul...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sancili-uyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimizin Yerine', 'i-kimizin-yerine-ozlem-aksoy-6fiqj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hala bir kahramanımmışsın  gibi söz ediyorum senden

Beni bende bırakıp kaçacak kadar korkak olduğun halde

Birimiz ayakta kalmalıydı, sadık kalmalıydı yeminlere.

Bunu da ben başardım ikimizin yerine.

Bundan böyle hasret olsun hayatta ki En güzel düşün

Benimle yaşadıklarını unut, kaybettiklerini düşün ….', 'Hala bir kahramanımmışsın  gibi söz ediyorum senden Beni bende bırakıp kaçacak kadar korkak olduğun halde Birimiz ayakta kalmalıydı, sadık k...', ARRAY['Türk Edebiyatı','Şiir','Özlem Aksoy']::text[], 8.5, '{"poet":"Özlem Aksoy","poet_slug":"ozlem-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ikimizin-yerine-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçmen kuşu ruhum', 'gocmen-kusu-ruhum-elazigli-mustafa-kaya-sj5m0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'utangaç

ve

cüretkar yorgunluğum

geniş göğe sığmıyor.

ruhumda,

azaplı kelimeler

kol geziyor.

göçmen kuşlarına döndüm.

korkularım

konup havalanıyor..

Mustafa kaya

03.02.2006 / HASKÖY', 'utangaç ve cüretkar yorgunluğum geniş göğe sığmıyor. ruhumda, azaplı kelimeler kol geziyor. göçmen kuşlarına döndüm. korkularım konup havala...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gocmen-kusu-ruhum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Gülüm Derim', 'ben-sana-gulum-derim-yusuf-onder-bahceci-r90i7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen beni düşünüp te sevmeseydin,

Ben sana böyle şiirler yazamazdım ki,

Sen istediğin kadar bana kızsan da,

Ben sana Gülüm derim kızamazdım ki,

Biliyorum bunda senin bir suçun yok,

Bu sevda da bizim düşmanımız çok,

Benim kalbimde hüzün se pek çok,

Ben sana Gülüm derim kızamazdım ki,

Şimdi dağlarda, taşlarda geziyorum,

Sen beni seversin kalbimle seziyorum,

Yunus Emre gibi dergahlar geziyorum,

Ben sana Gülüm derim kızamazdım ki,

Ölünceye kadar böyle şiirler yazıp ta,

Hayallere dalıyorsun, hayal kurup ta,

Bir gün mutlu olurmusun onu bulup ta,

Ben sana Gülüm derim kızamazdım ki...', 'Sen beni düşünüp te sevmeseydin, Ben sana böyle şiirler yazamazdım ki, Sen istediğin kadar bana kızsan da, Ben sana Gülüm derim kızamazdım k...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-sana-gulum-derim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selcen', 'selcen-selcen-boyar-gji8r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aklımda sen,

Fikrimde sen,

Sözlerim hep Selcen

Yürürken sokaklar sen,

Uykuda rüyada sen,

Sabahta, öğlende sen

Akşam oldu gene Selcen.

Kadehte sen, neyde sen,

Hayelde sen, düşte sen,

Gerçek desem değilsin,

Perimisin sen Selcen.

Hecede sen, sözde sen,

Mısra mısra işlesem,

Roman desem değilsin,

Şiir misin sen Selcen.

Şekerde sen,  tat''da sen,

Şerbette sen, balda sen,

Yudum desem değilsin,

Deryamısın sen Selcen.

Havada sen, yerde sen,

Karanfilde sen, Gül de sen

Demet demet derlesem,

Çiçek misin sen Selcen..

 :)', 'Aklımda sen, Fikrimde sen, Sözlerim hep Selcen Yürürken sokaklar sen, Uykuda rüyada sen, Sabahta, öğlende sen Akşam oldu gene Selcen. Kadeht...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/selcen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Sonsuz Hediye', 'sana-sonsuz-hediye-ahmetnecat-ucur-lzyo2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açmadan çiçeğin soluyor,neden ne diye,

Sevdiğini söylemiyorsun hala ne diye...

Bekliyorum yıllardır,sevmesen de sev diye,

Seviyorsun aslında ama,eh işte diye...

Söylemiyordun,belki de sevmiyordur diye,

Sevse de,çok zor,bu böyle olmaz diye...

Zorlayıp da kendini,evlenmedin ne diye,

Söylemedin sevgini,düşerim dile diye...

Sakladın sevgini,çekiyorsun çile diye,

Dolmayan çileler,bir gün elbet dolar diye...

Bozdurmuyorsun doları,değeri çok diye,

Yaşıyorsun yaşamı aşksız,fakat aşk diye...

Tatmadığın duygular varken,deme yok diye,

Seviyorsun,seviyorum,aşkımız çok diye...

Biz mi çekeceğiz acıları,bu aşk diye...

Yaşamın cilvesidir sevgiler,zevkler diye...

Sevgin,aşkın,yaşamın,olsun bana hediye,

Çok bekledim  o da bana desin he diye...

Yeter ki gel,sen bana sevgilim de diye,

Birlikte sunalım yaşama,sonsuz hediye...', 'Açmadan çiçeğin soluyor,neden ne diye, Sevdiğini söylemiyorsun hala ne diye... Bekliyorum yıllardır,sevmesen de sev diye, Seviyorsun aslında...', ARRAY['Türk Edebiyatı','Şiir','Ahmetnecat Ucur']::text[], 8.5, '{"poet":"Ahmetnecat Ucur","poet_slug":"ahmetnecat-ucur","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-sonsuz-hediye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelliğin’le şiirleşir benliğim! ...', 'guzelligin-le-siirlesir-benligim-muammer-celik-x3iua', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bakmaya kıyamadığın aynadır, benim yüreğim

aynada yansıyan güzelligindir, benim sevdiğim... 

şiir şiir aktığım yüreğinde açınca gönül güllerim 

dize dize döküldüğüm dudaklarından gülümserim 

pırıl pırıl ab-u hayat gözlerinle oynaşınca gözlerim 

sen güldükce, ballanır dolaştığım ağzında dillerim! ...

BirDeli 

03.02.2006', 'bakmaya kıyamadığın aynadır, benim yüreğim aynada yansıyan güzelligindir, benim sevdiğim...  şiir şiir aktığım yüreğinde açınca gönül güller...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guzelligin-le-siirlesir-benligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Şu İnadı Bırakalım', 'gel-su-i-nadi-birakalim-yusuf-onder-bahceci-g6ljl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel seninle şu inadı bırakalım biz,

Bu Memleket kimler sizler ve biz,

Cahil kalmayalım bak esir oluruz,

Gel seninle şu inadı bırakalım biz.

Aydınlık olmazsa önünü göremezsin,

Kitap okumazsan sen neleri bilirsin,

Gün boyu kahvede pişpirik oynarsın,

Gel seninle şu inadı bırakalım biz.

Kahvenin pis kokusu sana ne verir,

Elinde ve avucunda ne varsa verilir,

Kahveye gidenler hep yerlere serilir,

Gel seninle şu inadı bırakalım biz.

Birşey yapmıyorsan hakaret etme,

Allah''ın verdiği ömrü böyle tüketme,

Oralarda harap oldun beni söyletme,

Gel seninle şu inadı bırakalım biz....', 'Gel seninle şu inadı bırakalım biz, Bu Memleket kimler sizler ve biz, Cahil kalmayalım bak esir oluruz, Gel seninle şu inadı bırakalım biz. ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-su-inadi-birakalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güney Yeli', 'guney-yeli-demiss-vangelis-h4o66', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatımın son güney yeli

Estin geçtin yirmi semalarımdan

Gözyaşlarını bıraktın üzerimde

Gölgen var buğlu gözlerimde

Rüzgar her estiğinde, güney yeli gibi esiyor

Güneş her doğduğunda, gülümseyişini görüyorum

Yıldızlara her baktığımda, umutlarımızı hatırlıyorum

Yağmur her yağdığında, omuzumda ağlayışını...

Hayatımın son güney yeli

Estin geçtin üzerimden

Kalbimde imzan var

Ruhumda lanetin...

Seni hatırlatan herşeyde, vuruyor yıllar tokatını

Acıtmıyor ama, kahrediyor beni

Rüzgar her estiğinde, senin gibi esiyor

Beni oradan oraya savuruyor

Hayatımın son güney yeli

Estin geçtin yirmi semalarımdan

Gözyaşlarını bıraktın üzerimde

Gölgen var buğlu gözlerimde', 'Hayatımın son güney yeli Estin geçtin yirmi semalarımdan Gözyaşlarını bıraktın üzerimde Gölgen var buğlu gözlerimde Rüzgar her estiğinde, gü...', ARRAY['Türk Edebiyatı','Şiir','Demiss Vangelis']::text[], 8.5, '{"poet":"Demiss Vangelis","poet_slug":"demiss-vangelis","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/guney-yeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Pesimistin İntiharı', 'bir-pesimistin-i-ntihari-baris-aluk-7w61e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hepiniz birer aşk çocuğuydunuz başta

Neden sonra,

bir fahişenin elleri değdi

yüzünüzdeki gülümsemeye.

Oysa ben,

onun uğradığı ilk tecavüz kadar eskiydim

yorgundum

ama temizdi henüz saçlarım.

Ey kalpleri mutasyona uğramış hilkat garibeleri

üzerime bulaşan bu kandan siz sorumlusunuz ulan! 

Şimdi bu pesimist ayak izlerinin

nereden kaldığını soruyorsunuz

geçmişimin takvim yapraklarında.

Çünkü milattan önce bir rezil günde

yarattığı tanrıya taptı bir adam...

Ruhlarınız bir kuduz gibi titriyor şeytanın ellerinde

Sırtıma yüklenen bu günahlardan siz sorumlusunuz ulan! 

Çekin ellerinizi saçlarımın renginden

ben çekerim kendi ipimi

bu kehanetler, geçmişimin izleri

ve kalbimin bir köşesinde ılık ılık kanayan aşkım.

Bırakmayacağım sizin çarpık dişlerinizin arasına...

Bu intihardan,

...üzerime sıçrayan kandan,

..................bu eski günahlardan,

aldığınız her haksız nefesten siz sorumlusunuz ulan! 

Cehennem yalnız benim avuçlarımdaki ateşte kalmayacak

yaşam sandığınız bu ölüler diyarında

yaktığım ateş çürümüş ruhlarınızda yanacak...

Ey ölüm saçan patlamaların fâili

bu kan kokan sözlerim

sizden ben değil,

onlar sorumlu.

Artık bu rezil oyunda kazanan olmayacak

Savur geçmiş yangınlarımdan kalma küllerimi Boreas*...

(03.02.2006)  İstanbul', 'Hepiniz birer aşk çocuğuydunuz başta Neden sonra, bir fahişenin elleri değdi yüzünüzdeki gülümsemeye. Oysa ben, onun uğradığı ilk tecavüz ka...', ARRAY['Türk Edebiyatı','Şiir','Barış Aluk']::text[], 8.5, '{"poet":"Barış Aluk","poet_slug":"baris-aluk","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-pesimistin-intihari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne kül duman ister ne ateş gönül', 'ne-kul-duman-ister-ne-ates-gonul-kemal-eyupoglu-r911w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğer hazmedersen çile çekmeyi

                                                                   Her şey nasip kısmet gelir sırası

				   Bir nifak tohumu boy uzatırsa

				   Dostla dostun bozuk olur arası.

				 Araya hasretlik  girmeye görsün

				 Göz uzaksa  azar gönül yarası

				 Eğer dost elinden yersen hançeri

				 Ehveni şer olur zulmün karası.

				 Herkesin midesi ve yolu farklı

				 Zenginin kendine yarar parası

				 Çamura da düşse b… da düşse

				 Sevgimin değişmez düşmez darası.

				Ne kül duman ister ne ateş gönül

				Bin türlü uğraşsan yanmaz çırası

				Görür sürme çekmiş ok kirpikleri

				Kapılır tamaha gelmez durası.

							     02/02/2006', 'Eğer hazmedersen çile çekmeyi                                                                    Her şey nasip kısmet gelir sırası 				   Bi...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-kul-duman-ister-ne-ates-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinaslı Mani l', 'cinasli-mani-l-latif-oz-795ba', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yar sana

Sular akar yar sana

Bakışınla bir tanem

Şu dağları yarsana', 'Yar sana Sular akar yar sana Bakışınla bir tanem Şu dağları yarsana...', ARRAY['Türk Edebiyatı','Şiir','Latif Öz']::text[], 8.5, '{"poet":"Latif Öz","poet_slug":"latif-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cinasli-mani-l-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinaslı Mani ll', 'cinasli-mani-ll-latif-oz-8ccoe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yara beni

İnletiyor yara beni

Gurbet elde garip kaldım

Götürsünler yara beni', 'Yara beni İnletiyor yara beni Gurbet elde garip kaldım Götürsünler yara beni...', ARRAY['Türk Edebiyatı','Şiir','Latif Öz']::text[], 8.5, '{"poet":"Latif Öz","poet_slug":"latif-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cinasli-mani-ll-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıma', 'askima-zeliha-ural-y3ohj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'S ensizliğin içinde seni özlüyorum

E llerini sıcaklığını istiyorum

D üşünüyorum dünümü, hergünüm sensin

A şığım diyorum birtanem sana

T itrerken yüreğim sensizlikte

U mut oldun, can oldun ömrüme

R azıyım seninle her doğan güne

A llahım emanet ettiğim her günde

L eventisin ömrümün, her deminde

(Canlar vardır candan içeri, bir can varki benden içeri (sevgili Eşime)', 'S ensizliğin içinde seni özlüyorum E llerini sıcaklığını istiyorum D üşünüyorum dünümü, hergünüm sensin A şığım diyorum birtanem sana T itre...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Ural']::text[], 8.5, '{"poet":"Zeliha Ural","poet_slug":"zeliha-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/askima-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinaslı Mani lll', 'cinasli-mani-lll-latif-oz-0fucx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Maniler

Cinaslıdır maniler

Zalim çıkarır karşıma

Olur olmaz maniler', 'Maniler Cinaslıdır maniler Zalim çıkarır karşıma Olur olmaz maniler...', ARRAY['Türk Edebiyatı','Şiir','Latif Öz']::text[], 8.5, '{"poet":"Latif Öz","poet_slug":"latif-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cinasli-mani-lll-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Nesin Sen', 'soyle-nesin-sen-muammer-susuzlu-dbo7v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başımda sevda mı sinemde gül mü

Gönlümün içinde söyle nesin sen

Seraba kandığım kızgın bir çöl mü

Bilerek yakarsın, böyle ne''sin Sen.

Aşkınla yansam da yaktın sanmazsın

Diz çöküp yalvarsam inan kanmazsın

Halime acımaz bir an anmazsın

Gülerek bakarsın, öyle ne''sin Sen.

Baharın bilinmez kış mıdır yazın

Yay kaşın çatılmış bitmez mi nazın

Derinden inletir ruhumu sazın

Kalbimde Ney misin, söyle nesin Sen.

07 - Ağustos - 2004

B.evler - İstanbul.

           23.30', 'Başımda sevda mı sinemde gül mü Gönlümün içinde söyle nesin sen Seraba kandığım kızgın bir çöl mü Bilerek yakarsın, böyle ne''sin Sen. Aşkınl...', ARRAY['Türk Edebiyatı','Şiir','Muammer Susuzlu']::text[], 8.5, '{"poet":"Muammer Susuzlu","poet_slug":"muammer-susuzlu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/soyle-nesin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Kadar Gider', 'nereye-kadar-gider-yusuf-onder-bahceci-3hpt0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer ki senle bunu konuşamazsam,

Ben derdimi sana anlatamazsam,

Sende böyle böyle devam edersen,

Nereye kadar gider bu işin sonu.

Benim tek suçum var oda sevmektir,

Sadece sevmek mi cânımı vermektir,

Yıllardır düşünürüm de bunca emektir,

Nereye kadar gider bu işin sonu.

Senden evvel ölürsem bekleyeceğim,

Benden evvel ölürsen ne diyeceğim,

Mezarına gelip te sevdim diyeceğim,

Nereye kadar gider bu işin sonu.

Bilirmisin olan bizim sevdamıza oldu,

Bizi böyle ayıranlar Allah''ından buldu,

Kalbim seni sevdi, yandı da kavruldu,

Nereye kadar gider bu işin sonu.....', 'Eğer ki senle bunu konuşamazsam, Ben derdimi sana anlatamazsam, Sende böyle böyle devam edersen, Nereye kadar gider bu işin sonu. Benim tek ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nereye-kadar-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özlüyorum', 'seni-ozluyorum-mustafa-bilgili-9ojqh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün şarkılarımda seni söylüyor,

Şiirlerimde hep seni yazıyorum.

Her gece rüyalarımda seni görüyor,

Yanımdayken bile seni özlüyorum.

Manalı bir bakış atmasan bile,

Aşkıma tenezzül etmesen bile,

Benden uzaklara gitmesen bile,

Hasretinle yanıp,seni özlüyorum.

Ellerin elime hiç değmesin varsın,

Sen benim gönlümde elmasın,narsın,

Aşkın alevleri gelip ruhumu sarsın,

Kalbimdeyken bile seni özlüyorum.

Aşkın yüreğime sonsuz acı verse de,

Kara sevda şu bedenimi yere serse de,

Kör kurşunlar birer.birer beni vursa da,

Elimde değil bir tanem seni özlüyorum.

Aşkımız aylar değil,yıllar sürse de,

Zalimler çıkıp yoluma engel örse de,

Gözlerim sadece bir tek seni görse de,

Ben yinede seni,hep seni özlüyorum.

                                                  21.11.1996', 'Bütün şarkılarımda seni söylüyor, Şiirlerimde hep seni yazıyorum. Her gece rüyalarımda seni görüyor, Yanımdayken bile seni özlüyorum. Manalı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-ozluyorum-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgidir Sevgi', 'sevgidir-sevgi-huseyin-sigirtmac-kgox7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiyle bakalım şen olsun canlar.

El ele verelim gülsün insanlar.

Kin, nefret yüzünden matem mekânlar.

Neşenin kaynağı sevgidir sevgi.

Sevgiyle bakan göz görür güzeli.

Sevgisiz can solar döker gazeli.

Yarının temeli bu günden belli.

Gönüllerin bağı sevgidir sevgi.

Aşığın türküsü dağlar başına.

İnsan olmak değil boşu boşuna.

Ozan ses verir ya sazın döşüne! 

Gözüyle kulağı sevgidir sevgi.

Sığırtmaç’a candır aşkın közleri.

Cansıza can verir sevgi sözleri.

Sevgisiz bir ömrün kalmaz izleri.

Varlığın durağı sevgidir sevgi.', 'Sevgiyle bakalım şen olsun canlar. El ele verelim gülsün insanlar. Kin, nefret yüzünden matem mekânlar. Neşenin kaynağı sevgidir sevgi. Sevg...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgidir-sevgi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse bilmesin', 'kimse-bilmesin-mete-yildiz-j6znb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurda rüzgarla gel; 

Hiç kimse duymasın bana ne söylediğini

Yalnız ben bileyim dudak hareketinden,

Gözlerin anlatsın kalbinin derinliklerindeki koyu ifadeyi

Bir ben bileyim beni sevdiğini

Hiç kimse bilmesin

Benim sana,senin bana hislerini,

Bırak hülyalara dalayım

Çekme başımın altından dizlerini.', 'Yağmurda rüzgarla gel;  Hiç kimse duymasın bana ne söylediğini Yalnız ben bileyim dudak hareketinden, Gözlerin anlatsın kalbinin derinlikler...', ARRAY['Türk Edebiyatı','Şiir','Mete Yıldız']::text[], 8.5, '{"poet":"Mete Yıldız","poet_slug":"mete-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kimse-bilmesin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni anlarmısın', 'beni-anlarmisin-mete-yildiz-ifmg5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben sana ben seni desem

Gerisini anlar mısın? 

Sussak hiçbir şey söylemeden

Gözlerini kapatsan,nefeslerimiz karışsa

Kıpkırmızı olur,terler boşanır,

Kalbin patlayacakmış gibi olur.

Ben seni bilir,anlarım

Peki sen beni anlar mısın? 

Sussak hiç konuşmasak,yalnızlığa pusu kursak

ıssız bir ada da ikimiz kalsak,

Ben sana baktığımda gözlerinde beni görsem

Ve bir tebessümle daldığım hayalden kendime gelip

Hiç hareketsiz bir süre gözgöze dursak

Tekrar gözlerine baksam

Beni anlarmısın', 'Ben sana ben seni desem Gerisini anlar mısın?  Sussak hiçbir şey söylemeden Gözlerini kapatsan,nefeslerimiz karışsa Kıpkırmızı olur,terler b...', ARRAY['Türk Edebiyatı','Şiir','Mete Yıldız']::text[], 8.5, '{"poet":"Mete Yıldız","poet_slug":"mete-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beni-anlarmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-fatma-guven-73h9o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilir misin yağmurun öyküsünü

Nasıl yollardan geçtiğini? 

Bazen sert mekanlardan,katı

Bazen kaygan zeminlerden,ıslak

Bazen görünmez,

Atmosfer gibi sarar seni

Zamanı gelince yağar damla,damla

Bazen kamçılar,öfkeli 

Bazen okşar,meltem gibi

Dersen ki; bana dol, yüreğimi sula,

Gelirim istemeler yeter bana.

Hazan vakti yağmuru değil,

Baharı getiririm ayaklarına.

Dağ başlarının esrikliğini,

Denizlerin sunarım meltemini.

Yeter ki iste, yağ de bana,

Yüreğine yağarım yağmur gibi.', 'Bilir misin yağmurun öyküsünü Nasıl yollardan geçtiğini?  Bazen sert mekanlardan,katı Bazen kaygan zeminlerden,ıslak Bazen görünmez, Atmosfe...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yagmur-261-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuruldum', 'vuruldum-mete-yildiz-99c0f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aslanköyün yüce toros dağında

Başpınar yanında yeşil bağında

Onyedi yaşında sevda çağında 

Narın ince belli kıza vuruldum.

Okula gidiyor çanta kolunda 

Şu zalim hayatın çamur yolunda 

Gör tanrım bu kulu Anadolunda

Esmer tatlı dilli kıza vuruldum.

Elinde gergefi işler nakışı

İçi sevgi dolu tatlı bakışı

Deli eder beni küpe takışı

Elinde al güllü kıza vuruldum.

Işıl ışıl bakan gözü güzeldir 

Temiz aşk anlatan sözü güzeldir

Yüzügüzel asıl özü güzeldir

Saçı ince telli kıza vuruldum.

Kuzu otlatıyor suyun başında 

Kuzyaka boyunda Odadaşında

Aşk derdine düşmüş ogenç yaşında

Entarisi allı kıza vuruldum.

Büyük adam olmak okumak düşü 

İçimi ısıtır güzel gülüşü 

Muhteşem olacak köye dünüşü

Kalın nasır elli kıza vuruldum.

Yıldız derki içim buruk buruktur

Yetişmezsen üzüm niye koruktur

Üzdü beni aşkı kalbimde oktur

İçi sevgi selli kıza vuruldum.', 'Aslanköyün yüce toros dağında Başpınar yanında yeşil bağında Onyedi yaşında sevda çağında  Narın ince belli kıza vuruldum. Okula gidiyor çan...', ARRAY['Türk Edebiyatı','Şiir','Mete Yıldız']::text[], 8.5, '{"poet":"Mete Yıldız","poet_slug":"mete-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vuruldum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-mete-yildiz-pc1yx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanmışım birde o kavurdu beni 

Yeliyle çöllere savurdu beni 

Felek vurdu birde o vurdu beni 

Ele çömert bana kuraktı zaman 

Dedimki hayata pembe bakayım 

Bulanık değil de durgun akayım 

Artık kafa tutma senden yakayım 

Dertlerle başbaşa bıraktı zaman 

Rüyamda görmüştüm hayale daldım 

Kendimce çok yeni kararlar aldım 

Beyhude çabalar bak yalnız kaldım 

Benim hayalimden ıraktı zaman 

Suçum neyse söyle bende bileyim 

Bağışla diyerek ben af dileyim 

Dindir şu acımı yaşım sileyim 

Bir usta yanında çıraktı zaman 

Ben doğdum doğalı benle uğraştı 

Çocukken ağlattı gözümde yaştı 

Oynadığın oyun boyunu aştı 

Kader oyununda kırıktı zaman', 'Yanmışım birde o kavurdu beni  Yeliyle çöllere savurdu beni  Felek vurdu birde o vurdu beni  Ele çömert bana kuraktı zaman  Dedimki hayata p...', ARRAY['Türk Edebiyatı','Şiir','Mete Yıldız']::text[], 8.5, '{"poet":"Mete Yıldız","poet_slug":"mete-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zaman-292-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen bir aşkla', 'bitmeyen-bir-askla-halil-colak-syom5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bitmeyen bir aşkla

Bu gönül sevecek seni

Senin aşkın ateşi artacak

Yakamozlar gibi

Ruhumda parlayacak

Bir ömür boyu sürecek

Gece gündüz bitmeyecek

Bu hayat seninle

Vuslata erecek yine

Halil Çolak 3.2.2006 Ankara', 'Bitmeyen bir aşkla Bu gönül sevecek seni Senin aşkın ateşi artacak Yakamozlar gibi Ruhumda parlayacak Bir ömür boyu sürecek Gece gündüz bitm...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bitmeyen-bir-askla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm aşkınla yanıp tutuşur', 'gonlum-askinla-yanip-tutusur-halil-colak-9rbrs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalp hep sana aşıktır Rabbim

Gönlüm aşkınla yanıp tutuşur

Bir gün nasıp olursa 

İki cihan selveri ile buluşur

Bu aşk uçsuz bucaksız  okyanusta yüzüyor

Seven Kalpler seni gece gündüz  anıyor

Kalpler seni andıkça Rabbim 

Sonsuz mutluğa,felaha eriyor

Halil Çolak 3.2.2006 Ankara', 'Kalp hep sana aşıktır Rabbim Gönlüm aşkınla yanıp tutuşur Bir gün nasıp olursa  İki cihan selveri ile buluşur Bu aşk uçsuz bucaksız  okyanus...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gonlum-askinla-yanip-tutusur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki gözüm', 'i-ki-gozum-mete-yildiz-pvbf6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu ara başında dolaşır hüzün

Morali bozulmuş can iki gözüm

Sinir harab olmuş dalaşır sözüm

Uykusuz gözlerin kan iki gözüm.

Eller çeker gider keyfine bakar

Sen kendi derdine yan iki gözüm

Bu yaz bizim sular bulanık akar

Dertlerin kervanı han iki gözüm

Sırrın demez ele içine atar

Katmerlenmiş bizde dert katar katar

Uyku girmez göze dost nasıl yatar

Hava aydınlandı tan iki gözüm

Felek reva gördü bunca çileyi

Nasılda doldurduk onca seneyi

Düşün,taşın,konuş kapat çeneyi

Tepende çalınır çan iki gözüm

Dert bir olsa belki katlanır insan 

Yoksulluk sırtımdan inmiyor bir an

Şu çarkı tersine çevirsem inan 

Aklımdan çıkmıyor nan* iki gözüm

Mete YILDIZ

*Nan:Ekmek', 'Bu ara başında dolaşır hüzün Morali bozulmuş can iki gözüm Sinir harab olmuş dalaşır sözüm Uykusuz gözlerin kan iki gözüm. Eller çeker gider...', ARRAY['Türk Edebiyatı','Şiir','Mete Yıldız']::text[], 8.5, '{"poet":"Mete Yıldız","poet_slug":"mete-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/iki-gozum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Sonra Samsun''a Gittim', 'yillar-sonra-samsun-a-gittim-yusuf-onder-bahceci-mjv86', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllar sonra ben Samsun''a gittim,

Deniz kıyısında daldım da gittim,

Bilmiyorum gittiğime iyimi ettim,

Yıllar sonra ben Samsun''a gittim.

Samsun hiç tat vermiyordu inan,

Dalgalar kıyıyı dövüyordu Liman,

Geçti gözümün önünden yaşanan,

Yıllar sonra ben Samsun''a gittim.

Gezdiğim yerleri tekrar gezdim,

Kalbim mahsundu gülümsedim,

Sen yoksun Samsun''da dedim,

Yıllar sonra ben Samsun''a gittim.

Samsun denince kalbim çarpıyor,

Samsun''un güzeli yürek yakıyor,

Samsun denilince yola bakıyor,

Yıllar sonra ben Samsun''a gittim....', 'Yıllar sonra ben Samsun''a gittim, Deniz kıyısında daldım da gittim, Bilmiyorum gittiğime iyimi ettim, Yıllar sonra ben Samsun''a gittim. Sams...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yillar-sonra-samsun-a-gittim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşun Gibi Sıkılıyorum', 'kursun-gibi-sikiliyorum-adnan-yesiltas-gwwnc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duygusallık... 

Başımdaki en büyük bela. 

Diyorlar ki, 

Politik ol mesela

Susamıyorum,

Dayanamıyorum.

Bir atımlık,

Kurşun gibi sıkılıyorum.', 'Duygusallık...  Başımdaki en büyük bela.  Diyorlar ki,  Politik ol mesela Susamıyorum, Dayanamıyorum. Bir atımlık, Kurşun gibi sıkılıyorum....', ARRAY['Türk Edebiyatı','Şiir','Adnan Yeşiltaş']::text[], 8.5, '{"poet":"Adnan Yeşiltaş","poet_slug":"adnan-yesiltas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kursun-gibi-sikiliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gece hüzünlüyüm ben', 'bu-gece-huzunluyum-ben-halil-colak-nd8ik', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gece hüzünlüyüm ben

Yoksa çünkü yanımda yoksun sen

Ay bile doğmuş erkenden

Gökyüzünde yıldızlarda yok

Bu gecenin karanlığında 

Yalnız kalmışım ben

Kalbim hicranı aşkınla yanarken

Güzelim hiç aldırmıyorsun sen

Sevginle kıvranıyorum aşkım ben

Halil Çolak 3.2.2006 Ankara', 'Bu gece hüzünlüyüm ben Yoksa çünkü yanımda yoksun sen Ay bile doğmuş erkenden Gökyüzünde yıldızlarda yok Bu gecenin karanlığında  Yalnız kal...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-gece-huzunluyum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim dostluk', 'bizim-dostluk-mete-yildiz-g1hwh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eski tanıdığım dostlardan biri,

Çok konuda usta işinin piri,

Dertlerle yoğrulmuş bedeni diri,

Okulda en güzel araydı bizim.

Yetmiş sonlarında tanıştık onla,

Nice anılar var belki de tonla,

Karşılıklı güven bak şimdi anla,

Mesajımız arza varaydı bizim.

Her şeyi paylaştık beni üzmedi,

Uğraştı,didindi boşta gezmedi,

Dostluğun sırrını kimse çözmedi,

Tam kaynaştığımız yaraydı bizim.

Ben fakirdim o da benden fakirdi,

Bozulmuş toplumda ender bakirdi,

Böl diye ucundan ekmek getirdi,

İlk paylaştığımız paraydı bizim.

İkimizde dertli o bir başkaydı,

Maalesef bu tarzda benden baştaydı,

Ayrıldık dünyamdan bir yıldız kaydı,

Belli ki bahtımız karaydı bizim.

Bir ekmek bulmuşsak o gün mutluyduk,

Okumak isterdik çok umutluyduk,

Cam gibi havada biz bulutluyduk,

En has katığımız şıraydı bizim.

Odunları yakar biz ısınırdık,

Ocak çevresinde ders çalışırdık,

Odadan odaya çıra taşırdık,

Süper ışığımız çıraydı bizim.

Karayolu üstte kavak dibinde,

Mete nin metelik yoktur cebinde,

Çalışkan ahlaklı tam edebinde,

Baraka evimiz kiraydı bizim.

Bu şartlarda derse hazır olurduk,

Yılmadık gayretle didindik durduk,

Edebiyat dedik gözünden vurduk,

Şiirde en güzel sıraydı bizim.

Çok bilmiş olmadık adam seçmedik,

Zayıf kişilerle dalga geçmedik,

Gurbete gittiysek kalben göçmedik,

En güzel yanımız buraydı bizim.

Hayatı tanıdık hayret içinde,

Bir yıl oldu nikah otuz üçün de,

Ekmek için dostum gurbet göçünde,

Yaş otuz beş yolun yarıydı bizim.

O mısır satardı bende karsambaç,

Çalmadım çalıştım çünkü karnım aç,

Arkadaş görünce oyna saklambaç,

O kar Arslanköy''ün karıydı bizim.

Heyecanla oturup saydık parayı,

Emek yok sermaye geçti yarıyı,

Ayırdık kar ile yirmi darıyı,

On lira kısa gün karıydı bizim.

Acımasız hayat pişirdi bizi, 

Kul önünde mahcup düşürdü bizi,

Ayrı diyarlardan deşirdi bizi,

Aslında yerimiz saraydı bizim. 

(28 Yıllık eskimeyen bir dostluğun ürünü,dostuma en derin sevgilerimle,yolu açık kalemi keskin olsun)', 'Eski tanıdığım dostlardan biri, Çok konuda usta işinin piri, Dertlerle yoğrulmuş bedeni diri, Okulda en güzel araydı bizim. Yetmiş sonlarınd...', ARRAY['Türk Edebiyatı','Şiir','Mete Yıldız']::text[], 8.5, '{"poet":"Mete Yıldız","poet_slug":"mete-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/bizim-dostluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şen gönüllerde kaldı yitirdiğimiz zaman', 'sen-gonullerde-kaldi-yitirdigimiz-zaman-kemal-eyupoglu-urr7n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şen gönüllerde kaldı yitirdiğimiz zaman

			        Birbirine karıştı  dünyada sapla saman

			        Öyle bir kış yaşadım, bir öncekinden yaman

			        Şimdi ne gençlik kaldı ne bitmeyen arzular

			        Ulu çınarı bile kırdı harap etti kar.

			        Teselli fayda etmez yaralı gönüllere

			        Göz görmüyor baksa da ince kıvrak bellere

			        Sade Mecnun mu düştü  yangın yeri çöllere

			        Yol bitti yolcu gitti, büyük aşka dünya dar

			        Şimdi uzakta kaldı, görünmeyen oldu yar.

			       Nerelere gizlendi o eski  muhabbetler

			       Yıkıp tüketti bizi tükenmeyen kasvetler

			       Serçe yüreği sevdam, önünde bitmez setler

			       Köhnemiş bile olsa yüreğimde boş yer var

			      Ecel gelip sarmadan bir kere olsun sen sar. 

			        						03/02/2006', 'Şen gönüllerde kaldı yitirdiğimiz zaman 			        Birbirine karıştı  dünyada sapla saman 			        Öyle bir kış yaşadım, bir öncekinden ya...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-gonullerde-kaldi-yitirdigimiz-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet vatan', 'cennet-vatan-mete-yildiz-uxgbg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir günde dört mevsim yaşıyor yurttaş

Tarih, doğa, orman cennet arkadaş

Mavi denize gir geçmemişse yaş

Bu cennet vatanı sevmek ibadet

Dünyada her yerden gelir turistler

Aksilik olmasa akar dövizler

Yer altında vatan tarihler gizler

Bu cennet vatanı sevmek ibadet

Dağlar yeşil orman kıyıda deniz

Masmavi, cam gibi ah bir görseniz

Vatan kıymetini bilenlerdeniz

Bu cennet vatanı sevmek ibadet

Kutsal değerlerle aldık nitelik

Ödeşemem şiir yazmazsam gündelik

Aşkı iliğime geçti üstelik

Bu cennet vatanı sevmek ibadet

Tarih, doğa maden cömert diyarım

Yurdumda olmaktan gurur duyarım

Ayrıca Türklükten çok bahtiyarım

Bu cennet vatanı sevmek ibadet

Yer altında petrol çok imiş bor’u

Neden işlenmez’ki kafamda soru

İstemeyenin var aklından zoru

Bu cennet vatanı sevmek ibadet

Yuh olsun hizmette cömert değilsek

Bu güzelliklere bizler eğilsek

Vakit çok geçmeden kıymetin bilsek

Bu cennet vatanı sevmek ibadet

Vatan sevgisiyle doluyum gayet

Hizmet şeref fırsat bulursam şayet

Şu ömrüm yolunda bulsun nihayet

Bu cennet vatanı sevmek ibadet

Nice medeniyet beşiği olmuş

İnsanlığın büyük ışığı olmuş

YILDIZ gezip görmüş aşığı olmuş

Bu cennet vatanı sevmek ibadet', 'Bir günde dört mevsim yaşıyor yurttaş Tarih, doğa, orman cennet arkadaş Mavi denize gir geçmemişse yaş Bu cennet vatanı sevmek ibadet Dünyad...', ARRAY['Türk Edebiyatı','Şiir','Mete Yıldız']::text[], 8.5, '{"poet":"Mete Yıldız","poet_slug":"mete-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/cennet-vatan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetim', 'yetim-ali-cengiz-turan-b88f5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küçükken yetim kalmış,görmemişti ana kucağı,

Kucağında uyuyup saçlarını okşatacağı,

Gözleri pırıl pırıl sevgi saçarak bakar,

İyilik meleği gibi kötüye iyilik yapar.

Baharda çiçek toplar deste deste yapardı,

Onları alır gider  pazarlarda satardı,

Yüzü her zaman güler kimseyi incitmezdi,

Sevgi.şevkat yoksunu; kahrını bildirmezdi.

Birde türküsü vardı yanık yanık söylerdi,

Dinleyici toplumu haklıca büyülerdi.

Horlamak görse dahi sevgiyle bakardı,

Kalplere taht kursada ana sevgisi arardı.', 'Küçükken yetim kalmış,görmemişti ana kucağı, Kucağında uyuyup saçlarını okşatacağı, Gözleri pırıl pırıl sevgi saçarak bakar, İyilik meleği g...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yetim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkta kaybetmem', 'askta-kaybetmem-mete-yildiz-jixpi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçici aşklara kapım kapalı,

On iki yıl oldu ona tapalı,

Kimseye bakmadım nikah yapalı,

Kumarda kaybetsem aşkta kaybetmem,

Daha önceleri basit hevesi,

Sevdiğimi sandım aşkın cilvesi,

Cillop gibi kızlar işin neşesi,

Şansta olabilir aşkta kaybetmem.

Değişik çiçekler artık duruldum,

Aslıhan hanıma birden vuruldum,

Nikahını aldım köşke kuruldum,

İşimi bilemem aşkta kaybetmem.

Kuşkusuz inanır tamdır güveni,

Yalanı tanımaz yoktur dümeni,

Karşılıklı güven aşkın düzeni,

Borsada kaybettim aşkta kaybetmem.

İkimiz bir elma iki yarısı,

Herkes gıpta eder kimin karısı,

Mutluyuz çok şükür size darısı,

Yazı tura değil aşkta kaybetmem.

Canı gibi sever gösterir örnek.,

Çok saygı değerdir gerekir görmek,

Kızdırmayın sakın ateşten gömlek,

Hiddet ile kızıp aşkta kaybetmem.

Hep beni düşünür canımın içi,

İki yavru bir ben hayatı üçü,

Bize neler verir yeterse gücü,

Darısı sizlere aşkta kaybetmem.', 'Geçici aşklara kapım kapalı, On iki yıl oldu ona tapalı, Kimseye bakmadım nikah yapalı, Kumarda kaybetsem aşkta kaybetmem, Daha önceleri bas...', ARRAY['Türk Edebiyatı','Şiir','Mete Yıldız']::text[], 8.5, '{"poet":"Mete Yıldız","poet_slug":"mete-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/askta-kaybetmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğumgünü', 'dogumgunu-murat-gulener-mq4my', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen doğduğunda dünya değişti

Herkes kıyamet kopacak demişti

Oysa bilmiyorlardı ki

Dünyaya bir melek gelmişti

Bir melek ki melekler kıskanır

Bir güzel ki gönlüm ıslanır

Bir de huyu var ki

Gözyaşlarım uslanır

Hayata gelirken bile güldüysen

Çokmu senin için öldüysem

Sana yüreğimi göndersem

İçine bir tutam sevgi koyar mısın

Sevgimiz dünyaya örnek olsun

Melekler bile ağlar olsun

Gözyaşlarının adı sevinç olsun

Doğumgünün kutlu olsun.', 'Sen doğduğunda dünya değişti Herkes kıyamet kopacak demişti Oysa bilmiyorlardı ki Dünyaya bir melek gelmişti Bir melek ki melekler kıskanır ...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dogumgunu-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suret Şaire', 'suret-saire-tulay-sustam-qe2ag', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'daha düne kadar

okur yazardın

beni okumaya başladıktan sonra

şiir yazamadın

bir günde değişiklik yap

benden başkasını oku

belki bir gün

okuduklarından anladığını yazarsın', 'daha düne kadar okur yazardın beni okumaya başladıktan sonra şiir yazamadın bir günde değişiklik yap benden başkasını oku belki bir gün okud...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/suret-saire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna Tarifine Arif Gerekmez', 'ayna-tarifine-arif-gerekmez-hasan-ozcan-gornn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayna Tarifine Arif Gerekmez

Bahardan geçti ömrüm

Gün yirmi dört saatti, sevda yirmi dört

Şiir ikliminde demirliydi gönlüm

Eylül geliyorum demezmiş, sonbahar öyle

Şarkılar beni çekmez

Simaya ukba vurmuş, serviler el sallar

Ayna tarifine arif gerekmez

[email protected]', 'Ayna Tarifine Arif Gerekmez Bahardan geçti ömrüm Gün yirmi dört saatti, sevda yirmi dört Şiir ikliminde demirliydi gönlüm Eylül geliyorum de...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özcan']::text[], 8.5, '{"poet":"Hasan Özcan","poet_slug":"hasan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayna-tarifine-arif-gerekmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelde Kışım Dönsün Bahara', 'gelde-kisim-donsun-bahara-kamil-soylemez-ie4li', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel sevdam, gel bana da

Kışım dönsün bahara

Salınıp,meyve tutsun

Ömrüm uzansın sana

Sevmek varsa hağla

Bilki sanadır sana

Başkasına körüm

Senin aşkın,sevdanla

Haydi çıkta gel

Otur yanı,yanıbaşıma

Tut ellerimi

Tut haydi durma

Yüreğim sanadır

Ömrüm sana

Neyim varsa senin

Bunu sakın unutma', 'Gel sevdam, gel bana da Kışım dönsün bahara Salınıp,meyve tutsun Ömrüm uzansın sana Sevmek varsa hağla Bilki sanadır sana Başkasına körüm Se...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelde-kisim-donsun-bahara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafağı Bekliyorum', 'safagi-bekliyorum-hasan-ozcan-g38pz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şafağı Bekliyorum

Sen uyu zeytin gözlüm ay doğsun üzerine

Yağmurlar yağdırayım ben rüyana bereket

Mahmurluğu, hüznü öyle yoğur sabaha

Can yangını çıkarsın bir can değsin bu lezzet

Rüyamdan çıkmasan da bölünür dayanamam

Artık gündüzlerimi geceye ekliyorum

Biliyorum bu aşka bu kısa ömür yetmez

Uykuyu ben uyuttum şafağı bekliyorum

[email protected]', 'Şafağı Bekliyorum Sen uyu zeytin gözlüm ay doğsun üzerine Yağmurlar yağdırayım ben rüyana bereket Mahmurluğu, hüznü öyle yoğur sabaha Can ya...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özcan']::text[], 8.5, '{"poet":"Hasan Özcan","poet_slug":"hasan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/safagi-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek ve Ayrılık', 'sevmek-ve-ayrilik-murat-gulener-ob2tl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmek; 

Elinden tutmak değil

Ona sarılmak değil

Birkere olsun öpmek değil

Sevmek; 

Bunlar olmadan da yaşayabilmektir

Ayrılık; 

Onu görmemek değil

Ona gitmemek değil

Ondan uzaklaşmak ta değil

Ayrılık; 

Onu düşünmeden de yaşayabilmektir', 'Sevmek;  Elinden tutmak değil Ona sarılmak değil Birkere olsun öpmek değil Sevmek;  Bunlar olmadan da yaşayabilmektir Ayrılık;  Onu görmemek...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmek-ve-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öykü 4', 'oyku-4-levent-i-skenderoglu-ajpu5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Su birikintileri içinde 

Sürüklenen birkaç sonbahar

Saman duvarlı evin 

Penceresinden onlara bakan 

Bir çift göz

Sıcak sadece içeride

Anlı soğuk cama yaslı 

Gök dumanlı dağlar puslu

İki söyle bir suslu

Muhabbetler içindeyim

…

Sürüklenen sadece boşluk

Annem ve hatıralar sadece

İçimde kalan ve susların

Yağmurlarla ıslandığı yerde 

Sade iniltileriyle

Kara saplı bir keman

…

İniltiler içinde çocukluğum

…

Sıcak soba kör kapılar

Soğuk balkon

Şaşı vişne ağaçları

Çürük tahtalarıyla bir ahşap merdiven

Akşamları sabırla beklenen

Bulgur pilavı

Sabahları dokuz parçaya bölünen 

Bir dilim peynir

Islatılıp rengi kaçana kadar içilen 

Çaylar

İçilmeyen gazozlardan biriken 

Kapaklar

…

Tahta masa muşamba gerili

Üçlü ocak dar pencere

Teldolapta unutulan bal kavun

Kazanda kaynayan bulgur

Sokağa serilen pestil

…

Ak dolaklar 

Sarmaşıklar

İri direkler 

Güçlü hezanlar

İki akşam sefası 

Bir mor menekşe

…

İçli içli beklenen bir serçe

Bir kalbur

Uzunca bir ip

Küçük bir sopa 

Ve bir avuç ekmek kırıntısı

…

Büyük düşler

Ani susuşlar

Sıçrayan zaman

Kaybolan anılar

Direnen renkler

Sardunyam 

Ve annem

…

2002', 'Su birikintileri içinde  Sürüklenen birkaç sonbahar Saman duvarlı evin  Penceresinden onlara bakan  Bir çift göz Sıcak sadece içeride Anlı s...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/oyku-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya sen? Sen Beni! ! !', 'ya-sen-sen-beni-gul-yazganarikan-hm18b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben seni sevmiş miydim,

O sen miydin? 

Damarlarımda dolaşan,

Alev alev yakardı parmakların

Pişerdi etlerim de

Yine de kaynaşırdı kemiklerim seninle...

Ben seni sevmiş miydim? 

O Sen miydin? 

Yağlı urganlarla boynuma doladığım,

Sevgili azrailim, alın yazım, celladım,

Durma al canımı,

Azrail sensen eğer.

Ölüm seninle gelsin...

Sana değer....

Yine de ölmeden önce, 

Ben seni sevmiş miydim? 

Ya sen! , Sen beni?', 'Ben seni sevmiş miydim, O sen miydin?  Damarlarımda dolaşan, Alev alev yakardı parmakların Pişerdi etlerim de Yine de kaynaşırdı kemiklerim ...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ya-sen-sen-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum sen de üzüleceksin...', 'biliyorum-sen-de-uzuleceksin-ercan-akbay-evzo5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyorum sen de,üzüleceksin

   Söylemeye bir güç,bulamıyorum

   Oysa ki isterdim,bu aşk bitmesin

   Sürdürmeye bir yol,bulamıyorum.

   Sanki boynu bükük,gül ağacıyım

   Yüzüne bakıp ta,gülemiyorum

   Sanacaksın küstüm,sana dargınım

   Anla beni biraz,üzülüyorum..

   Biliyorum sen de,ağlayacaksın

   Elvedalı bir söz,diyemiyorum

   Oysa ki gönlüm de,bir yanardağsın

   Söndürmeye bir su,bulamıyorum...   

   Sanki boynu bükük,gül ağacıyım

   Yüzüne bakıp ta,gülemiyorum

   Sanacaksın küstüm,sana dargınım

   Anla beni biraz,üzülüyorum....

                    21.7.1993

                    Makam..Uşşak   Beste..Ruşen Yılmaz

                    Ruşen Yılmaz tarafından kaset ve cd. ye okunmuştur.', 'Biliyorum sen de,üzüleceksin    Söylemeye bir güç,bulamıyorum    Oysa ki isterdim,bu aşk bitmesin    Sürdürmeye bir yol,bulamıyorum.    Sank...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/biliyorum-sen-de-uzuleceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gittim Ben', 'dun-gittim-ben-gul-yazganarikan-dblvi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sustu gözlerim artık,

Konuşmazlar seninle...

Sözlerim, onlar da bitmiş.

Ben 

Gittim

Dün gittim Ben,

Bugün gittim.

Gittiğinden beri, gitmekteydim..

Bilemedim geleceğini,

Bu dikeni bıraktım...

Senin Gül’ün yerine...', 'Sustu gözlerim artık, Konuşmazlar seninle... Sözlerim, onlar da bitmiş. Ben  Gittim Dün gittim Ben, Bugün gittim. Gittiğinden beri, gitmekte...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dun-gittim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Taneyim', 'ben-bir-taneyim-dogan-i-nceman-8ddzr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çuval pirinçte

Bir tane''yim ben; 

Benim gibiler,

Biz olmazsak

Sarmaş dolaş,

Nasıl geliriz masanıza,

Bir tabak pilav olarak? 

Arkadaşlarımız o güzelim sosuyla

Nasıl kuru''lur üstümüze? 

Ben,bizim...

Ben,önemliyim! 

Çuvalın en dibinde de kalsam

Ben bir taneyim!', 'Bir çuval pirinçte Bir tane''yim ben;  Benim gibiler, Biz olmazsak Sarmaş dolaş, Nasıl geliriz masanıza, Bir tabak pilav olarak?  Arkadaşları...', ARRAY['Türk Edebiyatı','Şiir','Doğan İnceman']::text[], 8.5, '{"poet":"Doğan İnceman","poet_slug":"dogan-i-nceman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-bir-taneyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük', 'dortluk-ali-cengiz-turan-ony5a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çağlayan duygularım karışık hisle dolu,

Çekilen çilelerin denizinde boğuldum.

Bir yol istiyorum doğruluğa gidecek,

Hayatın acısını ferah ile silecek.....', 'Çağlayan duygularım karışık hisle dolu, Çekilen çilelerin denizinde boğuldum. Bir yol istiyorum doğruluğa gidecek, Hayatın acısını ferah ile...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Dünyası', 'hayal-dunyasi-ali-cengiz-turan-f1773', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğmuşuz kaza ile yaşıyoruz hayal ile,

Para servet hayali renkli rüyalar yarab! ! 

Hayallerle yaşayıp gerçekler tak deyince,

Sudan çıkmış balığa dönmüşüz yarab! ! ! 

Yıllarca hayallerle ömrümüz geçiyor,

Hayalleri ümite banmışız yarab! ! ! ! ! ! ! 

Ha bugün ha yarın belki deyipte,

Şu kısacık hayatta yanmışız yarab! ! ! ! ! ! ! ! 

Gerçeğin hayalleri her zaman bizle,

Yaşayıp hayallere dalmışız yarab! ! ! ! ! ! ! ! 

Zamanın darbesi hayallerimize,

Doğduğumuza pişman olmuşuz yarab! ! ! ! ! ! ! 

Binlerce hayalin varlığı senin,

Binde bir olsa da gerçekle yarab! ! ! ! ! 

Şu zalimce akıp geçen zamanda,

Hayalimizin kurbanı olmuşuz yarab! ! ! ! ! ! ! ! ! ! ! ! ! ! ! !', 'Doğmuşuz kaza ile yaşıyoruz hayal ile, Para servet hayali renkli rüyalar yarab! !  Hayallerle yaşayıp gerçekler tak deyince, Sudan çıkmış ba...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayal-dunyasi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giden Senelerimle', 'giden-senelerimle-ali-cengiz-turan-cs5aq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zamandan zamanımı çıkardım zamanım benimle,

Ömrümden ömür vermiyorum giden senelerimle,

Durdurdum zamanı kendi hünerlerimle,

Bin seneye bir sene aşlı meyvelerimle.......

Zamanımı çevirdim geri dönüş başladı,

Ruhum kendini buldu,doğuşum kolaylaştı.

Geçen yılları sildim ruhumun gözleriyle,

Zamanımı anladım geri dönüş başladı.....', 'Zamandan zamanımı çıkardım zamanım benimle, Ömrümden ömür vermiyorum giden senelerimle, Durdurdum zamanı kendi hünerlerimle, Bin seneye bir ...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/giden-senelerimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes yapamaz', 'herkes-yapamaz-omer-dalman-x6d10', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herkes yazar

herkes çizer

herkes iletir bir şeyleri; 

herkes uçar

herkes kaçar

ama

kaç kişi bir şeyi tam yaşar

                            ve benliğine kaydeder? 

Herkes konuşur

herkes fikir verir

hayatı kağıt üstünde bitirir

                            mezun olur

ama

kaç kişi mucize sergiler? 

kaç kişi bütün o çekilmez yüklere rağmen

yüzündeki aydınlığı bitmez kılar

hep ayakta kalır umutlarıyla

ve herkese aynı umudu verir? 

Herkes yazar

herkes çizer

ama

herkes ''yapamaz''

(Temmuz 2005)', 'Herkes yazar herkes çizer herkes iletir bir şeyleri;  herkes uçar herkes kaçar ama kaç kişi bir şeyi tam yaşar                             v...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/herkes-yapamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konu ''Şiir'' Olunca (İzlenim)', 'konu-siir-olunca-i-zlenim-aynur-uluc-tio3t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Şiir'' konuşmak gerek

Coşa coşa

Düşe kalka

Güle ağlaya

En çok da

Şiir olup akmak gerek

Hayata…

Türk Dili Dergisi Geleneksel Perşembe Toplantılarında şubat ayının ilk konusu yine şiir ‘e ayrılmıştı.Yakın tarihlere baktığımızda, 5 ocak tarihinde Ahmet Necdet, “Türk Şiirinde Nazım Biçimleri” konusunu aktarmıştı. Daha sonra 19 ocak tarihinde Sebahattin Kömürcüoğlu “Şiirin Oluşum Öyküsü”  ana başlığı altında bir çalışma hazırlamıştı.  Şiir konusundaki bir diğer toplantı da 2 şubatta Bedrettin Aykın’ın hazırladığı “Türk Şiirinin Geçmişi” konulu konuşma oldu.

Hazırlanan sunum bittikten sonra başlayan soru cevap bölümünde şiire ilişkin pek çok konu tartışıldı bu toplantılarda.ve farklı bakış açıları ortaya kondu. Şiirin konuşulduğu her yerde bir kavşak illa ki, düz yazıdan geçer. Aralarındaki farklar açımlanır. Bu toplantıların her birinde de böyle oldu. Düz yazıya içindeki şiirsel dilin kattığı zenginlikten ve düz yazının da aynı şiir gibi kendi müziğini yaratmayı başarırsa daha fazla değer kazanacağından ve  şiirin düz yazıdan ayrışma noktalarının öneminden konuşuldu. Yer yer “şiir çıkmazda mı”  sorusu gündeme getirildi, tarihin pek çok döneminde de bu sorunun aynı şekilde sıkça masaya yatırıldığına da dikkat çekilerek. Ve şiir ile halkın arasındaki ilişki düzeyleri konuşulurken şiirin tarihçesinde nasıl olduğu incelenerek bugünkü duruma bakıldığında elbette sanal ortamın şiire olacak farklı etkileri konuşulmadan bırakılamazdı. Burada kontrol mekanizması olmaksızın okuyucu ile buluşan dizelerin genel çerçevede niteliksiz bir gidişe zemin sağlayabileceği ifade edildi.

Konuya dergiler açısından bakıldığında ise; şimdilerde toplam sayıları iki yüze varan  dergilerin varlığının gençlere  kendisini gösterme adına fırsat kapısı açtığı belirtildi. Ancak bu anlamda edebiyata sağladığı avantajın, pek çok niteliksiz ürünün de kendine dergilerde yer bulabilmesi ve dolayısıyla şiir yazanların daha güzeli arama noktasında rahatlaması ve daha güzele ulaşmayı   zorlamaması ve bu durumun da genel şiir niteliği düzeyini de beraberinde düşürmesi açısından ise edebiyata dezavantaj olarak yansıyan bir yanının da bulunduğu dile getirildi. 

Konuşulmuş pek çok açının yanı sıra toplantıya ayrılan sürenin kısıtlılığı  nedeniyle pek çok konuşulamayan cümleyle ayrılındı her seferinde de bu toplantılardan. Ancak “Şiir” konulu toplantıların diğer haftalarda işlenen farklı konulara göre sunum sonrasındaki soru cevap bölümünde daha heyecanlı geçmesi, belki de “şiir”in kendi mayasında tuttuğu dokudan kaynaklanıyordur diye düşündüm ben de bu hararetli konuşmaları izledikçe.

(03-02-2006)', '''Şiir'' konuşmak gerek Coşa coşa Düşe kalka Güle ağlaya En çok da Şiir olup akmak gerek Hayata… Türk Dili Dergisi Geleneksel Perşembe Toplant...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/konu-siir-olunca-izlenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Dağlar....', 'mor-daglar-nurdane-diken-cssqm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel! senden bir haber hemen sorayım

Bu dert neden gitmez el verin dağlar

Gerçek sevenlere yürek süreyim

Bu dert neden bitmez, bel verin dağlar..

Bir bülbül konmuşsa dalın başına 

Yâr gülü takmışsa kendi başına 

Biterler güzelin kalem kaşına

Ilgıt ılgıt esin, yel verin dağlar..

Her nereye baksam halim yamandır

Yıldızdağı neden kıştır dumandır? 

Hasret gönlüm sıktı hayli zamandır

Açılın kapılar, yol verin dağlar..

Dağların ardında hep kalacaksan

Şeyda''dan haberler sen alacaksan

Kendine sen gibi yâr bulacaksan

Gelmeyin üstüme, sel verin dağlar..

Bülbül dalda öter gül yolu tutar 

Hasretin dondurur beden buz tutar

Gönlüm bir çıradır yâr hemen çatar

Kışından üşüdüm, şal verin dağlar..

Sen gibi güzele nasıl bakayım

Ceza haktan geldi kime takayım

Sensiz aşk ateşi nasıl yakayım

Bir çapsıza çarptım, sal verin dağlar...', 'Gel! senden bir haber hemen sorayım Bu dert neden gitmez el verin dağlar Gerçek sevenlere yürek süreyim Bu dert neden bitmez, bel verin dağl...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mor-daglar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sitem**', 'sitem-serkan-turna-vdl8m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Talihin rüzgarı

Ters eser belki.

Sabır taşı olur

Beklerim…

Bilirsin.! 

Nede olsa 

Hep tersine gider

İşlerim.

Ama sen 

Sakın küsme 

Aynadaki yüzüne.

Aynalar yalan 

Söylemez bilirim.

Görünen değil,

Görünmeyen 

Yüzüne ki

Sitemim…', 'Talihin rüzgarı Ters eser belki. Sabır taşı olur Beklerim… Bilirsin.!  Nede olsa  Hep tersine gider İşlerim. Ama sen  Sakın küsme  Aynadaki ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Turna']::text[], 8.5, '{"poet":"Serkan Turna","poet_slug":"serkan-turna","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sitem-227-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-ali-cengiz-turan-gjyap', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hızla geçen zamanda hep boynu bükük,

Ağlayıp güldüren heves olmuşsun.

Mevsimler içinde bahar gibiydin,

Zamansız başlayan kışa dönmüşsün.

Sengiyle,şefkate her zaman hasret,

Rüzgarla uçuşan yaprak olmuşsun.

Dikenle çevrili bir gül gibiydin,

Sararmış,solmuş çöle dönmüşsün............', 'Hızla geçen zamanda hep boynu bükük, Ağlayıp güldüren heves olmuşsun. Mevsimler içinde bahar gibiydin, Zamansız başlayan kışa dönmüşsün. Sen...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kader-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-i-brahim-halil-demir-ln0nj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönlüme giden yollar çamur,

Nazlı yarimin elleri hamur.

Sabreyle sevdiceğim, az kaldı vuslata! 

Bak yağıyor bardaktan boşanırcasına yağmur.

Yarime giden yollar gül bahçesi,

Akıyor şarıl şarıl sevda çeşmesi.

Al eline doldur ha bire sevda kovalarını! 

İçeyim kana kana, artsın gönlüm neşesi.

Aşkımıza giden yollar, dikenli taşlı,

Sevdalılar meclisinde, yarim en ağır başlı.

Sürmeler çekmesine hiç gerek yok,

Gönlümü çalan yar,vesmer yüzlü, kara kaşlı.

Mutluluğa giden yollar tehlikeli,

Giydirdiğin sevdanın gömleği lekeli.

Bitmez, tükenmez sana olan duygularım,

Aşkın zoruyla, yüreğimi söktün sökeli.

Seveni sevdiğine, kavuşturan yollar inişli çıkışlı,

Uğruna her şeyimi feda ettiğim yar, sevda bakışlı.

Okumaya doyamadığım, yarin mektupları,

Satır,satır sevda işlemeli, en güzel aşk nakışlı.

02/02/2006', 'Gönlüme giden yollar çamur, Nazlı yarimin elleri hamur. Sabreyle sevdiceğim, az kaldı vuslata!  Bak yağıyor bardaktan boşanırcasına yağmur. ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yollar-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Zamana Sîtem', 'zamana-s-tem-ahmet-turan-altunsu-4kqvd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'selâmsız, sabahsız kaldık yine telve gözlü yâr

bir kahır cenderesinde boğuşur hayallerim

kapatılmış kapılardan ibaret izbe diyâr

bağlar elimi kolumu; bir ümit hayallerim…

dağlar... sıra sıra dağlar... dizilmiş ardı sıra

bir intizar gönderirim nazar edip dağlara…

hasret, basamak basamak çıkarken yücelere

her adımında ezilir yüreğim: sızım sızım...

ne yetinir, ne sığarım gündüz ve gecelere

kim bilir hangi zamana gizlenmiş hayırsızım...

yollar... bitmek bilmez yollar... uzanır sonsuzluğa

bir intizar gönderirim: vursun zamansızlığa...

........................03.02.2006 / Güdül / ANKARA

..............................Ahmet Turan Altunsu', 'selâmsız, sabahsız kaldık yine telve gözlü yâr bir kahır cenderesinde boğuşur hayallerim kapatılmış kapılardan ibaret izbe diyâr bağlar elim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zamana-sitem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-nazan-i-zmirli-e8t9d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dil  tutulmuş

gözler 

erdemliğinin

derinlerinde

sessizliğimin sesini

arar oldum 

usumda  ki  yerinde

03.02.2006-ant', 'dil  tutulmuş gözler  erdemliğinin derinlerinde sessizliğimin sesini arar oldum  usumda  ki  yerinde 03.02.2006-ant...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sessizlik-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜNYANıN EN GÜZEL KADINI', 'dunyanin-en-guzel-kadini-olgun-ekinci-ig7x9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '_____Hey! ! ! 

Doğuşu asırlar önce kutsanan kadın..

Kraliçe Amyitis''i kıskandırırken yüreğin,

Serinletirken BABİL**''in asma bahçelerini

Yedi harikaya yansıyor ışıltıların…

Milat''lar öncesinde renklerisin doğanın..

KEOPS''a** mimarisini sunan Mısır''da

Nil Nehrinin gizeminde, çoşkulu, esintili

Keşf edilmemiş misyoner rahibesin sen..

Geçmişte ve bugünde en yüksek, ışıltılı

Ve gelecekte evrene

Fenersin sen İSKENDERİYE''den,**

Dünya limanlarına  örnek olacak,

Pharos adasından dalga dalga yayılan..

Ve gülerdi yüz yıllık uykusunda 

Tanrıça ARTEMİS**, haykırırdı sana, Efes''ten

Bulutlara yükseldiği semadan; 

___ZEUS''a** dön yüzünü, Olimpos''a

___Zeus ikliminden bir adam

___Aynı paralelden bir deli

___Seni sevecek yüzyıllar sonra…

Gülerdin, inanarak, sabırla, hakkınca..

MAUSOLEUS**''un mezarından, Artemis anısına

RODOS**''a mumlar yakarım tütsüler eşliğinde

Ege denizi boyunca, Helios''a

Artemis yalancı çıkmasın değil

Asırlardır sevdiğim sana..diye….

Dünyanın en güzel kadınına

En güzel hüzün gözlüsüne dünyanın

Yedi harikasına bedel, hepsinden güzel

Sekizinci son harikaya…

30.01.2005 - Adana

**Onlar sevdamdan sonraki harikalar..', '_____Hey! ! !  Doğuşu asırlar önce kutsanan kadın.. Kraliçe Amyitis''i kıskandırırken yüreğin, Serinletirken BABİL**''in asma bahçelerini Yedi...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dunyanin-en-guzel-kadini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-hasan-ozcan-2v8n6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabahtan ümidi keser ya ufuk

Karanlık kollarla sarınca gece

Bir anne nuruna ağlar bin çocuk

O ışık gözlere varınca gece

İçimde yalnızlık yakar kederi

Denizi ürkütür acımın teri

Gönlümde çıbanlı en hassas yeri

Cellat körlüğüyle yarınca gece

Zorsa da yaşamak vazifemizken 

Geceler isyana çıkan bir izken

Ah ahh sevdiceğim bir de sensizken 

Nasıl yaşanacak ahh bunca gece

[email protected]', 'Sabahtan ümidi keser ya ufuk Karanlık kollarla sarınca gece Bir anne nuruna ağlar bin çocuk O ışık gözlere varınca gece İçimde yalnızlık yak...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özcan']::text[], 8.5, '{"poet":"Hasan Özcan","poet_slug":"hasan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizlik-337-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Konmamış Şiir', 'adi-konmamis-siir-hasan-ozcan-6xwnf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak aynalar kırılmış

Yıllar düşmüş üstüne

Tekerlek yoldan yılmış

Yolcu gelmez bugüne

Bu gece de yağmur var

İki serseri eksik

Hep ağlayacak kadar 

Maziye neler ektik

Biz serseri yoldaştık 

Can adayan hayale

Hüzünde Mecnun aştık

Baharda kaldı lale

Mecnunüstü sevmenin

Biz gönüllü kobayı

Yarla seyrettik diye

Gökten çalanlar ay''ı

Bu kervanda biz varız 

Gerisi vesaire

Her saniye yanarız

Adın çıkar şaire', 'Bak aynalar kırılmış Yıllar düşmüş üstüne Tekerlek yoldan yılmış Yolcu gelmez bugüne Bu gece de yağmur var İki serseri eksik Hep ağlayacak k...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özcan']::text[], 8.5, '{"poet":"Hasan Özcan","poet_slug":"hasan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adi-konmamis-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Veda', 'son-veda-birsen-ates-wlj44', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'giderken

bir buse çaldım dudaklarından

şimdi ağlıyor biliyorum

son bir bakış aldığım gözlerin

son busen kaldı aklımda

eriyorum düşüncelerimde ve

beni sımsıkı saran sıcaklığında.

vedaları sevmem ama

gitmeliyiz

yıpratmadan birbirimizi

biliyorum sana ait her şey

yerli yerinde duracak

sen benim tek aşkımsın

ve öyle kalacak

    03.02.06', 'giderken bir buse çaldım dudaklarından şimdi ağlıyor biliyorum son bir bakış aldığım gözlerin son busen kaldı aklımda eriyorum düşüncelerimd...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/son-veda-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savruk', 'savruk-nazan-i-zmirli-0gped', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'savruk

düşünceler

saçlarımın  tellerinde

aynalara   bakmak 

son  çare

ellerim uzanmıyor

nedensiz! 

cesaretim yok

sensizlikteki 

hüznüme 

şahit  etmeye

kırık bir ayna 

görmek istediğim 

en son şey

bu

savruk 

düzende...

03.02.2006-ant', 'savruk düşünceler saçlarımın  tellerinde aynalara   bakmak  son  çare ellerim uzanmıyor nedensiz!  cesaretim yok sensizlikteki  hüznüme  şah...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/savruk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli', 'deli-hasan-ozcan-fh0ji', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'A.Zeki ÖĞÜT''e

Gölgeler eteğin çekerler sudan

Gün soğur, gözlerde ışıklar söner

Ve melal ansızın çıkar pusudan

Dünyanın yerine bu gönül döner

Beni bulamazsın şimdi ararsan

İsrafil elinde sur''un sesiyim

Tezatlar kaçırda oldu da korsan 

Bilirim kendimin ben fidyesiyim

Peri kanadında yazılmış gelir 

Benim gönlüm için cinnet formülü

Bir gün bir mezardan çığlık yükselir 

Derler ki burada deli gömülü', 'A.Zeki ÖĞÜT''e Gölgeler eteğin çekerler sudan Gün soğur, gözlerde ışıklar söner Ve melal ansızın çıkar pusudan Dünyanın yerine bu gönül döner...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özcan']::text[], 8.5, '{"poet":"Hasan Özcan","poet_slug":"hasan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/deli-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıfır Elde Var Sıfır', 'sifir-elde-var-sifir-tulay-sustam-lqfg3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni kendime eklediğimde

günün birinde yeniden ben olacağımı bilseydim

ben, hiç bensiz kalır mıydım?', 'seni kendime eklediğimde günün birinde yeniden ben olacağımı bilseydim ben, hiç bensiz kalır mıydım?...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sifir-elde-var-sifir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Sevgimde', 'i-lk-sevgimde-omer-dalman-dvyab', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimseye verebileceğim aşk kalmadığında

kimsenin yanağını okşamaktan haz almadığımda

öpücükler benim için anlamını sonsuza dek yitirdiğinde

o çok çekici kadın tenleri

o hamur renkli, pürüzsüz, cilalı kadın bacakları

kırmızı dudakları, bordo ojeli tırnaklı pürüzsüz ayakları

çekiciliğini tam anlamıyla yitirdiğinde

o ilk sevgimde yeniden yüceldim.

Bir geri dönüş yaptım.

Dönüşüm muhteşem oldu! 

Eşsiz, el değmemiş, tam ‘bana özel’ buldum

bıraktığım yerden de ileride...

Ve yeni doğmuş bir bebekten daha saftı.

Düzineyle kadının tadına baktıysam da

ellerinde, ayaklarında, dudaklarında gezmiş olsam da

o ilk sevgimi kirletmedi, yok etmedi! 

Sadece yeni imkanlar sundu...

Kimseye verebileceğim hiçbir duygu kalmadığında,

o ilk sevgimde yeniden yüceldim.

Ve o ilk sevgiliye şükür! 

Bunca zaman

bütün keşiflerime rağmen

o ilk saflığıyla beni beklemiş...

(Ocak 2004)', 'Kimseye verebileceğim aşk kalmadığında kimsenin yanağını okşamaktan haz almadığımda öpücükler benim için anlamını sonsuza dek yitirdiğinde o...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ilk-sevgimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Özledim', 'cok-ozledim-huseyin-sonmez-oonsg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretini içiyorum yudum yudum

Sana geliyorum her gün adım adım 

Kalmadı artık şu dünyada tadım

Gel artık yavrum seni çok özledim.

Dayanmaz oldu şu ana yüreğim

Ne elim tutuyor ne de bileğim

Ansızın gideceğini nerden bileyim

Gel artık yavrum seni çok özledim.

Her günüm azap,her günüm hüzün

Tadı yok artık ne baharın ne güzün

Sen benim her şeyimdin,can iki gözüm

Gel artık yavrum seni çok özledim.

Sen bizimlesin duyarsın bizi

Her tarafta senin hatıranın izi

Yüreğimin içinde dinmedi sızı

Gel artık yavrum seni çok özledim.

                                        

                                   (Kamer Anne''den Server''e)', 'Hasretini içiyorum yudum yudum Sana geliyorum her gün adım adım  Kalmadı artık şu dünyada tadım Gel artık yavrum seni çok özledim. Dayanmaz ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cok-ozledim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geliyorum', 'sana-geliyorum-asude-gediz-a6gby', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kestim.Yeminlerim lime lime

Fırlattım esaretimi. Dinle! ! 

sığmıyor sözlerim kelimelere

vermek için can suyu senli günlere

Sana geliyorum

Saçlarımda bahar, tenimde gül

yüreğim volkan, nefesim sümbül

avucumda minicik buselerimle 

aç kollarını sana geliyorum

Bütün hücrelerimde tatlı bir nağme

uzun..gizemli... şık bir gece

bütün rafine oyunlarım elimde 

Bekle...

Sana geliyorum

Seni Seviyorum', 'Kestim.Yeminlerim lime lime Fırlattım esaretimi. Dinle! !  sığmıyor sözlerim kelimelere vermek için can suyu senli günlere Sana geliyorum Sa...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sana-geliyorum-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu', 'suclu-hasan-ozcan-2tdcr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlıktan yontulmuş 

Bir kadın heykel gibi

Hüzün kaidesinde

Yansıdı macerası 

Sabit bakışlarından

Yetim oldu insanlık

Dönüp bakmadı emanetçileri

Suçları merhameti de

Katletti belli

Hani yardı bacıydı 

Anaydı kadınlar

Garipliği utandı

Çektiğimiz sevdalar yollarında

Döktüğümüz yaşlar

Ağladı halimize

Yarasalar geçti uzaktan

Alnında karalar kadının

Alnımıza layık

Sen anasın ey kadın

Yarsın bacısın

Bize kimler acısın

Yalnızlıktan yontulmuş 

Bir kadın heykel gibi 

Hüzün kaidesinde

[email protected]', 'Yalnızlıktan yontulmuş  Bir kadın heykel gibi Hüzün kaidesinde Yansıdı macerası  Sabit bakışlarından Yetim oldu insanlık Dönüp bakmadı emane...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özcan']::text[], 8.5, '{"poet":"Hasan Özcan","poet_slug":"hasan-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/suclu-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbül ve Baykuş', 'bulbul-ve-baykus-gul-yazganarikan-dljtu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eskiden başka güzeldi kahve,

Şarap daha kırmızıydı

Güneş böyle yapışmazdı üstüme

Kuşların sesini işitirdim...

Çiçeklere toprak olurdu bağrım...

Ben miyim değişen Tadı mı değişti hayatın? 

Bu kadar mı insafsız olur adına aşk dediğin,

Aşk şöyle dursun merhametin yok senin,

Gözyaşıma karışıp aktın gittin içimden

Ne istersin içtiğim bir yudumluk kahveden

Kuşları da susturmuşsun işte,

Sabah aldım haberi pencerede baykuştan

“Sesleri yok nicedir haber var mı kuşlardan”

Çattı kaşlarını “gittiler” dedi...

Ne de olsa onlar aşk şarkısı söylerdi...

Hayat kopmuş dalından gidişinle...

Belli ki yazık ölmüşüm ben de...

Yaşanacak yer gerek bana şimdi seninle...

Uzak olsun senden

Bir haberin gelir de yine öldürürsün sen...

Baykuş yeter bana, Bülbül seninle kalsın...

Sevdiğin her kadında beni anacaksın...

Bülbül''ün baykuşa döndüğü yerde

Ağlayacaksın...', 'Eskiden başka güzeldi kahve, Şarap daha kırmızıydı Güneş böyle yapışmazdı üstüme Kuşların sesini işitirdim... Çiçeklere toprak olurdu bağrım...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bulbul-ve-baykus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BiR KADIN / BİR ADAM / BİR SEVDA', 'bir-kadin-bi-r-adam-bi-r-sevda-olgun-ekinci-fotpu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '_____Kadın,

Yüklendiği, sevdalarıyla dolu

Öznesi yüreğinde saklı

Gözlerinde sıcağının  şefkati

Emekçi annenin meleksi hüznü..

Varoşları buz tutmuş kenti, gök yüzünden

İnci kanatları, merhametiyle saran, sarmalayan..

_____Adam,

Saklı kentleri, yaşanmamış sevdaları

Gözleri lacivert hareli

Çocukluğunda büyük adam

Büyüdü oysa, 

Küçüklüğünü özleyen ve büyüyemeyen

Deli mi? kendi de bilmeyen…

_____Kadın,

Onuru sevdasında anlamlı

İçlerine akıtmış hüzünlerini, ırmak ırmak

Isıtmak için nefer şimdi ve her zaman

O deli adam ve deli çocuğa, hasretinde..

_____Adam,

Susamış, saklı kentlerin sevdalarına

İçmek yudum yudum, kana kana 

Doymak derdinde, açlığından,

Hüzünlü bir kadının

Öznesini, hüznünü, merhametini..

Sarılırken şefkatine,

Çıkarken geçmişine onurla, sahiplenirken,

Onu ve geleceğini ve payına düşeni..

Tüm bedellerini ödemeye hazır

Ve diyetlerini dün geceden ödemiş bu aşkın..

_____Bir kadın ki…seviyor,

_____Bir adam ki…tapıyor,

Kim engel ki! bu sevdaya

Kim olabilir ki bu sevdaya engel

30.01.2005 - Adana', '_____Kadın, Yüklendiği, sevdalarıyla dolu Öznesi yüreğinde saklı Gözlerinde sıcağının  şefkati Emekçi annenin meleksi hüznü.. Varoşları buz ...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-kadin-bir-adam-bir-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana', 'ana-ramazan-sozeri-g3des', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ana

Coktandır ki görmedim yüzünü

Beni öldürecek bu halet ana

Halimi gelenden gidenden degil

Sıcak kollarında sual et ana! 

Ana gurbetteyim el ocagında 

Sevgin yüregimin ta ocagında 

Beni özler isen ya kucagında 

Yahut göz yasında hayal et ana! 

Rüzgarım bu gurbet illerde esen 

Bilsen sana nasıl hasretim bilsen 

Gönlümde muhabet sancagına sen! 

Klem kaslarını hilal et ana 

Ayrılıkmıs alın yazım kaderim

Dönmeye bir ümit var allah kerim 

Belki buralarda ölür giderim

Ne olur hakkını helal et anam!', 'Ana Coktandır ki görmedim yüzünü Beni öldürecek bu halet ana Halimi gelenden gidenden degil Sıcak kollarında sual et ana!  Ana gurbetteyim e...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Sözeri']::text[], 8.5, '{"poet":"Ramazan Sözeri","poet_slug":"ramazan-sozeri","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ana-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınların Etrafında', 'kadinlarin-etrafinda-omer-dalman-8ie3v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yoksa

kadın’a verdiğim değer

günden güne artıyor mu? 

Beni bile bir gün hiçe sayacak

bitirecek, tüketecek

değersiz kılacak

2 dakikada harcayacak kadar

yüceliyor mu? ! 

En değerli etlerle beslenen bir canavar gibi

gün gelip

beni, yani sahibini yiyecek kadar

acımasızca büyüyor mu? ! 

”Bu ne güzellik! ? ” dediğim her an

sonradan sırtıma yüklenip

beni altında ezecek kadar acımasız

bir borca mı giriyorum? ! 

Birine bu kadar iltifat etmek

onu bu kadar yüceltmek

kendimi arkadan mı vurmak acaba? ..

Yoksa kadınları bu kadar beğenmekle

hata mı ettim? 

Sakın! 

ama sakın bana

’Dünya kadınların etrafında dönmüyor’ deme!', 'Yoksa kadın’a verdiğim değer günden güne artıyor mu?  Beni bile bir gün hiçe sayacak bitirecek, tüketecek değersiz kılacak 2 dakikada harcay...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kadinlarin-etrafinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avukat Ve Oğlu', 'avukat-ve-oglu-mehmet-akif-tiryaki-60moj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Filmin en can alıcı noktasında

Kurtlar çocuğa saldırdı.

Çocuk yerden uzunca bir tahta parçası aldı,

Başının üstüne tuttu kaldırdı,

Kurtlar geri çekildi, saldıramadı.

İşte o anda avukat Turan Baba ağladı,

Filmi oğlu ile seyrediyordu,

Hayatta devamlı böyle ol oğlum diyordu.

Olduğundan farklı göstereceksin

Düşmana karşı kendini,

Asla ezdirmeyeceksin gururunu ve aileni.', 'Filmin en can alıcı noktasında Kurtlar çocuğa saldırdı. Çocuk yerden uzunca bir tahta parçası aldı, Başının üstüne tuttu kaldırdı, Kurtlar g...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/avukat-ve-oglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşında dimdik!', 'karsinda-dimdik-omer-dalman-x1q79', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çağlarız biz coşarız

yine yollarda

yağmurda, çamurda

karda kışta koşarız

Paçalarımız ıslansa da

her zamankinden daha fazla umutlanır

karşında dimdik dikiliriz biz! 

Dilediğini çevir arkamızdan

kullan bizi

konuş arkamızdan

suni gündemler yarat her ortamda! 

bitmeyiz, tükenmeyiz

bölünürüz, arada gerileriz belki ama

çoğalırız biz! 

Ayağımız sağlam basar yere

üretiriz, yaparız, yazarız, çizeriz biz

havadan, sudan yaşamayız! 

Paçalarımıza bulaşsan da

paltolonumuzu, donumuzu, ceketimizi

gömleğimizi alsan da

çağlarız biz çoğalırız

yine yollarda

şehirin, dağın, köyün her yanında

karşında dimdik dikiliriz biz! 

(Şubat 2006)', 'Çağlarız biz coşarız yine yollarda yağmurda, çamurda karda kışta koşarız Paçalarımız ıslansa da her zamankinden daha fazla umutlanır karşınd...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/karsinda-dimdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece kendinlesin', 'sadece-kendinlesin-omer-dalman-k0h1s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önceki gece

En büyük assolistle de birlikte olsak

parti başkanıyla da yemek yesek

İngiltere Kralı’yla da yatsak

veya

Dünya’nın en büyük adamıyla da görüşsek

bugün yine tamamen yalnız

kendimizle kalacağız...

Kendi hesaplarımızı gözden geçireceğiz uyku öncesi

ve

kendi soluğumuzla başbaşa uyuyacağız

kendi tabağımızı kaşıklayacağız

kendi faturalarımıza kölelik edeceğiz

kendi yalanlarımızın kanburunu yükleneceğiz.

Yalan atma bana! 

Herkesinki kendine! 

Yediği kendine

aldığı kendine

dinlediği kendine

kazandığı kendine

ruhu kendine

hesabı kendine

ahireti kendine...

Önceki gece kiminle ne yaparsan yap

bugün sadece kendinlesin...

(07.02.2005)', 'Önceki gece En büyük assolistle de birlikte olsak parti başkanıyla da yemek yesek İngiltere Kralı’yla da yatsak veya Dünya’nın en büyük adam...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sadece-kendinlesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basamak', 'basamak-i-rfan-tansel-turhan-iq7eh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç kimseyi değil kendini yaşamak

Yalnız kaldığım anlarda tarifsiz  ivmeler

Talihsiz düşükler, kanamalardı hislerim

Ama sen,  hiç benim kadar orospu 

                            hissettin mi kendini? 

Geç kaldığında kaçırdığın müşterilerin

                                     oldu mu senin? 

Yitirilen sesler yankılandı mı hiç 

                                         kulağında? 

Yaşamak sevmeden 

Yaşamak doymadan

Aç ve  saldırarak görmemişcesine

Ve yaşamak  dorukları alçak kılarak

Ya da, sevginin ardına saklanarak

Beklemek mi satış anını? 

Yaşamına hep sponsor mu 

                                      aradın sen? 

Beyaz atlı finansör ve rapunzel

                                  masalı mı bu? 

Sen hiç merdiven boşluğunda

Komşunun kızına tecavüz ediyormuş

                 gibi hissettin mi kendini? 

Benim kadar yenilmişliğin oldu mu senin

Yok pahasına, pazarlıksız bir o kadar

                                         haraç mezat

Her kuruşuna küfrederek

Her kelimesine tiskinerek 

                                         satılmışlığın...!', 'Hiç kimseyi değil kendini yaşamak Yalnız kaldığım anlarda tarifsiz  ivmeler Talihsiz düşükler, kanamalardı hislerim Ama sen,  hiç benim kada...', ARRAY['Türk Edebiyatı','Şiir','İrfan Tansel Turhan']::text[], 8.5, '{"poet":"İrfan Tansel Turhan","poet_slug":"i-rfan-tansel-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/basamak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakarya’m şahitsin tarihteki kanlı da mücadeleye', 'sakarya-m-sahitsin-tarihteki-kanli-da-mucadeleye-halil-colak-c3zss', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sakarya’m şahitsin tarihteki kanlı da mücadeleye 

Senin kıyılarında Türk evlatları gömüldü topraklara

Mehmetlerimin ruhları da gitti vaat edilen cennetlere

Sen bilirsin Sakarya’m Türk aşıktır her zaman istiklale

Şimdi  yorgunsun ağır akıyorsun ağırdır tarihi yükün

Anlat akarken gaflettekilere tarihi mücadeleyi bütün

Ne kanlı kahpece savaştı kardeşim bu Türk milleti için

Hür yaşamış milletimize gelecek ve hürriyeti seçin

Bu mücadeleye bir daha rastlanmaz  kitabelere geçin 

Halil Çolak 3.2.2006 Ankara', 'Sakarya’m şahitsin tarihteki kanlı da mücadeleye  Senin kıyılarında Türk evlatları gömüldü topraklara Mehmetlerimin ruhları da gitti vaat ed...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sakarya-m-sahitsin-tarihteki-kanli-da-mucadeleye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namus Gibi', 'namus-gibi-mehmet-yusuflar-hz1eq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üstüme kasvet çöktü, kabus gibi...

Karantinaya alındım, fanus gibi.

Dilbere dil uzatamam gayri...

İkram-ı buse: belki, namus gibi', 'Üstüme kasvet çöktü, kabus gibi... Karantinaya alındım, fanus gibi. Dilbere dil uzatamam gayri... İkram-ı buse: belki, namus gibi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yusuflar']::text[], 8.5, '{"poet":"Mehmet Yusuflar","poet_slug":"mehmet-yusuflar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/namus-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-orhan-yildiz-a2pmo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani senin bir tanendim

Hani…

Sen diyordun,

Seni diyordun,

Bütün bunları

Unutmak için mi söyledin

Yalancı', 'Hani senin bir tanendim Hani… Sen diyordun, Seni diyordun, Bütün bunları Unutmak için mi söyledin Yalancı...', ARRAY['Türk Edebiyatı','Şiir','Orhan Yıldız']::text[], 8.5, '{"poet":"Orhan Yıldız","poet_slug":"orhan-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hani-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büşra Meleğim...', 'busra-melegim-i-brahim-ethem-bingul-nlqxm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Reyhan kokunla

Büşra ile geldin, güldün meleğim

Bize mutluluk getirdin güzel bebeğim...

Gamzenin nakışlarında sakladığın gizler

Tebessümünü soldurmasın kem sözler

Seni ağlatanı ağlatırım bunu bileler...

Filizler verip çoğaldığına

Büyük dedenin şiirini oku bir daha

Seni de torunların erdirsin böyle mutluluğa...

www.iebingul.com', 'Reyhan kokunla Büşra ile geldin, güldün meleğim Bize mutluluk getirdin güzel bebeğim... Gamzenin nakışlarında sakladığın gizler Tebessümünü ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/busra-melegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuyudaki Yusuf’un Terkedilmişliği...', 'kuyudaki-yusuf-un-terkedilmisligi-dilan-tan-jq62k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmur damlasında gizli hüznüm, ben ağladıkça gözyaşlarım yağmur olup gelecek sana

Oradan da sonsuzluğa karışacak...

Saklandım yalancı sevdaların arka sokaklarında,

Saklambaç oynadım hep sobelenen bendim bu yalancı dünyada 

Tek gerçeğimdin benim ama senden de sakladım...

Suskun diyarlarda yolumu bulamadım dipsiz kuyularda uyudum,

Kuyudaki Yusuf’un yalnızlığı sana olan sevdamın cesareti,

Aşk cesaretti ben hiçbir zaman cesur olamadım.

Kâbus gecelerde sığındım senin yüreğinin gölgesinde üşüdüm,

Ruhumda kırgın yangınlar, küskün ızdıraplar, yandım küle döndüm 

Sensizlikte ölüm soğuklarında sırça heykeller gibi kırıldım buza döndüm 

Sigaramın dumanı kadar yakındın bana savruldum hiçe döndüm... 

Kuyudaki Yusuf’un yalnızlığı sana olan sevdamın cesareti,

Aşk cesaretti ben hiçbir zaman cesur olamadım.

Kuyudaki Yusuf’un terkedilmişliği sana olan sevdamın sessizliği kimsesizliği...', 'Yağmur damlasında gizli hüznüm, ben ağladıkça gözyaşlarım yağmur olup gelecek sana Oradan da sonsuzluğa karışacak... Saklandım yalancı sevda...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kuyudaki-yusuf-un-terkedilmisligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen/Sizlik', 'sen-sizlik-bahri-yildirim-dgw7v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki elim,

İki gözüm,

İki yüreğim vardı

Birisi sen için çarpan

Sana dokunurken birisi

Birisi sana bakan

Biliyorsun bu nedenle

Sana bir tanem dedim

Ömrümün ilkbaharısın

O günden bu güne

Son goncası,

Son demisin ömrümün

Zamanlarıma tutsak kalmış gülüşün

Gülüşümün,senli anlamı,bu gülüş bilirsin

En iyi sen bilirsin hem de

Şah damarısın  varlığımın

Duydumki:

Şimdiki zamanımı çalacakmış sensizlik

Sana feda olsun,kabülüm

Helal olsun sana 

Bu zamansızlık ortamı

Nasılsa, sen de varsın  içinde

Sensizlik dolu zamanı 

Belliki  en iyi sen anlarsın

Sen anlarsın da,ben anlatamam

Halâ,Sensizliğe  şiirler yazarken...', 'İki elim, İki gözüm, İki yüreğim vardı Birisi sen için çarpan Sana dokunurken birisi Birisi sana bakan Biliyorsun bu nedenle Sana bir tanem ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-sizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeytin Dalı İhtilali', 'zeytin-dali-i-htilali-tahsin-ozmen-76xcu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökyüzü bazen ağır bir dumanla örtülür, sanki kara bulutlar kurşun dökülmüş birer zırhmış gibi. Ama yine de ararsın o bir karış maviyi; çünkü duymak istersin: Bu devasa gürültüde adaletin kalbi hala atıyor mu?

İşte böyle bir sancıyla uyandım bugün. Bir askerin tüfeğini bırakıp bir çiçeğe su verişindeki o saklı iyiliğe aşık oldum önce. Sonra bir annenin, yıkıntılar arasında evladının oyuncağına sarılan o sonsuz direncine. Birinin merhametini aldım heybeme, diğerinin zulme karşı dimdik duran o mağrur öfkesini. Ruhum bugün bir meydan kadar kalabalık, bir o kadar da yaralı.

Işıktı barış; karanlıktı hırs; ve insanlık, o her an kırılmaya hazır ince camdan kule. İçinde çokça kan vardı maalesef ama asıl harcı vicdandı, adaletti. Önce gözlerimi kör etti nefret, sonra hayallerim yandı. Sonra yandı barışın sancağı. Aşık oldum doğruluğa. Kaybolmuş masumiyete, hakkaniyete.

Sağıma baktım zulüm, hırs, yıkım, kaos. Harabelerden sarktım, mülteci teknelerinden ufka gözlerimi bağladım, soluma bakındım. Uzun ve kanlı bir destan oldu tarihim. 

Elime bir zeytin dalı aldım; çeliği delercesine kazıdım umudu dünyanın taş kalbine. Bir cepheyi kapattım, bir bahçe açtım. Göç ettim nefretlerden. Kapattım perdeyi, yeni bir sayfa daha açtım. Feth ettim kendi vicdanımı. Kapattım perdeyi, yeni bir nefes açtım. Bir adalet çığlığı ile yıktım bütün o muktedir kulelerini. Kapattım perdeyi. Yeni bir dünya açtım sonra. Yeni bir mana, bir daha.

Mevsim kıştı!

Ben hep üşüdüm. Sürükledim vicdanımı, gözlerim zulüm yorgunu. Ellerim, baruta bulaşmış acılara müptela. Vatansızları düşündüm. Evsizleri, anasızları, babasızları. Ben hep düşündüm. Biteviye düşündüm. Kahrolarak, yana yakıla. Susuz, havasız ve fakat ateşli. İyiliği güzelliği düşündüm.

Gündüz yarılarında, geceleyin sığınaklarda akan gizli gözyaşlarında, örneğin öğleyin, mesela ikindi vakitlerinde çaresizlikten bitap düşmüş insanları düşündüm. Seyredemedim zulmü. İnsanlığın suskunluğuna üzüldüm. Yenilgilerim değil, dünyanın vahşeti geldi üstüme; günahlar birer çelik yelek oldu sırtımızda. Kısa vadeli çıkarlara eğdim kalbimi. Kapandıkça merhamet kapıları, vuruldukça kuşlar uçurtmaların yanında -sözgelimi bir yetimin tozluysa yüzü, yaralıysa düşleri- ve demetlendikçe silahlar bir çıkar pazarında. 

Birdenbire, kabil''den habil''e giden o kadim kavgayı düşündüm. Ve karanlığın aydınlıkla, kötülüğün iyilikle hep bir derdi olduğunu. Dünyanın insanın eliyle de can çekiştiğini gördüm.

Sonra sustum.

Yıkık duvar diplerinde çokça. Barikat yalnızlıklarında, şehir altı sığınaklarında. Tank izlerinin yanında, füze çukurlarında, çatlamış kaldırımlarda. Sustum. Yıllarca, aylarca, haftalarca yuttum hıçkırığımı. Sadece seyrettim. "Alışmak zorundayız"lar giyindim üzerime. "Dünya böyle"lerle taradım ruhumu. Yüzüme "elimizden ne gelir ki"ler sürdüm. Zamanla her şey unutulur! Her zaman iyiler kazanamaz diye bir şey yok. Kötüler de kaybeder. Yenilmek de davanın şanından. İçimden hep dedim; bu kötülüğe bu zulme şahit olmaktansa, kahrından öl. Kahrından öl. Kahrından öl.

Sonra yoruldum.

Bir karınca, bir toprak solucanı gibi. Bir oyuk, bir sığınak bulup içine vicdanımı sığdırıp kendimi öylece saklayabilmek için. Kaçtım bütün o sahte kalabalıklardan. Kuytu köşeler aradım; kuytu köşelerde bir zeytin çekirdeği, bir güvercin kanadı aradım. Sonunda bir "Erdeme oydum" yüreğimi.

Ellerini nereye koyacağını bilmeyen bir çaresiz adama döndüm. Ellerimi, dilsiz dualarıma verip, yonttum adaletin heykelini. Ve en büyük yalnızlığın, bu vahşetin içinde merhametli kalmak olduğunu. Öğrendim. İnsanın kendi türünde boğulduğunu bir türlü göğe anlatamadığını da. Sustum. Tek başına bir ordu olmuş ruhumla, vicdanımı dinledikçe sustum. Bu yorgun dünyanın hal-i pür melalini düşündükçe. Sustum. Savaş yıkıntılarında yankılandı suskunluğum.

Bir gizde parladı, iyilik. Bir sır gibi saklandım insanlığıma. Titredi gökyüzü, bir infilak gibi. Yağmurlar yağdı. Dünyanın kanını temizlemek için. Yağmurlar, berrak yağdı. Bir orman yangınına ağlayan karınca gibi ağladım. Bunu gören   bezirgânbaşı ve saldırgan kovboy güçsüz ve yalnız olduğumu sandı. Sessizce bağırdım. Anlatamadım yahut anlamadılar binlerce yıllık varoluşu. (Ki en büyük yalnızlık, bu yangında bir damla su taşırken yalnız kalmaktı.)

Zaman!

Bir çemberin, tarihin, çapıydı zaman. Daha büyük bir kardeşlik dairesi çizdim. Daha da büyük. Yarıldı o dar çap. Doğdu insalık.

İyilik!

Bir anahtardı iyilik, paslı vicdanları açan, "füzeler" arasında. Açtım. İçeride hala atan bir kalp. Işık hızı ile bir saniye. Bir dakika, bir saat. Döndüm. Gün oldu. Adalet geldi: müşfik, vakur. Hafta oldu, ay oldu, yıl oldu. Kar dindi, güneş ısıttı, sonra bahar geldi. Barış geldi.

Hayal görmüş olmalıydım.

Çıldıracaktım. Bu zulme son verecek bir delilik yapmaya hazırdım. Düşüyordum. Uykusuz rüyalar görüyordum. Rüyalarımda tüfeklerin namlusundan çiçekler fışkırıyordu. Boşlukta duruyordu dünya. Çocuklar sadece oyun parklarında düşüyordu. Masumlar yaşıyordu. Ellerim titriyordu. Umutla. Kalbim barış ilan edilmiş bir meydandaki binlerce güvercinin kanat çırpışı kadar hızlı çarpıyordu. Hızla bir aydınlığa düşüyordum. Bağırıyordum. Zafer çığlıklarını herkes duyuyordu. Olan oluyordu. Muazzam bir sekinetle. Ve zulmü seyretmekten artık vazgeçmiştim.

Yapraklarını barutla dökmüş bir zeytin ağacı gibi, bir meşe gibi, bir çınar gibi direndim. Düşündüm. Mukaddes emanet gibi bir "Barış" lazımdı bize. Bir Barış. Yara sarar gibi sardım mukaddes barışı insanlığıma. Düşündüm. Tatlı bir esintiydi yaşamak. İlk defa huzur duydum. Berrak bir mavi içindeydi gök. Ellerimde bütün nehirlerin suyu.

Derken toprak. Evet onu düşündüm. Doğayı düşündüm. Aşık olduğum. Bizi her şeye rağmen besleyen toprağı. Savaşlardan sonra yeniden yeşeren toprağı. Zulümden sonra sinesinde masumları saklayan toprağı. Kandan sonra yağmurla yıkanan toprağı.

Ve bir gece. Aydınlık bir gece. Tohum gibi her güzel niyetin içinde olduğu bir gece. Yerkabuğu ısındı. İnsanlık kıpırdadı. Doğruldu. Bir şafak vakti gibi göz bebeklerim. Barışa doğru büyüdü. Vicdan, tam zamanında "ebedi huzuru" müjdeledi. İyilik yeşerdi. Kalpte niyetten. Yerde sevgiden hayat. Çiçek kokularıyla birlikte barış ve özgürlük kokuları da yeryüzüne salındı.

(Sessizlik. Hakikat içerir. Dinginlik, bir duruş. Kötülüğün sesini kısmak gibi. İyilik ise o düğmeyi sonsuza dek açmak. Silahın sustuğu, toprağın barut kokusundan arındığı o büyük suskuyla bağıran. Başka hiçbir hakikatin olmadığını. Gördüm.)

İyilik, gürültülü bir nehir gibi değil, toprağın derinliklerine sızan mahcup bir yağmur gibi büyütür hayatı; kötülük yakıp yıkan bir kasırga olsa da, iyilik o kasırganın dindiği yerde filizlenen ilk sessiz sevinçtir.

Zulüm, kör bir balta gibi dallarımıza inse de bilmez ki; iyilik budandıkça gürleşen, taşlandıkça şifa dağıtan ve en sonunda kendi gölgesinde zalimi bile ağırlayacak kadar geniş bir yürektir. İyiliğin direnci, geceyi yırtan cılız bir kibrit alevi değil; ufkun ardında pusuda bekleyen ve her şafağa sadakatle söz vermiş o mağrur güneşin ta kendisidir.

Zeytin dalı, göğsün kafesinde çırpınan o kadim inadın dilsiz alfabesi; kayanın kalbini sabırla oyan, fırtınanın ıslığına kendi yeşil şarkısıyla cevap veren direniş. 

Bir zeytin tohumunu düşündüm. Toprağın altında karanlıkta, yaşam enerjisiyle filizlenip ışığa ulaşmaya çalışan. Bu biyolojik mucizeyi. Üzerine çöken tonlarca karanlığı bir ışık huzmesi için hiçe sayan; ruhun maddeye karşı başlattığı en zarif ihtilali, varoluşsal direnci düşündüm.

Ve dudaklarımdan bir inci misali döküldü o güzel hakikat:

Zeytin Dalı!

Zeytin Dalı!

.

Evet bütün mesele:

-Zeytin dalının inadında olabilmek...!-

Tüm cevr-ü cefaya, savaşlara, kaosa rağmen. Sonunda zulmün biteceğini, zalimlerin yenileceğini, barışın yine geleceğini, adalet meşalesinin sönmeyeceğini bilmek...!

Düşünmek Yaşamın Pasını Silmektir, Karina Yayınevi, Ank,2018.', 'Gökyüzü bazen ağır bir dumanla örtülür, sanki kara bulutlar kurşun dökülmüş birer zırhmış gibi. Ama yine de ararsın o bir karış maviyi; çünk...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Özmen']::text[], 8.5, '{"poet":"Tahsin Özmen","poet_slug":"tahsin-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/her-cocuk-bir-tomurcuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yüreğimde gizlisin...', 'sen-yuregimde-gizlisin-halide-selcan-karagul-5tcjn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen Yüreğimde Gizlisin... 

Bir gün hiç beklemediğim bir anda 

Sessizce çıkmıştın karşıma 

Seni sevmek için hiç bir neden aramadan 

Seni ilk görüşde sevmiştim 

Ahh o gözlerinin mavisi 

Çakmak çakmak bakışın 

Beni benden almıştı... 

Gözlerinin o meşhum derinliğiyle 

Bakarken gözlerimin içine 

Sevgin yüreğime akmıştı... 

Her ''Sevgililer gününde'' 

Senden masum sevgime 

Karşılık beklemedim... 

Ahh! .. Bir bilseydin sevgili... 

''karşılıksızdı sana olan tüm sevgim'' 

Şunu bilki sevgili 

Aradan bir ömür geçsede 

Sevgin hala yüreğimde 

Sen yüreğimde gizlisin... 

03.02.2006', 'Sen Yüreğimde Gizlisin...  Bir gün hiç beklemediğim bir anda  Sessizce çıkmıştın karşıma  Seni sevmek için hiç bir neden aramadan  Seni ilk ...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-yuregimde-gizlisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimde bir damlasın', 'gozlerimde-bir-damlasin-selcen-boyar-6786q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu gözler hep seni gözler

belki bir gün gelir diye

bilmezlerki boşa bekler

giden sevgililer

daha dönmezler

bu gözlerde yaş olsan da

akmaya gelemezsin

öpülmeyen dudaklardan

öpmeye gelemezsin

uzaklardasın  diyarlardasın,

sevmeye gelemezsin

gözlerimde bir damlasın 

sen akıp gidemezsin', 'bu gözler hep seni gözler belki bir gün gelir diye bilmezlerki boşa bekler giden sevgililer daha dönmezler bu gözlerde yaş olsan da akmaya g...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerimde-bir-damlasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Aşkıma', 'can-askima-sidika-seylan-76baf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'E skiyi hatırlama

R ahatın bozulur

G ünler senindir

Ü mütle gelecektir

N iyetin ne isen

B ahtın o dur

E lbet gelecek senindir

K aybın kazancındır

Ş enlesin yüreğin

E lbet mutluluk senindir

N eşen mutluluğumdur', 'E skiyi hatırlama R ahatın bozulur G ünler senindir Ü mütle gelecektir N iyetin ne isen B ahtın o dur E lbet gelecek senindir K aybın kazanc...', ARRAY['Türk Edebiyatı','Şiir','Sıdıka Seylan']::text[], 8.5, '{"poet":"Sıdıka Seylan","poet_slug":"sidika-seylan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/can-askima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gözün Diğerinden Farkı', 'bir-gozun-digerinden-farki-tulay-sustam-pi43k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir delikten bakıldığında, dip gözükseydi

dibe baktığımda deliği görmezdim', 'bir delikten bakıldığında, dip gözükseydi dibe baktığımda deliği görmezdim...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bir-gozun-digerinden-farki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiyeroglif', 'hiyeroglif-asima-azra-x7hxd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ateşini yolla bana

hani yanmam dedimse buz da değilim

ama çıra hiç değil…

Mümkün değil göremeyeceksin

dilime tünemiş isminin

duvarlara yazıldığını

ve hiçbir zaman bilemeyeceksin

göz ardı ettiğin şiirin

korneana kazındığını! ! ! 

Şubat/1', 'Ateşini yolla bana hani yanmam dedimse buz da değilim ama çıra hiç değil… Mümkün değil göremeyeceksin dilime tünemiş isminin duvarlara yazıl...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hiyeroglif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydın Adam, Aydın Kadın', 'aydin-adam-aydin-kadin-halay-sadi-f18nz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aydın kadın

Kadın olmaktan öte

Erkek de olmaya çalıştı

Her hal ve şartta

Kendine,evine,çocuğuna

Yetebilmeyi öğrendi

Özetle, yeni yükler aldı.

Aydın erkek,

Gençlik söylemlerinin aksine

Sımsıkı sarıldı törelere

Sunulan özgürlüğü kullandı

Tanınan rahatlığı kullandı

Kendisini daha sıkı savundu

Usturuplu kılıflar uydurdu

Bir arpa boyu yol alamadan

Rahatına baktı..

Aydın kadın, erkeğinin

Yanına yoldaş, arkasında destek

Aydın adam, kadınının

Yanına yoldaş gibi

Aslen ayağına köstek

Aydın olmak erkeğe değil

Kadına ait bir gerçek…

11.12.2005', 'Aydın kadın Kadın olmaktan öte Erkek de olmaya çalıştı Her hal ve şartta Kendine,evine,çocuğuna Yetebilmeyi öğrendi Özetle, yeni yükler aldı...', ARRAY['Türk Edebiyatı','Şiir','Halay Sadi']::text[], 8.5, '{"poet":"Halay Sadi","poet_slug":"halay-sadi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aydin-adam-aydin-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğumun evleri', 'cocuklugumun-evleri-elazigli-mustafa-kaya-rb7u1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sanki,

trenlerin kalabalığı

çocukluğumun evleri.

hep rüzgar çıkacakmış

gibi.

iç içe ve 

omuz omuza 

aynı türküleri okudu

dudaklarımız

birlikte yaşamışız.

çocukluk arkadaşlarım

kanı çekilmiş çehreli.

çaresizlik

yokluk

dünyadan habersizlik 

aileleri.

yeryüzünün,

hüzün kalbi evler 

evlerimiz.

bir yalnızlık çemberidir

ezanlarla uyanırdık

yine ezanlarla yaşardık

gün boyu geçmez

canlılık..

sofralara geldiğimiz

akşamlar ,

sokakları tenhaydı

evlerin.

güneş devrilir devrilmez.

hiçbir ayna 

bizi 

mutlu gösteremedi.

oyunlarımız kaldı sadece

sokakları taş döşeli 

evlerin önünde.

yağmurlara çivilendiğimiz

günlerdi

sevinçlerimiz.

ve bayramlar

kandil gecelerimiz

ve,

tok kaldığımız düğünler.

oynar durur hala içimde

çocukluğum.

dar sokakları taşlı

birbirine yaslı evler

toz-topraklı çocuklar

arasında

gökyüzü kadar ses içinde

kalmışlığım.

işte,

şehir biçse de 

tüm geçmişi.

değiştirse de 

yaşadığım mahalleyi

değişmeyecek ben de

çocukluğumun evleri..

Mustafa kaya

03.02.2006 / istanbul', 'sanki, trenlerin kalabalığı çocukluğumun evleri. hep rüzgar çıkacakmış gibi. iç içe ve  omuz omuza  aynı türküleri okudu dudaklarımız birlik...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/cocuklugumun-evleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın Toprak, Deniz Erkek Midir?', 'kadin-toprak-deniz-erkek-midir-halay-sadi-s1i5b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deniz erkektir alır-verir

Soluğu-sesi heybetlidir

Hoyrat ve öfkelidir

Deniz kadın gibidir denir ya 

Doğru değildir.

Toprak dişidir, doğurur

Demiş bir yazarımız*

Denize siz kafa yorun

Toprağı düşündüm ben,

Toprak dişidir hakkaten

Doğurur,üretir,biri bin eder

Durağandır, sabırlıdır,kararlıdır

Önemini fark ettirmez,mütevazidir

Ne ekersen onu biçersin

Özünü beslersen iyisini alırsın

Verdiğin emek sana yansır

Aldığı kadarını depo eder

İhtiyaç halinde kullanır

Aldığını kendine saklamaz

Sonuna kadar fedakardır

Toprak,

Hayat onu yamaçta bırakmışsa,

Koşullara direnememişse

Tozu dumana katarak ayrılır

Tutunacak dal-kök yoksa

Deprem yaşarsa yerinden ayrılır

Toprak vatandır, vatansa güven

Kadın yuvadır, yuva da güvendir

Toprak pisliği örter,

Kadın aileyi arındırır

Doğumdan ölüme toprağın misafiriyiz

Ve bir de anaların…..

*inci Aral...MOR', 'Deniz erkektir alır-verir Soluğu-sesi heybetlidir Hoyrat ve öfkelidir Deniz kadın gibidir denir ya  Doğru değildir. Toprak dişidir, doğurur ...', ARRAY['Türk Edebiyatı','Şiir','Halay Sadi']::text[], 8.5, '{"poet":"Halay Sadi","poet_slug":"halay-sadi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kadin-toprak-deniz-erkek-midir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni yine sev!', 'beni-yine-sev-omer-dalman-xabls', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatın bu boktan

karmaşık yalanlarla dolu

       yollarında ilerlemekten

üzerimdeki erkeklik kılıfı

yerini

kalitesiz bir orospuluğa da bıraksa

en ahlaksız, en edepsiz

değersiz, haysiyetsiz insan da ilan edilsem

ya da tam tersi

bütün piyasa mankenlerinin peşinde koştuğu

parayı bulmuş bir jigolo da olsam

bir şeyden hep eminim:

kapına gelip

orada uslu, yalnız, masum bir kedi gibi kıvrılıp

”Lütfen beni yine sev! 

Lütfen beni yine sev! ” diye miyavlayacağım...

En yüksek mevkiilere de çıkıp otursam

krallar ve kraliçelerin en büyük kankileri de olsam

veya evrende yaratılmış

tüm hayat formlarına bürünsem de

bir şeyden hep eminim:

bütün o safsatanın bendeki göz boyayıcılığını

                                                    üzerimden silkinip

”Lütfen beni yine sev! 

Lütfen beni yine sev! ” diye

o sıcak dizlerine kapanacağım...

Bir marangozun henüz bitirdiği

o taş gibi sağlam

gürgen mobilyadaki

yeni çakılmış buz gibi soğuk çivi de olsam

oradan çıkar, ayaklanırım

kapına gelirim ve

”Lütfen beni yine sev! 

Lütfen beni yine sev! ” diye ağlarım...

İşte bundan eminim...

(15.02.2005)', 'Hayatın bu boktan karmaşık yalanlarla dolu        yollarında ilerlemekten üzerimdeki erkeklik kılıfı yerini kalitesiz bir orospuluğa da bıra...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/beni-yine-sev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al birini vur ötekine', 'al-birini-vur-otekine-omer-dalman-kfnl2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O akşam yine

çayı içtim

kahveyi içtim

kolayı içtim

arada su içtim

               boğazımı cilaladım

yine çayı içtim

puroyu içtim

ağır dumanıyla

kendimi eğlediğimi zannettim

her bir boku içtim

ama

gece yine boktan...

Tv’de filmleri seyrettim

salakça, kokuşmuşça zapladım

saati yine ikiledim

gece yine boktan

bir de bu haliyle

beni yarına bağlayacak

yarın’sa kendini ne bok zannediyorsa

bir tek ışığı farklı salağın! 

Yoksa

al birini vur ötekine! 

(Şubat 2005)', 'O akşam yine çayı içtim kahveyi içtim kolayı içtim arada su içtim                boğazımı cilaladım yine çayı içtim puroyu içtim ağır dumanı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/al-birini-vur-otekine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bol keseden', 'bol-keseden-omer-dalman-lufei', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Açarım çeşmemi

başlarım yazmaya

harcarım kendimi

bol keseden...

Kaliteli-kalitesiz kimine göre

bilemem

takmam kafayı

harcarım kendimi

bol keseden...

Elbet birileri bir şeyler der

boş durmaz ağızlar

                          işler

kelimelerimi seven çıkar mutlaka

                      kendini bana yakın hisseden

                      benim gibi ‘kafayı takmayan’...

Açarım çeşmemi gönülden

başlarım doldurmaya bardakları

harcarım kendimi

hiç düşünmeden

bol keseden...

(13.02.2005)', 'Açarım çeşmemi başlarım yazmaya harcarım kendimi bol keseden... Kaliteli-kalitesiz kimine göre bilemem takmam kafayı harcarım kendimi bol ke...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bol-keseden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '“Demedi” deme', 'demedi-deme-omer-dalman-jun5i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çivisi çıkmış bu binanın

ne yapsan, ne etsen toparlanmaz.

Dört bir yandan kasnaklasalar da

istinatlarla çevirseler de

çelik halatlarla gerseler de

ayakta kalmaz...

Akıllı ol

kendini bil

dışında kal bir şekilde

faydası olmaz çabalamanın

göçük altında kalırsın

”demedi” deme! 

Çivisi çıkmış bu binanın

salağa yat en iyisi

                         idare et

girme fazla altına

herkes biliyor

                 ayakta kalmaz.

Akıllı ol

kendini bil

”demedi” deme...

(Şubat 2005)', 'Çivisi çıkmış bu binanın ne yapsan, ne etsen toparlanmaz. Dört bir yandan kasnaklasalar da istinatlarla çevirseler de çelik halatlarla gerse...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/demedi-deme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kankiler yine Dünyayı kurtardılar!', 'kankiler-yine-dunyayi-kurtardilar-omer-dalman-bczwh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kaç dost bir araya gelince

ortada donatılmış bir masa

biraz da içki olunca hele

herkes filozof kesiliyor! 

ne dünyalar kurtarılıyor

ne siyasetçiler

ne futbol takımları

en küçük detayına kadar çözülüyor

yerden yere vuruluyor! 

Amerika, İran, Irak, Sovyetler

Alaska’daki buzlar

ne varsa çözülüveriyor.

Birbirinden kopyalar çektikçe

masadaki herkes hızla gaza geliyor

güçleniyor

iradeleri

o bir sıkımlık mermiler gibi de olsa

bir kereliğine ‘çelik’ gibi sertleşiyor! 

Ahmet her gün spora başlıyor

Mehmet çok sıkı rejime giriyor

Ulki yarından itibaren

                       düzenli kitap okumaya başlıyor

Selaattin yoga kurslarına başlayıp

          hayatın ruhuna yaptığı ağırlıktan kurtuluyor

Müge hemen

bir zamanlar o ilk keşfetmiş olduğu

fotoğrafçılık yeteneğine zaman ayırmaya başlıyor

Arzu bundan böyle

           boş boş diskolara gitmeyeceğini

           bazı akşamlar evde oturup

           adam gibi programlar seyredeceğini söylüyor

ama

bunların hepsi de nedense

sanki o masada bir anda çözümlenip

yapılıvermiş oluyor da

bir daha yapmaya gerek bile kalmıyor! 

Yarın kankiler

bütün o masaya koydukları

beyanatlardan bihaber

yine

o tek düze

tüketmeye köle

kokuşmuş, solmuş

tipsiz yollarında

saçlarını süpürge ede ede

kendilerinden uzakta

başkalarının onlara bahşettiği rutin’le

yürümeye devam edecekler! 

Boş ver sen takma

kankiler takılsınlar

konuşsunlar

sevinsinler

bu dünya daha çok kurtulur! 

(Mart 2005)', 'Bir kaç dost bir araya gelince ortada donatılmış bir masa biraz da içki olunca hele herkes filozof kesiliyor!  ne dünyalar kurtarılıyor ne s...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/kankiler-yine-dunyayi-kurtardilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz gümüş, sûkut altınsa...', 'soz-gumus-s-kut-altinsa-halide-selcan-karagul-9eai7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söz gümüş, sûkut altınsa...

Sus bee güzel kardeşim 

Hakim ol diline biraz konuşma! 

Zehir zemberek gibi sözlerin

Hududu yok malayani sözlerin

Aklın varsa güzel kardeşim

Tut şu dilinide biraz konuşma! 

Bunca...itici, kırıcı söz edersen

Kırdığın kalpleri bin parçaya bölersen

Bir düşün bakalım

Dönüşü olur mu bir daha geriye? ! 

Son anında pişmanlık fayda verir mi dersin? 

Bir gün gelecek... yüzyüze bakacaksın belkide

Başın dik... Alnın açık olmak istersen eğer

Eline, diline,  beline... hakim ol en başta! 

Ya! ... güvenme karşındaki insana

Ya da! ...sımsıkı sarıl dost biliyorsan o cana! 

Gönül kırmak çok kolay, yapması zordur...

Kendine hakim ol, diline kilit vur! 

Ne olursa olsun! ...Tut dilini! ...biraz olsun konuşma! ! ! 

Bir gün gelir dost düşman... düşman dost olur

Sen yaptığınla kalırsın sonunda...

Sende bilirsin ki güzel kardeşim

''Söz gümüşse, sûkut altındır...'' diye...

26.08.2005', 'Söz gümüş, sûkut altınsa... Sus bee güzel kardeşim  Hakim ol diline biraz konuşma!  Zehir zemberek gibi sözlerin Hududu yok malayani sözleri...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/soz-gumus-sukut-altinsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretini çektiğim sevda', 'hasretini-cektigim-sevda-dilek-kadioglu-fdqsx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni anlattım

ismini yazdım

gökyüzüne..

aydınlığını kıskandı

şehrin  ışıkları..

odama sızan ışık

sendin

uykularıma gelen

rüya da,

beni uyandıran şarkı da

sensin.

hayallerimi kaplayan

yüzün,

gecelerimin ay  ışığı.

nasıl dayanır yüreğim

hasretine nasıl katlanır

gecelerim

adını ezberledi yıldızlar

her gece tekrar ettiğim

gün boyu beklediğim

sen sevdam

seni  her yerde

gün boyu beklediğim

sen sevdam

seni  her yerde bekleyeceğim

özleyeceğim…

03.02.2006 / Beşiktaş', 'seni anlattım ismini yazdım gökyüzüne.. aydınlığını kıskandı şehrin  ışıkları.. odama sızan ışık sendin uykularıma gelen rüya da, beni uyand...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kadıoğlu']::text[], 8.5, '{"poet":"Dilek Kadıoğlu","poet_slug":"dilek-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hasretini-cektigim-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader!', 'kader-mesut-ozturk-ax74m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaderdir insanın gözünde yaş koymayan,

Kaderdir aşığın gönlünde yaralar peydahlayan,

Bir derd-ü avare oldu hep bahtlar,

Kaderdir insanı dağdan dağa atan.

Ağladım bekliyorum bir el,

Gel ey dostum gel gayrı gel,

Yetmedi mi çektirdiğin çileler? 

Ah kader istediğin hem saadet hem emel.

Kırık burkuk bir kalp, bir de dil,

Öyle bir bilmece ki? Hayat gel bunu bil.

Gözlerde yaş koymayan mübarek kader,

Insanlara herşeyide söyletir.', 'Kaderdir insanın gözünde yaş koymayan, Kaderdir aşığın gönlünde yaralar peydahlayan, Bir derd-ü avare oldu hep bahtlar, Kaderdir insanı dağd...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kader-113-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Kardeş', 'sair-kardes-husam-hasret-zmga6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şair kardeş dertleşelim gel bir az

Bizimle de koy inlesin dertli saz

Yazdığımın benzerini sen de yaz

Dert olduğu gibi derman olaydı

Çalışmak dek elde ferman olaydı

Şair kardeş yardım gerek her işte

Yardım ile başarılır iş işte

Öyle belli olalım da girişte

Uzak eller bizi yakın tanısın

Girişlerden olan farkın tanısın

Şair kardeş bir bilsek ne yaptık ki

Var, var iken yok duygusun kaptık ki

Yiten dostu gam içinde taptık* ki

Yarın için umut yoktur gönlünde

Var ise de hasret çoktur gönlünde

Şair kardeş bizi seven çok idi

Acımız da sevgimizle tok idi

Bizim gibi bu dünyda yok idi

Bilmiyorum başımıza ne gelip

Fikrimizde çözümsüz bir giz kalıp

Taptık: Bulduk', 'Şair kardeş dertleşelim gel bir az Bizimle de koy inlesin dertli saz Yazdığımın benzerini sen de yaz Dert olduğu gibi derman olaydı Çalışmak...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sair-kardes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Datça Yıldızı', 'datca-yildizi-mehmet-akif-tiryaki-me8l5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldızlar karanlık ortamlarda ortaya çıkar

Aydınlıktan utanır onlar

Datça''nın merkeze uzak bir yerinde

Etrafında birkaç evin bulunduğu iskelesinde

Seyrettim yıldızları bir yaz gecesinde.

İskeleye sırtüstü yattım, hava serin ve ılıktı.

Rüzgar ortama alışıktı

Yıldızlar parlıyor, gökyüzü ışık ışıktı.

Siyah bir sahan, içinde parlayan yıldızlar,

İskele dar, hayatsa up uzundu,

Ömrümün geri kalan kısmı Datça''da 

Huzur buldu.', 'Yıldızlar karanlık ortamlarda ortaya çıkar Aydınlıktan utanır onlar Datça''nın merkeze uzak bir yerinde Etrafında birkaç evin bulunduğu iskel...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/datca-yildizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısrak Atı Neyleyim', 'kisrak-ati-neyleyim-yusuf-ter-o6ot2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağları taşları delip geçmeyen

Senin gibi kısrak atı neyleyim

Kanat takıp yare doğru uçmayan

Senin gibi kısrak atı neyleyim

Aşkın için düşer isen dağlara

Dolanıp gel gönlümdeki bağlara

Gidiyorsan o hazanlı sağlara 

Senin gibi kısrak atı neyleyim

Ağlayıp ta yüreğimi üzersen

Mezarımı derin derin süzersen

O dağlarda doludizgin gezersen

Senin gibi kısrak atı neyleyim

Boynumu yanıma eğer  giderim

Sağanaklar gibi yağar giderim

Ay olur geceye doğar giderim

Senin gibi kısrak atı neyleyim

Yusuf’um sılaya dönülmez geri

Kovuklarda aşkım kalsa da yeri

Gidenler dönmüyor zaman çok seri

Senin gibi kısrak atı neyleyim

…………….Ben boynumu büker büker giderim

Yusuf Ter 28.01.06

Saat 21:35 İsviçre', 'Dağları taşları delip geçmeyen Senin gibi kısrak atı neyleyim Kanat takıp yare doğru uçmayan Senin gibi kısrak atı neyleyim Aşkın için düşer...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kisrak-ati-neyleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızca', 'yalnizca-murat-yumusakkaya-bzpyc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üşüyorum ayazda yalnızlığınla

Yalnızca seni istiyorum yalnızlığıma

Ne olur bebeğim anla

yalnızca anla...

belki gelecek 

o gün

üşüyeceğiz kalabalıkta

ta bakıpta

aksime 

göle düşen gözlerimde

görürsen hayallerimi

sakın

KORKMA 

ne olur bebeğim

anla

yalnızca 

anla...

üşüyorum ayazda

ıslanıyorum yağmurda

ağlıyorum yalnızlığında

yalnızca seni istiyorum yalnızlığıma...

ne olur bebeğim anla! 

yalnızca anla...', 'Üşüyorum ayazda yalnızlığınla Yalnızca seni istiyorum yalnızlığıma Ne olur bebeğim anla yalnızca anla... belki gelecek  o gün üşüyeceğiz kal...', ARRAY['Türk Edebiyatı','Şiir','Murat Yumusakkaya']::text[], 8.5, '{"poet":"Murat Yumusakkaya","poet_slug":"murat-yumusakkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yalnizca-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bankalar serpiştir', 'bankalar-serpistir-omer-dalman-h6hm6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Al beni

kirala, sat, döşe, boz, yap

ekle, çıkart

şekle sok, eğrilt, bük

üzerime şehirler kur

köyleri yık

çiçekleri bile kes gerekirse

saksılara boğ

ama lütfen

araya “bankalar” serpiştir! 

al beni

yaz, çiz, okut

şaplak at uyukladığımda

cezalandır ''doğru''yu üstelediğimde! 

ama lütfen

araya “bankalar” serpiştir! 

(Ekim 2005)', 'Al beni kirala, sat, döşe, boz, yap ekle, çıkart şekle sok, eğrilt, bük üzerime şehirler kur köyleri yık çiçekleri bile kes gerekirse saksıl...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bankalar-serpistir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ülkenin Aydınlanma Macerası', 'bir-ulkenin-aydinlanma-macerasi-hasan-sakman-84ot8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Hain emeller uğruna katledilen  Aydınlarımızın aziz ruhlarına...''

''Onların ışığını taşımaktan utanan, sıkılan,

aydınlanmaya ihanet ettiğini düşündüğüm kitlelere öfkemdir.''

Bir mum yandı,

zifiri karanlık

sardı dört bir yanı.

Bir mum yandı,

önemini yitirdi aydınlık.

Karanlıkken ortalık

yapılacak işler vardı.

Bir mum yandı,

tahammülü kalmadı 

karanlıktakilerin.

Bir kenara atıldı mumlar,

birileri fişini taktı ampulün,

aydınlandık(!)  

Sandılar...', '''Hain emeller uğruna katledilen  Aydınlarımızın aziz ruhlarına...'' ''Onların ışığını taşımaktan utanan, sıkılan, aydınlanmaya ihanet ettiğini...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-ulkenin-aydinlanma-macerasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kemal Bey...', 'kemal-bey-hasan-sakman-krg0i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Oturduğu makamda bulunma sebebini, 

onu oraya getirenlerin gayesini unutan,

hatırlatıldığında pişkin pişkin sırıtan,

bütün Kemal''lere...''

Çok iyi kazak 

örüyor Kemal Bey...

Çok seri mekik dokuyor.

Yetmiş milyon evladı var,

çok fazla masal okuyor.', '''Oturduğu makamda bulunma sebebini,  onu oraya getirenlerin gayesini unutan, hatırlatıldığında pişkin pişkin sırıtan, bütün Kemal''lere...'' Ç...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kemal-bey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilsen...', 'bir-bilsen-halide-selcan-karagul-e69w8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BİR BİLSEN! ..



Kalbimde yaşatsam seni

Düşlerimde ah! ..görsem seni...

Hasretim bir türlü dinmiyor

Yanımda olsan şimdi...

Dökülse dudaklarından

Sevgi dolu sözcükler...

Ve söylesen ismimi...

Özlemle dopdolu tutsan ellerimi...

Gözlerinde heyecan söylesen sevdiğini,

Nasıl mutlu olurum bir bilsen

Hecelere dökemem hissimi...



23.05.2001', 'BİR BİLSEN! .. Kalbimde yaşatsam seni Düşlerimde ah! ..görsem seni... Hasretim bir türlü dinmiyor Yanımda olsan şimdi... Dökülse dudaklarınd...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-bilsen-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 49', 'guncel-beyitler-49-huseyin-avdic-2fv3t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '$ah-Mat

$ah Ismail de gecmiste Yavuz Sultan Selim''e yenilmisti, fakat etmemisti 

ona itaat.

Tarih tekrar ediyor simdi: Ahmedinecad da ABD karsisinda olacaktir katiyyen mat! 

Berlin, $ubat 2006.', '$ah-Mat $ah Ismail de gecmiste Yavuz Sultan Selim''e yenilmisti, fakat etmemisti  ona itaat. Tarih tekrar ediyor simdi: Ahmedinecad da ABD ka...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/guncel-beyitler-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Dostlar...', 'eski-dostlar-halide-selcan-karagul-oc2hj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ESKİ DOSTLAR



Nice dostlar yitirdim

Göz yaşlarım sel oldu

Geriye dönüp baktım

Tüm dostlarım el oldu

Dostum dedim el verdim

Boşlukta kaldı elim

Tanıdım dediklerim

Güvenip sevdiklerim

Dostum, canım bildiklerim

Beni sırtımdan vurdu..

Yalan, riya bilmedim

Hiç ihanet etmedim

Dostlarımı çok sevdim

Canımdan aziz bildim

Allah bir söz bir dedim

Kötülüğü bilmedim

Neler değişti bilmem

Bir kalemde yok oldu

Dostlar inanmaz oldu

Dost olan düşman oldu

Düşmanlar baş taç oldu

Dostum canım dediklerim

Fütursuz sevdiklerim

Beni sırtımdan vurdu..

Düşmanlara gün doğdu

Dostlar bize ne oldu…..



18.07.2004

saat: 13.00', 'ESKİ DOSTLAR Nice dostlar yitirdim Göz yaşlarım sel oldu Geriye dönüp baktım Tüm dostlarım el oldu Dostum dedim el verdim Boşlukta kaldı eli...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/eski-dostlar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel! ...', 'gel-halide-selcan-karagul-3lynp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GEL! ..



Gözlerimdeki nem 

Kurumadan gel! ..

Bahçemde çiçeklerim

Sararmadan gel..

Hayatım, bir tanem

Ey gönül kuşum,

Gören gözlerim

Kapanmadan gel..

Ey nurum, cananım

Hayat pınarlarım

Tükenmeden gel! ..

Bu senden son arzum

Ölüm çalmadan kapım

Azrail almadan canım

Geç kalmadan gel! ..



22.05.2002', 'GEL! .. Gözlerimdeki nem  Kurumadan gel! .. Bahçemde çiçeklerim Sararmadan gel.. Hayatım, bir tanem Ey gönül kuşum, Gören gözlerim Kapanmada...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-267-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavrum!', 'yavrum-mesut-ozturk-3s70e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey ceylan gözlü, sırma saçlı yavrum! 

Baba deyişini özledim! 

Ey mis kokulu, kalbi temiz  yavrum! 

Bana sarılışını özledim.

Ey tatlı dilli, Dünya güzeli yavrum! 

O güzel gözlerini özledim.

Ey kıvırcık minicik  yavrum! 

Ben seni, senin tadını özledim.

Ey babasının birtanesi,

Elinden tutup gezmeyi,

Seninle yeniden gülmeyi,

Kısacası ben kızımı, yavrumu Özledim.', 'Ey ceylan gözlü, sırma saçlı yavrum!  Baba deyişini özledim!  Ey mis kokulu, kalbi temiz  yavrum!  Bana sarılışını özledim. Ey tatlı dilli, ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yavrum-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam olursam', 'adam-olursam-omer-dalman-3n4z3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün adam olursam

bundan hiç hayır beklemeyin! 

Ya Dünya’da adam kalmamıştır

ya Kıyamet Dünya’ya inmiştir

ya da iş hayatı tepetaklak gelmiştir.

Sanatçıdan adam olur mu? ! 

Harcanacak kaynak kalmadığında

doğanın içine hepten edildiğinde

sektörler birbirleriyle tokuşup

                        ortaya karışık menemen olduklarında

belki bana ‘Adam’ derler

o zamansa

bütün suçu bana yüklemek içindir bu! 

Ama hiç adam değildim

olmadım! 

Suçu kendinizde bulun bu yüzden...

(Şubat 2005)', 'Bir gün adam olursam bundan hiç hayır beklemeyin!  Ya Dünya’da adam kalmamıştır ya Kıyamet Dünya’ya inmiştir ya da iş hayatı tepetaklak gelm...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/adam-olursam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şeyler oluyor...', 'bir-seyler-oluyor-aysun-elagoz-m5jep', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şeyler oluyor...

İsmini bir türlü koyamadığım,

Ben farkındayım,

Sen farkındasın,

Bulutlar farkında...

Garip bir hüzün

Filizlendi yüreğimde..

Kara bir haber öncesinin,

Sıkıntısı dolaşmakta

Fikrimin kuytularında..

Bir yandan içim sızlamakta,

Yokluğunun telaşıyla..

Bir şeyler oluyor...

Öğrenmekten korktuğum,

Soramadığım...

İsmini bir türlü koyamadığım..

Bulutlar farkında..

Ben farkındayım...', 'Bir şeyler oluyor... İsmini bir türlü koyamadığım, Ben farkındayım, Sen farkındasın, Bulutlar farkında... Garip bir hüzün Filizlendi yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-seyler-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sevdalıyım', 'kara-sevdaliyim-halide-selcan-karagul-8d1l6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KARA SEVDALIYIM



Bir esmere gönül verdim

Gönlümü yoluna serdim

Günleri birbirine ekledim

Bir gün gelir geçer diye.



Ben bir çoban yıldızıyım

Bir esmere aşık kızım

Aşk yolunda yanık bağrım

Ağlıyorum gündüz  gece.



Mecnunum Leyla mı ararım

Kara sevdayım yanarım

Günleri birbirine bağlarım

Bir gün bulurum diye.



Ben kara sevdalıyım

Yakar yüreğimi göz yaşım

Olur ki, küllenir aşkım

Dua’dayım gündüz gece.



Her gün gizli ağlıyorum

Gönlüme taş basıyorum

Bu dünyada yaşıyorum

M e v l a m  için gündüz gece.



04.01.1999 - Pazartesi', 'KARA SEVDALIYIM Bir esmere gönül verdim Gönlümü yoluna serdim Günleri birbirine ekledim Bir gün gelir geçer diye. Ben bir çoban yıldızıyım B...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kara-sevdaliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer…..V', 'rubailer-v-sevinc-kavuk-0kfz7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Madem bu dünyada misafiriz, düşünmeye de gecikir isek

Önce ol ruhuna iyi misafirperver, gör hem ne onur kazanır

Ev sahibinin kurallarına uyalım abartı kaldırmaz bilmez isek

Kendinbilmezlik türeçleme kuralları çok bolundan kabarır

Subat  2006

(Ruhumuz bedenimizde misafir, bedenimiz evrende

Misafir hediyesiz gelmez, ruh sevgiyi getirdi göç evine

Toprağa uygarlığı ek diye ebedi o gençlik güzelliğine

Hediyen olsun ulus varlığı o mutluluk vatan severliğinde)', 'Madem bu dünyada misafiriz, düşünmeye de gecikir isek Önce ol ruhuna iyi misafirperver, gör hem ne onur kazanır Ev sahibinin kurallarına uya...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/rubailer-v-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelere Tutunmak', 'gecelere-tutunmak-adem-uzun-kyw5s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlığım

Hep geceleyin artar

Sonu olmayan karanlıkta

Sonsuz gökyüzünde

Kendimi görürüm hep

Yalnızlığım arttıkça

Karanlığı

Daha çok severim

Ve daha çok hissederim

Islak çimler üstünde

Boydan boya uzanıp

Karanlığa dalmayı

Onun kollarında hep

Hepten kaybolmayı

Hava kararınca

Karanlık ben olurum

Sararım yıldızları

Birer birer kollarından

İşte yıldızlar ondan

Karanlığı delemez

Bir bir sönerler gökte

Ve karanlık yine 

Benim olur bir gece

Karanlık göklerdeki

Karanlık benim

Issız sokaklardaki

Yalnızlık benim

Sisli bir gecede

Gökyüzünde dolaşan

Yalnız bir yıldız varsa

İşte o benim yıldızım

İşte ben o yıldızım', 'Yalnızlığım Hep geceleyin artar Sonu olmayan karanlıkta Sonsuz gökyüzünde Kendimi görürüm hep Yalnızlığım arttıkça Karanlığı Daha çok severi...', ARRAY['Türk Edebiyatı','Şiir','Adem Uzun']::text[], 8.5, '{"poet":"Adem Uzun","poet_slug":"adem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gecelere-tutunmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medyatör', 'medyator-mehmet-akif-tiryaki-nnmpa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Medyatör tavrını koydu, seslendi

Haydi dostlar siz de katılın dedi.

Melike hanım bu işi sevmedi,

İstersek yazarız veya yazmayız,

Bu bizim bileceğimiz iş dedi.

Medyatör üzüldü, özür diledi.

Sıkıntı kapandı ve ertelendi.

Dostluklar dile geldi, tazelendi.

İkinci bahar aşkı yenilendi.

Grup başı olmak kolay değildi,

Dostlar güldü bu işe çok sevindi,

Dostluklar kenetlendi, perçinlendi.', 'Medyatör tavrını koydu, seslendi Haydi dostlar siz de katılın dedi. Melike hanım bu işi sevmedi, İstersek yazarız veya yazmayız, Bu bizim bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/medyator-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamsın...', 'sevdamsin-halide-selcan-karagul-xndwa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SEVDAMSIN! ! ...



Sen ruhumdan bir parçasın

Kıpır-kıpır  duygularımsın

Derin yeşil gözlerinde

Kendimi bulduğum,

Yüreğimin derinliklerinde

Hesapsız yaşadığım

Sevdamsın! ! ......



09.01.2002', 'SEVDAMSIN! ! ... Sen ruhumdan bir parçasın Kıpır-kıpır  duygularımsın Derin yeşil gözlerinde Kendimi bulduğum, Yüreğimin derinliklerinde Hes...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdamsin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyen gönüllere ayrılık çıktı', 'sevmeyen-gonullere-ayrilik-cikti-halil-colak-9u1bp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıldızlara baktım falda da çıktı

Sevmeyen gönüllere ayrılık çıktı

Onlara inanmadım baktırdım fala

Onda bile gülüm ayrılık çıktı

Kendi kendimi yokladım şöyle

Kalbimde bile sana artık yer yok

Orada bile ikimizi ayrılık çıktı

Sana mutluk bana da özgürlük

Halil Çolak 3.2.2006 Ankara', 'Yıldızlara baktım falda da çıktı Sevmeyen gönüllere ayrılık çıktı Onlara inanmadım baktırdım fala Onda bile gülüm ayrılık çıktı Kendi kendim...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevmeyen-gonullere-ayrilik-cikti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakire Şiirler', 'bakire-siirler-omer-dalman-w7exm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazı şiirlerimi bakire haliyle bırakırım

bilirim

bir kaç kere dönüp baksam

makyajı eksik görünecek gözüme

alacağım elime kalemi

allığı, farı, rimeli, ruju

yürekleri hoplatan kadına çevireceğim kızı.

bu yüzden

bazı şiirlerimi bakire haliyle bırakırım

hep o sade

makyajsız gülümseyişi seyrederim yüzlerinde...

öteki ''allı pullu kadınlar''dan çok var etrafımızda! 

bu benim kadınım...

(Ekim 2005)', 'Bazı şiirlerimi bakire haliyle bırakırım bilirim bir kaç kere dönüp baksam makyajı eksik görünecek gözüme alacağım elime kalemi allığı, farı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bakire-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum!', 'oglum-mesut-ozturk-sileo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani okula gederken off deyişin varya! 

Hala kulaklarımı çınlatıyor,

Oyuncak almadığımda babaa deyişin varya! 

Hala evin içinde yankılanıyor.

Tasalanma oğlum sen gelirim birgün,

Sensiz cennette olsam, sanki sürgün.

Ayrılışımız aklımda zaten hergün,

Bekle oğlum baban dönecek birgün.

Oğlunun kıymetini bilmeyene,

çocuklar sıktı usandım diyene,

Evladına durmadan eziyet edene,

Ayrılık acısı ver rabbim birgün.', 'Hani okula gederken off deyişin varya!  Hala kulaklarımı çınlatıyor, Oyuncak almadığımda babaa deyişin varya!  Hala evin içinde yankılanıyor...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oglum-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-halide-selcan-karagul-zgxhw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SENSİZ! ..



Geceler sensiz geceler sessiz

Göz yaşlarım akar sedasız sessiz 

Karanlıklar şahit gizemsiz

Her tarafta senden bir iz…



Günlerim sensiz günlerim sessiz

Ben nasıl yaşarım sensiz

Ağlamaktan kaldım bitap nefessiz

Her tarafta senden bir iz..



23.05.2001', 'SENSİZ! .. Geceler sensiz geceler sessiz Göz yaşlarım akar sedasız sessiz  Karanlıklar şahit gizemsiz Her tarafta senden bir iz… Günlerim se...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensiz-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Klasik Müzik', 'klasik-muzik-omer-dalman-iq7lf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Söyleyecek çok şeyi olan

ama

öyle agresifler gibi

bir anda

sert ve çığlıkçı bir vuruşla değil de

yumuşak yumuşak

kendinden emin ve

adım adım söyleyenlerin işidir klasik müzik...

Direkt karşısındakinin eline fotoğraf vermez onlar

benzetmelerle anlatırlar dertlerini

Bunalımlarının sonucu bile bir anda intihara gitmez

yavaş yavaş ölümü kabullenir onlar

ve beklerler en saygın biçimde...

Hoş ve narin gelir ölüm bile onların koynuna

bırakın diğerleri balkondan atlaya dursunlar

klasik müzik sevenler onlara hafifçe bakıp gülümserler

arkalarından bakarlar ve

büyük bir bilge tavır içinde

alçak gönüllüce

yollarına sessizlik içinde devam ederler.

Onlar hep vardı ve hep de oluyorlar.

Tek vuruşluk türler de çoğalıyor

ama

klasik müzik sevenler

öz notaların üzerlerine basa basa

bulutlar üstünde

rüzgarla birlikte

kar taneleriyle oynaya oynaya

yaşamaya devam ediyorlar

bize onca şey’i söyleyerek...

(Şubat 2005)', 'Söyleyecek çok şeyi olan ama öyle agresifler gibi bir anda sert ve çığlıkçı bir vuruşla değil de yumuşak yumuşak kendinden emin ve adım adım...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/klasik-muzik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Seni Giyineyim', 'gel-seni-giyineyim-gul-yazganarikan-trpvy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle çıplağım sana 

öyle savunmasızım 

Sen kalın örtülerin ardından

Göz kırpmaktasın...

 ne kadar çıplaksam ben

O kadar giyiniksin sen

Kapamalısın önce gözlerini,

Soyunmalısın...

Dokunmalısın, dilediğince, 

Ağlamalısın indirmelisin göğü yerlere

Ben soyundum sana...

Sıyrıldım utancımdan, 

İşte ellerindeyim...

Çıkar at korkunu da 

Gel seni giyineyim...', 'Öyle çıplağım sana  öyle savunmasızım  Sen kalın örtülerin ardından Göz kırpmaktasın...  ne kadar çıplaksam ben O kadar giyiniksin sen Kapam...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gel-seni-giyineyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu akşam', 'bu-aksam-omer-dalman-cr57y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üzüldüm be baba akşam akşam.

Sebep? ..

Boş ver bende kalsın.

Sana sadece göz yaşlarımdan iz düşen kelimelerimi gönderiyorum.

Üzüldüm be baba bu akşam ben

sorma

olur böyle bizim gibilere arada...

Kelimeler, cümleler pek bir güzel çıkar da

olan ruhumuza olur

yine paramparça

yine terkedilmiş

yine en baştan beri yapayalnız olduğundan emin...

Üzüldüm be baba bu akşam

sorma sebebini dinle sadece

bu da yeter bana.

Paylaş beni, derdimi, kederimi

acımın sebebini...

Ne mi? ! 

Yaşamak...

(Ocak 2005)', 'Üzüldüm be baba akşam akşam. Sebep? .. Boş ver bende kalsın. Sana sadece göz yaşlarımdan iz düşen kelimelerimi gönderiyorum. Üzüldüm be baba...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-aksam-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinlene dinlene', 'dinlene-dinlene-omer-dalman-yebrs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen aşka gelirim

dinlene dinlene sevişir gibi

oturur kalkar

peş peşe şiirler yazarım.

Her seferinde doyuma ulaştığımı zanneder

rahatladığımı düşünürüm.

Mutfağa giderim

bir bardak çay daha koyarım

koltuğuma dönerim

iki televizyon bakarım

derken

yine bir yerlerim rahat edemez

tıpkı posta posta sevişmek gibi

bir şiir daha yazarım

sonra yine bir rahatlama…

”İyi” derim

”Yine günümdeyim herhalde! ”

Artık anlarım

bu gece böyle gidecek

3-5 neyse…

ve defalarca sevişirim böyle gecelerde

yedi veya sekiz şiirle birlikte olur

sonra kalkar giderim.

(Mart 2005)', 'Bazen aşka gelirim dinlene dinlene sevişir gibi oturur kalkar peş peşe şiirler yazarım. Her seferinde doyuma ulaştığımı zanneder rahatladığı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dinlene-dinlene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın', 'gunaydin-omer-dalman-mco79', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O yaşlı adam bana bir süre kesintisiz baktı diye

gözlerimi -ondan daha da kesintisiz-

gözlerine diktikten sonra

öyle pişman oldum ki

sanki bir adamı kesmiş

yaralamış

canına meydan okumuş gibi...

ve öyle utandım ki...

tipini de tam hatırlamıyorum

bu yüzden

artık sabahları

bizim sitede

her gördüğüm yaşlıya

''Günaydın! '' diyorum sevgi dolu gözlerle...

(Mart 2005)', 'O yaşlı adam bana bir süre kesintisiz baktı diye gözlerimi -ondan daha da kesintisiz- gözlerine diktikten sonra öyle pişman oldum ki sanki b...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gunaydin-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kartepe Maltepe', 'kartepe-maltepe-mehmet-akif-tiryaki-3c2zm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kartepe''den göle baktım,

Gölden Maltepe''ye

Göremedim Maltepe''yi

Yetiştim ada trenine,

Götürdü beni mahalleme

Maltepe''den baktım Kartepe''ye

Göremedim Kartepe''yi

Yetiştim ada trenine.

Götürdü beni Kartepe''ye

Maltepe, Kartepe arası 

Sapanca gölü

Dost bahşişi, hediye.', 'Kartepe''den göle baktım, Gölden Maltepe''ye Göremedim Maltepe''yi Yetiştim ada trenine, Götürdü beni mahalleme Maltepe''den baktım Kartepe''ye G...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kartepe-maltepe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir''in Dağ Çiçekleri', 'i-zmir-in-dag-cicekleri-ahmet-zekai-yildiz-4m1k1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün onbeş mayıs bin dokuzyüz ondokuz:

Hasan Tahsin İzmir''in Konak meydanında..

Elinde tabanca..

Sesinde bir kurtuluş muştusu var.

Çanakkale''de toprağın örtemediği,

Dedem uyanmıştır.

Gün yirmi altı ağustos bin dokuzyüz yirmiiki:

Mustafa Kemal Afyon Kocatepe''de.

Al bir atın üstünde..En önde..

Parmağı kurtuluş yolunu gösterir.

"Ordular! ..İlk hedefiniz Akdenizdir.İleri! ..

O yolda, dünyanın durduramadığı

Anam, babam, bacım yürümüştür.

Gün dokuz eylül bin dokuzyüz yirmi iki:

Kulağımda atların ayak sesleri..

Toz duman..

Atılır, o ayaklar altına

İzmir''in dağ çiçekleri.

Ve coşkulu insanların göz bebeklerinde; 

Bir bayrak indirilir çıkmamacasına.

Bir bayrak çıkarılır inmemecesine.', 'Gün onbeş mayıs bin dokuzyüz ondokuz: Hasan Tahsin İzmir''in Konak meydanında.. Elinde tabanca.. Sesinde bir kurtuluş muştusu var. Çanakkale''...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/izmir-in-dag-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldim!', 'geldim-mesut-ozturk-72af3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu günahkar ve naçiz kalpli bedenimle,

Huzurunda günahlarımdan arınmaya geldim.

Gözlerimde yaş kalbimde nefs ile,

Bu hastalıktan kurtulmak için bak sana geldim.

Affet beni lutf-u A-layı dergah-i büyük yarim,

Dizimdeki tek kuvvet, gözümdeki derin ferim,

Elimdeki pırlanta, gönlümdeki meşaleli nakışım,

Huzurundan feyz alıp coşmaya geldim.

Muhammedül emini görmeden giderim diye,

Elimdeki günah defterinden kurtulmak ümidiyle,

Bu yüce günde senin sevgili listene,

Mü`min olup geçmek için ölmeye geldim.

Affet beni yüceler yücesi Dergah-i padişah,

Merhametli şefkatinle,şu kara seccadeye bak,

Kabul demezsen cennete, cehenneme demem ah! 

Umudum sönmedi, günahkarım ateşe girmeye geldim.', 'Bu günahkar ve naçiz kalpli bedenimle, Huzurunda günahlarımdan arınmaya geldim. Gözlerimde yaş kalbimde nefs ile, Bu hastalıktan kurtulmak i...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geldim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Film Cd’lerim', 'film-cd-lerim-omer-dalman-bra9d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evimin salonundaki sehpanın üzerinde

televizyon sehpasının altındaki rafta

çalışma odamdaki o ihmal edilmiş köşedeki çantada

bir sürü film cd’si birikti.

Doğru dürüst bir düzeni de yok...

İstediğim filmi o dakikada bulmama imkan yok! 

Doğaçlama bir dağınıklık

Kendi içinde huzurlu, emin...

Ama aradığım filmin yine de

Onların arasında bir yerde olduğunu

ve

yeterince emek harcarsam

bulup

onu tekrar seyredebileceğimi bilmek bile

                                                     çok güzel...

Bir doğallık

bir gizem

ve isteyince

emek harcayarak

çözülecek...

Bazen bu düzensiz çokluğu seviyorum.

Tıpkı hayatlarımız gibi...

(Nisan 2005)', 'Evimin salonundaki sehpanın üzerinde televizyon sehpasının altındaki rafta çalışma odamdaki o ihmal edilmiş köşedeki çantada bir sürü film c...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/film-cd-lerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıç Pireleri', 'kic-pireleri-omer-dalman-rebig', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu güzel lafı ilk

            bir iş arkadaşımdan öğrenmiştim.

Ne güzel de kondurmuştu lafı yerine! 

Evet! 

işte o Kıç Pireleri’nden bir tanesini

                               trafikte bir sıkıştırsam

ağız, burun bırakmayacağım emin olun! 

Lan ne iğrenç bok bunlar! ? 

Gözleri bu kadar mı kara

bu kadar mı önemsiz hayat onlar için ki

insanın trafikte bu kadar kıçına yapışabiliyorlar! ? 

Her defasında bu pirelerden birinin yolunu kesip

aşağı inip

sıkıca bir benzetmeyi düşünüyorum

ama

gözüm o karalığa henüz gelmemiş olmalı ki

henüz ne onun, ne kendimin

               dünyasını karartmıyorum

ama

bir gün mutlaka

bu Kıç Pireleri’nden birini ezeceğim! 

Zaten şu ana kadar

yollarda bunların bir kaçının leşi bulunsaydı

bu kadar artmazlardı...

(Mart 2005)', 'Bu güzel lafı ilk             bir iş arkadaşımdan öğrenmiştim. Ne güzel de kondurmuştu lafı yerine!  Evet!  işte o Kıç Pireleri’nden bir tan...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kic-pireleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu!', 'suclu-mesut-ozturk-01cd9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar güçlü ve kuvettli,

Kalbimde huzur, ruhumda kudret vardı,

Bir zamanlar neşeli ve sohbetli,

Yüzümde mutluluk, gözümde aşk vardı.

Kahrolasıca Avrupa hepsini elimden aldı,

Bana sadece geriye anılarım kaldı,

Bütün vücudumu üzüntüden yaralar sardı,

Sadece bir suçlu, tek suçlu vardı, Almanya.', 'Bir zamanlar güçlü ve kuvettli, Kalbimde huzur, ruhumda kudret vardı, Bir zamanlar neşeli ve sohbetli, Yüzümde mutluluk, gözümde aşk vardı. ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/suclu-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naçar Geceler', 'nacar-geceler-huseyin-ozcan-49qgw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uğrunda gözyaşları döktüğüm sevgili,

habersizsin sen hıçkırıklara boğulduğum gecelerden

bilmezsin hangi girdaplarda kaybolduğumu….

ruhum dipsiz uçurumlarda çırpınırken çaresiz,

duymazsın sen hasretine feryatlarımı…..

oysa sen; 

her gece parlayan yıldızımdın benim,

ve her sabah doğan güneşimdin,pırıl pırıl….

şimdi sen de terkettin beni,

sen de kayboldun gittin……', 'uğrunda gözyaşları döktüğüm sevgili, habersizsin sen hıçkırıklara boğulduğum gecelerden bilmezsin hangi girdaplarda kaybolduğumu…. ruhum dip...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Özcan']::text[], 8.5, '{"poet":"Hüseyin Özcan","poet_slug":"huseyin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nacar-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-dilek-kadioglu-vugx0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökyüzüne bakıp seni anlattım.

Şehrin ışıkları bile

Sönük kaldı,

İsminin tek harfinde,

Odama ışık sızıyor,

Yarı açık perdeden.

Seni düşünmek bile aydınlatıyor.

Bulunduğum ortamı,

Uyku göz kapaklarım da ağırlı yapmak ta

Uyusam gelecek misin rüyama? 

Yoksa uyanık kalıp ta hayalinle mi

Yaşıyım seni hala? 

Bu gece de sevdam ağır bastı,

Her gece olduğu gibi

Gündüzden birikiyor. 

Hasretin yüreğime,

Geceleri daha ağır oluyor SEVDAM

01/02/2006 Beşiktaş', 'Gökyüzüne bakıp seni anlattım. Şehrin ışıkları bile Sönük kaldı, İsminin tek harfinde, Odama ışık sızıyor, Yarı açık perdeden. Seni düşünmek...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kadıoğlu']::text[], 8.5, '{"poet":"Dilek Kadıoğlu","poet_slug":"dilek-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevdam-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle!', 'oyle-mesut-ozturk-8zz6b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle bir Dünya ki hep mechullerle dolu,

Bilmek istiyorum işte ben onu,

Insan olmanın hakikat bir yolu,

Tanımaktır Dünya`yı canım dostlarım.

Garibin halini garibe sor derler,

Hayvanı insandan daha çok severler,

Avrupalı olmak uğruna,

Benliğini unutup,Maymuma dönerler.

Gidiyorum sonu bilinmez yarınlara,

Boşlukta uçan kuşlar misali,

yaşıyoruz sevgisiz bu Dünya`da,

Kanadı kırılmış kelebek misali.', 'Öyle bir Dünya ki hep mechullerle dolu, Bilmek istiyorum işte ben onu, Insan olmanın hakikat bir yolu, Tanımaktır Dünya`yı canım dostlarım. ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oyle-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Gülücükler Büyüyor', 'gul-gulucukler-buyuyor-hamdi-oruc-of95i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül Gülücükler büyüyor

Evin duası

Büyüsün bebek

Büyüsün bebek

Evin her yerinde

Saat gibi yüreği

Tık tık çalışır hep

Dinleyin hele

Gül gülücükler ile

Aynalar gülüyor

Bebek büyüyor

Yarım kalsın işin annesi

Emzir şu çiçeği

Yarım kalsın aşın babası

Gezdir şu çiçeği

Beşik gülüyor

Ev gülüyor

Görün hele

Bir bebek beşiğinde büyüyorsa

Şiirler yarım kalabilir artık

O evde o beşikte

Mutluluğun mısrası yazılsın diye', 'Gül Gülücükler büyüyor Evin duası Büyüsün bebek Büyüsün bebek Evin her yerinde Saat gibi yüreği Tık tık çalışır hep Dinleyin hele Gül gülücü...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Oruç']::text[], 8.5, '{"poet":"Hamdi Oruç","poet_slug":"hamdi-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gul-gulucukler-buyuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanatın Değeri', 'sanatin-degeri-omer-dalman-abomh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kiminin

bir sanat eserinin ne denli güzel olduğu anlaması için

                                               fiyatını duyması gerekir

                                               veya hangi meşhur sanatçıya ait olduğunu...

bence bunun

metrekare usulü tablo alan gavat’ın yaptığından

veya hal’den tonla meyve alan manavın yaptığından

                                                      hiç bir farkı yoktur! 

(Nisan 2005)', 'Kiminin bir sanat eserinin ne denli güzel olduğu anlaması için                                                fiyatını duyması gerekir      ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sanatin-degeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demem', 'demem-omer-dalman-2a775', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Koridorda

kaldırımda

yol kenarında

alışveriş merkezindeki

                vitrinlerin önünde yürürken

karşı taraftan gelen erkeğe baktığında

”onunla bir akşam yemeği yesem? ” demeyen

”onu öpsem nasıl olur acaba? ! ”

”elini tutsaydım nasıl elektriklenirdim? ! ”

”onunla sevişseydim nasıl olurdu acaba? ! ”

diye düşünmeyen kadına

                                    “kadın” demem...

aynı şekilde

karşı taraftan gelen kadına baktığında

”şu kadının yüzü ne güzel! ”

”onu şöyle dolanıp, bir sarıversem! ”

”bu akşamı aniden onunla geçirsem! ? ”

diye düşünmeyen adama

                                    “adam” demem...

madem ‘kadın-adam’ oldun

şekillendin

geldin bu ucuz küreye

görevini bileceksin

tadını çıkaracaksın bu ayrımın! 

mal mülk peşinde koşarken nefes nefese

bir yandan bu hazinenin değerini bileceksin! 

Gör bak sonra

nasıl da geliyor gerisi

’çorap söküğü’ gibi! ..

(Mayıs 2005)', 'Koridorda kaldırımda yol kenarında alışveriş merkezindeki                 vitrinlerin önünde yürürken karşı taraftan gelen erkeğe baktığında...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/demem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ablam!', 'ablam-mesut-ozturk-hgxb5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duydum bana şiir yazmışsın ablam.Kardaşım kara kaşlım diye,

Duydum bana hasret kalmışsın ablam,Kardaşım kara gözlüm diye,

Duydum beni düşünür, sorarmışsın ablam,Kardaşım kardaşım diye.

Sana tek bir cevabım olabilir ablam,Bu kardaşın sana kurban olsun!', 'Duydum bana şiir yazmışsın ablam.Kardaşım kara kaşlım diye, Duydum bana hasret kalmışsın ablam,Kardaşım kara gözlüm diye, Duydum beni düşünü...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ablam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi Kokuşmuş', 'hepsi-kokusmus-omer-dalman-l5289', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Niye şu bizim ''kokuşmuş'' iş yerlerimizde

birileri kendi işi olan şeyleri

                     doğru dürüst yapmadığında

                     ve uyarıldıklarında kibarca

hemen

şirket sınırlarındaki kardeşlik anlayışına

                     leke sürdüğümüzü ilan ederler de

kendilerinin yapması gerekli olan işleri

düzgün yapmamalarını

kardeşliği ihlal eden bir neden saymazlar? 

Bunlar nasıl ''kardeş'' kardeşim? ! 

Nasıl bir iş anlayışı bu? ! 

Püfff...

Hepsi kokuşmuş...

(Mart 2005)', 'Niye şu bizim ''kokuşmuş'' iş yerlerimizde birileri kendi işi olan şeyleri                      doğru dürüst yapmadığında                     ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hepsi-kokusmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bal Bakışlı Bebek', 'bal-bakisli-bebek-hamdi-oruc-ijpm3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bal Bakışlı Bebek

Annesi yetmiyor benim kelimelerim

Göz yaşlarım da yetmiyor

Senin gözyaşların anlatsın neşesini bu bebeğin

Şansıma tüküreyim olamamışım

Bal bakışlı bir bebek

Bir dakikalığına olsun 

Diyesim geldi

Annesine bakarken bu bebek

Bal bakışlı bebek

Elimdeki fotoğrafta

Bal bakışlı bebek

En bal bakışlım bu  bebek 

En eşsiz bu bal bakışlar

Bu bebek fotoğrafı ne söylüyor bana 

Bal bakışlar diyor  ki:

Oh daha ne isteyeyim

Temiz hava bol güneş

Gece ay beşiğimde

Gündüz güneş

Söylemiş şarkısını

Çamların dallarından bakıp

Sevincim çiçek açtı...

Beşiğim meşeden

Dört köşeyim neşeden...

Büyüyorum neşe ile

İnsanlar altın kalpli

Köyüm çiçek açtı

Şanslı bir çocukluk benimki

Gece yıldızlar

Gündüz güneş

Beşiğime nazar boncuğu olmuş

Dereler söylüyor ninni

Dereler çiçek açtı

Çiçeklerden bal toplamış bakışlarım

Kundağıma sevgisini işlemiş annem...

Kundağım çiçek açtı', 'Bal Bakışlı Bebek Annesi yetmiyor benim kelimelerim Göz yaşlarım da yetmiyor Senin gözyaşların anlatsın neşesini bu bebeğin Şansıma tüküreyi...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Oruç']::text[], 8.5, '{"poet":"Hamdi Oruç","poet_slug":"hamdi-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bal-bakisli-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-omer-dalman-cxtor', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir benim çerezim

şiir benim aperatifim

             benim özetim

                        genelim...

Detaylı açıklamadan uzak

                        gerçeğim...

Oyunsuz, kuralsız

uyumlu, uyumsuz dans edişim...

Şiirde hesap yok bana

yargı yok, ceza yok

şiir benim en geniş vadilerim

yaylalarım, sonsuz denizlerim

                                       uzayım...

benim kendimle birlikteliğim

ve seni kendime

sonsuza kadar ortak edişim...

Şiir benim delilik nöbetlerim

oraya, buraya saldırışlarım

kanımı akıtışım

acımı zevk için çekişim

ve tedavi oluşum...

benim en kısa, en öz gerçeğim...

(Şubat 2005)', 'Şiir benim çerezim şiir benim aperatifim              benim özetim                         genelim... Detaylı açıklamadan uzak              ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/siir-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyuncak Arabam', 'oyuncak-arabam-hamdi-oruc-ebpy6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oyuncak Arabam

Babam bana araba aldı

Bir oyuncak araba

Dünyalar sığıyor arabama

Dünyalara sığmıyor arabam

Rüyalarıma giriyor arabam

Yine rüyalarıma girsin arabam

Dolaşıyor rüyalardaki dünyayı

Çiçekler taşıyorum arabamla

Kelebekler taşıyorum arabamla

Bebekler taşıyorum arabamla

Koca koca dağları taşıyorum arabamla...

Hayatın yükünü taşıyacak oyuncak arabam...', 'Oyuncak Arabam Babam bana araba aldı Bir oyuncak araba Dünyalar sığıyor arabama Dünyalara sığmıyor arabam Rüyalarıma giriyor arabam Yine rüy...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Oruç']::text[], 8.5, '{"poet":"Hamdi Oruç","poet_slug":"hamdi-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/oyuncak-arabam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Almanya!', 'almanya-mesut-ozturk-ucsuk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerdeydin acı çektiğim zaman,

şimdi anlıyorum herşey tamam,

Bir hayal uğruna yaşanan o an,

Ekmeğim kalmadı acıktı gönlüm.

Açlığın ne olduğunu öğrendim nihayet,

Bir daha olursa paylaşırım elbet,

Bir kuruşum kalmadı, olursa şayet:

Yardım edeceğim, Hadi Mesut Yemin et.

Açlığı verdin bana öğrettin herşeyi,

Fakirliği yaşadım gördüm gerçeği,

Avrupanın merkezi olmuş Almanya,

Insanlık kalmamış teknoloji ne işe yarar ya!', 'Nerdeydin acı çektiğim zaman, şimdi anlıyorum herşey tamam, Bir hayal uğruna yaşanan o an, Ekmeğim kalmadı acıktı gönlüm. Açlığın ne olduğun...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/almanya-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazideki Sevgili', 'mazideki-sevgili-huseyin-ozcan-dc83j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen hayallerimde kalan sevgilinin aynısısın,

siyah saçlarını tarayışın da aynı…

başın öne eğikken,

kahküllerinin arasından bakışında.

teninin kokusu da aynıdır belki

koklayamadığım…..

sen,mazideki sevgilinin aynısısın.

onun için hala sana vurgunum,sana tutkun.

belki de sen o sun,

ya da o sendin,

zaman durdu belki,

belki,sen hiç gitmedin…', 'sen hayallerimde kalan sevgilinin aynısısın, siyah saçlarını tarayışın da aynı… başın öne eğikken, kahküllerinin arasından bakışında. tenini...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Özcan']::text[], 8.5, '{"poet":"Hüseyin Özcan","poet_slug":"huseyin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mazideki-sevgili-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elde Var Hüzün', 'elde-var-huzun-mehlika-tezcan-sedko', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elde var hüzün...

Dilimin ucuna geliyor da kelimeler çıkmıyor ağzımdan bir türlü,

Bilirim ki zehirli ok gibi saplanır yüreğine,

Yaralar seni içinden gelen dışarı vuramadıkların,

Yaşadıkların bir film şeridi gibi geçer gözlerinin önünden

Sözler yanardağ olur,lavlar püskürür hak etmediklerin,

İçten içe kahredersin, bir sen bilirsin içinde kopan fırtınaları

Acımasızdır hayat,acımasızdır bir zamanlar değer verip sevdiğin

Hoyratça kullanılmıştır duyguların,

Göz ardı edilmiştir karşılıksız verdiğin sevgin,

Kulakların duyduklarına inanamaz,gözlerin gördüklerine

Lal olur susar dil...

Elde var hüzün...', 'Elde var hüzün... Dilimin ucuna geliyor da kelimeler çıkmıyor ağzımdan bir türlü, Bilirim ki zehirli ok gibi saplanır yüreğine, Yaralar seni...', ARRAY['Türk Edebiyatı','Şiir','Mehlika Tezcan']::text[], 8.5, '{"poet":"Mehlika Tezcan","poet_slug":"mehlika-tezcan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/elde-var-huzun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Geldin Bebek', 'hos-geldin-bebek-i-smail-dogan-dwu0h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mevlam seni bize eyledi ihsan,

Anneye babaya düş oldun bebek.

İlk nefesde bastın feryadı vahsın,

....Gülpembe dünyaya hoş geldin bebek.

....Bağınan bahçeye hoş fidan bebek.

Ah bebek bir görsen dünya halini,

Ağlama hemen sil gözün selini,

Yüklü boyun borcu kırdı belini,

....Sıfırıı bol borca baş koydun bekek.

....Çalana, çırpana yaş fidan bebek

Hele bir fakirsen yazın kış olur,

Kuru soğan ekmek sana aş olur,

Güvendiğin dostun soğuk taş olur,

....Sefilliğe taze yoldaş geldin bebek,

....Meyvesi kurumuş boş fidan bebek.

Dünyanın malına duyarsan şehvet,

Alamazsın onu vermezsen rüşvet,

Yürek sızlar çöker başına kasvet,

....İşte o zaman da tuş oldun bebek.

....Herkesin yediği kuş fidan bebek.

Her yanın ısırgan otuyla dolu,

Bir dokunsan dağlar elinle kolu,

Çabuk büyü de göster doğru yolu,

....Şerlerin yoluna taş koyun bebek.

....Zalımlara çatık kaş fidan bekek.

DOĞANİ der dokuz ay koştun geldin,

İlk nefesden sonra gülmeyi bildin,

Zalımın boynuna borandan yeldin,

....Çalışıp kazanıp aş oldun bebek.

....Yokluğu kurutan baş fidan bebek.', 'Mevlam seni bize eyledi ihsan, Anneye babaya düş oldun bebek. İlk nefesde bastın feryadı vahsın, ....Gülpembe dünyaya hoş geldin bebek. .......', ARRAY['Türk Edebiyatı','Şiir','İsmail Doğan']::text[], 8.5, '{"poet":"İsmail Doğan","poet_slug":"i-smail-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hos-geldin-bebek-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüldüğüm tek birşey var?', 'uzuldugum-tek-birsey-var-mesut-ozturk-dn471', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaralı olan bu kalbime tuz basmaya mı? geldin.

Lanet olası kader sen bizi hep yendin.

Mücadele etmekten yorulmayacağım dedin,

Üzüldüğüm tek birşey var? 

Yavrularım yalnız kaldı.

Yıkılmadan durmak mı? imkansız değil.

Ey lanet olası kader ağlamak elimde değil.

Yeniden gülmek mi? Herhalde mümkün değil.

Üzüldüğüm tek birşey var? 

Yavrularım bensiz kaldı.

Nefret edemem ben, Onu hala seviyorum,

Hayat sana hergün kahrediyorum,

Birgün bende güler miyim? Bilmiyorum.

Üzüldüğüm tek birşey var? 

Yavrularım uzak kaldı.

Ben umudumu yitirmeyeceğim,

Nefret mi? Hiçbir zaman etmeyeceğim,

Gece gündüz seveceğim biliyorum ama? 

Ölene kadar yavrularım diyeceğim.', 'Yaralı olan bu kalbime tuz basmaya mı? geldin. Lanet olası kader sen bizi hep yendin. Mücadele etmekten yorulmayacağım dedin, Üzüldüğüm tek ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uzuldugum-tek-birsey-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Suçum Bu Olsa Gerek', 'tek-sucum-bu-olsa-gerek-yusuf-onder-bahceci-h0jjg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana yalan söylemedim,

Senle gönül eylemedim,

Seni sevdim diyemedim,

Tek suçum bu olsa gerek.

Gözlerim seninle güldü,

Gülmeyen bahtım güldü,

Dedim saçların sümbüldü,

Tek suçum bu olsa gerek.

Senin olsun sevdiklerin,

Benim gönül verdiklerim,

Bütün dualar, dileklerim,

Tek suçum bu olsa gerek.

Suçum neyse söyle bana,

Benim derdim yeter bana,

Ne çok sevdim anlasana,

Tek suçum bu olsa gerek...', 'Sana yalan söylemedim, Senle gönül eylemedim, Seni sevdim diyemedim, Tek suçum bu olsa gerek. Gözlerim seninle güldü, Gülmeyen bahtım güldü,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tek-sucum-bu-olsa-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orta Doğu', 'orta-dogu-muharrem-cetinkaya-k6w28', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ürdün,suriye,beyrut,şam

kim kimin yengesi

belli değil

yaktınız ortadoğu’yu

filistin’im bu ne çile

bu ne hüzün,bu ne gam! ! ! 

.

kuveyt,arabistan,ırak

kim kimin eniştesi

belli değil

bu ne kahpelik

bu ne kepazelik

bırak oğlum,

Irak çok ırak...

.

emirlikler,şeyhler,fas,mısır

kim kimin çocuğu

belli değil

yavrum,yavru vatanım

gıbrıs’ım

bu ne dölsüz politikalar

gelinde çocuk bol,,

oysa damat kısır..! ! !', 'ürdün,suriye,beyrut,şam kim kimin yengesi belli değil yaktınız ortadoğu’yu filistin’im bu ne çile bu ne hüzün,bu ne gam! ! !  . kuveyt,arabi...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/orta-dogu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atasözleri-I', 'atasozleri-i-muharrem-cetinkaya-wm6hj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“anasına bak

kızını al

kenarına bak 

bezini al”

__dediler

Baktım anasına; 

fingirdek mi fingirdek

kızı

İki dirhem bir çekirdek

baktım Kenarına

köşesine

bu zamana dek

bezi 

naylonmuş

çek Allah’ım çek!', '“anasına bak kızını al kenarına bak  bezini al” __dediler Baktım anasına;  fingirdek mi fingirdek kızı İki dirhem bir çekirdek baktım Kenarı...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/atasozleri-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumun Kirlerini Nil''de Yıkadım Dün Gece', 'ruhumun-kirlerini-nil-de-yikadim-dun-gece-nur-demirciler-vixc9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ruhumun kirlerini

Nil''de yıkadım dün gece,

Attım kini nefreti içimden,

Yeniden doğdum dün gece,

Nil’in kucağında.....

Ve gözlerimi  uzaklara kenetledim.

Nil’e demir attım dün gece sevdamı.

Suyun akışına karıştı sanki gözyaşım,

Sessizliğe boğuldu her yanım.

Bırak git dedim ne varsa geçmişte,

kendime.....

Git ve artık dönme geriye...

Hep ince bir sızı olsun içimde,

Söküp atamadığım,

Kırıp dökemediğim,

Sevip de vazgeçtiğim....

09/01/2006 

Aswan/Mısır', 'Ruhumun kirlerini Nil''de yıkadım dün gece, Attım kini nefreti içimden, Yeniden doğdum dün gece, Nil’in kucağında..... Ve gözlerimi  uzaklara...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ruhumun-kirlerini-nil-de-yikadim-dun-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Sevda', 'hayal-sevda-neslihan-uzel-8l4fw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayazın ortasına uyandım bu gün.

Yorgun, bezgin, kapkara

Nasılda üşümüş yıllardır yüreğim 

Usulca yağan sessiz karla.

Söylenmeyen ne çok söz varmış oysaki

Yarım kalan son cümleler, kırık dökük.

Hiç başlanmamışlar  hatta.

Bilmediğim diyarlarda,

Hiç bilmediğim ellerin, ellerimi ısıtmaz oldu

Çok uzakta martılar artık, 

Gülümsemiyor güneş yağmur bulutlarının arasından 

Üşüyorum ruhum, alışmışım  sevdana

Hiç görmediğim diyarlarda

Hiç görmediğim gözlerin, gözlerime bakmaz oldu.

Aşkımı yağmur sularına  bıraktım bir eylül akşamında

Söylenmemiş onca söz, hayal sevdamız

 Bir mevsim gibi gözden kayboldu.', 'Ayazın ortasına uyandım bu gün. Yorgun, bezgin, kapkara Nasılda üşümüş yıllardır yüreğim  Usulca yağan sessiz karla. Söylenmeyen ne çok söz ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Üzel']::text[], 8.5, '{"poet":"Neslihan Üzel","poet_slug":"neslihan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayal-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Danimarka''yı Tel''inimdir', 'danimarka-yi-tel-inimdir-alper-kuruk-qc1du', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana övgü yaraşır ki yakışmaz hakaret

İnsanlığa örneksin güzel adın:MUHAMMED.

Sana uzanan eller,diller lânetlendi hep

Onlara temsilcidir KUR''AN da Ebu Leheb.

Adınmış Danimarka edepsizliğin marka

Zannetme bulamazsın sana çıkacak arka.

MUHAMMED''in arkası ne ülkeler,ne silah 

O tek mükemmel insan,habib eyledi Allah...', 'Sana övgü yaraşır ki yakışmaz hakaret İnsanlığa örneksin güzel adın:MUHAMMED. Sana uzanan eller,diller lânetlendi hep Onlara temsilcidir KUR...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/danimarka-yi-tel-inimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takev Marşı', 'takev-marsi-i-smail-kocamaz-srgzm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yükseklerde gözlerimiz, uygarlıktır hedefimiz,

Vazgeçilmez öncelikle insanlığa hizmetimiz,

Bilim sanat uğraşımız, doğa içindir sevgimiz,

Çağdaş eğitimde önder, Özel TAKEV Okulları

Atatürk’ten alırız hız, dalgalanır bayrağımız,

Kardeşliktir ilk adımız, tüm dünyayı kucaklarız,

Güneş gibi ışık saçar, açıktır hep kapımız,

Çağdaş eğitimde önder, Özel TAKEV Okulları.

.', 'Yükseklerde gözlerimiz, uygarlıktır hedefimiz, Vazgeçilmez öncelikle insanlığa hizmetimiz, Bilim sanat uğraşımız, doğa içindir sevgimiz, Çağ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Kocamaz']::text[], 8.5, '{"poet":"İsmail Kocamaz","poet_slug":"i-smail-kocamaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/takev-marsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gayrı', 'gayri-mesut-ozturk-dohca', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canu sultanü barü hüdayu arayan gözüm,

Akıtma yaşlarını seli durdur dertlüm gayrı.

Duaların kabulü için kan bağlayan gözüm,

iyi olsun yaran, merhemini sür dertlüm gayrı.

çağır Yunus Emreyi yanan bağrıyla söylesin,

Allahını bilmeyen dost yanıma hiç gelmesin,

Kur-anıma söylüyorum, benim tek gayemsin,

Sus lal olmuş dilim ne olur Allah de gayrı.

Rabiam çıkmış dağlar başına, abası yırtılmış,

Mecnun Leyla için gözlerinden yaşlar akıtmış,

Kesiş Mirza keremden Aslı kızı kaçırmış,

Bilme zekam bunları gücüm kuvvetim yok gayrı,

Sırtımda abamla giderim birgün bu ellerden,

Kırılmaz kalbim dost zehir versede elinden,

Yaş döker mi? akranlarım kabrimde inceden inceden,

Dökmesin yaşını güller, söndü ateşim gayrı!', 'Canu sultanü barü hüdayu arayan gözüm, Akıtma yaşlarını seli durdur dertlüm gayrı. Duaların kabulü için kan bağlayan gözüm, iyi olsun yaran,...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gayri-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuduz köpekler', 'kuduz-kopekler-osman-taspinar-ge1mu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ya Sakarya,ya Fırat

Huzur bize çok ırak

Ülke elden gidiyor

Etmiyorsun hiç merak

Sol yanımdan Yunan''lı

Sağ yanımdan İran''lı

Göğsümü ataşlıyor

Dost bildiğim Irak''lı

Salata yemiş domuz

Benim diyor Akdeniz

Gizli planlar kuruyor

Fransız''la İngiliz

Gözü çıksın dünyanın

Hollanda''sı Alman''ın

İştahları kabarıyor

Amarika,Rusya''nın

Beşikte yatar bebekler

Saldırır kuduz köpekler

Analar yasın tutuyor

Göğe yükselir şehitler.', 'Ya Sakarya,ya Fırat Huzur bize çok ırak Ülke elden gidiyor Etmiyorsun hiç merak Sol yanımdan Yunan''lı Sağ yanımdan İran''lı Göğsümü ataşlıyor...', ARRAY['Türk Edebiyatı','Şiir','Osman Taşpınar']::text[], 8.5, '{"poet":"Osman Taşpınar","poet_slug":"osman-taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kuduz-kopekler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ç ile K', 'c-ile-k-ali-hakan-duz-s51rd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'düşünülen anları 

artakalan 

buruk sevinçlerinde biriktirir ''Ç'' 

çisil çisil yağmurdur 

akar can g i b i... 

damla gibi damlar canandır ''K'' 

akar şeklini alır mevsimin 

biriktirir okyanus rengini boşluğun 

ve bütünleşir bir resmin tuvalinde 

''Ç'' i l e ''K''... 

rengine boyar kırmızı, sevdalarını 

mevsimin en güzel meyvesi 

ki, denildiği an 

ilk onlar gelir akla 

uzak şehirlerin ıslak tatları gibi 

şekere sürünüp taşırlar a ş k ı... 

aşk''ın bir diğer t/adı da 

çisil çisil nağmeleri 

ve coşkusu sevinçlerinde saklı 

çoğalan aşklarındadır 

korkmadan t a ş ı d ı k l a r ı... 

ve mevsim baharın habercisi 

aşkı diğer adıyla çağrıştırır 

kısaca ''Ç'' i l e ''K''... 

*hissediyor/susuyordum... 

çok yakındın  biliyordum: içimde istiyordum, ç i l e k k o k u y o r d u n... 

Copyright © by ahd 

www.alihakanduz.com', 'düşünülen anları  artakalan  buruk sevinçlerinde biriktirir ''Ç''  çisil çisil yağmurdur  akar can g i b i...  damla gibi damlar canandır ''K'' ...', ARRAY['Türk Edebiyatı','Şiir','Ali Hakan Düz']::text[], 8.5, '{"poet":"Ali Hakan Düz","poet_slug":"ali-hakan-duz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/c-ile-k-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başçeşme', 'bascesme-mevlut-bicik-0i7qr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eğer günün birinde emri-hak vâki olursa

Vasiyetim olsun başçesmeye gömün beni

Can beden‘den ayrılır, hayat yok olursa

Vasiyetim olsun başçeşmeye gömün beni. 

Ölüm meleği  Azrâîl rûhumla  gittiğinde

Elimden,ayağımdan kuvvet gidip,bittiğinde

Dostların ikrâmı olan zemzemi içtiğimde

Vasiyetim olsun başçeşmeye gömün beni.

Yıllardır hayrânıyım başçeşmenin ben

Sevdikleriyle  yatmaya  râzî‘dir bu ten

Sevdiklerimse R. Adın ve H.Bâkır sen

Vasiyetim olsun başçeşmeye gömün beni.

Başçeşmenin hergün ziyâretcisi bol‘dur

Orada yatmak,dostlarla buluşmaya bir yol‘dur

Bu vasiyeti yazan elbette âciz bir kul‘dur

Vasiyetim olsun başçeşmeye gömün beni.

Mevlüt Bicik

03.02.2006  saat 15.43

Esslingen', 'Eğer günün birinde emri-hak vâki olursa Vasiyetim olsun başçesmeye gömün beni Can beden‘den ayrılır, hayat yok olursa Vasiyetim olsun başçeş...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bascesme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ACcı dünyam', 'acci-dunyam-osman-yagar-pupl5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir parça sevgi aradım

sevdiklerimden

Mutlu bir yuva aradım yuvamda

Canım dedim sevdiklerime

Bir damla sevgi görmedim sevdiklerimden.

Yanlız başıma kaldım

Elemler dünyasında,kan revan göz yaşlarımla

Köşe bucak geziyorumbelki karşılaşırım CANAN la diye

Küçük bir sevgi hecesi aradım.

Ne kötü talihim ve bahtım varmış

Tecrit edildim sevdiklerimden yana

Yanlız başıma kaldım acılar okyanusunda 

Sevdiremedim kendimi sediklerime

Esen sevgi lodosunda', 'Bir parça sevgi aradım sevdiklerimden Mutlu bir yuva aradım yuvamda Canım dedim sevdiklerime Bir damla sevgi görmedim sevdiklerimden. Yanlız...', ARRAY['Türk Edebiyatı','Şiir','Osman Yağar']::text[], 8.5, '{"poet":"Osman Yağar","poet_slug":"osman-yagar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/acci-dunyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler (113) '' Başımda Sevda Yeli...''', 'maniler-113-basimda-sevda-yeli-abdullah-atay-3l5p4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başımda sevda yeli

Esiyor deli deli

Eriyen muma döndüm

Yarim benden gideli...

Bir yar sevdim işveli

Şen şakrak ve neşeli

Çıra gibi yanıyom

Ben bu aşka düşeli...

Sevda gelince başa

Yürek düşer  ataşa

Cenneti de verseler

Yarimin yeri başka...

Ben baharı neyleyim

Yar yanımda olmazsa

Nerde gönül eyleyim

Gönül yari bulmazsa...

Gönül yarsız olunca

Baharlarım kış olur

Nazlı yarim gelince

Yüreciğim hoş olur...

Sensin yüzüm güldüren

Gönül sazım çaldıran

Hançer kurşun değil de

Veda sözün öldüren...

Alna yazılmış kader

Günü gelenler gider

Ecel başa geldi mi

Genç yaşlı ne fark eder...

Düşse gönül dengine

Yürek düşmez yangına

Bu dünyada hep rağbet

Güzel ile zengine...', 'Başımda sevda yeli Esiyor deli deli Eriyen muma döndüm Yarim benden gideli... Bir yar sevdim işveli Şen şakrak ve neşeli Çıra gibi yanıyom B...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/maniler-113-basimda-sevda-yeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Ölmem (!)', 'artik-olmem-muharrem-cetinkaya-bt33k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'içini boşalttınız kelimelerin

-yalan duygularla-

artık dokunmuyor 

kurşun gibi

hiç biri 

duygulu yüreğime

vurun

artık ölmem! 

.

içini boşalttınız sevgilerin

-yalan sözlerle-

artık aşık olunmuyor

kirli akıyor ırmaklar

yıkanmanız nafile

arıtamazsınız hiç birini

yalancı gönüllerin! 

artık sevmem!', 'içini boşalttınız kelimelerin -yalan duygularla- artık dokunmuyor  kurşun gibi hiç biri  duygulu yüreğime vurun artık ölmem!  . içini boşalt...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/artik-olmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık İnanmıyorum Ben', 'artik-i-nanmiyorum-ben-yusuf-onder-bahceci-sfoc8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin şu kara gözlerine,

Sevdim dersin sözlerine,

Beni çok seven yüreğine,

Artık inanmıyorum ben.

Gözlerime bir bak dersin,

Seven yüreği yak dersin,

Ondan sonra da gidersen,

Artık inanmıyorum ben.

Gönül seni sevmiş dersin,

Ben murada erdim dersin,

Çocuklar gibi de küsersin,

Artık inanmıyorum ben.

Bu oyunlardan bıktım artık,

Gözüm seni görmez  artık,

Bende ümit kalmaz artık,

Artık inanmıyorum ben....', 'Senin şu kara gözlerine, Sevdim dersin sözlerine, Beni çok seven yüreğine, Artık inanmıyorum ben. Gözlerime bir bak dersin, Seven yüreği yak...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/artik-inanmiyorum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Sevenler İçin', 'her-sey-sevenler-i-cin-mustafa-karamelek-0me7g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'HER ŞEY SEVENLER İÇİN

Sen benim her şeyimsin

Ben senin hiçbir şeyin

Benim her şeyim var

Senin hiçbir şeyin..

Yaşadığım gerçek masalda

Sen canan ben yanan

Benim külüm közüm var

Senin hiçbir şeyin yok…

Mustafa KARAMELEK', 'HER ŞEY SEVENLER İÇİN Sen benim her şeyimsin Ben senin hiçbir şeyin Benim her şeyim var Senin hiçbir şeyin.. Yaşadığım gerçek masalda Sen ca...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/her-sey-sevenler-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yazar', 'ne-yazar-yusuf-onder-bahceci-g92lr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya''nın en güzel şiirlerini,

En güzel şiirlerini yazsam,

Sen bu şiirleri okumadıktan,

Okumadıktan sonra ne yazar....', 'Dünya''nın en güzel şiirlerini, En güzel şiirlerini yazsam, Sen bu şiirleri okumadıktan, Okumadıktan sonra ne yazar.......', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-yazar-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldi geçti', 'geldi-gecti-omer-dalman-bikr1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Orada

her zamankinden daha kuvvetli

ve daha net

seninle olmak...

kendimin üzerinde oturmak

başkalaşmak

’olması gereken’ olmak...

sonra

tekrar eve dönersem

ki önemi yok

’bir başka ben’ olmak...

yeni giyisilerimi kuşanmış olarak

İnsandan da öte...

gerisini boş ver

hepsi geldi, geçti...

(Mayıs 2005)', 'Orada her zamankinden daha kuvvetli ve daha net seninle olmak... kendimin üzerinde oturmak başkalaşmak ’olması gereken’ olmak... sonra tekra...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geldi-gecti-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Baş, Küçük Baş', 'buyuk-bas-kucuk-bas-omer-dalman-x6nmt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Büyük Baş, Küçük Baş bizim için fark etmez! 

Bıraktığı pisliğe, ezdiği çimene göre durumu değerlendiririz biz! 

Zararın büyüğünü de küçüğünü de bir görür

gerekenin fişini çekeriz biz! 

Büyük Baş, Küçük Baş bizim için fark etmez

bir kere bu toprağı kirlettimi gafilin teki

damgamızı vururuz biz! 

Biz çoktan iptale uğramışız kendi ortamımızda

kaybedecek bir şeyimiz kalmamışken

bir baş eksilmiş, bir baş eklenmiş

hiç fark etmez

gerekenin fişini çekeriz biz! 

Büyük Baş, Küçük Baş bizim için fark etmez.

Herkesin iki bacağı, iki kolu, bir gövdesi ve başı yok mu? ! 

Sarayda da yaşasa

ayağını çamura

elini soğuk suya koymasa da

sonuçta evine dönmüyor mu? 

O kapıdan içeri girmiyor mu? 

Mutlaka bir yerde bulur

biletini keseriz biz! 

İnsan değil misin sonuçta yeğenim? 

Kendine hakim ol

yanlış yapma! 

Büyük Baş, Küçük Baş bizim için fark etmez…', 'Büyük Baş, Küçük Baş bizim için fark etmez!  Bıraktığı pisliğe, ezdiği çimene göre durumu değerlendiririz biz!  Zararın büyüğünü de küçüğünü...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/buyuk-bas-kucuk-bas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Başka Sevmedim', 'senden-baska-sevmedim-yusuf-onder-bahceci-x5puy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana bakan şu gözlerim,

Senden başka görmüyor,

Seni sevdim be güzelim,

Senden başka sevmiyor.

Senin yollarına ölen ben,

Benim çağırmadan gelen,

Gözlerine hep bakıp gülen,

Senden başka sevmedim.

Ben bülbülüm gül dalında,

Seni sevdim her halimda,

Söyle benim günahım ne,

Senden başka sevmedim...', 'Sana bakan şu gözlerim, Senden başka görmüyor, Seni sevdim be güzelim, Senden başka sevmiyor. Senin yollarına ölen ben, Benim çağırmadan gel...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senden-baska-sevmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlham baharla gelir? ..', 'i-lham-baharla-gelir-omer-dalman-dybe4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '’İlham baharla gelir’ diyenler ne çoktur.

Peki

o soğuk, ıslak, karanlık günlerinde

burnumuza, keskin kokusuyla

dağların tazeliğini getiren,

ruhumuzu

o sağnaklı fırtınalarla yalanmış tepelere doğru

şehrin üzerinden alçak uçuşlarla

seyahate yollayan havanın

sert tavırlarından kurtulup, içeri girince

camın arkasından

bir güven ve keyif içinde

bütün sokaklar sırılsıklam ıslanırken

kendini bize seyrettiren

                            o ‘kış’a ne demeli? ! ..

Koca bir sene oturup

’bahar gelsin’ diye beklemek

hava somurtuyor diye ‘gri-gri’

                     başını öne eğmek mi yaratıcılık? 

’İlham Sahibi’ kendini bahara mı teslim etti? ! 

kış uykusuna mı yattı? ! 

”İlham baharla gelir.” diyenler

sakın uyuşukluğa ve sekse susamış olmasınlar! ? 

’Gerçek İlham Sahibi’! 

sakın kış uykusuna yatma! 

(Nisan 2005)', '’İlham baharla gelir’ diyenler ne çoktur. Peki o soğuk, ıslak, karanlık günlerinde burnumuza, keskin kokusuyla dağların tazeliğini getiren, ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ilham-baharla-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçmez miydim? !', 'i-cmez-miydim-omer-dalman-ojj0p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne oldu şimdi? ! 

Al işte

her türlü sorumluluğa rağmen omuzlarımdaki

leş gibi

yavaş yavaş

kadeh kadeh

zevkine vara vara

yavşaya yavşaya

kırmızı şarap içiyorum yine! 

Ne oldu ki bana en büyük nasibi vermedin de? ! 

Verseydin de böyle leş gibi olmaz mıydım? 

Sarhoşluğuna, güzelliğine, enginliğine

anlaşılmazlığına denk olmak için

yine içmez miydim kırmızıyı ‘leş’ gibi? ! 

yakmaz mıydım puroları püfür püfür? ! 

İster mal ver, ister mülk

ister aşk ver, ister sevgi

ister en büyük afeti

veya kendi sonumu

                en acılı yoldan

veya ne olurdu ki

hiç bir şey vermeseydin? ! 

yine içmez miydim kırmızıyı leş gibi

sarhoşluğuna, güzelliğine, enginliğine

anlaşılmazlığına denk olmak için? ! 

İçmez miydim? ..

(Nisan 2005)', 'Ne oldu şimdi? !  Al işte her türlü sorumluluğa rağmen omuzlarımdaki leş gibi yavaş yavaş kadeh kadeh zevkine vara vara yavşaya yavşaya kırm...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/icmez-miydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimlerim ve Sen....', 'mevsimlerim-ve-sen-pinar-koc-5gmol', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Önce ilk bahar geldi,

Baharın ilk çiçeklerini

Görür gibi oldum,engin derin gözlerinde...

Yanaklarında 

Kırmızı gül tomurcukları yakaladım

Senden hiç izin almadan kokladım 

Ve ciğerlerime doldurdum

Misk-ü amber kokularını...

Sonra sıcacık bir yaz 

Ve sıcacıktı gülüşün! 

Ve sıcacıktı gözlerindeki sevinç...

Terlemiş vücudundan

Kana kana sıcaklığını içiyordum! 

Sana doyabilmek için

Gözlerinden hiç ayırmıyordum gözlerimi! 

Sonra serin bir sonbahar ve

Yaprak dökümü başladı...

Sonbahar bizim için değildi aslında! 

Biz hiç düşmedik daldan! 

Sevgi aynı sevgi,

Aşk aynı aşktı...

Ne sonbahar ne kış

Bizi hiçbir şey indiremez 

Bu mutluluk dağından....

                                                                         06.10.2002   pazar', 'Önce ilk bahar geldi, Baharın ilk çiçeklerini Görür gibi oldum,engin derin gözlerinde... Yanaklarında  Kırmızı gül tomurcukları yakaladım Se...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mevsimlerim-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '21. Yüzyıl!', '21-yuzyil-mesut-ozturk-hmrfn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dinleyin dostlar sizlere birşeyden bahsedeceğim,

Belki yıllar öncesine belkide ileri gideceğim,

Bir cevher ki benim ceddim, ben onların derdindeyim.

Ne gökler, ne denizler nede yerler ağlar,

21.yüzyıl her yaşlının dertli bağrını dağlar.

Evlat dinlemez sözünü, başına kalkar parasını,

Kimi bir odaya hapseder,kimi atar anasını,

Asrın verdiği delilikle tanıyamaz atalarını,

Ne diller, ne sazlar nede vicdanlar ağlar,

21.yüzyıl her yaşlının dertli bağrını dağlar.

Kimi terketmek ister, köyünü, yolunu ocağını,

Kimi bıkar yaşamdan yük eder tatlı canını,

Kiminin mirası mutlu etsede evlatlarını,

Ne evlat, ne kardeş, nede akranlar ağlar,

21.yüzyıl her yaşlının dertli bağrını dağlar.

Bazen gözler pınar olur katılır dildeki ağıta,

çizgi dolan çehreler, alay olur torunlara,

Binbir manayla bakılır yorgun düşük omuzlara,

Ne yürekler, ne gönüller, nede gözler ağlar,

21.yüzyıl her yaşlının dertli bağrını dağlar.

Huzur eviymiş bilmem hertür konfor içinde,

Spor müzik herşey gönlüne göre,

Neylesin gariban o küsmüş herhezlere,

Ne eller derdini duyar, ne feryadına ağlar,

21.yüzyıl her yaşlının dertli bağrını dağlar.

Kuytu bir köşede seccade serilsede yerlere,

Hor görülmeyelim diye girilsede gönüllere,

Asra uymak zor gelir, yazık uysun diyenlere,

Yaşlımın dertlerine bütün yıllar ağlar,

21.yüzyıl her yaşlının dertli bağrını dağlar.

Ben elele verdiğimiz akranlarıma sesleniyorum,

Onları yaşlılara saygıya davet ediyorum,

Biz bir ömür boyu gençmi kalacağız diyorum,

Ne sözler ne diller, nede gönüller ağlar,

21.yüzyıl her yaşlının dertli bağrını dağlar!', 'Dinleyin dostlar sizlere birşeyden bahsedeceğim, Belki yıllar öncesine belkide ileri gideceğim, Bir cevher ki benim ceddim, ben onların derd...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/21-yuzyil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbet', 'elbet-aylin-onder-4rw1j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzaklarımda çırpınan yaprakların

Sesleri karışıyor; 

Damla damla düşüp yüreğinde yankı bulan sevdaya.

Ne volkanlar sönüp,

Ne depremler yaşanıyor tenimde 

Senden ayrı kaldığım her dakika.

Bir sürü faili meçhul geçiyor yanımdan

İnan o zaman; 

Kan değil kor akıyor damarlarımdan.

Kristelleşen sulara basıyor ayaklarım

Ve aynı şişede balık oluyorum,,,

Oltalara gönüllü takılan.

Topluyorum; 

Tutuyorum bir ucundan,bir hayalimi daha kaldırıyorum

Mahsene,yıllanmış olanların yanına.

Belki bir mutluluk akşamında,

O kurtulur çeker alırım aralarından.

Ne hoş olurdu onun sarhoşluğu ya neyse...

Yine başka baharlara.....

Elbet bizde görürüz dişlerini, 

Dudaklarının arasından kaderin...

Elbet sebebi halimi anlar göz bebeğimden...

Elbet bilir geleceğini güzel günlerin...

Elbet sabreder gönül...

Vazgeçilmezdi bu kadar beklemişken', 'Uzaklarımda çırpınan yaprakların Sesleri karışıyor;  Damla damla düşüp yüreğinde yankı bulan sevdaya. Ne volkanlar sönüp, Ne depremler yaşan...', ARRAY['Türk Edebiyatı','Şiir','Aylin Önder']::text[], 8.5, '{"poet":"Aylin Önder","poet_slug":"aylin-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/elbet-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma', 'korkma-i-lknur-er-1fk98', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Titriyorsun içimde

Korkma açmam demir parmaklıkları

Sen istesende göndermem seni benden

Bulmaya çalışıyorum sadece kendimi

Seni gördüğümde kaybettiğim benliğimi arıyorum', 'Titriyorsun içimde Korkma açmam demir parmaklıkları Sen istesende göndermem seni benden Bulmaya çalışıyorum sadece kendimi Seni gördüğümde k...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/korkma-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikanlıydın Vesselam', 'delikanliydin-vesselam-muharrem-cetinkaya-zntdr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'delikanlı kızdın

o yüzden

ben hep seni yirmibir yaşında görürüm

şimdiki gibi pantolon giymezdin

hani lacivert puanlı

boydan bir elbisen vardı ya

içinde

dipdiri dururdun…

en güzel kız sendin

saçların kumraldı

boyamayı bilmezdin saçlarını

şimdiki gibi

bilsen de boyamazdın zaten

ve

hiç beğenmezdin benim taradığımı

kendin yapar-yakıştırırdın

çok ta güzel olurdun…

.

delikanlı kızdın

vesselam

bakışlarında yüreğinin içi görünürdü

sözün_yüreğin

yüreğin_gözündü

şimdiki gibi

yalan bilmezdi bakışların…

.

iste o yüzden ben seni hep

yirmibir yaşında bilirim

ellerin yüreğin gibi sıcak

yüreğin coşkun akan ırmaklar gibi

dökülür

söndürürdü gönlümde yanan ateşi

şimdiki gibi

kurumuş bir şelale değildi

vefasız gönlün….

.

ve ben seni hep yirmibir yaşında

yaşatırım

her gün konuşup

dertleştiğin

saksıdaki çiçekte

elimi cebime attığımda

yaktığım her sigaranın

hayalini çizdiğim dumanında

ve

elimde kazma-kürek

her gün taze bir mezar açar

yirmibir yaşında 

delikanlı bir kız gömerim…

[email protected]', 'delikanlı kızdın o yüzden ben hep seni yirmibir yaşında görürüm şimdiki gibi pantolon giymezdin hani lacivert puanlı boydan bir elbisen vard...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/delikanliydin-vesselam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-tarik-yasin-3c6gu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden ben ki ben olan beni benden aldınız 

Niye almak yerine vermeyi tercih etmediniz 

Neden vermeyipte verenlerden verenide vermiyenden aldınız

Şimdi söyleyin ben mi yoksa beni bende olana mı sormak lazım', 'Neden ben ki ben olan beni benden aldınız  Niye almak yerine vermeyi tercih etmediniz  Neden vermeyipte verenlerden verenide vermiyenden ald...', ARRAY['Türk Edebiyatı','Şiir','Tarık Yasin']::text[], 8.5, '{"poet":"Tarık Yasin","poet_slug":"tarik-yasin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/neden-217-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '21. Yüzyıl! 1', '21-yuzyil-1-mesut-ozturk-xw5pr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Huzur eviymiş bilmem hertür konfor içinde,Spor müzik herşey gönlüne göre,Neylesin gariban o küsmüş herhezlere,

Ne eller derdini duyar, ne feryadına ağlar,21.yüzyıl her yaşlının dertli bağrını dağlar.

Kuytu bir köşede seccade serilsede yerlere,Hor görülmeyelim diye girilsede gönüllere,Asra uymak zor gelir, yazık uysun diyenlere,

Yaşlımın dertlerine bütün yıllar ağlar,21.yüzyıl her yaşlının dertli bağrını dağlar.

Ben elele verdiğimiz akranlarıma sesleniyorum,Onları yaşlılara saygıya davet ediyorum,Biz bir ömür boyu gençmi kalacağız diyorum,

Ne sözler ne diller, nede gönüller ağlar,21.yüzyıl her yaşlının dertli bağrını dağlar!', 'Huzur eviymiş bilmem hertür konfor içinde,Spor müzik herşey gönlüne göre,Neylesin gariban o küsmüş herhezlere, Ne eller derdini duyar, ne fe...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/21-yuzyil-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik 42 (teslim oluyorum)', 'lirik-42-teslim-oluyorum-fevzi-cebe-mos25', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben teslim oluyorum

peki sen, alabilir misin

ellerim yukarıda değil

başım dik, bakarken sana

ama sen? 

sen hazır mısın bu(a) na

yorgun gözkapaklarımın altından

bakarken sana

gözkapaklarım düşmeden

girebilecek misin içeriye

şahit edebilecek misin 

sessizliği 

tanıklığımıza

bu anı mühürlemeye

şahit edebilecek misin

sessiz kalmış kadimliği

...

sabahlayan hayallerim

şövalye olarak mı doğdum

ne farkeder

beni çeken ne gidemediğim noktaya

sesine hayranım

büyüledin

değişik bedenlerden çıksa da

bu güzel hem

ben sesini takip ediyorum

belki aklında bile değilim

sana dokunamasam da

soluğum tenine şekil vermeli

29.01.2005 gece yarısının sırtları – 30.01.2005 14.45', 'ben teslim oluyorum peki sen, alabilir misin ellerim yukarıda değil başım dik, bakarken sana ama sen?  sen hazır mısın bu(a) na yorgun gözka...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Cebe']::text[], 8.5, '{"poet":"Fevzi Cebe","poet_slug":"fevzi-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/lirik-42-teslim-oluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni narlar beni korlar yandırır', 'seni-narlar-beni-korlar-yandirir-hayri-arikan-serdaroglu-l29kb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevda bahçesinin bağbanı olsan 

Seni bülbül beni güller yandırır.

Dostun hanesine destursuz gelsen.

Seni yollar beni eller yandırır.

Bülbüle cefadır hep gülün nazı.

Bülbül ağlar hep güledir niyazı.

İnleyen aheden aşığın sazı.

Seni teller beni diller yandırır.

Sensin gönlümdeki dinmeyen sızı.

Sensin bu alnıma yazılan yazı.

Turan ülkesinin uslanmaz kızı.

Seni narlar beni korlar yandırır.

İşte böyle gönül mülkü tarumar.

Serdaroğlu yardan bir sevgi umar.

Sevgi masasında oynarsan kumar

seni dürler beni pirler yandırır

 Hayri Arıkan (Serdaroğlu)', 'Sevda bahçesinin bağbanı olsan  Seni bülbül beni güller yandırır. Dostun hanesine destursuz gelsen. Seni yollar beni eller yandırır. Bülbüle...', ARRAY['Türk Edebiyatı','Şiir','Hayri Arıkan (Serdaroğlu)']::text[], 8.5, '{"poet":"Hayri Arıkan (Serdaroğlu)","poet_slug":"hayri-arikan-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-narlar-beni-korlar-yandirir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel', 'bedel-aylin-onder-b7iai', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne demeli halden anlamayan kuluna

Ne anlatayım da yormasın daha fazla 

Cananı cana sarmaya bedel nereye kadar

Nereye kadar dayanır yastığım bu göz yaşlarına 

Sormasın diye ömrüm mahşerde 

Çektiklerinin bedelini illa dünyada ayrılık mı gerekli

Sarıp sarmalamalı bu yası

Akan sulara def etmeli...', 'Ne demeli halden anlamayan kuluna Ne anlatayım da yormasın daha fazla  Cananı cana sarmaya bedel nereye kadar Nereye kadar dayanır yastığım ...', ARRAY['Türk Edebiyatı','Şiir','Aylin Önder']::text[], 8.5, '{"poet":"Aylin Önder","poet_slug":"aylin-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bedel-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderler...!', 'giderler-hasan-basri-kale-nskh5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'geldim gitmemecesine der giderler

sevdim unutmamacasına der giderler

gün gelir kırıp dökerler gönlü derinden

eyvah...! der pişman olup giderler...

**bakî kalan bu kubbede bir hoş sada imiş....!', 'geldim gitmemecesine der giderler sevdim unutmamacasına der giderler gün gelir kırıp dökerler gönlü derinden eyvah...! der pişman olup gider...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/giderler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllardır halkını sömüren beyler', 'yillardir-halkini-somuren-beyler-mikdat-bal-tk33n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllardır halkını sömüren beyler

Çatlasın mideniz, doymaz mısınız? 

Fakirin hakkını kemiren beyler

Onların ahını duymaz mısınız? 

İçinizde yok mu doğru kişiniz? 

Köşe dönmecedir sizin işiniz

Çalmaya alettir makbuz fişiniz

Yalanı hırsızlık saymaz mısınız? 

Kalemle bol yazıp çalıyorsunuz

Diğer yandan rüşvet alıyorsunuz

Veballer altında kalıyorsunuz

Bir dine kitaba uymaz mısınız? 

Böyle büyük cürmü kodes mi paklar 

Kan irin olası çalınan haklar

O bunu aklıyor, bu onu aklar

Bu ahlaksızlıktan caymaz mısınız? 

Mikdat der bu millet bilmez zannedin

Hesabı sorulur her ihanetin

Bu meydan sizindir günü gün edin

Bir gün o koltuktan kaymaz mısınız?', 'Yıllardır halkını sömüren beyler Çatlasın mideniz, doymaz mısınız?  Fakirin hakkını kemiren beyler Onların ahını duymaz mısınız?  İçinizde y...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yillardir-halkini-somuren-beyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Depresyon Masalı!', 'bir-depresyon-masali-mesut-ozturk-udsb5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşadıklarımı, gördüklerimi, başka insanlarla paylaşmak, anlatamadıklarımı bir kağıta dökmek, eskiden beri bende bir alışkanlık olmuştu, ağladığım zamanları, sevindiğim anları bu kağıt ve kalemimle paylaşmayı sanki bir görev gibi bilmiş ve herşeyimi şiirlere dökmüştüm.

Gece karanlığının yerini Güneşin ışıklarına bıraktığı, dağların zirvesinden ve denizlerin derinliklerinden gelen sis tanelerinin Güneşin sıcağından kaçtığı, şu minicik canlıların bile şen şakrak oynaştığı, çiçeklerin rengarenk açtığı,

şu bahar sabahında, ben neden burdayım? Ben nerede yanlış yaptım? 

Yapılanlarda ne kadar haklı yada suçluydum? Bilmiyorum ama! Bildiğim birşey var? Ben yanlızım hemde yapayalnız.

Ne yapayım? Ne anlatayım? Acı çekmek acıyı yaşamak, duyduklarımıza üzülmek, gördüklerimize ağlamak tam bizim yapımız.

Hep depresyon müzikleri dinleyecek değiliz ya! 

Birazda depresyon şiirleri okuyalım. Bizim kanımızda var. Buyrum benim depresyonlu Dünya`ma Hoşgeldiniz!', 'Yaşadıklarımı, gördüklerimi, başka insanlarla paylaşmak, anlatamadıklarımı bir kağıta dökmek, eskiden beri bende bir alışkanlık olmuştu, ağl...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-depresyon-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-murat-gulener-smtzq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinden akan bir damla yaşı

Başından düşecek bir tel saçı

Verme kimseye o güzelim yılları

Onlar benim için unutulmaz bir anı

Anılarla dolup taşarken gönlüm

Aklımda hep sen varsın kara gözlüm

Bir yüzükle oldun benim sözlüm

Güneş gibi bitanesin ayyüzlüm

O savrulan saçlarında

O sevdiğim bakışlarında

Uzatmadığın o kollarında

Sabahlamak istiyorum', 'Gözlerinden akan bir damla yaşı Başından düşecek bir tel saçı Verme kimseye o güzelim yılları Onlar benim için unutulmaz bir anı Anılarla do...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdigim-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuz', 'otuz-yunus-isikoglu-j9zkj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Otuz 

Sen nesin? 

Ben 

Ay sonu bekçisi

Gel bu isten vazgec

Hayır gecemem

Takılmışım ay sonuna

Ben olmasam

eylül ekim

Tüm aylar birbirine girer

Dur derim ay a ben

korurum onu kollarım

Giden ay gidisine üzülür

Ben de terkederim zaten onu 

Gelen ay sevinir

Ben de onun la olurum

İste böyle

Yillar boyu yuvarlanır giderim

Su ay senin bu ay benim

Gezer dururum

Umurumda mı dünya

Zaten o dönecek

Beni de mecburen taşıyacak

Sevinen de olacak

Üzülen de', 'Otuz  Sen nesin?  Ben  Ay sonu bekçisi Gel bu isten vazgec Hayır gecemem Takılmışım ay sonuna Ben olmasam eylül ekim Tüm aylar birbirine gir...', ARRAY['Türk Edebiyatı','Şiir','Yunus Isikoglu']::text[], 8.5, '{"poet":"Yunus Isikoglu","poet_slug":"yunus-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/otuz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Senle Olmak İstiyor', 'canim-senle-olmak-i-stiyor-murat-gulener-pyfvo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çile çekmek için mi geldim dünyaya

Mutluluk benim için ancak rüyada

Gözlerim kapanmadan yalan dünyaya

Gel artık canım senle olmak istiyor

Yağmurda ıslanmış bir garip gibiyim

Evsiz barksız yuvasız berduş gibiyim

Dertten acıdan sarhoş ayyaş gibiyim

Gel artık canım senle olmak istiyor', 'Çile çekmek için mi geldim dünyaya Mutluluk benim için ancak rüyada Gözlerim kapanmadan yalan dünyaya Gel artık canım senle olmak istiyor Ya...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/canim-senle-olmak-istiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla', 'beni-hatirla-murat-gulener-gez57', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir şarkı duyarsan sevdadan yana

Bir şiir okursan gözyaşı dolu

Ve hüsran olursa her aşkın sonu

Beni hatırla sevdiğim

Bir çiçek görürsen boynunu bükmüş

Bir ağaç görürsen yaprağını dökmüş

Birine rastlarsan genç yaşta ölmüş

Beni hatırla sevdiğim', 'Bir şarkı duyarsan sevdadan yana Bir şiir okursan gözyaşı dolu Ve hüsran olursa her aşkın sonu Beni hatırla sevdiğim Bir çiçek görürsen boyn...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beni-hatirla-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
