INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyüş', 'yuruyus-suna-onur-fo77u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'geçtiğim yol bakışların, 

hal yağmurlu, dalgın bulutlar, 

yapraklar yorgun, sırılsıklam... 

gözlerin, şemsiyem, parkam, 

sen sığnak... 

ten buruk ve yara, 

yol uzun, boyalı bağlar, 

dağ, taş, sağnak... 

şeffaf bir ev dünden uzak, 

başaklar engin, kalemim orak, 

gök zengin, taze toprak, 

ve ben bu yolda hep ıslak...', 'geçtiğim yol bakışların,  hal yağmurlu, dalgın bulutlar,  yapraklar yorgun, sırılsıklam...  gözlerin, şemsiyem, parkam,  sen sığnak...  ten ...', ARRAY['Türk Edebiyatı','Şiir','Suna Onur']::text[], 8.5, '{"poet":"Suna Onur","poet_slug":"suna-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuruyus-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz', 'i-simsiz-suna-onur-lpaxc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ışık silsilesi ve yansıma 

ümitle çekilen arayış yükü; 

boşluk, karanlık ve bahçe... 

gölgeli dilde ağaçlar soğuk. 

varlıktaki ziya, 

ışık silsilesi ve yansıma 

günün dönüşü, askıda akşam... 

kayan bulut zaman, 

yürek renginde aşk, 

bahara bürünmüş yaş, 

sonu taş susuzluğun. 

kaygan bulut zaman, 

sınırı sonsuzluğun aşk. 

(2005/İstanbul)', 'ışık silsilesi ve yansıma  ümitle çekilen arayış yükü;  boşluk, karanlık ve bahçe...  gölgeli dilde ağaçlar soğuk.  varlıktaki ziya,  ışık s...', ARRAY['Türk Edebiyatı','Şiir','Suna Onur']::text[], 8.5, '{"poet":"Suna Onur","poet_slug":"suna-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/isimsiz-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşim gücüm yok bi de oturup şiirmi yazacağım sana', 'i-sim-gucum-yok-bi-de-oturup-siirmi-yazacagim-sana-ugur-koroglu-96zzr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'işim gücüm yok bi de oturup şiirmi yazacağım sana.

Sanki yazmayı biliyormuşum gibi.

Hiç beceremem iki kelimeyi bi araya getirmeyi.

Öyle kafiye falan hiç işim değildir.

Becerebilsem yazardım inan.

En azından denerdim.

İçinde aşk geçerdi şiirlerimin.

Gözlerinden bahsederdim.

Her bakışta ayrı anlam taşıyan gözlerinden.

Ama beceremiyorum işte şiir yazmayı.

Becerebilseydim eminim yazardım.

Özlediğimi söylerdim seni her fırsatta,

Verdiğin huzurdan bahsederdim.

Yok işte olmuyor.

Şiir felan yazamam ben.

Becerebilseydim inan yazardım.

İyisimi bu seferlik affet sen beni.

Bir dahakine yazarım söz.

Aklında bi yerlerde kalsın şu sözler,

En beceriksiz halimle Seni Seviyorum..', 'işim gücüm yok bi de oturup şiirmi yazacağım sana. Sanki yazmayı biliyormuşum gibi. Hiç beceremem iki kelimeyi bi araya getirmeyi. Öyle kafi...', ARRAY['Türk Edebiyatı','Şiir','Uğur Köroğlu']::text[], 8.5, '{"poet":"Uğur Köroğlu","poet_slug":"ugur-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isim-gucum-yok-bi-de-oturup-siirmi-yazacagim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öfke', 'ofke-reyhan-tataroglu-m4zet', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey! Sevgili... 

                              ne bir el uzanabilir

                              Sana

                              ne bir dil

                              hangi küstah bu

                              çekil çekil...', 'Ey! Sevgili...                                ne bir el uzanabilir                               Sana                               ne bir d...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ofke-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Karga İle Tilki', 'yeniden-karga-i-le-tilki-suna-onur-davgv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YENİDEN KARGA İLE TİLKİ   

Hava  sıcaktı, yapraklar üzerindeki çiğ damlaları esrik bir edayla kıvrıla kıvrıla buhar olurken, yoldan açlıktan takati kesilmiş, kuyruğunu kısmış, bir tilki daha çok sürünmeye benzeyen halde yürümekte ve kendi kendine söylenmekteydi:

   -Günlerdir açım. Hep tembelliğimin cezasını çekiyorum. Şu karıncalara gıpta etmemek elde değil. Keşke biraz daha büyük olsalardı, hem kendilerini hem de biriktirdiklerini yerdim. Allah kimseyi açlıkla terbiye etmesin.

   Tüylü çenesini mecalsizce, mırıltılarla hareket ettirerek, hiç susmayan bebek gibi ağlayan karnının sesini duya duya dolaşıyordu; o kadar dolaşmıştı ki, dermansız, bir ağacın altına içi boş çuval gibi yığılıp kaldı. Yarı baygın gözlerini açlığını uykuyla bastırmak için kapatmaya çalışırken bir dal hışırtısı kulaklarına umut tohumları attı. Hızla filizlenen ses tilkinin başını doğrulttu, yukarı baktı tilki, bir de ne görsün; kendi fikirleri kadar kara bir karga, ağzında da peynir, tilkinin midesi genişliğinde.

   Aniden bir canlanma geldi kaslarına, doğruldu ve konuşmaya başladı:

   -Hu hu, karga kardeş! 

   -Efendim! 

   -Adım İlki. Nasılsın iyi misin, buralarda oturuyorum ben, yeni misin sen? 

   -Yoo, komşu sayılırız. Seni yukarılardan gördüm birkaç defa. Ayrıca iyiyim, dinleniyorum.

    Sen nasılsın? Yorgun görünüyorsun biraz.

   -Sıcaktandır. Bu ara tüylerim bile ağır geliyor üstüme. Yine de havadan şikayetçi olduğumu söyleyemem. Güzel havaları severim.

   Karıncalar böyle havalarda çalışır, yığar; böyle havalarda avlanırım ben. Anlayacağın toplama mevsiminin başlangıcı.

   Aaa Kargacığım toplamak dedim de, dostlarımı haberdar ediyorum, bir banka var; hemen yanındaki peyniri görünce de aklıma geldi, bir peynir bankası, Harp parkının ilerisinde.

   -Nasıl yani! Bir o kalmıştı. Demek sonunda onu da yaptılar. Pes vallahi! 

   -Kibrit kutusu kadar beyaz peynir veriyorsun, tır tekeri kadar bir kaşar peyniri yuvarlıyorlar sana doğru.

   -Anlıyorum. Sen de bankaya mı yatırdın peynirini? 

   -Elbette, kargacığım, akıllı sınıfına girenler, geleceği görürler. Gel sen de katıl aramıza, hayallerimiz gerçeğin ötesine geçsin.

   -Banka işlerinden anlamam. Ayrıca faiz maiz karışır. Allah’a nasıl veririm hesabını sonra? 

   -Canım kardeşim faizsiz kazanç    kulvarları da var, orada da döndürebilirsin tekerlerini.

   -Duydum, işime gelmiyor İlkicik. Hem ayrıca senden bazı kokular yayılıyor yukarı doğru. Nasıl desem yanlış anlama ama, sinsi bir koku. Yıkanmıyor musun bu ara? 

   -Efendim! 

   -Diyorum ki, yiyeceğimle niye bu kadar ilgilisin. Açık  konuşalım, peynirimi istiyorsun sen. 

   -Yok canım daha neler, gün altında kar arıyorsun.

   -Ne karı İlkicik, peynirime dikmişsin gözlerini, sanki benimle değil de onunla konuşuyorsun, ayrıca dişlerin kırık cama benzemekte, parlıyor buradan...

   -İki gözümün yuvaları peynirinin delikleri gibi olsun ki, söylediklerinle günahımı alıyorsun. Kaldı ki, benim bankada istemediğin kadar var.

    Tilki işinin pek de kolay olmadığını düşünerek yere pençeleriyle anlamsız şekiller çiziyor ve plan yapıyordu.

       Karga peyniri kadar akça pakça yüreğiyle İlkiy’e inanmış, hatta onun hakkında kötü şeyler geçirdiği için usundan, utanmıştı.

    Tilki, geriye kalan enerjisiyle son bir hamle yaparak:

    -Kargacığım! 

    -Buyur İlkicik.

    -Ses parkında bu hafta konser varmış gelecek misin? 

    -Kimin? 

    -İbo’nun.

    -Doğru mu diyorsun? 

    -Yalnız biletler tükenmiş, karaborsada.

    -Tüh! Geçen Tatlıses Irak’a gitti diyorlardı televizyonlarda; ne çabuk dönmüş.

    -Irak mı kaldı, hangi Irak’a? 

    -Hani şu Buş’un işgal ettiği peynir zerrelerini dahi boğazıma düğümleyen görüntülerle her Allah’ın günü haberlere konu olan Irak’a.

    -Hatırladım! 

    -İlkicik, İbo sahneye çıkmış, orada Saddam bir daha devrilmiş. Yanık sesiyle tanklardan beter ateşlemiş o yerleri.

    -Yanık ses...

    -Acıdan olmuştur değil mi? Hemi de ses... Bir de yaralı türküler okuyor ki...

     Ağzı iyice sulanan tilki:

    -Bende iki bilet var; para pul istemem yalnız senin sesin güzeldir şimdi, İbo’dan ne eksiğin var. Tatlıses’in okuduğu türkülerden birini söyle de içimiz açılsın şöyle.

     Türkü okumak sevdasıyla heyecanlanan Karga kuyruğunu oynattı. Bir çift kulak kendisini dinlemek istiyordu; ne nimetti onun için.

     Şöyle bir silkinip tüylerini kabartmak istedi, kanatlarını açtı, o anda yanıbaşında duran peynire çarpıverdi. Hızlı davranan tilki yakalayıp, afiyetle yediği peynir için teşekkür dahi etmeksizin kaçıp gitti. Karga ise dalda kalakaldı.

(2005/İSTANBUL)', 'YENİDEN KARGA İLE TİLKİ    Hava  sıcaktı, yapraklar üzerindeki çiğ damlaları esrik bir edayla kıvrıla kıvrıla buhar olurken, yoldan açlıktan...', ARRAY['Türk Edebiyatı','Şiir','Suna Onur']::text[], 8.5, '{"poet":"Suna Onur","poet_slug":"suna-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/yeniden-karga-ile-tilki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokul', 'sokul-mehmet-can-80mui', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen kendi derdindesin

ben kendi derdimde..

batık tüccar gibiyiz.

sokul yanıma..

sende konuşma..bende..

sende gülümse..bende..

sende anlatma.. bende..

daha sıkı sokul.

sımsıkı ol..

bırak dünya dönsün..

aldırma..', 'sen kendi derdindesin ben kendi derdimde.. batık tüccar gibiyiz. sokul yanıma.. sende konuşma..bende.. sende gülümse..bende.. sende anlatma....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sokul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Benim Doğum Günüm', 'bugun-benim-dogum-gunum-hulya-ellikci-lqzs4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün benim doğum günüm

Sen yoksun ya biraz durgunum

Biraz da sessizim işte

Sen yoksun ya biraz kırgınım 

Bugün benim doğum günüm

Sabah annem kıyamadı kaldırmaya

Doya doya uyusun dedi galiba

Kahvaltı yaptık başbaşa 

Babam erken geldi 

Gezmeye gittik başbaşa

Dedi ki: ''bugün biraz solgunsun''

Sen yoksun ya biraz solgunum

Bugün benim doğum günüm

Akşamüstü boğazda bir lokantada

Bütün arkadaşlarımız yanımda

Sen yoksun ya biraz suskunum 

Hem biraz da yorgunum 

Sen yoksun ya hastayım', 'Bugün benim doğum günüm Sen yoksun ya biraz durgunum Biraz da sessizim işte Sen yoksun ya biraz kırgınım  Bugün benim doğum günüm Sabah anne...', ARRAY['Türk Edebiyatı','Şiir','Hülya Ellikçi']::text[], 8.5, '{"poet":"Hülya Ellikçi","poet_slug":"hulya-ellikci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bugun-benim-dogum-gunum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğini Sevmişim....', 'yuregini-sevmisim-omer-golge-xuim0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yanık barut kokulu ellerim

Hayalini okşayarak terlerken

Gözlerim pusuların tedirginliğinde

Nefesim kuşatırken nefesini

Parmaklarım mavzerimin tetiğinde

Bir tavşan ürkekliğinde yüreğim

Sıcak düşler sarıyorken geceyi

Gözlerim karanlığın en derin köşesinde

Serin dağ esintileri ürpertir beni

Bir an..sadece küçücük bir an..

Senden de kendimden de çaldığım

Yalnızca savaşmayı öğretti hayat

Bir tek sensin aşk adına bildiğimi sandığım

Çekme beni yaşadığın şehire

Bırak beni dağlarımda kalayım

Sert eser rüzgar bu yalçın doruklarda

Bu yüzden çatlaktır dudaklarım rüzgar yangını

Ben şaşkın,acemi,çocuksu

Hüzün gözlerinin deli vurgunu

Çatık kaşların arasındaki bu derin izler

Yıllardır bitmemiş kavgaların yorgunu

Bilmediğim bir öfke yerleşmişse gözüme

Ve bir duman gibi inmişse melankoli

Bu yürek yaşadığı acıların kırgını

Sebep sen değilsin bu hallerime

Gölgem gibi taşıdığım geçmişim

Gözlerinin esmer akşamlarında

Yeniden yaşama dönmek isteyişim

Bir de..İmkansızdan bahsetme bana

Nice olmazları var eylemişim

Tarih şahidimdir inan sözüme

Bir zaman Ferhat olup dağlar delmişim

Mecnun olup başka bir coğrafyada

Seni azık edip çöller geçmişim

Kerem olup gül gamzenin uğruna

Ayağına saltanatlar sermişim.

Yoklukla elimi bağlanmış sanma

Nice zorba,hain,kaniçiciye

Aldığı nefesi haram etmişim

Bu yüreği sana teslim etmişsem

Seni kavgam...

Seni sevdam...

Seni davam bilmişim

Saplayıp gönlüme o gözlerini 

''Bana öyle bakma'' deme sultanım

Ne varsa kendimce mukaddes olan

Hepsini sevginde birleştirmişim

Güzelliğin,endamın hepsi bir yana

Hüzün gözlüm ben senin yüreğini sevmişim', 'Yanık barut kokulu ellerim Hayalini okşayarak terlerken Gözlerim pusuların tedirginliğinde Nefesim kuşatırken nefesini Parmaklarım mavzerimi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/yuregini-sevmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sen Ol', 'sen-sen-ol-necmiye-sarpkaya-o3hq6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sıyrıl hazan duygularından 

Billur su kaynaklarına dönüş 

Dönüş ki koşsun bağrı yanıklar 

Kana kana içsinler 

Işıklar saç etrafına yaz güneşi ol 

Yok et kini nefreti hırsı 

Yok et umutsuzluğu mutsuzluğu 

Kurtul gafletten delaletten 

Kurtul ataletten kurtul 

Kurtul cefadan beladan

Terk et çıkarlarını bırak şikayeti 

Kes heva ve heveslerinin sesini 

Genişlet gönlünü misafirlerini karşıla 

Misafirlerini çoğalt 

Gül kokuları yolla 

Kaçın ifrattan tefritten 

Kaçın hiddetten şiddetten

Nefis doğrul düzel kendine gel 

Koş  yitirdiğin cennetlere

Koş açarak kollarını vefaya 

Koş sadakate 

Ağaç  bulut rehber yağmur ol

Umut meltem mehtap ol 

Sıyrıl hazan esintilerinden 

Yurtsuzlara yurt 

Yuvasızlara yuva 

Vesayetine sığınanlara 

Aç kollarını aç kalbini 

Sahip çık insanlığına 

Dert dinle dert çek dert yaşa 

Derman ol etrafına ferman ol 

Mutluluk mührünü vur geceye 

Hakkın lütuflarını 

Tefahür vesilesi yapma 

Bekleme iltifatlar takdirler 

Ötelerden gelecek taltifler 

Teslim gününü düşün emaneti 

Yarından yakın dünden beri 

Kim bilir hangi gün hangi saatte 

Sıyrıl hazan duygularından sıyrıl', 'Sıyrıl hazan duygularından  Billur su kaynaklarına dönüş  Dönüş ki koşsun bağrı yanıklar  Kana kana içsinler  Işıklar saç etrafına yaz güneş...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sen-sen-ol-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gündelikçi Şaire', 'gundelikci-saire-tulay-sustam-9jeu6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sana 

kitap dolusu bir şiir okuturum

sen şiiri

bir kitaptan okuma', 'sana  kitap dolusu bir şiir okuturum sen şiiri bir kitaptan okuma...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gundelikci-saire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih-i tekerrür', 'tarih-i-tekerrur-sair-hejaryan-0hot1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'TARİH-İ TEKERRÜR

Bekliyorum kapının önünde

Çalıyorum kapıları bir haykırışın 

Tanımsal gözyaşı sesinde 

Bekliyorum kapının önünde umutsuzca

Düşüyorum yerlere, kalkıyorum yeniden düşmelere

Anlıyorum,duyuyorum ama soramıyorum kapının önünde 

Bakıyorum her şeyi söylüyorum,hiç birşey beklentisinde 

Ne yapsam olmuyor, kandıramıyorum gözlerinin

         ŞİİRSEL GÜZELLİĞİNİ

Gözlerin kansada,ayakların gelmiyor

Kapının klasik açılmama hastalığına 

Şiirlerim okunuyor, bir fatiha ezgisinde

Bıkıyorum,sıkılıyorum ancak vazgeçemiyorum

Kapıdaki gözlerini soruyorum

Onlar sadece bakıyor, açmıyor gözyaşıyla sulanmış 

YALNIZLIK ZAMANLARIMA

Bekliyorum kapının önünde

Mücadele ediyorum,cevapsız kalmış ve

Anlatılmaya layık görülmemiş 

Birkaç elele tutuşma,tutuştukça sönen 

AYRILIK EZGİSİNDE

Senin için yaşamaya çalışıyorum ve içimde benimi bulamıyorum

Ölümü beklediğim gibi, seni de  bekliyorum

Herşeye muhtaç oldum hayatta

Belkide bu kadar muhtaç olmadım

SENİ SEVİYORUM KELİMESİNE

                                     02/02/2006

	M.S.', 'TARİH-İ TEKERRÜR Bekliyorum kapının önünde Çalıyorum kapıları bir haykırışın  Tanımsal gözyaşı sesinde  Bekliyorum kapının önünde umutsuzca ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/tarih-i-tekerrur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökmavi', 'gokmavi-abdulkadir-karaca-b7cgs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzükoyun kurşunlanmışsam

Beni vuranı görmemişimdir gökmavi

Yani bu dava düşmüştür

İçime düşürdüğün her ateş gibi

Yüzüne düşürdüğüm her öfke gibi

Bir çocuk düşmüştür gökmavi

Koştukça düşecek her çocuk gibi

Bir duvara yaslanmışsam

Muhakkak ayaklarım titrediğindendir

Seni görmüşümdür aniden gökmavi

Uzun süre şiir yazmamışım

Su içmemişim

Özlemişim seni gökmavi

Seni ürkütmekten korkup yoluna çıkmamışım

Muhakkak bundandır bu duvara yaslanışım

Bir yıldız kaymıştır gökmavi

Sen ağlayınca giden her yıldız gibi

Ne tuhaf bir hayaldi mutluluğumuz

Cebimizde barış, ağzımızda aşk

Şarkılar ihtiyar mı gökmavi

Romatizmalı ve ağırdılar dudağımızda

Bir kuş kaç kere ölebilir aynı yaradan

Herhangi bir ölüm kaçıncı provada yakışır üstüme

Nolur bana küsme ama

Ben sensizliği yakıştıramadım kendime

Şimdi şiir dediğin ölüm fermanımdır

Alelade bir ölüm istemediğimdendir kafiyelerim

Zaten alelade bir yaşam ve çıt kırıldı bir aşktır gerimizdeki 

Tesiri kaç saat sürer en dönülmez ayrılığın

Bir gidişe kaç şiir yazılabilir gökmavi

Yokluğuna yazdığım onca şiir hatrına

Konuş gökmavi! 

Suskunluğundur bunca acıma sebep

Nasıl kurtulurum yokluğunun  ağırlığından

Bu paramparça yürek nasıl ölecek

Ölülere nefes veren bir karmaşada bu aşk

Mutluluk eski bir çerçevenin yalancısı

Çünkü fotoğraflardan sökülmüyor maskeler

Ağlanacak onca sensiz nefesim varken

Nasılda çirkinleşiyor gülümsemem

Bu hançeri kalbime vurmuşsam

Aşkı sende bildiğimdendir gökmavi

Bir toz kalkar aniden

Sana adadığım yüreğimden

Bir şehir doğurur gökmavi

Güneşi mutluluk olan

Evet hayaldir gökmavi

Gidişinle biten her hayal gibi

03,02,2006', 'Yüzükoyun kurşunlanmışsam Beni vuranı görmemişimdir gökmavi Yani bu dava düşmüştür İçime düşürdüğün her ateş gibi Yüzüne düşürdüğüm her öfke...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/gokmavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde büyümek', 'gozlerinde-buyumek-sair-hejaryan-7yf4c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GÖZLERİNDE BÜYÜMEK                    

Bir renk bir filiz bir çocuk bir gece

Neyse o,tanımama noktasında

Anlatmak mecburiyeti taşıyan biçare yalınlık

Saklanmış mutlulukların simgesi

Umutlarımın kaygı taşıyan kimsesizlik belirtisi

Bir gül kadar dokunaklı işlenmiş, ve de bir gece kadar karanlık

GÖZLERİN

Tanrının anlamakta zorlandığı,anlaşılmaz güzellik

Ve de anlatılmaya hiç müsait olmayan

Neresinden baksan, bakmaya doyulmayan

Ne kadar anlatsan da şiirlerde zayi olan

GÖZLERİN

Esaretin son umut halkalarında kaygısal bir gözün,başka bir göze takılması

Umutsuz bir çırpınışın başka bir gözle seyredilme vakası

Bakabilme noktasında görebilme eksikliği

Yasakların saklandığı apaçık duyguların kapatılma isteği 

GÖZLERİN

Kaybedilmiş hayatların,solmuş güzelliklerin,umutsuzlukların

Mecburiyet noktasındaki sonu olmayan güzellik penceresi

Açıldığında kapanmayı bilmeyen kirpik ve göz kardeşliği

Tek başına yalnızlıkların birleştikleri birkaç tensel yaşam sevinci

GÖZLERİN

Gözlerine bakmanın yasak olduğu sokaklardan geçiyordum

Aslında yasakları değil gözlerini seviyordum

Göz göre göre, seviyordum

Ve artık gözlükleri çıkarıp, gözlerini görmeni bekliyordum

Ve de büyüyordum gözlerinde 

Büyümekte gözlerin kadar güzel olmuyordu  HER ZAMAN

	                                                      M.S.', 'GÖZLERİNDE BÜYÜMEK                     Bir renk bir filiz bir çocuk bir gece Neyse o,tanımama noktasında Anlatmak mecburiyeti taşıyan biçare...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gozlerinde-buyumek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybetme aşkı', 'kaybetme-aski-sair-hejaryan-uvwhm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KAYBETME AŞKI

Gerçekten bir şiir yazmak gerekiyorsa

Birilerini anlatmak lazımsa 

Ve de içinde aşksal bir tavır 

Hazin bir haykırış duyulursa

Ve de umutsuzca yaşanan hayatlara bir umut inşaa ediliyorsa

Bir çift göz için bin gözyaşı dökülürse

Ya da sevmek gerekirse birilerini ya da birilerinin bir yerlerini

Kazanan yazan olmasa da elbette duyanlar olacaktır

Her zaman kazananların kazanamadığını

Ya da önemli olanın yola ulaşmak olmadığını

O YOLDA YÜRÜMENİNDE GÜZEL OLDUĞUNU 

Anlatmak gerekiyorsa

Sana ulaşmak için bin yol deneniyorsa

Gözlerin taşınsada buralardan elbet tesellisi olacak şiirin 

O yolculuğun bitiş noktasında  KAYBETME AŞKI

M.S.', 'KAYBETME AŞKI Gerçekten bir şiir yazmak gerekiyorsa Birilerini anlatmak lazımsa  Ve de içinde aşksal bir tavır  Hazin bir haykırış duyulursa...', ARRAY['Türk Edebiyatı','Şiir','Şair Hejaryan']::text[], 8.5, '{"poet":"Şair Hejaryan","poet_slug":"sair-hejaryan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kaybetme-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakıp Gittin', 'birakip-gittin-murat-gulener-kz4kh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Koskoca aşktan yana bir ben kaldım

Gitmedi yüreğimden ne hayalin ne tadın

Günahım sevmekse suçum müebbed

Ben yaşarken öldüm sen sağ olasın

Beni bırakıp gittiğin günü hatırla

Ne kadar kolay dı dimi ayrılık

Git istediğin yere cehenneme kadar yolun var

Yeterki, yeterki bana dönüşün olmasın', 'Koskoca aşktan yana bir ben kaldım Gitmedi yüreğimden ne hayalin ne tadın Günahım sevmekse suçum müebbed Ben yaşarken öldüm sen sağ olasın B...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/birakip-gittin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer Günü', 'sevgililer-gunu-murat-gulener-47t1r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün çık dışarı bak

Bütün sevgililer sevgi gösterisi yapıyorlar

Ama olsun canım olsun

Bir gün gelir ki

Onlar bizi seyrederken

Biz başbaşa

Onlara yüreğimizdeki sevgimizi gösteririz

Bırak bu sevgililer günüm de

Sensiz ve yalnız geçsin

Biz sevgililer günüde buluşanlardan değil

Buluştuğumuzda sevgililer günü olanlardanız', 'Bugün çık dışarı bak Bütün sevgililer sevgi gösterisi yapıyorlar Ama olsun canım olsun Bir gün gelir ki Onlar bizi seyrederken Biz başbaşa O...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevgililer-gunu-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül getir bana', 'gul-getir-bana-abdullah-oral-utusd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GÜL GETİR BANA

Kekik yavşan kokan dağlardan geldim

Ben bende değilim bir bak halime

Yitirdim kendimi ben bu şehirde

Bul beni cananım bul getir bana

İnceden bir sızı sardı yar teni

Hasretin kor olmuş yakar bedeni

Yağmur taneleri söndürmez beni

Sel getir cananım sel getir bana

Bu bendeki yara eski çağlardan

Viranım şehirde viran bağlardan

Ara yüreğimi bulda dağlardan

Al getir cananım al getir bana

Salına salın,a eyle bir geliş 

Gel ki son bulsun yar hasretten yanış

Solgun dudaklardan tatlı bir gülüş

Bal getir cananım bal getir bana

Değildir özlemim değil bal kaymak

Hasretim diz dize çiğ soğan kırmak

Zoruma gidiyor ele dert yanmak

Kül getir cananım kül getir bana

Vurgun,i tezene yarama değer

Hasret öldürürmüş insanı meğer

Yar yüzüne hasret göçer sem eğer

Gül getir cananım gül getir bana

                                                             MAYIS 1994', 'GÜL GETİR BANA Kekik yavşan kokan dağlardan geldim Ben bende değilim bir bak halime Yitirdim kendimi ben bu şehirde Bul beni cananım bul get...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gul-getir-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak sen kokuyor', 'toprak-sen-kokuyor-abdullah-oral-dcsch', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'TOPRAK SEN KOKUYOR

Koşarak dağılan akşamın 

Solgun yüzüne asılmakta

Bulutların ağrısı

Yine dumanlandı gökyüzü

Yitik aşkların üstüne yağıyor gözler

Sokaklar kanıyor

İçimi ürperten

          Serin duyguların 

          Serpintisinde yüreğim 

Duygular ıslak öpüşlerin

                         Titreyişinde

Dudaklarımda sevdanın izleri 

Toprağını koklarım

Duldasında  saklandığım ağacın

Yaprak sen  kokuyor

                         Bulut sen 

                              Yağmur sen

Belli ki

     Bütün çiçekler 

           Almış kokusunu senden

Serin rüzgarlardan çekerim 

                         Kokunu içime 

                            Ciğerlerimi patlatırcasına

Çıldırtan labirentlerinden 

          Geçmekteyim yaşamın

İhtiras ateşiyle dövünmekte arzular

Kara  gözlerine  asıyorum geceyi

Firara kalkıyor hapis duygular 

Depreştikçe büyümekte 

                    Yüreğimde sevdalar 

Emekliyor zavallı kalbim 

Bitimsiz aşkların 

Aşılması zor yollarında

Toprak sen kokuyor

                                                                      Ocak 1996

                                                               Etlik SSK Polikliniği

                                                     Enfektüs Geçirdiğim Zaman

                                                                            Mayıs  2000', 'TOPRAK SEN KOKUYOR Koşarak dağılan akşamın  Solgun yüzüne asılmakta Bulutların ağrısı Yine dumanlandı gökyüzü Yitik aşkların üstüne yağıyor ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/toprak-sen-kokuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harman yeri', 'harman-yeri-abdullah-oral-wa5zu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'HARMAN YERİ

Ekin olduk ömür biçtik

Katığımız alın teri 

Zehir zıkkım yedik içtik

Emeğimiz harman yeri

Bu yıl yine baskı zulüm

Dağlara gedik açıyor

Ana avrat küfretmenin 

Zamanı geldi geçiyor 

Her gün soysuzu güldürdük

Görenler sanır çıldırdık 

Yoklukla sofra kaldırdık

Umudumuz harman yeri 

Vurgun,i gerek yok aha

Umutlarım kalksın şaha

Ne durursun yoldaş daha 

Yüreğimiz  harman yeri

                                                              30 Ağustos  (Ünye', 'HARMAN YERİ Ekin olduk ömür biçtik Katığımız alın teri  Zehir zıkkım yedik içtik Emeğimiz harman yeri Bu yıl yine baskı zulüm Dağlara gedik ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/harman-yeri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmeyenler Yolu', 'gecmeyenler-yolu-murat-gulener-z9skq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni görmek istiyorum

Ömrümün son baharında

Seni hep bekliyorum

Geçmeyenler Yolu''nda

Zaman geçmek bilmiyor

Seni görmediğim an

Dünyam cennet oluyor

Benim olduğun zaman

Hatırlayıp bir gün gelirsen

Bana döndüğünü söylersen

Seni tek şartla affederim

Geçmeyenler Yolu''nda beklersen', 'Seni görmek istiyorum Ömrümün son baharında Seni hep bekliyorum Geçmeyenler Yolu''nda Zaman geçmek bilmiyor Seni görmediğim an Dünyam cennet ...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecmeyenler-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim seni görmesin.', 'gozlerim-seni-gormesin-veysel-alkan-77wyc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşim olmaz  artık aşkla.

Yaradan izin vermesin.

Duramaz ki akıl başta.

Gözlerim seni görmesin.

Yollarıma çıkma sakın! 

Hallerimi  sorma sakın! 

Bakışınla yakma sakın! 

Gözlerim seni görmesin.

Şu gönlümü avuturum.

Şarkılarla uyuturum.

Zaman gelir unuturum.

Gözlerim seni görmesin.

Resimleri yırtıp yaktım.

Eşyaların çöpe attım.

Acını dünde bıraktım.

Gözlerim seni görmesin.

Umutluyum, huzurluyum.

Bil ki yanlız çok mutluyum.

Tek kendimden sorumluyum.

Gözlerim seni görmesin.

Kaderimle başbaşayım.

Tanımazsın, bambaşkayım.

Hasretinle barıştayım.

Gözlerim seni görmesin.

Gülümsersin, yıkılırım.

Mazimizi hatırlarım.

Yine sana kapılırım.

Gözlerim seni görmesin.', 'İşim olmaz  artık aşkla. Yaradan izin vermesin. Duramaz ki akıl başta. Gözlerim seni görmesin. Yollarıma çıkma sakın!  Hallerimi  sorma sakı...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gozlerim-seni-gormesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim', 'hasretim-abdullah-oral-u3g5b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'HASRETİM

Ekin başakları misali

                 Savrulur yüreğim.

Genç bir kızın saçlarında

                 Çiçeklenir umut.

Avuçlarımda nergiz papatya. 

Menekşelerini koklamalı 

                               Dağların. 

Sırılsıklam bir ürperti 

Yapraklarda titreşen 

                    Çiğ damlaları.

Gözlerim çığlık çığlığa 

Uyanışında ovaların', 'HASRETİM Ekin başakları misali                  Savrulur yüreğim. Genç bir kızın saçlarında                  Çiçeklenir umut. Avuçlarımda ne...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hasretim-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımın kadının''a', 'hayatimin-kadinin-a-abdullah-oral-trx7w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'HAYATIMIN KADINI

Kızılında  yandığımAteşi körükleyen           

Gecelerden geçerken öğrendim

              Sevdayı sevmeyi

Gözlerinden öperek

              İş dönüşü akşamların.

Hüzünlü Sevinçlerimizin

      Paylaşıldığı daracık odamızda

     Ateşin buz tutmuş yanlarımı

     Damıtırken damla damla

                          sevdim seni.

Sancıya düşmüş

             Gecelerin doğurganlığında

                      Yaşama sevincim.

Ah böle bilseydim acılarını

                     Kızıl yüreklim.

Zincirini kıran deli taylar gibi

        Koşmazmıydım yardımına.

                                            

Yakmadı,mı sanıyorsun beni de 

Bedenindeki O yangın geceler boyu

Sen sancılarındaydın gecenin 

                       Ben ateşinde

Bilirim savrulur acılı türkülerin

                       Burukluğunda yüreğin

Doğurmak ve doyurmak sana kalmış 

            Alacasında sabahın.

Sen kanatlarının sıcaklığına sığındığım

                              Tanrıçamsın benim.

Paylaşılan ekmeğin  öteki yarısı

Bir elmanın ayvanın narın.sen kadınım.

Ben senin yoksul soframızda

Bir zeytini ikiye bölerken

Üşümüş gözlerinde 

Gülüşlerini sevdim

Sevdim seni kadınım  

                                                         Mayıs 1996', 'HAYATIMIN KADINI Kızılında  yandığımAteşi körükleyen            Gecelerden geçerken öğrendim               Sevdayı sevmeyi Gözlerinden öpere...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hayatimin-kadinin-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlarımız', 'kadinlarimiz-abdullah-oral-2sxaq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KADINLARIMIZ

Baharı andıran tel duvağıyla

Çiçeğe bezenir kadınlarımız

Zemheri sonrası bahar gibidir

Dalında gül verir kadınlarımız.

Karnında büyütür oğlu kızı

Güneşle emzirir baharı yazı

Ağarır saçları kırışır yüzü

Çınardır dal  verir kadınlarımız.

Anadır teline kurban olduğum

Canandır kendimi onda bulduğum

Sevdamdır bitimsiz aşkla dolduğum

Peteksiz bal verir kadınlarımız.

Hasat şarkısıdır kazma kürekli

Baskılar örseler onu sürekli

Anadolu gibi yiğit yürekli

 Zalime dil verir kadınlarımız.

Savaşır düşmana vermez hakkını

Toprağından söker kendi kökünü

Hain namlulara gerer göğsünü

Yoldaşa yol verir kadınlarımız.

Zulme karşı düşer dili türküye

Yer vermez içinde kötü korkuya

Sürer yüreğini çıplak namluya

Dağlara el verir kadınlarımız.

Vurgun,i tarihi sallar dizinde

Bir isyan ateşi yanar özünde

Savrulur dumanı kendi közünde

Düşmana kül verir kadınlarımız.

Yakar bedenini beylere inat 

  Düşmana kül verir kadınlarımız.

                                                                    Mart 2000', 'KADINLARIMIZ Baharı andıran tel duvağıyla Çiçeğe bezenir kadınlarımız Zemheri sonrası bahar gibidir Dalında gül verir kadınlarımız. Karnında...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kadinlarimiz-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldesen kalacaktım', 'kaldesen-kalacaktim-abdullah-oral-gfxpl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KALDESEN KALACAKTIM

Bütün renkler çekildi işte

Akşam ağır ağır örtüyor üstümüzü

İçimde hasret büyümekte 

                                     Bir çığ gibi

Kokun nasılda karışmış havaya 

Gözlerinin derinliğine düşer gibi 

Giriyorum karanlığın içine 

Kal desen kalacaktım sende 

Dur gitme demeye

Yenik düştü dudaklarım 

Bütün sözlere 

Düğüm vurulmuş bu akşam 

Sonsuz sevginin 

Gamsız dünyasında

Hiç bu kadar özlememiştim 

Dur gitme 

Bende kal demeni 

    

                                                                  Temmuz 2002', 'KALDESEN KALACAKTIM Bütün renkler çekildi işte Akşam ağır ağır örtüyor üstümüzü İçimde hasret büyümekte                                     ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kaldesen-kalacaktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşur', 'konusur-abdullah-oral-cyrj4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KONUŞUR                                      Kapitalizm sermayeyi 

                                                                   Sermaye    baskıları

                                                         Baskılar Sosyalizmi yaratır

Kendi koyağında seker taşlardan

Dağlardan boşalan sular konuşur

Gün susar akşamın karanlığında

Sazını okşayan ozan konuşur

Tırnakla kaşınmaz aşkın yarası

Ozanın kanıdır coşan deresi 

Tellere düşünce matem sırası

Gözlerinden hasret sızan konuşur

Ocaklarda kömür demiri yakar

Potalardan kızıl sevdalar akar

Bak nasırlı eller cevheri döker

Umudun resmini çizen konuşur

İçimde duygular şahlandı yine

Aşka düştü gönül yollandı yine

Bakma vurgun,i,nin, dellendiğine

 Kırılmış aşkları yazan konuşur



                                                                                                                       24  11  2000', 'KONUŞUR                                      Kapitalizm sermayeyi                                                                     Sermay...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/konusur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Hezeyan', 'dosta-hezeyan-volkan-yoruc-ovgu8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dost ağlamalıydı ya 

Anlatabilmeliydi 

Dostu dost olan anlam anlayışta gizliydi ya hesapta 

Ağlarken gülümsetebilmeliydi 

Anlatırken anlamalıydı 

Susmamalıydı dost 

Sarılmalıydı ya 

Hani kimse olmadığında öylesine sıkıca 

Konuşmalıydı dost 

Dertten kederden 

Sevinçten ümitten 

Yani hayata dair herşeyden 

Karanlıkta olmakmıydı dost 

Güneş kadar sıcak 

Olmamalıydı yıldızlar kadar uzak 

Raksı yüreğiyle yapabilen değilmiydi dost 

Elinden tutmadan 

Çılgın gibi savrulmadan 

Susmamalıydı dost 

Dostu bildiğimiz her kelimeden bulabilmeliydik ya 

Ha bir çayırdan, ha bir bayırdan 

Ama uzak ama candan 

Dostu unutmakmıydı kitabımızda yazılan 

Böylemi olmalıydı dosta olan 

Ve böylemi anılmalıydı hatıralara ilen', 'Dost ağlamalıydı ya  Anlatabilmeliydi  Dostu dost olan anlam anlayışta gizliydi ya hesapta  Ağlarken gülümsetebilmeliydi  Anlatırken anlamal...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dosta-hezeyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuruldum', 'vuruldum-abdullah-oral-nwyjq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'VURULDUM

Seni dağdan taştan sordum

Yüreğine bak dediler

Özümü kanattım durdum

Sular gibi ak dediler

Aşılmaz zor yollar çetin

Gidem dedim gidemedim

Dedim dostadır hasretim

Biraz daha çek dediler

Arar oldum bende beni

Dedim ki ellerin hani

Görsün  şu gözlerim  seni

Karanlıktan çık dediler

Gün tutuşur gece ağlar 

Yüreğimde özlem çağlar

Geçit vermez sana dağlar

Ferhat olda yık dediler

Seni vatan seni yurdum 

Seni aşıklardan sordum

Düşe kalka sana vardım

Ama evde yok dediler

                                                           

Sen olmazsan dağlar kızı

Dinmez şu günlümün yası

Yetmez mi bunca göz yaşı

Biraz daha dök dediler

Oysa ben dağlarda kıştım

Baharla bendimden taştım

Koyaklara yenik düştüm

Bunlar sana hak dediler

Diyar diyar sürüldüğüm

Dedim uğruna öldüğüm

Hani benim özgürlüğüm

Sen kendini yak dediler

Sen güneşimsin al yüzlüm

Sen mevsim sin bahar gözlüm

Zulamda tutsak hürlüğüm

Sana umut çok dediler

Senin için suçlu oldum

Hücrede mahpusta kaldım

Yargısız infazlar aldım

Bir komut diz çök dediler

                                  VURULDUM', 'VURULDUM Seni dağdan taştan sordum Yüreğine bak dediler Özümü kanattım durdum Sular gibi ak dediler Aşılmaz zor yollar çetin Gidem dedim gid...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/vuruldum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü...', 'gokyuzu-beyza-beyza-pmj20', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökyüzü erişilmezlerin sevgi durağı

Özlemlerin son bulduğu istasyon

Kabusların rüyaya dönüştüğü

Yalnızlıkların son bulduğu

Üzüntülerin, kederlerin

Zifiri karanlıkların aydınlığı

Ümidi olanların yaşama sevinci...

Gökyüzü erişilmezlerin sevgiye yolculuğu

Ne bir durağı, ne limanı,

Ne de

Son istasyonu belli...

(Akrostiş deneme...)', 'Gökyüzü erişilmezlerin sevgi durağı Özlemlerin son bulduğu istasyon Kabusların rüyaya dönüştüğü Yalnızlıkların son bulduğu Üzüntülerin, kede...', ARRAY['Türk Edebiyatı','Şiir','Beyza Beyza']::text[], 8.5, '{"poet":"Beyza Beyza","poet_slug":"beyza-beyza","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gokyuzu-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanıyorum', 'utaniyorum-abdullah-oral-lwxyx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'UTANIYORUM

Kim yazmışsa bozsun alın yazımı

Çözün bu düğümü utanıyorum

İnsanlık yitirmiş güzel yanını

Demeyin yazgıymış utanıyorum

Savurur acının dağı neşemi 

Bırakmaz rüzgarlı ölüm peşimi

Görmesin bu berbat rezil yaşamı

Sökün şu gözümü utanıyorum

Esiri olmuşuz  Konağın köşkün 

Kendini yitirmiş İnsanlar şaşkın 

İhaneti çalar özünde aşkın 

Kırın şu sazımı utanıyorum

Ozanın dilin de söylence narin

Aşıklarda şimdi yaşama serin

Rüzgarlı saçını kim öper yarin

Yakın şu özümü utanıyorum

Hangi yola  düşsem çıkmaz ve eğri

Yenik düşmüş gülüş dostundan ayrı

Bağlayın açmasın çiçekler gayrı

Silin gökyüzünü utanıyorum

Ölüm düşmüş bağa bayıra dağa

Zulüm nasıl sığar bu güzel cağa

Vurguni ölmeden kara toprağa

Çevirdim yüzümü utanıyorum

                                         Kasım 2001', 'UTANIYORUM Kim yazmışsa bozsun alın yazımı Çözün bu düğümü utanıyorum İnsanlık yitirmiş güzel yanını Demeyin yazgıymış utanıyorum Savurur ac...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/utaniyorum-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Guzeli', 'bu-guzeli-yasar-gurlek-kcepx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu  guzeli

sanmaki  bir  tanesin  cikar senden  guzeli	

cok  cektim  elinden oldum simdi bir  deli	

sevmenin  sevilmenin olurmu  hic  bedeli	

raziyim her  bedele  sevmisim bu  guzeli	

	

ah bir  kere  sevde gor yoktur hic  sakasi	

deli gonlum zaten asik sana oldum olasi	

yaktin beni deli ettin allahindan bulasi	

raziyim her  derde  sevmisim bu  guzeli	

	

gonlumun son duragi  gozlerinin  karasi	

dinmiyor  yuregime  actigin ask  yarasi	

sevdim seni  neyleyim ey basimin belasi	

raziyim ben  her  derde  sevmisim bu  guzeli	

	

yasar  gurlek  31-01-2005	

rotterdam  hollanda', 'bu  guzeli sanmaki  bir  tanesin  cikar senden  guzeli	 cok  cektim  elinden oldum simdi bir  deli	 sevmenin  sevilmenin olurmu  hic  bedeli...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bu-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç...', 'hic-beyza-beyza-zajer', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve bir son...

Aralanan yeni kapılar

Kapının ardını meraklı bekleyiş

Araladığın kapıyı

Açmaya çabalarken

Merak etmeye devam edişin...

Sonunda 

Kapıyı tamamen açmayı başardığın an

O kapı ardında da hiç olduğunu

Sadece hiç olduğunu görüşün...

Yine de üzülme 

Hiç görmek de birşeydir

Unutma! ...

(28/01/1996)', 'Ve bir son... Aralanan yeni kapılar Kapının ardını meraklı bekleyiş Araladığın kapıyı Açmaya çabalarken Merak etmeye devam edişin... Sonunda...', ARRAY['Türk Edebiyatı','Şiir','Beyza Beyza']::text[], 8.5, '{"poet":"Beyza Beyza","poet_slug":"beyza-beyza","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hic-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda üstüne', 'sevda-ustune-abdullah-oral-2278x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SEVDA ÜSTÜNE

Derler ki bir günah meyvesiyiz biz

Her insanın gönlü aşkla dolmaz mı

Sevip sevilmeyi haram bilmişiz

İnsan sevdiğinde hakkı bulmaz mı

Bir sevda başımda pervane dönen

Yar sevdası ile tutuşup yanan

Yar olmazsa gönül köşküne canan

Bahçıvansız bağın gülü solmaz mı

Sevda ummanın,a daldım erenler

Aşk badesi içtim doldum erenler

Perdede kendimi buldum erenler

Aşık olan gönül sazı çalmaz mı

Sofular yalanmış derler dünyayı

Balçıkla sıvarlar güneşi ayı

Haram bellemişler aşkı sevdayı

Şu sizin tanrınız aşkı bilmez mi

Vurguni yim yar yar yüreğim erir

Tüm duygular sana secdeye durur

Yardan gayrısına secde mi olur

İnsan sevdiğine secde kılmaz mı', 'SEVDA ÜSTÜNE Derler ki bir günah meyvesiyiz biz Her insanın gönlü aşkla dolmaz mı Sevip sevilmeyi haram bilmişiz İnsan sevdiğinde hakkı bulm...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevda-ustune-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu akşam ölmeliyim', 'bu-aksam-olmeliyim-i-lyas-genc-pd6fv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk defa adımı mırıldadı dudakların

İlk defa yakın oldu bu kadar uzaklarım

Ve bu ilkleri sen..neden bu kadar sakladın…

Öyle durgun gözlerle bakma

Bir kelimene bir ömür adadım

Ben neronun roma sı gibi şehri değil, 

Senin için kendi dünyamı yaktım..

Bir candan bakışına bin umut bağladım

Seni tanıdıktan sonra, anladım ki..! 

Ben bunca yıl boşuna yaşadım….

Hep yanlış yaptım..gizli günahlara karıştım..

Her gördüğüm sevgiliyi sen sandım

Kör kuyularda senelerce, yandıkça yandım

Tam umudu kesmişken…..! 

Mutluluğu seninle yakaladım

Bu kadar mutluyken bu akşam

Yarına çıkmamalıyım

Bu akşam bütün günahlardan arınmalıyım

Bu fırsatı bir daha olmayabilir

Bu kadar mutluyken daha ötesini 

Düşünmemeliyim

Özün özümle.ruhun ruhumla birleşirken

Sabaha varmadan ölmeliyim..

ne demiş şair.....

''''Eğer İnsan sevecekse en umutsuz olduğu anda sevmeli 

Eğer insan ölecekse en mutlu olduğu anda ölmeli''''…..

Hadi tut ellerimden mutluluk beni bırakmadan

Ruhum bedenimi terk etmeli….

Benden sonra yüreğin olacak olsa da çöl

Seni hiç bir kula reva göremem...A:E:O:', 'İlk defa adımı mırıldadı dudakların İlk defa yakın oldu bu kadar uzaklarım Ve bu ilkleri sen..neden bu kadar sakladın… Öyle durgun gözlerle ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Genç']::text[], 8.5, '{"poet":"İlyas Genç","poet_slug":"i-lyas-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bu-aksam-olmeliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-abdullah-oral-zrrtf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SÜRGÜN

Filiz kıran gibi düştü 

Şu yüce dağlara zulüm 

Yüreği çatlar taşların 

Kirpiğimde yaşlar sürgün

          

          Sürgün umutlarım 

          Sürgün sevdalarım

          Sürgün emekçi halk 

          Kendi yurdun da sürgün 

Acılarla gönül eyler

Yalan bilmez doğru söyler

Yakılmış ovalar köyler

Yıkılmış dört yanım sürgün 

Kefen giymiş ölü gibi 

Zemheriye yatmış dağlar

Yakındır uyanır toprak

Göğsünde boy verir sürgün

                                                                   Ocak 2003', 'SÜRGÜN Filiz kıran gibi düştü  Şu yüce dağlara zulüm  Yüreği çatlar taşların  Kirpiğimde yaşlar sürgün                      Sürgün umutlarım...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/surgun-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen Eğer', 'gidersen-eger-murat-gulener-jtcj2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensizlik benim belimi büker

Hasretin dağları deler geçer

Sensiz kör olur bu yaşlı gözler

Beni bırakıp gidersen eğer

Yüreğim yalnızlar rıhtımına demir atar

Bedenim hasret ağacında çürür, yanar

Kemiklerimdeki deriyi kan kaplar

Beni bırakıp gidersen eğer', 'Sensizlik benim belimi büker Hasretin dağları deler geçer Sensiz kör olur bu yaşlı gözler Beni bırakıp gidersen eğer Yüreğim yalnızlar rıhtı...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gidersen-eger-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irmaklar konuştu', 'irmaklar-konustu-abdullah-oral-donrr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'IRMAKLAR KONUŞTU

Soframıza uzanan kirli eller 

Ekmeğimizi çalmadan öğrenemedik

Geleceğimizin  alınıp götürüldüğünü

Acısına öyle alışmış ki gözyaşları

Faşist kurşunların

Sustu insanlar

Köklere can veren 

Irmaklar konuştu halkın yerine

Geçmişin ağlamaklı kıldığı 

Şu iki yüzlü zamandan geçerken

Düştü aklıma bizimkiler

Bütün suçlar

Omuzlarına yıkılmış başkaldırının

Sevgi sularımızda açan

Sevda çiçekleri vurulmuş bir şafak vakti

Kanatılırken milyonların yüreği

Kızıl dere kana kesmiş koyaklar boyu

İsyan ateşinin 

Alevli rüzgarı savrulmakta

Karadeniz dağlarında

Özgürlük ve bağımsızlık adına

Munzur selamlamış 

Karadeniz esintisini

Nurhak öpmüş alnından

Mahirin nefesini

Sürmek için amerikan emperyalistini yurttan

Almış silahını düşmüş yollara

Alpaslan Kadir Sinan

Habersiz İşbirlikçilerin kurduğu pusudan

Hain kalleş duruşlara 

Ana avrat küfretmenin

Öteki adıdır isyan

Yürüyorlar 

Kanserli hücreyi 

Söküp atmak için

İncirlik toprağından

Acılara bırakırken

İsyan çığlıları yerini

Bir çığ gibi

İbrahim’in sesi düşmüş 

            Munzur sularına

Dersimin direniş türküleri kuşatmış 

Cudi Şırnak Şemdinli mazı dağını

Sönen ocak yanan et 

           Sökülen tırnak gibi

Ondandır

Dicle nin Fırat ın deli dolu akışı

Ondandır Sürgün suların

Kızıl derede yürek yakışı

Karadeniz dövüne dövüne

Munzur devine devine

Dile getirmiş isyanı

Seslerine 

Sesimizi katamadığımızdan

           Vurulup düşenlerin

Şimdilerde 

Mahirlerin türküleri söylenir

Onurlu insanların dillerinde

Oy dere kızıl dere 

Böyle akışın nere

                                                                Mart 1998', 'IRMAKLAR KONUŞTU Soframıza uzanan kirli eller  Ekmeğimizi çalmadan öğrenemedik Geleceğimizin  alınıp götürüldüğünü Acısına öyle alışmış ki g...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/irmaklar-konustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygum Nerdesin? ! ...', 'duygum-nerdesin-beyza-beyza-4tr5c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duygularım yenilir mantığıma yaşamım boşunca. Gizlenir yaramaz çocuk misali.

Suç işleyen bir çocuk hani... Kaçan birşeylerden, ceza almamak içinse hemen herşeyi inkar eden...

İşte böylesi durumlarda kaçıyor gönlüm. Nedenini bilmiyorum ama meydanı mantığıma bırakıp gidiyor. Hem de ona en ihtiyacım olduğu anlarda...

Duygum nerdesin? ! ...

(28/01/1996)', 'Duygularım yenilir mantığıma yaşamım boşunca. Gizlenir yaramaz çocuk misali. Suç işleyen bir çocuk hani... Kaçan birşeylerden, ceza almamak ...', ARRAY['Türk Edebiyatı','Şiir','Beyza Beyza']::text[], 8.5, '{"poet":"Beyza Beyza","poet_slug":"beyza-beyza","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/duygum-nerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz baba''ya kesik Alaattine', 'beyaz-baba-ya-kesik-alaattine-sedat-akguden-6hqcj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'saclari beyaz

biyigi beyaz

kaslari beyaz

ruhu karbeyaz

anlar rakinin beyazindan

en az...', 'saclari beyaz biyigi beyaz kaslari beyaz ruhu karbeyaz anlar rakinin beyazindan en az......', ARRAY['Türk Edebiyatı','Şiir','Sedat Akgüden']::text[], 8.5, '{"poet":"Sedat Akgüden","poet_slug":"sedat-akguden","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/beyaz-baba-ya-kesik-alaattine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonuna kadar', 'sonuna-kadar-abdullah-oral-ni9b4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SONUNA KADAR

Bir sevdaya düştü şu  deli gönlüm 

Uyutmaz geceler dön yana yana

Durmak yok kavgamız çetin olsa da

Ogünlere koşacağız düşene kadar

Sonuna kadar yoldaş sonuna kadar

Sınıfsız bir dünya kurana kadar 

Tohumlar toprağı kızıla kesti

Çiçekler yürüdü dağlara kadar

Gelir günler gelir gül ayaklanır

Boy verir fidanlar bahara kadar

Sonuna kadar yoldaş sonuna kadar 

Durmak yok bu kavgada ölene kadar

                                         

                                                         Şubat  2002', 'SONUNA KADAR Bir sevdaya düştü şu  deli gönlüm  Uyutmaz geceler dön yana yana Durmak yok kavgamız çetin olsa da Ogünlere koşacağız düşene ka...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sonuna-kadar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Meyve', 'yasak-meyve-beyza-beyza-nlaxo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Asırların yaşattığı aşık yollarda kayboldum

Karşımda incir ağaçlarından bir bahçe içinde

Adem ve Havva''yı gördüm

Mutlu günlerinde...

Anıların unutulduğu nefret yollara düştüğünde yolum

Bu kez elma ağaçlarından bir bahçe içinde

Adem - Havva ve bir yılan gördüm

Mutluluklarını yok eden 

Hatanın gölgesinde...

(27/04/2004)', 'Asırların yaşattığı aşık yollarda kayboldum Karşımda incir ağaçlarından bir bahçe içinde Adem ve Havva''yı gördüm Mutlu günlerinde... Anıları...', ARRAY['Türk Edebiyatı','Şiir','Beyza Beyza']::text[], 8.5, '{"poet":"Beyza Beyza","poet_slug":"beyza-beyza","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasak-meyve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen benim neyimsin tarif edemediğim', 'sen-benim-neyimsin-tarif-edemedigim-i-lyas-genc-uorg1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen benim neyimsin tarif edemediğim

Beni her gece uykusuz bırakan bir rüya

Ömrüm boyunca geçmeyecek bir sera

Yüreğimde damla damla damlayan bir yara

Sen benim neyimsin tarif edemediğim

Durup durup yüreğimde başlayan sancı

Hiç gelmeyecek yolcuyu bekleyen hancı

Bedenim kadar yakın ruhum kadar yabancı

Sen benim neyimsin tarif edemediğim

Sevildikçe sevdiğine zarar veren acizliğim

Kadere daima  yenık  düşen  yalnızlığım 

Zamanın merhametsizliğine  bırakılan  gençliğim

Sen benim neyimsin tarif edemediğim

Yanında iken hissettiğim sevgi duygusu 

Beni sürekli hüzünlü yapan aşk öyküsü

Ve dilimden düşürmediğim ayrılık türküsü

Sen benim neyimsin tarif edemediğim

Çocukken kayıp ettiğim  oyuncaklarım 

Hep beni zamansız terk eden  sevdalarım

Belki de müebbet yediğim  yasak tutkularım

Sen benim neyimsin tarif edemediğim

Gözlerimle göremediğim Elerimle tutamadığım

Özleminle yandığım yandıkça hasret kaldığım 

Sen benim neyimsin bir türlü anlayamadığım

Sen benim neyimsin bi türlü yaşayamadığım

Sen benim neyimsin bir türlü tarif edemediğim', 'Sen benim neyimsin tarif edemediğim Beni her gece uykusuz bırakan bir rüya Ömrüm boyunca geçmeyecek bir sera Yüreğimde damla damla damlayan ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Genç']::text[], 8.5, '{"poet":"İlyas Genç","poet_slug":"i-lyas-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-benim-neyimsin-tarif-edemedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takıntı', 'takinti-beyza-beyza-f7g5f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Takıntılarına takıldığı zaman

