INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir doğru 4 yanlış', 'bir-dogru-4-yanlis-reyhan-tataroglu-euepd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'doğru ile yanlış çarpışır 

                      arada kalanlar

                      birbirine yapışır', 'doğru ile yanlış çarpışır                        arada kalanlar                       birbirine yapışır...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bir-dogru-4-yanlis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak İsyankar Bellesinler', 'birak-i-syankar-bellesinler-serhat-caliskan-bsd22', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizi hep feryatlarımızdan bildiler,

Daha doğarken,yaşamaya değmez diye ağladık

Herkes kendi cehennemini yaşarken,

Kim bize cenneti vadedebilirdiki,

Aldandık

Yangınları söndürmeye çalıştık

Kendimiz yanarken

Umutlarımızı feda ettik,umutlulara

Sevgilerimiz armağandı sevgililere

Merhameti öğrettik gönlümüze,

İsyana karşı direndik,

Karşı koyduk bencilliğe

Yanıldık

Hayat sırtımızda,bıçak yarasıydı,

Ve yeğledik hayatı dil yarasına,

Dünyayı horlamak olsaydı gayemiz

Fikirlerimizi,satılığa çıkarırdık,

kıskandık

Yalnızları değil ama,yalnızlığı sevdik

sürülere katılmayıp,

Kartallara özendik,

Dışlandık

Eksikleri fazla bildik,kendimizden

Fazlaların yanına yaklaşamadık

Artık farketmez gayrı,

kaç yaramız olduğu; 

Son nefesi vermeden haykır. 

Bağır! 

Parçala kendini! 

Nasılsa inandığımızı yaşatmadılar,

Bırak     İSYANKAR   bellesinler.........', 'Bizi hep feryatlarımızdan bildiler, Daha doğarken,yaşamaya değmez diye ağladık Herkes kendi cehennemini yaşarken, Kim bize cenneti vadedebil...', ARRAY['Türk Edebiyatı','Şiir','Serhat Çalışkan']::text[], 8.5, '{"poet":"Serhat Çalışkan","poet_slug":"serhat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/birak-isyankar-bellesinler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
