INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğru dur!', 'dogru-dur-reyhan-tataroglu-g2kzq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yine kaynıyor sular

                               yine birilerinin canı

                               haşlama çekmiş

                               kimileri ise kanı kımız

                               yapıp  içecekmiş

                               göz dikilmiş imana

                               kalp sarılmış şerre

                               bu dava mahşere...

                               bu dava mahşere...', 'yine kaynıyor sular                                yine birilerinin canı                                haşlama çekmiş                      ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dogru-dur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil-sen', 'bil-sen-guler-ilgaz-cagkz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dayanabildiğimce geçerim

Kendimden

Sevebildiğimce özgürümdür

Seni senden

Bilsen de bilmesen de

İçiçeyim seninle

....................................................

Duyabildiğimce yaşarım seni

Sabrım kanat çırptığında

Bilsen de bilmesen de

Taşıyarak sevgimi

Alıp göçerim sensizliğe...

SENİ.......DE..............', 'Dayanabildiğimce geçerim Kendimden Sevebildiğimce özgürümdür Seni senden Bilsen de bilmesen de İçiçeyim seninle ...............................', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bil-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-adnan-gordum-sm8ui', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurmudur

Seni hatırlatıp üzen beni,

Yoksa senmisin

Yağmura katan hüznü kederi..

Hızlı da yağsa,

Yavaş da yağsa

Sanki hüzünlü bir melodi,

Neden her damlası 

Israrla hatırlatır seni..', 'Yağmurmudur Seni hatırlatıp üzen beni, Yoksa senmisin Yağmura katan hüznü kederi.. Hızlı da yağsa, Yavaş da yağsa Sanki hüzünlü bir melodi, ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Gördüm']::text[], 8.5, '{"poet":"Adnan Gördüm","poet_slug":"adnan-gordum","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yagmur-262-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-mehmet-ali-cibikli-g7r82', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar

Bir çocuk vardı.

Çikolatayı çok sever,

O olmayınca ağlardı.

Bir zamanlar

Bir ihtiyar vardı.

Göçüyordu ebediyete doğru,

Hayat yaşanmaya değer sanırdı.

Bir zamanlar 

Bir ölü vardı.

Gencecik yaşında hayata,

Doyamadan gittiğine yanardı.

Bir zamanlar

Bir genç vardı.

Kendisini sevmeyen vefasıza,

Ömrünce umut bağladı.', 'Bir zamanlar Bir çocuk vardı. Çikolatayı çok sever, O olmayınca ağlardı. Bir zamanlar Bir ihtiyar vardı. Göçüyordu ebediyete doğru, Hayat ya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umut-246-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gonca da Sensin Gül de Sen', 'gonca-da-sensin-gul-de-sen-alaz-enderin-16r7u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gonca da sensin gül de sen

Bakma sen; ağlar ağlar yorulurum

Gonca da sensin gül de sen

Biraz da başka kaldırımda yürürüm

Gonca da sensin gül de sen

Nolacak, oralara da alışırım

Varsın buğulanmasın bu sabah ayna

Varsın bayatlasın sepette duran ekmek

Varsın seslenemesin kimse adımı bir daha

Gonca da sensin gül de sen...', 'Gonca da sensin gül de sen Bakma sen; ağlar ağlar yorulurum Gonca da sensin gül de sen Biraz da başka kaldırımda yürürüm Gonca da sensin gül...', ARRAY['Türk Edebiyatı','Şiir','Alaz Enderin']::text[], 8.5, '{"poet":"Alaz Enderin","poet_slug":"alaz-enderin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gonca-da-sensin-gul-de-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğuna Ağıt', 'yokluguna-agit-mehmet-ali-cibikli-ectoa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine seni aradım,dün bu ıssız sokaklarda

Adım adım dolaştım Balıkesir kaldırımlarını.

Bir ben vardım kahrolan bu yollarda

Hiçbir şey dindiremedi benim acılarımı.

Önümden geçen herkese hep seni sordum

Ne gören vardı burda seni,ne de tanıyan.

Sensiz,yapayalnız,delicesine dolaştım durdum

İçin için eriyip yüreğimdi kanayan.

Yokluğundan beri acılarım kat kat oldu

Ayrılık bu diyoruz,kader bu diyoruz

Ağlamak istiyorum gözlerime yaşlar doldu

Gözyaşlarının halledemiyeceğini de biliyoruz.

Bitmeyecek mi daha bunca çektiğim çile? 

Sona ersin istiyorum  sensizliğim.

Eskiden ateş idim,şimdi dönmüşüm küle

Yeter artık uzaklaşsın benden çaresizliğim.

Bil ki,dayanamam yokluğuna daha fazla

Bitkinim,alın yazıma lanet edeceğim.

Gel sarıl bana,sev beni en büyük hazla,

Yoksa sensizlikten burda ölüp gideceğim.', 'Yine seni aradım,dün bu ıssız sokaklarda Adım adım dolaştım Balıkesir kaldırımlarını. Bir ben vardım kahrolan bu yollarda Hiçbir şey dindire...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yokluguna-agit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Enteresan', 'ask-enteresan-alaz-enderin-5mxrx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk enteresan bir malzemedir.

Ateş gibidir, su gibidir,

Rüzgar gibidir aşk! 

Ya yakar, boğar ve dağıtır, 

Ya da ısıtır, yaşatır ve tazeler...', 'Aşk enteresan bir malzemedir. Ateş gibidir, su gibidir, Rüzgar gibidir aşk!  Ya yakar, boğar ve dağıtır,  Ya da ısıtır, yaşatır ve tazeler.....', ARRAY['Türk Edebiyatı','Şiir','Alaz Enderin']::text[], 8.5, '{"poet":"Alaz Enderin","poet_slug":"alaz-enderin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-enteresan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Bayrak', 'beyaz-bayrak-ethem-turan-8ld91', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beyaz bayrak açtım hayata ve sana 

Teslim oldum  istediğin gibi

Silahım yok elimde vurmana gerek yok 

Bir buket gül almakta  istemedim 

Sarıp sarmana da hiç gerek yok 

İstediğiniz gibi olsun her şey

Rüzgarınız istediğiniz yönden essin

Olsun,

Sana olan aşkıma gülmedi hayat 

Tınaz gibi savurdu nedense 

Oysa ki; 

O kadar içten sevmiştim ki 

Senin sevginden başka

Hiçbir beklentim olmamıştı 

Öyle hayaller kurmuştum ki 

Hiçbir şey yoktu senden başka 

Dicle ve Fırat’ın suyu gibi

Akıp gitti  umutlarım 

Bir siman kaldı belleğimde

Birde yüreğimde köz olmuş ateşin

Bir şey dilemem istenseydi 

Mutluluğunu dilerdim çiçeğim

Sonsuza dek  mutlu olmanı', 'Beyaz bayrak açtım hayata ve sana  Teslim oldum  istediğin gibi Silahım yok elimde vurmana gerek yok  Bir buket gül almakta  istemedim  Sarı...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beyaz-bayrak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Kardelenim', 'sevgili-kardelenim-muammer-erturan-stx7b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç gelmeyecek sandığım bahar

hiç ummadığım bir akşamüstü 

gösterdi yüzünü...

Ilık bir hüzün okunuyordu 

gözlerinde önce 

ve ürkek bir telaş 

çözüldü lakin 

dilinin bağı 

yavaş yavaş 

gönlümün bam teline 

dokundu durdu...

Ve bir soru 

yanıtını buldu aniden 

ve bir sır 

sıyrıldı örtüsünden 

ve kanatlandı gece bir anda 

parlak yıldızlara doğru...

Ve un ufak oldu putlar 

kadife depremlerle... 

Dumanı üstünde bir sevişmenin 

üstüne doğdu güneş 

karakış ortası...

Karakış ortası bahar 

açarsa böyle açar 

kokarsa isyan kokar böyle 

aşk diye buna derim... 

Benim sevgili kardelenim! ..

(18 Ekim ''95)', 'Hiç gelmeyecek sandığım bahar hiç ummadığım bir akşamüstü  gösterdi yüzünü... Ilık bir hüzün okunuyordu  gözlerinde önce  ve ürkek bir telaş...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevgili-kardelenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğamazdım', 'dogamazdim-alaz-enderin-wqj44', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saklambaç oynar gibiydik; 

Sen saklanırdın, ben bulamazdım.

Acımasız bi'' ebe gibiydin; 

Çok istesem de doğamazdım!', 'Saklambaç oynar gibiydik;  Sen saklanırdın, ben bulamazdım. Acımasız bi'' ebe gibiydin;  Çok istesem de doğamazdım!...', ARRAY['Türk Edebiyatı','Şiir','Alaz Enderin']::text[], 8.5, '{"poet":"Alaz Enderin","poet_slug":"alaz-enderin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dogamazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Bir Alev Gibi İçimde', 'sensizlik-bir-alev-gibi-i-cimde-mehmet-ali-cibikli-9lgjf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karaoğlan Mahallesinin İğneci Sokağında,

Otuz sekiz numaralı odamda seni düşünüyorum.

Biliyorum ki,sen değilsin devamlı yanımdaki,

Yanımda olmayışına da büsbütün üzülüyorum.

Gözlerin geliyor aklıma,gözlerin...Bilebilsen,

İçmek istiyorum gözlerini,doyasıya içmek.

Geliversen diyorum bir an,ah bir geliversen,

İstiyorum baktıkça gözlerine,kendimden geçmek.

Sonra dudaklarını hayalliyorum birden,

Kah arzu dolu isterik,kah sımsıcak bir dudak.

Düşündükçe kalbim fırlayıverecek yerinden,

Neredeyse dudaklarım sensizlikten kuruyacak.

Ve...Seni düşünüyorum ardından sevgilim,

Kadınsı halinle bana doğru yaklaşan.

Ne dermanım var,ne de tutacak bir elim,

Bir ben kaldı şimdi bende,benden uzaklaşan.', 'Karaoğlan Mahallesinin İğneci Sokağında, Otuz sekiz numaralı odamda seni düşünüyorum. Biliyorum ki,sen değilsin devamlı yanımdaki, Yanımda o...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensizlik-bir-alev-gibi-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Takılı Kaldım', 'ben-sana-takili-kaldim-zulfikar-yapar-kaleli-b6qza', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Atmışın evveli, yetmişten sonra

Ben sana takılı kaldım beyhude.

İki bin de işi bitmişten sonra

Yeniden aşığın oldum beyhude.

Seni sevdiğimi kimseye deme

Acep söylesem mi deme, söyleme

Sakın bana kızma, sitem eyleme

Ben gönlümü sana saldım beyhude.

Dünyada her şeyin var bir göreni

Dosttan dosta gider gönül treni

Aşkın tekeri yok, tutmaz freni

Düşerken aklımı buldum beyhude.

Bırak tunçtan eller tene dokuna

Sevenin ki hasret yaşar kokuna

Avcı bu, yaralar, gelsen okuna

Çok dedim, nasihat aldım beyhude.

En masum işini göremez deme

Arzulara cevap veremez deme

Bana ulaşamaz, eremez deme

Gönlüme köz düştü, soldum beyhude.

Yastığın taş olsun ekmeğin yavan

Çığlıktan inlesin döşeme, tavan

Beni hiçe sayan, başından savan

Hayali sükuta daldım beyhude.', 'Atmışın evveli, yetmişten sonra Ben sana takılı kaldım beyhude. İki bin de işi bitmişten sonra Yeniden aşığın oldum beyhude. Seni sevdiğimi ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-sana-takili-kaldim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-mehmet-ali-cibikli-zzrbu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine seni arıyorum bu sensiz yerde

Yokluğunda acılarım kat kat arttı, gel.

Sensizliğin acısını tatmak varmış kaderde

Ümit denizinde gemilerim battı,gel.

Senin hasretinle bak nasıl yaşıyorum

Koca bir mum gibi eridim gittim,gel.

Artık vücudumu bile zor taşıyorum

Dayanamadım,yok olup bittim,gel.

Nereden çıktı bu ayrılık sanki

İkimizi de perişan etti,gel.

Daha da dayanamam hasretine bil ki,

Bütün benliğim beni terketti,gel.

Ayrılığa beraberce bir son verelim

Gözlerim yollarda daha da kalmasın,gel.

Sevgi bahçemizde mutluluğu görelim

Sevmek özlemek suçumuz olmasın,gel.

Sen orda perişan,bende ise dert dolu

Kader mi bu böyle,yazımız mı,gel.

Birlikte bulalım mutluluğa giden yolu,

Tek başıma bulamam ben onu,gel.

Geleceksen gel artık...Bekletme daha çok,

Gelişini belki göremem,belki görürüm.

Mecalim kalmadı,bekleyecek gücüm yok,

Belki de seni göremeden ölürüm.', 'Yine seni arıyorum bu sensiz yerde Yokluğunda acılarım kat kat arttı, gel. Sensizliğin acısını tatmak varmış kaderde Ümit denizinde gemileri...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gel-269-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül ateşim', 'gonul-atesim-elazigli-mustafa-kaya-fqbcd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir rüya:

bir damla deniz ve,

coşkun dalgalar

ortasındayım

hayat ırmağımı aradım.

kuru bir ağaçmışım

ateş seline uğradım

üzüntü ve utanç

içinde

geceyi sabahladım..

gizi bir dünya

bu rüya

gözümden damladı

gönül ateşim

günlerdir

aklımdan çıkmadı..

Mustafa kaya

04.02.2006 / kandilli', 'bir rüya: bir damla deniz ve, coşkun dalgalar ortasındayım hayat ırmağımı aradım. kuru bir ağaçmışım ateş seline uğradım üzüntü ve utanç içi...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gonul-atesim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Nokta', 'uc-nokta-sair-odesus-c92kv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'başlamak için 3 nokta gerek,

kesişebilmesi için içinden geçen yolların.

iki nokta yanlızlıktır,

üç nokta kesişmeye aday yolların 

kavşak noktası.

üç nokta gerek bana

bir noktada sen,

bir noktada ben,

bir noktada buluşması kalplerimizin,

şehrin sokaklarında

çıkmaz yollara düşmeden.

seni bulabilmem için

üç nokta gerekir,

bir de üç nokta,

bir şeylerin bitmeyeceğinin simgesidir...', 'başlamak için 3 nokta gerek, kesişebilmesi için içinden geçen yolların. iki nokta yanlızlıktır, üç nokta kesişmeye aday yolların  kavşak nok...', ARRAY['Türk Edebiyatı','Şiir','Şair Odesus']::text[], 8.5, '{"poet":"Şair Odesus","poet_slug":"sair-odesus","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uc-nokta-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burnumun direği', 'burnumun-diregi-ayse-adlim-en9ws', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Burnumun direği sızlıyor 

derlerdi de hani

Nasıl sızlarmış derdim

burnun direği

Oysa şimdi

İrili ufaklı taşların

Yerlerini hiç unutmadığım

duvarlar

Süpürdükçe oyulan

Toprak yollar

Çatlak taşlı merdivenler

Ardıç damlı evler

Yüzünü bile görmediğim

Mini mini yavrular

Aklıma geldikçe

Burnumun direği

Öyle bir sızlıyor ki', 'Burnumun direği sızlıyor  derlerdi de hani Nasıl sızlarmış derdim burnun direği Oysa şimdi İrili ufaklı taşların Yerlerini hiç unutmadığım d...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/burnumun-diregi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul boğazı ve kaderim', 'i-stanbul-bogazi-ve-kaderim-elazigli-mustafa-kaya-hu84e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sahildeyim

İstanbul boğazı bu

Zikzak sahilleri

Sayısız sandal gemi

Bir uçtan diğer uca

Akıp gidiyor mavi

Durup Anadolu kavağında

Düşünüyorum

Uykusuz gecelerimden

Aydınlığa hasret günlerime kadar

Dalgaların coşkunluğu

Daha yakıcıydı

Atıp koynuna 

Mavinin kollarına

Derinlere uzaklaşmak

Boğazın kaderiyle

Bir su kabarcığı olup

Kayalara çarpmak

Boğaza batan güneşle

Batmak istedim

Bir sır olup kaybolmak

Unutturmak kendimi

Mustafa kaya

10.08.2005 / Anadolu kavağı', 'Sahildeyim İstanbul boğazı bu Zikzak sahilleri Sayısız sandal gemi Bir uçtan diğer uca Akıp gidiyor mavi Durup Anadolu kavağında Düşünüyorum...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/istanbul-bogazi-ve-kaderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmenin Bedeli', 'sevmenin-bedeli-mehmet-ali-cibikli-v0qtc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerde sarı yaprak görsem

İçime bir hüzün çöker.

Halimi bir bana sorsan

Sıralarım teker teker.

Ben de bir gün seviyordum,

Neşelenip gülüyordum,

Mutluluğu özlüyordum,

Onu bana çok gördüler.

Bilseniz ne çok mutluyduk,

Yarınlardan umutluyduk,

Çok görüldü bu mutluluk,

Onu da alıp gittiler.

Suçumuz bizim sevmekmiş,

Mutluluğu özlemekmiş,

Kaderimiz gülmemekmiş,

Gülmeyi haram ettiler.

Şimdi bir sarı yaprağım,

Eksilmiyor acılarım,

Anam babam bacılarım,

Onlar bile terkettiler.', 'Nerde sarı yaprak görsem İçime bir hüzün çöker. Halimi bir bana sorsan Sıralarım teker teker. Ben de bir gün seviyordum, Neşelenip gülüyordu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevmenin-bedeli-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoksun', 'sen-yoksun-elazigli-mustafa-kaya-g23q6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sustun,

çöllere döndüm.

gönül ateşimdin,

bahçemin çiçeği,

gökyüzümün dolunayı,

gonca gülüm.

yoksun,

iniltilere döndüm..

MUSTAFA KAYA

04.02.2006 / salacak', 'sustun, çöllere döndüm. gönül ateşimdin, bahçemin çiçeği, gökyüzümün dolunayı, gonca gülüm. yoksun, iniltilere döndüm.. MUSTAFA KAYA 04.02.2...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-yoksun-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kütdadanak', 'kutdadanak-sair-odesus-djs1y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kütdadanak söylemeyi sevmiyorum belki

belki çikolata içerisine saklamak hoşuma gidiyor kelimeleri.

belki gizlice köşeden çıkıp önce korkutmak,

sonrada korkunu bahane edip sarılmak istiyorumdur

olamaz mı dersin

dolaylı yollardan gelirken geç kalırım

doğru

kızarsında buna belki

ama 

ne çok yer görür

ve seni sevmekle

ne kadar güzel bir şey yaptığımı

bir kere daha gördüğüm içindir

hem kızdığında korksamda

öte yandan sonrasında gelen

gülümsemeni sevdiğim içindir

gıcıklığım birazda', 'kütdadanak söylemeyi sevmiyorum belki belki çikolata içerisine saklamak hoşuma gidiyor kelimeleri. belki gizlice köşeden çıkıp önce korkutma...', ARRAY['Türk Edebiyatı','Şiir','Şair Odesus']::text[], 8.5, '{"poet":"Şair Odesus","poet_slug":"sair-odesus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kutdadanak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sengârenk', 'seng-renk-muammer-erturan-jd5br', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiirler ördüm sana

ilmik ilmik,

ilmik ilmik hasret

ilmik ilmik umut

ilmik ilmik sevgi,

seni üşütecek yalnızlığın

alnını karışlar her biri...

Şiirler derdim sana

gönül deryamdan,

serseri bir dalga değil öyle

rasgele savrulan

ve kıytırık bir esintide

kıyıya vuran

ve bir daha kendisinden

haber alınamayan,

uçsuz bucaksız,

sengârenk bir umman...

Şiirler dövdüm sana

çifte su verilmiş umutlardan,

nasıl bir mahşerin fitilini

ateşlerse ateşlesin

ardındayım,

ucunda yanmak varsa,

yanayım anasını satayım! ..

(''95)', 'Şiirler ördüm sana ilmik ilmik, ilmik ilmik hasret ilmik ilmik umut ilmik ilmik sevgi, seni üşütecek yalnızlığın alnını karışlar her biri......', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sengarenk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuzluk', 'susuzluk-ayse-adlim-jthk7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Susuz bir toprak gibi

Çatlamış, dağılmış

Arzular, istekler

Uzaklarda kalmış

Dalında öten

Serçenin sesi

Terkedilmiş yalnız

İhtiyarın gülüşü

Bahçemde açılan 

Çiçeklerin kokusu

Sönmeyen güneşin

Parlak ışıkları

Kurak toprağın

Bir damla suyu

Sararan yaprakların

Güzel yeşilliği

Ölmüş duyguların

Canlı filizleri

Uzatıp ellerini

Alsalar beni

Gömseler, saklasalar

Öldürseler

Bir daha

Vermeseler geri', 'Susuz bir toprak gibi Çatlamış, dağılmış Arzular, istekler Uzaklarda kalmış Dalında öten Serçenin sesi Terkedilmiş yalnız İhtiyarın gülüşü B...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/susuzluk-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastahane günlüğüm - 2', 'hastahane-gunlugum-2-elazigli-mustafa-kaya-rkoxz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'saat  9.20

şehrin,

tuzlu mavi duruşunda

içimi yakan açmazlar

ve

bin bir ömür çizgileri geziniyor

202 no.lu oda

hastahanenin ikinci katı

aynı odada da

emekli hasta kendinden çok

çocuklarından dertli

trabzon’lu maliyeci 9 gündür burada

“babam olsa adalet yaparım..” diyor

yaşlı bir kadın 45 gün hastanede 

oğlu perişan

sigara isteyen hastaya 

tereddüt ettim..

dışarıya döndüm

kadıköy şurada

haydarpaşa orada

ve Marmara

boğaza girmeye çalışıyor

karşıda adalar

inci taneleri gibi serpilmiş

saat 10.20

hemşirenin yüzü bıkkın

sırtı açık yakasız bir entari

idamlık mahkumum sanki

soyuldum sedyeye uzattılar

ölmeden ölmüştüm

kefenlenmiş götürülüyordum

zemin kat ilaç kokuları

kaç koridor geçtik

kaç dönemeç döndük

koşuşan panik görevliler

ışıklar..ışıklar ameliyat masaları

yarı aydınlık odalar

yarı çıplak insanlar

sıram gelmeli

gelince de 

bir hemşireye teslim

edildim

lokal anestezi başlıyor …

Mustafa kaya

09.03.2004 / İstanbul', 'saat  9.20 şehrin, tuzlu mavi duruşunda içimi yakan açmazlar ve bin bir ömür çizgileri geziniyor 202 no.lu oda hastahanenin ikinci katı aynı...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/hastahane-gunlugum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Geldi Hüzün Mevsimim', 'geri-geldi-huzun-mevsimim-melih-coskun-4clys', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geri geldi hüzün mevsimim 

Beyazın siyaha meydan okuduğu aşk ayazı

Dar çerçeveli camlarına soluğumun buğusuyla yazılmış yazı 

Her tanesi etime 

Yüreğime işleyen kar beyazı 

Şiir tadında geçip gitmek var bu sulardan 

Dört yanı beyaza sarmalanmış 

Yedi tepeli bir şehrin ortasından 

Ömrüm ufukta kaybolan bir vapur bacası

Hiç dönmemek ihtimalide var artık bu limana

Koskoca bir sayfayı

Hiç yazılmamışçasına yırtıp atmak defterinden 

Hiç yaşamamış gibi 

Kopup gitmek bir şehirden

Geri geldi hüzün mevsimim 

İçimde hep aynı aşkın ayazı 

Kader diye alnımıza yazdıkları kahpe yazı...

2004', 'Geri geldi hüzün mevsimim  Beyazın siyaha meydan okuduğu aşk ayazı Dar çerçeveli camlarına soluğumun buğusuyla yazılmış yazı  Her tanesi eti...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/geri-geldi-huzun-mevsimim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Elim Kanda Olsa Bile Olmayacak Bu İş Heh Yazdım Buraya', 'i-ki-elim-kanda-olsa-bile-olmayacak-bu-i-s-heh-yazdim-buraya-sair-odesus-r3fl8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zaten olmayacağını bildiğim bir aşksın

bile bile sürdüm bulutlarımı toprağının üzerine

senin sularının karışması için sularıma

sonra o suları alıp

koyupta kelime kalıplarına

buzlukta

buz gibi şiirler yapmak için sana

yazın belki meyve suyuna atıp

yudumlarken bir sahil kenarında

tadı ne kadar da tanıdık

ne kadar bildik

dersin diye', 'zaten olmayacağını bildiğim bir aşksın bile bile sürdüm bulutlarımı toprağının üzerine senin sularının karışması için sularıma sonra o sular...', ARRAY['Türk Edebiyatı','Şiir','Şair Odesus']::text[], 8.5, '{"poet":"Şair Odesus","poet_slug":"sair-odesus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iki-elim-kanda-olsa-bile-olmayacak-bu-is-heh-yazdim-buraya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalarım', 'ruyalarim-birsen-ates-djr8b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'öncesinde

kutlu gecesinin

bir rüya gördüm

uçuyordu gökyüzünde

çok güzel biri

peleriniyle

her iki yanında biri.

her yer

yemyeşildi.

bir tepenin üstüne geldiler.

bilmediğim bir duaydı

arapça..

çınlatıyordu her yeri 

bembeyazdı elbiseleri üzerlerinde 

toplanmış kalabalık bakıyordu 

heyecanla o zata

bakıyordum

bende vardım aralarında

kadınların arasından

çağırdı beni

işaret etti 

gel dedi..

erkeklerin arasından

bir de erkek seçti

oturduk önünde. 

içimde de bir kırgınlık 

çınlıyordu

dua beynimde.

neden önde 

oturttu erkeği diye

geçirirken içimden.

kaldırdı gözlerini bana baktı

o anda içime bir huzur yayıldı..

o gün bugündür 

unutmam rüyamı

pırıl pırıl yanan 

o yanık tenli zatı..

07.01.05', 'öncesinde kutlu gecesinin bir rüya gördüm uçuyordu gökyüzünde çok güzel biri peleriniyle her iki yanında biri. her yer yemyeşildi. bir tepen...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ruyalarim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gelmişimdir', 'ben-gelmisimdir-sair-odesus-5paq7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'benle olabilir ancak o 

hüzünlüsündür

ağlıyorsundur

ben gelmişimdir yanına

bitmeyeceğini sandığın bir geceye

doğan güneş gibi

yağmur birden dinemeyecektir elbet

ama güneş açmıştır bir kere işte

tam da bu zamanda olur

ağlarken gülebilirsin

ben gelmişimdir yanına

pencerenden odana sızan

bir demet güneş huzmesi gibi

düşmüşümdür ağlayan yüzüne.', 'benle olabilir ancak o  hüzünlüsündür ağlıyorsundur ben gelmişimdir yanına bitmeyeceğini sandığın bir geceye doğan güneş gibi yağmur birden ...', ARRAY['Türk Edebiyatı','Şiir','Şair Odesus']::text[], 8.5, '{"poet":"Şair Odesus","poet_slug":"sair-odesus","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ben-gelmisimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazamadıklarım', 'yazamadiklarim-ayse-adlim-hgx8k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sana aşığım adam

Her gece 

kelimeler dökülür dilimden

yazamadığım

Damlalar süzülür gözlerimden

sakladığım

Mesajlar yazarım

gönderemediğim

Seni seviyorum adam

Ara bir sor

Bak neler var yüreğimde

Sana hiç söyleyemediğim', 'Ben sana aşığım adam Her gece  kelimeler dökülür dilimden yazamadığım Damlalar süzülür gözlerimden sakladığım Mesajlar yazarım gönderemediği...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yazamadiklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-65 (M.S.) 03/02/2006', 'mektuplar-65-m-s-03-02-2006-mahzun-doga-11u5d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerimde unutulmuş ellerin

Tenime rengin bırakılmış

her kimsem sen gösteriyorum 

aklımda unutulmuş kalbin

sesin dilime bırakılmış

ne desem sen duyuluyorum

yüzüme yüzün yontulmuş

seni buluyor beni arayan

Toplam bir ediyoruz ikimiz birden

ve hasret sıfır gösteriyor', 'Ellerimde unutulmuş ellerin Tenime rengin bırakılmış her kimsem sen gösteriyorum  aklımda unutulmuş kalbin sesin dilime bırakılmış ne desem ...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mektuplar-65-m-s-03-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-66 (M.S.) 04/02/2006', 'mektuplar-66-m-s-04-02-2006-mahzun-doga-5sb55', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidişin yaşam sakarlığı 

telafisiz

zorba

kızsak sabırsızlık

sussak haksızlık

Tehir halinde buluşmamız

sıfır gösteriyor saat

aramızın ortasında

sessizce geçen aynı zaman

ne geç

ne erken

sorumu akrep sokumu 

cevabı yelkovan fırtınası

Gidişin haksızlık

cana bela 

ömre yayılan felaket

yaşam kabalığı

rezalet mi rezalet', 'Gidişin yaşam sakarlığı  telafisiz zorba kızsak sabırsızlık sussak haksızlık Tehir halinde buluşmamız sıfır gösteriyor saat aramızın ortasın...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mektuplar-66-m-s-04-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılan Ömrüm', 'yilan-omrum-muammer-erturan-2tluy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırak masalı falcı! .. 

Üç gün mü desem 

üç hafta mı

üç ay mı 

ayaklarını bırak! .. 

Kavuşmak mavuşmak 

yok artık…

O, 

artık yok... 

Bırak mavalı falcı! .. 

Olacakları söyle 

bundan böyle... 

Nasıl geçer o olmadan 

kalan ömrüm 

yalan ömrüm 

yılan ömrüm? .. 

De hele! .. 

(''96)', 'Bırak masalı falcı! ..  Üç gün mü desem  üç hafta mı üç ay mı  ayaklarını bırak! ..  Kavuşmak mavuşmak  yok artık… O,  artık yok...  Bırak m...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yilan-omrum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-ayse-adlim-j2v2c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk ıstıraptır

Çekmekten bıkmadığım

Kurtar beni diye Allah''a

Asla yalvarmadığım', 'Aşk ıstıraptır Çekmekten bıkmadığım Kurtar beni diye Allah''a Asla yalvarmadığım...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-532-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Aşk', 'sonsuz-ask-ethem-turan-bhfov', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yangınlar içinde

Sana sitem dolu gönlüm

Suda boğulan insan gibi

Her ağzımı açıp bağırmak istediğimde

Tıkanıyorum

Yutuyorum içimdeki zehri tekrar

Göğsüme ağrılar doluyor

Kahreden yaşamıma

Kaldığım yerden devam ediyorum 

Vücudumun sızıları 

Karabasan gibi çöküyor üstüme

Gelmeyeceğini biliyorum ama işte

Yine bağırmak istiyorum

Kurtar beni diye 

Seni görmek istiyorum 

Görmemeliyim biliyorum 

Konuşmak istiyorum 

Konuşmamalıyım onu da biliyorum 

Ne yapmalıyım işte onu bilemiyorum 

Gece olduğunda ıssız  yerlerde 

Senin adını bağırabiliyorum

Yudum yudum seni içip 

Yüksek yerlere çıkıp düşleyebiliyorum

Yeter deme sakın 

Yetmiyor,onu da biliyorum.

Bilmeni istiyorum

Avucuna aldığın kar tanesinin erimesi gibi

Senin için eriyip gidiyorum 

Gün gün  yok oluyorum

Sana kapılmadan önce 

Sevgiye aç  bir gönül 

Hayatı ve insanları kabullenen bir ruhum vardı

Şimdi,gönlünü ve ruhunu yok ettiğin bu kölenin 

Son bir isteği var senden

Sonsuzluğa göç ettiğimde 

Kabrimi ziyarete gel 

Gözünden bir damla yaş akıtmadan

Yaşarken ezdiğin gibi 

Toprağımı ezmeden 

Elimi tutarmış gibi

Bir avuç toprağımı  tut

Tut ki gözümde kalan son bir yaş damlası

Toprak altında mutluluktan aksın', 'Yangınlar içinde Sana sitem dolu gönlüm Suda boğulan insan gibi Her ağzımı açıp bağırmak istediğimde Tıkanıyorum Yutuyorum içimdeki zehri te...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sonsuz-ask-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birleşeceğiz', 'birlesecegiz-suleyman-yavuz-k4sai', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiir yazarım budur benim halim

Elbet gün doğacak bana da

Sen yanımda olunca

Elin elime değdiğinde 

Ruhumu sesin okşadığında 

Mesut olacağız biz seninle

Ne ölüm geçmeli önümüze 

Ne de kötü

Arada mesafeler olsa da 

Kalbimiz hep bir durmalı

Bir gün gelince kavuşacak eller

Gözler dudaklarımızdan akacak 

Nice sevgi dolu sözler

Bu kez mutluluğa akacak yaşlar

Kavuşacağız biz âşıklar

Yanacak ayrılık ve hasret

Kül olup gidecek 

Geri de bir sen birde ben kalacağız

Ömür boyu ayrılmayacağız', 'Şiir yazarım budur benim halim Elbet gün doğacak bana da Sen yanımda olunca Elin elime değdiğinde  Ruhumu sesin okşadığında  Mesut olacağız ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/birlesecegiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapsa', 'kapsa-ayse-adlim-8riey', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimi kapsadın

Beynimi çoktan

Şimdi sıra dudağımda 

Onu da kapsasana', 'Yüreğimi kapsadın Beynimi çoktan Şimdi sıra dudağımda  Onu da kapsasana...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kapsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet Ne Olur', 'affet-ne-olur-suleyman-yavuz-5kzn3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu geceler bitmez bana 

Zehir oldu senden ayrıldım ayrılalı 

Her an her saat bekledim 

Aradım hep bir fırsat 

Görmek için seni 

Özledim sevdiğim özledim 

Gittiğim için affet beni 

Ama yandın hep içimde için için 

Ölürüm bir tel saçın için 

Döndüm sevdiğim 

Beni affetmen için', 'Bu geceler bitmez bana  Zehir oldu senden ayrıldım ayrılalı  Her an her saat bekledim  Aradım hep bir fırsat  Görmek için seni  Özledim sevd...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/affet-ne-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldim Sana', 'geldim-sana-suleyman-yavuz-ba4nw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geldim uzaktan çok uzaktan

Geçtim ne acıdan ve tuzaktan

Döndüm kollarına al beni

Ölüm senle gelsin bırakma beni

İnanmasan da ben çok sevdim seni

Yalan desende ölüm kıskacındayım

Asla yalan olmaz dilimde adın

Azrail almaya gelmiş canımı

Ölürken bile zikredeceğim 

SEVDİCEĞİM adın', 'Geldim uzaktan çok uzaktan Geçtim ne acıdan ve tuzaktan Döndüm kollarına al beni Ölüm senle gelsin bırakma beni İnanmasan da ben çok sevdim ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/geldim-sana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-67 (M.S.) 05/02/2006', 'mektuplar-67-m-s-05-02-2006-mahzun-doga-fzh3z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüzünün  öbür yarısı

asî ve inatkâr

incir yaprağı altında

bir köşesinde gözlerim

ve dudak yarası

Yüzünün öbür yarası

eski ve aşîkâr

ağ ve perde tozu altında

bir köşesinde özlemim

ve duvak yarası

Yüzünün öbür yakası

uzak ve umutkâr

gizli bir geçit sonunda

bir ucunda gözlerin

ve durak yarası

Yüzünün alenisi eski günah yarısı

asil ve sevapkâr

elmas bir gül dalında

bir yaprağında masumiyetim

ve budak yarası', 'Yüzünün  öbür yarısı asî ve inatkâr incir yaprağı altında bir köşesinde gözlerim ve dudak yarası Yüzünün öbür yarası eski ve aşîkâr ağ ve pe...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mektuplar-67-m-s-05-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döndüm', 'dondum-suleyman-yavuz-3zjxv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıl oldu ayrı düşeli seninle 

Döndüm bak geri yine

Özledim bir tanem özledim işte 

Ama sen gideli olmuş epey bir zaman

Ömür geçiyor dönmelisin 

Durmuyor ne hayat nede zaman

Kaybetmeye değer mi 

Hiç aşk ile sevgi

Değmez bana inan', 'Yıl oldu ayrı düşeli seninle  Döndüm bak geri yine Özledim bir tanem özledim işte  Ama sen gideli olmuş epey bir zaman Ömür geçiyor dönmelis...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dondum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Gidersin', 'nereye-gidersin-derin-oger-weel2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'içim bin hüzün düşünür seni

geleceksen başıma seyrek yağma yağmur

varlığını duyan yürek sıyrılır uykusundan

iki gözüm yüzüme yıldız dökülür

sel olmadan taşırır beni

çığlığının ruhu rüzgâr

alevimden bir kara bulut geçer 

dağlarımı ıslatmaz suyu yorma gözlerini 

dalgaların kıyıya vurduğu çakıl misali

toza toprağa bular beni

gün karış yürek eskitir

gece derin soluklarla içine çeker beni

banyoda damlayan musluğun sesi

gözlerimi yere eğip hatırlatır masal günlerimizi

mendil sallatır canlı sanır beni...', 'içim bin hüzün düşünür seni geleceksen başıma seyrek yağma yağmur varlığını duyan yürek sıyrılır uykusundan iki gözüm yüzüme yıldız dökülür ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nereye-gidersin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüdük mü?', 'buyuduk-mu-birsen-ates-w13ij', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'masumduk

küçücük bir çocuktan farksız

büyüdük yalanlarla

hayatı hep toz pembe sandık

çekince dertlerini hayatın

şimdi 

büyüdük mü 

ne aşklar gördüm 

benliğimi sarsan

utandıran düşlerde beni

ne yalan sevdalar çıkmış karşıma

yıllar sonra ağlatan

  

06.02.06', 'masumduk küçücük bir çocuktan farksız büyüdük yalanlarla hayatı hep toz pembe sandık çekince dertlerini hayatın şimdi  büyüdük mü  ne aşklar...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/buyuduk-mu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen suçlusun....', 'sen-suclusun-ercan-akbay-106kw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unutuldun sanma sakın

   Unuttuysan sen unuttun

   Yüreğimde hala aşkın

   Bulmuyorsan sen suçlusun.

   İşte güfte,işte beste

   Şarkıları duymuyorsun

   Gönlüm sanki bir kafeste

   Açmıyorsan sen suçlusun.

   İnan sana küs değilim

   Neden kaçıp, birden sustun

   Şu kalbimi sana verdim

   Almıyorsan sen suçlusun.

   Güneş batar gece başlar

   Özlem nedir bilmiyorsun

   Gözümde var senli yaşlar

   Silmiyorsan sen suçlusun....

                        13.6.1991

   Hicaz şarkı

   Beste...İsmail Ötenkaya', 'Unutuldun sanma sakın    Unuttuysan sen unuttun    Yüreğimde hala aşkın    Bulmuyorsan sen suçlusun.    İşte güfte,işte beste    Şarkıları d...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-suclusun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lal', 'lal-tarkan-ragipoglu-zrumi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağulu sözler sırra kadem çığlık  bozuyor ağzımın tadını...

İki paket cıgaraya aralıksız ard arda sözler acıtıyor gırtlağımı...

Lal oluyorsun sen karanlığın ortasında bağ bozumu... 

Kırsın diye aynaları çirkinliğim 

yığılsın diye kapılarına 

ses oluyorsun kana yakın,kandan uzak 

kanayarak...

Lal oluyorsun sen karanlığın ortasında bağ bozumu...

Çifte utanç...

Bakamıyorsun yüzüne kimselerin

Susuyorsun sesin dirimidir çünkü sözde ihanetin', 'Ağulu sözler sırra kadem çığlık  bozuyor ağzımın tadını... İki paket cıgaraya aralıksız ard arda sözler acıtıyor gırtlağımı... Lal oluyorsun...', ARRAY['Türk Edebiyatı','Şiir','Tarkan Ragıpoğlu']::text[], 8.5, '{"poet":"Tarkan Ragıpoğlu","poet_slug":"tarkan-ragipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/lal-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Olur mu?', 'gel-olur-mu-humeyra-yildiz-dnlha', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'artık sabır yetmiyor be bitanem..

sen tütüyorsun 

sen geliyorsun 

sen gidiyorsun

sen otuyor 

sen kalkıyorsun bu limandan...

zaman dondu sanki...

cunku heryerde 

sen varsın artık..

rahatlamam lazım 

yanımda olman lazım 

konuşmasak ta 

suskunlugunda erisem 

aldıgın solugu duymak 

bir ömre deger biliyor musun? 

bakmasakta birbirimize,

denize, ucan kusa, 

kosan bir cocuga bakısında 

her yerde bana bakar gibisin

yeter ki yanımda ol..

hatta seni beklesem 

ama sen gelmesen dahi 

rahatlarım...

kaçmam lazım herşeyden 

hatta herkesten 

sadece sen... 

bir fırtınada su alan bir gemideyim 

ve sıgınacağım tek liman sensin...

bekliyorum

bekliyorum 

gel...gel...gel olur mu?', 'artık sabır yetmiyor be bitanem.. sen tütüyorsun  sen geliyorsun  sen gidiyorsun sen otuyor  sen kalkıyorsun bu limandan... zaman dondu sank...', ARRAY['Türk Edebiyatı','Şiir','Humeyra Yildiz']::text[], 8.5, '{"poet":"Humeyra Yildiz","poet_slug":"humeyra-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gel-olur-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöle Düştü Yüreğim', 'cole-dustu-yuregim-guzin-eye-dundar-8sgha', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapımı araladım, 

gelen sahibimdi

tenimde kaldı gözyaşı

geceye uzadı ışıklarım 

uzakların çağrısını 

aldı ve gitti

çöle düştü  yüreğim  

......ötelerde kaldım

çoğaldı yokluğu

dilimde alıngan adı  gidenin

ne diller dokundu

suskunluğuma 

kaç iklim sardı tutkulu

gizli bahçelere ektim  umudu

İlgisiz mekanlara taşıdım gözlerini 

dilsiz duvarlar  yıkıldı

yokluğuna taşındı

içimde ki masum çocuk

yaşamak isterdi

sisli sabahlarında

sensizlik sardı tenimi 

bensiz  yürüyorum

bir dilim  kaldı sevda

ne söylediğini bilmiyor hasret 

soluk alamıyorum 

tükendi kokusu teninin 

bunun için döküldüm

sisli sabahlara

sınırlar çizildi

içlenmeler sardı İzmir i 

yüzümdeki serinlik rüzgar değil

karanlığın değdi

hedefsiz başlangıçsız  yollara düştüm

sislerin içinde ki senden 

ışığa  kavuşacaktım

kızgın ateşine tan  yerinin

istersen dokunacaktım

bir günlük kelebek olmak yeterdi yanında 

körfez gibi karıştı renklerim 

dudakların değse tuzuma durulacaktım.', 'Kapımı araladım,  gelen sahibimdi tenimde kaldı gözyaşı geceye uzadı ışıklarım  uzakların çağrısını  aldı ve gitti çöle düştü  yüreğim   ......', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/cole-dustu-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın iki yüzü', 'sevdanin-iki-yuzu-sinan-aydindag-1fdlk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '04.Şubat.2006

Sevdanın iki yüzü var birini sana yaşatıyorum

Diğerini kendim yaşıyorum

Sende yaşadığım ve yaşattığım aşk, sevgi

Bende yaşayan ise hasret ve acı

Yanındayken nedense her şey daha bir anlamlı oluyor

Yollar sokaklar sanki her şey sevgi doluyor

Hani hatırlar mısın? 

Çocukken bayram sabahları

Bir heyecan dolar ya içine

İşte seninleyken böyle duygular dolar içime

Sevinir sevinir dururum

Birde sensizlik var bu hayatta

Düşün şimdi güzelim

Küçüksün... 

Elinden en sevdiğin oyuncağını alıyorlar

Ne büyük bir çaresizlik değil mi? 

Her gidişinde böyle duygularla baş başayım işte

Kara karamsar yaşanası olmayan bir yaşam gibi

Hiç güneşi açmayan, hep bulutlu olan şehirler gibi

Dalından zamansız kopmuş bir yaprak gibi

Yokluğunda sararıp solmamak elde değil ki

Hep seninle sevmek hep seninle sevilmek dileğiyle', '04.Şubat.2006 Sevdanın iki yüzü var birini sana yaşatıyorum Diğerini kendim yaşıyorum Sende yaşadığım ve yaşattığım aşk, sevgi Bende yaşayan...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevdanin-iki-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temren', 'temren-guney-donmez-ld72h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'temrenli bu sevda,

deşti göğsümü.

sırat köprüsünden geçmeden, 

kara yemiş fidanına doymadan,

peyderpey, 

öldürür beni.

yaslı rügarın silüeti,

mütemadi düşmüş gönlüme de,

bitablığımı hoş görün.

keşmekeş bu arya,

çetrefil bu dil,

ve,

doğaçlama bu şiir.

melankolik olamadım aşka,

temrenli bu sevda,

deşti göğsümü,

dehlizleriyle,

musalla taşında ömrüm.

bir yanda,

aforoz edilmiş gençliğim,

bir yanda 

kansere savaş açan sevdiğim

hakeza duygularla,

bizar bu adam.

debdebeli de olsa, 

beyeban bu dünya,

müptezel insanlara kanmış yarınlar,

bopstile hediye edilmiş yosmalar,

kendini hediye etmiş,

naçar,

zavallı,

ototrof kızlar. 

kent içinde yeis rüzgarları estiren şirretler,

ve müstenit benim cefam,

ve bir yanda,

temrenli sevdam,

geçiyor ömrümün ortasından.

tağyir etmem kendimi,

hatta ne mutlu bana,

serzeniş etmeden,

taşıyabiliyorsam bu seviyi.

selam olsun benden,

sevda uğruna,

cemal burcunda,

tüten hayatlara.', 'temrenli bu sevda, deşti göğsümü. sırat köprüsünden geçmeden,  kara yemiş fidanına doymadan, peyderpey,  öldürür beni. yaslı rügarın silüeti...', ARRAY['Türk Edebiyatı','Şiir','Güney Dönmez']::text[], 8.5, '{"poet":"Güney Dönmez","poet_slug":"guney-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/temren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Aşık Bir Ruh''la....', 'sana-asik-bir-ruh-la-hatice-guler-r0c2k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevda yoluna bir de sen hasret ektin

Şimdi kavuşturdun bu ayrılmaz ikiliyi

Sen kendi derdinde,ben hasretimle

Binbir güçlükle geçireceğim günlerimi.

Aklım

Fikrim

Gözüm

Sözüm

Özüm

Ruhum ve de bedenime sığmayan

Kalbim ve duygularım

Seninle bir

Seninle yanık

Seninle ve de sana aşık....', 'Sevda yoluna bir de sen hasret ektin Şimdi kavuşturdun bu ayrılmaz ikiliyi Sen kendi derdinde,ben hasretimle Binbir güçlükle geçireceğim gün...', ARRAY['Türk Edebiyatı','Şiir','Hatice Güler']::text[], 8.5, '{"poet":"Hatice Güler","poet_slug":"hatice-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sana-asik-bir-ruh-la-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Son Kararım', 'en-son-kararim-hatice-guler-2l1f9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevmek

Verdiğim en doğru kararım

Seni sevmek

Verdiğim en son kararım

Seni sevmek

Seni sevmek

Seni sevmek

Ömrümce aldığım

Ömrümce alacağım

Ömrümce soldurmayacağım

En nadide,en sevdalı,en özel

En tutkulu,en arzulu...

İnatla beni sana kavuşturacak

Ebedi beni senden ayırmayacak

En içten duam...', 'Seni sevmek Verdiğim en doğru kararım Seni sevmek Verdiğim en son kararım Seni sevmek Seni sevmek Seni sevmek Ömrümce aldığım Ömrümce alacağ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Güler']::text[], 8.5, '{"poet":"Hatice Güler","poet_slug":"hatice-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/en-son-kararim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu aşk beni kül eyledi!', 'bu-ask-beni-kul-eyledi-mikdat-bal-axq61', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağlayarak ah ederim

Bu aşk beni kül eyledi

Gâh dururum, gâh giderim

Bu aşk beni kül eyledi

Bazı dondum bazı yandım

Döndüm döndüm yine andım

Yudum yudum içtim kandım

Bu aşk beni kül eyledi

Günden güne eriyorum

Yana yana yürüyorum

Dertten derde giriyorum

Bu aşk beni kül eyledi

İçim yara dışım yara

Bu aşk beni yaktı nârâ

Ayrı düştüm bahtım kara

Bu aşk beni kül eyledi

Bundan gayri yolumsun sen

Dikenimsin gülümsün sen

Bana tatlı ölümsün sen

Bu aşk beni kül eyledi

Çölden geçtim dağdan aştım

Çaresiz bir derde düştüm

Hasretine yandım piştim

Bu aşk beni kül eyledi

Mikdat der ki ben aşığım

Ben bu derde alışığım

Güneş, ayım ey ışığım

Bu aşk beni kül eyledi', 'Ağlayarak ah ederim Bu aşk beni kül eyledi Gâh dururum, gâh giderim Bu aşk beni kül eyledi Bazı dondum bazı yandım Döndüm döndüm yine andım ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bu-ask-beni-kul-eyledi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul hala karlı mı?', 'i-stanbul-hala-karli-mi-berk-gulen-j2yzq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstanbul hala karlı mı? 

Yalnız mı sokaklar bu günlerde? 

Yoksa aynı sokak çocukları mı var caddelerde? 

Tek sadık dostları İstanbul''un...

İstanbul hala soğuk mu,? 

Caddelerde sadece sevgililer mi var ısıtan etrafı? 

Yoksa güvercinler gelmiyor mu meydanlara

Birkaç buğday için bile artık..

İstanbul hala aşk mı kokuyor? 

Uçsuz bucaksız, Samatyadan Bebeğe..

İstanbul''uma ne oldu da ışıklar yanlız kaldı,

Bana ne oldu da bu kadar hislendim,

Neden yazmadım bunları yıllarca, 

Madem yıllardır içimde vardı,

Demek ki bir tek beni İstanbul sardı...', 'İstanbul hala karlı mı?  Yalnız mı sokaklar bu günlerde?  Yoksa aynı sokak çocukları mı var caddelerde?  Tek sadık dostları İstanbul''un... İ...', ARRAY['Türk Edebiyatı','Şiir','Berk Gülen']::text[], 8.5, '{"poet":"Berk Gülen","poet_slug":"berk-gulen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istanbul-hala-karli-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-ulker-kara-wjofi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığında, sessizliğinde

Penceresinin kenarına 

Bir kadın oturmuş yapayalnız

Suçlanmaktan kırılmış, üzülmüş besbelli

Yaşam ağır gelmiş omuzlarına

Gitmeliyim gitmeliyim diye haykırıyor Sessizc

Hislerini gecenin karanlığına

Sessizliğini gecenin sessizliğine bırakmış.', 'Gecenin karanlığında, sessizliğinde Penceresinin kenarına  Bir kadın oturmuş yapayalnız Suçlanmaktan kırılmış, üzülmüş besbelli Yaşam ağır g...', ARRAY['Türk Edebiyatı','Şiir','Ülker Kara']::text[], 8.5, '{"poet":"Ülker Kara","poet_slug":"ulker-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sessizlik-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarayevo''dan', 'sarayevo-dan-akin-akca-qbi6k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kavaçi Gırbavitza mahallesi, ağaçlıklı ve açık yemyeşil; 

Osmanlı hamamı içinde’n bir başka imparatorluk Pontus

Ve uzar böyle gider insanlık tarihi rus bebekleri –

Atom üstlerinden sanki farklı lezzetteki  6 kuarklara; 

Yıldızlardan ama sümüklüböcek şeklendirilmiş

Galaksilere, ceviz gibi bağırsak ve beyin, sağanak …

İmparatorluklar taşıyan toprakların Trabzon’unda,

Santa Maria Kilisesi’nin sevilgen papazının öldürülüşü,

Keskin nişancılarına benziyor akıl dışı Bosna Savaşı’nın.

Birinci Dünya Savaşı başlatıcısı bir kötücül deli,

Karşı beyaz binaları çatılarındaydı Kavaçi Gırbavitza’nın.

Tam da şu karikatür krizine denk geldi, sersemlik geçidine; 

Eskiden olan savaşlar burada, Boşnaklar, Hırvatlar,

Sırplar ki aslında Sırbistan Karadağlılar.. Slovaklar, Çekler …

Camiler, sinagoglar, kiliseler ve sosyal zaman kalıtları

İle Doğu ve Batı’nın Greenwich’i Sarayevo; 

Granada - Al Hamra işlev görmüşlüğü İspanya’nın

Bir ölçüde benzetilebilir, o zaman akla gelir:

Sırp nişancıları neden Madrid’i bombalamamıştı? 

Avrupa’nın Kudüs’ü tanımlanan, tam bir kültür başkentiymiş

Ve işin garibi, o Kovaçi mahallesi, çok ağaçlıklı, cıvıl; 

Dini savaşa araç yapanlara sormalı, insanlık katl’lerini! ! ! 

Sarayevo’da buldu şair, yazar, mizah sahibi Hüseyin *

Baş’ı Vivet Kanetti (Bennu Gerede’ye çektiği o klibe benzer

Hüseyin Çağlayan’ın, bir uzay mekiğimdevari’de asfaltta) 

Goran Bregoviç’in konserini izlemeye gelmiş,* oturmuş cafeye.

İki tarafın da radikal hamasi takkeli züppeleri,

Diğer zıt ucunu ama B. TOMYO’daydı da sizin – 1

Züppe ama zengin, ayrımc’l, ekiden (’92-’99 zam(an) ları,

’99-‘o1 zamanları değil)  Takkesiz, sakalsız ama 

Aşk/ sevgi kazanmak denli, uzak olan bu değerlere.

Büyük çoğunluğu Bogomiller’di.. Boşnakların –

Bir eski Orta Asya dini, sonra Vatikan geldi

Ve Macarlar da..:yok etmeye başladılar…

Ne var ki engelleyemedi Báthory Erzsébet; 

Gelişini Türkler’in, Bosna’ya Boşnaklar’a yardıma.2

Faith, Fatih3 buradaydı; Müslüman sonra oldu

Bu süreçten, Boşnaklar –öncesinde Bogomil.

Yardım din adına gelmemiş, gelmişti yardım adına! ! 

Hayrettin Usta ki koca Mimar Sinan öğrencisi,

İşte şu köprüyü inşa etti Bosna’nın kalbine Mostar! 

Barış olsun diye, Boşnaklar’a bir kanıt, yani onlar hk.

Sonra geldi yıktı Hırvatlar, hiç düşünmeksizin nakş

Fakat anılar kazınır tarih boyu böyle, fidan gönüllere

Ve geleceğe bir güç, ruhları serpilerek yaşatmaya! ! 

Avrupa’nın “dayak yiyen”, “sünnetli”, “jambonlu..” yumur

“..Yumurta yemeyen çocuğu”, üzülme hiç sen; 

“Hristiyan Slav” turistler gelir,o güzel sokaklarda sorar: 4

“İnançlı mısınız? ” Cevapsa,Oh, evet! Amon Re Aman … 5

Hemen korkarlar.. ki (ekleyivermişler) : “Bir tehlikesiniz! ”

Bazı eski inananlar kapalı, çoğu kapanmaz inançlarında; 

Sarayevo ne kadar da benziyor Türkiye’ye –sanırsam,

Tarihi de Osmanlı’ya, uzanır giderken tozlu eskilere …

Yanlış anlaşılmasın, ‘hadislerin kuşatması altınca olan 

Ayetlerin..’ kuşatılmıştır ‘..dini’; bu hadislerin çevrelediği,

Öyle ya da böyle, bir dünya tarihidir aynı zamanda.

Kah empozeci Katoliklik, bağnaz yanı Müslümanlığın hem; 

Belki şayetse headbang ya da aczimendi törenlerince, 

Astara değil siyaha bürünmüş, kara sakallı mormonların.

Rahat yaşamaları için rahat bırakın insanaları! 

Dinin ne olduğunu algılamalarına fırsat vermiyorsunuz; 

Bir fırsat, barış yüceltmeleri için, pınarsa var! ! 

M. Ali Erbil’in tv. Şovunda, Simoviç eski günler anısına,

Top kalede tutmada; Katanec gibi, Katana 6

Tarihin dokusunda, güler, gülümsetir, gülümser.

Sanki pek konuşmaz yöneltilen laflamalara,

Espirilere, ama gülümser, ya da şuursuz lakaytlıklara.

Endüstri Devrimi ve gelişen ekomiyle şaha-vücd Batı; 

Kökten dincileri çok sofu Ve ayıraç, olanı korkutucu.

Radikal böyle olmasın insan bir, kullanır dini,

Kullanır ekonomiyi, çıkar ummaya başlar her bir şeyden.

Çoğunluğu olan “İslam dünyası fukaralığı ve cehaleti”,

“Kenar bazı erbunak kışkırtmalarına” Hristiyanlığın; 

İşte hemen kapar baltaları altından toprağın, çığırır cihat …

Aptal kısımları hadislerin; barışa yaramaz, harbe yamanır.

Tanrı korkusunu bile bazı çevreler –ki bu aslında

Olmamalıdır-,her iki yakadan kendilerini sınırlayamaz,

Nefslerine, tüh, kendileri yön veremez, bilinçleri …

Savaşlara yön veren ne o dindir, ne de bu dindir; 

İnsanlık içgüdülerinin derinine inen bir korkuda saklıdır.

Değildir; korkmamak.. da, ölümü göze almayı bilmek

Bunu bilmek, kaldı ki; her zaman ölüp ölüp değildir

Dirilmek de Ama bazen ölümü göze alacak

O cesareti sergilemek -ki Osman Pamukoğlu, oh:

“Atılmak siyasete polemiktir, kompleks sahipliği..” 7

- Korkuları yenmektir -zamanın çıkardığı Atatürk,

Politika yapmadı ki, koşuların dimdikleştirdiği ortaya! ! 

- Ve din savaşlarını! ... Ve Göktürk’lerden ateş 

Ve göktanrı’ya inerek Ve Kelt şafağı’na değin 8

Şairin, inerek William Butler’ın, Niffleheim’a Yggdrasil 9

Dünya Ağacı’na Germen veya Göllerin Hanımı’nın

Suskun apseli gamzeli ancak pıhtı ihtivalı; Guinevere’nin 1o

Düşüncesiz aldatışı’nda ki bir krallığı hatta,

Arthur’u savurup atmasıyla … Genghis’in o bir Çin 11

Sarayı’nı inşa edişindeki tempo tutturulmak

Zorunda bırakılışı emektar-haklı Samuel Taylor tarafından –

Müzikle inşa eden asıl kendisiydi- işçi’si bile oluşu,

Tempo tutturmaksı(na)  zorunlu bırakırken görevi Genghis’e; 

Şairin estetik-empati duyarlılığını serpiler, kubi’ye iletilen 

… Bir garip döngü. İnerek esas, buralara; 

Tüm insani ulvi değerleri çıkartmaktır gün ışığına! ! ! 

Ya, Tremors! 12 O kocaman toprak 

Solucanları ayaklarımızın altında, bizi dibe çalışıyor

Çekmeye Ve bizler sadece seyrediyoruz, zorunlu muyuz? ? 

Çaremiz yokmuş gibi! ne budalalık: Sankidir, sevgili

Bir ses verse; her şey hallolacak, çünkü anlaşılacak …

Tut bizi Bosnia Herzigovina, orası bizim de yurdumuz, 13

Osmanlı’dan Türkiye ki Bulgaristan, Makedonya v.s.

Bak işte, İslamiye Sarıyer Köyü’nden Bulgaristan’ın; 

Başlarmış Türkiye göçü Anadolu’ya baba’nın

Babalar tarafında, Romanya üzerli..ki annesi de

Selanik’ten, varan bir Ata, varan iki Abdi İpekçi

Vesaire …Kırım tatarı asıllı anneanne ise; 

Dede, Ayaş: Ayaş, çok yaşa Ayaş! Ve Kızılcahamam 

Anne, çok yaşa, kızılca! Hafız ama felsefeci, Dedekorkut; 

Okur yazar nüfusun ışıtır Ayaş, Milli Eğitim’i.

Kırım tatarı da anneanne, teyze neden Kıpçak Türkü; 

Meğer anladım ki, gelmiş yerleşmişler sonradan.

Be, ne tuhaf işler bunlar; hısım ne, ya görümce

Buna göre nasıl? Göre bana, örümcek maymunu 

Eteğe dağ yamacından, ağaca ki zıplayıp gene havalana.

bak Bay Konar –akrepyal kelebek işte uçuşkan nötr sinek, 

Sokar- taşıyoruz büyük uzay üssünü Anıtkabir’den Trakya.

Haydi yelkenler fora, büyükçe bir bodoslama, manevral! ! ! 

Mostar köprüler görüyoruz yerleştirdiğimiz Boğaziçi

pek farksızsın hala, sıcacık insanlar ve

yavrucuk vatan, aldanma, önemsenensin; 

dünya bir bilye, düzle düzle evreni yuvarla; 

Aynı ulaştırıcılar, eğilmeyen sevgiler güzel kene

Açıklamalar:

Asteriks işaretleri, benzeşen noktaları açıklamakta

1 bilkent Turizm ve Meslek Yüksek O.

2. Elizbeth Bathory Carpathian Dark Countess yaşamış bir şahsiyet

3. burada “ezginin günlüğü” arkadaşın ufak katkı ilhamına tşkler.

4. Bu tırnaktakiler, tv belgeselden ilhama alıntı

5. belgeseldeki bi Boşnak kadının ağzından (gene tırnaktakiler) 

6. Katanec eski bir Yugoslav milli takım futbolcusu, Simoviç eski gs’li

7. Osman Pamukoğlu’ndan şeklen esneterek alıntı

8. Kelt Şafağı, W. B. Yeats (bir şiir adı) 

9. Alman efsanesinde dünya ağacı dokuz dünyaya köklerini salar.

   Niffleheim’da böyle bir dünya(ya örnek) 

1o. Arthur efsaneleri ve Gölelrin hanımı vs Merlin, Frigg …

11. Kubilay Han’a Coleridge yorumu (ref. “Kubla Khan” şiiri – ben olayı Genghis Khan’a 

   kadar aldım, Kubilay’ı bir ölçmek babında) 

12. bir film. Dev solucanlar amerikan kasabasını işgal ediyor v.s. (oyn. Kevin Bacon..) 

13. buradan itibaren aile kısaca secere :)  ama bölümün uzunluğu “tut bizi Bosna “lafıyla şiirin 

   baş bölüme daha bir bağlantılandı, (sanırım)  bölümü açıklayan bu rakamdaki sonrakisel dizede

   Bosna’ya “Bosnia Herzigovina” deme sebebim, “tut bizi geliyoruz” dediğim a.b. kıta 

   sahanlığına direktifen …

not. Baştaki santa maria olayı kısımları, güncel bir haber üzerine

tam adı: Sarayevo’dan (bir çeşit- Dinler Muhakemesi) 

‘o6 6. Şbt Pzt', 'Kavaçi Gırbavitza mahallesi, ağaçlıklı ve açık yemyeşil;  Osmanlı hamamı içinde’n bir başka imparatorluk Pontus Ve uzar böyle gider insanlık...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":152,"source_url":"https://www.antoloji.com/sarayevo-dan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Figan iste', 'figan-iste-umit-isikdag-u0lvg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Figan iste feryad iste gönül

Şehrimdeki yedi tepe de siste...

Ay akiste,ve zihnim kimbilir hangi hapiste

Tuba iste,ırmak iste gönül

Sen yalvar cennet iste, bunca günah üste

Diken dolu gül,ve kırık kalpler deste', 'Figan iste feryad iste gönül Şehrimdeki yedi tepe de siste... Ay akiste,ve zihnim kimbilir hangi hapiste Tuba iste,ırmak iste gönül Sen yalv...', ARRAY['Türk Edebiyatı','Şiir','Ümit Işıkdağ']::text[], 8.5, '{"poet":"Ümit Işıkdağ","poet_slug":"umit-isikdag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/figan-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahu zar içinde geçen yıllarım', 'ahu-zar-icinde-gecen-yillarim-mikdat-bal-xvv91', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ahu zar içinde geçen yıllarım

Gör başıma neler getirdi anam

Esti deli poyraz kırdı dallarım

Kır başıma neler getirdi anam

Eğilirim ama kırılmam derdim

Vefasız dünyaya ömrümü verdim

Heves bitti artık sona mı erdim

Yar başıma neler getirdi anam

Artık dayanmıyor özüm pek  zarif

Dertler yüce kalem edemez tarif

Bu figanı anlar gören her arif

zor başıma neler getirdi anam

Zaman daraldıkça aşkım artıyor

Akıl inkar eder gönül tartıyor

Şeytan bırakmıyor nefis dürtüyor

Şer başıma neler getirdi anam

Mikdatî, kederi eken şu zaman

Gam kasavet çekilmiyor el aman

Sanırdım yıkılmaz koca bir kirman

Sur başıma neler getirdi anam', 'Ahu zar içinde geçen yıllarım Gör başıma neler getirdi anam Esti deli poyraz kırdı dallarım Kır başıma neler getirdi anam Eğilirim ama kırıl...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ahu-zar-icinde-gecen-yillarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Ağrısı', 'yurek-agrisi-sadettin-deren-irjfk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni yaşamak sensizken

En çok bastırdı,ezdi yüreğimi.

Madem vardın,neden yoktun? 

Ruhsuz bir bedendim,çengellerde asılı kaldım,

Al beni artık,al beni kurtar.

Sanki büyüyor kahkahaların yokluğunda,

Atardamarımda kan yok görmüyorsun,

Denizanaları yiyorlar tırnaklarımı,

Ellerim bir dal arıyor tutunacak yetiş artık,

Zavallı dudaklarım seni kanıyor bir umut,

Bir güvercinsin uzaklardan bana kanat çırpan,

İliştirilmiş bir çiçek sanki saçlarında,

Nakış-nakış ağrıyan yüreğim.', 'Seni yaşamak sensizken En çok bastırdı,ezdi yüreğimi. Madem vardın,neden yoktun?  Ruhsuz bir bedendim,çengellerde asılı kaldım, Al beni artı...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Deren']::text[], 8.5, '{"poet":"Sadettin Deren","poet_slug":"sadettin-deren","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yurek-agrisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Treni kaçırdık', 'treni-kacirdik-i-lhami-arslantas-fsd60', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gurbet elde bir hal gelirse baş’a,

Halini arayıp soran bulunmaz.

Yüreğin kafeste çırpınır boşa,

Hasret yarasını saran bulunmaz.

Evine girersin ev başa çöker,

Dışarı çıkarsın el dudak büker,

Sahibin yok ise kahrın kim çeker,

Virane bağını deren bulunmaz.

Buram buram sıla tüter gözünde, 

Viran halin matem olur sazında,

Dört mevsimin kışa döner özünde,

Mayısta bahara giren bulunmaz.

Kadim dostlar medet etmez el olur,

Ela gözler ağlar ağlar sel olur,

Başın dara düşer serin del olur,

Delinin bendini gören bulunmaz.

El ayaktan yüzden kanın çekilir,

Suyun ısıtılır, kefen dikilir,

Boyun ölçüsünde tabut çakılır,

Belki de bir mana veren bulunmaz.

Der ilhami derya geçtim boyladım,

Saz ile söz ile gönül eyledim,

Desem sevdim başka kime neyledim,

Bu saatten sonra tren bulunmaz.

NOT: Değerli arkadaşlar acı da olsa bunlar yaşadıklarımz

elbette arzuladıklarımız değil

Bu halde yaşayan insanlarımızın varlığını unutmamalıyız saygılarımla', 'Gurbet elde bir hal gelirse baş’a, Halini arayıp soran bulunmaz. Yüreğin kafeste çırpınır boşa, Hasret yarasını saran bulunmaz. Evine girers...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/treni-kacirdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşilin hayali', 'yesilin-hayali-akin-akca-0c21f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yeşilin hayali,

yapraklarda rüzgar.

yanıbaşımızda dallar,

kesen balta ağacı

kendi dalından,

taptaze hala kökler

) hiç kesmemiş ki

balta yerine tüymüş:

ağaçları tutuyorum,

kutupların hizmetçisiyim

berhudarım) 

doğaçlama', 'yeşilin hayali, yapraklarda rüzgar. yanıbaşımızda dallar, kesen balta ağacı kendi dalından, taptaze hala kökler ) hiç kesmemiş ki balta yeri...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yesilin-hayali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yağmur**', 'yagmur-hulya-simsek-g14j0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnce parmaklarıyla

Ruhuma

Hafifçe dokunuyor 

Yağmur..

İçimde unutulmuş

Bir testi

Yağmur topluyor

Çatlarsa dudaklarım

Hani yüreğim çatlarsa

Ortasından…

Hani sen de gelmezsen 

İmdadıma

Can suyum olsun diye

Gözlerimde unutulmuş

Bir testi 

Yağmur topluyor…', 'İnce parmaklarıyla Ruhuma Hafifçe dokunuyor  Yağmur.. İçimde unutulmuş Bir testi Yağmur topluyor Çatlarsa dudaklarım Hani yüreğim çatlarsa O...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmur-263-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen yaz', 'bitmeyen-yaz-delinin-1-i-1zx91', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzakligin kadar yalnizligimsin

Usumuslugum mesafeler kadar

Olmasa yuregime sizan askinin isigi

Hasretin karasi geceler kadar

Disarda yagmur yagiyor 

Penceremin arkasindan sokaga bakiyorum

Hatirliyorum ilk yagmurumuzu

ilk islanisimizi

ilk asik olusumuzu

ilk aglayisimizi

ilk yagan gozyaslarimizin arkasindan 

Birbirimize ilk bakisimizi

Simdi bulundugun yerde deniz varmi bilmiyorum

Varsa eger

Dalgalarin kayalara vurusunu

Firtinanin yapraklari savurusunu seyret

Ben gozkapaklarima vuruyorum en sert dalgalarimi

En sert firtinayi ozleminle kalbimde yasiyorum

Alisamiyorum sensizlige ama

Karanligina alismaya calisiyorum

Benim icin disarda hep yagmur var

Dalgalar devamli kayalari dovuyor

Firtinalar dallari kirmak istercesine haylaz

Ahhh ah bir gelisin varya

Bir donusun varya

Once bahar 

Ardindan hic bitmeyecek YAZ', 'Uzakligin kadar yalnizligimsin Usumuslugum mesafeler kadar Olmasa yuregime sizan askinin isigi Hasretin karasi geceler kadar Disarda yagmur ...', ARRAY['Türk Edebiyatı','Şiir','Delinin 1 İ']::text[], 8.5, '{"poet":"Delinin 1 İ","poet_slug":"delinin-1-i","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bitmeyen-yaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih tekerrürdür derler', 'tarih-tekerrurdur-derler-mikdat-bal-8ci8i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Defolsunlar bu diyardan

Artık bıktık istismardan

Seçemezler nur’u nardan

Karanlık sözlü aydınlar

Kelebek gözlü aydınlar

Sorsanız zulmetten kaçar

Ateş dıştan ışık saçar

Sanırlar ki nur’a uçar

Karanlık sözlü aydınlar

Kelebek gözlü aydınlar

Şartlıdırlar dönemezler

İleriyi bilemezler

Tehlikeyi göremezler

Karanlık sözlü aydınlar

Kelebek gözlü aydınlar

Neden bizleri aldatsın

Nur mu nar mı gitsin baksın

Önce kendileri tatsın

Karanlık sözlü aydınlar

Kelebek gözlü aydınlar

Girerler türlü boya ya

Konuşmazlar bedava ya

Zehir saçarlar hava ya

Karanlık sözlü aydınlar

Kelebek gözlü aydınlar

Tarih tekerrürdür derler

Bu yönde yazar çizerler

İpret almak istemezler

Karanlık sözlü aydınlar

Kelebek gözlü aydınlar

Mikdat der ki artık yeter

Bunlar kelebekten beter

Bilmeden ateşe gider

Karanlık sözlü aydınlar

Kelebek gözlü aydınlar', 'Defolsunlar bu diyardan Artık bıktık istismardan Seçemezler nur’u nardan Karanlık sözlü aydınlar Kelebek gözlü aydınlar Sorsanız zulmetten k...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/tarih-tekerrurdur-derler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-baran-demir-a87tq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'birden aklıma düştün.

bütün güzelliğinle.

sevdama düştüğün gibi.

mutluluk kapladı yüzümü gülümsedim.

ve ne güzel şey bu AŞK dedim', 'birden aklıma düştün. bütün güzelliğinle. sevdama düştüğün gibi. mutluluk kapladı yüzümü gülümsedim. ve ne güzel şey bu AŞK dedim...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-533-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ehli beyt nuru', 'ehli-beyt-nuru-kadir-kaya-tlpji', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İslamda Ehli beyt nuru ışıldar,

On dördünü her dem anar yüreğim.

Ümmeti olana müjde fısıldar,

Sevgisiyle dolu pınar yüreğim.

Ehli beyt tevhidin hakikat dili,

Hakkın sevgilisi Peygamber yolu,

Hasanla, Hüseyin canların gülü,

Acısına hala yanar yüreğim.

Sır ilmine açılır Ali kapısı,

Hoşgörülü, cömert nurdan yapısı,

Canı cananına verdi hepisi,

Canlar sofrasına banar yüreğim.

Yüzlerde parlarken nurun şiarı,

Ehli beyte mashar ümmet yanarı,

Muhammet’ten gelen soyun damarı,

Kökleri geçmişte çınar yüreğim.

Muhammet güneştir, Ali''miz ay’dır,

Hasanla, Hüseyin  yadiğar soydur,

Nurlaşan yıldızı göklerde saydır,

İncinen kalpleri onar yüreğim.

Kerbela çölünün duyuldu ahı,

Geceler bekledi nurlu sabahı,

Özünde imanla dua silahı,

Acımasız zulmü kınar yüreğim.

Niyazla daldılar Hakk ile vecde,

Ok atışı varken ettiler secde,

Melekler verdiler cennetle müjde,

Cennet bahçesine konar yüreğim.

Mevla’nın yoluna canları feda,

Ömrün baharında hayata veda,

Çırpınan kalplerde duyuldu seda,

Hasreti özümde kanar yüreğim.

Can figan haykırış yürek dağladı,

Yedi ğöğün ehli ona ağladı,

Kuşlarla, balıklar matem bağladı,

Keder ırmağında yunar yüreğim.

Sade bir hayatla oldular zahit,

Yoksula yardımda vicdanlar şahit,

Cesurca savaşıp oldular şehit,

Cihana barışı öner yüreğim.

Kurtuluşa çare olurdu fikir,

Dil ile kalpleri ederdi zikir,

Olan musibete sabırla,şükür,

Sabırla nefsimi yener yüreğim.

Cihat cırağında iman hislenir,

İlahi sözlerle gönül uslanır,

Sadakatla, vefa dosta yaslanır,

Dost bağında özlem diner yüreğim.

Hikmetli bakışla kalpler okurdu,

Merhameti sunar,  sevgi dokurdu,

İbadete aşık, sade, vakurdu,

Gururdan, kibirden iner yüreğim.

İmanı besleyen edep ile ar,

Sevgiyle barışa esmeli rüzgar,

Gelecek nesile sevgi yadigar,

Ehli beyt aşkıyla döner yüreğim.

Rabbim’iz bizlere gönderdi ayet,

Doğruluk yolunda güzeldir niyet,

Pir sultan Abdal''ım ödedi diyet,

Sevgiyle yansıyan fener yüreğim.

Yaralı yürekle düştüm izine,

Ulaşırım belki bir gün tozuna,

Kadirim, kavuştum ulvi hazına,

Hürmetle saygıyı sunar yüreğim', 'İslamda Ehli beyt nuru ışıldar, On dördünü her dem anar yüreğim. Ümmeti olana müjde fısıldar, Sevgisiyle dolu pınar yüreğim. Ehli beyt tevhi...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/ehli-beyt-nuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dip Dalgalarım', 'dip-dalgalarim-sevtap-ozkahraman-m72kt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle sessiz çığlıklarım varki

Nedensiz bekleyişlere dair..

Sustursam,

Duyarsızlar duyar korkarım! 

Konuşmak,

Ayrılmak kadar ölüm! 

Ayrılmak,

Hain pusu bilinmezlere! 

Suskunluğuma sürgün ettim de inancımı

Sahipsiz kaldı hayallerim..

Bugün şiir yarın ağıt dip dalgalarım..

Tetikteki umut,

Son nefesim,

Tutunuşum...

Aşk adına tüm sınırları kaldırırken sendeki ben,

Sevdalar hüzün tutmuş bozkırda..

Bu mevsim zor geçecek belli

Ben

Yaşanmamış mevsimlerin yasındayken...

03/02/2006 ANKARA', 'Öyle sessiz çığlıklarım varki Nedensiz bekleyişlere dair.. Sustursam, Duyarsızlar duyar korkarım!  Konuşmak, Ayrılmak kadar ölüm!  Ayrılmak,...', ARRAY['Türk Edebiyatı','Şiir','Sevtap Özkahraman']::text[], 8.5, '{"poet":"Sevtap Özkahraman","poet_slug":"sevtap-ozkahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dip-dalgalarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruh Sürgünü', 'ruh-surgunu-sevtap-ozkahraman-3g6ak', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akbabalar gururla besleniyor

Lime lime didiklerken yürekleri! 

Ki

Sınanmasıdır bu

Rağmen yaşananların..

Yürek depreminden geri kalan,

Yarımyamalak yaşamlar..

Taslak sevdalar..

Ürkek adımlar..

Gerçeğin gölgesinde soluklanacak elbet

Bu ruh sürgünü

Temize çekilirken ödünç duygular..

04/02/2006 ANKARA', 'Akbabalar gururla besleniyor Lime lime didiklerken yürekleri!  Ki Sınanmasıdır bu Rağmen yaşananların.. Yürek depreminden geri kalan, Yarımy...', ARRAY['Türk Edebiyatı','Şiir','Sevtap Özkahraman']::text[], 8.5, '{"poet":"Sevtap Özkahraman","poet_slug":"sevtap-ozkahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ruh-surgunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kari Katır', 'kari-katir-fahrettin-selcik-443rt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KARİ    KATIR

Danimarkalı bir yazar,

Densiz bir karikatür yapar,

Dünyadaki dengeyi bozar,

Trabzon da bir densiz, papaza kıyar.

Sahip olsana, çizer kalemine,

Dünyayı karıştır diye vermediler  eline,

Aklınca arıyorsan müslüman anarşist,

Kendin oldun en büyük ulusal faşist.

Erdemlikte bir ölçü vardır,

Sahip olmalısın eline,diline,

Hazreti Muhammed karikatür neyine,

Sayende,olanlara bak,yazık insanların haline.

Fahrettin Selçik  6-2-2006', 'KARİ    KATIR Danimarkalı bir yazar, Densiz bir karikatür yapar, Dünyadaki dengeyi bozar, Trabzon da bir densiz, papaza kıyar. Sahip olsana,...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kari-katir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm-"siz hiç ay aşığında ağladınız mı" Kitabından', 'gulum-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-z05xe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakma benim gülüm arsız halime 

İçim kıvrım kıvrım kasavet gülüm 

Bir de bana sor sor ahvalime 

Her gün bana hicran ve zulmet gülüm

Nutfeden hidayete

Kabirden kıyamete

Ne mavi rüyam var ne hülyalarım 

Beşinci mevsim mi hadi ordan be 

Ne mevsim kaldı sus ne rüyalarım 

Katlettik baharı yıllar harabe 

Her şeyi biz yarattık

Hâşâ neyi var ettik

Ağlayamıyorum ziyan oldu yaş

Ben gülemem gülüm gülemem artık

Ne kalpte heyecan ne sevgi ateş

Ne olacak halim bilemem artık', 'Bakma benim gülüm arsız halime  İçim kıvrım kıvrım kasavet gülüm  Bir de bana sor sor ahvalime  Her gün bana hicran ve zulmet gülüm Nutfeden...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gulum-180-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Seni Anladım', 'ask-seni-anladim-serdar-ahmet-guzel-2hmkl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkın ne demek olduğunu anladım. 

Sensiz geçen karanlık gecelerimde,

Yarım eksikti.

Senin olmadığın yerde…

İki bölümden oluşan bir filme benziyordu.

Biri seyredildiğinde tat vermiyor

Birlikte seyredildiğinde anlaşılıyor, 

Keyfinden süründürüyordu...

Sevdanın ne demek olduğunu anladım,

Kararan yüreğimde.

Sen varsan aydınlık,

Senin yokluğunda ebedi karanlık…

Aşk budur elbet,

İnsanın içini aydınlatan bir ışık,

Martıları coşturan bir şarkı,

Yağmurdan sonra açan gökkuşağı…

05.02.2006 saat:22.38', 'Aşkın ne demek olduğunu anladım.  Sensiz geçen karanlık gecelerimde, Yarım eksikti. Senin olmadığın yerde… İki bölümden oluşan bir filme ben...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ahmet Güzel']::text[], 8.5, '{"poet":"Serdar Ahmet Güzel","poet_slug":"serdar-ahmet-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-seni-anladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilık Bir Rüzgar Gibi', 'ilik-bir-ruzgar-gibi-huseyin-erdogan-twvoc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen bir çiçek bahçesi gibisin

her sabah demet demet topluyorum seni

sen gönlümde esen bir meltem yelisin

hem çiçeklerde hem de yellerde kokluyorum tenini

rengarenk güller karanfiller açarsın bana

her anımda yaşatıyorsun beni yemyeşil bir baharda

ılık bir rüzgar gibi esip duruyorsun yüreğimde

razıyım hasretin beni yakıp kavursa da ömrümce

ay ve yıldızların parlaklığını görüyorum gözlerinde

sanki güneşin sıcaklığı taplanmış senin bedeninde

inan ki seni buluyorum her bakışımda resimlerinde

ne olursun şiirim beni sensiz bırakma mahşerde bile

                                                            06.02.2006

                                                         Hüseyin Erdoğan', 'sen bir çiçek bahçesi gibisin her sabah demet demet topluyorum seni sen gönlümde esen bir meltem yelisin hem çiçeklerde hem de yellerde kokl...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ilik-bir-ruzgar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülemem', 'gulemem-selcen-boyar-th4eh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne yemekte gönlüm var,

Ne içmekte....Gelemem.

Bir derdim var,

Ta yürekte.... Diyemem.

Gözlerim küskün sevinçlere,

Gül desende.... Gülemem.

Derman yok dizlerimde,

Gel desende.... Gelemem.', 'Ne yemekte gönlüm var, Ne içmekte....Gelemem. Bir derdim var, Ta yürekte.... Diyemem. Gözlerim küskün sevinçlere, Gül desende.... Gülemem. D...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gulemem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz iken ben öleyim..', 'sensiz-iken-ben-oleyim-selcen-boyar-ywgd9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni öyle sev,

Öyle sevki....

Her hücremde,

Seni hissedeyim.

Dokularım seni zikretsin,

Öyle sevki beni....

Sensiz iken ben öleyim..', 'Beni öyle sev, Öyle sevki.... Her hücremde, Seni hissedeyim. Dokularım seni zikretsin, Öyle sevki beni.... Sensiz iken ben öleyim.....', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sensiz-iken-ben-oleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-gul-yazganarikan-9yopw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık çöktü

Şehrin üstüne

Sensizim,

Bensizim.

Gayrı yok ötesi

Her nefes azap

Her nefes zehir ciğerime,

Sabaha ya çıkarım,

Ya ölürüm bu gece...', 'Karanlık çöktü Şehrin üstüne Sensizim, Bensizim. Gayrı yok ötesi Her nefes azap Her nefes zehir ciğerime, Sabaha ya çıkarım, Ya ölürüm bu ge...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-gece-185-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-selcen-boyar-izpjn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamak için gidiyorlar ona

Bir umutla.

Makinanın bir ucunda can,

Diğer ucunda kan.

Bir heves yaşamak,

Bir heyecan.

Yaşamak ne güzel,

Ne güzel değilmi canan.

NOT: Bu şiiri diyaliz makinasına giren böbrek hastası bir arkadaşım için yazmıştım. Ona armağan olsun.', 'Yaşamak için gidiyorlar ona Bir umutla. Makinanın bir ucunda can, Diğer ucunda kan. Bir heves yaşamak, Bir heyecan. Yaşamak ne güzel, Ne güz...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasamak-203-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikâyetname', 'sik-yetname-mehmet-postalli-c23ru', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Değerli Kardeşim İbrahim Sönmez''e İthaf Ediyorum

Sen gittin gideli sorma burayı

Kendimde kalmadı hal, İbrahim Bey

Açma içimdeki gizli yarayı

Kapladı üstünü kül, İbrahim Bey

Müdür devri bitti, burası çarlık

İhale ne gezer, gizli pazarlık

Bu beyler, burada çeker mi darlık? 

Buldular tükenmez mal, İbrahim Bey

Az gelir buraya çiftlik deyimi

Gözünle gör, gel de burada yiyimi

Elimden hiçbir şey gelmez, iyimi? 

Beni de buradan al, İbrahim Bey

Altında Toyota gezer ülkeyi

Sanırsın, atanmış bir derebeyi

Aklına getirmez hesap vermeyi

Kırılmaz sanıyor dal, İbrahim Bey

Kime açsam bunu hepsi susuyor

Korkusundan köşesinde pusuyor

Dalkavuklar her gün zehir kusuyor

Azdırdı yediği yal, İbrahim Bey 

Olanı gördükçe donuyor kanım

Bu talana dayanmıyor vicdanım

Tansiyon yükselir, yanıyor canım

Gönlüme teselli ol, İbrahim Bey

Ahmet Bey diyordu, uykum kaçıyor

Haksızlıklar derin yara açıyor

O, emekli sevincinden uçuyor

Bense bulamadım yol, İbrahim Bey', 'Değerli Kardeşim İbrahim Sönmez''e İthaf Ediyorum Sen gittin gideli sorma burayı Kendimde kalmadı hal, İbrahim Bey Açma içimdeki gizli yarayı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sikayetname-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Kapım mı Var', 'baska-kapim-mi-var-yusuf-onder-bahceci-e9zhn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni nasıl öveyim be güzelim benim,

Senin şu sevdan kalbimdedir derim,

Sen beni sevmesen üzüldüm derim,

Söyle benim başka kapım mı var.

Yollarına çıktım da baktım ağladım,

Albümde resimlere baktım ağladım,

Yalçın dağlar yol vermez di ağladım,

Söyle benim başka kapım mı var.

Mevlana çağırıyor ne olursan ol gel,

Bende çağırıyorum ne olursan ol gel,

Yıllar ne çabuk geçiyor ne olursun gel,

Söyle benim başka kapım mı var.', 'Seni nasıl öveyim be güzelim benim, Senin şu sevdan kalbimdedir derim, Sen beni sevmesen üzüldüm derim, Söyle benim başka kapım mı var. Yoll...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/baska-kapim-mi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudaklarım Tutuyor Seni', 'dudaklarim-tutuyor-seni-gul-yazganarikan-wzci5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlıyorum,

Kendimi seviyorum böyle ağlarken...

Kendimle kalmışım 

İçimi döküyorum işte...

Benden başka kim kalmış ki

Şu serseri alemde...

Hafifliyorum her damlada,

Her damla sen olup okşayarak iniyor yanaklarımı,

sonra 

dudaklarım tutuyor seni...

Boynuma kadar iniyorsun bazen...

Yavaşlıyorsun tenimde, 

Ardından gözeneklerim hapsediyor seni içinde...

Kendimi seviyorum böyle ağlarken...

Az şey mi ben de ben oluyorsun...

Her damlada can verip, yine doğuyorsun...', 'Ağlıyorum, Kendimi seviyorum böyle ağlarken... Kendimle kalmışım  İçimi döküyorum işte... Benden başka kim kalmış ki Şu serseri alemde... Ha...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dudaklarim-tutuyor-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilecek', 'bilecek-husam-hasret-83jjp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahara umutlu olan yüreğim

Aşkını güllere serpebilecek

Gerçek umutlarla dolan yüreğim

Yarın için çok şey yapabilecek

Yüreğim her mutlu emele düşkün

Bu yüzden geçirmez nafile ömrün

Yaşamak olursa sevinçle beş gün

Mutluluk yüzünü öpebilecek

Yüerğim bağımsız yaşama kanmış

Aydınlık uğrunda mum gibi yanmış

Sevinçli görünür, sevince banmış

Umutlu gerçeğe tapabilecek', 'Bahara umutlu olan yüreğim Aşkını güllere serpebilecek Gerçek umutlarla dolan yüreğim Yarın için çok şey yapabilecek Yüreğim her mutlu emele...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilecek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehter Marşı Çalar', 'mehter-marsi-calar-yusuf-onder-bahceci-ruxi8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim bu Yüce Milletim necip Millettir,

Memleketimde oynanan oyunsa illettir,

Bilinsin biz Türk Milletiyiz Alemi inletir,

Mehter Marşı çalar Alemi inletir bre.

Bilinki Dünya''nın en güçlü ordusu bizde,

Mehmetlerimin kalbinde şehitlik var be,

Sakın ağlamasın anneleri yiğitlik serde,

Mehter Marşı çalar Alemi inletir bre.

Benim üç Kıtaya hükmeden atalarım var,

Mertlik, yiğitlik, şan ve şeref, itibarım var,

Deyin ey kalleşler deyin sizin neyiniz var,

Mehter Marşı çalar Alemi inletir bre.

Gittiğimiz yerlere hep kardeşlik götürürüz,

Sevgi, dosluk, vefa, sefa, iman götürürüz,

Önümüzde kalleş duramaz siler süpürürüz,

Mehter Marşı çalar Alemi inletir bre.', 'Benim bu Yüce Milletim necip Millettir, Memleketimde oynanan oyunsa illettir, Bilinsin biz Türk Milletiyiz Alemi inletir, Mehter Marşı çalar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mehter-marsi-calar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Değilim', 'yalniz-degilim-husam-hasret-rk0dw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne annem var ne de baba

Ama yalnızlık bilmem ne

Bir selamdan yüz merhaba

Söylenir her günde bana

Yalnız değilim bu kadar

Yarım, yoldaşım, dostum var

Yarım ise gönül safam

Mutluluğum gözlerinde

Yoldaşımsa doğru vefam

Gerçekliğim sözlerinde

Yalnız değilim bu kadar

Yarım, yoldaşım, dostum var

Dostum ise hayatımdır

Dünyaları avucumda

Her biri bir horyatımdır

Sözleri hoş dil ucumda

Yalnız değilim bu kadar

Yarım, yoldaşım, dostum var', 'Ne annem var ne de baba Ama yalnızlık bilmem ne Bir selamdan yüz merhaba Söylenir her günde bana Yalnız değilim bu kadar Yarım, yoldaşım, do...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yalniz-degilim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halin Nedir', 'halin-nedir-yusuf-onder-bahceci-afhab', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İyiden ve güzelden mi yana,

Dostluk, sevgiden mi yana,

Vefa ve sefadan mı yana,

Söyle senin hâlin nedir.

Sevdim seni unutamam,

Rüya ve şiirle avunamam,

Ben seni sevdim el aman,

Söyle senin hâlin nedir.

Yola çıkıp yollara baksan,

Bir su gibi çağlayıp aksan,

Seven yüreğimide yaksan,

Söyle senin hâlin nedir.

Birgün olur bahar gelirmi,

Seven sevdiğini görürmü,

Yoksa görmeden ölürmü,

Söyle senin hâlin nedir.', 'İyiden ve güzelden mi yana, Dostluk, sevgiden mi yana, Vefa ve sefadan mı yana, Söyle senin hâlin nedir. Sevdim seni unutamam, Rüya ve şiirl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/halin-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efkarın Söylettikleri', 'efkarin-soylettikleri-muhammed-mehmet-gul-8e6ff', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah güzel gözlü kadın 

Karanlık dehlizerde yitirdim gençliğimi 

Sen yoktun. 

Yokluğunda dinlediğim 

Şarkılar susarsa bir akşamüstü 

Avutmaya çalışırsa birileri kirpiklerini 

Hiç düşünme bugün avuntusuzluk günüdür, de 

Dön şehre sırtını 

At ipek şalını omzuna 

Savur tel tel saçlarını rüzgara 

Dağlara vur kendini 

Yada vur kendini sulu sepken sokaklara 

Şehrin günbegün büyüyen günahına inat. 

Ben öldüğümde kırk ikindi yağmur yağacaktır şehre bilesin 

Ayak bastığım tüm kaldırımlar 

Hiç ıslanmadıkları kadar ıslanacaklar yağmurdan. 

Bakma savur tel tel saçlarını rüzgara dediğime 

Hayır istemem tek teli incinmesin 

Efkardandı bütün söylediklerim 

Yada 

Bu dünyadan vakitsiz firardan 

Hani sevdiğimiz bir türkü vardı,beraber söylediğimiz 

...Eklemedir koca konak ekleme... 

Ah yar ben gider oldum sen bekleme 

Bir zaman sonra gökten,gündüz gözüyle yıldızlar kayacak 

Güneş başka doğacak senin için ufuktan 

Gün saymadım,takvim tutmadım ama 

Ben ölünce 

Kırk ikindi yağmur yağacak unutma 

Unutma 

Ağlama. 

.........................................................................................................', 'Ah güzel gözlü kadın  Karanlık dehlizerde yitirdim gençliğimi  Sen yoktun.  Yokluğunda dinlediğim  Şarkılar susarsa bir akşamüstü  Avutmaya ...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/efkarin-soylettikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hay-Ellerim', 'hay-ellerim-muhammed-mehmet-gul-szme1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerim ellerim,hayallerim 

Gökyüzümü alçaldı yoksa başımmı dönüyor 

Yıldızlar deyilmi yoksa avuçlarımdaki 

Yoksa ben ben deyilmiyim 

Yoksa yokmu hayallerim 

Hayallerim hayallerim,hey ellerim 

Yıldızlarmı yoksa şehrin ışıklarımı sönüyor 

Gözyaşlarım mı yoksa parmak uçlarımdaki 

Yoksa ben ben deyilmiyim 

Yoksa yokmu ellerim.', 'Ellerim ellerim,hayallerim  Gökyüzümü alçaldı yoksa başımmı dönüyor  Yıldızlar deyilmi yoksa avuçlarımdaki  Yoksa ben ben deyilmiyim  Yoksa ...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hay-ellerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşek Gitti', 'esek-gitti-mehmet-akif-tiryaki-3mvx3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cömert insanlar bitti,

Diğerleri süpermarketlere gitti,

Ucuz mal peşinde bütün halk,

Süpermarketlerde kuyruklar uzayacak.

Fakir halk çoğaldıkça

Ödemeler büyük marketlerde 

Kartlarla yapılacak.

Yirmi gün de ordan avanta,

Bu kartı kim ödeyecek sonunda? 

Hediye, hediye, hediye

Kimse sormaz,

Bu hediyenin özelliği ne diye.

Eşek gitti dansı bunun sebebi,

Zavallı insanlar bunu bilmeli

Bir seyyah eşeğini otele bağladı,

Dinlenmeye çekildi,

Lakin uyumak mümkün değil

Aşağı indi baktı herkes dansta,

Eşek gitti şarkısı ağızlarda

O da katıldı eğlenceye o gece,

Sabah uyandı devam edecekti yoluna

İstedi eşeğini,

Garson dedi efendim

Siz de söylediniz şarkısını ya 

Sizin eşek gitti.

Dün geceki tantanaya.

Hediyeler, hediyeler, hediyeler

Toplanan sizin faiz paralarınızdan

Ödenenler,

Eşek gitti şarkısı söyleyenler çoğaldı,

Geçen senenin iki katına vardı.

Hala insanlar uyanmadı,

En sonunda icralar kapılara dayandı.

İnsanlar canına kıydı,

Bu halk buna layıkmıydı..

Görüyorsunuz seneler önceki olayla

Şablon aynı.

Kaybedenler süratle akıllanmalı.', 'Cömert insanlar bitti, Diğerleri süpermarketlere gitti, Ucuz mal peşinde bütün halk, Süpermarketlerde kuyruklar uzayacak. Fakir halk çoğaldı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/esek-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizede Düşer', 'bizede-duser-muharrem-kemal-gunduz-ljtoi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamakla ölmek arasında

Acı duymaksa sevmek..

Amansız bir direniş

Bir isyansa sevdamız

Bastırılması imkansız

Alma ellerini ellerimden

Kaçırma bakışlarını

Susma çaresizlikten

Biz başlattık yarınları

Biz sürdürmeliyiz..

Ne yenilgilerin tutsağıyız

Ne hayata isyankar

Güçte olsa yaşamak

Bizede düşer bir tanem

Yengilerden nasip almak..

    28. Haziran. 1983 Ankara', 'Yaşamakla ölmek arasında Acı duymaksa sevmek.. Amansız bir direniş Bir isyansa sevdamız Bastırılması imkansız Alma ellerini ellerimden Kaçır...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Kemal Gündüz']::text[], 8.5, '{"poet":"Muharrem Kemal Gündüz","poet_slug":"muharrem-kemal-gunduz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bizede-duser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicret-Muhacir Ağrısı', 'hicret-muhacir-agrisi-muhammed-mehmet-gul-9nzlf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gittikçe kaybolan gökkuşağı altında 

Gözlerimi diktiğim grubun yangınıydı 

Şöyle bir baktığımda 

...................................Kırık aynaya göz ucuyla 

Sulusepken bir yağmurdu ufukta beliren 

İnfialdi 

Olağanütü bir haldi 

Önce gözlerim hicret etti buralardan 

Sonra muhacir ağrısı oldu şiirlerim 

Gittikçe kaybolan gökkuşağı altında', 'Gittikçe kaybolan gökkuşağı altında  Gözlerimi diktiğim grubun yangınıydı  Şöyle bir baktığımda  ...................................Kırık ay...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hicret-muhacir-agrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bile İsteye', 'bile-i-steye-muhammed-mehmet-gul-raids', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her şeyin değiştikçe aynı kaldığı zamanların 

sanki binlerce yıl öncesinden 

umutsuz ruhumu sarıp sarmalar köklerin 

masmavi göklerin 

tılsımını taşırken,bir efkar silsilesiyle 

yerlebir eder ufkumu gözbebeklerin 

Bile isteye 

savrulurken hasretinin saçları yüzüme efil efil 

mahkumu olmuşum titreyen kelimelerin 

yerin göğün dili olsada söylese 

and vermişim dağlara taşlara 

her nereye gitsem ucundayım kirpiklerinin 

Öle isteye 

ölümsüz ezgilerin kol gezdiği 

eskilerin kabristanlarında,bir servinin kakülüyüm 

külüyüm ben 

ateş böceklerinin çıkarttığı yangının 

asırlardır arayıp bulamadığın 

bahar ülkesinin, ıssız çölüyüm 

Güle isteye 

Gitme dediysem öyle deyil; 

kalmalısın gözlerimin ta içinde 

Üç zamanın üçünde de kan kırmızı gözlerinle 

Bir Lokman edasıyla 

İçimde kanayan yaramı sar-ma ki 

Hergün ayrı biçimde ruhum senden 

Çile isteye', 'Her şeyin değiştikçe aynı kaldığı zamanların  sanki binlerce yıl öncesinden  umutsuz ruhumu sarıp sarmalar köklerin  masmavi göklerin  tılsı...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bile-isteye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-muhammed-mehmet-gul-bo1gc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sis perdesinin ardından 

Sanki küçücük bir tepenin sırtından 

Gece sihir, gece 

İçime süzülen çıngıraklı yılan 

Bir sabun köpüğü gibi ellerimden kayıp 

Hiçe sayıp varlığımı, bir el gibi uzayıp 

Gece sessiz, gece 

Hırsız apansız ruhmu çalan 

Bir parçası pembe, bin parçası siyah 

Pişmanlıklar denizim gibi eyvah 

Gece duman, gece 

Baştan sona hep yalan 

Kurulmuş gözlerime sürgünlüğün kokusu 

Farkına varamadığım bir sinsi pusu 

Gece sürgün, gece 

Vurgun, gece isyan, gece talan 

Şakaklar kar, çıkmaz sokaklar eski yar 

Ruhumu çaldırdım, yitiğim var 

Gece soygun, gece 

Kayıplara verdiğim son ilan 

Ve.... ezgiler dökülürken dudağımdan 

Bir anda ortaya çıkı, solumdan sağımdan 

Gece katil, gece 

Kurşun vakitsiz alnıma sıkılan.', 'Bir sis perdesinin ardından  Sanki küçücük bir tepenin sırtından  Gece sihir, gece  İçime süzülen çıngıraklı yılan  Bir sabun köpüğü gibi el...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gece-208-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baktığım Yerde', 'baktigim-yerde-muharrem-kemal-gunduz-0aiga', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Parçalayıp böldün uykularımı

Karanlığın en koyulaştığı yerde

Bir sen anlamadın duygularımı

Aşk çıkmazının başladığı yerde..

Kayıp benliğim; görmez olurum

Seviyorum desen; duymaz olurum

Bıraksan kendini varmaz olurum

Yarim: sevdamızın bittiği yerde..

Uzar ayrılığın hiç bitmez zaman

Bir bizmiyiz kaderimize aldanan

Bunca yıllık hasrette biter inan

Bulmak isterim seni bıraktığım yerde

Bir rüzgar seninle dolu eser yüzüme

Hiç aldırmaz oldun sevgili sözüme

Başka bir güzel görünmezken gözüme

Sen canlanırsın baktığım yerde..

                06.04.1984 ŞIRNAK', 'Parçalayıp böldün uykularımı Karanlığın en koyulaştığı yerde Bir sen anlamadın duygularımı Aşk çıkmazının başladığı yerde.. Kayıp benliğim; ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Kemal Gündüz']::text[], 8.5, '{"poet":"Muharrem Kemal Gündüz","poet_slug":"muharrem-kemal-gunduz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/baktigim-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarihin Başladığı Yer', 'tarihin-basladigi-yer-muhammed-mehmet-gul-e09xr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zaten asırlardır fırtınalarla bitap

Yangınlarla

Yanılgılarla ahuzara düşen

Gönül ülkemi birbirine kattın

Asi rüzgarın kollarına kapılmış

Sararan yapraklar misali

Beni yerden yere fırlatıp attın

Bu azap  niye

Yüreğinde başlar taşın tarihi. 

Ya bir ışık göster simsiyah pencerelerden

Yada kır zincirlerimi

Azat et ruhumu hayalin kursun

Çölmü dedin,Leylamı dedin

Çölleri kaplayan vaveylamı dedin sus bahsetme

Mecnun,benim yanımda şöyle dursun

Başka yerde değil 

Gönlümde başlar ataşın tarihi 

Bu habersiz bu adressiz

Yüreğimdeard arda  depremlere sebep

Gidişinde uzayan yollar sarhoş

Ellerimin eski sıcaklığı yok artık

Kırgınlık bir çığ gibi düşerken gönlümün üzerine

Bu akşam ben bir hoşum akşam bir hoş 

Şarkılar türküler avutmaz beni 

Elinde başlar ayyaşın tarihi 

İsmini deli dolu dalgalara haykırdığım

Nice gemileri batırdığım

Deniz ki kirpiklerimden süzüldü

Yıllar boyu zikrederek

Dervişin ellerinde dağılan yorgun tesbih gibi

Boncuk boncuk yanağıma düzüldü

Yağmurlar ne ki 

Gözlerimde başlar yaşın tarihi', 'Zaten asırlardır fırtınalarla bitap Yangınlarla Yanılgılarla ahuzara düşen Gönül ülkemi birbirine kattın Asi rüzgarın kollarına kapılmış Sar...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/tarihin-basladigi-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Dudaklım', 'gul-dudaklim-mustafa-bilgili-wort8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerine kına yakmışsın,al al olmuşsun,

Şeker kaymak ne kelime sen bal olmuşsun,

Gönül bahçemde açılan bir gül olmuşsun,

Koklamaya geldim seni aç artık gülüm.

Bakmaya doyulmuyor,ela gözüne,

Bu canım fedadır bir tek sözüne,

Utanırım bakamam o gül yüzüne,

Aşkım bade olmuş,iç artık gülüm.

Kirpiklerin ok olmuş,kaşın yay gibi,

Güzel mahcemalin,hilal ay gibi,

Bu aşk gönlümde akan,deli çay gibi,

Köprü at üzerimden geç artık gülüm.

Şeyda bülbül olmuşsun,dilin şakıyor,

O dillerden söz değil,ballar akıyor,

Bu sevda bir alev olmuş,beni yakıyor,

Seveni sevmeyeni seç artık gülüm.

Nazik ellerin elime dokunduğu an,

Bedenimde can yanıyor,damarımda kan,

Tek dileğim Allah’tan,benim gibi yan,

Senden vazgeçmek mi,güç artık gülüm.

                                                        22.11.1996', 'Ellerine kına yakmışsın,al al olmuşsun, Şeker kaymak ne kelime sen bal olmuşsun, Gönül bahçemde açılan bir gül olmuşsun, Koklamaya geldim se...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gul-dudaklim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '....Mişim', 'misim-muhammed-mehmet-gul-eiqyi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir vakit 

Görülmüşüm elimi alnıma sürerken 

Bir içimlik cigaranın keyfini sürerken 

Aynanın karşısında 

Gözyaşlarıma gülerken görülmüşüm 

Bir vakit 

Sürülmüş kandındım kendi alnıma 

Yaklaştırmazdım kendimi bile kendi yanıma 

Aynanın karşısında 

Kendi içime sürülmüşüm 

Bir vakit 

Gerilmişim,bunalmışım,yanılmışım 

Zaman zaman çeşitli isimlerle anılmışım 

Aynanın karşısında 

Yay gibi sonsuzluğa gerilmişim 

Bir vakit 

Serilmişim yerlere kendimi ararken 

Kayan yıldızlar gözlerimi tararken 

Aynanın karşısında 

Vurulmuş yerlere serilmişim 

Bir vakit 

Verilmişim hüznün kollarına 

Çıkarmıyım diye düşünürken yarına 

Aynanın karşısında 

Gün aşırı toprağa verilmişim 

................................................Bir vakit.', 'Bir vakit  Görülmüşüm elimi alnıma sürerken  Bir içimlik cigaranın keyfini sürerken  Aynanın karşısında  Gözyaşlarıma gülerken görülmüşüm  B...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/misim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdesin', 'i-cimdesin-seyfettin-bilal-ozluk-901of', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlık treni söylenen şarkı

Yoksun kadınım yanımda

Uzaklarda bildiğim bir yerlerdesin

Binmeyelim yalnızlık trenine

Uzanalım mavi gecelere

Demir raylarda kalmasın karanlık sevdamız

Bu soğuk mevsimde içim yanıyor

Titreyen mum ışığında seni arıyorum

Tut ellerimi hiç bırakma kadınım

Kadehler senin için kalkıyor kimse bilmiyor

Dudağımda alkol yok içmiyorum ama

Camlı çerçevelerde kalmasın kırılgan sevdamız

Uzandım yatağıma herkes odalarında

Sınırsız alkolun uykusundalar

Ben hala mavi gece de seni seyrediyorum

Çok güzelsin şarap gibisin kadınım

Yıllar geçse de hep içimde olacaaksın

Mahzen gecelerde kalmasın ürkek sevdamız', 'Yalnızlık treni söylenen şarkı Yoksun kadınım yanımda Uzaklarda bildiğim bir yerlerdesin Binmeyelim yalnızlık trenine Uzanalım mavi gecelere...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/icimdesin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Lâ', 'dunya-l-mehmet-akif-tiryaki-cianp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen onu zannedersin yayla

Gezer tozarsın sağda solda

Eyvah dersin işin sonunda

Neden gitmedin Allah yolunda

Sığındım zatı Hakka gel gidelim,

Cemal-i ba kemali seyr idelim

Gece vaktinde yatmasını, ve

Vaktinde kalkmasını bilelim,

Hacı Ali Rıza Efendi gibi dikkat edelim

''Bana padişah misafir gelse, yine vaktinde yatarım'' derdi.

Bunun için her gece sabaha kadar

Ellibin kelime-i tevhid çekerdi.

Sahabe-i Kiram (R.A.hüm) 

Yatsı namazından eve dönerken

Cüppelerini daha yolda çıkarmaya başlardı.

Çünkü gece işleri vardı.

Kalkıp zikir yapacaklardı.

Benim gibi değil onlar, adam gibi adamdı.', 'Sen onu zannedersin yayla Gezer tozarsın sağda solda Eyvah dersin işin sonunda Neden gitmedin Allah yolunda Sığındım zatı Hakka gel gidelim,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dunya-la-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yusufi', 'yusufi-muhammed-mehmet-gul-yewox', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seğriyen yıldızların peşi sıra 

seğirttim dolu dizgin doru atlar gibi 

Seğriyen gözlerimmiydi 

Yoksa kirpik uçlarıma düşen yıldızlarmı bilmem 

Hayırsız düşler gibi darmadağın 

Bu sesiz karmaşada 

Taş duvarların, kavgaların yabanıl şehrinde 

Bu hissiz meydanların, küflenmiş şehrinde, ben 

Ben Yusufiyim 

Ben sana mahpus sen taş medreseye 

Sokaklarda bir garip sessizlik var 

Bu anlatılmaz bir vakıadır yalnızlığa dair 

Zamansız üşüyüşler gibi darmadağın 

Dağıldığım bir kavga sonrası 

Haramilerden şehir eşkiyalarından 

Kaçarken apansız tutsakladığın 

Bir gece kaçakken kolumdan tutup sakladığın 

Alnımdan öpüp kucakladığın, ben 

Ben Yusufiyim 

Ben sana mahpus sen taş medreseye 

İnkarmı edeceğim halimi, hayır etmiyeceğim 

Dudağımdaki gülüşler gibi darmadağın 

Namlu ucunda titreyen kuş gibiyim 

Bilki şafağın atma vaktindeyim 

Belki aklımı atma vaktidir bu an 

İzinsiz gösterilerde ezilen şiirlere 

Karabasanlar baskın verirken, ben 

Ben Yusufiyim 

Ben sana mahpus sen taş medreseye 

Sonbahar akşamlarında kıvrandığım zamanlarda 

Kılpayı kurtulduğum kavgalarda, mırıldandığım isyan 

Tılsımlı bir ezgidir dudaklarımda 

Boş skaklarda diz çöküşlerim gibi darmadağın 

Yağmurlar kadar esrarlı 

Ölüm kadar ısrarlı bir yağmacıdır parmaklıklar 

Yağmaladıkça yağmalar şakaklarımı 

Mütevekkil uykularımda rüyalarımı 

Allaha yürüyen yollarımı 

Allaha açılan kollarımla, ben 

Ben Yusufiyim 

Ben sana mahpus sen taş medreseye.', 'Seğriyen yıldızların peşi sıra  seğirttim dolu dizgin doru atlar gibi  Seğriyen gözlerimmiydi  Yoksa kirpik uçlarıma düşen yıldızlarmı bilme...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yusufi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotograf', 'fotograf-muhammed-mehmet-gul-lekb7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanklarıma 

yağmurlar 

yağarken 

kimse 

fotografımı 

çekmeye 

kalkmasın. 

Hiçbir zaman 

fotojenik 

olmadım. 

Olur olmaz 

fotografım 

çekildiyse de, 

yalnızca 

şiirlerim 

iyi poz 

verirdi. 

Kalemimden 

göz yaşlarım 

damla damla 

dökülürken

.', 'Yanklarıma  yağmurlar  yağarken  kimse  fotografımı  çekmeye  kalkmasın.  Hiçbir zaman  fotojenik  olmadım.  Olur olmaz  fotografım  çekildi...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/fotograf-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayki', 'sayki-muhammed-mehmet-gul-dfnn7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sayki; sarhoş şişelerin arasında 

Yalnızlığın yudumlandığı bardayım 

Sayki; akşam oldu saat dokuz buçuk 

Trenler kalkıyor ben yine gardayım 

Sayki; esrik yıldızların aydınlatmadığı 

Gözyaşımın ıslattığı bulvardayım 

Sayki; sebepsiz yere sorgulanmışım 

Sessiz seneler boyu zindanlardayım 

Sayki; her mahpus benim, her kalemle ben 

Satır satır, çentik çentik duvardayım 

Sayki; aklımı attığım gecelerde 

Yokluğun içerisinde ki vardayım.', 'Sayki; sarhoş şişelerin arasında  Yalnızlığın yudumlandığı bardayım  Sayki; akşam oldu saat dokuz buçuk  Trenler kalkıyor ben yine gardayım ...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sayki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yusufa Ağıt', 'yusufa-agit-muhammed-mehmet-gul-kpbx4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gül kokusu kan tortusu 

Rüyalarım herdaim tabire muhtaçtı 

Ben bıçak sırtındaydım 

İhtiyati tedbir konmuştu bakışlarıma 

Ve 

Sırılsıklam bir rüyaydı gördüğüm 

Islık çalsam,yarı yolda kalsam,kaybolsam 

Gülsem,devrilsem,ölsem 

Şimdi kim yorumlar hepsini 

Islığın manası nedir 

Gülmek neye delelet eder kimbilir 

Ya ölmek,devrilmek 

Ne demek 

Yusuf nerelerde kaldın 

Rüyalarım tabirsiz kaldı 

Yusuf ben sessiz kaldım 

Kan tortusu,gül kokusu 

Başladı korkusu karabasanların 

Hayırsız düşlerin yortusu 

Sen ey rüyaların dili 

Yine gördüklerim hep aynı 

GÖRDÜĞÜM,Körlüğüm 

KÖRLÜĞÜM,Kördüğüm 

Ne mısır ne zindan nede kuyuydu derdim 

Yakup gözlerinden oldu senin için 

Sadece ben 

.....................Delirdim 

Sen ey rüyaların delili 

Sen kuyularda kaldın 

Rüyalarım tabirsiz,ben öylece ortada sensiz kaldım 

Gül kokusu kan tortusu 

Yerle bir olurken herdem gövdem 

İçimde yine başlar hayırsız düşlerin yortusu', 'Gül kokusu kan tortusu  Rüyalarım herdaim tabire muhtaçtı  Ben bıçak sırtındaydım  İhtiyati tedbir konmuştu bakışlarıma  Ve  Sırılsıklam bir...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yusufa-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamız', 'sevdamiz-seyfettin-bilal-ozluk-sa7gq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlık treni söylenen şarkı

Yoksun kadınım yanımda

Uzaklarda bildiğim biryerlerdesin

Binmeyelim yalnızlık trenine

Uzanalım mavi gecelere

Demir raylarda kalmasın karanlık sevdamız

Bu soğuk mevsimde içim yanıyor

Titreyen mum ışığında seni arıyorum

Tut ellerimi hiç bırakma kadınım

Kadehler senin için kalkıyor kimse bilmiyor

Dudağımda alkol yok içmiyorum ama

Camlı çerçevelerde kalmasın kırılgan sevdamız

Uzandım yatağıma herkes odalarında

Sınırsız alkolun uykusundalar

Ben hala mavi gece de seni seyrediyorum

Çok güzelsin şarap gibisin kadınım

Yıllar geçse de hep içimde olacaaksın

Mahzen gecelerde kalmasın ürkek sevdamız', 'Yalnızlık treni söylenen şarkı Yoksun kadınım yanımda Uzaklarda bildiğim biryerlerdesin Binmeyelim yalnızlık trenine Uzanalım mavi gecelere ...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevdamiz-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Sokağında', 'dus-sokaginda-gul-yazganarikan-5aw6c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnız seni getirir düşler,

Düş sokağında sevişiriz, düş sokağında kaynarız seninle...

Düş sokağı yanar, yangın yangın...

Düşlerim sen olur her gece,

Ve ben düşerim...

Bacaklarım götürmez beni geleceğe 

Seninle, 

Ayaklarım bilmez yürümek nedir...

Kaybolur gidersin düşlerimden...

Gözlerin düşlerim olur,

Dudaklarında uyur dudaklarım düşlerimde,

O dudakların, 

Ateş toplarından yakıcı sözleriyle

Dağladıkça tenimi

Düşlerimde düşersin gözümden....

Sen düştükçe ben düşerim...

Ve ben yine düşlerim seni...', 'Yalnız seni getirir düşler, Düş sokağında sevişiriz, düş sokağında kaynarız seninle... Düş sokağı yanar, yangın yangın... Düşlerim sen olur ...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dus-sokaginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikkat Kan Aranıyor', 'dikkat-kan-araniyor-muhammed-mehmet-gul-5pnur', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mevsim kardı kıştı 

En umulmadık yerde 

Biçare gözlerim pusuya düştü 

Dikkat can aranıyor 

Bir gece istasyonda sorulmuşum 

Kaç zamandır uykusuzken 

Etrafım sarılmış, gözkapaklarımdan vurulmuşum 

Dikkat kan aranıyor 

Kanım yavaş yavaş süzüldü içimden, kaldırımları ıslatarak 

Oysa açtım oysa bi-ilaçtım 

Ruhum haykırıyordu sonsuzluğa adım atarak 

Dikkat nan aranıyor 

Hava kardı, belkide benim gözlerim karardı 

Sessiz bir yolculuğun eşiğinde 

Bir zamanlar benimde ufkumda güneş vardı 

Dikkat tan aranıyor.', 'Mevsim kardı kıştı  En umulmadık yerde  Biçare gözlerim pusuya düştü  Dikkat can aranıyor  Bir gece istasyonda sorulmuşum  Kaç zamandır uyku...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dikkat-kan-araniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selvi Boylum İnce Bellim Ruhumda', 'selvi-boylum-i-nce-bellim-ruhumda-kamil-soylemez-1xo4u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdam kıra gider,kırlanır

Dudağı kiraz,dudağımda ballanır

Ah bu yürek bende durmaz harlanır

...........Harlanır da bu can ona yarlanır..

Selvi boylum,ince bellim ruhumda

Gözüm kalır,allarında,pulunda

Bir eşi yok,bu güzelin dünyada

Ah bu yürek,bende durmaz harlanır

...........Harlanır da bu can ona yarlanır...

Güzelliği var,hem huyunda,suyunda

Tatlı dilli,sözleri vardır bana

Bir eşi yok bu güzellin soyunda

Ah bu yürek,bende durmaz harlanır

............Harlanır da bu can ona yarlanır...

Ne desem,ne söylesem az kalır

Gülen yüzü,gözümde canlanır

İnciler,prlantalar yanında sönük kalır

Ah bu yürek,bende durmaz harlanır..

............Harlanır da bu can ona yarlanır', 'Sevdam kıra gider,kırlanır Dudağı kiraz,dudağımda ballanır Ah bu yürek bende durmaz harlanır ...........Harlanır da bu can ona yarlanır.. Se...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/selvi-boylum-ince-bellim-ruhumda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbrahim Ethem', 'i-brahim-ethem-mehmet-akif-tiryaki-53oev', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gece İbrahim Ethem hanımı ile

Köşklerinde yatak odasında yatıyor,

Birbirleri ile şakalaşıyordu.

İbrahim Ethem:''Cennette de böyle şakalaşacağız'' dedi.

O esnada köşkün tavanından gürültü geldi.

Orada kim var, ne oluyor diye seslendi.

''Bir şey yok telaşlanma deve güdüyoruz'' denildi.

İbrahim Ethem ''tavanda deve güdülürmü'' dedi.

Bunun üzerine:

''Tavanda deve olmaz da, yatakta cennet bulunurmu''

Diye cevap geldi.

Bu sözden İbrahim Ethem müteessir oldu,

Köşkünü, ailesini bırakıp, 

Çoban elbiseleri giyip, yola koyuldu.

Mevla''ya şöyle münacatta bulundu:

''İlahi! Asi kulun günahlarını itiraf ederek 

Sana geldi, dua etti.''

''Sana olan sevgim yolunda,

Beni parça parça kessende 

Yine kalbim başkasını özlemez,

Senin uğruna ailemi çocuğumu terk ettim,

Seni ahrette görebilmek için yetim bıraktım'' dedi.

Birgün baktı iki melek elinde

Kağıt kalem yazıyor,

Sordu baktı melekler ne yapıyor? 

''Allah dostlarının ismini yazıyorum'' dedi melek,

İbrahim Ethem ''benide yazdınızmı'' dedi

Kendisine ''hayır'' denildi.

Evliya değildi ama Allah dostlarını seviyordu,

Melek bir müddet durdu, sordu.

Sonra:

''Müjde yâ İbrahim'' fermanı ilahi geldi,

Defterin başına isminin yazıldığı söylendi.', 'Bir gece İbrahim Ethem hanımı ile Köşklerinde yatak odasında yatıyor, Birbirleri ile şakalaşıyordu. İbrahim Ethem:''Cennette de böyle şakalaş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ibrahim-ethem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafiyelerin Dini', 'kafiyelerin-dini-muhammed-mehmet-gul-a07bl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen

Alacakaranlık kuşağında

Şiirlerimi kanat kanat göğe uçuran 

Avare güvercinlerin

Yorgun ceylanların sığındığı

Yedi uyuyanların saklandığı in gibisin

Bazen

Acı bir kahvenin tutsakladığı uykularda

Apansız böğrümü delen

Gümüş saplı bir hançer gibi

Sevda sözlerinin arkasına gizlediğin

İçimden çıkaramadığım kin gibisin

Bazen

Bir sigara kağıdına karaladığım

Gün ortası yalnızlıklar gibi

Dudaklarımdan ol verip dökemediğim

Lal olan cümlelerimin

Kafiyelerimin inandığı din gibisin', 'Bazen Alacakaranlık kuşağında Şiirlerimi kanat kanat göğe uçuran  Avare güvercinlerin Yorgun ceylanların sığındığı Yedi uyuyanların saklandı...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kafiyelerin-dini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Yok Sevdamın..', 'adi-yok-sevdamin-filiz-turan-tvqzz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adı yok sevdamın..

Tarifi yok..

Tek bildiğim,

Büyüdüğü içimde

Her geçen gün..

Yüreğimi dolduran,

Bu sevginin adı yok..

Sadece kelimeler

Can veriyor sevdama..

Satır aralarında mutlu oluyor..

Bir isim yetiyor gülümsemesine..

Yüreğimin..

Biliyorum delilik bu..

Adı yok sevdamın..

Tarifi yok..

Tek bildiğim,

Dağlar kadar yüksek..

Başında bulutlar geziyor..

Irmaklar kadar coşkun akıp,

Bentleri yıkıp çağlıyor..

Denizler kadar engin..

Ucu bucağı görünmüyor..

Adı yok sevdamın..

Tarifi yok..

Tek bildiğim,

Kar taneleri kadar masum..

El değmemiş,

Öylesine saf, öylesine temiz..

Ve kuşlar kadar özgür..

Hesapsızca alıp başını gidiyor..

Bazen de yağmur olup,

Öyle içten ağlıyor..

Adı yok sevdamın..

Tarifi yok…

Sadece.. 

Bir deli  sevda işte..

06  şubat 2006', 'Adı yok sevdamın.. Tarifi yok.. Tek bildiğim, Büyüdüğü içimde Her geçen gün.. Yüreğimi dolduran, Bu sevginin adı yok.. Sadece kelimeler Can ...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/adi-yok-sevdamin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hedef', 'hedef-mehmet-akif-tiryaki-gsyd2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hedef dünyayı kazanmaksa boş,

Eğer cennet ise hedef iyi hoş,

Allah''ın cemalini görmekse hedef

En yükseğidir bu,

İşte o kimseler yüksek himmeti buldu.

Cennete müslümanlar hayran olacak,

Daha büyük nimet varmıdır, soracak.

Ne zaman ki Mevla Teala''nın cemalini görecek,

Cennet nimetlerinin değerinin olmadığını 

O zaman bilecek.

İşte geldi zaman hemen Hakka gidelim

Cemali ba kemali seyr idelim

Velev ki sen kur''an bilmedin

Sanki dünyaya hiç gelmedin.', 'Hedef dünyayı kazanmaksa boş, Eğer cennet ise hedef iyi hoş, Allah''ın cemalini görmekse hedef En yükseğidir bu, İşte o kimseler yüksek himme...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hedef-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaz Gecelerde Gel Gir Koynuma!', 'ayaz-gecelerde-gel-gir-koynuma-i-brahim-halil-demir-ujojx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayaz gecelerde gel gir koynuma! 

Isıt, terlet beni boncuk-boncuk! 

Aşığın et at aşkın kemendini boynuma! 

Bozulsun uykularım, sevinçten ağlasın bu çocuk.

Gül ol açıl bahçemde dalında ötüşsün kuşlar! 

Doya-doya seyredeyim her kokladıkça seni.

Yaşanmasın hayatımda ne zemheriler ne de kışlar!

Utansın dünya güzelleri her gördükçe seni!

Pınar ol içir suyundan, dinsin sana olan hararetim! 

Cayır-cayır yanmasın aşkına müptela olan  bu gönlüm!

Görülmedi şimdiye dek senden başkasına esaretim,

Okundukça okunsun kesik uçlu kalemlerle sana yazdığım günlüğüm!

Yedi veren asma ol eksinler seni gönül bahçeme! 

Gölgende otursun sevdalılar anlatsınlar yaşadıklarımı! 

İster aşkını yazsınlar kolumdaki kelepçeme! 

İster çerçeveleyip assınlar aşkına neler  yazdıklarımı.

06/02/2006', 'Ayaz gecelerde gel gir koynuma!  Isıt, terlet beni boncuk-boncuk!  Aşığın et at aşkın kemendini boynuma!  Bozulsun uykularım, sevinçten ağla...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayaz-gecelerde-gel-gir-koynuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin', 'sesin-ahmetnecat-ucur-c2plf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çınlıyor hep kulaklarımda sesin

Bilmeden, oluyorsun bana esin.

Söyler misin sahi, güzel, sen nesin,

Olursun aşığı, haykıran sesin! 

O kadar güzel ki, gerçekten sesin

Sevgiden aşktan, taşacak kesesin,

Nasıl da aşktan ümidin kesesin,

Ümidim, gözüne beni kesesin! 

Ah bir bilsen ki, sevgidir sesin,

Elbet dolacaktır, ruhuma sesin.

Doldukça sevgiyle, aşkıma sesin

Olacak aşık, aşkımıza sesin! 

Biliyorum, aşıksın bana, kesin,

Olmasın haberi diye, herkesin,

Saklıyorsun, kara sevdanı, kesin

Gizleme benden de, aşkımız kesin! 

Aşk ve sevgidir, yaşamında besin,

Boş verelim biz, kim ne derse desin! 

Sebil, değil ki bu, yemeyen yesin,

Sevenler beni, se vi yo rum desin! 

Biliyor musun, sevgilim nerdesin,

Sana aşık gözlerimde, perdesin

Tatlımsın sen çok tatlımsın,zerdesin

Nerde olursam, sen de o yerdesin! 

Söylemesen de sen, gözlerin desin

Sevgilimsin sen de, sevgilim desin

Yemin ediyorum, Allah bir desin

Kim sevmezse, gönül borcu ödesin! 

Ettikçe dualar, sen de edesin,

Aşkınla, aşkımla, aşkla edesin! 

Sevgimi, sevginle mutlu edesin,

Sevgini, sevgimle kutlu edesin! 

Seni, ne çok sevdiğimi bilesin,

Söylemeseydim, nereden bilesin,

Sevgimle sevgin, aşkımı bilesin

Seviyorsun, seviyorum, bilesin! 

Yeter ki sevgin, aşkımı dilesin

Aşkımıza mutluluklar dilesin

Yaşamında hep mutlu edilesin 

Edildikçe,dualarımda sesin!', 'Çınlıyor hep kulaklarımda sesin Bilmeden, oluyorsun bana esin. Söyler misin sahi, güzel, sen nesin, Olursun aşığı, haykıran sesin!  O kadar ...', ARRAY['Türk Edebiyatı','Şiir','Ahmetnecat Ucur']::text[], 8.5, '{"poet":"Ahmetnecat Ucur","poet_slug":"ahmetnecat-ucur","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sesin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Konuşursam', 'bir-konusursam-yusuf-onder-bahceci-53f3n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir konuşursam kıyamet kopar,

Benim bildiklerimi bir bilseniz,

Konuşursam yer yerinden oynar,

Bilin çok canlar yanacak çok,

Haydi açıkla kardeşim açıkla,

Bir şey bilipte açıklamamak,

Bilirsin ki bu Vatana ihanettir,

Herhalde derdin ünlü olmak mı,

Bir suçtan paçayı kurtarmak mı,

Bir konuşursam kıyamet kopar,

Benim bildiklerimi bir bilseniz,

Konuşursam yer yerinden oynar,

Bilin çok canlar yanacak çok,

Yanarsa yansın be kardeşim,

Yananları Allah görmüyor mu,

Lütfen bırakırmısınız bu ağızları,', 'Bir konuşursam kıyamet kopar, Benim bildiklerimi bir bilseniz, Konuşursam yer yerinden oynar, Bilin çok canlar yanacak çok, Haydi açıkla kar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-konusursam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-mavinin-esiri-7y81f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne Kadar Yaşadığımız Değil Önemli Olan

Kimi Ne Kadar Yaşattığımızdır İçimizde

Kimin Ne Kadar Umutla Baktığı Değildir Yaşam

 Kime Ne Kadar Umut Olduğumuzdur

Vücut Haritasında Kaç Tane Cumhuriyet Kurduğumuz

Bir Vücuda Ne Kadar Dayanak Olduğumuz 

Yağmurları Ne Kadar Kesebildiğimiz

Yaşatmaya Çalıştıkça İçimde Ölümü Seçenlere

Umut Ağacının Yeşilliklerinde

Çürümüş Meyva  Olanlara

Bir De Sana Ne Ağaç Ne Umut Ne De Yaşama Dair

Anlamlar Yükleyemediğim Sana

Benzetmeleri Bile Değersiz Kılan Çünkü Benzemeyen

Hiç Bir Anlama.

Ne Desem  Söylediğim Kelimeyide Değersiz Kılarsın.

Bir Şey Söylemesem Bendeki  Beni Boşluğa Atarsın.

Günün Her Dakikasında 

Sendeki Her Bir Noktaya Bir Sözlük Yazılmalı

Toplanmalı Kelimeler

Anlamlar Sorgulanmalı

Hiç Olanı Herşey

Yok Olanı Var Ettin

Bazen Gözlerimde  Sonsuzluk Oluyorsun

Bazen Dalışım Uzaklara

Bazen Kayboluyorsun

Bendeki Derin Savruluşlarda

Her Gün Yeni Bir Şeyler Katıyorsun

Yaşama Bana Nefes Alışıma

Bazen Sessiz Bazen Fırtınalar Gibi Atıyor Kalbim

Bazen Duruyor Sessizliğinde Sesim.

Biliyorum Yokluğunda Her Şey Eski Anlamını Bulacak

Renkler Eski Renk Sesler Aynı

Biliyorum Bakışlar Sonsuz Olmayacak

Biliyorum Kaçışlarım Hep Aynı

Ne Gitme Diyebilirim Sana

Ne Varlığım Gitmene Engel

Hayat Sensizde Yaşanır Ama Nefes Alışımdaki 

Fırtına Sessizlik Olmaz Asla

Kuşlar Yine Öter Ahenkli 

Ama Her Gün Ölür Bendeki Sesler

Bir Ömürlük Kelebek Misali', 'Ne Kadar Yaşadığımız Değil Önemli Olan Kimi Ne Kadar Yaşattığımızdır İçimizde Kimin Ne Kadar Umutla Baktığı Değildir Yaşam  Kime Ne Kadar Um...', ARRAY['Türk Edebiyatı','Şiir','Mavinin Esiri']::text[], 8.5, '{"poet":"Mavinin Esiri","poet_slug":"mavinin-esiri","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sen-754-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahara Varılmaz', 'bahara-varilmaz-orhan-tuncay-9idsy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahara Varılmaz

Güller sessiz, ürkek, bülbüller solgun, ötmez olmuş

Hazan mevsimi soğuk ürpertileriyle benzimde

Gönül bahçemin açmamış gülleri ölmüş

Sevginin adı gitmiş, tadı kalmış son nefesimde

Yare kanmış ümitler güller misali solmuş

Bülbül bulamaz çare kendi sesinde

Devran dolmuş, saat gülmüş, vakit gelmiş

Bahara varılmaz, o erilmez yolun ötesinde', 'Bahara Varılmaz Güller sessiz, ürkek, bülbüller solgun, ötmez olmuş Hazan mevsimi soğuk ürpertileriyle benzimde Gönül bahçemin açmamış gülle...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bahara-varilmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceza', 'ceza-mehtap-tezcoskun-l1k1q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neydi o ses? ..

Söylemekten korktuğum yalnızlığın sesimiydi yoksa? ..

Acı bir çığlıktı duyduğum. 

Böylesi yalnız mıydım ben, 

bu muydu kalabalığın bedeli? 

Bu yalnızlık çığlığımı olmalıydı? …

Tek başınalık, 

öylece kalakalmışlık, 

bir başınalık..

Her şeyin bittiğinin işaretimiydi bu çığlık.

Ve bu yükün üzerine bir başına kucaklamak mıydı,

koca bir geceyi. 

Yıllardır saklamaya, 

korumaya çalıştığım o yaraya dokundu yine kör bıçak. 

O hep kanayan yarama..

Yine tükenmez gecelerde bir ses, 

belki bir ışık, 

belki sıcak bir gülümseme beklemek var zaman kavramlarımda. 

Terk edilişlerimin teker teker aklıma düştüğü anlarımda…

giderken kapatılan,

ve bir daha hiç açılmayacak dediğim,

ama her seferinde aldanıp,

yine açtığım kapılarımda..

her kaybedişin ardından yeni bir ben aradığımda..

hep böyle zamanlar da,

korktuğumdu yalnızlığın çığlığı oysa..

Benim miydi bunca ceza,

bunca mahkumiyet…

bitmedi mi bunca zamandır,

zindanlarında maruz kaldığım işkencem. 

Yok muydu mahkemelerinin affı? ..

kapılarımı bir bir üstüme kapatıp gidenlerin,

hiç mi suçu yoktu? 

Yoksa onlarında mı cezaları bana yüklendi..? 

yetmez miydi bu dört duvar arası karanlık? 

Saatler daha kaç defa vuracaklar sonsuzluğun üstüne? 

Yok mu bu kavramın bir anlamı,

yok mu be benim cezalarımın bir sonu? ..', 'Neydi o ses? .. Söylemekten korktuğum yalnızlığın sesimiydi yoksa? .. Acı bir çığlıktı duyduğum.  Böylesi yalnız mıydım ben,  bu muydu kalab...', ARRAY['Türk Edebiyatı','Şiir','Mehtap Tezcoşkun']::text[], 8.5, '{"poet":"Mehtap Tezcoşkun","poet_slug":"mehtap-tezcoskun","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ceza-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Kadın, Kaçıncı Erkek?', 'i-kinci-kadin-kacinci-erkek-turan-tuncer-78ijz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İKİNCİ KADIN, KAÇINCI ERKEK? 

Bir kadını mutsuz eden 

İkinci kadın

Erkeğin onurunu yaralayan 

Yine bir erkektir

Ustam demişti

Bir zamanlar 

Oğul! 

Kadının en tehlikelisi

Bir erkek''çe yaralanan 

Ve 

Şifayı yine bir erkekte arayandır.

Erkeğin aptalı

Böylesinin peşinde şirazesi kayandır

Kalesi düşende aşk''ta

Kadının, 

Olurmuş

Sevgi hırsızı

                    Aşk arsızı

Yarayı derinden alanda

Erkek

Kaybolurda güveni

Gecelik aşk''lar peşinde 

Sadakât düşmanı

İnsanın en hayırsızı

Ocağına düşen kadın

Yaratılanların en bahtsızı..

04 Şubat 2006 /İst

Alkadraz_Kuşcusu', 'İKİNCİ KADIN, KAÇINCI ERKEK?  Bir kadını mutsuz eden  İkinci kadın Erkeğin onurunu yaralayan  Yine bir erkektir Ustam demişti Bir zamanlar  ...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ikinci-kadin-kacinci-erkek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçtim Senden', 'vazgectim-senden-gul-yazganarikan-w3i3a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vazgeçtim senden....

Vazgeçtim...

İstemem artık ellerini

İstemem...

Öpmem ben o dudakları

Yemin olsun...

Yanıp tutuşsam da hasretinle

Dokunmam...

Anmam artık adını

Tutamazsam sözümü,

Aldığım bir nefes bin kere 

haram olsun...

Vazgeçtim senden...

Vazgeçtim...

İnanmam sözlerine,

Ve o yalan oynaşan gözlerine,

Gönlüm bağlanmaz senin

Zehirli gönül tellerine...

Vazgeçtim...

Vazgeçtim senden...

Bil ki bozarsam bu yemini ben

Koynuma senden önce giren

Ölüm olsun....', 'Vazgeçtim senden.... Vazgeçtim... İstemem artık ellerini İstemem... Öpmem ben o dudakları Yemin olsun... Yanıp tutuşsam da hasretinle Dokunm...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/vazgectim-senden-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski', 'eski-bilal-i-lhami-koksal-im8nk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni sevmek 

Çok eskiden çektirdiğin bir fotoğrafa bakıp

Ne kadar da komikmişim diye gülümsemek 

Sahi ne kadar da çocukmuşuz...', 'Seni sevmek  Çok eskiden çektirdiğin bir fotoğrafa bakıp Ne kadar da komikmişim diye gülümsemek  Sahi ne kadar da çocukmuşuz......', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/eski-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başkasın', 'bir-baskasin-mehmet-sait-akkus-76jyl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün bir başkasın güzelim

Duruşun başka

Gülüşün başka

Konuşman başka

Başlıbaşına bir başkasın

Yürüşün başka

Sevmen başka

Sevilmen başka

Başlıbaşına bir güzelsin

Giyimin başka

Oturuşun başka

Yemek yiyişin bile başka

Başlıbaşına bir abidesin

Bana bakışın başka

Hayta bakışın başka

Ama sen

Gözümde bir başkasın güzelim', 'Bu gün bir başkasın güzelim Duruşun başka Gülüşün başka Konuşman başka Başlıbaşına bir başkasın Yürüşün başka Sevmen başka Sevilmen başka Ba...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-baskasin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğime Akıyorsun', 'yuregime-akiyorsun-mehmet-sait-akkus-4ardy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmur olup yağacaksan

Yüreğime akacaksan

Benim için yanacaksan

Ölümüne seviyorum

Damla damla düşüyorsun

Yüreğime akıyorsun

Benim için ölüyorsun

Ölümüne seviyorum

Sana canlar cananımı

Gözümdeki mercanımı

Senin için bu canımı

Vereceğim biliyorsun', 'Yağmur olup yağacaksan Yüreğime akacaksan Benim için yanacaksan Ölümüne seviyorum Damla damla düşüyorsun Yüreğime akıyorsun Benim için ölüyo...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuregime-akiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Bir Ümit Neylerim', 'i-cimde-bir-umit-neylerim-yusuf-onder-bahceci-8zy3j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel sen her lafa inanıp kanma,

Senin için ölürüm sen yanma,

Şu aşkın kâlbimi yakıyor ama,

İçimde bir ümit şimdi neylerim.

Ben sensiz gecelerde ağlıyorum,

Hem ağlıyorum hem de arıyorum,

Bildiğim dualarla yalvarıyorum,

İçimde bir ümit şimdi neylerim.

Sen bana sevmiyorum demedin,

Sadece boyun büktün bilmedim,

Kendime kahırlar edip gülmedim,

İçimde bir ümit şimdi neylerim.

Benim böyle şiirlerim bilki duadır,

Ellerimi Allah''a açarım ona onadır,

Dizlerime vuruyorsam bilki duadır,

İçimde bir ümit şimdi neylerim....', 'Gel sen her lafa inanıp kanma, Senin için ölürüm sen yanma, Şu aşkın kâlbimi yakıyor ama, İçimde bir ümit şimdi neylerim. Ben sensiz geceler...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/icimde-bir-umit-neylerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-mehmet-faruk-turkoglu-ol4s4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir yer vardı düşümde, 

uçsuz bucaksız. 

ayaklarım yeşil,başım mavi. 

uyandırdın. 

neden bu kadar karanlık? 

açma pencereyi, 

korkuyorum. 

aç kucağını anne, 

uyumak istiyorum.', 'bir yer vardı düşümde,  uçsuz bucaksız.  ayaklarım yeşil,başım mavi.  uyandırdın.  neden bu kadar karanlık?  açma pencereyi,  korkuyorum.  a...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Türkoğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Türkoğlu","poet_slug":"mehmet-faruk-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anne-196-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek', 'bebek-mehmet-zeki-gezici-vzz7k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Torunum İsmail Deniz'' e

Sen geleceksin diye bebek,

Açık tuttuk

Gökyüzünün kapılarını,

Nehir yataklarını açık,

Açık tuttuk özgürlüğün yollarını

Yüreğimizin kapılarını açık.

Sen hayatın baharı mısın

Başlangıcı mısın esen rüzgarların

Yeniden doğan güneşin

Umudu musun bebek.

Sen şarkılarını

Saçlarını büyüten bebek

Doğmadan önce

Sonsuzun kıyısında uyurdun.

Şimdi rüzgarın içinde

Sonsuz bir geleceksin,

Sen özgürlüğü

Yıldızlarla paylaşan bebek.', 'Torunum İsmail Deniz'' e Sen geleceksin diye bebek, Açık tuttuk Gökyüzünün kapılarını, Nehir yataklarını açık, Açık tuttuk özgürlüğün yolları...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bebek-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-muhammed-mehmet-gul-29zcb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Türküydü şarkıydı gözlerin

Farkın tek farkıydı gözlerin

Ruhumu yokluğa götüren

Irmağın arkıydı gözlerin

Gecelere aydı gözlerin

Yıldız gibi kaydı gözlerin

Beni şiirlerimden vuran

Bir oktu bir yaydı gözlerin

Yudum yudum meydi gözlerin

Tarifsiz herşeydi gözlerin

Hep garip garip üflediğin

Tılsımlı bir ney''di gözlerin', 'Türküydü şarkıydı gözlerin Farkın tek farkıydı gözlerin Ruhumu yokluğa götüren Irmağın arkıydı gözlerin Gecelere aydı gözlerin Yıldız gibi k...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerin-220-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-mehmet-faruk-turkoglu-mclbk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karakışın kör ayazındayım, 

gece soğuk, 

dumanı tüten bir ömrün, yanıbaşındayım. 

geriye kalan:

bir avuç kül,

rüzgarda savrulan. 

ve bir çift kor parçası:

senin gözlerin, 

yıldızlardan da uzakta sanki parlayan. 

uzansam, dokunamam. 

dokunsam,ellerim yanacak. 

korkmaktayım. 

gece acımasız, 

ben güneşe hasret,inadına sabah çok uzak. 

nefesim kasiliyor,avuçlarım yanıyor, 

tükenmekteyim. 

bir yıldız kayıyor, 

dilek tutuyorum, 

yıldız kaymasın.', 'Karakışın kör ayazındayım,  gece soğuk,  dumanı tüten bir ömrün, yanıbaşındayım.  geriye kalan: bir avuç kül, rüzgarda savrulan.  ve bir çif...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Türkoğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Türkoğlu","poet_slug":"mehmet-faruk-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gece-209-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melankoli', 'melankoli-mehmet-faruk-turkoglu-zpq3g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'garip bir his var içimde, 

ölesim tuttu. 

feryatlarım sahipsiz,

sesim boşlukta bir yankı. 

umutlar, hayaller

beni unuttu.', 'garip bir his var içimde,  ölesim tuttu.  feryatlarım sahipsiz, sesim boşlukta bir yankı.  umutlar, hayaller beni unuttu....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Türkoğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Türkoğlu","poet_slug":"mehmet-faruk-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/melankoli-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Tanrı...', 'dost-tanri-hidir-cam-hqa2e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün gece Tanrı’yla bir sofra kurduk

Saz çalıp eğlendik sabaha kadar

Arz-u hal eyleyip, hal hatır sorduk

Birlikte demlendik sabaha kadar

Dizine yaslandım, zaman çürüdü

Bir gece dedimse, on bin yıl sürdü

Her bana bakışta, kendini gördü

Diz dize dinlendik sabaha kadar

Büyük başın derdi, daha büyükmüş

Cümle can, kainat sırtında yükmüş

Ömür, bir tadımlık ötesi yokmuş

Aşk ile bellendik sabaha kadar

Dedi hiç hırslanma boşa o telaş

Çok bela getirir başa bu telaş 

Ne katran kazanım, ne kor, ne ataş

Su serpti küllendik sabaha kadar

Dedim terkeyleme hep yanımda kal

Dedi bir bütündür kök, gövde  ve dal

Meğer ben körmüşüm, O da suskun, lal

Can gördük, dillendik sabaha kadar

Bir gece boyunca, bin sual sorduk

Adem’den bugüne çok kafa yorduk

Gökten yere inen bir çift tohumduk

Birlikte, çimlendik sabaha kadar', 'Dün gece Tanrı’yla bir sofra kurduk Saz çalıp eğlendik sabaha kadar Arz-u hal eyleyip, hal hatır sorduk Birlikte demlendik sabaha kadar Dizi...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Çam']::text[], 8.5, '{"poet":"Hıdır Çam","poet_slug":"hidir-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dost-tanri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hülya', 'hulya-mehmet-faruk-turkoglu-yzxmk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir tutabilsem ellerinden,

alıp götürsem seni 

yürüsek bir deniz kenarında

bir akşam vakti

ay kıskanıp güzelleğini gözükmese gökyüzünde 

senin yüzün düşse denize yakamoz olsa 

seyretsem seni 

sabah olmasa. 

dalıp gitsem gözlerine 

aydınlansa karanlıklar cevap bulsa tüm sorular

 o simsiyah gözlerinde 

unutsam dünyayı unutsam herşeyi 

bir sen olsan aklımda bir senin gözlerin 

çiçek açca kumsal, bahar olsa mevsim, bayram gelse gönlüme çocuk olsa 

koysam başımı dizlerine 

dilimde bir garip türkü 

''''düşlerin parlayıp söndüğü yerde buluşmak seninle...'''' 

zaman dursa.', 'bir tutabilsem ellerinden, alıp götürsem seni  yürüsek bir deniz kenarında bir akşam vakti ay kıskanıp güzelleğini gözükmese gökyüzünde  sen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Türkoğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Türkoğlu","poet_slug":"mehmet-faruk-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hulya-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beynamazlar', 'beynamazlar-sahin-erturk-xy859', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haram bilmiyorlar

Helal yemiyorlar

Yüzünü yıkamayan

Beynamazlar

Abdessiz

Açık,saçık camideler

Evde namaz kılmıyorlar

Nahmahrem

Erkeklerle aynı safta

Namaz kılacağız diyorlar

Belliki

Reklam peşindeler

Dini bilmeden

Anlamadan,dinlemeden

Fetva veriyorlar

Ağzı olan konuşuyor

Farzı bilen yok

Sünneti takan yok

Ayat bilmiyorlar

Hadis takmıyorlar

Din düşmanı

Beynamazlar

Çekin elinizi İSLAMDAN

Camiler size yakışmıyor

Size meyhaneler

Kiliseler yakışır

Gidin oralarda tepişin

Gidin oralarda sevişin

Egolarınızı,arzularınızı

Gidin oralarda tatmin edin

Sizler evet,evet sizler

İslama yakışmıyorsunuz

Çekin elinizi İSLAMDAN

Sizi gidi BEYNAMAZLAR

Sizi gidi BEYNAMAZLAR

(06.02.2006)', 'Haram bilmiyorlar Helal yemiyorlar Yüzünü yıkamayan Beynamazlar Abdessiz Açık,saçık camideler Evde namaz kılmıyorlar Nahmahrem Erkeklerle ay...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/beynamazlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsun', 'olsun-mehmet-zeki-gezici-zy59o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırk yıllık eşi olacağına 

Bir hükümdarın

Bir şairin üç günlük sevgilisi ol.

Ömrün kelebek kadar güzel olsun.

Bir çiftçinin yavuklusu ol

Mısır ekmeğinde tüten buhar

Senin emeğin olsun

Bir ağacın dalı ol

Ardıç ve gürgen ormanlarında

Çiçeklerin adı badem olsun.

Dağlara bak

Gökten inen su

Topraktan gelen bahar tatın olsun.

Şimdi gökyüzüne bak

İşaret parmağı ile Tanrının

Gösterdiği yerde beni göreceksin

Gülüm yüreğim senin olsun.', 'Kırk yıllık eşi olacağına  Bir hükümdarın Bir şairin üç günlük sevgilisi ol. Ömrün kelebek kadar güzel olsun. Bir çiftçinin yavuklusu ol Mıs...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olsun-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldü Say', 'oldu-say-muhammed-mehmet-gul-amwfy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey

Yüreğimin meydanlarında başlamadan biten halay

Biliyorsun ezgilerim erken vuruldu

Ben duruldum

Hadi geçmiş gibi aradan yıllar

Ve binlerce ay

Beni öldü say.', 'Ey Yüreğimin meydanlarında başlamadan biten halay Biliyorsun ezgilerim erken vuruldu Ben duruldum Hadi geçmiş gibi aradan yıllar Ve binlerce...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/oldu-say-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Başımdan', 'git-basimdan-mustafa-selcuk-keskin-aws64', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Git başımdan istemiyorum ben seni.

Her sabah aynamdan bana bakıp durma! 

Bırak rahatça yaşayayım günümü.

Hayalinle karşımda kırıtıp durma! 

Git başımdan istemiyorum ben seni.

Başımı belaya sokmayamı geldin? 

Ne işim olurdu ki benim sevdayla.

Gözlerindeki kurşun tenindeki kin...

Git artık baştan çıkaran günahınla! 

Başımı belaya sokmayamı geldin? 

Pul altın olmaz boyamakla sarıya.

Bendeki o beni sen ne bileceksin.

Suyu tırnaklayan ellerim duru ya...

Kan kustuğum günleri de göreceksin.

Pul altın olmaz boyamakla sarıya.

Niye hep adını sayıklıyorum ki? 

Sırılsıklam uykulardan uyanırken? 

Oysa beynimde çoktan öldü bu türkü.

Bu gece kendimi bile sevemezken; 

Niye hep adını sayıklıyorum ki? 

(Konya-2001)', 'Git başımdan istemiyorum ben seni. Her sabah aynamdan bana bakıp durma!  Bırak rahatça yaşayayım günümü. Hayalinle karşımda kırıtıp durma!  ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Selçuk Keskin']::text[], 8.5, '{"poet":"Mustafa Selçuk Keskin","poet_slug":"mustafa-selcuk-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/git-basimdan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Aşk Bu Kalbe Sığmıyor', 'bu-ask-bu-kalbe-sigmiyor-sahin-erturk-y43yc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana olan sevgim

Artık bu kalbe sığmıyor

Yıllar geçtikce

Ağacın,toprağa

Dişin,damağa

Bağlandığı gibi

Dahada çok

Bağlanıyorum sana? 

Bu ülkenin

Bütün barajlarından

Çok daha fazla

Senle,sevginle doluyum? 

Bazen

Korkutuyor bu sevdan

Taşarsam

Taşıyamazsam aşkını

Sen duramazsan

Bu taşkının önünde

Kaldıramazsan

Bu aşkın büyüklüğünü? 

Sana olan sevgim

Artık bu kalbe sığmıyor

Korkuyorum güzelim

Artık korkuyorum

Bu dünyaya,bu kalbe

Bu aşk sığmaz diye

Aşkımın büyüklüğünden

Artık korkuyorum

Artık korkuyorum

(06.02.2006-Yeni)', 'Sana olan sevgim Artık bu kalbe sığmıyor Yıllar geçtikce Ağacın,toprağa Dişin,damağa Bağlandığı gibi Dahada çok Bağlanıyorum sana?  Bu ülken...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bu-ask-bu-kalbe-sigmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Tanrısı', 'siir-tanrisi-mehmet-zeki-gezici-sybh2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kadın

Gönlünü

Bir şaire

Hoş ettirirse

Ben onun

İki dünyasını

Cennet eylerim.', 'Bir kadın Gönlünü Bir şaire Hoş ettirirse Ben onun İki dünyasını Cennet eylerim....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/siir-tanrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığı Bu Kalbe Sor', 'ayriligi-bu-kalbe-sor-sahin-erturk-bpon9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beynimdeki seni silmek

O denli zor,o denli zor

Ayrılığı sen bana sor

Sor güzelim,bu kalbe sor

Ayrılığı bu kalbe sor

(06.02.2005-Yeni)', 'Beynimdeki seni silmek O denli zor,o denli zor Ayrılığı sen bana sor Sor güzelim,bu kalbe sor Ayrılığı bu kalbe sor (06.02.2005-Yeni)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayriligi-bu-kalbe-sor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Korktum Ahım Yakacak Diye', 'cok-korktum-ahim-yakacak-diye-yusuf-onder-bahceci-axp11', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilirmisin yıllarca yollara baktım da baktım,

İçimi çekerek tabakadan bir sigara yaktım,

Bir duman çekip te şöyle bir savuracaktım,

Çok korktum âhım seni yakacak diye.

Benim sevdiğim güzel böyle zalim değildi,

Acep kim ne dedi de böyle yerlere eğildi,

Ben onun için cânı verirdim o neyi verirdi,

Çok korktum âhım seni yakacak diye.

Seviyorum seni güzelim başka ne deyim,

Seni elimden aldılar söyle nasıl güleyim,

Senden ne haber deyim selam söyleyim,

Çok korktum âhım seni yakacak diye.

Şimdi bize bu yüce sevdadan neler kaldı,

Çok sevdiğim güzel yârdan yalanlar ayırdı,

O bunu mutlaka anladı da günlerce ağladı,

Çok korktum âhım onu yakacak diye....', 'Bilirmisin yıllarca yollara baktım da baktım, İçimi çekerek tabakadan bir sigara yaktım, Bir duman çekip te şöyle bir savuracaktım, Çok kork...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-korktum-ahim-yakacak-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Avuç Toprak', 'bir-avuc-toprak-sahin-erturk-gq4wn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mal peşinde koşma,doyumsuz olma

Dünya yalan ölüm gerçek unutma

Hak yolu İslamdan,sakın ayrılma

Yatların,katların doyurmaz amma

Gözünü doyurur bir avuç toprak

(05.02.2006-Yeni)', 'Mal peşinde koşma,doyumsuz olma Dünya yalan ölüm gerçek unutma Hak yolu İslamdan,sakın ayrılma Yatların,katların doyurmaz amma Gözünü doyuru...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-avuc-toprak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Ayrılık Şarkıları', 'i-cimde-ayrilik-sarkilari-turan-tuncer-5bjk0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İÇİMDE  AYRILIK  ŞARKILARI

Sen 

Gelmezsen,

Akşam 

Olurmu samırsın? 

Ağustosta

Karlar yağar başıma

Gözlerimde

Kapılara

Umutsuz bakışlar

Hep bir özlem

Büyürde içimde

Akşamlara

Şarkılarım 

Özlemelerle dolu

Ayrılıklar üstüne

Bütün şiirlerim

Hep sonbahar 

Bende yaşam

Tüm güzel dileklerimi

Ekin ettim,

Yaşamın bozkırına 

Yağmura bereket

Yalnız gözlerimde şimdi

Hep kurak

Hep kıtlık 

Bende yaşam

20-06-2005/İst

Alkadraz_Kuşcusu', 'İÇİMDE  AYRILIK  ŞARKILARI Sen  Gelmezsen, Akşam  Olurmu samırsın?  Ağustosta Karlar yağar başıma Gözlerimde Kapılara Umutsuz bakışlar Hep b...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/icimde-ayrilik-sarkilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taksimetre', 'taksimetre-mustafa-selcuk-keskin-4w0qw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bende geceler pahalı olur.

Tüm duygularım çifte tarife...

Gündüz bir seviyorsam seni

İki, beş, bin her gece...

Bende geceler pahalı olur.

Tüm duygularım...

Yok yok! ? ...

Yalnız sevdan çifte tarife

Her gece...

(Konya-2000)', 'Bende geceler pahalı olur. Tüm duygularım çifte tarife... Gündüz bir seviyorsam seni İki, beş, bin her gece... Bende geceler pahalı olur. Tü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Selçuk Keskin']::text[], 8.5, '{"poet":"Mustafa Selçuk Keskin","poet_slug":"mustafa-selcuk-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/taksimetre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak Sevda', 'tutsak-sevda-taylan-cicek-7u1wb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tutsak bir sevda benimkisi, biliyorum

Zincirlenmiş, prangalar vurulmuş

Sürgün bir sevda benimkisi, biliyorum

Yorulmuş, elden ele savrulmuş

Ben unutsam da, ellerim unutmadı saçlarında dolaşmayı, gözlerim unutmadı gözlerinde kaybolmayı ve yüreğim; senden her kaçışımda en büyük karanlıkları, en amansız korkuları ve en derin sessizlikleri bir çığlık gibi yarıp beni sana getiren yüreğim, seni asla unutmadı

Yasak bir sevda benimkisi, biliyorum

Anadilim gibi, tarihim gibi

Yorgun bir sevda benimkisi, biliyorum

Dağlarım gibi, taranmış, hırpalanmış

Gel bahar gözlü tutsak sevdam, ovalarından kaçarak çıktığımız bahar kokulu memleketimize dağlarından koşarak inelim. Masum bir çocuğun duası, elleri nasırlı anaların umudu olsun sevdamız. Ve şunu unutma sevdiğim, uğruna ölümlere gidip geldiğim; 

Seni en çok ellerim bağlıyken sevdim ve hüznüm tutsakken özledim.', 'Tutsak bir sevda benimkisi, biliyorum Zincirlenmiş, prangalar vurulmuş Sürgün bir sevda benimkisi, biliyorum Yorulmuş, elden ele savrulmuş B...', ARRAY['Türk Edebiyatı','Şiir','Taylan Çiçek']::text[], 8.5, '{"poet":"Taylan Çiçek","poet_slug":"taylan-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tutsak-sevda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılmaz Güney''e', 'yilmaz-guney-e-yusuf-ter-6zcp1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Devrimler için savaşı 

Yılmazım benim yoldaşım

Kavgamız faşizme karşı

Yılmaz Güney’i aradım

Çirkin kral  sinemada 

Nasıl benzerdi halkıma

Halkıyla gezdi kol kola

Yılmaz Güney’i aradım

Şafak olmuyor burada

Güneş doğmaz şu mapusda

Dört duvarın arasında 

Yılmaz Güney’i aradım

Yusuf Ter 05.02.06

Saat 01:55 İsviçre', 'Devrimler için savaşı  Yılmazım benim yoldaşım Kavgamız faşizme karşı Yılmaz Güney’i aradım Çirkin kral  sinemada  Nasıl benzerdi halkıma Ha...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yilmaz-guney-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlatla konuşma', 'evlatla-konusma-tevfik-karinca-fp9rr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok uzun bir yolculuğa çıkıyorum dedi

Baba, evladına

Beni anlaman zor olacak

Gelecekte

Sorgulaman uzun sürecek

Biliyorum ki

Önce yanlışlarımı göreceksin

Doğruların görünmesi zordur çünkü

Haklı olmam ya da haksızlığım

Zerrece değerli değil

Bilmeni istediğim tek şey

Herşey senin içindi

Mücadele ettim yaşamla

Kaybettim

Babanı affet', 'Çok uzun bir yolculuğa çıkıyorum dedi Baba, evladına Beni anlaman zor olacak Gelecekte Sorgulaman uzun sürecek Biliyorum ki Önce yanlışlarım...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/evlatla-konusma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesiniz?', 'neredesiniz-saim-bastik-gijwi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Peygamber’e hakaret, ettiler içim sızlar

Dinden geçinen beyler! Neden böyle suspuslar

Dilinizmi tutuldu, DİYALOGÇU deyyuslar

İşte; biz burudayız,hani siz  nerdesiniz? 

Diyalog diye diye,ne hallere geldik bak

Eserinle övünüp,her yerine  kına yak

Diyalog halkasını,münasip yerine tak

İşte; biz  buradayız,hani siz nerdesiniz? 

Türban için camide,gösteriler yapanlar

Ellerinde GÜL’lerle,buna çanak tutanlar

Bir adım önde gidip,aslını unutanlar

İşte; biz buradayız, hani siz nerdesiniz? 

Biliriz; münafıkla ilişkiniz çok derin

Susarak siz bunlardan,aldınız mı aferin

Türban kadar değeri,yokmudur Peygamberin? 

İşte; biz buradayız, hani siz nerdesiniz? 

Papanın aciz kulu,hahamın dastları,siz

Nerenizden tutalım,rezillik diz boyu diz

Korkmayın; gerekirse, sizleri koruruz biz

İşte; biz buradayız, hani siz nerdesiniz? 

05/02/2006', 'Peygamber’e hakaret, ettiler içim sızlar Dinden geçinen beyler! Neden böyle suspuslar Dilinizmi tutuldu, DİYALOGÇU deyyuslar İşte; biz burud...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/neredesiniz-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümdür Yalnızlık', 'olumdur-yalnizlik-ali-gencay-zf961', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sızlayan yürekte gördüm ölümü

Siz, yalnızlık diye böğürenler 

Duyun beni

Çıkarıp gelmişi, geçmişi

Üşümek mi istiyor ruhunuz

Ölmek istiyorsunuz

Ben yalnızım! 

Hadi öldürün beni

Üşüyorum

Sessizliğin tavşan kanı deminde

Ne garip umutlanmak

Kendi ayak sesinle

Size yemin ısınmıyor insan

Tek kalan kibritin alevinde

Üşüyorum

Yalnızlığın bendeki esirliğinde

Küçük çocuğun gözlerinde yaşam

Devleşmiş hayalleriyle

Büyük bedende yalnızlık

İşte ben! 

Yitirilmiş günlerin inlemeleriyle

Şimdi şarkılarla sarhoş olma vakti

Ya da küfür etmek meziyetse

Dilim döndüğünce

Satmışım anasını

Ne kalmış elimde

Siz yalnızlık diye böğürenler

Ben yalnızım! 

Hadi öldürün beni

Aşk sevgili ister, şiir aşk

Yalnızlık ölümü ister

Gün gelip sessizlik zifirleştiğinde

İşte yalnızım ben

Katran karası gecemde

Hadi öldürün beni

Sizde yalnızlık dirilmeden önce', 'Sızlayan yürekte gördüm ölümü Siz, yalnızlık diye böğürenler  Duyun beni Çıkarıp gelmişi, geçmişi Üşümek mi istiyor ruhunuz Ölmek istiyorsun...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/olumdur-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşkın', 'saskin-oktay-baykurt-09w8z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözlerinin arkasındaki aklın

kalbine bir yol açar  inceden

yola düşmek istemezsin

ama ayağın atmıştır ilk adımı çoktan

sen geri çekilmek istedikçe

yolu yarılamışsındır

gitmek istemezken

dönmeyi göze alamazsın

ve işaretlerini takip edersin sözlerimin

bana gelmek için mi

yoksa içindeki adsızı teskin etmek için mi bilinmez

kalbine varırsın dona kalırsın

şaşarsın böyle durumda olduğuna

ama kendi kalbinde benim gözlerimi ararsın

mührümü görürsün  yine şaşırırsın

anlarsın ki sen benim sevdamsın', 'gözlerinin arkasındaki aklın kalbine bir yol açar  inceden yola düşmek istemezsin ama ayağın atmıştır ilk adımı çoktan sen geri çekilmek ist...', ARRAY['Türk Edebiyatı','Şiir','Oktay Baykurt']::text[], 8.5, '{"poet":"Oktay Baykurt","poet_slug":"oktay-baykurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saskin-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pembeyi Sevmiyorum Artık', 'pembeyi-sevmiyorum-artik-yusuf-onder-bahceci-tpv0v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pembe hâyallerle başladı,

Pembeyi sevmiyorum artık,

Pembe ne kadar da yalan,

Pembeyi sevmiyorum artık.

Hayat toz pembeydi inan,

Pembe tablolardı satılan,

Duvarlar pembe olacaktı,

Pembeyi sevmiyorum artık.

Pembeydi yalancıların rengi,

Bil pembe hâyallerimi yedi,

Yanakları da gül pembeydi,

Pembeyi sevmiyorum artık.

Bana pembe güzel demeyin,

Allah aşkına gönül eylemeyin,

Benim bahtım karadır deyim,

Pembeyi sevmiyorum artık...', 'Pembe hâyallerle başladı, Pembeyi sevmiyorum artık, Pembe ne kadar da yalan, Pembeyi sevmiyorum artık. Hayat toz pembeydi inan, Pembe tablol...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pembeyi-sevmiyorum-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat bir nefes', 'hayat-bir-nefes-osman-ergun-9xk8z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Git diyor içimden bir ses.

Yüreğinin götürdüğü yere,

Git gidebildiğin kadar,

Nereye olursa git.

İşte geldin gidiyorsun, 

Hayat dediğin ne ki, 

Hepsi bir nefes.

Yap ne istiyorsan, yapabildiğince.

Ne yapacaksan yap.

Kimse tutamasın seni,

Kırılsın etrafındaki kafes.

Bu zorluklar durdurmasın seni,

Koş koşabildiğince, deli taylar gibi

Deli desinler sana, mecnun desinler.

Ne derlerse desinler, asla etme pes.

Özgür ol kuşlar gibi,

Dik ol, aşılmaz yokuşlar gibi

Yağmur gibi yağ, rüzgar gibi es.

Bak geriye,

Hayat dediğin ne ki,

Hepsi bir nefes.

04.02.2006', 'Git diyor içimden bir ses. Yüreğinin götürdüğü yere, Git gidebildiğin kadar, Nereye olursa git. İşte geldin gidiyorsun,  Hayat dediğin ne ki...', ARRAY['Türk Edebiyatı','Şiir','Osman Ergün']::text[], 8.5, '{"poet":"Osman Ergün","poet_slug":"osman-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hayat-bir-nefes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlilik mi, Bekarlık mı?', 'evlilik-mi-bekarlik-mi-hasan-i-yigun-tvfi8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sordular bana dün gece, bir dost meclisinde

Evlilik mi güzel, bekarlık mı hoş diye

Sordum onlara evlenmek için sevgi şart mıdır? 

Bekar kalmak, sevgiden mahrum olmak mıdır? 

Nice evliler gördüm; sevgiden, aşktan yoksun 

Nice bekarlar tanıdım aşkı ve sevgiyi yaşayan

Sordum onlara: Evlisin, aşık mısın? 

Bekarsın, aşktan mahrum musun? 

Evliler başını salladı ah çekerek

Bekarlar ah çekti gülümseyerek.', 'Sordular bana dün gece, bir dost meclisinde Evlilik mi güzel, bekarlık mı hoş diye Sordum onlara evlenmek için sevgi şart mıdır?  Bekar kalm...', ARRAY['Türk Edebiyatı','Şiir','Hasan İyigün']::text[], 8.5, '{"poet":"Hasan İyigün","poet_slug":"hasan-i-yigun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/evlilik-mi-bekarlik-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Derim', 'nasil-derim-asude-gediz-pzcpv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kilitdir çaresizliğim

yüreğimin esiri gözlerim, sözlerim

ciğerlerimde nefesken izlerin

nasıl derim? 

güneşi kucaklıyorum hayalinle

sevdam gururumun zinciri

dilim bağlı,  yeminli

nasıl derim? 

gitmek için bu ne heves böyle

ölüm, sevgimiz; çelişkide

geçmiş sarıyor benliğimi sessizce

ne ederim....', 'kilitdir çaresizliğim yüreğimin esiri gözlerim, sözlerim ciğerlerimde nefesken izlerin nasıl derim?  güneşi kucaklıyorum hayalinle sevdam gu...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nasil-derim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Temiz Diyor', 'kalbim-temiz-diyor-yusuf-onder-bahceci-nqbc4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sorsan kâlbim temizdir diyor,

Allah''a, dine ve imana küfrediyor,

Dedem de hocaydı vallahi diyor,

Bir sorsan kâlbim temizdir diyor.

Benim kâlbim çok temizdir diyor,

Türlü türlü pislik, melanetler yiyor,

Dedem de müftüydü vallahi diyor,

Bir sorsan kâlbim temizdir diyor.

Benim kâlbim çok temizdir diyor,

Yalan ve dolanı maharet sanıyor,

Haramı da o biçim o biçim yiyor,

Bir sorsan kâlbim temizdir diyor.

Benim kâlbim çok temizdir diyor,

Türlü türlü pırasa ve naneler yiyor,

Bıraksan kardeşim sen bu lafları,

Bir sorsan kâlbim temizdir diyor.....', 'Bir sorsan kâlbim temizdir diyor, Allah''a, dine ve imana küfrediyor, Dedem de hocaydı vallahi diyor, Bir sorsan kâlbim temizdir diyor. Benim...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalbim-temiz-diyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biiiiiiit.... ti.', 'biiiiiiit-ti-nazan-i-zmirli-an963', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tanıştığın   ben

sen  de  yaratılan

ben  di

sen  de   yaşandı 

sen  de   bitti

ne..  öncesi 

.............oldu

ne   sonrası

........olacak

biiiiiiiit......ti.

06.02.06-antalya', 'tanıştığın   ben sen  de  yaratılan ben  di sen  de   yaşandı  sen  de   bitti ne..  öncesi  .............oldu ne   sonrası ........olacak b...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/biiiiiiit-ti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Desende Olur Demesende', 'desende-olur-demesende-zeliha-bicer-bw73n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Desende olur

Söylemesende sevgini

Dokunmasan da razıyım

Yeter ki gitme..', 'Desende olur Söylemesende sevgini Dokunmasan da razıyım Yeter ki gitme.....', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/desende-olur-demesende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Ne Derse Desin', 'el-ne-derse-desin-yusuf-onder-bahceci-d023f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'El ne derse desin, sevdim benimsin,

Seviyorum seni derim sevdim benimsin,

Ne kadar da güzelsin sevdim benimsin,

El ne derse desin, sevdim benimsin.

Şu Dünya''da zalimler ne kadar da çok,

Sen ne dediğimi düşünsene pek çok,

Bu kalbimde hiç bir zaman ihanet yok,

El ne derse desin, sevdim benimsin.

Gül bahçesine girenler hep gül kokuyor,

Bu ayrılığın acısı bak yıllar sonra çıkıyor,

O seni seviyorsa bilki yollarına bakıyor,

El ne derse desin, sevdim benimsin.

Ben her şeyi öğrendim suçun yok senin,

Ben de senin gibiyim suçum yok derim,

Allah''ım ne çok seviyorum nasıl ederim,

El ne derse desin, sevdim benimsin....', 'El ne derse desin, sevdim benimsin, Seviyorum seni derim sevdim benimsin, Ne kadar da güzelsin sevdim benimsin, El ne derse desin, sevdim be...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/el-ne-derse-desin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasemin', 'yasemin-tugba-simsek-0i1e6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeni yeni sevgililer aramak istemiyorum ben

Askim, canim, sevdam, kalbimsin sen

Seni istiyorum, sadece senin olmak istiyorum ben

Evlenip benimle yuvamin kadini olur musun sen? 

Merak etme yaricegim yalniz seni sevecegim ben

Inan ne olursun, su kalbime gel benim ol sen

Ne olursun bebegim sonsuza dek senin olacagim ben

4.02.2006  22.59

(yasemin duru ya...)', 'Yeni yeni sevgililer aramak istemiyorum ben Askim, canim, sevdam, kalbimsin sen Seni istiyorum, sadece senin olmak istiyorum ben Evlenip ben...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Şimşek']::text[], 8.5, '{"poet":"Tuğba Şimşek","poet_slug":"tugba-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasemin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanal Dünya', 'sanal-dunya-cemil-aygen-xrjoc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aklımda 

Bir sürü Güzel düşünce var

Hep iyiye çok yakın

Sevgiye çok yakın

Hani yaşamla birlikteyim

Sevgi içimde saf ve net bir duygu

Mevsimlerle zamanla Geceyle Gündüzle

Değişen bir durum değil

Hani iyilik yap 

Denize at

Sevgiyle yürek yapta Cennete git der gibi

Binlerce heyecan binlerce kıpırtı içimde

Sevinçten ölüyorum desem de

Sıkılıyorum desemde

Hayatın içindeyim desemde..Aslolan..

Bir yaşam sevinci...

Bir yaşama arzusu var bende

Hani hayatı da yaşamayı da seviyorum

Fakat biliyorum ki

Hayatın içi yanlışlıklarla dolu

Bencil bir dünya ve bencil düşünceler var

Hiçbirşey Düzgün değil

Yanlışta Hepsi koca bir Gerçekle

Hayatın içine saklanmış

Zırt pırt yakışıksızca önümüze çıkıyor

Kendime yarattığım mükemmel bir sanal dünyadayım

Her şeyi seviyorumla

Daha nekadar kandırılmalardayım

Bu yeni dünyamda kaç yaşındayım

Devamı nekadar mı? ..Bilmiyorum ki

Kim izin verdiyse bu sanal aleme

Niyeyse bu yarattığım Hayal

Dokunmayın

İzin bitene kadar Mükemmellerdeyim...', 'Aklımda  Bir sürü Güzel düşünce var Hep iyiye çok yakın Sevgiye çok yakın Hani yaşamla birlikteyim Sevgi içimde saf ve net bir duygu Mevsiml...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sanal-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerime Haram Uykular', 'gozlerime-haram-uykular-i-lknur-er-bbxb7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerime haram uykular

Ellerim buz tuttu sensiz

Saatlerin geçmesine isyanım var çok zamandır

Ve hasret şarkılarını söylemesine benden başkasının

Acılar bana dair

Sensizliği düşünmeyi reddediyor beynim

Kalbimse durdu sen gittiğin an 

Kimbilir nerelerdesin şimdi

Neler yapıyorsun bensiz mutlumusun

Sende gözlerini kapatıyormusun içine düştüğüm an

Ahh kalbimin gücü olsada kalksam 

Gelsem kapılarına

Yarım yamalak ömrümü harcasam yollarında

06.02.06', 'Gözlerime haram uykular Ellerim buz tuttu sensiz Saatlerin geçmesine isyanım var çok zamandır Ve hasret şarkılarını söylemesine benden başka...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozlerime-haram-uykular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu ne leylidir te', 'bu-ne-leylidir-te-ali-riza-unal-jb37g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne şarışın ne esmer,nede humraldan edâsı,

Bir suzî dil sedâdır,ruh-i revandır devası,

Zülfe hicaptır na ehil müşrik,tende bu cana,

Sun ey saki lebbi,visâli tiryakidir müptelâsı,

Batını ayan gönüle,zahiri leylâdır siması,

Neylesin gafil ahir-i narı,bundadır belası,

Ne sırrı ilâhiki,cismin perdedir  bu cana,

Sun  ey baki,bu goncadır vaslın sefası..

--     nakarat    --

Bu ne leylidir te,te leyli,te leyli,te leyli Ha,

Bu ne leylidir te,te leyli,te leyli,te leyli Ha,', 'Ne şarışın ne esmer,nede humraldan edâsı, Bir suzî dil sedâdır,ruh-i revandır devası, Zülfe hicaptır na ehil müşrik,tende bu cana, Sun ey sa...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bu-ne-leylidir-te-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimde Siyah Bir Şal Kalıyor Ardından', 'elimde-siyah-bir-sal-kaliyor-ardindan-gul-yazganarikan-xvwm7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Solgun akşamların ayazında 

Kalabalık şehrin en kalabalığında

Yalnızım ben...

Üstüme üstüme geliyor yaşam

Çığlık çığlığa bağırıyor gök kubbe

Ve yer kayıyor ayaklarımın altından...

Yaşanmıyor kahrolası akşamlar,

Koyulaşan gecenin karanlığında

Onca açtığın yara kabuk bağladığında

Unutuyorum ettiğin kötülükleri

 yüreğime açtığın oyuklardan

sessizce giriyorum içeri...

derinlere en derinlere iniyorum....

öyle karanlık öyle ürkütücü bir sessizlik 

dönülmesi zor bir sensizlikte 

kayboluyorum...

örümcek ağları sarkıyor bir yandan

bir yanda buzul çağını hatırlatan 

sarkıtlar tutunmuş damarlarıma

donmuş kalmış göz yaşlarım, 

kendi ayazında....

bir ateş yakıyorum gözlerinden

sönüyorlar az sonra...

unutmuşum rengini gözlerinin,

bir ateş daha yakıyorum öpüşlerinden

biraz olsun ısınıyorum...

az sonra sönüyor, üşüyorum işte yine

son bir ateş daha yakıyorum ihanetlerinden, yalanlarından

alevler sarıyor, boyunu aşar görsen, boyumu aşıyor

alevler 

koyu bir grilik kaplıyor sonra ansızın, boğucu bir kara duman

siyah bir şal gibi sarıyor yokluğun 

ağlayamıyorum....

Sessizce çıkıyorum yüreğime açtığın oyuklardan

Sessizliğinde gecenin

Sessizce boğuluyorum...

Elimde siyah bir şal kalıyor ardından...

Uyanıyorum...', 'Solgun akşamların ayazında  Kalabalık şehrin en kalabalığında Yalnızım ben... Üstüme üstüme geliyor yaşam Çığlık çığlığa bağırıyor gök kubbe...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/elimde-siyah-bir-sal-kaliyor-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkısı...', 'askisi-i-brahim-ethem-bingul-adnk0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Donarken şubat güneşinde bedenim

Cehennem ateşinde Cenneti yaşadı yüreğim

Dakikalara ömürlük mutluluk sığarmış meğer

Gönlüme kattıklarından sevda saçar gözlerim...

Bakışına gizlediğin sevginden yanarım

Ya biterse bir gün diye kanarım

Her saniye günlere katlanır çağlarım

Ne saadet ki aşkımın gıdasıyla yaşarım...

Yüreğimde değilsin sadece

Aşkısın, Aşksın hücrelerimde bile

Bir görebilsen sende gel bak

Gönül gözünle bendeki kendine...

www.iebingul.com', 'Donarken şubat güneşinde bedenim Cehennem ateşinde Cenneti yaşadı yüreğim Dakikalara ömürlük mutluluk sığarmış meğer Gönlüme kattıklarından ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askisi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinaslı Mani lV', 'cinasli-mani-lv-latif-oz-pserw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yara derin

Kızıl gülden yara derin

O yar bana zulüm eder

Yürekteki yara derin', 'Yara derin Kızıl gülden yara derin O yar bana zulüm eder Yürekteki yara derin...', ARRAY['Türk Edebiyatı','Şiir','Latif Öz']::text[], 8.5, '{"poet":"Latif Öz","poet_slug":"latif-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cinasli-mani-lv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinaslı Hoyratlar - 3 –', 'cinasli-hoyratlar-3-esat-erbil-s9lui', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kale sen 

Erbil''e tek Kale sen

Etrafiw qaçırtma dost

Sora yalğuz kalasan.

***

Kan göziwi

Al edip kan göziwi

Gel dostum düz bir yola 

Tutmasın kan göziwi.

***

Alma yandı 

Ağaçta alma yandı 

Meni ucuz satan dost

Derdimde almayandı.

***

Onay sizden 

Armağan o, Nay sizden

İstirem dewrim yapım

Beklirem onay sizden.

***

Dil açmasın

Bağlıdı dil açmasın

Çox dertleri uturam 

Karğalar dil açmasın.

***

Ezerem

Tanışmadım az aram

Ataların sözü iyden

Yad başını ezerem.

***

Qalmıyağ

Bir gün gelir qalmıyağ

Eskiden ibret alağ 

Yanlış yolda qalmıyağ.

***

Tam eli 

Tutmamışam tam eli

Yapıda qatılmırsaw? 

Barığ yıxma temeli.

***

Tam elden 

Elim çektim tam elden

Yad eli bina yapsa 

Çuruk olur temelden.

***

Ezan werir

Nemazdı ezan werir

Arif olmayan kimse 

Qabaqta ezan werir.', 'Kale sen  Erbil''e tek Kale sen Etrafiw qaçırtma dost Sora yalğuz kalasan. *** Kan göziwi Al edip kan göziwi Gel dostum düz bir yola  Tutması...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/cinasli-hoyratlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Yazsam Dedim', 'bir-siir-yazsam-dedim-murat-isik-xdm3c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazsam dedim. 

Anlatsam zifir karanlığımı.

Harflere,kelimelere dizsem,

Aktarsam yalnızlığımı.

Ve yanıp kavrulsam 

En mahrem hayallerde. 

Üşüyüp titresem 

Çıplak tepelerinde.

Eriyip kaybolsam 

Islak cehenneminde.

Bir ritim tuttursam 

Bir harmoni bir kafiye 

Bir şiir yazsam dedim 

Anlatsam sana....', 'Bir şiir yazsam dedim.  Anlatsam zifir karanlığımı. Harflere,kelimelere dizsem, Aktarsam yalnızlığımı. Ve yanıp kavrulsam  En mahrem hayalle...', ARRAY['Türk Edebiyatı','Şiir','Murat Işık']::text[], 8.5, '{"poet":"Murat Işık","poet_slug":"murat-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-siir-yazsam-dedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinaslı Hoyratlar - 4 –', 'cinasli-hoyratlar-4-esat-erbil-lrict', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Olmasan 

Saat aldıw olma sen

Alam hepsi yanlışsa 

Sende doğru olmasan.

***

Dil açar

Dinç olusan dile çar

Pis terde xarabada

Qarğa, Bayğuş dil açar.

***

Red werex

Qonağ gelin red werex

Bizlerde adet değil

Aqlı keme red werex.

***

Onda men 

Dokuz aldım onda men

Hizmet eyle Millete

Sen bir ayım onda men.

***

Bu yerden

Sepilipti bu yer den

Millet mene bil olsa 

Hizmet edim bu yerden.

***

Bir ax çeksem

Derdim çox bir ax çeksem

Yandırram dostu yadı 

Urekten bir ax çeksem.

***

Onda birin

Sewmişem onda birin

Dost işi yarı qoysa 

Sende gel yap onda birin.

***

Uyan dostum

Gel gezex oyan dostum

Öox şeyımız qayp ettix

Bes gaflet uyan dostum.

***

Her kese

Dudağ wurma her kese

Millete xayın olan

Xayın olur her kese.

***

Bağışlar 

Ekinciler bağ işler

Xalqını sewen kimse 

Öz cebinden bağışlar.', 'Olmasan  Saat aldıw olma sen Alam hepsi yanlışsa  Sende doğru olmasan. *** Dil açar Dinç olusan dile çar Pis terde xarabada Qarğa, Bayğuş di...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/cinasli-hoyratlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişmediğim Gün Ölürüm', 'sevismedigim-gun-olurum-mehmet-zeki-gezici-wrozb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yolcuyum Ademden  önce

elini istiyorum

seni cennetime götürmek için.

Ateşim var kızılcıktan

yüreğini istiyorum

içine koymak için yaşama sevincini.

Şairim ışığın renginde

düşlerini istiyorum

özgürlüğe çifte su vermek için dört yanından.

Akan bir suyum

gökyüzünün yıldızlarından

gözlerini istiyorum aydınlatmak için yıldızları.

Usta br marangozum

parmaklarını istiyorum

kendime yeni bir kader çizmek için.

Bedenin bahar toprağı

bedenini istiyorum

yeni bir can yaratmak için.

Yorgunum

saçlarını istiyorum

karanlığında uyumak için.

Ben sevişmediğim gün ölürüm.', 'Yolcuyum Ademden  önce elini istiyorum seni cennetime götürmek için. Ateşim var kızılcıktan yüreğini istiyorum içine koymak için yaşama sevi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevismedigim-gun-olurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinmelimi Bu Tutsaklığa', 'sevinmelimi-bu-tutsakliga-murat-isik-uyqq6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevinmelimi bu tutsaklığa 

Haftada bilmem kaç görüş günü 

Kısa izinlerle 

Dalmak için gözlerine, 

Yasak olsada dokunmak 

Engel çoksada koklamaya 

Kısa izinlere biraz voltaya 

Sevinmelimi bu tutsaklığa 

Vakit tamam dendiğinde 

Mahkum olsamda zindana 

Işıksız katıksız dolunaysız 

Sevinmelimiyim kör karanlığa 

Seni gönderirken hoyrat kollara', 'Sevinmelimi bu tutsaklığa  Haftada bilmem kaç görüş günü  Kısa izinlerle  Dalmak için gözlerine,  Yasak olsada dokunmak  Engel çoksada kokla...', ARRAY['Türk Edebiyatı','Şiir','Murat Işık']::text[], 8.5, '{"poet":"Murat Işık","poet_slug":"murat-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevinmelimi-bu-tutsakliga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değersiz Dünya', 'degersiz-dunya-esat-erbil-fr8zf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz gelmedik dert çekmeye,

Eğlenceli hoş dünyada,

Rakı, şerap zehr içmeye,

Bu değersiz boş dünya''da.

Sokulmayız köşk seraya,

Toplanalım bir araya,

Aldanmayız pis paraya, 

Bu değersiz boş dünya''da.

Yalvarcıyım tek Huda''ya,

Düşmiyelim çöl ada''ya,

Barı düşün pek sevdaya,

Bu değersiz boş dünya''da.

Küstü yürak bağladılar,

Hiç bilmeden dağladılar,

Gör erenler ağladılar,

Bu değersiz boş dünya''da.

Elden gelse kurtar kendin,

Mutluluğun anla fendin,

Yaşam zordur çözün pendin,

Bu değersiz boş dünya''da.

Aşkı bilmez içi püçtür,

İçi püçse kötü içtir,

yalan aşkın sonu hiçtir,

Bu değersiz boş dünyada.

Söyler (Esat)  bilmiyene,

Göz yaşını silmiyene,

Dava için ölmiyene,

Bu değersiz boş dünyada.

Gel cevherin vurma taşa,

Huzurlusun düşme şaşa,

Hep çileler geldi başa,

Bu değersiz boş dünyada.', 'Biz gelmedik dert çekmeye, Eğlenceli hoş dünyada, Rakı, şerap zehr içmeye, Bu değersiz boş dünya''da. Sokulmayız köşk seraya, Toplanalım bir ...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/degersiz-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülmeyene!', 'gulmeyene-esat-erbil-782lo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşam okul biz öğrenci,

Yazık ibret almayana,

Yürek dolar bitmez sancı,

İçin için gülmeyene.

Yar gözlerin ne aladır,

Boyun yüksek ne kaledir,

Anlamazdır budaladır,

Bu dünya''yı bilmiyene.

Gelir gider yapar cadı,

Yaşam nedir bilmez tadı,

Vefasızdır onun adı,

Dosta sadık olmayana.

Dostlar iyi kimi yaman,

Vefasızdır inan zaman,

Biz oluruz ona aman,

Huzurunu bulmuyana.

Çok yaralı dost buluruz,

Derdine çare oluruz,

Öksüzlere gah ölürüz,

Göz yaşını silmiyene.

Gül bahçada bir gün solur,

Siyah saça ağlar dolur,

Ekmek yese haram olur,

Adaletle bölmiyene.

Aran bular sora sora,

Can kurbandı doğru yara,

Cift sözüm var gelsin bura,

Yar yanında kalmıyana.

Tatlı yaşa aman olur,

Yaş bitiren zaman olur,

En sonunda pişman olur,

Doğru yola gelmeyene.

Yaşam bilsen olur düğün,

Çözülecek zorlu düğün,

Başarsıza uğrar bir gün,

Durust işe dalmıyana.', 'Yaşam okul biz öğrenci, Yazık ibret almayana, Yürek dolar bitmez sancı, İçin için gülmeyene. Yar gözlerin ne aladır, Boyun yüksek ne kaledir...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gulmeyene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Işık', 'mavi-isik-murat-isik-v2u4k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mavi derinliklerden yansıyan 

Bir ışık hüzmesi gibi

İnebilsem derinliklerine,

Boğulmadan.

Atabilsem tenimi 

Serinliklerine

Yanıp kül olmadan

Ve daha çoğalabilsem...', 'Mavi derinliklerden yansıyan  Bir ışık hüzmesi gibi İnebilsem derinliklerine, Boğulmadan. Atabilsem tenimi  Serinliklerine Yanıp kül olmadan...', ARRAY['Türk Edebiyatı','Şiir','Murat Işık']::text[], 8.5, '{"poet":"Murat Işık","poet_slug":"murat-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mavi-isik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İPTEKİ MANDAL / Hayat Hikâyesi', 'i-pteki-mandal-hayat-hik-yesi-tulay-sustam-gq0mi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman kendimi çaresiz, yalnız, savunmasız ve darağacında hissetsem beni hayata bağlayan mandaldın sen… 

Sımsıkı tutardın ellerimi, yanında kendimi güvende hissederdim. Seninle daha çok gülerdim, daha az ağlardım. Deniz seninle mavi, orman seninle daha yeşildi. Ne zaman evin bahçesinde oyun oynasak, kumdan kaleler yapıp seni içine saklardım. Kimse seni benden almasın diye. Seni kaybetmekten korkardım. 

Evin ilk göz ağrısı, ilk çocuğu olduğumdan ilkleri ben yaşadım, sonları sen… Sen benim çocukluğumun bez bebeğiydin. Ne zaman; avuç içimden minik ellerin kayıp gitse, ellerimde bir parmağım kalır sanırdım. Çocukluk aklı işte… 

Bana kırmızı ayakkabı alınsa, sana beyaz alınırdı. Eşyalarımız birbirine karışsa iki kardeş, iki düşman kesilirdik. Birbirimizleydi en büyük kavgamız. Sen bir şeye beyaz demişsen ben inadına siyah derdim. Benim olan her şey benimdi, senin olan her şey yine benim… Bütün kavgalar da hep bunlardan çıkardı ya… 

Ben senin asi yanındım, sen benim ağırbaşlılığım… Bütün olaylar da sen suçlu olurdun, bense hep haklı. Her taşın altından sen çıkardın. Oysa; taş taş üstünde bırakmayan bendim. Kaç kez benim yüzümden annemden dayak yedin. Sen ağlamaya başladığında yaptığım her şey için pişman olurdum olmasına da iş işten geçmiş olurdu. Her şeye dayanırdım da bir  göz yaşına dayanamazdım. 

- Sen yere düşsen, benim dizlerim kanardı.- 

Her akşam yatmadan önce duâ ederken bütün ağaçların yapraklarının da Allah’a el açtığını düşünürdük. Bu bizim herkesten sakladığımız en büyük sırrımızdı. Çocukluk aklı işte… Seninle çocuk yaşta, ne kadar büyük düşünürdük… 

Gün geldi, toprağın koynuna bırakılmış iki tohum gibi kök saldık hayata… Biz büyüdükçe, hayat küçüldü gözümüzde. Her geçen gün el girdi aramıza, biz bize yabancı olduk. Ömür denen şey, bizi bizden aldı… Birbirimizle hiçbir eşyamızı paylaşmazken aşk uğruna, dost uğruna canımızı verir olduk. Oysa sen ve ben bir çatının altında biz bizeyken ne kadar mutluyduk. Anne ve babamızın yanından bir an bile ayrılmazken hayatın ortasında kavgamız uğruna kendimizi savaşırken bulduk… 

Hayat; beni bir dağın arkasında bırakırken, seni havasını, suyunu bilmediğim bir şehre rüzgâr gibi sürükledi. Benden uzaklaştığında, uçurum kenarında çiçek açmayı öğrendim. Bir başına dimdik ayakta durmanın zorluğunu da… “”Ellere karışmanın, dağlarla güreşmek”” olduğunu o zaman anladım. En önemlisi sensiz hayata kafa tutmayı öğrendim. 

Biz büyüdükçe, hayat küçüldü gözümüzde… Yollar uzadıkça sen gözümde BÜYÜDÜN, ben KÜÇÜLDÜM. Nerede olursan ol kardeşim! ... İçindeki küçük kızı öldürme… 

Ey Hayat! ... 

Bu saklambaç oyununu hiç sevmedim. Gözümden bile sakındığım bez bebeğimi bilmediğim bir şehrin sokağına sakladın. 

- Onsuz çıkmazdayım.- 

Ne zaman kendimi çaresiz, yalnız, savunmasız ve darağacında hissetsem beni hayata bağlayan mandaldın sen…', 'Ne zaman kendimi çaresiz, yalnız, savunmasız ve darağacında hissetsem beni hayata bağlayan mandaldın sen…  Sımsıkı tutardın ellerimi, yanınd...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ipteki-mandal-hayat-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Kıvamında', 'siir-kivaminda-murat-isik-hm05w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiir kıvamında dolu gözlerim 

Sızı yayılıyor pınarlarımdan 

Her şey hasret biçimi 

İsyanım sessiz hücremden 

Yokluğun yakıyor içimi 

Boğazım kuru sesim titrek 

Ağır bir cürüm işledim bilerek 

Cezam kesildi..MÜEBBET 

Kendi parmaklıklarımda mahkumum 

Yerler dikenli kor,

Yollar labirent 

Şiir biçiminde ızdırap sonsuz 

Bir tek kalemim tutuksuz 

Bir sessizlikte hürüm 

Şiir kıvamında özgürlük 

Ve bir şiir boyunda', 'Şiir kıvamında dolu gözlerim  Sızı yayılıyor pınarlarımdan  Her şey hasret biçimi  İsyanım sessiz hücremden  Yokluğun yakıyor içimi  Boğazım...', ARRAY['Türk Edebiyatı','Şiir','Murat Işık']::text[], 8.5, '{"poet":"Murat Işık","poet_slug":"murat-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siir-kivaminda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinyal gönder', 'sinyal-gonder-mete-yildiz-xg1rk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SİNYAL GÖNDER

Sinemdedir hala okun,

Ne olur bir sinyal gönder

Arıyorum nerde kokun

Ne olur bir sinyal gönder

Diz üstüne çökerim ben

Kanlı yaşlar dökerim ben

Kefen giysem sökerim ben

Ne olur bir sinyal gönder

Ne tadım var nede tuzum

Dinmez içimdeki sızın

Yaşamaya kararsızım

Ne olur bir sinyal gönder

Unutayım unutamam

Takatim yok iş tutamam

Bir lokmacık aş yutamam

Ne olur bir sinyal gönder

İsyan ettim günahkârım

Ben bir sana tamahkârım

Kurban olam nazlı yarım

Ne olur bir sinyal gönder

Hani senin asil yanın

Kalmadı mı hiç vicdanın

Kessen akmaz damla kanım

Ne olur bir sinyal gönder

Kalbe kabul kıldırırım

Görenleri yıldırırım

Bu gidişle çıldırırım

Ne olur bir sinyal gönder

Eriyorum erim erim

Kalmadı gözümde ferim

Görüyordur Allah kerim

Ne olur bir sinyal gönder

Yolarına çıkacağım

Gönülleri yıkacağım

Bak beynime sıkacağım

Ne olur bir sinyal gönder

Yok, oldu o bildiğin dev

Yanıyorum alev alev

Seveceksen gel şimdi sev

Ne olur bir sinyal gönder

Suya düşmüş söğüt dalı

Aramızda karaçalı

Aslıyla Kerem misali

Ne olur bir sinyal gönder

Güneşsizim, ışıksızım

Ağlıyorum sızım sızım

Ne talihsiz bir Yıldızım

Ne olur bir sinyal gönder', 'SİNYAL GÖNDER Sinemdedir hala okun, Ne olur bir sinyal gönder Arıyorum nerde kokun Ne olur bir sinyal gönder Diz üstüne çökerim ben Kanlı ya...', ARRAY['Türk Edebiyatı','Şiir','Mete Yıldız']::text[], 8.5, '{"poet":"Mete Yıldız","poet_slug":"mete-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sinyal-gonder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçlikte Bir Heplikte', 'hiclikte-bir-heplikte-murat-isik-pj4gc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ya kör bir karanlık

Yada gözleri kör eden parlak bir ışık içindeyim

Her durumda görmüyor gözlerim

Her durumda aranıyorum bütün duyularımla

Ya ölüm sessizliği oluyorsun

Ya sağır eden bir çığlık kulaklarımda

Kendi içimde yankılanıyorum

Duymuyorum.

Ya acı oluyorsun yanan boğazımda 

Yada içimi kavuracak kadar tatlı

Bir yudum suya hasret

Yutkunamıyorum

Ya yüreğime yapışıp kalan ayaz bir demir

Ya hiç küllenmeyecek kor kor kömür oluyorsun dünyamda

Her şey yanıyor gözüm önünde

Sönmüyorum.

Kendi küllerimi soluyorum ciğerlerime

Nefesim kendi dumanım

Zehir doluyum ama ÖLMÜYORUM

Bazen herşey oluyorum dünyada 

Bazen hiç bir şey', 'Ya kör bir karanlık Yada gözleri kör eden parlak bir ışık içindeyim Her durumda görmüyor gözlerim Her durumda aranıyorum bütün duyularımla Y...', ARRAY['Türk Edebiyatı','Şiir','Murat Işık']::text[], 8.5, '{"poet":"Murat Işık","poet_slug":"murat-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hiclikte-bir-heplikte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaaf...', 'zaaf-muharrem-cetinkaya-jbqwy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir fil sığar mı demeyin

İğnenin deliğinden

Gönülde bırakmayın iğne deliği

Şeytan giriverir kendiliğinden.

Bir fili yıkar mı küçücük iğne demeyin

Zaaf bırakmayın gönülde

Şeytan giriverir iğne deliğinden

Unutmayın; 

Zaaflarımızda gizlidir şeytan

Açık bırakmayın kapıyı

Giriverir kendiliğinden!', 'Bir fil sığar mı demeyin İğnenin deliğinden Gönülde bırakmayın iğne deliği Şeytan giriverir kendiliğinden. Bir fili yıkar mı küçücük iğne de...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zaaf-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibi', 'gibi-mete-yildiz-dlq5x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GİBİ 

Buluşalım yedi gibi 

Senin kokun eter gibi 

Seviyorum dedi gibi 

Sanki daha beter gibi 

Yirmi iki yaşı gibi 

İnce kalem kaşı gibi 

Bir göz attı şaşı gibi 

Hani canı çeker gibi 

Bana ilgi taşır gibi 

Şaşmış başın kaşır gibi 

Sanki vedalaşır gibi 

Yere düştü yeker gibi 

Boyun bükmüş sümbül gibi 

İnce teni bir tül gibi 

O gül bende bülbül gibi 

Gül tohumu eker gibi 

Ümit verir coşturursun 

Hep peşinde koşturursun 

Yeşil dalda hoş durursun 

Ala keklik seker gibi 

Güzellerle akışırsın 

Kıskanırlar takışırsın 

Sen tam bana yakışırsın 

Çöle fidan diker gibi. 

Sevgi ile bakışırız

Hep birlikte akışırız

Biz ne güzel yakışırız

Ben çay sende şeker gibi.

Mete YILDIZ', 'GİBİ  Buluşalım yedi gibi  Senin kokun eter gibi  Seviyorum dedi gibi  Sanki daha beter gibi  Yirmi iki yaşı gibi  İnce kalem kaşı gibi  Bir...', ARRAY['Türk Edebiyatı','Şiir','Mete Yıldız']::text[], 8.5, '{"poet":"Mete Yıldız","poet_slug":"mete-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gibi-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikanlım tuzağa düşersen yazık olur', 'delikanlim-tuzaga-dusersen-yazik-olur-mikdat-bal-qk9to', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Delikanlım tuzağa düşersen yazık olur

Dünya kamuoyunu aleyhte kurmaktadır

Biliyorum bu günler yüreğin ezik olur

Kanın kaynıyor, kalbin nerdeyse durmaktadır

Haçlıdan müteşekkil bir ordu kurmak için

Yakında Amerika İranı vurmak için

Bunun da hesabını bizlerden sormak için

Etrafı bulandırıp, kafanı yormaktadır

Karikatör yapmışlar, bir şey yazıp çizmişler

Kahrolası zalimler bunda bir rant sezmişler

Kafalarına göre müslümanı üzmüşler

Bir hadiste peygamber bak ne buyurmaktadır

Görürseniz basınız benim resmimi eğer

Benim resmim olamaz ona vermeyin değer

Bunların elinde ki karikatörmüş meğer

Bununla cahilleri, işleyip kurmaktadır

Aman dikkatli olun, muhattap almayınız

Zalimlerin elinde oyuncak olmayınız

Körü körüne çıkıp sokağa dolmayınız

Sizin en hayırlınız evde oturmaktadır

Mikdat derki uyanın oyunlara düşmeyin

Mü’min vekarlı olur hudutları aşmayın

Bu kurulmuş bir tuzak, doğru yolda şaşmayın

Taşkınlık aleyhtedir hüsrana varmaktadır', 'Delikanlım tuzağa düşersen yazık olur Dünya kamuoyunu aleyhte kurmaktadır Biliyorum bu günler yüreğin ezik olur Kanın kaynıyor, kalbin nerde...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/delikanlim-tuzaga-dusersen-yazik-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Biliyordum ki..', 've-biliyordum-ki-zeliha-bicer-npnkw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabah uyandım,

Gün ışığı pencereme vuruyordu

Rüzgarın esintisi duyuluyordu.

Gökyüzüne baktım 

Gri beyaz bulutlarla bezenmişti

Seni düşündüm. 

Gittiğin gün de yine gri beyaz bulutlar vardı

Rüzgar esiyordu,deniz hırçındı

Sevgim gibi

Bencildim belki 

Hep kal istedim yanımda

Dilime gelen onca kelimelerden

Birini söyleyemedim.

-Gitme- demelerim vardı

-Gitme- demenin tüm çeşitlerini ezberledim

Söylemek için

Belki gitmezdin o zaman 

Diyemedim ama..

Biliyordum ki gitmen gerek

Biliyordum ki bensiz kalmak

Benim sensiz kalmamdan daha acı

Ve biliyordum ki

Seviyorsun beni...', 'Sabah uyandım, Gün ışığı pencereme vuruyordu Rüzgarın esintisi duyuluyordu. Gökyüzüne baktım  Gri beyaz bulutlarla bezenmişti Seni düşündüm....', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ve-biliyordum-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 51', 'guncel-beyitler-51-huseyin-avdic-s3ve1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayat 2

Kâinatin en kiymetli ve en mükemmel bir meyvesidir hayat.

Bu meyveyle beslenenler, yapmalidir Rabb''e binler te$ekkürat.

Berlin. $ubat 2006.', 'Hayat 2 Kâinatin en kiymetli ve en mükemmel bir meyvesidir hayat. Bu meyveyle beslenenler, yapmalidir Rabb''e binler te$ekkürat. Berlin. $uba...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonunda yaratana da yazdım derdimi arzuhalimi', 'sonunda-yaratana-da-yazdim-derdimi-arzuhalimi-halil-colak-94iqu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arı çiçekle de anlaşarak yaptı kovanda balını

Ben ise kimseye anlatamadım dostum halimi

Şimdiye kadar da almadım kimsenin vebalini

Sonunda yaratana da yazdım derdimi arzuhalimi

Halil Çolak  6.2.2006 Ankara', 'Arı çiçekle de anlaşarak yaptı kovanda balını Ben ise kimseye anlatamadım dostum halimi Şimdiye kadar da almadım kimsenin vebalini Sonunda y...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sonunda-yaratana-da-yazdim-derdimi-arzuhalimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Üniversite Hikayesi', 'bir-universite-hikayesi-muharrem-karaman-wqufn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her şey bir kelimede saklıydı, ve sadece seni seviyorum diyebilmekti. Ardından gözlerine bakarak kalbini görebilmekti. Böyle düşlemiştim sana olan aşkını anlatmayı, katıksız, yalansız gözlerine bakarak her şeyi söylemeyi ve seni senden istemeyi böyle istemiştim....

Sen ise hep aşkını bir roman gibi, hikaye gibi ve bir aşk sineması gibi, anlatırdın. Beni öyle büyülerdin ki, ayrılamazdım senden. Her an yanında her an başucunda olmak isterdim. Yani seni kendi canımdan öte severdim.  Hep böyle devam etmesini isterdim ta ki benimle ölene kadar….Ama öyle olmadı aylar, yılalar geldi geçti derken, okul bitti.

Ve ben şimdi sana yazıyorum bunları, belki olurda bir gün okursun diye belki unutmazsın seversin diye…..

Hani hatırlar mısın, sabah uyandığımızda  bembeyaz, aniden karşıladık karı. Ve o gün otobüse binmemiştik, yürüyerek gittik okula. Ve çok üşümüştük, kantinde sırtımızı dayadığımız kalorifer bile ısıtmıyordu bizi, çünkü içimizdeki sevgiydi bizi titreten, bizi üşüten ve bir bardak çaydı, içimizi ısıtan. O çayın tadı bile farklıydı çünkü yanımda sen vardın…..

Şu anda sen yoksun yanımda İzmir güzeli içtiğim çayın tadı bile yok….

Farklıydı o zamanlar, her şeyin bir tadı bir tuzu vardı. Yani sevgimiz vardı.Şimdilerde durgunum, yorgunum biraz da sessizim.

Her şeyi yazmak isterdim ama yüreğimi bağlıyorum ve seni çok özlüyorum İzmir kızı…..

İçimdeki ince sızı…..', 'Her şey bir kelimede saklıydı, ve sadece seni seviyorum diyebilmekti. Ardından gözlerine bakarak kalbini görebilmekti. Böyle düşlemiştim san...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Karaman']::text[], 8.5, '{"poet":"Muharrem Karaman","poet_slug":"muharrem-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-universite-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde', 'nerde-yasemin-birbudak-icozz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nerede şimdi o sıcacık eller                                                     

Bakmaya doyamadığım                                                           

Deniz mavisi gözler                                                        

                                                                                                 

O olmazsa ne yapardım derken                                               

Kaybettim  bir tanemi                                                                

                                                                                                    

                                       

Ne olur uyuma

Aç gözlerini yumma                                                 

Arasam  yıllarca	

İmkansız  daha                                                                  

Bulamam senin gibi  dostu                                               

                                                                                               

Ne yapacağım şimdi  sensiz                                             

Kime dert yanacağım çaresiz 

Üşüdüğüm zaman ellerimi kim ısıtacak

Üzüldüğüm an benimle kim ağlayacak

Seni seviyorum dostum diye

Kim haykıracak

Kemiklerimi kırarcasına 

Kim  sarılacak

Söyle  bu kalp sensiz nasıl yaşayacak

Sensiz olmaz yaşanmaz

Hayattan zevk alınmaz

Sensizliğe  can inan dayanmaz

Engel olamıyorum 

Kirpiklerimden süzülen yaşlara

Dayanamıyor yüreğim yokluğuna

Son gördüğümde onu 

Öylece uzanmış melek gibi uyuyordu

Yalnız o deniz mavisi gözleri donuktu

Sıcacık elleri ise soğuktu

Tanrım bu benim dostum muydu

Can yoldaşım

Nasıl yenik düşerdi ölüme

Kalkmalı uyanmalı

Sıcacık bakışları yüreğimi ısıtmalı

Teslim olmamalı AZRAİLE

Çabalarım boş yere bir tanem şimdi cennette

Görüyor gibiyim tebessüm edişini

Bense hasretim deniz gözlüme

Burada bırakmalı hüznün güneşini

Yol almalı ölümsüz dostluğumuzun şerefine

Beraber yaşanan ölümlere

Kapıları zorla aç dostum sozsuza

Kapılma yalnızlık duygusuna

Anlam kalmadı yaşamımda

Ölümsüz sevgimizin adına

Geliyorum yanına

Bas beni bağrına

Elveda dünyaya

Merhaba dostuma...', 'Nerede şimdi o sıcacık eller                                                      Bakmaya doyamadığım                                       ...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Birbudak']::text[], 8.5, '{"poet":"Yasemin Birbudak","poet_slug":"yasemin-birbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/nerde-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal Diyemem', 'kal-diyemem-salim-erben-im8jo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlama bir tanem boynu bükük 

Gitme vedalaşıp el öpüp 

Bunca yıl tatlı dil döküp 

Sarılıp boynuma ağlatma beni 

İçim kan ağlıyor dışarı akmaz 

Sen gidersen eğer kimse bakmaz 

Gözlerim yaşlı kirpik bırakmaz 

Şu yarama merhem ol diyemem 

Dalım kolum sendin bir bilsen 

Dökülen damlaları oturup silsen 

Arada bir olsun gelsen görsem 

Telinle duvağınla kal diyemem 

Zalım dır dağlar bende aşamam 

Çocuklar gibi peşinden koşamam 

İpek saçlarını bir daha okşamam 

Canım benim sana kal diyemem 

Bu şiiri kızım esraya yazdım

Salim ERBEN (Zalım)', 'Ağlama bir tanem boynu bükük  Gitme vedalaşıp el öpüp  Bunca yıl tatlı dil döküp  Sarılıp boynuma ağlatma beni  İçim kan ağlıyor dışarı akma...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kal-diyemem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylemedim Sana', 'soylemedim-sana-salim-erben-lmne3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saçım ağardı belim büküldü

 Dağların başında yüreğim söküldü

 Gözyaşlarım bir tek sana döküldü

 Gözyaşıma bent olursun diye

 Yosun tutar ağaçlar nasırlı elleri

 Göğsünde açılan gonca gülleri

 Dudakta hapis olan cümleler

 Anlatamadım dinlemezsin diye

 Gece zindan derede kaldım

 Kulakların çınlasın seni andım

 Alın terime ekmeği bandım

 Söylemedim sana yemezsin diye

 Zalım oldu gece yok ay ışığı

 Severim canı gönülden hak aşığı

 Gözümün nuru kalbimin ışığı

 Söylemedim sana sönersin diye', 'Saçım ağardı belim büküldü  Dağların başında yüreğim söküldü  Gözyaşlarım bir tek sana döküldü  Gözyaşıma bent olursun diye  Yosun tutar ağa...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soylemedim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '&&& Sevmeye Yeminli Yüreğim &&&', 'sevmeye-yeminli-yuregim-i-brahim-dikmen-2-4hanz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gittin ya

Yas tuttu yüreğim

Gözlerime inmeler çöktü

Görmez oldum

Karabasanlar kuşattı

Sensiz düşlerimi

Uykuya hasret kaldım

Bilmem kaç gecedir

Şehir karanlığa gömüldü

Anladım ki gözlerinmiş

Dünyamı aydınlatan

Bilsen şimdi ne haldeyim

Bilsen ki tarumar olmuş

Aşka küskün yüreğim

Sen gittin ya

Kalem tutmaz oldu ellerim

Parmaklarıma çöktü inmeler

Yazamaz oldum

Umutsuz düşünceler sardı

Sensiz mısraları

Şiirlere küstü yüreğim

Anladım ki senmişsin

Bana şiirler yazdıran

Bilsen şimdi ne haldeyim

Bilsen ki naçar kaldı

Sen gittin ya

Damarlarımdan çekildi kan

Yüreğimi sardı inmeler

Hayat durdu sanki

Ay tutuldu geceleri

Yıldızlar küstü sanki

Bilsen şimdi ne haldeyim

Bilsen ki feryad eyler

Sevmeye yeminli yüreğim

Sevmeye yeminli yüreğim

06/02/2006

Gidenlerin ardından.......', 'Sen gittin ya Yas tuttu yüreğim Gözlerime inmeler çöktü Görmez oldum Karabasanlar kuşattı Sensiz düşlerimi Uykuya hasret kaldım Bilmem kaç g...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sevmeye-yeminli-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Dedim', 'ask-dedim-mehmet-zeki-gezici-9ps78', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hangi yola girsem topraktı ekinsiz

ölümle kırdım bademle yaşadım  herşeyi.

Geldin uzanıp kayalıklara

dedin ki ''nasıl boyanıyorsa

zamanla herşey kendi rengine,

öyle olacağım işte çaresiz

sen dezamanla döneceksin kendine.''

Ben seni öperken sosuz

sonsuzu öperken

saçlarında uyuyordu zaman

bak seninle büyüdü kuşlarım

sularım seninle duruldu.

Sana aşk dedim ey ölümsüz.', 'Hangi yola girsem topraktı ekinsiz ölümle kırdım bademle yaşadım  herşeyi. Geldin uzanıp kayalıklara dedin ki ''nasıl boyanıyorsa zamanla her...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-dedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asayış No Berkemal', 'asayis-no-berkemal-murat-demir-ry1io', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kime sorsam diyor ki ummet değil bu millet

Nedir peki olanlar nerdedir cumhuriyet

Ne yasayı takan var, ne mağdura bakan var

Asayış no berkemal, mahküm olmuş hürriyet

Vatanı savunanlar orda burda ölürken

Hırsızlar çalar çırpar edep haysiyet derken

Hukuk hukuksuzların elinde şey şey olmuş

Neye yarar bilinmez bu kadar kanun varken

Herkes kendi deminde, ya sağcı, ya da  solcu

Her iki tarafada göz kırpan aynı kolcu

Şu güzelim vatanda, nizamı intizamı

Paramparça edenler, peki kimdir bölücü

Bizi bu hale getiren size, aferin beyler aferin

Cephede aç, susuz ölsede, ne önemi var neferin

Siz çalın, siz çaldıklarınızı yiyin tıkabasa

Sanmıyorsunuz ya solacağını birgün, gözlerinizde ki ferin', 'Kime sorsam diyor ki ummet değil bu millet Nedir peki olanlar nerdedir cumhuriyet Ne yasayı takan var, ne mağdura bakan var Asayış no berkem...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asayis-no-berkemal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirde Kışın Resmi', 'siirde-kisin-resmi-alper-kuruk-0srt5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kışın resmini çizdim şiirde

Kullandığım renkler hep soğuktu,

Yaprak yaprak sevgiler yerleştirdim ağaçlara

Sevgiler de donuktu.

Kışın resmini çizdim şiirde

Kullandığım renk hep karbeyazdı,

Aşkı yerleştirdiğim geceler

Birbirinden ayazdı.

Kışın resmini çizdim şiirde

Çizerken kâlbimi koydum ortaya,

Ateşinden eridi buzlar

Kış varsa kâlbim de var ya...', 'Kışın resmini çizdim şiirde Kullandığım renkler hep soğuktu, Yaprak yaprak sevgiler yerleştirdim ağaçlara Sevgiler de donuktu. Kışın resmini...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siirde-kisin-resmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Ülkesine Göç Ettik', 'deniz-ulkesine-goc-ettik-nurhan-gokturk-fh0y5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Orta Anadolu’nun bozkırlarında,

Hiç görmediğimiz denizlerin,

Hayallerine dalardık,

Sahiller, dalgalar ve martılar,

Serap gibi önümüzde yer alırdı,

Aşkımızı deniz hayalleriyle süslerdik,

Bir gün mutlaka gidecektik,

O sahillere, martıların şarkılarını dinleyecek,

Balıkçıların “heyemolaları" ile şenlenecektik.

Uzak ufuklara açılmış kırık kanatlar,

Ağma gözlere serilmiş efsunlu güzellikler,

Göç zamanı takılıp turnaların peşine,

Göç ettik…

Düşlerimizdeki sahillere,

Havası, suyu çaldı bizi 

Bozkır çocuklarını…

Kendi kurduğumuz düşlerin serabında,

Boğulduk…

Hangi durakta ineceğimizi bilmeden,

Bindik, 

Sen arka kapıdan, ben ön kapıdan

İndik.

Şimdi düşlerimizin sahilinde,

Martıların şen şarkılarını değil,

Ağıtlarını.

Dalgaların isyanını dinliyorum,

Sen nerde sin? 

Hiç ama hiç bilmiyorum.

Nurhan Göktürk

(21.01.2006/Antalya)', 'Orta Anadolu’nun bozkırlarında, Hiç görmediğimiz denizlerin, Hayallerine dalardık, Sahiller, dalgalar ve martılar, Serap gibi önümüzde yer a...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/deniz-ulkesine-goc-ettik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vahşi Medeniyet', 'vahsi-medeniyet-koksal-akar-nqeyh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ruh kalıbında esir, tene isyanda suret,

Uyku da neden hala fikir ve akıl; hayret! 

Neslini inkâr ile garba dönmüş hayali,

Yoktur cebriliğinin cihanda bir emsali! 

Utansın soysuz tarih, bu vahşi medeniyet; 

Utansın yüzsüzlüğün girdabında kemiyet…

Asım’ın nesli bile şimdi suskun ve yetim; 

Nasıl yaşıyorum der hala kemiğim, etim...

Dayan birazcık daha mahzun ve öksüz millet,

Bir gün bitecek elbet çektiğin bunca zillet.

Anlatabilmek ona; neyi, nasıl ve niçin…

Ancak kendisi olur koskocaman bir hiçin! 

Sonsuz bir bekleyişti asırlar süren uyku; 

Hangi kuvveti yenmez varlığındaki korku? 

Yeter ki dimdik dursun karşısında hür başın; 

Boğacaktır bu küfrü ağlasan da; gözyaşın! 

Kibrinin kıskacında perişan azgın fikir,

Haydi, bulandır akan suyu; temizlensin kir!', 'Ruh kalıbında esir, tene isyanda suret, Uyku da neden hala fikir ve akıl; hayret!  Neslini inkâr ile garba dönmüş hayali, Yoktur cebriliğini...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/vahsi-medeniyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altın Sevgisi', 'altin-sevgisi-mehmet-akif-tiryaki-g21y3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ahret altını iman ve amel-i salih

Altından geç budur mutlak selamet

Allah''ın mert kullarından başkası çocuk,

Nefsin arzularından vazgeçmeden yok olgunluk

Önce Allah sevgisi tad sonra evlen,

Allah''ın (c.c) huzurunda nefeslen.

Dünya da yedi şey sana sevdirildi,

Birincisi kadın sevgisi idi,

İkincisi evlat sevgisi dikkat,

Üçüncüsü altın sevgisi aman bırak,

Dördüncüsü gümüş sevgisi ah ah,

Beşincisi otluğa salınmış güzel atlar,

Altıncısı süt hayvanları verimli,

Yedincisi, ekin tarlası elbet ki.

Bunların her biri on bin perdedir,

Toplam eder yetmişbin epeydir,

Bütün perdeleri aşıp hakka gidelim,

Cemali ba kemale seyr idelim.

Asıl sevilecek kimdir bilelim,

Yağlı yemeklerimiz ahrette diyelim,

Bu yedi şeyden faydalanalım 

Ama asla sevgisini gönlümüze sokmayalım.

Huzuru mahşer den korkmayalım.', 'Ahret altını iman ve amel-i salih Altından geç budur mutlak selamet Allah''ın mert kullarından başkası çocuk, Nefsin arzularından vazgeçmeden...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/altin-sevgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşli Pazar Sokağı', 'gunesli-pazar-sokagi-cevdet-solak-3frwo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşli pazar sokağı ve güneşli gün

Patates, limon ve emek karışımı eller

Aşağı yukarı yürüyen insanlar

Ve aşağı yukarı yürüyen hayat

Bak bu güneşli pazar sokağı gibisi yok

Nasır tutmuş eller burada huzur bulur

Onur burada huzur bulur

Aralarından geçip giden hayat

bizim hayatımız 

Ve geçip giden zaman bize ait', 'Güneşli pazar sokağı ve güneşli gün Patates, limon ve emek karışımı eller Aşağı yukarı yürüyen insanlar Ve aşağı yukarı yürüyen hayat Bak bu...', ARRAY['Türk Edebiyatı','Şiir','Cevdet Solak']::text[], 8.5, '{"poet":"Cevdet Solak","poet_slug":"cevdet-solak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gunesli-pazar-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben - Gönül Ve İnsan -', 'ben-gonul-ve-i-nsan-mustafa-benkli-o6wul', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsan bir umut mudur? Benim; budur umudum...

Ümidim insan olmak; insanlıksa hududum! ...

Gönül; bak ki, sende, ben ne gördüm? Bilebilsen:

Sen; şafaktan nur topu, bekleyenlere ihsân...

Bir hâneye, ümitle gelen bir efsâneydin...

Heyecanla beklenen  hazîne, haseneydin! ...

Bir müddet elden ele âdetâ bir kelebek; 

Zaman zehir zemberek, sen oldun koca bebek! ...

Lâkin zaman çok haşin, senin de bitti işin; 

Okulun, akadaşın, insanlar daha haşin! ...

Hepsi çıktı karşına, dert katıldı aşına,

Bir de, gurbet taşına; kaldın yalnız başına! ...

Rüyâ mıydı; hakikat? O naz, o hülyâ! ... Hey hât! ...

Bebeklik ümidiymiş; insanlıksa, ne hoyrat! ...

Anladın; en sonunda, sezdin işin sırrını

Yaşadığın dünyada; riyâyla, taksirini...

Ve birden, sen oldum ben; aradım iksirini; 

Gönlümde gizlenen, tek, ümmîdimin sihrini! ...

Bir melek yoklar idi, ömrümde sık-sık beni; 

İnsanlarsa, ürkerdi; duysa,O`nun ismini! ...

Neden; bilemem, bana, O, hep sevimli geldi? 

Ümmîdim kırılınca, gönlüme ümit verdi...

Söz; toprağa gelince, bana, hep, şunu derdi:

Seni, ben alacağım; unutursun her derdi! ...

Orda Nekîr ve Münkir; benden öğrenir vîrdi

Diye, Azrâil, bana, Ordan, çok sırrı verdi! ...

Bu sırla, birden, sanki, bir kabirden silkindim; 

`Kamusal` kabir denen bu kabirden irkildim! ...

Meleğim; inanmazsın, ama, sana muhtâcım; 

Şu rûhsuz, hor kabirde; sen benim gönül tâcım...

Belki, inanmazsın sen; ben yemini de sevmem! ...

İnan! Yemin ederim; yeter ki, sen, gel hemen! ...

Hayatım boyunca hep, bu hisle muntazırım; 

İnanmazsan, gel de gör! ... Vallahî! ... Ben hazırım! ...', 'İnsan bir umut mudur? Benim; budur umudum... Ümidim insan olmak; insanlıksa hududum! ... Gönül; bak ki, sende, ben ne gördüm? Bilebilsen: Se...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ben-gonul-ve-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkin Koray', 'erkin-koray-mehmet-akif-tiryaki-0jhjt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söylediği şarkı şaşkın,

Tenhalarda bitmiş aşkın,

Gitarı bağlamadan bozma tılsımlı,

Perdeleri özel alışımlı

Kendisi bir ekol müzikte,

Belliki kalbi hala bizde.

Canlılık veriyor bize bu krizde

Sanatçılık bu günlerde belli,

Dinleyenlerini mutlu etmeli

Ölürsem kabrime gelme istemem

Rock müziği yaptı bu türküyü,

Dinletti bize,

Şarkı söylettirdi İbrahim Tatlıses''e

Üç kere güzel dedi kral,

O da beğendi bu düzeni,

Bu ikili bence dünyada birinci.

Krallar çarpıştı sahnede,

Yeni bir stil girdi litaratüre

İstemem dedi ikisi birden,

Şarkı bitti,

Türkü-rock litaratüre girdi.', 'Söylediği şarkı şaşkın, Tenhalarda bitmiş aşkın, Gitarı bağlamadan bozma tılsımlı, Perdeleri özel alışımlı Kendisi bir ekol müzikte, Belliki...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/erkin-koray-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuz Beş Yıllık Dostum (II)', 'otuz-bes-yillik-dostum-ii-i-brahim-halil-demir-tmfa4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sağına birde soluna,

Sonrada ayakabıların ucuna,

Ürkek gözlerle de gözlerimim içine baktı.

Özür diler gibiydi,

Rengi de sararmıştı,

Utancından sesi titriyordu.

Belki de kalp atışları bile normal değildi.

Bu halinden dolayı özür dilemek ister gibiydi.

Gayesi sanki şunu anlatmaktı.

Bilseydim senle karşılacağımı,

Hapis ederdim kendi kendimi der gibiydi.

Uzun süre bakakaldı.

Gözleri yaşardı.

Bu halini gizlemeye çalıştığı halde başaramadı.

Nihayet pişmanlık gözyaşları,

Dökülmeye başladı mahsun gözlerinden.

Yavaş yavaş o eski gözlerine,

Dönüşüyordu gözleri.

O gözler ki, saf bakışlı.sevgi saçan,

Ve de çok anlamlar ifade ederdi.

“üzüm üzüme baka baka kararır”misali,

Gözler şatırlaşmış,anlam ve safiliğini,

Yitirmiş bu kozmopolit yerlerde.

Belki de haklıydı,çünkü

Değişmemek neredeyse mümkün değildi.

Ulaşım araclarında insanlar,

Pencereden dışarıya baka-baka,

Büyüklerine, öncelikle oturması gerekenlere,

Yer vermeyi unutmuştular.

O an içimden kendi özeleştirimi,

Yapmak geldi işin kolayına kaçmadan.

Acaba onun yerinde ben olsaydım,

Değişmezmiydim diye.

Tuttum ellerinden,eskiden olduğu gibi,

Kucakladım onu muhabbetle.

Gönlünü alırcasına.

Ben de ağlamaklı oldum,

Ve şu cümleyi duyar gibiydim o an.

“hay Allah keşke buralarda yaşamak nasip olmasaydı”

Anladım ki kendi haline o da çok üzülüyordu.

Dalgaların sahile vurduğu bir yerde,

Uzun süre oturduk.

O konuştu ben dinledim.

Ben konuştum o dinledi.

Yavaş-yavaş,buram-buram memleket kokan,

Bir hal yaşanıyordu.

Başladı hayatından bölümler anlatmaya,

İçini çeke-çeke.

“yabancı uyruklu biriyle evlendiğini,

Boyuna ve deniz yosunu yeşilimsi gözlerine,

Aşık olduğunu,

Duygularına gem vuramadığını,

Ve onunla yıldırım nikahıyla evlendiğini,

Nur topu gibi bir kızının bir de oğlunun olduğunu,

Ama gün geçtkçe boyu ve gözlerinin,

Hiçbir anlam ifade etmediğini,

Çünkü günahsız çocuklarının bize göre,

Çok ters olan adetlerle yetiştirildiğini,

Defalarca uyarmış olmama rağmen,

Sert kafalılığını devam ettirdiğini,

Ben de katil olmamak için ayrıldığımı,

Şimdi de çocuklarımın gözümde tüttüğünü,

Zira kadın her iki çocuğumla birlikte,

Kendi ülkesine kaçıp geri gittiğini “söyledi.

Bunları dinledikten sonra,

Dokunsan ağlayacaktım.

Çünkü bu tür metropoller insanı,

Halden hale sokabiliyormuş meğer ki.

Yeni anladım.

Ayrılık zamanı gelmişti,ama ben hiç,

Ayrılmak istemiyordum.

Çünkü yaşadıkları beni derinden etkilemişti.

Ev,iş telefonunu,adreslerini yazıp verdi bana.

En kısa zamanda daha uzun süreli,

Görüşme dilek ve temennisinde bulunduk.

Daha anlatacak çok şeylerinin olduğunu söyledi.

Eskiden olduğu gibi,dostça,kardeşçe kucaklaştık.

Ve ayrıldık.

Ben bir daha ki görüşmemizi sabırsızca,

Şimdiden beklemeye başladım bile.

05/02/2006', 'Bir sağına birde soluna, Sonrada ayakabıların ucuna, Ürkek gözlerle de gözlerimim içine baktı. Özür diler gibiydi, Rengi de sararmıştı, Utan...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/otuz-bes-yillik-dostum-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerindeyim', 'gozlerindeyim-neslihan-uzel-aw71t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gözlerime bakarken

Umurumda değil nerdeyim, hangi mevsimdeyim...

Sahildesin, 

Ilık esen rüzgar ve dalga sesleri 

Kaldır başını bak

Gökyüzündeyim...

Güneşi hisset, göreceksin

Ellerimde çiçek, gözlerindeyim.', 'Sen gözlerime bakarken Umurumda değil nerdeyim, hangi mevsimdeyim... Sahildesin,  Ilık esen rüzgar ve dalga sesleri  Kaldır başını bak Gökyü...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Üzel']::text[], 8.5, '{"poet":"Neslihan Üzel","poet_slug":"neslihan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gozlerindeyim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Daha İyiyim', 'cok-daha-i-yiyim-omer-dalman-xh174', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O -yıllanmış, kupkuru- gözlerimden

usul usul akmasaydı ''o yaş''

ner''den bilebilirdim

yüreğinin bu kadar yumuşak olduğunu? 

ner''den bilebilirdim

benim için ağladığını? 

bu -geçirimsiz, çelik gibi- insan ırkına zıt

meleksi bir incelikte baktığını? ..

ner''den bilebilirdim? ..

o halde gidip, Yaratan''a mı şükretmeliyim

düşen o çekingen gözyaşım için? 

''gerçek kalbin''i bana tekrar verdiği için? 

ner''den bilebilirdim? ! 

O -yıllanımış kuruluktaki- gözlerimden

usul usul aktı ya ''o yaş''

şimdi biraz içim buruk belki ama

çok daha iyiyim...

(Şubat 2006)', 'O -yıllanmış, kupkuru- gözlerimden usul usul akmasaydı ''o yaş'' ner''den bilebilirdim yüreğinin bu kadar yumuşak olduğunu?  ner''den bilebilird...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cok-daha-iyiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-suleyman-demir-yk70q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'nedendir bu kadar düşman kesildiniz bana? 

yare giden yolları kesmek oldu mu dağlar? 

hercai gönlümü kalleşçe atıp yabana,

feryadıma karşılık susmak oldu mu dağlar? 

bir ben kaldım çaresiz tavrınızdan muzdarip! 

tükettiniz ömrümü gençliğimi kemirip! 

pervasızca bir hain sevgiliye yol verip,

benim gibi garibe küsmek oldu mu dağlar? 

farkında değilmisiniz ak ile karanın? 

ateşi yangın oldu gönlümdeki çıranın! 

şirin için ferhattan aldığınız yaranın,

kinini suratıma kusmak oldu mu dağlar?', 'nedendir bu kadar düşman kesildiniz bana?  yare giden yolları kesmek oldu mu dağlar?  hercai gönlümü kalleşçe atıp yabana, feryadıma karşılı...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Demir']::text[], 8.5, '{"poet":"Süleyman Demir","poet_slug":"suleyman-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/daglar-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Bizim', 'sevda-bizim-mehmet-akif-tiryaki-8jyql', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ud ve klarnet,

Savaş ve esaret,

Darbuka arkadaş onlara,

Klasik müziğimiz şehnaz longa

Bir yerden başlamalı ulusal kalkınma

Olmalıyız artık farkında,

Yeter oturduğumuz Gülhane Parkı''nda

Gençler bu gidişin farkında,

Rüzgarlar esmeli içimizde

Fırtınalar bitmemeli bizde.

Gelelim artık kendimize,

Benzeyelim ecdadımıza, dedemize,

Umarım bu enerji içimizde

Yeter,

Başlasın artık yeni akım,

Dursun bu zulmü batının

Uygarlık bizim, cesaret bizim,

Kim büker bileğini milletimizin,

Yaşasın özgürlük bitsin bu mezalim,

Sanat bizim, aşk bizim, sevda bizim.', 'Ud ve klarnet, Savaş ve esaret, Darbuka arkadaş onlara, Klasik müziğimiz şehnaz longa Bir yerden başlamalı ulusal kalkınma Olmalıyız artık f...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevda-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tiryaki', 'tiryaki-hayatin-i-cinden-pcx7q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doğduğu gün düşüyor 

hayatın ılık sarhoşluğuna

Tiryakisi olup çıkıyor

yavaş yavaş yüzü kırıştıkça

İnsan zamanla anlıyor

hayatın riyakarlığını.

Sahte yüzlerin çokluğunu

farkında olmadan tanıyor.

Ve insan öldüğü gün tadıyor

hayatın yalancılığını,

ölümün gerçekliğini...', 'Doğduğu gün düşüyor  hayatın ılık sarhoşluğuna Tiryakisi olup çıkıyor yavaş yavaş yüzü kırıştıkça İnsan zamanla anlıyor hayatın riyakarlığın...', ARRAY['Türk Edebiyatı','Şiir','Hayatın İçinden']::text[], 8.5, '{"poet":"Hayatın İçinden","poet_slug":"hayatin-i-cinden","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tiryaki-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-hayatin-i-cinden-50sst', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her sabah uyandığım gibi kalkmıyorsam yatağımdan,

geceyi gündüzü ayırtedemez olduysa gözlerim,

dalgınsam,

ve hala nefes alıp verebiliyorsam bu gurbet elde,

içim titriyorsa,üşüyorsam vakitli vakitsiz,

ve gecenin köhne saatinde bile aklıma geliyorsan anne; 

seni özlediğimdendir bu hallerim,

seni çok sevdiğimdendir bu şiir...', 'Her sabah uyandığım gibi kalkmıyorsam yatağımdan, geceyi gündüzü ayırtedemez olduysa gözlerim, dalgınsam, ve hala nefes alıp verebiliyorsam ...', ARRAY['Türk Edebiyatı','Şiir','Hayatın İçinden']::text[], 8.5, '{"poet":"Hayatın İçinden","poet_slug":"hayatin-i-cinden","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anne-197-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reklamlar', 'reklamlar-mehmet-akif-tiryaki-9x97d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Reklamlar yeniliklerin aşamasında

Beş firma tekrarlanıyor her defasında,

Katılım diğer firmalardan da gelmeli,

Ufak esnaf reklam verebilmeli.

Genelde televizyonda banka reklamı çok,

İmalatçı firmalar ortada yok.

Hiç reklam veren köylü gördünüzmü

Bir iki süt firması onları temsil etmemeli,

Demir firmasının reklamı neden yok,

Parfüm, saç boyası, şampuan reklamı çok.

Boru reklamları şimdilik iyi,

Dershaneler de kazanıyor, reklam vermeli.

Mahallemizdeki bakkal reklam vermek istedi,

Ben nereye başvuracağım dedi.

Komik oldu, bu talep esnafın,

Dedi ben paranın büyüğünden ne anlarım.

Haftada üç kilo sigara parasını ancak tamamlarım.

Eğer plaza çarşısındaysa dükkanınız,

Sattığınız malın yapılır reklamı şanslısınız.

Köylüye, esnafa şans yok anlaşılan,

Kimdir bu işleri planlayan çalışan

Her ülkenin bir plan ve projesi olmalı,

Köylüyü, işçiyi, esnafı korumalı.

Kitleler arası kopukluk azalmalı, olmamalı.

Adalet, kanun bir de etik uygulanmalı.

Reklamlar tüm köylüye, esnafa açılmalı,

Yerli imalatlara teşvikler uygulanmalı,

Türkiye ihracatta fark atmalı,

Reklamın faydalarını bir çok firma tatmalı,

Sadece bankalar, cep telefonları

Televizyonlarda bekçi olmamalı.', 'Reklamlar yeniliklerin aşamasında Beş firma tekrarlanıyor her defasında, Katılım diğer firmalardan da gelmeli, Ufak esnaf reklam verebilmeli...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/reklamlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaren', 'yaren-i-zaver-gurbuz-22zav', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yanlızlığıma arkadaş oldun sen

Aşkı sevmeyi öğrettin bana

Sevda denizlerinde kayboldum seninle

Ellerimi hiç bırakma ne olur sev beni

Mutluluk güzel şey hiç bitirme kalbinde

İçimdeki aşkını değişmem kimselere

Neden nasıl diye sorma bana benimde sevdam bu işte.', 'Yanlızlığıma arkadaş oldun sen Aşkı sevmeyi öğrettin bana Sevda denizlerinde kayboldum seninle Ellerimi hiç bırakma ne olur sev beni Mutlulu...', ARRAY['Türk Edebiyatı','Şiir','İzaver Gürbüz']::text[], 8.5, '{"poet":"İzaver Gürbüz","poet_slug":"i-zaver-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yaren-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardaş', 'gardas-hayatin-i-cinden-p6z8y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sızı var gardaş içimde,

tam şuramda; 

kalbimin derinliklerinde.

Hüzün var gardaş yüzümde,

süzülüyor damlacıklar

yine aynı göz bebeğinde.

Acı var gardaş dilimde,

ne rakı ne bade

aşk yarası bu, yara açar dilimde.

Ümitsizlik var gardaş yüreğimde,

dönüşü olmayan bir yoldayım sanki,

tüm dertler benim üstümde.

Yalnızlık var gardaş doğan günümde,

asi ve sessiz bir yalnızlık,

yine kaldı benim üstümde.

Ölün var gardaş esen yelde,

Azrail''in nefesini hissediyorum,

sanki kulağımın dibinde.', 'Bir sızı var gardaş içimde, tam şuramda;  kalbimin derinliklerinde. Hüzün var gardaş yüzümde, süzülüyor damlacıklar yine aynı göz bebeğinde....', ARRAY['Türk Edebiyatı','Şiir','Hayatın İçinden']::text[], 8.5, '{"poet":"Hayatın İçinden","poet_slug":"hayatin-i-cinden","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gardas-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-sair-esantiyon-dd82w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç bilmedim sensizliği

Yada tahmin edemedim

Geri dönmek hep 

Mümkün sandım

Yada hep kendimi kandırdım

Bu son vedaymış 

Söylemedin bana

Büktün kırılmas sandığım belimi

Ahhh.....

Bilseydim sallarmıydım sana

O kırılası elimi', 'Hiç bilmedim sensizliği Yada tahmin edemedim Geri dönmek hep  Mümkün sandım Yada hep kendimi kandırdım Bu son vedaymış  Söylemedin bana Bükt...', ARRAY['Türk Edebiyatı','Şiir','Şair Esantiyon']::text[], 8.5, '{"poet":"Şair Esantiyon","poet_slug":"sair-esantiyon","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/veda-197-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issız bir tarladasın', 'issiz-bir-tarladasin-levent-i-skenderoglu-vvl67', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Issız bir tarladasın 

Sapsarı bereketli

Yağmur ıslatmışsa hatıralarını

Aldırma

Bırak rüzgarlar  essin

Karşı ki tepeden  eteklerine

Komşuların dallarına konan serçelerin 

Ve kargaların  nasibini  ver

Yeşil  yeşil  sallanırken ılık yellerle 

Birden

Sarmaşıklar  sıkar ya  boğazını

Hani  kan tükürürsün

Köylülerin taştan ellerine

Sonra kardeşlerine arandaki  boşluğa

Bırakır ya bir ana bebeğini

Güven ver

Keskin kılancına nasıl dayanır cılız gövden

Uçurmak yerine boynunu

Bir ipe dolaşan ayaklarını

Bir gün bir sürü dadansa

Çoban uzakta

Çoban gündüz gözü 

Geceyle  boğuşurken

Tükensen

Yeniden büyü

Sen umutsun

Gözler umut

Sözlerinde kin yok

Bereket dudaklarında çatlak, sessiz,yumuşak

Sözü uzatma fazla, el ver

Çünkü  sana uzayan saman yolunda 

Nice eller var

Sana uzanan

					

					26.10.1998

					pazartesi-', 'Issız bir tarladasın  Sapsarı bereketli Yağmur ıslatmışsa hatıralarını Aldırma Bırak rüzgarlar  essin Karşı ki tepeden  eteklerine Komşuları...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/issiz-bir-tarladasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamüstü', 'aksamustu-hayatin-i-cinden-q13ys', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kızıllık çöktüğü an

bronzlaşan yorgun bedenimizin üstüne

herşeyi yapabilir miyiz,

gerçek bir sevginin üstüne? 

Koparabilir miyiz meyveleri mutluluk ağacından,

susamışçasına içebilir miyiz aşk iksirinden,

doya doya öpüşebilir miyiz

bizimle bütünleşen güneşin önünde? 

Son kıvamına varabilir miyiz sevişmenin,

sadakatin ve samimiyetin.

ne dersin sevgilim yapabilir miyiz,

yani biz gerçekten biz olabilir miyiz?', 'Kızıllık çöktüğü an bronzlaşan yorgun bedenimizin üstüne herşeyi yapabilir miyiz, gerçek bir sevginin üstüne?  Koparabilir miyiz meyveleri m...', ARRAY['Türk Edebiyatı','Şiir','Hayatın İçinden']::text[], 8.5, '{"poet":"Hayatın İçinden","poet_slug":"hayatin-i-cinden","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksamustu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olimpos', 'olimpos-mehmet-akif-tiryaki-dshdy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dingin ve huzur içinde bir dere,

Dereden geçtik denize,

Sahilde hışır hışır dalga sesleri,

Gönlümüz denizde.

Tepedeki evde yaşıyor bir hanım,

Yeni bir hayat kurmuş keser ve testereyle,

Misafir etti evinde bir gece

Makinasını da satmıştı arkadaşı

Çekeceğime yaşıyorum dedi doğayı

Ayaklı kütüphaneydi eskiden,

Çakıl taşı topladı sahilden cebine,

Burada dalgalar karaya vuruyor dedi,

Bu dalgaları biri seyretmeliydi.

Beş gün marketlere gelmezse erzak,

Şehirde oturanın hali ne olacak

Bahçe duvarları bile onları koruyamayacak.

İnsanlar artık köylere ev kuracak.', 'Dingin ve huzur içinde bir dere, Dereden geçtik denize, Sahilde hışır hışır dalga sesleri, Gönlümüz denizde. Tepedeki evde yaşıyor bir hanım...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olimpos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun', 'yoklugun-zeliha-ural-o03hy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O öyle bir aşk ki senli ya da sensiz

Nasıl da sevmişti gözü kara

Yıllar geçti senden,

Ondan habersiz

Ne bir umut,

Nede bir ışık kalmıştı

YARINLARDAN.

Alışmıştı hasretine 

Tiryakin olmuştu, özlemin

Yokluğun.....Yokluğun,

Ondan güzel umut varmı ki

Ha geldi ha gelecek

Ne olur görmeden git

Ne olur alevlendirme sönen ateşi

Yokluğunun acısını 

Sensizlikte SEVDİ.', 'O öyle bir aşk ki senli ya da sensiz Nasıl da sevmişti gözü kara Yıllar geçti senden, Ondan habersiz Ne bir umut, Nede bir ışık kalmıştı YAR...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Ural']::text[], 8.5, '{"poet":"Zeliha Ural","poet_slug":"zeliha-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yoklugun-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimden Gelmedi Bu Gece Eve Gitmek', 'i-cimden-gelmedi-bu-gece-eve-gitmek-kamil-soylemez-izua9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni ilk kez seninle ağladım koridorlarda				

Prangalar ektim tüm içim acısı ile ortama				

Acıdı kalbim,acıdı her yanım pranga				

Şimdi bir garip,şimdi bir tuafım sen başucunda				

				

Sen yığılıp,kaldınya kucağıma,ben yandım				

Ben bayıldım,fırtınalı bir aşkın ardı sıra 				

Doktorlar bir başkaydı,hastalar bir başka				

Şimdi sen uyuyor,ben ağlıyorum başucunda				

				

Yalvarıyorum şu aciz doğa kanunları duşunda				

Sessiz gece uçuşları karanlık akşam şafağında			

Sabahı kucaklıyorum bir ben başlı başına ruya				

Soldu gece sen kurşun gibi rahatsızlığında				

				

Benlerin anlamı çözülüp,döküldü sereserpe				

Şimdi anlıyorum,şimdi derin kuyu bir gece				

Sensiz olmayan bir acı istemedim 				

Şimdi anlıyorum sevginin özlemin güzelliğinide				

				

İçimden gelmedi gitmek bu gece eve				

Sanki bir kuş çırpınıp duruyor göğsümde				

Bir garip,his bir garip sızı tutuyor elleriyle				

Ve işte sebebi gece yırtılıyor sen sızın ile				

				

Bir garip duygu bir garip sancı içimde				

Durmuyor bedenimde yer,yer titreme				

Ellerin elimde gidiyoruzya belirsizliğe				

Ölüyor içimde çırpınan kuş sessizce				

				

Korkuyorum bu gece korkuyorum seninle				

Düş kurmak yok sadece yetişmek hastaneye				

Bir an evvel dinsin bu acı bu çile çekmeler				

Ömrüm son bulsun sana olmasın hiç bir şeyler				

				

Kıyamadım sen acı çekmelerine,ağladım				

Karlı dağlar kurak çöller yüreğime bağladım				

Aşkım dedim aşkım geceyi yüreğime dağladım			

Sen ah sevdam sen acılarında sana yandım				

				

Düşsün istedim tüm acılar senden ben cana				

Yalvardım allahım alda ver ondan acıları bana				

Dayanamıyordum senin bu kıvranıp sızlamalarına			

Ağladım ağladım ağladım geceden sabaha				

				

Seni seviyorum sevdam şimdi daha bir fazla				

Gözüm kulağım sende senin mutluluğunda				

Ne olursun sende biraz düşün biraz beni anla				

Sağlık bu atıp gitme ne olursun yabana				

				

Anlarmısın sevdiğim ben gibi sende sevgiyi				

Özleminle terkettiğim ömrün değersizliğini				

Sen yoksan gerçeğin bu candan gittiğini				

Bilmemki sen nerede ölüp,nerede dirildiğini				

				

Şimdi daha iyi anlıyorum sensizliğin zemherisini			

Şimdi daha bir üşüyorum sen çekip,gittiğin geceyi			

Daha bir içime sindiriyorum acılı gecenin çekilmezliğini			

Sağlığın ne kadar beni yıpratıp,tükettiğini				

Ve yalvarıyorum sana,ne olur incitme kendini				

Takma kafana anlamsız seni üzen düşleri				

Sen yoksan bende yokum seviyorsan anla				

Sensiz hiç çıkamam geceden sabahlara				

				

Sakın ağlayıp,sızlama,yüreğini boş yere dağlama			

Bak geçiyor ömür hemde fırtına gibi sarsa sarsa			

Duymazdan gel acıların dilini bundan sonra				

Takıl hayatın sende gerçek tatlı uçan kanadına', 'Seni ilk kez seninle ağladım koridorlarda				 Prangalar ektim tüm içim acısı ile ortama				 Acıdı kalbim,acıdı her yanım pranga				 Şimdi bi...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/icimden-gelmedi-bu-gece-eve-gitmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamüstü 2', 'aksamustu-2-hayatin-i-cinden-hsl38', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorgun kızıllıkta açan sevgi çiçeği

başlamadan biten bir beraberlik gibi

yalnız ve çaresiz şimdi.

Engin denizler ve dağlar ardında

Çığlık çığlığa bir hasret türküsü çınlıyor

duygu yüklü bu sarhoşlukta

insan ne yapacağına şaşıyor.

Buram buram sevgi tütüyor

ve kokusu her bedene işliyor

yalnızlıktan doğan bir dalgınlık ki sorma

insan ne yapacağını bilmiyor bu havada

Hasret olduk hasretlik çektirene,

böyle havada kendini sevdirmeyene...', 'Yorgun kızıllıkta açan sevgi çiçeği başlamadan biten bir beraberlik gibi yalnız ve çaresiz şimdi. Engin denizler ve dağlar ardında Çığlık çı...', ARRAY['Türk Edebiyatı','Şiir','Hayatın İçinden']::text[], 8.5, '{"poet":"Hayatın İçinden","poet_slug":"hayatin-i-cinden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aksamustu-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-zeliha-ural-x6c5m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülistanda dolaşırken sensiz

Hep boyun eğdiler sessiz

Açmalıydı bir goncası

Olmalıydı bir tanesi

O sevda benim.....

Ben..... sessiz çığlıklarımla, 

Dolaşırken sensiz 

Seni sormadılar bana 

Böylesine yok olmuşken sende,

Seni gördüler belkide; 

Dağlar,taşlar uçan kuşlar

Selama durdular...

 Sanki hayat durmuştu.', 'Gülistanda dolaşırken sensiz Hep boyun eğdiler sessiz Açmalıydı bir goncası Olmalıydı bir tanesi O sevda benim..... Ben..... sessiz çığlıkla...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Ural']::text[], 8.5, '{"poet":"Zeliha Ural","poet_slug":"zeliha-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sensiz-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk Şarkısı', 'dostluk-sarkisi-mehmet-akif-tiryaki-on5q8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dostluğun biz sevgisiyle

Toplandık her an burda

Diyor Amerika Irak''da.

Bu sevgi bağı kopmaz hiç,

Dağılsak bütün dünyaya.

Bunların hepsi hülya

Filimlerde söylenir ıslıkla

Gerçek hayat farklı, zorluklarla dolu,

Barıştan geçer huzurun yolu

Her yere uzanır Türk Milleti''nin kolu

Yüreğimiz önce Hak sonra

Vatan aşkıyla dolu,

Belli olacak sonunda

Bozguncuların hazin sonu.', 'Dostluğun biz sevgisiyle Toplandık her an burda Diyor Amerika Irak''da. Bu sevgi bağı kopmaz hiç, Dağılsak bütün dünyaya. Bunların hepsi hüly...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dostluk-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oda Yüzüçten', 'oda-yuzucten-hayatin-i-cinden-fauae', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece çirkin vakte yaklaştığında

kilit vurulur yurdum kapısına,

gündüzün özgürlüğü gecenin mahkumluğuna bırakır yerini

ve beton duvarlar arasında boğulmaya başlar yüreğim,

ya bir sigara yakarım,

ya da içim yanar çalan radyodan...', 'Gece çirkin vakte yaklaştığında kilit vurulur yurdum kapısına, gündüzün özgürlüğü gecenin mahkumluğuna bırakır yerini ve beton duvarlar aras...', ARRAY['Türk Edebiyatı','Şiir','Hayatın İçinden']::text[], 8.5, '{"poet":"Hayatın İçinden","poet_slug":"hayatin-i-cinden","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/oda-yuzucten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Dileniyorum', 'seni-dileniyorum-dilek-uz-pzk3f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensizlik...

Bir gün daha sensizim..

Kaç geceler geçti yokluğuna,

Kaç gündüzler sensiz sokaklarda dolaşacağım,

ne zaman sabahlarımda olacaksın...

Acılar,dertler,özlemler,

Sıralandı,birbiri ardına

Yüreğime kenetlendi yokluğun...

Nefesini nefesimde hissedemez,

Yüreğinin sıcaklıgına,

Öyle hasretim ki sana...

Kırık dökük yaşantıma

Sağanak bir yağmurla girdin adeta

Yüreğimin sızlayacagını,acıyacağını bildiğim halde

Hayır diyemedim sana...

Pişmanlık duyuyor musun diye sorsalar; 

ASLA...

Sadece yüreğim sızlar oldu,

Sensiz günler geçmez oldu,

Sabahlarımda,gecelerimde yanımda olmanı arzuluyorum..

Bekliyorum esen rüzğarları 

esip geçtikçe,belki seni getirir ümidiyle

Seni bana getirmedikçe,Yüreğimi açıyorum

Her gece seni diliyorum...

Boynu bükük kuytu bir köşede seni bekliyorum 

İçtiğim sudan,soluduğum havadan bile,

Seni dileniyorum...', 'Sensizlik... Bir gün daha sensizim.. Kaç geceler geçti yokluğuna, Kaç gündüzler sensiz sokaklarda dolaşacağım, ne zaman sabahlarımda olacaks...', ARRAY['Türk Edebiyatı','Şiir','Dilek Uz']::text[], 8.5, '{"poet":"Dilek Uz","poet_slug":"dilek-uz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seni-dileniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Koca İstanbul', 'ey-koca-i-stanbul-mehmet-akif-tiryaki-g95o2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbul''da kazandım,

İstanbul sokaklarında kaybettim.

En güzel yıllarımı 

Sahtekarlara devrettim.

İşte geldim gidiyorum,

Onlara da hakkımı helal ettim.

İstanbul''da kazandım,

İstanbul sokaklarında kaybettim.

En güzel yıllarımı ziyan ettim.

Otuzüç yaşımda kendimi fark ettim.

Şükrettim, Allah''ıma hamd ettim.

İstanbul''da kazandım,

İstanbul sokaklarında kaybettim.

Birçok güzel dost edindim,

Sevdim, sevildim

Ortam hoştu, gönlüm sarhoştu,

Aklım başımdan gitti,

Sabah oldu yaprak yaprak,

Saçlarıma aklar doldu,

Mevsimler sonbaharda başladı,

Takvimler sonbaharda durdu.', 'İstanbul''da kazandım, İstanbul sokaklarında kaybettim. En güzel yıllarımı  Sahtekarlara devrettim. İşte geldim gidiyorum, Onlara da hakkımı ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ey-koca-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam', 'adam-umut-engin-deniz-96op2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ADAM

Soğuk bir kış günü;

her yer bembeyaz.

Terso delikanlıdır İstanbul.

Çatmış kaşlarını; elleri cebinde.

Böyle bir günde —

adamın üzerinden ceketini,

cebinden parasını,

yüreğinden sevgisini aldılar.

Hiçbir şeyi kalmamıştı.

Nereye gideceği belli değil.

Belki sıcak bir çay ocağı,

belki de soğuk bir park…

Ama o, adamdı.

Önemli olan bu değil mi?

Yokların arasında var olabilmek.

İnsanlığın bir adım ötesi —

adam olabilmek.

Kararını ver!

Doğan herkes insandır;

İnsanlığın bir adım ötesine geçebilen?

06.02.2006

Unlbbcn

Umut Engin Deniz', 'ADAM Soğuk bir kış günü; her yer bembeyaz. Terso delikanlıdır İstanbul. Çatmış kaşlarını; elleri cebinde. Böyle bir günde — adamın üzerinden...', ARRAY['Türk Edebiyatı','Şiir','Umut Engin Deniz']::text[], 8.5, '{"poet":"Umut Engin Deniz","poet_slug":"umut-engin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/adam-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterse Dursun Dünya', 'i-sterse-dursun-dunya-yavuz-bayram-caliskan-gh7p6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zemheride İstanbul çok güzel

Senle daha güzelleşirdi,

El ele gezerdik, tozardık,

Ulus parkına giderdik çamlıca''ya kısın çok güzel oluyor.

Renkleriyle tepesine binerdik İstanbul’un,

Hem de nasıl,

Renkleriyle çatlardı ayazları,

İkimize dayanamazdı,

İstanbul kazan biz kepçe,

Meyhanelerde, çalgıların ses verdiği her yerde,

Nihavent şarkılarda,

Denizlere dökerdik akşamları.

Kafalar aynı şişeye göz dikmiş,

İçmeler bardaksız,

Şişe dibini görünce,

Tepene dik akşamları.

Başlıyor ney sesi uzaktan gelmeye,

Hoş oluyorum ya da sarhoş.

Neyin sesinde meşk başlıyor sevdaya,

Omuzuma yaslansın şarkılarda.

Omuzundaki baş sevdalıysa aska,

Bırak ağlasın gözden dökülsün yaş.

İç aşkın şarabını gecelerimde.

Mutluluğa ağlarsın.

Geceler gözlerinde ışıl ışıl olur,

Geceler yüreğinde beni korur,

Işık sensin güneş sen,

Ay sensin şarap sen,

Yanında sarhoş olan ben.

Tenler ister bu sevdayı, ayyaşlığına gideceğiz  ey sevda.

Trenin nerde? 

Her durakta aradım seni her limanda,

Bir gece vakti trenle geldin yanıma.

Beklemek seni o ölmek gibiydi garda,

Geldin ya.

İsterse dursun dünya.', 'Zemheride İstanbul çok güzel Senle daha güzelleşirdi, El ele gezerdik, tozardık, Ulus parkına giderdik çamlıca''ya kısın çok güzel oluyor. Re...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/isterse-dursun-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrenemediğim Sevgi', 'ogrenemedigim-sevgi-mehmet-akif-tiryaki-u02o5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öğrenemediklerim,

Sevmek, 

Özlemek.

Öğrendiklerim mi? 

Kelebeğin kısa ömrü,

Bir şiir defteri,

Belli değil şairi söyleyeni

Bir zaman tüneli

Ahşap bir ev yokuşun başında

Pencereleri tenteneli perdeli,

Cumbalı,

Tavanları kuş resimli

Bardakların üstü nakışlı işlemeli,

Merdivenler ahşap,

Giriş mermer döşemeli,

Birileri birilerini sevmeli,

Sevgi

İnsanın eseri, aktör sensin,

Sevgisiz hayat bir trajedi bilirmisin

Topal filozof ne dedi dersin:

Seveceksen toprak bir vazo sev,

Kırılırsa üzülmezsin.

Arkadaş sende inanma bu topal filozofa kanma,

Bak kollarını açmış bekliyor seni koca Mevlana...', 'Öğrenemediklerim, Sevmek,  Özlemek. Öğrendiklerim mi?  Kelebeğin kısa ömrü, Bir şiir defteri, Belli değil şairi söyleyeni Bir zaman tüneli A...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ogrenemedigim-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göksu Geceleri', 'goksu-geceleri-mehmet-akif-tiryaki-wl8ot', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vaktiyle bu koltukta

Kimler oturdu, kimler kuruldu

Bu işlemeli aynalara

Kimler baktı durdu

Altın varaklı mobilyalar oldu,

Evlerde baş köşelere koyuldu,

El işçiliği dönem dönem makbul oldu

Ebrular, hatlar, sedef kakmalar,

Elde dokunurdu bir zamanlar halılar

Denize karşıydı büyük yalılar,

Boğazın çalkantılı suları hareketli,

Göksu''da geceler mehtaplı ve debdebeli,

Saltanat kayıkları el yapımı,

Beyler sandallarda gezerdi,

Hanımlar konaklarda nakış işler,

İstanbul''da geceleri

Bekçiler sokak sokak gezer,

Tepelerden batan güneş

Boğaza göz süzerdi.

Mehtaplı geceler boğazda ne güzeldi.', 'Vaktiyle bu koltukta Kimler oturdu, kimler kuruldu Bu işlemeli aynalara Kimler baktı durdu Altın varaklı mobilyalar oldu, Evlerde baş köşele...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/goksu-geceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metehan', 'metehan-mehmet-sukru-bas-bn9px', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Torunuma.       

 Bir bahar günü can bulurken cihan,        

 Beş Mart ta doğdu gönüllerde Metehan

 Bahar gibi şad ol,bahar gibi can,

 Ömrün hep bahar olsun,yavrum Metehan.

 Dertlere konaktı,her çileye duraktı baban,

 Acılar dolu,köhne bir handı baban.

 Suskun doğmuştu,hep de,suskun yaşadı,

 Oysa o ömrümde mana,hayatımda bahar dı,

 İstedim seninle yeşersin alem,sende can bulsun,

 Seninle kederler yok,dertler son bulsun.

 Sevgin sarsın beni,can bulayım can,

 Ömrün hep şad olsun,yavrum Metehan.

           05.03.2002   Elazığ S.S.K.Hst.', 'Torunuma.         Bir bahar günü can bulurken cihan,          Beş Mart ta doğdu gönüllerde Metehan  Bahar gibi şad ol,bahar gibi can,  Ömrün...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/metehan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardaş', 'gardas-halil-colak-lq2o7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gurbetin adı bile acıdır Gardaş

Yerin cennet de olsa da

Gurbette kötüdür Gardaş

Sana candeselerde çor gelir Gardaş

Evin altından mekan olsa da

Mutlu olman zor olur

Yine vatanı istersin Gardaş

Halil Çolak 6.2.2006 Ankara', 'Gurbetin adı bile acıdır Gardaş Yerin cennet de olsa da Gurbette kötüdür Gardaş Sana candeselerde çor gelir Gardaş Evin altından mekan olsa ...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gardas-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın yerinde filizlenen papatya...!', 'yangin-yerinde-filizlenen-papatya-musfik-saltik-lf13w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her şeyin var olduğunu sandığında 

Hiçbir şeyin olmadığını farkına varmak

Sevincin içindeki hüzünlerin yükselişi

Hüznün içinden yeşeren sevinçler

Şiddete yönelmenin doğal olduğu  anda

Yüreğinden filizlenen seni durduran  şefkat

Şefkat gösterdiğinden sana yönelen şiddet

Umut gördüğünün sana sunduğu umutsuzluk

Huzur beklediğinden  yansıyan huzursuzluk

Önemli olanların önemini yitirmesi

Var sandıklarının birden bire sönüp gitmesi

Güneş sandığının aslında ay olduğunu  görmek

Karanlığa boğulup bir anda ölesiye üşümek

Uzun bir yolda yürüdüğünü sanırken beraber

Aslında  hep yalnız yürüdüğünü fark etmek

Değer yüklediklerinin, değerliler listede 

Senin hiçbir zaman olmadığını görmek

Ters yüz oluvermesi bir anda her şeyin

Ve yeniden başlamak için vaktin kalmaması senin.

Boşlukta kalan, umutla planladığın geleceğin

Bir çırpıda silinip giden her şeyin

Bu noktaya geldiğinde 

İki yolun vardır önünde 

Ya her şeyi bitirir şalteri kaparsın

Ya da tutunacak yeni bir dal ararsın

Kolayı şalteri kapamaktır

İkincisiyse tercihin

Ufacık bir dal bile bulursan bir gün

Geçmişte, deymeyene verdiğin sevginin

İlginin, şefkatin binde birini

Verebilirsen eyer o ufacık daldan

Kısa zamanda yükseliverir  dev bir çınar', 'Her şeyin var olduğunu sandığında  Hiçbir şeyin olmadığını farkına varmak Sevincin içindeki hüzünlerin yükselişi Hüznün içinden yeşeren sevi...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yangin-yerinde-filizlenen-papatya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalar Şehri İstanbul', 'ruyalar-sehri-i-stanbul-mehmet-akif-tiryaki-9iyzz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul elimizden kaydı gitti

Nereye mi? 

Rüyalar ülkesine

Anılar kayboldu

Nereye mi? 

Eski bir kitap köşesine

Kırmızı gelincikler? 

Bir ressamın tablosunda saklı,

Beykoz''un sahil yolu

Dar ve zikzaklı

Baharın kokusu

Parfüm şişelerinde

Tepelerin ağaçlı dokusu

Yağlı boya ve sulu boya resimlerinde,

Çok sevdalar yaşandı boğazın penceresinde

Romanlar yazıldı,

Şarkılar bestelendi

İstanbul üzerine niye? 

Rüyalar şehri İstanbul

İsteyen görsün diye.', 'İstanbul elimizden kaydı gitti Nereye mi?  Rüyalar ülkesine Anılar kayboldu Nereye mi?  Eski bir kitap köşesine Kırmızı gelincikler?  Bir re...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ruyalar-sehri-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezdiğimiz Yerleri Gezdim', 'gezdigimiz-yerleri-gezdim-yusuf-onder-bahceci-xuti0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gezdiğimiz yerleri kaç kere gezdim,

Düşününce seni cânımdan bezdim,

Sen oralardaydın inan ki sezdim,

Gezdiğimiz yerleri kaç kere gezdim.

Benim gözyaşlarım hiç bitmeyecek,

Bana hiç bir söz teselli etmeyecek,

Hâyalin se gözümden gitmeyecek,

Gezdiğimiz yerleri kaç kere gezdim.

Şuralarda göz göze oturduk dedim,

Şurada bir demli çay içmiştik dedim,

Şurada da yeminler etmiştik dedim,

Gezdiğimiz yerleri kaç kere gezdim.

Gezdiğim yerlerde hep hayalin vardı,

Şunu bilki ruhumu ince bir sızı sardı,

Şimdi oralarda  bir başkaları vardı,

Gezdiğimiz yerleri kaç kere gezdim.', 'Gezdiğimiz yerleri kaç kere gezdim, Düşününce seni cânımdan bezdim, Sen oralardaydın inan ki sezdim, Gezdiğimiz yerleri kaç kere gezdim. Ben...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gezdigimiz-yerleri-gezdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baykuşun GÖZLERİ', 'baykusun-gozleri-levent-i-skenderoglu-z7zqp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yakında karanlıkta 

Görebileceğini fark edeceksin

Gün ışığı

Vazgeçilmezdir

Ama 

Rüyalarımıza 

Doğan güneş

Us un aydınlığıdır....', 'Yakında karanlıkta  Görebileceğini fark edeceksin Gün ışığı Vazgeçilmezdir Ama  Rüyalarımıza  Doğan güneş Us un aydınlığıdır.......', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/baykusun-gozleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Koridorun Arkadaşlığı', 'sari-koridorun-arkadasligi-hulya-endogan-1jrox', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sarı dar koridorda ilerledim,

İlk önce yavaş yavaş,

Sonra ise hızlı,

Güneşi yanımda hissettim o an,

Sarı rengin bana verdiği duyguyla,

Öyle derinden yaşadım ki o duyguyu,

Anlatılmaz arkadaşlık kurdum sarı rengin duygusuyla,

Sanki güneşin kolları bana uzanır gibi,

Sanki güneşin verdiği ışıkla bana gülümser gibi,

Sanki güneşin o parlak sarı rengiyle dünyamı aydınlatır gibi,

Sanki...

Ve sanki... en sevdiğim oyun sahamı ışıklandırır gibi...', 'Sarı dar koridorda ilerledim, İlk önce yavaş yavaş, Sonra ise hızlı, Güneşi yanımda hissettim o an, Sarı rengin bana verdiği duyguyla, Öyle ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Endoğan']::text[], 8.5, '{"poet":"Hülya Endoğan","poet_slug":"hulya-endogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sari-koridorun-arkadasligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki Sevdiğini Bilmiyormuyum', 'sanki-sevdigini-bilmiyormuyum-yusuf-onder-bahceci-qydrp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen istediğin kadar saklansan,

Sanki sevdiğini bilmiyormuyum,

Sen istediğin kadar gizlensen,

Sanki sevdiğini bilmiyormuyum.

Sen istediğin kadar söylensen,

Benim gönlüm sende yok desen,

Bu adam da zamk gibi be desen,

Sanki sevdiğini bilmiyormuyum.

Sen istediğin kadar hayır desen,

Ben bunu ters anlarım bir bilsen,

Seni gören gözlerime gülmesen,

Sanki sevdiğini bilmiyormuyum.

İstediğin kadar yola bakmasan,

Yollara bakıp ta yola çıkmasan,

Bir sigara yakıpta savurmasan,,

Sanki sevdiğini bilmiyormuyum...', 'Sen istediğin kadar saklansan, Sanki sevdiğini bilmiyormuyum, Sen istediğin kadar gizlensen, Sanki sevdiğini bilmiyormuyum. Sen istediğin ka...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sanki-sevdigini-bilmiyormuyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*En Çok Sen Seviyorsun! (2)', 'en-cok-sen-seviyorsun-2-umut-gul-j20x0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi soğuk bir odadayım

Üşüyor ellerim ayaklarım 

Sadece dudaklarım sıcak

Öptüğünü hayal ettiğim dudaklarım

…

Biliyorum, sende üşüyorsun şimdi 

En çokta ellerin,

Türküler söylüyorsun ısınmak için

Ellerini koyup yüreğinin üstüne

Sevgimle ısınıyorsun

…

Yine o türküyü söylüyorsun biliyorum; 

“ Seviyorum seni,

ekmeği tuzu banıp, yer gibi…

……………………………………..”

Hem söylüyor, hem ağlıyorsun; 

“…atlara su veriyor, daha bir seviyorsun dağları bayırları

güller dikiyorsun ellerimin değdiği yere”

…

Her gül bir özlem oluyor,

Her özlem kor ateş olup,yakıyor  yüreğini

Ama gelemiyorum ben de 

Dindirmeye özlemini 

Seviyorsun beni, ekmek gibi aş gibi

Avunuyorsun sevgimle geceler boyu

Ama biliyorsun bende seviyorum seni

Senin sevdiğin gibi...

…

Her sabah benimle yapıyorsun kahvaltını

Ayırıyorsun bana  yarısını ısırdığın zeytini

Ansızın ben düşüyorum aklına 

Yarıda bırakıyorsun çayını

Dışarı atıyorsun kendini,

Yürüyüşe çıkıyorsun benimle…

…

Hayaller kuruyorsun gün batımında ellerim elinde 

Geldiğim günü düşlüyorsun her aldığın nefesde 

Bir korku giriyor içine gelmeyecek mi yoksa? 

Ölecek gibi oluyorsun gelişim geciktikçe

…

Her akşam yankılanıyor sesim duvarlarında

Duyacak diye birisi kapatıyorsun ağzımı

Sus! Diyorsun,yüreğimle duyarım seni

Sesime dokunuyorsun,

Öpüyorsun  hayalindeki gözlerimi

…

Papatya fallarında arıyorsun teselliyi 

Şarkılardan fallar  tutuyorsun ikimize

Kanadı kırık bir kuş gibisin şimdi

Uçamıyorsun olduğum yere

Ahh..! 

Bir gelebilsem, bir gidebilsem diyorsun

Isıtsam, üşüyen ellerimi sevgisiyle …

…

Akıtıyorsun iki damla göz yaşını 

Yüreğine yapıştırdığın resmimin üstüne

Öpüyorsun sesimi sana getiren telefonu

Kokluyorsun  şiirlerimdeki beni

Ve bastırıp sol yanına, üşüyen ellerini

Haykırıyorsun yürekli; 

En çok ben seviyorum seni! 

…

Biliyorum,  itirazda etmiyorum

En çok  sen SEVİYORSUN beni…', 'Şimdi soğuk bir odadayım Üşüyor ellerim ayaklarım  Sadece dudaklarım sıcak Öptüğünü hayal ettiğim dudaklarım … Biliyorum, sende üşüyorsun şi...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/en-cok-sen-seviyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Gidiyorum', 'aska-gidiyorum-yavuz-bayram-caliskan-69e4h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sevdiğime, ben aşka gidiyorum. 

Dudaklarımdan dökülenlerle, hasret olup çekilenlerle,

 Unutamadığım içimdeki senle, ben aşka gidiyorum. 

Ne tebessümlerini arayacak umutlar,

Ne kulağımdaki sesini.

İçim loş, 

Gözlerim mutluluktan ıslak, 

Yorgun düşürdüğümüz mevsimlere dönde bir bak.

Seninle dolu, ay siyah geceler. 

Hasrete sarılıp, sevgilim derken,

 

Hasretimizi kucakladı askla,

Alın yazımı, kader alnıma çizerken.

Yankılara koştum delice, beni çağıran o kadife sesine.

Her şeyini özledim gecelerde.', 'Ben sevdiğime, ben aşka gidiyorum.  Dudaklarımdan dökülenlerle, hasret olup çekilenlerle,  Unutamadığım içimdeki senle, ben aşka gidiyorum. ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aska-gidiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meğer', 'meger-mahmut-bugrul-fbo7r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdanın yoluna girince erken,

Baltayı bir taşa vurmuşum meğer.

''Bu sevda beni de yakar mı? '' derken,

Ateşi güneşe, sormuşum meğer.

Sevda diyarında seçtim yolumu,

Yüreğimle yaktım tatlı dilimi.

İş işten geçince gördüm külümü,

Dumansız ateşe, varmışım meğer.

Anlatsam derdimi hangi dostuma,

Bir damlacık derman akmaz testime.

Yorganımı dörtte çektim üstüme,

Saatimi beşe, kurmuşum meğer.

İçimdeki sertlik yoktur demirde,

Umudum kirlenir saklı çamurda.

Baharı olmayan kısa ömürde,

Bitimsiz bir kışa, girmişim meğer.

Gönlümde heyecan başladı ilkin,

Cefayı sonradan gördüm ve-lakin.

Anladım bu duygu oldukça tekin,

Yüreğimi boşa, yormuşum meğer.

Çilesiz saadet bulunmaz sandım,

Acıların tamamına dayandım.

Sevda ateşinde yandıkça yandım,

Gözümdeki yaşa, harmışım meğer.

01.02.2006

Milano', 'Sevdanın yoluna girince erken, Baltayı bir taşa vurmuşum meğer. ''Bu sevda beni de yakar mı? '' derken, Ateşi güneşe, sormuşum meğer. Sevda di...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Buğrul']::text[], 8.5, '{"poet":"Mahmut Buğrul","poet_slug":"mahmut-bugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/meger-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekmek Nefsimi Kör Etsin ki', 'ekmek-nefsimi-kor-etsin-ki-sevinc-kavuk-erjcs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ekmek nefsimi kör etsin ki

Sevgimin şahidi olacak kadınım

Verdim ele kendimi uyanık herkes

Ben de uyanacağım ya, hayrola, hele bir sabah ola

Ekmek nefsimi kör etsin ki

Evleneceğim delikanlımla bir kalemde 

Verdim ele kendimi firsatçı töreye, göreneğe

Ben de ayıkacağım ya, hayrola, hele bir şu gün doğa

Ekmek nefsimi kör etsin ki

Hepsi yalan hepsi oyun bunlar

Annemin yeminidir bu hani aceleden

Aman akıllı dur canım kızım diye o ihtarına... /sağol anam 

Ver elini koklayayım doğru mu yalan mı diye 

Saklardım ikisini birden öyle alel acele

Kenetlerdim de arkamda bir güzelce

Sımsıkıca o cici ellerimi.../çocuk mutluluğuma o emeğine

………....kendimi öyle ele verdiğimi yıllarca hiç bilmedim

Tadardım 

gönlümce

doymak bitmeyecesine

o sımsıcak gülücüğü gözlerinde annemin

dudaklarında hayal güzelliği gül o tebessümü

06.02.2006

Saat:    mazide duruyor hepsi

______adeti, töresi, geleneği, göreneği

______çocukluğumda yaşayan o övgü, hoş ihtar

______gözlerimin önünden geçtiler böyle hepsi birer birer', 'Ekmek nefsimi kör etsin ki Sevgimin şahidi olacak kadınım Verdim ele kendimi uyanık herkes Ben de uyanacağım ya, hayrola, hele bir sabah ola...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ekmek-nefsimi-kor-etsin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayıranlara Düşmanım', 'ayiranlara-dusmanim-yusuf-onder-bahceci-728gn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni benden böyle ayıranlara,

Bilki kaderi hep kayıranlara,

Türlü yalanlarla kandıranlara,

Düşmanım ben düşmanım.

Seni ne çok sevmiştim ben,

Utandım da diyemedim ben,

Benim sevgim yüreğimden,

Düşmanım ben düşmanım.

Bilseydim fırsat verirmiydim,

Bilseydim onları görürdüm,

Bilseydim seviyorum derdim,

Düşmanım ben düşmanım.

Kime düşmanım biliyorsun,

Bana sabır sabır diyorsun,

Seni çok sevdim biliyorsun,

Böyle ayıranlara düşmanım....', 'Seni benden böyle ayıranlara, Bilki kaderi hep kayıranlara, Türlü yalanlarla kandıranlara, Düşmanım ben düşmanım. Seni ne çok sevmiştim ben,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayiranlara-dusmanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akp Gömleği', 'akp-gomlegi-mehmet-ayhan-gunaydin-qgrnv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'AKP GÖMLEĞİ

Arkadaşlar mahirdir,

Gömlektir, çıkartırlar.

İyi hoşta, velakin

Giyilen dantellidir.

Bu millete uymazlar.

M. Ayhan Günaydın.

     4 Ocak 2006 

        Ankara', 'AKP GÖMLEĞİ Arkadaşlar mahirdir, Gömlektir, çıkartırlar. İyi hoşta, velakin Giyilen dantellidir. Bu millete uymazlar. M. Ayhan Günaydın.    ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/akp-gomlegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleşir Gider Gölgelerimiz Duvarlara', 'soylesir-gider-golgelerimiz-duvarlara-abdullah-karabag-t8j15', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman sevdalansam kol kola seninleyim,

kıymık kıymık duvar bedenlerinde gezinirim

bazan kısa, bazan uzun sürer kırılmışlığım. 

Hep yanımdasın, söyleşir gider gölgelerimiz,

olmazsan da duvarlar var eder seni,

sana eşlik etmeyi kendime zanaat edinmişim.

Yürümezsek de birleşir gider gölgelerimiz,

bilinen yolları bırak, hiç taşımadılar ki bizi.

Ne bulduysam duvar yazılarında buldum,

korkma, yaklaş, uzat elini, kapa

belki dayanmaz gözlerin duvar kayıtlarına.

Yürü, sevdiğinin kolunda değil misin,

benim değil misin, bana gelmiyor musun; 

dizmediler mi sevgimizi duvar dibinde kurşuna,

yiğit bir delikanlı gibiydi o duvar, çökmedi yere! 

Adımla, sesim eşlik ediyor sana, o duvardayım,

yaklaş umutsuzluğa kapılmadan.

Parmaklarının okşandığı, ayaklarının ağırlaştığı

Ve kalbinin sıcak bir buğuyla ıslanıp yıkandığı

anda dur, çıkarma sesini, kurşun aşka işlemez.

Tüm varlığımla seni bekliyordum, uzat ellerini

gözlerini açmadan, dokun duvardaki yaralara,

elinin öpüldüğü izdeyim.

Güldestan Gibi, toplu şiirler, 2.baskı', 'Ne zaman sevdalansam kol kola seninleyim, kıymık kıymık duvar bedenlerinde gezinirim bazan kısa, bazan uzun sürer kırılmışlığım.  Hep yanımd...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/soylesir-gider-golgelerimiz-duvarlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-ebru-temizkan-tu3xl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dışarıda bir siren sesi 

Etrafta sadece gecenin şehre vuran ışıkları 

Gece

Yalnızlığımı paylaşan çalan müzik olmasa 

Ürktüğüm içimi titreten an 

Yalnızlığım 

Bazen gözlerimi dikiyorum geceye

Arıyorum orada nedenlerimi 

Ama yüreğimi yormaktan öteye 

Gitmiyor bu durum 

Yalnızlığım 

Ne zaman terk eder beni 

Yâda terk eder mi bilmiyorum 

Aslında yalnızlığımı seviyor muyum? 

Onuda bilemiyorum 

Müzikteki Nağmeleri kalabalıkta anlayabilir miyim? 

Yâda günümü etrafımda biri varken tekrar yaşayabilirmiyim 

Anlamalı mıyım çalan müziğin nağmelerini 

Peki, günü tekrar yaşamasam ne olur

Bilmiyorum 

Yalnızlığım 

Denizde oynayan şehrin ışıklarıyla meşk ediyor şuanda 

Gözlerim yalnızlığıma ihanet ediyor 

Çünkü bir çift göz arıyor yalnızlığını paylaşacak.

Ve bu arayışta yüreğim yine yoruluyor 

Yalnızlığım 

Yorma yüreğimi 

Yalnızlığım 

Bırak nağmeleri anlamayayım 

Yalnızlığım 

Bırak günü yaşamıyım 

Yalnızlığım 

Bir çift göz bulayım izin ver

Yalnızlığım 

Bırak beni 

Yalnızlığım 

Anlamıyor musun? 

Yalnızım…

Ebru Temizkan

26.12.2005', 'Dışarıda bir siren sesi  Etrafta sadece gecenin şehre vuran ışıkları  Gece Yalnızlığımı paylaşan çalan müzik olmasa  Ürktüğüm içimi titreten...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yalnizligim-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'V'' li Şiir', 'v-li-siir-sadik-altinkaynak-udn7r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'V’ li Şiir

Van’ lı

Varyemez Veli

Vergi vermezdi

*

Van Valisi 

Veli’ ye vade verdi

*

Veli Van’ ı 

Velveleye verdi 

Vergi vermedi

*

Vali Van Vaizine 

Vazife verdi

Vaiz de 

Veli’ ye vaaz verdi:

-Veli vergi vatani vazifedir

Varlık Vatana vakfedilmelidir

Vakarınla vergini ver...

*

Veli vergi vermedi

Vali Veliye verdi veriştirdi; 

-	Vahşi Veli! 

Vergi vermemek vefasızlıktır

Ve/de vahşettir

*

Veli vıcık vıcık vınladı

Ve/lakin vergi vermedi...

Ve/nihayet

Vadesi /yetti

Vefat /etti

Veledi Veysi

Veliye vekâleten

Vergiyi verdi...

            Sadık ALTINKAYNAK', 'V’ li Şiir Van’ lı Varyemez Veli Vergi vermezdi * Van Valisi  Veli’ ye vade verdi * Veli Van’ ı  Velveleye verdi  Vergi vermedi * Vali Van V...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/v-li-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke...', 'keske-elif-erdem-foec2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Keşke...

Gözlerinde mutluluktan akan bir yaş olsam

Tenini okşayan rüzgar olsam

Seni saran gece olsam

Ve ardına dönüp bakmadan giden ''sen'' olsam...

Keşke...

Yeniden gittiğin yar olsam

Canını yakan yara olsam

Bir nefeslik canın olsam

Ve ardından dizelerle uğurlanan ''sen''olsam...

Keşke...

Bir sevgili olsam senin için 

Özlenen ve hatırlanan; 

Bir dilek olsam sana ait

Hep istenen ve beklenen; 

Bir ümit olsam sadece senin

Sensizliğimin biteceğine dair...

Keşke...

Beni benden alan bir ''sen'' olmasa

Keşke sensizken dünya dönmese, zaman dursa

Hayat sadece seninle yaşansa, güneş seninle doğsa...

Keşke...

Geceler kolay; sensizlik umarsız bir yanlızlık olmasa,

İçimde fırtınalar olmasa,gözlerim hiç dolmasa

Sözlerin hafif olsa, canımı acıtmasa 

Ve ''keşke''  ile başlayan cümlelerim seninle sonlanmasa

Sensizlik esareti dinmeyen kabus, seninle olmak sadece bir rüya olmasa...', 'Keşke... Gözlerinde mutluluktan akan bir yaş olsam Tenini okşayan rüzgar olsam Seni saran gece olsam Ve ardına dönüp bakmadan giden ''sen'' ol...', ARRAY['Türk Edebiyatı','Şiir','Elif Erdem']::text[], 8.5, '{"poet":"Elif Erdem","poet_slug":"elif-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/keske-127-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiceğim', 'sevdicegim-i-brahim-yavuz-3hg3w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah o nazlı nazlı gülüşün var ya

Kurdun şu gönlüme taht sevdiceğim

Gülmek istiyorsan yalan dünyada

Baht gerek insana baht sevdiceğim

Hayallerin gerçek olması için

Yüreğine huzur dolması için

Mutluluğun bizi bulması için

Baht gerek insana baht sevdiceğim

Neye baksam gözüm seni arıyor

İçimi bir garip hüzün sarıyor

Dürüstlük doğruluk neye yarıyor

Baht gerek insana baht sevdiceğim

Bir imtihandayız biz bu okulda

Zenginde, fakirde, yetimde, dulda

Hiç gözün olmasın parada pulda

Baht gerek insana baht sevdiceğim

İçimde bir aşkın kördüğümü var

Kör talih yüzüme güldüğümü var

Şu feleğin bizi gördüğümü var

Baht gerek insana baht sevdiceğim

İbrahim dünyadan dersini aldı

Her gün ayrı bir dert kapımı çaldı

Bizim kavuşmamız mahşere kaldı

Baht gerek insana baht sevdiceğim', 'Ah o nazlı nazlı gülüşün var ya Kurdun şu gönlüme taht sevdiceğim Gülmek istiyorsan yalan dünyada Baht gerek insana baht sevdiceğim Hayaller...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdicegim-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavişlenen Aşklar', 'mavislenen-asklar-abdullah-karabag-1czu4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Robotların sergisinde baş robotlar

Baş robotların oturumunda putlar sürüsü

Yazgıların üleştirilmesinde

Bir acayip küçültmüşler

Yaratıcı üreticileri tanrılar sürüsü

Söylenir hiçlenir söylenir

Ununu elemiş duvara asmış eleğini

Hasretinden gözleri mor halkalı

Parklı köşkün saygın hanımı

Hiçlenir söylenir hiçlenir

Meşguliyetsizlik

Günde bir tırnağını kestirir

Kalın keser ince keser eğeler ojeler

Şaşaalı parkın köşklü hanımı

Acılanır hislenir acılanır

Süpürür köşkün içini dışını

Solur hanımın parfüm kokusunu

Mengili selvilerin navişli gülşeni

Parklı köşkün mutsuz hanımı

Aşklarını gezdirir gezmelerinde

Doyumsuz sevişmelerin sahnelerini

Buruk ayrılıkların yanık karelerini

Hislenir acılanır hislenir söylenir

Bond çantalı tek çekli çok hesaplısın

Cüzdanı dolu dolu boş kartlısın

Bir acayipsin vefasız sevgilim

Hazan gezmelerimde yâr uyaklısın

Parklı köşkün saygın hanımı

Elemiş köşkün içine dışına

Mor halkalı gözlerin öyküsünü

Söylenir süpürür selvilerin mavişli gülşeni

Bir acayipsin büyük hanım

Bir acayip sevmişler seni

Bir acayip derde salmışlar seni.

Güldestan Gibi, toplu şiirler, 2.baskı', 'Robotların sergisinde baş robotlar Baş robotların oturumunda putlar sürüsü Yazgıların üleştirilmesinde Bir acayip küçültmüşler Yaratıcı üret...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karabağ']::text[], 8.5, '{"poet":"Abdullah Karabağ","poet_slug":"abdullah-karabag","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/mavislenen-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-sair-xeyalfiros-2cfdt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uğramak isteyince neferleriyle ölüm 

Yüreğimin cennet şehirlerine 

Seni davet ettim senden habersiz düşüncelerime 

Saldırınca çirkinliğin talancı orduları 

Seni umut ettim ve savaştım ama yılmadım 

Hala Umutsun ve ben hala savaşıp 

Güzelleşmek için seni yaşamak için yaşamaya gayret ediyorum

Seni düşünmek yaşadığımın bilincine varmaktır', 'Uğramak isteyince neferleriyle ölüm  Yüreğimin cennet şehirlerine  Seni davet ettim senden habersiz düşüncelerime  Saldırınca çirkinliğin ta...', ARRAY['Türk Edebiyatı','Şiir','Şair Xeyalfiros']::text[], 8.5, '{"poet":"Şair Xeyalfiros","poet_slug":"sair-xeyalfiros","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasam-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Galiba…', 'galiba-aydin-tutcali-jvvzr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu şiir''i sevipde birleşemeyen ve bu aşkı hiç untmayanlar için yazmıştım.', 'Bu şiir''i sevipde birleşemeyen ve bu aşkı hiç untmayanlar için yazmıştım....', ARRAY['Türk Edebiyatı','Şiir','Aydın Tutçalı']::text[], 8.5, '{"poet":"Aydın Tutçalı","poet_slug":"aydin-tutcali","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/galiba-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kışla', 'kisla-mehmet-zeki-gezici-rykvm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüzümüz sevdanın ve hasretin

ve dağlarında suçlu bir adam gibi 

vurulmuş çıplak üç cesedin

deliren sakallarından biçildi.

Biz sevdayız

bu mevsim üç bahar görmüşüz

üç kuru dalda

dört mevsim açan.

Yenilginin ve cesaretin

ve umudun bile ansızın

perişan ettiği kışladan

sokaklar mühürlenince akşamları

kurtuluştan kalma paslı bir hançerin

yanına uzatmışız

birden patlayacak gövdemizi.

Alışınca dar geliyor

insana dağlar

içimizde yırtılan kuş seslerinden

acının parmakları gibi

göğsümüzü kuşatan mermilerden

adam öldürmenin

sevdalısı değiliz

kanatları kırpılmış

hüznün kuşlarından

akıp gidiyor yaşamak

akıp gidiyor...', 'Yüzümüz sevdanın ve hasretin ve dağlarında suçlu bir adam gibi  vurulmuş çıplak üç cesedin deliren sakallarından biçildi. Biz sevdayız bu me...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kisla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Seni Anlatsam', 'sana-seni-anlatsam-salih-ozalasan-fuzav', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana seni anlatsam

Neresine koyacağım hasreti

Hayatta bir sana bağlansam

Nasıl yeneceğim gurbeti

Ben bir serseriyim desem

Dersin serseri bilmez sevmeyi

Dağı taşı un ufak etsem

Gösterirsin bana tımarhaneyi

İki arada bir deredeyim

Sevdan ile bir pervaneyim

Rüzgar esiyor senden yana

Yönümü hep sana dönmekteyim

Anlatamam seni sana

Aklıma sen düştüğünde susmaktayım

Yürekte olmak yetmiyor cana

Sevdan ile cana kıymaktayım

Sana bir hikaye anlatsam

İçinde olsa sadece sevgim

Romana döner bir yerde dursam

Çünkü romanın sayfaları kâlbim

Anlatamam sana seni mümkün değil

Sevdaya düşmüş bir yürek taş değil

Bir uçurumun kenarındayım sanadır meyil

Her cümleyi sana methiye yazmak hoş değil

Sanacaklar ediyorum şimdi sana yağcılık

İdam mahkumu olacağım ipimi çekecek savcılık

Söz gelmeyecek hiç savunmaya yok haklılık

Müebbede razıyım o sadece bedensel ayrılık

Velhasıl zor gözleri abı hayatı anlatmak

Dilinden dökülen cümleye ne mümkün tat katmak 

Güneş ve kar resimlerde ancak birlikte yaşatmak

Bir kardelene güneşi sevdirmek kolay değil

Y.Tarihi 15-01-2006 Saat 01,40

Salih ÖZALAŞAN', 'Sana seni anlatsam Neresine koyacağım hasreti Hayatta bir sana bağlansam Nasıl yeneceğim gurbeti Ben bir serseriyim desem Dersin serseri bil...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sana-seni-anlatsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Aşk Olsa Gerek', 'adi-ask-olsa-gerek-baran-demir-2hfd1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bilsen nasılda güzel bakmakta 

Gözlerin sanki uçsuz bucaksız okyanuslara

Bakar gibi yem yeşil, 

Öylesine masum öylesine güzel ki

Suskunluğunu anlatırcasına 

Gülümsüyorum, 

Seni yeni tanımıştım oysa

Esaret bu olsa gerek

Tutuldum alı koyamıyordum

Gözlerimi senden 

Adı aşk olsa gerek 

Sen,gözlerin birde ben

Bakmakta ya, sessiz sessiz 

Seni bana anlatmakta 

Yüreğini anlatır gibi

Bazen ağlamaklı

Yağmuru anlatıyor,

Bazen de sevinçli

Güneşli günleri anlattığı gibi,

Karamsar bakmamalı 

Zifiri karanlık gibi,

Hep yeşil yeşil bakmalı

Baharı anlatır gibi', 'Bir bilsen nasılda güzel bakmakta  Gözlerin sanki uçsuz bucaksız okyanuslara Bakar gibi yem yeşil,  Öylesine masum öylesine güzel ki Suskunl...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/adi-ask-olsa-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Direniyorum', 'direniyorum-ayse-hazal-beytas-l0qcq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öldürür beni bu sevda 

Biliyorum.

Ölürüm ölmesine ama,

Daha türkü dinlemeye doymadım.

Direniyorum...', 'Öldürür beni bu sevda  Biliyorum. Ölürüm ölmesine ama, Daha türkü dinlemeye doymadım. Direniyorum......', ARRAY['Türk Edebiyatı','Şiir','Ayşe Hazal Beytaş']::text[], 8.5, '{"poet":"Ayşe Hazal Beytaş","poet_slug":"ayse-hazal-beytas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/direniyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabirde bir gece', 'kabirde-bir-gece-reyhan-tataroglu-bt4tz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Korkunç bir gece 

                   Günahların omuzlara çöktüğü

                   Yağmurların gözyaşları döktüğü

                   şimşeklerin gökleri söktüğü

                   Korkunç bir gece bu gece

                            Korkunç bir gece

                   Karanlıkların aydınlıkları ezdiği

                   Kimsesizlerin yalnızların gezdiği

                   Umutların umutsuzluklardan bezdiği

                   Korkunç bir gece bu gece

                            Korkunç bir gece

                   Hayellerin pembelerde yüzdüğü

                  Gerçeklerin siyahlarla büzdüğü

                  Düşmanlıkların dostlukları üzdüğü

                  Korkunç bir gece bu gece

                            Korkunç bir gece

                  Hesapsızlıkların hesapları çektiği

                  Kötülüklerin iyilikleri  ektiği

                  Yanlışların doğrulardan sektiği

                  Korkunç bir gece bu gece

                           Kokunç bir gece

                  Virgülün noktaya konduğu

                  Güneşin buzlarla donduğu

                  Ayın zamanda kaybolduğu 

                  Korkunç bir gece bu gece

                        Korkunç bir gece

                  Ölümün hayatı sevdiği

                  Maddenin manaya geldiği

                  Toprağın bedeni deldiği

                  Korkunç bir gece bu gece', 'Korkunç bir gece                     Günahların omuzlara çöktüğü                    Yağmurların gözyaşları döktüğü                    şimşek...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kabirde-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Müslüman Gibi Doğrul', 'ya-musluman-gibi-dogrul-durmus-kaya-ucn7r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Din kardeşimin canı incise

Bir fermanla  dize getirirdim

Frengistanı! 

Bağırmazdım

Çağırmazdım,

Kılıç sallamazdım

Silah  sıkmazdım hayaletlere…

Edirne’den Hind’i Çine 

Bize neler oldu? 

Bana  neler oldu 

Bu soru bana asıl! 

Dolarlara doğru

Ağzı sulu giderken

Gerçeği görmek nasıl? 

Bir kafirin eli

Dokunmuş peygamberime! 

Günaydın gülüm,

Atı alan Üsküdar’ı çoktan geçti,

Günaydın Mekke’ye

Medine’ye…

Günaydın Kahire’ye, Taşkent’e

Günaydın Almatı’ya, Bakü’ye,

İstanbul’a,

Ankara’ya, başkent’e! 

Günaydın! 

Sevginin iri  başağı

Güneşin ışığı,

İlimlerin beşiği sendin! 

Kanımla gönlümün bileşiği sendin! 

Günaydınlar sana

Günaydınlar,  ehli  İslam’a,

Türkiye’ye  İran’a Mısıra,

Suud’a! ...

Nerdesiniz? 

Neden çıkmıyor sesiniz? 

Sesiniz şeytana taş atmak kadar cılız,

Sataşmak kadar  gülünç! 

Giden gitti atlarını

Ay’da sulamaya! 

Tepki, elçilikler basmakla mı

Papazları asmakla mı,

Sandıklarda susmakla mı? 

Nerde bir lokma bir hırkanız? 

Nerde  önünüz arkanız? 

Şeyhleriniz

Şıhlarınız! ! ! 

Öyle meydanlarda 

Yuh’lamak ayıp! 

Demek ki özün

Yüreğin kayıp! 

Belli değil ki zaten

Sen ne yandasın! ? 

Niçin bunca hezeyandasın? 

Belki beş yüz senedir

Günün gününden eksik

Ziyandasın! 

Sen içir  petrolünü

Amerikanyaya

Git İspanya’da donsuzlarla ol! 

Dinsizlerle

Densizlerle ol! 

Ve ipini ver Lavrens’e,

İsviçre’de havyar

Paris’te  ense! ...

Peygamberime  söven

İpsiz mesnetsiz şoven

Ve şeytan! …

Şeytan senin içinde! 

Yüreğinde kışlattığın,

Hacılara taşlattığın,

Yemlediğin,

Beslettiğin

Şeytan senin içinde! 

Osmanlı’yı kesen sensin,

İblis gibi susan sensin,

Sonra da

Filistin’de

Bağdat’ta

Kan kusan sensin,

Ben ne deyim gardaş sana,

Git kendini at Umman’a! 

Alnında kara lekeyle,

Ya Kızıldeniz’de boğul

Ya Müslüman gibi doğrul!', 'Din kardeşimin canı incise Bir fermanla  dize getirirdim Frengistanı!  Bağırmazdım Çağırmazdım, Kılıç sallamazdım Silah  sıkmazdım hayaletle...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Kaya']::text[], 8.5, '{"poet":"Durmuş Kaya","poet_slug":"durmus-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/ya-musluman-gibi-dogrul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara/rını ver', 'kara-rini-ver-reyhan-tataroglu-i1vxd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'keşke! 

                   aydınlıklarda gösterdiğin 

                   cesareti...

                   karanlıklarda da gösterseydin

                   aaah! ...

                   karanlıkların güzelliğini bir görseydin', 'keşke!                     aydınlıklarda gösterdiğin                     cesareti...                    karanlıklarda da gösterseydin       ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kara-rini-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Olur Doğarım', 'gunes-olur-dogarim-sevinc-kavuk-nmpvi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Maziye şöyle bir bakılsa da 

Özlemler saygıyı selam dursa 

Geleceğe aydın ümitler yarına

Bir dün ışığı bugünü nakışlasa

olsa, olsaydı ya… 

Ahh be karamsarlık, şu senin karalığına 

Güneş olur doğarım da

Yok olmasan bile bari yarasın kör olmana 

karnı aç, soytarı, zengini 

barış adına savaş zevkini 

beyni aç kimilerini 

güçlenme güdü hırs keyfiliği 

vicdanı aç inatlığın sümsük sinek vızıltısını...

Bu gürültü bu curcuna bir yana

Var şu medeniyet ya… 

Hey gidi dünya ne diyeyim, sen aldırma

Sen keyfine bak, sen yaşa...

Ben, ben de… 

Az kaldı tohumun çatlamasına...

06.02.2006 

Saat:__Karamsarlık ve ben 

______ne ben onunla, ne o benimle sevişemeyiz

______ökçemde sürür durur, ayrılmayız da

______gör şirin sevgili demeye taş yarılır, şaşı bile olmayız

______insanlığa yürek ister, mangal kullanmaya alışırız

______varlığı ve bütünlüğü azalttık, sürtüklüğe çoğaldık coşarız

______sürtük ağası semirdikçe biz de geğirmeye başlarız

______azınlık çoğunluk der bir de dansına yuvarlanırız

______sus be canım yüreğim, taş yarılıyor vicdan tınmıyor 

______git taşa yarenlik et sen... puta tapmak böyle mi oluşmuş yoksa? 

______nerde kalabalık var orda sosyallık kokuşuyor, yanaş ha yanaş.... 

______doğru... savaş artık kusuyor...', 'Maziye şöyle bir bakılsa da  Özlemler saygıyı selam dursa  Geleceğe aydın ümitler yarına Bir dün ışığı bugünü nakışlasa olsa, olsaydı ya…  A...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gunes-olur-dogarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda İçinde', 'sevda-i-cinde-mehmet-zeki-gezici-3zaav', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ekmek içinde

sevda tşırmış Piraye

benim Gülüm sevda içinde

bir tas çorba getirdi Bursa''ya..

Ha Piraye İstanbul kızı

ha benim Gülümün kızı İstanbul.', 'Ekmek içinde sevda tşırmış Piraye benim Gülüm sevda içinde bir tas çorba getirdi Bursa''ya.. Ha Piraye İstanbul kızı ha benim Gülümün kızı İs...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevda-icinde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep geceleri,', 'hep-geceleri-levent-i-skenderoglu-7s2fv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep geceleri, karanlıkları yazarım şiirlerimde

Bilmem nedendir? 

Ruhumun bu karanlık sevdası

Kör bir yılan ve gece

İri bir örümcek ağı ve karanlık

Zihnim  ne zaman karışsa 

Ne zaman canım bir dost sohbeti istese

Ve bulamazsam

Ve korkular, bebek çığlıkları duysam

Olur, olmaz....

Hep kapkara duygulara

Kilitlenir kalemim

Oysa hep söylediğim gibi

Ben beyazı severim

Güneşe sevdalığım

Bir kuşun kanat çırpışında

Ve helezonlu kelebeğe

Birde beni en iyi anlayan bebeğe

İçim sevgi dolu insanlık dolu

Keskin bir hançer

Gümüş bir cep saati

Ve zaman

Uzayda zihnimi dolduracak

Bir nesnenin varlığı yeter bana

Sabahın ilk ışıklarıyla

Bir dost yüzü görmek

Bir dost sesi duymak

Ne güzel şey

Bir merhaba, gülen gözler

Yeter bana', 'Hep geceleri, karanlıkları yazarım şiirlerimde Bilmem nedendir?  Ruhumun bu karanlık sevdası Kör bir yılan ve gece İri bir örümcek ağı ve ka...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hep-geceleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Kuş', 'mavi-kus-nilgun-acar-d4e57', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Görüyorsun onu gözlerimde

Promete''nin yaktığı ateş

karanlık soğuk gecelerde

hiç sönmeyen güneş

çiçeklerin sereserpe uzandığı

yumuşacık gizemli öpüş

ipek ve sabır yüklü koza

tırtıldan kelabeğe dönüş

İnançla elele damlalar

okyanuslarca yaşama gebe bütün

soruların yanıtları içinde

durmaksızın koşuyor gün

taşıyor koynunda evreni

yemyeşil buğulu bir tohum

avuç çizgilerimde okunuyor

kanat kanat mavi kuşum', 'Görüyorsun onu gözlerimde Promete''nin yaktığı ateş karanlık soğuk gecelerde hiç sönmeyen güneş çiçeklerin sereserpe uzandığı yumuşacık gizem...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Acar']::text[], 8.5, '{"poet":"Nilgün Acar","poet_slug":"nilgun-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mavi-kus-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabirin Gücü', 'sabirin-gucu-gultekin-toga-ius3z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üstüme üstüme gelme,

Israr etme, üsteleme,

İçimdeki dünyadayım,

Rahat bırak hiç elleme..

Gözlerimi yumuk bırak,

Başım eğik yamuk bırak,

Beni dünyamın içinde

Dibine dek gömük bırak..

Oğul.. gönül yurdu oğul,

İçimin dert kurdu oğul,

Eldir işte seyran eder,

Acılarımm verdi oğul.

Sentezi yangın içinde,

Beyazlar süstür saçında,

Hala ayakta dimdikse

Huzur sabırın gücünde....', 'Üstüme üstüme gelme, Israr etme, üsteleme, İçimdeki dünyadayım, Rahat bırak hiç elleme.. Gözlerimi yumuk bırak, Başım eğik yamuk bırak, Beni...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sabirin-gucu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultan', 'sultan-mehmet-zeki-gezici-cl7ss', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dilim ıslatsın yüreğini

geyiklerin serin ve gergin

boyunlarında yol alsın geceler.

ikiye ayrılmış kaderin

birinde sen gideceksin

diğerinde seni çürüten hayallerin.

Bir ölümden sonra yakılacak

aşk adresleri bıraktın kafir.', 'Dilim ıslatsın yüreğini geyiklerin serin ve gergin boyunlarında yol alsın geceler. ikiye ayrılmış kaderin birinde sen gideceksin diğerinde s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sultan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temeldekiler', 'temeldekiler-gultekin-toga-6ydk6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tesadüfle gelmiyor ki başarı

             İnanç,azim,basirettir temeli.

             Bazen içe doğru,bazen dışarı,

             İnce hesap küsürattır temeli.

          

             Kokrak kuş avıdır alıcı kuşun,

             Mimarı var her yapının, her işin,

             Gercekleşen hayel,canlanan düşün,

             Bir adanmış cesarettir temeli..

           

             Sentezi, boşuna değil ki acın

             Tadı acı imis emin,ilacın

             Ferhat´a dağları deldiren gücün,

             Gerçek aşka hasirettir temeli..', 'Tesadüfle gelmiyor ki başarı              İnanç,azim,basirettir temeli.              Bazen içe doğru,bazen dışarı,              İnce hesap k...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/temeldekiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Biri Beni Bana Anlatsın*', 'biri-beni-bana-anlatsin-ozkan-sahin-ekydr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'açılıyor du birer birer kapılar

teker teker girdim içeri

anladım ki çıkar var! 

hiç biri bana göre değil

çarpıyordum çıkarken....

anladım ki her şey ben de gizli

kendimi kendime yasak etmişim

özgürüm diye bir de gezermişim

bu çark  böyle dönmez! 

kimliğim beni bana doğru anlatmaz

insanların arasın daki tek fark

yaşam da tarz

ve ben buna ters düşmüşüm

çok dostum çok arkadaşım var

ama hiç biri beni bana anlatamıyor

kimseye kendimi anlatamadım ki bir kere

sokaklar aydınlıkmış, karanlıkmış

umrumda değil 

kötülükten değil, iyilikten yargılanmışım

korkmam ben bana olacaklardan

ardımdan yapılan dedikodulardan

düşman olanlardan

dostlarımdan

kendimden başka kimseden korkmam

uzun yollara düştüm yıllarca

huzuru aradım sevgiyi...

yaratılış, tevrat, mezmur, incil, kuran ve vs. vs.

okudum okudum

yaşamı Allahı anlamak için

yetme di beni bana etmedi

tersi beni benden uzak etti

tarihti hepsi kanlı ve kanatmaya devam eden

kendimi kendime yasak etmişim

ne sevgi ne huzurmuş aradığım

benmişim ben

biri beni bana  anlatamadıktan sonra

huzurlu olsam ne çıkar

kendi hatalarını görmeyen

benim yanlışlarıma nasıl saldırırsın

kendini anlamayan biri

beni bana nasıl anlatsın

her şey bende gizli

kendimi kendime yasak etmişim

bir kere.

                   -1-2-2006-', 'açılıyor du birer birer kapılar teker teker girdim içeri anladım ki çıkar var!  hiç biri bana göre değil çarpıyordum çıkarken.... anladım ki...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/biri-beni-bana-anlatsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Güller ve Sen', 'kirmizi-guller-ve-sen-mehmet-ozer-58nxo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne zaman ki sen gittin

Ben o günden sonra

Kırmızı güllerden nefret ettim

Kar yağmaya başladı gecenin üzerine

Yorgan oldu yollara

Aldı karanlığı götürdü uzaklara

Beyazı hatırlattı yorgun gözlerime

Ve seni…sesini…tenini…

Düşlerimizi anımsattı

Çünkü ilk defa seni seviyorum dediğinde

Üzerimize tane tane düşmüştü kar

İlk defa sarıldığımızda

Dudaklarının  sıcaklığını tattığımda

O alyansı uzattığımda

Parlamıştı bembeyaz parkın ortasında

Sen evet dediğinde 

Yıldızlar dansetti ayın etrafında

Koca çınarın yaprakları yeşerdi

Güller açtı kışın ortasında

Ne zaman ki sen gittin

Ben o günden sonra

Kırmızı güllerden nefret ettim

Açmasın istedim

Yeşermesin hiçbir ağacın yaprağı

Bahar gelmesin hiç

Ve yağmasın kar

Engel olamadım ne çiçeklere

Ne ağaçlara

Ne de yağan kara

O yüzden yorgun gözlerim

Tüm sonbaharı uykusuz geçirdim

Kışı ve baharı görmeden

Ne kadar uykuya dalabilirim diye

Ama düşlerime de engel olamadım

Gözlerim ne zaman kapansa

Gözlerini gördüm

Saçlarını sevdim

Anladım ki; 

Ne ben senden kopabilirim

Ne de hayata küsebilirim

Tek bir şansım vardı

Ona da cesaret edemedim

Ne zaman ki sen gittin

Ben o günden sonra

Kırmızı güllerden nefret ettim…', 'Ne zaman ki sen gittin Ben o günden sonra Kırmızı güllerden nefret ettim Kar yağmaya başladı gecenin üzerine Yorgan oldu yollara Aldı karanl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kirmizi-guller-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Öp', 'simdi-op-gultekin-toga-mfc9o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hangi güldür o solmaz,? 

             Hangi kuldur o ölmez?                   

            Yarının ardı gelmez,

            Yapacaksan şimdi yap.

            Temizdir insan baştan,

            Sanma ki kalbi taştan,

            Her türlü çirkin işten,

            Sapacaksan şimdi sap.

            Gör garibin işini,

            Kolaylaştır kışını,

            Bir öksüzün başını,

            Öpeceksen şimdi öp.

            Ermek icin felaha,

            Ne bekliyon ne daha,

            Tam hakkıyla  Allah´ a

            Tapacaksan şimdi tap..

            Sentezi ağır ağır,

            Su damladan coşalır,

            Nefsin arzusunu kır,

            Kopacaksan şimdi kop..', 'Hangi güldür o solmaz,?               Hangi kuldur o ölmez?                                Yarının ardı gelmez,             Yapacaksan şimdi...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/simdi-op-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnat', 'i-nat-gultekin-toga-ehlc7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur eşit yağar,adil dökülür,

Toprak kucak açar,taş inat eder..

Dizde derman kalmaz belde bükülür,

Gönül hiç kocamaz baş inat eder..

Istırap avcisi,ağ gibi ömrüm,

Kurt sürüsü girmiş bağ gibi ömrüm

Rakımı sekiz bin dağ gibi ömrüm

Bahar nasıl gelsin,kış inat eder..

İlk bakışta göze çarpan zarardır,

Lakin tecrübesi hayata kardır

Dolu yüreklerde sukunet vardır

Kuru gürültüye boş inat eder..

Sentezi aşıka düzdür yokuşlar,

Maşukun yolunda donmuş bakışlar,

Güze doğru göçer, yaylacı kuşlar

Karga,serce adlı kuş inat eder,', 'Yağmur eşit yağar,adil dökülür, Toprak kucak açar,taş inat eder.. Dizde derman kalmaz belde bükülür, Gönül hiç kocamaz baş inat eder.. Istır...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/inat-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonrası', 'sonrasi-muhammed-mehmet-gul-fujo3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '*******************************************Sorma neydi adım

************************************Kimseye uğramadan sana uğradım

*****************************İstersen halimi hayra yorsunlar

**********************İstersen beni vursunlar

*****************Sonra sonra,sorma

************Sonrası güç', '*******************************************Sorma neydi adım ************************************Kimseye uğramadan sana uğradım *************...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sonrasi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senmiydin', 'senmiydin-i-lhan-altin-7fp3b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensiz,sevgisiz yaşıyorum,

Senle kurduğum dünyamda,

Uyandım bir bir rüyalarımdan,

İşte yalnızlığım,sensizliğim...

Oysa ne güzeldi gözlerinde yaşamak,

Bir dünya yaratmak yıkıntılardan, sevgiden,

Sıcaklığında ben ve küçük mutluluklar...

Sevmek çok güzeldi seni sevgilim.

Senmiydin? 

Baharım, umutlarım, uğruna çırılçıplak kaldığım,

Aldandığım, çocuklar gibi inandığım...

Sevgilim senmiydin? 

Belkide gerçek sensin sevgilim...

Karanlık, yalnız gecelerim gibi,

Kırık hayallerim, yüreğim gibi

Yalan bir dünyaydı benimkisi,

Oysa ne güzeldi sevgilim,

Gözlerinde yeni bir dünya yaratmak.', 'Sensiz,sevgisiz yaşıyorum, Senle kurduğum dünyamda, Uyandım bir bir rüyalarımdan, İşte yalnızlığım,sensizliğim... Oysa ne güzeldi gözlerinde...', ARRAY['Türk Edebiyatı','Şiir','İlhan Altın']::text[], 8.5, '{"poet":"İlhan Altın","poet_slug":"i-lhan-altin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/senmiydin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çok Şey Kaçırmışız Seninle Baba', 'ne-cok-sey-kacirmisiz-seninle-baba-sevgili-ozbek-k61et', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Takvimlerde sakladığımız mevsimler 

Uzun bir telaşın dalgınlığında

Gün görmeden koparılan yapraklar gibi 

Geçen ömrümüzün farkına vardık mı baba 

Alınan her nefes 

Zamanın duruşudur avuçlarımızda ve

Belleğimizde peyda olan geçmiş ayrıntılar 

Hangi anlamı kuşanabilir, anlayabildik mi baba 

Sana söyliyeceğim o

Geçmiş günlerden sakladığım 

Sözsüz dünyamı söylemek yerine 

Sunmak isterim gündüz gibi 

Ateşin korundan

Gül bohçasından kırmızı, 

Servetinden erdemin

Bir demet gül baba, bir demet gül 

Ah

Ne çok şey kaçırmışız seninle baba 

Yosunlu taşların yüreği değirmen ikliminde 

Hayat, kozasını örerken öğütülen taneler de 

Yeşil kalmışız hani pişmeyen soyut fikirlerden 

İsyanlarını beceremeyen bakışlarımızda 

Yaşamışız öylece bilgisiz, isteksizce doğduğumuz gibi 

Ve özleyişlerimiz gömülü kalplerimizde 

Ne çok şey kaçırmışız seninle baba 

Ne çok şey 

Sevgimiz, salt alaturka dağlar gibi topraktı 

Şefkatimiz, hasat sonrası aldığımız tahıl 

Çalışkanlığımız akıtılan tuzdu alın terimizde 

Ekmek parası nasırlı ellerimizdi kanayan 

Ve devrilen günün ardından sadece 

Bir aferin duyabilmekti ödülümüz 

Ve 

Daha daha 

Ne çok şey kaçırmışız seninle baba 

Şefkatin rengini solgun çizmişiz sarmaş dolaş 

Bihaber, nakşetmişiz gülün kırmızı çizgilerine 

Her vakit, aynı sabah yelinin serinliğinde 

Tutarsa tutsun misalinden sulamışız fidanları 

Koyuvermişiz kılavuzsuz, çalıntı bedbaht hayatı 

Ve saf kaynağından da olsa akan derenin 

Suyu 

Kalbur kalplerin bakracını dolduramaz 

Herşey vaktinde doldurulmalıdır ve yaşanılası 

Ki 

Gök yüzü yorganımızdı başka ne vardı bilecek 

Dikiliğdi kör iplikle dört bir yanı yıldızların 

Bilinçsiz kokuyordu herşey çobaniğnesinde 

Kardelenlerde kural doğduğumuz gibiydi 

Serpildik doğduğumuz gibi gölgesinde şafağın 

Ve bizim için 

Harmanlarda hasatlar bitti artık baba 

Saklanan kavramlarda büyüdük 

Sıradan yeni bir yaşama geçerken yüz yıl adına 

Duygularımız nasırlaştı bu sefer ellerimiz gibi 

Baba 

Yanlış hatalar zincirinden 

Seninle kaçırdığımız günler adına 

Şöyle bir onbeş, yirmi yıl daha 

Bizi mutlu kılar mı 

Yukarıda vadettiklerimden veremesem de sana 

Benden de bu şiir, sefil ama olsun 

Ve arzu ettiğin gibi 

Sevgili kızın nazım karalıyor baba 

Ellerinden ellerinden öperim 

06/02/2006', 'Takvimlerde sakladığımız mevsimler  Uzun bir telaşın dalgınlığında Gün görmeden koparılan yapraklar gibi  Geçen ömrümüzün farkına vardık mı ...', ARRAY['Türk Edebiyatı','Şiir','Sevgili Özbek']::text[], 8.5, '{"poet":"Sevgili Özbek","poet_slug":"sevgili-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/ne-cok-sey-kacirmisiz-seninle-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Örtüyor…', 'kar-ortuyor-nurettin-gumusbas-xw48c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kar örtüyor artık izlerini 

Ve yavaş yavaş bulanıklaşıyor hayalin 

Beyaz değil kar, mavi değil gökyüzü 

Düşlerim gibi yeşil değil toprağın örtüsü 

Hiçbir şey gerçek değildi 

Sana olan aşkım kadar 

Sevgim kadar 

Yüreğim kadar... 

Kar örtüyor artık seni 

Hayalini, gözlerini 

Ve benim aşkımı... 

Bir sen olduğunu düşünmüştüm 

Bir bizim aşkımız 

Bir yıldızlar olduğunu düşünmüştüm 

Bir gözlerin 

Oysa satılık aşklar varmış 

Kiralanmış mutluluklar 

Bir sonrakini bekleyen 

Bir öncekini kıskandıran 

Bizde aşk bedava 

Sevmek, sevilmek bedava 

Gülmek, güldürmek bedava 

Ağlamak bedava... 

Bir tek ağlatmanın cezası vardı bende 

Onu da sana vermeye kıyamadım…', 'Kar örtüyor artık izlerini  Ve yavaş yavaş bulanıklaşıyor hayalin  Beyaz değil kar, mavi değil gökyüzü  Düşlerim gibi yeşil değil toprağın ö...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Gümüşbaş']::text[], 8.5, '{"poet":"Nurettin Gümüşbaş","poet_slug":"nurettin-gumusbas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kar-ortuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecr''im Yok Azığımda', 'ecr-im-yok-azigimda-burhanettin-akdag-qsi7l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretimi dindirdim, hülyalı gözlerinde 

Derinden soluklandım, sevdalı dizlerinde 

Her şey böyledir sandım, manalı sözlerinde. 

Bin hakikat seyrettim, gök kubbe üzerinde 

Dardayım ben aczimle, heybem boş huzurunda. 

Döndüm bir yol geriye, gönül gözümle baktım 

Ölçtüm biçtim titredim, meğer ebedim yaktım 

Anladım ki sonunda, güçsüz bedene yüktüm. 

Beş pulluk talaş oldum, devranın hızarında 

Kazançsız bitti ömrüm, heybem boş huzurunda. 

Affet Allah’ım affet, çâre ver düştüm dara

Hiddetime sabır ver, yanmayım ben kadere 

Kalbime Nur’unla dol, yol vereyim kedere. 

Ben gafil bir Adem’im, herkesin nazarında 

Ecr’im yok azığımda, heybem boş huzurunda. 

(25.01.2006)', 'Hasretimi dindirdim, hülyalı gözlerinde  Derinden soluklandım, sevdalı dizlerinde  Her şey böyledir sandım, manalı sözlerinde.  Bin hakikat ...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ecr-im-yok-azigimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olamamışlar', 'olamamislar-tuba-deniz-kuslar-676g3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dosdoğru bir uğursuzluk bu

bir lanet

her güne kötü başlama

ve kötü bitirme

timsah derisi bütün derim

taştan yüreğim

günün hatta ömrümün vurucu cümlesini sarfeden

o kızıl adam 

bir devlet memuruydu

yeni doğan bebeklerin saflığına kanmamalı

ya da güzel kızların

ciltleri kaymak gibi hatunların da

gözlerimin haşmetiyle yaptığım

değersiz bir saçmalık

esnafın ya da zengin bir erkeğin salon kahkahası

sabah sekiz akşam beş olmadıkça

ciddi bir toplantıda

akledilemeyeni

zekice söyleyemedikçe

akraba meclislerinde

zibil gibi inatla nükseden 

hüznün de bir anlamı olmalı

21:51  02.04.05', 'dosdoğru bir uğursuzluk bu bir lanet her güne kötü başlama ve kötü bitirme timsah derisi bütün derim taştan yüreğim günün hatta ömrümün vuru...', ARRAY['Türk Edebiyatı','Şiir','Tuba Deniz Kuşlar']::text[], 8.5, '{"poet":"Tuba Deniz Kuşlar","poet_slug":"tuba-deniz-kuslar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/olamamislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl?', 'nasil-harun-coban-u7pis', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gülzarda,ken gördüm yarimi

bir anda unuttum kendimi

bilmemki ne ola bu nazarların manası

özlem mi? gurbet mi? sıla mı? vuslat mı? 

yoksa.. yoksa Allahım bunun adı aşk mı? 

    ama....ama ben bilmem ki aşkı 

    nasıl desem, ne etsem de yaşadığım acıyı 

    yalan olmayan bir sözle 

    riya olmayan bir edeple 

    susmadan ama konuşmadan bildirsem beyanımı', 'gülzarda,ken gördüm yarimi bir anda unuttum kendimi bilmemki ne ola bu nazarların manası özlem mi? gurbet mi? sıla mı? vuslat mı?  yoksa.. y...', ARRAY['Türk Edebiyatı','Şiir','Harun Çoban']::text[], 8.5, '{"poet":"Harun Çoban","poet_slug":"harun-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nasil-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar -3-', 'bahar-3-mehmet-sukru-bas-1lnfu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün Vefasızlara

                                                   

Ne bahar geldi ömrüme, ne de sen,

Dağların ardında kaldınız öyle.

Bir ömür sizleri bekleyip durdum,

Gönlümde alev alev yandınız öyle.

Bahar bahar dedim kış oldu mevsim,

Buz tuttu gönlümde sevgin, hayalin.

Bak bir ömür geldi de geçti,

Peki, sen hala niye gelmedin? 

Ömür bitiyor cananım yazık değil mi? 

Ne olurdu bahar olup gelseydin? 

Asla inanmadın, sevdiğimi bilmedin,

Türlü cefan geldi, yine gelmedin

Görmedin gönlümde yanan ateşi,

Hasretine bir damla, su da serpmedin.

Yıllar rüzgâr oldu esip de geçti, 

Beklediğim sendin, ama gelmedin.

Korkum odur gelsen de beni bulaman, 

Zamansız tedavi, olmaz ki derman.

Ayrılık acısı göğsümde ferman,

Bir bakıp da ne haldeyim  görmedin.', 'Bütün Vefasızlara                                                     Ne bahar geldi ömrüme, ne de sen, Dağların ardında kaldınız öyle. Bir ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Baş']::text[], 8.5, '{"poet":"Mehmet Şükrü Baş","poet_slug":"mehmet-sukru-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bahar-3-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine göz yaşlarım bent dinlemedi.', 'yine-goz-yaslarim-bent-dinlemedi-servet-suner-7t109', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabah yatağımdan kalktım oruç olduğum için hiçbir işe bakmadan abdest alıp zamanında kılamadığım namazı kıldıktan sonra kur’ân okumaya başladım.Biraz sonra bir ağırlık bastı “hele bir dolaşayım geri gelir devam ederim” deyip kalktım odaları dolaşırken,giden akşam iftara davet ettiğimiz misafirler incelik etmiş bir buket (bir çift gonca)  yaptırmışlar teşekkür ederiz kardeşlerimize.Gözüm ona takıldı,çiçekler geldiğinde canlıydılar,buketin üzerine pırıltılar serpiştirilmişti.Kıyamadığımızdan,buketi bozup çiçekleri suya koymadık bu yüzden sabaha kadar çiçekler canlılıklarını yitirmiş boyunlarını bükmüşler ama pırıltıları hala onları süslüyordu.İşte tam bu safhada bende gözyaşları faaliyete geçti,ruhum sıkıldı,gönlüm daraldı.

              Böyle değil mi; kimi zaman  o güzelim goncalar gibi hayatının baharında,birilerinin hayallerinin gerçekleşmesi için onların tabi güzellikleri ile yetinmeyip yapay güzelliklerde eklenip sunulan filizler,tomurcuklar,goncalar(İNSANLAR) kısa bir zaman sonra yapay güzelliklerin gizlediği tabi güzelliklerin yitirildiğini fark edince bunalımlar,stresler,davranış bozuklukları,aile ortamından uzak ve kendilerini olumlu biçimde yönlendirecek bilinçleri/önderleri olmadığından tabi ki o ruh halinden kurtulmak,kendilerini unutmak için kalan sermaye(güzellik) lerini de harcamak üzere kötü alışkanlıklara sevk edilirler.

              İzbe,köhne,gün ışığından/temiz havadan uzak,sigara dumanı ve alkol kokuları içinde (başka kim bilir ne alışkınlıklar) gürültülü o disko müzikleri arasında; ……

             Aynı solduktan sonra çöpe atılan buketler/çiçekler gibi ….. 

ALLAH tüm çiçeklere dallarında,temiz,huzurlu sonlar nasip etsin.

AMİN!', 'Sabah yatağımdan kalktım oruç olduğum için hiçbir işe bakmadan abdest alıp zamanında kılamadığım namazı kıldıktan sonra kur’ân okumaya başla...', ARRAY['Türk Edebiyatı','Şiir','Servet Suner']::text[], 8.5, '{"poet":"Servet Suner","poet_slug":"servet-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yine-goz-yaslarim-bent-dinlemedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtuluş', 'kurtulus-emin-nadir-yiu21', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Goethe; 

''Şiir yazmak, kurtuluştur.''

Demiş.

Kelime,kelime

Bağlandım sana.

Şiir,şiir

Kurtuluyorum.', 'Goethe;  ''Şiir yazmak, kurtuluştur.'' Demiş. Kelime,kelime Bağlandım sana. Şiir,şiir Kurtuluyorum....', ARRAY['Türk Edebiyatı','Şiir','Emin Nadir']::text[], 8.5, '{"poet":"Emin Nadir","poet_slug":"emin-nadir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kurtulus-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* HoVaRDaYıM Bu GeCe *', 'hovardayim-bu-gece-mine-ozdemirtas-qb4l4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir prenses masalında yıllarca uyutulmuş gibi

tozlu raflarda saklanıp özenle çürütülmüş gibi

öylece kalıp / ölebilirim

Ya da

Ömrümce çocuk olup bir günde büyümüş gibi

altın beşiklerden düşüp te / kalkıp yürümüş gibi

alıp başımı / gidebilirim.

bu tercih benim /günah çıkarmak istemiyorum.

yedi kat yerin dibinde taç giyiyormuş Şahmeran

bana ne? 

zaten çıbanın başı artık her yerde

sadece / ben göremiyorum.

yokluğumun kutsanıyor olmasını da hiç irdelemiyorum

.

madem ki arzın merkezinde dans edemiyorum

o halde

boşluk büyüyebilir içimde

bu gece  hovardalığım tuttu işte / engelleyemiyorum

gönül ferahlığıma benden selamlar olsun

bütün suçlarımı / affediyorum.

06/02/2006', 'Bir prenses masalında yıllarca uyutulmuş gibi tozlu raflarda saklanıp özenle çürütülmüş gibi öylece kalıp / ölebilirim Ya da Ömrümce çocuk o...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hovardayim-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıyorum', 'yaziyorum-omer-dalman-alsno', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yazıyorum...

çünkü

her arkamı döndüğümde

''deryalar''ı görüyorum

anmadan geçemiyorum

her an''ı kutsuyorum

her an''a borcumu ödüyorum.

yazıyorum...

çünkü

verecek bir şeyim yok ki başka? ..

bitmişken,

nefesimi

arzumu

hedeflerimi

kendimi devretmişken o koskoca sıfır''a

elimde duran bir tek ''kelimeler''...

belki bir iki gözyaşı bir de...

ama onları da veriyorum ve

yazıyorum...

çünkü

dönecek yerim kalmamışken

tadılacak tatlardan sıkılmışken

koparıp almayı oldum olası sevmemişken

ve son perdenin kapanmasından başka

beklediğim kalmamışken

başka ne yapabilirim? ..

yazıyorum...

(Şubat 2006)', 'yazıyorum... çünkü her arkamı döndüğümde ''deryalar''ı görüyorum anmadan geçemiyorum her an''ı kutsuyorum her an''a borcumu ödüyorum. yazıyorum....', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yaziyorum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilgisayar Başında “tık” Diye', 'bilgisayar-basinda-tik-diye-omer-dalman-hi8ly', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yakın dostlarım bazen hakkımda endişe ederler

çok sinirle yazdığımdan bazı şiirleri

birgün bilgisayar başında

sinir krizinden “tık” diye gideceğimden.

Çeşit çeşit konuları

sokaklardaki, iş yerlerindeki

evdeki, restoranlardaki, wc’lerdeki

kafama fazla takmamamı

böyle şeylere üzülmememi öğütlerler

kimi zaman -bilgece tavırlarla-

ben de diyorum ki

hırpalarım kendimi

yollara sürterim burnumu

yakarım kollarımı sigaralarla

çöpleri bile karıştırırım! 

ve de zevkle anlatırım

yazarım! 

Bilge gizlemez

Bilge sakınmaz

Bilge görür, duyar

Bilge ağlar, bağırır, küfreder

hayata katılır

ve yaşadıklarından utanmaz! 

Bilge ettiği lafın hep önünde gider

arkada özetlerini bırakır; 

paylaşılsın diye

dertlere derman

muhabbetlere meze olsun diye...

Bilge bilgi’ye erdi diye

burnunu havaya dikip

karlı soğuklarda, fırtınalı havalarda

parlayan güneşten bahsetmez

dardaki fakirin sofrasına oturup

ziyafetleri anlatmaz...

birgün bilgisayar başında

sinir krizinden

“tık” diye gideceğimden endişe eden dostlarım

bakın dalganıza ve

yolunuz benden geçtikçe kırkyılda bir

otururuz, söyleşiriz en harbisinden

yalansız...

(Şubat 2006)', 'Yakın dostlarım bazen hakkımda endişe ederler çok sinirle yazdığımdan bazı şiirleri birgün bilgisayar başında sinir krizinden “tık” diye gid...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bilgisayar-basinda-tik-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boka Bastımı', 'boka-bastimi-omer-dalman-jvp7a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir kere boka bastımı insan

o gün peşpeşe gelir yakasına yapışır

                                  ne var ne yoksa! 

eşinin dostunun sitemi tutar.

karısı, çocuğu

banka kartı, kira borcu, yanlış işlemlerin derdi

tersine giden işler, projeler...

yollar bile yokuş görünür gözlerine.

bir kere boka bastımı insan

hani var ya

şu dönüp te bakmadığı karasinek bile

onun ağzına kaçar yolda yürürken! 

hele bir de puroyu, içkiyi de bırakmışsa ''boka basan''

en böğürtülü-sert müziği

kulaklarına gömmekten başka çaresi kalmaz.

açar camları bağırır avazı çıktığı kadar da

yine yetmez! 

bir kere boka bastımı insan

hiçbir ''başka boka'' elini sürmese mi o gün acaba? 

(Şubat 2006)', 'bir kere boka bastımı insan o gün peşpeşe gelir yakasına yapışır                                   ne var ne yoksa!  eşinin dostunun sitemi ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/boka-bastimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mısralarım', 'misralarim-cahit-pehlivan-dz3jp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mısralarda arıyorum, her şeyimi.

Ne bileyim ki işte.

Bu mısralardan diliyorum.

Geleceğimi, şansımı, talihimi.

Bana nasıl yardımcı olacaklar.

Bilmiyorum.

Ama, 

Öyle ümit ediyorum ki.

Bu mısralar bir gün bana,

Hemde hiç umulmadık

Bir yerde ve de anda,

Öylesine yardımcı olacaklar ki.

Şaşıracağım.

Evet, gördüğünüz gibi,

Bütün ümitlerim sizlersiniz.

Mısralarım...

Çanakkale', 'Mısralarda arıyorum, her şeyimi. Ne bileyim ki işte. Bu mısralardan diliyorum. Geleceğimi, şansımı, talihimi. Bana nasıl yardımcı olacaklar....', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/misralarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalantor Ayılar', 'kalantor-ayilar-omer-dalman-k9htf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben de isterdim

o, her gün trafikte

“belki düz mü geçecek? ” diye

arabamla yol verdiğimde

arabalı “kalantor ayılar”ın, bu terbiyeli

ve asil davranışımı umursamadan

sinyal vermeden

sağa, yani beklemede olduğum sokağa saptıklarında

ve beni ağzı açık, dili dışarda kalmış salaklar gibi

“aptal” yerine koyduklarında

önlerini kesip

önce arabalarını dört bir yandan tekmeleyip

harab edip

sonra en büyük zevk olarak

şoför camını da aşağı indirip

ayıyı ellerimle dışarı alıp

dümdüz, kafa-göz dalmayı! 

ama bu “kalantor ayılar” her durumdan

-yavşaklar gibi- kaçıp, arkalarına bakmadan

sıyrılmaya o kadar alışkınlar ki; 

her seferinde kahretsin

bana kalan 2 saniye içinde

o “buldog köpeği” olmuş suratlarına

sığdırabildiğim kadar küfrü yükleyip

suratımı da “vahşet” hale sokup

arta kalan içte patlayan sinirimi de

içimdeki volkanın içine yükleyip

yoluma devam etmek zorunda kalıyorum! 

Halbuki ben de isterdim

bu “kalantor ayılar”dan bir tanesini köşeye kıstırıp

kafa-göz dümdüz girmeyi! 

bak o zaman o kibar ve işlevsiz sol ellerini

nasıl da üşenmeden

sinyal vermede kullanıyorlar! 

(Şubat 2006)', 'Ben de isterdim o, her gün trafikte “belki düz mü geçecek? ” diye arabamla yol verdiğimde arabalı “kalantor ayılar”ın, bu terbiyeli ve asil ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kalantor-ayilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hür Savaş', 'hur-savas-eyup-gok-k9t69', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Değer mi Özgürlük uğruna savaşmaya? 

Yoksa devam mı esaretle yaşamaya? 

Ruhlarımızı hür bırakarak başlamaya

Varmısın yeniden, insanı yaşatmaya

Bir onuru var hayatının, unutma

Kötü güçlü olsada, kendini bırakma

Eğer hayvan gibi yaşlanmaktansa

Ölmek elbet daha iyi, yaşamaktansa 

Hayatımız var emanet, neticede bir tek

Merak ediyorum, nasıl olacak ölene dek? 

Heyhat! fanide kula kul olanlar yek tek

İki dünya arasında, ne acaip dengesin Ey! Felek

Mükafat-ı Hürriyet, Tanrıdan''sa eğer

Haşa, İlahi hediyedir, faniyiz bizler

Kuldansa esaret, ne yapayım mı der? 

Özgürlük uğruna, inan savaşmaya değer.', 'Değer mi Özgürlük uğruna savaşmaya?  Yoksa devam mı esaretle yaşamaya?  Ruhlarımızı hür bırakarak başlamaya Varmısın yeniden, insanı yaşatma...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Gök']::text[], 8.5, '{"poet":"Eyüp Gök","poet_slug":"eyup-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hur-savas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Dua', 'son-dua-cahit-pehlivan-z9wwv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerinden içmek isterim sevgilim, 

Bana uzatacağın bir kadeh şarabı.

İçince, kendimden geçmek isterim sevgilim.

Nasıl olsa zindana çevirdin sen dünyamı.

Al senin olsun aşk ateşinle yanmış

Küle dönmüş olan kalbim.

Yalnız sevgilim senden tek isteğim.

Üzerime döksünler senin telini duvağını.

Zafer senindir artık sevgilim.

Dostlarım etsin, benim son duamı. 

Keşan', 'Ellerinden içmek isterim sevgilim,  Bana uzatacağın bir kadeh şarabı. İçince, kendimden geçmek isterim sevgilim. Nasıl olsa zindana çevirdin...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/son-dua-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgâr', 'ruzg-r-cahit-pehlivan-26r2s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsanın yaşaması için hava var.

Serinlemeye ise gölge arar.

Gölgede serinlik neylesin.

Serinlik rüzgârlı havada var.

Rüzgârda coşkun ırmak gibidir. 

Aklına esince aniden azar.

Meltem, bora derken tayfun olur.

Evler evlikten çıkar, hepside viran olur.

Bu denli şiddetli olur, kızdığında rüzgâr. 

Tek dileği, varmaktır sonbahara ve kışa. 

Zamanı gelince de sayılı rüzgârların.

Yorgan üstüne yorgan çektirir insanlara.

Merzifon', 'İnsanın yaşaması için hava var. Serinlemeye ise gölge arar. Gölgede serinlik neylesin. Serinlik rüzgârlı havada var. Rüzgârda coşkun ırmak g...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ruzgar-136-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rezillik', 'rezillik-adnan-yesiltas-4okd5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan haklarından bahsedenlerin,

İnsan hakkı yemesi değil,

Hakları yenenlerin susması,

Asıl rezillik.', 'İnsan haklarından bahsedenlerin, İnsan hakkı yemesi değil, Hakları yenenlerin susması, Asıl rezillik....', ARRAY['Türk Edebiyatı','Şiir','Adnan Yeşiltaş']::text[], 8.5, '{"poet":"Adnan Yeşiltaş","poet_slug":"adnan-yesiltas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rezillik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Künyem', 'kunyem-emrah-karakoc-5f2n5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merak edip sormuş biri 

Biri demiş ki tanırım 

Sen beni ne bilirsin ki

Ben kendimi anlatırım

Ne maşuğum ağlar bana

Ne kimse bel bağlar bana

Mekanım dağlardır ama

Ovayada bayılırım

Hüzün canım ciğerimdir

Hasret özlem kaderimdir

Vefasızlık kederimdir

Hor görülür dağılırım

Düşenler gardaştır bana 

Dertliler sırdaştır bana 

Tüm çileler hoştur bana 

Dert çekmeye bayılırım

Fazla merak etme emi 

Hoşnut etmez dünüm seni 

Araştır bak kökenimi 

Gariplerden sayılırım

Elbet paktır dünüm benim 

Bak ap aktır günüm benim 

Hakk''a gider yönüm benim 

Emrah diye anılırım', 'Merak edip sormuş biri  Biri demiş ki tanırım  Sen beni ne bilirsin ki Ben kendimi anlatırım Ne maşuğum ağlar bana Ne kimse bel bağlar bana ...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kunyem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '“Şair” Şaire Hediye', 'sair-saire-hediye-omer-dalman-3olyv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şair

güzel yazan şairi gördümü

başka bir zevklenir

yüzünde binbir gül açar bilinmeyen renklerde...

eşini, benzerini görmekten daha öte bir şeydir.

bir dostun

bir sevgilinin elini tutmaktan daha öte...

şair

güzel yazan şairi gördümü

kıskanmaz

“kendine hediye” bilir

paketini yavaş yavaş açar

elleriyle yoklar

eğilir koklar

kağıdının hışırtılarını dinler

rengini merak eder

sonra içindekini görmek ister

hele bir de sesi de hoşuna giderse

dinlemeden edemez bundan böyle! ..

farklı bir ödüldür şaire

güzel yazan şairi bulması

yoldaştan öte

sevgiliden öte

anneden öte

kendinden öte...

(Şubat 2006)', 'Şair güzel yazan şairi gördümü başka bir zevklenir yüzünde binbir gül açar bilinmeyen renklerde... eşini, benzerini görmekten daha öte bir ş...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sair-saire-hediye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabalı Vapurda', 'arabali-vapurda-murat-yolyapan-8dakt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üçkuyular bostanlı arası

Yine gözlerimi reddetti siyah mantolu kadın

Bir gemi-grostonları pelte pelte semiz-gördü olanı

Anırdı üç defa müzevir martılar dalgaya aldı

Bir velvele kuyruk oldular gemiye 

                                      madara oldum körfeze

Asabım bozuldu çok

Neyse ki ege kalender dalgalı bugün candan mavi

Sıvazladı sırtımı

Yakıştırdı gençliğime sustalı sancımı

Şaşılacak iş: güvertede üç serçe

Mangal yürekli maceracı

Böyle kadın kalmadı bu devirde

Ben maceracıyım mesela

Bu gemi afrikaya gider deseler

Giderim

Yanımda sağdıcım mehmet olsun

Bir de kambur

Korsanlık ederim

Kanatlarım olsa uçarım

Tek başıma martılara dalarım

Batsın bu gemi

Ne sadıcım Mehmet var

Ne kambur

Ne siyah mantolu kadın maceracı

Şu mangal yürekli serçeler var tek

Bir de şu serçe boyunlu boyacı velet

Bir de ben elbet

Ama tutuklu

İki yanımda iki inzibat er

Martıları boş ver

Alayı fırsatçı ibneler

(6 Şubat 2006, İzmir)', 'Üçkuyular bostanlı arası Yine gözlerimi reddetti siyah mantolu kadın Bir gemi-grostonları pelte pelte semiz-gördü olanı Anırdı üç defa müzev...', ARRAY['Türk Edebiyatı','Şiir','Murat Yolyapan']::text[], 8.5, '{"poet":"Murat Yolyapan","poet_slug":"murat-yolyapan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/arabali-vapurda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Türküsü', 'ayrilik-turkusu-mehmet-halil-twlea', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkım beni ayrılıkla sınadı

Başımı vurduğum taşlar kanadı

Yandım! kül oldum, dostlar oynadı.

Yürek buna ne yapsın da dayansın

Ilık ılık dalga dalga damarım

Barut ile benzin ile dolarım

Nefes alsam, ateş olup yanarım.

Yürek buna ne yapsın da dayansın

Şimşek bile gözün gibi çarpamaz

Ateş değse senin kadar yakamaz

Balyoz bile senin kadar yıkamaz

Yürek buna ne yapsın da dayansın

Tütün gibi kıyım kıyım kıyıldım

Üzüm gibi pres pres sıkıldım.

Senin için hücrelere tıkıldım.

Yürek buna ne yapsın da dayansın

Ne söylese onun için köleyim,

Dünya gibi etrafında döneyim,

Mermer değil çelik değil yüreğim,

Yürek buna ne yapsın da dayansın.', 'Aşkım beni ayrılıkla sınadı Başımı vurduğum taşlar kanadı Yandım! kül oldum, dostlar oynadı. Yürek buna ne yapsın da dayansın Ilık ılık dalg...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayrilik-turkusu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Anlatır Şiirler', 'seni-anlatir-siirler-ergin-hayal-6o2f9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilinen tüm şiirler

şimdi en yalın halinde

ve hiçbiri,imge kullanmıyor

seni anlatırken...

Halbuki sen; 

hiçkimselerin yaşadığı

gecenin,

en uzak vaktindesin...

Bense; 

güneşin ısıttığı 

kubbelerin ardındaki

buğulu ve ıslak 

gökyüzü kadar 

asiyim...

Ve mavinin derininde

kaybolmuş martının,

kanat uçlarındaki,

tuzlu deniz suyu kokusu kadar

sahipsiz...', 'Bilinen tüm şiirler şimdi en yalın halinde ve hiçbiri,imge kullanmıyor seni anlatırken... Halbuki sen;  hiçkimselerin yaşadığı gecenin, en u...', ARRAY['Türk Edebiyatı','Şiir','Ergin Hayal']::text[], 8.5, '{"poet":"Ergin Hayal","poet_slug":"ergin-hayal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-anlatir-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gul acar kabrimde', 'gul-acar-kabrimde-yasar-gurlek-e90u8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'GUL ACAR KABRIMDE

viranbagimda kalmadi

sana verecek bir gul

sen sakrak sakirdi

simdi susuyor bulbul

lale menekse hemde sumbul

hepsi soldu bugun

viranbagimda kalmadi

sana verecek bir gul

omrumun son deminde

guller gormek isterdim elinde

ah nazlim sen herseye layiksin

belki bir tomurcuk gul acar kalbimde

kabir gulune belki biraz gul verirsin

mezarim basinda erim erim erirsin

oldukten sonra beni seversin

belki bir tomurcuk gul acar kabrimde

YASAR GURLEK

8-1-1992

LEIDEN  HOLLANDA', 'GUL ACAR KABRIMDE viranbagimda kalmadi sana verecek bir gul sen sakrak sakirdi simdi susuyor bulbul lale menekse hemde sumbul hepsi soldu bu...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gul-acar-kabrimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarin yokuz', 'yarin-yokuz-yasar-gurlek-c6jw2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YARIN  YOKUZ

Misafiriz  bu  dunyada

Bugun  varz  yarin  yokuz

Kanma  dunyaya  sakin

Bir  gun  variz  bir  gun  yokuz

Tatli  tatli  eyleniriz

O gun kefeni  giyeriz

Kurtar bizi  rabbim  deriz

Bugun variz  yarin  yokuz

Icki  icip   sizarlar

Dogru  diyeni azarlar

El ilen  mezar kazarlar

Bugun variz  yarin  yokuz

Adim yasar  yasamadim

Hayattan  tad  alamadim

Hak yolunu  bulamadim

Bu gun  varim  yarin  yokum

Iyi  kullar  cile  ceker

Dunyada  azigi  eker

Ahirette  olur  seker

Bugun variz  yarin  yokuz

Fani  dunya  kanmam  sana

Haram girmedi  bu  cana

Helal sutlu  canim  ana

Bugun variz  yarin  yokuz

Hak yoluna  gidek  yayan

Ayan  olur  bana  ayan

Hersey  ap acik olur beyan

Bugun variz  yarin  yokuz

Sapma hak yolundan  gayri

Rabbin  yolu  baska  ayri

Allahimdan  yoktur  gayri

Bu gun  varim  yarin  yokum

20-01-1992  yasar  gurlek

LEIDEN  HOLLANDA', 'YARIN  YOKUZ Misafiriz  bu  dunyada Bugun  varz  yarin  yokuz Kanma  dunyaya  sakin Bir  gun  variz  bir  gun  yokuz Tatli  tatli  eyleniriz...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yarin-yokuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Virane gönül', 'virane-gonul-huseyin-kerim-fhx6s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne  isterki senden  başka, şu  virane  gönül

Gitme  desemde  durmazki,geçsede  bir  ömür

Ağlamaksa  karşında,  diz  çökmekse  önünde

Neye   yarar   bilmezki,  şu  virane gönül

Gitme desem gidersin,kal  desem  istemezsin

Gerçek  sevgi  bu  değil,desemde  dinlemezssin

Tutabileceğini  bilsem,git  koş  derdim peşinden

Geceler boyu  yasta, kaldınmı  şimdi  gönül

Gülüşüne kanma,tebessümüne  hiç  inanma

Seninmiş gibi  durur ama  uzaktadır  aslında

Çölde  kalır  susarsın,serap  değil sanırsın

Tam  ortadasın  işte,gel  vazgeç   be  deli  gönül', 'Ne  isterki senden  başka, şu  virane  gönül Gitme  desemde  durmazki,geçsede  bir  ömür Ağlamaksa  karşında,  diz  çökmekse  önünde Neye   ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim']::text[], 8.5, '{"poet":"Hüseyin Kerim","poet_slug":"huseyin-kerim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/virane-gonul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gulmem aci gulemedim', 'gulmem-aci-gulemedim-yasar-gurlek-thyqo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gulmem aci gulemedim

derdim  coktur   alan   olmaz

su  halimdan  soran  olmaz

benim  yuzum gayri  gulmez

hayat  aci  gulemedim

dert   ararsan  sira  sira

benim  bahtim  nede  kara

ta   sinemde  koca  yara

gulmek  aci  gulemedim

dert  ustune  dert  olurmu

dost  kalbinden  vurulurmu

buna  sorgu  sorulurmu

sevmek  aci  sevemedim

21-02-1993   yasar  gurlek

leiden  hollanda', 'gulmem aci gulemedim derdim  coktur   alan   olmaz su  halimdan  soran  olmaz benim  yuzum gayri  gulmez hayat  aci  gulemedim dert   ararsa...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gulmem-aci-gulemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayattan Bir Kesit', 'hayattan-bir-kesit-yasar-ekrem-kocakurt-ju4xp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayat ağacında solmuş iki yaprağız biz,

yüreklerimizde koca çınar ağaçları.

Rüzğarlarla savrulmuşuz sonbaharda,

O sonbahar rüzgarı değilmiydi buluşturan

bizi tozlu yollarda.Kaybedilen bir zaman telaşıyla.

Tutunduk birden,hiç düşünmeden.Farklıydık ama

yapraktık dallardan kopan.Sararmışız,solmuşuz yeşillik 

özlemiyle.Düşünceler doluyken yüreklerde geçmişi

paylaştık seninle.

Şimdi içimizde buruk bir telaş,bir rüzgar daha esermi? 

ayırırmı bizi? savrulur gidermiyiz ayrı ayrı bir kuytuya? 

Dayanırmı yüreklerdeki çınar bu yazgıya? 

Kuytular rüzgar almaz.Hangi rüzgar getirir bizi tekar bir araya,

bir umut düşeriz belki yanyana.Taşıdığımız tohumlarla

fidan olup fışkırırız yeni bir hayata.Yada durup izleriz zamanı

çürüyüp,karışıncaya kadar toprağa.....

   (İstanbul  25.12.2005)', 'Hayat ağacında solmuş iki yaprağız biz, yüreklerimizde koca çınar ağaçları. Rüzğarlarla savrulmuşuz sonbaharda, O sonbahar rüzgarı değilmiyd...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ekrem Kocakurt']::text[], 8.5, '{"poet":"Yaşar Ekrem Kocakurt","poet_slug":"yasar-ekrem-kocakurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayattan-bir-kesit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalvarmam', 'yalvarmam-yasar-gurlek-6ugc4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YALVARMAM

sendemi  bana  inanmiyorsun

aglamaktan  gozlerime  kan  doldu

sendemi  bana  inanmiyorsun

vay  vay   vay   vay  benim  halima

seni  canimdan cok  sevmisidim

seni  cana  can  bilmisidim

su  omrumu   sana  vermisidim

sendemi  bana  inanmiyorsun

aglamam sizlamam artik  sana  yalvarmam

acimam  uzulmem  artik sana  guvenmem

seni  cana  can  bilip sana omrumu vermem

seni  candan  cok sevip artik  sana  yalvarmam

zaten  bana  inanmiyorsun

goz  yaslarimi  goremiyorsun

sevgi  ask  nedir  bilemiyorsun

artik  sana  guvenmem 

artik  sana  yalvarmam

05-08-1992  yasar  gurlek

leiden  hollanda', 'YALVARMAM sendemi  bana  inanmiyorsun aglamaktan  gozlerime  kan  doldu sendemi  bana  inanmiyorsun vay  vay   vay   vay  benim  halima seni...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalvarmam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin sevgine yazik', 'senin-sevgine-yazik-yasar-gurlek-vc6i6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'senin  sevgine  yazik

sevmesini   sen  gosterdin

canima  canin  verdin

sonra neden terk  ettin

yazik  senin  sevgine

bana  guller  sunar  idin

icin  icin  yanar  idin

her  nefeste  anar  idin

yazik  senin  sevgine

unuttunmu  bu  elleri

gezdigimiz  o  yerleri

verdin  beyaz gulleri

yazik  senin  sevgine

hayirsizin  tekiymissin

vijdansizin biriymissin

bu gonlumde yucelmistin

yazik  senin  sevgine

yazik  senin  sevdana

yazik  senin  askina

yazik  senin  sevgine

yazik  senin  guzelligine

yazik  yazik  yazik senin

her  seyine yazik  yazik

05-08-1992  yasar  gurlek

leiden  hollanda', 'senin  sevgine  yazik sevmesini   sen  gosterdin canima  canin  verdin sonra neden terk  ettin yazik  senin  sevgine bana  guller  sunar  id...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/senin-sevgine-yazik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konusmaz', 'konusmaz-yasar-gurlek-akw0h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KONUSMAZ

guzumden  yaslar  akar

gozlerim  yollara  bakar

felek bana  celme  takar

dilim  konusmaz  konusmaz

can  canandan  ayrilali

yuregim  derde  dolali

caresiz  nacar  kalali

dilim  konusmaz  konusmaz

aci  sitem  ettim  dosta

gozum  yolda  gelmez  posta

dertli  gonlum  yine  hasta

dilim  konusmaz  konusmaz

yasar  yanar  dertli  bugun

dost  yuzunden  oldum  surgun

dusersin sende dostum bir gun

dilim  konusmaz  konusmaz

08-10-1994  yasar  gurlek

leiden  hollanda', 'KONUSMAZ guzumden  yaslar  akar gozlerim  yollara  bakar felek bana  celme  takar dilim  konusmaz  konusmaz can  canandan  ayrilali yuregim ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/konusmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Bana Zehir Oldu Neyleyim(Derlenmiş Türkü)', 'hayat-bana-zehir-oldu-neyleyim-derlenmis-turku-seyfet-bozcali-k2pkf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bende bu Dünya''ya geldim geleli,

Hayat bana zehir oldu neyleyim.

Keşke gelmeseydim ben bu Dünya''ya,

Hayat bana zehir oldu neyleyim,

Dünya bana zindan oldu neyleyim...

Dedim yara gidem yetmedi yolum,

Elimi kaldırdım kırıldı kolum,

Bende ne talihsiz dertli bir kulum,

Hayat bana zehir oldu neyleyim,

Dünya bana zindan oldu neyleyim...

Adımımı attım düştüm çukura,

İleriye baktım döndüm şaşkına,

Derler Seyfet nettin Allah aşkına,

Hayat bana zehir oldu neyleyim,

Dünya bana zindan oldu neyleyim...

             1974 Yöresi Kars', 'Bende bu Dünya''ya geldim geleli, Hayat bana zehir oldu neyleyim. Keşke gelmeseydim ben bu Dünya''ya, Hayat bana zehir oldu neyleyim, Dünya ba...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayat-bana-zehir-oldu-neyleyim-derlenmis-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gururla Haykırıyor Yüreğim', 'gururla-haykiriyor-yuregim-atilla-guler-op3yb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dün

gecenin bir yarısı üzerime çöktü yokluğunun puslu kokusu

vurdu suratıma nankörlüğün kudurmuş tokadı

gıkım çıkmadı

tuttum onurumun elinden

veda bile etmedim

kapıda karşıladı beni yalnızlık tam çıkarken

atladım bir arabanın arka koltuğuna

açık pencereden hiçliğini solukladım

uyku mahmuru gözlerimle 

zifiri karanlıklarda yalnızlığı ezberledim

yazdım, yazdım, yazdım...

rüyalarımın en ücra köşelerine gizledim ihanetleri

öfkemi biriktirdim

üzerime sinmiş yokluğunun naftalin kokulu bulantısı

sessiz diyarlara yelken açtım

bugün

yalnızlığım ve ben

başım dimdik

gururla haykırıyor yüreğim

masmavi okyanuslarda bir damla su gibi özgür

yalansız

aldatmadan

sonuna kadar...', 'dün gecenin bir yarısı üzerime çöktü yokluğunun puslu kokusu vurdu suratıma nankörlüğün kudurmuş tokadı gıkım çıkmadı tuttum onurumun elinde...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gururla-haykiriyor-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekmi', 'gercekmi-huseyin-kerim-m0bzx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak  işte  tam  karşımdasın,  sigaranda elinde

Olmuşsun  çakır  keyif,  tayyareler  tepende

Bakmaya  çekindiğim,o  gözlerin  içine

Şişeler  arkadaş olmuş,  bense  bi  çare

Biran  gitsemmi diye, düşündümde  içimden

Nasılsa  haberin  yok, ne çıkarki  beklesem

Gizliden gizliye,baksam  sana  karşıdan

İnan yeterdi  bana,  kalkmadan  sen karşımdan

Seyrine  doyulmayan, ey güzel canan

Bir  yol versende  geçsem,sensin  bana yakışan

Sakın  gitme  ne  olur,bensiz  otur   karşımda

Seyretmek yeter bana, hiç haberin olmasada

Anlatmak istemezmiyim,içimdekileri bir  bir

Seni  kaybetmek  korkusu, inan  beni  bitirir

Benim  değilsin  ama,  bak  şimdi  karşımdasın

Öğrenince  belkide,acımadan  kıyarsın.', 'Bak  işte  tam  karşımdasın,  sigaranda elinde Olmuşsun  çakır  keyif,  tayyareler  tepende Bakmaya  çekindiğim,o  gözlerin  içine Şişeler  ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim']::text[], 8.5, '{"poet":"Hüseyin Kerim","poet_slug":"huseyin-kerim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gercekmi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Uykular', 'kucuk-uykular-yasar-ekrem-kocakurt-7gfxs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sonbahar akşamı

Dolunayın parlak yakamozu

Parlıyor siyah deniz yüzünde

Işıktan bir yol gibi

Çeviriyorum sessizlikte,

Tıkırdayan motorun sesiyle tekneyi

Dolunay üstüne.

Dayanılmaz sevdalarda

Tükenmeyen aşklar gibi.

Yol alıyorum durmadan.

Dolunay aşkım,ışıklı yol sevdam.

İçimde sen,dışımda sessizlik

Varacağım noktada bitecek bu hasretlik

İçimde hep sen oldun,yanımda hiç ayrılmayan 

Sen olacaksın dolunayım..', 'Bir sonbahar akşamı Dolunayın parlak yakamozu Parlıyor siyah deniz yüzünde Işıktan bir yol gibi Çeviriyorum sessizlikte, Tıkırdayan motorun ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ekrem Kocakurt']::text[], 8.5, '{"poet":"Yaşar Ekrem Kocakurt","poet_slug":"yasar-ekrem-kocakurt","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kucuk-uykular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğru Dönen Çarkı Felek (Derlenmiş Türkü)', 'dogru-donen-carki-felek-derlenmis-turku-seyfet-bozcali-i6u3m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doğru dönen çarkı felek,

Şimdi doğru dönmez oldu,

Ana,bacı,dost arkadaş,

Hiç halimi sormaz oldu.

  Dokunmayın kanar yaram,

  Dert üstüne dert çekerem,

  Tabip yaramı elleme,

  Yar elinden benim çarem.

Benim yaram kalp yarası,

Bulunmaz oldu çaresi,

Dokunmayın sızılıyor,

Yardır bu derdim çaresi...

  Dokunmayın kanar yaram,

  Dert üstüne dert çekerem,

  Tabip yaramı elleme,

  Yar elinden benim çarem.

  1978 Yöre Kars', 'Doğru dönen çarkı felek, Şimdi doğru dönmez oldu, Ana,bacı,dost arkadaş, Hiç halimi sormaz oldu.   Dokunmayın kanar yaram,   Dert üstüne der...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dogru-donen-carki-felek-derlenmis-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mağlup', 'maglup-birsen-ates-58f54', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'biliyordum ki

böyle olacağını

sıcaklığın ayaza çekeceğini

hissetti de gönül

dur demedi 

öylesine

gülen bir yüzüm

artık

nihayetinde mağlup

06.02.06', 'biliyordum ki böyle olacağını sıcaklığın ayaza çekeceğini hissetti de gönül dur demedi  öylesine gülen bir yüzüm artık nihayetinde mağlup 06...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/maglup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sor Beni', 'sor-beni-munevver-senol-ivmm2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocukluğumu sormayın bana, 

ben hiç çocuk olmadım ki. 

Hep büyüktüm ablaydım ben, 

oyuncağım bile yoktu. 

Babamda erkenden bırakıp gitti,

öksüzlerden sor beni. 

Genç kızlığımı yaşamadım,

hemen gelin oluverdim. 

Birde baktım oğlum kızım,

kendimi anne buluverdim. 

Kocam sefa adamıymış,

ondan hesap sorulmazmış. 

İstediği zaman gelir, 

istemezse gelmez imiş. 

EE o zaman niye evlenmiş? 

Hiç huzurlu bir günüm yok,

gözyaşlarım sicim gibi. 

Gök yüzü de bulutlanmış,

çakan şimşeklerden sor beni,

En iyi o anlar beni. 

İçimdeyse fırtınalar,

geceleri yalnızım karanlıktan korkar ağlarım. 

Gözyaşımla ıslattığım sarılarak uyuduğum,

yastığımdan sor beni. 

Şimdi sağlık gitti elden,

ne sen kaldın nede ben. 

Tükenmezdi benim aşkım 

bir nefeste tükettin sen. 

Zalimin zulmüne uğrayan,

mazlumlara sor onlar iyi anlar beni. 

Yıllarımı mahvettin ya 

asla affetmem ben seni.', 'Çocukluğumu sormayın bana,  ben hiç çocuk olmadım ki.  Hep büyüktüm ablaydım ben,  oyuncağım bile yoktu.  Babamda erkenden bırakıp gitti, ök...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sor-beni-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Bir Ömür Geçsin', 'bekle-bir-omur-gecsin-kenan-yildiz-l28tl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamak,

Seninle mutlu olacak birkaç anı…

Sessizce doğuverecek olan güneşi beklemek,

Beklemek saatlerce, 

Beklemek…

Sonra hayaller kurmak,

Mavilikler üzerine gökyüzündeki.

Saniyeleri dakikaları saymak bir bir

Gelecek zamanlarda

Kavuşma anını beklemek

Beklemek…

Bir ömür süresince

Belki daha uzun,

Umutların solgunlaştığı,

Rüyaların yok olmaya yüz tuttuğu bir anda…

Bitmeyen gecelerin, 

Bitmeye yüz tuttuğu bir anda…

Birleşir eller,

Yorgun kalpler dinçleşir.

Yine hatıralar diriliverir

Belleklerde…

Unutulur…

Sayılan saniyeler, 

Uzayan zaman,

Duvarda kırılan birkaç kadeh,

Unutulur,

Kirli gömlekler, 

İçki şişeleri..

Hepsi.

Geçen ömür unutulur…

Unutulmayanı,

Bir çift bakış ve yağmurlu bir sabahta,

Ansızın beliriveren hayali sevgilinin,

Dikilir karşında.

İşte o an:

Dolar insan sonuna dek,

Hayat denen nesne ile.

Ölüm nedir onun için? 

Ulaşılmaz hayaller umutlar nedir? 

Sadece var olan gerçektir; 

Sevgiliye duyulan hazlar, ve hatıralar…

Günü geldi mi ölümün,

Direnesin gelir,

Senin için hiç olan ölüm,

Sana acı verir. 

Bekle…

Bekle…Belki bin kere,

Bekle diyesin gelir ölüme,

Meydan okursun Azraile.

O an, 

Kadehte duran içkinin tadını,

Bir nefes sigaranın iştahını duyarsın.

En güzeli ise; 

Sevgiliyi son bir kez 

Güzel hatıralarla anarsın.

Azrail, 

Sen ve 

Uzaklaşmak dünyadan.

Uzaklaşmak sevdiğin birkaç hazdan.

Bilmiyorum, belki mutlu olursun,

Belki anlarsın yaşamın ne olduğunu,

Belki umurunda olmaz yaşamak.

Ama yine de bilmelisin ki; 

Biz birbirimiz için yaratılmışız dersin,

Onsuz oraya gittiğin için

İsyan edersin….', 'Yaşamak, Seninle mutlu olacak birkaç anı… Sessizce doğuverecek olan güneşi beklemek, Beklemek saatlerce,  Beklemek… Sonra hayaller kurmak, M...', ARRAY['Türk Edebiyatı','Şiir','Kenan Yıldız']::text[], 8.5, '{"poet":"Kenan Yıldız","poet_slug":"kenan-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/bekle-bir-omur-gecsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-ramazan-ates-xqpid', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerim ellerinden hayat buldu,

Gözlerim gözlerinden ışık aldı.

Dilimde dudağıyın tadı kaldı,

Özledim, özledim, özledim seni.

Sözlerin ruhuma neşe kaynağı,

Gözlerin yüzünün balı kaymağı.

Kollarım ömrümce seni sarmalı,

Özledim, özledim, özledim seni.

Saçında huzurun şifresi saklı,

Kaşların gözlerinle bir ahenk yaptı,

Yüce mevlam seni özel yarattı,

Özledim, özledim, özledim seni.

İnce uzun selvi gibi boyun var,

Sinende saklarsın bir çift gülün var,

Seni farklı yapan hoş bir kokun var,

Özledim, özledim, özledim seni.

Seninle inanki ömürler uzar,

Aklıma başımdan sen ettin firar,

Bu canı yoluna sersem ne çıkar? 

Özledim, özledim, özledim seni.

Ramazan Ateş/Enschede-30.1.2006', 'Ellerim ellerinden hayat buldu, Gözlerim gözlerinden ışık aldı. Dilimde dudağıyın tadı kaldı, Özledim, özledim, özledim seni. Sözlerin ruhum...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozledim-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-sami-akman-ywqzx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerede başlayıp nerede bitersin

Seni nasıl tarif edeyim, nasıl anlatayım

Tatlı bir dokunuşta mı? 

Sıcacık bir öpüşle dudaklar damı? 

Şefkatle okşayışlar damı? 

Yoksa sancılı geçen günlerde

Özlemi içinde büyüyen 

Yar hasretin demi? 

Ey zaman seni nasıl anlatayım! 

Islık çalan rüzgârlar damı? 

Çisil çisil yağan yağmurlar damı? 

Yalnızlığın hançer gibi saplandığı

Çığlık çığlığa ürperen geceler demi? 

Yoksa içindeki acıyla kıvrandığın

Gölgeler gibi saklandığın

Karanlık dehlizlerde 

Bir var olup bir kaybolduğun

Yar hasretin demi? 

Ey zaman seni nasıl anlatayım! 

Yıldızlar gibi pırıldayan gözler demi? 

Sevgi dolu yürekler demi? 

Sevda türküsü gibi bir sazın

İnleyen nağmelerinde

Hasret dolu yanık sesinde mi? 

Gözyaşlarına inat yağmurun

Geceye inat güneşin her doğuşunda

Dayan diyen yüreğin demi? 

Her gün durmadan büyüyen

Yar hasretin demi? 

Ey zaman seni nasıl anlatayım! 

Her gün uydurulan bahanelerin

Adına sevgi dendiği! 

Sinsice planlanmış bir oyunun

Yavaş yavaş sahneye konduğu

Uzaklarda ki ayrılığın

Ayak seslerinin duyurulduğu

Gününü gün edip yaşandığı

Sonra sensiz olamam dendiği

Bir dünya damı? 

Yoksa adam gibi sevdiğin

Yar hasretin demi? 

Ey zaman seni nasıl anlatayım! 

Hani ilaçtın? Hani her derde deva

Senle aşılırdı her şey, hani çareydin? 

Bitmeyen süreydin, dertlere deva

Girdabında sürüklediğin bu bedenin

Körüklediğin yangının damısın? 

Yoksa yeniden başlatacağın oyunun

Henüz başın damısın? 

Söyle ey zaman söyle seni nasıl yaşayayım? 

Söyle ey zaman söyle bana

Seni, yar hasretin demi anlatayım…..

®©', 'Nerede başlayıp nerede bitersin Seni nasıl tarif edeyim, nasıl anlatayım Tatlı bir dokunuşta mı?  Sıcacık bir öpüşle dudaklar damı?  Şefkatl...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/zaman-294-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beste/kar', 'beste-kar-reyhan-tataroglu-opfsn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'olunca; 

                                    akıl saz

                                    söz ise edep

                                    aşk bestelenir hep...

                                    aşk bestelenir hep...', 'olunca;                                      akıl saz                                     söz ise edep                                     a...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/beste-kar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbula kar yağıyor', 'i-stanbula-kar-yagiyor-bugra-demirhan-qzxh2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'istanbulda kar yağıyor.. küçüğüm gelme diyor bana buralarda kar var.. bursa misafirlerine yağmıyor kar..istanbulda kar yağıyor benim canım acıyor.. Oysa ne istanbul dayanabilir benim yangınıma nede sokağına yağan kar taneleri...

 Ne o gelmemi istiyor nede istanbul.. oysa içimdeki yangın ne istanbuldaki kar ı dinliyor nede bursadaki zamansız gelmeleri.. gelme sözcüğünün yaktığı kadar yakmıyor istanbula yağan kartaneleri...

 İstanbula kar yağıyor.. haber bültenleri bağırıyor zincirsiz çıkma yola.. ben zincirimi çoktan kopardım habersiz bültensiz kadınıma..', 'istanbulda kar yağıyor.. küçüğüm gelme diyor bana buralarda kar var.. bursa misafirlerine yağmıyor kar..istanbulda kar yağıyor benim canım a...', ARRAY['Türk Edebiyatı','Şiir','Bugra Demirhan']::text[], 8.5, '{"poet":"Bugra Demirhan","poet_slug":"bugra-demirhan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/istanbula-kar-yagiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Men Seni Sevirem (Azeri Derlenmiş Türkü)', 'kiz-men-seni-sevirem-azeri-derlenmis-turku-seyfet-bozcali-d19js', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Köynümce sevdim seni,

Eşkınnan oldum deli,

İnan Mecnuna döndüm,

Seni sevdim,seveli.

Kız men seni sevirem,

Yar men seni sevirem,

El sözüne inanma,

Vallah seni sevirem...

Sevgine inanarak,

Gerçek aşık sanarak,

Kerem gibi yanarak,

Kız men seni sevirem.

Kız men seni sevirem,

Yar men seni sevirem,

El sözüne inanma,

Vallah seni sevirem...

Sevgin üreyim yağar,

Günbe gün derdim artar,

Ferhat''ın eşkı kadar,

Kız men seni sevirem.

Kız men seni sevirem,

Yar men seni sevirem,

El sözüne inanma,

Vallah seni sevirem...

      1977 Yöresi Kars', 'Köynümce sevdim seni, Eşkınnan oldum deli, İnan Mecnuna döndüm, Seni sevdim,seveli. Kız men seni sevirem, Yar men seni sevirem, El sözüne in...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kiz-men-seni-sevirem-azeri-derlenmis-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
