INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fani Dünya''da Yan Biçare', 'fani-dunya-da-yan-bicare-yusuf-onder-bahceci-2f409', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel bu fani Dünya''da yan biçare,

Gel de sen bu hâline yan biçare,

Yârini eller almışsa varmı  biçare,

Gel bu fani Dünya''da yan biçare.

Bu derdin çaresi varmı ki bi çare,

Sevdiğini el almış varmı ki biçare,

Bu derdin çaresi yoktur bi çare,

Gel bu fani Dünya''da yan biçare.

Ancak böyle şiir yazarsın bi çare,

Şiir yazmak neyi halleder biçare,

Gelmez elinden başka şey biçare,

Gel bu fani Dünya''da yan biçare.

Şiirler yazıp ta ağla sen bi çare,

Allah''a dualar edip te ağla biçare,

Ahın yakar bu zalimleri bil biçare,

Gel bu fani Dünya''da yan biçare.', 'Gel bu fani Dünya''da yan biçare, Gel de sen bu hâline yan biçare, Yârini eller almışsa varmı  biçare, Gel bu fani Dünya''da yan biçare. Bu de...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fani-dunya-da-yan-bicare-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanadır İsyanım', 'sanadir-i-syanim-mustafa-tas-5ubpu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilemezsin.

Sanadır isyanım

Uyandığım her yalnızlık 

Kaçtığım tüm duygular sana.

Anlasana.....', 'Bilemezsin. Sanadır isyanım Uyandığım her yalnızlık  Kaçtığım tüm duygular sana. Anlasana........', ARRAY['Türk Edebiyatı','Şiir','Mustafa Taş']::text[], 8.5, '{"poet":"Mustafa Taş","poet_slug":"mustafa-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sanadir-isyanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana-Sana-Anlatılanalara Göre', 'bana-sana-anlatilanalara-gore-muhammed-mehmet-gul-qhpnr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana göre

Ellerimin varlığı bir varsayım

Aslında ben yüzyıllar öncesinde

Bir esir gemisinde yaşlı bir forsayım

Bana göre

Sana göre

Kahkahaların ortasında tasayım

İstediğin doğduğum günün gecesinde

Yaşlı incir ağacına gövdemi asayım

Sana göre

Anlatılana göre

Senin karşında hergün büyüyen İsayım

Beni tarife gücün yetmez

Kızıldenizin ortasında Asay-ı Musayım

Anlatılana göre.', 'Bana göre Ellerimin varlığı bir varsayım Aslında ben yüzyıllar öncesinde Bir esir gemisinde yaşlı bir forsayım Bana göre Sana göre Kahkahala...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bana-sana-anlatilanalara-gore-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelen Gidiyor', 'gelen-gidiyor-hifzi-ozbekmez-uhrdh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GELEN GİDİYOR

Güvenme yalan dünyaya

Unutma gelen gidiyor

İster kaç güneşe aya

Kural bu gelen gidiyor

Olsan uzun olsan kısa

Gönlüne getirme tasa

Allah’tan değişmez yasa

Kural bu gelen gidiyor

Fark etmiyor güzel çirkin

Kalmaz orda hiçbir farkın

Bir günde  omzunda halkın

Kural bu gelen gidiyor

Saçın olsun ister sırma

Tavsiyem kimseyi kırma

Sen kafanı boşa yorma

Kural bu gelen gidiyor

İster zengin ister fakir

Görme kimseyi sen hakir

Mevlayı eyle gel zikir

Kural bu gelen gidiyor

Latif dinecek göz yaşın

Kesilecek ekmek aşın

Dikilir mezara taşın

Kural bu gelen gidiyor

05  EKİM  2005  SAAT: 02:00', 'GELEN GİDİYOR Güvenme yalan dünyaya Unutma gelen gidiyor İster kaç güneşe aya Kural bu gelen gidiyor Olsan uzun olsan kısa Gönlüne getirme t...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gelen-gidiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 52', 'guncel-beyitler-52-huseyin-avdic-rcf93', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kesilmesi Gereken Agac

