INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutarlılık', 'tutarlilik-hasan-kostak-cobtv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yakındın ve uzaktın

Heran bu ikisini yaşatabilirdin bana 

Çizgi çok ince

Ama sonunda tutarlılık

Artık hep uzaktasın', 'Yakındın ve uzaktın Heran bu ikisini yaşatabilirdin bana  Çizgi çok ince Ama sonunda tutarlılık Artık hep uzaktasın...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kostak']::text[], 8.5, '{"poet":"Hasan Kostak","poet_slug":"hasan-kostak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tutarlilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Her Şey Negatif', 'bende-her-sey-negatif-tulay-sustam-j86tx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'otuz iki dişiyle

gülerken sana hayat

adımın üstünden

yirmilik dişini çekme



8 şubat''a şiir...', 'otuz iki dişiyle gülerken sana hayat adımın üstünden yirmilik dişini çekme 8 şubat''a şiir......', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bende-her-sey-negatif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Kızın Hikayesi 20', 'deli-kizin-hikayesi-20-can-ozcan-ozkan-89zay', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün

Kalbimden geçtiğin bir anda

Belirdin karşımda tutulan dilek gibi

Onca yaşanmışlıklara hiç der gibi 

Selamladın gördüğün bedeni

Ruhsuz...

Ruhumu kaldırımlara vura vura

Salındın yanımdan yabancı gibi

Bakamadım gözlerindeki

Çiğ düşmüş güle

Söyleyemedim sana

Beni bıraktığın yerin sensizliğini

Ve 

Tekrar yazılıyor

Deli kızın Hikayesi...

Bilmem kaçıncı oldu

Yazdığım değil! 

Bana bakmayışın

Bana bakmayışın

Kaçıncı...', 'Bugün Kalbimden geçtiğin bir anda Belirdin karşımda tutulan dilek gibi Onca yaşanmışlıklara hiç der gibi  Selamladın gördüğün bedeni Ruhsuz....', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deli-kizin-hikayesi-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlat', 'hatirlat-hasan-kostak-kitmz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman geldin

Ne zaman gittin

Ne zaman ağladım

Ne zaman unutmaya başladım

Unuttum gelde bir hatırlat hadi', 'Ne zaman geldin Ne zaman gittin Ne zaman ağladım Ne zaman unutmaya başladım Unuttum gelde bir hatırlat hadi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kostak']::text[], 8.5, '{"poet":"Hasan Kostak","poet_slug":"hasan-kostak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hatirlat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minör Telaş', 'minor-telas-oktay-baykurt-n0rdm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'minör bir telaş bu

kahyası notalardan sol

uşağıysa solfejsiz bir seshadi tıngırdatalım bu bestevari işisen kanun çalben  kemandurduk yerde biter mi dersinoturarak yapar mıyız bu işisöyler miyiz  bir raksı endülüsdudak tokuşmaları yapar mıyız bu hızlanasırlaşsın zaman terimizdekanunun telleri kırılsın hışmındankemanın nihavendi kaçsın kulalklardanminör bir telaş buyazılmamış bir sözebeste aramak gibi insafsızcatiz bir isteğin safsatası sadecemarkasız bir şefin yönettiği sevgi belki de', 'minör bir telaş bu kahyası notalardan sol uşağıysa solfejsiz bir seshadi tıngırdatalım bu bestevari işisen kanun çalben  kemandurduk yerde b...', ARRAY['Türk Edebiyatı','Şiir','Oktay Baykurt']::text[], 8.5, '{"poet":"Oktay Baykurt","poet_slug":"oktay-baykurt","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/minor-telas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur ateş ve odun', 'yagmur-ates-ve-odun-baran-demir-03h3x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmur damlası bu 

Yüzüme düşen 

Sıcacık odun ateşinin aydınlığıyla 

Ardı ardına düşmek de 

Bulutlardan süzülerek 

Gecenin karanlığında 

Parıldayan ateş kıvılcımlarına 

Karışarak dans edercesine 

Ateş yağmur tanesine sevdalı 

Yağmurda ateşi söndürmek de inatcı 

Attırıyor şiddetini 

Vurdum duymaz hoyratça 

Düşmek de sevda çeken ateşe 

Ateş ve yağmur damlası 

Biri içimi ısıtıyor 

Biride yanan odunun 

Hayat kaynağı 

Aslında bakmayın yağmura 

Hayat olduğu 

Besleyip büyüttüğü ağacın 

Kül olup gitmesine içerliyor 

Ağlaması da bundan 

Yağmurun ateşe öfkesi de bundan 

Ne emekle gün gün hayat olduğu 

Yılarca beslediği ağacı 

Odun olmuş yanıyor 

İşte yagmur damlası buna içerlemiş 

Ateşi söndürmeye çalışıyor 

Aslında yağmur damlası 

Yeşile sevdalı 

Oysa sevdası yok olup gidiyor', 'Yağmur damlası bu  Yüzüme düşen  Sıcacık odun ateşinin aydınlığıyla  Ardı ardına düşmek de  Bulutlardan süzülerek  Gecenin karanlığında  Par...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yagmur-ates-ve-odun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İspiyon 1', 'i-spiyon-1-hasan-kostak-73zcw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinle konuşacağım uzun uzun

İzin vermesende

Çığlık atıyorlar bak 

Sen kaçır onları

Örtüşmüyor sözlerin

İnadına yalanını ispiyonluyor çığlık çığlığa gözlerin', 'Gözlerinle konuşacağım uzun uzun İzin vermesende Çığlık atıyorlar bak  Sen kaçır onları Örtüşmüyor sözlerin İnadına yalanını ispiyonluyor çı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kostak']::text[], 8.5, '{"poet":"Hasan Kostak","poet_slug":"hasan-kostak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ispiyon-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Danimarka (akrostiş)', 'danimarka-akrostis-selim-basar-wxb36', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Danimarka domuz soyu  soysuzluğun eşiği 

Adın hayvan listesinde hayvandanda aşağı 

Nadanlık sana ödül, cühelalık kavşağı 

İmansızlar güruhu eyy  cehennem aşığı

Meymenet mahrumu sen, abd nin kırığı 

Aptalın daniskası,  beyinsizin şaşığı

Rahat batmış gayrı yerin, aşağıdan aşağı

Kalleşin son durağı, haç küfrünün uşağı

Arsızlığın  toprağı,  dinsiz fitne başağı..

O, mikrop''ki göremezsin bedenin iflas eder;

Huzur içinde cihanı üç mikrop ifsad eder...', 'Danimarka domuz soyu  soysuzluğun eşiği  Adın hayvan listesinde hayvandanda aşağı  Nadanlık sana ödül, cühelalık kavşağı  İmansızlar güruhu ...', ARRAY['Türk Edebiyatı','Şiir','Selim Başar']::text[], 8.5, '{"poet":"Selim Başar","poet_slug":"selim-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/danimarka-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arife söz gerek', 'arife-soz-gerek-ali-riza-unal-q1v4z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu dür-ü kelama,seyranı göz gerek,

sindedir meram,hayranı öz gerek,

bir lûtfu fenaki,nicedir meâli idrak,

kül olur  varın,bu mecale köz gerek,

Peyman verdim yare,cilve-i naz gerek

Hak oldu melam,aşığa haz gerek

Budur ahde vefa,zulumdur gafile idrak,

Ne keramet ne mucize,arife söz gerek', 'Bu dür-ü kelama,seyranı göz gerek, sindedir meram,hayranı öz gerek, bir lûtfu fenaki,nicedir meâli idrak, kül olur  varın,bu mecale köz gere...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/arife-soz-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peri Kızı', 'peri-kizi-yuksel-kasim-im5a5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Peri Kızı gibi süzülüver bana

Masallardan,rüyalardan; 

Peri Kızı gibi öpüver kalbimden

Belli belirsiz.

Parmaklarımın ucuyla

Sana dokunurken

İncinirsin diye korkardım.

Kristal vazoda duran

Gonca güller gibi narin

Diye düşünürken…

Düşüverdin ansızın kollarımdan.

Ben seni unutmam Peri Kızı,

Ihlamur çiçeği,Çoban Yıldızı.

Süzülüver sen yine

Yalnız gecelerime,rüyalarıma; 

Öpüver yine beni kalbimden

Belli belirsiz.

				

12 Mayıs 1998

Aydın', 'Peri Kızı gibi süzülüver bana Masallardan,rüyalardan;  Peri Kızı gibi öpüver kalbimden Belli belirsiz. Parmaklarımın ucuyla Sana dokunurken ...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Kasım']::text[], 8.5, '{"poet":"Yüksel Kasım","poet_slug":"yuksel-kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/peri-kizi-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Domates', 'kucuk-domates-yuksel-kasim-juhy5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bir küçük domatesim

Hep ama hep seni sevdim.

Biriciğim,yazım benim,

Güneşim,dalım benim,

Suyum,böceğim,ilacım,yaprağım,

Toprağım,köküm benim.

Vazgeçemediğim.

2 Şubat 2003

Arga', 'Ben bir küçük domatesim Hep ama hep seni sevdim. Biriciğim,yazım benim, Güneşim,dalım benim, Suyum,böceğim,ilacım,yaprağım, Toprağım,köküm b...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Kasım']::text[], 8.5, '{"poet":"Yüksel Kasım","poet_slug":"yuksel-kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kucuk-domates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağ', 'bag-hasan-kostak-q8exf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tren yolunun bir ucu sende

Diğer ucu bende

Birbirini görmeyen iki ayrı şehir

Arada kalmış şehirler 

Gelip gitmeler', 'Tren yolunun bir ucu sende Diğer ucu bende Birbirini görmeyen iki ayrı şehir Arada kalmış şehirler  Gelip gitmeler...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kostak']::text[], 8.5, '{"poet":"Hasan Kostak","poet_slug":"hasan-kostak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bag-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Hayat Öylece Kaldı', 've-hayat-oylece-kaldi-yuksel-kasim-sd2xj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gökyüzünü çok severdin; 

Denizi de…

Çünkü sen maviyi severdin.

Hatta mavi bir elbisen vardı

Ve mavi ayakkabıların.

Ben de seni severdim; 

Severdim işte…

Çünkü beni

Mavi düşlere salan

Rüzgarlı saçların vardı.

Ama ben gökyüzü olamadım; 

Olamadım denizler gibi…

Ve hayat öylece kaldı

Bıraktığım yerde.

Karışıklıklar bıraktım

Benden sonra gelenlere.

Ve hayat öylece kaldı

Beni bıraktığın yerde.

Gökyüzü oldum şimdi

Hayatı bıraktığım yerde.

9 Eylül 2004

Aydın', 'Sen gökyüzünü çok severdin;  Denizi de… Çünkü sen maviyi severdin. Hatta mavi bir elbisen vardı Ve mavi ayakkabıların. Ben de seni severdim;...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Kasım']::text[], 8.5, '{"poet":"Yüksel Kasım","poet_slug":"yuksel-kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ve-hayat-oylece-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken', 'giderken-yuksel-kasim-lcx4j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden öncesini sildim

Senden sonrası zaten yok

Tek harfli alfabemsin benim

Bütün cümlelerimi seninle kurdum

Bütün yazılarımı seninle yazdım

Hiçbir zaman anlayamadım

Hayır deyişinin altında yatan sebebi

Sislerin arasında kayboldun

Biliyorum dönmeyeceksin artık geri

Koştum ardından yorulmadım

Aradım seni ama bulamadım

Giderken

Savurduğun saçların kaldı aklımda

Bir de o çaresiz bakışın

11 Mayıs 2004

Aydın', 'Senden öncesini sildim Senden sonrası zaten yok Tek harfli alfabemsin benim Bütün cümlelerimi seninle kurdum Bütün yazılarımı seninle yazdım...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Kasım']::text[], 8.5, '{"poet":"Yüksel Kasım","poet_slug":"yuksel-kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/giderken-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor', 'zor-sultan-mustafa-cfbwv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneş selama durursa sabah akşam

Tekmil alıp

Vatanın ovasından dağından

Ve

Bire bin verirse bu topraklar

Bu yurt, bu bayrak için

Bu millet 

Bu koca millet

YAAR diye haykırmalı.

Gelirse Çin tebessümü

Tarih öncesinden

Zakkum yüklü ipeklerle

Ve 

Giderse akıl baştan

Yılan ıslıklı bir sarıyla, kızılla

Bu millet

Bu koca millet

DUUR diye haykırmalı

Derman tükenir, takat kalmazsa

Yürümeye

Yedi yön, sekiz taraftan çevrilirse namlular

Üstümüze

Ve

Çare arayan olursa ümitsizliğe

Gecenin kör karanlığında

Bu millet

Bu koca millet

VAAR diye haykırmalı

Şaşırıp yolunu

Topuyla tankıyla girmek isterse birileri

Sınırlardan

Ve 

Gaflet uykularının on beşinde

Gören olursa ihanet düşleri

Bu millet

Bu koca millet

ZOOR diye haykırmalı

Tamtamlar çalınırsa olura olmaza

Ateş üstünde danslar yapılırsa

Ritmini başkaları vuran

Ve

Sezerse hainleri

Başka türkülere sevdalı

Bu millet

Bu koca millet

VUUR diye haykırmalı', 'Güneş selama durursa sabah akşam Tekmil alıp Vatanın ovasından dağından Ve Bire bin verirse bu topraklar Bu yurt, bu bayrak için Bu millet  ...', ARRAY['Türk Edebiyatı','Şiir','Sultan Mustafa']::text[], 8.5, '{"poet":"Sultan Mustafa","poet_slug":"sultan-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/zor-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Az', 'az-kenan-taskin-vgdiu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kabaran deniz kapatmaz yüreğimdeki yarayı

Belki bu yüzden yağmur yağar üzerime

Dar gelir gönlümdeki barakaya, yarin sarayı

Bu da az gelir sürgündeki sebebime', 'Kabaran deniz kapatmaz yüreğimdeki yarayı Belki bu yüzden yağmur yağar üzerime Dar gelir gönlümdeki barakaya, yarin sarayı Bu da az gelir sü...', ARRAY['Türk Edebiyatı','Şiir','Kenan Taşkın']::text[], 8.5, '{"poet":"Kenan Taşkın","poet_slug":"kenan-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/az-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustum', 'sustum-aysegul-gedik-bj4zl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinde ışığı gördüm

Bakarken çocuksu sevincini

Heyecanını...

gözlerim yanıt vermekten korktu önce

sonra onlarda aynı ışıkla baktı

yıldız gibi ışıldayan gözlerine...

göz bebeklerinde kendimi gördüm

bakışlarında manalar...

uçalım gökyüzüne diyorlardı

karışlım semanın maviliklerine

ayaklarım yerden kesiliyordu adeta

çocuklar gibi seviniyordu yüreğim

yüreğinde ki sıcaklığı hissettim yüreğimde

simsicak yaptı yüreğimi

kıpırtılar hissettim yüreğimde

heyecanla korku arası met cezirler

bir çocuğun yıllarca hayal ettiği oyuncağına kavuşma sevinci gibi

ve bir daha asla kaybetmeme güven ve hissi

sonra

gözlerinde yalanı gördüm

önce inanamadım ve tekrar tekrar baktım gözlerine

içim acıdı 

yüreğim yandı

ve o an gördüm ki,

o yıldız gibi parıldayan gözler başkasını aydınlatıyordu

simsicak sandığım

ve 

paha biçemediğim yüreğini

meğer vermişin bir başkasına, üç kuruş...

Sonra kendimce en iyisini yaptım 

ve kilit vurdum yüreğime

ve attım anahtarını en dipsiz Ummanlara

ve yumdum gözlerimi 

bir daha açmamak üzere aşka

ve sustum....', 'Gözlerinde ışığı gördüm Bakarken çocuksu sevincini Heyecanını... gözlerim yanıt vermekten korktu önce sonra onlarda aynı ışıkla baktı yıldız...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Gedik']::text[], 8.5, '{"poet":"Ayşegül Gedik","poet_slug":"aysegul-gedik","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sustum-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Dudağının Arasındadır Aşk...', 'i-ki-dudaginin-arasindadir-ask-perver-bozan-uo9p0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum! 

Çünkü henüz değmese de yüreğin yüreğime, 

Değecek mutlaka.

Hissedeceksin ben her ne hissedersem... 

Hissedeceksin aldığım nefesi, 

Uzaklara dalan düşüncelerimi, 

Hissedeceksin sana olan sevgimi... 

Her daim kulaklarında çınlayacak, 

Seni düşünürken keyiflendiğimde çaldığım ıslık... 

Sarılırken kulağına fısıldayacağım aşk sözleri. 

Gel artık söyle sende, 

Gel artık sende koy ver hislerini... 

Yüreğimin içindeki en güzel düş bahçelerini ayırdım sana! 

Mutluluğu yaşayacağız... 

Bir ömür doya doya.

İki dudağının arasındadır aşk! 

Gel sende söyle beni sevdiğini...

Başlayalım bu aşkı yaşamaya.', 'Seni seviyorum!  Çünkü henüz değmese de yüreğin yüreğime,  Değecek mutlaka. Hissedeceksin ben her ne hissedersem...  Hissedeceksin aldığım n...', ARRAY['Türk Edebiyatı','Şiir','Perver Bozan']::text[], 8.5, '{"poet":"Perver Bozan","poet_slug":"perver-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/iki-dudaginin-arasindadir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uslanmaz Asi', 'uslanmaz-asi-perver-bozan-suya4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben asiyim...

İster yiğit ister serseri de bana.

Gözüm senden başkasını görmez...

İster deli ister aşık de bana.

Hem susarım hem severim seni,

Yiğitsen gel de uslandır beni.', 'Ben asiyim... İster yiğit ister serseri de bana. Gözüm senden başkasını görmez... İster deli ister aşık de bana. Hem susarım hem severim sen...', ARRAY['Türk Edebiyatı','Şiir','Perver Bozan']::text[], 8.5, '{"poet":"Perver Bozan","poet_slug":"perver-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/uslanmaz-asi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Destanlar..', 'destanlar-mehmet-coban-jhhyi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürürken yolda, 

Bir yazı gördüm panoda

Anılacaktı yiğitler, efeler

Söylenecekti türküler

Önce gülüp geçtim

Aklıma gelenlerle ürperdim….

O destanları yazanlar

Anılarımda canlandılar

“Kimi, zalimin zulmüne

Kimi, vatanı işgal edene

Kimi, haine ihanete

Kimi, aşka sevgiye

Çıkmış dağa

İnmiş sokağa

Kiminin kılıç elinde

Kiminin tabanca belinde

Vurmuş kendini düşmana

Dayanmış bir kutsal savaşa

Yol olmuş, 

Yol vermiş

Yazdırmış adını

Ulu destanlara

Kiminden kalmış güzel öyküler

Kiminden kalmış güzel türküler

Kiminden kalmış güzel töreler

Kiminden kalmış güzel oyunlar

Kiminden kalmış güzel havalar

Simdi sen sanır mısın ki? 

Haksızlık, zulüm var diye

Ülkem çağdaş işgalde diye

Adaletsizlik aldı yürüdü diye

Bir destanda sen yazmak için

Hak, adalet ve özgürlük için

Çıksan aşılmaz dağlara

Dalsan kalabalık sokaklara

Yazabilir misin? 

Hayır! ..

Koskoca bir hayır! ..

Sakın örnek alma destanlarını

O destanları öğren oyalanmak için

Çal, türkülerini söyle, oyna oyunlarını

Düşünüp, destanlar yaratmamak için

Unutma! ..

Destanlar sana sadece oyalanmak için! ..

Unutursan eğer…..

Dünyayı başına dar ederler bak ne biçim! ..

07.02.2006-İzmir', 'Yürürken yolda,  Bir yazı gördüm panoda Anılacaktı yiğitler, efeler Söylenecekti türküler Önce gülüp geçtim Aklıma gelenlerle ürperdim…. O d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/destanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YB-26 Eleman alınıyor', 'yb-26-eleman-aliniyor-mehmet-coban-6lfo5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir dağın orta tepelerinde

Güzel bir çay bahçesinde

Ülkemi seyrediyorum

Ve derin, derin düşünüyorum

Düşüncelerim,

Neşeli, tehlikeli, üzgün

İçimi kaplıyor hüzün

Bir senaryo canlanıyor hayalimde

Dökülüyor hayalim dizelere

Şehrin kalabalık orta yerinde

Koca bir binanın önünde

Kalabalık bir kuyruk görüyorum

Onlara doğru yürüyorum

Kuyruk iki tane

Biri bina yönüne

Diğeri binanın tersine

Bina yönüne olanlar sıra bekliyor

Tersine olanlar işini bitirmiş geliyor

Sordum kuyruğun sonundakine

Ne kuyruğu bu, ne bu hal diye? 

Biri bilmiyorum dedi safça

Herkes girmiş girdim kuyruğa

Bak binanın camında yazıyor

Duydum ki eleman alınıyor

Öğrenmek için yürüdüm binaya

Yürürken baktım sağıma soluma

Tanıdığım birçok kişi girmiş kuyruğa

Bekliyor gelsin diye sıra

İşini bitirip gelenler arasında

Tanıdıklarım ulaşmış mutluluğa

O kadar çok meraklandım

İşin aslını öğrenmek için hızlandım

Yaklaştım kapıda asılı yazılara

Başladım hafiften okumaya

“ Eleman Alınıyor

   Şartları aşağıda yazıyor”

“Kültürlü kültürsüz fark etmez

Dinli dinsiz bizi ilgilendirmez

İster siyasetçi, ister bürokrat

İster cahil ister aristokrat

Öğrencide olur öğretmende

Bulunabilecek her görevde

Tercihtir, basıncı yayıncı

Tercihtir, kendi kültürüne yabancı

Dünyayı yönetmek için çıktık yola 

Yardımcılar lazım bize haberiniz ola

İster ücretli

İster ücretsiz

İster gönüllü 

İster gönülsüz

Eleman aranıyor

Sadece bir şartla

Aklı başına gelince

El aman dedirtmeyecek

Ne yaparsak yapalım 

Bize sadık kalacak

Her zaman her yerde

Sürekli bizi övecek

Asla halkını düşünmeyecek

Hep bizim çıkarlarımızı gözetecek

Dese de vatan millet Sakarya

Bize olması gerekecek palikarya

Bulduk mu biz böylesini

Donatırız ona her şeyi

Para güç her şey bizde

Çok şükür dünya elimizde

Veririz her türlü makam mevki

Dayarız döşeriz yaşayacağı yerleri

İnsanları öldürsekte

Bütün halkları sömürsekte

Ağlatsakta,  güldürsekte

Yağsak gürlesekte

Olacak hep yanımızda

Olmayacak hiç karşımızda 

Sırrımızı vermeyecek kimseye

Yalanımızı söylemeyecek yüzümüze

       

 Unutmayın, 

Her zaman güçlüden yana olun

Yoksa kırılır kanadın kolun

Düşünmeyeceksin mazlumu düşeni

Düşünmeyeceksin hakkı, adaleti 

Eleman olacaklara

Müracaat yandaki oda”

Şaştım kaldım 

Oradan uzaklaştım

Dedim işsiz aşsız kalsam da

İşim yok böyle uşaklıkta

Kuyrukta sıra bekleyen

Kimler gördüm kimler

Kendini kaydettiren

Kimler gördüm kimler

Söylemeye dilim varmaz

Ben utanırım onlar utanmaz

Zaten söylemeye gerek yok

Onları size tanıtacak alamet çok

Hızlıca yürürken sokaklarda

Bir başka kalabalık daha

Yine büyük bir bina var ortada

Yine bazıları eleman kuyruğunda

Kiminde ABD, kiminde Avrupa

Yazıyor binalarının kapısında

07.02.2005-İzmir', 'Bir dağın orta tepelerinde Güzel bir çay bahçesinde Ülkemi seyrediyorum Ve derin, derin düşünüyorum Düşüncelerim, Neşeli, tehlikeli, üzgün İ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":102,"source_url":"https://www.antoloji.com/yb-26-eleman-aliniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yb-30 Seçmeler', 'yb-30-secmeler-mehmet-coban-r4qkl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tarih jürisi toplanmış

Beğendiklerini tarihe yazacakmış

Bende girdim kuyruğa

Baktım şöyle etrafıma

Geçmişten, günümüzden, yarınımızdan

Yazılmak için sıra bekleyen bir sürü insan

Hepimizi aldılar büyük bir salona

Jüri insanları sorguluyor karşısında

Hem jüri dinliyor, hem bekleyenler

Kulakları çınlatıyor söylenenler

Duyduklarımı hilafsız aktarıyorum

Siz jüri olun yapın yorum

Sırayla sunuyorum size

Notlarınızı geçirin önünüze

“Ben uğraşırım sanatla

Bazen resim yaparım

Bazen yazı yazarım

Bazen şiir yazarım

Uğraşmam onunla bununla

Karışmam hiçbir kavgaya

Kendimle barışık yaşarım

İnsanlarla barışık yaşarım

Eserlerimi sunarım ortaya

Yazılmak isterim tarih sayfalarına”

İnsanlar baktı alaylı gözlerle

Jüri başkanı söyledi alaylı sözlerle

Yaşarken sürüm, sürüm sürüneceksin

Yaptıklarınla arkandakileri güldüreceksin

Arkandakiler yaptıklarınla övünecekler

Adını, eserlerini üstlenecekler

Kendilerine seni kılıf yapacaklar

Adına, eserlerine, sığınacaklar

Kendileri şan ve şöhrete konacak

İsimleriniz bunun için anılacak

Ürettikleriniz paraya çevrilecek

Senin yiyemediğini sonrakiler yiyecek

“Ben asil ve güçlü biriyim

Vardır önü alınmaz hayallerim

Topladım bana güvenenleri ardıma

Haykırdın erkekseniz çıkın karşıma

Önüme çıkanı ezdim yok ettim

Binlerce milyonlarca insan katlettim 

Fethettim ülkeleri bir, bir

Ölenleri saymam, yaşayanlar benimdir

Bütün ülkelerin altını üstünü isterim

Bana karşı duranı affetmem gebertirim”

İnsanlar baktı ona hayran, hayran

Çocuklar etti sanki bayram

Oleeee..   be, işte bu diye bağırdılar

Aslansın, kahramansın diye haykırdılar

Kadınlar, kızlar çiçek attılar

Anlamlı anlamlı aralarında fısıldaştılar

Diğerleri kahramanı kıskandılar

Jüri başkanı ayağa kalktı saygıyla

El etek öptü, divan durdu karşısında

Merak etme efendim diye söze başladı

Sana ayıracağız en büyük sayfaları

“Efendim ben neferim

Ben kahramanlara askerim

Ben öldüm onlar yaşadı

Ben unutuldum onlar kahramandı

Bende öldürdüm onların emriyle

Onlar övülüyor, ben övülmüyorum niye? 

Ben olmasaydım onlar başaramazdı

Bana da ayırın biraz sayfaları”

Uğultu koptu halk arasında

Konuştular sürekli aralarında

Diyorlardı ne işi var onun burada

Değer mi kaybettiğimiz zamana

Jüri üyeleri baktılar alayla

Gülüştüler hep sırayla

Başkan dedi adamlarına

Yahu ne işi var bunun burada

Çıkarın atın onu dışarıya

Adam dışarıya çıkarken 

Sesler yükseldi üyelerden

Yahu bize ne pisipisine ölenlerden

“Efendim ben çok zekiyim

Her zaman işimi bilirim

Çıkardır benim ilkem

Çıkarım uğruna hiçbir şey dinlemem

Savaş barış beni ilgilendirmez

Bana para kazandırmayan beş para etmez

Barışta, savaşta kazanmasını bilirim

Kazandıklarımla dünyanın zenginiyim”

Halk arasında kaynaştılar

Kıskanç gözle bakıştılar

Hepsinin içi gitti birden

Etkilendiler zengin efendiden

Jüri başkanı ayağa kalktı

Arzı endam etti önünde

Efendimle başladı sözlere

Sizi hep takdirle karşıladık

Ama ilke gereği tarihe yazamadık

Özürlerimizi lütfen kabul et

Biz seni yazmasak ta sen bizleri var et! ..

“Biri öne çıktı mütevazılıkle

Başladı saygıyla söze

Efendim ben halktan biriyim

Zenginle, siyasetçiyle, kahramanla

Başı sürekli dertliyim

Siyasetçiler yönetti yalanlarıyla

Zenginler kandırdı paralarıyla

Kahramanlar yapıştı yakamıza

Bize asker lazım deyip götürdüler

Cephelerde hep öne sürdüler

Her birimizi tek, tek öldürdüler

Kendileri oldu kahraman

Bizler olduk sürekli figüran

Canları istedi karımızı kızımı aldılar

Canları istedi oğlumuzu malımızı aldılar

Sormadılar bize hiç ne istersiniz? Diye

Hak vermediler hiç, verdiler köleliği hediye

Vergi verdik, can verdik, namus verdik

Hep yerden yerlere serildik”

Halk arasından yükseldi uğultular

Bağırdılar bozguncunun burada ne işi var? 

Sen kim oluyorsun çıkıyorsun oraya? 

Konuşup başımızı belaya  mı sokacaksın? 

Gel buraya başımıza bela olma sakın? 

Jüri baktı şöyle halktan birine

Esef etti ne hallere düştük diye

Jüri başkanı büyük bir hiddetle

Başladı sinirli, sinirli, sözlerine

Sen kim oluyorsun da tarihe yazılacaksın? 

Karşımıza çıkmaya utanmaz mısın? 

Sen nerede gördün halkın tarihe yazıldığını? 

Görmedin mi halk devrimlerinde bile asillerin yazıldığını? 

Çabuk yıkıl karşımızdan bizi daha çok sinirlendirme? 

Haddini bil, dön kendi yerine! .............

Atmosfer çok kötüydü

Söyleyecektim doğru sözü

Ne olursa olsun dedim

Jürinin karşısına dikeldim

“Ben insanım, insan

Söyleyemem asla yalan

Haksızlık var yaptığınızda

Kan ve gözyaşı dökenler başınızda

Hakları alınanlar ayalarınızın altında

Böyle gerçekler yazılmaz

Böyle saçmalıklar insanlığa sığmaz”

Başkan ayağa kalktı hiddetle

Sen kimsin ki, işimizi öğretiyorsun  bize? 

Sen tarihten ilimden ne anlarsın? 

Sen lafını bilmez aptallardansın! ..

Hey görevliler atın bunu dışarıya

Yaklaştırmayın ne buraya, ne insanlara

Fikirleriyle, her şeyi bulandırıyor

Önü alınmaz şeylerle insanları düşündürüyor

Bilmiyor her devirde düşüncenin suç olduğunu

Bilmiyor düşünce özgürlüğünün oyalama olduğunu

Oyalama için verdiklerimizi gerçek sandı

Bakın görün işte, kendini ele verdi yakalandı

Hemen oradan kaçtım

Yaşadığım dünyaya şaştım

Bilim, ilim, tarih hikâye

Yasak konulmuş hep düşünmeye

Sadece güçlüler sahip özgürlüklerine

Bilmiyorum ben gittikten sonra ne oldu

Hangileri tarihe yazılıp, hangileri yok oldu…

07.02.2006-İzmir', 'Tarih jürisi toplanmış Beğendiklerini tarihe yazacakmış Bende girdim kuyruğa Baktım şöyle etrafıma Geçmişten, günümüzden, yarınımızdan Yazıl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":161,"source_url":"https://www.antoloji.com/yb-30-secmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-059 Gecede doğdum', 'ub-059-gecede-dogdum-mehmet-coban-tla47', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecede doğdum 

Beklerim sabahı

Güneş doğacak 

Dünya aydınlanacak

Karanlıklarda yürüdüm

Yıldızların altında

Yaşadım hep umutlarla

Belki kavuşurum sabaha

Yıldızlara bakarım

Yol için kendime 

Yıldızları görürüm

Karanlıklar içinde

Ne yıldızlar gördüm

Duada güneş doğmasın diye

Ne yıldızlar gördüm

Sanki güneşi kıskançlık içinde

Sanki yıldızlar biliyor

Güneş doğunca kaybolacaklar

Güneşin önünde duruyor

Güneşi dünyaya salmayacaklar

Az kaldı şurada biliyorum

Sanki gecede doğdum 

Gecede öleceğim

Görmedim eskilerin anlattığı güneşi

Görmedim güneşin yaktığı ateşi

Bazen güneş doğdu diye duygulandım

Serapmış meğer gerçeklerle uyandım

Ufuklara bakıyorum dağların ötesine

Bekliyorum sabah olsun diye özlemiyle

07.02.2006-İzmir', 'Gecede doğdum  Beklerim sabahı Güneş doğacak  Dünya aydınlanacak Karanlıklarda yürüdüm Yıldızların altında Yaşadım hep umutlarla Belki kavuş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ub-059-gecede-dogdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Üzerine...', 'ask-uzerine-perver-bozan-6yowo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimileri akıllıdır! 

Aşk üzerine düşünür.

Kimi akıllılılar, aşkı biriyle bölüşür...

Herkes aşk için bir şeyler söyler.

Ben ne düşünürüm

Ne de konuşur...

Bana aşkı yaşaması düşer.', 'Kimileri akıllıdır!  Aşk üzerine düşünür. Kimi akıllılılar, aşkı biriyle bölüşür... Herkes aşk için bir şeyler söyler. Ben ne düşünürüm Ne d...', ARRAY['Türk Edebiyatı','Şiir','Perver Bozan']::text[], 8.5, '{"poet":"Perver Bozan","poet_slug":"perver-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-uzerine-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kacak Canbaz', 'kacak-canbaz-perver-bozan-remzf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlamakla, ağlamamak arasında kalmış... Gözlerim

Ve sevmekle, sevmemek arasında sıkışmış kalmış yüreğim.

Köhne bir gemidir benim ruhum,

Ne yelkeni ne direği var.

Kaybettiği huzuru,

Kayıp ruhlarda arar.

Artık ağlamak istiyorum her gün

Ve sonsuza kadar sevmeyi.

Herkes denizden kaçıp...

Sığınacak bir liman arar.

Ben arıyorum dingin denizimi.', 'Ağlamakla, ağlamamak arasında kalmış... Gözlerim Ve sevmekle, sevmemek arasında sıkışmış kalmış yüreğim. Köhne bir gemidir benim ruhum, Ne y...', ARRAY['Türk Edebiyatı','Şiir','Perver Bozan']::text[], 8.5, '{"poet":"Perver Bozan","poet_slug":"perver-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kacak-canbaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Bir Otopsi Raporudur', 'bu-bir-otopsi-raporudur-perver-bozan-erfai', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kan kırmızı gözlerimi görüp aldanma arkadaş! 

Ne uğruna ağlayacağım sevgi,

Ne düşünüp uykusuz kalacağım...

Sevgilinin gözleri var.

Hala diyorsan ki nedir bu gözlerinin hali? 

Anla be gülüm...

Ben dün gece öldüm! 

Teşhisi koyan doktor,

Yalnızlıkmış ölüme sebep dedi.

Yüzünde acılı bir ifadeyle titreyerek sesi,

Öyle ilerlemiş ki hastalık...

Bakın! 

Gözleri açık gitti.', 'Kan kırmızı gözlerimi görüp aldanma arkadaş!  Ne uğruna ağlayacağım sevgi, Ne düşünüp uykusuz kalacağım... Sevgilinin gözleri var. Hala diyo...', ARRAY['Türk Edebiyatı','Şiir','Perver Bozan']::text[], 8.5, '{"poet":"Perver Bozan","poet_slug":"perver-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-bir-otopsi-raporudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmeyen MEKTUP', 'gelmeyen-mektup-levent-i-skenderoglu-nfuiv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ruhun içini dolduran

Kıpkırmızı kan

Izdırap mı

Her gece yüreğime akan

Sordum kekik dağından

Henüz geçmemiş kervan

Lakin çığlıklar geçmiş ufuktan

Doğuran gökyüzüdür işte

Yol donmuş zamanda

Elde pusula yok

Parlayan tam o anda

Şimal yıldızıdır işte

İklim zamana zıt

Sonsuzluğa geçişte

Ne açıkta yara var

Ne teneşirde cenaze

Ne de taraf var 

Ey insan

Bu zerzenişte

Her kızıllıkta umdum 

Nefesimi tutup

Gelmeyecek anladım

Anam kokan o mektup

Ruhun içini dolduran

Kankırmızı kan

Korkuyor mu sonsuzdan

Yüreğimi okuyan

Sordum kekik dağından

Henüz geçmemiş kervan', 'Ruhun içini dolduran Kıpkırmızı kan Izdırap mı Her gece yüreğime akan Sordum kekik dağından Henüz geçmemiş kervan Lakin çığlıklar geçmiş ufu...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gelmeyen-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sataşma', 'satasma-hasan-kostak-ss7fu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelmeyeceksin belli bu

Bendende çok uzak olmayacaksın

Anılarımız sataşıp duruyor

Sanada musallat oluyorlarmı söyle', 'Gelmeyeceksin belli bu Bendende çok uzak olmayacaksın Anılarımız sataşıp duruyor Sanada musallat oluyorlarmı söyle...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kostak']::text[], 8.5, '{"poet":"Hasan Kostak","poet_slug":"hasan-kostak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/satasma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Sesi', 'sairin-sesi-mehmet-zeki-gezici-yevyu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1.

Çavdarın yulafın

ateşin ve şuyun

buğdaya karıştığı

ekmeğin içinde olmalı şairin sesi

darağaçinda

üzüm salkımı gibi sallanan

adamın son nefesinde olmalı.

2.

Kafası çıplak ayakları çıplak

adamın içinde olmalı şairin sesi

habersiz bir şarkı gibi dolaşmalı

ölüme dört nala koşan

milyonlarca kanserli hücrenin yarasında

olgun karadut gibi bereketli doktorun

kızıl bir gülün yaprakları gibi incelmiş

yüreğinde olmalı.

3.

Pamuktan ipekten ve bakırdan

ve darphanelerin bir pula çevirdiği

paranın içinde olmalı şairin sesi

portakalın çiçeğini dalına döşeyen

adamın ellerinde olmalı.

Sınır boylarını zulada geçen

ve devlet darphanelerinde

uçan kuşlardan habersiz

irsaliyesi bir yerde mendil gibi katlı

çarşı esnafına basılan

kirli altınların içinde olmalı.

4.

Medya kemiklerinin içinde şaklı orman kuşları

gözümüze Haymana ineği gibi bakan

hanımların göbeği çıplak mal beyanlarında

sesleri kırık omuzları çıplak oğlanların

şarkılarında olmalı şairin sesi.

Yaratan ve çürüten sıfırla bir

kafatasları bilgisayar uyumlu

çelik ve beton kıvrımlarının

tenleriyüksek cam kafeslerinin içinde

ömürleri mandaların göl kıyılarında bıraktıkları

iri kıvrımlı mayıs kokusundan mayalı

uçan sineklerin kanat uçlarını

kıllı bacaklarını karafatmaların

bütün ölülerin yalnızlığını kredi kartlarında

dört çekerli otomobillerin hızını

hormonlu kadın memelerinden iri

akü başlarından ateşleyen

medya kemiklerinin yüreğinde saklı adamların

dilinde akrep gibi olmalı şairin sesi.

5.

Toprak kokan rüzgarla bulutla

ardıç kuşlarının ölüm oruçlarına doğru

hücrelerinde tek başına kanat vuran

yarım kalmış

bir hayatın içinde olmalı şairin sesi

yapraklara başaklara sokak içlerine

ve seninle yürüken yüzümüze çarpan 

bir gözünde sevincin

yüreğinde hüznün yaşlarında olmalı 

bir bardak suyun içinde ıslanma korkusu

yağmurların sicim gibi çözmeli bulutları

kendini soğutan bir bardak çayın içinde.

yarım kalmış bir hayatın içinde olmalı.', '1. Çavdarın yulafın ateşin ve şuyun buğdaya karıştığı ekmeğin içinde olmalı şairin sesi darağaçinda üzüm salkımı gibi sallanan adamın son ne...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/sairin-sesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittikten Sonra', 'sen-gittikten-sonra-i-brahim-etem-bakir-yovb2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gittikten sonra

Başlıyor sancılarım,

Baş ağrılarım daha çok tutuyor; 

Hiç gitmeyesin istiyorum

Gitmesen de olmaz biliyorum.

Sen gittikten sonra

Çakıyor beynimdeki şimşekler

Sonra kalbime iniyor

Tam şuramda bir çarpma oluyor.

Sonra göğsüm.

Göğsümde de bir tuhaflık oluyor.

Ruhun, ruhumdan uzaklaştığından olsa gerek.

Doktora gitmeyi hiç düşünmedim

Adamın derdi ve dermanı bir olunca

Doktora gitme gereksinimi doğmuyor işte.

Gözlerinin gözlerime tutukluk yaptığı andır

Sancılarımın geçmesi…

Bana ırak olmadığın anlardır

Huzur içindeki yaşantım.

Bazen de unutu veriyorum

Anlatacaklarımı,

Söyleyeceklerimi,

Yazmak istediğim nağmeleri.

Bir şeyler konuşacağım geliyor

Konuşamıyorum; 

Buda korkularımdan değil.

Seni kırarım diye değil…

Seni kıracak ne söyleyebilirim ki

Böyle bir şeyi kim haddine sayabilir? 

Sen gitme ki

Tutmasın sancılarım

Ve ağrılarım.

Hem seninde gitme saatlerin çattığında

Gitmek istemediğin oluyor mu? 

Gitmen gerektiğini bile bile.

Gel, sen gitme kal.

Kal ki

Tutukluk yapmasın kalbim.

Ey kalbim.

E.B…', 'Sen gittikten sonra Başlıyor sancılarım, Baş ağrılarım daha çok tutuyor;  Hiç gitmeyesin istiyorum Gitmesen de olmaz biliyorum. Sen gittikte...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Etem Bakır']::text[], 8.5, '{"poet":"İbrahim Etem Bakır","poet_slug":"i-brahim-etem-bakir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sen-gittikten-sonra-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçinde', 'i-cinde-mehmet-zeki-gezici-6z7ku', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'cennet ve cehennem komşu olabilir

gece ve gündüzün içinde.

ateş ve su kardeş olabilir

savaş ve barışın içinde.

kırmızı şarap yüreğinin atışına

dönüşebilir  güneşin içinde.

doğduğun gün yetişebilir  ruhun

evrenin  sonsuz  akışına

hayatın ve ölümün içinde.

bir avuç aydınlığı

yüreğine düşürmeye  gör,

gör kralları bol gübreli toprak

şairleri gökte birer yıldız içinde.', 'cennet ve cehennem komşu olabilir gece ve gündüzün içinde. ateş ve su kardeş olabilir savaş ve barışın içinde. kırmızı şarap yüreğinin atışı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icinde-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Yar', 'ey-yar-i-brahim-etem-bakir-h4uwf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamalıydık dı

Adına kuruntu denilse de

Kötü bir zaaftır bu

İnanmamalıydın onlara

Buda geçer

Acı mı? 

Mutluluk mu kalır ardında

Buda senin elinde

Eğer istersen...

Buna inanmamalıydın dı.

Hiç unutmayacaktın dı.

''Herkes sevdiğiyle beraberdir.'' hadisini

Onlar çarpıtmasınlar; 

Valla da

Billa da

İnsan, sevdiğiyle baraberdir.

Mavi deryada

Rüyaları yaşamıyoruz

An be an

Gerçekleri yaşıyoruz; 

Kanı yaşıyoruz; 

Anı yaşıyoruz; 

Bir aşkın peşine düşmüş,

Onu arıyoruz

Bu mavi değil

Yaşayan tüm güllerin renginde olmalı en sevgili

Hadi beni boş ver

Ya yaşadığın anlar...

Ya sevdiklerin...

Ya arayış içinde boynu bükük iskeletin

Bir anda yığılı verse...

Ya herşeyi 

Bir anda yitiri versen

O zaman ne olacak? 

Hangi yar...

Hangi sevgili korur adamı? 

En acılı anlarında kime sığındınsa

Kim seni başının çaresine koymadıysa...

Kim hayatını sana bağışladıysa...

Ve

Kim sana bir anne bir baba

Birde gönülden sevenleri

Musallat ettiyse

Odur en sevgili; 

Adur en bağışlayan; 

Odur en seven seni; 

Odur ey yar

Ben değilim...

E.B.', 'Yaşamalıydık dı Adına kuruntu denilse de Kötü bir zaaftır bu İnanmamalıydın onlara Buda geçer Acı mı?  Mutluluk mu kalır ardında Buda senin ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Etem Bakır']::text[], 8.5, '{"poet":"İbrahim Etem Bakır","poet_slug":"i-brahim-etem-bakir","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ey-yar-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşin Gibi', 'esin-gibi-mehmet-zeki-gezici-wtcmq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İş tutarken bir elin

yardımına koşarsa  öteki

kırk yıllık dostun gibi.

Anlamak için bakarken

bir gözün uzaklara

işte şurası

diyebiliyorsa diğer gözün

bin yıllık kardeşin gibi.

Açılıp kapanırken

kalbinin  bir kapakçığı

diğeri benziyorsa

çırpınan bir kuş

sevincinin kanadına

evin içinde  sevgili eşin gibi.', 'İş tutarken bir elin yardımına koşarsa  öteki kırk yıllık dostun gibi. Anlamak için bakarken bir gözün uzaklara işte şurası diyebiliyorsa di...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/esin-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Rengi', 'hayatin-rengi-mehmet-zeki-gezici-hezi2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1.

İnsan

çenesinden  tepesine

bir karıştır kardeşim,

elmas olacaksın cevherinden

cam parçalarını keser gibi

dişlerinde öğüteceksin kelimeleri

dağılacak çemberinden ay ışığı 

sekiz yapacaksın 

güneşin yedi rengini. 

2.

Üstünde kırkıncı paralelin 

güneş doğurmuş beni,

toprağa değmiş göğün etekleri

kızıl bir uykunun sarnıcından

yanık baharlar getirmiş 

karların ateşini dolanmış 

kırları başucumda temmuz

suyun içinde atan yüreğime

düşürmüş tohumlarını 

ustalar ustası kayalar 

içinde yontulacak rüzgarla

yol aldım 

tek başıma bütün zamanları

dağ aslanları doğururken

özgürlüğümün  mercan dişlerini.

3.

Gittiği yerde güneşin

toprak ve çelik koksun 

felsefenin 

dokuz düğümlü filizleri

gecelerin köpüklerden çizdiği 

deniz yoludur Oğlak Dönencesi

Ekvator 

dünyanın ateşten ince bel kemeri.

4,

Evrim teorisiyle 

yaratırken yeryüzünü Tanrı 

yalnız geometri kullanmış

 Eflatun’a göre

yirmi dört Yahudi bir de Muhammet 

inancın kökleri ölümün içinde cehennem ve cennet 

peygamberlerin gönlüne yazıldı.

Şimdi Ortadoğu 

salkım saçak külhani..', '1. İnsan çenesinden  tepesine bir karıştır kardeşim, elmas olacaksın cevherinden cam parçalarını keser gibi dişlerinde öğüteceksin kelimeler...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/hayatin-rengi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Ömrü', 'i-nsan-omru-banu-savas-1aw82', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'insan ömrü ters akan bir nehir

arada bir pişman olması da gerekir

kaldırıp başını

çiçeklerini sulamaktan

kaldırıp başını çocukları okşamaktan

bir anı düşünüp gizlice

içinde yanan ateşe

küsmesi de gerekir

insan ömrüdür

avuçlarında ter

kaldırıp başını ömrünün sonbaharında

kaldırıp başını ardındaki ormanlara

hiç dokunamadığı ağaçlara

ağlaması da gerekir

insanın tek çiçeğidir belki

sulak verimli bir vadi

ve insan ömrü yine de

kenarda köşede unutulmuş

çakıl taşları

sesleri, kokuları, tatları

insan ömrü kapsar tüm bunları

bir de içinin kuytusunda

sevemediği kuşları

bir türlü elinin ulaşmadığı meyveleri

bir de severek açmaya ikna edemediği 

çiçeği

okşar ve saklar bütün bunları

insan ömrü kendi içine akan bir nehir

arada bir elindekine şükretmesi de gerekir…', 'insan ömrü ters akan bir nehir arada bir pişman olması da gerekir kaldırıp başını çiçeklerini sulamaktan kaldırıp başını çocukları okşamakta...', ARRAY['Türk Edebiyatı','Şiir','Banu Savaş']::text[], 8.5, '{"poet":"Banu Savaş","poet_slug":"banu-savas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/insan-omru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Edirne', 'edirne-mehmet-zeki-gezici-xe7gt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1

Kıssası Enbiya’da

950 yıl  yaşadı Adem

Edirneyi görmeden öldü

yaşayan Adem’se hala kahveci.

2

Ne Birinci Osman gördü

Karaağac’ı güller içinde Ayşekadını

Balkan karlarının 

getirdiği serinlikleri nehirlerde 

söğüt diplerinde gölgeleri

otlar bir ormandı

Rumeli’nde tepeler uzun soluklu 

çocuklar parmak kadar az ömürlü

ıhlamur kabukları düğüm 

edilmemişti gürgen dallarına

yol yoktu sallar inmemişti Karabiga’dan.

3

ikincisi cocuktu gençti zaten

Lehistan’a varana kadar sakalım çıkar

sultanlığım da büyür derdi

at sırtında ancak Yedikule’ye vardı

derken ilmik boynunda asılı kaldı.

4

Birinci Selim doğuya bakardı 

kılıç oluğundan alevi kanı içmek için

çocuktum  ilk gördüğüm filmdi sinemada

kızıl bir nehir gibi akıyordu boyun  yarasından

şerbet niyetine içtigi  kızılbaş kanları

ikincisi Sinan Ustanın işvereniydi

aşkları teninde alevlendi

Nurbanu hamamda bir ölüm tası.

5

Zaman kendini eskitir de geçerdi

değdiği taş oyuklarından güvercin kanatlarında

revnaklarında yıkanan su sesleri 

döşeli mermer kalıplarını uyandıran

sekiz payeye dayanmış 

kubbenin içinde sonsuz zaman 

Şehzade Mustafa’nın başıydı omuzlarında 

yükselen İznik kayalıkları

         mercan çinilerinde

                                erimiş

akan karanfillerdi 

         dönerek geçen 

                ışığın altından.', '1 Kıssası Enbiya’da 950 yıl  yaşadı Adem Edirneyi görmeden öldü yaşayan Adem’se hala kahveci. 2 Ne Birinci Osman gördü Karaağac’ı güller içi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/edirne-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Ölüm Kuşudur', 'yalnizlik-olum-kusudur-mehmet-zeki-gezici-pj6en', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1

Yontulmuş 

kireç taşları gibi  soluyan kartalların

kanatlarından indirdiği  yeryüzüne 

yalnızlık,

darağacının kirlenmiş yüzüdür

dalga dalga denizleri 

tutsan köpüklerinden 

kayalıklardan ellern kirlenir

gecenin bir kıyısında coğrafya uyanık

atlas yırtılır 

suların akıp gider Mezopotamya’dan.

Çocukluk ateşinin kirinden kalan

yalnızlık ölüm kuşudur.

2

Borsada çürümüş gemilerin

uğradıkları limanların yeni adresleri

dilimli portakal ve hardali suyu

sabah kahvaltısı ve banka hesapları

tahvillerin kaç paralık ekranda

toprakların tuzunu delirten kim, 

kim doların kıyılarını ölçüp biçen 

sen yine de ırmakların

suyuna batıracaksın parmaklarını

uçsuz bucaksız

bir ormanın kıyısında kalsan bile

yapraklarından  ince yeşil

bir yol bulacaksın

özgürlüğü akıtmak için kendine.

Yalnızlık ölüm kuşudur.

3.

Martılar konar  kentin ıslak yüzüne

sesine  inen çifte kumrular uyanır 

süryani boylarında seni soran yalnızlık

yeraltı suları saçlarından yürüyecek

otların içinde adamotu

incelikten allanmış gelincik yaprağına 

terini döken şahmerdan kuyusu        dilinde acıya çalan debremin rengi

yüzünün bir yanı aynalara bakan yalnızlık 

yalnızlık

kollarında eriyen sonsuz ölüm korkusu.

Yalnızlık ölüm kuşudur.

4

Yel yavrusu dağıtırken

dört ucundan yasemin kokusunu

içinde ben vardım dağların ve nehirlerin

ay büyüten gül kökünde dallarından

acının  kirli yüzünde büyüdü dişlerim

uykularım bulanık resimli siyah beyaz

korkulu pazar günlerim bulutsuz

iliğine giden bir yol vardı

çöz kendi denklemini

suyun içinde beklerken yalnızlık.

Yalnızlık ölüm kuşudur.

5

Yüreğinin içinde bekler seni yalnızlık

aslan yelesine çarpan rüzgarın 

gürültüsüne  kapatmış kendini

çürümüş  yüreğine benzer yalnızlık

Yalnızlık ölüm kuşudur.', '1 Yontulmuş  kireç taşları gibi  soluyan kartalların kanatlarından indirdiği  yeryüzüne  yalnızlık, darağacının kirlenmiş yüzüdür dalga dalg...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/yalnizlik-olum-kusudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmet Gümüşdere', 'i-smet-gumusdere-mehmet-zeki-gezici-homie', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşayan ruhunu getirdim sana

çürüyen bedeninden kopmuş parçalarını

hastane odasında çarşaflara dökülmüş

gözlerinde donmuş yaşama sevincini

yarım kalan hayallerini getirdim sana.

Sonsuzluğun kıyısında uyudun 

masmavi gözlerinde gökyüzü

bulutların şaşkın rüzgarını yitirmişler

resim karesinden nereye gidilir? 

koca bebeklerin yollarını

yeni doğmuş çocukların uykularını

 yaşayan ruhunu getirdim sana.

Yağmurların indiği bahçelerde

bütün ölüler kardeştir salkım saçak

sevincin  suyunu paylaşanlar

kitapçı dükkanımın camında

bütün gün öpüşüyor güvercinlerin

bakım isteyen sevginin ilk dersinden

serpilmiş kanat uçlarından dağılan

yemyeşil mapushane kapısından

merhaba özgürlük diyen kuşların

selamın ak gerdanlığını getirdim sana.

Orta okuldan ayrılmış

büyük adamlar apartmanı

ilk katında ağacın kökleri gövdesi 

koskoca Yaşar Kemal Homeros’la arkadaş

geçen yıldan hüzünlü 

bahçende otların rengi Menekşenin

deniz kokusu yaprakları sonbahara dönen 

Adile’nin güzel selamını getirdim sana.

Merhaba İsmet Gümüşdere

güzel insanlar merhaba.', 'Yaşayan ruhunu getirdim sana çürüyen bedeninden kopmuş parçalarını hastane odasında çarşaflara dökülmüş gözlerinde donmuş yaşama sevincini y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ismet-gumusdere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sam Amcanın Körfez Maceraları...', 'sam-amcanin-korfez-maceralari-omer-golge-1937n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sakın ölümlerle korkutma bizi

Kaybedecek şeyleri olan içindir,

Ölüm korkusu....

Esaret hayatın bedeli dersen

Baldan tatlı gelir ölüm,

Bize doğrusu......

Kızıl gecelerin yangın koynunda

Cehennemler üzerine kurup sıratı

Azraille çatışarak geçmişiz..

İhanetin riyakar bakışını

Zifir karanlıkların ortasında seçmişiz

Hesabı yanlış yapıp sonra dövünme..

Biz onuru,hürriyeti,toprağımızı,

Bacıdan,anadan,yardan,oğuldan

Evvel bilip deli gibi sevmişiz.

Kendi kaderimiz bu çoğrafyada

Ezilen halklarla aynı demişiz..

Efelik hoş olur okyanus ötesinden

Senin işbirlikçi  bütün uşaklarını

Gönül defterinden çoktan silmişiz

Geçmişe bakmakta bazen fayda var

Körfeze gelmiştin çok yıllar önce

Gökten ölüm yağdıran uçak gemilerinle

Cehennem yürekli bir avuç yiğit..

Üç beş plastik bot oldu masrafın bize

Kaçar gibi dönmüştün o yıl körfezden

Bakarak kaide-i nezaketine

Bunca sözden sonra şimdi Sam Amca,

Hararetle yollarını gözleriz

Ölümü bayılmak zannetme sakın! 

Dostumuzda bilir,düşmanımız da

Biz.. kavganın en zorunu severiz..

Ardına sığındığın haçlı bayrağı

O çirkin yüzünü saklıyor sanma

Bu ders Murteza''dan yadigar bize

Sorulmaz mazluma dini, kavga anında

Bu şiir 1979 devriminden sonraki süreçte A.B.D. ve onun bölgedeki işbirlikçilerine yiğitçe karşı duran İran İslam cumhuriyetinin yürekli insanlarına ve bölgedeki tüm direnişçilere ithaf olunur', 'Sakın ölümlerle korkutma bizi Kaybedecek şeyleri olan içindir, Ölüm korkusu.... Esaret hayatın bedeli dersen Baldan tatlı gelir ölüm, Bize d...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sam-amcanin-korfez-maceralari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim', 'kim-mehmet-zeki-gezici-0zawo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bin dokuz yüz kırkla elli arası

yarın İstanbul’a geliyorum deyince

boğazın iki yakasında

yirmi dört saat öncesinden

iki bin ceket düğmesi ilikleten

kimler başbakan olmuş

dilinizin ucunda kimler kaldı

geliyor zatı muhterem.

gelsin bakalım.

yataklı vagondan 

Haydarpaşa Garına inmeden 

yanaklarını öpecek deniz kokusu.

öpsün  bakalım..

Rivayet bu  ya 

Beyazıt’tan Kumkapı’ya inen

dar sokakların birinde

akşam hava kararmadan

evine erken gitmek zorunda

garip Orhan Veli

yanlış tahtaya basarsam

başıma çöker virane diye diye..

desin bakalım,

elli yıl geçmiş aradan

kim denizde güzelim balık kokusu

yalılarda insan ölüsü olan kim?', 'Bin dokuz yüz kırkla elli arası yarın İstanbul’a geliyorum deyince boğazın iki yakasında yirmi dört saat öncesinden iki bin ceket düğmesi il...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kim-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeynep', 'zeynep-mehmet-zeki-gezici-lqexl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nereye güzel Zeynep Beşiktaş’tan

- Büyük oğlun Şafak’la eş olmaya

kız Zeynep nereye Ankara’dan

- Küçük oğlun Güneş’le arkadaş olmaya

Nereye Zeynep hanım? 

- Olsaydı,ah bir oğlun daha 

   ben de  gelin olsaydım! 

Küçük Zeynep neden 

bu kadar aydınlık ve güzelsin

- Dedem İsmet Gümüşdere’yi

  çok sevdim 

  uyusam kalbimin içinde dolaşır

  beni yanaklarımdan öper gülsem,

  sevgiyle bakan insanlarda onu görürüm.', 'Nereye güzel Zeynep Beşiktaş’tan - Büyük oğlun Şafak’la eş olmaya kız Zeynep nereye Ankara’dan - Küçük oğlun Güneş’le arkadaş olmaya Nereye ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zeynep-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aş', 'as-i-brahim-etem-bakir-gvpjo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimse yok mu? 

İşçi sofrası...

Yoklar.

Yetim aşını sordum; 

Dağıtmıyorlar.

Bebek maması mı? 

Mahrum ettiler.

Hayır

Kimse yok.

Aradıklarımız yok.

Yoklar,

İşçi tadında

Sıcak sofrada yoklar; 

Şimdi atalarımızın izini kaybetmiş

Yetim aşını çöpe döken

Kavimler iz sürmekte.

Şimdi bebekler toz içeceklere mahküm.

Annelerini kırmamak için içecekler; 

Anneleri öz sütten mahrum etse de

İçecekler! 

Kırmamak için...

Üzülmesinler diye...

Kızmasınlar...

Bağırmasınlar diye içecekler.

Kimse yokmu? 

''Hayır

Kimse yok; 

Aradıklarımız yok; 

Yoklar var.

E.B...', 'Kimse yok mu?  İşçi sofrası... Yoklar. Yetim aşını sordum;  Dağıtmıyorlar. Bebek maması mı?  Mahrum ettiler. Hayır Kimse yok. Aradıklarımız ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Etem Bakır']::text[], 8.5, '{"poet":"İbrahim Etem Bakır","poet_slug":"i-brahim-etem-bakir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/as-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-ahmet-uslu-astla-jb5r7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni düşündüm yine bu akşam

ama sadece ve sadece seni...

sensizlik aklımın ucundan bile geçmedi

belkide geçtide ben hatırlamıyorumdur

belkide hatırlımak istemiyorumdur

bilemiyorum...

seni düşündüm yine bu akşam

aklıma bişey takıldı birden:

acaba sen benim için ne idin! 

yani neydi seni düşündüren bana? 

bilemiyorum...

bulamadım ve:

bilmedikçe iyic aklıma takıldı ve:

yeni baştan başladım düşünmeye.

birden aklıma ben geldim! 

acaba ben ne idim ki de:

bu kadar çok sevebiliyordum seni

bilemiyorum...

seni düşündüm bu akşam birde:

birde kendimi düşündüm bi ara

sen olmasan dedim...

düşünmek bile istemedem sensizliği.

sonunda buldum bişeyler ama:

ama iiçinde sensizlikte vardı.

sen bir idin ben ise iki...

ikiden bir çıkıncada:

YALNIZLIK KALIYORDU.', 'seni düşündüm yine bu akşam ama sadece ve sadece seni... sensizlik aklımın ucundan bile geçmedi belkide geçtide ben hatırlamıyorumdur belkid...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uslu Astla']::text[], 8.5, '{"poet":"Ahmet Uslu Astla","poet_slug":"ahmet-uslu-astla","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-ve-ben-172-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana Agit', 'ana-agit-ibrahim-ozdemir-xh9s7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ANA''YA AGIT

       Ben agladıgımda gözlerim yanardı,

       Nazlanınca gönlüm hep sana dertlendi,

       Sensiz tesellisi yok ne neşenin ne baharın,

       Ben annemi kendimden bile çok severdim,

       Oüzülmesin diye zehir bile içerim,

       Hep şevkar dolu sözleri ondan gördüm,

       Sevgi dolu ışıgı hep ondan buldum,

       Yüzü en asil bir yüzdü,

       Gözü en manalı en şevkati derin gözdü,

       Özü sözü en  degerli pırlanta hürmetinde sözdü,

       O her gülüşüyle sankı ilahi çaglayan,

       O her insana anne kıymetinde gönül baglanandı,

       O ilk kundagım,

       ilk oyuncagım,

       Tatlı dilde damagım,

       Kolum kanadım,

       Dilim dudagımdı,

       Ecelin kanlı yüzü  sırtıma vurdugunda,

       Sisli hatıralar titredi gözyaşımda,

       Gözleri ufuklara daldıgında,

       Annemin bir serçe gibi,

       Can vermesini isterdim kollarımda

       Şimdi o ta çok uzakta,

       Seslenişimi artık almamakta,

       Gök kubbenin ucundaki kabir yatakta,

       Kaderin acı saati çaldı,

       Bir anda mutsuzlandı gönlüm harebe oldu,

       Bizim evde koptu  tufan,

       Anne cennetimi özledin,

       Yaslandı bütün ev aglıyor,

       Evin duvarlarında dinamitler patlatılıyor,

       Gittin diye kalbim daglanıyor,

       Gözümden akan yaşlar durmuyor,

       Katraklaşmış gözlerimden kanlar boşalıyor,

       Dünyadanmı bıktın gittin anne,

       Kaç günler oldu öksüz kalalı,

       Sıcak bagrında kalmış gibi elim,

       İçimde belirmiyor sensiz hiç bir şafak,

       Annesi olanlara gün hala doguyor tabak tabak..

       Senin yoklugunda insanı çekiyor,

       Nedeni belli olmayan bir agrı

       Rotası belirsiz,sahipsiz bir gemi gibi,

       Gözlerim ufuklara dalıp,

       Heykelini diktim bahşettiğin yüce gönlüme,

       Dinmeyen gözyaşımı artık dindirdin,

       Nefesini tutupta can evime bıraktın,

       En büyük kötülüğü yapıp,

       Alın yazını bana bahşettin,

       Son nefesinle beni ta gurbetin içine ittin,

       Kanadımı kırıp artık topragamı deydin,

       Ta  can evimin içlerine dokundu silinmez acın,

       Şimdi artık ne varım ne yokum,

       Ana ana diyerek  gece gündüz aglarım,

       Canımın içinde hep acını tabiata söylerim,

       Haykırırım öksüzlüğümde çekecegim çileyi,

       Görün göz yaşlarımla mendilime öbek öbek yaptıgım oyayı,

       Aglayan gözlerimden yattıgın yere bile varacak seli,

       Hep ısıtacak solugun yine solugumu,

       Ah mezarının başında çiçek olsam,

       Sonbahar yaprakları gibi solsam,

       Sen bu dünyada kalsaydında ben orda olsam,

       Gecenin en derin vakti bölebilsen uykunu,

       Hem saçını okşasaydın oglunun,

       Hem görsen şu anki durumunu,

       O zaman kahrından çıldırıp aglamazdım anam,

       Senin acını ta içime attım,

       Sanki dünyanın en acı zehrini tattım,

       Agrılarım var gönül sazımın ince tellerinde,

       Izdıraplar esiyor dört mevsimin her yelinde,

       Acı mesken tutmuş can bahçemin kuytu yerinde,

       Kulaklarımın duydugu her seste,

       Cigerimin soludugu her nefeste,

       Artık ol cennetin kıymet bagının solmayan gülü,

       Bende yoklugunda hep çaglar gözümün seli,

       Durmadan aglarım seni özlerim,

       Sensizlikte her yuttugum lokmayı bogazıma dizerim,

       Yoklugunda bölünüyor çile çile,

       Döndüm yangından kalan küle,

       Boguluyorum sensizlikte çıglıgım,

       Günden güne artık bozuluyor oldu saglıgım,

       Yoklugunda ben kötürüm hayatım bir kördüğüm,

       Çünkü sen bedenimde iki koldun,

       Zaman yelkovanında gidip gelgigim yoldun,

       Güllerin açtıgı tomurcukta,

       arının yaptıgı baldın,

       bedenimde can,

       damarımda kan,

       Sıgındıgım tek zırhlı handın,

       Lambaların gece vardıgı akdın,

       Kollarım boynuma sarılıyken,

       Gökte uçtugum kanattın,

       Yıkıldı gelecegimin umut kaleleri,

       Yalancı dünyanın sensiz bitmiyor çilesi,

       Sensizlikte hep karalara baglanıyorum,

       Göz yaşımı sel yapıp durmadan darlanıyorum,

       Ah bir gelsen dizlerine çöksem,

       Nehir olup gönlüne aksam,

       Güneş olup üstüne dogsam,

       Bir buket çiçek olup elini tutsam,

       Sensizlikte ıslanan gözlerimi güldürsen,

       Ellerini öpüp doya doya koksam,

       En gizli sırlarımı sana emanet etsem,

       Ellerine kır çiçekleri verip,

       Bir tas su içirsem,

       Yoklugunda kahroluyorum,

       Cani gönülden sevip ugruna ölmeyi yeglesem,

       Sensiz ellerimi buz tuttu,

       Yaktı zalim kader düştüm dara,

       Mecalim bitti o gün seninle  girmişim ben mezara,

       Yüregimde hep göz yaşı,

       Kederli gözlerim  hep nemli,

       Mutsuzlugum mühebbetli zindanlar diyarı,

       Canevimde yangınlar durmadan artıyor,

       Bu can ipek döşekli yatarken bile,

       Sanki dikenli çulda yatıyor,

       Sensizlik hanceri hep kalbime batıyor,

       Fırtınalar gibi gürleyip essen,

       Koksam mis gibi gül nefesini,

       Boşluga uzatsam kucaklasam ellerini,

       Ölüme git desen pusuda beklerim uçurumu,

       Tutsam şu aramızdaki karanlıgı tutsamda yırtsam,

       Tutsak yüzünü bagrıma bassam,

       İçlerim paylaşamadıgım dertlerle doldu,

       Sensizlikte şaşırdım dogru yolu,

       Koskoca dünyada kalmışım boynu bükük,

       Diktigin gülün artık kanatları dökük,

       Yıllar önce yaktıgın mumun artık feri sönük,

       Küçücük dertlerim artık oldu bende dag gibi büyük,

       Seni özlemimden çigerim sönük,

       Hasret meşalen bende sönmeyecek,

       Ayrılık karanlıgı erken çöktü dünyama,

       Dermansız dert buymuş ayrılıkta,

       Ölümayırdı bizi biricik anamızdan,

       Sensizlikte içim içimi yiyor maf oluyorum,

       Yanlışlarım oldumu diye kendimi hırpalıyorum,

       İyi evlat olamadımmı diye dövünüyorum,

       Agaç ve dalları gibi ayrılmaz parçalardık hani,

       Erken yaşta bizi terketmek bu adaletmi yani,

       Elbet bu dünyada kimse asla kalmaz baki,

       Sana doyamadım dertlerime paylaşamadım nur yüzlü anne,

       Evlat ecel dinlemez,

       Çocuklugum hep gözümde tütüyor senli var olan akşamları,

       Hele hele kucagına alıp,

       Evladım deyip,

       Yüzümü öpüp,

       Saçımı oksayışın,

       Doya doya koklamaların,

       Sensiz yıllar bana haram,

       Kaç günler özlemişligin gözlerimde katran,

       Yolunu beklemişligimdeki yükselen duvarları durduramam,

       Rüzgarlara haber sordum hala cevap alamam,

       Kanat tak gel melek anne,

       Ölüyorum hasretinden,

       Yoklugun kabusların en beteri,

       Yıllar boyu yoksun kalacagız şevkatinden,

       Rüya dolu gecelerime gelde öpeyim ellerinden,

       Özlem dolu dualarım olsun en derinden,

                                                      İBRAHİM ÖZDEMİR', 'ANA''YA AGIT        Ben agladıgımda gözlerim yanardı,        Nazlanınca gönlüm hep sana dertlendi,        Sensiz tesellisi yok ne neşenin ne ...', ARRAY['Türk Edebiyatı','Şiir','Ibrahim Özdemir']::text[], 8.5, '{"poet":"Ibrahim Özdemir","poet_slug":"ibrahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":159,"source_url":"https://www.antoloji.com/ana-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyden Geldim Sehre', 'koyden-geldim-sehre-ibrahim-ozdemir-nh7p8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KÖYDEN GELDİM  ŞEHRE

      Köyden geldim büyük şehrin kenar mahallesine,

      Bin bir umutla yerleştim mahallenin tek hanesine,

      Muhtaç olacagımı bilmezdim  ufacık kar tanesine,

      Köyde bilmezdim burda abone oldum hastanesine,

      Yurdun dört bir yanından gelmiş bu insanlar,

      Her biri ayrı ayrı lisanları konuşurlar,

      Kimi yaşar köy hayatı,kimi sosyete hayatı yaşarlar,

      Köyde bilmezdim eve kapanmak,burda dışarı çıkmamak,

   

      Şehrin taşı topragı altınmış inanmıyorum,

      Kendimi tanımayı bırak çocukları bile tanıyamıyorum,

      Köyde kızdıgıma burda bilakis hiç aldırmıyorum,

      Köydeki yaşamı burda bulamayıp çocukları hırpalıyorum.

      İnsanlar birbirinin kuyusunu kazmak en büyük moda,

      Yediklerin hepsi düşman midene iç devamlı soda,

      Burda yaptıgın her iyilik başkasına göre hata,

      Köyde bilmezdim ne güneşin ne ayın hasretine,



      Sabahın alaca karanlıgında giderim işe,

      Emekcilikten dönerim dönüşümde yine gece,

      Hasretim dogusu ve batısı başka başka güneşe,

      Köyde bilmezdim ne güneşin ne ayın hasretine,



      Şehirden köye gittim gezmeye 

      Gördüler beni özendiler içi masum şehirliye,

      Namelerimle içerleyerek şehri acı şerbetlemeye,

      Köylü bilsin şehri devam etsin tatlı yaşamaya,

                                                   İBRAHİM ÖZDEMİR', 'KÖYDEN GELDİM  ŞEHRE       Köyden geldim büyük şehrin kenar mahallesine,       Bin bir umutla yerleştim mahallenin tek hanesine,       Muhta...', ARRAY['Türk Edebiyatı','Şiir','Ibrahim Özdemir']::text[], 8.5, '{"poet":"Ibrahim Özdemir","poet_slug":"ibrahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/koyden-geldim-sehre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vah Vah Memleketim', 'vah-vah-memleketim-ibrahim-ozdemir-jpfl5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'VAH VAH MEMLEKETİM

      Ne olacak memleketin  hali,

      Yol bitmiş,kalmış tek yol,oda tali,

      İnsanlar kurumuş ekmege kalmış onuda almayın bari,

      Vah vah olmuş benim memleketim.

      Dün küçücüktü benim  maaşım,

      Oda gitti ne olacagım bundan sonra ben berdoşum,

      Düştümya tabutumu bile taşıyan kalmazki sırdaşım,

      Bir bir vah vah oluyor benim memleketim.

      Bugün bendim,yarın niceleri oluyor aç yolcu,

      Tavernada kırılan bir tabaga ben muhtaçlıgıma,ben suçlu,

      Çalçırpıcılar yüzlercesini kırmış onlarmı haklı,

      İşte bu durumda vah vah benim memleketim

      Sicimleşen yagmur altında peçete satmaya çalışan çocuk,

      O okula gitmesi gerekiyor,yaşıtları arasında olmadan geçik,

      İçimizde ölmeyecegini sanan ben benciler olduktan sonra kaçık,

      Fırsatcılar diyarı olmuş vah vah olmuş benim memleketim.

      Dün neredeydik bugün nerdeyiz bilen yok,

      Vurguncular cırıt atıyor defterini tutan yok,

      Bu zihniyetler temizlenmezse dahada geriye gideriz çok,

      Daha geç olmadan bir şeyler  yapalım,vah vah olmuş memleketim,

      Bak sokaklara  düşmüş be bu insanlar,

      Bir dokunsan  herbiri düşecek tutmuyor ne bacaklar ne kollar,

      Onlara da kalmayacak  şaibelerle dolu dışa giden yatırımlar,

      Kulak tıkaya,tıkaya vah vah olmuş benim memleketim,

      Bakın bakın ne yapıyor bu adam şuan,

      Sokakta buldugu çöpleri eve götürüyor yine yok utanan,

      Dedelerinin kanıyla sulanmış ülkesi,sıla olmuş vatan,

      Hemen şu an bir şeyler yapalım,vah vah olmuş memleketim,

    

       VAH VAH MEMLEKETİM

      Ne olacak memleketin  hali,

      Yol bitmiş,kalmış tek yol,oda tali,

