INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benimsin', 'sen-benimsin-murat-gulener-4figs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmurun ıslattığı kadar ıslaksın

Güneşin ısıttığı kadar sıcak

Seni sevdiğim kadar güzelsin

Gözlerden gönlümden ırak

Elimden çekip aldılar seni

Çekilmez acılara saldılar beni

Düşündükçe içim ağladı seni

Özledim canım ne olur dön geri

Sen olmazsan olmaz derim

Buralardan çeker giderim

Seni bana vermezlerse

Kara toprak olur yerim', 'Yağmurun ıslattığı kadar ıslaksın Güneşin ısıttığı kadar sıcak Seni sevdiğim kadar güzelsin Gözlerden gönlümden ırak Elimden çekip aldılar s...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-benimsin-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmaz', 'unutulmaz-murat-gulener-2dt8q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir özlem var içimde uçsuz bucaksız

Bir sevgi var içimde dalsız budaksız

Bir duygu var içimde lekesiz tertemiz

Tek sen varsın içimde unutulması imkansız

Bir anısın okuyup bitiremediğim

Bir özlemsin yalvarıp hükmedemediğim

Bir tek sensin elveda diyemediğim

Tek bildiğim seni çok özlediğim', 'Bir özlem var içimde uçsuz bucaksız Bir sevgi var içimde dalsız budaksız Bir duygu var içimde lekesiz tertemiz Tek sen varsın içimde unutulm...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unutulmaz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne çok sevmişim', 'ne-cok-sevmisim-temel-kilincarslan-4gxpu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uyuşmuş her yerim,yüzüm, ellerim

Bu fani dunyayı sensiz neylerim 

Artık şarkımızı sensiz söylerim

Meğer ben o yari ne çok sevmişim

Tek tanem demiştim, gerçekten tektin

Sen beni gönlüne, ömrüne çektin 

Madem çok sevmiştin neden terkettin,

Meğer ben o yari ne çok sevmişim

Allah''ım yardım et nasıl olacak

Baharım gelmeden yolda solacak

O hep gönlümdeydi orda kalacak

Meğer ben o yari ne çok sevmişim

Hadi git, ardından böyle kalırım,

Çileden nasibim varmış,alırım

Hatıralarınla oyalanırım

Meğer ben o yari ne çok sevmişim', 'Uyuşmuş her yerim,yüzüm, ellerim Bu fani dunyayı sensiz neylerim  Artık şarkımızı sensiz söylerim Meğer ben o yari ne çok sevmişim Tek tanem...', ARRAY['Türk Edebiyatı','Şiir','Temel Kılınçarslan']::text[], 8.5, '{"poet":"Temel Kılınçarslan","poet_slug":"temel-kilincarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-cok-sevmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-murat-gulener-p4qh8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arıyorum bakışların kadar sıcak ellerini

Arıyorum o en masum gülüşlerini

Özlüyorum gölgem bile sensizlikten şikayetçi

Bu yalnız sokaklarda oldum refakatçi

Giderim ben umutsuzca yelkensiz gemi misali

Hasretin vurur beni vefasız hançer misali

Sanma ki korkarım ölümden, ayrılıktan

Sensizlik; ölümden gerçek ayrılıktan acı', 'Arıyorum bakışların kadar sıcak ellerini Arıyorum o en masum gülüşlerini Özlüyorum gölgem bile sensizlikten şikayetçi Bu yalnız sokaklarda o...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensizlik-242-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Gözlerin', 'guzel-gozlerin-murat-gulener-xqxn5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşıkların yüreğinde ateş kor olur

Senin baktığın gözler kör olur

Senden ayrılmak ölümden zor olur

Seni seven çok sevilen tek olur

Denizler durulmaz dalgalanmadan

Umutlar yeşermez sevgi olmadan

Yalnızlıklar yol almaz beraber olmadan

Mutluluk yaşanmaz inan sen olmadan

Yapraklar sararıp düşerken yere

O güzel gözlerini çevir göklere

Her gün değil yılda  bir kere

Beni ne kadar sevdiğini söyle

Pembe karanfilleri yine öyle takınsan

Ararken gözlerini umursamaz bakınsan

Bir küçük gülüşü cimri gibi sakınsan

Bir de seni ne çok özlediğimi anlasan', 'Aşıkların yüreğinde ateş kor olur Senin baktığın gözler kör olur Senden ayrılmak ölümden zor olur Seni seven çok sevilen tek olur Denizler d...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzel-gozlerin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Yüreğimle Yarışmak', 'kendi-yuregimle-yarismak-melih-coskun-olfrg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzerken uçsuz bucaksız imgeler denizinde 

Kollarıma değer milyonlarca balık 

Yosun kokar avuçlarımdaki çizgiler 

Sensizlik kaçar genzime her hece 

Nefessiz kalırım 

Uzun bir sessizlik olurum

Kendi yüreğimle yarışırım her gece

Her hece çıldırtırım açık denizlerde yakamozları

Kokun karışır soluğuma 

Gözlerim dolar hiç yoktan 

Ağlarım...

2004', 'Yüzerken uçsuz bucaksız imgeler denizinde  Kollarıma değer milyonlarca balık  Yosun kokar avuçlarımdaki çizgiler  Sensizlik kaçar genzime he...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kendi-yuregimle-yarismak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemek', 'ozlemek-murat-gulener-efjwo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Denizlerde yakamoz senin gülen gözlerin

Mehtap, deniz, dalgalar bir de şirin sözlerin

Hasretinden fırtınalar kopsa da gönlümde

Bir seni arar seni özler gözlerim

Kimine göre ateştim cayır cayır yanan

Kimine göre yıldız hep parlayan

Kimi çiçeğe benzetirdi hiç solmayan

Ben ise su olmak isterdim senin için

Her zaman her yerde muhtaç olunan

Sevgimi taşımak değil hasretini çekmek zor

Gülmeye değil ağlamaya alışmak zor

Yaşamak değil ölmek te değil

Özleyip te görememek zor', 'Denizlerde yakamoz senin gülen gözlerin Mehtap, deniz, dalgalar bir de şirin sözlerin Hasretinden fırtınalar kopsa da gönlümde Bir seni arar...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozlemek-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlediğim', 'ozledigim-murat-gulener-l24ff', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasretinle sararıp solacak kadar

Sevginle bahtiyar olacak kadar

Uğruna canımı verecek kadar

Kimseyi özlemedim seni özlediğim kadar

O kara gözlerinin bakışını özledim

Yanağında güllerin nakışını özledim

Omzumda usulca yatışını özledim

Seni sevmekten bile çok özledim

Öyle senden çok uzaklarda değilim

Görmesini bilen gözlerin bakışındayım

Belki sana senden daha yakın bir yerde

Çarpan kalbinin her atışındayım

Özlem bir yolculuktur aşkın kendisi gibi

Yol aldıkça geçmişten uzaklaşmak

Keşfedilmemiş yanlarını keşfetmek

Ve kendi içinde yanan bir ateşle

Aşk acısının bir yönünü fark etmek', 'Hasretinle sararıp solacak kadar Sevginle bahtiyar olacak kadar Uğruna canımı verecek kadar Kimseyi özlemedim seni özlediğim kadar O kara gö...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülener']::text[], 8.5, '{"poet":"Murat Gülener","poet_slug":"murat-gulener","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozledigim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ne yaşlanır ne öl..', 'ask-ne-yaslanir-ne-ol-fadime-dizdar-8xxkx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbimin hücresinde,

Gizli bir hazine var.

Güneş bile değmedi,

Dört yanı etten duvar.

Seviyorum diyerek,

Kimseyi aldatmadım,

Ben bu yüce aşkımı,

Allah ma sakladım.

Bu dünyada aşkıma,

Asla mezar kazamam,

Niyetim sonsuza dek,

Orucumu bozamam.

Bir yudum sevda ile,

Paklanır bu bedenim,

Bir avuç toprak yeter,

Aşktır benim kefenim.

Aşk mezarı var ise,

Gösterin de göreyim,

Bedenimi taşına,

Yaslayarak öleyim.', 'Kalbimin hücresinde, Gizli bir hazine var. Güneş bile değmedi, Dört yanı etten duvar. Seviyorum diyerek, Kimseyi aldatmadım, Ben bu yüce aşk...', ARRAY['Türk Edebiyatı','Şiir','Fadime Dizdar']::text[], 8.5, '{"poet":"Fadime Dizdar","poet_slug":"fadime-dizdar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-ne-yaslanir-ne-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni unutacağım', 'seni-unutacagim-i-lhami-arslantas-vrvjp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğime asmıştım düşürdüm gözlerimden

Aramayacak  gözüm  her izimi  sürsen de

Ayak bağı olmuştun çözüldün dizlerimden

Haz almaz artık  özüm  yüzüme yüz sürsen de

……………………….Seni unutacağım her zerreme girsen de

Ömrümü sana verdim meyus olanda bile

Şimdi  can derdindeyim  haydi git güle güle

Hatıram kaldı ise  bebeğim diye bele

Anmayacak bu  sazım sazıma  söz sürsen de

……………………….Seni unutacağım her zerreme girsen de

Sürükleme peşinden benden sana hayır yok

Belki  sana her yer düz, tepe, dağ yok bayır yok

Sana  tılsım edecek Sahıra ya  sahir yok

Sana  dönmeyeceğim gizime   gez sürsen de

……………………….Seni unutacağım her zerreme girsen de

  

  Der İlhami dünyamı yaktın  ayaz  eyledin

Gururumla oynadın kaçtın hep naz eyledin

Nasırlaştı umudum artık ummaz eyledin

Vefasız  yar aramam güzüme  yaz sürsen de

    ……………………….Seni unutacağım her zerreme girsen de', 'Yüreğime asmıştım düşürdüm gözlerimden Aramayacak  gözüm  her izimi  sürsen de Ayak bağı olmuştun çözüldün dizlerimden Haz almaz artık  özüm...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-unutacagim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Talanı', 'sevgi-talani-kamber-bal-qpf90', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ölçtük arşın arşın

geçen yollarını tüm sevginin

gördüm ki mezalim kalmış bizelere pay

tartanlar vardı okka okka tadanlar

bildim ki hasreti örttüler bize şal

ne sen söyle, ne de gizlesin onlar

her şey hakkın huzurunda ayan beyan

bir ölçek ektik aldılar yedisini

paymızdır diye kaptılar gerisini

umut bağladık gelecek sevgiye

biz uyanmadan uçacak sevgiye

ahdı zamanda belliydi bize yar olmayacağı

bizde vücut bulup biz de var olmayacağı

kayırıp kendimizi kapandık içimize

büklüm büklüm olup çıktık dışımıza

nice bilinmez karlar yağdı başımıza

sevgimizi Bal''da bulup oturduk döşüne', 'ölçtük arşın arşın geçen yollarını tüm sevginin gördüm ki mezalim kalmış bizelere pay tartanlar vardı okka okka tadanlar bildim ki hasreti ö...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgi-talani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmeden ölürsem ona yanarım', 'gormeden-olursem-ona-yanarim-mikdat-bal-rib0h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah dedim ah derim ölünceye dek

Bırakıp da gitme gelinceye dek

Beni benliğimle bilinceye dek

Çizip de silersen ona yanarım

Beyinden vuruldum düştüm bayıldım

Ufacık bir krizdi ölü sayıldım

Hastanede gözüm açtım ayıldım

Kızıp da silersen ona yanarım

İlaçtan uyuştum tutmazdı elim

Konuşmaya zaten dönmezdi dilim

Ne sağduyum vardı ne aklı selim

Yazıp da silersen ona yanarım

Dünyamı da yıktım bu halde iken

Gül diye uzattım dallarım diken

Öyle bir hastalık belimi büken

Sezip de silersen ona yanarım

Mikdatî, yolcuyum bu gün ya yarın

Bütün dertlerimle kefenle sarın

Açılan mezarın başına varın

Görmeden ölürsem ona yanarım', 'Ah dedim ah derim ölünceye dek Bırakıp da gitme gelinceye dek Beni benliğimle bilinceye dek Çizip de silersen ona yanarım Beyinden vuruldum ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gormeden-olursem-ona-yanarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıları Yüreğe Gömmek Lazım!', 'acilari-yurege-gommek-lazim-orhan-eren-uncu-j3b29', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne kadar sevsen,

Ne kadar  sevilsen

Bir ağlasan, bir gülsen

Yaşananları düşününce

Acıları yüreğe gömmek lazım

Bir avuç bahçen olacak 

Yağmurlar yağacak

-İşte be gülüm,

-İşte o zaman, 

Tomurcuklar çiçek açacak

Acıları yüreğe gömmek lazım

Her taraf çiçek dolacak

Bir nasihat, bir sevgi

Ne kadarda hazlansan

Çiçeği demet yapan sevgi

Acıları yüreğe gömmek lazım

Demet demet çiçek, açmak lazım

Kış olacak,kar yağacak

Kimine mutluluk,kimine beyaz yorgan olacak

Koyacağız başımızı öne bitap

Dışarda yaşananları hatırlamak  lazım

karanlıkta yalnız

Acıları yüreğe gömmek lazım

Dışarıya da bakmak lazım

Günü sevgiyle kucakla

Sevgiyi, kucak kucak,yaşa

Yüreğinde hep mutluluğu ara

Bir gün hüzne inat,göz damlasından

-Yüreğin de tomurcuklar olacak

Biri sevgiye,bir hüzne çiçek açacak

İşte o zaman

Acıları yüreğe gömmek lazım

Sesin çıkmıyor,anlatamıyorsun

yüreğin tükenmiş, hüzün yapıyor

Atacaksın kendini sokaklara

İşte o zaman

koşmak isteyeceksin, düşünmeden  her şeyi

koca yeşile doğru

betonlara çarpmadan! 

-Çarptın..

-Canın yanacak..

Acıları yüreğe gömmek lazım

Betonların gereksizliğini anlatmak lazım

Ben hep acı, hüzünmü yaparım

Yağmurlar yağmadan

Hep hüzünmü yazarım

Yok! 

Acıları yüreğe gömmek lazım

Bende çiçek olur açarım

Bir şeyler anlatmak için yaşarım

07.02.2006

01:25', 'Ne kadar sevsen, Ne kadar  sevilsen Bir ağlasan, bir gülsen Yaşananları düşününce Acıları yüreğe gömmek lazım Bir avuç bahçen olacak  Yağmur...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/acilari-yurege-gommek-lazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-68 (M.S.) 06/02/2006', 'mektuplar-68-m-s-06-02-2006-mahzun-doga-of2nr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmediğim bir dilde şarkılar içindeyim

soğuk yerler yapışmış ayaklarıma

saçlarım parmaklarıma dolanmış 

kimse duymuyor ne bağırdığımı

anladıklarımı bilen yok

Saatlerdir dışımdayım

içimi gören yok

ki cama döndüm

her yanım izsiz

Ve hepsi senden başka

beni içine götüren yok

ki sana döndüm

her yanım bensiz

Ne yapsak

aklımızı terk mi etsek

ne yapsak

da çıksak bu yersiz yurttan', 'Bilmediğim bir dilde şarkılar içindeyim soğuk yerler yapışmış ayaklarıma saçlarım parmaklarıma dolanmış  kimse duymuyor ne bağırdığımı anlad...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mektuplar-68-m-s-06-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-69 (M.S) 07/02/2006', 'mektuplar-69-m-s-07-02-2006-mahzun-doga-16nb5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bekliyorsun

ellerin çalınmış

gözlerine düşmüş yalnızlığım

saçların ömrümü uzatıyor

aklım kısalıyor

rengimden mavi çalınmış

Yetemiyorum artık sensizliği yetmeye

bir karış havada sabrım

sakinliğin aşkı kanatıyor

Şimdi

uzatsam elimi

tutamıyorsun

yalan görüyoruz

bana ellerin gerek

yalan söylüyoruz

bana ellerin gerek

yalan söylüyorsun

sana gözlerim gerek

yalan söylüyorum

Ve susuyorsun

bağırsan

kim duyar ki zaten

susuyorsun

konuşsan

kim anlar ki zaten

yalan söylüyor gerçek dünya

bana gerçeğin gerek

doğru söylüyor bütün yalanlar

Yanaklarını gönder yatağıma

biraz da tenin olsun

ve gözlerini

kuru olsun

bakışlarını gönder bana

Hadi

yak beni

yapamazsan

yak beni

yerine getiremezsen bunları

yak bizi

kül bitti

mektup bitti', 'Bekliyorsun ellerin çalınmış gözlerine düşmüş yalnızlığım saçların ömrümü uzatıyor aklım kısalıyor rengimden mavi çalınmış Yetemiyorum artık...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/mektuplar-69-m-s-07-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usulca Sığındım Yüreğine', 'usulca-sigindim-yuregine-fethi-aslan-knabb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir geceye bir de hasrete Kurşun işlemez

Kahpedir gecenin karanlıkları Anne

Usulca sığındım yüreğine

Teslim etme,

teslim etme beni geceye Anne.

Batıyor güneş,

çırılçıplak bırakıp geceyi.

Karakollar kurmuşlar yüreğime,

çekiyor perdelerini ölüm gözlerime

Haykırışlarım yankılanıyor çarpıp sessizliğe,

bir umut düşüyor yere,

vurulup sırtından kalleşçe

ellerin,ellerin nerede Anne.

Sen olsan tutardın ellerimden

aldırmadan üstüme yağan ölüme.

Sen olsaydın,

düşmezdim,düşmezdim yere Anne

Şimdi müebbet uykuya

kapanıyor gözlerim,

canım kan olmuş akıyor,

üşüyorum Anne.

Sen olsaydın 

yorgan yapıp bulutları sererdin üstüme.

Sen olsaydın 

üşümezdim,üşümezdim Anne

Ellerin uzanmış ellerime,

gözlerin gözlerim`de.

Çağırıyorsun  beni

korkma gel,ben buradayım diye.

Bu karanlığın içinde buldum ya seni Anne,

artık ölümü bile öperim gözlerinde.', 'Bir geceye bir de hasrete Kurşun işlemez Kahpedir gecenin karanlıkları Anne Usulca sığındım yüreğine Teslim etme, teslim etme beni geceye An...', ARRAY['Türk Edebiyatı','Şiir','Fethi Aslan']::text[], 8.5, '{"poet":"Fethi Aslan","poet_slug":"fethi-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/usulca-sigindim-yuregine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklınıza Şaşayım', 'akliniza-sasayim-mine-yirmili-8p2ry', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kumar; 

Nice ocaklara, kibrit yakmadan, ateşler düşürmedi mi? 

Nice ateşler; 

Kendi sönerken, ocaklarıda söndürmedi mi? 

Sönen ateşlerin; 

Külleri değildi savrulan... 

Yıkılmış ümitlerdi; bir  bir, yok olan! 

Bütün gün, rızkının peşinde koşarken; 

Kendi parana kastın ne ki? 

Giden paranmıydı? 

Yoksa da emeğin mi! 

Ya da, hepsinden değerlisi; 

Yuvanda seni bekleyen, 

Canın,Ciğerin,Gözbebeğin Ailendi... 

Böyle bir müsibete boyun eyenin 

Vallahi aklına şaşayım...

Billahi... ''AKLINIZA ŞAŞAYIM! ''

8 Şubat 2006    sa:02:29', 'Kumar;  Nice ocaklara, kibrit yakmadan, ateşler düşürmedi mi?  Nice ateşler;  Kendi sönerken, ocaklarıda söndürmedi mi?  Sönen ateşlerin;  K...', ARRAY['Türk Edebiyatı','Şiir','Mine Yirmili']::text[], 8.5, '{"poet":"Mine Yirmili","poet_slug":"mine-yirmili","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/akliniza-sasayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Diyordun, Al Bu Aşk!', 'ask-diyordun-al-bu-ask-fevzi-gunenc-niubu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk istiyorsun ha,

al sana, işte aşk

bak, bu yüreğim

yar, bak

içinden ne çıkacak? 

İçin gider görsen

İçinden sen çıkacaksın Sen…

Aşık olmak istiyorsun ha

işte sana aşık olacak bir adam

biraz kurbağaya benzer ama ürkme

mavi atlı prens olur öpersen.

Tut onun elini

yürü onunla yağmurda

mum ışığında yemek ye.

gözleriniz ışıtsın dünyayı

sevinçle parlayan gözlerin

mutlulukla ışıldayan

“seni seviyorum” diyen gözlerin…

Bırak kendini bana

yüreğim kuyu, kuyum derin

orada altın tacın, altın tahtın

orası senin sarayın, orasıdır senin yerin.

Mum ışığında yemek yemek istiyorsun

işte sana mum ışığında bir masa

kırmızı şarap var kadehlerimizde

onura

birlikteliğin onuruna

onuruna aşkın.

Biz şaşkın değiliz artık

Dünya şaşkın.

Arayan buluyor demek ki sevgiliyi

ben bulduğumu sanmanın sevincindeyim

kanatlanan kuşum artık

yüreğim esen

Ya sen? ..', 'Aşk istiyorsun ha, al sana, işte aşk bak, bu yüreğim yar, bak içinden ne çıkacak?  İçin gider görsen İçinden sen çıkacaksın Sen… Aşık olmak ...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ask-diyordun-al-bu-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şairler Olmasa.', 'bu-sairler-olmasa-suheyl-turkoglu-x5dpv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Havva ananın

Dünkü çocuk olduğunu,

Kelepçe zincirlerinin,

Pulluk yapılacağını,

Yanlızlığın paylaşılamayacağını,

Han duvarlarını,

Selamın

Rüşvet sayılamadığını,

Nereden bilirdim,

Bu şairler olmasa?', 'Havva ananın Dünkü çocuk olduğunu, Kelepçe zincirlerinin, Pulluk yapılacağını, Yanlızlığın paylaşılamayacağını, Han duvarlarını, Selamın Rüş...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-sairler-olmasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılsama', 'yanilsama-birsen-ates-kciow', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hani bazen sorgusuz sualsiz

yol alırsın yaşamda

öylesine

düşünür durursun sıcacık bir gülüşe

ruhunu teslim etmeye

örtersin duyguları

günahların yakar kavurur içini

zemheride bile 

cemreler düşmeden ruhuna

bahar gelir sanırsın da

çiçek verir ağaçların

yanılsama

08.02.06

Sunu

oysa henüz ağlamaktaydı zaman zemheride

asılamadan mutluluğa geldi ölüm sessizce.', 'hani bazen sorgusuz sualsiz yol alırsın yaşamda öylesine düşünür durursun sıcacık bir gülüşe ruhunu teslim etmeye örtersin duyguları günahla...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanilsama-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumuzu Teslim Alan Şeytan', 'ruhumuzu-teslim-alan-seytan-i-rfan-kaban-uea3g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç uykuda düşte uyandırıldık

Kaç düşte uykudan uyanmışız sandık

Madem ki bilincimiz etkisizdi,yerinde değildi

Hayat

Uykuda başlar,uykuda sona ererdi.

Ne denli öğünsek azdır

Öyle der insanlık gururumuz

Yapay gereksinimler yığar

Kendi üretkenliğimizin esiri oluruz.

Sabahtan başlar kızarır,

Çınlar kulağımız

Seğirir gözümüz

Hayır olsun

Aman da ne tatlı kaşınır elimiz....

Belli; 

Belli belirsiz bir hedefteyiz biz

Pazarlamacının reklam manevrası

Usta tezgahlar açar

Beynimizde kurulur teknolojinin en son harikası

İt gibi çalışırız da satın almaya

Lakin gelmez önü arkası

Ne dirilik kalır,ne soluk

Ne bir, dur- aman

Koşturmacada başlar ömür

Koşturmacada biter zaman

Kışkırtır durur insanlık gururumuz

Bizim de olsun almalıyız

Hem kimin kızından aşağıyız? 

Kaç uykuda düşte uyandırıldık

Kaç düşte uykudan uyanmışız sandık

Madem ki bilincimiz etkisizdi,yerinde değildi

Hayat

Uykuda başlar,uykuda sona ererdi.', 'Kaç uykuda düşte uyandırıldık Kaç düşte uykudan uyanmışız sandık Madem ki bilincimiz etkisizdi,yerinde değildi Hayat Uykuda başlar,uykuda so...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kaban']::text[], 8.5, '{"poet":"İrfan Kaban","poet_slug":"i-rfan-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ruhumuzu-teslim-alan-seytan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümserim', 'gulumserim-birsen-ates-cca8n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'salınarak gelen gecenin

karanlığın da gördüm ölümü

gülümsedim

üzerimdeydi gözleri 

tuttu parmak uçlarımdan

uyandım

oysa 

sen bana gelmeden

ben sana gelirim

bakar gözlerine 

gülümserim

08.02.06', 'salınarak gelen gecenin karanlığın da gördüm ölümü gülümsedim üzerimdeydi gözleri  tuttu parmak uçlarımdan uyandım oysa  sen bana gelmeden b...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gulumserim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmen Gelmese', 'gitmen-gelmese-muammer-erturan-7xpg6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu denli güzel olabilir

bir sürpriz ancak

tam seni düşünürken

kapım çalınacak

ve karşımda sen...

Teninde nisan kokusu

dudakların temmuz...

Akşamı bulmadan

kafayı bulmuşuz

ne çıkar...

Kim takar işi gücü

borcu harcı

öpüşüp koklaşmak varken...

Bir de bitmese gün

hiç bitmese

gitmen gelmese hiç...

(18 Nisan ''95)', 'Bu denli güzel olabilir bir sürpriz ancak tam seni düşünürken kapım çalınacak ve karşımda sen... Teninde nisan kokusu dudakların temmuz... A...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gitmen-gelmese-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeri', 'yeri-muammer-erturan-8o87n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Işıdı ışıyacak derken

yepyeni bir gün

gömülmüşsün bir anda

kopkoyusuna karanlığın...

Sırtında hançeri imansızın

kalakalmışsın kaldırımlarda

boynu bükük

eller cepte

acayip de yaralı,

oralı bile değil üstelik

yedi tepeli şehir...

Hey gidi! ..

Ne yapsan

ne etsen

nerelere gitsen? ..

Yerin dibine girsen

yeri...

(23 Temmuz ''95)', 'Işıdı ışıyacak derken yepyeni bir gün gömülmüşsün bir anda kopkoyusuna karanlığın... Sırtında hançeri imansızın kalakalmışsın kaldırımlarda ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ürkek Adım İleri', 'urkek-adim-i-leri-muammer-erturan-azva4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ürkek adım ileri! ..

İleri geri şeyleri düşünme şimdi...

Ardından bakan varmış...

Bakarsa baksın...

Sokağın sonunda

kaybolduğun an gözden

en ağır yükünden sırtının

kurtulmuş olacaksın...

Hoyratça çöküşü karanlığın,

toz pembe bulutların

buzula dönüşü ardıl,

yabanıl kışların kuşatmasında

bir yaralı kuş,

bir yanık yürek...

Ufak tefek ayrıntıları işte

geride kalan dekorun...

Sıradışı bir oyunun

bu son sahnesine

nasıl da cuk oturdu ama

alaca efekti akşamın...

Hele ki sen,

sırt çevirmeyi aniden

nasıl da oynarsın; 

yaşayarak ve yaşatarak...

Ürkek adım ileri! ..

Bakalım nasılmış yaşamak...

(29 Ocak ''96)', 'Ürkek adım ileri! .. İleri geri şeyleri düşünme şimdi... Ardından bakan varmış... Bakarsa baksın... Sokağın sonunda kaybolduğun an gözden en...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/urkek-adim-ileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki damla göz yaşı 1.Bölüm', 'i-ki-damla-goz-yasi-1-bolum-ayhan-isin-iha2u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...........................Anadolu’nun şirin bir kasabasının hemen yanında yüce bir dağ vardı. Etekleri yeşil mi yeşil, düzlükleri kır çiçekleri çiğdemler, kekikler iri iri papatyalar, yaban gülleri, çitlembikleri hiç eksik olmazdı. Kekliklerin bağırışları bülbülün güzel ötüşleri ile kelebekler, arılar bal toplardı bin bir çiçekten. Tavşanlar koşuşurdu, yaban keçileri dans ederdi doğayla. Kelebekler âşıktı papatyalara, bülbüller yaban güllerine burada herkes birbirine âşıktı. Rüzgâr taşırdı deniz kokularını dağın yamaçlarına; dağdan aldığı kır kokularını kasabanın sokaklarını yalayarak denize taşırdı. Dağın zirvelerinde kar, buz yaz ayların da bile kalkmazdı. Cılız derelerle dağın suyu hiç tükenmezdi. Bazen yerin derinliklerine iner kilometrelerce öteden kasabanın hemen yanından fışkırırdı. Kasabanın çocukları her gün bu kaynağın yanına gelir, burada oyunlar oynarlar yorulunca buz gibi kaynaktan su içerlerdi. Kemal’le Arzu çok iyi arkadaşlardı. Beraber kasabanın tek okuluna gidiyorlar, aynı sınıfı aynı sırayı paylaşıyorlardı. Zaten evleri de yan yanaydı. Aileleri de yıllardır atadan dededen beri beraber birçok sıkıntıyı sevinci paylaşmışlardı.

...........................Kemal oyundan yorulunca pınarın başına oturur sürekli zirvede ki karlara bakardı. Kendini bildiğinden beri kasabalarına hiç kar yağmamıştı. Zaten Anadolu’nun güneyine çok nadir kar yağardı. Arzu da hemen gelir yanına oturur beraber seyrederlerdi. Kemal büyünce o zirveye çıkı cam karların üzerinde yatıp yuvarlanacağım derdi. Arzu’ bensiz mi gideceksin derdi. Sensiz olur mu? 

...........................Böyle günler akıp gidiyordu. İkisi de bayağı büyümüşlerdi şimdi on birinci sınıfa gidiyorlardı. Arzu’nun babası şehirde iyi bir iş bulmuş gitmek zorunda kalmıştı. Tabi ki Arzu da gidecekti. Kemal de Arzu da ayrılacakları için çok üzülüyorlardı. Arzu Kemal’le artık içinde tarif edilemeyen bazı duygular besliyordu. Sanki Kemal de ona söylemek istediği ama söyleyemediği bir şeyler vardı. Bir gün Kemal Arzu’ya hani hep düşünüp yapamadığımız şeyi yapalım mı dedi. Arzu hemen anlamıştı. Ertesi gün erkenden kimsenin haberi olmadan beraber dağa çıkmaya başladılar. Kemal tedbir olarak babasının tüfeğini ve birazda yiyecek almıştı. Karlara yaklaştıkça içlerindeki heyecan da artmıştı. Kemal koştu dizlerinin üzerine kara çöktü Arzu da hemen yanı başına.  Kemal birden Arzu ya döndü gözlerinde yaşlar vardı ama çok değişik bakıyordu. Onu hiç böyle görmemişti. Kemal tatlı ve masum bir sesle ‘sana bir şey söyleyeceğim:.............................  ..........................Arzu bunu sana birçok defa söyledim ama bu başka SENİ SEVİYORUM!  Arzu Kemal’e birden bire sarıldı BEN DE BEN DE SENİ SEVİYORUM BEN SENSİZ YAPAMAM KEMAL! Diyordu. Arzu’nun da gözyaşları boşalmıştı. Uzun süre birbirlerine baktılar gözlerinden ip gibi yaşlar boşaldı. Gözyaşları önlerindeki kar tanelerinin içinde kayboluyordu. Arzu önünden iki avucu ile kar aldı elinde sıktı Kemal’ sende böyle yap dedi. Arzu iki kartopunu aldı birleştirdi. Kemal işte biz böyleyiz ayrılamayız Sevgilim dedi. Arzu sordu peki nasıl bildin böyle düşündüğümü dedi. Çünkü Sana aşığım seni senden daha iyi tanıyorum. Kemal’in aklına bir fikir geldi biz bu topu şu ilerideki buzun içerisine saklayalım bu bizim AŞKIMIZIN simgesi olsun Nasılsa bu dağın karı buzu erimez.  Bu beyazlıkta bizim aşkımızın saflığı temizliği olsun Aşkımız sonsuza kadar var olsun. Söz veriyor musun Arzu! Söz veriyorum!  Dedi ve kartopunu iyicene buzla örttüler. Sonra Kemal Arzu’yu karların üzeride yuvarladı. Sonra Arzu Kemal’li. Birbirlerine kartopu attılar. Çok eğlendiler. Dans ettiler. Artık dönme zamanı gelmişti. El ele tutuştular bayırdan kır çiçeklerinin arasından koşa koşa geçtiler. Sonra karınları acıktı. Papatyaların arasına oturdular. Kemal çantasından ekmek, peynir, üzüm çıkarttı. Arzu harikasın sevgilim üzümü sevdiğimi biliyorsun. Seni çok seviyorum ayrılacağımızı hiç düşünmek istemiyorum. Ama uzağa gitmiyorum bir saatlik yol beni görmeye gelirsin değil mi? Sen beni özler misin? Hem de çok! O zaman her hafta gelirim. İkisi de papatyaların üzerine uzandılar. Elerini hiç bırakmadan mavi gökyüzüne güneşe baktılar hayaller kurdular. Arzu sevgilim bak şurada çok büyük bir bulut var yağmur yağabilir mi? Yağsın! De meye kalmadan bir iki damla yüzlerine düşmüştü bile. Kemal hadi kalk! Yine el ele tutuştular kâh koştular kâh yürüdüler. Yağmurda epeyce bastırdı. İkisi de sırılsıklam ıslanmışlardı. Arzu biraz dinlenelim dedi. Bir zeytin ağacının altına çöktüler. Kemal Arzu’nun yüzünü saçlarını eliyle silerken Arzu kemal’lin avuçlarının içini öpüyordu. Kemal iki eliyle Arzu’nun yüzünü saçlarını geriye doğru tarayarak tuttu sonra hiç sana gözlerinin bu kadar güzel olduğunu söylemiş miydim dedi ve dudaklarına bir buse kondurdu ve çekildi. Arzu ben sana ne kadar güzel koktuğunu söylemiş miydim dedi ve Kemal’li kendine çekerek dudaklarını kenetledi belki böyle dakikalarca öpüştüler. Yağmur saçlarının arasından süzülerek bütün vücutlarını ıslattı ama onlar bırakamadılar. Aşkın gözyaşları yağmura karıştı. Birden bir ışık belirdi bulutların arasından güneş bütün sıcaklığıyla birleşen vücutları; sıcaklığıyla ayırdı. Bir süre birbirlerine baktılar, gözlerindeki bu değişik pırıltıyı hiç görmemişlerdi. Kokuları birbirlerine karışmış bu güne kadar böyle güzel bir koku duymamışlardı. Arzu: sevgilim bana söz ver biz sonsuza kadar beraber olacağız değil mi! Evet,  sonsuza kadar.   Kemal de aynı soruyu Arzu’ya sordu! Karşılık aynıydı. Ve el ele yürümeye devam ettiler. 

............................Evlerine yaklaştıkları sırada ikisi de geriye döndüler ve ikisi de dona kaldılar gökkuşağı dağın bir ucundan diğer ucuna uzanıyordu. Hayretle birbirlerine baktılar. Hiç bir şey söylemeden yürümeye devam ettiler. Gökkuşağının altından geçmişlerdi tüm dilekleri kabul olacaktı! 

08-02-2006', '...........................Anadolu’nun şirin bir kasabasının hemen yanında yüce bir dağ vardı. Etekleri yeşil mi yeşil, düzlükleri kır çiçek...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Işın']::text[], 8.5, '{"poet":"Ayhan Işın","poet_slug":"ayhan-isin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/iki-damla-goz-yasi-1-bolum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüz', 'yuz-muammer-erturan-gf7x5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzlerce resim

şahidim

ne bir çizgi eksik,

ne bir renk fazladan

aklımda kalan yüz

yüzde yüz sen...

Aklımı alıp giderken

yüzünü unutmuşsun aklımda...

(20 Haziran''99)', 'Yüzlerce resim şahidim ne bir çizgi eksik, ne bir renk fazladan aklımda kalan yüz yüzde yüz sen... Aklımı alıp giderken yüzünü unutmuşsun ak...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yuz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tolerans', 'tolerans-pascal-dascal-w41on', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Peygamber efendimiz

kendisine hakaret  edenlere karsi

cok tolerans sahibiymis…

Kuyusunu kazan Ebu cehile bile 

dostluk elini uzatmis…

Ne diyelim

elcilikleri atese veren

puromanyak kalabalikmi

yoksa ici bosaltilmis marka muslimani

dandik muslimanmi...

Ici beni uzer disi seni suzer

dedirten bi olay…

Penisini ilah sanan

Hintli dindar 

kim bilir simdi

ne bahtiyar…

Seytan Hintli profete 

88 ayet indirmis

elestirmenlerce

tam bi komedi filimmis…

Hz Isanin son 12 saati de filim oldu 

oldu da ne oldu...

Mel Gipsom Hz Isayi oynadi

öyle yer yerinden oynamadi…

Birer cizgi roman kahramani olan

Batman Superman Örumcek adamda

zati eskiden beri kötuluklere karsi...', 'Peygamber efendimiz kendisine hakaret  edenlere karsi cok tolerans sahibiymis… Kuyusunu kazan Ebu cehile bile  dostluk elini uzatmis… Ne diy...', ARRAY['Türk Edebiyatı','Şiir','Pascal Dascal']::text[], 8.5, '{"poet":"Pascal Dascal","poet_slug":"pascal-dascal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tolerans-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlara çarptı hayalim', 'daglara-carpti-hayalim-elazigli-mustafa-kaya-n9c8e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'göklere yaktığım 

hayal mumum söndü

kayboldum

karanlığında gecelerin.

parça parça kıyıldım.

eski çeşmeler gibi

başı eğik düşüncelerim,

dipsiz

ve sonsuz hayallerim

dağlara çarptı.

dert ve kederlerim

coştu

gönlüm ihtiyarladı

batan bir güneş

gibi

betim benzim sarardı...

yağmur görmüş

saçlarını özledim

gözlerimin ışığı

gamzelerini.

ahh…yoksun

senin denizinde boğulmalıyım

tek dayanağım,

sevginle alevlenen

rüyalarım..

Mustafa kaya

08.02.2006 / istanbul', 'göklere yaktığım  hayal mumum söndü kayboldum karanlığında gecelerin. parça parça kıyıldım. eski çeşmeler gibi başı eğik düşüncelerim, dipsi...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/daglara-carpti-hayalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gittin gideli', 'sen-gittin-gideli-elazigli-mustafa-kaya-21h2g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'şehrin 

tüm martıları 

öfkeli.

kış soğuğu yırtıyor

canları.

sen gittin gideli.

kar iniyor tipi

içimde birikenler

beyaza dönüşen

şehre dağıldı.

sımsıcak bir kelimeydi

duymak istediğim senden. 

acı çekiyorum şimdi

sevinç nöbetlerim

yok artık.

bana sevinçler veren,

ellerindi.

ellerin yok artık,

ruhuma yayan

yüreğindeki sevgiyi..

Mustafa kaya

08.02.2006 / Üsküdar', 'şehrin  tüm martıları  öfkeli. kış soğuğu yırtıyor canları. sen gittin gideli. kar iniyor tipi içimde birikenler beyaza dönüşen şehre dağıld...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-gittin-gideli-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanmaz Dedi.', 'dayanmaz-dedi-seyhmus-sait-aydin-woyc1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oturdum derdimi, Kerem '' e yazdım, 

Bu sevdaya dağlar dayanmaz dedi, 

Benim kadar o da yanacak sandım, 

Bu sevda seni yakar amma o, 

o yanmaz dedi, 

Şair; AYHAN UÇAR.

            

           NOT:Şiirin Tamamı şiirin yazarı   Sayın Ayhan UÇAR''ın Kendi Sayfasında yayınlanmakta olup,Kadim dostumuz''a Sayın Hocamıza Şu soğuk günlerde İzmirden Yorumcu Ortagı Sayın Aysun Asar ''ın güzel sesi,Ilık nefesi ile yorumladıgı bu güzel kendi eserini   Şaire İthaf Edelim İstedik.

           Kabul Buyurulursa ne mutlu Bize.

           Sürçi lisan ettikse Affola.

Saygıyla.', 'Oturdum derdimi, Kerem '' e yazdım,  Bu sevdaya dağlar dayanmaz dedi,  Benim kadar o da yanacak sandım,  Bu sevda seni yakar amma o,  o yanma...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dayanmaz-dedi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin, Sana Özel', 'senin-i-cin-sana-ozel-savas-dincbas-adpue', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir ev yaptım mercanlardan

sevdam yolu üzerinde

senin için, sana özel

halılar gökyüzünün

gece mavisinde dokundu

koltuk takımlarını

istiridyelere ısmarladım

en güzel incileriyle süsleyecekler

gökkuşağı ustaları boyadı

özenle, tüm duvarlarını

bulutları indirdim gökyüzünden

yatağını yaptım

gönlüm yorganın

bir ev yaptım

sevgimle ısınan

şöminende yanan aşk ateşim

bir ev yaptım mercanlardan

sevdam yolu üzerinde

senin için, sana özel...', 'bir ev yaptım mercanlardan sevdam yolu üzerinde senin için, sana özel halılar gökyüzünün gece mavisinde dokundu koltuk takımlarını istiridye...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/senin-icin-sana-ozel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ömür Geçse de', 'bir-omur-gecse-de-huseyin-erdogan-hverg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir ömür geçse de

bir tek sen olacaksın bende

hayallerim sende düşlerim sende

yalnızca ellerin olacak ellerimde

seni sensiz yaşamak zor olsa da

katlanırım razı olurum ben buna

yeter ki sen de beni yaşat yüreğinde

dün gece rüyamda çıkıp geldin bana 

ne olursun dönme diye yalvardım sana

tam sen sevinçle atılırken kollarıma

uyandım üzüldüm durdum yatağımda

inan ki bir başka güzel düşlerimde olsa da

sabahlara dek seninle yaşamak senin olmak

senin o muhteşem yüreğine sevgimi dolmak

mutluluğu heyecanı seninle doruklarda paylaşmak 

inanmıyorsan sevdiğim beni rüyanda bir gör de bak

işte buna denir havalara zıplamak göklere çıkmak

meğer ne de güzelmiş şiirim seninle aşkı yaşamak

bil ki seni yüreğimde taşımak ömrümce benim onurum olacak 

                                                                    08.02.2006

                                                                Hüseyin Erdoğan', 'bir ömür geçse de bir tek sen olacaksın bende hayallerim sende düşlerim sende yalnızca ellerin olacak ellerimde seni sensiz yaşamak zor olsa...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-omur-gecse-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Bir İntihar Mektubudur', 'bu-bir-i-ntihar-mektubudur-perver-bozan-76ns3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece bütün umutlarımı yargılamadan insafsızca öldürdüm.

Ki'' nazlı bir bebek gibi büyütmüştüm hepsini yüreğimde

Ama başıma ne geldiyse bu bebek yüzlü alçaklar yüzünden geldi.

Sabretmemi fısıldayıp durdular kulağıma,

Mutlaka günü gelecekti...

İşte o gün bu gündür. Günü geldi.

Sabır taşı çatladı. ''YETER'' dedi.

Bütün umutlarımı öldürüp çarmıha gerdim bu gece; 

Aşklarım, şahit yazmasınlar diye kaçtılar...

Dönmezler bence! 

Kim bilir nerdeler? 

Elimde bir dostluklarım kalmıştı,

Sabah kalktım onlarda yoktu.

Hey Hat! 

Meğer hepsi umutlarımın içini doldurduğu bir balonmuş,

Şimdi hepsi yokluğun içinde kaybolmuş.

Birden odayı bir ıssızlık sardı

İğrenç kokusuyla yalnızlık

Dönüş yoktu yaşananlardan

Fayda etmezdi son pişmanlık

Biliyorum kimse yakıştırmazdı böyle bir ölümü bana

Ama yaşanmaz bir ömür böyle yalınız

Kim kazandı bilmiyorum

Bildiğim ben kaybettim

Kısacık ve anlamsız ömrümde kazandıklarımın

Yarısı terk etti beni

Yarısını ben katlettim

Bu gece yaşadıklarımın özeti budur

Dünya bile rahatlayacaktır gitmemle

Bu bir intihar mektubudur

Sevinin öldüğüme.', 'Bu gece bütün umutlarımı yargılamadan insafsızca öldürdüm. Ki'' nazlı bir bebek gibi büyütmüştüm hepsini yüreğimde Ama başıma ne geldiyse bu ...', ARRAY['Türk Edebiyatı','Şiir','Perver Bozan']::text[], 8.5, '{"poet":"Perver Bozan","poet_slug":"perver-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bu-bir-intihar-mektubudur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye...', 'sevgiliye-perver-bozan-f4wf7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmeye severdim aslında,

Sevemedim işte...

Nedenini, sebebini sorma bana

Hiç bir şey sorma...

Tuzla buz olmuş kalbime.

Merhaba gülüm...

Aşkımı nasıl anlattıysam şiirlerle

Derdimi de anlatmaya çalışacağım

Neden artık sevemiyorum kimseyi

Neden artık istemiyorum hiçbir şeyi

Herkesin bebeğini topunu sevdiği zamanlarda tanıştım aşkla

Daha yaşım onbir, yüreğim on gram

Kim duysa gülüp geçiyor yaşadığım aşka

Kim duysa çocuk hevesi zannediyor

İnanmayıp şaşırıyorlar bu küçük adama

O yaşlarda bile inatçıyım hayatın karşısında

Kimseyi umursamıyorum. Dinlemiyorum

Yaşıyorum aşkımı herkesin inadına

Her ne kadar sevdiğimi haykırsam da

Sevdiğimi dahi sevdiğime inandıramıyorum

Babam bir adım gerisine düşüyor hayatın

Bense babamın bir adım ardına

Aşklar bu dönem uğramıyor kapıma

Ama ben gene de besliyorum yüreğimi

Olurda onbir gram olur mu diye...

Hayat direnmeye kalbim beslenmeye dayanmıyor

Her ikisi de ardına kadar açıyorlar kapılarını

Güzel bir hayat ve aşklar yaşıyorum

İnsanların o dönemki çirkefliklerine rağmen

En temiz duygularımla tüm insanları seviyorum.

Ruhumda fırtınalar kopartan aşklar

Ayağımı yerden kesen aşklar

İnsanı ''ölmezsin sen'' diye kandıran aşklar...

Giriyor hayatıma, ömrümün en güzel zamanında

Yirmi yaşımın hemen altında

İşte hayatımın bu pembe döneminde

Bir aşk giriyor hayatıma

Ömrümün ilk aşk acısı yaşanıyor

Kader yazıcısı, ''felek''

İlk bıçağını saplıyor sırtıma

Ondan sonra başlıyor kaderimden kaçışım

İnsanlarla kavgam başlıyor. Hayatla savaşım.

Artık gözümde herkes kötü, her şey yanlış

O tanrı aldı ya sevdiğimi yanına

Başlıyor her daim tanrıya haykırış

Yani anlayacağın ey sevgili

Yeni bir durum değil bendeki bu serzeniş

Taaa o zamanlarda da vardı bu isyan

O zamanlar aldığım sağalmış yaramdır

Şimdi durmadan kanayan...

Derken bu kurak çölde bir umut

Bir delimavi gül filizlendi herkese inat

Hiç beklemediğim bir anda girdin hayatıma

Kapıyı bile çalmamıştın. Pencereden girdin...

''Ben geldim'' diyerek çıktın karşıma.

O kadar dağınıktı ki hayatım önce kabul etmedim seni

Dağınıklığımla beraber, huzurlu değilsem de

Mutsuz hayatımdan pekte memnundum

Ama hayatıma girip çıkarkenki esintin bile

Toplamaya yetti. Hayatımın dağınık halini

Nerdeyse bir sene sonra

Yeniden yansıdı gülümsemen pencereme

Ne yapıyorsun bi tanecik der gibiydi

O görmediğim bocuk gözlerin

Yüreğimin en derinlerine...

Keyifle sürüyordum varlığını

Dostluğun ilgin hoşuma gidiyordu

Ama içimde bir korku ya severse diye

Ya severseden kötüsü de vardı

Ya kendini sevdirirse! 

Korkunun ecele faydası yokmuş derler

Çünkü hem sevdin hem sevdirdin kendini

Sonu acı değil ölüm bile olsa sevdim seni

Çünkü gülüm razıydım her şeye

Savaşıyordum eski olan tüm kötü hislerimle

Ama ne kadar güzel, ne kadar iyisende

İçimdeki şeytan kadar güçlü değildin

Sonunda gene o galip geldi

Sakın ha aklına bir şey gelmesin

Seni yüreğimden değil elimden söküp aldı

Artık benim değil onun bedenidir bu taşıdığım

Sakın üzülme o şeytanla yaşamaya alışığım

Acılar hüzünler dertler bende hiç bitmez

Ben tanrıya isyan etmiş bir kulum

Bu lanet benden hiç gitmez

Ölmeye ölürdüm aslında,

Ölemedim işte...

Nedenini, sebebini sorma bana

Hiçbir şey sorma... 

Hiç olmuş kaderime.', 'Sevmeye severdim aslında, Sevemedim işte... Nedenini, sebebini sorma bana Hiç bir şey sorma... Tuzla buz olmuş kalbime. Merhaba gülüm... Aşk...', ARRAY['Türk Edebiyatı','Şiir','Perver Bozan']::text[], 8.5, '{"poet":"Perver Bozan","poet_slug":"perver-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/sevgiliye-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Sadakat', 'sonsuz-sadakat-perver-bozan-olk4w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevsem bir seni seveceğim biliyor musun? 

Yumduğumda hayalin gelecek gözlerime,

Ağlamak için kapanacağım dizlerine...

Türküler yakacak,

Şiirler yazacağım adına

Hayatta kalsam aşkınla yaşayacağım

Ölürsem kavuşacağım sana!', 'Sevsem bir seni seveceğim biliyor musun?  Yumduğumda hayalin gelecek gözlerime, Ağlamak için kapanacağım dizlerine... Türküler yakacak, Şiir...', ARRAY['Türk Edebiyatı','Şiir','Perver Bozan']::text[], 8.5, '{"poet":"Perver Bozan","poet_slug":"perver-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sonsuz-sadakat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstersen Sorma Alışmışım', 'i-stersen-sorma-alismisim-yusuf-onder-bahceci-jml6a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vuslatı kalbimde buluşturdum ben,

Hasreti de gönlüme alıştırdım ben,

Ayrılığı hislerime karıştırdım ben,

Sen istersen sorma alışmışım ben.

Bu ayrılık kâlbimden vuruyor beni,

Bilirmisin ne kadar severim seni,

Beni sevdinmi ki bir bileyim hani,

Sen istersen sorma alışmışım ben.

Bil gözlerinde her an yaşlar olmalı,

Kâlbin mahsun olup yüzün solmalı,

Yüce sevdanın sonu toprak olmalı,

Sen istersen sorma alışmışım ben.

Öbür Dünya''da da mutlu olamam,

Bu şartlarda inan mesut olamam,

Orada da böyle yaparsın inanmam,

Sen istersen sorma alışmışım ben....', 'Vuslatı kalbimde buluşturdum ben, Hasreti de gönlüme alıştırdım ben, Ayrılığı hislerime karıştırdım ben, Sen istersen sorma alışmışım ben. B...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istersen-sorma-alismisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efkara Çeyrek Kala, Aklımdakiler...', 'efkara-ceyrek-kala-aklimdakiler-perver-bozan-nbjno', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen manasız günlerin anlamsız gecelerinde

Bazen herhangi bir vaktin zamansız saatlerinde...

Gösterir akrep efkarı

Boşunadır yelkovanın dönmesi

Akrep takılmıştır bir kere

Ve gidemez bir yere

Ya efkar gönülde boğulacaktır bu andan sonra

Ya da efkar gönlünü boğacaktır sonsuza kadar.

Boğan gönlünse,

Perde açılacak, zaman geçecek

Ve damağında efkarın tadı kalacaktır

Boğulan gönlünse,

Vücudun gevşeyecek, gözlerin kapanacak

Ve ağzında aldığın son nefesin tadı kalacaktır.', 'Bazen manasız günlerin anlamsız gecelerinde Bazen herhangi bir vaktin zamansız saatlerinde... Gösterir akrep efkarı Boşunadır yelkovanın dön...', ARRAY['Türk Edebiyatı','Şiir','Perver Bozan']::text[], 8.5, '{"poet":"Perver Bozan","poet_slug":"perver-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/efkara-ceyrek-kala-aklimdakiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yolcu  - Asrın Hissiyatı Kitabından', 'bir-yolcu-asrin-hissiyati-kitabindan-omer-ekinci-micingirt-8aehe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yolcu ki başıboş

Zihni çarık ve sarhoş

Yırtılıyor izânı

Ruhu sisli girdapta

Akıl firar koş hâ koş

Diz mecalsiz azık boş

Yol heyula sisli loş

Dâva zorlu yol yokuş

Bir yolcu ki başıboş

Bir yolcu ki başıboş

Surat buzlu karakış

Yırtılıyor izânı

Pusulasız ve berduş

Hedef şaşı tuz kokmuş

Bozuk çarklar kör bakış

Yol heyula sisli loş

Dâva zorlu yol yokuş

Bir yolcu ki başıboş', 'Bir yolcu ki başıboş Zihni çarık ve sarhoş Yırtılıyor izânı Ruhu sisli girdapta Akıl firar koş hâ koş Diz mecalsiz azık boş Yol heyula sisli...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-yolcu-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Zenginim', 'cok-zenginim-yusuf-onder-bahceci-s9qki', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben çok zenginim zengin,

Benim Yüce Allah''ım var,

Ben çok zenginim zengin,

Benim Yüce Kuranım var.

Bana söylermisiniz bana,

Kalbi hain, zalim ve  lain,

Söyleyin sizlerin neyi var,

Benim Yüce Kuranım var.

Bu Dünya birgün bitecek,

Ameller bir bir görünecek,

Alim ve de zalim bilinecek,

Benim Yüce Kuranım var.

Ben çok zenginim zengin,

Allah''ını sevenler dengim,

Her an Allah, Allah derim,

Ben çok zenginim zengin....', 'Ben çok zenginim zengin, Benim Yüce Allah''ım var, Ben çok zenginim zengin, Benim Yüce Kuranım var. Bana söylermisiniz bana, Kalbi hain, zali...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-zenginim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher vaktini beklemek', 'seher-vaktini-beklemek-murat-yazici-fwnb5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seher Vaktini Beklemek

Düştün ya yine aklıma; 

Uykular haram bana.

Geceler sabahsız, 

Sabahlar karanlık.

Gel de göreyim gözlerindeki aydınlığı ey güzel.', 'Seher Vaktini Beklemek Düştün ya yine aklıma;  Uykular haram bana. Geceler sabahsız,  Sabahlar karanlık. Gel de göreyim gözlerindeki aydınlı...', ARRAY['Türk Edebiyatı','Şiir','Murat Yazıcı']::text[], 8.5, '{"poet":"Murat Yazıcı","poet_slug":"murat-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seher-vaktini-beklemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansızca - Seher', 'zamansizca-seher-murat-yazici-yg1ag', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar, 

Zamanımın gelmesini bekler dururken, 

O çıkmıştı karşıma 

Zamansızca...', 'Bir zamanlar,  Zamanımın gelmesini bekler dururken,  O çıkmıştı karşıma  Zamansızca......', ARRAY['Türk Edebiyatı','Şiir','Murat Yazıcı']::text[], 8.5, '{"poet":"Murat Yazıcı","poet_slug":"murat-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zamansizca-seher-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende miyim?', 'sende-miyim-belgin-turan-etoxa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Can aşkı ile perişan, nerde bir vefa sevgilim,

Hasreti hep kendine şan, kalbe bin cefa sevgilim,

Bende miyim? Sende miyim? Yanar içim, söyler dilim,

Vuslatı görse artık can, sürelim, sefa sevgilim.

Belgin Turan', 'Can aşkı ile perişan, nerde bir vefa sevgilim, Hasreti hep kendine şan, kalbe bin cefa sevgilim, Bende miyim? Sende miyim? Yanar içim, söyle...', ARRAY['Türk Edebiyatı','Şiir','Belgin Turan']::text[], 8.5, '{"poet":"Belgin Turan","poet_slug":"belgin-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sende-miyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Büyüdüm Anne', 'ben-buyudum-anne-omer-osman-avci-gaqxu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya

Çemberimden hızlı döndü.

Yıllar

Telden arabamı gerilerde bıraktı.

Ben büyüdüm

Hem de 

Kocaman adam oldum

Anne! ...

Yamalı kısa pantolonu

Hep düşen,

Uçurtması tellere takılan

O sümüklü

O cılız çocuk yok artık.

Ben büyüdüm...

Büyüdüm ben anne...! 

Şimdi:

Öyle geniş ki omuzlarım

Dünyanın yükünü taşıyabiliyorum.

Öyle büyük ki yüreğim

Tüm çileleri çekebiliyorum.

Öyle uzun ki kollarım

Boşlukları sarabiliyorum.

Ve...

Öyle hızlı ki adımlarım

Mutsuzluğa koşabiliyorum...

Ben büyüdüm

Büyüdüm ben anne!', 'Dünya Çemberimden hızlı döndü. Yıllar Telden arabamı gerilerde bıraktı. Ben büyüdüm Hem de  Kocaman adam oldum Anne! ... Yamalı kısa pantolo...', ARRAY['Türk Edebiyatı','Şiir','Ömer Osman Avcı']::text[], 8.5, '{"poet":"Ömer Osman Avcı","poet_slug":"omer-osman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ben-buyudum-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakka Gönül Vereneler', 'hakka-gonul-vereneler-sair-aveleye-86jiy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hakka Gönül Verenler 

Hakkı Hak İle Bulur

Ne Edersek Edelim

Hakkın Dediği Olur

                             Aveleye', 'Hakka Gönül Verenler  Hakkı Hak İle Bulur Ne Edersek Edelim Hakkın Dediği Olur                              Aveleye...', ARRAY['Türk Edebiyatı','Şiir','Şair Aveleye']::text[], 8.5, '{"poet":"Şair Aveleye","poet_slug":"sair-aveleye","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hakka-gonul-vereneler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahverengi', 'kahverengi-nilgun-acar-ych0q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kahverengi bir hüzün var

içimde

kahve tadında değil

yanar döner

yaprakların ezgizi

sisli dönemeçlerde

kezlerce yürünmüşlüğün sezgisi

yüreğimde

küçücük kanatları kopuk

bir serçenin gözleri

yağmurlara can vermiş

iki inci tanesi

değirmenlerde öğütülmüş

darmadağınık sesi

duyulmamış

ince sızı

yaşadığım kahverengi

yapış yapış

tüm benliğime sarılmış', 'Kahverengi bir hüzün var içimde kahve tadında değil yanar döner yaprakların ezgizi sisli dönemeçlerde kezlerce yürünmüşlüğün sezgisi yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Acar']::text[], 8.5, '{"poet":"Nilgün Acar","poet_slug":"nilgun-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kahverengi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişi Saklıyorum Gözlerimde', 'gecmisi-sakliyorum-gozlerimde-celal-topo-vb3t4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayalimin ıslak sokaklarında bekleyerek

Çıkıp ta gelecek olan mutluluğu gözledim

Anlık sevinçler tat bırakmadı dudaklarımda

Dost olduğum o eski acılarımı özledim.......

Bir rüzgar gibi esip te geçti dostluğun sesi

Dalları kırık duygular bıraktı yüreğimde

Şimdi hazan sarısı ellerimle kapattığım

Hayata küs bir geçmiş saklıyorum gözlerimde...

07 / 02 / 2006 Antalya', 'Hayalimin ıslak sokaklarında bekleyerek Çıkıp ta gelecek olan mutluluğu gözledim Anlık sevinçler tat bırakmadı dudaklarımda Dost olduğum o e...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gecmisi-sakliyorum-gozlerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanma', 'aldanma-suleyman-yavuz-ecjki', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılığın zamanı geldiyse eğer

Direnmek neye yarar

Ömür geçip gittiyse bir vefasız için

Ağlamak neyi çözer

Kırılmadıysa yüreğindeki buzlar

Söyleyin bu halinize

Onun içi nasıl sızlar

Aldanmayın seviyorum diyen her yüze

Kanmayın her tatlı gülüşe 

İnanmayın bir buseye kanmayın

Sonra vefasız yar aşkıyla 

Yanıp kül olmayın

İnanmayın…

Kanmayın…

Yanmayın…

Bir olmaz uğrunda yok olmayın…', 'Ayrılığın zamanı geldiyse eğer Direnmek neye yarar Ömür geçip gittiyse bir vefasız için Ağlamak neyi çözer Kırılmadıysa yüreğindeki buzlar S...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aldanma-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gürün Çok Güzel Görün', 'gurun-cok-guzel-gorun-yusuf-onder-bahceci-dyj6j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gürün''ün Tato diye bir elması var,

Sade elmasımı var Gökpınar''ı var,

O da bir kenara iyi insanları  var,

Gürün çok güzel, görün diyorum.

Gürün''ün Köyleri birbirinden güzel,

Köylerde bir tarafa güzelleri güzel,

Gürün bir vadi içinde şiirler düzer,

Gürün çok güzel, görün diyorum.

Suçatı diye güzel bir Kasabası var,

Kasaba ama inanın her şeyleri var,

Dutları, kaysıları, armutları bile var,

Gürün çok güzel, görün diyorum.

Gürün''ün Tıhmın diye bir Köyü var,

Bu köyde de inan ki ne ararsan var,

Tarihiyle, doğal güzelliğini soranlar,

Gürün çok güzel, görün diyorum.

Gürün’ün Gübün diye mahallesi var,

İnsanları çok zeki, iman libasları var,

Öyle lahanalar yetişir ki hevesleri var,

Gürün çok güzel, görün diyorum.

Gürün’ün pekmezini Dünya biliyor,

Astıma ve nefes darlığına iyi geliyor,

Suçatı’da ise Dut Festivali yapılıyor,

Gürün çok güzel, görün diyorum.

Gürün’de yaz ayında festivaller olur,

Herkes birbirini bulur, hasbıhal olur,

Bu ayda düğünler, dernekler kurulur,

Gürün çok güzel, görün diyorum...', 'Gürün''ün Tato diye bir elması var, Sade elmasımı var Gökpınar''ı var, O da bir kenara iyi insanları  var, Gürün çok güzel, görün diyorum. Gür...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gurun-cok-guzel-gorun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hürriyeti Kısıtlamayalım Beyler', 'hurriyeti-kisitlamayalim-beyler-recep-uslu-9vg40', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En çok sevdiğim şey

Helada sigara içerek

Şiir yazmaktır.

Bir de oğlumun beni dinlememesi

Dileğince büyümesi.

Haa şu da var...

Öğrencilerimin ödev yapmaması.

Ama; 

Helada sigara içmeme

Karım karışır

Kokudan durulmaz diye.

Oğlumun dinlememesine annesi

Hayırlı evlat olmaz diye.

Öğrencilere de öğretmen

Vatan kurtulmaz diye.

Acaba...

Karım.anne ve öğretmen

Böylemi dünyaya geldiler? 

Hürriyeti kısıtlamayalım beyler.

              22.04.1986

Önemli Not:Çok kötü alışkanlık olan ''sigara'' için herkesten özür diliyorum.', 'En çok sevdiğim şey Helada sigara içerek Şiir yazmaktır. Bir de oğlumun beni dinlememesi Dileğince büyümesi. Haa şu da var... Öğrencilerimin...', ARRAY['Türk Edebiyatı','Şiir','Recep Uslu']::text[], 8.5, '{"poet":"Recep Uslu","poet_slug":"recep-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hurriyeti-kisitlamayalim-beyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her yağmur içimde zindan''lı Yusuf', 'her-yagmur-icimde-zindan-li-yusuf-ramazan-kayak-8kuiv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her yağmur yağdığında benim ömrüme 

Bir  ateş içimde yangına döner

Akar damlalar tüm bedenime 

Ruhumda bir deprem……..döner

Yapraklar ıslanır güller ıslanır 

Kapalı ağızlarda diller ıslanır

Mevla’ya açılan eller ıslanır

Ruhumda bir feryat……..döner 

Anlamam ne olur tende ki ben de

Kaçmak uçmak ister bu beden''den 

Kalbim çılgın olmuş yüreğim dert’e

Ruhumda bir kaçış……..döner

Ne kaçmak ne uçmak dinmez bu arzu 

Yürek bin parçadır  geçmiyor tutku

Her yağmur içimde zindan’lı Yusuf

Ruhumda bir kuyu……..döner', 'Her yağmur yağdığında benim ömrüme  Bir  ateş içimde yangına döner Akar damlalar tüm bedenime  Ruhumda bir deprem……..döner Yapraklar ıslanır...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/her-yagmur-icimde-zindan-li-yusuf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Külaltı', 'kulalti-tahsin-simsek-922bn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KÜLALTI

Bir salla geleceği sana

Yine o kıyısız korkularla

Bilinmedik koyaklar mı kaldı

Ah, bunca yıldan sonra

Süt mavisi yeleleri rüzgârda

Sen ki yüreğimin koru

Söyle hangi ırmak dökülür

Bir yanardağın ağzına

Ve bilinmesi deşeleyebilir misin

Merakım, bir tek oralarda

O yer altı mercan mağaralarında

Halaya dururmuş ya, can /

                                          An', 'KÜLALTI Bir salla geleceği sana Yine o kıyısız korkularla Bilinmedik koyaklar mı kaldı Ah, bunca yıldan sonra Süt mavisi yeleleri rüzgârda S...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Şimşek']::text[], 8.5, '{"poet":"Tahsin Şimşek","poet_slug":"tahsin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kulalti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozan', 'ozan-tahsin-simsek-9n8sf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'OZAN

Seslere vurgun sözcüğe yüklü

Ne denli zor birleşiyor seslem

Sözcükleşince “gebe” utanmak örtülü

Oysa çoktan esin doldu özlem

Onurdur çağlarca yüklü olmak

Ve bir gece yarısı yükselip dağlarca

Tanda buluşup boşalmak

Sonra da güllerde donuvermek

                 damla

                  dam 

                    la

Sevi çiçeklerinin toprağıyım

Anlıyorum korurken neden titiz

Çoğaldıkça anlıyorum şimdi

Ve analar neden hiç küsüp gitmez

Ozanım ben küstüremem sözcükleri

Ben hem bulut hem toprağım

Utanır mıyım hiç sizler için yüklenmeyi

 Çünkü ben sözcükleri doğurtup

             şiiri doğuranım

                       ki 

       katmer katmer çiçekçe

                      açım

                   a  ç  ı  m', 'OZAN Seslere vurgun sözcüğe yüklü Ne denli zor birleşiyor seslem Sözcükleşince “gebe” utanmak örtülü Oysa çoktan esin doldu özlem Onurdur ça...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Şimşek']::text[], 8.5, '{"poet":"Tahsin Şimşek","poet_slug":"tahsin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ozan-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Faust''u okurken', 'faust-u-okurken-tahsin-simsek-5pt6v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'FAUST’U OKURKEN

O yaşayan ve yaşatan halkım için

Çiyde yıkanmış düşüncelerimi bellemek varken

Serin kokulu bilmek sağnağından kaçıp

Durup durup Faustluğa özenmek neden

Ama yaşam ağacının yeşili arasından doğan

Gül rengi ışığı doğuran karanlıkta

Tek durmayan bir yıldızdır umut

Aşktır bu, ağıp ağıp ruha dolan

Aşk denilen o engin memeden doyabilecek miyim

Ozanları bağlamayan zamanın bir yerinde

Orospuluğuna tel kondurulmayan Helena’yı

İd aya da Arkadia’da şeytanla yalınayak beklersem

Oysa her zaman yanılır yorulan insan

Ey sen, yaşayan ve yaşatan halkım

İşte bu yüzden uzağım –belki- her türlü sevinçten    

Ki beklemektir gülün başına dikeni bela eden', 'FAUST’U OKURKEN O yaşayan ve yaşatan halkım için Çiyde yıkanmış düşüncelerimi bellemek varken Serin kokulu bilmek sağnağından kaçıp Durup du...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Şimşek']::text[], 8.5, '{"poet":"Tahsin Şimşek","poet_slug":"tahsin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/faust-u-okurken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzgörümlüğü', 'yuzgorumlugu-tahsin-simsek-sn0k7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'YÜZGÖRÜMLÜĞÜ

                 -Zeynep''e-

Zamanın en duru yerinden

Kana kana sular içiyorum seninle

Ipılık oluveriyor hemen

          her şey / yepyeni

Bir yaşamın dörtyol ağzında

Bahar toprağı gibiyim

Çiçeklerim var tomur tomur

Ayışığında son anka neşeyle

Şarkısını söyler gecemizin

Ufkumdan hiç eksilme

Güneşim olduğunu bileyim,

Yaşamın sıcaklığını ver,

Ellerini ver, gözlerini

             ver öpeyim

Her öpüşte

Bu sıradışı zamanın

En güzel sabahında

Varolduğumu bilmekteyim

Dönüp dönüp sana gelmekte

         senin olmaktayım

Zamanın en duru yerinden

Çiçekler dermekteyiz seninle

Gonca olup açıyor

           ellerimiz ilk kez

Uzanırken ilkyaz bir sevgiye

Sevmeliyiz yürekteki sözüm

Sevmeliyiz beraberliğimizi

Sevdanın ten çiçeklerini

Ve yaşama kenetli her şeyi', 'YÜZGÖRÜMLÜĞÜ                  -Zeynep''e- Zamanın en duru yerinden Kana kana sular içiyorum seninle Ipılık oluveriyor hemen           her şey...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Şimşek']::text[], 8.5, '{"poet":"Tahsin Şimşek","poet_slug":"tahsin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yuzgorumlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bela', 'bela-zeynal-yaman-zgy76', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey Zeynel! Bela dilden çıkıp konarmış başa

Ya bin düşünüp bir söyle ya da sessiz yaşa', 'Ey Zeynel! Bela dilden çıkıp konarmış başa Ya bin düşünüp bir söyle ya da sessiz yaşa...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bela-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çorak Ömrüm', 'corak-omrum-ahmet-unal-cam-wmdek', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Maziyi unutup, atiye baksam

Bütün dertler biter mi

Her acıma bir mum yaksam

Mumlar bana yeter mi? 

Acep, bir haber salsam nazlı yare

“Yar, bana bir çare,bana bir çare! ”

Tutar mı elden.

                          Yoksa ben biçare.

Son nefesim tende iken yiter mi? 

Gelsin şimdi,  çalsın davullar, zurnalar

Halay çeker gönlümde acılar

Küsüp gitti artık bana aynalar

Şu çorak ömrümde, gül biter mi?', 'Maziyi unutup, atiye baksam Bütün dertler biter mi Her acıma bir mum yaksam Mumlar bana yeter mi?  Acep, bir haber salsam nazlı yare “Yar, b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/corak-omrum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Git', 'simdi-git-suleyman-yavuz-wbutu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle bir anda git ki

Anmayayım adını bir daha

Öyle git ki

Kinim yensin sevgimi

Beni öyle derinden yarala

Beni sırtımdan vur da git ki

Bir daha ağlamayayım sana

Yanmayayım bir daha

Şimdi git 

Ve bakma sakın ardına

Çünkü göreceğin senden geriye kalan

Kin nefret ve kan olacak

Birde yere batası bir aşk', 'Öyle bir anda git ki Anmayayım adını bir daha Öyle git ki Kinim yensin sevgimi Beni öyle derinden yarala Beni sırtımdan vur da git ki Bir da...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/simdi-git-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet Kuşağı', 'cumhuriyet-kusagi-tahsin-simsek-v8uw0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'CUMHURİYET KUŞAĞI

               (Orda bir köy var (dı)  uzakta

                O köy bizim köyümüzdü / r)  -  II

Biz o evlerde büyüdük

Damına tuz atılan

Ak toprakla sıvalı

Kiliti hiç bilmeyen o kapılar

Arkası, sadece geceleri dayaklı

Biz ne savaşlar yaşadık

       -Düşman, artık İzmir''den de öte

Yüreğimizi hiç eskitmedik

Gecelerce iplik büküp

Kara dimiden donlar

Ak astarlı işlikler diktik

Herkes kendine terziydi

      -Cumhuriyet hepimize

Eskidi pantolonlarımız

Süvarilik geçirdik

Yamalıydı fistanımız

Nalçalı ayakkabılarla

Hem ne acılar ezdik

Bilmedik, hiç ezilmeyi

      -Biz, bir Cumhuriyet''i bildik

Tabanlarımız yarılır

Ellerimiz çatlardı koşuşturmaktan

Her yarığa zift koyduk

Soğan dövdük ağrıyan yerimize

Karahayıt yakıları vurduk

Kızgın tuğlalara oturduk

Ağrıdıkça karnımız ah,

Ama düşman sofrasına

Hiç mi hiç oturmadık

      -Çaremizdi Cumhuriyet

Hiç gök ekin çiğnemedik

Buğdayı şehirliye

Yumurtayı beylere sattık

O arpa ekmeğiyle yediğimiz

Sıcacık paparayla yattık

Horozu mu

Onu sadece damada keserdik

      -Biz, biz hiç kesilmedik

Aşılanmayı bekleyen çöğürdük

Ocakta pelit közlerdik bazen

Hasırlara armutlar yardık

Katığımız pazar ekmeğiydi

Ağzımızda, ak tülbentten

Sorup sorup emdiğimiz

Kuru lokma, anamızın çiğnediği

Daha, daha dünkü bebeydik

      -Cumhuriyet, hep gözümüzün bebeği', 'CUMHURİYET KUŞAĞI                (Orda bir köy var (dı)  uzakta                 O köy bizim köyümüzdü / r)  -  II Biz o evlerde büyüdük Damı...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Şimşek']::text[], 8.5, '{"poet":"Tahsin Şimşek","poet_slug":"tahsin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/cumhuriyet-kusagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmak İstemesen de', 'i-nanmak-i-stemesen-de-hasan-i-yigun-6eqqa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hani eski bir resim görünce, gözlerin dolar

Hislenirsin, boğazın düğümlenir, duyguların coşar

Sayarsın ama inanamazsın, yıllar nasıl geçti diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani bir şarkı duyarsın,  birlikte dinlediğiniz

Gözlerinde canlanır o yerler, beraber gezdiğiniz

Sorarsın kendine acaba şimdi nerede, nasıl diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani ayrılmadan önceki o son günler

Hissediyorsun bitecek bu beraberlik, o acı sözler

Kendini inandırmaya çalışıyorsun, biz ayrılamayız diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani o ilk ayrılık günü, eşyalar toplanırken

Bazı şeyleri paylaşıyorsunuz o resmi sen al, bu resmi ben

Sanıyor musun faydası olacak, o resmi aldı diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani bazen düşünüyorsun, biz böyle mi olacaktık

Nasıl mutluyduk, gelecekte güzel günler yaşayacaktık

Hatırlamak artık boş, bizi nasıl kıskanırlardı diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani ayrılığın ilk günlerinde sen öfkelisin, o kırgın

İkiniz de birbirinizden bekliyorsunuz, atılmasını ilk adımın

Düşünüyorsunuz ilk adımı o atarsa, barışırım diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani sen onsuz yapamazdın, o da sensiz

Uzun uzun göz göze bakardınız sessiz

Kelimelere gerek duymazdınız, gözleriniz yeter diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani bazen yolda birini görürsün, birlikte tanıdığınız

Sorar eski günlerden, vardır ortak anılarınız

Düşündüklerini söyleyemezsin, yanlış anlaşılır diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani bazen rüya görürsün, tekrar birliktesiniz

Uyanınca fark edersin, yine yanlız,  yine kimsesiz

Sonra oturup düşünürsün, bu ayrılık nedendi diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani ayrılınca özlüyorsun onun kokusunu odada

Ama çaresiz bulamıyorsun ne çarşafta, ne yastıkta

İnanmaya çalışıyorsun, bitti artık her şey diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani bazen içinde hissedersin derin bir sızı

Ayrı geçirmişsinizdir, bir çok kışı ve yazı

Düşünürsün bazen acaba hiç pişman oldu mu diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani bazen düşünüyorsun, pişman olup gelecek

Evet pişman geldi sana, var mı yürek onu kabul edecek

Bakıyorsun çevrene, düşünüyorsun toplum ne der diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani şiirler vardır, aşk acısını anlatan

Birlikte dinlediğiniz şarkı gibi, sonunda ağlatan

Düşünürsün gerçekten ayrılık çare miydi diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani düşünürsün bazen, acaba şimdi mutlu mu

Merak edersin, ara sıra seni hatırlıyor mu

Düşünürsün, bir selam göndersem ne der diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani bir gün karşılaşırsın onunla tesadüfen

Bir an göz göze gelirsiniz, oradan geçiyorken

Çok şey söylemek istersin, susarsın üzülür diye

İnanmak istemesen de, artık bitmiştir o sevginiz

Hani gerçeği kabul ediyorsun zamanla, biz ayrıldık

Hiç bir şarkı, hiç bir resim, bizi birleştiremez artık

Şimdi çok geç barışmak için, bu beraberlik bitti diye

İnanıyorsun sonunda çaresiz, artık bitmiştir o sevginiz.', 'Hani eski bir resim görünce, gözlerin dolar Hislenirsin, boğazın düğümlenir, duyguların coşar Sayarsın ama inanamazsın, yıllar nasıl geçti d...', ARRAY['Türk Edebiyatı','Şiir','Hasan İyigün']::text[], 8.5, '{"poet":"Hasan İyigün","poet_slug":"hasan-i-yigun","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/inanmak-istemesen-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün batarken', 'gun-batarken-elazigli-mustafa-kaya-fd1s4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ellerini diyorum..

ellerini tutamazsam,

bu şehirde

bu hasretle kahrolurum

zaman geçiyor

ömür bitiyor

bahçemin gülleri solmadan

beni sevdiğini söyle

yağmur ol 

rüzgar ol 

bir martı

bir güvercin ol gel

çok uzaklarda kalma öyle

düşüyorum

üşüyorum sensiz

gün batarken

bırakma beni

kimsesiz..

Mustafa kaya

08.02.2006 / kanlıca', 'ellerini diyorum.. ellerini tutamazsam, bu şehirde bu hasretle kahrolurum zaman geçiyor ömür bitiyor bahçemin gülleri solmadan beni sevdiğin...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gun-batarken-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir dostum tutsun beni', 'bir-dostum-tutsun-beni-elazigli-mustafa-kaya-nswfj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zehir zemberek

bir kış soğuğu

elimi tutsun 

bir dostum

kırılmaz o zaman

kanadım kolum..

Mustafa kaya

08.02.2006 / üsküdar', 'zehir zemberek bir kış soğuğu elimi tutsun  bir dostum kırılmaz o zaman kanadım kolum.. Mustafa kaya 08.02.2006 / üsküdar...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-dostum-tutsun-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin içinden', 'gecenin-icinden-baris-polat-uhyk5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine bir hüzünlü gece doğuyor hayata

kuşların sesi kısılıyor sanki

önceden bildikleri birşey gibi

Sokaklar ıssız gaybana oluyor gece

Ayyaşların narası inletiyor sokakları

Ve birde,seni seviyorum diye

Haykırışların gürültüsü küçük,küçük

Sokak lambaları eşlik ediyor geceye

Kendince aydınlatıyor etrafı ve birde

Aşk acısı yaşayanların iniltisi yakıyor geceyi

Hüzünlü vehüzünlü olduğu kadar suskun çileli

Sanki yalvararak çağırıyor doğacak güneşi

Kalabalığa karışabilmek için

Her ne kadar güneş doğsada,bilmezmisin

okadar''da gece doğar hayata.', 'Yine bir hüzünlü gece doğuyor hayata kuşların sesi kısılıyor sanki önceden bildikleri birşey gibi Sokaklar ıssız gaybana oluyor gece Ayyaşla...', ARRAY['Türk Edebiyatı','Şiir','Barış Polat']::text[], 8.5, '{"poet":"Barış Polat","poet_slug":"baris-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gecenin-icinden-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Görmeden Ölemem....', 'seni-gormeden-olemem-ahmet-ucyildiz-wqt27', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben Sensiz Ölürüm

Hesabını Tanrı''ya veremem

Bir umut olarak doğduğum diyarda

Sensiz yeşeremem

Kapkaranlık dünyamı aydınlatan ışığımdın

Sensiz önümü göremem

Gül''ün Bülbüle küstüğü gibi

Seni görmeden ölemem

                                                           07/02/2006', 'Ben Sensiz Ölürüm Hesabını Tanrı''ya veremem Bir umut olarak doğduğum diyarda Sensiz yeşeremem Kapkaranlık dünyamı aydınlatan ışığımdın Sensi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Üçyıldız']::text[], 8.5, '{"poet":"Ahmet Üçyıldız","poet_slug":"ahmet-ucyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-gormeden-olemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acırım O Yıllara', 'acirim-o-yillara-cafer-tayyar-ozkan-ke64v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni anlamak ne mümkün,

Aşkın ne vakit acı gerçekleri haykırsa

Suskun kalır, 

Kadınlığını hatırlarsın.

Ardından ihanet rüzgarları estirirsin gecende,

Kutsal emanetim bedenin, kaderinle izdivaçta,

Yalnızlığın pençesine atıldığın anlardaysa

Mantığın nefse mağlup, can özünse revaçta…

Sana inanmak ne mümkün,

Kadınlık sıranı savıp arzuyla aşk teri döker

Mektup yazar,

Ezildiğimi bildirirsin.

Yaz gününde zemheriye keser kutsal duygular,

Bilmem ki o zaman yüreğin hangi boş savaşta,

Ben kıskançlığın kol gezdiği hain zamanlarda

Umutla ağlarken, hercai sevgilimse koklaşta…

Sana kavuşmak ne mümkün,

Aşkın hasretini çekmiyor artık ışılgözlerin

Dönüşüm yok,

Bir daha gelme diyen sensin.

Çabuk unutulmuş, sevgi adına atılan adımlarım,

Çok yazık kara gözlerimden vuslata akan yaşlara,

“Sen benim, benim erimsin” diyerek sarılışların

Koskoca bir yalanmış meğer, acırım o yıllara…

Seni unutmak ne mümkün,

Silinmez hafızamdan vuslata, murada dair sözlerin

Ölüm olur,

Sevdan biterse deyişlerin.

Dudakların sevgi sözcüklerini mırıldanacak elbet,

Lakin senden çok daha vefalı çıkacak tatlı anılar,

Her şeyinle sevdana teslime koştuğun anları

Gün gelip acıyla haykıracak, fakir dediğin duvarlar…

Sana yaslanmak ne mümkün,

Hiç kurtulmadı ruhum senin ihanet darağacından

Zehir olsa,

Ellerinden içebilirdim.

Oysa şimdi, reva gördüğün acı hicran şerbetini,

Canparçam diye sineme vurup hüzünle içiyorum,

Mahşere bırakıyorum ben bu sevdanın kalanını

Hesaplaşma sonra  deyip, sessizce cana gidiyorum

Senle uzlaşmak ne mümkün,

Ruhunu mutlu kılan sevgi nuru koydum kalbine

Aşkla içtin,

Cana can katan sevgimden.

Seneler geçti sense vefasızlıktan vazgeçmedin,

Ardımdan sakın boşuna ağlama ölümsüz varlığa,

Sen beni hiçbir zaman gerçekte sevemedin,

Sahibinle her gece diri diri gömdün kara toprağa

Senle anlaşmak ne mümkün,

Kul hakkını yerken hüzün şerbeti içeceğini

Çok işittin,

Sevgi akan dillerimden.

Er geç geleceksin mecburen helalliğe kapıma,

Gün gelecek çok ağır basacak çobansı sevdam,

Gönül fırtınasından kaçıp da sığınırsan affıma

Belki o zaman biter, arzuladığın kaderinle kavgam…

Sana sarılmak ne mümkün,

Kaderin koynundayken sevdamla neleri yaşadın

Nasıl kıydın,

Umut serdiğim sevdama.

Meğer boşunaymış uğruna tuttuğum aşk oruçlarım,

Gayri mutsuzluk senin kanın, ahımsa rehberin.

Kadınım olsan da demek ki buymuş yaşayacaklarım,

Söyle ey canan, kadınlık tacında mı namus değerin? ...

02 Eylül 2004 Ankara

(Sevginin büyüklüğü, yaşatılan küçük ayrıntılarla tartılır.)', 'Seni anlamak ne mümkün, Aşkın ne vakit acı gerçekleri haykırsa Suskun kalır,  Kadınlığını hatırlarsın. Ardından ihanet rüzgarları estirirsin...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/acirim-o-yillara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çam İğnesi Değilim Ama,Aşk Bu Ya....', 'cam-i-gnesi-degilim-ama-ask-bu-ya-pinar-koc-19lbb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yaprak dökümüyle başladı her şey 

Ki

Soğuk bir sonbahar sabahı

Düştüm dalından……..

Savruldum,

Sormadan kendime bile

Nereye gittiğimi……..

İstemedin beni,

Gitmek zorundaydım kanatlarından……..

Sonbahar gelmişti 

Ve

Bir güz dökümü,

Bir yaprak düşümü………

Her rüzgarda savruluşum

Biraz daha acıttı

Biraz daha kanattı 

Yaralı olan yüreğimi……

Sordum sonra hayat ağacıma,

Ne olur,

Bir kış,

Bir bahar daha…….

Sende doğup,

Sende filizlenip,

Sende büyüdüm…….

Ne olur,

Üç mevsim var

Bir sonraki son bahara……

      Döndüm şimdi.

Kışta da buradayım,

Baharda da……

Ve 

Üç mevsim daha…….

Ve bu dalda

Hayal kurup,

Kurumak var ya…….

Çam iğnesi değilim ama

Aşk bu ya……………..

                                                             08.02.06', 'Bir yaprak dökümüyle başladı her şey  Ki Soğuk bir sonbahar sabahı Düştüm dalından…….. Savruldum, Sormadan kendime bile Nereye gittiğimi…….....', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/cam-ignesi-degilim-ama-ask-bu-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Hayata Susmak **', 'hayata-susmak-sakine-aydin-sdi5f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben Susardım.....

Ben Susunca Sende Susardın.....

Susardık Hayata.....

Bazen İsyanlarımız  Olurdu....

Kavgalarımız....Ama Yenikti Bahtımız.....

Ben Susardım.....

Ben Susunca Sende Susardın.....

Unutamam Gözlerindeki Masumiyeti....

Sustuğunda Gözlerindeki İfadeyi....

Bir Ben Bilirim....

Hayata Her Şeye Rağmen Susmayı....

Ben Susardım.....

Ben Susunca Sende Susardın.....

Kavgalarımız İsyanlarımız Beraber....

Ama Yinede....

Gözlerimizi Yere Eğer....

Başımızı Dik Tutardık....

Haksızlıklara.......

Acılara......

Yokluğa......

Varlığa.......

Derde Sevince......

İhanetlere.....

Ne Güzeldi Seninle....

Hayata Susmak....

Kimse Bilmezdi Neden Sustuğumuzu.....

Es Geçerdik  Tuhaf Bakan Gözlere....

Asiydik....Yokluk Vardı Ama Bizden Güçlüsü Yoktu....

Biz Beraberken Güçlüydük....

Şimdi....

İçimde Bir Yer Yarım.....

Şimdi......

Varsında Yoksun......

Şimdi......

Susuyorum.......

23.01.2004

Murat’ıma......', 'Ben Susardım..... Ben Susunca Sende Susardın..... Susardık Hayata..... Bazen İsyanlarımız  Olurdu.... Kavgalarımız....Ama Yenikti Bahtımız.....', ARRAY['Türk Edebiyatı','Şiir','Sakine Aydın']::text[], 8.5, '{"poet":"Sakine Aydın","poet_slug":"sakine-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/hayata-susmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karınca Ka(ra) rınca Özür', 'karinca-ka-ra-rinca-ozur-tulay-sustam-4zsl6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'senin göğünde

uçurtmamı uçursam

ve 

her zamankinden daha kısa

tutsam ipimi

bulutları geçmeyeceğime

söz versem 

beni affeder misin?', 'senin göğünde uçurtmamı uçursam ve  her zamankinden daha kısa tutsam ipimi bulutları geçmeyeceğime söz versem  beni affeder misin?...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karinca-ka-ra-rinca-ozur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanoğlu', 'i-nsanoglu-baris-polat-nnphf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Pirim pir sultan gibi assalar dara

Alçalma,düşme sende onlar gibi

Allahın aslanı,Aliyle zülfükara

Kalpten bağlan,Hacıbektaş,Mevlana gibi

Hayattan gördüysen kötülük çile,

Yüce Allahtan bir rahmet dile

Allahtan korkmayıp şeytan ile,

Bir olup gitme sakın onlar gibi

Sayılı günlerin iyilik dile,

Düşme kötüye sen bile bile

Hayata katma kin ile hile,

Zay olup gitme sakın onlar gibi

Şair Barış derki onlara

Her şeyi hayra yoranlara

Elini kalbine koyanlara,

Selam olsun kulluğa uyanlara.', 'Pirim pir sultan gibi assalar dara Alçalma,düşme sende onlar gibi Allahın aslanı,Aliyle zülfükara Kalpten bağlan,Hacıbektaş,Mevlana gibi Hay...', ARRAY['Türk Edebiyatı','Şiir','Barış Polat']::text[], 8.5, '{"poet":"Barış Polat","poet_slug":"baris-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/insanoglu-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-huseyin-sigirtmac-xs1bt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünya kaynar kazan pişer her yeri.

Özgürlük adına yürü ha yürü.

Nifak düştü kimse gitmez ileri.

Tohum saçtık ekin biçemedik biz.

Hile sardı doğru gitmez işimiz.

Ayaklar yan basar bozuk başımız.

Ah vah edip boşa döktük yaşımız.

Kapandı yol çığır açamadık biz.

Hazıra alışıp olduk tüketen.

Tembellik düşürüp bizi çökerten.

Ateş özümüzde yanarız kökten.

İnsanlığa ışık saçamadık biz.

Hurafe, efsane sardı dört yanı.

Hayal kurup sahiplendik cihanı.

Avrupalı ettik sözde insanı.

Açlık sınırını geçemedik biz.

Deve edip mahmuzladık pireyi.

Sistem, düzen deyip kaptık sırayı.

İnsanlıktan öne aldık parayı.

Suç tebelleş oldu kaçamadık biz.

Demokrasi deyip çaldık kılıcı.

Ha bu gün ha yarın bitmedi acı.

Baş tacı edildi hırsız, yalancı.

Doğruyu yanlışı seçemedik biz.

Özgürlük adına verdik ateşi.

Balçıkla sıvadık ayı, güneşi.

Haklının bulunmaz tarafı, eşi.

Sunduğu şerbeti içemedik biz.

Sığırtmaç vatana, bayrağa kurban.

Global dünyada edildik harman.

İtlaf kararı var kesildi ferman.

Kuş gribi sardı uçamadık biz.', 'Dünya kaynar kazan pişer her yeri. Özgürlük adına yürü ha yürü. Nifak düştü kimse gitmez ileri. Tohum saçtık ekin biçemedik biz. Hile sardı ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/biz-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğin Dehlizlerinde/Düz yazı', 'yuregin-dehlizlerinde-duz-yazi-serap-demirturk-qxgcu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu sonsuz karanlığı ben gibi kim hissedebilir ki? Boy boy salınan umut tohumları nasıl ta dibinden koparılır, kim anlar ki? Yeminlerle başlayan sevdaların kökünü kim kazıyabilir ki? Yok, bin kez daha söylüyorum ki yok. Güven denen limanda demirlemek yok. Savrulup gitmeli.Varsın kimse bulmasın yüreğini. Varsın o kara gözlerin için türküler yakılmasın...

Bomboş, bomboş her yer:sessiz. Sessiz bir çığlık atılıyor yüreğin dehlizlerinde.Yıllara inat hala sevgisiz, ağaran saçlara inat hala buruk ve altı morarmış gözlerde gülemeyen mimikler. Sevgi mi? Güldürme hayat.Sevgiyi alıp astım bir elek gibi duvara. Fırat’ın sularını taşıdım o elekle şu vahaya da...Toprak doymadı suya.Çatlayan toprak mıydı, kuruyan yürek miydi, bilemedim. Bildiğim, sevgi adına atılan adımlar, çelme oldu can.İlikler titredi sevgisizlikten.

Kimsin sen ey ses? Sen...hangi yüreğin ağıdısın? Sus! Sus ey dilsiz umut! Sus da bileyim kim ne der. Sus ki uçurumun başında biten kır çiçeğinin ağıdını duyayım...

Evren, yüreğin kıvrımlarındaki açlığı görmez mi? Duymaz mı ''Can... can! '' diye haykıran, şu kanayan yarayı? Sağırlık...Hışırdayan yaprağın ağıdı mıydı şu ıssızlıkta duyulan? Git! Git ta öteye yeniden dinle.Ağlayan kim, gülen kim? Ağlattığını bilmeden gülen kim? Nedir ki oysa ağlamak? 

Yüreğin içine dökülen gözyaşlarında boğulup gittin ey yar...Yar olmaktan kurtuldun, eridin.Belki de köz oldun.Ver saçlarını şimdi rüzgara.Çık şu dağın yamacına, haykır ''Kurtuldum.'' diye. Mümkün mü, kurtulabilir misin? Sen varsın içinde dev gibi: sen! O gitse, şu gitse...Sen kalırsın içinde, sen! Başından sonuna dek adım adım takip eder yüreğini her soluk alıp verişinde.Bırakıp gitse de ölümsüz sandığın sevdalar seni, al kana bulanmış yüreğinle sen, kendine iyi bak. Bil ki gitse de yüreğim dediğin, göndersen de kıvrılan yollarından hayatın, ürkek ve korkak bakışlarıyla yeni doğan bir bebek gibi...Sen hep içinde var olacaksın. Gidenlerin ardından ağlayarak yeniden doğacaksın ve bileceksin ki her tükeniş, bir doğumdur. Gidişlerin çığlığındadır, gelişlerin hoşluğu.

Bu hengamede, zifiri karanlıkta sakın çığlığın ardını arama! Bir cana hasret, bir soluğa hasret bak gökteki yıldız; sana göz kırpar, gördün mü? Budur hayat.Kıvrılmışken dört büklüm, elinde al kanlar içinde yüreğin...Başını kaldırırken bak, şu gülümseyen yüzün dudaklarındaki kıvrımlarında saklıdır hayatın gizi...

8.2.2006', 'Şu sonsuz karanlığı ben gibi kim hissedebilir ki? Boy boy salınan umut tohumları nasıl ta dibinden koparılır, kim anlar ki? Yeminlerle başla...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yuregin-dehlizlerinde-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '- Duyguların ölümleri..-', 'duygularin-olumleri-oner-kaciran-v1hbd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Erken açan çiçekler gibi

açar tomurcuğunda aşklar

Düşer tutmamış bedenlerden 

damla damla

Bir trenin ağır ağır gelişi gibi

görürsün

İstasyon sensen eğer

alır duygularından

tutkularından yükünü, zamanla

Sır olmaktan çıkar

iki kişinin bildiği şey

Aşk asla sır olmaz ki

Açığa çıkar duygular

kalkar ortadan giz

Kalan son vagonu da

alıp yükünü

sevginden ve yaşamından

Uzaklaşır ağır ağır

hiçbirşey olmamış gibi

hayatından

Eskisindir artık

......Eskitilmiş

..........Eksiltilmiş

Ölülerin duyguları olmaz

Ya duyguların ölümleri 

Ve sen

…anlarsın

…….öğrenirsin

seve seve 

vazgeçmeyi

Sahi

ölümsüz aşk

var mı....

12.01.2006 Dionisos

Biter elbet 

.......bu firari duygular', 'Erken açan çiçekler gibi açar tomurcuğunda aşklar Düşer tutmamış bedenlerden  damla damla Bir trenin ağır ağır gelişi gibi görürsün İstasyon...', ARRAY['Türk Edebiyatı','Şiir','Öner Kaçıran']::text[], 8.5, '{"poet":"Öner Kaçıran","poet_slug":"oner-kaciran","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/duygularin-olumleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne farkeder', 'ne-farkeder-baris-polat-qu4is', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yedisinde doğmuşum

Ne farkeder

Ha yedisi ha yetmişi

Öylede çekiyoruz böylede

Ha yirmi altısındayım

Ha elli altısında

Sürünüyorsak ne önemi var.

Tadı yoksa baharın

Vakti yoksa zamanın

Satarım dünyayı,

Her şey bir tutam

Mutluluk için değilmi

Ha öyle ha böyle

Akıl almaz olur

Yaş bitmez olur

Deli gibi savruluruz bir yere

Ha öylesine ha böylesine', 'Yedisinde doğmuşum Ne farkeder Ha yedisi ha yetmişi Öylede çekiyoruz böylede Ha yirmi altısındayım Ha elli altısında Sürünüyorsak ne önemi v...', ARRAY['Türk Edebiyatı','Şiir','Barış Polat']::text[], 8.5, '{"poet":"Barış Polat","poet_slug":"baris-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-farkeder-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla', 'leyla-zeynal-yaman-uo16c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey perişan gönlümün iştiyakı Leyla! 

Sen benim ana sütü kadar helalimsin

Ey elif boylu, hilal kaşlı,gözi ela

Sen benim gözlerimden akan melalimsin!', 'Ey perişan gönlümün iştiyakı Leyla!  Sen benim ana sütü kadar helalimsin Ey elif boylu, hilal kaşlı,gözi ela Sen benim gözlerimden akan mela...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/leyla-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdası Kâlbimi Yaktı Kavurdu', 'sevdasi-k-lbimi-yakti-kavurdu-yusuf-onder-bahceci-f64w4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdası kâlbimi yaktı kavurdu,

Bir sigara gibi çekti savurdu,

Bana böyle si darbeyi vurdu,

Sevdası kâlbimi yaktı kavurdu.

Gözlerimden anlamadı sevgiyi,

Gözlerinde bildim bana vergiyi,

Ona göstermiştim sade sevgiyi,

Sevdası kalbimi yaktı kavurdu.

Yananları Allah''ım görüyor ama,

Bu sözlerim ele değil ki sana,

Sevda da demişim ben dama,

Sevdası kalbimi yaktı kavurdu.

Sevdası kâlbimi yaktı kavurdu,

San ki sapı samandan ayırdı,

Dönüp te bir de kaderi kayırdı,

Sevdası kâlbimi yaktı kavurdu...', 'Sevdası kâlbimi yaktı kavurdu, Bir sigara gibi çekti savurdu, Bana böyle si darbeyi vurdu, Sevdası kâlbimi yaktı kavurdu. Gözlerimden anlama...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdasi-kalbimi-yakti-kavurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utangaç', 'utangac-kenan-taskin-ncrs7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mavi bir İstanbul rüyasıydı önümüzden geçen

Hani elimizi uzatsak tutacağız sabahı

Öyle utanıp durma karşımda

Tökezlemeden iç şu şarabı', 'Mavi bir İstanbul rüyasıydı önümüzden geçen Hani elimizi uzatsak tutacağız sabahı Öyle utanıp durma karşımda Tökezlemeden iç şu şarabı...', ARRAY['Türk Edebiyatı','Şiir','Kenan Taşkın']::text[], 8.5, '{"poet":"Kenan Taşkın","poet_slug":"kenan-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/utangac-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorarız Zamanı', 'yorariz-zamani-zeynal-yaman-eigx1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu aşk maratonunda yorarız zamanı

Asırlara sığmaz bu sevda bu iştiyak

Enginlerde gezenin engindir limanı

Zamandan zamana akarız çağlayarak', 'Bu aşk maratonunda yorarız zamanı Asırlara sığmaz bu sevda bu iştiyak Enginlerde gezenin engindir limanı Zamandan zamana akarız çağlayarak...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yorariz-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-fatih-kuyucu-2pxii', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bilmece çöz çözebilirsen

İçi dışı farklı gir girebilirsen

Mükafatı belli bul bulabilirsen

Değeri büyük tut tutabilirsen', 'Bir bilmece çöz çözebilirsen İçi dışı farklı gir girebilirsen Mükafatı belli bul bulabilirsen Değeri büyük tut tutabilirsen...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kuyucu']::text[], 8.5, '{"poet":"Fatih Kuyucu","poet_slug":"fatih-kuyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bilmece-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Benim Neyime', 'sevmek-benim-neyime-said-demirel-1agv0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yarın bayram bugün arefe

Kına yaksınlar şerefe

Sensiz sevdamızın yıldönümü

Sevmek benim neyime

Affet deli gönlümün

Sarpa vurmasıdır bu

Kapanmış yarasının

Tekrar nüksetmesidir bu

Sen mecbur değilsin sevmeye

Benim sevdiğim kadar

Herkes Said olamaz

Ölümüne sevecek kadar

Ne hevesim, ne hedefim

Yetmedi ömre nefesim

Kalmadı artık mecalim

Sevmek benim neyime

Ankara - 07/01/2000', 'Yarın bayram bugün arefe Kına yaksınlar şerefe Sensiz sevdamızın yıldönümü Sevmek benim neyime Affet deli gönlümün Sarpa vurmasıdır bu Kapan...', ARRAY['Türk Edebiyatı','Şiir','Said Demirel']::text[], 8.5, '{"poet":"Said Demirel","poet_slug":"said-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevmek-benim-neyime-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlam Tortusu', 'anlam-tortusu-veysel-colak-5n9mk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşarken ne çok durdurdunuz hayatı. Karıştınız 

çiçeklerin solgunluğu olduğunuz daha çok. Varlığınız 

yeni doğan bebeklerin kocaman şaşkınlığı. 

Bir şakayla çelişmek iyi ve yalan olmak 

bir roman kahramanı kadar. Unutuldu 

durmadan sıkılmanın bir dil olduğu 

anlatılanların ufuk çizgisi, turaç sökünü... 

Kemirilmiş tenin sonsuz sıcaklığı da. 

Sizin saatiniz durduruldu. 

Oysa unutkanlıktı korktuğunuz kelime 

Dişlerinizi kırarcasına ısırdığınız gül 

kucağınızda çoğalıp duran anlam tortusu, 

bozuk cümlelerde yanlış ihtilâl 

bir kamanın çırılçıplak öfkesi, 

ölümün keskin tadı. 

Uzakta, bekleten umut; ağzımızdaki katran 

ve sonra ekonomi, hırsız, oynak ve tıkırında. 

Herkes bir yangın gibi kendine dönebilir aslında 

Kimi düşünseniz solmuştur kan kaybından 

Bunu bilenleriniz çatladı sevişmekten. 

Bir kırık eli anlatmak olanaksız bir başkasına 

Kimleri sevdiysem usulca ayrıldılar; bense 

kendimi bıraktım her gelişimde... Gurbetlerden 

siyah-beyaz İstanbul hatırası. 

Aklımızda bir akarsuyu sevindiren kum 

sonsuz değişim, bir filin bilgeliği 

dedirten coğrafya, boşluğumda çalkalanan bir deniz. 

Dize, Haziran 2001', 'Yaşarken ne çok durdurdunuz hayatı. Karıştınız  çiçeklerin solgunluğu olduğunuz daha çok. Varlığınız  yeni doğan bebeklerin kocaman şaşkınlı...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/anlam-tortusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Beni Seviyorsun', 'sende-beni-seviyorsun-sahabettin-mert-wg17i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazen bakakalıyorum.

Güzel gözlerine öylece.

Derinliklerine dalıyorum.

Girebilmek için kalbine.

Sonra bir şiir mırıldanıyorum.

Teması senli benli,

Sonra iç çekiyorum.

Yok bunun geleceği.

Çabuk geçiyor zaman,

Gönlüne inemeden.

Gözlerine bakarken.

Sonra anlıyorum.

Sende beni seviyorsun,

Ama ben rüyadayken…', 'Bazen bakakalıyorum. Güzel gözlerine öylece. Derinliklerine dalıyorum. Girebilmek için kalbine. Sonra bir şiir mırıldanıyorum. Teması senli ...', ARRAY['Türk Edebiyatı','Şiir','Şahabettin Mert']::text[], 8.5, '{"poet":"Şahabettin Mert","poet_slug":"sahabettin-mert","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sende-beni-seviyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara Yara İçinde', 'yara-yara-i-cinde-veysel-colak-vrqva', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak, bu beyaz karanfil senin akşamın olsun 

Hohlayıp onunla silersin kalbini 

Ne zaman yüzüne çalışsam gökyüzü oluyor 

Göğsün yaz içinde 

Dağlara bakmaya koşuyoruz birlikte 

Ama sen sıyırıp gidiyorsun içimi. 

Bir ırmaktan aktıkça yıkandığım 

Kılıç için dokunmuştun ipektin kesinlikle 

Bana kızdığında kuş seslerine yenilirdin 

Hızlandırırdın soluğumu 

Harlı gövdene alıştırırdın 

Tenin gelip de geceme vurunca 

Soyunur çoğalırdın 

İçimde, batığına aşık bir denizin kokusu. 

Bir bıçağın iki yüzü, huysuz dilin 

Nerede bir ayaklanma olsa iterdin kendini 

Dokunsan sönerdi ateş 

Sabahı uyurduk isteseydin eğer 

Bir okyanusla yarıştırırdın çıplaklığını 

Saçlarını topla ki boynunda alanlar açılsın. 

Alnım kanıyor, üstüme devriliyor uzaklık 

Alıp gidiyorsun işte geveze günlerini. 

Aşk değil bu, yara içinde yara! 

Kavram-Karmaşa, Eylül 2001', 'Bak, bu beyaz karanfil senin akşamın olsun  Hohlayıp onunla silersin kalbini  Ne zaman yüzüne çalışsam gökyüzü oluyor  Göğsün yaz içinde  Da...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yara-yara-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gri Müzik', 'gri-muzik-veysel-colak-b5aam', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duygularımdan oyulurdum ayrıla ayrıla. Bir yürek 

güreşinde öpe öpe döverdik birbirimizi. Ses olunca 

tutuşan, dili kesen kelime; delil olan gri müzik... 

Halkın habercisi alnın terliyor. Bu yüzden 

anılara çağrıldım, aşklara, korkulara. Sulara verildim, 

bölündüm bir kuşluk vakti. Herkes gelince 

anladım boşluğu; içecek olsaydım kırılırdı çeşmeler. 

Kimin yüzüne baktıysam karıştırdım kendimi: 

Teninde bir çıbanla değiştirildim. 

Bir ömür hiçliğe alışılmış ve orada unutkan odalar 

yaraları anlamsız kılan günbatımları, terli bir deniz. 

Esrarlı, tehlikeli, daha çok akıldışı beni dindiren 

sağanak. Akrebimi çağırın. Benim için çoğaltın pusuları 

artık aşka kefil değilim. Ve boşlukta bir sokak 

menekşesi acemi, çocukları sabırsız. Orada 

hangi tuzağı bozduysam kendimle karşılaştım. 

Gül vakti. Kızaran sular. Mevsimin üşüten çağıltısı. 

Kurşun yenildi gene de geyiğin yaşama sevincine 

ve bu tılsım, mermeri eriten anlam tortusu 

çözülsün diye öldürüldün derimle kanım arasında. 

Ama bir aşkın yangından doğuşuna katıldım, 

benim işim sizin için korkmak olsun. 

Yüreğimle bir söyleşiye çalıştım durdum. 

Varlık, Kasım 2001', 'Duygularımdan oyulurdum ayrıla ayrıla. Bir yürek  güreşinde öpe öpe döverdik birbirimizi. Ses olunca  tutuşan, dili kesen kelime; delil olan...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gri-muzik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İnsanın Asılırken Tekmelediği Boşluk', 'bir-i-nsanin-asilirken-tekmeledigi-bosluk-veysel-colak-9c3p9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçersiz bir yolculuk seninki 

dönüp arkana bakıyorsun. 

Kıyıların çoğalıyor ama darsın kendine 

bir imgenin borcusun 

avucunda bir kan damlası. 

Anlat bunu bir insanın hiç yaşamadığına. 

kırgınlıklarını gezmelere götür; 

boynu kesik ince tarih 

uyumsuz bir anı gibi durur ölüme karşı. 

Sen kocaman bir aşk saklarsın ağzında 

sana benzesin diye yontarım kalbimi 

beni bağışlama, uzaklara bırak 

geri al sonsuzluğunu 

bazen boğucudur buluşmaların koyu denizi. 

Koyuhüzün bir sabah som sıkıntıda 

fırtınanı dinlendir ve anlat bunları 

Bir çocuğun ansızın yalnız kalmasına. 

Dolgun bir su sesi olsun 

sürekli ve sarmaşık bir umut. 

kal orda; gelip çarpacaksın yoksa 

çoğul bir arkadaşlığın kül olmasına. 

Aramızda bir insanın asılırken tekmelediği boşluk 

sıyrık kelimeler, yanık yüzün 

ve bir daha hiç konuşamama korkusu. 

Edebiyat ve Eleştiri, Kasım-Aralık 2001', 'Geçersiz bir yolculuk seninki  dönüp arkana bakıyorsun.  Kıyıların çoğalıyor ama darsın kendine  bir imgenin borcusun  avucunda bir kan daml...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-insanin-asilirken-tekmeledigi-bosluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlıyorsun Sana Kıyamam', 'anliyorsun-sana-kiyamam-yusuf-onder-bahceci-p65wp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstersem seni gözlerimle yakardım,

İstersem seni sözlerimle yıkardım,

İstersem  sana binler dua ederdim,

Ama istesem de sana kıyamam.

Gel de sözlerimi sen yabana atma,

Ben seni seviyorum kafana takma,

Kırmızı ışıkta dururken beni atlatma,

Çünkü istesem de sana kıyamam.

Sarı yanarken çok bekledim geçti,

Kırmızı yanacak sandım yeşili seçti,

Yeşil lamba yanınca çok hızlı geçti,

Anlıyorsun her hâl sana kıyamam.

İstersem bende sarı da geçerdim,

Kırmızıyı dinlemez basar giderdim,

Senin cânını böyle sıkar giderdim,

Anlıyorsun her hâl sana kıyamam....', 'İstersem seni gözlerimle yakardım, İstersem seni sözlerimle yıkardım, İstersem  sana binler dua ederdim, Ama istesem de sana kıyamam. Gel de...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anliyorsun-sana-kiyamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsandan Bir Uçurum', 'i-nsandan-bir-ucurum-veysel-colak-20szm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir deniz bekliyorduk. Duvara çarpıp ölmesi gibi 

özgürlüğüne uçan bir kuşun. Anlamın 

düğüm olduğu zamanlar. Bütün yaraları 

denedim. Ağzımda kan tadı. Saklanacak 

o su kıyısı uzakta. Dağıldım 

yaşlandığım yol için. Hangi çağa gittiysem 

gülünçtü tarih baktıkça insanlara. 

Acının yurdu aşklar, yağmurun kırdığı 

görüntü, cinayetlerin karaladığı atlas. 

Gelmeyişindi aslında beklediğim 

derimin altındasın işte, 

içindeki tuzaklar ezberimde 

karnında büyüttüğün acı 

çığlıktan daha ağır ama yankısız. 

Kırıktı işaret, harfler uçucu 

Dünyanın gördüğü kapkara düş 

içimizde oluşan girdap 

katranla naylon arasında pıhtılaşan insan 

silinen bir bakıma 

gövdesi kadar bir boşluk daha doğrusu. 

Her kum tanesinin sakladığı çölde 

korkaklığımın tek nedenisin sen. 

Unutmadım, herkese bir akarsu borçluyum. 

E, Kasım 2001', 'Bir deniz bekliyorduk. Duvara çarpıp ölmesi gibi  özgürlüğüne uçan bir kuşun. Anlamın  düğüm olduğu zamanlar. Bütün yaraları  denedim. Ağzım...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/insandan-bir-ucurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sapı Kırık Çiçek', 'sapi-kirik-cicek-veysel-colak-erpld', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Asitle parlatıyoruz hayatı, ölümün hızıyla 

Yaralarımıza çakılan buzla besleniyoruz 

Nerede yenilirsek orada şımarık bir ayrılık 

Kalbimiz, artık durmalı aşkların dargın yüzünde 

Kar gelecek, kimse kimseyi beklemesin, yollar kırgın 

Usulca gökyüzüne kapandı her pencere. 

Tırmanıp duruyoruz içimizdeki dağa 

Orada mahşerin ilk atlısı besleniyor kötülükten 

Gövdeden bir avuç kan düşer gibi toprağa. 

Üstüm açık, babam saatini durdurdu 

Kapı önlerinden toplayıp parçalarımı gittim 

Artık hiçbir şeyim yok kendime uzak olmaktan başka 

Ellerimde yalnızlığa bir gece, sapı kırık bir çiçek 

Yaralı bir kelime ve paslı bir giyotin bıçağı. 

Gözlerimi bağlayıp çıkıyorum sokağa 

Korkular bir yasa gibi düşüyor gırtlağıma 

Gülünden sıkılan diken artık uzakta 

Dolaştırıyorum yırtık yerlerimi 

İnsan yüzleri öylesine belirsiz ve ürkütücü 

Kime baksam kendine kaçak, gülüşüne yabancı 

Her sokağın ucunda iktidar ve intihar. 

Kar gelecek. Oturdum bir kediyle söyleştim 

Derindi ruhum, kenti oldukça öteledi 

Birimiz hep karanlıkta, kanın kıvraklığında 

Artık ateşle söndürün suyu 

Ses taşıyan kuşları da öldürün. 

Sürsün bu belirsizlik, azaltın birbirinizi 

Ölü geceler saklayın yatak odalarında 

Altımız gökyüzü, bitimsiz yalan 

İkimiz, iki cehennem, sonsuz cinayet, bir darağacı. 

E, Nisan 2000', 'Asitle parlatıyoruz hayatı, ölümün hızıyla  Yaralarımıza çakılan buzla besleniyoruz  Nerede yenilirsek orada şımarık bir ayrılık  Kalbimiz, ...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sapi-kirik-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmge', 'i-mge-veysel-colak-dhyxs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzaklıklar getiren yüzün anlam biriktiriyor 

orada yaşamak bir ayrıntı, orada parlayan boşluk. 

Neresinde duracağımı bilseydim Dünyanın 

ses olur düşerdim sabaha. Kendini savunan 

bir sözcük gibi hançerle yazılırdım. Aşkı aşkla 

ölümü ölümle, kalbimi ayrılıkla korkuturdum. 

Dökülür giderdim sokakların dışına. Sonra 

bir gölge oyununda ah! kırmadan, kırılmadan 

birkaç türkü söyleyebilseydik, incelirdik birbirimize. 

Herkesin bir yarası var özenle koruduğu, 

iyileşecek diye korkarak bakıyorlar onun derinliğine 

bir tarih dersi diye kazıyorlar acıyı. 

Gövdelerimiz kargaşa içinde. Birimiz ötekinin koynunda 

korkutan bir ikona; kıyısız suların en aşk olanı 

dikeni sevmenin gözlerimize batırdığı gül 

her günde bir bozgunun öyküsü, her günde 

etin çıkarttığı gürültü. 

Yalnızlıktır her şehir bir insana. Geceyi 

boyuyor kan. Bir çığlık eşliğinde anılan 

parçalanıp alanlara dapılan imge. Ve bir kılıç 

kendini biçecek. Bu bilinmedi, bilinmesin. 

Ve bir çocuk, alnı uçurum içinde. 

Jilet tadında uzun geceler, zehrin özlediği zehir 

duvarsız bir hücrede durduran yerçekimi. 

E Dergisi Nisan 2000', 'Uzaklıklar getiren yüzün anlam biriktiriyor  orada yaşamak bir ayrıntı, orada parlayan boşluk.  Neresinde duracağımı bilseydim Dünyanın  ses...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/imge-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimiz Yer Değiştirirken', 'i-cimiz-yer-degistirirken-veysel-colak-2n1vy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her akşam gelişen bir ayrılık buluyorum odamda 

duvarlara gizleniyor, ruj lekelerine 

müzik sesine ve kocaman boşlukta bir kadının 

yalın yüzüne. Onun aklı bir şelalede 

hep bir martıyla birlikte 

üstelik güz düşkünü. Kanı küstürmek telaşından 

içimiz yer değiştirmişti çoğu kez 

ne kadar dürüsttü ikimizin de elleri titrerken. 

Şimdi ince bir anıya yaslayıp başımı 

sökülüyorum senden. Ağzımla beslediğim aşk 

artık bir uzaklığın yakın ucunda. 

Yüzünden akıp duran irkiliş bana ne kadar kül 

ne kadar yangın... 

Bir yalnızlıktan yontuluyordun sen 

bir taşa sarılıp fırlatıldın derinliğine, 

senin arandığın bir yemindi daha çok 

belki de bir filin ölüm ülkesi 

bezgin bir suçortağı bu çapulcu dünyada. 

İşte darıltan bir şafaktasın ağzındaki güneşle 

acı acıya damlıyordur, yürek yüreğe; elveda 

elvedalara. Yara yaraya dökülüyordur 

kalbinin yarısı yaz, yarısı kış altında. 

Uygunsuzluğun tam sırası. Yüz yüze sevişmenin 

kocaman bir boşlukta. Vurulmuş arkadaşlar söylesin 

ölüm burcudur insan; yarısı cellat, yarısı kurban. 

Teni küstüren dans, özlenen delilik, yaratıcı mermer; 

iyileşsin diye bir geyiği düşlemek 

eşlik etsin geceye. İçimiz karanlık, yaz alıngan 

ve her buluşmayı kamaştıran dağılmış bir hayat. 

Varlık, Mart 2000', 'Her akşam gelişen bir ayrılık buluyorum odamda  duvarlara gizleniyor, ruj lekelerine  müzik sesine ve kocaman boşlukta bir kadının  yalın yü...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/icimiz-yer-degistirirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat güzeldir', 'hayat-guzeldir-kemal-eyupoglu-8sntr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boşver başkalarının dediklerine

Hayat güzeldir her şeye rağmen

Aşk güzeldir, sevmek güzeldir

Can çekişirken bile

Hayat güzeldir.

Gözlerde gördüğün mutluluğu

Doldurabilsen de gönlüne

Dolduramasan da

Hayat güzeldir

Ağlasan da 

Ağlatsan da başkalarını

Hayat güzeldir.

Minicik yüreğinde yaşatsan da 

Yaşayamadıklarını

Esiri olsan da korkularının

Ve mahkum olsan da 

Bir delinin göğüs kafesinin içinde

Hayat güzeldir.

Hayat güzeldir

Kısacık gibi görünse de güzeldir

Bak, hala yaşıyor Leyla

Hala hayatta Şirin

Ve sesi geliyor Aslı’nın

Kimseler yok olmadı alemde

Hayat devam ediyor

Senle benle, sensiz bensiz

Kim ne derse desin boşver

Hayat güzeldir.', 'Boşver başkalarının dediklerine Hayat güzeldir her şeye rağmen Aşk güzeldir, sevmek güzeldir Can çekişirken bile Hayat güzeldir. Gözlerde gö...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hayat-guzeldir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Resimaltı', 'hayata-resimalti-veysel-colak-b6mfe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Renkli bir suyun taşmasını bekliyorsun ha, 

böyle durmaktan. Bu ipekten bir yalan 

hem de büyüden. Bir çocuğa göz değilsin 

onların parmak izi korkular. 

Yüzündeki gülücükle bir başınasın, simit ve çaya uzak 

Öfkeli zaman. Tartaklanmış bir uzaklıktasın 

tuzun tadında kötü geceler. Beklemelerin 

sedef çiçeği artık naylondan. 

Hızla unutuyorum ben de, örtüyorum anımsadıklarımı 

ve yaşanmış ne varsa. Kararıyor içim; ürkütüyor bu. 

Yani, o susamışlık: Elbette öğretici, elbette taşkın 

ama her şey, darmadağın bir anlam. İşe yorgun işçiler 

ekmek saldırgan. Utançla genişliyor kent 

soluyor bir fotoğraf. Daralıyor alanlar 

büyüyen kalçalara. Devrilen yüzüm, 

binlerce yalnızlık arasında. Beklediğim sudan 

daha dalgın daha alıngan. 

Sofada unutulan çocuk her oyundan atılan 

babası kadar yorgun, bir fabrika kadar gürültülü, 

kin kadar sessiz, ama hüznü usulca. 

Aşklara resimaltı bir söz: Çiçeğin, 

kopartılan sapına bakması gibi, bir yanı yufka 

bir yanı yedi iklim dört köşe. Artık tutuşmayan 

bir pankarta inanma. Bir şarkıya yakalan. 

Ben de senin gibi aranırken kayboldum 

gövdemin her yerinde bir fazlalık 

ve atlastan bir sancı o günden sonra. 

Bak işte göğsünüzdeyim serinlik oldurmaya 

ağrıdan bir yakınlık bu 

durmadan yalçınlaşan aramıza yağan kar 

ah! uçurumdan sevgili, buzdan gece. 

Ter sorsun bunu, kandan yontulan bulsun 

mermer gecikecek gene ellerin bilenmiş alışkanlığına. 

Günlerimize sarmaşık gönderen arkadaşlar 

kopkoyu birkaç imge, uzakta. 

Masmavi bir karanfıl, unumuza su olan. 

Dize, Şubat 2000', 'Renkli bir suyun taşmasını bekliyorsun ha,  böyle durmaktan. Bu ipekten bir yalan  hem de büyüden. Bir çocuğa göz değilsin  onların parmak i...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/hayata-resimalti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirsizlik, Zaman Denilen Pusu', 'belirsizlik-zaman-denilen-pusu-veysel-colak-7tj4k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ömrümü toplasam elde var bir kaç anı. Ah! 

İnsanlar gökyüzünü sevmiyor. Bu yüzden 

kayboluyor herbiri, topluca ölüyorlar. 

-Bunu ben aptal bir dünyadır bileyim! 

Her şeyi başlatan sağanak içinizde 

sevgiliden tuz tadı. Ben bunu da 

konuşanı kalmamış bir dil diye/bileyim. 

Vurun uykuyu, gece büyüsün 

ve bu masal hızla silinsin günden. 

Kuşku dursun, 

şimdi çoğu kez sancıdır gizlenen bize. 

Oyle işte her hançer kendine bükülür 

git artık ve bu aşkı ihbar et 

kaçıp gidecek kalbim olmasın 

pusulaları kırın, silin haritaları. 

-Ama ben bunu bilmeyeyim. 

Yırtılın, çekilin bütün kelimelerden 

bekliyorum sizi her büyük çalkantıda 

boynunuzda harflerden bir gerdanlık 

güvercinlere serpilen gözleriniz 

yaşamak bir hüznün koyağında sürçerek... 

Şaşırırım boyuna 

tanrı da yanılır bir çocuk düşünürken 

dil çürür, dudak düşer, kan yenilir 

bir deniz gibi birikir sabah, 

insandan esen rüzgar tarih burcudur 

taşa dönüşmüş zaman. 

-Ben bunu da öldüren ecza diye/bileyim. 

Bıkmadım beklemekten. Yoruldum belki 

sarıldığım kin artık bittiyse 

öfkeyle çözün beni. Dağılın, merak olun 

sizden sonra gelenler olacak, 

onlar toplasın parçalarınızı. Ben bunu da 

şimdilerde yasak anlam bileyim. 

Dize, Ekim 2000', 'Ömrümü toplasam elde var bir kaç anı. Ah!  İnsanlar gökyüzünü sevmiyor. Bu yüzden  kayboluyor herbiri, topluca ölüyorlar.  -Bunu ben aptal b...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/belirsizlik-zaman-denilen-pusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğu Kokla...', 'mutlulugu-kokla-i-brahim-ethem-bingul-3tco1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kıvranırım sensizliğin sabırsızlığında

Saniyeler bile acı vermekte bana

Benziyorum sarı güz yapraklarına

Savrulurken özleminin rüzgârlarında...

Saadetimse gözlerine kavuşma

Hapsedilmiş onlar ulaşılmaz bir zamana

Dersin zamanın ne önemi var aşkta

Vuslat var ya delikanlım sonunda...

Yüklesem hasretimi bulutlara

Yağsam bensiz yaşadığın o topraklara

Sevdamla bin gül ve bin renge kavuşunca

Her bir gülde sen mutluluğu kokla...

www.iebingul.com', 'Kıvranırım sensizliğin sabırsızlığında Saniyeler bile acı vermekte bana Benziyorum sarı güz yapraklarına Savrulurken özleminin rüzgârlarında...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mutlulugu-kokla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölen ve Öldüren Hücre', 'olen-ve-olduren-hucre-veysel-colak-men51', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceden bir pencere, yılanlı duvar 

muslukta kan sesi. İçimizde 

ıssız ve ısıran uykular 

Damla damla birikiyor ölüm 

bir dilin yıkılışı gibi 

dünyadan çıkıp gidiyor kuşlar. 

Bir papatyanın unutuluşu 

güneşe kapanıyor kapılar. 

Sonra boğucu merak. Orada özlem 

gelişen bir uzaklıkta tükenen deniz. 

Öldürüyor düşlenen sevgililer. 

Ağrı''nın ve ağrıyan yanlarımızın keskin öfkesi 

köpürten özgürlük, çocukların ayçiçeği yüzü 

uğruna ölünecek kadar sevilen hayat. 

Paslı bir bıçakla tene çizilen yasa 

bir kobranın kocaman ağzı 

ölen ve öldüren hücre. 

Çıplak bir mermere damlayan gökyüzü 

aşkların masal kılıcı betona gömülen tarih. 

Dize, Aralık 2000', 'Geceden bir pencere, yılanlı duvar  muslukta kan sesi. İçimizde  ıssız ve ısıran uykular  Damla damla birikiyor ölüm  bir dilin yıkılışı gib...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olen-ve-olduren-hucre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokul Yanıma Sokul', 'sokul-yanima-sokul-murat-demir-mj5vq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdan sevdama okul

Kapısında bir ben kul

Ne zaman diyeceksin

Sokul yanıma sokul

Beklerim bekle dersen

Bir benim bende bir sen

Beklemekte nedir ki

Gıkım çıkmaz öldürsen

Sen dert veren ben alan

Olsam ne olur talan

İçimde sen olmazsan

Zaten yalanım yalan

Yazım yazılmış kara

Sensiz etmem on para

İşte beni bu dertler

Getirdi buralara

Ellere doğan güneş

Karanlığın bana eş

Benden gayri herkese

Beleş olmuşsun beleş', 'Sevdan sevdama okul Kapısında bir ben kul Ne zaman diyeceksin Sokul yanıma sokul Beklerim bekle dersen Bir benim bende bir sen Beklemekte ne...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sokul-yanima-sokul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etinizdeki Acı', 'etinizdeki-aci-veysel-colak-9o8yc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangi an''a dokunsam, avuçlarımda 

sesinin yeşeren içi. Su unutur belki 

sildiğin kelimeler kadardır anlam 

konuş ki bölüneyim, yarıl ki 

anlatabil kendini. 

Kaosu başlat, 

özenip durma taşın yalnızlığına, hadi 

aramıza iki uçlu bir mızrak koyalım 

boğucu bir yakınlık olsun akşam 

aşklara öğret bunu; su, terlediği için sudur. 

Ve ölmekten yorulan dünya 

biriktirdiğin yüzlerle bir korku odasısın 

birazdan Amerika, birazdan Afganistan 

göle düşen ut sesi 

herkesin boynunda ipten bir yasa. 

Öpüşülen kızların kardan yüzü uzakta 

kusturuldu küçücük çocukların içindeki gökyüzü 

düşeceklerini bile bile sarkıp durdular karanlığa 

kördünüz birbirinize 

sağırdınız ormanların sesine. 

Oysa kentler başka görünürdü dağlara bakınca 

göz incinirdi bu yolculukta. Deniz 

kaynadığı zaman, ilk işim kandırmaktı kalbimi 

ince hüzün, keskin yalnızlık ve sen 

bu geceyi deneme; suçun tarihini anla 

onun parmak izi korkudur sana. 

Her şey ölüdür zaten kandan yoğun değilse 

yankılanan sesiniz etinizdeki acı. 

Kum, Ocak 2002', 'Hangi an''a dokunsam, avuçlarımda  sesinin yeşeren içi. Su unutur belki  sildiğin kelimeler kadardır anlam  konuş ki bölüneyim, yarıl ki  anl...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/etinizdeki-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Solmak', 'sende-solmak-veysel-colak-stc14', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Konuştuğumuz gibi: Senin istediğin oldu 

uzaklarım bitti, gökyüzü yabancı bana. 

Beni bağışlama, 

kanıma paslı jiletler karıştır 

evden kaçan kızlara iyi davran 

aşktır diye vuruşalım istersen 

beni gömsünler ama 

papatyalar yıkılış olmasın sana. 

Kaçıyorum işte 

bir yol ağzında bırakıp kölemi 

kolum koparılmıştı uzandığımda sana 

kucakladığımda artık göğsüm yok 

dağılıyor gün bir anı bulduğumda. 

Konuştuğumuz gibi oldu: 

Bir boşluğa dönüştü gövdem 

iyice azaldı yüzümüzde kuşlar, 

hangi yanımda dursan öbür yanım uçurum. 

Ama ben su gibi sarıldım 

aşkla sevdim üstüne düştüğüm hançeri 

sımsıcak bir kadın eti gibi çoğaldım ona. 

Bir deniz gibi çekildim kıyılarımdan 

bir çöl gibi özledim seni, 

istediğin gibi oldu... 

Ama ancak büyük acıya varır 

böyle yaşarsa kalbin. 

Dize, Nisan 2002', 'Konuştuğumuz gibi: Senin istediğin oldu  uzaklarım bitti, gökyüzü yabancı bana.  Beni bağışlama,  kanıma paslı jiletler karıştır  evden kaça...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sende-solmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler Tanır Beni', 'geceler-tanir-beni-seval-kemertas-zm7yr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceler tanır beni

Hep erken dalarım karanlığa

Dünlerim kadar eski

Acılarım kadar yaslı

Bakarım uzaklarda yanan ışıklara...

Bu zifiri gecelerde 

Kaybolduğum karanlığa

Bilirim güneş doğmayacak bir daha

Ve yeşermeyecek hiç bir bahar...

Şimdi yenik  gülüşlerimi

Dudağımdan söküp atıyorum

Umutları heba ediyorum her nefeste

Gözlerimde yine o tanıdık  bulut

Kar yağıyor yüreğimde bıraktığın boşluğa...

08.02.2006', 'Geceler tanır beni Hep erken dalarım karanlığa Dünlerim kadar eski Acılarım kadar yaslı Bakarım uzaklarda yanan ışıklara... Bu zifiri gecele...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/geceler-tanir-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim baharları', 'ozledim-baharlari-kemal-eyupoglu-xwldc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şey,doğmak için zamanı bekler

			Zamansa zamana zamanı ekler

			Larvalarda mahkum şu kelebekler

			Nasıl özlemesin gelen baharı.

			Kar kış bitti,vakit artık baharın

			Dallarda yapraklar,beyaz çiçekler

			Her canlı,hayatta yaşamak için

			Ya bir şeyler ister, ya bir şey bekler.

			Beklenti,zamanla çıksa da boşa

			Gönül umut eder ve yine bekler

			Sonbaharda sararsa da tabiat

			Bir başka baharda açar çiçekler.

			Yeşilliğe,özlem duyan sarılar

			Yaz gelince başak veren darılar

			Kovanlarda hapis kalan arılar

			Nasıl özlemesin gelen baharı.', 'Her şey,doğmak için zamanı bekler 			Zamansa zamana zamanı ekler 			Larvalarda mahkum şu kelebekler 			Nasıl özlemesin gelen baharı. 			Kar ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozledim-baharlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sor Antalya '' yı...? ? ? ?', 'sor-antalya-yi-nazan-i-zmirli-dowcn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'fethiyeden;  erenlerden

aladağdan;  gelenlerden

likya   yolu, kral  yolu

adım adım  gezenlerden

sor Antalya yı...? ? ? ? 

dervişlerden................

ayağında  çarığı

yüreğinde  yaraları

serpe serpe tohumları

elinde kalan son acıları

sor Antalya yı....? ? ? ? 

erenlerden....................

zeustan

tanrıçaya

arar durur tarihi

yazılı kanyonlarda

sor Antalya yı....? ? ? ? 

taşlar da  adı  kanayanlara

termosos  kapısından

fasinis  limanına

hadrianus  girişinden

side  surlarına

sor Antalya yı? ? ? ? 

perge den selge ye 

uzanan   adım adım 

gizemli  kral

yollarında

sor antalyayı...? ? ? ? 

dağları  dağ  yapan

olimposa adaklar yakan

büyüsünde  kaybolan

cesur   yüreklerin

damarlarından akan 

kanlara.....................

08.02.2006-antalya', 'fethiyeden;  erenlerden aladağdan;  gelenlerden likya   yolu, kral  yolu adım adım  gezenlerden sor Antalya yı...? ? ? ?  dervişlerden.........', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sor-antalya-yi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Gözleri Var Nasıl Edeyim', 'guzel-gozleri-var-nasil-edeyim-yusuf-onder-bahceci-l3sge', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O Sevdiğim bana camdan bakıyor,

Camdan mı bakıyor can mı yakıyor,

O güzel gözleriyle de beni arıyor,

Güzel gözlerin var nasıl edeyim.

Birazcık gecikmişsem yola çıkıyor,

Yola çıkıyor da Gülüm yola bakıyor,

Acep nerede kaldı bu acep diyor,

Güzel gözlerin var nasıl edeyim.

Gözlerine bakınca dalar giderim,

Kalbimi de kalbine salar giderim,

Eğer git dediysen ağlar giderim,

Güzel gözlerin var nasıl edeyim.

Sadece gözleri mi sözleri güzel,

Sanki bir ceylandır salınır gezer,

Benim olmadı yâr bağrımı ezer,

Güzel gözleri var nasıl edeyim....', 'O Sevdiğim bana camdan bakıyor, Camdan mı bakıyor can mı yakıyor, O güzel gözleriyle de beni arıyor, Güzel gözlerin var nasıl edeyim. Birazc...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzel-gozleri-var-nasil-edeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalıyım Sana', 'sevdaliyim-sana-cengiz-kapusuz-fn5xp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdalıyım sana, anlasana! 

Çünkü gözlerim parlıyor,

Heyecandan yüreğim yanıyor.

Sevdalıyım,

Çünkü gece uyuyamıyor,

Sabah erken kalkıyorum.

Yerimde duramıyorum.

Sevdalıyım,

Yanımda olmasanda,

Seni düşünüyorum,

Hayalimdeki, 

Sevdanla  avunuyorum.

Sonra...

Sen kayboluyorsun,

Ben afakanlarla uyanıyorum...', 'Sevdalıyım sana, anlasana!  Çünkü gözlerim parlıyor, Heyecandan yüreğim yanıyor. Sevdalıyım, Çünkü gece uyuyamıyor, Sabah erken kalkıyorum. ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevdaliyim-sana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arta Kalan', 'arta-kalan-metin-soydeveli-vwnbt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamanında olgunlaşıp geçmek varmış imbikten

Dolaşmak damarlarında ince ince kanında

Olgunlaşıp düşmek dalından vakti gelince...

Kurda kuşa yem olmak varmış 

Arta kalınca

Açmakmış gözünü esas olan

Kapmakmış marifet yemi gagadan

Aval olan, aç kalan, cılız kalırmış

Yuvadan atılırmış 

Arta kalınca

Sürü olmakmış asıl olan

Koyun olup güdülsen de

Birlik olup dolanmakmış 

Kurt kaparmış 

Arta kalınca

Kurulmakmış baş köşeye, esas olan

Hürmet, saygı, edep derken 

Ayaz kalan, yeri yurdu olmaz

Donakalırmış 

Arta kalınca

Aşk od’una yanmakmış esas olan

Demet olup bağ olup çıra gibi yanmak

Geçip küllenmek birlikte tam zamanında

Suyla söndürürlermiş; küllenmez  köz olup 

Arta kalınca.

Zamanında yaşamak varmış kısıtlamadan aşkı

Birlikte ölüp gitmek, vakti gelince

Kalabalıklar  bitermiş elbet, terk ederlermiş çaresizliğe 

Sebil, ziyan olurmuş insan 

Arta kalınca

Ömür biter her şey bir anda olur yalan

Yazgı dediğin bitebilir her an

Aşk, sevda, ayrılık, bütün duygular yalan

Sevgidir baki, sevgidir gerçek arta kalan

(Ankara Şiir Rüzgarı Antolojisi 2009)', 'Zamanında olgunlaşıp geçmek varmış imbikten Dolaşmak damarlarında ince ince kanında Olgunlaşıp düşmek dalından vakti gelince... Kurda kuşa y...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/arta-kalan-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Kardaşım', 'kardasim-ahmet-turan-altunsu-ylis4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '/yağı sarmış dört bir yanımızı hey! 

/sömürür sülükler al kanımızı

/muktedir lekeler şanımızı hey! 

/tüketirler bir bir handanımızı! ..

/zehrederler de her anımızı hey! 

/pusarlar... usları tunda kardaşım! ..

meydanlar dar gelir diye düşündüm, 

sordum milletime: hani düşündüm? 

dedi ki: dar vakit, vallah üşendim, 

dedim: umut hâlâ han'' da kardaşım! ..

bir yanlışlık var bu işte, tuhaf hal

han'' ı uykularda farz etmek saf hal

yedisi yetmişi kalmışsa afal

belli ki kabahat zanda kardaşım! ..

iyi yurttaş, rantiyeye sarılmaz,

acı söylese de dosta darılmaz,

han’ a saldırmakla hedef vurulmaz; 

kurtuluş beldeki kında kardaşım! .. 

 ''Türk, ulu Tanrı'' nın soylu gözdesi,

Malazgirt, Bizans'' ın Türk'' e secdesi,

bu ses insanlığa Hakkın müjdesi...''

muştu ilk sabahta, tanda gardaşım! ..

08.02.2006 Güdül / Ankara

Ahmet Turan Altunsu 

(tırnak içindeki dizeler, destan şairimiz rahmetli Niyazi Yıldırım Gençosmanoğlu'' na aittir!)', '/yağı sarmış dört bir yanımızı hey!  /sömürür sülükler al kanımızı /muktedir lekeler şanımızı hey!  /tüketirler bir bir handanımızı! .. /zeh...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kardasim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şefkat', 'sefkat-mustafa-benkli-56bue', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rabbimin, rahmıyla, mahlukuna bahşetme şefkattir...

İnce bir sevdayla, sevgiliye meyletme şefkattir; 

Kimsesiz yavruyla ağlayana rikkat de şefkattir...

Mazlumun gönlüyle hüznü ise imdât ve şefkattir; 

Zâlimin zûlmüyle inleyene himmet de şefkattir...

Allahım! Şefkatle, isteyene şavkın; ne şefkattir? 

Fâ i lâ tün / müf te î lü / fe i lâ tün / me fâ î lün

(-  .  -   -   /   -   .   - . / . .   -   -   /   .   -  -   -) 

[ Vezîn; *Fâilâtün feilâtün mefâîlün* kalıbına *müfteîlü* cümlesinin eklenmesiyle bu şiire mahsus tertip edilmiştir. M.Benkli.)', 'Rabbimin, rahmıyla, mahlukuna bahşetme şefkattir... İnce bir sevdayla, sevgiliye meyletme şefkattir;  Kimsesiz yavruyla ağlayana rikkat de ş...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sefkat-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür', 'omur-mehmet-zeki-gezici-rhhss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Işıktan kırılmış

pencere camları gibi dağıldı su

ağızları açık

dilleri ıslak kurşini

çakıllar buldum göl oyuklarında miller

ömür desem saçlarından

        sular 

              yürüyecek

külün ateşlerini bakışlarına serperek

kendini sonsuz bir ömürden doyuran

bu kör karanfillerden kanadı ellerim

yapraklar delindi

taşlar oyuldu

alnım dedim dokunduğum her yanına boynum

terdendi avuçlarımdaki karanfiller.

iki yanımda katlı mendiller kurudu.', 'Işıktan kırılmış pencere camları gibi dağıldı su ağızları açık dilleri ıslak kurşini çakıllar buldum göl oyuklarında miller ömür desem saçla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zeki Gezici']::text[], 8.5, '{"poet":"Mehmet Zeki Gezici","poet_slug":"mehmet-zeki-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/omur-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümmüş Sensizlik', 'olummus-sensizlik-i-lknur-er-zqf4m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretini çekmeden hasret şiirleri yazmak ne kolaymış

Acısını bilmediğin harfleri yan yana sıralamak

Şimdi haykırmak isterken hislerimi

Elim gitmiyor hiç bir kelimeye

Sanki hiçbiri anlatmıyor seni, beni

Karanlıkların ortasında kaldım 

Ne yana dönsem sensizlik

Nefes aldığım hava düşmanım sensiz

Her saniye kalbimde atıyor sanki

Ne zor birşeymiş hasret

Ölümmüş sensizlik

Sevdiğimi askere uğurlamaya ramak kala

Kalemimden dökülenler...

Sen istanbuldan giderken kalbimde seninle gelecek...

08.02.06', 'Hasretini çekmeden hasret şiirleri yazmak ne kolaymış Acısını bilmediğin harfleri yan yana sıralamak Şimdi haykırmak isterken hislerimi Elim...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olummus-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutup ayaklarından silkelesek dünyayı', 'tutup-ayaklarindan-silkelesek-dunyayi-nilgun-acar-gjflt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şöyle derin bir soluk alsam

ve haykırsam varlığım dolusu

heeey yete artık

gümbür gümbür kırılsa çemberler

gerçekten ölse çevremdeki ölüler

yaşam korkağı bakışlarından kurtulsam

sonra sürdürsem evren yolculuğumu

alarak yanıma yalnız çocukları

bir de mavi yürekli dostları

kuşları ağaçları toprağı

ırmaktan bir sevgilim olsa

hep bana koşan

doldurup doldurup taşıran

her sabah yeniden

tutup ayaklarından

silkelesek dünyayı', 'Şöyle derin bir soluk alsam ve haykırsam varlığım dolusu heeey yete artık gümbür gümbür kırılsa çemberler gerçekten ölse çevremdeki ölüler y...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Acar']::text[], 8.5, '{"poet":"Nilgün Acar","poet_slug":"nilgun-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tutup-ayaklarindan-silkelesek-dunyayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtlar Vadisinin Ortasına Düştüm', 'kurtlar-vadisinin-ortasina-dustum-yusuf-onder-bahceci-b239g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurtlar Vadisinin tam ortasına düştüm,

Bunlar Kurt değilmiş çakalmış bildim,

Aklım yeni yeni başıma geliyor bildim,

Kurtlar Vadisinin tam ortasına düştüm.

Çakal olduklarını bilsem savururdum,

Sinsi planlarını öğrenir de bulurdum,

Allah korusun belki kendimi vururdum,

Kurtlar Vadisinin tam ortasına düştüm.

Benim dediğim kurtlar başka kurtlardır,

Umutlarımızı söndüren çandır kurtlardır,

Olan olmuş kalansa hâyaller umutlardır,

Kurtlar Vadisinin tam ortasına düştüm.

Polat Alemdar gibiydim de düşürdüler,

Dostları ağlatıp düşmanları güldürdüler,

Böylesi hain planlar kurup da güldüler,

Kurtlar Vadisinin tam ortasına düştüm....', 'Kurtlar Vadisinin tam ortasına düştüm, Bunlar Kurt değilmiş çakalmış bildim, Aklım yeni yeni başıma geliyor bildim, Kurtlar Vadisinin tam or...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kurtlar-vadisinin-ortasina-dustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-cengiz-kapusuz-9aysb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canım ciğerim.

Ekmeğim aşım.

Tohum ektiğim tarlam

Sevdam! 

Aşk içtiğim tasım,

Yanık türkümdeki,

Göz yaşım.

Dertlerin en güzeli ile,

Yorulmuş dertli başım.

Senden uzakta değil.

Sana çok yakın,

Benim bitanem,

Güzel aşkım.', 'Canım ciğerim. Ekmeğim aşım. Tohum ektiğim tarlam Sevdam!  Aşk içtiğim tasım, Yanık türkümdeki, Göz yaşım. Dertlerin en güzeli ile, Yorulmuş...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askim-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-gulten-ornek-viuam', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüzüm aynanın arkasında

Bütün gücümle asılıyorum almaya

Geri vermiyor asla

Dönüyorum arkamı

Gün bitmek üzere kapının pervazında

Göremiyorum kendimi

Rüzgarlar delik deşik ediyor kulaklarımı

Yağmurlar anlamsız of çekiyor yanaklarıma

Nasıl aşk bu 

Ben aynaların mı oldum', 'Yüzüm aynanın arkasında Bütün gücümle asılıyorum almaya Geri vermiyor asla Dönüyorum arkamı Gün bitmek üzere kapının pervazında Göremiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Gülten Örnek']::text[], 8.5, '{"poet":"Gülten Örnek","poet_slug":"gulten-ornek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayna-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deruni Hasbihal -9-', 'deruni-hasbihal-9-zulfikar-yapar-kaleli-cccwq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' 

Bu yerde şairin dili perişan

Ne kadar olsa da nazsız, nedendir? 

Bülbülü lâl bağın gülü perişan

Göllerim dudusuz, kazsız, nedendir? 

Ben miyim divane, sen misin hasif? 

Sen mi takıntılı, ben miyim pasif? 

Ben miyim meyane, sen mi agrasif? 

Sesimiz hep kısık, tizsiz, nedendir? 

Güvercinler saldım yaban ellere

Bülbüller zulmeder esmer güllere

Bastığı toprakta huzursuz ere

Baharlar, baharsız, yazsız, nedendir? 

Ucuz sevdalara kucak açalı

Aramıza girdi çok karaçalı

Gönül beğenmiyor yeşili alı

Davulsuz, zurnasız, sazsız, nedendir? 

Huzuru divanda gözü ağların

İlkbaharda kışı geldi bağların

Belleri aşılmaz karlı dağların

İnişsiz, çıkışsız, düzsüz, nedendir? 

Başımız ısrarla aynı hatada

Kanımız akıyor yedi kıtada

Gözümüz kan kusan şu haritada

Umutlar yarına, izsiz,  nedendir? 

* Kaleli''yle Hasbıhâl - 9 *

Perişan eden dil, edilen değil… 

Dilsizlerin kârı ne olsa iyi? 

En leziz şerbet ki, tadılan değil 

Körükleyen hârı… Ne olsa iyi? 

Bir sevdâ uğruna vurduk şoseye… 

Tatlı bir kelâma, pak bir bûseye 

Hasret kaldık, sen de deme kimseye, 

Heybemin zarârı ne olsa iyi? 

Gittikçe artıyor kini küslerin, 

Yankısı aslını aştı seslerin! 

Yıkıldı duvarı hep kafeslerin, 

Kuşların efkârı ne olsa iyi? 

Şu yollar diyorum, usta şu yollar, 

Riyâyla açılan gönülsüz kollar… 

Vuruldu bilete dert rengi pullar! 

Yolun mihmandârı ne olsa iyi? 

Derûnî, rahatlık senin neyine? 

Şu ipek gömlekler tenin neyine? 

Güneş varken yıldız günün neyine? 

Şu ömrün bahârı ne olsa iyi? .. 

Abdulkadir Öğdüm', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''  Bu yerde şairin dili perişan Ne kadar olsa da nazsız, nedendir?  Bülbülü lâl bağın gülü ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/deruni-hasbihal-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer Gününe', 'sevgililer-gunune-alper-kuruk-jb7mg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi bir güne sığmaz

Ona gün kesmek niye? 

Bir On Dört Şubat mıdır

Sevenlere hediye? 

Nice On Dört Şubatlar

Gelip de geçer gider,

Şubatta bir hikmet var

Ömrü de kısa sürer.

Sevmeyi bilmeyenin

On Dört Şubat neyine? 

Bu günü bekleyenin

İnanmam sevdiğine...', 'Sevgi bir güne sığmaz Ona gün kesmek niye?  Bir On Dört Şubat mıdır Sevenlere hediye?  Nice On Dört Şubatlar Gelip de geçer gider, Şubatta b...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgililer-gunune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz de Ayaktayım', 'sensiz-de-ayaktayim-kevser-gulistan-cakir-67kpl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllar tek engelimizdi

Yolları saymazsak

Günlerim gün saymakla geçti

Gecelerim 

Sana rüyalarımda sarılmakla

Geleceğim demiştim bir gün

Senin şehrine karışacağım

O zaman asla

Ellerini bırakmayacağım

Takvimler yavaşça inceldi

Ve koptu bir gün pamuk ipliği

Senin için geldiğim şehirde

Sensiz kaldım

Yıkılan çok şey var

Ben ayaktayım...', 'Yıllar tek engelimizdi Yolları saymazsak Günlerim gün saymakla geçti Gecelerim  Sana rüyalarımda sarılmakla Geleceğim demiştim bir gün Senin...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensiz-de-ayaktayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güllerin İçinde', 'gullerin-i-cinde-yusuf-onder-bahceci-4bx1n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırmızı güllere söz mü söylenir,

Sarı güllerle bilki gönül eylenir,

Pembe güller ile adın söylenir,

Güllerin içinde en güzelisin.

Zakkum çiçeği güzel ama zehir,

Benim şu kalbim se laleye esir,

Menekşe insanlara ediyor tesir,

Güllerin içinde en güzelisin. 

Akasyalar da nasıl koku saçıyor,

Papatyalar açmışlar aya bakıyor,

Limon çiçeği uzaktan anlaşılıyor,

Güllerin içinde en güzelisin.

Nilüfer hep göllerde salınır gezer,

Aman Allah''ım ne kadar da güzel,

Senin gibi gül yok ki sözlerim uzar,

Güllerin içinde en güzelisin...', 'Kırmızı güllere söz mü söylenir, Sarı güllerle bilki gönül eylenir, Pembe güller ile adın söylenir, Güllerin içinde en güzelisin. Zakkum çiç...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gullerin-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isırgan Otu', 'isirgan-otu-aynur-avci-mbrit', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Isırgan tohumu

Topla ez dediler

Bala karıştır ye dediler

İyi olur,yara durur..

Güldüm....

Ağaçlar saçaklanmış

İçimde bir defa

Isırgan otu bal niye? 

Doktorlar bile olamamış şifa

Ecel gelmiş nasihat bahane

Isırgan otu bahane...', 'Isırgan tohumu Topla ez dediler Bala karıştır ye dediler İyi olur,yara durur.. Güldüm.... Ağaçlar saçaklanmış İçimde bir defa Isırgan otu ba...', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/isirgan-otu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Gitme Ne Olur', 'bu-gece-gitme-ne-olur-gul-yazganarikan-lrtgc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kal bu gece yanımda,

Öyle masumca,

Ellerin elime değmese de olur

Bu gece gitme ne olur...

Kal bu gece yanımda.

Gitme

Susarım ben, susarım 

İçimdeki sesler onlar da susar istersen...

Dinlemem yüreğimi,

Ellerin elime değmese de olur

Bu gece gitme ne olur...

Sokulur yatarım kıyıcığında nefesinin

Sırtını da dön istersen

Ne çıkar uyurken biraz seyretsem

Varlığını yanımda, canımda hissetsem

Kal bu gece

Ellerin elime değmese de olur

Bu gece gitme ne olur...

Gitme

Esirgeme varlığını bu gece benden

Gidersen bil ki! bu gece son olur, öyle ki sonum olur... 

Gitme ne olur...', 'Kal bu gece yanımda, Öyle masumca, Ellerin elime değmese de olur Bu gece gitme ne olur... Kal bu gece yanımda. Gitme Susarım ben, susarım  İ...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bu-gece-gitme-ne-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük 1', 'dortluk-1-aynur-avci-5e5h8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yudum nefesim ol

Gel benim sevenim ol

Gel ömrümün tacı ol

Bekletme tut elimi,elim ol...', 'Bir yudum nefesim ol Gel benim sevenim ol Gel ömrümün tacı ol Bekletme tut elimi,elim ol......', ARRAY['Türk Edebiyatı','Şiir','Aynur Avcı']::text[], 8.5, '{"poet":"Aynur Avcı","poet_slug":"aynur-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-1-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İz', 'i-z-deniz-cetin-3bjr2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'okyanus gözlerinde damlayım,

ağladıkça gezinirim yüzünde...', 'okyanus gözlerinde damlayım, ağladıkça gezinirim yüzünde......', ARRAY['Türk Edebiyatı','Şiir','Deniz Çetin']::text[], 8.5, '{"poet":"Deniz Çetin","poet_slug":"deniz-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/iz-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Âh-u Zâr', 'h-u-z-r-hikmet-kucuk-ex8ud', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günaydınlar olsun ey âfitâb-ı gülzârım benim,

Âfitâb görüverse kıskanır ol ruhsârın senin.

Doğduğun yer pek güzelmiş, gölleri dağları varmış,

Amma sen doğunca  sönük kalmıştır diyarın senin.

Cümle alem niye bilmem, senden şikayet etmekte,

Gözü kör etmekten gayrı olmaz ki zararın senin.

Cennetinden alıvermişte sanki dünyaya koymuş, 

Sonsuz  övgülere layıktır yüce mimarın senin.

Yüzümü senden yana çevirince birden yanıyor,

Kış günü de olsa hararetlidir civarın senin.

Tartıya dahi bakmadım şüphem yoktur ağır basar,

Bir yandaki cihandır, diğer yanda didarın senin.

Uzaklardan geçen gün seni görür görmez tanıdım,

Letafet, zarafet,  bir de güzellik şiarın senin.

Âb-ı hayattır gülüşün, ancak öldürür bakışın,

Ne olur bir söyle güzel, nedir  miktarın senin? 

Sonraki günler uğramaz oldun doğduğun yerlere,

Gülşeni tarumar eylemiştir bu firârın senin.

Müebbete niyetlendim, beraatımı istemem,

Sana mahkumum ne çıkarsa çıksın kararın senin.', 'Günaydınlar olsun ey âfitâb-ı gülzârım benim, Âfitâb görüverse kıskanır ol ruhsârın senin. Doğduğun yer pek güzelmiş, gölleri dağları varmış...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Küçük']::text[], 8.5, '{"poet":"Hikmet Küçük","poet_slug":"hikmet-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ah-u-zar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldi Geçti', 'geldi-gecti-kevser-gulistan-cakir-lz75o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Batmayan güneşler

Bitmeyen gecelerden önceydi

O da öyle bir şeydi

Geldi geçti...

Engellerin olduğu

Bildiğimiz şeydi

Neden serden geçsin

Ankaralım

Yârdan vaz geçti...

Sıyrıl gönül karalardan

Yas bitti

Zaten o öyle bir şeydi

Geldi

Geçti...', 'Batmayan güneşler Bitmeyen gecelerden önceydi O da öyle bir şeydi Geldi geçti... Engellerin olduğu Bildiğimiz şeydi Neden serden geçsin Anka...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/geldi-gecti-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-kadir-uskup-5nlks', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yazıyorum:

Bir de benden dinleyin diye,

Anlamını hayatın bunca yazılandan ziyade.

Maddenin kör kuyusunda kaybolmuş zihinler,

İman yoksulu efendilerin köleliğinde…

Ellerde kelepçeler, meta zindanlarında,

Prangaların sıkılığında zayıf bilekler.

Ya yürekler? Kapkara kanın boğduğu yürekler? 

Satılmış tümü üç beş kuruşa,

Ebedi kurtuluş gününü bekler.

Kimbilir belki bir gün ileride…

Belki de kaldı binlerce yıl geride,

Zaman diye birşey yok artık,

Herşey yazanın kaleminde……', 'Yazıyorum: Bir de benden dinleyin diye, Anlamını hayatın bunca yazılandan ziyade. Maddenin kör kuyusunda kaybolmuş zihinler, İman yoksulu ef...', ARRAY['Türk Edebiyatı','Şiir','Kadir Üsküp']::text[], 8.5, '{"poet":"Kadir Üsküp","poet_slug":"kadir-uskup","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayat-300-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Dönerse Yine Başım', 'ya-donerse-yine-basim-murat-isik-7v3jb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ya dönerse yine başım

Ya alırsa beni  uçurumların

Korkmuyor da değilim hani

Unuttum artık desemde

Yine görmezse sensizliği gözlerim

Ya kalırsam altında özlemin

...

Hayır unuttum artık

Teninde beni yakan o dokuyu

Bir nefeste sarhoş eden kokuyu

Unuttum artık

Zaten demiştim yıllar önce

Unutmak kolay diye

Not düşmüştüm ya  hani defterine; 

''Artık hiç vaktim olmayacak

Seni düşünüp adını anacak

Çünkü çalışıyor olacağım

Unutmak için ağlayarak''

Evet sözümü tuttum 

Unuttum artık.', 'Ya dönerse yine başım Ya alırsa beni  uçurumların Korkmuyor da değilim hani Unuttum artık desemde Yine görmezse sensizliği gözlerim Ya kalır...', ARRAY['Türk Edebiyatı','Şiir','Murat Işık']::text[], 8.5, '{"poet":"Murat Işık","poet_slug":"murat-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ya-donerse-yine-basim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-kadir-uskup-0vwh1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umut her derdin devası

Nasıl desem… sanki bir ressamın fırçası.

Simsiyah gecedir önce tualdeki renk,

Ayı, yıldızı boyar üstüne, parlak gümüş sırması.

Kayıpsan bir okyanus azametinde,

Ararsın bir fener fersahlarca ilerde.

Bir varsın bir yok, kural herkese denk,

Umuttur seni saran soğuk tenler içinde.', 'Umut her derdin devası Nasıl desem… sanki bir ressamın fırçası. Simsiyah gecedir önce tualdeki renk, Ayı, yıldızı boyar üstüne, parlak gümüş...', ARRAY['Türk Edebiyatı','Şiir','Kadir Üsküp']::text[], 8.5, '{"poet":"Kadir Üsküp","poet_slug":"kadir-uskup","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umut-249-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birşey Anlamıyorum', 'birsey-anlamiyorum-yusuf-onder-bahceci-jbncs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adını vermeyeyim başka bir sitede de şiir yazıyorum,

Hemi yazıyorum, hemi de kendi kendime kızıyorum,

Seven dostlarım şiirlerin güzel diyor mutlu oluyorum,

Bu sitede şiirler yazıyorum, pek birşey anlamıyorum,

Vatan, Bayrak, Din, İman, İhlas gibi değerler diyorum,

Acaba hangi şiirleri yazmak gerekir ki bilemiyorum,

Hey hat ben bu sitede pek fazla benimsenmiyorum', 'Adını vermeyeyim başka bir sitede de şiir yazıyorum, Hemi yazıyorum, hemi de kendi kendime kızıyorum, Seven dostlarım şiirlerin güzel diyor ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/birsey-anlamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Önce', 'yillar-once-kadir-uskup-mzr8s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocuk,

Ufacık..

Bir elinde simit,

Diğerinde gazozu.

Çocuk,

Zavallıcık..

Ayağında sandalet

Yanında lastik topu.

Mahalle,

Toz toprak.

Hava sıcak, galiba yaz.

Fotoğraf,

Siyah, beyaz..

Hangi yıldı...dur biraz..', 'Çocuk, Ufacık.. Bir elinde simit, Diğerinde gazozu. Çocuk, Zavallıcık.. Ayağında sandalet Yanında lastik topu. Mahalle, Toz toprak. Hava sıc...', ARRAY['Türk Edebiyatı','Şiir','Kadir Üsküp']::text[], 8.5, '{"poet":"Kadir Üsküp","poet_slug":"kadir-uskup","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yillar-once-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmge Beslersin', 'i-mge-beslersin-deniz-cetin-9tq65', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanma ki sözcükler gece olunca biter 

ay buluta çekilince bu vakit 

tüm şiirler sana akar...', 'Sanma ki sözcükler gece olunca biter  ay buluta çekilince bu vakit  tüm şiirler sana akar......', ARRAY['Türk Edebiyatı','Şiir','Deniz Çetin']::text[], 8.5, '{"poet":"Deniz Çetin","poet_slug":"deniz-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/imge-beslersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana da bana da yazık oluyor', 'sana-da-bana-da-yazik-oluyor-mikdat-bal-pundm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensiz geçmez anım gündüz gecede

Sana da bana da yazık oluyor

Her yerde sen varsın sözde hecede

Sana da bana da yazık oluyor

Ne oldu bize ki ağlar dururuz

Kendimize halat bağlar dururuz

Sen beni ben seni dağlar dururuz

Sana da bana da yazık oluyor

Ya beni ağlatma, veyahut sen gül

İkimiz ağlarsak kalmaz gülen kul

Ya beni unut geç ya yanında bul

Sana da bana da yazık oluyor

Mikdatî, yanarım boş geçen güne

Depreşti yaralar ağladım yine

Bu kadar elemi çekmez bu sine

Sana da bana da yazık oluyor', 'Sensiz geçmez anım gündüz gecede Sana da bana da yazık oluyor Her yerde sen varsın sözde hecede Sana da bana da yazık oluyor Ne oldu bize ki...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-da-bana-da-yazik-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-ebru-rabia-berkul-vls0q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamansız gelen 

Özlemimdin.

Mesafelerle sınırlanan,

Hasretim oldun.

Gözlerine doyamadığım,

Sevdiğimdin.

Acılara gebe

,Üzüntüm oldun.

Hayallerim vardı,

Kalbime sığdıramadığım.

En ücra köşemde 

Sakladığım.

Küçücük isteklerdi,

Olsun diye umutlandığım.

Olmadı,hayaller

 O küçücük yaşama sığmadı.', 'Zamansız gelen  Özlemimdin. Mesafelerle sınırlanan, Hasretim oldun. Gözlerine doyamadığım, Sevdiğimdin. Acılara gebe ,Üzüntüm oldun. Hayalle...', ARRAY['Türk Edebiyatı','Şiir','Ebru Rabia Berkul']::text[], 8.5, '{"poet":"Ebru Rabia Berkul","poet_slug":"ebru-rabia-berkul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayal-132-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-mustafa-bilgili-ks443', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen bir gül ağacı olsaydın,

Ben dalın olurdum,

Sen bir arı olsaydın,

Ben balın olurdum.

Sen bir yolcu olsaydın,

Ben yolun olurdum.

Sen bir aşk mektubu olsaydın,

Ben pulun olurdum.

Sen bir kraliçe olsaydın,

Ben kulun olurdum.

Sen bir ermiş olsaydın,

Ben şalın olurdum.

Sen bir altın kemer olsaydın,

Ben belin olurdum.

Sen bir lal olsaydın,

Ben dilin olurdum.

Sen bir aşk pınarı olsaydın,

Ben gölün olurdum.

Sen bir güneş olsaydın,

Ben çölün olurdum.

Sen bir dağ başı olsaydın,

Ben delin olurdum,

Sen bir aşk ateşi olsaydın,

Ben külün olurdum.

Daha ne olmamı isterdin 

Ey vefasız sevgili,

Dileseydin ben senin kölen olurdum.

                                                       29.11.1996', 'Sen bir gül ağacı olsaydın, Ben dalın olurdum, Sen bir arı olsaydın, Ben balın olurdum. Sen bir yolcu olsaydın, Ben yolun olurdum. Sen bir a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-ve-ben-173-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dost Ağlıyor', 'bir-dost-agliyor-kevser-gulistan-cakir-1l0j8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ansızın hücum ediyor

Sesler ruha

Körpe dallar zamansız

İşte böyle kuruyor

Deli dolu çiçekler

Güneşe doyamadan 

Ay doğuyor

Gece oluyor...

İnsanlar yorgun

İnsanlar düşünceli

İnsanlar mahzun

Evlerine dönüyor...

Şimdi 

Bir ben kaldım pencerede

Bir de cam, perde, çerçeve

Artık yüreğimi tek

Habersiz şimşekler aydınlatıyor

Gözlerim dalıyor

Yağmur yağıyor

Kulaklarım

Bakışlarım ötesini kucaklamakta

Uzaklarda bir yerlerde

Bir dost ağlıyor...', 'Ansızın hücum ediyor Sesler ruha Körpe dallar zamansız İşte böyle kuruyor Deli dolu çiçekler Güneşe doyamadan  Ay doğuyor Gece oluyor... İns...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-dost-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne gam ne elem sana agyar olan,', 'ne-gam-ne-elem-sana-agyar-olan-ali-riza-unal-x4qtr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne gam ne elem sana agyar olan,

Firak-ı hicab eyle,sûkunun olayım,

Tükenmez neşve dir,sana yar olan,

Talib-i visâl eyle,meramın olayım', 'Ne gam ne elem sana agyar olan, Firak-ı hicab eyle,sûkunun olayım, Tükenmez neşve dir,sana yar olan, Talib-i visâl eyle,meramın olayım...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-gam-ne-elem-sana-agyar-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaradan Güzel', 'yaradan-guzel-cengiz-kapusuz-nummc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel! 

Sen güzel,

Seni doğuran güzel.

Kötü, çirkin elbet olacak.

Güzel, 

Yanında anlam bulacak,

Karışıp harman olacak,

Kötü savrulup,

Güzel kalacak.

Unutma! ...

Güzel,

Sen güzel,

Seni doğuran güzel,

En önemlisi.

Yaradan güzel...', 'Güzel!  Sen güzel, Seni doğuran güzel. Kötü, çirkin elbet olacak. Güzel,  Yanında anlam bulacak, Karışıp harman olacak, Kötü savrulup, Güzel...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yaradan-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunlar Hangi Taraftan', 'bunlar-hangi-taraftan-yusuf-onder-bahceci-4skfx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu adamlar Alpay''ıma tekme atıyor,

Kamera iyi çekmiş herkes görüyor,

Yine de Alpay tekme atmıştı diyor,

Bunlar hangi taraftan anlamıyorum.

Türkiye İsviçre Maçını anlatıyorum,

Anlatıyorum da iyi  anlatamıyorum,

Fatih Terim''in suçu yoktu diyorum,

Bunlar hangi taraftan anlamıyorum.

Altı maç seyircisiz sahada oynansın,

Türk Milli Takımına oyunlar oynansın,

Yoksa Türkleri erkekçe yenemezsin,

Bunlar hangi taraftan anlamıyorum.

İçerden ve dışardan pazarlıklar var,

Kahpeliğin her çeşidi, envaisi var,

Bunların yaptığına kalleşlerde kızar,

Bunlar hangi taraftan anlamıyorum.', 'Bu adamlar Alpay''ıma tekme atıyor, Kamera iyi çekmiş herkes görüyor, Yine de Alpay tekme atmıştı diyor, Bunlar hangi taraftan anlamıyorum. T...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bunlar-hangi-taraftan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kuş', 'kucuk-kus-kevser-gulistan-cakir-7zlax', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yarın yine balkonuma gel küçük kuş

İstersen sırdaş oluruz seninle

Gökyüzünü ilk rengine boyarız

Sonra rengarenk uçurtmalar salarız

Sen de çiçekleri seversin eminim

Senin de yüreğin

Benim korkularımla titrer

Bu türküler sana

Hangi yüzyıldan miras kaldı

Söyle

Göç edersen

Benim ezgilerimi de götürür müsün

Uzak iklimlere...', 'Yarın yine balkonuma gel küçük kuş İstersen sırdaş oluruz seninle Gökyüzünü ilk rengine boyarız Sonra rengarenk uçurtmalar salarız Sen de çi...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kucuk-kus-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağrımda Tekmelerin', 'bagrimda-tekmelerin-gul-yazganarikan-s2rpf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eksilmek nedir bilmezsin,

Eksilmezsin hiç,

Ana rahmine düşmüş bir döl gibi

Yüreğime düşmüşsün 

Öyle büyütüyorum seni,

Gözyaşlarımla besleniyor gibisin...

Acıdıkça yüreğim hızlanır bağrımda tekmelerin 

Yine de çıkmaz sesim

Dertlenmem sana, dertlenemem,

Hani nasıl ana gururlanır  tekmeden

Canımı yaksan da vazgeçemem ki senden...

Zor öyle zor ki seni sensiz büyütmek,

Yüreğimde kıvranırken 

Bir bebek gibi habersizsin ettiğinden,

Doğumun bile bir zamanı varken....

Sen hiç doğamayacaksın benden...

Yine de dertlenmem, 

Hangi ana dertlenir ki bebeğinden.

Senin de yok farkın gözümde

Doğmamış, doğamamış nice bebekten...', 'Eksilmek nedir bilmezsin, Eksilmezsin hiç, Ana rahmine düşmüş bir döl gibi Yüreğime düşmüşsün  Öyle büyütüyorum seni, Gözyaşlarımla besleniy...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bagrimda-tekmelerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Sus 3 (sayfa çalışması)', 'sus-3-sayfa-calismasi-nurten-altinok-potew', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hoşgeldiniz 

                      



Bu gece yanımda olabilmeliydin 

Gölgeni seyredebilmeliydim holde gezinen 

Mutfaktan bir şeyler aramalıydın ve 

Kırılmalıydı bir bardak mermerde, en kıymetlisinden 

-Canın sağ olsun, seslenebilmeliydim, - boş ver aldırma 

Yüreğinin atışını duyabilmeliydim bu gece, dalga dalga 

Şekerini karıştıran bir kaşığın bardak sesine karışmalıydı sesin 

–Sen de ister misin? 

Bu gece yanımda olabilmeliydin 

Demleyebilmeliydik zamanı seninle 

Demlenebilmeliydik 

Korumasızdır yavruları kumruların / biraz saf, uçmaya hevesli 

Taşıyamaz kanatları oysa acemi uçuşları 

En uslu dokunuşlarım gezinebilmeliydi saçlarında / düşmeden önce 

Çenenden tutup yüzünü bana doğru kaldırabilmeliydim 

Körkuyu gözlerinde dibe vurabilmeliydim özlediğim 

Kozasında büyümeliydi mavi şafak renginde ipekten bir sevgi 

Ayrılık nedir bilmemeliydi ve öğrenmemeliydi 

Ölüme bir türlü sonsuzluk dendiğini 

İbadetine diz çökmüş bir bekleyişin dualarında 

Kokun dokunuyor önce bam teline sızımın / pan flüt eşliğinde 

Arka fonda gözü kan çanağı yarasa geceler bekçim 

Resimlerinde flu bir bulut / kir beyazı, pamuk duman 

Çalmayın mavimi diyorum gözlerimin mayasından 

Acıtıyor dudaklarımı filtresinden yanan ateş 

Bu kaçıncı bilmem 

Bu kaçıncı sigaram 

Bu gece yanımda olabilmeliydin, çırılçıplak soyunup geçmişinden 

Harman yeri savrulmuş duygularıma yenik düşmüşlüğümde 

Küfürlerin binini bir paraya savurduğum bu yazgıya 

Öpebilmeliydin dudaklarımdan 

- Sus..! 

Bu gece yanımda olabilmeliydin 

İmansız bir acının terkisinde kırbaç ıslığı sesim 

..........Sus / tura 

....................bilmeliydin 

..........Sus / a 

....................bilmeliydim 

Bu gece yanımda olabilmeliydin...', 'Hoşgeldiniz                         Bu gece yanımda olabilmeliydin  Gölgeni seyredebilmeliydim holde gezinen  Mutfaktan bir şeyler aramalıyd...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sus-3-sayfa-calismasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir dedikleri...', 'sehir-dedikleri-halide-selcan-karagul-znho8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şehir dedikleri bir kuru kalabalık, herkes birbirine yabancı 

Köyden göçmüşler belli bir çoğu, çekiyor hesapsız sancı 

Ne varsa satıp gelmişler şehre, yüreklerinde bir umut saplantısı 

Ne bilsinler şehir bu kadar acımasız ve hoyrat kalmamış imkanları... 

08.02.2006', 'Şehir dedikleri bir kuru kalabalık, herkes birbirine yabancı  Köyden göçmüşler belli bir çoğu, çekiyor hesapsız sancı  Ne varsa satıp gelmiş...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sehir-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşarken', 'yasarken-kevser-gulistan-cakir-s5i1r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şaşkın bir damla düştü

Kirpiklerimin üstüne

Ağlayan buluttan...

Damlacık

Boşluğa düştüğünün farkında değildi

Yapayalnız yürüyordum

Yağmurun altında

Mutluluk için

Ne kadar yürümek gerekliydi

Hoşlandığımdan değil

Bu duraksız yolculuklar

Bu ufuk yürüyüşü yaşamaksa

Her adıma sahip çıkmalı sindirerek

Varsın ölüm gelsin dostum

Ölmeden önce ölmemek gerek...', 'Şaşkın bir damla düştü Kirpiklerimin üstüne Ağlayan buluttan... Damlacık Boşluğa düştüğünün farkında değildi Yapayalnız yürüyordum Yağmurun ...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasarken-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala Bekliyorum...', 'hala-bekliyorum-halide-selcan-karagul-ckbiu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hala bekliyorum hayatımın anlamını,bir gün gelecek ümidiyle

Yıllar varki özlemekten zaman ayıramadım kendime

Ellerimde beyaz güllerle yollarına kırmızı halılar serdirdim yine

Hala gözlüyorum hasret kokulu gülümü bir gün açacak diye...

08.02.2006', 'Hala bekliyorum hayatımın anlamını,bir gün gelecek ümidiyle Yıllar varki özlemekten zaman ayıramadım kendime Ellerimde beyaz güllerle yollar...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hala-bekliyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yakarış**', 'yakaris-dursun-elmas-70erh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu bir yakarıştır; gönül avazım

Şanına malumdur,nakıs namazım

Kadir Mevlâm senden duam niyâzım

Sağlık ver,sıhhat ver, ''pul'' verme bana.

Heba ettik gitti,onca zamanı

Irak et gönülden; yalan dolanı.

İstemem rütbeyi,makamı şanı

İlim ver, irfan ver, ''mal'' verme bana.

İmânı,ihlâsı fikre tabip et

Yol verme İblis''e, nefse, galip et.

Resûlü Zişan''a komşu nasip et

Edep ver,hâyâ ver, ''zül'' verme bana.', 'Bu bir yakarıştır; gönül avazım Şanına malumdur,nakıs namazım Kadir Mevlâm senden duam niyâzım Sağlık ver,sıhhat ver, ''pul'' verme bana. Heba...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yakaris-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eza', 'eza-zeynal-yaman-ppu73', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boş konuşan sultan olsa sözü ezadır bana

Anlatsa Allah''ı bir gedâ sultan olur bana', 'Boş konuşan sultan olsa sözü ezadır bana Anlatsa Allah''ı bir gedâ sultan olur bana...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/eza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Yıldızım', 'deniz-yildizim-ethem-turan-6zqkw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gemisini yitiren kaptan oldum 

Uçsuz bucaksız deryada

Soğuk tuzlu suyuna

Nice dostlar gömdüm 

Nice duygular yoğurdum 

Elimde kalan filikamda 

Umut ışığım tükendikçe 

Ölümü diledim hiç istemeden

Ne arandım nede bulundum 

Ölümün soğuk kuyusunda

Yapayalnız kala kaldım 

Ne bir martı uçtu üzerimde 

Ne de bir uçak geçti 

Güneş bütün yakıcılığıyla 

Günlerce saldırdı 

Su deryasında

Bir damla suya hasret düştüm

Gecenin güneşi de 

İçimi yaktı istemeden 

Anlayacağın ne teselli olan oldu 

Ne de yön gösteren 

Seni fark edene dek 

Hiç umut ışığım olmadı 

Sana doğru çektiğim her kürekte

Bir bir aydınlandı yollarım 

Uçmayan martılar  uçar

Geçmeyen uçaklar geçer oldu 

Hayattan haz almayı

Yeşilin güzelliğini 

Senin ışığında bir daha  keşfettim 

Umut ışığım oldun içimde

Sünger çektim geçmişe 

Suya gömdüklerime üzüldüm sadece

Seninle yeni bir hayata  selam verdim 

Işığınla nice tohum yeşerdi içimde

Hep orda kal deniz yıldızım 

Bak nasılda mutluyum  seninle', 'Gemisini yitiren kaptan oldum  Uçsuz bucaksız deryada Soğuk tuzlu suyuna Nice dostlar gömdüm  Nice duygular yoğurdum  Elimde kalan filikamda...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/deniz-yildizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Olsun Tüm Kara Kışlar', 'bahar-olsun-tum-kara-kislar-kamil-soylemez-84cfv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sus ne olursun.sus söyleme

Bana sakın sevme deme

Sevdim seni sevdim bir kere

Dönemem ki gerisin geriye

Gideceğim belki cehenneme

Belkide senin ellerinde cennete

Belki deli,belkide divane

Sevdim seni sevdim ölümüne

Gölgen olup,uçacağım sevginle

Masmavi gök yüzü ve denizlerine

Kanat çırpacağım sevdan özlemiyle

Hep seveceğim dönmek yok geriye

Başım aşılmaz karlı dağ zirvesi

Gözlerim palandöken çiğ tanesi

Seni söylüyor seni inliyor şimdi

Sevdim diyor gönül sevdim yar

Haydi şimdi sende beni uyar

Bahar olsun tüm kara kışlar.......!', 'Sus ne olursun.sus söyleme Bana sakın sevme deme Sevdim seni sevdim bir kere Dönemem ki gerisin geriye Gideceğim belki cehenneme Belkide sen...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bahar-olsun-tum-kara-kislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-kevser-gulistan-cakir-h23ty', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerim ceplerimde

Saçlarım ıslak

Yine yağmur yağıyor bak! 

Bir çift yanımdan geçiyor

Tanıdık bir ezgi mırıldanıyorlar

Görüyorsun ya

Şarkımız hâlâ dillerde

Başkalarının şarkısı olarak...

Hava kapalı olduğunda

Yağmurlar ilk benim yüreğimde yağardı

Yüreğim

Esrik çaylar gibi sana akardı

Her şey yaşanmaya mahkûmmuş meğer

Ve unutulmaya...

Dolaşıyorum perişan yollarda

Bu, sensizliğin ilk sonbaharı

Kabullenmesi en zor şeymiş

Senin için ağlamak

Ellerim ceplerimde

Gözlerim ıslak

Yine yağmur yağıyor bak...', 'Ellerim ceplerimde Saçlarım ıslak Yine yağmur yağıyor bak!  Bir çift yanımdan geçiyor Tanıdık bir ezgi mırıldanıyorlar Görüyorsun ya Şarkımı...', ARRAY['Türk Edebiyatı','Şiir','Kevser Gülistan Çakır']::text[], 8.5, '{"poet":"Kevser Gülistan Çakır","poet_slug":"kevser-gulistan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yagmur-264-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıdım', 'tanidim-mevlut-bicik-v7mqd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bunca yıllık ömr-ü dünya‘mda,

Bir tâne zât-ı şahâne tanıdım.

Nîce yâreler açan şu bünyâmda,

Bir tâne zât-ı şahâne tanıdım.

Otuz senelik aşk lambamı söndüren

Ma’neviyâtımı  mahvedip  öldüren

Kalbimi ise nefretlerle dolduran

Bir tâne zât-ı şahâne tanıdım.

Telâfîsi lâ-yümkin yâreler açan

Etrâfına riyâkâr gülücükler saçan

Enâniyetle yaşayıp,nahnü‘den kaçan

Bir tâne zât-ı şahâne tanıdım.

Beynennâs nâm-ı dîğeri derviş

Enâniyyetin tâ zirvesine ermiş

Kibirli fakat tevâzu postuna girmiş

Bir tâne zât-ı şahâne tanıdım.

Keşke tanımaz ve tanışmaz olaydım

Hizmetimde kalıp,meşakkatle dolaydım

Gözü tok gönlü tok bir dost bulaydım

Lâkin! Bir tâne zât-ı şahâne tanıdım.

Mevlüt Bicik

08.02.2006  saat  13.35

Esslingen', 'Bunca yıllık ömr-ü dünya‘mda, Bir tâne zât-ı şahâne tanıdım. Nîce yâreler açan şu bünyâmda, Bir tâne zât-ı şahâne tanıdım. Otuz senelik aşk ...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tanidim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun...', 'gidiyorsun-aysun-elagoz-p17lq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidiyorsun

Sessizce sokaklarını geçerek,

Yüreğimin sana ait şehrinin...

Sözler bir bir uçuşuyor

Özlemlerin gökyüzünde...

Ve çarpışıp düşüyorlar boşluğa...

Her adımda,

Benden biraz daha gidiyorsun..

Saplanıp kalmış bakışlarım,

Yokluğunun buram buram sindiği

O anlamsız kocaman yalnızlığa...

Bir çift kelime süzülüveriyor

Dudaklarımdan..

Duyamayacak kadar uzaksın oysa..

Belki hissedersin...

Gitme...Özleneceksin...', 'Gidiyorsun Sessizce sokaklarını geçerek, Yüreğimin sana ait şehrinin... Sözler bir bir uçuşuyor Özlemlerin gökyüzünde... Ve çarpışıp düşüyor...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gidiyorsun-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Hüzün', 'gozlerinde-huzun-yusuf-onder-bahceci-dk8pa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey sevdiğim  ölünceye kadar hep böyle olacak,

Senin gözlerinde hüzün benim ki yaşla dolacak,

Acaba bu sevdanın sonunda neler neler olacak,

Senin gözlerinde hüzün benim ki yaşla dolacak...

Senin sevdan olduğu gibi hep tap taze kalacak,

Benim bu şiirlerimi okuyanlar hayret te kalacak,

Önder''de herkes gibi birgün kara toprak olacak,

Senin gözlerinde hüzün benim ki yaşla dolacak.

Belki bizi böyle ayıranlar eyvah, eyvak diyecek,

Çok sevdiğin güzel belki bir gün mesut olacak,

Belki de bu yaptıkları için çokça pişman olacak,

Senin gözlerinde hüzün benim ki yaşla dolacak....', 'Ey sevdiğim  ölünceye kadar hep böyle olacak, Senin gözlerinde hüzün benim ki yaşla dolacak, Acaba bu sevdanın sonunda neler neler olacak, S...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerinde-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
