INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana aşkı Anlatma', 'bana-aski-anlatma-fadime-dizdar-dei1i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben aşka gönül vermiş,

Sevdalının biriyim.

Yer  ile  gök arasında,

Yağan Yağmur gibiyim.

Senin aşkın aşk mı ki,

Bu aşkımın yanında. 

Kah l u beriden beri,

Mayası var kanımda.

Kav dağın tepesinden,

Dönüp yüzüme bakma! 

Aşkın ası kalbimde,

Bana aşkı anlatma!', 'Ben aşka gönül vermiş, Sevdalının biriyim. Yer  ile  gök arasında, Yağan Yağmur gibiyim. Senin aşkın aşk mı ki, Bu aşkımın yanında.  Kah l u...', ARRAY['Türk Edebiyatı','Şiir','Fadime Dizdar']::text[], 8.5, '{"poet":"Fadime Dizdar","poet_slug":"fadime-dizdar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bana-aski-anlatma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-abdullah-atay-xgoif', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seven gönül engindir

Yürek dostsuz yangındır

Para pulla değil de

Kişi dostla zengindir...

Boşa geçmesin günün

Sevgiyle dolsun gönlün

Dost yarenin yok ise

Baharda kıştır ömrün...

Her gönüle dost gerek

Sevgiyle çarpar yürek

Kırarsan dost kalbini

Neye yarar üzülmek...

Çağdaşlık bir yarıştır

Dostluk özü barıştır

Hal hatır selamlaşma

Karlı alışveriştir...

Gönül dostsuz acıda

Tükenmeyen sancıda

Dostsuz kalan gönüller

Sabahsız bir gecede...

Gönül bir değirmendir

Suyu ise sevgidir

Bir selam bir de hatır

Gönüle hoş gelendir...

Dünya malı hep yalan

Sevgidir asıl olan

Hazanı bahar olur

Gerçekten dostu bulan...', 'Seven gönül engindir Yürek dostsuz yangındır Para pulla değil de Kişi dostla zengindir... Boşa geçmesin günün Sevgiyle dolsun gönlün Dost ya...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dost-134-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun Kadar', 'yoklugun-kadar-senol-alaca-qcoci', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'soguklar gelecekmiş 

donduran 

ne gam! inan ki korkmam 

ne soğuk, ne fırtına, ne kar 

hiçbiri üşütmez içimi inan, yokluğun kadar.

azrail gelecekmiş 

can alan 

ne tasa! umrumdamı ki kıyamet kopsa

ne azrail, ne ölüm, ne mezar 

hiçbiri ürpertmez içimi inan, yokluğun kadar.', 'soguklar gelecekmiş  donduran  ne gam! inan ki korkmam  ne soğuk, ne fırtına, ne kar  hiçbiri üşütmez içimi inan, yokluğun kadar. azrail gel...', ARRAY['Türk Edebiyatı','Şiir','Şenol Alaca']::text[], 8.5, '{"poet":"Şenol Alaca","poet_slug":"senol-alaca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yoklugun-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktaki Çınar', 'uzaktaki-cinar-samiha-i-kbal-w2oby', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beklentiler kara bir elbise giydirdi ümitlerime

Susmalarım konuşuyor şimdi

Dar vakitlerinde ömrümün

Sökmüş olmalı haklı kelimeleri

Müjdeler vermişsede melekler

Toplayamadılar içimin kırıklarını

Her bir söz birer hançer gibi saplandı

Kolay kabuk bağlamıyor açılan yaralar

Yar,

Yaradana yalvardım

Üzmeyesin beni

Aşkın bir adıda ayrılık oldu dilimde

Müjdeli haberlere dayadım kulaklarımı

İlk meyvesini vermiş uzaktaki çınar.', 'Beklentiler kara bir elbise giydirdi ümitlerime Susmalarım konuşuyor şimdi Dar vakitlerinde ömrümün Sökmüş olmalı haklı kelimeleri Müjdeler ...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uzaktaki-cinar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutku / Cesaret', 'tutku-cesaret-umut-engin-deniz-zaofx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'TUTKU / CESARET

Sen varken

ne geçmişimi

ne geleceğimi düşünüyorum.

Her yer tek renk — sepya.

Sen ve ben

sarıyla kırmızıyız;

tutkuyla cesaretin tam ortasında,

sımsıkı bağlıyım,

aşkla.

Kavgam var.

Korkularım var.

Korkularım karşısında

saygıyla eğiliyorum —

bana haddimi bildiriyor.

Aşk.

Cesaret.

Korkudan doğar —

boğar.

UNLBBCN

Umut Engin Deniz', 'TUTKU / CESARET Sen varken ne geçmişimi ne geleceğimi düşünüyorum. Her yer tek renk — sepya. Sen ve ben sarıyla kırmızıyız; tutkuyla cesaret...', ARRAY['Türk Edebiyatı','Şiir','Umut Engin Deniz']::text[], 8.5, '{"poet":"Umut Engin Deniz","poet_slug":"umut-engin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tek-renk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kadar Zor Mu', 'bu-kadar-zor-mu-sacide-yaylaz-a8sbq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne var göstersen sevgini, 

Elle tutulmaz,gözle de görülmez 

Sadece yürek de hissedilir, 

Neden korkuyorsun ki, 

Bu kadar zor mu sevdiğini söylemek. 

Karşındakine güven verebilmek 

Seni seviyorum diyebilmek, 

Yürek atışlarını dinletmek, 

Ellerinin sıcaklığını hissettirmek, 

Bu kadar zor mu sevdiğini söylemek. 

. 

Hadi artık söyle,çekinme 

Seni seviyorum de,haykır 

Şimşekler çaksın gökyüzünde, 

Sevi yağmurları yağsın, 

Bu kadar zor mu sevdiğini söylemek.', 'Ne var göstersen sevgini,  Elle tutulmaz,gözle de görülmez  Sadece yürek de hissedilir,  Neden korkuyorsun ki,  Bu kadar zor mu sevdiğini sö...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-kadar-zor-mu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hançerlenir Yüreğim*', 'hancerlenir-yuregim-i-sa-tekin-a5yxq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdiğim

Birtanem

Aşkım

Sevdam

Dört duvar arasında

Bir avuç mavi gökyüzünde

Aradım seni

Bulutlarda gözlerini görmek için

Özgürlüğe kanat çırpan

Serçeye sordum

Gülüm

Karagözlüm

Nazlım

Narinim

Anlattıklarım yetmiyor ardından

Yüreğimde sakladım

Bizden yana tüm özlemlerimi

Senden yana rüzgar esmiyor

Yorgun bedenime

İsyan ediyor yüreğim

Birtanem

Gülüm

Nazlım

Sevdiğim

Karanlık bulutlar içindeyim sanki

Beyaz bulutlara çıkmak isterim

Sana ulaşmak

Yanında olmak için 

Dört duvara baktıkça

Hançerlenir yüreğim

Evet aşkım

Sevdiğim

Yaban çiçeğim

Hasretim, özlemim

Sana bizden yana

Güzel şeyler yazmak isterdim

Dicle kenarında el ele koşmayı

Nemrut''ta güneşin doğuşunu seyretmeyi

Hayal olduğunu düşündükçe

Hançerlenir yüreğim', 'Sevdiğim Birtanem Aşkım Sevdam Dört duvar arasında Bir avuç mavi gökyüzünde Aradım seni Bulutlarda gözlerini görmek için Özgürlüğe kanat çır...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hancerlenir-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsan', 'tutsan-nuray-acar-6p7mf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutsan diyorum ellerimden

Haber bile vermeden

Öpsen diyorum gözlerimden

Henüz veda etmeden

Ve yaşanılan her anı ölümsüz kılan

Sözler bulsan diyorum

Şöyle fiyakalı ölümsüz

Eh biraz da senden bana bulaşan

Aşkın sihrinden köşe bucak kaçmadan', 'Tutsan diyorum ellerimden Haber bile vermeden Öpsen diyorum gözlerimden Henüz veda etmeden Ve yaşanılan her anı ölümsüz kılan Sözler bulsan ...', ARRAY['Türk Edebiyatı','Şiir','Nuray Açar']::text[], 8.5, '{"poet":"Nuray Açar","poet_slug":"nuray-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tutsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı hava', 'ayni-hava-nazli-guller-lqc1y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aynı havayı soluyabiliyoruz ya 

Bu da yeter...

Razıyım ben buna.

Aynı semtin kaldırım taşlarına

İz bırakıyor ayaklarımız

Belki aynı dükkanın vitrininde 

Siluetimizi izliyoruz ikimiz de

Belki aynı caddeden geçiyoruz 

Birer saat arayla

Geçen gün sokakta gördüğüm

Bir kadını kıskandım

Seninle aynı havayı

Soluyabiliyor diye.

Pencerenin altından her geçtiğimde

Beni görmeni bekliyorum

Seni soluyorum havada 

Derin nefeslerle

İçime çekiyorum.

Arada bir buluşup

Kaçamak kahve içmek birlikte

Tüm aidiyetimiz bu kadar olsa bile

Varlığını hissetmem yeter

Gecelerinin içinden geçemesem de

Aklından geçtiğimi biliyorum

Gecelerinin içinde.

Dansettiğimi zihninde

Ve aynaların yansımasında 

Biliyorum beni aradığını

Ve özlediğini

Seviyorum sana

Kendimi özletmeyi

Özleyince görebilmek önemli...

Uzak şehirlerde olmak da vardı,

Ümitsiz, çaresiz, ayrı ve yalnız

Zaman zaman buluşmasız

Hasrete bulanmak vardı 

Kavuşmasız...

Aynı havayı soluyabiliyoruz ya

Ve seni görme ümidi var ya

Bu da yeter.', 'Aynı havayı soluyabiliyoruz ya  Bu da yeter... Razıyım ben buna. Aynı semtin kaldırım taşlarına İz bırakıyor ayaklarımız Belki aynı dükkanın...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Güller']::text[], 8.5, '{"poet":"Nazlı Güller","poet_slug":"nazli-guller","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ayni-hava-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmez', 'yetmez-serhat-kulu-pdwzw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşlerin yetmez hayatı anlamaya,

En doğrusu yokturki dünyada.

Rastlamadığın binbir umut, binbir acı

Teslim olmak yok, elbet direnmektir yaşamak,

Avuçlarında gözyaşın, yüreğin buruk kalsada...', 'Düşlerin yetmez hayatı anlamaya, En doğrusu yokturki dünyada. Rastlamadığın binbir umut, binbir acı Teslim olmak yok, elbet direnmektir yaşa...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kulu']::text[], 8.5, '{"poet":"Serhat Kulu","poet_slug":"serhat-kulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yetmez-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufuklarımda Beklediğim Güneş Doğmadan', 'ufuklarimda-bekledigim-gunes-dogmadan-hatice-kuzu-xzqvr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ufuklarımda beklediğim güneş doğmadan

Hüzün yasak benliğime.

Açmamış güllerin dikeni batıyor ellerime.

Kanıyor,kanıyorum.

Durdur zamanı,çekip gitme apansız

Bırakma beni nafile haykırışlara.

Yine sensiz uyandım sabaha,

Ellerim bomboş,kollarım bomboş.

Alamadığım nefes

Dokunamadığım hayalin

Ve olmadığım benliğimle

 Günleri düğümledim dünlere.

Göz yaşlarım yaşıma karıştı

Tutsak oldum geçen yıllara

Düşlerle,düşüşlerle

Yasaklı ve suskun bekledim seni.

Bekledim seni zehir,zemberek gecelerde

Karanlığa haykırdım duy diye sesimi.

Sen yoktun,şarkılar yoktu,şiirler yoktu 

Vazgeçtim senden,vazgeçtim karanlık gecelerden.

Karanlık gecelerde bestelenir en güzel şarkılar, 

Şarkılarda dile gelir sevdalar,hicranlar

El bağlanır, kol bağlanır, dil bağlanır

Güneş doğmaz beklediğin ufka.

Elveda hayallere, elveda umutlara

Elveda düne,elveda güne

Elveda  yarın,elveda yazgım.

Elveda hayallerimi yıkan kadın…

2006 Ocak Almanya', 'Ufuklarımda beklediğim güneş doğmadan Hüzün yasak benliğime. Açmamış güllerin dikeni batıyor ellerime. Kanıyor,kanıyorum. Durdur zamanı,çeki...', ARRAY['Türk Edebiyatı','Şiir','Hatice Kuzu']::text[], 8.5, '{"poet":"Hatice Kuzu","poet_slug":"hatice-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ufuklarimda-bekledigim-gunes-dogmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çirkindik Gönlünce', 'cirkindik-gonlunce-elvan-genc-xc0uf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz dünyaya sevmeye geldik,

Sevdiğimiz gönüllerdi

Biz gönüller almaya geldik

Aldığımız ödül neydi

Yarattığın bu bedeni

Gözler gördü, gönül sevdi

Hangi mertebedeydi ki; 

O muhteşem beğenmedi

Ah bu beden iki hokka

Bir aşağıda bir yukarıda

Çok çok iki dirhem tutsa

Üçte biri sevgindendi...

Gözler kara, saçlar keza

İki mısra bir satıra

Bakmak ile doyulmaz ya

Beğenmemen kibrindendi...

Ocak 2006', 'Biz dünyaya sevmeye geldik, Sevdiğimiz gönüllerdi Biz gönüller almaya geldik Aldığımız ödül neydi Yarattığın bu bedeni Gözler gördü, gönül s...', ARRAY['Türk Edebiyatı','Şiir','Elvan Genç']::text[], 8.5, '{"poet":"Elvan Genç","poet_slug":"elvan-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cirkindik-gonlunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma öyle...', 'bakma-oyle-serhat-kulu-yz8xg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakma öyle gözlerime,

Anlayamazsın bendeki beni

Hangi yol ayrımındayım? 

ağlasam beni duyarmısın? 

Rehin kaldım kara gözlerinde,

Bırak desem bırakırmısın?', 'Bakma öyle gözlerime, Anlayamazsın bendeki beni Hangi yol ayrımındayım?  ağlasam beni duyarmısın?  Rehin kaldım kara gözlerinde, Bırak desem...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kulu']::text[], 8.5, '{"poet":"Serhat Kulu","poet_slug":"serhat-kulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bakma-oyle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-mehmet-isikoglu-83iuh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgili yanında süresiz zaman

Mutluluk gönülün baş köşesinde

Kalp teli titreşen bir yaylı keman

Ruhların gıdası özel sesinde

Doyum olmaz vuslattaki aleme

Yüreklerin çarpıntısı birleşir

Tarifi imkansız gelmez kaleme

Gönül yuvasına sevgi yerleşir

Öyle yaşam her canlının özlemi

Nede sıcak olur aşkın kucağı

Gerçekleşir rüyaların alemi

Pekişirde kopmaz gönüller bağı

Korku dalgaları yaklaşmaz kolay

Sarılmış sineler kuvvet dillere

O anın lezzeti bambaşka olay

Yaşanır da anlatılmaz ellere

Sohbet ile ateşlenir duygular

Yükselir havaya gizli bir duman

Taş isede pamuk olur yaygılar

Keyifler yerinde her yer sütliman

Ayrı bir ortamda yaşar sevdalar

Arzular serilmiş cennet misali

Sarmaş dolaş olur uykuya dalar

Kimler arzu etmez böyle visal', 'Sevgili yanında süresiz zaman Mutluluk gönülün baş köşesinde Kalp teli titreşen bir yaylı keman Ruhların gıdası özel sesinde Doyum olmaz vus...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vuslat-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşkıya..', 'eskiya-serhat-kulu-ewy0z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yıldız daha kaydı, 

yırtarak gecenin karanlığını...

Şimdi bir eski zaman eşkıyası,

vurulduğu yerde kaldı.

Failsiz bir çığlık bırakarak ardı sıra

bedeni paramparça,

Düştü, titrek,

Yaprağa öykünerek

toprağa...', 'Bir yıldız daha kaydı,  yırtarak gecenin karanlığını... Şimdi bir eski zaman eşkıyası, vurulduğu yerde kaldı. Failsiz bir çığlık bırakarak a...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kulu']::text[], 8.5, '{"poet":"Serhat Kulu","poet_slug":"serhat-kulu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/eskiya-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Omuzları', 'yalnizligin-omuzlari-muammer-erturan-kiekw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimi boğar kahkahayı

kimi buharlaşır kahkahadan,

arada mekik dokumaktan

yorgun düşer

kurur gider kimi de...

İnsan manzaraları içinde

bir renk işte

koyusundan açığına...

Dahası

damlası damlasına insan...

Ortaçağ goygoycusundan

zamane dalkavuğuna

kuşatmışlarsa ama yaşamı

gardını açmak anlamına gelir

tek bir damlası bile...

Kalakalmışsan hele bir başına,

ta ortasında kavganın...

Yalnızlığın omuzları vardır

orda tek,

dayayıp başını

gözyaşı dökebilecek...

(Kasım ''97)', 'Kimi boğar kahkahayı kimi buharlaşır kahkahadan, arada mekik dokumaktan yorgun düşer kurur gider kimi de... İnsan manzaraları içinde bir ren...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalnizligin-omuzlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında', 'aslinda-salih-ozalasan-d8km5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Derler ki güzel konuşmak

Dinlemesini bilmekle öğrenilir

Merak ederim başa bela merak

Dinleyen dilsiz yada  sağırsa? 

Güzelle tatlı eşdeğerde aslında

Ama yılan tatlı dile yenilir yuvasında

Dil mi tatlı söz mü bilinmez aslında

Birde susmak altın; Kaldık ikisi arasında

Aslında ne güzel olurdu

Hem konuşmasını bilsek

Yeri geldiğinde susmasını

Güzel olan kararın bilmek aslında

“ ben güzele güzel demem”

“güzel benim olmazsa”

boşuna söylememiş Karacaoğlan

güzel olan yüreği sızlatıyor aslında

Y.tarihi 20-01-2006 Saat 01.40

Salih ÖZALAŞAN', 'Derler ki güzel konuşmak Dinlemesini bilmekle öğrenilir Merak ederim başa bela merak Dinleyen dilsiz yada  sağırsa?  Güzelle tatlı eşdeğerde...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aslinda-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Yerinde', 'eski-yerinde-osman-dagistan-tdxsn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anahtar yine paspasın altında

Eski yerinde

Kapım açık sana

Ne zaman istersen gel.

Kalbimi ise kilitledim

O gittiğin günden beri

Kimse el sürmesin diye 

Sana vaadettiğime.

Anahtarı denize attım...', 'Anahtar yine paspasın altında Eski yerinde Kapım açık sana Ne zaman istersen gel. Kalbimi ise kilitledim O gittiğin günden beri Kimse el sür...', ARRAY['Türk Edebiyatı','Şiir','Osman Dağıstan']::text[], 8.5, '{"poet":"Osman Dağıstan","poet_slug":"osman-dagistan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/eski-yerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında(2)', 'aslinda-2-salih-ozalasan-b4rpr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dil bizim söz bizimdir, yerli yerinde etsek 

Çivi değil sökülmez, doğrusu haddin bilsek

Dost üzülür düşman sevinir dil ile üzsek

Doktor çaresiz kalır her yürek yarasında

Güzel olanı bize vermiş yüce yaradan

Her canlı öğrenir öz konuşmayı anadan

Birde güzel huyları kapabilse babadan

Güzellik ana babada değil mi aslında

Sözün bilesin söylerken mutlaka dostuna

Haşa güvenme geçici şaşalı postuna

Post gider dost kalır o en sadık ardında 

Vizon giy beyhude ömrü bir güve aslında

Y.Tarihi 08-02-2006  Saat 16,10

Salih  ÖZALAŞAN', 'Dil bizim söz bizimdir, yerli yerinde etsek  Çivi değil sökülmez, doğrusu haddin bilsek Dost üzülür düşman sevinir dil ile üzsek Doktor çare...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aslinda-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm mezarı olur...', 'omrum-mezari-olur-serhat-kulu-eapky', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ömrüm mezarı olur kirpiğinin teli,

Ben seni bugün sevmedimki

Sanırım fi tarihiydi; 

ne dağı delendim ne çöle düşen...

Gitmemiştim kafdağının ardınada.

Yaşamak yalan geliyordu,

gereçek olan bir sendin,

Düşlerimde büyüttüm ben seni,

yarım ağız gülüşlerimde...

Ömrüm mezarıdır yarin yüreği,

Kefensiz gömün oraya beni...', 'Ömrüm mezarı olur kirpiğinin teli, Ben seni bugün sevmedimki Sanırım fi tarihiydi;  ne dağı delendim ne çöle düşen... Gitmemiştim kafdağının...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kulu']::text[], 8.5, '{"poet":"Serhat Kulu","poet_slug":"serhat-kulu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/omrum-mezari-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ertesi..', 'ertesi-serhat-kulu-8tdhx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ertesi yalnızlıktır yaşanılmışlığın,

Bir yap boza benzer hayat

Sürekli değişen bir döngü

Bazı başın döner yere düşecekmişsin gibi,

ayakların kesilir yerden, bastığın yer bulut olur.

Bir alçak basıncın alçaklığında,

Damla olursun süzülerek yanağımın gamze çukurunda.

Ama yalnızlık milat öncesi bir icat,

bir gün sende kalırsın bir başına...', 'Ertesi yalnızlıktır yaşanılmışlığın, Bir yap boza benzer hayat Sürekli değişen bir döngü Bazı başın döner yere düşecekmişsin gibi, ayakların...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kulu']::text[], 8.5, '{"poet":"Serhat Kulu","poet_slug":"serhat-kulu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ertesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir tek ben ve...', 'bir-tek-ben-ve-serhat-kulu-8e2q1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmurlarda sırılsıklam ıslanmak, 

Hasretine sarılmak yalnız gecelerde.

Bir ırak diyarda yaşamak seninle

bir tek ben ve bendeki sen...

Hadi desen gözüm kara

Adressiz düşeriz yollara,

bavulumuzda umut yürekte sevda ile,

Bir tek ben ve bendeki sen...', 'Yağmurlarda sırılsıklam ıslanmak,  Hasretine sarılmak yalnız gecelerde. Bir ırak diyarda yaşamak seninle bir tek ben ve bendeki sen... Hadi ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kulu']::text[], 8.5, '{"poet":"Serhat Kulu","poet_slug":"serhat-kulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-tek-ben-ve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleri Susan Kadın….', 'gozleri-susan-kadin-duygu-devrim-yr793', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi sen yoksun ya  sevgilim

Ben yine bıraktım yüreğimi....

Her defasında ki gibi, o koca enkazlar altında

Bak! Bak bu kez ağlamıyorum, ağlamayacağım da…

Silmeyeceğim elimin tersiyle gözlerimi

Hissetmeyeceğim yanağımdan dökülenleri

Ve kan çanağına dönmeyecek gözlerim asla! ..

Bak! Bak bu kez ağlamıyorum ağlamayacağım da…

Hani gözlerimden akan, yağmur misali dökülen o yaşlar vardı ya

Şimdi yüreğimden akıyorlar 

Kan misali dökülüyorlar, içimin en kuytularına 

Bak! Bak bu kez ağlamıyorum, ağlamayacağım da...

Evet sustu gözlerim, usandılar onlar da sonunda! ..... 

Sen hiç duydun mu? 

Gözleri susan kadını….

Yüreğinden ağlayan, 

Sessiz sessiz haykıran kadını? 

Ne söyleyecek sözü, ne sevgiliye aşkı

Ne de, aşka inancı  kalmamıştır artık! ...

Susar ve bekler! 

Sessizce akıtır yaşlarını

Susar ve bekler! 

Sanki bekleyeceği bir düşü var gibi

Ne bekleyeceği bir düşü

Ne de düşleyeceği bir ümidi, yoktur aslında

Bıkmıştır! Çünkü

Hayatından, yaşamandan, kaderinden

Gönülden, sevgiden aşktan

Ve bıkmıştır esasında canından

Susar ve bekler! 

Usul usul akıtır yaşlarını

Susar ve bekler! 

Kanayan yüreğiyle….

Susar  Ağlar! ……..', 'Şimdi sen yoksun ya  sevgilim Ben yine bıraktım yüreğimi.... Her defasında ki gibi, o koca enkazlar altında Bak! Bak bu kez ağlamıyorum, ağl...', ARRAY['Türk Edebiyatı','Şiir','Duygu Devrim']::text[], 8.5, '{"poet":"Duygu Devrim","poet_slug":"duygu-devrim","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gozleri-susan-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsız...', 'anlamsiz-serhat-kulu-7n7dv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlamsız bir bakış geçti,

Düşlerimi yırtarak.

Sardı tüm benliğimi,

Düşlerim yalınayak...', 'Anlamsız bir bakış geçti, Düşlerimi yırtarak. Sardı tüm benliğimi, Düşlerim yalınayak......', ARRAY['Türk Edebiyatı','Şiir','Serhat Kulu']::text[], 8.5, '{"poet":"Serhat Kulu","poet_slug":"serhat-kulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/anlamsiz-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalabalıkta', 'kalabalikta-muammer-erturan-kep4e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ucu bucağı duman

masadan masaya yol olmuş türküler... 

Gönüller yorgun düşmüş 

koşturmaktan belli ki 

öteki yarısı peşinde kendinin... 

Herkesin bir öyküsü var

her öykünün bir kahramanı

her kahramanın bir günahı... 

Kadehler dert babası 

kadehler ağlama duvarı

kadehler dost,

zaman ortak düşman... 

Tanıdık yabancılarla dolu 

bir boşluk bu

ağlayan kendine ağlıyor 

gülen kendine... 

Paylaşmak güya 

işin ambalajı mı desem

makyajı mı

her neyse artık 

yalnızlık kol geziyor oysa... 

Ve işin tuhaf yanı 

daha da çok duyumsanması 

kalabalıkta... 

(''00)', 'Ucu bucağı duman masadan masaya yol olmuş türküler...  Gönüller yorgun düşmüş  koşturmaktan belli ki  öteki yarısı peşinde kendinin...  Herk...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kalabalikta-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnkar Sesi...', 'i-nkar-sesi-taner-nisanci-hdb90', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '``Şüphesiz Allah Nurunu Tamamlayacaktır:``

Hak gelip de batıl zail olunca

Küfür korkup ürktü güzel hitaptan

Aç gönüller gül Nebiyi bulunca

İnkar sesi çıktı ehl-i kitaptan

O geldi; putlar yüzüstü devrildi

Küfrün kaleleri bir bir çevrildi

Münafıklar yaprak gibi savruldu

İnkar sesi çıktı ehl-i kitaptan

Kendinden evvel verildi muştular

Binbir zorluğu sabırla aştılar

Yayıldı İslam, düşmanlar şaştılar

İnkar sesi çıktı ehl-i kitaptan

Nur tamam olacak bunu bilse de

Yanlışı bilip doğruyu görse de

Şirin olmak için şekle girse de

İnkar sesi çıktı ehl-i kitaptan

Bir Garip der; geçmişten kin alarak

İnat edip haçlı ruhu salarak

Çizgisiyle küfre kalem çalarak

İnkar sesi çıktı ehl-i kitaptan

08/02/2006', '``Şüphesiz Allah Nurunu Tamamlayacaktır:`` Hak gelip de batıl zail olunca Küfür korkup ürktü güzel hitaptan Aç gönüller gül Nebiyi bulunca İ...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/inkar-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim gönlüm bir yuva...', 'benim-gonlum-bir-yuva-ercan-akbay-3q4e8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim gönlüm bir yuva,

   Gel gir sevda kuşum ol.

   Sabah,akşam her saat,

   Şarkım,türküm,neşem ol..

   Eksilmesin gülüşün,

   Dudağımda gülüm ol.

   Hayat versin bakışın,

   Gözlerimde sevinç ol..

   Benim gönlüm bir petek,

   Gel gir sen de balım ol.

   Yazım,kışım,dört mevsim,

   Coşkum,arzum,neşem ol...

                              HAZİRAN-1992

                              Makam...Acemkürdi

                              Beste......Nurettin Demirtaş.', 'Benim gönlüm bir yuva,    Gel gir sevda kuşum ol.    Sabah,akşam her saat,    Şarkım,türküm,neşem ol..    Eksilmesin gülüşün,    Dudağımda g...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/benim-gonlum-bir-yuva-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lânetlik Tür!', 'l-netlik-tur-huseyin-avdic-gyt8v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Lânetlik Tür! 

Ah $u karikatür varliklar, yaptilar bir karikatür; 

