INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Özlem', 'dosta-ozlem-guner-kurt-rcbl3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül dağlarını dışa vuramadım ki	

Sana sevgimden bir demet sunamadım ki	

Gönül yandı durdu da canım	

Bir teselli bulamadı ki	

Hayli zaman oldu göremeyeli	

Hayli zaman oldu detleşmeyeli	

Uzağı yaşar gönül gelemeyeli	

Sende bu hisleri taşıyormusun	

Bir gün geleceğim görüşeceğiz	

Bir gün geleceğim dertleşeceğiz	

Gönül uzakları yakın edecek	

Sende bu hisleri taşıyormusun			

Sabreyle gönül ferman olmasın			

Özlenen gün elbet bir gün gelecek			

Gönül dosttan yana hiç sitem etmez			

Bir ahım var derinde selamın gelmez			

			

Sensizken seni yaşamak gibi			

Hediyelerin avuttu yıllardır beni			

Dayanamazsam daha bekle ne olur			

Bekle geleceğim canım bekle beni', 'Gönül dağlarını dışa vuramadım ki	 Sana sevgimden bir demet sunamadım ki	 Gönül yandı durdu da canım	 Bir teselli bulamadı ki	 Hayli zaman o...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dosta-ozlem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen...', 'sen-sibel-uygun-ck0er', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün yine cok mutlu uyandım  sabaha.

Sen yanımda yoktun, ama yine de hep benimleydin.

Güneşin ışıklarıyla,

Kuş cıvıltıları eşliğinde  giriyordun penceremden.

Yudumladığım su, yediğim yemeğin tadı bile sendin…

Benim icin herşeydin…

Yanımda olmasan da, 

Seninle yürüyordum her çıktığım yola.

Sahillerin serinliğine yüreğimi salarken ben,

Yildizlarda ismin,

Mehtapta resmin,

Dalgalarda hep senin sesin vardi.

Ama bir sen yoktun…', 'Bugün yine cok mutlu uyandım  sabaha. Sen yanımda yoktun, ama yine de hep benimleydin. Güneşin ışıklarıyla, Kuş cıvıltıları eşliğinde  giriy...', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-757-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuktu', 'soguktu-ali-kemal-i-cen-d863s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soğuktu,

İnsanlar mum ışığında ısınıyordu

Biz ise o kavganın ateşiyle

Koşuyorduk meydanlara

Fabrikada,gecekonduda

Üşümedik inatla sarıldık sevdamıza

Yılmadan yorulmadan.

Soğuktu,

Ses verirdik seslerimize

Yitip giden sadece zaman değil

Soğuktu ve biz baharı umut ediyorduk.

Çünkü biliyoruz ki her bahar yeniden yetişecek umut

Sevgimiz daha bir çoşacak

Kavgamız dahada büyüyecek

Ve bir ülkenin kaderi olacak....', 'Soğuktu, İnsanlar mum ışığında ısınıyordu Biz ise o kavganın ateşiyle Koşuyorduk meydanlara Fabrikada,gecekonduda Üşümedik inatla sarıldık s...', ARRAY['Türk Edebiyatı','Şiir','Ali Kemal İçen']::text[], 8.5, '{"poet":"Ali Kemal İçen","poet_slug":"ali-kemal-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/soguktu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Sizi Biri Küçük Biri Büyük Ağçaya Söylerim', 'bak-sizi-biri-kucuk-biri-buyuk-agcaya-soylerim-eyup-selahattin-dalkiran-akr0m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl olsa yakında ikiside dışarda

Allahıma

sizi  sabahın,akşamın alaca karanlığında

Boğduracağım onlara

pis Kapitalistler,Emperyalistler diye

Nasıl olsa.', 'Nasıl olsa yakında ikiside dışarda Allahıma sizi  sabahın,akşamın alaca karanlığında Boğduracağım onlara pis Kapitalistler,Emperyalistler di...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bak-sizi-biri-kucuk-biri-buyuk-agcaya-soylerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytan Görsün Yüzünü! ..', 'seytan-gorsun-yuzunu-vedat-sahin-a5zbu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu son şiirim sana, bundan sonra yok artık! 

Çal başına aşkını, gözlerine sok artık! 

Şeytan görsün yüzünü, benim karnım tok artık! 

Sevda denizlerinde, beni Mecnun gezdiren! 

Aşkın kitabındaki, karizmamı çizdiren... 

Bırak beni kendime, defterimi dür benim! 

Ne yapsan yok faydası, rüyalarım hür benim! .. 

Ve artık senden yana, neyim varsa sır benim! ... 

Uzatma ellerini, çoktan kalktı o tren! 

Ey benim yıllarımı, gençliğimi bitiren... 

Neler demiştin bana, nerde kaldı sözlerin! 

Nerde arkamdan yaşlı; sulu, sepken gözlerin! 

Senden eser geriye, ben ve gerçek yüzlerin! 

Yürü bakma ardına, beni yiyen sindiren! 

Bu dünyadan indirip, bir meçhule bindiren... 

Olmam gayrı sana ben, ne köle ne kul artık! 

Sana bıraktım seni, Allah''ından bul artık! 

Senin adın nezdimde, geçmez para pul artık! .. 

Sakın çıkma karşıma, beni yıkan deviren! 

Yem yeşil baharımı, sonbahara çeviren... 

Nasıl tutuldum sana, kendime güler oldum! 

Senle geçen zamanı, geçmişten siler oldum! 

Simdi kalbimi yeni, aşklara biler oldum! 

Sür eşegin Niğde''ye, geçti Bor''un pazarı! 

Belki orda bulursun, dilediğin mezarı... 

06.10.2002 Olching

Not: Şiir 08.02.2006 tarihinde 526 antolojim ile A Listesinin 10. sırasında iken gördüğüm lüzum üzerine tarafımdan silinip tekrar eklenmiştir.', 'Bu son şiirim sana, bundan sonra yok artık!  Çal başına aşkını, gözlerine sok artık!  Şeytan görsün yüzünü, benim karnım tok artık!  Sevda d...', ARRAY['Türk Edebiyatı','Şiir','Vedat Şahin']::text[], 8.5, '{"poet":"Vedat Şahin","poet_slug":"vedat-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seytan-gorsun-yuzunu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* KıRıK AyNa *', 'kirik-ayna-mine-ozdemirtas-bnkac', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'masumiyet kılıç çekmiş olmalı

kını yerde

yoksa..! 

birileri.................

kılıf mı hazırlıyor minareye? 

Nedense..? 

hergün

biraz daha azalıyor içim

eksilenleri koyarken yerine.

Hangi taşı kaldırsam

altında ki cam parçacıkları batıyor elime.

Ayna

Kırılmış mı ne..? 

07/02/2006', 'masumiyet kılıç çekmiş olmalı kını yerde yoksa..!  birileri................. kılıf mı hazırlıyor minareye?  Nedense..?  hergün biraz daha az...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirik-ayna-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hanği Ülkede Postacılar Sakladı Benim Mektuplarımı', 'hangi-ulkede-postacilar-sakladi-benim-mektuplarimi-eyup-selahattin-dalkiran-m0eze', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen bu işi      

unutmayacaksın

kara talihim

Ölümün beni unutmadığı gibi

Tutsaklığım onda

Kahrın ta içinde

benle beraber.

bırak beni

Baharı özledim

Şeytan Çarpmışcasına.

Ben ölünce

Kara talihim

Sen ne yapacaksın

Doğum günümümü kutlayacaksın

Sahiplenilmemiş anılar içinde

Kara talihim söyle

Hangi ülkede postacılar

sakladı benim mektuplarımı

Kaybettiğim,eline geçmeyen

Bir sevgiliye karşı.', 'Sen bu işi       unutmayacaksın kara talihim Ölümün beni unutmadığı gibi Tutsaklığım onda Kahrın ta içinde benle beraber. bırak beni Baharı ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Selahattin Dalkıran']::text[], 8.5, '{"poet":"Eyüp Selahattin Dalkıran","poet_slug":"eyup-selahattin-dalkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hangi-ulkede-postacilar-sakladi-benim-mektuplarimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül güzelim', 'gul-guzelim-guner-kurt-hes8q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana ağlamalar yakışmaz ki	

Önünde çok baharların var	

Sen hep gül güzelim	

Kim girerse girsin 	o kapıdan

Seni ağlatmasınlar 	

Sen hep gül güzelim	

Gül ki çicek açtığını göresin	

Gül ki bahçende çicekleri deresin	

Ne mevsimler seni alsın savursun		

Ne üzüntü yüreğini kavursun		

Baharların ömrünce var olsun		

Bahçende bir tek çicek solmasın		

Sen hep gül güzelim		

Gününe güneş gönlüne eş

Güzellikler seninle olsun 		

Sen hep gül güzelim', 'Sana ağlamalar yakışmaz ki	 Önünde çok baharların var	 Sen hep gül güzelim	 Kim girerse girsin 	o kapıdan Seni ağlatmasınlar 	 Sen hep gül g...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gul-guzelim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gül', 'sen-gul-guner-kurt-q919g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gül sen gül ağlama

Göz yaşın hüznün kalsın bana	

Sen gül sen gül ağlama

Gülmeler sana gözyaşı bana	

Ölümdür ayrılık sonudur yaşam	

Gören gözdür dersen biter	

Gözden başkadır gören	

Ayrılık son bulur bulursan eğer	

Kıyamam hüzünle bakan gözlere	

Sen gül sen gül ağlama	

Göz yaşın hüznün hep kalsın bana	

Sen gül sen gül  ağlama', 'Sen gül sen gül ağlama Göz yaşın hüznün kalsın bana	 Sen gül sen gül ağlama Gülmeler sana gözyaşı bana	 Ölümdür ayrılık sonudur yaşam	 Gören...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-gul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çılgın Gönül Gazeli', 'cilgin-gonul-gazeli-vedat-sahin-rk5eu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllardır her kavgaya gözüm kapalı daldım 

Bir gün içimden kopan çığın altında kaldım 

Ve sonra adım çıktı sakıncalı birine 

Barutlara sokuldum insanların yerine 

Görünmekten kaçındım sulara bulutlara 

Veba gibi yaşadım düşmandım umutlara 

Başı boş itler gibi dünyayı arşınladım 

Bu da yetmezmiş gibi güneşi kurşunladım 

Dağlara çelme taktım uçurdum bakalları 

Şehirlere indirdim aç kalmış çakalları 

Kuyruklu yıldızları uçurtmama doladım 

Bir Eylül akşamında ısırganı daladım 

Meydanlarda kükredim kafa tuttum devlete 

Kuşluk vakti yürüdüm sürgün gittim gurbete 

Ve öyle gelip geçti güme gitti yıllarım 

Ve duruldum sonunda düze bitti yollarım 

Artık noktayı koydum bu çılgın kavgalara 

Yurdumda göç başladı ılıman yaylalara 

Götür beni yüreğim kaçır beni oraya 

Yoksa vuracak bir gün deli gönlüm karaya 

18.05.2001 Olching

Not: Şiir 08.02.2006 tarihinde 384 antolojim ile A Listesinin 27. sırasında iken gördüğüm lüzum üzerine tarafımdan silinip tekrar eklenmiştir.', 'Yıllardır her kavgaya gözüm kapalı daldım  Bir gün içimden kopan çığın altında kaldım  Ve sonra adım çıktı sakıncalı birine  Barutlara sokul...', ARRAY['Türk Edebiyatı','Şiir','Vedat Şahin']::text[], 8.5, '{"poet":"Vedat Şahin","poet_slug":"vedat-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cilgin-gonul-gazeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı', 'yalanci-guner-kurt-ppx50', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalancı yalancı		

Gözlerin vurur 		

Verir acı		

Bir gülüp bir ağlayan		

Yokmu ortası		

Yalancı yalancı 		

Sözlerin vurur		

Verir acı		

Bir gün ciddiysen		

Bir gün şakacı		

Yol ver 		

Önünden gideyim		

Müsaden olmazsa		

Peşin sıra geleyim		

Sevmek yürek ister bilirim		

O yürek bende var		

Sende var mı bileyim		

Yalancı yalancı		

Sözlerin vurur		

Verir acı		

Bir gün ciddiysen		

Bir gün şakacı		

Değişmene değil		

Benim bu sözüm		

Kararsız tutumlar	

Evetler hayırlar	

Sonra çaymalar	

Yalancı yalancı

Seni sevmek 

Hem tatlı hem acı

Yalancı yalancı', 'Yalancı yalancı		 Gözlerin vurur 		 Verir acı		 Bir gülüp bir ağlayan		 Yokmu ortası		 Yalancı yalancı 		 Sözlerin vurur		 Verir acı		 Bir g...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yalanci-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sade', 'sade-reyhan-tataroglu-54pu2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'üşümenin derinliğine düştüm

                      kaçarken alevlerle öpüştüm

                      her taraf mahşer yeri iken 

                      ben yalnızlığa dönüştüm', 'üşümenin derinliğine düştüm                       kaçarken alevlerle öpüştüm                       her taraf mahşer yeri iken               ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sade-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Faraş', 'faras-reyhan-tataroglu-7ogu1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'küllen yalan...

                                      küllen yalan...

                                      dedikçe aşkına

                                      alevlendi külüm

                                      açtı gülüm

                                      döndüm şaşkına', 'küllen yalan...                                       küllen yalan...                                       dedikçe aşkına                  ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/faras-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben şair değilim..! !', 'ben-sair-degilim-muhsin-yener-vh3qg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben ne Nazım Hikmet oldum

ne Ahmed Arif kadar yaralı bir ses,

ne Attilâ İlhan gibi gecelere yürüdüm,

ne de Can Yücel gibi asi bir kahkaha bıraktım dünyaya.

Ben şair değildim belki…

ömür boyunca tek bir dize bile yazmasam

yine de bir şair gibi yaşadım hayatı.

Bir şiiri okurken

kırıldım bazen içimden,

bazen bir mısrada kendimi buldum.

Yeri geldi

Nihal Atsız kadar serttim,

yeri geldi

Yusuf Hayaloğlu kadar yaralı.

Bir türkünün içinde kayboldum bazen,

bir kitabın sayfasında sabahladım.

Ve gün geldi…

kelimeler kendi yolunu buldu içimde.

Şiirler yazdım.

Kimi bir yüreğe dokundu,

kimi rüzgâr gibi geçti gitti.

Beğenilen de oldu,

sessiz kalan da.

Ama ben

yazmaktan vazgeçmedim.

Okumaktan, anlamaktan,

insanı sevmekten vazgeçmedim.

Çünkü yaşam nedenimi

kelimelerin arasında buldum ben.

Bulutları aştım sonra,

bir şiirin içinde ölümsüz oldum sanki.

Anladım ki

geriye kalan tek şey

sevebilmekmiş insanı.

Bu dünyadan göçüp giden

bütün şairlerin

mekânı cennet olsun.

Yaşayanlarınsa

kalemleri susmasın,

yüreklerinden

sevgi eksilmesin hiç.

Ben de buradayım işte…

bir şiirin kıyısında,

yüreğimle

sevgi bırakıyorum dünyaya.

Muhsin yener', 'Ben ne Nazım Hikmet oldum ne Ahmed Arif kadar yaralı bir ses, ne Attilâ İlhan gibi gecelere yürüdüm, ne de Can Yücel gibi asi bir kahkaha bı...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ben-sair-degilim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkar', 'cikar-kamer-taskin-ccn23', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çıkarını gör,

Çıkarını koru,

Çıkarını gözet,

Çıkarından sözet,

Çıkarmaya çalışsan,

Çıkarını aradan,

Çıkmaz.

Çıksa; 

Arkasından,

Çıkarsızlığın çıkar.', 'Çıkarını gör, Çıkarını koru, Çıkarını gözet, Çıkarından sözet, Çıkarmaya çalışsan, Çıkarını aradan, Çıkmaz. Çıksa;  Arkasından, Çıkarsızlığı...', ARRAY['Türk Edebiyatı','Şiir','Kamer Taşkın']::text[], 8.5, '{"poet":"Kamer Taşkın","poet_slug":"kamer-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cikar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-bulamadım', 'a-bulamadim-mikdat-bal-atge8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gurbetin yoluna düşdüm düşeli

Yönümü şaşırdım iz bulamadım

Hasret çadırında piştim pişeli

Bezlerim yırtıldı piz bulamadım

Umutlarım vardı işin başında

Gençtim dinamiktim yirmi yaşında

Sıhhati kaybettim elin işinde

Ovalarda bile düz bulamadım

Rüzgara kapıldım yönüm belirsiz

Umut istikbaldi önüm belirsiz

Sonsuz bir deryada sonum belirsiz

Hedef çok uzaktı tez bulamadım

Gönlüm diyordu ki doğrudur yolun

Güçlüsün sağlamdır kanadın kolun

Vatana millete yardımda bulun

Bundan daha gerçek hız bulamadım

Mikdadi der uzun sürdü bu sefer

Umudum tükendi nerede zafer

Ne şehit ne gazi oldu bu nefer

Söyleyecek başka söz bulamadım

Şair Mikdat Bal', 'Gurbetin yoluna düşdüm düşeli Yönümü şaşırdım iz bulamadım Hasret çadırında piştim pişeli Bezlerim yırtıldı piz bulamadım Umutlarım vardı iş...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/soz-bulamadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya - 2', 'ruya-2-elazigli-mustafa-kaya-xz66b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ölüm rüyaları görüyorum

bir çamura düştüm

toprağın ,

göğün ateşini tattım.

mezar taşlarında

çölün sıcaklığında yattım

uçmayı unutan

kelebeklere rastladım.

servilerden daha güzel ağaçlar

serap oldular

ruhumu kurutan

şimşekleri gördüm

ateşiyle dondum

ve uykularım kaçtı

göğe yükselen

ruhumu çağırdım

yakıcı ışığında

gerçeğin güneşinde buldum

bana gülen rüyalarla kayboldum .

Mustafa kaya

09.02.2006 / üsküdar', 'ölüm rüyaları görüyorum bir çamura düştüm toprağın , göğün ateşini tattım. mezar taşlarında çölün sıcaklığında yattım uçmayı unutan kelebekl...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ruya-2-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat müziğim', 'hayat-muzigim-elazigli-mustafa-kaya-bidvp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hayat dalım

hayat müziğim

arzularımın baharı

sevgilim,

gözyaşlarınla tazelenir

hasretim.

ruhumun kanatlanıp

vardığı yer

senin sabahların.

senin hüznün

duygularımı nağmesiz

bıraktı

hedefsiz ve ümitsiz

yalnızlığın

uykularımı kaçırdı.

gözlerinin ışığı

bulutlara kurduğun

hayallerin..

Mustafa kaya

09.02.2006 / Çengelköy', 'hayat dalım hayat müziğim arzularımın baharı sevgilim, gözyaşlarınla tazelenir hasretim. ruhumun kanatlanıp vardığı yer senin sabahların. se...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayat-muzigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kav', 'kav-reyhan-tataroglu-n9qq5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşkın bir kibrit çöpü

                              başında yansam

                              sonunu göremem

                              sonunda  yansam 

                              başa dönemem

                              ne yapsam ki...', 'aşkın bir kibrit çöpü                               başında yansam                               sonunu göremem                             ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kav-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan**', 'yalan-selma-sengoren-yrft9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hoşgörü bohçasını almışım elime,

Taşı taşıyabildiğince

Gülen gözler mi yalan

Kurşun sözler ne yaman

Gönlüm harman sevgi ile,

Yürüt yürütebildiğince

Düşünceler mi yalan

Davranışlar ne yaman

Merhameti şevkatiyle,

Fikri ile zikri bir olana

Özü sözü er olana

Sözüm yoktur mert olana

Yaşadığımız yer yalan,

Topraktır esas mekan

Her şey gelip geçici

İyiliğin hoş sedasıdır baki kalan..', 'Hoşgörü bohçasını almışım elime, Taşı taşıyabildiğince Gülen gözler mi yalan Kurşun sözler ne yaman Gönlüm harman sevgi ile, Yürüt yürütebil...', ARRAY['Türk Edebiyatı','Şiir','Selma Şengören']::text[], 8.5, '{"poet":"Selma Şengören","poet_slug":"selma-sengoren","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalan-981-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Yeter Ama', 'artik-yeter-ama-ramazan-ates-0c0bm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırkbeş yıldır uğraşırım,

Tanısınlar beni gayri.

Burda doğdum yaşlanırım,

Tanısınlar beni gayri.

O tanımak istemiyor,

Yabancıyım hep gözünde.

Neyim varsa hep görüyor,

Tanısınlar beni gayri.

Yıllar yılı gayret ettim,

Umulmadık taviz verdim.

Neyim varsa hep terk ettim,

Tanısınlar beni gayri.

Artık ısrardan vaz geçtim.

Ben buyum, ben böyleyim,

İşine gelen tanır beni,

Tanımayan kendi bilir.

Artık umurumda değil.

Ramazan Ateş/Enschede-8.2.2006', 'Kırkbeş yıldır uğraşırım, Tanısınlar beni gayri. Burda doğdum yaşlanırım, Tanısınlar beni gayri. O tanımak istemiyor, Yabancıyım hep gözünde...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/artik-yeter-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce Fikir', 'dusunce-fikir-kamil-at-ki6u4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşünce Fikir

Ben senin düşünceni bilirim

Önce öğrendim, sonra eledim

Benim Düşüncem ise,

Senin o kül kafana girmez...', 'Düşünce Fikir Ben senin düşünceni bilirim Önce öğrendim, sonra eledim Benim Düşüncem ise, Senin o kül kafana girmez......', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dusunce-fikir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kalp Beni Taşımıyor', 'bu-kalp-beni-tasimiyor-ramazan-ates-tqxk2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yorgun düştü garip gönlüm,

Taşımıyor beni gayri.

Yüreğime geçmez sözüm,

Taşımıyor beni gayri.

Ritmi bozuk, bozuk çalar,

Uyutmuyor çok acı var.

Hem acı var hem sancı var,

Taşımıyor beni gayri.

Yıllar yılı hiç gülmedi,

İçten içe çok inledi.

Acılara o yenildi,

Taşımıyor beni gayri.

Bir gün durdu duracak,

Acılardan hissediyom.

O da artık kurtulacak,

Yorgun düştü kalbim gayri.

Taşımıyor beni gayri.

Ramazan Ateş/Enschede-6.2.2006', 'Yorgun düştü garip gönlüm, Taşımıyor beni gayri. Yüreğime geçmez sözüm, Taşımıyor beni gayri. Ritmi bozuk, bozuk çalar, Uyutmuyor çok acı va...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bu-kalp-beni-tasimiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılarımın Çetelesini Tutmadım Hiç', 'acilarimin-cetelesini-tutmadim-hic-melih-coskun-qksd5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acılarımın çetelesini tutmadım hiç

Ya da çıkartıp kılıcımı kınından 

Savaşmadım tek başıma   

Gecenin üzerime saldığı hüzünlerle

Dünyada yazılmış bütün şiirleri ezbere bilip de 

Tek bir dize yazamayan adam kadar garip 

Yahut usta bir şairin 

Yüzlerini bile görmediği insanların yaralarını sarıp

Yanı başındakilere duyuramadığı ses kadar derin 

Şizofren bir sayıklama gibi belki de 

Ceylan bakışlı bir sevgili yaratıp satırlarında 

Sonra onun için geceler boyu uykusuz kalmak

Hayır 

Acılarımın çetelesini tutmadım ben hiç

Oynamadım da hiçbirinizin yaralarıyla 

Ne demir kapıları pas tutmuş karanlık zindanlarda yattım 

Ne iğrenç ıslığını duydum ıslak bir sopanın 

İnerken ense köküme 

Peki nedir o zaman 

Şu kahrolası dünyayla alıp veremediğim 

Her gece boğazımı saran bu yağlı urgan 

Hiç kimse duymadığı halde 

Kulaklarımı sağır edercesine çınlayan o ses. 

Oysa o kadar sessiz ki geceleri bu şehir

Ve odam o kadar huzurlu

Ne bir polis sireni 

Ne kırılan camların karanlığa savruluşu. 

Yine de mümkün mü sanıyorsunuz

Mil çekip yüreğimin gözlerine

Kendi vicdanımın yüzüne tükürmek

Mümkün mü 

Kenarı desenli kağıtlarda aşkı ağlatmak 

Kolay mı be dost 

Sadece kendi acılarımın çetelesini tutmak…

2005', 'Acılarımın çetelesini tutmadım hiç Ya da çıkartıp kılıcımı kınından  Savaşmadım tek başıma    Gecenin üzerime saldığı hüzünlerle Dünyada yaz...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/acilarimin-cetelesini-tutmadim-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku Vize Koymuş', 'uyku-vize-koymus-ramazan-ates-uubzc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerime vize koymuş,

Uykulara geçemiyom.

Şartları çok ağır olmuş,

Kolay vize alamıyom,

Uykulara geçemiyom.

Acılarım dinmeliymiş,

Yüzüm artık gülmeliymiş.

Düşünceler gitmeliymiş,

Yoksa vize alamıyom,

Uykulara geçemiyom.

Ağlamayı unutmalı,

Elem, keder yok etmeli,

Yalnızlığı hapsetmeli,

Yoksa vize alamıyom,

Uykulara geçemiyom.

Düşünceyi rafa koyup,

Tüm geçmişi unutmalı,

Huzur ile yatmalıyım,

Yoksa vize alamıyom,

Uykulara geçemiyom.

Ben bunları ne yapayım? 

Boş ver uykusuz yatayım! 

Ben, ben isem hep böyleyim,

Ben ne vize istiyorum,

Ne uykuya geçiyorum.

Ramazan Ateş/Enschede-7.2.2006', 'Gözlerime vize koymuş, Uykulara geçemiyom. Şartları çok ağır olmuş, Kolay vize alamıyom, Uykulara geçemiyom. Acılarım dinmeliymiş, Yüzüm art...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/uyku-vize-koymus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meleklerden Muteber', 'meleklerden-muteber-lokman-hamitoglu-utrhi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'MELEKLERDEN MUTEBER

Kur’an’ı yol etmeyen boyun eğmiş küfüre

Dininden utanmayan yol veriyor kafire! 

Ulan senin Rabbin kim? Söyle Yaradanın kim? 

Neden yaltaklanırsın şu utanmaz kafire? ! ? 

En büyük şeref  kimin... En öndeki Peygamber

Kimdir şu semalarda Meleklerden mutaber

Sen hangi ümmettensin? Dinin ne? Kitabın ne? 

Okunan şu Ezan’dan hiç almazmısın haber? ! ? 

                                     Lokman HAMİTOĞLU', 'MELEKLERDEN MUTEBER Kur’an’ı yol etmeyen boyun eğmiş küfüre Dininden utanmayan yol veriyor kafire!  Ulan senin Rabbin kim? Söyle Yaradanın k...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/meleklerden-muteber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Ayrıldık', 'biz-ayrildik-suleyman-yavuz-yx6nu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrıldık şimdi seninle 

Geride bir sen ve bir ben kaldı

Biz ise ayrılık aldı

Yerine biten bir aşk

Ve bu aşktan arta kalan bir kaç anı kaldı

Ve bitti biz bittik biz

Şimdi geride bir sen birde ben kaldık

Evet, ayrılık fırtınasına kapıldık

Evet, anladım anladın anladık

Biz ayrıldık', 'Ayrıldık şimdi seninle  Geride bir sen ve bir ben kaldı Biz ise ayrılık aldı Yerine biten bir aşk Ve bu aşktan arta kalan bir kaç anı kaldı ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/biz-ayrildik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedin', 'gelmedin-kamer-taskin-u93wk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oynamaya dedin,

Eğlenmeye dedin,

Geçti saatler,

Gelmedin.

Buluşmaya dedin, 

Kavuşmaya dedin,

Geçti günler.

Gelmedin.

Çalışmaya dedin,

Dinlenmeye dedin,

Geçti yıllar. 

Gelmedin.

Hep beklettin,

Hasretleri eskittin,

Geldi geçti bir ömür,

Sen gelmedin.', 'Oynamaya dedin, Eğlenmeye dedin, Geçti saatler, Gelmedin. Buluşmaya dedin,  Kavuşmaya dedin, Geçti günler. Gelmedin. Çalışmaya dedin, Dinlen...', ARRAY['Türk Edebiyatı','Şiir','Kamer Taşkın']::text[], 8.5, '{"poet":"Kamer Taşkın","poet_slug":"kamer-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelmedin-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müebbet Ver Bana', 'muebbet-ver-bana-ramazan-ates-c689g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Niye beni mahkum ettin? 

Söylesene, gözlerine.

Suçum neydi, hapis ettin? 

Kelepçeyle, ellerine.

Önce tuttun ellerimden,

Sonra sardın gözlerinle.

Düğümledin sözlerinle,

Mahkum ettin yüreğine.

Neydi suçum? Niye tuttun? 

Yüreğim ateşe attın.

İdam mahkumu yaptın,

Hapis ettin yüreğine.

Hapisliğim son bulmasın,

Ordan başka yer görmesin.

Sakın ama af gelmesin,

Hep durayım yüreğinde,

Ben mutluyum o hücremde.

Ramazan Ateş/Enschede-8.2.2006', 'Niye beni mahkum ettin?  Söylesene, gözlerine. Suçum neydi, hapis ettin?  Kelepçeyle, ellerine. Önce tuttun ellerimden, Sonra sardın gözleri...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/muebbet-ver-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havalardayım', 'havalardayim-reyhan-tataroglu-vvfqi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevdalandım

                                          her gördüğüme 

                                          göremediğime

                                          senin için sevdalandım

                                          sarpasarsamda dönsem

                                          kördüğüme

                                          önemli değil ki neyi sevdiğim

                                          önemli değilmi sevdiğim

                                          sevmek sen...

                                          ben ise sev dediğin...', 'sevdalandım                                           her gördüğüme                                            göremediğime                 ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/havalardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elif Kumru...- Akrostiş', 'elif-kumru-akrostis-halide-selcan-karagul-l9dle', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elif Kumru

En sonunda gelebildin dünyamıza teşrif ettin

Leylak kokusunu etrafa saçtın mis gibi yaptin

İyi ki doğdun bekleyenleri sevindirdin

Ferah doldu yürekleri mutluluğa eriştirdin

Küçücük miniciksin kumru kadar narinsin

Uçamazsın henüz erken, sen minicik bebeksin

Melek kadar  günahsızsın, masumsun 

Rüya gibi geldin tüm yürekleri sevindirdin

Umut verdin gönüllere sen ne şirin bebeksin...

08.02.2006', 'Elif Kumru En sonunda gelebildin dünyamıza teşrif ettin Leylak kokusunu etrafa saçtın mis gibi yaptin İyi ki doğdun bekleyenleri sevindirdin...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/elif-kumru-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki damla göz yaşı 2. Bölüm', 'i-ki-damla-goz-yasi-2-bolum-ayhan-isin-gshut', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.......................O yaz çok sıcaktı sanki her yer kavruluyordu. Yirmi yedi yıldır bu kadar sıcak yaşamamıştı Anadolu. Hele, hele Güney bölgeleri; gölgede sıcaklık elli dereceyi geçmişti. Çöl sıcakları desek doğru olurdu. Yaşlı adam zeytin ağaçlarının gölgesine oturmuş; ta eskilere gitmişti yine böyle sıcak bir gündü karısı evde köyün ebesi komşu kadınlar sağa sola koşuşuyorlardı. Kendiside Allaha yalvarıyor ne olur Yarabbi onlara yardım et diyordu. Kasaba doktoru da yoktu. Acil bir yaralı için gitmişti. Bu arada bir çığlık sesi duyuldu karısının sesiydi içi parçalandı ezildiğini hissetti! Sonra bir bebek ağlaması hayatında iki kere bu kadar sevinmişti. Bir evlendiği gün. Bir de bugün. Ebe göründü kapıdan. Patiska beze sarılmış bebek elinde kucağına veriyordu. Ebe,  bir şeyler söylüyordu ama o sadece karısının iyi olduğunu anlayabildi. Pembe bir bebek bir şeyler arıyor gibiydi yüzü gülüyordu yumuk, yumuk elleri vardı Allah’ıma şükürler olsun hayatta tek Arzu ettiğim varlık benim Çocuğum!  Ebe kız dedi. Tanrım Bir kızım oldu, bir kızım bir kızımmmmmmm!  ARZU olsun ismi Arzularımın, ARZU’SU Besmele çekti salâvat getirdi. Ezan okudu üç kere kulağına ARZU, ARZU, ARZU! Dedi. Hey gidi günler heyyyyy ne günlerdi bir iç çekti. Sonra yüce dağa baktı o yılda çok sıcaktı, karlar erimişti Arzu’nun doğduğu yıl.

.......................Sıcak yüce dağın karlarını, buzlarını eritmiş dağın çıplak çirkin yüzü açığa çıkmıştı. Ama belki de biraz böyle kalması kasabanın manzarasını değiştirmişti. Bazen değişiklikte lazımdı. Kasabanın pınarı bile kurumak üzereydi. Arzu ile Kemal’in Kartopları yani Aşklarının simgesi de erimek üzereydi. 

İki gözyaşı birbirlerine sarıldılar dayanmalıyız ayrılmamalıyız diyorlardı. Ne oldu yoksa sözler unutuldu mu? Diye birbirlerine sordular. Neden, neden, neden? Ben seni hala seviyorum! Bende seni ama bir şeyler yapmazsak kötü şeyler olacak gibi geliyor. Neden se! Ben de aynı şeyleri hissediyorum. O ZAMAN Erimeliyiz ama ne olursa olsun ellerimi bırakma sende benim elerimi söz mü? Söz! Belki aşkımız için kısa bir süre olabilir. Sadece aşkımız için!

.......................El ele tutuştular eridiler. Arzu ile Kemal’lin yaptığı gibi çayırların çimenlerin arasından süzüldüler. Yoruldular küçük gölcüklerde dinlendiler. Güneş yakıyordu bedenlerini ama onlar durmadılar. Kasabanın pınarından çıktılar. Buraları hatırlıyor musun? Dedi, hiç unutmadım ki! Dedi göz damlaları. Aktılar, aktılar son anda bir keçinin dilinden zor kurtuldular. Sonra geniş bir nehir e ulaştılar artık çok yavaşlamışlardı. Derinlerden gitmeliyiz güneş bizi almadan sakın ellerimizi bırakmayalım. Derinlerde balıklar yosunlar harikaydı her şey hayal bile edemezlerdi. Biraz çamur kaplanmıştı kurbağalar dalıp, dalıp çıkıyorlar kuşlar suyun yüzünde yüzüyor ayaklarını heyecanla çırpıyorlardı. Bir baloncuğun kenarına tutundular. Karşıdan iki balık tartışa, tartışa geliyordu. Beli ki seviyorlardı birbirlerini! Uyum içinde yüzüyorlardı. Sen beni aldatıyorsun diyordu biri diğerine. Öbürü aman bıktım senin dırdırından derken baloncuğu kapıverdi! Gözyaşları birden şaşırdılar balığın solungaçlarından atıldılar. Oh derin bir nefes aldılar! Yine beraberdiler. Balık birden değişiverdi. Aşkım özür dilerim öğle demek istememiştim, seni seviyorum seni bir daha kırmayacağım seni sonsuza kadar seveceğim. Bende seni çok seviyorum. Damlacıklar şaşırmış birbirlerine baka kaldılar biz mi yaptık diye! 

EVET! EVET! Bizim Aşkımız bunu başardı! Hay di yüzelim daha çok yolumuz var. Arzu’yla Kemal’i bulmamız lazım! 

.......................Yüzdüler, yüzdüler şimdi su daha da berraktı aynı kendi tatları gibi. Uçsuz bucaksız Masmavi hava çok rüzgârlı oyana buyana savruluyorlardı. Sonra çok kötü sesler duymaya başladılar. Gümmmm  şowwwwwww bana sıkı tutun bırakma birden kendilerini bir kayanın üzerinde buluverdiler. 

.......................Güneş, rüzgâr kavuruyordu birden çok hafiflediklerini hissettiler. Ne oluyor bize? Sıkı tutun uçuyoruz sarıl bana sevgilim daha sıkı sarıl!  Kendimi çok büyümüş hissediyorum! Ben de!  Evet, böyle daha iyi bütün dünya ayağımızın altında biz niye bunu daha önce düşünemedik. Ama güzel bir seyahat ti tecrübe kazandık. Şimdi hedefimize daha kolay ulaşabiliriz, rüzgâr bize yardım ederse. Rüzgâr esti dedi ki ben sevenlere her zaman yardım ederim. Yaşasın dediler. Seni seviyorum Aşkım! Ben de Seni Aşkım! Rüzgâr dedi ki Arzu ile Kemal’li gördüm. Şu her zaman buluştukları ısız kumsaldalar. Tabi siz nereden bileceksiniz. Ben sizi götüreyim. Beraber uçtular, uçtular akşam olmak üzereydi. Bütün bulutlar toplanmıştı ne olacaktı şimdi. Damlacıklar ne yapacaklarını biliyorlardı. Rüzgâra fısıldadılar. Arzu ile Kemal tartışıyorlar birbirlerine kötü şeyler söylüyorlardı. Anladıkları kadarıyla ayrılmayı düşünüyorlardı. Damlacıklar çok üzüldüler. Tam zamanında gelmişlerdi. Bazen cesaretli ve ani kararlar işe yarayabiliyordu. Bütün bulutlar damlacıklara değmez hiç bir yararı yok! Diyorlardı. Peki, ne olmuştu da böyle ayrılmayı düşünüyorlardı? Sonsuz Aşk neden tükenmişti?         			

09-02-2006', '.......................O yaz çok sıcaktı sanki her yer kavruluyordu. Yirmi yedi yıldır bu kadar sıcak yaşamamıştı Anadolu. Hele, hele Güney ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Işın']::text[], 8.5, '{"poet":"Ayhan Işın","poet_slug":"ayhan-isin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iki-damla-goz-yasi-2-bolum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte gerçek, işte yalan', 'i-ste-gercek-iste-yalan-mikdat-bal-zyqvl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boykot boykot derken hepsi

İçtikleri Cola pepsi

Cikolata dolu tepsi

İşte gerçek, işte yalan

Bin dört yüz yıl düşman bunlar

Kanımızla şişman bunlar

Asla değil pişman bunlar

İşte gerçek işte yalan

Dün nerdeydik yarın nerde

Gözlere mi indi perde

Mü''minlerin kanı yerde

İşte gerçek işte yalan

Kurulmayın ikide bir

Sarhoş sarhoş etme tekbir

Dinde baskı yok ne cebir

İşte gerçek işte yalan

Yüz binlerce hakaret var

Yıkmak için çok gayret var

Medya sunmuş da hayret var

İşte gerçek işte yalan

Müslümanı kurmasınlar

Üstümüze varmasınlar

Yolumuza durmasınlar

İşte gerçek işte yalan

Daha dündü Selman Rüştü

Kim korudu böyle puştu

Aniden gündemden düştü

İşte gerçek işte yalan

Bunda herkes rant peşinde

Mutlak hile var işinde

Ey müslüman bir düşün de

İşte gerçek işte yalan

Mikdati der aç gözünü

Ey müslüman bil kozunu

Nerden aldın süt tozunu

İşte gerçek işte yalan', 'Boykot boykot derken hepsi İçtikleri Cola pepsi Cikolata dolu tepsi İşte gerçek, işte yalan Bin dört yüz yıl düşman bunlar Kanımızla şişman ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/iste-gercek-iste-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet Bizi Ey Sevgili...', 'affet-bizi-ey-sevgili-hatice-guler-hcvd6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana dil uzatmış zalim

İncitmiş seni 

Yüreğimden hançerlendim

Sensizliğime bir yara  daha aldim

Gül boynunu büktü bükeli

Gül çaresiz

Bülbül suskun..

Gölgelerim Sensiz

Dualarim Sensiz

İnsanlığım çaresiz

Sevdam öksüz

Hasretim Sensiz

Sevinçlerim mahzun

Ruhum garip....

Affet bizi ey Sevgili...', 'Sana dil uzatmış zalim İncitmiş seni  Yüreğimden hançerlendim Sensizliğime bir yara  daha aldim Gül boynunu büktü bükeli Gül çaresiz Bülbül ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Güler']::text[], 8.5, '{"poet":"Hatice Güler","poet_slug":"hatice-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/affet-bizi-ey-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekle Düş Arasında', 'gercekle-dus-arasinda-birsen-ates-a5zyj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'inadına

düştüm sevinin peşine

bırakmadım özlemlerimi

şubat mı ağır ağır donmakta

yoksa ruhum mu

üzerime

sinmiş kokun henüz bendeyken 

gittin çoktan sonsuzluğa

unutamadığım

şimdi

ben sensiz

gerçekle düş arasında

kaybolduğum günlerde

anlamını yitirdiğim zamanların

son bulduğu güzelliklerdeyim

09.02.06

gitsen de

ben hep sendeyim

noktanın sonsuzluğunda

bıraktığın yerde

y a l n ı z ı m', 'inadına düştüm sevinin peşine bırakmadım özlemlerimi şubat mı ağır ağır donmakta yoksa ruhum mu üzerime sinmiş kokun henüz bendeyken  gittin...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gercekle-dus-arasinda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kullanıyorlar', 'kullaniyorlar-suheyl-turkoglu-hdxml', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sardı gökyüzünü,

Geçen bulutlar.

Karartıyorlar.

Önce bora,

Sonrasında yağan

Nifak tohumları.

Mürekkep gibi

Karartırcasına,

Aydınlığa yağıyorlar.

Şaka gibi,

İnanamıyorum,

Ne yapıyorlar? 

Dine saygısızlık,

Son kozları,

Kullanıyorlar.', 'Sardı gökyüzünü, Geçen bulutlar. Karartıyorlar. Önce bora, Sonrasında yağan Nifak tohumları. Mürekkep gibi Karartırcasına, Aydınlığa yağıyor...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kullaniyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Bir Faişe', 'hic-bir-faise-yilmaz-yigiter-0bhk8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Derinden tırkan izleri var,avuçlarım kanıyor

Geride 35''lik bi faişe bıraktım 

Ucuz,bayat tekel rakısı niyetine

Ama Hiç biri o duvarı nemli, o kötü kokulu 

o soğuk motelde becerdiğim

Gördüğümde beni sana hatırlatan faişenin tadını,zevkini vermiyor bana,

Lanetlerle bezenmiş beyin damarlarımdan akan kan 

Vücudumda azgınca dolasıyor

Kar yağıyor üstümüze 

Her tanesi tenimi yakıyor

Sehvetlice 2 nefes cigara çekmişim ciğerlerime 

1 yudum şarap allığı kanımdan kara 

çekmişim başım fena halde uyuşmuş bedenimin üstünde sızlanıyor

Uyku bastırıyor derinden, ebedi bir uyku 

Bir sefere çıkmısım yorgun,ağır vücudumla

Bi çok sokakta mola vermişim 

Adını o sokakların caddelerine kazıyarak her bir kaldırıma iz bırakmışım 

Cesedim Kolay bulunsun

Son durağa geldim artık 

Bu göz alıcı yeşil çimenlik üzerine kazılmıs topraga 

Boylu boyunca uzandım 

Yağmur üzerimi örttü, üşümiyim diye kara toprakla 

Derin bir uykudayım 

Ahh gözlerinin içindeki kara toprakta 

Sebepsizde uyuduğumun 

                        FARKINDAYIM', 'Derinden tırkan izleri var,avuçlarım kanıyor Geride 35''lik bi faişe bıraktım  Ucuz,bayat tekel rakısı niyetine Ama Hiç biri o duvarı nemli, ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Yigiter']::text[], 8.5, '{"poet":"Yılmaz Yigiter","poet_slug":"yilmaz-yigiter","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hic-bir-faise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmadık', 'unutmadik-mehmet-ali-demircan-hvvnk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şafak vaktinde

Kızıl ateşler

Şakaklar delik

Bedenler ezik

Güller yağlı urganda

Yürekler suskun.

Yıkıldılar 

Gençliğin baharında

Bedenler özgürlüğe feda

Diller, eller niyazda

Umutlar

Kara toprakta.

Diller suskun

Sözler hançer yarası

Gözler kan deryası.

Dersim de barut kokusu

munzur da sevgisizlik seli

An/kara da

yürekler yangın

canlar suskun.

Baharlar kara kışta. 

Dar ağaçları utanç abidesi 

Dalında solmuş güller

Dillerde ağıtlar

Ağlaşıyor bülbüller

Adalete kızgın

Küskün yürekler. 

Unutma / dık

Unutma / yacağız

Yürekler de

Yaşayacak

Hüzünlü hasretimiz.

''Halk için, Emek için, özgürlük için mücadelede kaybedilen Tüm Fidanlarımıza ithafımdır.''

MAD. 10,01,2006 - 24,30

MADemircan.*Radyoerguvan.com

*** Aynalar Gerçeklerin Ta Kendisidir.

Konuş onunla, Doğruyu Söylemekten Çekinmeyecektir. ***', 'Şafak vaktinde Kızıl ateşler Şakaklar delik Bedenler ezik Güller yağlı urganda Yürekler suskun. Yıkıldılar  Gençliğin baharında Bedenler özg...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Demircan']::text[], 8.5, '{"poet":"Mehmet Ali Demircan","poet_slug":"mehmet-ali-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/unutmadik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kehanet Değil', 'kehanet-degil-birsen-ates-szffj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kinle salınmış tohumlar evrene

tek bir lokma bulamayan çocuklar

uyumaya çalışırken açlıktan

üretin yeni silahları doldurun 

insanları birbirine kırdırın

martta iran inatla nükleer denemede

yakında çok yakında

muhtemel bir savaş insanlığı beklemekte

ne oluyor artık

bir duyan yok mu

bu gidişle

yine çığlıklar saracak evreni

artık ipi çözülmüş ülkelerin

bunların hepsi bir oyun

oturup bir düşünelim

basmayalım faka

sanmayın bu dizeler bir şaka

yakında başlayacak din savaşları

belli ki çizilmiş kader

acı ama gerçek

insanoğlu bu azgınlığıyla

yakında kendi başını yiyecek

09.02.06', 'kinle salınmış tohumlar evrene tek bir lokma bulamayan çocuklar uyumaya çalışırken açlıktan üretin yeni silahları doldurun  insanları birbir...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kehanet-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakıp da gitme beni', 'birakip-da-gitme-beni-mikdat-bal-6q16p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensiz artık yaşayamam 

Bırakıp da gitme beni

Ben bu yükü taşıyamam 

Bırakıp da gitme beni

Gece gündüz düşümdesin

Gönlümdesin başımdasın

Önümdesin peşimdesin

Bırakıp da gitme beni

Gönlüm hicran benzim soluk

Yaşlar akar oluk oluk

Sensin nefes, sensin soluk

Bırakıp da gitme beni

Kasırgalar gibi aşkın

Volkan lavı gibi taşkın

Beni böyle şaşkın şaşkın

Bırakıp da gitme beni

Mikdati der gel de bana

Gel beimle öl de bana

Yanlız benim ol de bana

Bırakıp da gitme beni', 'Sensiz artık yaşayamam  Bırakıp da gitme beni Ben bu yükü taşıyamam  Bırakıp da gitme beni Gece gündüz düşümdesin Gönlümdesin başımdasın Önü...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/birakip-da-gitme-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Günceleri', 'gece-gunceleri-birsen-ates-tt97u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sabahlıyorum yine

sanrılı gecenin kollarında 

uykusuzluğum

dökülüyor  anılarım

sana dair özlemlerim

gece bitmiyor

canlanıyor içimde gidişin

yüreğimin

tam orta yerinde saplı

son bakışların

saymıyorum günleri

yokluğunda 

buradaymışsın gibi

yaşıyorum şiirlerde seni

09.02.06', 'sabahlıyorum yine sanrılı gecenin kollarında  uykusuzluğum dökülüyor  anılarım sana dair özlemlerim gece bitmiyor canlanıyor içimde gidişin ...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gece-gunceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekmek çakmağı', 'ekmek-cakmagi-akin-akca-tflsh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O bıçakla kimi yakacaksın...

Demin düşünen seni sigaramı 

kesmiştim ıslak onla; 

kenarı köşesinde mutfak ocağının,

bu ocaktan

uzanan duyarlı ama duvarsız, 

gaibin koridorunda salona..

(biliyorum bırak(sa)  malıyım)

elimde parmak, parmağımda sigara.

duvaksa dönüşlere,

 sen bekliyorum...', 'O bıçakla kimi yakacaksın... Demin düşünen seni sigaramı  kesmiştim ıslak onla;  kenarı köşesinde mutfak ocağının, bu ocaktan uzanan duyarlı...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ekmek-cakmagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sormamalısın', 'sormamalisin-akin-akca-wfnmm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saklamamalısın aşkını, yaşamalısın.

Bir kez mi sevdin, daha sevecek misin, pek bilemezsin

Ama bana bakman lazım

O zaman, bunu sormayacaksın.

Şu şiirindeki gibi çağdaşımız bir kadın şairin:

“Compulsory Antedepressants 

We won''t take anymore 

of these anti-depressants; 

(It''s worse than depression.)

You think we''ve lost our reason... 

seeing as we''re refusing... 

But who the hell has tries them? 

and who the hell can damn them.

zorunlu antedepresanlar 

daha fazla bu anti-depresanları almayacağız. 

(Depresyondan kötü)

Sebebimizi kaybettiğimizi düşünüyorsun 

Birbirimizi reddettiğimizi görürken. 

Fakat hangi lanet olasıcalar bunu deniyor, 

ve hangi kahrolasıcalar buna lanet ediebilir”

Hadi uy bakalım şimdi sözlerine; uç, uyma cinsine.

Bu şiirden sonra da bunu diyebilir misin.

O zaman kınından çıkar

Ve saldır …

Kırkbeşlik magnum ikindileri yağmuru Dirtty Harry’nin,

Beş çayı hazır.

Cheshire kedisinden ürkme

Aradaki şiir ve çevirisi Carol Batton adlı şairden. Çevrisi benden

Sevgiler candostlar', 'Saklamamalısın aşkını, yaşamalısın. Bir kez mi sevdin, daha sevecek misin, pek bilemezsin Ama bana bakman lazım O zaman, bunu sormayacaksın....', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sormamalisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şef Seba Baybou (masalsı)', 'sef-seba-baybou-masalsi-akin-akca-ta68n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok evreli uyku, uyku bozukluklarında kolay dalışı sağlayan kendine, bir yetebilirlik; ancak bilmiyor sevgili ayaklarının üşüdüğünde, donmadığını kafa kısmının bu sebepten. Ortalık soğuksa ne oldu sanki, sığ uyku 5 dakika kesin sürecek, ama REM uykusu –daha sonra gelen ardışık- 5’ - 3o’ dakika’ya değin olması gereken, 5o dakikayı buluyordu bazı seferler Ve artık sanırım 55’ten, bir saati bile

zong®uyor. Cortex, asla düşünmeyi bırakmayan, boşa kürek çekmiyor, ama sanki tüm hareketlere hakim oldu artık. REM safhasında tüm zihin onarılıyor uykuda, ayrıyeten gele dair anılarnda senin ya da planlarında da düzetmeler. Peki ne, Ay’a götüren bizi bunlar mı oluyor yoksa ayak basan Ay’a, Gagarin’in Armstrong’undan hani, Jules’ten; ilk uçan Türk pilotu ya da yerin merkezinden dönen-demir eriyik sağan o elek değildi de, rüyalarımız mıdır? Veya uyku gördüğümüz kısım, güncel yaşamadığımız kısımları mızdır? Yine de, ilk safha o uyku bozuntusu’yla, geçişle; REM arasında bir fark var. Bizi fark ettirenler arasında, Ortadünya’da; uyumakla uyanmak pek benzer olmamalı gibi ve/fakat yani …

Aşağıda ne yapıyor Baybou, namı diğer Bolu Beyi. Boa cinsinden kapkaç anakondagillerden, tılsımını geçiş(g) en rüzgarın bekiyor.. kar üstünde piti piti izler pati… Ve bir kök: görebilir! Karın altında ama kendisi –astar.. ki kah de ‘kılıf’ ona- suyun yüzünde: birkaç dal, bir gövde üzerinde.

Bir bitkinin etrafında bağdaşını kurmuş, ‘Gündüz Gözü’ arkadaşını yeni edinmiş, kabilesini ise yakında kuracak. “Sevginin Işığı” adı annesinin. Şimdi değiş tokuş etti piposunu, ikinci bir elden gelen diğer bir barış çubuğuyla, diğer yeni kabile üyesi Xanho Alukas’tan …

Oturan Boğa Baybou, karın hikmetini biliyor, ışıtanında zerrelerinin güneşin beyazın denklik yakamoz orijini bir izotropik homojenide: Oturan Boğa olunmaz ki, karşı olmayarak matadorluk vahşetine, e yalan mı? Çünkü oturunca saldırmaz, tribüne atladı yarım tonluk Meksika’da “Küçük Kuş”, sonrasında saplandı ensesine bir pala, her zamanki şer, aşikar şekliyle! Ah, Küçük Kuş, atla anneyin kollarına Küçük Kuş. açık susam, açıl; * istersen nick değiştir de gel, Minik Kuş …* yeter ki gaza gel, olma tuş.

Nehir Çiçeği’ni bükme, Nergis’i! …

“ehircan”daki KızılderiliYıldız, altın gibi alıp toplarsan mücizelerini hayatın ve dalından sökersen; Ehircin olacak, burnun Midas gibi bükülecek, düşüverecek ve yeni çıkan, çok daha uzun olacak! yok seyredersen, güzel mi güzel Kızılderiliyıldız, Zardoz’un o giz labirentleri’ ndeki kristalize yapıya pek benziyor, ve hep öyle kalacak hatırat sandukalar, Pandora değil.

Gene de Ehricn’i aramalı, aramak için aramalı, ya da bulmak için, fakat doğa’nın muhteviyatı bozmamalı! ! Guneydenus, bunu fark etmişti çok önceleri ve yardımıyla bazı seferler Xhantia’nın, Carotte’lerin merkezindeki o Mağranın Alimi’ni görmeye gitmişti,sormak, yerini öğrenmek için Ehricn’in.

Bazı geceler yol çok uzun olur okyanusta: fırtınalar; sulu sepkenler, gemiye… Gökten büyükçe bir kuş geçti, o ‘All batros Balık-Akrepyal’ işte, ama bir inci fırlatıp attı, gönüllerimize! ! ! Ve anladılar ki, oradadır Ehricn. Onu bulmaya balıkadam kıyafetlerini ve dalgıç teçhizatlarını kuşandılar. Su soğuktu, ama Ege gibi; poyraza hemen alıştılar. İnciyi topladıklarında, “Sevginin ışığı”nı keşfettiklerini anladılar. Önce değil …

:Balık-Akrepyal klozete tel atacağım der, atmaz; denize inci atacağım demez, atar. Akreptir ama balık, saat içince döner, döner …

! ! ! 

Haber salındı dağdan, üfürük büyük duman.

Doğan Güneş’in kocası herkese güvenir,

Hademeyle vali arasına sınır koymayan,

Tanırım yakınen seni, damarımdan şah,

Zengin olmayı beceremez, fazla verici.

Çarşamba günü, yelken yine sabah

Açıdı fikirlerime.. bak, aynı program

Çıktı şimdi.. gene, canlı CNN Türk’te,

“Her Evde 1 Haber”, değilmişiz birhaber.

Selahattin Kalaycıoğlu, sen ne kadar

Da benziyorsun Kızılderililere, söyle hele.

(Önce o itfaiyeci adam ki son derece

Sessiz, sakin, tutarlı ama şaşkınca

Alıp götürülen Cemil İpekçi huzurlarına; 

N’doğuştan çiziyor, stilist gönüllü o

Eve döndüklerinde, boş vakitlerince

Ya da şu Korkuteli’li Sinan, ne muazzam) 

“Kesmeye kıyamıyorum bu uzun, gri

Saçları.” Berber söyledi ilk, ona bunları.

İçindeki güçlü duygular hep vardı

Ve şimdi şeklini anlamasıyla, birleşti.

Hatice kalaycıoğlu’na göre ki annesi:

“Kızılderililer geçerken düşürmüşler

Yayladan buldum, topladım, büyüttüm..”

Üç sene aldı sislerin ardından Boluluların,

Domuzeti yiyip içmeyene rakı alışmaları.

Bolu şehri içince, yürüyerek turlamakta; 

Ulu şef, eşi ile, ötenaz ipini asla çekmedi.

Tüylü şapka kafasında, omuzlarında ceketi; 

Ona deli dediler, kartopu da fırlatmışlardı.

“O” diyorlardı, 3 sene geçti, diyorlar mı “veli”? 

Evlerde Haber Var; izde sür iz sen kar.

Güven İslamoğlu’nu aldı karşısına, bağdaş; 

Hayatı anlatıyor, ‘Babo-Bobo Oturan Boğa’ …

Güven İslamoğlu, güvendim sana “dostum”; 

Bacağına vurdum, ot geviş getirdim, sormadım

Ona “Kar Kartalı” ismini taktı, yaktı barış çubuğu

… Her evde iki haber oldu Şef Oturan Boğa; iki haber ile iki şiir, bir dil bir insan, çift elden(se)  alkış; sen bunu görünce koş… sen coştuğuna sevin; paylaşmayı, bildiğin …

Selahattin Kalaycıoğlu, kalaylıyor doğayı (kahsa)  internete girdiği makinayla bir Kızılderili. Doğa Ana’yı taşıyor, yarınlara çıkacak tek, miğfer göğsü! ! 

--

Açıklamalar:

Karakterler.

“Oturan Boğa” Baybou – baybou türetme (Bolu Beyi)  “Boa” adlı filmden esinle “Bolu”yla karıştırılarak elde edilen: Bou

“Sevgi(nin)  Işığı”

Gündüz Gözü – türetme (Kar)  :)) 

Balık-Akrepyal – türetme (svegili, alişen

Xantho Alukas (Xhanto diye yazacaktım ancak “Xanadu”ya daha bir andırmak için böyle yazdım. Namı diğer Barış Aluk) 

Carotte (carlotte adlı can arkadaştan türetme, caretta caretta’lara da anımsama..) 

Guneydenus (çok yaşa sevgili Ümran Demircan, sevgi dolu günlere) 

“Kar Kartalı”

Ortadünya’dan “Rohan” (bu adamın isim benzerliği şaşırttı. tanıyanınız var mı acaba? bu yazıyı yazmamıştım. ayrıca Rohan karakteri, Ortadünya lafı da ilgi çekti. ne anlama gle bu yazı.

ehricn (bir mucizevi taş, eline alırsan ‘ehircin’, almaz isen ‘ehircan’ oluveriyorsun. Bir türetme. Namı diğer Nergis Demet can dost, blogcudaki namı ehircan) 

http://www.ortadunya.com/odunya/normal.asp? Sayfa=0&DataId=328&Kategori=2&Key=

)  ilgilenenler için açıklama adlı, şiirin yeni sayfasına bu yazıyı açacağım.

Mağranın Alimi

Şef Sebo Baybou bou Beyi=”Oturan Boğa” Sabahattin Kalaycıoğlu=Küçük Kuş adı verilen meksikadaki o yarım tonluk boğa=Şef Babo Bobo (hem amerikadaki ayıcık hem de türkiyedeki babo)  :) 

Hatice Kalaycıoğlu= “Sevgi(nin)  Işığı” (Annesi) 

Sabahat Kalaycıoğlu, eşi=”Doğan Güneş”

Çift tırnaktakiler alıntı isimler

Bu hikayenin gerçek kısmı, Bolu’da yaşayan ve Kızılderili yaşamı hayata geçiren kişiyle ve karakterlerle alakalı.

CNN Türk ‘ Her evde 1 habe var’ programından esinle yazdığım ikinci… ilki, ‘Korkuteli’li Sinan’ şiirimdi.

İlk bölümse bir NTV kısa belgeselinden esin', 'Çok evreli uyku, uyku bozukluklarında kolay dalışı sağlayan kendine, bir yetebilirlik; ancak bilmiyor sevgili ayaklarının üşüdüğünde, donmad...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/sef-seba-baybou-masalsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şıp şıp', 'sip-sip-akin-akca-zwqul', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kanser edersin,

Sormazsın bağını.

İlle çağrılınca,

Gelirsin döner.

E ki ne söner? 

Yakayı ele verince

Haşa. Hala Tanrı

Mı sanarsın? 

Etten kemikteniz,

Yol yolcusuyuz.

Bak ama, zamanı

Bükeriz, 

Kullanmaya onu,

Uğuröceği çıngırak

sadece, bizse

daha güzelleştiririz.

Yakında güzel

ederlerse seni

uzatıp da telomerazı

Ve hatta 

yok ederlerse

serbest radikalleri; 

ah iyi huycul

antioksidanlar toksik; 

gene sen

Azrail sanama

Yaşadıklarımız çünkü 

hoş şeylerdir

sadece -dünkü

- dönüşün için:

Geçmiş hazırlanır,

gün değil; 

gelecek hazırlamak.

Bugünü, yaşarız; 

Biliriz

olmaz borcumuz.

….', 'Kanser edersin, Sormazsın bağını. İlle çağrılınca, Gelirsin döner. E ki ne söner?  Yakayı ele verince Haşa. Hala Tanrı Mı sanarsın?  Etten k...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sip-sip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlük çabasından sanat''a yazılar-1', 'gunluk-cabasindan-sanat-a-yazilar-1-akin-akca-wq7ss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şey gibi şiirde de hareket lazım. Nerede hareketse orada bereket, bir de vakit nakittir.Turgay Renkliy(k) urt''un örneklediği bir lafa göre, bir söz Trakya''da vardır: ''Nerde ekmek, orda..''..''sinek''; ''e nerde sinek, orda..'' ''..peki nerde ehe,.. orda raket''. Hadi bakalım, Allah versin bereket... Gözümüz saniyede 1ooo''ler kere atıp kalbimiz kıpırdamasa gözbebeğimiz moleküllerimiz saniyede, körler olurduk. Atom çekirdeği etrafındaki elektronlar farklı yörüngelere çöküp ya da yükselmeseler şayet; devamlı bir hareket halinde, vücutlarımız birer hayalet olur, şeffaflığa felçlileşen bireyler olacak olan biz, kütleden yoksunlaşan bedenlerimizi seyrederdik. Tabiat olarak Türkiye çok zengin olsa da, bunlar sanırım belli başlı bölgelerde: Şöyle ki, ingiltere''de 1 kişiye 4o km karelik yeşillik alanlar düşerken -ki gariptir, bu kapsamda William Morris''in bir yazısı, ha şöyle der:

''Para hırsı yalnız kentleri değil doğayı da katledecek

İşin içinde para kazanmak mı var? Evlerin arasındaki güzel

ağaçları kesin,Londra''da birkaç yardalık pis toprak elde

etmek uğruna,saygı duymamız gereken eski yapıları yıkın,

nehirleri karartın,güneşi gizleyin ve havayı dumanlarla zehirle-

yin... Çağımız ticaretinin bize yapıp yapacağı hizmet budur

işte.''

- bizim Türkiyemize ise, kişi başına, bunun onda biri kadar bile bir alan düşmüyormuş. Bakın hele şu işe! ! Şimdi Seyfe Gölü''nü kirletip sorumsuzca, Tuz Gölü''nü ise kendileri töhmetleri altına almaya çalışanlara, dünyayı kirleten her ülkeye ve hatta; sormalı, bu ne iş! ! Doğayı sevmeyen kendini sevemez, bilim bile tepeden yeryüzüne indi. William Blake''in dediği gibi, ya da John Donne’nin ''çevre'' meselesi:

''Enerji...

''ENERJİ YAŞAMIN TA KENDİSİDİR

VE ONUN RUHUDUR; 

VE ASIL NEDEN, ENERJİNİN SINIRI

YA DA DIŞ ÇEMBERİDİR,

ENERJİ SONSUZ ÖLÜMDÜR.''

w.blake''

Umutsuz gibi gözükür, ama son dizesiyle umarsız bir ümit pınarı saçar. Enerjiyi yaşamak için bırakmıştır sanki. Sadece yaşamak için...

Evet, doğayı sevmeyen kendini sevemez, ne de sporu, şiiri; sanatı! Samuel Taylor''un bir şiiri, ''Kubla Khan'', sanırım neden bu kadar sevdiğimi anladım onu. Tabi Cengiz''den pek hazzetmemem (durumu :)  Kubilay Han''ı sevmeme mani değil ancak hala neden antipati beslemedim diye şaşarım. Şiir Kubilay''ın bir Çin sarayı inşaatı serüvenini anlatır. (Maksat o ya, müzik, bu inşaatın amemeleriymiş.)  Ama aslında bu bir tabiatı yüceltiş serenatıdır. Dini coşkularla yükselmiştir, fakat anlatılan farklıdır.. Anlatım bence muhteşem, şiirin teması sonucu ise Habeşli bir genç kanımca kızdır. Vaktiyle okuduğum herkes, aşk şiirinden başka her şeye benzetmişti. Peki, hayat gerçekten böyle mi(!) ? 

Fakat,yüzeyden derine inmekten kaçan; yeşil alanlarını koruyabilir mi? 

Çift tırnaklar alıntı', 'Her şey gibi şiirde de hareket lazım. Nerede hareketse orada bereket, bir de vakit nakittir.Turgay Renkliy(k) urt''un örneklediği bir lafa gö...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunluk-cabasindan-sanat-a-yazilar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
