INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mikdatiyim bilin beni', 'mikdatiyim-bilin-beni-mikdat-bal-9i6y2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsanlara sevgim sonsuz

Zengin, fakir ünlü, ünsüz

Başta sevgi olmaz onsuz

Mikdatiyim bilin beni

Şiirlerde bulun beni

Şiirlerim dini, milli

Yalın uslüp tatlı dilli

Ad yazmazsam kimin belli

Mikdatiyim bilin beni

Şiirlerde bulun beni

Halktan yana kulağım var

Türkiyeden ulağım var

Kalem tutan bileğim var

Mikdatiyim bilin beni 

Şiirlerde bulun beni

Bazen durgun göl olurum

Bazen taşar sel olurum

Bendim yıkar yol olurum

Mikdatiyim bilin beni

Şiirlerde bulun beni

Hak edeni yererim ben

Yerden yere sererim ben

Defterini dürerim ben

Mikdatiyim bilin beni

Şiirlerde bulun beni

Ben yurdumu çok severim

Sevenleri hem överim 

Ne acı der ne döverim

Mikdatiyim bilin beni

Şiirlerde bulun beni

Şahıslarla olmaz işim

Bazen kaya gibi taşım

Korkum olmaz geçti yaşım

Mikdatiyim bilin beni

Şiirlerde bulun beni', 'İnsanlara sevgim sonsuz Zengin, fakir ünlü, ünsüz Başta sevgi olmaz onsuz Mikdatiyim bilin beni Şiirlerde bulun beni Şiirlerim dini, milli Y...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/mikdatiyim-bilin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Krizlerde vurgunlar yedim...', 'krizlerde-vurgunlar-yedim-pinar-koc-c1n28', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidişinin ardından vurgunlar yedim,

Yüreğim sızladı için için……

İçimden neler geçti,

Neler geçmedi bir bilsen……

Sol yanım sızladı derinden……..

Ve sol yanım bölündü

Sevginden bazen,

Bazen sevgisizliğinden….

Umurun muydum,

Değil miydim? 

Uğurunmuydum,

Uğursuzluğun mu? 

Gidişinin ardından vurgunlar yedim,

Dönecektin,

Bilirdim.

Ama 

Dönsen de,

Kendimi yalnız hissedecektim………

Güvensizliğimin uç noktalarındaki

Krizlere ve kır izlerine

Baktım,

Bilmeyecektin…….

Bende mi gitseydim

Bilinmezliklere

Sevinir miydin? 

Sen bilirsin der miydin? 

Yoksa içinden geçenleri

Derin dalgalardaki sonsuzluklara 

Gömmez miydin? .......

Tepkili mi olmalıydı sözlerim,

Yoksa

Her zaman ki gibi

Sessizliğim miydi sesim……..

Korkardım sensizlikten bilirdin……

Vurgunlar yedim ardından

Yüreğim sızladı için için……..

Güvensizliğimin uç noktalarındaki

Krizlere ve kır izlerine

Sessiz kaldım hep

Sadece beni ve

Benim seni sevmem için……….              08.02.06

sevgili dostum aysun a...........', 'Gidişinin ardından vurgunlar yedim, Yüreğim sızladı için için…… İçimden neler geçti, Neler geçmedi bir bilsen…… Sol yanım sızladı derinden……...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/krizlerde-vurgunlar-yedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk seven gönüllere Allah’ın Lütuf u', 'ask-seven-gonullere-allah-in-lutuf-u-halil-colak-s2fdj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ufuklar birleşmiş canım yerle bir gibi

İnan ruhlar kuşlar gibi özgür ve mutlu

Ademle hava’dır birbirin sevenin ilki

Aşk seven gönüllere Allah’ın Lütuf u

Halil Çolak 8.2.2006 Ankara', 'Ufuklar birleşmiş canım yerle bir gibi İnan ruhlar kuşlar gibi özgür ve mutlu Ademle hava’dır birbirin sevenin ilki Aşk seven gönüllere Alla...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-seven-gonullere-allah-in-lutuf-u-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suphe', 'suphe-ulya-erkman-8d26l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kucucuk bir soz ama mahveder 

Insani

Dogry mu soyluyor yoksa 

Yalan mi? 

Kivranir durursunsupheyle

Nasil inanmali? 

Cikinca yalan ortaya kizarsin unutmak 

Istersin o insani

Sevmissindir bir insani 

Cok derinden

Sevdigini soyler sana Adeta 

Icten

Suphe edersin Ama bazi 

Hallerinden

Ogrenince yalani mahvolursun

Uzuntuden

Supheci insan da kalmaz dogru durust 

Bir huzur

''Acabalar'' la yasamak sanki bir 

Adet olur

Bazan hakli cikar suphelerine 

Cevap bulur

Yine de suphe insanlari yorar cok defa da

Luzumsuzdur', 'Kucucuk bir soz ama mahveder  Insani Dogry mu soyluyor yoksa  Yalan mi?  Kivranir durursunsupheyle Nasil inanmali?  Cikinca yalan ortaya kiz...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/suphe-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirler Yazacağım', 'siirler-yazacagim-yusuf-onder-bahceci-dwhbo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben seni çok sevdim diyemedim be,

Sende beni sevmiştin diyemedin de,

Sana şimdi ne deyim diyemem ki be,

Ölene kadar böyle şiirler yazacağım.

Ayrılığın rüzgarı bak nasıl da sert esti,

Bilirmisin sen yalancılar yollarımı kesti

Seni seveceğimi derken sesimi kesti,

Ölene kadar böyle şiirler yazacağım.

Çok uğraştılar seninle ve de benimle,

Benim kadere isyanım yok bedenimle,

Dünya''da yalnız seni sevdim anla be,

Ölene kadar böyle şiirler yazacağım.

Bilseydim bu yalan, dolan ve planları,

Ölçülerini alırdım bil, kalırdı kalanları,

Bana ve sana söylediler bu yalanları,

Ölene kadar böyle şiirler yazacağım....', 'Ben seni çok sevdim diyemedim be, Sende beni sevmiştin diyemedin de, Sana şimdi ne deyim diyemem ki be, Ölene kadar böyle şiirler yazacağım....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siirler-yazacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şirin Yol', 'sirin-yol-mehmet-isikoglu-zfc6q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cayarmı o yola başını koyan 

İster erkek olsun isterse bayan 

Titretir yüreği o sesi duyan 

Aldırmaz dünyası tersine dönse 

Riskine katlanır dönemez geri 

Yüreğin özünde aşkının yeri 

Ondan başkasını görmez gözleri 

Koşar sevgiliye hayatı sönse 

Tutukludur başka yere gidemez 

O davadan gayrı dava güdemez 

Bir an olsun düşünmeden edemez 

Koşar ona hayalinde görünse', 'Cayarmı o yola başını koyan  İster erkek olsun isterse bayan  Titretir yüreği o sesi duyan  Aldırmaz dünyası tersine dönse  Riskine katlanır...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sirin-yol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramızda Kader', 'aramizda-kader-ali-kaybal-h90w5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aradım yari buldum derken güle,

Açıldı, yar oldu aramda kader.

Arkamda dağ gibi dur derken hele,

Yığıldı, dağ oldu aramda kader.

Parlayan yıldız buldum derken şule,

Çıban, irin oldu aramda kader.

Toprağa damla buldum derken böyle,

Yıkıcı, sel oldu aramda kader.', 'Aradım yari buldum derken güle, Açıldı, yar oldu aramda kader. Arkamda dağ gibi dur derken hele, Yığıldı, dağ oldu aramda kader. Parlayan yı...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aramizda-kader-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular', 'duygular-ahmetnecat-ucur-yomj1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öncelikle bakmalısın gözlerime

Vermelisin, ellerini ellerime

Dolasana kollarını, bellerime

Doyacaksın aşk ve sevgi sellerime

Ulaşacaksın en derin hislerime

Dokunacaksın en hassas yerlerime

Silineceksin tertemiz terlerime

Alışacaksın, buğulu sislerime

Yaşayınca tatmadığın duyguları

Bulacaksın bulmadığın bulguları

Bileceksin bilmediğin duyguları

Atacaksın içindeki kaygıları

Ah, bir kerecik sarılsan kollarıma

Her an, her gün bakacaksın yollarıma

Hiç ayrılmamacasına kollarıma

Bağlanıp da yatacaksın yollarıma

Sardıkça seni, sıkı sıkı kollarım

Her an, her gün, her yerde seni kollarım

Sanma ki bırakıp da seni sollarım

Bekliyor seni, her an hazır kollarım', 'Öncelikle bakmalısın gözlerime Vermelisin, ellerini ellerime Dolasana kollarını, bellerime Doyacaksın aşk ve sevgi sellerime Ulaşacaksın en ...', ARRAY['Türk Edebiyatı','Şiir','Ahmetnecat Ucur']::text[], 8.5, '{"poet":"Ahmetnecat Ucur","poet_slug":"ahmetnecat-ucur","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duygular-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cenneti Sana Bıraktım', 'cenneti-sana-biraktim-ozay-karakus-lfgxa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'cenneti sana bıraktım

M erak etme gideceğim yalnız sana 

cesetimle geleceğim...sana dönerken 

.........her bir organım seni seviyorum diyecek... 

belki beni kara toprak yiyecek ama seni çürütecek,seni yiyecek bir karış toprak bulamayacaksın her ne kadar gönül bahçen erozyona uğramış olsada.....attığın her yeni aşk tohumu cehennemde yeşerecek alevler ortasında etrafına bakacaksın bir zebaniden başka hiç kimseyi 

göremeyeceksin.....yaklaşacaksın ona doğru ve iki çift söz duyacaksın, dünyada yalnızca bir kişiden defalarca duyduğun o büyülü iki kelimeyi...SENİ SEVİYORUM..... 

kaynar sular dökülecek başına ama yanmayacaksın sadece utanacaksın hani seni dudaklarından ilk öptüğüm gibi 

tırnakların sökülecek ama hiç acı çekmeyeceksin aksine 

gülümseyeceksin hani parmaklarını saçlarımda dolaştırdığın gibi........ve gözlerine mil çekilecek azabın zerresi olmayacak 

gözlerinde lakin yaş yerine kan akıtacaksın kırmızıya bulanacaksın baştan ayağa hani kırmızıyı çok severdin ya 

hani beyaz gülü reddetmiştin yerine kırmızı aldırmıştın ya bana,hani dünyalar senin olmuştu ya işte aynen öyle ahiret de senin olacak onca günahına rağmen... bağışlanacaksın 

RABbim seni benim sana olan yeryüzünde görülmemiş sevgimden dolayı affedecek.sorgusuz sualsiz sıratı geçerken yürüyüşün hurileri kıskandıracak ve o zebani sana tebessüm edecek yine o iki kelimeyi duyacaksın.....SENİ SEVİYORUM... 

cennete ulaştığında merak edeceksin kim o zebani neden beni sevdiğini söylüyor diye soracaksın meleklere....ve melekler ağlamaya başlayacak gökten yağan yağmur şiddetinde gözyaşları cehennemi ıslatacak ve diyecekler ki o zebani 

dünyada terkedip gittiğin seni kendinden çok senin yerine yanmayı göze alacak kadar seven KAAN........ 

ve ben seni senden bile seni benden bile çok ama çok 

herşeyden çok seven ben cehennemden sesleneceğim sana.......................................................................... 

sakın ağlama aşkım sakın ağlama ki zebanilikten kurtulup kendi cismime bürüneyim,o zaman cehennem ateşi kalbimde yaktığın ateşin gölgesinde kalacak azabı hissedeceğim ama kokunu duyacağım cehennemin her köşesinde her azap bana seni daha da çok sevdirecek diyeceğim...... 

anlayacaksın bu defa aşkımın büyüklüğünü,hatırlayacaksın sen giderken sana verdiğim yemini..........gitme birtanem ben senin için cehennem ateşinde yanmazsam namerdim... 

ya işte sevgilim ben yanacağım artık dönüşüm yok 

sen giderken veda bile etmedin yüzüme bile bakmadın 

ama ben, ben var ya ben, 

ne diyeyim artık al işte....... cenneti sana bıraktım..... 



------------münhasıran', 'cenneti sana bıraktım M erak etme gideceğim yalnız sana  cesetimle geleceğim...sana dönerken  .........her bir organım seni seviyorum diyece...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cenneti-sana-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölsem Bile Dönemem', 'olsem-bile-donemem-yusuf-onder-bahceci-105vx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cân dostlara selam selam,

Güzel sevdim yola devam,

Ne var birgün benim olsan,

Ölsem bile dönemem ben.

Haber salayım dostlarıma,

Fazla ara vermeyeyim ara,

Aşkıdır kâlbimde gizli yara,

Ölsem bile dönemem ben.

Çıksam kârlı dağlar başına,

Uzaktan baksam yalvarışına,

Dönmüşüm ben bir şaşkına,

Ölsem bile dönemem ben.

Sanmasın ben unutmuşum,

Başka birini mi bulmuşum,

Yanıp yanıp ta kül olmuşum,

Ölsem bile dönemem ben....', 'Cân dostlara selam selam, Güzel sevdim yola devam, Ne var birgün benim olsan, Ölsem bile dönemem ben. Haber salayım dostlarıma, Fazla ara ve...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olsem-bile-donemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olması Gereken Budur', 'olmasi-gereken-budur-banu-savas-9kndy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yazgının

anlaşılmaz, ölümcül ve sonlu

olması değil

yaşamı sevmiyor da değiliz

bu sanki olması gereken

kendi içindeki karanlığı

sürekli besleyen

budur olması gereken

bütün ömür buna hazırlanır insan

bazı günler midesi bulanarak

öğrendiği günden beri

gizli gizli ağlayarak

olması gereken buymuş gibi

hazırlanır

seçilmiş bir ölüm

sancılıdır, kötüdür, acımasızdır

ama

onurludur, huzurludur, cesurdur

bazıları için

olması gereken budur…', 'yazgının anlaşılmaz, ölümcül ve sonlu olması değil yaşamı sevmiyor da değiliz bu sanki olması gereken kendi içindeki karanlığı sürekli besle...', ARRAY['Türk Edebiyatı','Şiir','Banu Savaş']::text[], 8.5, '{"poet":"Banu Savaş","poet_slug":"banu-savas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olmasi-gereken-budur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Yorucu Bir İştir', 'nasil-yorucu-bir-i-stir-banu-savas-7tx6l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nasıl yorucu bir iştir 

bir erkeği ruhundan öpmek

işlemek sancıların dantelini

ve yakmak

çok dayanmayacak meşaleleri

nasıl yorucu bir şeydir

kaldırıp başını

içinin penceresinden

yaşamının kamçısına bakmak

sırtında izlerini sızlatarak

hadi çıkalım dışarı

bunlar kendi kavgamızın yaraları

çıkalım

bizden önce kimse açmadı bu dolapları

yorgunluk

henüz düzelttik yazgının çarşaflarını 

şimdi o çarşaflarda yatırıyoruz

kimsenin evine sokmayacağı sanrıları', 'nasıl yorucu bir iştir  bir erkeği ruhundan öpmek işlemek sancıların dantelini ve yakmak çok dayanmayacak meşaleleri nasıl yorucu bir şeydir...', ARRAY['Türk Edebiyatı','Şiir','Banu Savaş']::text[], 8.5, '{"poet":"Banu Savaş","poet_slug":"banu-savas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nasil-yorucu-bir-istir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-dilek-kadioglu-9ehr8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğime girdiğin günden bu yana senle olup seninle dalıyorum rüyalara sensiz  geçirdiğim bir saniyem bile olmadı yüreğime girdiğinden beri bir saniye olmasan aklımda boşluklara düşüyorum yarım kalıyorum ve seni alıyorum yine hayallerimin içine kendimle bütünlüyorum sen olmayınca anlıyorum ki ben, ben olmuyorum  içimdeki sevdamı, hasretini anlatamadım sana yar anlatmak istediysem de hep susturdun susmam gerektiğini söyledin ben susunca sen mutlu oluyorsun diye dilime kelepçe vurdum, yüreğime ateşleri koydum ve sustum  sadece sen mutlu ol diye her şeyden önce gelir senin mutluluğun gözünden damlayan bir damla gözyaşıyla boğulur ölürüm ben adın dilime düşünce sen sus dedin diye yüreğimin dili çözülür o anlatır sevdam sana yalan yok sözlerimde inanma el sözüne dediysem de gece gündüz hep sen, sen dediysem de duymadın be sevdiğim dağlar taşlar duydu feryadımı ama sen duymadın haykırışlarımın sebebi ne diye bir gün  sormadın hep sustun sen sustun ben öldüm. Gelirse adım aklına bir mezar taşı ara o anda yağmuru takip et getirecek seni benim yanıma dua etme rüyalarıma bile gelmeyen sen mezarıma olsa bile gel öldüğümü sandığın ben senin gelişinle doğmuş olacağım yeniden beni hasretin öldürdü gelişin yaşatır.

07/02/2006 Beşiktaş', 'Yüreğime girdiğin günden bu yana senle olup seninle dalıyorum rüyalara sensiz  geçirdiğim bir saniyem bile olmadı yüreğime girdiğinden beri ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Kadıoğlu']::text[], 8.5, '{"poet":"Dilek Kadıoğlu","poet_slug":"dilek-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sensiz-191-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çerçici Tezgâhı', 'cercici-tezg-hi-alper-kuruk-xr361', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağarcığında birşey var mı diye sorana

Gönlümü açıverip de dökerim ortaya,

Çerçici tezgâhıdır bilerek arayana

Uygunu bulunur da yanaşmam mal satmaya.

Gönlümdeki sevgiler kopuk zincir baklası

Perçinle birleşmeye gerçek sevgili ister,

İçimdeki umutlar halkacının halkası

Sigaralardan sekip sekip de boşa geçer...

Sana belki yaramaz malım kıymetli benim

Herbirini ömürden karşılık verip aldım,

Yıllarca taşıyorum alıştı bu bedenim

Çok tezgâhlar kapandı bir ben ayakta kaldım.

Birgün ben de yükümü sırtımdan atacağım

Ben de anlayacağım o gün yaşlandığımı,

Gün gelecek tezgâhı ben de kapatacağım

Kimseler görmeyecek ne alıp sattığımı...', 'Dağarcığında birşey var mı diye sorana Gönlümü açıverip de dökerim ortaya, Çerçici tezgâhıdır bilerek arayana Uygunu bulunur da yanaşmam mal...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cercici-tezgahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alda Git', 'alda-git-ozay-karakus-gbzdf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sensiz başkasında aşk-u muhabbet aramadan 

şu fani dünyada devr-u afet saramadan 

kakül bırakıp zülfün telini taramadan 

uzat pansuman pamuğu ellerini yolda git 

tıkanmadan kalp kapakçığım nefessiz kalmadan 

ahr-i aleme hab-ı derun dalmadan 

beni azap kapısında ecr-i zulme salmadan 

onca günahıma bence sevap olda git 

nabız atışlarım son deminde gel durmadan 

ayrılık okları aşkımızı hedefte vurmadan 

her vakit senli benli hayal kurmadan 

bir leyl-ü beka yanımda kalda git 

ne yapar bu aczi gönül sen olmadan 

vazgeçermi sanırsın aşkın ömrü dolmadan 

ahengim bozulmadan rengim solmadan 

sevgimize bir ayar bulda git 

sevgilim iki gözüm sel olup akmadan 

gizlice kapattım evvel cemaline bakmadan 

nar-ı cehennem bedenimi yakmadan 

gözyaşınla bedenimi ıslatda git 

çok seviyorum seni zira hiç usanmadan 

haykırırım aşkımı cihana hiç utanmadan 

sada etme güruh-u dide-i kem uyanmadan 

usul usul saçlarımı sev okşada git 

seni ne kadar sevsem az bilirim noksan 

sensiz yapamam asla olurum viran-ı yeksan 

çekilirmi güzelim bu hayat sen yoksan 

kalalım yekpare beni de yanına alda git 

------------münhasıran', 'sensiz başkasında aşk-u muhabbet aramadan  şu fani dünyada devr-u afet saramadan  kakül bırakıp zülfün telini taramadan  uzat pansuman pamuğ...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/alda-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhammed ''il emindi', 'muhammed-il-emindi-halil-colak-ej7dr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kul ellerini kaldırır her zaman kıbleye dururda duaya

Günahların bağışlanması için de yalvarırda Mevla’ya

Ümit kesmez mümin samimi  olarak güvenirde Allah’a

El boş dönmez  yeter ki samimi tövbe et yaratan  Huda’ya

Hiç boş döner mi kul  cömerttir o kapının yaratandır sahibi

Hazineler,rahmetler güzellikler onundur her şeyin  yaratanı

Doğru yoldan ayrılmayalım diye gönderdi iki cihan güneşini

Herkes doğruluğundan emindi çünkü adı Muhammed'' il emindi

Halil Çolak 9.2.2006 Ankara', 'Kul ellerini kaldırır her zaman kıbleye dururda duaya Günahların bağışlanması için de yalvarırda Mevla’ya Ümit kesmez mümin samimi  olarak g...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/muhammed-il-emindi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğidim', 'yigidim-ozay-karakus-3dsm8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'NE BEDENİME NE ZİHNİME VURABİLİRLER BİR KİLİT 

NE DE BAŞKASININ SIRTINDA YAŞAYAN PİRE BİT 

NE DE KAPISINDA DURAN YAL BEKLEYEN İT 

OLMADIM GÜZELİM BEN YİĞİDİM YİĞİT 

GÜLLER ARASINDA DOLAŞIRKEN BİR DİKEN GİBİ ÖNÜMDE BİT 

EN KALLEŞ ACILARIN DİBİNE EN YÜKSEK UÇURUMDAN İT 

TERKEDERSEN BENİ GİDECEĞİN YERE KADAR GİT 

ÜZÜLÜP AĞLARMIYIM BE BEN YİĞİDİM YİĞİT 

ATSALAR BİR ATEŞİN İÇİNE MÜNFERİT 

BAĞRIMA KURŞUNDAN ÇİZSELER BİR ŞERİT 

İNAN Kİ GÜZELİM BUNLAR BANA ÇOK BASİT 

DEDİM YA BEN YİĞİDİM YİĞİT 

...HEMDE YİĞİTLERİN KRALI...DUYMAK İSTEMEZSİN GÜCÜNE GİDER BELKİ AMA BAK DUR DİNLE BEN NE SAF BİR AŞIK NE DE ZAVALLI BİR KÖLEYİM 

DEDİM YA HEP SÖYLÜYORUM YA......BEN... YİĞİDİM.....YİĞİT... 

------------münhasıran', 'NE BEDENİME NE ZİHNİME VURABİLİRLER BİR KİLİT  NE DE BAŞKASININ SIRTINDA YAŞAYAN PİRE BİT  NE DE KAPISINDA DURAN YAL BEKLEYEN İT  OLMADIM GÜ...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yigidim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severse Eğer', 'severse-eger-mehmet-sait-akkus-0ci16', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adını anacağım

Aşkına yanacağım

Huzur bulacağım

Seni seversem eğer

Mutluluğu ararsam

Belinden kucaklarsam

Senin için yanarsam

Seni sevmişim meğer

Kucak dolusu meğer

Seni sevmeye değer

Senin için olsa eğer

İnan ölmeye değer

Yanar isem yanayım

Aşkına avareyim

Sanki bir pervaneyim

Sevgin olursa eğer', 'Adını anacağım Aşkına yanacağım Huzur bulacağım Seni seversem eğer Mutluluğu ararsam Belinden kucaklarsam Senin için yanarsam Seni sevmişim ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/severse-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Kavuşurum Söyle Sana', 'nasil-kavusurum-soyle-sana-ozay-karakus-wmmqz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaradan adına biten sevdamın 

doymadım tadına büyük aşkımın 

aşksız bir dünyada anlamı yok yaşamamın 

sensiz bir dünyada yoktur anlamım 

sevgiyle yanan kalbim 

şimdi sanki buz tutmuş 

bu ayrılık çok zalim 

bizi bize unutturmuş 

toz pembe gördüğümü hayaller 

söylesene yar şimdi nerdeler 

umudumuz yok çaremiz yok 

bize dünyayı zehir ettiler 

haketmedik biz bunları 

ayırıpta koparanlar utansın 

ALLAH yaksın onları 

seven kullar ne yapsın 

nasıl kavuşurum söyle sana 

nasıl dayanırım ben yokluğuna 

tuzak kurmuşlar yollarımıza 

bin kurşun sıktılar bu canımıza 



------------münhasıran', 'yaradan adına biten sevdamın  doymadım tadına büyük aşkımın  aşksız bir dünyada anlamı yok yaşamamın  sensiz bir dünyada yoktur anlamım  sev...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nasil-kavusurum-soyle-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seversem Eğer', 'seversem-eger-mehmet-sait-akkus-hdv25', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adını anacağım

Aşkına yanacağım

Huzur bulacağım

Seni seversem eğer

Mutluluğu ararsam

Belinden kucaklarsam

Senin için yanarsam

Seni sevmişim meğer

Kucak dolusu meğer

Seni sevmeye değer

Senin için olsa eğer

İnan ölmeye değer

Yanar isem yanayım

Aşkına avareyim

Sanki bir pervaneyim

Sevgin olursa eğer', 'Adını anacağım Aşkına yanacağım Huzur bulacağım Seni seversem eğer Mutluluğu ararsam Belinden kucaklarsam Senin için yanarsam Seni sevmişim ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seversem-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alda Gel', 'alda-gel-ozay-karakus-tbl68', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne kadar mutluydum sevgilim yanımda sen varken 

umutsuzluğu ektin yüreğime giderken 

bekliyorum o gün kararından dönerken 

götürdüğün yarım kalan anıları alda gel 

ben gün gün sana hasret çekerken 

yüreğime binbir özlem ekerken 

kafan hafif tam şekerken 

bari pekmezde reçelde balda gel 

ayrılık sevilene kolay bilirim ama erken 

hemde ben seni böyle mecnun severken 

ellerim duada ya RAB kavuştur derken 

bir sürpriz yap kiliti at kapıyı çalda gel 

karanlığa bürüdün dünyamı sebepsiz neden 

suçum ne sevgili söyle kırdım mı seni bilmeden 

affettirecekse beni sana bir demet yasemen 

çok özel en güzel hayallere dalda gel 

ben her gece hayalini düşlerime sararken 

düşlerim gördünüzmü yari diye sorarken 

yeniden kavuşmak için sana çareler ararken 

kahveler içip baktığım falda gel 

cismini hafızamdan silemiyorum fikren 

ismini dilimden düşürmüyorum zikren 

her daim her yerde seni anarken 

sende her gece uykusuz kalda gel 

kayboldun ansızın maviye çalan gözlerimden 

bir tarifi olmayan sızı sardı beni dizlerimden 

çok şey anlar seviyorsa sevgili sözlerimden 

biraz gayret et birgün de leyla şirin olda gel 

yanan her lambanın ışığında senin gölgen 

ben unutamıyorum sen unuttuysan hadi göster varmı belgen 

benim sevgim yüreğimde seninde kalbinse en hassas bölgen 

elini koy üstüne ortada değil az biraz sol da gel 

ey sevdiğim seven seni sevgili gibi severken 

gözlerin gözlerimi gözbebeklerine sorgusuz hapsederken 

ben kalbinin zindanlarına faili meçhul delilsiz giderken 

suçlu olduğuma dair en ufak bir kanıt bulda gel 

oldumu şimdi bu ayrılık ben alev alev yanarken 

sevgilerin pınarında ölesiye aşkına doyasıya kanarken 

güç yetiremez hiçbir kuvvet buna imkan yok sanarken 

ne olur sevgili sende ben gibi ümitlerle dolda gel 

hangi seven mutlu olur ki sevilen sözden cayarken 

ben sana doruklara ulaşmış zirvede bir sevgi duyarken 

tamda mecnunun ferhatın tahtına adaylığımı koyarken 

sende sevgiyi anlatan destanda öyküde masalda gel



------------münhasıran', 'ne kadar mutluydum sevgilim yanımda sen varken  umutsuzluğu ektin yüreğime giderken  bekliyorum o gün kararından dönerken  götürdüğün yarım ...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/alda-gel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişerek Öldüler', 'seviserek-olduler-ozay-karakus-vpxu2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hani kör karanlığın hayal meyal seçebildiği ay ışığında 

bir sen, bir ben, iki ten, tek vücut, sevişen iki kalp, bütünleşen iki ruh,iki duygu aynı his aynı heyacan 

ateşli dudaklarda aynı alev aynı şiirsel yaklaşım 

üzerimizde tatlı bir utanç örtülü,yatağımız çıplak bedenler, yastığımız günahımıza şahit çimenler,korkumuz ayrılıktan da öte hiçbir zaman kavuşamama varsayımları ümitsizliğinde 

nefes almak bile en büyük vakit kaybı, kalp atışlarımız dahi 

kuzuların sessizliğinde,zaman kavramı aklımızın en ücra köşesinde asla yer bulamazken kendisine, ihtiraslarımız yüz nokta doksan dokuz şiddetinde, öpüştükçe sallanıyor seviştikçe yıkılıyor dağılıyoruz ama herbir parçamız yeniden birleşiyor gözgöze geldiğimizde,ellerimiz birbirinden bağımsız tampon bölgelerde görev yapıyor tüm ciddiyetiyle ve ben senin taciz ateşinde sen benim hedefimdesin onikiden vuruyoruz aşkı noter tasdiksiz.rekorlar kitabına girmemize az kaldı sevgilim biraz daha sabır biraz daha gayret nolur biraz daha kal hücrelerimde biraz daha damarlarımıza dolsun sevişirken gözbebeklerimizden dökülen yaşlar,inan biter bitmez bu reytingi yüksek sevişme anı tarih bizi yazacak en sansürlü kitaplara, kaynağı iki mezar bir mezar taşı olarak gösterecek ve bir dip not düşececekler sansasyonel aşkımızın hikayesine...............sevişerek öldülerrrrrrrrrrrrr



------------münhasıran', 'hani kör karanlığın hayal meyal seçebildiği ay ışığında  bir sen, bir ben, iki ten, tek vücut, sevişen iki kalp, bütünleşen iki ruh,iki duyg...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/seviserek-olduler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayvanlar Bilmezler', 'hayvanlar-bilmezler-yusuf-onder-bahceci-qc3pr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilki aşk şiirlerini sevenler anlar,

Sevmeyi bilmeyenler neleri anlar,

Yemek, içmek marifet se bunlar,

Bunları hayvanlar iyi yapıyor.

Sevmeyi herkese vermiyor Allah,

Sevenlerin kâlbi diyor hep Allah,

Feyli Şermi sandın aşkı ahmak,

Bunları hayvanlar iyi yapıyor.

Benim aşktan anladığım yücedir,

Özden sevenlerin hâli ise nicedir,

Hayvanlar yayılır gezer bilmecedir,

Bunları hayvanlar iyi yapıyor.

Bil gerçek aşıklar ölmez, ölmezler,

Onlar Dünya''da gülmez, gülmezler,

Hayvanlar aşkı, sevdayı bilmezler,

Bunları insanlar iyi yapıyor.', 'Bilki aşk şiirlerini sevenler anlar, Sevmeyi bilmeyenler neleri anlar, Yemek, içmek marifet se bunlar, Bunları hayvanlar iyi yapıyor. Sevmey...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayvanlar-bilmezler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişerek Yaşadılar', 'seviserek-yasadilar-ozay-karakus-ce53j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hani her gecenin ayan beyan ay ışığında bir heves iki ses 

bir nefes iki tutku bir arzu tek amaç tek gaye aynı dilek aynı yürek....yangınlarda iki vücut alev almış iki ruh kulağımızda aynı melodi aynı bestesel çağrışım aynı sevgisel koklaşım.... 

üstümüzde gökkuşağı üryan bedenlerimiz bahar yağmurlarında sırılsıklam kavruluyor aşk ateşinde..... 

döşeğimiz ıslak kaldırımlar şahidimiz az ötemize düşen arsız yıldırımlar...ümidimiz hayaldende öte hiçbir zaman ayrılmama yeminleri şiddetinde........elele tutuşmak bile sıradan yaz aşkı suretinde...öpücüklerimiz dahi seyredilen avantür bir film karesinde...inleyişlerimiz bir küçük anektod gibi kayıtlı sadece gönül defterimizde...heyecanlarımız bir saniyelik yürek çarpıntısından ibaret..heyecanlandıkça yanıyor yandıkça tutuşuyor eriyoruz ama her bir zerremiz yeniden buhar olup hayat veriyor bulutlara bir araya geldiğimizde...avuçlarımız şehvetin emrinde uzuvlarımız aşkın hizmetinde..bakışlarımız bile ahlaksız, edepsiz tavırlar sergilerken hava şartlarına rağmen hiç durmadan birleşen bütün noktalarımız noksansız temaslarda firara geçit vermeyen kaçılması en imkansız aşk hücrelerinde tutsak.. 

hadi sevgilim bize durmak yasak illegal yollardan sevişelim 

kanunsuz....sevişmemiz mahkemelik olsun en güçlü savcı suçlasın bizi iniltilerimizi delil saysın ve hakkımızda müebbet istesin kimin umrunda bebeğim son nefesimize kadar sevişerek yaşayacağız ve sansasyonel spekülasyonlarda hep biz olacağız her ressamın sergisinde bizden esinlenilerek yapılmış bütün nü tablolara paha biçilemeyecek.... 

ve şairler bizi yazacak her şiir başlığında büyük harflerle 

.....................SEVİŞEREK YAŞADILAR................................. 



------------münhasıran', 'hani her gecenin ayan beyan ay ışığında bir heves iki ses  bir nefes iki tutku bir arzu tek amaç tek gaye aynı dilek aynı yürek....yangınlar...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seviserek-yasadilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmeyecek Kadar Ölümsüzsün', 'olmeyecek-kadar-olumsuzsun-ozay-karakus-p2gf7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir başka sabahtı bu sabah sevinç ve güzün bir arada kol kola 

bambaşka duygulardayım sevineyimmi üzüleyimmi bilemiyorum.....onca yıl koştum bir ümitle senin ve aşkının peşinden....hep hayal ettim yalnız bir anı sensiz rüyaları kabus adlettim....sensiz varlığın yokluktan daha zor olduğunu öğrendim seni karşılıksız severken..... 

pes etmedim pes etmeye en elverişli zamanlarda dahi daima yüreğimde yaşattım seni....gönlüme ektiğin aşk tohumunu 

hücrelerimin her bir köşesinde muhafaza ettim damarlarımdan 

kan akıtarak suladım..günlerce bedenimi aç bırakıp sevgimle besledim seni bilmem kaç öğün..sağlığa zararlı olduğunu bildiğim hergün üç paket içtiğim sigarayı sağlığım için değil sen içimde büyüyesin diye bıraktım bir çırpıda..... 

öyle kapıldımki sana öyle çarpıldımki gözlerine....ben hayatım boyunca böyle bir organ görmedim böyle bir organ yüreğime nakletmedim...hele o yüzün yokmu tebessümde bahar kadar taze gülümsemede çiçek kadar güzel ve kahkahada güneş kadar sıcak.... sen farkında değildin ama yada farkındaydın ben farkında olduğunun farkında değildim..her neyse işte 

ben yüzüne her baktığımda gözümün görme çapının senin yüzünden ibaret olduğunu biliyordum... 

ve işte bu sabah yine evinin güzergahında vatana aşık bir asker gibi nöbet beklerken...kapıdan yine bir melek endamında çıkmış ve süzüle süzüle ilk defa yanıma gelmiştin 

heyecandan elim ayağım felçli bir hasta görünümünde titremeye başlamıştı....sen sakin sen hüzünlüydün sen bir başkaydın bu sabah...bense bambaşka..... 

hafifce eğildin kulağıma ve dedinki (ben SENİ SEVİYORUM.. 

ama şimdi gidiyorum uzaklara kalbimde götürüyorum seni affet beni izinsiz düşlerime saracağım cismini.......)

ağlıyordun sen ilk kez seni ağlarken görmüştüm.....sanki sen değil yüreğim ağlıyordu....adına türküler yakan dilim sus pus olmuştu.....nereye gidiyorsun bile diyemiyordum... 

diyemiyordum çünkü korkuyordum seni artık uzaktan bile sevemiyeceğimi duymak istemiyordum.... 

elimi tuttun birden zaten kalbim gözlerime baktığın vakit son çarpmalarındaydı bir de teninin dokunuşu beyin ölümünü de gerçekleştirmişti.....ve daha sımsıkı kavrayamadığım o pansuman pamuğu ellerin kayıp gitmişti o an..... 

savaş meydanında yenilgiye uğramış bir kumandan misali diz çöktüm bulunduğum yere...gitme....ne olur gitme...bırakma beni.....ecelin darağacına...yalvarırım benide götür....umutsuzluğun kol gezdiği o umarsız yarınlara... 

sevdiğini söyledin beni sen bilmiyorsun ama ben inan ilk defa sevindim ve şimdi gidiyorum diyorsun bana ben seni sensiz yaşarken bin defa öldüm ama şimdi gidersen SEVGİLİM şunu bilki bu defa ölmekle kalmam her adım atışında bilirim ölümün ötesinin tarifi olmaz ancak ölümden öte ölürüm yani her ruh sorguya çekilir fakat benim sorguya çekilecek ruhum bile kalmaz yalnız cesedim değil ruhumda ölür sen beni bırakıp gidersen.......ama biliyorum sen ölü bir ruhta bile ölmeyecek kadar ölümsüzsün......... 



------------münhasıran', 'bir başka sabahtı bu sabah sevinç ve güzün bir arada kol kola  bambaşka duygulardayım sevineyimmi üzüleyimmi bilemiyorum.....onca yıl koştum...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olmeyecek-kadar-olumsuzsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıplardayım(versionic)', 'kayiplardayim-versionic-ozay-karakus-0r3y0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözümde nefret uykusuz uykulardayım 

yüzümde tebessüm şuursuz korkulardayım 

sözümde isyan var duygusuz şarkılardayım 

başardınız sonunda yokum ben artık kayıplardayım 

kalbimde hiçbir ümit teselli kalmadı zararlardayım 

gönlümde tek bir keder faydasız yararlardayım 

içimde sonbir telaş anlamsız biçare kararlardayım 

kazandınız sonunda yokum ben artık kayıplardayım 

bileğimde zincirler kaçılmaz yüce yargılardayım 

yüreğimde zehirler aşılmaz nice kaygılardayım 

dileğimde engeller yaşanmaz ince duygulardayım 

oldu işte sonunda yokum ben artık kayıplardayım 

önümde yarınlar kayboldu cevapsız sorgulardayım 

yönümde yılanlar çok oldu plansız kurgulardayım 

dünümde kalanlar hep soldu yalansız vurgulardayım 

doldu işte sonunda zamanım yokum artık kayıplardayım



------------münhasıran', 'gözümde nefret uykusuz uykulardayım  yüzümde tebessüm şuursuz korkulardayım  sözümde isyan var duygusuz şarkılardayım  başardınız sonunda yo...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kayiplardayim-versionic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıplardayım', 'kayiplardayim-ozay-karakus-8f976', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'soruyorum yüreğime geçmişim nerede diye ama dur söyleme sus kalbim biliyorum kayıplardayım 

yıllar önce gülüyor iken şimdi acılarla sınanıyorum 

varoluşumun amacından uzakta isyanların eşiğindeyim 

benliğimin kimliğimin belgesi buruşturulup atılmış hayallerin dipsiz kuyusuna ve ben gözü kara dalıyorum içine arıyorum ama bulamıyorum ve anlıyorumki kayıplardayım..... 

içimde bir buzdağı oluşturulmuş en sıcak duygularda bile bir cm erimiyor hislerim..bir başkasıyım artık sizin dünyanızda 

bambaşka bir yabancıyım...gülmelere yabancı sevmelere yabancı hayallere yabancı ümitlere yabancı........cesaretim katledilmiş katilim ise mechullerde izini kaybettirmiş yalnızca gölgesi hafızamda elini kolunu sallayıp geziyor rüyalarımda....şekillendiremiyorum artık zihnimde bir çiçeğin tomurcuğunu bile şekilsizim kayıplardayım.... 

ayrılık vakti yaklaştı artık elveda dünya elveda içinde bulunan 

topluluklar...gidiyorum her nefeste son nefes gibi ölümün adresindeyim....şevkatli kollarıyla beni sarmasını bekliyorum bütün şiddetiyle..öyle bir sarsınki beni en büyük depremlerde bile cesedim dışa vurmasın sizin dünyanıza bedenim temas etmesin...etmesinki yeniden kirlenmesin çürümeye yüz tutmuş 

kabir azabındaki vücudum...yeni baştan günahlarınızla... 

rahatsız etmeyin beni artık topraklardayım ve kayıplardayım.. 

uğramam artık değil semtinize düşlerinize bile.... 

kurtuldum ya cefanızdan kurduldum ya yalan dostluğunuzdan 

bu bana yeter gayrı bahçenizde yetişen en küçük fidana bile gübre olup hayat vermem asla size ait olana.....şimdi sahip çıkma zamanı bana ait benim olana.... 

yokum ben var olan yokluklardayım evet belki bir serseriyim ama sonunda başardım ve ben kazandım......kayıplardayım 



------------münhasıran', 'soruyorum yüreğime geçmişim nerede diye ama dur söyleme sus kalbim biliyorum kayıplardayım  yıllar önce gülüyor iken şimdi acılarla sınanıyo...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kayiplardayim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşarken de Ölünür', 'yasarken-de-olunur-efsun-aydin-6pmml', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamsal davranışlardan uzak,

Kendin gibi olmaya korkak 

En kötüsü de aşkı çıkarmışsın hayatından…

Bir engelli hisse yenik,

Hala bendesin.

Senin çık dediğin o kapıdan

Ben hergün isimsiz girdim.

En güzeli de,

Sen de bunu hep bildin.', 'Yaşamsal davranışlardan uzak, Kendin gibi olmaya korkak  En kötüsü de aşkı çıkarmışsın hayatından… Bir engelli hisse yenik, Hala bendesin. S...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasarken-de-olunur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Beni Hiç Öldürme', 'sakin-beni-hic-oldurme-huseyin-erdogan-2fzz8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu gün bir başka gülüyor yüzüm

sana kavuşacağım diye 

bir umut düştü yüreğime

bir bak istersen şimdi resimlerime

ışıl ışıl değil mi gözüm? 

birdenbire bu kış mevsiminde bile

bahar geldi gönlüme

rengarenk çiçekler açtı sevgime

seni tanıyıp da sevdiğimden beri

hep senin kokunu çekiyorum içime

zaten her gecenin zifiri karanlığında

bir tek sen pırıl pırıl çıkarsın semaya

bil ki sevgili şiirim ben de seni

gece yarılarında evimin balkonunda 

hayranlıkla seyrederim doya doya

ne de muhteşem huzur verirsin bana

sen tek yıldızsın benim dünyamda

ömrümce baksam da doyamam sana

ışığınla uzatıver ellerini benden yana

seni hapsedeyim yüreğimde yaşadıkça

çektim perdeleri kilitledim yüreğimi

seni benden başkası göremesin diye

inan ki sen bende yaşayacaksın ömrümce

ne olursun sende sakın beni hiç öldürme

                                        09.02.2006

                                   Hüseyin Erdoğan', 'bu gün bir başka gülüyor yüzüm sana kavuşacağım diye  bir umut düştü yüreğime bir bak istersen şimdi resimlerime ışıl ışıl değil mi gözüm?  ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sakin-beni-hic-oldurme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komşunun Ölümü', 'komsunun-olumu-metin-yalti-veohb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün, 

Siteden çıkışta gördüm başkanı 

Asıktı yüzü 

Selamımı almadan daha 

Ölmüş dedi, kırk bir numara… 

Sarsılmıştım. 

Şaşkın, şaşkın sordum 

Kimdi bu kırk bir numara? 

Hiç tanımamıştım 

Üç yıldır otururmuş bizim sitede 

Başkan anlatsa da bildiğince 

Bir çağrışım yapmadı genede. 

—İşin yoksa camiye gidelim birlikte dedi 

Gittikte… 

Oturduğumuz site dört yüz konutluktu 

Anadolu’daki çok kasabadan büyüktü. 

Oysa büyüdüğüm kasabanın 

Çoğunu ben, diğerleriyse beni 

Böylece herkes birbirini tanırdı. 

Düşündüm de bizim katta 

Karşı dairede kim otururdu? 

Caminin geniş avlusunda 

Ölenin yakınları olmalıydı 

Şu köşede ağlaşan bir avuç insan. 

Ve amacından soyutlanmış gibi duran 

Birbirine yabancı bir sürü insan. 

İçlerinden biri yaklaştı yanıma 

—Başınız sağ olsun dedi 

Sadece göz aşinalığından. 

Namazdan çıkan 

İnançlı bir kısım insan 

Başında saf tutunca tabutun 

Katıldık bizde. 

İşini biliyor imam. 

Düzgün ve sık tutun dedi safı 

Önce tanımladı namazı. 

Dualar edildikten sonra 

—Merhumu nasıl bilirdiniz sorusuna 

—İyi bilirdik dedi cemaat topluca. 

Dudağımı ısırmışım 

Acı gülüşümü bastırmak isteyince. 

Üst üste üç kez 

—Hakkınızı helal ediniz dedi imam 

Helal olsun dedik üst üste. 

Hakkımız varmışçasına… 

Yükselince tabut 

İtiş kakış arasında omuzlara 

İnancım doğrultusunda 

“Yolun ışıklı olsun “ dedim bir fatihayla. 

Komşuluk derdi sevgili babam 

“Doğana beşik, ölene tabut olmaktır” 

Anımsayınca bu sözünü 

Saklayıp nem yürümüş gözümü 

Uzanıp dokundum sessizce tabutuna, 

Selam yolladım babama usulca 

Sonsuzluğa erişen komşumla… 

08.02.06', 'Dün,  Siteden çıkışta gördüm başkanı  Asıktı yüzü  Selamımı almadan daha  Ölmüş dedi, kırk bir numara…  Sarsılmıştım.  Şaşkın, şaşkın sordum...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/komsunun-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uefa', 'uefa-ozay-karakus-wappl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kaderin başlama düdüğüyle başlamıştık aşkımıza 

sen sağlı sollu ataklarla gönül sahama girmeye çalışıyordun 

bense kalp kale`me çelikten bir nefret ağı örmüştüm 

sen umudumu boşalttığım alanlarda sevgi pasları yaparken 

ben şuursuzca yapılan preslerde yeni savunma varyasyonları deniyordum.öyle enteresan bir taktikle oynuyordun ki bu oyunu ne tandem duygular nede sarkık gönüller kar ediyordu.baklava tarzı yayarken düşlerimi kanatlara göbekten açık veriyordum aşk maker`ına.hızlı hücüma 

kaldırırken o gönül forvetlerini bense kalbimde bloklar arası 

bağlantıyı bir türlü sağlayamıyordum.sen kin dolu gönlümün ceza sahasına girmek için depar atarken ya demarke vaziyette kalıyor yada girmeden indiriyordum duygu forvetlerini acımasızca sevgimi kaybettiğim yere.sen kalp kale`sine endirek kullanırken serbest kalp atışlarını bense kin barajını bozan içimdeki son sevgiyi ikaz ediyordum.kavisli yaptığın aşk ortasında hisle buluşan duygu forvetini yaka paça yere indirirken yüreğimin son sevgi tohumu, penaltıya neden olmuştu yaşımın 18`i içinde.kader tarafından kırmızı kartla cezalandırılırken kartlaşmış kalbimin kenar yönetimi 1 duygu eksik kalmanın ve senle nasıl mücadele edilebileceğinin kaygılarını taşıyordu.sen atışı kullanmış ve ilk aşk golünü atmıştın nefret ağlarıma.eksik kalmanında verdiği dez avantajla sinir sistemim 3-5-2 den 4-4-1`e dönmüştü.artık tamamen bilinçsizce saldıran aşka sevgiye küsmüş umutsuz duygularım gönlümde boşluklar veriyordu ve sen o boşluklardan fazlasıyla yararlanıyor netice aşk gollerini ardı ardına sıralıyordun.evet sonunda yenilmiştim tarihi bir hezimete uğratmıştın beni.evet kazanmıştın bu aşk oyununu hemde yüreğinin hakkıyla hakederek.UEFA yani ULAŞILABİLECEK EN FAZİLETLİ AŞK fedarasyonu sana kalbimin sevgi kupasını takdim ederken bense hüzünle karışık bir mutluluk yaşıyordum yenilmenin verdiği moral bozukluğuyla.neticede de sana ait senin olmuştum.ben senin aşk müzende, kazandığın ilk ödül; sense benim gönül paketimde kaybettiğimi sandığım en büyük hediye oldun..... 

------------münhasıran', 'kaderin başlama düdüğüyle başlamıştık aşkımıza  sen sağlı sollu ataklarla gönül sahama girmeye çalışıyordun  bense kalp kale`me çelikten bir...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uefa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikanlı Gibi', 'delikanli-gibi-ozay-karakus-wj96t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 've ben gidiyorum, çaresiz ümitsiz yüreğimle, söz verdiğim gibi 

sana herşeyimi bırakıp senden tek birşey almadan, 

adımlarım metreyle ölçülmüyor hız ayarı bozulmuş ibresi çatlamış ayaklarla, sanki koşuyorum her adımda, rakımı yükselen kaldırımlarda......delikanlı gibi... 

ve ben düşüyorum, zaman zaman hasretin tuzağına 

gözümde özlem bulutu,ateşler içinde üşüyorum,ayrılık yağmurunda,kurallarım çiğnenmiş, yasalarım ibra edilmiş 

kendi kanunlarımla yargılanıyorum,kanunsuz bir yüreğin gönül mahkemesinde,..........delikanlı gibi... 

ve ben susuyorum,susma hakkımı kullanıyorum son arzum mahiyetinde,iftiraya uğramış suçsuz bir aşığın en masum halini oynuyorum metrajı kısaltılmış yayın hakkı gasbedilmiş kendi filmimde,rol icabı öleceğimi düşünenler öldüğümün farkında bile değiller........delikanlı gibi.... 

ve ben kusuyorum,içimde kalan son nefreti,nefret etmeden 

en saygın duruşumla, ve seni vicdanının sesini bile vicdansız 

dinlerken duyuyorum,sorunsuz durgun kalp atışlarımda 

hissediyorum şimdi hissetmediğim yada hissedemediğim onca 

güzel duyguları ve anlıyorum senin bende bittiğini senin kalpte öldüğünü...ama ben senin gibi aciz bir yüreğin çarpması gibi vermiyorum, teslim etmiyorum bu canı 

suratına çarpılmış çelik bir kapı şiddetinde can verip 

aşkımı namazı kılınmadan gömüyorum karanlıklara.... 

tahmin edeceğin gibi........delikanlı gibi..... 

------------münhasıran', 've ben gidiyorum, çaresiz ümitsiz yüreğimle, söz verdiğim gibi  sana herşeyimi bırakıp senden tek birşey almadan,  adımlarım metreyle ölçülm...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/delikanli-gibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelmeyince', 'sen-gelmeyince-ozay-karakus-s6ljf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ümitsiz hasreti öldüremem ben 

ıslanır yanağım sen gelmeyince 

şekilsiz suratı güldüremem ben 

bükülür dudağım sen gelmeyince 

hayalin gözümde ateştir yanar 

sensizlik özümde yaradır kanar 

özlemin yüzümde buzuldur donar 

neyleyim resmini sen gelmeyince 

gelmezsen bedenim mezara iner 

sevabın baş ucumda günaha döner 

yaktığın ateş son nefesle söner 

çürütür topraklar sen gelmeyince 

------------münhasıran', 'ümitsiz hasreti öldüremem ben  ıslanır yanağım sen gelmeyince  şekilsiz suratı güldüremem ben  bükülür dudağım sen gelmeyince  hayalin gözüm...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-gelmeyince-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milletimin Hepsi Aydındır', 'milletimin-hepsi-aydindir-yusuf-onder-bahceci-xhtrc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim Milletimin hepsi aydındır,

Yüzlerinde aydınlık var aydındır,

Bu aydın sınıfı kimlerin ayıbıdır,

Benim Milletimin hepsi aydındır.

Ne diyor Atatürk iyi dinleyin be,

Köylü Milletimin Efendisidir be,

Ben aydınım diye hava atmayın,

Benim Milletimin hepsi aydındır.

Aydınım diyor da aydınım diyor,

Sorsan yeniçağı, çağı bilmiyor,

Papağan gibi  ay aydınım diyor,

Benim Milletimin hepsi aydındır.

Gerçek aydın olan aydınlık olur,

İçi dışı bir olur, adam mert olur,

Avrupa''ya karşı biraz sert olur,

Benim Milletimin hepsi aydındır.', 'Benim Milletimin hepsi aydındır, Yüzlerinde aydınlık var aydındır, Bu aydın sınıfı kimlerin ayıbıdır, Benim Milletimin hepsi aydındır. Ne di...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/milletimin-hepsi-aydindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüncelerdeyim', 'dusuncelerdeyim-ozay-karakus-ytq6d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'geciyorum yine aynı dar sokaklardan 

her gece olduğu gibi düşüncelerde 

bak yine beyazlandım şakaklardan 

her gece olduğu gibi düşüncelerde 

ağır aksak adımlıyorum kaldırımları 

her gece olduğu gibi düşüncelerde 

sağır kör yudumluyorum yıldırımları 

her gece olduğu gibi düşüncelerde 

sonu olmayan belirsiz olgulardayım 

her gece olduğu gibi düşüncelerde 

yıpratılmışım belgisiz bulgulardayım 

her gece olduğu gibi düşüncelerde 

------------münhasıran', 'geciyorum yine aynı dar sokaklardan  her gece olduğu gibi düşüncelerde  bak yine beyazlandım şakaklardan  her gece olduğu gibi düşüncelerde ...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dusuncelerdeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumun Şeffaf Küresi', 'ruhumun-seffaf-kuresi-ozay-karakus-d10am', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kapandı kalbimin yine hücresi 

canıma kelepçe takıyorsun 

kırıldı ruhumun şeffaf küresi 

sebebsiz dünyamı yıkıyorsun 

aklımda bir sendin somut düşünce 

durdu bak beynim komut gidince 

ne anlamı var aşkın umut bitince 

gözümden yaş gibi akıyorsun 

kanımın damlası sel olur akar 

temas ettiği yeri kavurur yakar 

içimde fırtına şimşekler çakar 

yüreğime kurşun sıkıyorsun

------------münhasıran', 'kapandı kalbimin yine hücresi  canıma kelepçe takıyorsun  kırıldı ruhumun şeffaf küresi  sebebsiz dünyamı yıkıyorsun  aklımda bir sendin som...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ruhumun-seffaf-kuresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni de götür', 'beni-de-gotur-selahattin-yetgin-cma38', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana gelmeyişim, seni aramayışım

Güneşsiz fidanın büyümesi gibi

Sonsuz acıları gömüp yüreğime,

İnsan kalabalığında seni unutuşum

Unutmak değil, bil ki yürek yangınım.

Yaşamak, sensiz bir yolculuk,

Gökte uçan ipsiz bir uçurtma

Ve bu yaşamın eğri büğrü hali.

Kaldıysam sensiz ayakta, bir taş gibi

Öfkemin katmanlarına yumruk vurup,

Sarsılıp ağlamak sıcacık omuzlarında

Ne kadar özledim, bilir misin? 

Bilir misin, nasıl kar yağar sensiz üstüme.

Geceler olmasa, katlanırdım yokluğuna,

Onlar bin soru şimşeğini çaktırır bana,

Kopan umut ipliklerinin renkli ucunda

Mor mor çiçekler yetiştirirdim bahçemde.

Al beni benden, göçmeden kuşlar

Bilinmeyen diyarlara uçur beni

Yitmiş senelerin acılarını çekemiyorum

Beni de götür, anılarının sıcak kucağına.

Hangi hoyrat rüzgara yalvarsam,

Aç denizlerden umut dilensem,

Kader dediğin ya ağıt, ya türküdür

Hangi şarkılardan seni istesem? 

Al beni, gümüş aynalı odalardan,

Masallarındaki ülkene götür sık sık,

Sana sevdam büyüyor her geçen gün

Tırmanır içimde deli bir sarmaşık.', 'Sana gelmeyişim, seni aramayışım Güneşsiz fidanın büyümesi gibi Sonsuz acıları gömüp yüreğime, İnsan kalabalığında seni unutuşum Unutmak değ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/beni-de-gotur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümname', 'olumname-ozay-karakus-dd6hf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'her gün aynı işkence aynı zulüm................ 

paspasla zedelenmiş baygın fayanslarda kaygan zeminler üzerinde yalıtımsız duvarlara dayanarak yürümeye çalışıyorum.. 

koridorlar labirent destekli, ne girdiğim yeri ne de çıktığım yeri biliyorum............. 

dalgın yürüyüşlerde salgın hastalığımın çaresinin yollarını arıyorum......ne çare bulamıyorum...... 

sinirleniyorum......kızıyorum........huysuz bir ihtiyar portresi çiziyorum karşımda duran bön,avanak bakışlara........ 

kabullenemiyorum....inkar ediyorum illetimi.......dürüst dudaklarım sahtekar boyutunda türevsel yalanlar türetirken sus pus olmuş konuşmama eğiliminde...içten içe kadere sitem ediyor........biliyorum yolun sonundayım.... 

yine biraz sonra adı UMUT olan umutsuz doktorun kapısını çalacağım bir ümitle......öyle tahmin ediyorum ki yine teselli edilecek yeni bir kontrole tabi tutulacağım ama ne değişecekki 

zaten benim ayım günüm güneşim tutulmuş.....ışıksızım soğumuşum....yüreğim yangınlarda...........yansıtamıyorum 

artık tatlı gülüşleri gamzeli tebessümlerde..... 

fire vermişim şakalarıma.......saçmalıklarda espri yeteneğim.. 

starı verilen ömrüm henüz yolu yarılamadan finişe yaklaştı... 

...ikmallerdeyim..... 

Ey sevdiğim kadın ve onun masum hediyesi canımın içi biricik yavrum; farkında değilsiniz benden bi habersiniz........ 

pembe panjurlu evinizin kapı ve pencerelerini kapatmayı unutmayın...sakın ha açık bırakmayın....yakında karamsar yeller esecek üzerinize çok uzaklardan.... 

Aşkım...kadınım...aşkımızın meyvesini kurutma ne olur... 

ona söylediğin yalan kısa zamanda gercek olacak...bu yalandan kurtulacaksın... 

oğlumun al yanaklarında seni öptüğüm ilk günün utangaçlığını 

gör emi....benim için defalarca öp yavrumun yüzündeki mahçup ifadeyi.... 

eğer bir gün yavrum babasını soracak olursa onun boynuna dudaklarını sürt ki babasının senin dudaklarına bıraktığı sevgi ve şevkati tatsın oğlum...babasının ne kadar yürekten sevmesini bilen insan imajının farkına varsın....yokluğumu hissetmesin...yokluğum yalnızca senin öksüz bırakılan ellerinde ve yetim kalan gözlerinde kalsın... 

son günlerimdeyim ben odamın ışıklarını söndürdüm nasılsa yansalarda bir müddet sonra aydınlatmayacaklar kararmış gözlerimi..... 

şimdi yanında hiç bir meftanın bulunmadığı ıssız bir arazide boş bir mezar arıyorum.....bana söylemiyorlar ama ben biliyorum....................... 

.........yakında çok yakında.......öleceğim....... 

elveda sevdiğim elveda bebeğim elveda yavrum elveda........ 

------------münhasıran', 'her gün aynı işkence aynı zulüm................  paspasla zedelenmiş baygın fayanslarda kaygan zeminler üzerinde yalıtımsız duvarlara dayana...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olumname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-turk-oger-koc-wcqb3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'senin

yüreğinde ben

benim

yüreğimde memleketim

zaman ayarlı

bomba gibi

yelkovanı saatin

atar dururdu zamanı

tik tak ları bırakarak

boşluğa

sen

beyaz gelinlikli

birini 

hayal ederdin

bense

baharını 

memleketimin

nasılda yeşerecekti ovalar

nasılda açacaktı çiçekler

kuşları karıncaları sevecektim

ellerimi sevecektim

özgür bileklerimi

su katılmamış

sütler içecekti bebekler

soğuğa yenik düşmeyecektiler

sonra

bir gelin

olacaktı elbet

kara yağız yiğit

başları 

öne eğik olmayan

torunların olacaktı

belki

anlayacaktın beni

belki

o zaman bende seni

sevgi

her şeyi

anlamak değilmiş

anne

sevgi 

her şeyi yaşamak 

değilmiş

yarım

yamalak ta olsa

korkuyu taşımakmış

acıyı özlemi

benim

zamanım

hiç olmamıştı

düşünmelere 

anne

şimdi

her şeyin var

yiğit bir gelinin

başları dik

torunların

bahara özlem dolu

oğlun var anne

bahar 

nasıl bir şey

bilir misin 

anne

koyun kırkarken

ıtır kokularını

burna çekmek 

değil

yada dalından

koparılmış

elmayı dişlemek

taze yapılmış

bir şarabın ılıklığı

korkmamak anne

yarınlardan

korkmamak insanlardan

bir gece yarısı

kapının çalınmaması

yatağından sıçramamak 

vatanını severken

anne

şimdi

her şeyin var anne

korkularımız büyüse de

2006-02-09', 'senin yüreğinde ben benim yüreğimde memleketim zaman ayarlı bomba gibi yelkovanı saatin atar dururdu zamanı tik tak ları bırakarak boşluğa s...', ARRAY['Türk Edebiyatı','Şiir','Türk Öğer Koç']::text[], 8.5, '{"poet":"Türk Öğer Koç","poet_slug":"turk-oger-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/anne-199-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birleşimlerin Şairi', 'birlesimlerin-sairi-ozay-karakus-j9f58', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'o akşam yeniden parmaklarına davet etti,bir daha yazmamak üzere çekmecesine gömdüğü mürekkepi tükenmeye yüz tutmuş rengi elinin kirinden karamsar karalara belenmiş bir zamanlar erciyes zirvesi beyazını yansıtan kalemini.... 

ayın solduğu mehtabın küstüğü bir akşamdı o akşam.... 

baykuşlar bile susmuş bulutlar kızgın şimşeklere kırgındı 

çiçekler goncalarına açmamaları yönünde tehditkar davranışlar sergilerken isyan edip dayatmalara aldırmayan bir demet orkide hüznü içine çekerek ağlıyordu.... 

şair de ağlıyordu derisine temas eden elini yakan son sigarasının son dumanını iflas etmiş ciğerlerine salıyordu.... 

bu son,bu defa son; yemin bozmak yok diyordu..... 

....gözlerinden iki nehir boşaldı ayrılık denizine..... 

masasının sol yanında bulunan; kabına sığmadığını,dalgalarının med-cezir edasında kabardığını farkettiği çöl tozu yutmuş şiir defterini derin bir hayıflanma ile açıp okumaya başladı...her satırda duraklıyor her kıta da her mısrada üzüntüsü katlanıyordu...fakat içine sinmiyordu eksik bir şeyler vardı bir iki harf noksandı her sayfada...ve çıkartamıyor bulamıyordu na tamam harflerin ne olduğunu....eksiklik her sayfanın anlamını yitiriyordu...şairde anlamını yitirmişti kendince...ilk defa kendini yardıma muhtaç hissetti... 

etrafına bakındı...önünde duran ahşabı sirkülasyona uğramış masasından ve üzerinde güç bela denge sağlayabildiği bir ayağı topal iskemlesinden bir de üstüne gazete parçalarından elbise yaptığı çıplak duvarlardan başka hiç bir şey göremedi.... 

....ve şair yakındı.....yaşlılığından yoksulluğundan kimsesizliğinden çaresizliğinden.... 

şimdiye dek hiç bir zaman hiç bir şiirinde imdat kelimesini kullanmamamıştı ama şimdi bu sözcüğün her bir harfinden ayrı bir anlam çıkartıyordu....şair utanıyordu.....sessiz çığlıklarda haykıran feryatlar beyninde volkan gibi kaynıyordu 

bir ara imdat imdat dememek için ağzını yapıştırmayı bile düşündü...sonra bunu kendine yakıştıramadı...oysa o na zamanında ne çok şey yakıştırmışlardı...güzel olan herşey onunla anılıyordu onunla anlam kazanıyordu.... 

şair iki dudağının arasında bir gedik açtı...........yutkundu yutkundu ve küskün kelimelerle dört beş nefeslik barış imzaladı..... 

.........sözlerinden iki zehir boşalttı ayrılık limanına.... 

duyguları şiirleri sayesinde onca ayrılığı sona erdirmiş onca ayrılanın birleşmesine vesile olmuştu....aslında şairin yoksulluktan yaşlılıktan şikayetci değildi...onun isyanı kimsesizliği çaresizliği velhasıl bunca yıldır aynı yastığa baş koyduğu yaşama sevinci hayat ışığı sevginin manası şiirlerinin ilham kaynağı sevgi pınarı biricik ve tek aşkı birtanesi kadınının bu vefasız dünyadan göçüp onu bir başına yalnız bırakmasıydı......şair ayrılmıştı canından; canına kıymak istiyor ama mahşerde kavuşamamaktan korkuyordu....ayrılığa savaş açmıştı hep nicelerine zafer kazandırmıştı lakin kendi yenilmiş hüsrana bozguna uğramıştı. 

. 

.....şair daldı yüreğindeki sığ ummanlara...şair kopmuştu... soyutlamıştı kendini zihnindeki hain zulümkar azaplardan.. 

o an felsefesinden idealinden ödün vermemesi gerektiği fikrine vardı...birleştirmeliyim dedi ama birleştireceği tek bir canlı yoktu çevresinde....arandı arandı bir nesne takıldı gözüne 

aldı eline ve başladı kenarları yırtılmış sayfaları birleştirmeye 

daha önce ne kadar da çok şey birleştirmişti...bu onun sanatının bir parçasıydı...çünkü o BİRLEŞİM`lerin ŞAİR`iriydi...

------------münhasıran', 'o akşam yeniden parmaklarına davet etti,bir daha yazmamak üzere çekmecesine gömdüğü mürekkepi tükenmeye yüz tutmuş rengi elinin kirinden kar...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/birlesimlerin-sairi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahımı Yanıma Getirin', 'gunahimi-yanima-getirin-ozay-karakus-x0s7s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kapanmış gönlün kapıları ardına kadar...umudun anahtarını kefensiz karanlığa gömdüler.....sevdama bir baş sağlığı dilemeden çekip giden hayallerin gerisinde kalan bir nokta düş 

tüm gayretiyle beynimde var olma savaşı veriyor..... 

yırtılmış yarınlara yıpratılmış dünlerle ulaşmaya çalışıyorum.. 

uzuvlarım hareket kabiliyetinden bi haber duyguların keşifinde yeni heyecanlara soluksuz iç çekerken yüreğime pompalayabildim bir kaç zerre nefes ona olan nefretimden olsa gerek çoğalıyor sigaranın kölesi ciğerlerimde giderek... 

aceba bu beni bekleyen sonun,ölümün habercisinin kalbimin butonlarına deneme mahiyetinde alaylı basışlarımı yoksa hedef tahtasına dönüşmüş zedelenmiş vucudumun zihnimde cereyan eden olaylara aklımda izinsiz yapılan gösterilere eylemlere farklı bir yandan bakışı ayrı bir yaklaşımımı.... 

ya da çiğnenmiş bedenimle sonsuzluğa iltica talebinde ki ruhumun sevdası kirletilmiş koklaşımımı... 

kim bilir belki de yufka yüreğimi mangal zannedip etimi kemiğimden ayırıp pişiren aç duygularını doyurmaya çalışan o aç gözlü vicdansızın ağzından damlayan kanın solmuş damarlarımdan enjekte edilmiş olması ve o kanın ak olan yuvarlarını ala bulaması ecele yaklaştırmıştı beni ansızın.... 

artık değil yüzünü görmek sesini bile duymak istemiyorum o şeytan suratlı kansızın.....ölüm anında hissedilen susuzlukta hani şeytan elinde bir bardak su ile gelir RAB`bini inkar et dermiş ya...inanın ondan değil o suyu o imansız o kitapsız getirecek diye korkuyorum ve de ürküyorum iki kez ölmek istemiyorum....... 

şimdi gülümsemelerim bile benimsemelerim kadar benliğini yitirmiş ağlamalarım nemrut gibi kibirli.....her hangi bir nesneye tek dokunuşumda, temasımda binlerce çiçeğin solduğunu boynunu büktüğünü hissediyorum hisden habersiz organ mafyaları tarafından işe yaramaz denilip çöplük halini almış vücuduma gelişi güzel geri iade edilen duyu organlarımda...... 

varoluş nedenimin sınırlarını çoktan aşmışım.....yok olmam için bir tanecik ilk ve tek günahım yeter de artar bana....sevap sandığım çemberini ateşlerin çevrelediği günahım.....ve o günah evet tahmin edeceğiniz gibi o insafsızın 

ta kendisi...haydi artık yetiş bana ölüm gelde çekeyim günahımın bedelini yanayım nar ateşlerde yalnız günahımı da yanıma getirin ki onun da yanıp kavrulduğunu gözlerimle göreyim..................................... 

------------münhasıran', 'kapanmış gönlün kapıları ardına kadar...umudun anahtarını kefensiz karanlığa gömdüler.....sevdama bir baş sağlığı dilemeden çekip giden haya...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunahimi-yanima-getirin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okuyun Okuyun Okuyun Okutun', 'okuyun-okuyun-okuyun-okutun-yusuf-onder-bahceci-7k8m7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Okuyun, okuyun, okuyun, okutun,

İslam''ın ilk emridir okuyun diyor,

Soruyorum size bunlar ne diyor,

İslamın ilk emridir okuyun diyor.

Bizler okumadık böylece kaldık,

Eller aya gitti biz ise yaya kaldık,

Parmağında oynatırlar aldatıldık,

İslamın ilk emridir okuyun diyor.

Haşa İslam cahil değil, olamaz,

Okumayan gerçekleri anlamaz,

Oynanan oyunları da çakamaz,

İslamın ilk emridir okuyun diyor.

Okuyanlar öğreniyor imanı, feni,

Okuyanlar öğreniyor dini, imanı,

Elimiz de yok ki berat fermanı,

İslamın ilk emri okuyun diyor....', 'Okuyun, okuyun, okuyun, okutun, İslam''ın ilk emridir okuyun diyor, Soruyorum size bunlar ne diyor, İslamın ilk emridir okuyun diyor. Bizler ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/okuyun-okuyun-okuyun-okutun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Dişi Halimsin', 'sen-benim-disi-halimsin-onder-karadag-ht4so', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 've sevdamsın

dinimsin

dilimsin

noktasız 

şiirimsin

senden başka

kimim

kimsem

yok benim

sen benim dişi halimsin!', 've sevdamsın dinimsin dilimsin noktasız  şiirimsin senden başka kimim kimsem yok benim sen benim dişi halimsin!...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-benim-disi-halimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dım Dım', 'dim-dim-ozay-karakus-vcxwb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kimliğim adım 

lezzetim tadım 

tarihim miadım 

sana susadım 

didikledim aradım 

izlerini taradım 

ben kimim yaradım 

kaderimi karadım 

koştum adım adım 

yürüyüşüm inadım 

isteğim muradım 

sana can adadım 

kavuşmak maksadım 

zaman oldu aksadım 

gerçi artık kanıksadım 

ayrılığı bile kutsadım 

ateşler de yandım 

sensizliğe boyandım 

kabuslarda uyandım 

yalnızlığa dayandım 

bir nefes aldım 

bin nefes saldım 

öylece kaldım 

kapını çaldım 

yataktan kaldırdım 

üzerine saldırdım 

kollarına aldırdım 

rüyalara daldırdım 

bıkmadım yıldırdım 

ne yapayım çıldırdım 

o ana neler sığdırdım 

cenazeni kıldırdım 

yokluğunda morardım 

halimi hayra yorardım 

resimlerine sorardım 

hayalden yuva kurardım 

adını ismini anardım 

için için kanardım 

alevlenmiş nardım 

kendi içimde yanardım 

bazen tek başına donardım 

hemen gidip onardım 

sobanın başına konardım 

aklımı yitirir bunardım 

sensiz kalınır sanırdım 

ne bilir ne de tanırdım 

buna ne çok inanırdım 

olmadı eşek gibi anırdım 

daha önce de yaşardım 

ne zorluklar aşardım 

durdurulmaz taşardım 

bilsen neler başardım 

hayalden hayale koşardım 

içimde umutları taşırdım 

mutluluktan öte çoşardım 

seni görür görmez şaşırdım 

senin için herkese dalaşırdım 

suçlu veya suçsuz bulaşırdım 

an gelir korkar çalıyı dolaşırdım 

gururumu yener sana ulaşırdım 

genelde başımı belaya sokardım 

nezarete abone girer çıkardım 

dört beş polis aynı anda yıkardım 

hatırlarmısın nasıl da sıkardım 

evet biliyorum çok sakardım 

ayağımı bir yerlere takardım 

alnımı mutlak duvara çakardım 

utanmadan bir de sana bakardım 

ne de güzel günlerdi unutmadım 

doğru söyledim hiç yanıltmadım 

ben bu aşkta bir kez kıvırtmadım 

sevdim seni gönlümü avutmadım 

gün geldi sana alındım 

boşluklara salındım 

senin arın balındım 

peteğinden çalındım 

gecelerce ağladım 

yüreğimi dağladım 

gönlümü bağladım 

sana aktım çağladım 

hep aşkımı kolladım 

derinlere yolladım 

beşiğimdin salladım 

geçtim acıları solladım 

kendimi azarladım 

bendimi pazarladım 

gözüm mavi nazarladım 

eridim çok nizarladım 

sonunda sona vardım 

etmedi kimse yardım 

ben acımı yalnız sardım 

harmanladım kardım 

sönsün gayrı ateşimi buzladım 

dinsin artık kan yaramı tuzladım 

çok acı çektim çok sızladım 

direksiyon bende bastım gazladım 

dumura uğradım afalladım 

sensiz fena çuvalladım 

alçaklara yuvarladım 

yaramaz sensiz işe anladım 

------------münhasıran', 'kimliğim adım  lezzetim tadım  tarihim miadım  sana susadım  didikledim aradım  izlerini taradım  ben kimim yaradım  kaderimi karadım  koştu...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/dim-dim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zikreyle', 'zikreyle-ozay-karakus-gn0jr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'açmış cennetin kapılarını her yandan 

bekliyor seni o büyük o yüce yaradan 

zaman yakın bir avuç toprak olmadan 

hamd eyle hamd eyle şükreyle,şükreyle 

bir düşün fikreyle her daim zikreyle 

toz pembe tatlı rüyadan uyanmadan 

vakit çatıp ecel kapına gelip dayanmadan 

nar_ı cehennem de kalıp yanmadan 

hamd eyle hamd eyle şükreyle,şükreyle 

bir düşün fikreyle her daim zikreyle 

bak koşuyor yaklaştı sana tahtadan atın 

gayet ince keskindir yolları sırat`ın 

hadi hala var iken senin fırsatın 

hamd eyle hamd eyle şükreyle,şükreyle 

ol kaim fikreyle her daim zikreyle 

daha dün bir çocuktun şimdi oldun kocaman 

nerde söylermisin sevdiklerin anan baban 

dilemek istemezsen Azrail`den el aman 

hamd eyle hamd eyle şükreyle,şükreyle 

ol kaim fikreyle her daim zikreyle 

tek bir nefesi yoktur ki örnek al mahlukattan 

geçirmez bir anını o Rahim ALLAH`ı anmadan 

kopmadan kıyamet fani dünya ziynetine kanmadan 

hamd eyle hamd eyle şükreyle,şükreyle 

irem naim fikreyle her daim zikreyle 

ağla aşk ile Afüv ALLAH(C.C)  korkusundan 

silkin artık kalk uyan bu gaflet uykusundan 

iç gerçek aşk şarabından ol islam fırkasından 

hamd eyle hamd eyle şükreyle,şükreyle 

irem naim fikreyle her daim zikreyle 

uzak dur nefsinden o şerri tağutdan 

al hisse Süleyman`dan Davut`dan 

şefaat beklersen o alem_i mahbubtan 

sarıl sünnete hamd eyle ümmet ol şükreyle 

havz_ı kevseri fikreyle eşsiz ismini zikreyle 

karanlık gecelerin aydınlık beyazında 

sıcak mevsimlerin rüzgarlı ayazında 

kıldığın her namazın her niyazında 

hamd eyle hamd eyle şükreyle,şükreyle 

gör mevti fikreyle çek tesbihi zikreyle 

------------münhasıran', 'açmış cennetin kapılarını her yandan  bekliyor seni o büyük o yüce yaradan  zaman yakın bir avuç toprak olmadan  hamd eyle hamd eyle şükreyl...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/zikreyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bana Sevdirdiler', 'seni-bana-sevdirdiler-ozay-karakus-xxwoy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'güllere sordum kokan dediler 

dillere sordum tadan dediler 

ellere sordum tutan dediler 

seni bana kana kana sevdirdiler 

yüzlere sordum bakan dediler 

gözlere sordum yakan dediler 

sözlere sordum anan dediler 

seni bana yana yana sevdirdiler 

yanağını sordum al dediler 

dudağını sordum bal dediler 

nefesini sordum tal dediler 

seni bana candan cana sevdirdiler 

hayalini sordum dal dediler 

dileğini sordum çal dediler 

yüreğini sordum kal dediler 

seni bana baştan başa sevdirdiler 

------münhasıran', 'güllere sordum kokan dediler  dillere sordum tadan dediler  ellere sordum tutan dediler  seni bana kana kana sevdirdiler  yüzlere sordum bak...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-bana-sevdirdiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Umut Yar Ya Umut', 'ya-umut-yar-ya-umut-murat-demir-rtmf5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ya umut yar ya umut

Diyerek çıktım yola

Bilmeden girdiğimi

Olmazlarla kol kola

Kime dönüp anlatsam

Ne düşünüp ne yapsam

Acılar pusu kurmuş

Nereye adım atsam

Neylesem ben neylesem

Bilmem kime ne desem

İçimde ki dertleri

Kim dinler ki söylesem

Ne işin var yollarda

Dediler erken erken

Gözlerime mil çektiler

Sana kavuştum derken

Neylesem ben neylesem

Bilmem kime ne desem

İçimde ki dertleri

Kim dinler ki söylesem

Kime dönüp anlatsam

Ne düşünüp ne yapsam

Acılar pusu kurmuş

Nereye adım atsam', 'Ya umut yar ya umut Diyerek çıktım yola Bilmeden girdiğimi Olmazlarla kol kola Kime dönüp anlatsam Ne düşünüp ne yapsam Acılar pusu kurmuş N...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ya-umut-yar-ya-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürkü Anarken', 'ataturku-anarken-husam-hasret-zo26w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neler etmedin neler bu asil millet için

Bölünmez toprağında kurdun Cumhuriyeti

Sarsılmaz bir güç ile medeniyet kerpicin

Elinle sıraladın ey Türkün saltanatı

Ereğe varmak için sırattan daha ince

Geçitleri aştın ki ey ulu, ey kahraman

Kurtuluş yollarını çizince de bir gece

''Ya istiklal ya ölüm'' buyruğunla söktü tan

Hakkında bin bir destan yazılsa da hele az

O kadar ulusun ki övülmek her an hakkın

Türk milletinin kalbi inan ki sensiz çarpmaz

Sen ki ona her kesten daha yakınsın yakın

Milletinle kaynaşıp bir güç ile şahlandın

Yadlara el olmaktan kurtardın ana yurdu

Benden sonra ebedi yaşayacaktır dedin

Sayende aynı güçle vatan ayatkta durdu

Bu yurda, bu vatana çepeçevre sarıldın

Ölüm cezasın verdin yurda kıyana Atam

Gönüllerde yerleşip, başlar üstünda kaldın

Mutluluk bağışladın ''Türküm diyene'' Atam

Yaşamak vardır Atam yaşam adlı canında

Yurdun dört köşesinde duyulmaktadir sesin

Hep dünya Türklerinin gönlünde, vicdanında

Hala yaşamaktasın, hala yaşamaktasın', 'Neler etmedin neler bu asil millet için Bölünmez toprağında kurdun Cumhuriyeti Sarsılmaz bir güç ile medeniyet kerpicin Elinle sıraladın ey ...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ataturku-anarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırgınlığım kendime', 'kirginligim-kendime-nazan-i-zmirli-qa8ru', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ertelenmiş düşlerden

ne kalacak

yaşamak  tadında

kırgınım 

kırgınım  kendime

maddeye  bağımlılık

bu   değil   istediğim 

ruhum! 

asılsızlık  peşinde.

bir  keman  sesi

bir  ney   mi

belkide; 

çocuksu

özlemim

buruş  buruş  kağıtta 

sıkıştırılmış

kırık  bir  taraktan 

çıkan

mızıka  sesinde

gizli.

özlenen huzurun

sesi

bir ses

bir ses

yaşadığını

yaşadığımı

hissettiren.

''ertelenmiş  düşlerimdeki en huzurlu ses, kırgınlığım kendime''

09.02.2006-antalya', 'ertelenmiş düşlerden ne kalacak yaşamak  tadında kırgınım  kırgınım  kendime maddeye  bağımlılık bu   değil   istediğim  ruhum!  asılsızlık ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kirginligim-kendime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koptun Sen Omurumda', 'koptun-sen-omurumda-ozay-karakus-8z76i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'iki büklüm eğilsin 

koptun sen omurumda 

inan lazım değilsin 

olmazsın umurumda 

somurulsun sağılsın 

duygular göğsünden 

her tarafa dağılsın 

kurtulam büyüsünden 

hesaplarda sorulsun 

sırıtan gülüşlerin 

yokuşlarda yorulsun 

kırıtan yürüyüşlerin 

hep yerlerde sürünsün 

o kibirli emellerin 

ateşlere bürünsün 

mahşerde amellerin

------------münhasıran', 'iki büklüm eğilsin  koptun sen omurumda  inan lazım değilsin  olmazsın umurumda  somurulsun sağılsın  duygular göğsünden  her tarafa dağılsı...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/koptun-sen-omurumda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alem Yüzüme Tükürsün', 'alem-yuzume-tukursun-ozay-karakus-4ec2d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ağzımda besmelem 

duamda şükürsün 

senden vazgeçersem 

alem yüzüme tükürsün 

kalbimde mabedim 

miracım namazımsın 

sen benim ibadetim 

en büyük sevabımsın 

elimde tesbihim 

dilimde zikrimsin 

aldığım abdestim 

alnımda secdemsin 

gözümde kıblem 

tarafım yönümsün 

içimde vesvesem 

ihlasım özümsün 

------------münhasıran', 'ağzımda besmelem  duamda şükürsün  senden vazgeçersem  alem yüzüme tükürsün  kalbimde mabedim  miracım namazımsın  sen benim ibadetim  en bü...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/alem-yuzume-tukursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kefen Giyemedim', 'bir-kefen-giyemedim-ozay-karakus-py2qa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu akşam giderken karanlık caddelerde 

gözyaşım aktı yine sensiz kalamadım 

hep izini aradım aradım cansız maddelerde 

sinmedimi kokun hiç bir yere; bulamadım 

kalakaldım bir soğuk kaldırım üstünde 

dondum sanki o an bir adım atıp inemedim 

bıraktın kimsesiz nefessiz beni; küstünde 

senden sonra o eve bir daha dönemedim 

ay beklemedi beni zamansız yıldızlar söndüde 

yağmurlar boşaldı fırtınalar koptu; gidemedim 

hep seni düşündüm saatler geçti zaman döndüde 

inan sensiz çaresiz ümitsiz sabahı edemedim 

sırılsıklam oldu vücudum üşümedim yinede 

şikayet etmedim lanet olsun sana diyemedim 

sıkıştı yüreğim bir acı oldunda kaldın öyle sinede 

düştüm yerlere yaşarken öldümde bir kefen giyemedim 

------------münhasıran', 'bu akşam giderken karanlık caddelerde  gözyaşım aktı yine sensiz kalamadım  hep izini aradım aradım cansız maddelerde  sinmedimi kokun hiç b...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-kefen-giyemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşarmı Sandın', 'yasarmi-sandin-ozay-karakus-6v5kl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bilmemki sevgilim kimlere kandın 

kime aldandın kime inandın 

habersiz terkedip beni bıraktın 

gittin ama sevda bitermi sandın 

gitti diye dünyam karardı 

insan derdini bir anlatırdı 

sana verdiğim gülüm sarardı 

sen dönmeden açarmı sandın 

fırtına kopuyor şimdi içimde 

hayalin gitmiyor yaşlı gözümde 

sardı bedenimi sevgin özümde 

bir heves değil geçermi sandın 

ruhumda güneş dünyamda ay`dın 

tapındığım mabet yaşadığım saraydın 

gönlümde taşıdığım sızısız yaraydın 

yokluğun bu yarayı sararmı sandın 

nerde kaldı senin yeminin andın 

hani sevdiğindim canımda candın 

yalvardım yakardım anlamadın 

bu hasreti bu can çekermi sandın 

zevk alınmaz sensiz hayattan 

bıkar be canım insan bu yaşamdan 

bende olmam sen olmazsan 

bu beden sensiz yaşarmı sandın

------------münhasıran', 'bilmemki sevgilim kimlere kandın  kime aldandın kime inandın  habersiz terkedip beni bıraktın  gittin ama sevda bitermi sandın  gitti diye d...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yasarmi-sandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azraile Söz Verdim', 'azraile-soz-verdim-ozay-karakus-1umd2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'YETER ZALİM ARTIK SENİ ÇEKEMEM 

UĞRUNA CANIM VERDİM FAZLA VEREMEM 

BU SON GÖRÜŞÜM SENİ BİR DAHA GÖREMEM 

AZRAİLE SÖZ VERDİM ÖLÜMLE EVLENİYORUM 

BİLMEDİN KIYMETİMİ HİÇ BİR ZAMAN 

SENİN YÜZÜNDEN OLDUM PERİŞAN 

YAKINDA YAPACAĞIM BİR NİŞAN 

AZRAİLE SÖZ VERDİM ÖLÜMLE EVLENİYORUM 

İSTERDİM Kİ BU AŞK BİTMESİN SÜRSÜN HATASIZ 

AMA OLMADI AYRILDIK SESSİZ SEDASIZ 

ELVEDA DİYORUM SANA SON KEZ VEDASIZ 

AZRAİLE SÖZ VERDİM ÖLÜMLE EVLENİYORUM 

SEVMEMİŞSİN BENİ GÖNÜLDEN BİR GÜN 

BU HAYAT BANA SANKİ CEZA SANKİ SÜRGÜN 

YAKINDA YAPACAĞIM BİR DÜĞÜN 

AZRAİLE SÖZ VERDİM ÖLÜMLE EVLENİYORUM

------------münhasıran', 'YETER ZALİM ARTIK SENİ ÇEKEMEM  UĞRUNA CANIM VERDİM FAZLA VEREMEM  BU SON GÖRÜŞÜM SENİ BİR DAHA GÖREMEM  AZRAİLE SÖZ VERDİM ÖLÜMLE EVLENİYOR...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/azraile-soz-verdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatabilsem', 'anlatabilsem-ozay-karakus-0e794', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir zalimin beni yaktığını 

bana acı dert kattığını 

bunları sonunda anladığımı 

birde şu gönlüme anlatabilsem 

beni seviyor sandığımı 

bile bile ona kandığımı 

ateşler içinde yandığımı 

birde şu gönlüme anlatabilsem 

bir mutluluk tatmadığımı 

huzur ile yatmadığımı 

onu kalbimde tutmadığımı 

birde şu gönlüme anlatabilsem 

o zalimin çekip gittiğini 

bırakıpta beni terkettiğini 

bu aşkın bende de bittiğini 

birde şu gönlüme anlatabilsem 

------------münhasıran', 'bir zalimin beni yaktığını  bana acı dert kattığını  bunları sonunda anladığımı  birde şu gönlüme anlatabilsem  beni seviyor sandığımı  bile...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anlatabilsem-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mantar Gibi Türediler', 'mantar-gibi-turediler-yusuf-onder-bahceci-qimyr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mantar gibi türediler,

Kimler di bu türediler,

Hatır gönül bilmediler,

Mantar gibi türediler.

Kimi kapkaç yapıyor,

Kimiyse tiner çekiyor,

Kimi cepten çekiyor,

Mantar gibi türediler.

Kimisi banka batırır,

Kimiyse gemi batırır,

Kimi halkımızı aldatır,

Mantar gibi türediler.

Kimi bomba koyuyor,

Kimiyse molotof diyor,

Milletimin sabrı taşıyor,

Mantar gibi türediler.

Kimisi hanımını döver,

Maganda kurşun der,

Hep talebelere değer,

Mantar gibi türediler.

Popçu, punkçu türedi,

Müzikleri kafa ütüledi,

Türkiye''yi de kötüledi,

Mantar gibi türediler.

Homoseksüeller taştı,

Transeksülleri yetişti,

Bunları kim yetişdirdi,

Mantar gibi türediler.

Ben bu işe kızıyorum,

Kalleşliktir seziyorum,

Az bekleyin geliyorum,

Mantar gibi türediler....', 'Mantar gibi türediler, Kimler di bu türediler, Hatır gönül bilmediler, Mantar gibi türediler. Kimi kapkaç yapıyor, Kimiyse tiner çekiyor, Ki...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/mantar-gibi-turediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki yüzlü ABD-Avrupa (Türkü Formatı)', 'i-ki-yuzlu-abd-avrupa-turku-formati-ahmet-unal-cam-1uh6b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bomba yapar

Önce satar

Karıştırıp

Sonra bakar

ABD-Avrupa(2) 

Adam sanıp güvenilmez

Kaptırırsın, el verilmez

Hiç insanlık beklenilmez

ABD-Avrupa(2) 

1-2 neyse de,zalimdir çoğu

Belli olmaz sağı-solu

Yakıp-yıkar, işte Ortadoğu

Oy ben sana demedim mi

İki yüzlü ABD-Avrupa(2) 

Demokrasi hep kendine

Salkım yutar

Talkım verir eline

Güven artık kendine

Seni yolda kor ABD-Avrupa(2) 

Uyarılar yolladılar

Katilleri kolladılar

Çoluk-çocuk aldırmadan

Bombaları salladılar

ABD-Avrupa(2) 

Medeniyet derler ama

İşte Irak-Hiroşima

Hiç martaval anlatma

Yalancıdır ABD

İki yüzlü Avrupa

ABD-Avrupa(2) 

Oy ben sana demedim mi

İki yüzlü ABD-Avrupa(2) 



Not: ''Karşıki dağlar Jandarma''

türküsünden esinlenerek yazıldı.

o ritimde okuyabilirsiniz.', 'Bomba yapar Önce satar Karıştırıp Sonra bakar ABD-Avrupa(2)  Adam sanıp güvenilmez Kaptırırsın, el verilmez Hiç insanlık beklenilmez ABD-Avr...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/iki-yuzlu-abd-avrupa-turku-formati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yandığımı Gör', 'yandigimi-gor-ozay-karakus-iarxe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözyaşlarım süzüldü yanaklarıma 

zamansız aklar düştü şakaklarıma 

sensiz boş kar yağdı sokaklarıma 

yandığımı gör kül olduğumuda 

ayrılıklar senle başladı bitti 

aşklar seninle yok oldu gitti 

bilsen aşkın bana neler etti 

yandığımı gör kül olduğumuda 

hüzünlerim boğuldu yutaklarımda 

kelimelerim gizlendi dudaklarımda 

sevgilerim son sevda ataklarında 

yandığımı gör kül olduğumuda 

yağmurlar senle boşaldı yağdı 

çamurlar seninle beden boyadı 

adı yokki aşkın bilinmez soyadı 

yandığımı gör kül olduğumuda 

------------münhasıran', 'gözyaşlarım süzüldü yanaklarıma  zamansız aklar düştü şakaklarıma  sensiz boş kar yağdı sokaklarıma  yandığımı gör kül olduğumuda  ayrılıkla...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yandigimi-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüm', 'gordum-ozay-karakus-co45o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'beni terkettiğin o günün ertesinde 

seninle buluştuğumuz çay bahcesinde 

başbaşa  gözgöze biriyle el ele 

saklama boşuna gezerken gördüm 

yürüdüm yolda her adımımda 

sen varsın kalbimde aklımda 

dün gece düşümde ve rüyamda 

beni gözyaşına boğarken gördüm 

aşkımı sevgimi hiçe sayarak 

beni böyle bir başına yalnız koyarak 

derde acıya gama boğarak 

bakmadan ardına giderken gördüm 

şimdi başka bir el tutuyor elinden 

o simsiyah saçlarının telinden 

kalbimi söküpte ta derinden 

ayağının altında ezerken gördüm', 'beni terkettiğin o günün ertesinde  seninle buluştuğumuz çay bahcesinde  başbaşa  gözgöze biriyle el ele  saklama boşuna gezerken gördüm  yü...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gordum-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-sevket-yucel-srw00', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kuş sesidir zaman

Bir elmadır dalından sarkan

Atışıdır yüreğin

Zaman gökyüzüdür uzar sonsuza

Bir renk cümbüşüdür dağlarda, ovalarda

Bir öpüştür anılarda kalan

Zaman gurbettir, sıladır

Sevdadır, umuttur biraz

Seni de yanıltır, beni de

Zaman bir çocuktur doğan

Ölümdür gömütlerde

Açılan bir güldür, batan bir diken

Zaman bakışındır senin

Gidişindir yollardan

Acılı, sevinçli, hüzünlü

Nice yıllar geçse de

Hepsi bir dakika kadar', 'Bir kuş sesidir zaman Bir elmadır dalından sarkan Atışıdır yüreğin Zaman gökyüzüdür uzar sonsuza Bir renk cümbüşüdür dağlarda, ovalarda Bir ...', ARRAY['Türk Edebiyatı','Şiir','Şevket Yücel']::text[], 8.5, '{"poet":"Şevket Yücel","poet_slug":"sevket-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zaman-295-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kansıza Kanarsın', 'bir-kansiza-kanarsin-ozay-karakus-ccfmz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'derdimsin dermanımsın 

harımsın harmanımsın 

sevdiğim sevdalımsın 

niye böyle yaparsın 

yanlış yola saparsın 

bir kansıza kanarsın 

alev alev yanarsın 

beni çok ararsın 

bakmazlar yüzüne 

inanmazlar sözüne 

geri dön özüne 

gel bırakma beni 

tacımsın tahtımsın 

kaderimsin bahtımsın 

yeminimsin ahtımsın 

niye böyle yaparsın 

yanlış yola saparsın 

bir kansıza kanarsın 

alev alev yanarsın 

beni çok ararsın 

uyarsın ellere 

düşersin dillere 

nazar değer gözlere 

gel bırakma beni', 'derdimsin dermanımsın  harımsın harmanımsın  sevdiğim sevdalımsın  niye böyle yaparsın  yanlış yola saparsın  bir kansıza kanarsın  alev ale...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-kansiza-kanarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seslenişim Sana 6', 'seslenisim-sana-6-zeliha-bicer-jrcyu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzun bir günün ardından

Yüreğimde senden kalanlarımla

Evimin kapısını açtım.

Yalnızlığıma açılan bir tünel gibiydi.

Sensizliğin garip kokusu sinmişti

Evimin her bir köşesine.

Pencereme vuran, günün son ışıkları

Turuncuya dönen hüzünlerimle

Öylece oturdum.

Seni düşündüm, seni yürüdüm 

İstanbul un tüm sokaklarında.

Adım adım.

Sonra seni andım

Bir bardak çay eşliğinde.

Özlemlerin yine döver olduğundan 

Gönül kıyılarımı

Duramıyorum yerimde

Turuncu hüzünlerimle

Bırakma beni sensizlikte', 'Uzun bir günün ardından Yüreğimde senden kalanlarımla Evimin kapısını açtım. Yalnızlığıma açılan bir tünel gibiydi. Sensizliğin garip kokusu...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seslenisim-sana-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-ozay-karakus-tt4y1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aşkınla yanan kalbim 

bir başka atıyor inan sevgilim 

resmine bakan gözlerim 

mutlulukla doluyor inan sevgilim 

rabbimden bana armağan ödülsün 

yaşadığım her anım her günümsün 

vazgeçemem yüreğim gönlümsün 

aşkımın ateşinde sen ölümsüzsün 

kalp senin can senin ben seninim 

azrailim ol canımı al hemen veririm 

yemin olsun meleğim bebeğim 

seni üzmektense bağrımı kurşuna dizerim 

küçüğüm sensiz ben ölürüm 

küçüğüm sevda kokan gülüm 

küçüğüm etsende bana sen zulüm 

acı değil zevk verir bu cana küçüğüm 

...münhasıran...', 'aşkınla yanan kalbim  bir başka atıyor inan sevgilim  resmine bakan gözlerim  mutlulukla doluyor inan sevgilim  rabbimden bana armağan ödüls...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kucugum-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misafir Olurum', 'misafir-olurum-omer-dalman-q6gw0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'affedin kusurlarımı...

hep ''kendi evrenim''de şekillendim

büyüdüm

kurşun geçirmez oldum

kendi gezegenlerimi kurdum

kendi yıldızlarımı serpiştirdim gökyüzüme

ay''ı gereksiz buldum

fırlattım attım. 

denizleri, dağları, ağaçları

fırtınaları, buz gibi soğuğu

nasıllarsa öyle kabul ettim

her sabah erkenden

onlarla buluştum koşularımda

içime çektim, ''şifa'' bildim.

benimsedim hep onları, Yaratan''dan ötürü

reddetmedim.

ve şimdi öyle büyüdü ki bu Evren

öyle çok sevgiyi iskan etti

öyle çok demirledi ki onları kendi topraklarına

havası güzel, suyu güzel, özel ki öyle çok

kardeşlerimi ara sıra da olsa

evim''e davetten başka gücüm kalmadı.

bırakamam bu toprakları

bu doğayı

ama arasıra

ben de misafir olurum...

(Şubat 2006)', 'affedin kusurlarımı... hep ''kendi evrenim''de şekillendim büyüdüm kurşun geçirmez oldum kendi gezegenlerimi kurdum kendi yıldızlarımı serpişt...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/misafir-olurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bunu Bildinmi Söyle', 'sen-bunu-bildinmi-soyle-yusuf-onder-bahceci-lyikb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni görmeseydim kimi severdim,

Severdim de böyle gönül verirdim,

Ben seni sevmişim, cânı verirdim,

Sen bunu bildinmi söylesen bana.

Şahin gibiyim ben bakar bakarım,

Güzel gözlerine de bakar yakarım,

Seni böyle kafama takar, takarım,

Sen bunu bildinmi söylesen bana.

Seviyorsan, bunu bana demezsen,

Çok seviyorum be bunu bilmezsen,

Ömrüm solup gitti eğer gelmezsen,

Sen bunu bildinmi söylesen bana.

Karacoğlan gibiyim güzel peşinde,

Dadaloğlu gibi sevdanın beşiğinde,

Yunus Emre gibi dergahın eşiğinde,

Sen bunu bildinmi söylesen bana....', 'Seni görmeseydim kimi severdim, Severdim de böyle gönül verirdim, Ben seni sevmişim, cânı verirdim, Sen bunu bildinmi söylesen bana. Şahin g...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-bunu-bildinmi-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözünde Durmadın', 'sozunde-durmadin-ozay-karakus-kyhvl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hani gözlerin hep bana bakacaktı 

hani ellerin hep beni saracaktı 

hani yüreğin hep benle çarpaçaktı 

yemin etmiştin sen sözünde durmadın 

seni hep okşayacaktım 

saçını hep ben koklayacaktım 

hani ben hiç acı tatmayacaktım 

tattırdın zalim sen sözünde durmadın 

hani aşkımızın ateşi sönmeyecekti 

küllenmeyecekti yandıkça alevlenecekti 

hani sevenler sözünden dönmeyecekti 

kahpelik ettin sen sözünde durmadın 

hani sen hep benim olacaktın 

bir ömür benle kalacaktın 

mutluluk dolu bir yuva kuracaktın 

ALLAH`tan da korkmadın sen sözünde durmadın 

hani hatırlarmısın daha çocukken sevmiştik birbirimizi 

ayrılmamaya söz vermiştik büyük etmiştik yeminimizi 

hani gülüm nazar değmesinden endişe duyardık 

kıskanırlardı sevgimizi korkardık koparacaklar diye ikimizi 

keşke eller ayırsaydı eller koparsaydı bizi 

ama sen yaptın bunu sen vurdun bana hayatın en acı darbesini 

senin sevgi neyine kahpe sen,seen ne anlarsın aşktan meşkten,git..yolun açık olsun ama attığın her adımda önüne 

dikenler dolsun,koparıpta kokladığın her çiçek elinde solsun 

dilerimki RABbimden tüm belalar kötülükler seni bulsun 

sen seen vefasız,,sen ALLAH`sız hiç bana sormadın,bu sevdamı hiç hayra yormadın......... 

.....sen sözünde durmadın.... 

münhasıran', 'hani gözlerin hep bana bakacaktı  hani ellerin hep beni saracaktı  hani yüreğin hep benle çarpaçaktı  yemin etmiştin sen sözünde durmadın  s...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sozunde-durmadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Ne Olur', 'gitme-ne-olur-mustafa-bilgili-9jocf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu yalan dünyada hiç bir şeyim yoktu,

Bir kadehim,bir sigaram ve senden başka,

Şimdi sende gidiyorsun bırakıp beni,

Söyle beni kim teselli edecek? 

Yokluğuna nasıl dayanacağım? 

Kim unutturacak bana acılarımı,

Peki ben kime “seni seviyorum” diyeceğim? 

Sen dünyanın tüm acılarını bana bırakıp,

Hiçbir şey olmamış gibi gidiyorsun.

Oysa  ne kadar da sevmiştim seni.

Tıpkı yaşamayı,gülmeyi sevdiğim gibi,

Ümitlerimi de alıp götürüyorsun.

Beni karanlık zindanlarda bırakarak,

Sigara ve kadehlerde teselli edemez beni,

Ben buralarda kalamam artık,

En derin acıları burada tattım,

Seni burada tanıdım,burada kaybettim,

Burada yeşerdi ümit çiçeklerim,

Yine zamansız esen bir kasırgayla,

Bu şehirde kurudu hepsi birer birer,

Sen çıktın karşıma ben acılardayken,

Paylaştın benimle dertleri,sevinçleri,

Sevdirdin bana dünyayı,yaşamayı,

Acılarında güzel olduğunu öğrettin,

Çok zamansız gidiyorsun be güzelim,

Tüm acıları bana bırakarak,

Sırasımıydı şimdi bu ayrılığın? 

Kim teselli edecek beni,kim avutacak? 

Kimin için şiir yazacağım,kime okuyacağım? 

Kime”seni canımdan çok seviyorum” diyeceğim? 

Ah be Kardelen gitmesen olmazmıydı? 

                                                                      01.12.1996', 'Şu yalan dünyada hiç bir şeyim yoktu, Bir kadehim,bir sigaram ve senden başka, Şimdi sende gidiyorsun bırakıp beni, Söyle beni kim teselli e...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gitme-ne-olur-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönüllerin Şampiyonu....İSTANBULSPOR.', 'gonullerin-sampiyonu-i-stanbulspor-ercan-akbay-vt9pw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sarı-siyah renklerinle

   Seksen yıllık tarihinle

   O şahane gollerinle

   Gönüllerin şampiyonu,İSTANBULSPOR.

   Taraftarın liselidir

   Her maçında gür seslidir

   Senin aşkın kalplerdedir

   Gönüllerin şampiyonu,İSTANBULSPOR.

   Kimler geldi,kimler geçti

   Aykut geçti,oğuz geçti

   Golleri hep,Tanju dizdi

   Gönüllerin şampiyonu,İSTANBULSPOR.

   Şaha kalktı UZAN ile

   Küme düştü devlet ile

   Taraftarın hep senin ile

   Gönüllerin şampiyonu,İSTANBULSPOR.....

   Büyük başkan SAFFET SANCAKLI geldi,

   Dertlerimiz artık bitti,

   Haydi yürü kupalara,

   Gönüllerin şampiyonu İSTANBULSPOR....

                                                             9.ŞUBAT..2006', 'Sarı-siyah renklerinle    Seksen yıllık tarihinle    O şahane gollerinle    Gönüllerin şampiyonu,İSTANBULSPOR.    Taraftarın liselidir    He...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gonullerin-sampiyonu-istanbulspor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazret', 'hazret-mesut-yokus-uvq1b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'korkuyorum nazar değer diye

ama soramıyorum bu çalışkanlık niye

sen güneş ışığından daha yakınsın dünyaya

şuna bir fener verin bakınsın dünyaya

yanmaz devreleri,dijitaldir evi

sorumludur maddi manevi

dünyada eşi yok tam bir bakar

kaptı mı klavyeyi dünyayı yakar

neyse sayın editör kafana göre takıl

değer biçemez sana hiçbir akıl', 'korkuyorum nazar değer diye ama soramıyorum bu çalışkanlık niye sen güneş ışığından daha yakınsın dünyaya şuna bir fener verin bakınsın düny...', ARRAY['Türk Edebiyatı','Şiir','Mesut Yokuş']::text[], 8.5, '{"poet":"Mesut Yokuş","poet_slug":"mesut-yokus","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hazret-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Hayatımdan', 'kac-hayatimdan-gul-yazganarikan-9qhp7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç hayatımdan, 

Hızlandır adımlarını

Ben yükü acı dolu bir kervan

Sen çıplak bir tay, yetişemem sana

Yetişemem. 

Sen durma vakit varken hızlan...

Ne asi rüzgarlar vurur benim yüzüme,

Ne bir yandan kavrulurken güneşte,

Gecenin bir yarısı, ne de üşürüm kor bir ateşte...

Ağır yüklerim benim.

Taşıyamazsın.

Gün doğuyor. 

Uzaktan, kızıllık yırtılıyor.

Uyan 

Yolcu yolunda gerek

Ben dert yüklü bir kervan

Sen çıplak bir taysın...

Vakit çok geç olmadan

Yola çıkmalısın...

Belki bozkırın ardından

Yaylaya ulaşırsın

Hızlandır adımlarını durma dörtnala koş şimdi

Şu ucu bucağı olmayan bozkırda, fırtına olmalısın

Tozu dumanı kat birbirine...

Unutma 

Neşeli taylar yaşıyordur bir yerde...

Onları bulmalısın...

Kendin gibi...

Ben de belki bir gün azaltıp yüklerimi

Gelir de bir yer de bulurum seni...

Belki...', 'Kaç hayatımdan,  Hızlandır adımlarını Ben yükü acı dolu bir kervan Sen çıplak bir tay, yetişemem sana Yetişemem.  Sen durma vakit varken hız...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kac-hayatimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asrın Aşk Mektubu', 'asrin-ask-mektubu-ozay-karakus-mo5u2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'EY SEVDİĞİM! BİLİYORMUSUN SENİN O GİDİŞİN PASLI BİR NAMLUDAN TETİK ZORUYLA ÇIKAN,MİKROBU KIRILMAMIŞ BİR MERMİ MİSALİ SAPLANMIŞTI GÖĞSÜME..... 

AMA SUSTUM TEHDİT ETTİM YÜREĞİMİ KONUŞMAMASI İÇİN 

GÖZÜMÜ KORKUTTUM AĞLAMASIN DİYE YAD YÜZLERE BAKMASIN GÖNÜL KOYMASIN 

DİYEREK KÖR ETTİM SEVDAMIN GÖZLERİNİ 

ELLERİMİ KELEPÇELEDİM SENDEN GAYRI TENLERE DOKUNMASIN SENDEN GAYRISININ SAÇLARINI OKŞAMASIN DİYE.........KULAKLARIMI TIKADIM HER TÜRLÜ SÖZE SENDEN O İKİ SİHİRLİ KELİMEYİ DUYANA KADAR... 

-*ÖLMEYECEĞİM SENSİZ DUDAKLARIMIZ KAVUŞMADAN-* 

HALA MUHAFAZA EDİYORUM YANAKLARIMA YETİM BIRAKTIĞIN BUSELERİ 

ANILARA YENİDEN SENARYOLAR YAZIYORUM 

RÜYALARIMIN BAŞROLÜNDE HER DAİM SENİ OYNATIYORUM 

AYRILIĞIN ACISI BENİ YİNE DERİNDEN VURUYOR 

BEYNİM YİNE OSCAR`A ADAY HAYALLER KURUYOR 

-*ÖLMEYECEĞİM SENSİZ KALPLERİMİZ BULUŞMADAN-* 

HALA YAKTIĞIN ATEŞ YÜREĞİMDE YANGINA SEBEBİYET VERİYOR 

BEN YİNE VAR OLAN YOKLUĞUNUN YOK OLAN VARLIĞIMIN KASELER DOLUSU AĞIZ DOLUSU ZEHRİNİ AKITMAKTAYIM CİĞERLERİME...DAMARLARIMDAN BEYNİME GİDEN SEVDA YOLUNA VARABİLMEK İÇİN YÜREĞİMİN GÜZERGAHINDA SEYRETMEKTEYİM 

VE BİR ISSIZ ÇÖL RÜZGARI BİR DELİCE BORAN MİSALİ ESMEKTEYİM 

GÖNLÜNÜN KIYILARINA ULAŞABİLMEK İÇİN 

-*ÖLMEYECEĞİM SENSİZ GÖZLERİMİZ KONUŞMADAN-* 

HALA SEVİNÇLERİNİN GÖZYAŞI MENDİLİMDE DAMLA DAMLA 

İÇİME YOKLUĞUN DOLUYOR HER KATLAYIŞIMDA 

CANIM YANIYOR BEBEĞİM``ANNESİZLİĞE ALIŞMAYA ÇALIŞAN ÖKSÜZ BİR BEBEK GİBİ 

ELİNDEN OYUNCAĞI ALINMIŞ BİR MASUM ÇOÇUK MİSALİ 

KALBİM NAMAZA DURMUŞ,GÖNLÜM İSYANLARDA 

...GÜNAHA GİRİYORUM BİLİNÇ ALTINDA.... 

GEL, GEL BE ARTIK BİR TANEM! 

YORGUN YÜREĞİMİN DİNLENECEĞİ BİR GÖNÜL PALAS`I YOK SENDEN BAŞKA 

ARTIK DAYANMAYA ALIŞMIŞLIĞIM TÜKENMEK BİTMEK ÜZERE 

ÇARESİZLİK; DÜŞÜNCELERİMDE UMUTSUZLUĞUN GÖLGESİ GİBİ 

ZAVALLI KALBİM HAYKIRIŞLAR İÇİNDE ÇIRPINMAKTA,YAŞLI GÖZLERİM AYDINLIK BAKIŞLARDA KARANLIKLARLA PENÇELEŞMEKTE 

ZİHNİM HALA ALGILAYAMADIĞI GÜZEL GEÇMİŞİMİN SORGUSUNDA VE BEDENİM HİSSETTİĞİ 

SOĞUĞUN,YORGUNLUĞUN,AĞRILARIN,ACILARIN VE SANCILARIN VERMİŞ OLDUĞU KARARSIZLIK KABİLİYETİNİN KORKUSUNDA... ANLAYACAĞIN YEŞİL GÖZLÜM; SENSİZLİĞİN ACISI BUGÜNDE DAMARLARIMA ENJEKTE EDİLİYOR HER DEFA...........BİR DEĞİL....BİN.... DEFA.... 

AMA ÖLMEYECEĞİM BİLESİN ÖLMEYECECEĞİM SENSİZ İPEK YÜZLÜM... 

SEVDANIN PINARINDA AŞKIN ŞARABINI KANA KANA İÇMEDEN 

ZİL ZURNA SARHOŞ OLUP KENDİMDEN GEÇMEDEN ÖLMEYECEĞİM..... 

HALİS ZONGULDAK KÖMÜRÜ KARASI,YALNIZLIĞA MEYİLLİ GECELERDE SENSİZLİĞİN TACİZİNE UĞRADIM DEFALARCA....AMA BUNA RAĞMEN BİLMEDİĞİM BİR YERDE,BİLDİĞİM 

SEVDİĞİM BİRİSİN OLDUĞUNUN,FARKINDA OLMAKSIZIN, BİLE BİLDİĞİM BİLİNMEYENLERİN ARASINDA DAHİ TEK BİLDİĞİM SENİ HALA SEVDİĞİMİ BİLMEMDİ SERÇE YÜREKLİM...... 

DİNLE SEVDİĞİM! KALP ATIŞLARIMIN ZİKRİNİ DİNLE 

RUHUNDA DUY BENİ,YÜREĞİNE KUNDAKLA GÖZBEBEKLERİMİ 

SOYKIRIMA UĞRAT EBEDİYEN SİL AŞKIN TARİHİNDEN BENLİĞİMİ 

YAKIP YAĞMALA,VİRANEYE ÇEVİR GÖNÜL BAHÇEMİ 

AMA ASLA SENSİZ ÖLMEMİ İSTEME........ 

ÖLDÜRMEYECEĞİM İÇİMDEKİ SENSİZLİĞİ...SENLE ÖLMEDEN 

SENSİZLİĞİN ARKADAŞI OLMAKTANSA,SENLİLİĞİN ESİRİ OLMAK 

YALNIZLIK DENİZİNDE YOL ALMAKTANSA RUHUNUN DERİNLİKLERİNDE 

SENİ SEVDİĞİMİ TÜM DÜNYAYA HAYKIRARAK,ÇIRPINA ÇIRPINA 

BOĞULMAK İSTİYORUM AŞKIN GİRDABINDA 

CİNAYETE KURBAN GİDİYOR UMUTLARIM FAİLİ MEÇHUL DUYGULARDA 

SANIK DURUMUNA DÜŞTÜM DELİLSİZ YARGILANIYORUM 

DİLİM İSYANLARDA,SÖZLERİM İNFAZDA,HER KELİMEDE AYRI AYRI DAVA AÇILIYOR 

GÖNLÜMÜN MAHKEMESİNE 

SAVUNMA YAPAMAYACAK KADAR SAVUNMASIZIM 

İTİRAZ ETMEYİ AKLIMA BİLE GETİRMİYORUM 

BİR AN EVVEL MAHKUM OLMAK KALBİNİN ZİNDANLARINA ATILMAK, 

SONSUZA DEK ORDA KALMAK ORADA YAŞAMAK İSTİYORUM 

ÖLMEYECEĞİM SENSİZ........ DUALARIM YERİNİ BULMADAN.............. 

SANA OLAN AŞKIM ERGENLİĞİNİ ÇOKTAN BİTİRDİ 

EN OLGUN DÖNEMİNDE HATTA KEMALE ERDİ 

ŞİMDİ DAHA ÇOK DAHA CESUR SEVİYORUM SENİ 

KORKMUYORUM BİR AN OLSUN ÖLMEKTEN 

TEK KORKUM SENSİZ ÖLMEK VARSAYIMLARI ÜZERİNE 

BERABERE BİLE KALMAK İSTEMİYORUM NE KADAR KORKSAMDA 

BU KORKUMU EZE EZE YENECEĞİM,HAKLI BİR GALİBİYET EDİNECEĞİM 

DEDİM YA...... ÖLMEYECEĞİM SENSİZ............. 

CANIM SEVGİLİM; SANA OLAN AŞKIMI FERHAT BİLSE 

ŞÜPHE EDERDİ SEVGİSİNDEN,VAZGEÇERDİ BELKİDE ŞİRİNDEN 

MECNUN BU DENLİ SEVEMEZDİ LEYLA`YI CANI GÖNÜLDEN 

KEREM BAŞINI TAŞLARA VURURDU BENİM YÜZÜMDEN 

AŞKIMIN BÜYÜKLÜĞÜNE İNANMIYORSAN GELDE OKU AŞKIMI GÖZÜMDEN 

ÖLMEYECEĞİM SENSİZ...........YEMİN ETTİM CAYARMIYIM SÖZÜMDEN 

GÜLÜM; DÜN OLDUĞU GİBİ BUGÜN DE YÜREK YİNE YARALI,YİNE KARALI YİNE SENSİZ 

DİL YİNE SÖZSÜZ YİNE SESSİZ YİNE SENSİZ.....GÖZ YİNE NEMLİ YİNE FERSİZ YİNE SENSİZ 

DUDAKLAR YİNE KURU YİNE BÜKÜLMÜŞ YİNE ÖPMEDEN YOKSUN YİNE BUSESİZ 

YİNE SENSİZ.....BAKIŞLAR YİNE MUTSUZ YİNE UMUTSUZ YİNE ÇARESİZ YİNE KİMSESİZ 

......................YİNE SENSİZ............................................... 

BENSE BİR BÜTÜN OLARAK SENSİZ YAŞAMDAN VE HAYATTAN BIKMIŞ VE USANMIŞIM 

...........ARTIK SENSİZ OLMAKLA NEFESSİZ KALMAK ARASINDAKİ MANADAR BENZEŞMENİN SERZENİŞLERİNDEYİM......................... 

bir gün bitecek bu hasret biliyorum ve bekliyorum 

okşayışlarının esiri olmaya devam edeceğim 

lakin o ana kadarki olmayışların ürkütüyor beni 

her saniye düşüncelerin kararsızlığa,umutların karamsarlığa dönüştüğü zaman dilimleri yaşıyorum...... 

düşüncelerimin kararsızlığı sana olan sevdamın büyüklüğümü 

sana olan çılgıncasına özlemin gözlerimdeki bütünlüğümü 

bilemiyorum.umutların karamsarlığı sana bir an kavuşma arzusu mu yoksa yokluğunun yüreğimde parelenmiş; 

korkarcasına,ürperircesine saygın ve sancılı feryadının 

haykırırcasına,bağırırcasına,çağırırcasına tutkusunun 

zihinsel ve bedensel içe vurumunun,dışa vurumunun 

kapalı veya na açıkça bir ifadesi mi anlamıyorum...... 

...her şeye rağmen ölmeyeceğim sensiz; sensizlik başımdan savuşmadan 

O kadar yorgunum ki sensizliğin yüreğimdeki vurgunluğu tüm düşüncelerimi allak bullak etmeye yetiyor 

bakışlarımın mutsuz durgunluğu ve tebessümlerimin kırgınlığı, 

ağlamaklı gözlerimin suskun yılgınlığı birde baş belası bu soğuk algınlığı seni aklımdan çıkarmama engel olmuyor.... 

sensiz ağlamayı çoktan umutmuşum,gülmeyi ise sahte mizahlarda arıyorum.özüm yok perişanım,sözüm yok boş lisanım 

eksikliğini yüreğimde hep hissettim hala hissetmekteyim 

cismini hafızamda şekillendirip hayallerimde resmetmekteyim 

hep o devasa kavuşma anının hayalindeyim,meyalindeyim 

zikrettiğim heceler manasız,kendi kendime zifrettiğim geceler 

merhamet özürlü sevdiceyim! 

ama ölmeyeceğim sensiz......sevgin damarlarıma ulaşmadan... 

Ben hala yalnızlığın çeşmesinden sensizliği içiyorum,içmeye devam edeceğim; ağzımda çalkalayıp sana kavuştuğum gün aşk ateşi kusacağım avuçlarına 

Yokluğunun acısını yüreğimde hissede hissede,çeke çeke 

varlığına bir adım daha yaklaştığımın tezindeyim.. 

Umutlarımın kaybolduğu her anda varlığının bilincine vararak ümidimi buldum,tazeledim her daim; göz yaşı pınarımı kuruttum sevgimin üstüne yağmur yağmasın aşk ateşim sönmesin diye 

Rüyalarla bezedim hayallerle süsledim sevdamı; damarlarıma saldım kanımda yüzdürdüm,sana olan çılgınca sevgime sardığım özlemini 

Sensiz talan edilen gönül bağımda artık çiçekler açmıyor 

ruhum hastalıklı hala karantinada,bitkisel hayatı yaşıyorum 

bitkilerden ve senden uzakta........ 

Seni dolaştırıyorum vücudumun her bir yanında; hücrelerime hapsettim seni,iradem her konuda idaresini yitirmiş bir konumda,sensiz depremle yerle bir olmuş taşınmaz koca bir enkazım.....gel......gel....harcımı yeniden kar, temelimi yeniden at beni yeniden inşa et bebeğim...... 

......ölmeyeceğim.....sensiz....ellerin tenime dokunmadan.... 

Ekseni etrafında dönüyor duygularım koordinatsız,umutlarım paralel düşüyor hayallerime dört mevsim zamansız 

Sensiz gönül sözlüğünde aşkın tarifi yok,imla hatası bulmak mümkün,olası sorulara verecek hiç bir cevabım yok ne kadar 

aşkın dersine çalışmış olsam da,sensiz sevgilerin sinyali zayıf 

her ne kadar frekansı doğru yazsam da kalbimde tek bir kıpırdanma yok sevgiye dair.....anlaşılan yönü tutturamıyorum 

yada aşkın kablosunu fişten çekmişler..... 

......ölmeyeceğim sensiz sevgim kalbine oturmadan.... 

Ultrasonda gördükleri sevgim sezaryanla doğum yapıyor sensizlik hastanesinde...... 

feryadım yankılanıyor bütün koridorlarda,taş kalpli bir doktorun ameliyat masasında kobay olarak kullanılıyorum,... 

aşka saygısı olmayan tüm insanlar mezarımı kazmış ölmemi bekliyorlar...ama bilmiyorlar ki benim kalbim sende atıyor... 

...bilmiyorlar ki ölmeyeceğim sensiz..... 

Sensiz geçen zaman içimdeki sana olan özlemi sana olan hasreti sana olan yangını daha da körüklüyor,,, 

Gel, gel artık kollarım hep açık,sonuna kadar; sarılmanı bekliyor göğsüm,gizlediğin gizlerle sensiz günlerin bende bıraktığı derin izlerle bekliyor.... 

Seni bir gün değil,seni bir hafta değil,seni bir ay değil,seni bir yıl değil,seni bir ömür değil seni mahşere kadar seveceğim... 

sanmaaaa...... seni mahşerden sonrada seveceğim..... 

ne zaman dersenki aç kollarını sana döneceğim,o zaman 

dizlerinde yatıp kollarında öleceğimmmmm.... 

DEDİM YA! HEP SÖYLÜYORUM YA! ............. 

.....ÖLMEYECEĞİM SENSİZ.... 

................münhasıran..............', 'EY SEVDİĞİM! BİLİYORMUSUN SENİN O GİDİŞİN PASLI BİR NAMLUDAN TETİK ZORUYLA ÇIKAN,MİKROBU KIRILMAMIŞ BİR MERMİ MİSALİ SAPLANMIŞTI GÖĞSÜME.......', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":126,"source_url":"https://www.antoloji.com/asrin-ask-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Analarım Bacılarım Kardeşlerim', 'analarim-bacilarim-kardeslerim-yusuf-onder-bahceci-r79mg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Analarım, bacılarım, kardeşlerim,

İnan ben sizleri çok çok severim,

Okuyorsunuz şiirlerimde överim,

Analarım, bacılarım, kardeşlerim.

Ben Türk Oğlu Türküm diyorum,

Size Kürt-Türk kardeş diyorum,

Vatanımı bölüyorlar deliriyorum,

Analarım, bacılarım, kardeşlerim.

Biz bu Vatanı nasıl kurtardık bre,

Milyonları şehit verdik verdik be,

Şehitlerden utanın diyorum bre,

Analarım, bacılarım, kardeşlerim.

Nene Hatunlar''la, Kara Fatmalar,

Ne ki bu yapılan türlü dayatmalar,

Sütçü İmamlar''a da sataşmalar,

Analarım, bacılarım, kardeşlerim....', 'Analarım, bacılarım, kardeşlerim, İnan ben sizleri çok çok severim, Okuyorsunuz şiirlerimde överim, Analarım, bacılarım, kardeşlerim. Ben Tü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/analarim-bacilarim-kardeslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizliğin sesinde herşey', 'sessizligin-sesinde-hersey-nazan-i-zmirli-9ivnm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sessizliğin sesini dinliyorum

gözlerim  kapalı

duyuyor,hissediyor,dokunuyorum

önce ürperiyor,sonra korkuyorum

çığlık  çığlığa  sessizliğin   sesinde

kayboluyorum..........................

sessizliğin  sesini  dinliyorum

derin  bir  nefes  alıp,  göğsümü   kabartıyor

indirdiğimde  yüreğimde  sessizliğin hazzını

burnumda yedi verenlerin kokusunu alıyorum

çığlık   çığlığa   sessizliğin  sesinde

varoluyorum...........................

sessizliğin  sesini dinliyorum 

beni  bana  hatırlatan 

beni  bana  yaşatan

sessiz  bir  rüzgar

yüzümü   yalıyor

sessiz  bir  sıcaklık

bedenimi  sarmalıyor

ardından

her   şeyi  unutturan

çığlık  çığlığa  sessizliğin  öpüşlerine

uyanıyorum......................

gözlerimi  açıyorum

sessizliğin    sesini  dinliyor,  izliyorum

gökyüzü mavi, mor, pembe çığlıklarda

bulutlar  öbek  öbek  patlamakta

dağlar  karlarla  sarmal  sarmal

ovalar yağmur damlalarını avuçlamakta

sessizliğin   sesinde   herşey

....çığlık  çığlığa  görüyorum.....

sessizliğin  çığlıklarına karışıyor

........kayboluyor

.........................varoluyor

.......................................uyanıyorum........

09.02.2006-antalya', 'sessizliğin sesini dinliyorum gözlerim  kapalı duyuyor,hissediyor,dokunuyorum önce ürperiyor,sonra korkuyorum çığlık  çığlığa  sessizliğin  ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sessizligin-sesinde-hersey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemedin YAR Bilemedin', 'bilemedin-yar-bilemedin-baki-ceylan-m8i5x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sen olmuşum

Ama

Sen gittin 

Vurdu bir kurşun

Sana dokunan bedenim ya

Ortada kan yok

Seni yaşayan ruhumu

Onu göremedin 

Ölüm içimdeydi

Bilemedin yar bilemedin

Sen gittin ya

Gitme 

Diyemedim

Başım düştü omzuma 

Ben bende değilim 

Seninle beraber gittim 

Ben sendeydim

Bilemedin yar bilemedin 

Sen gittin ya

Yalnızım 

Gözyaşlarım arkadaşım

Her damlasına 

Bizi anlattım

Ağlamaz bilirdin beni hep

Onuda

Bilemedin yar bilemedin', 'Ben sen olmuşum Ama Sen gittin  Vurdu bir kurşun Sana dokunan bedenim ya Ortada kan yok Seni yaşayan ruhumu Onu göremedin  Ölüm içimdeydi Bi...', ARRAY['Türk Edebiyatı','Şiir','Baki Ceylan']::text[], 8.5, '{"poet":"Baki Ceylan","poet_slug":"baki-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bilemedin-yar-bilemedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadeh kadeh içtim', 'kadeh-kadeh-ictim-saadet-ekinci-08ucp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakışlarınla içime akan,

O heyecan,

Unutulmaz sevgin,

Gözlerinde gördüğüm,

Masmavi okyanus,

Sesinde hissettiğim,

Melodi…

Varlığında duyduğum,

Güven,

Ümitlerim, hayallerim

Ve unutamadığım,

Sen...! 

Arkama dönüp bakınırken,

Hissettiğim ayak seslerin,

Kalbimin çırpınışı,

Zaptedemediğim heyecanım,

Elim ayağıma,

Sözcükler dilime dolaşır.

Sakarlaşırım.

Yüzüne baktığımda; 

Masum bakışların,

Tatlı tebessümün,

Yağ gibi akar yüreğime,

Eritir aktığı yeri.

Gitmek zorundasın bilirim; 

Ayakların gider ama,

Sen…

Sen benimlesin.

Bak; 

Yıllar geçti,

Ne sen geldin,

Ne ben vazgeçtim,

Sensiz geçen günleri,

Kadeh kadeh içtim…

İçimde öbekleşti hasretin,

Ne kadar dayanır bilinmez,

Bu yorgun bedenim

Saadet EKİNCİ', 'Bakışlarınla içime akan, O heyecan, Unutulmaz sevgin, Gözlerinde gördüğüm, Masmavi okyanus, Sesinde hissettiğim, Melodi… Varlığında duyduğum...', ARRAY['Türk Edebiyatı','Şiir','Saadet Ekinci']::text[], 8.5, '{"poet":"Saadet Ekinci","poet_slug":"saadet-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kadeh-kadeh-ictim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meslek Lisesinde Tuvalet Sorunu', 'meslek-lisesinde-tuvalet-sorunu-ekrem-sama-dlaim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok çok uzaklarda, vardı bir ülke,

Mahkemesi imza attı bir ilke.

Burada mevcuttu iki tür lise,

Gençler muhayyerdi nasıl isterse.

Klasik düz lise ve meslek lisesi,

Birazcık riskliydi meslek sevmesi.

Meslek lisesinde ayrı tuvalet,

Mahkemeye düştü, bir gün nihayet.

''Kız erkek ayrıdır tuvaletlerde,

Tehlike arzeder diye ilerde...''

Kararını verdi, hemen yargıtay,

İşte gerekçeli, imzalı onay: 

(((Demokrat ülkedir, Güney Afrika,

Burada yapılmaz hiç bir tefrika.

Bu meslek lisesi... Durum çok vahim! 

Nasıl yapılmış tuvaletler hem kim? 

Burda var ayırım ötesi sorun,

Bu öğrencileri insan saymaz kanun...

Sorun buna göre derhal çözülsün,

Yıkın tuvaletleri hemen bugün....))) 

(İstanbul:09.02.2006)', 'Çok çok uzaklarda, vardı bir ülke, Mahkemesi imza attı bir ilke. Burada mevcuttu iki tür lise, Gençler muhayyerdi nasıl isterse. Klasik düz ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/meslek-lisesinde-tuvalet-sorunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler-33', 'guzel-sozler-33-huseyin-erdogan-jwql9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Gülümsemek,bu kadar zor mu? O halde,gözlerin neden buğulu? ''

