INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Boşuna Uğraşma Anlarım', 'sen-bosuna-ugrasma-anlarim-yusuf-onder-bahceci-d7m2c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana boşver diyenler di ayıranlar,

Sen boşuna uğraşma ben anlar,

Hiç düşündün mü neden ayırdılar,

Sen boşuna uğraşma ben anlar.

Önce anneni güzelce kandırdılar,

Öyle güzel yalanlarla inandırdılar,

Annen de seni etkiledi, yalanlar,

Sen boşuna uğraşma ben anlar.

Şimdi vah demeli eyvah demeli,

İşte böyle oldu, kime ne demeli,

Senden ayrı düştüm nasıl etmeli,

Sen boşuna uğraşma ben anlar.

Benim bu sevdam, alemi yakar,

Sadece yakar mı belki de yıkar,

Sen ellerdesin Önder''se bakar,

Sen boşuna uğraşma ben anlar...', 'Sana boşver diyenler di ayıranlar, Sen boşuna uğraşma ben anlar, Hiç düşündün mü neden ayırdılar, Sen boşuna uğraşma ben anlar. Önce anneni ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-bosuna-ugrasma-anlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım Grileşiyor', 'umutlarim-grilesiyor-seyfettin-bilal-ozluk-zn6c3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her taraf kar beyaz örtülmüş günlerime

Yarına ektiğim umutlar grileşiyor

Gece ise dunden karanlık

Ay sahte güneş ise dünden daha karanlık...

Dönerken geçmişe yeniden

Yeşermeye başlayan umutların dalları kırılıyor

Mahzende kalan umutlarım ışık göremiyor

Gülücükler sahte gülümsemeler ise çoktan yalancı...

Çıkarmamalıyım içimdeki hayallerimi

Onları ekmiştim nadas yüreğime

El ele değmeden gitmek var mıydı ey sevgili

Gelişin sahte gidişin ise yarından uzak...

Yalpalarken düşen karlar gibi şimdi yüreğim

Nerde takılır nereye yığılırım bilemiyorum

Koparırmı ağırılığım takıldığım yere düşünemiyorum

Tutunmalarım sahte tutunacaklarim ise geçmişten kırık...

Gidişin nereye bu muhteşemliğinle

Her giden muhteşem dönmez dönsede geride kalan olmaz

Dönmek istersen haber et ey sevgili ben bekliyor olacağım

Çünki gitmelerim sahte dönüşlerim ise sende kaldı...', 'Her taraf kar beyaz örtülmüş günlerime Yarına ektiğim umutlar grileşiyor Gece ise dunden karanlık Ay sahte güneş ise dünden daha karanlık......', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/umutlarim-grilesiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ma’bed-i fersude,mehr-i’can olur.', 'ma-bed-i-fersude-mehr-i-can-olur-ali-riza-unal-2kvma', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne çekti gönül-pürgür-ü zâr elinden,

Şu dilzâr-ı canân,kabristan olur,

Es ey bad-ı saba,kesir-i yar ilinden,

Bu gülnihal bağ’ban-ı gülîstân olur,

Bir suziş-i nihan,dür döker dilinden,

Şu can içre bakış,muhlis-i can olur,

Ne şüphe lâ yûsâl,lûtfu kerimden.

Ma’bed-i fersude,mehr-i’can olur.

Lûgâtçe –Bad-ı Pürgü:  hışırtılı esen huzursuz edici rügâr,

Zâr :  inleyen, sesli ağlayan,zayıf dermansız,

Dilzâr: dil ile,söz ile feryad eden,

Bad-ı saba: baharda esen hafif ve hoş rüzgâr,sabah yeli,

Kesir:  sürekli devamlı aralıksız.

Gülnihal:  gül fidanı,

Gülistan : gül bagçesi,gül tarlası.

Suziş-i nihan: için,için yanma,gizli yanma

Dür :   inci,

Muhlis :katkısız,ihlaslı,içten,

Lâ yusâl:  hikmetinden suâl olmayan,yaptığından hesap sorulmayan,Hazreti Allahın esmasından biri,

Ma’bed-i fersude: eskimiş yıpranmış mabet,

Mehr  :aşk,şefkat,muhabbet* güneş *huk mihr, evlenme münasebetinde buluna erkeğin kadına verdiği

Nikah bedeli..', 'Ne çekti gönül-pürgür-ü zâr elinden, Şu dilzâr-ı canân,kabristan olur, Es ey bad-ı saba,kesir-i yar ilinden, Bu gülnihal bağ’ban-ı gülîstân ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ma-bed-i-fersude-mehr-i-can-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Biz arkadaşız**', 'biz-arkadasiz-zernisan-aydogan-sddnl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin için bir his hissetmiyorum

Aşka yer yok arkadaş bak söylüyorum

Derin duygular da beslemiyorum

Seninle sadece biz arkadaşız

O sıcak ellerin elimi tutsa 

Şu gönlüm yanında huzuru bulsa 

Hasretin özlemin beni kavursa

Seninle sadece biz arkadaşız

Karlı dağları toz duman aşsak

Birlikte koşsak birlikte coşsak

Issız çöllerde yalnız da kalsak

Seninle sadece biz arkadaşız

Gönül bağıyla bağlanma bana

Kalbim de yer yok sevgiye aşka

Bu güzel dostluğu çıkmaza sokma

Seninle sadece biz arkadaşız

                           

                             Erzurum', 'Senin için bir his hissetmiyorum Aşka yer yok arkadaş bak söylüyorum Derin duygular da beslemiyorum Seninle sadece biz arkadaşız O sıcak ell...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biz-arkadasiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyen Hüznümdür', 'usuyen-huznumdur-selahattin-yetgin-66p2i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuru dallar bir çiçek dökümünden sonra

Açmış kollarını, taşıyabildiğince kara,

Üşüten bir soğukla iç içe, birlikte,

Kararsız bir salıncak gibi, sallanır durur.

Yollar çocukları taşır, kahırlı ve ürkek,

Çamurlu göğsünde sıcacık bir gülümseyiş,

İs ve duman içinde çağırır akşamı,

Barındırır koynunda kış günlerini.

Ve yeniden doğar tepelerin ardından,

Karlı dağları yalar, iner düze güneş

İhtiyar yüzler gülümser, ısınınca eller,

Üşüyen şimdi şehirdir, üşür şehirler.

Gülümser tüm yitik sevgilerimiz,

Özlemini çektiğimiz küçücük evlerde

Kargalara taşlar atar çocuklar,

Çığlık çığlığa sarı bahçelerde.

Az yaşanmış bir ilk yazdan,

Anılarla düşler arasında ömür sürer adam

Çarmıha gerili düşüncelerin ipini keser,

Hüzün yürür gençliğinin özünden.', 'Kuru dallar bir çiçek dökümünden sonra Açmış kollarını, taşıyabildiğince kara, Üşüten bir soğukla iç içe, birlikte, Kararsız bir salıncak gi...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/usuyen-huznumdur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UB-044 Desem! ..', 'ub-044-desem-mehmet-coban-yjcgu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocukluk, yalanlarla avutulmak

Büyümek, gerçeklerle uyanmak

Hayat, yaşanmak zorunda olan

Ömür, yaşandıkça kaybolan

Aşk, tutkularda kaybolmak

Evlilik, sorunlarla yaşamak

Bilgi, hiç tükenmeyen sudan içmek

Bilinç, her an bilgilerle yenilenmek

İnanç, bilgi ve bilinçle kuşanmak

Dava, fedakârlıklarla kaybolmak

Kölelik, benliğe, benliklere teslim olmak

Özgürlük, bütün köleliklerden kurtulmak

İsimsiz, ölümle kaybolup gitmek

İsimli, ölümlerle ölmemek

Ne dersiniz? 

09.02.2006-İzmir', 'Çocukluk, yalanlarla avutulmak Büyümek, gerçeklerle uyanmak Hayat, yaşanmak zorunda olan Ömür, yaşandıkça kaybolan Aşk, tutkularda kaybolmak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ub-044-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var,', 'var-mehmet-coban-tx2sl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsanlar var,

Yatak, yorgan döşekte

Fikren kölelikte

Bilgisiz, cahillikte

İnançsız şüphelerde

Amaçsız, oyunda eğlencede

Gözü başkalarının işinde

Kendi işleri yerlerde

Toplumlar var,

Durulmaz bir düzende

Ülkeleri tümden işgalde

Açlıklar, ölümler tetikte

Doğa, her an öldürülmekte

Bu sonuçlara ulaştılar

Karanlıkta kayboldular

Bir tek hedefte birleştiler

Bize, hiçbir şey olmaz dediler! ..

09.02.2006-İzmir', 'İnsanlar var, Yatak, yorgan döşekte Fikren kölelikte Bilgisiz, cahillikte İnançsız şüphelerde Amaçsız, oyunda eğlencede Gözü başkalarının iş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/var-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsız ve Cansız Kelimelerle Savaşıyorum', 'anlamsiz-ve-cansiz-kelimelerle-savasiyorum-seyfettin-bilal-ozluk-uk6g5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzümde kalan gülümsemeydin

Yol gösteren klavuzum

Nefes almamı sağlayan damarlarımdaki kandın

Sen bende can değil

Şahdamarımdın...

Ağlayan sesin yıkıyor bedenimi

Gözlerim kan çanağı belli etmemeliyim

Kızılcık şerbeti şimdi kadehimdeki

Yarınlar geceden daha karanlık

Gitmemeliydin...

Susma susuşun bir girdap yatarıyor benliğimde

Melekler diyarındaydım sen varken

Şimdi şeytanı yaratıyorum içimde

Sen yoksan melekler neye yarar ibadetlerimde

Susmamalıydın...

Yoruldu kelimelerim

Kalemimin ucu çoktan kırıldı

Nerdesin ey gönlümün yargıcı

Kırdığın kalem boynumu ipe götürdü

Kırmamalıydın...

Yarattığın boşluğa düşüyorum

Çıkarmıyım geriye umutsuzum

Çıksam geriye ne kaldı ki

Giden zaten dünden yolcu

Düşürmemeliydin...

İlk dudağımdaki kadınımdın

Dudağım kanıyor

Silmiyorum bir başkası için o kanı

İçiminde dudağımdan bir fark yok ki

Kanatmamalıydın...', 'Yüzümde kalan gülümsemeydin Yol gösteren klavuzum Nefes almamı sağlayan damarlarımdaki kandın Sen bende can değil Şahdamarımdın... Ağlayan s...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/anlamsiz-ve-cansiz-kelimelerle-savasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse', 'kimse-halil-pazarli-vbacj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimselerle paylaşmadığım bir aşkım var şimdi

Anlatamadığım bir sen var

Bir bebek kadar masum uyuyor yüreğimde

Kendime anlatırken bile yorulduğum sevdam

Belki de bir sevincin aşırı kıskançlığı  işte

Bu gönül neleri unutmadı ki

Sayısız hüzünleri gömdü maziye

Ne acılar çekti bilerek ve isteyerek

Ne renk cümbüşleri boyandı siyaha

Ne beyazlar döndü griye

Ne şiirler tıkandı kaldı nefesimde

Bir sen aklımdan çıkmıyorsun şimdi

Unutulmadın

Ve seni özledim çocuk

Bu bir itiraf olsa bile

Ama koyamıyorum bir türlü 

senden başkasını

Ne aklıma 

Ne gönlüme 

Ne de şiirlerime

Ve seni seviyorum çocuk

Hem de delicesine', 'Kimselerle paylaşmadığım bir aşkım var şimdi Anlatamadığım bir sen var Bir bebek kadar masum uyuyor yüreğimde Kendime anlatırken bile yoruld...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kimse-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Tokat Dedikleri', 'su-tokat-dedikleri-ali-gencay-6h4de', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kar yağmış şu Tokat’ın başına

Kurban olayım yar hilal kaşına

Üşürüm, çatır ayazdır zemherin

Koyarsan beni sensiz tek başına

Gelinler al yazma bağlar başına

Kına yakar sürme çekilir kaşına

Sanma ki kalır sende güzelliğin

Kardan beyaz aklar düşer saçına

Türkü söylenir vurulur mızraba

Oynar delikanlılar kızlar aşkına

Gönlümde büyür senin hasretin

Kalkmaz kollarım düşer iki yana

Şu Tokat dediğin iki dağ arasında

Gül koymuşlar camdan bardağa

Benim gönlümün dermanı sensin

Kurban olayım yar seni yaratana', 'Kar yağmış şu Tokat’ın başına Kurban olayım yar hilal kaşına Üşürüm, çatır ayazdır zemherin Koyarsan beni sensiz tek başına Gelinler al yazm...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/su-tokat-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayağa Tekrar Nasıl Kalkarım', 'ayaga-tekrar-nasil-kalkarim-yusuf-onder-bahceci-6xxlh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Böyle ayrılığın vebali bende değildi,

Bu suçun bedeli de, sende değildi,

Dimdik olan bedenim şimdi eğildi,

Ben ayağa tekrar nasıl kalkarım.

Bana gitme, gitme diyordu ayıran,

Ayıp, ayıp diyordu, diyordu ayıran,

Sonra ustaca, kaderi hep kayıran,

Ben ayağa tekrar nasıl kalkarım.

Kametimi büktüler, bana yüktüler,

Bil önceden gözümde büyüktüler,

Allah belalarını verdi de, çöktüler,

Ben ayağa tekrar nasıl kalkarım.

Şimdi her tarafları yalan olsa da,

İstedikleri kadar da, plan olsa da,

Gördüğün bedenim toprak olsa da,

Gör bakalım ayağa nasıl kalkarım.', 'Böyle ayrılığın vebali bende değildi, Bu suçun bedeli de, sende değildi, Dimdik olan bedenim şimdi eğildi, Ben ayağa tekrar nasıl kalkarım. ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayaga-tekrar-nasil-kalkarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Güller', 'beyaz-guller-asude-gediz-wyf2m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Varlığın,

tatlı bir esinti bedende

acı, keder, üzüntü sürgünde

hasret kördüğüm olmuşken sinede

güller feda olsun serine.

Sözler sözlere gebe

Gül goncaya döner sevince

bir çığlık, 

yırtarcasına sinede

ne kadar solsa da rengi

Kırmızıdır bülbüle

Nekadar solsa da rengi 

kırmızı gül sinede', 'Varlığın, tatlı bir esinti bedende acı, keder, üzüntü sürgünde hasret kördüğüm olmuşken sinede güller feda olsun serine. Sözler sözlere gebe...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beyaz-guller-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkında mısın', 'farkinda-misin-atilla-guler-zx967', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'küçük adımlarını hızlandırdı bana doğru

suskunlukların sessiz başkaldırışına yakalanmış

yağmur damlalarının ıslaklığında kaybolan

çocukluğumun masumiyeti

artık dilimde tek şarkı

uyumak ki

hiç kimse söz dinlemez akşamlara geçiremiyor sözünü

ve mahkumluğuma yatıyorum

karanlıklarda çağlayan yağmurların

çamuru üstüme sıçramış

günlerim bir öncekinden daha beyaz

daha mavi

daha kırmızı

bir sıcaklığa yaslıyorum başımı

alıp götüren müziğin

deli ritmi içime işlerken

cızırtılı radyonun

bataryasız suskunluğunda kaybolup

son söylenen şarkıda yine aşk vardı

natürmort bir tablonun son renginde

gözlerinin ışıltılı bakışlarına vurulmuş

deli bir kan fışkırıyor kıpkırmızı

farkında mısın

bir yürek daha çarpıyor senin için

farkında mısın

seni seviyorum', 'küçük adımlarını hızlandırdı bana doğru suskunlukların sessiz başkaldırışına yakalanmış yağmur damlalarının ıslaklığında kaybolan çocukluğum...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/farkinda-misin-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Girmedi Uyku Gözlerime Hep uyanığam', 'girmedi-uyku-gozlerime-hep-uyanigam-i-brahim-halil-demir-61ykg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küstürdü o yar beni benden,

Şefkat görmedim sevdiklerimden.

Bıraktım alacaklarımı ahirete,

Silenmeyecek yazılanlar defterimden.

Geçmeyen ağrılarım oldun bedenimden,

El çeksinler zalim oğlu zalimler kefenimden! 

Her şeyi gizleyen, toprak bile üzülür belki,

Ölürsem günün birinde kederimden.

Gönül kapımı dostça çalan olmadı,

Söndü ışıklarım kimse aydınlatmadı.

Sevenlerim birer-birer terk etti beni,

Azdı kanayan yaralarım,şifa bulmadı.

Tutmaz oldu aşkından elim ayağım,

Bitirip tüketti beni, kalmadı dayağım.

Gitti gideli o yar bu yerlerden,

Girmedi uyku gözlerime, hep uyanığım.

Bir-bir açılıyor goncalarım dalımda,

Alınyazım olarak çıkıyorsun kahve falımda.

Baş koymazsam bile senle aynı yastığa,

Nakış nakış dokur seni yüreğim aşk halıma.

Nalbantım ol çak sevda atıma aşk nalım,

Fırtınalı havalarda yol almaz yelkenim salım.

Getirmezse aşkın rüzgarları beni sana,

Söylesene kimin yanında barınıp kalım.

08/02/2006', 'Küstürdü o yar beni benden, Şefkat görmedim sevdiklerimden. Bıraktım alacaklarımı ahirete, Silenmeyecek yazılanlar defterimden. Geçmeyen ağr...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/girmedi-uyku-gozlerime-hep-uyanigam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firakın ceşm-i eceldir', 'firakin-cesm-i-eceldir-ali-riza-unal-970qk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Firakın ceşm-i eceldir,lakin vefayım,

Bir lebb-i badeye,bin ömrü hebayım,

Bu bahrı umman,gördümki kahrı cefa,

Bilirim ahiri sefa,ben gönlü fedayım.', 'Firakın ceşm-i eceldir,lakin vefayım, Bir lebb-i badeye,bin ömrü hebayım, Bu bahrı umman,gördümki kahrı cefa, Bilirim ahiri sefa,ben gönlü f...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/firakin-cesm-i-eceldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerim Yeniden Kanar', 'ellerim-yeniden-kanar-mehmet-faruk-habiboglu-eaafr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kesif düşlerimde kırık silüet

Dağ başlarında akbabalar haykırır

Bir inkilaptır yüreğimde yeniden

Sevdaya dair sancılar vardır

Yitiktir kaldırımlar caddeler kapalı

Sokak başlarında gölge adamlar

Ellerim yeniden kanar yeniden

Apansız yüreğime damlar

Yollar çamur derya ve yağmur

Kağnıların peşindedir kadınlar

Cephelerde ben ölürüm yeniden

Beni ancak sevdalılar anlar

Aşk yeniden diriliştir elbet

Bir direniştir dönüşün

Uzandıkça ellerimle sana

Savrulurum içine yeni bir düşün

Benim direncim gözlerimde

Sol yanımda kavi bir yürek

Ufka dikilen gözlerimdir

Sana bağlandım bir tek

Tut ki ellerimden sıkıca

Koşalım kentin sokaklarında

Düşlerimden açılan kapıdan

Düşelim yeniden uzaklara', 'Kesif düşlerimde kırık silüet Dağ başlarında akbabalar haykırır Bir inkilaptır yüreğimde yeniden Sevdaya dair sancılar vardır Yitiktir kaldı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Habiboğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Habiboğlu","poet_slug":"mehmet-faruk-habiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ellerim-yeniden-kanar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nakış Nakış Süsle Beni Mahirce !', 'nakis-nakis-susle-beni-mahirce-i-brahim-halil-demir-vo7nf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen  nadide bir gül, ben de bülbülün olayım,

Her seher vaktinde,dallarına konayım,

Sevginin her türlü çalı çırpılarıyla,

En görkemli, en sıcak yuvalardan birini yapayım.

Sen, kutup yıldızı, ben de asuman olayım,

Sevdiklerine gidenler, yolunu bulsunlar seninle.

Nakış nakış süsle beni mahirce,

Hayranlıkla temaşa etsinler övüneyim seninle.

Sen, bedenimi ayakta tutan, sevdalı yüreğim ol,

Sevdalılar meclislerinde, överek anlatayım seni.

Sen, beni hayata bağlayan, nimetlerin menbaı ol,

Yeter ki her özlem duyduğumda, görebileyim seni.

Sen, suyun dibini süsleyen, renkli kum zerrecikleri ol! 

Ben ise bir o yana, bir bu yana, rastgele yüzen balık olayım.

Sen, çatlamış kurumuş topraklara yağan, rahmet tanecikleri ol! 

Ben ise yaradan dan seni dileyen, aciz bir mahluk olayım.

08/02/2006', 'Sen  nadide bir gül, ben de bülbülün olayım, Her seher vaktinde,dallarına konayım, Sevginin her türlü çalı çırpılarıyla, En görkemli, en sıc...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nakis-nakis-susle-beni-mahirce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yandan Bağlıyım', 'i-ki-yandan-bagliyim-yusuf-onder-bahceci-2ssgn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İki yandan bağlıyım nasıl edeyim,

Bana gel desen bile nasıl geleyim,

Eğer bana öl desen hemen öleyim,

İki yandan bağlıyım nasıl edeyim.

Her yanım kesik, böyle engeller ile,

Sanki daragacı kurulu çengeller ile,

Sana söz versem bile, yeminler ile,

İki yandan bağlıyım nasıl edeyim.

Arada böyle engeller olmasa bilki,

Her yeri dümdüz ederim bilsen ki,

Başka hiç bir engel tanımam bilki,

İki yandan bağlıyım nasıl edeyim.

Ben Allah''ıma dualar eder ağlarım,

Sanma yaşıyorum böyle sağlarım,

Dediğim engeller sanma dağlarım,

İki yandan bağlıyım nasıl edeyim...', 'İki yandan bağlıyım nasıl edeyim, Bana gel desen bile nasıl geleyim, Eğer bana öl desen hemen öleyim, İki yandan bağlıyım nasıl edeyim. Her ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iki-yandan-bagliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkıldım Böyle Yaşamaktan', 'sikildim-boyle-yasamaktan-i-brahim-halil-demir-bxq6h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilemiyorum,geçer mi bu sıkıntı yüreğimden,

Bir ses diyorki bana derinden,

Büyük günah olmasaydı şayet,

Son verirdim hayatıma,vazgeçerdim canımdan.

Harama tevessül etmedim,pişman değilim,

Mazlumum ama zalim değilim,

Saymadım bana yapılan zulümleri,

Helal etmiyorum hakkımı,ama şikayetçi de değilim.

Beni teselli eden sadece zengin olan gönlümdür,

Belli olmaz belki de bu sıkıntılar sonumdur,

Kapılmışım hayatın acımasız,keskin dişlerine,

Kafeste çırpınan kuşlar değil,benim ruhumdur.

Hiçbir şeyde israf etmiyorum haramdır diye,

İnsanlar insanlığını unutmuş,kalmamış seviye,

Halil İbrahim’in sofrasındaki bereket uçmuş,

Bismillahirrahmanirrahim demeye demeye.

10/12/2003', 'Bilemiyorum,geçer mi bu sıkıntı yüreğimden, Bir ses diyorki bana derinden, Büyük günah olmasaydı şayet, Son verirdim hayatıma,vazgeçerdim ca...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sikildim-boyle-yasamaktan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durur Yüreğim', 'durur-yuregim-mehmet-faruk-habiboglu-ouiw5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün uzun

Gün sıcak

Cehennem misali gönlüm

Gözlerinde yanacak

Kızıl kıyamet hüzün

Bir ayrılık şarkısı

Bir hasret türküsüdür

İlla gülüşün

Gülüşünde yüzün

Ve yüzünde

Bir gül gibi

Bir tül gibi

Busecan dudakların

Ey sevgili ben

Kalbimi sana adadım

Başımda bin türlü bela olsa

Çekerim

Gözümde biteviye yağmurlar

Ve hazan içimde

Bu yaz mevsiminde

Uğruna olduktan sonra

İçerim

Kana kana gözlerini

Yeter bana

Serinlerim

Hele bir de 

Ellerine dokunmak

Depremlere düşer ellerim

Hayır uzak tut dudaklarını

Dayanamam bu kadarına

Vallahi o an durur yüreğim

Ölürüm', 'Gün uzun Gün sıcak Cehennem misali gönlüm Gözlerinde yanacak Kızıl kıyamet hüzün Bir ayrılık şarkısı Bir hasret türküsüdür İlla gülüşün Gülü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Habiboğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Habiboğlu","poet_slug":"mehmet-faruk-habiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/durur-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sil Gözlerini....', 'sil-gozlerini-nurdane-diken-r3bso', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akıtma içine, sen közlerini 

Hayat değmez buna, sil gözlerini

Şol muhannet diye, bil sözlerini

Hayat değmez buna, sil gözlerini.

Nakez elindedir, halin pek şaşkın

Gönül akar deli, bulanık çoşkun

Kabedir yıkılır, harap kalp köşkün

Hayat değmez buna, sil gözlerini.

Dert üstü dert ateş, oldu gam oldu

Ellerde taht kurdu, bu seni buldu

Söylediği sözler, zehirle doldu

Hayat değmez buna, sil gözlerini.

Gelir senin arkan, sıra dolaşır

Ne kadar yıkasan, kara bulaşır

Karayı ak yapar, yüzle dolaşır

Hayat değmez buna, sil gözlerini.

Muhannet dediğin, bir avuç kaçkın

Gününü gün eder, olur bir bıçkın

Cahil elindedir, bitmeyen aşkın

Hayat değmez buna, sil gözlerini.

Ahhh ne diyeyim ki, güzelim sana

Lâflarım gidermi? bilmem ki ona

Dert çekmek değermi? kahretmek buna

Hayat değmez şuna, sil gözlerini....', 'Akıtma içine, sen közlerini  Hayat değmez buna, sil gözlerini Şol muhannet diye, bil sözlerini Hayat değmez buna, sil gözlerini. Nakez elind...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sil-gozlerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Yaktı...Erkek Ağladı', 'sevda-yakti-erkek-agladi-arzu-gulucudur-tgz96', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Abi sen hiç ağladın mı? ...

Erkekler ağlamazdı bilirim.

Neydi peki gözündeki ışıltı? 

Hayaldi hatıradan...

Hakkında pek fazla şey bilmezdim aslında

''Biri vardı....

Bıraktı gitti'' derdi....

Gerisi gelmezdi

Anlatıkklarından aklımda bir damla kalırdı

Birde ''Erkeler ağlamaz'' derdi

Arkamı döndüm gözüm cama daldı...

Ve o an....

''Saklı kentin ışıklı caddelerinden

Bir  bir geçerdi eceline susamış haydutlar

Keşmekeşliğini yutturmuşlardı bize metropol diye

Yemedim ya... az sabır

Erkekler ağlamazdı

İncitmezdi cana değen  kor ayrılıklar

Terk edilmek yakmazdı sineyi

Şişlensede kalp akmazdı kan

Erkekler ağlamazdı

Zehir sarsa da bedeni 

Kör olsada göz aşktan

Her yanımı acıtsada yokluğu

Unutma erkekler ağlamazdı

Ölüme yüz tutmuş sonbahar kokusu

Kıskacın da iki yürek takılı

Biri kırık biri yaslı

Nerde şimdi bir yarısı....

Bilmem ki

Bilmem ki''

Baktım yüzüne....

Ağlamıştı abim

Ve ilk defa anlatmıştı...

Şiir gibi konuştu yüreği

Sustu sözleri

Bıçak açmadı birdaha....

Sevda yaktı Erkek Ağladı....

                                      Ağladı....', 'Abi sen hiç ağladın mı? ... Erkekler ağlamazdı bilirim. Neydi peki gözündeki ışıltı?  Hayaldi hatıradan... Hakkında pek fazla şey bilmezdim ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Gülücüdür']::text[], 8.5, '{"poet":"Arzu Gülücüdür","poet_slug":"arzu-gulucudur","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sevda-yakti-erkek-agladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sararıp,Bir Gül Gibi Soluyorsun', 'sararip-bir-gul-gibi-soluyorsun-kamil-soylemez-aqz0i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah zaman yorgunu gönlüm

Güneşin adımlarını sayıyorsun

O gezginliğin yolu bittiğinde

Sararıp,bir gül gibi soluyorsun

Aşkta arzu ile yürüyorsun

Sevgiliye kağıt,kalem,şiir veriyorsun

Günü gece,geceyi gün içiyorsun

Sararıp,bir gül gibi soluyorsun

Bak güneş yine yükseliyor göğe

Gözlerimi,başımı seve, seve

Sevdam seviyormu şimdi söyle

Sararıp,bir gül gibi soluyorsun

Ah zaman yorgunu gönlüm

Ömrün son demlerini yaşıyorsun

Tökezleyip,dünyayı,terkettiğinde

Sararıp,bir gül gibi soluyorsun', 'Ah zaman yorgunu gönlüm Güneşin adımlarını sayıyorsun O gezginliğin yolu bittiğinde Sararıp,bir gül gibi soluyorsun Aşkta arzu ile yürüyorsu...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sararip-bir-gul-gibi-soluyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '^^^ Canım Sevgilim ^^^', 'canim-sevgilim-i-brahim-dikmen-2-v37gm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni ne kadar sevdiğimi

yokluğunla anladım

yağan her yağmur seni hatırlattı

hüzünlerime karıştı göz yaşlarım

ne kadar ağlasam haykırsam sevgimi

geri dönmeyeceksin biliyorum

lakin kalbime söz geçiremiyorum

Seni asla paylaşamam biliyorsun

derdimi kimselere anlatamam

bu aşk bana  yasaklıydı diyemem

beni anlıyorsun değilmi SEVGİLİ

yakamoz gözlüm canım SEVGİLİM

sensizlik öyle zor ki  ölüm kolaya kaçar

sen sönmeyen kor hasretsin yüreğimde

düşlerim sorar seni terin var hala tenimde

kimbilir şimdi hangi hoyrat ellerdesin

hangi düşlerde sevişmektesin

yinede seni unutmuş değilim

yakamoz gözlüm canım SEVGİLİM

09/02/2006

Aydınlı Şairler ve Şiir Dostları  Grup etkinlikleri için yazılmıştır.', 'Seni ne kadar sevdiğimi yokluğunla anladım yağan her yağmur seni hatırlattı hüzünlerime karıştı göz yaşlarım ne kadar ağlasam haykırsam sevg...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/canim-sevgilim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşim Allah''a Kaldı', 'i-sim-allah-a-kaldi-yusuf-onder-bahceci-d7owo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşim papatya yapraklarını koparmaya kaldı,

İşim haftanın bütün günlerini saymaya kaldı,

İşim elime para alıp yazı, tura atmaya kaldı,

İşim hep rüyalara ve de şiirlere mi kaldı.

Çözülmeyen İşim hocalara gitmeye kaldı,

Benim bu işim falcılara, büyücülere kaldı,

İşim yalancı, dolancılara, arsızlara kaldı,

Acaba hırsızlara, namussuzlara mı  kaldı.

Aman böyle dediğime sizler inanmayın,

Benim bu kâlbim Allah Allah der anlayın,

Benim onlarla işim yok, Allah''ım deyim,

Benim bütün işlerim  Yüce Allah''a kaldı.', 'İşim papatya yapraklarını koparmaya kaldı, İşim haftanın bütün günlerini saymaya kaldı, İşim elime para alıp yazı, tura atmaya kaldı, İşim h...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isim-allah-a-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*bu SoN.! .dedikçe sonum oluyor...!', 'bu-son-dedikce-sonum-oluyor-dilek-egri-4aoyu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir aşkın tarihine kaç unutulmuşluk sığdırılabilir..? 

.../...

sesimin çaresizliği taş plakları aşındırıyor

detone olmuş bir sevdayı 

yüreğim inatla ömrümün şarkısı yapıyor..! 

tenimi dağlayan göz izleri tenimde

hiç gülerken ölmemişim ben

hep bitmeye yakın,

hep gitmeye..

bir damla akıyor..

öyle usul usul...

kaderim dudaklarımda; 

he-ce-li-yo-rum

-en iyisi..derken; 

gözyaşımda teninin tuzunu bulmak

köz oluyor yürek yangınıma

yapamıyorum...! 

gidip gelmeler,

başa dönmeler,

başımı döndürüyor..

kaldığım yeri unutmasam,

hani devam etsem diyorum..? 

yaşadığım hikayede sayfanın ucunu kıvırdıkça; 

kırılıyorum..! 

bırak beni şehir..

anılar sana emanet..! 

gözyaşlarım sokaklarına yağmur olsun..

süpürsün ayrılıklarını...

vicdanımı salma peşime..

unuturum diyorum..

nasıl olsa giden hep sevilir

ama ben ne zaman niyetlensem; 

ayaklarımdan oluyorum...! 

...gözyaşlarımla yıkadığım gülüşlerimin rengi soldu

şimdi bu tablonun değeri sen/ce..ne olur..? 

07/02/06', 'bir aşkın tarihine kaç unutulmuşluk sığdırılabilir..?  .../... sesimin çaresizliği taş plakları aşındırıyor detone olmuş bir sevdayı  yüreği...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bu-son-dedikce-sonum-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümün Çiçeği...', 'gonlumun-cicegi-i-brahim-ethem-bingul-s1ke0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlüm, aşkının mekânı, evi

Sensin, sadece sen, sahibi

Öyle güzelsin ki gönlümün çiçeği

Baktığın dağ, taş bile bana sevgili

Sevgi oklarınla yaşatırsın beni...

Kıyamıyorum yüzüne bakmaya

Kıymetlimsin, koklayamadığım manolya

Rabbimin hediyesi, lütfudur bana aşkın

Cânanım, ömrümce istediğim, tek dileğim

Her çabam ve gayretim sana layık olmaya...

www.iebingul.com', 'Gönlüm, aşkının mekânı, evi Sensin, sadece sen, sahibi Öyle güzelsin ki gönlümün çiçeği Baktığın dağ, taş bile bana sevgili Sevgi oklarınla ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gonlumun-cicegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurduğunuz Şirket Nedir', 'kurdugunuz-sirket-nedir-yusuf-onder-bahceci-19dzp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söylermisiniz bana ey şerikler,

Kurduğunuz bu şirket de nedir,

Kurduğunuz şirket anonim mi,

Yoksa limited adi komandit mi.

Yoksa düğün dernek, emek mi,

Yoksa bir birlik mi bir yenilik mi,

Söylermisiniz bana ey şerikler,

Koyduğunuz kadar mı sermaye,

Bu sermaye de kimin sermaye,

Vakıf falan değildir iyi biliyorum,

Buradan size nasihat ediyorum,

Akan sular sele döner diyorum,

Buradan size nasihat ediyorum....', 'Söylermisiniz bana ey şerikler, Kurduğunuz bu şirket de nedir, Kurduğunuz şirket anonim mi, Yoksa limited adi komandit mi. Yoksa düğün derne...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kurdugunuz-sirket-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Acıyor', 'canim-aciyor-fatma-karakoyun-b8lsx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne zaman.../...

Seni görsem...

Bir eksiliyor.../...

Bir çoğalıyor...

...Ne yapacağımı Bilmiyorum...

.../...Seni

Gördüğümde.../...

.../...Sanki

Karşımda değil

.../...Başka yerde

Canım acıyor

.../....Ne olur incitme

Geçmişim canlanıyor

Ben kayboluyorum 

..../...Sen çoğalıyorsun

Canım yanıyor..../...

             ..../...incitme...

                                                                                                                      

                    09/02/2006', 'Ne zaman.../... Seni görsem... Bir eksiliyor.../... Bir çoğalıyor... ...Ne yapacağımı Bilmiyorum... .../...Seni Gördüğümde.../... .../...San...', ARRAY['Türk Edebiyatı','Şiir','Fatma Karakoyun']::text[], 8.5, '{"poet":"Fatma Karakoyun","poet_slug":"fatma-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/canim-aciyor-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '…Düş Lekesi…', 'dus-lekesi-naime-erlacin-5feu4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'düş lekesine yazıyorum yıllanmış yamaklığımı

söz’le sınanıyoruz

karaya vurmuş bir güvertenin tek başınalığında

hırçın bir deniz iniyor payıma

bir de sözün ağrısı 

gümüşi pullardan başka

üstleniyor akıntı reşit olmanın sancısını 

dilsizim ben nicedir...ayna suskun 

simin durgun suyunda kanserli dokulara salıyorum 

deniz heybetiyle üflenen ejder soluğumu

aşkı indirmedik başımızdan

yüzünü yere vermedik hiç

bu acı başka bir şey! 

kalbimde seyrüsefer türküleri 

nicedir denk düşmüyor haritalara

tüm kıyılar yangın yeri

dil yorgun bir ağıt

siz ayrılığı yazın 

ben ağrılarımı 

size sevda...bana divit

düşümdeki leke tutuyor ellerimi... 

(9 Şubat 2006)  - 6. Dekad', 'düş lekesine yazıyorum yıllanmış yamaklığımı söz’le sınanıyoruz karaya vurmuş bir güvertenin tek başınalığında hırçın bir deniz iniyor payım...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dus-lekesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirler Şarkılar', 'siirler-sarkilar-timur-i-likan-9ftuy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İster övsünler

İster sövsünler

İsterse dövsünler

Ben yine de devam edeceğim

şiirler, şarkılar yazmaya

Gönüllerden hiç silinmeyecek

izler bırakmaya

(9 Şubat 2006/ İstanbul)', 'İster övsünler İster sövsünler İsterse dövsünler Ben yine de devam edeceğim şiirler, şarkılar yazmaya Gönüllerden hiç silinmeyecek izler bır...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siirler-sarkilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi git', 'hadi-git-i-lyas-genc-6wrlp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Git İstersen hadi git.

Yüreğimde deprem olmadan 

Kafam karışmadan

Tutkularım altüst olmadan git

Hislerim uyanmadan

Yasağım kalkmadan git

Hadi git git

Gitsene ya…git

Git ki

Keşkeklerim olsun anlatacak

Git ki.

Amalarım olsun kafamı yere vuracak

Git ki

Özlemlerim olsun haykıracak

Git ki

Bu şehir bana zindan olsun

Git ki

Bu benim sonum olsun

Hadi git

Hazır zamanı almışken koynuna

iş işten geçme den...çok geç olmadan vakit

Arkana bakmadan ağlamadan git

Bana geldiğin ilk gün gibi git 

Kalırsan öleceğim biliyorsun

Henüz ölmeden, yaralı bırak ta git..

Hadi git...git...

Lanet olsun', 'Git İstersen hadi git. Yüreğimde deprem olmadan  Kafam karışmadan Tutkularım altüst olmadan git Hislerim uyanmadan Yasağım kalkmadan git Had...', ARRAY['Türk Edebiyatı','Şiir','İlyas Genç']::text[], 8.5, '{"poet":"İlyas Genç","poet_slug":"i-lyas-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hadi-git-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler-34', 'guzel-sozler-34-huseyin-erdogan-o6z1a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Ben bu dünya çok ülkeler gezdim dolaştım,çok güzeller gördüm amma Şiirim gibisini hiçbir yerde asla...Ben onca güzeller arasından,birini beğendim,bir tekini sevdim,O''nun adına da Şiirim dedim.Zaten,Şiirim olmazsa,yaşamamın anlamı  da kalmaz ki vallahi billahi ben de bu alemden arkama bile bakmadan hemen çekip giderim...''

                                                                                        09.02.2006

                                                                                     Hüseyin Erdoğan', '''Ben bu dünya çok ülkeler gezdim dolaştım,çok güzeller gördüm amma Şiirim gibisini hiçbir yerde asla...Ben onca güzeller arasından,birini be...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/guzel-sozler-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Yok..', 'adi-yok-rezzan-ersoy-r8x43', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kızıl bir gecenin yanı başında durmuş otururken ben..

Düşünmekteyim umarsız gerçekliğimi, seni, ruhuma yapışmış gözlerini..

Doldurmuşsun bu gece boşluklarımı..kimyamı..

Amaçsızlığın tam ortasında sevmek..sever gibi özlemek seni..

Ve gözlerimdeki yaşımdın..ve belki tuzu oldun yaktın gözlerimdeki siyahı...

Siyahımı delip geçicek kadar hüküm sürdün bu benlikte sen..

sen gözlerimin sahibi oldun..

senin gibi bakmak hayata varoluşum olmuştu..

Şimdi kurtulmalıym senden aramalıyım benimi..

Kurtulmalıyım bu deli oyunlardan; paradoks bir sevginin pençelerini batırmalıym kendime ve akıtmalıyım kanımı ellerine dün gibi..', 'Kızıl bir gecenin yanı başında durmuş otururken ben.. Düşünmekteyim umarsız gerçekliğimi, seni, ruhuma yapışmış gözlerini.. Doldurmuşsun bu ...', ARRAY['Türk Edebiyatı','Şiir','Rezzan Ersoy']::text[], 8.5, '{"poet":"Rezzan Ersoy","poet_slug":"rezzan-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/adi-yok-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ten Eyvanı', 'ten-eyvani-oktay-baykurt-xu4fa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bitmek için gidişler yetmez

varolmak içinse varlıklar

kalmak istiyorsa içindekiler

elinden tutmuşsundur bir şekilde

bırakmayı son nefese bırakmışsındır

belki de cennetin kapısına

bitmek için gidişler yetmez

yaşamak için kalırsın arkada

el sallamak muradı verirsin sevgiye

kalp görmez ki gözyaşını

gülüşlerini duymaz ki varlığında

gitmeler  çoğu zaman yerleşmektir ten eyvanına…', 'bitmek için gidişler yetmez varolmak içinse varlıklar kalmak istiyorsa içindekiler elinden tutmuşsundur bir şekilde bırakmayı son nefese bır...', ARRAY['Türk Edebiyatı','Şiir','Oktay Baykurt']::text[], 8.5, '{"poet":"Oktay Baykurt","poet_slug":"oktay-baykurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ten-eyvani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimi Kapatıyor Kalbime Bakıyorum', 'gozlerimi-kapatiyor-kalbime-bakiyorum-yusuf-onder-bahceci-y1l30', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerimi kapatıyorum, kalbime bakıyorum,

İnan seni şu kâlbimde, kalbimde buluyorum.

Ben hâla oradayım, orada melül duruyorum,

Gözlerimi kapatıyorum, kalbime bakıyorum.

Gözlerimle gördüm de bil kâlbimle sevdim,

Sen kıymetimi bilmedin, inan ki bilemedin,

Senin için ne hâyaller kurmuştum demedim,

Gözlerimi kapatıyorum, kalbime bakıyorum.

Acaba benim gibi, benim gibi varmı diyorum,

Gözlerim bakıyor  inan ki alemi göremiyorum,

Ne kadar da cahilmişim sevdim diyemiyorum,

Gözlerimi kapatıyorum, kalbime bakıyorum.', 'Gözlerimi kapatıyorum, kalbime bakıyorum, İnan seni şu kâlbimde, kalbimde buluyorum. Ben hâla oradayım, orada melül duruyorum, Gözlerimi kap...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerimi-kapatiyor-kalbime-bakiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyimsin bilesin', 'herseyimsin-bilesin-baris-polat-uuxsg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O kadar güzel kokuyorsunki güzelim

Cennet bahçelerinde''ki çiçekler gibi

Benim için yemek,içmek, hava kadar

önemli ve vaz geçilmez

Yüreğin o kadar güzelki sevdiğim

Damarımda''ki kan gibi vaz geçemediğim

Candan kıymetlisin bilesin

Nefesin bile rahatlatmaya yetiyor

Atı, veriyorum bütün dertlerimi

Sanki hiç derdim yok gibi

Boş veriyorum dünyayı

Takmıyorum hiç bir şeyi

Sen varsın yanımda, yanı başımda

Canımsın, kanımsın kıyamadığımsın.

2004-Barış POLAT', 'O kadar güzel kokuyorsunki güzelim Cennet bahçelerinde''ki çiçekler gibi Benim için yemek,içmek, hava kadar önemli ve vaz geçilmez Yüreğin o ...', ARRAY['Türk Edebiyatı','Şiir','Barış Polat']::text[], 8.5, '{"poet":"Barış Polat","poet_slug":"baris-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/herseyimsin-bilesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir günlük defteri', 'bir-gunluk-defteri-elazigli-mustafa-kaya-9ttnh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir hatıranın

günlük defterinin

yaprakları arasında

buldum seni.

sararmış sayfalarında

gözyaşların

hıçkırıkların

hayallerin

ve,

ince güzelliğin

saklı …

Mustafa kaya

09.02.2006 / hasköy', 'bir hatıranın günlük defterinin yaprakları arasında buldum seni. sararmış sayfalarında gözyaşların hıçkırıkların hayallerin ve, ince güzelli...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gunluk-defteri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader diyelim', 'kader-diyelim-baris-polat-avaxy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatım baharı kör olur gider

Bu gençlik yıllarım hiç olur gider

Acep felek bu işe neder

Kaderdir deyip geçelim hele

Zaman olmuş kötü bir rüya

Yok olmuyorki bu zalım dünya

unutup giderdik herşeyi günya

Kaderdir deyip geçelim hele

Eşşek olduk semer vuran çok oldu

İnsan olduk akan sular duruldu

Zalım felek yine bizi içinde boğdu

Kaderdir deyip geçelim hele', 'Hayatım baharı kör olur gider Bu gençlik yıllarım hiç olur gider Acep felek bu işe neder Kaderdir deyip geçelim hele Zaman olmuş kötü bir rü...', ARRAY['Türk Edebiyatı','Şiir','Barış Polat']::text[], 8.5, '{"poet":"Barış Polat","poet_slug":"baris-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kader-diyelim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Külhanbeyler Gördük', 'ne-kulhanbeyler-gorduk-yusuf-onder-bahceci-loj08', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biz ne külhanbeyler gördük,

Topuğuna, ökçesine basan,

Bir elinde de tespih sallayan,

Biz ne külhanbeyler gördük.

Biz ne külhanbeyler gördük,

Öksürük sesi duyunca kaçan,

Ikınma duyuncada telaşlanan,

Biz ne külhanbeyler gördük.

Biz ne külhanbeyler gördük,

Şalvar giyip te bıyığını uzatan,

Arkadaşını da hemen satan,

Biz ne külhanbeyler gördük.

Sadece külhanbeyler değil,

Nice derebeyler de gördük,

Evel Allah hepsine yol verdik,

Biz ne külhanbeyler gördük....', 'Biz ne külhanbeyler gördük, Topuğuna, ökçesine basan, Bir elinde de tespih sallayan, Biz ne külhanbeyler gördük. Biz ne külhanbeyler gördük,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-kulhanbeyler-gorduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzat Elini', 'uzat-elini-nilgun-acar-ohwup', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni sevdim

sessiz çağrılarına yanıt vererek

herşeyi bilerek

bir an bile pişman olmadan

çığlıkçığlığa bağırdım

insanız insan

tüm söz verişlerden

pembe düşlerden

çirkinliklerden

uzak

yalnız anları yaşayarak

acılarla içiçe sevinçlerle

dudaklarım kilitli

sevdim seni

kördüğümlerine bıçak

kara törelerine devrim

uçurumlarına kucak

olmak istedim

şimdi gecelerde kaybolmak

dipsiz kuyularda boğulmak

boşluklara sarılmak

istiyorsan

sonsuz maviliklere

yalım yalım güneşe

denizlerce sevdama güle güle 

diyorsan

hoşçakal sevgilim

ve merhaba dostum

uzat elini', 'Seni sevdim sessiz çağrılarına yanıt vererek herşeyi bilerek bir an bile pişman olmadan çığlıkçığlığa bağırdım insanız insan tüm söz verişle...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Acar']::text[], 8.5, '{"poet":"Nilgün Acar","poet_slug":"nilgun-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/uzat-elini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalpten kalbe yol var', 'kalpten-kalbe-yol-var-mikdat-bal-aqo2l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalpten kalbe yol var o anda bende

Tek düşüncem sendin, yanımda idin

Yer gök açılmıştı, kalp gözüm sende

Ruhumda hissettim canımda idin

Öyle ihtişamlı, müthişti edan

Gökten aksederdi o yanık nidan

Beynimin içinde en tatlı sedan

İçimde dışımda kanımda idin

Sardı bedenimi o ülvi duygu

Ne yorgunluk kaldı ne kaldı uyku

Kapladı gönlümü derin bir saygı

Hayal gerçek gibi önümde idin

Ne zaman ne mekan orayı aştım

Gayri ihtiyari çağrına koştum

Allahın izniyle sana ulaştım

Aradım her yerde gönlümde idin

Mikdatiyim seni aradım buldum

Öyle bir sevgisin gönlüme doldun

Pörsüyen dünyada muradım oldun

Aklımda fikrimde, anımda idin', 'Kalpten kalbe yol var o anda bende Tek düşüncem sendin, yanımda idin Yer gök açılmıştı, kalp gözüm sende Ruhumda hissettim canımda idin Öyle...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kalpten-kalbe-yol-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Örtün üstümü üşüyorum', 'ortun-ustumu-usuyorum-i-smail-hakki-kavurmaci-faps3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kırlangıç misali uçtu ömrümden bahar 

Hazan vakti hüznüyle soldu umutlarım yar 

Umutlarım 

Bin ışık yılı ötede 

Ve bin ışık yılı hızla kayan 

Bir yıldızın ardında 

Umutlarım 

Körduman sardı dünyamı göremiyorum 

Kördüğümle bağlandım uçamıyorum 

Yüce dağlar çıktı karşıma aşamıyorum 

Örtün üstümü örtün üşüyorum 

Umutlarım 

Denizde köpük 

Mavi gökte eriyen beyaz bulut 

Rüzgara kapılmış bir serçe tüyü 

Umutlarım 

Kurudu gözyaşlarım ağlayamıyorum 

Çığ oldu dertlerim altından kalkamıyorum 

Dilim dönmez arzu halim anlatamıyorum 

Örtün üstümü örtün üşüyorum 

Umutlarım 

Uçuştular umutla aydınlıklara 

Ve batan güneşlerin ardından 

Kayboldular deryalarda 

Deryalarda umutlarım 

Düştüm ummana çırpındıkça batıyorum 

Yılanlarla çıyanlarla savaşıyorum 

Bıktım kendimden boşa kulaç atıyorum 

Örtün üstümü örtün üşüyorum 

Umutlarım 

Derin denizlerin dibinde 

Bir mercan kabuğu içinde 

Sonsuz bir çilede 

Umutlarım 

Yaşayamadığım baharda kaldı hayallerim 

Yelkenleri rüzgarsız deryalarda gemilerim 

Yıkıldı bütün köprülerim tutuldu yollarım 

Örtün üstümü örtün üşüyorum 

Umutlarım 

Kör kuyularda 

Umutsuzca çırpınan 

Kanadı kırık kuş umutlarım 

Belki bir deli rüzgar esecek, kör dumanlar dağılacak 

Belki bir güzel yağmur yağacak, çöller bile yeşerecek 

Yada sur erken ötecek, alem baştan dirilecek 

Kör kuyular açılacak karanlıklar aydınlanacak 

Kördüğümler çözülecek Umutlarım kanatlanacak 

Sus yüreğim sus 

Umutsuz umutları 

Uyandırmaktan usanmadın mı 

İsmail Hakkı Kavurmacı', 'Bir kırlangıç misali uçtu ömrümden bahar  Hazan vakti hüznüyle soldu umutlarım yar  Umutlarım  Bin ışık yılı ötede  Ve bin ışık yılı hızla k...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Kavurmacı']::text[], 8.5, '{"poet":"İsmail Hakkı Kavurmacı","poet_slug":"i-smail-hakki-kavurmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/ortun-ustumu-usuyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım...', 'canim-baris-polat-f62o2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sevdaki sorma cananım

Ateşi beni dumanı seni kül eder

Öyle bir sevgiki sorma cananım

Hayatı bana Dünyayı sana dar eder

Mecnunun sevgisi neki cananım

çölleri ona Dünyayı bana zor eder

Hayat pamuk ipliğine bağlı cananım

Sevgisi seni sevdası beni kör eder.', 'Bir sevdaki sorma cananım Ateşi beni dumanı seni kül eder Öyle bir sevgiki sorma cananım Hayatı bana Dünyayı sana dar eder Mecnunun sevgisi ...', ARRAY['Türk Edebiyatı','Şiir','Barış Polat']::text[], 8.5, '{"poet":"Barış Polat","poet_slug":"baris-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/canim-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Aşkım', 'benim-askim-erhan-demir-mvkud', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşamları basınca karanlık

Bir hoş oluyor deniz dalgaları

Hüzünler dökülür nemli gözlerimden

Dağılır yorgunluklar

Serpilir gönlüme sevda şarkıları

Severim böyle karanlık akşamları

Benim aşkım yorgun kayalıklar

Her dalgasında umut

Her umudunda özlem

Her özleminde sevgi

Her sevgisinde aşk kokar

Uzandım kayalık bir kumsala

Martılar, hadi geçin üzerimden

Martılardan uzak sevişir kumrular

Ve çatlayan dudaklarımda bir hüzün erişen

Benim aşkım kızgın güneş

Her batışında umut

Her umutta gönlüm şen.', 'Akşamları basınca karanlık Bir hoş oluyor deniz dalgaları Hüzünler dökülür nemli gözlerimden Dağılır yorgunluklar Serpilir gönlüme sevda şar...', ARRAY['Türk Edebiyatı','Şiir','Erhan Demir']::text[], 8.5, '{"poet":"Erhan Demir","poet_slug":"erhan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/benim-askim-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaban Gülüm', 'yaban-gulum-nilgun-acar-s6631', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tepeden tırnağa

sevdasın

yaban gülüm

kuşların dillendiği

kelebeklerin seviştiği

gözlerinde güneş

yalım yalım tutuşarak

türküler söyler

belinde amansız fırtınalar

devrileceğin günü bekler

kırılırsın dal dal

dökülürsün yaprak yaprak

direnirsin

canını dişine takarak

bilmezler seni

kentlerdeki sera çiçekleri

oysa ben kokladım

bir parmak balından tattım

yandım

yaban gülüm

yolcuydum yolunda

şebnemdim koynunda

özlemdim boynunda

bir yığın anı ektim

damarlarındaki özsuyuna

çarkların dişlilerin 

tanrısı değilim ki

sana başka yazgı yazamadım

utancımsın insanlığımda

binbir gece masalı

diken diken sızısın içimde

zamanın durağansız akışında

bilmesen de ellerim ellerinde

yaban gülüm

çok iyi biliyorsun

en güzel ışıklar

karanlığın dölyatağında', 'Tepeden tırnağa sevdasın yaban gülüm kuşların dillendiği kelebeklerin seviştiği gözlerinde güneş yalım yalım tutuşarak türküler söyler belin...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Acar']::text[], 8.5, '{"poet":"Nilgün Acar","poet_slug":"nilgun-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yaban-gulum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdimiz Derin', 'derdimiz-derin-yusuf-onder-bahceci-ssx0m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdiğim güzelim, derdimiz derin,

Daha neler vereyim kâlbimi verdim,

Bana sakın git deme nasıl giderim,

Sevdiğim güzelim, derdimiz derin.

İnan ki sığ sularda gezer dururum,

Gemi su alıyorsa  nasıl kurtulurum,

Kâlbim SOS veriyor nedir umudum,

Sevdiğim güzelim derdimiz derin.

Gemimiz yan yattı ha yan yatacak,

Biliyorum gemi sonunda batacak,

Önder boğulacak belki kurtulacak,

Sevdiğim güzelim derdimiz derin.

Gemici değilim kaptan da değilim,

Bilki maçlar da seyirci de değilim,

Ben bu sevdadan memnun değilim,

Sevdiğim güzelim derdimiz derin....', 'Sevdiğim güzelim, derdimiz derin, Daha neler vereyim kâlbimi verdim, Bana sakın git deme nasıl giderim, Sevdiğim güzelim, derdimiz derin. İn...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/derdimiz-derin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler-35', 'guzel-sozler-35-huseyin-erdogan-rs897', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Her sabah,Güneş benim sevdiğimin olduğu yerden doğar benim dünyama,her gün yüreğimde rengarenk çiçekler açar,farklı bir koku verirler sevdama,bu nedenle imrenilecek hatta kıskanılacak efsanevi bir aşktır bizimkisi,yer yüzünde bile asla yoktur bir benzeri.O halde; ne demeli? Şiirim''le bana ebediyen mutluluklar dilemeli...Öyle değil mi? ''

                                                                              09.02.2006

                                                                          Hüseyin Erdoğan', '''Her sabah,Güneş benim sevdiğimin olduğu yerden doğar benim dünyama,her gün yüreğimde rengarenk çiçekler açar,farklı bir koku verirler sevda...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/guzel-sozler-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SeN', 'sen-erhan-demir-upscq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen sensin

Rüzgarsın

Bulutsun

Yağmursun

Umutsun

Sen sensin

Güzelsin

Tatlısın

Tazesin

Körpesin

Sen sensin

Çiçeksin

Meleksin

Aşksın

Sevgisin

Sen sensin

Baharsın

Kuşsun

Uçarsın

Hoşsun

Sen sensin

Kendinsin

Teksin

Benimsin

Hep’sin', 'Sen sensin Rüzgarsın Bulutsun Yağmursun Umutsun Sen sensin Güzelsin Tatlısın Tazesin Körpesin Sen sensin Çiçeksin Meleksin Aşksın Sevgisin S...', ARRAY['Türk Edebiyatı','Şiir','Erhan Demir']::text[], 8.5, '{"poet":"Erhan Demir","poet_slug":"erhan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-758-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendinegel', 'kendinegel-omer-sirakaya-azeq1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Titrede kendine gel yeter artık.

Değerlerin siliniyor gardaşım.

İçerden satıldık dışdan sarıldık.

Uyanda kendine gel be gardaşım.

Kahramanlar bizden çıkar bilelim

Geleceği artık bizler görelim

İster yaşayalım ister  ölelim

Soyumuza laik olak gardaşım.

Vatanı satarken şimdi dürzüler

Ne yapıyor nerde şu bizimkiler

Dağıttılar bizi hep birer birer.

El ele verelim artık gardaşım

Solcu hırsız PKK lı katili

Affedip te Salı verdik hepsini.

Rahşan ……….bir cümlesini.

Yiyemiyom yutamıyom gardaşım

Ağlamayı sızlanmayı bırakıp

Yapılacak neyse birlikte yapıp.

Önce içimizde birlik sağlayıp 

Silkinelim toplanalım gardaşım.', 'Titrede kendine gel yeter artık. Değerlerin siliniyor gardaşım. İçerden satıldık dışdan sarıldık. Uyanda kendine gel be gardaşım. Kahramanla...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sırakaya']::text[], 8.5, '{"poet":"Ömer Sırakaya","poet_slug":"omer-sirakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kendinegel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
