INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tutam Mutluluk', 'bir-tutam-mutluluk-nilgun-acar-7nmt7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ilık bir yaz gecesinde

alabildiğine kimsesizliğimi yaşarken

küçücük penceremden

caddedeki akışa karışıyordum

bölük pörçüktüm

boşluklarda savruluyordum

kalabalıkların ortasında

ve çok uzaklarda

yaşamın sevincini özlüyordum

apansız telefon çaldı

dost sesin yağmur yağmurdu

yıldızlar indi yeryüzüne

bir tutam mutluluk ektin yüreğime', 'Ilık bir yaz gecesinde alabildiğine kimsesizliğimi yaşarken küçücük penceremden caddedeki akışa karışıyordum bölük pörçüktüm boşluklarda sav...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Acar']::text[], 8.5, '{"poet":"Nilgün Acar","poet_slug":"nilgun-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-tutam-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalçın Dağları Aşarım', 'yalcin-daglari-asarim-yusuf-onder-bahceci-6o191', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bu yalçın dağları aşar, aşarım,

Bilki yâre doğru böyle koşar, koşarım,

Çoşkun seller gibiyim çoşar, çoşarım,

Ben bu yalçın dağları aşar, aşarım. 

Bahar gelince dağlarda kârlar erirse,

Kârlar eriyince de yârim geri gelirse,

Ona neler neler derim ki geri gelirse,

Ben bu yalçın dağları aşar, aşarım.

Yüksekler de hep ayaz olur, buz olur,

Gerçek sevenlerin yüreğinde köz olur,

Ben seni sorarım amma lafla söz olur,

Ben bu yalçın dağları aşar, aşarım.....', 'Ben bu yalçın dağları aşar, aşarım, Bilki yâre doğru böyle koşar, koşarım, Çoşkun seller gibiyim çoşar, çoşarım, Ben bu yalçın dağları aşar,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalcin-daglari-asarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'seni-terk-ediyorum', 'seni-terk-ediyorum-dursun-elmas-yvp09', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocuksu bir heves ile

Kapılmıştım cazibene.

Derken geçti onca sene

__Bıktım senden gidiyorum

__Sana elveda diyorum.

Öptüm sevdim, tattım seni

Bazen çöpe  kattım seni

Terk etmedin yine beni

__Sevdim deme gidiyorum

__Sana elveda diyorum.

Gece gündüz kokun derdim

Uğruna bir ömür serdim

Senden başka olmaz derdim

__Ama şimdi gidiyorum

__Sana elveda diyorum.

Otuz yılın geçti nazla

Sarmaladın tuttun hazla

Hatta biraz daha fazla

__Yalvarma hiç gidiyorum

__Sana elveda diyorum.

Ağısı al senin dedin

Gerisini yele verdin

Yıllar yılı cepten yedin

__İşte gördün gidiyorum

__Sana elveda diyorum.

Ne olursun gelme daha

Uğrama bizim dergâha.

Tükettin  ömrümü aha

__Dönememeye gidiyorum

__Sana elveda diyorum.

Zehir içtim yunağından

Hiç düşmedin dudağımdan

Öpem uzat yanağından

__Sona geldim gidiyorum

__Sana elveda diyorum.

09.02.2006', 'Çocuksu bir heves ile Kapılmıştım cazibene. Derken geçti onca sene __Bıktım senden gidiyorum __Sana elveda diyorum. Öptüm sevdim, tattım sen...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/seni-terk-ediyorum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yazar', 'ne-yazar-mehmet-postalli-r6c2h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün günlerden Pazar; 

Pazar olsa ne yazar? 

Beynimi dişleyen kurt; 

Asla yapmıyor Pazar.

Arsızların elinde; 

Lekelenir Gülizar.

Yel eser dal kırılır; 

Umut canından bizar.

Huzura düşman olan; 

Sevgiye kuyu kazar.

Çok ütülen kumarbaz; 

Hayatına atar zar.

İşleri birbirine; 

Karıştırır işgüzar.

En maharetli olan; 

Yine işitir azar.

Tomruklar akla gelmez; 

Gülü kesiyor hızar.

Güçsüzün, kimsesizin; 

Yanağından kan sızar.

Merhemlenmeyen yara; 

Tazelenir ve azar.

Eşekten çifte yiyen; 

Gider palana kızar.

Şu dikenli zeminde; 

Yürüdükçe yol uzar.

Birinin yaptığını; 

Diğeri kökten bozar.

Biçare sabır taşı; 

Eriyor azar azar.

Dedemden kalma mitil; 

Sopa yedikçe tozar.

Gönül hep yükseklerde; 

Akla gelmiyor mezar.

Güzele, güzelliğe; 

Nazar değdiler nazar.

Bugün günlerden Pazar; 

Pazar olsa ne yazar.', 'Bugün günlerden Pazar;  Pazar olsa ne yazar?  Beynimi dişleyen kurt;  Asla yapmıyor Pazar. Arsızların elinde;  Lekelenir Gülizar. Yel eser d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ne-yazar-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Serseri', 'tatli-serseri-nilgun-acar-0jt77', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamı ertelemiyorum

tatlı serseri

içim kıpır kıpır

hüznü ve sevinci

içiçe yaşıyorum

yeşil sarı Eylül

bir sevi mi getiriyor

tatlı serseri

amansız dalgalarla

kıyılarıma vuruyorsun

durmadan

alıp alıp götürüyorsun

birşeyleri bölüşüyoruz

bütünleşip

ayrılıyoruz

konuşamıyorum seninle

paramparça oluyorum

kuş kanatlarında

tutsaklığı tadıyorum

üşüyorum yangınlarda

yüreğimi bırakıyorum

çağrılarına

çığlıkçığlığa susuyorum

sana

bir anlatabilsem

tatlı serseri', 'Yaşamı ertelemiyorum tatlı serseri içim kıpır kıpır hüznü ve sevinci içiçe yaşıyorum yeşil sarı Eylül bir sevi mi getiriyor tatlı serseri am...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Acar']::text[], 8.5, '{"poet":"Nilgün Acar","poet_slug":"nilgun-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tatli-serseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler -36', 'guzel-sozler-36-huseyin-erdogan-d4oc8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgili Şiirim''e

''Eğer,bana bir tek seçim hakkı verselerdi,Şiirim''le ömrümce Büyükada''da yaşamak isterdim...Gün doğumlarında ve gün batımlarında,geceleri de ay ışığında,adanın her seferinde bir başka yerinde,Sevgili Şiirim''e aşkımı ve sevgimi ifade eden şiirler söylerdim...''

                                                                                               09.02.2006

                                                                                            Hüseyin Erdoğan', 'Sevgili Şiirim''e ''Eğer,bana bir tek seçim hakkı verselerdi,Şiirim''le ömrümce Büyükada''da yaşamak isterdim...Gün doğumlarında ve gün batımlar...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guzel-sozler-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülent Dost', 'bulent-dost-suleyman-zaman-tkb91', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BÜLENT CAN

        

Çok iylik gösterdin inan ki bana

Gelen gider bir gün, kalmaz bu hana

Muhabbet etmeli erdemli cana

Yaşamın anlamı budur Bülent Can

Var mıdır? Evrenin sonsuz ahengi

Olmaz ki bir şey, başka şeyin dengi

Zenginlik var eden, muazzam rengi 

Bu renkten biri de sensin Bülent can

Kendini bilenler bilir sözünü

Esirgemez dosttan, güler yüzünü

Kapılıp yanlışa  dövme dizini

Sende benim gibi, sonra Bülent can 

İnsanlık kalmadı, koca mekanda

Umut vardır, çıkmayan her bir canda

Fazla kalınırsa, siste dumanda

Yitirir yönünü kişi Bülent can

Zamanım değer verir,  iyi dosta

Atma içine sorun, olma hasta

Dünyada üretilen  her tür pasta

Pay edilse kavga olmaz Bülent can.

                      09.02.2006', 'BÜLENT CAN          Çok iylik gösterdin inan ki bana Gelen gider bir gün, kalmaz bu hana Muhabbet etmeli erdemli cana Yaşamın anlamı budur B...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bulent-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sev Ya Öldür', 'ya-sev-ya-oldur-senol-alaca-fs7ys', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ya  seni sevdiğim gibi sev beni

allahına kadar, 

yada alıp uzaklara git gözlerini 

gidebildiğin kadar... 

insan bir kere gelir dünyaya bir kere ölür.

ya seni yaşadığım gibi yaşa beni

doya doya,

yada al götür cismini, hayalini 

bin kere öldür...', 'ya  seni sevdiğim gibi sev beni allahına kadar,  yada alıp uzaklara git gözlerini  gidebildiğin kadar...  insan bir kere gelir dünyaya bir k...', ARRAY['Türk Edebiyatı','Şiir','Şenol Alaca']::text[], 8.5, '{"poet":"Şenol Alaca","poet_slug":"senol-alaca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ya-sev-ya-oldur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran', 'hicran-mehmet-postalli-jp2dp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülüm, ayrılalı günler yıl oldu

Ayrılık acısı varken, gezemem

Temmuzda kalemin boyası dondu

Kalem renk vermiyor, mektup yazamam

Senin hicranınla kalbim titrerken

Yüreğim çırpınır adını derken

Sabırla, ümitle, aşkla beklerken

Çilemi çekerim, sana kızamam

Sanki akvaryumdan çıkmış balığım

Âlemin içinde benzi soluğum

Tükendi direncim, bitti soluğum

Kelimeler düğümlendi çözemem

Gülüm, sen gelirsen gül açar gülüm

Harfler dile gelir, kalkar virgülüm

Gönlüm aydınlanır, açılır dilim

Lakin, sensiz heceleri dizemem.', 'Gülüm, ayrılalı günler yıl oldu Ayrılık acısı varken, gezemem Temmuzda kalemin boyası dondu Kalem renk vermiyor, mektup yazamam Senin hicran...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hicran-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haklısın Derlerdi', 'haklisin-derlerdi-yusuf-onder-bahceci-3hde8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölümüne sevdim nerden bilsinler, 

Seni benim gözlerimle görsünler,

Ondan sonra da yanıma gelsinler,

O zaman haklısın derler di bana.

Güzel gözlerin kâlbimi yakıyor da,

Sevdiğim yollara çıkıp bakıyor da,

Seven şu kâlbimi nasıl yakıyor da,

O zaman haklısın derler di bana.

Böyle bir şiir yazan gördünüzmü ki,

Gerçekten seversen yazarsın bil ki,

Benim sevdam yeni değil değil ki,

O zaman haklısın derler di bana.

Vallahi gücüm kalmadı tükendi be,

Bu şartlarda ben nasıl yaşarım be,

Ölecek biri varsa evvel öleyim be,

O zaman haklısın derler di bana.', 'Ölümüne sevdim nerden bilsinler,  Seni benim gözlerimle görsünler, Ondan sonra da yanıma gelsinler, O zaman haklısın derler di bana. Güzel g...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haklisin-derlerdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceksin! ...', 'gideceksin-tulay-sustam-yvdyb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gideceksin! ...

saçımdan bir tel beyaz kopacak

karanlığa gömeceksin beni

gideceksin! ...

şehrin kapısı kapanacak yüzüme 

yokluğunda, gölgemle köşe kapmaca oynayacağım

gideceksin! ...

dudağım kuruyacak 

güneşin saçından süzülen yağmur ıslatacak beni

gideceksin! ...

bir kuyruklu yıldızın peşinden

çocukluğumu büyüteceğim düş bahçelerinde 

sen bilmeyeceksin! ...

09 şubat / herhangi bir yer...', 'gideceksin! ... saçımdan bir tel beyaz kopacak karanlığa gömeceksin beni gideceksin! ... şehrin kapısı kapanacak yüzüme  yokluğunda, gölgeml...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gideceksin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin dediği gibi', 'sairin-dedigi-gibi-tevfik-karinca-u33u9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yansımalarında başarısızlıklarımın

Kahrımı çeken hep sen vardın

Belki çi_kindin

Ya da en çi_kini sevdiğim kadınların

Ne olursan ol be birtanem

Şairin dediği gibi ben sana mecburum

İçimde hiç te adam sendeci olmayan

O sıcaklık

Sevdiğine inandırdığın yakınlık

Herşeyden değerli değil miydi? 

Gözlerine bakıp ta

Kendimi gördüğüm

Tüm kaçışlarımda vazgeçip geri döndüğüm

Tek kadın sen değil misin? 

Hani şairin dediği gibi

Ben sana mecburum

Gidecek gibi olsan da zaman zaman

Çekilmezliklerime kızıp

Ben seni deliler gibi seviyorum

Hoyratlığıma ver serkeşliğime

Densizliğime serseriliğime

Ya da seni çok sevmeme

Benim canım değerlim

Eş ruhum

Şairin dediği gibi

Bil ki ben sana mecburum', 'Yansımalarında başarısızlıklarımın Kahrımı çeken hep sen vardın Belki çi_kindin Ya da en çi_kini sevdiğim kadınların Ne olursan ol be birtan...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sairin-dedigi-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birini Buldum', 'birini-buldum-mehmet-postalli-mu0fn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin açtığın yarayı;

Saracak birini buldum

Yıkıp gittiğin sarayı,

Kuracak birini buldum.

Kara gecenin sabahı

Geldi, yaşattı felahı

Bana yönelen silahı; 

Vuracak birini buldum.

Nevruz çiçek açmış gözde

Benler sıralı ak yüzde

Her vakit verdiği sözde; 

Duracak birini buldum.

Pırıl pırıl vicdanını

Sevgi kaynayan kanını

Seveni için canını; 

Verecek birini buldum.', 'Senin açtığın yarayı; Saracak birini buldum Yıkıp gittiğin sarayı, Kuracak birini buldum. Kara gecenin sabahı Geldi, yaşattı felahı Bana yön...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birini-buldum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Erittiğim Sızılarım', 'i-cimde-erittigim-sizilarim-yalcin-giray-kaya-nr4q5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendimi içine atamadığım

o derin rıhtım serinliğinde rüyalar yaşattı bana,

yalnızlığın kaybolmuş resim hatırası.

Ve ben gün geçtikçe daha çok acıyorum,

güneşe set vuran is kokulu perdenin ardında

yudum yudum çekip içimde erittiğim sızılarıma.

Tutup ellerinden kaldırmak istiyorum,

okşamak istiyorum saçlarını,

can alıcı saatlerde kavak yelleri estiren

bu kimsesiz sevdanın.

Ağlasam bir kere..,

kar mevsimi dile gelen gonca güller gibi gelir,

gelir belki, ya da belki dize gelir, insaf eder, pişman olur,

pişmanlığın en silik yanına nokta koyan puslu sevdam.', 'Kendimi içine atamadığım o derin rıhtım serinliğinde rüyalar yaşattı bana, yalnızlığın kaybolmuş resim hatırası. Ve ben gün geçtikçe daha ço...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Giray Kaya']::text[], 8.5, '{"poet":"Yalçın Giray Kaya","poet_slug":"yalcin-giray-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/icimde-erittigim-sizilarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilin öksüzü', 'dilin-oksuzu-serpil-maglicoglu-zb5y3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu dil benim/mi? 

Dil/immi ben/miyim

Duy/gu dilim/sen benim

Dil/siz miyim ben

Kelimesiz gibi

Eksik kelimelerim

Beynimi yaralar

Anlayisimi zorlarken

Bedeli emek/lemek

Dilin öksüzü oluyorsa

Ben anasiz babasiz

Bu dilin öksüzü

Yaralisi, yalnizi

Tek basina kalmisi

Bu dil benim/mi? 

Dil/immi ben/miyim

Dilsiz  yasarim

Kelimesiz asla

Algilamam, yansimam

Düsünürlügüm  var olmam

Bilincin  hücresine sarilmam

Zaman zaman üsümem

tek bir kelimeyle

Yeniden Isinabilmem

Emek/ledigim/dedigim

Dilimin

Öksüzü de olsam

Bu dil benim', 'Bu dil benim/mi?  Dil/immi ben/miyim Duy/gu dilim/sen benim Dil/siz miyim ben Kelimesiz gibi Eksik kelimelerim Beynimi yaralar Anlayisimi zo...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dilin-oksuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniyorum', 'sesleniyorum-battal-ozcan-6dbni', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saf kalbinin keşfedilmemiş yerlerine sesleniyorum; 

Bağrışlarım çağrışlarım yetmiyor tükeniyorum,

Duyuramıyorum haykırışlarımı,

Belki bir nefes kadar yakınım,

Belki bir adım sonra yanındayım

Ama takatimin son damlaları artık,

Duy sesimi yada sana yakaran kelimelerimi,

Aç kalbini yada gör sana ağlayan gözlerimi. 

Duy da al mutluluktan payına düşen hisseni

Aç ta gör yüreğine tek tek düşecek olan közlerimi.', 'Saf kalbinin keşfedilmemiş yerlerine sesleniyorum;  Bağrışlarım çağrışlarım yetmiyor tükeniyorum, Duyuramıyorum haykırışlarımı, Belki bir ne...', ARRAY['Türk Edebiyatı','Şiir','Battal Özcan']::text[], 8.5, '{"poet":"Battal Özcan","poet_slug":"battal-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sesleniyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Batımına Yetiş Hiç Olmazsa', 'bir-gun-batimina-yetis-hic-olmazsa-gul-yazganarikan-6pi47', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her sabah açıyorum güne bakan çiçekleri gibi

Bir ümit bir coşku ha birazdan ha şimdi

Derken akşam oluyor,

Alıp başını gidiyor güneş 

Küskün, kırgın, 

Utancından kızarıyor yüzü

Sen gelmiyorsun...

Her sabah ben açıyorum 

Akşam olup da batarken güneş

Ben de öyle batıyorum...

Bir gün batımına yetiş hiç olmazsa

Şöyle uzaktan da olsa

O güneş 

doğar da, batar da...

Ben onunla bir olamam

Ömrüm o kadar yok benim...

Ümitsiz bir ümitle güne tutunamam...

Bir gün batımına yetiş hiç olmazsa,

Kızarıyor güneş bile utancından

Gelmediğin her gün batımında

Ağlamak kalıyor bana, geceye düşen ay ışığında...', 'Her sabah açıyorum güne bakan çiçekleri gibi Bir ümit bir coşku ha birazdan ha şimdi Derken akşam oluyor, Alıp başını gidiyor güneş  Küskün,...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-gun-batimina-yetis-hic-olmazsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Ve Sevgi', 'cocuk-ve-sevgi-huseyin-sonmez-qk9w5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bütün çocuklar sevgi ister,

Onlara sevgini ne olur göster,

Onlardaki temiz hisler,

İşte o zaman gelişir.

Gözlerde hep nur vardır.

Kalpleri bembeyaz kardır.

Ellerinden  tut onları kaldır,

Ne olur göster, onlara sevgini.', 'Bütün çocuklar sevgi ister, Onlara sevgini ne olur göster, Onlardaki temiz hisler, İşte o zaman gelişir. Gözlerde hep nur vardır. Kalpleri b...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cocuk-ve-sevgi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kural Bu', 'kural-bu-cemil-aygen-kcnxc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anlattığım Herşeye 

İsyanı vardı çocuğun

Bir yılgınlık bir kırgınlık ki

Bıraksam ağlayacak gibi

Beni dinlese

İsyanını bastırıacağıma inanıyor

Oturup dinlemekten inadına kaçıyor

Sakinleşeceğine bağırıp çağırıyor

Orta yere birden

Sert bir el kol haraketiyle

Öyle bir bağırmışım ki

Bu dünyanın sonu değil diyen sesimden 

Ben bile ürktüm

Etkisini gösterdi..Sustu...

Dinle dedim...Zeliha iyi kız

Evet güzel de kız

Ama evlendi oğlum...Evlendi

Evlendiği oğlan 

Senin en yakın arkadaşın olmuş

Ne değişir

Hayat devam ediyor

Daha ne Zelihalar göreceksin

Tanrıya isyan etme

Kural bu...

Zengin olan kuvvetli olan..Şanslı olanın

Kazandığı bir dünyadayız

Dürüstmüşte,Yakışıklıymışta

Çıplaksın çıplak

Hem güzellikle çıplaklık bir olunca

Kader değişecek diye birşey mi var

A benim aptal oğlum......', 'Anlattığım Herşeye  İsyanı vardı çocuğun Bir yılgınlık bir kırgınlık ki Bıraksam ağlayacak gibi Beni dinlese İsyanını bastırıacağıma inanıyo...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kural-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Unutma', 'beni-unutma-cemil-aygen-ozd6c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni Unutmuşsun...Tamam da

Yaşadığımız hatıralar ne olacak

Ağaç diplerinde gizlenmelerimiz

Sahil boyu gezmelerimiz

Gizlice öpüşmelerimiz

Birbirimize yazdıklarımız ne olacak

Dönmeyeceğim diyorsun

Tamam..

Beni aldatığına bile kabulum

Bende yalnızca yaşadıklarımla kalırım

Ama sen ne dersen de

Ben hep seni sevdim

Sende bana...Hani hatırla

''Çok güzel öpüşüyorsun Cemil''

Dediğini ve 

Yine de beni 

Hiç ama hiç unutma emi...', 'Beni Unutmuşsun...Tamam da Yaşadığımız hatıralar ne olacak Ağaç diplerinde gizlenmelerimiz Sahil boyu gezmelerimiz Gizlice öpüşmelerimiz Bir...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beni-unutma-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir değil şair seçer', 'siir-degil-sair-secer-mikdat-bal-g5wug', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiir değil şair seçer

Okumadan yazar geçer

Bir de tıklar üçer üçer

Birbirini kandırırlar

Öyle güzel tatlıYORUM

Bakıp bakıp gülüYORUM

Hoş güzeldi kutluYORUM

Bunlar neyi andırırlar

Hece eksik nasıl işti

Yorum yazan saptı şaştı

Mükemmeldi, hem müthişti

Beni de inandırırlar

Yaranmaktır ona buna

Bundan çıkar böyle mana

Sen bana yaz ben de sana

Yorumları kondururlar

Mikdati der neylesinler

Böyle devam eylesinler

Yalan dersem söylesinler

Beni de utandırırlar', 'Şiir değil şair seçer Okumadan yazar geçer Bir de tıklar üçer üçer Birbirini kandırırlar Öyle güzel tatlıYORUM Bakıp bakıp gülüYORUM Hoş güz...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siir-degil-sair-secer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abdurrahman''a', 'abdurrahman-a-huseyin-sonmez-93184', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Minik yüreğiyle,gitti fırına,

Bilemedi ki çıkacak mıydı 

Yarına? 

Cebin de,bir beş yüzlük

Bir ekmek parasını kaptı,

Köşeden saptı

Koşarak caddeye fırladı.

Gözleri parladı.

Bir ekmek alacak

Artan bozukluk onun olacaktı.

Kalbi mutluluk dolacaktı.

Bir şeker parası

Ne de güzel yalayacaktı

Onu.

Caddeyi hızla geçti.

Tam kaldırıma çıkacaktı ki,

Hain bir kamyon

Onu seçti.

Sürükledi

Cadde boyunca

Miniği,

Yere yığldı kaldı! 

Acılar feryatlar! 

Kırşehir''i sardı.

Bu dünya ona dardı.

Kan ağlıyordu sabahın ayazı,

Kıpkırmızı kan olmuştu

Yere düşen çiğin beyazı.

Yürekler yanmış,kavrulmuştu.

Minik Abdurrahman

Minik yavrum

Bir sabah ayrılmıştı

Aramızadan.

Geride acı, gözyaşı

Bırakarak,

Yoksul aile

Alışmak zorundaydı

Onsuz yaşayarak...', 'Minik yüreğiyle,gitti fırına, Bilemedi ki çıkacak mıydı  Yarına?  Cebin de,bir beş yüzlük Bir ekmek parasını kaptı, Köşeden saptı Koşarak ca...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/abdurrahman-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Yok', 'adi-yok-i-brahim-etem-bakir-2brl2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Herkes gibi yazmamalıyız

Sevgilerimizi, aşklarımızı

Farklı yollarla anlatmalıyız

Bir sevgili özlenmez ki

Yaşanır.

Kimseyi özlemiyorum

Özlemem gerekenlerin yanındayım

Ve

Yanında olacağım

Herkes gibi olamayız ki

Herkesin bir adı var, soyu var.

Ve herkes, adına, soyuna layık olmalı.

Adlarımız,

Musa,

Davut,

İsa,

Ahmed değil mi? 

Ve Züleyha

Ve Meryem

Ve Sümeyye

Ve Fatıma değil mi? 

İsimlerimiz belli de

Soyumuz nereye dayanıyor; 

Nerde birleşiyor.

Herkes gibi olacaksam

Herkes gibi yazacaksam

Gece herkese geceyken

Neden bana gün olsun ki

Ve niye yazayım ki

Yazılması gerekenleri

İfade edenler oldukça...

E.B...', 'Herkes gibi yazmamalıyız Sevgilerimizi, aşklarımızı Farklı yollarla anlatmalıyız Bir sevgili özlenmez ki Yaşanır. Kimseyi özlemiyorum Özleme...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Etem Bakır']::text[], 8.5, '{"poet":"İbrahim Etem Bakır","poet_slug":"i-brahim-etem-bakir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/adi-yok-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen''de Ben', 'sen-de-ben-adem-tok-r046h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ya özgürlüğümü düşünüyorum

ya seni..

sende sonsuzluk var

sonsuzlukta sen...

                                                    (22.06.04) 

                                                    f tipi hapishane EDİRNE', 'ya özgürlüğümü düşünüyorum ya seni.. sende sonsuzluk var sonsuzlukta sen...                                                     (22.06.04)  ...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-de-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eda', 'eda-emrevildan-dost-n6tok', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yolun yok ulasamıyorum sana

umudun yok kuramıyorum düşünü 

sesin yok duyamıyorum şarkını

güneşin yok üşüyorum dünyanda

sen yoksun

gözlerin yok kaybolabileceğim 

saçların yok öpebileceğim 

gülüşün yok görebileceğim 

sadece bir şey var yapabileceğim 

onu da yapmaya dayanmıyor içim

her gün senin için

farklı bir çiçek koparmak

ve koymak mezarına', 'yolun yok ulasamıyorum sana umudun yok kuramıyorum düşünü  sesin yok duyamıyorum şarkını güneşin yok üşüyorum dünyanda sen yoksun gözlerin y...', ARRAY['Türk Edebiyatı','Şiir','Emrevildan Dost']::text[], 8.5, '{"poet":"Emrevildan Dost","poet_slug":"emrevildan-dost","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-goksel-bicak-cxkgd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'biriki dostla

küçüksu kıyılarında

küçük bir meyhanenin

sakin bir köşesinde

Hisar''a karşı bir masadayım

masanın örtüsü muşamba

günlerden çarşamba

önümde bir ufakla,balık ızgara

dudağımda tütüyor

edalı bir cigara

eşşiz tablolar geçiyor

Anadoluhisar''ı Rumeli''ye sevdalı

Aşiyan''dan selama durmuş şiirler

binbir işveyle parıldıyor

sularda yakamozlar

akgerdana takılmış

bir kolyeye benziyor

ışıl ışıl Boğaz köprüsü

vapurlar geçiyor nazlı edalı

peşine düşmüş koca bir martı sürüsü

ara ara taaa derinden

okşuyor ruhumu

çook eski bir Rumeli türküsü', 'biriki dostla küçüksu kıyılarında küçük bir meyhanenin sakin bir köşesinde Hisar''a karşı bir masadayım masanın örtüsü muşamba günlerden çarş...', ARRAY['Türk Edebiyatı','Şiir','Göksel Bicak']::text[], 8.5, '{"poet":"Göksel Bicak","poet_slug":"goksel-bicak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/istanbul-385-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yalancı Baharsın', 'sen-yalanci-baharsin-murat-demir-j4ixj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi söylüyormuşsun

Beni çok sevdiğini

Unutmuş gibi o gün

Vurup devirdiğini

Başına taş mı düştü

Aklından zorun mu var

Kalkar mı sanıyorsun

Aramızda ki duvar

Beklemene gerek yok

Gitti artık o tren

İçimde ki o aşkı

Sendin o gün bitiren

Cesaretin olsaymış

Gelecekmişsin  bana

Kararın kesin imiş

Ayrılmamaktan yana

Sanma ki benim için

Yeniden dönüp bakar

Sanma ki hala beni

O eski ateş yakar

Sen artık benim için

Sen artık dünkü yarsın

Çiçek çiçek açsan da

Sen yalancı baharsın', 'Şimdi söylüyormuşsun Beni çok sevdiğini Unutmuş gibi o gün Vurup devirdiğini Başına taş mı düştü Aklından zorun mu var Kalkar mı sanıyorsun ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-yalanci-baharsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miyav Miyav', 'miyav-miyav-emrevildan-dost-mucgc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen misin kapımı çalan ey yalnızlığım? 

Neredeydin bunca zamandır? 

Dertleşip teselli etmekse eğer niyetin 

Buyur içeri gir bi çayımı iç

Sahte sevinçler diyarında sevgini kaybettim

Yağmurun altında miyavlıyan bir kedi gibiyim şimdi

Eğer miyavlamam gerekiyorsa bana geri dönmen için

Duy o zaman ''miyav...miyav...miyav', 'Sen misin kapımı çalan ey yalnızlığım?  Neredeydin bunca zamandır?  Dertleşip teselli etmekse eğer niyetin  Buyur içeri gir bi çayımı iç Sah...', ARRAY['Türk Edebiyatı','Şiir','Emrevildan Dost']::text[], 8.5, '{"poet":"Emrevildan Dost","poet_slug":"emrevildan-dost","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/miyav-miyav-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açsam Yüreğimi', 'acsam-yuregimi-seher-ercan-so30s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşanası ne varsa 

Yeniden başlasam 

Dönüp ardıma bakmadan. 

Hiç görmediğim diyarlar 

Tanımadığım insanlar olsa karşıma çıkan 

Gittiğim yerde. 

Aralasam yüreğimin kapısını 

Sonra 

Sonra ardına kadar açsam. 

Biter mi dersin yalnızlığım 

Yalansız olur mu sence 

Başka dünya insanları 

Koşulsuz sevebilirler mi 

Benim gibi 

Yine de.', 'Yaşanası ne varsa  Yeniden başlasam  Dönüp ardıma bakmadan.  Hiç görmediğim diyarlar  Tanımadığım insanlar olsa karşıma çıkan  Gittiğim yerd...', ARRAY['Türk Edebiyatı','Şiir','Seher Ercan']::text[], 8.5, '{"poet":"Seher Ercan","poet_slug":"seher-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/acsam-yuregimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretindeyim', 'hasretindeyim-fatma-guven-lv6lf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elim ermez,gözüm görmez,

Canımın canı hasretindeyim.

Sitem değil bu kadere,

Canımın canı hasretindeyim.

Aramızda uzar sıra dağlar,

Hasretin gönlümü dağlar,

Sitem değil bu kadere,

Canımın canı hasretindeyim.

Gül gibi sararır solarım,

Haberin almazsam ona yanarım.

Sitem degil bu kadere 

Canımın canı hasretindeyim.

Kısmetten ötesi gurbet imiş,

Sensizlik bana ölüm imiş.

Sitem degil bu yaradana 

Canımın canı hasretindeyim.

Gül benzim soldugu zaman,

Ecel beni bulduğu zaman,

Sitemim yok yaradana.

Canımın canı hasretindeyim', 'Elim ermez,gözüm görmez, Canımın canı hasretindeyim. Sitem değil bu kadere, Canımın canı hasretindeyim. Aramızda uzar sıra dağlar, Hasretin ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasretindeyim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Mahalle', 'bizim-mahalle-huseyin-sonmez-81ujd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tan yerinin ağarması,

Sabahın ilk ışıkları,

Minarede okunan ezan,

Horozların ötmesi,

Hasan amcanın öksürüğü,

Belli ki camiye gidiyor,

Sonra ayak sesleri,

Önce tek tek,

Sonra tok tok,

Bakkal Ali kepenklerini açıyor.

Ayşe hanım köpeğini gezdiriyor,

Manav Mehmet çoktan başlamış

Karpuzlarını parlatmaya,

.

Hızlı hızlı yürüyen insanlar

Düşüyorlar

Birer birer yola

Ancak öğleyin

Verecekler mola,

Belki,

Ekmek arası peynir,

Hayat pahalı.

Yine kavga ediyor

Zehra annesiyle

Harçlık harçlık diye

Önlüğünü giymiş

Gözü yaşlı,

Çok güzel kız Zehra

Kara kaşlı

Babası polis

Annesi yurtta büyümüş

Kimsesiz.

Az dayak yemedi

Kacasından zavallı.

Polis baba

Bayağı havalı

Kimi günler içer

Naraları atar

Kuzeyden gelmiş 

Eski bir tatar.

Sabah başkadır

Bu mahallede

Ayrı bir gizem var

Her hanede...', 'Tan yerinin ağarması, Sabahın ilk ışıkları, Minarede okunan ezan, Horozların ötmesi, Hasan amcanın öksürüğü, Belli ki camiye gidiyor, Sonra ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bizim-mahalle-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liman', 'liman-nazli-guller-d39in', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gene yelken açtın, uzaklardasın 

Bense seni bekleyen sakin limanın 

Kıpırtısız sularım, dingin ve sessiz 

Hislerim yanılmaz, dönüşün yakın 

Kimse bilmez ne hissettirir 

Sensizlik bana 

Sen yokken beni besleyen aşk 

Çekilir damarlarımdan 

Kırık bir kalp, kırık bir gülüş 

Bir bekleyiş kalır geriye 

Merak ederim ne hissettiğini bensiz 

Umursamaz mı, dertsiz misin 

Ya da tasasız 

Ama her dönüşünde 

Kendine bile itiraf etmesen de 

Göz bebeklerin ele verir 

Bana olan özlemini 

Ne çok zaman oldu 

Ne çok şey paylaştık 

Sen dostluk dedin buna 

Bense ''aşk'' 

En güzel dostlukta 

Aşk barınmaz mı? 

Aşkın en güzelini 

Dostluk beslemez mi? 

Sen ister öyle söyle 

Ya da böyle de 

Bilirim yelkenlerinin görüneceğini 

Hiç gitmemiş gibi 

Geri döneceğini', 'Sen gene yelken açtın, uzaklardasın  Bense seni bekleyen sakin limanın  Kıpırtısız sularım, dingin ve sessiz  Hislerim yanılmaz, dönüşün yak...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Güller']::text[], 8.5, '{"poet":"Nazlı Güller","poet_slug":"nazli-guller","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/liman-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ambalajına Para', 'ambalajina-para-omer-dalman-z798i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şöyle

akşamları evine gidip de

gündüzleri, üzerinde taşıdığı

süper kamufle, gıcır gıcır

pak-temiz takımları üzerinden attığında

-her haliyle görünür- olduğunda

bütün manzaranın içine sıçmayan

hala o ''ambalajlı güzelliğini'' koruyan

ve daha da önemlisi

ambalajından sıyrılmadan önce

şöyle bir genelini süzdüğümde

yüzü bana

''bu ayakkabları bir çıkarırsam

ortalık leş gibi kokar'' gibi bakmayan Erkek

bence de güzeldir! 

ötekilerini salla gitsin be kadın! 

ambalajına mı para vereceksin? ! 

(Şubat 2006)', 'şöyle akşamları evine gidip de gündüzleri, üzerinde taşıdığı süper kamufle, gıcır gıcır pak-temiz takımları üzerinden attığında -her haliyle...', ARRAY['Türk Edebiyatı','Şiir','Ömer Dalman']::text[], 8.5, '{"poet":"Ömer Dalman","poet_slug":"omer-dalman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ambalajina-para-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'C a N', 'c-a-n-seher-ercan-7y799', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O an mahşerdi 

Yangın yeriydi sanki yürek 

inan. 

Son bir çırpınışla denedi 

Kurtarılacak geride kalan ne varsa 

Aşktan sevgiden arta kalan. 

Lakin 

Çoktan kararıp kül olmuştu 

Bir zamanlar senin için 

Candan yanan bu can. 

09.Şubat.2006', 'O an mahşerdi  Yangın yeriydi sanki yürek  inan.  Son bir çırpınışla denedi  Kurtarılacak geride kalan ne varsa  Aşktan sevgiden arta kalan....', ARRAY['Türk Edebiyatı','Şiir','Seher Ercan']::text[], 8.5, '{"poet":"Seher Ercan","poet_slug":"seher-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/c-a-n-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay Değildir', 'kolay-degildir-mehmet-ali-demircan-l6y7w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duyduğun her söze kulak aldırma,

Söylenen her kelâm doğru değildir,

Emin değil isen dostunu kırma,

Dostu bulmak dostum kolay değildir.

Şu günler fanidir, gelip geçecek,

Has olan elbette asla dönecek,

Yüreklerde asıl sevgi kalacak,

Dostu bulmak dostum kolay değildir.

İyi düşün; sözü bir kere söyle,

Uzun edip boşa dostunu üzme,

Haydi gel de barış kendini üzme,

Dostu bulmak dostum kolay değildir.

Bugün küskünlere barış günüdür,

Dilden hançerleri atma günüdür,

Sevgi yüreklerde bir gül gibidir,

Dostu bulmak dostum kolay değildir. 

MAD. 19.04.1995', 'Duyduğun her söze kulak aldırma, Söylenen her kelâm doğru değildir, Emin değil isen dostunu kırma, Dostu bulmak dostum kolay değildir. Şu gü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Demircan']::text[], 8.5, '{"poet":"Mehmet Ali Demircan","poet_slug":"mehmet-ali-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kolay-degildir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık...', 'karanlik-mehmet-ali-demircan-ctbri', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzünleri ektin yüreğime

Aşkın acıtır bedenimi,

Işık girmez penceremden

Dışarısı zehir karanlığı

tıpkı içim gibi,

Sabahı olmaz bu zehir gecelerin,

Ne ay gider

Ne güneş doğar içime,

Sensiz ayaz dolar yatağıma,

Yatılmaz, sıcak bir bedensiz,

Cellat olur

Kapımda bekler sabaha dek, karanlık.

Ne gül açar bahçemde

Ne bülbül olur neşeyle öterim,

Diken olur batar her yanıma aşkın,

Zehir olur sensiz

Kadehte rakım,

İçerim, hem ağı olur

Hem de ilaç,

Severim, hem hüzün olur

Hem de keder.

bazende en acımasızından

yağlı urgan.

22,04,2005 - 23-29

MADemircan.*Radyoerguvan.com

*** Aynalar Gerçeklerin Ta Kendisidir.

Konuş onunla, Doğruyu Söylemekten Çekinmeyecektir. ***', 'Hüzünleri ektin yüreğime Aşkın acıtır bedenimi, Işık girmez penceremden Dışarısı zehir karanlığı tıpkı içim gibi, Sabahı olmaz bu zehir gece...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Demircan']::text[], 8.5, '{"poet":"Mehmet Ali Demircan","poet_slug":"mehmet-ali-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/karanlik-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Gölge', 'vefasiz-golge-sabri-geldi-oxx4t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'VEFASIZ GÖLGE

Gölgem olmanı isterdim senin,

Hiç yanımdan ayrılmazdın benim,

Her zaman yanımda olman için,

Gündüzleri güneşin karşısında,

Akşamları sokak lambası altında,

Geceleri ise mum ışığının ardında,

Seni beklerdim,beklerdim beklemesine de..

Acaba sen beni istermiydin? 

Gündüzleri hava kapandığında,

Akşamları lambalar yanmadığında,

Geceleri mum eriyip bittiğinde,

Ne yapardım? 

Ne mi yapardım! 

Seni son kez görebilmek için,

Kendimi yakardım. 

 [email protected]', 'VEFASIZ GÖLGE Gölgem olmanı isterdim senin, Hiç yanımdan ayrılmazdın benim, Her zaman yanımda olman için, Gündüzleri güneşin karşısında, Akş...', ARRAY['Türk Edebiyatı','Şiir','Sabri Geldi']::text[], 8.5, '{"poet":"Sabri Geldi","poet_slug":"sabri-geldi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vefasiz-golge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk iki kişiliktir', 'ask-iki-kisiliktir-ozlem-aksoy-yr2hy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen durgunlaştığımda 

huzur bulduğum kucak

çoşunca öptüğüm dudaksın

tenimde sevgiyi hissettiren

rüzgarsın öyleyse.

ben senin kabulünsem

bütün savaşlara hazırım

ömrüm boyunca.

her zaman ki gibi bu gün de

yüreğimle sesleniyorum

içimdeki sevgiyi sana hediye ediyorum

aşk hep senin ve benimle olsun...', 'Sen durgunlaştığımda  huzur bulduğum kucak çoşunca öptüğüm dudaksın tenimde sevgiyi hissettiren rüzgarsın öyleyse. ben senin kabulünsem bütü...', ARRAY['Türk Edebiyatı','Şiir','Özlem Aksoy']::text[], 8.5, '{"poet":"Özlem Aksoy","poet_slug":"ozlem-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-iki-kisiliktir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağı', 'gokkusagi-zafer-mutlu-pct99', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sanma

bu feryatlar

bu yakarışlar,

ışıl ışıl caddelerin ses perdesine

takılır...

binlerce yürek,bir -kök peşinde,

ağlamak ayıp sayılır...

sanma

her geriye sayım,

yeni birşeyin başlangıcı...

karanlık

senin gözlerin dönmüş

kulakların sağır...', 'sanma bu feryatlar bu yakarışlar, ışıl ışıl caddelerin ses perdesine takılır... binlerce yürek,bir -kök peşinde, ağlamak ayıp sayılır... san...', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gokkusagi-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım', 'yarim-vahan-i-saoglu-9m22g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elle tutulamayanları çizmişti hep bir yerlere,

Karışık duygu salatalarının, hazmı zor zeytin yağı olmuştu çoğu zaman,

Yorucu gündüz rüzgarlarının nefesini saklardı hep,

Geceleri, solmuş,ıslak ve tuzlu suların ıslattığı kağıtları kuruturdu o nefesle...

Sıkılmamıştı yazmaktan, yıllar çok yazdırmıştı,

Bazen basit bir kelebeğin vadesi geçmiş ömrünü,

Sesi kısılmış, hiç konuşmadan bekleyen bir telefonu...

Körleşmiş bıçakların maziye dalışlarını,

Kimsesiz ağaçların yanı başında ulaşamadığı dostuna dallarını uzatmasını,

Şarkıların notalarını yazardı bazen, nasıl hayallerin kilitli kapılarına anahtar olduklarını...

Yer önemli değildi onun için, nasıl olsa misafirleri hep aynıydı, mekanın önemi yoktu.

Uzanırdı bazen bir yerlere, duramazdı, kağıtlara yazamasa bile beyninde birleştirirdi alfabenin minik yavrularını.

Onları el ele tutuşturur, birbirinden ayrılmaz sevgililer haline getirir sonra da zevkle izlerdi

Ayrılıkların yoldaşlığına çok şahit olmuştu ama onları kimse ayıramazdı,

Sonra bu aşkı yazardı bazen, öyle bir öpüşürdü ki bazen iki harf...

Yazıp çizmeye bile korkardı, ayıracaklar diye.

Arada sarhoşlukların zikzaklarını anlatırdı istemeden...

Çakırlıkların hafif ekşiliği gizlenirdi bazen üç satır arasına...

Bir sonraki sefer yamuk görülse de önemi yoktu, zaten o an sarhoştu, onu anlatmalıydı...

Harfler de sarhoş dururlardı, 

Mesela S harfinin omzuna öyle bir koyardı başını E harfi ki aşk ancak böyle anlatılabilirdi,

Hesapsız teslimiyetlerin ilk umutlarını anlatırdı bu sevişmeler...

Belliydi, ikisinin de başı dönüyordu ama mutluydular o güvenin maskesiz omzunda

Seni ve seviyorum kelimelerinin yürümeye başladığı ilk adımlardı bu harfler, asla unutulmazdı...

Asırlara sığmayacaktı yazacakları, ömrü yetmeyecekti varlıkların yokluğunu anlatmaya...

İsyanlar sığmayacaktı defterlere, kitaplara...

Bazen çok yorulur, uzun süre yazmaz, sadece izlerdi reklam arası almadan...

Sonra yine devam ederdi yaşamın, çizgilerden oluşan temelsiz prefabrik inşaatlarını çizmeye...

Sadece dört çizgiyi bir araya getirip yanına da iki çizgi çizip tepesinden öpüştürdümü.

Al sana EN kelimesi...

Mutlu oluyordu bu kelimeyi yazmaktan..

Yanına her meze giderdi artık, Yüklemler, tümleçler, özneler hep peyniri zeytiniydi masanın...

Aşkların köşesine çekilip ürktüğü dönemlerde bile yaşatabilirdi yazılarıyla.

Büyük dalgaların arasındaki yalnız balıkçının cesaretini boyayabilirdi bir misket tanesinin ışık almayan yüzüne...

Güvenlerin denizde boğulduğu dakikaların ressamı olabilirdi...

Karanlığın gizliliğine tutunmaya çalışan ama rüzgara direnemeyen bir yaprağın sesi olabilirdi...

Ama artık gücünün tükendiğini hissediyordu...

Yazarken titriyordu çizgiler, tam öpüşmüyordu artık kelimeleri oluşturan minik aşıklar...

Sahtelerin en masum yüzlerini bile çizerken şevkle, aniden durup kafasını masalara vuruyordu...

Sinirleri zayıflamıştı artık...

Sahte yüzleri aydınlattığını fark eden güneşin,

Utancından yerin dibine girdiği zamanı gösteriyordu akrep ile yelkovan.

Sokak lambalarının sokakları aydınlatmak istemediğini fark etmişti.

Evet yazacaktı...

Sayfa yine çok ıslanmıştı,

Kelimeler boşluk bırakmamaya niyetliydi sözde bembeyaz kağıda...

Sert kabuklu bir nar gibiydi o anki yalnızlığın yudumları,

Kendiliğinden dağılıp binlerce minicik harf olmuştu.

Müzik eşliğinde bir-bir sarılıyorlardı harfler titrek bir elin şefkatiyle, 

Soluğu kesiliyordu ağır-ağır,

Keskin notaların hüzün dolu çarpışmaları vardı karanlığın kan dolaşımında

İyice titrer olmuştu artık,

Bir şişe sarhoşluğun altında ezilen üç günlük teraziyi anlatıyordu çaresizliği.

Farkına varmıştı her şeyin...

Bu sahneyi bitirebilirdi ama bitirmek istemiyordu...

Hayatında ilk defa yazmak istemiyordu, direnmeye başladı.

Arası açılıyordu artık harflerin, kelimelerin,

Uzaklaşmalıydı oradan, bitmemeliydi bu yazı, bu şarkı...

Son kullanma tarihi geçmiş yolların, görünmeyen şeritleri gibiydi artık kelimeler,

Ama hala devam ediyordu istemeyerek,

Duraksadı bir an

Hayatının anlamını oluşturan minicik harflere baktı, son bakışıydı...

Önce Büyük harfleri öptü ellerinden, 

Sonra küçük harfleri gözlerinden,

Sesli veya sessiz, ünlü, ünsüz önemi yoktu.

Hepsi her şeyiydi...

Sevgilerinin sonsuz sarılmalarına şahit olamayacaktı belki tekrar.

Bir gözyaşını yazıp, okuyanları ağlatınca, iyi anlattığını düşünüp gururlanamayacaktı...

Ağlayamayacaktı...

Derin bir nefes aldı...

Ve son nefesini haykırdı tüm gücüyle, 

Lacivert kanının son damlasını, imzanın tam yarısında tükürdü,

Asla yazamayacaktı tekrar, bir çöp olacaktı...

Yaşamı bitmişti belki, tamamlamamıştı yazıyı

Ama yıllardır onun yalnızlığını paylaşan hayat arkadaşının, 

En karanlıklarda son kibritinin de sönüşünü,

Yaşama dair ne varsa vazgeçişini,

İsyanların EN isyanında kendini darağacına sürüşünü anlatan bir mektubu yazan KALEM olmayacaktı...

Mürekkebi bitmişti...

İmza yarım kalmıştı...', 'Elle tutulamayanları çizmişti hep bir yerlere, Karışık duygu salatalarının, hazmı zor zeytin yağı olmuştu çoğu zaman, Yorucu gündüz rüzgarla...', ARRAY['Türk Edebiyatı','Şiir','Vahan İsaoğlu']::text[], 8.5, '{"poet":"Vahan İsaoğlu","poet_slug":"vahan-i-saoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/yarim-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler', 'guzel-sozler-nazli-guller-ho6ct', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tek duymak istediğim güzel sözler 

Kandırılmak istiyorum aşk sözcükleriyle 

Mevsim hep bahar olsun 

Mor leylaklar açsın 

Pembe sümbüllerin kokusu yayılsın 

Ve tatlı vaatlerin fısıltısı kulaklarımda 

Yüzünde cömert bir gülümseme 

Yüreğim kanatlansın', 'Tek duymak istediğim güzel sözler  Kandırılmak istiyorum aşk sözcükleriyle  Mevsim hep bahar olsun  Mor leylaklar açsın  Pembe sümbüllerin k...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Güller']::text[], 8.5, '{"poet":"Nazlı Güller","poet_slug":"nazli-guller","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guzel-sozler-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Kayıp An', 'bekle-kayip-an-kemal-sakan-3gzep', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim de seferlerim tutmuş

İzleyeceğim ufuklarda atan kalbimi

Çalacağım eski yorgun bir kapıyı,

O anıtsız kadın, karşımda asırlık suskunluğuyla 

Yumuşacık gülümseyecek, konuşmadan

Gireceğim o vakit  ağrılarla kapanan 

Ve ilk kez umutla açılan kapıdan. 

.Beni yeniden doğuracak gibi, gözlerinde

Müşfik  güneşler gibi bakacak

O hep bekleyen yorgun kusursuz teslimiyetime.

Çekilmiş acılar avuçlarından parmaklarına doğru akacak 

Yüzümü uzatıp ortak olacağım yağmur ve toprak

Aç mıyım diye sormuyor

Eğilip alnını seriyor açlığımın üzerine unutuyorum

Var olmakla yok olmak arasındaki çıldırtan farkı', 'Benim de seferlerim tutmuş İzleyeceğim ufuklarda atan kalbimi Çalacağım eski yorgun bir kapıyı, O anıtsız kadın, karşımda asırlık suskunluğu...', ARRAY['Türk Edebiyatı','Şiir','Kemal Sakan']::text[], 8.5, '{"poet":"Kemal Sakan","poet_slug":"kemal-sakan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bekle-kayip-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine sevdalı...', 'oylesine-sevdali-serhat-kulu-zwpti', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tahrip gücü yüksek bir bomba yüreğim,

Mayınlanmış tarla,

Yeryüzünde katır sırtında bir kaçakçı.

Yüreği öyle sevdalı...

Oy sancılarına durduğum acı

Kolum kanadım kırık,

Haritalar delik deşik önümde

Yollarına düşmüşüm  her vakit,

Çıkınımda sevda yüreğim avucumda...', 'Tahrip gücü yüksek bir bomba yüreğim, Mayınlanmış tarla, Yeryüzünde katır sırtında bir kaçakçı. Yüreği öyle sevdalı... Oy sancılarına durduğ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kulu']::text[], 8.5, '{"poet":"Serhat Kulu","poet_slug":"serhat-kulu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oylesine-sevdali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görüş Günü', 'gorus-gunu-mehmet-faruk-turkoglu-968m9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat:

bir garip zindan.

kiralık.

ben içerde mahpus,

sen dışarda.

uzak:

özgürlük,

senin kadar.

gelme sen,

bana yeter,

yağmuru göndersen,

görüş gününe.', 'Hayat: bir garip zindan. kiralık. ben içerde mahpus, sen dışarda. uzak: özgürlük, senin kadar. gelme sen, bana yeter, yağmuru göndersen, gör...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Türkoğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Türkoğlu","poet_slug":"mehmet-faruk-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gorus-gunu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş', 'donus-mehmet-faruk-turkoglu-mu1zf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bekle beni.

birgün,

sana geleceğim.

belki tutunup bir martının kanadına,

yada ılık bir yağmur damlasına,

belkide:

düşen bir sarı yaprakla,

sonbaharda.

sana geleceğim.

son nefesimi avuçlarında vereceğim.', 'Bekle beni. birgün, sana geleceğim. belki tutunup bir martının kanadına, yada ılık bir yağmur damlasına, belkide: düşen bir sarı yaprakla, s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Türkoğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Türkoğlu","poet_slug":"mehmet-faruk-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/donus-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinayet', 'cinayet-mehmet-faruk-turkoglu-fxrzm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birini vurdular.

ben gördüm.

ömrünün en aydınlık sokaklarında,

gün ortasında.

birini vurdular.

bir  gül bahçesiydi sanki,

göğsünde açan.

güller içinde yatıyor şimdi.

boylu boyunca

heryanı:

kırmızı.

birini vurdular.

ben gördüm.', 'Birini vurdular. ben gördüm. ömrünün en aydınlık sokaklarında, gün ortasında. birini vurdular. bir  gül bahçesiydi sanki, göğsünde açan. gül...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Türkoğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Türkoğlu","poet_slug":"mehmet-faruk-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cinayet-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-damla-guven-63x92', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman sonbahar gelse bitanem,

Içimde martılar uçuşur yazdan kalma.

Bilirsin severim sonbaharı,

Bilirsin, hem de çok, senin yüzünden…

Her sonbahar senin yağmurlarınla ıslanır yüreğim; 

Ne zaman bir yaprak solup düşse dalından,

Benim de içimden birşeyler kopup gider.

Ne zaman rüzgar esse,

Bende fırtınalar kopar

Ve ne zaman akşam çökse bu şehire,

Tutamadığın ellerim üşür…

Ne zaman bir sokak kedisi görsem,

Sarılasım gelir onun yalnızlığına,

Tıpkı bir zamanlar sarıldığın gibi bana! 

Işte bu yüzden ne zaman sonbahar gelse,

Benim içim ısınır…

Ne zaman seni özlesem sonbaharla gelirsin; 

Bazen kaldırım taşlarında bir gölge,

Bazen küçük bir kızın üşüyen küçük elleri,

Bazen minik bir serçe,

Bazen de bir yağmur damlası.

Ne zaman sonbahar gelse bitanem,

Seni arar durur gözlerim…', 'Ne zaman sonbahar gelse bitanem, Içimde martılar uçuşur yazdan kalma. Bilirsin severim sonbaharı, Bilirsin, hem de çok, senin yüzünden… Her ...', ARRAY['Türk Edebiyatı','Şiir','Damla Güven']::text[], 8.5, '{"poet":"Damla Güven","poet_slug":"damla-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sonbahar-131-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kağıt gemi...', 'kagit-gemi-vahan-i-saoglu-fbxs8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçükken bir kağıt gemi yapmıştım minicik parmaklarımla,

Büyük amcaların yürüdüğü uzun bir sahilde salmıştım denize.

Bilmeden dünyadaki kirli havayı, tertemiz nefesimle yelken almıştı uzaklara,

Kim bilir sağ kalmış mıdır acımasız fırtınalarda,

Tertemiz bir yüreğin yükü ağır gelmiş midir boğuşurken dalgalarla,

Acaba beklesem, yolunu gözlesem...

Yanaşır mı tekrar gönlümün limanına...

Çocukluğumdan kalan bir avuç hatırayla...', 'Küçükken bir kağıt gemi yapmıştım minicik parmaklarımla, Büyük amcaların yürüdüğü uzun bir sahilde salmıştım denize. Bilmeden dünyadaki kirl...', ARRAY['Türk Edebiyatı','Şiir','Vahan İsaoğlu']::text[], 8.5, '{"poet":"Vahan İsaoğlu","poet_slug":"vahan-i-saoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kagit-gemi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncirli', 'i-ncirli-bilal-i-lhami-koksal-d28t6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yok işte cebimde beş kuruş para

Gribim; 

Sesim tok ve burnuımda akmakta

Yürümek mecburiyetten kirli sulara basa basa

Bir çocuk geldi yanıma 

‘Abi selpak lazım mı? ’

Yok güzelim gerek yok

Aslında gerek var; gerek var da

Yetersizim 

Yeteneksizim alışveriş yapmaya

Hazır morlimde bozukken bir şarkı patlatmanın tam sırası

Yağmur yağmur,soğuk ıslak Bakırköy İncirli arası

Okula da son iki üç yüz metre şunun şurası

Nerden aklıma geldiyse –anla işte-

Yaşarın ikinci kasetinin sekizinci parçası

Cebimdeki para bir kırmızı güle ancak yetti

Gül; 

O kadar değerli ve aşk gülün yanağında gizli

Ama ne yapalım gribim işte

Sesim tok

Ve burnumda akmakta

Param hayallerimle aynı yerde bitti.', 'Yok işte cebimde beş kuruş para Gribim;  Sesim tok ve burnuımda akmakta Yürümek mecburiyetten kirli sulara basa basa Bir çocuk geldi yanıma ...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/incirli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Önce', 'senden-once-hasan-ekrem-iftbu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senden önce,

Dinmesi imkânsız fırtınalar vardı,

Çakmak çakmak gözbebeklerimde.

Güneşin yanışıydı, kıpkızıl can çekişen,

Bir çığlık, saralı bir nöbet hiç bitmeyen,

Bir çocuğun doğuşu ruhumun derinliklerinde..

Senden önce,

Durulması sonsuzluğa uzayan geceler,

Ve o geceler boyu yağmurlar yağardı.

Kapkara çamurda iğrenç diz boyu bataklar,

Ve o bataklarda bir çiçek doğmaya çırpınırdı.

Bomboş sokaklarda, sigara izmaritlerinde..

Senden önce,

İhtişamı yaşanırdı, sefillik ve berduşluğun,

Kapkara duygular nazire yapardı ölümlere,

Ruhların inlemesiydi sessizlik, haykırışlarıydı.

Gözlerden nefret ibadetiydi, veremli bir boşluğun,

Işık seliydi korkulan,yarasa kentlerinde..

Senden önce,

Yalandı her şey, karanlık bir hiçti yaşamak,

Cehennemdi o gözler, yanmaktı inanmak.

Şimdi sen geldin, bir pınardır mutluluğum,

Taşar aşkın doruklarından, dinmez susuzluğum,

Bir ömür sürer gözlerinde aşkınla sarhoşluğum…', 'Senden önce, Dinmesi imkânsız fırtınalar vardı, Çakmak çakmak gözbebeklerimde. Güneşin yanışıydı, kıpkızıl can çekişen, Bir çığlık, saralı b...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/senden-once-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git kendi yoluna..', 'git-kendi-yoluna-tarik-teke-jt6pq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbini göm yanlızlıklara

O zaman tüm acıların son bulacak nasıl olsa

Anıların rahat bırakmayacak olsada

Aldırma sen onlara.

Bırak bütün acılar kalsın ona

Mutlulukları sıyırıp git kendi yoluna

Ve yeterki şimdi dimdik dur sen ayakta

Yenilmeyesin acılarına ve anılarına..', 'Kalbini göm yanlızlıklara O zaman tüm acıların son bulacak nasıl olsa Anıların rahat bırakmayacak olsada Aldırma sen onlara. Bırak bütün acı...', ARRAY['Türk Edebiyatı','Şiir','Tarık Teke']::text[], 8.5, '{"poet":"Tarık Teke","poet_slug":"tarik-teke","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/git-kendi-yoluna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Doğası', 'askin-dogasi-alper-kuruk-krh5x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tek başına sürülmez zevki bu saltanatın

Bir ayağı erkekse diğer ayağı kadın.

Sırrına ererlerse bu ilâhî san''atın

Yaratılan esere kâinatta aşk derler.

Niye kadın sevgide bir ayrıcalık arar? 

Sevişmekte ayrılık-gayrılık yok birlik var,

Yapılan naz boşuna,yapsan ne işe yarar? 

Birleşince bedenler ruhlar Cennet''e gider...', 'Tek başına sürülmez zevki bu saltanatın Bir ayağı erkekse diğer ayağı kadın. Sırrına ererlerse bu ilâhî san''atın Yaratılan esere kâinatta aş...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askin-dogasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşuyordun Yağmurlarla', 'kosuyordun-yagmurlarla-dilek-hokkaomeroglu-x62ye', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.Geçmeyen zamanlarda

Anılsa da dünler,

Susuyor yüreğim.

Gelmeyecek bil o mutlu günler.

Sustuğumu kuşlar duymasın

Kanat kırarlar.

Bırak! 

Kırılsın kanatlarım...

Ne farkeder? 

Işıkların göllere düştüğü an

Bak saçlarımada düştü

Bir tutam ışık.

Kırıldın mı? sende

Sana kırılan ben gibi.

Sanma ki ebediyete taşınır aşklar.

Şimdilerde yağmur yağıyor anılara.

Yürümek gerek.

Dinmez sevda yağmurları,

Hep aynı yola sevdalar düşer.

Pembe pembe hayaller gülümser

''''Aynı kadeh aynı mey''''

İçtiğim sarhoş etmez.

Gönül yaram dinmez.

Işıkların göllere

Bir de senli yüreğime..

Ay doğmadan doğdum,

Bir de sen doğdun geceme

Kalbi kırık yıldızların,

Dünyasında.

Koşuyordun Yağmurlarla...', '.Geçmeyen zamanlarda Anılsa da dünler, Susuyor yüreğim. Gelmeyecek bil o mutlu günler. Sustuğumu kuşlar duymasın Kanat kırarlar. Bırak!  Kır...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kosuyordun-yagmurlarla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Baharda Yağan Kar Demektir', 'ayrilik-baharda-yagan-kar-demektir-turan-tuncer-in7cv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AYRILIK BAHARDA YAĞAN KAR DEMEKTİR

Acının adresi,

Ayrılığın künyesinde yazılıdır da

Şerbetini içmeyenler bilemez.

Acının bir haritası olsa

Sınırları,

İnsanın 

Sevdiklerini kaybettiği zamanla çizilidir.

Yüreğin

Delirir, 

Acı; dağlara zirve olur da

Atışı üzengisiz, tımarsız 

Yılkı atı,

Dizgin vuramazsın.

Ve kasılması, gidişlere,

Özlem, denizler olur da

Seni taşıyan rüzgârlar, yırtar

Bütün yelkenlerini.

Aşamazsın,

Ayrılıklar, acılara teslim

Kalbin, istilasına uğrar da

Her koyulan, yeni den denlerde

Kimyası bozulur,

Bakışının, duruşunun.

Ayrılık,

Baharda yağan kar demektir.

09 Şubat  2006/İst

Alkadraz_Kuşcusu', 'AYRILIK BAHARDA YAĞAN KAR DEMEKTİR Acının adresi, Ayrılığın künyesinde yazılıdır da Şerbetini içmeyenler bilemez. Acının bir haritası olsa S...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ayrilik-baharda-yagan-kar-demektir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-rabia-baris-7a0i3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yârim ilk mevsimde gelir diyordum,

Umut bağlamışım boşa sevdiğim.

Gelir de halimi görür diyordum,

Ömrümü döndürdün kışa sevdiğim.

Geceler muamma, gündüzüm densiz.

Saatim, saniyem geçmiyor sensiz.

Yüreğim seninle, ruhum bedensiz.

Hesap sormuyorum, hâşâ sevdiğim.

Kara gözlerine takılıp kaldım.

Bin türlü cefâyı sineme aldım.

Sır olan sevdamı rüzgara saldım.

Sevgimi vakfettim düşe sevdiğim.

Seninle uyanıp seninle yattım,

Tarifi imkansız acılar tattım.

Çırpına çırpına derine battım.

Benzedim kanatsız kuşa sevdiğim.

Her akşam içimi dondurdu ayaz.

Yoksun diye bir gün giymedim beyaz.

Kalk da seher vakti ahvalimi yaz.

Aşkımı sardırdın başa sevdiğim.

Neden kurtarmadın gönlümü dardan? 

Felek ayrı tuttu anadan, yardan.

Yolunu beklerken uzak diyardan,

Oturdum bir kara taşa sevdiğim.

İlkbahar, yaz derken dolandı yıllar.

Kurudu fideler, kırıldı dallar.

Sana gelecektim tutuldu yollar.

Katık olamadım aşa sevdiğim.', 'Yârim ilk mevsimde gelir diyordum, Umut bağlamışım boşa sevdiğim. Gelir de halimi görür diyordum, Ömrümü döndürdün kışa sevdiğim. Geceler mu...', ARRAY['Türk Edebiyatı','Şiir','Rabia Barış']::text[], 8.5, '{"poet":"Rabia Barış","poet_slug":"rabia-baris","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevdigim-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paçavralar İçinde', 'pacavralar-i-cinde-sezgin-cetin-fb4uz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nereden çıktı bilinmez

ölümü düşledim bu gece 

paçavraya dönmüş bir otobüs 

bense hemen yanıbaşında ama...

Dokunmak istedim biran 

İrkilerek çektim elimi daha uzatmadan

kolbolduğunu gördüm felaket siluetinde

Anam geldi aklıma babam geldi 

haber vermesinler ağabeyime

elem indirmesinler yüreklerine 

Ben onları özledim 

bakarken gözlerine 

belki kucaklamadım seviyorum diye

içimden sevdim...

Kendime hayattan silercesine 

Annemin kıpkırmızı yüzünde 

çağlayan soğukluğu, dayanamam bile

Babam ağlayamaz bilirim 

kendine saklar derdini

sigaraya başlar belki de...

Ağabeyim can dostum 

yüzün çevirir belki 

soğuk bedenimden 

Beni göz kapaklarına çizer silmezdi de...

yalnız içer belki 

deniz kıyısında,türkülerle,birasını

beni anardı herhalde 

Kayan her yıldızda 

üşürdü de belli mi olur 

Nereden çıktı bilinmez

ölümü düşledim bu gece 

paçavraya dönmüş bir otobüs 

bedenim hemen içinde ama...

ruhum bedenimi seyretmekte', 'Nereden çıktı bilinmez ölümü düşledim bu gece  paçavraya dönmüş bir otobüs  bense hemen yanıbaşında ama... Dokunmak istedim biran  İrkilerek...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Çetin']::text[], 8.5, '{"poet":"Sezgin Çetin","poet_slug":"sezgin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/pacavralar-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıktı Kaşını', 'yikti-kasini-rabia-baris-04yib', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hatır sordum ela gözlü yarime,

Akıttı gözünden kanlı yaşını.

Nedir bu celalin, bu nazın dedim,

Çevirdi başını, yıktı kaşını.

Yıllar var ki onu aramamışım,

Aşkının farkına varamamışım,

Gönül sarayında duramamışım,

Çevirdi başını, yıktı kaşını.

Dedim seni candan, özge severim.

Aşkı aziz bilir boyun eğerim.

Seven unutur mu, bu mu değerim? 

Çevirdi başını, yıktı kaşını.

Aşk köprüsü kurdum geçtiği yola,

Affetmek yakışır seven bir kula,

Gönül limanında verdim de mola,

Çevirdi başını, yıktı kaşını.

Söyledim bu sevgi yâda sorulmaz,

Sevda yarasına hançer vurulmaz,

Haktan gel olmadan dosta varılmaz,

Çevirdi başını, yıktı kaşını.

Sanmış ki yadını unutacağım,

Gönül albümünden çıkaracağım,

Olur mu böyle şey be yavrucağım! 

Çevirdi başını, yıktı kaşını...', 'Hatır sordum ela gözlü yarime, Akıttı gözünden kanlı yaşını. Nedir bu celalin, bu nazın dedim, Çevirdi başını, yıktı kaşını. Yıllar var ki o...', ARRAY['Türk Edebiyatı','Şiir','Rabia Barış']::text[], 8.5, '{"poet":"Rabia Barış","poet_slug":"rabia-baris","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yikti-kasini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincik', 'gelincik-i-brahim-sarihan-yf5zn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklım almıyor bir türlü

Seni nasıl sevdiğimi bir bilsen gelincik

İçimdeki ateşini söndürebilsen

Gözlerinin içine dalıp,

Hiç çıkmamak istiyor gözlerim

Delicesine sevmek

Ve umutsuzca bağlanmak aşkına

Kalbim senin için çarparken

Sen yoksun gelincik

Sanki bir yaz yağmuru misali,

Gelmiştin yüreğime sessizce

Sonra, buharlaşıp birden kayboldun sanki

Ama dudaklarımda bıraktığın ıslaklık

Daha dün gibi be gelincik

Ah, bebek yüzlü

Yüreğimdeki sevdanla baş başa kaldım,

Yapayalnızım şimdi

Çok özlüyorum gelincik

Zıpkın bir hançer gibi saplanıyor hasretin

Varlığınla yaşıyorum

Ve papatya falı misali,

Seviyor, sevmiyor sendromundayım

Şöyle bir düşünüyorum da gelincik

An bile aklında olabilmek..

Benim için büyük mutluluk abidesi

Fakat yokluğun, ya yokluğun gelincik..

Kapkaranlık bir sokakta yürüyorum

Ortalık ıssız, alabildiğine sakin

Sessizlik, ayak seslerimle bozuluyor

Haykırmak istiyorum,

Kalbimin nasıl çılgınca çarptığını

Ve sonra, sensiz üşüme sarıyor bedenimi

İçime ılık, ılık işleyen sevginle

Tek tesellim de, o zaten gelincik

Özgür olmak istemiyor benliğim

Sadece, senin olmak ebediyen

Aşk parmaklıkları arkasında

Hıçkıra, hıçkıra ağlıyorum

Gözlerimden akan, her bir damlada sen

Sevgi çiçekleri açtı gönlümde

Can suyu sen, fakat sen yoksun

Sunamıyorum sevgimle yoluna

Duam Allah''ıma; 

Bir tek benim olasın

Benim olasın güzel gelincik

(Hakkâri, 04 Temmuz 2003)', 'Aklım almıyor bir türlü Seni nasıl sevdiğimi bir bilsen gelincik İçimdeki ateşini söndürebilsen Gözlerinin içine dalıp, Hiç çıkmamak istiyor...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıhan']::text[], 8.5, '{"poet":"İbrahim Sarıhan","poet_slug":"i-brahim-sarihan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/gelincik-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Yolcu', 'garip-yolcu-rabia-baris-xg0qd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gittiğin yollarda gam kervanına,

Ben de katılayım dur garip yolcu.

Sevgiden, neşeden haber ver bana,

Yüküme inciler vur garip yolcu.

Sermayem tükendi gelir mi geri? 

Dolaşır dururum ileri, geri.

Bir kez yola çıkar ömür seferi,

Varsa sualini sor garip yolcu.

Bir minval üzere, çile ördüğüm,

Esrarlı bir alem sanki kördüğüm.

Hayal mi, gerçek mi nedir gördüğüm? 

Önüme dikilen sur garip yolcu.

Ömür takviminde yıllarım yorgun,

Gözlerim bakar kör, yüreğim sürgün.

Ölüm seni, beni götürür bir gün,

O an belli değil, sır garip yolcu.

Yıldızlar topladım mavi göllerden,

Buket hazırladım pembe güllerden,

Encamını sordum esen yellerden,

Sonunda ölüm var, var garip yolcu.

Bir gün alıcı kuş başımda döner,

Gözümde fer kalmaz, ışığım söner,

Can bedenden gider, acılar diner.

Getir kefenimi sar garip yolcu.', 'Gittiğin yollarda gam kervanına, Ben de katılayım dur garip yolcu. Sevgiden, neşeden haber ver bana, Yüküme inciler vur garip yolcu. Sermaye...', ARRAY['Türk Edebiyatı','Şiir','Rabia Barış']::text[], 8.5, '{"poet":"Rabia Barış","poet_slug":"rabia-baris","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/garip-yolcu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöküş Ve Borsa', 'cokus-ve-borsa-mehmet-akif-tiryaki-le7tc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çöküş başladı,

Tavan arasında,

Kar yağışı bitti,

İstanbul''unda Ankara''sında

Devir eşek arılarının

Düzen devri bitti,

Düzensizliğin düzeni devreye girdi

Virüsler çoğaldı

Bilgisayarlar kaput,

Savaşlar başladı,

En güzel iş plastik tabut

Mehti geldi,

Yaşasın ankebut.', 'Çöküş başladı, Tavan arasında, Kar yağışı bitti, İstanbul''unda Ankara''sında Devir eşek arılarının Düzen devri bitti, Düzensizliğin düzeni de...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Tiryaki']::text[], 8.5, '{"poet":"Mehmet Akif Tiryaki","poet_slug":"mehmet-akif-tiryaki","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cokus-ve-borsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Ölüm Zamanı', 'simdi-olum-zamani-seyfettin-bilal-ozluk-umlv1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalbimin sarayının temelleri yıkıldı

Ayakta kalan bir kaç direk yıkıntısı

Yıkıntıdan kurtarılan kardır sanırdım

Yıkıntıda moloz olmak daha kötüyse

Şimdi ölüm zamanı.

Tenha köşeye atın çöpten farkım ne

Nice aylar büyüttüğün eserin son hali işte

Yıkılmaz zannedenler çöküntüde arar bulursa beni

Kime neyse gidişlerim 

Şimdi ölüm zamanı.

Sende kalan umutlarım senin olsun

Gidiyorum aşkım aşkın ölümsüz olduğu yere

Yıkıntılar döküntüye dönüşmeden

Kaçmak bana göre değildi ama

Şimdi ölüm zamanı.', 'Kalbimin sarayının temelleri yıkıldı Ayakta kalan bir kaç direk yıkıntısı Yıkıntıdan kurtarılan kardır sanırdım Yıkıntıda moloz olmak daha k...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/simdi-olum-zamani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapiste Doğan Cevdet', 'hapiste-dogan-cevdet-doner-ozeke-ligg7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kadın tanıdım hapis damında 

Karagözlü Cevdet vardı yanında 

Alçaklık var imiş kocasının kanında 

Benim yurdum kadınları çok garip 

Gaziantep imiş kadının yurdu 

Beyim kocam diye haykırıp durdu 

Her gelen gardiyana eşini sordu 

Benim yurdum insanları çok garip 

Beş aylık hamile düşmüş hapise 

Kocasıyla birlikte girmiş mapusa 

Bu kadın bilmemki kimlere küse 

Benim yurdum  insanları cok garip 

İşlemediği suçu almış kadın  üstüne 

Kocasını eliyle garibim verdi dostuna 

Kocası bürünmüş domuz postuna 

Benim yurdum insanları cok garip 

Kadın cahil kadın garip ümitsiz 

Yavrusuyla yatacak hala limitsiz 

Dilin kemiği yok söyler kilitsiz 

Benim yurdum insanları cok garip 

Kadın muhabbeti aldı yatıyor 

Hain koca kuma almış çaka satıyor 

Kadın hala kocasına tapıyor 

Benim yurdum insanları cok garip 

Gebe geldi bir gün oğlan doğurdu 

Üfleyerek yedi hergün yoğurdu 

Karagözlü Cevdet hapiste doğdu 

Benim yurdum insanları cok garip 

           DÖNER ÖZEKE 

              09.02.2006', 'Bir kadın tanıdım hapis damında  Karagözlü Cevdet vardı yanında  Alçaklık var imiş kocasının kanında  Benim yurdum kadınları çok garip  Gazi...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hapiste-dogan-cevdet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çilekeş Kadın', 'cilekes-kadin-doner-ozeke-tpc7e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kadın gidiyor günah yurduna 

Hele bir sorun bunun derdi ne 

Asla rastlamadım böyle merdine 

Kadınların çileleri neden bitmiyor 

Gergef gibi çileleri hergün dokuyor

Bir tane yavrusu Yüksek okuyor 

Kadının yüzünde çile acı kokuyor 

Kadınların çileleri neden bitmiyor 

Pavyonlarda masalarda geziyor 

Her masada sarhoşları süzüyor 

Bu kadının derdi beni üzüyor 

Kadınların çileleri neden bitmiyor 

Gelmeseydin mahalleme yurduma 

Bendeki dertmi ki ona sordumda 

Şapkamı bir anlık yere koydumda 

Kadınların çileleri neden bitmiyor 

           DÖNER TEMÜR 

              09.02.2006

                ANKARA', 'Bir kadın gidiyor günah yurduna  Hele bir sorun bunun derdi ne  Asla rastlamadım böyle merdine  Kadınların çileleri neden bitmiyor  Gergef g...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cilekes-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet', 'cennet-kamil-at-4oi3z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boşuna dövünüp durma

O sebepten beni vurma

Benim anlayışım var,

Varsa ailenden,

Varsa sülalenden

Cennete giden

Anıt yapıp 

Mezarı başına 

Levha diksinler...', 'Boşuna dövünüp durma O sebepten beni vurma Benim anlayışım var, Varsa ailenden, Varsa sülalenden Cennete giden Anıt yapıp  Mezarı başına  Le...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cennet-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Altında', 'yagmur-altinda-dilek-hokkaomeroglu-fpjf6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçmeyen zamanlarda 

Anılsa da dünler 

Susuyor yüreğim.. 

Gelmeyecek bil o mutlu günler 

Sustuğumu kuşlar duymasın 

Kanat kırarlar... 

Bırak! 

Kırılsınlar 

Ne farkeder? 

Harelerin suya düştüğünde 

Saçlarıma da dokundu 

Bir tutam ışığın... 

Kırıldın mı yoksa? 

Sana kırılan ben gibi.. 

Sanma ki ebediyete taşınır aşklar 

Yağmur yağıyor anılara 

Şimdilerde 

Islanan duygular... 

Dinmez sevda yağmurları 

düşer aynı yolun yolcularına 

Pembe hayaller gülümser 

Kadeh aynı, mey aynı olsa da 

İçtiğim sarhoş etmez 

Gönül yaram dinmez... 

Işıkların göllere 

Bir de senli yüreğime 

Ay doğmadan doğdum 

Sonrasında sen 

Kalbi kırık yıldızların 

Dünyasındaki ben.. 

Koşuyordun Yağmurlarla', 'Geçmeyen zamanlarda  Anılsa da dünler  Susuyor yüreğim..  Gelmeyecek bil o mutlu günler  Sustuğumu kuşlar duymasın  Kanat kırarlar...  Bırak...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yagmur-altinda-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Ay Işığı', 'neredesin-ay-isigi-osman-basbekleyen-6e4b9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay her zamanki gibi parlıyor

Etrafa ışık saçıyor

Aşk ışıklarını dünya’ya yayıyor

Beyaz kalpleri boyuyor

Ay bazen ağlatıyor

Gülen gözler kızarıyor

Gözlerin kızarması demek

Aşkın alevlenmesi demektir

Ben ayda kendimi arıyorum 

Bulamıyorum ve kendime kızıyorum

Yine sevdiğim yanımda yok

Dayanamayıp tekrar ağlıyorum

Ay bazen umuttur

Korkan gözlerde gülümseme

Ve soğuk bir havada 

Sıcak bir nefestir

Ben yine aya bakıyorum

Bu sefer ay beni geçmişe götürüyor

Gördüklerim beni üzüyor,kırıyor ve sarsıyor

Ama yine sevmekten vazgeçemiyorum

Şimdi kolum kırık kanadım kırık

Kalbim…kalbim zaten param parça

Umutsuzum ve çaresizim

Kara bulutlar ayı kapatıyor

Neredesin ay ışığı', 'Ay her zamanki gibi parlıyor Etrafa ışık saçıyor Aşk ışıklarını dünya’ya yayıyor Beyaz kalpleri boyuyor Ay bazen ağlatıyor Gülen gözler kıza...', ARRAY['Türk Edebiyatı','Şiir','Osman Başbekleyen']::text[], 8.5, '{"poet":"Osman Başbekleyen","poet_slug":"osman-basbekleyen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/neredesin-ay-isigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanmaz Adam', 'utanmaz-adam-emrah-karakoc-spnz1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hak - adalet - hukuk arama onda

İnsanlıktan çıkmış utanmaz adam

En candan dostunu kor yarı yolda

Bilmedim ne b.. muş utanmaz adam

Dinledşkçe sanırsın ki çok adil

Lafazandır herif laf yapar o dil

O cani sözüzünün eri hiç değil

Ah almaktan kokmuş utanmaz adam

Sorsanız ''sosyalist'' hemde emekçi

Halbuki gerçekte tam kan emici

Sözde aydın kişi ve ilerici

Pratikte yokmuş utanmaz adam

Sosyalistlik dersin ''Önce ben'' diyor

Parayı sorarsan ''Bence din'' diyor

Ot versende b... versende hep yiyor

Sorarsanız tomuş utanmaz adam

Karakoç'' um der ki; tanıdım seni

Yiye yiye şişirmişin enseni

Seni rezil, seni çakır dikeni

Müstahakın çokmuş utanmaz adam', 'Hak - adalet - hukuk arama onda İnsanlıktan çıkmış utanmaz adam En candan dostunu kor yarı yolda Bilmedim ne b.. muş utanmaz adam Dinledşkçe...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/utanmaz-adam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanmaz Adam / 2', 'utanmaz-adam-2-emrah-karakoc-4rje3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki yüzlüdür o sakın kanmayın

Fitne - fesat saçar utanmaz adam

Her sözü yalandır hiç inanmayın

Bala biber katar utanmaz adam

Sıkışınca çatar dine, islama''a

Kin güder camiye, kızar imama

Yurtseverim der ya, sakın inanma

Fırsat bulsa satar utanmaz adam

Emekçi geçinir emeği çalar

Çıkar için etek öper, el yalar

Her türlü konuya atlayıp dalar

Hak diyene çatar utanmaz adam

Yüze güler, kuyu kazar ardından

Bir kez geçen pişman olur yanından

Uzak durun dostlar uzak siz ondan

Akrep gibi sokar utanmaz adam

Karakoç''um der ki; utan be utan

Hizmet bekler bizden bu aziz vatan

Bedava geçinip yan gelip yatan

Emeğe hor bakar utanmaz adam.', 'İki yüzlüdür o sakın kanmayın Fitne - fesat saçar utanmaz adam Her sözü yalandır hiç inanmayın Bala biber katar utanmaz adam Sıkışınca çatar...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/utanmaz-adam-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayamadım ki', 'yasayamadim-ki-birsen-ates-plm8f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşk’ı hiç yaşamadım

ellerindeydi aşk

dokunabildim sadece

tutamadım ki

oysa

gözlerimi açmıştım sende

uyanmak istemediğim düşler gibi

kurtaramadın beni

uzatamadın elini

uyandım senli rüyalardan

hiç benimle bir ömür

kalamadın ki

büyüyemedim ki hiç

yıkamadım

saran duvarlarımı

artık çok uzaktasın

istesem de gelemem

ben

aşk’ı hiç yaşayamadım ki

 09.02.06', 'aşk’ı hiç yaşamadım ellerindeydi aşk dokunabildim sadece tutamadım ki oysa gözlerimi açmıştım sende uyanmak istemediğim düşler gibi kurtaram...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasayamadim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük.17 [Kader çalıyor...]', 'dortluk-17-kader-caliyor-ercan-akbay-4qwxd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzel olan ne varsa,kader bir bir çalıyor,

   Gönül sevip sardıkça,kader bir bir çözüyor,

   Ne aşkta bir vefa var,ne de seven gülüyor,

   Gönül sevip sardıkça,kader bir bir çözüyor...

                                                 12.AĞUSTOS.1999', 'Güzel olan ne varsa,kader bir bir çalıyor,    Gönül sevip sardıkça,kader bir bir çözüyor,    Ne aşkta bir vefa var,ne de seven gülüyor,    G...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dortluk-17-kader-caliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayağa dikildik', 'ayaga-dikildik-mikdat-bal-03a5i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayağa dikildik, koşuyoruz biz

Ayaklar altında çıyan ezilsin

Ya Allah, Bismillah çoşuyoruz biz

Milleti çalanla, soyan ezilsin

Saldırgan hayvanlar çözük ya bağlı

Ensesi kalınlar kuyruğu yağlı

Bütün eşkıyalar, şehirli dağlı

Mazluma gaddarca kıyan ezilsin

Kimliği Türk olup bölük bölükler

Hesabı sorulur tüm kötülükler

Milletin kanını emen sülükler

Komşuları açken doyan ezilsin

Her yerde kilise açıp kurduran

İşi tehlikeye kadar vardıran

Yalan beyanlarla günü kurtaran

Milleti enayi sayan ezilsin

Mikdati der millet sorar hesabı

Ozaman ortaya çıkar nisabı

Bir de İmralıda insan kasabı

Asmayıp da hapse koyan ezilsin', 'Ayağa dikildik, koşuyoruz biz Ayaklar altında çıyan ezilsin Ya Allah, Bismillah çoşuyoruz biz Milleti çalanla, soyan ezilsin Saldırgan hayva...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayaga-dikildik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil/sen -I', 'bil-sen-i-ugur-deniz-ulkegul-90gwr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öldürdüğüm zamanlar içinde 

Yaşatabildiğim kadar varsın sen 

Sanma ki sustuğum kadar çoksun 

İçimde sakladığım çığlık kadarsın sen.. 

Bilsen… 

Beklemenin sancısı düştü göz ucumdan 

Bir uçurumdan bıraktım günaha kendimi 

Kimsesiz vakitlerde ölümcül kavgaların 

Kan revan direncine yasladım sensizliğimi.. 

Ay’ı tam yüreğinden vurdular 

Sürgüne yolladılar göğün mavisini 

Toprağın rahminde öfkeyi döllediler 

Susturdular doğmamış çocuk seslerini… 

Yazgısı kör kuytularda kurşuna dizilen 

Yosma bir kadın telaşında kıvrandı şehir 

Uzak iklimlerin yorgunuydu sevişmeler 

Efkarın dumanından düş/tü, sızlandı şiir… 

Karaya vuran dalgaların hüznünde insan 

Çakıl taşlarında sakladığı amansız sabır 

Gel-Git sorgularında sus, yüzünde isyan 

Kumlarda sessiz bir hoşçakalın izleri kalır... 

Gitmek, seni özlemekten ibaret zaman 

Teninde yorulduğum akşam zulası 

Küfürbaz öfkemde sessizce kanayan 

Yüreğime sapladığın kurşun yarası…. 

Çarmıha gerilen çocuk düşleri 

Sen kokan ellerimde saklı cinayet 

Gölgemi ısırırken köpek leşleri 

İçimde son nefesini veren masumiyet.. 

Söyletme beni 

Sana öykündüğüm her akşamda 

Sabaha çıkmaz sancılar taşırım ben 

Kaç kez vururum kendimi bakışlarında 

Kaç kez yeniden doğarım bu aşkın küllerinden… 

Bil/sen……', 'Öldürdüğüm zamanlar içinde  Yaşatabildiğim kadar varsın sen  Sanma ki sustuğum kadar çoksun  İçimde sakladığım çığlık kadarsın sen..  Bilsen...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bil-sen-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglarken gülmeyi annemden ögrendim', 'aglarken-gulmeyi-annemden-ogrendim-serpil-maglicoglu-og14y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öfkemi yutmayi, 

kalbim kirilirken susmayi ögrendigimde,

saclari lüle lüle, yesil gözlü  kücücük bir kizdim. 

Hüzününde, hirsinda hep gülen,

hatta yaslar süzülürken icini acitarak gözlerinden,

isil isil gülümseyen. 

Beklentileri yerine getirmeye ugrasirken

kendinden vaz gecen, kendini yalanlayan,

hatta zaman zaman yok sayabilen.

Sessizligin ardinda cigliklara bogulan,

bastirilmis duygulariyla, itilmis kimligiyle 

Umutsuz bir savas veren. 

Üzerine giydirilmis pembe, cicili bicili giysiler,

ne de hos sun sen böyle, ne güzel, ne carpici.

Gözler hep üzerinde, eller hayran edana.

Sesin deki sihir akan sulari andirir adeta.

Tatli dilinle, yumus yumus halinle

hayranlarin dizilir yoluna.

Oysa icindeki memleketlerde savas ilan edilmis,

yakan yakilanlar var, ölüm dizboyu,

sen gizlen gülüslerinde gizlenebildigin kadar. 

Korkular da kurtaramaz bazen. 

bastirilmis duygular öcülesip girdimi düslere,

susturulmus isyanlar bas bas bagirmak istediginde.

Öfkemin ugruna yakmak gelir icimden.

gercekte benim olmayan giysilerimi. 

Silip  eski BENI, yeniden Kendim olarak SERPILmek

Bu gün hala aglarken gülerim oysa ben.

Aglarken  gülmeyi ben annemden ögrendim

Aglarken güldügümü hep kizimdan gizledim...', 'Öfkemi yutmayi,  kalbim kirilirken susmayi ögrendigimde, saclari lüle lüle, yesil gözlü  kücücük bir kizdim.  Hüzününde, hirsinda hep gülen,...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aglarken-gulmeyi-annemden-ogrendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Beni Kınama! !', 'gel-beni-kinama-zulfikar-yapar-kaleli-z9u0d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Bu ne salim yürek sevdiğim hatun

Her niyeti halis, yüreği bütün

Vesvese üzümün, kuruntu dutun

Aldırma dildeki saçmaya balam

Gel beni kınama kurbanın olam.

Doğduğumdan beri yayayım gülüm

Yalan söylüyorsam kurusun dilim

Dostu kırar isem koy alsın ölüm

Sevgiler az gelir uçmaya balam

Gel beni kınama kurbanın olam.

Bazıları beni bal ehli görür 

Bende ki ben beni zûl ehli görür 

Halden anlamazlar hâl ehli görür 

Özenmişim ışık saçmaya balam

Gel beni kınama kurbanın olam.

Ne bilir burunsuz leylak kokusu 

O kokunun ipektendir dokusu 

Ağrılı belinde katran yakısı 

Elvermez sırrımı açmaya balam

Gel beni kınama kurbanın olam.

Resmimi yollasam işe yaramaz

Hayalimi salsam düşe yaramaz

Kaleliyi dersen haşâ yaramaz

Bacaklar tutmuyor kaçmaya balam

Gel beni kınama kurbanın olam.', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Bu ne salim yürek sevdiğim hatun Her niyeti halis, yüreği bütün Vesvese üzümün, kuruntu d...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gel-beni-kinama-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayçiçeğim', 'aycicegim-elif-gulay-r8bsh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ayçiçeğim; 

dön yüzünü bana doğru,

güneşin benim.

bak nasıl yaktım kalbimi sevdanın kızıllığında,

nasıl serdim ışığımı yollarına,

ben karanlıklardayım; 

ben soğuk,

tüm sıcaklığımla,

döndüm sana yüzümü

kara bulutları arkamda bırakarak.

boş çıkarma sözümü.

bir saniye ver ömründen

ömrümün hepsi senin

hadi ayçiçeğim

güneşin benim..', 'ayçiçeğim;  dön yüzünü bana doğru, güneşin benim. bak nasıl yaktım kalbimi sevdanın kızıllığında, nasıl serdim ışığımı yollarına, ben karanl...', ARRAY['Türk Edebiyatı','Şiir','Elif Gülay']::text[], 8.5, '{"poet":"Elif Gülay","poet_slug":"elif-gulay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aycicegim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirdimsa seni', 'kirdimsa-seni-ulya-erkman-zn11e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kirdimsa seni kirildim 

Bende

Inanmaliydim beni boylesine

Sevene

Suphe etmemeliydim maksadi 

Ne diye

Hurmet etmeliydim ender

Sevgisine

Affedecekmisin bilmem

beni

Seni kiran su hasin 

Sevgilini

Sevgin affettirir dusuncesiz 

Sozlerimi

Kabul edermisin yine 

Bilmem sevgimi', 'Kirdimsa seni kirildim  Bende Inanmaliydim beni boylesine Sevene Suphe etmemeliydim maksadi  Ne diye Hurmet etmeliydim ender Sevgisine Affed...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirdimsa-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Çiçeği-2', 'ates-cicegi-2-adnan-durmaz-v7uhq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kar’Üseyin araladı kapıyı

Hatçe pusmuş oturur peykesine topak evin

Kekikli bir yel kokusu

Tüm sesler ölü

Ne gök mavi - ne toprak yeşil - ne taş sert

Ölene dek saldıracak 

             tutsak bir yaban hayvanı

İçinde kaynayan tiksinti - kin

Kangal dikenleri gibi

Batmaya hazır her yanı

Kar’Üseyin’in kurbanı

Pusmuş peykesine topak evin

Yeryüzünün en kimsesiz insanı

Bir çığlık / göğü  yırtan bir yıldırım

Akkor bir şimşek çakması

Eşkıya başının ruhuna çarptı

Yeryüzünün en kimsesiz kurbanı

İsyan kustu avcısına

Kanların altına aksın da yivrim yivrim

Asıl ayaklarından ölüm koksun ortalıkta

Yağlı kurşunlara gel

Hatçe dedi

Öyle bağırıp çağırma- şükür eyle Allah’ına

Seni bana yazdı da -şu dağların aslanına

Ne söylese dinlemedi

Çığlık çığlığa inledi

Yeşil çimenlerce güzeldi

Sarı papatyaların dengi

Mor menekşelerin ahengi

Ve pembe güllerdi Hatçe

Ağlayan güller gibiydi

İki gözü iki çeşme

Eey insanlar / hatırdan gönülden bilenler

Diz çöküp namaz kılanlar / adamdan sayılanlar

İleri gelenler- usul duranlar

Katiller Hatçe’yi aldı da kaçtı

Çiğillipınar’a konan Suvermezliler

Dayılar- böleler- emmiler - utlular-utsuzlar

Sizin de namusunuz değil miyim ben

      	bire gidi namussuzlar

Dağ- taş inledi sesinden

Konuştu Kar’ Üseyin

Ben de bu dağların hükümdarıyım

Ve dahi cümle köylerin

Bolvadin’den- Kareser’e

Çifteler’den Sivrihisar’a nam yürütmüşüm

Hiç bağırma boşuna yakma tatlı canını

Gücüme kimseler karşı gelemez

Sen benimsin bundan gayrı

Var teslim ol bana

Gül ol da açıl bağrımda

Dünyalar vereyim sana..

Kar’Üseyin adın kara yerlerden gelsin

Yeğniciğinden yan da teneşirlere gel

Tutul da nuzullara çot olsun elin yüzün

Dumansız bacalardan karanlık gecelerden

       	kurtulma kara köpek

Kar’Üseyin çıkıp gitti dışarı

Yüzü öfkeden seyriyerek

Vardı kardeşi Keloğlan’ın yanına

Kel Mustafa düşünceli

Ulen Üseyin

Elin yumruk kadar öğsüzünü ne edecektin

Daylak gibi karın vardı

Üseynin yüzü öfke karası

Çıktı bayıra yukarı

Ve Hatçe’nin bağırtısı geldi peşinden

Sonra bir daha vardı

Bir daha çıktı

Hatçe ha bire bağırdı

Yengeler girdi / oturaklı kadınlar

Gerisin geri çıktılar

Ne bir tas su ne bir çarpım yufka

       	içip yemedi

Ağladı- ilendi- sövdü

Gelenler kâr etmedi

Anasının yarasını sardılar

Olur bacım dediler

Bir sizden ürüsüm değil

Elden ne gelir

Gözlerinin yaşını sil

Garip yolcular geçer yürüyen ölüler gibi

Kimisi ağaç ayaklı kiminin başı sargılı

     	kolu kesilmiş

Ölüm haberleri - ağıt çığlıkları

Günlük işler arasında

Erkekler kırılmış savaşlarda

Trablusgarp’ten Balkan’a

        	ne emmi kalmış- ne dayı

Ne bir devlet var ortada

Ne Allah rızasına hak güdecek bir başkası

Aziziye Konağından Geri dönmüş

elleri boş - yayan- yapıldak

Ağlar Filik Abıla yüreği bir hoş

         kolları kopuk yaşın yaşın

Bu ne hak- bu ne hukuk

Kaldı harman yerinde samanı- çeci

Olancası bir avuççuk

Eller devşirip getirdi

Uzun yollardan gelirim dedi

Trablusgarp çöllerinden

Tobruk’tan- Derne’den

Susuzluktan ölenler

Kıvıl kıvıl bit içinden

Açlık - kum - ve bit harbinden

Irak yollardan gelirim

Tel örgülerden

Kurşun ve hançer kavlinden

Ölümü uçurum Balkanlar

Ölümü kara Karadağ

Tirana’dan - Üsküp’ten

Sofya’dan - ve Varna’dan

İnsan yüzü görmemiş acılardan

Bilinmedik açlıklardan

Bir kolum kopuk

Bacağım ağaç

Susuz- aç

Kaybedilmiş

       ama büyük kavgalardan...

Girdi topakeve yol yordam bilen kadınlar

Kalaylı sinilerde yayla balı- kaymak- katmer

Elden ne gelir dediler

Gayrı sen mundar oldun

Bir bu eve yakışırsın

Yok gidecek başka bir yol

Gelir sıkar ümüğünü dediler

Var Kar’Üseyin’e teslim ol

Alsın kudurmuş kart köpek

Sıksın ümüğümü / canımı alsın

Ölüp kurtulayım varsın 

Ona karı olacağıma

Gövdemi topraklar sarsın

Bir kadın yaklaşmak istedi

Sakın daklaşmayın bana

Kara Köpeğin itleri

Şu al kutnu sayanızdan utanın

   	dulukbastılı feslerinizden

Yılan dillerinize kanacak mıyım

Çıkın başımdan defolun

Kele kız delirmiş dediler

Vaa bacım hadi gidelim

İvedi çıkıp gittiler

Artlarından fıydırılan sininin

   	sesini işittiler

Zaman akmaz gibi yavaş

Uzaklardan çan sesleri

Ve yaylanın yeli kekik esintili

Bir kabaltı çınladı

Sonra bir hardal çanı

Arkasından zil

Yanal koyunları aklına düştü

Gümüş burum kuzuları

Sonra anasının yüzü

Acı içinde sefil / saçılmış al kanları

Açıldı kilim kapı 

bin bir rengiyle balkıyarak

Girdi Kar’Üseyin

Kara kaput yüzü yülenmiş

Kancık bir ifade gözlerinde

Gayrı barışalım pohur çiçeğim

Öyle bağırma konuşak

İnsan konuşa konuşa

Aşık koklaşa koklaşa

Bağırdı- taştı- tutuştu

Ak boynunda gök damarlar belirdi

Kanadı yarılmış dudakları

          	kar dişleri göründü

Kes ulan dedi Kar’Üseyin

Yolumu yokuşa vurma

Sarpa sardırma gönlümü

Kafa tasımı attırma

Çıktı gitti ormanlara yukarı

Üçüncü gün gelmedi

Gün uzadı- devrilmedi

Gecenin bir vaktinde

        	usulca girdi kapıdan

Beni zora koşma Filiğin Hatçe

Bundan böyle avradımsın

Namusun benim boynuma

Her şey gönüllüce olsun

Hatçe kıvrılmış sedire

Uyanıp belinledi

      	it oturumuna geldi

Bar bar  bağırdı

        yok mu bir can kurtaran

Çıktı gitti Kar’Üseyin

Dördüncü gün ikindi sularında

Kar’Üseyin gene geldi

          	dili ballar tadında

Geri gitti umudunun boynu kırık 

Dört gündür lokma yememiş

Aç ölmeğe karar vermiş

Bir telaş sarmış herkesi

Yalvarmış yenge kadınlar

Bir tas su bile içmemiş

Beşinci gün düşündü

       	topakevden çıkarken

Ulan tut diyor felek / yatır altına

          	bas tokadı / tut elini kolunu

          	kalmamış zaten takatı / bas

Baktı Hatçe arkasından

Kim alır ahını ölsen

Kim acır gebersen acıdan

Madem öyle yaşa- diren 

Yaşamayı fitil fitil getir burnundan

Kendin sor hesabını

Kar’Üseyin’den

Altıncı gün uzanıp tuttu kolundan

Tokatı yeyiverdi yüzünün ortasına

Hırsla bir tekme savurdu Hatçe’ye

       	kurban yuvarlandı yere

Fırlayıp kalktı öfkeyle saldırdı bağırarak

Beynine yankılandı yüzüne değen tokat

Düştü yeniden / darpadan kalktı

Çıkıp gitti Kar’Üseyin 

Hatçe hüngür hüngür ağladı...

Oysa böyle olsun istemiyordu

Tadı kekreleşti sevmenin dedi

Ertesi gün öğle sonu Keloğlan

Girdi topakevin kapısından

Hatçe’ye nasihat verdi

Ben de istemezdim dedi

Gümbür gümbür davulunan

Köylüye aş döke döke

Al duvaklar içinde

murad almak hakkın idi

Öyle iken böyle olmuş neyleyim

Kar’Üseyin ağamdır  ya

Aklı ermez yol yordama

Olan olmuş / çaresi yok / neyleyek

O dedi Hatçe ağladı

Sonra da çekilip gitti

Vardı Kar’Üseyin’e

Herhalde yumşuyor dedi

Elbet alışır sonunda

Sen de biraz sabır eyle

Kayıl olacak bahtına

Sekizinci gün gelmedi

Kar’Üseyin

Gene gitti kel Mustafa

nasihat etti

İnar-ı fener olmuş acıdan ve açlıktan

Gerçi yemeğe başlamış

Kadınlar öyle söyledi

Ertesi gün Kar’Üseyin geldi oturdu

Önce saydı döktü yiğitliğini

Sonra ağalığını anlattı

Üç bin davarım var dedi

Üç bin adamım

Gel etme gayri Hatçe

Sarplara vurma beni

Sen iste dağları yıkayım

Sen dile köyleri yakayım

Dilerim yalanların boğar seni

Dört vatan hayını

ne zaman üç bin oldu

Zenginlik ağalık sana mı kaldı

Dilerim, toprak bile kabullenmez gövdeni

Hatçe böyle söyledi

Kar’Üseyin çıkıp gitti

Bindi atına dörtnala vurdu

Yitti ay altında

Bir Göğüs Yaylasına vardı

Bir Kartal Pınar’ına

Doma’dan harmanladı

Oluklu’dan dolaştı

Belce’de sabaha ulaştı

Orda uyudu bir vakit

Yeniden bindi atına

Tekne Çukuru’na vardı

Keçi Gölcüğü’nde at suladı

Dolaştı Emirdağ’ın tüm yaylalarını

On sekiz yaylaya nal vurdu geçti

--

devam edecek

adnan durmaz', 'Kar’Üseyin araladı kapıyı Hatçe pusmuş oturur peykesine topak evin Kekikli bir yel kokusu Tüm sesler ölü Ne gök mavi - ne toprak yeşil - ne ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":276,"source_url":"https://www.antoloji.com/ates-cicegi-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman Olacaksın', 'pisman-olacaksin-birsen-ates-pqmwt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hangi yüreğin kapısını çalsan

hangi sevda da soluklansan

içinde büyüyen hücreler gibi

dolaşacağım damarlarında

her yüzde beni görecek

her konuşmada beni yaşayacaksın

geleceğim aklına

yarım olacaksın yarım

pişman olacaksın 

yaşayamadığın için beni

salınarak gelen güneşindim

ayazlarında ısıtan

karanlık çıkmaz sokaklarında 

sıcacık bir ışıktım

artık çok geç

göç etti sevgim bencilliğinde

ne zaman aklına gelsem

içini hüzün saracak

üşüyeceksin zemheride

geçmişe döndüğünde

pişman olacaksın

yaşayamadığın için aşk’ı

10.02.06', 'hangi yüreğin kapısını çalsan hangi sevda da soluklansan içinde büyüyen hücreler gibi dolaşacağım damarlarında her yüzde beni görecek her ko...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/pisman-olacaksin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uşağum (Yerel 2.)', 'usagum-yerel-2-mikdat-bal-28b5o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bekledum bekledum haber gelmedi 

Senun cevaplarun geçtur uşağum 

Sen gideli beri baban gülmedi 

Babayı ağlatmak suçtur uşağum 

Eyiyuk çok şükür bizden sorarsen 

Yaramazluk yoktur haber ararsen 

Buranun haline kafa yorarsen 

Bil ki komşularum açtur uşağum 

Fakiri kayıran koruyan yoktur 

Bizum da halumuz ne aç ne toktur 

Para desen tomar amcanda çoktur 

Onun da tek derdi hacdur uşağum 

Odun aldurtmadi dondurdi bizi 

Yanina uğraduk göderdi bizi 

Bu gün yarun deyup kandurdi bizi 

Bu bize ettuği kaçtur uşağum 

Otlarumuz bitti inek geberdi 

Bu da bizum içun acı haberdi 

Amcana giderduk geri teperdi 

Bunlari hazmetmek güçtur uşağum 

Buralar boyledur haberi yazdum 

Kusuruma bakma seni da üzdum 

Gel da bizi kurtar canumdan bezdum 

Sana bu yazduğum üçtur uşağum 

Dediler avrupa alacak bizi 

Ne gezer hınzırlar çalacak bizi 

Kendileri gibi bulacak bizi 

İlk gönderdukleri haçtur uşağum 

Misyonerler geldi tuzak kurdiler 

Gençlerun önine dolar sürdiler 

İçerden bizleri boyle vurdiler 

Bunlarun alduği öçtur uşağum 

Uşaklar okula artuk gitmeyur 

Ne soylersan söyle fayda etmeyur 

Hayale dalarler hayal bitmeyur 

Umutlar batıya göçtur uşağum 

Mikdatiyum gel uşağum buraya 

Ancak sen olursun merhem yaraya 

Hainleri sen düzersun sıraya 

Benum oğlum atak koçtur uşağum', 'Bekledum bekledum haber gelmedi  Senun cevaplarun geçtur uşağum  Sen gideli beri baban gülmedi  Babayı ağlatmak suçtur uşağum  Eyiyuk çok şü...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/usagum-yerel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erik ağacı', 'erik-agaci-sinan-oktay-9g8l4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Selamı var bahçedeki erik ağacının.

                                               sana

neredenmi biliyorum.

Uzun zamandır kupkuru dallarla

bahcede duruyordu,

Bu sabah dalları bembeyaz çicekler açmış.', 'Selamı var bahçedeki erik ağacının.                                                sana neredenmi biliyorum. Uzun zamandır kupkuru dallarla ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Oktay']::text[], 8.5, '{"poet":"Sinan Oktay","poet_slug":"sinan-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/erik-agaci-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Bakış Açısı-', 'bakis-acisi-elif-gulay-2dewb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''bir ömür geçse unutmam seni'' demiştin severken

ve benim ömrüm bitti sen giderken

ilk önce kızdım sana

gücendim

ağladım yalanların ardından

konduramasam da suçladım seni

nerden bileyim aklıma gelmedi

kelebeğin ömrü de, ömür değil miydi?', '''bir ömür geçse unutmam seni'' demiştin severken ve benim ömrüm bitti sen giderken ilk önce kızdım sana gücendim ağladım yalanların ardından ...', ARRAY['Türk Edebiyatı','Şiir','Elif Gülay']::text[], 8.5, '{"poet":"Elif Gülay","poet_slug":"elif-gulay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bakis-acisi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam''a mektup', 'babam-a-mektup-ayse-manav-88kj6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canım Babacığım,

Yattığın yerde rahat uyu babacığım,

Gözlerimi kapattığımda, aklıma ilk gelen görüntün son halin oluyor nedense, keşke seni o halde görmeseydim, aklıma gülen yüzün gelseydi ben böyle kahrolmasaydım. Seni o durumda görmek beni şoka sokmuştu ve aradan geçen 1,5 yılın ardından düşüncelerimde sıkıştı kaldı o görüntün...  Meğer seni ne çok seviyormuşum... Seni çok özlüyorum, benim canım babacığım...

Sen, daima benim en büyük desteğim olmuştun, çok nadir bile olsa bazen kızmış, bazen bağırmıştın, aradan beş dakika geçmeden gelip gönlümü almıştın.. Bana  “Sakın hata yapma, yapacaksan da küçük olsun, büyük hatalar hayatını etkiler” derdin. Ben ise, aldığım kararlarda defalarca düşünür, hatasız davranmaya çalışırdım ama insanız işte hatasız kul olmuyor.. Hiçbir zaman yüzünü kara çıkarmadım...

Tüm hayatım boyunca, seni bir kez dinlemedim, bunu kabul ediyorum, o yüzden bütün hayatım etkilenmiş ve hala etkileri devam etmekte. Yine de senin kızındım, affederdin, biliyordum.. 

Sen kimseye kırgın kalmazsın... Kalamazdın. Senin yapında yoktu bu.. Seni nasıl özlediğimi  görüyorsun babacığım, bunu hissediyorsun...

Çaresiz kaldığım zamanlarda, evde tek başıma kıvranırken yada bunaldığım zamanlarda “ ahhh baba neredesin? ” dediğim zamanlar aniden beni ziyarete gelir, sanki çaresizliğimi hisseder bana koşardın. Oturup sohbetler ederdik seninle, bir baba kız gibi değil, iki arkadaş gibi, yine de seni üzmemek adına sıkıntılarımdan söz etmez, yanında neşeli davranmaya özen gösterirdim.. Ama sen anlardın baba. Bana destek olabilmek için “Ne olursa olsun arkandayım, hiçbir şeyden korkma “ der, moralimi yükseltmeye çalışırdın..  Sen daima en büyük desteğim olmuştun, o zamanlar da bile olabilecekleri çok iyi görebiliyor, benden uzakta bile olsan en az zararla kurtulabilmem için, benden habersiz uğraş veriyor, beni bırakmıyordun.. Beklediğin o an geldiğinde ise her şeye hazırlıklı oluyordun.. Ben senin canın, kanındım..  Seni çok özlüyorum canım babam... Seni çok özlüyorum... 

Yattığın yerde rahat uyu..

Sana layık bir evlat olmaya çalıştım ve gururla söylüyorum ki; bütün huylarımı, özelliklerimi senden almışım. Tıpkı senin gibi hassas, duygulu biri olup çıkmışım. Şimdi sen yoksun yanımda, içim kan ağlıyor, bir şeyleri değiştirmek istiyorum, yapamıyorum.. Söylediğin sözler öylesine yerleşmiş ki içime, istesem de onlardan dışarı çıkamıyorum.. Seni çok özlüyorum, seni çok özlüyorum derken bile kalbimin acısını hissediyorum baba ve seni çok seviyorum..

Yattığın yerde rahat uyu babacığım...

Seni seviyorum.', 'Canım Babacığım, Yattığın yerde rahat uyu babacığım, Gözlerimi kapattığımda, aklıma ilk gelen görüntün son halin oluyor nedense, keşke seni ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Manav']::text[], 8.5, '{"poet":"Ayşe Manav","poet_slug":"ayse-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/babam-a-mektup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurun büyüsü', 'yagmurun-buyusu-ayse-manav-h88a9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şehrin üzerine çöken gri bulutların ardından, içime kasvet çörekleniyor, “keşke yağsa ve içimdeki kasvet  dağılsa” diye düşünüyorum bir an.. Yastığıma başımı koyduğumda yağmur çiselemeye başlıyor. Kendimi, yağmurun büyülü sesine 

odaklıyorum. Her düşen damlada ahenkli notalarını fısıldıyor kulaklarıma, ruhumla bütünleşip dans ediyor sanki damlalar.. Gözlerimi kapatıp, kendimi yağmur damlalarının  götüreceği uzak diyarlara bırakıyorum. Her düşen damlada, yüreğime umut dolup taşıyor, sırılsıklam ıslanıyorum. Çevredeki bütün çirkinlikleri yıkayıp, yağmurdan sonra açan güneş gibi temizliyor dünyamızı. Bulut bulut göz yaşlarım geçiyor düşüncelerimden, çisil çisil yağan yağmurda denizin rengini taşıyor damlalarında, yosun kokusu taşıyor, toprak kokusu sarıyor dört duvar  odamı..  ve ben tatlı bir sarhoşlukla  kayboluyorum gecenin alaca karanlığında..

Ruhum belki de bugüne kadar hiç olmadığı kadar hür ve bağımsız, sanki hafif bir esintide  bedenimden  ayrılıp savrulacak bilmediği diyarlara..  Karanlığın içinden faili meçhul bir el uzanıyor aniden,  “ gel “ diyor, “bulutların içinde gezinelim, huzuru bulacaksın, ‘hadi gel.”  Sesi takip ediyorum hiç düşünmeden, yüzüyorum sanki maviliklerde..  Bazen bir damla olup yağıyorum evrene, bazen de sevmeyi unutmuş yüreklere düşen sevgi tohumu, barış meşalesini yakan alev oluyorum, ocağında sevgi aşı pişen, dumanı sevgi, kardeşlik tüten buram buram  duman oluyorum. Denizlerde yolunu şaşıran balıkçılara yunus, istiridyeden çıkan inci oluyorum. Çaresizlere derman, fakirlere aş oluyorum.. Adım sevgi, kardeşlik, huzur, mutluluk olup, tüm evrene yağıyorum.

Bu huzur ve mutluluk içinde gözlerimi açıyorum, kırlangıçlar çoktan uyanmış sabah şarkılarını söylüyor, limon çiçekleri en güzel  kokularını dağıtıyor etraflarına, birazdan güneşin kızıllığı düşecek dağların ardından denizlerimize.. Islanan sokaklar pırıl pırıl yanacak güneşin aydınlığında, Gökyüzü her zamanki gibi masmavi gülümseyip, ışıldayacak dünyamıza.. 

ve ben yine maviliğime döneceğim içimde hiç tükenmeyen umutlarımla..



Umut mavi kanatları açmış baş ucuma

Gökyüzü mavi bir derya ışıl ışıl yanıyor

Yüzüme aksediyor güzelliği baharın

Yüreğim de çiçekler filiz atıyor

Gün, gecenin koynuna eş

Yıldızlar, aya tutsak sarhoş

Mavi ufkun büyüsü ne hoş

Yakamozlar arasında gel huzura koş', 'Şehrin üzerine çöken gri bulutların ardından, içime kasvet çörekleniyor, “keşke yağsa ve içimdeki kasvet  dağılsa” diye düşünüyorum bir an.....', ARRAY['Türk Edebiyatı','Şiir','Ayşe Manav']::text[], 8.5, '{"poet":"Ayşe Manav","poet_slug":"ayse-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yagmurun-buyusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Nefesteki Mutluluk', 'i-lk-nefesteki-mutluluk-melih-coskun-osqxq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soluksuz kaldıktan sonra

İlk nefesteki mutluluğu düşün,

Yağmurdan sonra açacak güneşi,

Demli bir sabah çayının

Boğazına bıraktığı sıcaklığı

Bil ki hiçbir dağ sonsuzluğa uzanmaz 

Bütün karanlık yollar çıkar mutlaka bir gün aydınlığa

Mideni kemiren açlıktan sonra 

İlk lokmadaki mutluluğu düşün,

Uzun bir deniz yolculuğundan sonra 

Ufukta ilk ışıklarını memleketinin

Ve o memleketin güleç yüzlü güzel çocuklarını

Alevlenen gözlerini ve çatlamış ellerini

Yani seni sen yapan bütün heyecanlarını

Düşün bugün de ölmediğini 

Bugün de inadına yaşadığını...

13 Haziran 2004

Foça', 'Soluksuz kaldıktan sonra İlk nefesteki mutluluğu düşün, Yağmurdan sonra açacak güneşi, Demli bir sabah çayının Boğazına bıraktığı sıcaklığı ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ilk-nefesteki-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuda yolculuk', 'umuda-yolculuk-ayse-manav-mdjij', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dalgın bir akşamın kolları dolanmış beynimin en ince kıvrımına kadar.

Gözlerimde geçmişin irinli gözyaşları, sigaramın dumanından çıkan kıvrımlarla konuşur, onlardan  şekiller çıkarırım.

Bazen; bir çiçek olur yedi renginde bağrında taşıyan.

Bazen, gülümseyen bir bebek yüzü belirir, melekler gibi en safından.

Bazen kolları dolanmış, aşk kokulu çiftler..

Bazen, hayaller kurarım mavilerin en güzelinden, mutlu, umutlu bir yuvayı düşlerim, bahçesince mavi-pembe ortancaları açan. Sabahın güneşle kucaklaştığı ilk saatlerinde, kuşların serenatlarıyla eşlik ettiği, ağaçların dallarından sevgiyle süzülerek üzerimize ışık ışık doğan bir günü düşlerim. Mutlu, huzur dolu, sevgi dolu, sıcacık kollarını düşlerim. Hayallerde yaşatırım seni kim olduğu bilmeden, kimsin, nesin, nasıl birisin bilmeden.

Bazen çivit badanalı bir ev düşlerim, ocağında sevgi aşı pişen, bacasında buram buram huzur tüten, yasemin kokuları içinde çevreye sevgi katan.

Bazen yağmur olurum, sevgi damlalarımı bırakırım toprağa, sevgi tohumlarını çatlatır, boy boy filiz attırırım. Kıraç topraklara sel olur akarım, sevgiyle güzelliği birbirine katar çoğaltırım. Bir ırmak oldur taştır yüreklerden, ay ışığında hoş bir yakamoz ışıltısı yürekleri dinlendiririm.  Büyür, bir göl olurum, büyür deniz olurum, sevgi deryasını paylaştıkça kocaman bir okyanus olurum en mavisinden..... ve ben o okyanusta küçücük bir Sal olurum, bir sağa, bir sola savrulan. Sevgi deryasında yüzen yaralı bir tekne olurum en eskisinden...

Bazen, coşkun akan bir ırmak olur, kabına sığmayan küçük bir çocuk edasıyla gülücükler saçarım. Umudun koyu mavisi sarar beni, yerimde duramaz olur, sabırsızca umudun yolunu gözlerim...

Bilirim ki; bir gün yolu mutlaka buralara düşecek..

Umut etmek...  Beklemek....

Doğacak masmavi bir günü düşleyip, geldiğinde son nefesim gibi ona sımsıkı sarılmak..

Düşlediğim Turkuaz sabahı görmek...

Göreceğim seni mavi gün...

Turkuaz sabahlara ulaşacağım..

Bekliyorum seni, bu kez her şey yerli yerinde. Tek eksik olan sen kaldın. Sana bu son sözüm..

Sarılacağım sana  son nefesim gibi..', 'Dalgın bir akşamın kolları dolanmış beynimin en ince kıvrımına kadar. Gözlerimde geçmişin irinli gözyaşları, sigaramın dumanından çıkan kıvr...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Manav']::text[], 8.5, '{"poet":"Ayşe Manav","poet_slug":"ayse-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/umuda-yolculuk-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esintiler', 'esintiler-ayse-manav-03dhd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar esti saçlarımın arasından,

Rüzgarın dokunuşu tene, bir ürperti ruhumda.

Deli fırtınaların saç diplerimde oynaşması

Gözlerimde kısık bir bakış ihtirasın acımasızlığına

Dudaklarımda diş izleri kanayan..

Bir rüzgar esti ve geçti saçlarımın arasından,

Buz kesti bedenim, kırağıya düştü tüm hücrelerim.

Alaca karanlığımda mavilerimi dağlıyorum.

Bak yıldızlar yine göz kırpıyor dünyaya,

Güneş yine ısıtıyor buz kesen ruhları,

Yine ay en güzel haliyle sevgililere ışıldıyor gülümseyerek

………ve en hoş yakamozlar ruhları okşuyor.

İnsanın kendini kandırması bu,

Bir hayale sığınıp zamanın akmasını sağlaması belki,

Yüreği sevgi dolup taşarken ruhuna kan damlaması bu,

Yalnızlığa sitem, tek başınalığa bir isyan bu.

Görüyor musunuz? 

Bir rüzgar esti geçti saçlarımın arasından,

Küllerimi savuruyor ruhuna kan damlayanlara,

Küllerim dökülüyor toz mavi zifiri karanlığa,

Umudu taşıyor, sevginin gücünü, yarınların mavi şafağını,

Karanlığın ışığını bırakıyor avuçlarına,

Bak bir rüzgar esiyor saçlarının arasından.', 'Bir rüzgar esti saçlarımın arasından, Rüzgarın dokunuşu tene, bir ürperti ruhumda. Deli fırtınaların saç diplerimde oynaşması Gözlerimde kıs...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Manav']::text[], 8.5, '{"poet":"Ayşe Manav","poet_slug":"ayse-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/esintiler-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmazsa Aşk', 'olmazsa-ask-muammer-erturan-lfnmr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne varsa aşka karşı 

karşı koymak zorundasın 

yaşamın özü 

çünkü aşk... 

Kevgire dönmüş olsa da yüreğin 

derin yüzülmüş de olsa 

iğneli fıçılar içinde 

büyüyüp dursa da çığ gibi 

yalnızlığın

savunmak zorundasın o özü... 

Çünkü 

yaşamaktasın hâlâ... 

Ne varsa aşka karşı 

karşı koymak zorundasın 

olamazsın çünkü 

olmazsa aşk... 

(''98)', 'Ne varsa aşka karşı  karşı koymak zorundasın  yaşamın özü  çünkü aşk...  Kevgire dönmüş olsa da yüreğin  derin yüzülmüş de olsa  iğneli fıçı...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olmazsa-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorsan eğer', 'seviyorsan-eger-ayse-manav-87hx2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni seviyorsan eğer,

Benim, seni sevdiğim kadar sevmelisin,

Seni düşündüğüm kadar düşünmelisin beni

Beklenmedik anlarda aramalısın mesela

Uyku tutmadığı, sabahlar olmadığı gecelerde

Beni seviyorsan eğer,

Yanımda olmalısın daima, 

Sonuna kadar güvenmelisin bana

Yüreğinin kilidini açmalısın sonuna kadar

Zincirlerini dipsiz kuyulara atmalısın.

Beni seviyorsan eğer,

Yarınlara benim gözlerimle bakmalısın,

İsyanları bir çuvala basıp denizlere atmalısın,

Çocuksu gülüşünle karşılamalısın acıları,

Her şeye ılımlı yaklaşmalısın.

Beni seviyorsan eğer,

Sevgini sonuna kadar göstermelisin,

Benim vereceğim sevgimi, sen de bana vermelisin,

Sonsuzluğa uzanan yolda yanımda olmalısın

En koyu mavilere benimle dalmalısın.

Beni seviyorsan eğer....

Benim yaktığım gibi yakmalısın,

Sana, baktığım gibi bakmalısın bana,

Yüreğimi can evinden yakmalısın.

Aşkım uğruna her şeyi göze almalısın.

Beni seviyorsan eğer.....', 'Beni seviyorsan eğer, Benim, seni sevdiğim kadar sevmelisin, Seni düşündüğüm kadar düşünmelisin beni Beklenmedik anlarda aramalısın mesela U...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Manav']::text[], 8.5, '{"poet":"Ayşe Manav","poet_slug":"ayse-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seviyorsan-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın Yok Gibi', 'yarin-yok-gibi-ahmet-zekai-yildiz-8gm06', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün göreceğimiz filan yok anlaşılan.

Gün, frontal duruşlu ceset gözlerinde saklanır.

Gece ise pegasus kanatlarında başına buyruk, belalı.

Kar taneleri kara mı yağıyor Hatice! .

Yoksa gözüm mü kararıyor? 

Düştüm, düşeceğim tut beni..

Ayrılık pusu kurmuş ekmeğimize

Soframızda yine acı soğan var.

Hey hat! . Bu kaçıncı dram,  kaçıncı sahne..

Ölüm gülümsüyor yüzüme,çocuklardan ne haber

"Hani alnım ak demiştin"

 Yüzün neden kara baba? demesin çocuklar.

Büyüdüklerinde sen anlat onlara..

Sen anlat, kömür karası gözlerinle..

Ak ekmeği.. Alın terini...

Dün çok uzaklarda şimdi.

Yarın ise yok gibi..

Bu öyle bir çizgi ki, kıldan ince…

Gelirsem tamam ama gelemezsem bağışla.

 Sen ağlama, Hatice..

Sen sakın ağlama..', 'Gün göreceğimiz filan yok anlaşılan. Gün, frontal duruşlu ceset gözlerinde saklanır. Gece ise pegasus kanatlarında başına buyruk, belalı. Ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Zekai Yıldız']::text[], 8.5, '{"poet":"Ahmet Zekai Yıldız","poet_slug":"ahmet-zekai-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yarin-yok-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana taş kalpli diyorlar', 'bana-tas-kalpli-diyorlar-ayse-manav-z39dc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana taş kalpli diyorsun, ama geçen zamanda nasıl katılaştığımı görüyorsun. 

Kalbimin sadece bir yanına bakıyorsun. Seni sevemediğim için beni buzdan  heykel sanıyorsun. 

Belki de haklısın, bir yanımda taş gibi, dağ gibi hala ayakta, dimdik durabilmenin verdiği gurur, diğer yanda bu gururdan eriyip giden yumuşacık bir yürek taşımak, acını acım, kederini keder, gözyaşına gözyaşı, için için seninle yada herkesle bir olan bir yürek benimki. 

Zaman ne kadar katılaştırmış olsa da pamuk gibi bir yürek benimki. 

Belki de  seni sevemediğim için böyle düşünüyorsun. 

Bir gün kalbimin kapısını kim çalacak bilmiyorum, ama bildiğim bir şey var yüreğimde gizlenen, onu görüyorum. Ona bir de isim takıyorum, mavi sevdam diyorum.

İçimdeki mavi umutlara ancak benim gibi gören gözler ulaşacak bunu çok iyi biliyorum ve işte ben o zaman kalbimi ona adıyor, onu seviyorum.

Sen geldiğinde, ılık bir meltem esintisiyle yüreğimde yerini bulacaksın. 

Kimsin, nesin, nasıl birisin hiç bilmiyorum ama gelişin, 

ışığın etrafında dönen ateş böcekleri gibi beni saracak, 

ancak bir tek sana yön bulacak. 

Bu yürek senin olacak.

Seni beklemek, her şeye rağmen bir yerlerde var olduğunu bilmek ve bir gün çıkıp geleceğin günü sabırsızca beklemek. 

Kim olduğunu bilmeden varlığından o kadar emin olmak ve günler, aylar sürse de seni beklemek yine de güzel.

 Belki hiçbir zaman gelmeyeceksin, belki de çok yakında gelip beni bulacaksın, varlığını hissettiğime göre bir yerlerde sende beni aramaktasın. 

Ben buradayım..

 Eş ruhum gel bul beni...

Sensiz ne kadar katlanmak zor olsa da bu hayatın yüküne, varlığını hissetmek güç verir yüreğime, sensiz ne kadar katlanmak zor olsa da sensizliğe, bekliyorum bir gün geleceksin diye. Ruhuma aktığın o ilk anda, kalbim senin, farkına varmasan da, o ilk bakışta ilk sözde sen de anlarsın ruhuna girdiğimde, beklediğim, özlediğim, nerelerdeydin onca zaman, yolunu gözlediğim.....

Mavi düşlerini kurduğum,  gece gündüz beklemekten yorulduğum, hayalde olsan yanımda hep soluduğum, neredesin...

Gel artık... 

Hayalimde değil yanımda olmalısın, benim için değil, sen istediğin için kalmalısın, sev diye değil, aşkı bulmalısın, benim için değil, kendin için ruhuma doğmalısın. 

Gel artık seni çok özledim..

Yine bahar geldi mavi sevdam, ağaçlar çiçek açtı da sen hala gelmedin. Gecelerimin şafağı bitti, ömrüm geçti de, sen hala gelmedin. Bir düşü kovalarken seneler akıp geçmiş, fark etmedim, saçlarıma aklar düşmüş meğer şimdi gördüm, ama sen hala gelmedin. Beklemekten yorulmuş yüreğim, geçen zamana yenildim.. Ama sen hala gelmedin.. 

Kara gecelerin bağrından çıkmalıyım artık, seheri kızıl değil, mavi sabaha uyanmalıyım artık. 

Sen gelsen de gelmesen de mavi sevdam, yarınlara umutla bakmalıyım artık. 

Seni bekledim bunca zaman, ömrümün en güzel çağında sendin içimdeki yalan. 

Bir hayale, bir düşe yenik düştü zaman, saçlarıma aklar geldi ama sen hala gelmedin mavi sevdam. 

Yılların yorgunluğu derin izler bırakmış yüzümün her santiminde, gözlerimin feri sönmüş sen gelmedikçe, uğruna bir ömür geçmiş yüreğim demlenmekte.. 

Ölümün ılık nefesi sonbaharımda beni beklemekte.. 

Artık ister gel mavi sevdam, istersen hiç gelme.. 

Seneler geçti bir hayalin peşinde, ne gelen oldu, ne de kapımı çalan, beklediğim sendin ama düşlerini yaşadığım sen,  başka sendin gözlerimde, sözlerimde bile başka senli kelimeler... 

Sendin beklediğim her zaman. 

Şimdi düşlerimin sonbaharındayım, fark etmez artık gelsen de inan... 

Öylesine yorulmuşum ki,  sevmeye bile dermanım kalmadı, 

Buz kesti yüreğim, buna da inan. 

Sevmeyen yürek zamanla nasırlaşır derlerdi,  inanmazdım... 

Öylesine nasırlaşmışım ki, kabuk kabuk yüreğim, sevenlerini görmeyen, bir inat uğruna kör olmuş gözlerim, sözlerim artık gecenin alacakaranlığı.. 

Gelme artık fark etmez inan, sevgi nehrini yüreğimden taşırıp çevreme hayat verdim, yeşerttim sevgi tohumlarını ama çöle döndüm ben, işte bana kalan... 

Nasır tutmuş bir yürek, bir damla suya, sana, hasret ben...

Neydi beni sana bağlayan, hiç anlamadım, anlayamadım, haysiyet, onur, gurur belki de bunlardı, beni böyle tek başına koyan...

Yalnızım işte, yapayalnız, 

Tek başına gidiyorum ömrümün sonuna ben....', 'Bana taş kalpli diyorsun, ama geçen zamanda nasıl katılaştığımı görüyorsun.  Kalbimin sadece bir yanına bakıyorsun. Seni sevemediğim için be...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Manav']::text[], 8.5, '{"poet":"Ayşe Manav","poet_slug":"ayse-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bana-tas-kalpli-diyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Yazasım Yok Artık', 'siir-yazasim-yok-artik-mehmet-emre-albayrak-16y2q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'eh benim yaşlı dünyam... 

geçmişim.. geleceğim.. varoluşum.. 

şimdi kanlı bak gözlerim.. 

avuçlarım yara 

düşmekten bıkmış omuzlarım..

vah benim kaybolmuş yıllarım..

vah ki ne vah bi ömür geçmicek

yaralarım kalbimde..

gidişine kan aktı ya bulutlardan..

dönüşüne kan akıtmaya hazır bu can..

ama sen yine de gelme..

her geliş bi gidişi tetikler..

gidenler yasta..

dönenler yasta..

çekilir yol diil yolum.. 

sen şimdi çok uzaklarda..

derdim.. yaram.. yarim..

peş peşe kafiyelerde gözlerin..

bakma bana.. 

şiir yazasım yok artık..', 'eh benim yaşlı dünyam...  geçmişim.. geleceğim.. varoluşum..  şimdi kanlı bak gözlerim..  avuçlarım yara  düşmekten bıkmış omuzlarım.. vah b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emre Albayrak']::text[], 8.5, '{"poet":"Mehmet Emre Albayrak","poet_slug":"mehmet-emre-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siir-yazasim-yok-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimi Yakıyor....', 'yuregimi-yakiyor-halide-selcan-karagul-pgwh4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğimi Yakıyor....

Ateşin kor olmuş yakıyor yüreğimi 

Buz gibi bakışların söndürmüyor ateşi... 

Ulaşamasın itfaiye diye 

Yüreğimin yollarına bent çektim... 

Hortumlardan fışkırmasın diye 

İtfaiyenin sularını tükettim... 

O nedenle 

Yüreğimin ateşini 

Söndürmesi mümkün değil... 

Aşkının ateşi kor olmuş yüreğimi yakıyor.... 

09.02.2006', 'Yüreğimi Yakıyor.... Ateşin kor olmuş yakıyor yüreğimi  Buz gibi bakışların söndürmüyor ateşi...  Ulaşamasın itfaiye diye  Yüreğimin yolları...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuregimi-yakiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baş başa', 'bas-basa-fatma-caglayan-5b9dw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gece yine baş başayız seninle 

Bakıştık 

saatlerce birbirimize 

Bakışların hep aynı 

her zaman aynı yerde 

Dayarsın dört duvara ayaklarını 

bakışırız geceden sabaha seninle 

Bazen yüzümü çeviririm senden 

sen asılı kalırsın 

hep aynı yerde 

hep durağan 

Bazen de üzerime çökersin kâbus gibi 

ah! tavan 

adın yavan 

kendin yavan 

ah! Tavan 

vah tavan', 'Bu gece yine baş başayız seninle  Bakıştık  saatlerce birbirimize  Bakışların hep aynı  her zaman aynı yerde  Dayarsın dört duvara ayakların...', ARRAY['Türk Edebiyatı','Şiir','Fatma Caglayan']::text[], 8.5, '{"poet":"Fatma Caglayan","poet_slug":"fatma-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bas-basa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüregimdeki çocuk', 'yuregimdeki-cocuk-halide-selcan-karagul-ruxbh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüregimde bir çocuk 

Sevinçle hüznü 

Bir arada yaşıyor 

Bir elinde umut çiçekleri 

Digerinde mutsuzluk dikenleri... 

Yüregimdeki bu çocuk aglıyor, 

Batmış eline 

Mutsuzluk dikenleri... 

Umut çiçekleri 

Gönlünü okşuyor... 

Kendisini 

Bekleyen geleceği 

Umut çiçeklerinde 

Biliyor... 

Yüregimdeki çocuk 

Ellerin de 

Umut çiçekleri, 

Gözlerinde 

Bir ümit ışıgı yanıp sönerken 

Kendisine sevgiyle uzanacak 

Bir dost eli bekliyor... 

Yüregimdeki çocuk 

Bir elinde umutsuz dikenleri 

Digerinde umut çiçekleri 

Gözlerinin içi gülüyor... 

Yüregimdeki bu çocuk 

Gelecekten umutlu 

Hayatla barışık yaşıyor... 

06.04.2005 saat: 12:00', 'Yüregimde bir çocuk  Sevinçle hüznü  Bir arada yaşıyor  Bir elinde umut çiçekleri  Digerinde mutsuzluk dikenleri...  Yüregimdeki bu çocuk ag...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yuregimdeki-cocuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rızık', 'rizik-abdulvahap-ates-5ec8m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kursağa  doldurup ta  tükettiğimiz; rızık.

Arta kalan, malımız sandığımız hamallık.', 'Kursağa  doldurup ta  tükettiğimiz; rızık. Arta kalan, malımız sandığımız hamallık....', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/rizik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden çıktın karşıma', 'nereden-ciktin-karsima-ayse-manav-k3bez', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günlerden sonra nerden çıktın karşıma

Aylardan sonra yeni mi geldim aklına

Giderken kördüğümler attın boynuma

Kapkara düşler yolladın uykularıma

Zindanlara saldın prangalarınla

Günlerden sonra nerden çıktın karşıma

Aylardan sonra yeni mi geldim aklına

Sensizliğin karanlığındaki çırpınışlarımda

Hiç mi düşmedim canına anlatsana

Gözlerimin son yağmurundaki damlalarla

Benden sende gittin anlasana

Günlerden sonra nerden çıktın karşıma

Aylardan sonra yeni mi geldim aklına

Hayatımı mahvetmemek adına, 

Yarattığın eserini görüp ağlasana

Seni sayıkladığım ayları geri yollasana

Hasretinle yandığım geceleri avutsana

Aylardan sonra neden çıktın karşıma

Zamanla derin yaralar unutulurdu hani

Şimdi sen beni UNUTSANA.', 'Günlerden sonra nerden çıktın karşıma Aylardan sonra yeni mi geldim aklına Giderken kördüğümler attın boynuma Kapkara düşler yolladın uykula...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Manav']::text[], 8.5, '{"poet":"Ayşe Manav","poet_slug":"ayse-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nereden-ciktin-karsima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan mevsimi', 'hazan-mevsimi-ayse-manav-pw3ia', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yakamozlar saçlarımda parlar olmuş

Beyazlar ışık ışık oynar olmuş

Yüzüme derin çizgiler dolmuş

Bahar meltemiymiş esen,

Mevsimlerden hazan olmuş,

Haykırsam akseder mi sesim maziden

Bir boşlukta dağılır diğer mi busem

Sevgim hissedilir mi en derinden

Yüreğimin kıyılarına dalgalar vururken

Bir yakamoz yansımış gözlerimden

Sözlerime gem vurmak isterken

Yüreğimin son satırına adını yazdım ben

Alaboralarla  geçip gitmiş zaman

Hafızama kazınmış an ve an

Yılların yorgunluğudur bana kalan

Dayan yüreğim bu son uçuş inan

Artık mevsimlerden hazan', 'Yakamozlar saçlarımda parlar olmuş Beyazlar ışık ışık oynar olmuş Yüzüme derin çizgiler dolmuş Bahar meltemiymiş esen, Mevsimlerden hazan ol...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Manav']::text[], 8.5, '{"poet":"Ayşe Manav","poet_slug":"ayse-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hazan-mevsimi-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan rüzgarı', 'hazan-ruzgari-ayse-manav-9x47a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonbahar yaprakları gibi savruldu yüreğim

 Sarardı gönlümdeki mavi umutlarım

Bir  esintiyle koptu dalından

Bir rüzgarla uçtu başucumdan

Kır çiçekleri soldu gönlümün

Boz kırlara kaldı meydan

Ürperdi kırışık tenimde zaman

Yaşanmış en güzel ilkbaharlardan

Bir martı kanadında uçup gitti zaman

Saçlarımda yıldızlar göz kırparken

Şimdi avucumun ortasında duran, 

Mevsimlerden hazan.', 'Sonbahar yaprakları gibi savruldu yüreğim  Sarardı gönlümdeki mavi umutlarım Bir  esintiyle koptu dalından Bir rüzgarla uçtu başucumdan Kır ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Manav']::text[], 8.5, '{"poet":"Ayşe Manav","poet_slug":"ayse-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hazan-ruzgari-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtun Soyu Kurt Olur', 'kurtun-soyu-kurt-olur-omer-sirakaya-2esvv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu yurdu bu kadar ucuz sanmayın

Kan bedelli, ödemesi güç olur

Dinime töreme çamur atmayın

Bir kıvılcım üflenirse kor olur.

Dönün şöyle bakıverin geriye

Kim boyun eğdirmiş bizim deliye.

Üç beş soysuz yağ çekmesin kimseye

Avradı dul parası da pul olur

Oğuzlardan,Osmanlı dan Türklüğe.

Yeltenmedik meydanlarda itliğe

Cephelerde hep sığındık mertliğe

Biliniz ki, kurdun soyu kurt olur.

Kapıdaki zağarlara kanmayın.

Türkü hasta, güçsüz falan sanmayın.

Sakın inancıma dil uzatmayın

Zayıf görme  titrer ise dev olur

Postun üzerinde oturan beyler.

Bakanda,Cumhurda olur deliler

Türklük sizden bir işaret, şöz bekler

Bir kükresen deli gönlüm hoşl olur.', 'Bu yurdu bu kadar ucuz sanmayın Kan bedelli, ödemesi güç olur Dinime töreme çamur atmayın Bir kıvılcım üflenirse kor olur. Dönün şöyle bakıv...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sırakaya']::text[], 8.5, '{"poet":"Ömer Sırakaya","poet_slug":"omer-sirakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kurtun-soyu-kurt-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın var', 'yangin-var-seref-ozturk-usta-qq4nr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne olur sevmesende kal orda

Yüreğimde ki ateş yetecek

Eski İstanbul yangınlarını

Yeniden tutuşturmaya

Koca denizlerin suları

Tulumbacıların koşturmaları

Nasıl yetmediyse söndürmeye

Aşkın yetmedi sevdamı öldürmeye.', 'Ne olur sevmesende kal orda Yüreğimde ki ateş yetecek Eski İstanbul yangınlarını Yeniden tutuşturmaya Koca denizlerin suları Tulumbacıların ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yangin-var-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEVDİM (Anarsın Gülüm)', 'sevdi-m-anarsin-gulum-seyhmus-sait-aydin-zresi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ateş oldun sevdim, taş oldun sevdim

Gözlerimden akan yaş oldun, sevdim

Bazen huysuz,bazen,hoş oldun,sevdim

Bu sevgiyi zamanla anlarsın,gülüm.

Seninde yüregin, birgün kan aglar,

Sanada hüzünlü bakar aynalar,

Gözünden damlalar düştüğü anlar,

Kıymetimi bilir yanarsın gülüm.

Yalnızlık büyüyüp bunalttığın’da

Ayrılık yüregini kanattığın da

Masana tek bir,mum yaktığın da,

Aklına gelirim ararsın gülüm.

Geri gelmez artık harcanan yıllar,

Çıkmaz sokak olur kapanır yollar,

Kapanır açılmaz olur da kollar,

Kendi bedenini sararsın gülüm,

Ben bu sevgi ile yandım tutuştum

Seni sevdim,ölüm ile yarıştım.

Dert,Çile,ayrılık,artık alıştım,

Sen bir başka dala konarsın gülüm.

Senin için sevgi,sadakat, boşmuş,

Yıllarca bu garip boşuna koşmuş,

Çokmu değer verip bendini aşmış

Birgün sende aldanır,kanarsın gülüm.

Saçlarına aklar düşecek birgün,

sana bakan gözler şaşacak birgün

Kara toprak seni de aşacak birgün

Sen beni orada,ARARSIN gülüm.

Şeyhmus Sait AYDIN

23.30

09,02,2006', 'Ateş oldun sevdim, taş oldun sevdim Gözlerimden akan yaş oldun, sevdim Bazen huysuz,bazen,hoş oldun,sevdim Bu sevgiyi zamanla anlarsın,gülüm...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevdim-anarsin-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Bahar', 'yalanci-bahar-fethi-aslan-mair1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karakışda doğan Güneş gibiydi

hayatıma girişin.

Boran,kış,kıyametde Çiçek açtı yüreğim

Çok geç anladım ki,

yalancı bir bahar havasıymış estirdiğin.

Ve yalancı bahara aldanan Akasya ağacı gibi

kuruyup,döküldü çiçeklerim.

Şimdi karakış ortasında meyvelerini veriyor yüreğim,

nefretim...', 'Karakışda doğan Güneş gibiydi hayatıma girişin. Boran,kış,kıyametde Çiçek açtı yüreğim Çok geç anladım ki, yalancı bir bahar havasıymış esti...', ARRAY['Türk Edebiyatı','Şiir','Fethi Aslan']::text[], 8.5, '{"poet":"Fethi Aslan","poet_slug":"fethi-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalanci-bahar-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-ayse-manav-24rrp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sende git,

Elimde kalan son damlalar gibi,

Giderken hayallerimi de götür,

Bende kalmasın düşüncelerim,

Bir kez daha, yıkıl kalbim.

Alıştım artık gitmelere,

Boşluğa uzanan ellere,

Kalmadı artık tahammül,

Seni sensiz sevmelere,

Gidişin dönüşü olsaydı,

Keşke yine beni bulsaydı,

Ayrılık acısını  yaşarken

Boşluğa uzanan ellerimi tutsaydı.', 'Sende git, Elimde kalan son damlalar gibi, Giderken hayallerimi de götür, Bende kalmasın düşüncelerim, Bir kez daha, yıkıl kalbim. Alıştım a...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Manav']::text[], 8.5, '{"poet":"Ayşe Manav","poet_slug":"ayse-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gitme-152-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koridor', 'koridor-muammer-erturan-ipmqv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dar mı dar bir koridor...

Kızıl mı kızıl bir perde dalgalanıyor

yegâne penceresinde, 

aheste mi aheste...

Ötelerinde perdenin

karanlığa karışıyor koridor.

Yoklaşıyor git gide...

Git gide yaklaşan ayak sesleri...

Git gide büyüyen bir silüet...

Git gide sıyrılıyor gölgelerinden...

Yaklaştıkça yaklaşıyor...

Yaklaştıkça ışıyor...

Işıdıkça berraklaşıyor...

O kadar dar ki koridor,

soluğu soluğuma karışıyor bir an

aheste mi aheste dalgalanan

kızıl mı kızıl perdenin

tam önünde...

Buğulu aynasında gözlerinin

puslu bir portre,

tıpkısı tıpkısına ben...

Yakamozlar geçiyor üstünden

sek sek sekerek,

kâh cesur,

kâh ürkek...

Teslimiyetçi titrek goncası

açtı açacak...

Lirik bir çiğ tanesi alında

düştü düşecek...

Öpmesem üşüyecek hani...

O kadar dar ki koridor,

küçücük bir öpücük bile sığmıyor...

Taşıyor sabaha

tadı damağımda hâlâ...

(''97)', 'Dar mı dar bir koridor... Kızıl mı kızıl bir perde dalgalanıyor yegâne penceresinde,  aheste mi aheste... Ötelerinde perdenin karanlığa karı...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/koridor-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak edene', 'hak-edene-bilge-karamehmet-cgzoo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yoktun...

her gelişinde gülerdi yüzüm nedensiz

uzaklığın değil de

alışkanlığın ürkütürdü

bilemezdin...

bir kahkahan yeterdi..

bir de boynunu büküşün çiçek misali..

varlığın milyon kişiye bedeldi

yokluğunsa ince dikiş iğnesi..', 'yoktun... her gelişinde gülerdi yüzüm nedensiz uzaklığın değil de alışkanlığın ürkütürdü bilemezdin... bir kahkahan yeterdi.. bir de boynunu...', ARRAY['Türk Edebiyatı','Şiir','Bilge Karamehmet']::text[], 8.5, '{"poet":"Bilge Karamehmet","poet_slug":"bilge-karamehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hak-edene-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-bilge-karamehmet-hs3mk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'küçükken oynadığımız oyunları andırırdı hayat

bir mızıkçı olurdu her seferinde..

büyüyünce 

tesadüflere oturttuk hayatı

sevmek bi tesadüftü bize

ayrılık içinse  gereklilik deniyordu

sonu yoksa başlanmazdı,

sonu olan aşk olamazdı

kural buydu..

son durağa gitmeden inilirdi genelde

ve müsait bi yerde atıverirdi aşk omzundan

indiğin yer

izbe bir mekandır

karanlık ve soğuktur

kar yağar ama

kar bile sıcaktır

sen hiç yanan kar gördün mü...', 'küçükken oynadığımız oyunları andırırdı hayat bir mızıkçı olurdu her seferinde.. büyüyünce  tesadüflere oturttuk hayatı sevmek bi tesadüftü ...', ARRAY['Türk Edebiyatı','Şiir','Bilge Karamehmet']::text[], 8.5, '{"poet":"Bilge Karamehmet","poet_slug":"bilge-karamehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgi-253-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlginç Savaş Birikileri (Çevirilerimden Derleme)', 'i-lginc-savas-birikileri-cevirilerimden-derleme-sevinc-kavuk-nttd0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anadolu uygarlığı insana, doğaya, yaşanan gerçeğe yönelik amaçla bilmek, öğrenmek ve öğretmektir. 

Barbar Anadoluda bulunan ilkçağ sanatını Uygar avrupanın gizliden kaçırmasıyla önyargı dönemi başladı denilebiliyor.

Nietsche, birçok düşüncesiyle çağını aştıysa da, anadolu uygarlığını yok saymasıyla çağı ile sınırlanmaktan kendini kurtaramadı. Kulaktan kulağa söylentiler ürünü, kutsal savaş hükümlü bir düşünce felsefesi deniliyor buna.

Strauss´un Wagner´e olan savaşı da var:

Erkekçe bir döğüşün ilk kuralı düşman karşısında eştliktir. İnsan, kücümsediği bir yerde savaşamaz. Buyruğu altına aldığı birşeyi kendinden aşağı gördüğü yerde savaşmamalı....

Gönüldeşiz seninle öteden beri acıya, korkuya

Toprağa ortağız seninle, güneşe de.

Konuşmayız birbirimizle, çok bildiğimizdendir bu

Sen, ateşimin ışığı değil misin? 

Sende değil mi kavrayış gücümün bir eşi olan gönül? 

Birlikte öğrenmişiz ne varsa, birlikte öğrenmişiz 

Kendimizden ötede kendimize yükselmeyi

Bir de bulut kesilmeden gülümsemeyi

Olamıyorsanız bilginin ermişleri savaşçıları olun en azından

Gözü boyuna düşman arayan kimseler olmalı

Yeni savaşlara koyulmak için bir araç olarak sevmeli barışı

Bir uçurum durur vermekle almanın arasında

Köprü atmak gerekir en küçük uçurumun bile

Kötülüğe karşı acıkmışların gönlünün bolluğunda öç almak geçiyor

Gözleri dolmuyor artık yalvarmalarından, utanç duyuşlarından

Titreyen ellerin karşısında vurdumduymaz artık yürekleri

Işığın ışıyana karşı düşmanlığıdır bu

Yiğit, yalnızlığı, aşılmaz olan yöresini kendi özünde taşır, gittiği yere götürür

Oynayanın ayak parmaklarında olurmuş kulakları

İnsan yüzü geçmişe değil geleceğe dönük olmalymış…vs

Geride bir şey olsaydı şarkı ettirirdi onu dillere ya…her neyse…

Deneye dayanan

Evrene, varlik bütününe bakan felsefenin ilk yıkıcıları

Felsefeyi yerinden yurdundan eden

Insan aklının bir sömürgesi haline getiren

Akılcı düşüncenin önderi olan

Ve ilkçağın üç bilgesi denilen

Sokrates, Platon, Aristoteles´tir deniliyor…

Onlar

Insanın önünde duranı, görüneni değil de

Yalnız düşüncede yaşayanı

Felsefeye dıştan

Iİnsana uzaktan

Doğaya ıraktan baktılar

Bize yakın olanları tanıdığımız gibi

Uzak olanı da tanımamız gerekiyor.

Aileden biri vurursa 

Belini yedi yerden kırar

Tanıdığı içindir deniliyor…

İlginç savaş birikileri felsefe yığışımında yine de 

Bilgiyle savaşmayı tercih ederim

Yine de Anadolu efsanesinde düşünmeyi seçerim....

09.02.2006

Persembe 20.30 (çevirilerimden derledim biraz...)', 'Anadolu uygarlığı insana, doğaya, yaşanan gerçeğe yönelik amaçla bilmek, öğrenmek ve öğretmektir.  Barbar Anadoluda bulunan ilkçağ sanatını ...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ilginc-savas-birikileri-cevirilerimden-derleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-70 (M.S.) 08/02/2006', 'mektuplar-70-m-s-08-02-2006-mahzun-doga-uuoab', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni bekliyor bütün kendim

sabırsız bir sabır içinde

hırçın ve sakin

seni bekliyor bütünüm

eksik ve tam

bir toz tanesi kadar da olsa

bekleyebilsem seni artık

akıllı tut beni

aklımı tut

kaçırma

bir dil ver bana

bir ses

tonlarca söz ver

seni anlatabilmeyi ver bana

sessizlik

sükunet 

ya da 

biraz çıldırmak ver bana

yazmak ve beklemek akıllı kalsın', 'Seni bekliyor bütün kendim sabırsız bir sabır içinde hırçın ve sakin seni bekliyor bütünüm eksik ve tam bir toz tanesi kadar da olsa bekleye...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mektuplar-70-m-s-08-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-71 (M.S.) 09/02/2006', 'mektuplar-71-m-s-09-02-2006-mahzun-doga-fk1v2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '15.07.1987

nerdeydim

kimdim

o doğarken

ne kadar doğuydum ben

ve sen

ne kadar batıydın

kaç sıra arkandaydım

aramızdaki ilkokul sıralarında

resim defterimde kaç gözlerin vardı

kaç Kürtçe şiirin vardı Türkçe defterimde

göz yaşın kaçtı

çocuk gösteriyorken yaşım

sen nerdeydim 

ben nerdeydin

ilk sütünü verirken sen

sütümü terk ettiğimde

kaç kıtası vardı tenimizin

ve kaçı istiladaydı o zaman

15.07.1987

nerdeydim

nerdeydin

kaç çocuk daha vardı aramızda

kaçını öldük

kaçı kaldı', '15.07.1987 nerdeydim kimdim o doğarken ne kadar doğuydum ben ve sen ne kadar batıydın kaç sıra arkandaydım aramızdaki ilkokul sıralarında re...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mektuplar-71-m-s-09-02-2006-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğuna Alışamadım', 'yokluguna-alisamadim-sami-akman-ej0f9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önce bir merhabana alıştım

Daha sonra tatlı gülümsemene

Beklemeye alıştım heyecanla

Yüreğimin çırpınmasına alıştım

Acısıyla, tatlısıyla, sancısıyla

Gecelere alıştım çünkü sen vardın

Güneşsizliğe alıştım, içimi ısıtan

İçimde büyüyen yangın gibi

Sarıp sarmalayan beni çırılçıplak

Yağmur bulutlarına alıştım

İliklerime kadar ıslatan 

Yağan yağmurda sen vardın

Rüzgârlara alıştım 

Bağrımı açıp ta “Es deli poyraz dediğim”

Yokluğundaki kadar hiç üşümediğim

Sensizliğe alıştım çünkü

Aldığım her nefeste sen vardın

Şimdi deniz tutkusu başladı bende

Med cezirlerde aradığım

Yüzmeyi bilmesem de hiçbir zaman

Tereddütsüz atladığım 

Umarsızca görmek için aradığım

Deniz gözlerinin yokluğuna alıştım

Sarı saçlarını okşamayı unuttum

Gözlerine bakmayı unuttum

Ellerini tutup ta gözlerine bakarak

Seni seviyorum demeyi unuttum

Her şeyi unuttum da

Bir seni unutamadım

Her şeye alıştım da

Sensizliğe ve yokluğuna alışamadım….

®©', 'Önce bir merhabana alıştım Daha sonra tatlı gülümsemene Beklemeye alıştım heyecanla Yüreğimin çırpınmasına alıştım Acısıyla, tatlısıyla, san...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yokluguna-alisamadim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyüm', 'koyum-ayla-efe-y6u95', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Köyüm.

Bir tepenin yamacinda,

Sirinmi sirinsin,

Yemsesil agaclar arasinda

Bir cennet gibisin…

Bakinca cal yolundan

Yükselir semaya minare

Selvi agaclari arasinda

Birde ilk okul

Meydanda koca cesme

Etrafi gölle cevrili

Sag tarafta ballik.

Solda kuru dere…

Tozunla topraginla

O temiz ve saf insanlarinla

Cana can katan havanla

Cennetten bir parca gibisin.

	Ayla Efe

1.4.1988 krefeld,ALMANYA', 'Köyüm. Bir tepenin yamacinda, Sirinmi sirinsin, Yemsesil agaclar arasinda Bir cennet gibisin… Bakinca cal yolundan Yükselir semaya minare Se...', ARRAY['Türk Edebiyatı','Şiir','Ayla Efe']::text[], 8.5, '{"poet":"Ayla Efe","poet_slug":"ayla-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/koyum-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Adıdır Hüseyin', 'askin-adidir-huseyin-halit-ozduzen-4bnug', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkın adıdır Hüseyin,

	Lezzet tadıdır Hüseyin

	Bilmeyenler Araftadır

	Arif tacıdır Hüseyin

	Muhammed gülü Hüseyin	

	Gülün bülbülü Hüseyin	

	Seni sevmeyen gönülü	

	Bilirim ölü Hüseyin	

	İlmin yoludur Hüseyin	 

	Ali oğludur Hüseyin	

	Aşk ile özü doludur,	

	Aşkın nurudur Hüseyin	

	Fatime nuru Hüseyin 	

	İsrafil suru Hüseyin 	

	İslamın büyük gururu 	

	Ümmet şuuru Hüseyin 	

	

	Ba’nın noktası Hüseyin	

	İlmin sakası Hüseyin	

	Kerbela’nın matem yası	

	Yiğitler hası Hüseyin 

  	Dinin fettahı Hüseyin

	Derdin felahı Hüseyin 

	     Ol şehitler Şeyhinşah’ı

	Derviş semahı Hüseyin

	Talibe rehber Hüseyin 

	Allah’tan eser Hüseyin

	İki cihandaki Kevser 

	Halid’e önder Hüseyin', 'Aşkın adıdır Hüseyin, 	Lezzet tadıdır Hüseyin 	Bilmeyenler Araftadır 	Arif tacıdır Hüseyin 	Muhammed gülü Hüseyin	 	Gülün bülbülü Hüseyin	 	...', ARRAY['Türk Edebiyatı','Şiir','Halit Özdüzen']::text[], 8.5, '{"poet":"Halit Özdüzen","poet_slug":"halit-ozduzen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/askin-adidir-huseyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincik', 'gelincik-ufuk-bayraktar-be75q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '______________________gaziantep''teki dostlara...

öğle arası dostlarla

buluşurduk

gelincik restoran''da.

oraya son defa  inerken

sahte sahte gülümserken

dedi biri

''''gel incik, gel boncuk''''

o kadar da komik değildi

ama güldük,

hüzün çökmesin üstümüze

çünkü güçlüydük.

bundan sonra

öğle arası

o kalabalıkta

eksik kalacak benim nefesim

o havasızlıkta.', '______________________gaziantep''teki dostlara... öğle arası dostlarla buluşurduk gelincik restoran''da. oraya son defa  inerken sahte sahte g...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gelincik-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Düşleri', 'gece-dusleri-birsen-ates-an04n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'öyle

sendeyim  ki sarmış beni fırtınalar

boğuşmaktayım dalgalarınla

kaybolurken sensizliğin  denizlerinde

yakalamışken

parmak uçlarından  aşk’ı

soluklansın 

nefesin nefesimde

ah sevgili

kuzey rüzgarları gibisin

içimi yokluğunla donduran

oysa yanan kalbimde

senin için yangınlar var

     10.02.06', 'öyle sendeyim  ki sarmış beni fırtınalar boğuşmaktayım dalgalarınla kaybolurken sensizliğin  denizlerinde yakalamışken parmak uçlarından  aş...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gece-dusleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Türküsü', 'sevda-turkusu-nurseven-atmaca-2uq1d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İlk akşamdan düşmüştü saçlarıma

Resmi kara bulutun

Yaşam savaşımda ıslak

Mutluluk savaşımda yorgun 

Pişmanlığa ağıt yakan gözlerim

Bahçemden eksilen ılık rüzgar

Dallarda

Avuç avuç toplandı

Bir damla yorgunluğuma

Bir damla mutluluğuma

Umarsızlık değilse

Düşleri gerçeğe verme telaşındayım

Gönülde bıçak yarası 

Ayrılık

Dışarıda telaşlı yaşam savaşı

Dokunması insana

...........Bu işte

Saatler zamanı tutmuyor

Bizden aldıkları geri dönmediğindendir

Bir çizgi umut.......bir tutam sevgi

Işığı sönmüş suların kıyısında 

..........Beklemekte

Bir o yana bir bu yana serpilmiş

Güneşten kalan kırıntıları 

Toplama telaşında gözlerim

Gülüşüm ürkek hüzün konaklarken

Karanlık tünelin ucunda ışığı gördüm 

Tuttum yüzümü uzun yağmurlara

Dilimin köprüleri yıkılmamış

Söylüyorsa hala sevda türküsünü

Sevgiye inandığından

Sevgisiz olduğundan', 'İlk akşamdan düşmüştü saçlarıma Resmi kara bulutun Yaşam savaşımda ıslak Mutluluk savaşımda yorgun  Pişmanlığa ağıt yakan gözlerim Bahçemden...', ARRAY['Türk Edebiyatı','Şiir','Nurseven Atmaca']::text[], 8.5, '{"poet":"Nurseven Atmaca","poet_slug":"nurseven-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sevda-turkusu-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-birsen-ates-muptz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şiirlerim ait olmadı hiç bir zaman

kendimden bir başkasına

kimseye yazmıyorum dizeleri

bu gönderme kendine pay çıkaranlara

düşler kurarım gecenin yalnızlığında 

kimseye ait olmayan

ve her sabah uyandığımda

kaybolurum 

tanımadığım insan yüzlerinde

10.02.06', 'şiirlerim ait olmadı hiç bir zaman kendimden bir başkasına kimseye yazmıyorum dizeleri bu gönderme kendine pay çıkaranlara düşler kurarım ge...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/serzenis-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nokta ki', 'bir-nokta-ki-muammer-erturan-1rvwb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir nokta ki 

bir adım ötesi 

uçsuz bucaksız bir diyar 

yitip gitmek var temelli

yolunda izinde... 

Bir nokta ki

bir adım atsan 

gerisi gelir kesin

ki feleğin şaşar

tüm taşlar oynar yerinden... 

Bir nokta ki 

bir adım ötesinde hemen 

delinmeyi bekleyen bir dağ

bir de külünk

ellerinden öper...', 'Bir nokta ki  bir adım ötesi  uçsuz bucaksız bir diyar  yitip gitmek var temelli yolunda izinde...  Bir nokta ki bir adım atsan  gerisi geli...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-nokta-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Deme', 'gel-deme-dolunay-kara-n2w06', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana veda ediyorum.

Gözyaşlarım bulutta,

Siyah bir ev sevgi karanlıkta,

Hasretim sarı yapraklarda

Gidiyorum...

Gel deme bana

Çoktan karıştım yeni yazılara.

Taze sevdalar sarmaşık koynumda.

Sanırdım bir kapı aralık daima

Ardındaki hatıralar ömürlük,

Eşi benzeri yok hayatlarda.

Camdan bir dünya ise yürek,

Yerini göremiyorsa hala,

Derdim gönül gözü âmâ.

Şimdi bir yazı duvarda,

Bakıyor bana,

Yalanım diye bağıra bağıra.

Cam çatlıyor anlasana.

Çatlaklar hızla ilerliyor! 

Karşıma çıkıyorsun,

İhanetin şeytanı bağrında.

Gözlerin alaycı...

Tek bir cam parçası yok,

Sen yoksun,

yerin yok içimde.

Gidiyorum...

Gel deme artık bana! 

Çoktan karıştım yeni yazgılara!', 'Sana veda ediyorum. Gözyaşlarım bulutta, Siyah bir ev sevgi karanlıkta, Hasretim sarı yapraklarda Gidiyorum... Gel deme bana Çoktan karıştım...', ARRAY['Türk Edebiyatı','Şiir','Dolunay Kara']::text[], 8.5, '{"poet":"Dolunay Kara","poet_slug":"dolunay-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gel-deme-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak çok kolay mı...', 'yasamak-cok-kolay-mi-reyhan-tataroglu-yegkr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatı birşey sanma zor değil aslında yaşamak

 Gülmek,gezmek, eğlenmek iyide kötümü ağlamak

 Zannediyormusun uzaklarda ölüm,son nefes, sayki kaldı ramak

 Beni pek dikkate alma saçmalıyorum işte sen yaşamana bak

 Diyorum amma yinede düşün etrafındaki olan biteni

 Sabah sarılıp öptüğün insanların arasından fark ettinmi yiteni

 Bir gün geldi  gelecek ayıracaklar  ruhundaki teni

 Hay Allah yine ne dedim ben, boş ver aldırma mutlu bir gelecek bekliyor   seni

 Desemde pek inanma sen yinede tedbirini al

 Acı içinde kıvransanda sen, san ki yiyorum bal

 Bataklığa düşşen,her melanete uğrasanda olduğun gibi kal

 Sonun çok iyi olacak işte ermiş gibi bir hal

 Orda kal; akşama kadar gezip tozacak,yanlışa sapacaksın

 Olur olmaz herşeye dikkat kesilip,pür dikkat bakacaksın

 Ondan sonrada dara düştümü  secdesiz Hakka tapacaksın

 Olmaz ama yinede Allah bilir,inşallah cennette olacaksın

 Dememe ne bakıyorsun,sen yalan,dolan,dedikodu, iftira, gıybet et

 Haklıya,mazluma,yetime,garibana,fakire acıma zulmet

 Zalime,caniye,haksıza selam söyle,çiçek gönder demet demet

 Fesübhanallah,Allah kadirdir,Allahüssamed

 Dedikten sonra dahi her şeyi ben bilirim,dediğim dedik, çaldığım düdük diyeceksin

 İçten pazarlık,gizli gizli iş çevirip kin besleyeceksin

 Herkesin en zayıf,en zor,en kötü anını bekleyeceksin

 Vallaha Allah bilir inşalllah sende sırattan geçeceksin

 Deyince herşey bitiyormu,sen her şeyin her hainliğini yap

 Bazen dilin,bazen elin,bazende belin ile çektir  millete azap

 Beyefendi edasıyla,pozlarıyla saman çıkar, ye sap

 Bekle o gün gelir denkleşir belki hesap

 Mı,kasapmı; okuduğun,dinlediğin,söylediğin doğrularla yaşantın uymasın

 Laf konuşuyorum diye ağzından çıkanı kulağın hiç duymasın

 Şeklini,şimalini,boyunu, posunu görenler seni adam sansın

 Neyse; Mevlam inşallah affeder seni sende bir insansın

 İnandınmı hemen seni gidi zavallı insan

 Belki hayellerin gerçekleşir biraz pişsen,yansan

 Düşünsen Yaradanı,tefekkür etsen hep onu ansan

 Sen o zaman kendini kurtulmuş bir kul san

 Duur! kolay değil bu iş,kolay değil böyle yaşamak

 Kolay gelir bekara her gün eşini boşamak

 Hoşuna gitti değilmi nefsini sevip,okşamak

 Hadi neyse şaka yaptım geçmiş olsun, kolay gelsin yaşamak

 Bi dakkaaa! ...', 'Hayatı birşey sanma zor değil aslında yaşamak  Gülmek,gezmek, eğlenmek iyide kötümü ağlamak  Zannediyormusun uzaklarda ölüm,son nefes, sayki...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yasamak-cok-kolay-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçindeki Çocuk', 'i-cindeki-cocuk-muammer-erturan-wpovt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Maskesiz gülüşlerinde 

rastladım ona 

sana benziyordu tıpkı 

bendeki sana... 

Maskesiz hüzünlerinde de 

o vardı 

bana benziyordu tıpkı 

sendeki bana... 

İçindeki çocuğu gördüm 

maskesiz hâllerinde 

anında kaynayıverdiyse kanım 

ondandı işte... 

Sonraları 

hiç çıkmadı yüzünden masken 

hiç çıkarmadın 

hiç sen olmadın sen... 

Görürsen selam söyle 

içindeki çocuğa! 

Özlediğimi söyle kendisini 

çok ama çok…

(''03)', 'Maskesiz gülüşlerinde  rastladım ona  sana benziyordu tıpkı  bendeki sana...  Maskesiz hüzünlerinde de  o vardı  bana benziyordu tıpkı  send...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/icindeki-cocuk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dışbükey Yanılsamalar', 'disbukey-yanilsamalar-muammer-erturan-coy6z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O

ben değil...

Benim dilim değil

o konuşan...

Sustuklarımı duysan bir de...

O

ben değil...

Benim gözlerim değil

o kör bakan...

Gördüklerimi bilsen bir de...

O

ben değil...

Benim ellerim değil

o el duran...

Tutsan da görsen bir de...

Onlar

dışbükey yanılsamalar

ona buna karşı...

Aslı

aslımda saklı...

(''03)', 'O ben değil... Benim dilim değil o konuşan... Sustuklarımı duysan bir de... O ben değil... Benim gözlerim değil o kör bakan... Gördüklerimi ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/disbukey-yanilsamalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karamanlı Georgia', 'karamanli-georgia-muammer-erturan-8hjmq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Konyak,

şiir

ve ben

herşey tamam

bir sen yoksun

bu akşam...

Konyak

şiir okuyamaz

şiir

konyak içemez

ve öpüşemez

ayyaş dudakların gibi

hiçbiri...

Konyak,

şiir

ve ben

ne köy olur

ne kasaba

üçümüzden

sen yoksan aramızda

Karamanlı Georgia! ..

(''86)', 'Konyak, şiir ve ben herşey tamam bir sen yoksun bu akşam... Konyak şiir okuyamaz şiir konyak içemez ve öpüşemez ayyaş dudakların gibi hiçbir...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/karamanli-georgia-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttunmu', 'unuttunmu-candeniz-azger-j53cu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen yüreğimde açan kirizantem çiçeği

Sen göğsümden uçan anka kuşu

Sen düşüncesizliklerimdeki tek düşüncem

Umutsuz anlarımda ki doğan güneş

Hasta ruhuma tek ilaç

Neredesin şimdi

Hangi diyardasın

Ben niye yokum yanında

Hani hiç ayrılmayacaktık

Hani bizi ayıran tek şey unutmak olacaktı

Hani şimdi nerdesin

Yoksa unuttunmu beni

Unuttunmu onca güzel günü', 'Sen yüreğimde açan kirizantem çiçeği Sen göğsümden uçan anka kuşu Sen düşüncesizliklerimdeki tek düşüncem Umutsuz anlarımda ki doğan güneş H...', ARRAY['Türk Edebiyatı','Şiir','Candeniz Azger']::text[], 8.5, '{"poet":"Candeniz Azger","poet_slug":"candeniz-azger","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unuttunmu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudum', 'umudum-candeniz-azger-bxugh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyormusun hani

Önce kendi elinle ateşlersin

Her nefeste içine çeker

Bedenini sarmasını hissedersin

Hani seni bugunden alan

Pembe hülyalara daldıran

Sigaram gibiydin

Şimdi sadece

Dışarıya üflediğim dumanı gibisin

Umudum 

Dağılan duman gibi

Bende kaybolman ve seni unutmam

Biliyormusun hani

Seni her andığımda ne olduğunu

Önce yüreğim sızlıyor

Sonra gözlerim kapanıyor

Senin yanımda olduğun o güzel güneri görüyorum

Daha sonra mı

Kapanan gözlerimden akan yaşlar oluyor

Umudum

Gözlerimden akan yaşlar gibi

Aklımdan akman ve seni unutmam', 'Biliyormusun hani Önce kendi elinle ateşlersin Her nefeste içine çeker Bedenini sarmasını hissedersin Hani seni bugunden alan Pembe hülyalar...', ARRAY['Türk Edebiyatı','Şiir','Candeniz Azger']::text[], 8.5, '{"poet":"Candeniz Azger","poet_slug":"candeniz-azger","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/umudum-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-candeniz-azger-1qxdj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyandım uykumdan yoktun

Ağladım ölesiye yoktun

Aradım köşe bucak yoktun

Tenini güzel kokunu özledim yoktun

Kötülüklerle dolu bu dünyada

Dertlerimle acılarımla

Başbaşa bıraktın beni

Korkuyorum sarsana beni

Neredesin be güzel sevdiğim

Sevdim seni ömrüm gibi

Göremedim güzel yüzünü

Nerdesin neredesin ey sevdiğim', 'Uyandım uykumdan yoktun Ağladım ölesiye yoktun Aradım köşe bucak yoktun Tenini güzel kokunu özledim yoktun Kötülüklerle dolu bu dünyada Dert...', ARRAY['Türk Edebiyatı','Şiir','Candeniz Azger']::text[], 8.5, '{"poet":"Candeniz Azger","poet_slug":"candeniz-azger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdigim-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşık Gibi Hasretin', 'sarmasik-gibi-hasretin-hatice-bediroglu-bczrn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Korkutuyor yokluğun 

Deliriyor anarşist ruhum 

Yakıversem her şeyi diyorum 

Kırıp döküversem rahatlar mıyım

Aşk mı hırçınlaştırdı bunca 

İsyanım yokluğuna mı bilmiyorum

Öfkeyi saklıyorum koynuma 

Uysallaşıveriyorum 

Döküyorum sevdamı dizelere 

Gözlerinmiş gibi bakıyorum 

Gökteki yıldızlara 

Şarkıların tadında mahsur kalbim 

Hızından yorgun düşüyorum 

Yüreğimin yarısı... 

Gel artık! 

Son ver bu sürgünlüğe 

Sıkı sıkı tut ellerimi 

Sarmaşık gibi hasretin 

Sarıyor bedenimin her yanını

'' Düş Kuruyor Gece '' adlı kitabımdan - Ocak 2008 -

www.haticebediroglu.net', 'Korkutuyor yokluğun  Deliriyor anarşist ruhum  Yakıversem her şeyi diyorum  Kırıp döküversem rahatlar mıyım Aşk mı hırçınlaştırdı bunca  İsy...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sarmasik-gibi-hasretin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tokluk Olmadığını', 'tokluk-olmadigini-sevinc-kavuk-pzchl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'içim kor gibi yanarken susmanın

acıların en beteri olduğunu

ayak uydurmaya her çalınan makama

çocukken daha yetişkini oynamaya

zorlandığımda anladım ancak

mide, zeka bir de ruhsal açlığımı

yanıp tutuşan dünyama dem çalarken

sararıp solan bedenimin rahatlığına

boğuşurken zaman renkliliğine

heyecanımda anladım ancak

acele etmeden, fakat durmadan

nefse yenilsem de fikrimde azalmadan

gerçekte sadece birazı zamana denk

öbüründe gecikmeye kaldığımı

biriken yaşımda anlandım ancak

dünkü acılardan o zorlu yükünün

bugünkü sevincime kaynak olmaya 

aceleyi yavaş yapma doruğuna 

eriştim ama sevgi, aşk, sevişmeye 

tokluk olmadığını anladım ancak

10.02.2006

Cuma 03.30', 'içim kor gibi yanarken susmanın acıların en beteri olduğunu ayak uydurmaya her çalınan makama çocukken daha yetişkini oynamaya zorlandığımda...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tokluk-olmadigini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adilliktir Asillik', 'adilliktir-asillik-sevinc-kavuk-38dz4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '__________gerçek 

sevgiyle doğar 

__________adaletten 

mutluluk 

hüküm giyer 

__________hakim 

olursa suçlu

__________beratı 

kolay olan iyi 

__________ama 

zor olan 

 __________adilliktir 

asillik

10.02.2006', '__________gerçek  sevgiyle doğar  __________adaletten  mutluluk  hüküm giyer  __________hakim  olursa suçlu __________beratı  kolay olan iyi...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/adilliktir-asillik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çatıda Leylek', 'catida-leylek-erdogan-ergin-uecjj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kuru gül yaprağında şimdi aşklar

en hafif dokunmada dökülüyorlar

delice diyorlar sevmelere

seveni deli zannediyorlar

oysa öyle mi aşk

suyun üzerinde kuğunun dans edişi

nilüferin suda duruşu

bir kaplanın avı karşısında heybeti

ve usulca rüzgarın boş kulaklara fısıldayışı aşk

kimi zaman

bir çığ dağlardan kopan

bir sel şehri boşaltan

ve bir kedinin et beklemesi

ciğerci kapısında

bazen

dolu dolu ağlamak

bazen usulca iç çekmek

bazense boş sokaklarda gezmek

lakin 

şimdi sevmek başka

çatıda leylek

ilk soğukta göç edecek', 'kuru gül yaprağında şimdi aşklar en hafif dokunmada dökülüyorlar delice diyorlar sevmelere seveni deli zannediyorlar oysa öyle mi aşk suyun ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/catida-leylek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-elazigli-mustafa-kaya-wsa1a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kimlerin hüznü var

gözlerinde 

bir başına sessizlik

sonsuz ufuklarla 

derdin mi var

dualar kadar güzel 

bir şehrin ruyası seninle 

gücenme  yaptığına

köhnemiş dünyanın …. 

Mustafa kaya

10.02.2006 / fatih', 'kimlerin hüznü var gözlerinde  bir başına sessizlik sonsuz ufuklarla  derdin mi var dualar kadar güzel  bir şehrin ruyası seninle  gücenme  ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sessizlik-269-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* BiR KaDıN ÖLdÜ DüN GeCe *', 'bir-kadin-oldu-dun-gece-mine-ozdemirtas-ivhe5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dün gece

bir kadın düştü yakamdan

üçüncü kadehimin içine.

yaralı,üzgün

ve 

sarhoştu iyice

umut

can çekişirken göz bebeklerin de

inançsız bir yakarışla

bakıyordu yüzüme

çıkarıp aldım boğulmasın diye

birlikte 

yürüdük sahilde

baştan kaybedilmiş bir savaşın

yenik kahramanıydı.

akıntıya kürek çekmekten yorgun

aç, susuz, yaralıydı

çözümsüz dü teninde ki bilmece

kendini 

yakamdan aşağı

neden attığını

anladım dinleyince.

ayaklarımız suda / kıyıya paralel

yürürken enine

ağladım onun için./ ağladım kaderine.

göz yaşlarımda ki tuz

kör gecenin

buz gibi ayazınla birleşince

kristal bir hançer halinde

düştü elime.

sadece

acıları son bulsun diye

yüzlerce kere

elimde ki hançeri

sapladım bedenine.

yıkıldı yere

o artık yaşamıyor

bende 

o kadınlardan 

bir sürü var diyeceğim ama

bende de kalmadı

nesilleri tükendi iyice

bundan böyle

ölümcül sevdaları asmadan yüreğine

yaşayıp giden

esmer, sarı, kumral

onlarca peruğun içinde

olabildiğince sahte

ruhsuz ve duygusuz

bir kaç yankie ile

kalan zamanda

idare edip gideceğiz işte.

zaten

hayat dediğin ne ki? ..

boş bir sahne

09/02/2006', 'dün gece bir kadın düştü yakamdan üçüncü kadehimin içine. yaralı,üzgün ve  sarhoştu iyice umut can çekişirken göz bebeklerin de inançsız bir...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/bir-kadin-oldu-dun-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Dediğin', 'dost-dedigin-mehmet-sait-akkus-s366e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dost dediğin candan olur

Yeri gelir maldan olur

Gerekirse candan olur

Benim fedekar can dostum

Dar gününde zor gününde

Rezil etmez el önünde

Mahşerde Allah önünde

Hesap verilir can dostum

Çağırsan hemen gelmeli

Ne varsa,sana vermeli

Dostluk dediğin ezeli

Olmalı diyorum dostum

Bu zamanda zor bulunur

Gün gelir hesap sorulur

Dostluk dediğin yoğrulur

Hamur gibi güzel dostum

Bulunmaz senin gibisin

İnan melek gibisin

Bilirim doğru birisin

Yüreği güzel can dostum', 'Dost dediğin candan olur Yeri gelir maldan olur Gerekirse candan olur Benim fedekar can dostum Dar gününde zor gününde Rezil etmez el önünde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dost-dedigin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretini Katık Yaptım', 'hasretini-katik-yaptim-mehmet-sait-akkus-tno35', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umutlarına sarıldım

Aylarca

Yıllarca

Hasretini katık yaptım

Doğradım tabağıma

Kaşıkladım defalarca

Bekledim saatlerce

Bir elimde çiçek

Bir elimde çikolata

Öylece yolunu gözledim

Bıkmadım seni sevmekten

Doymadım aşkını tatmaktan

Yarısıydı ömrümün

Hayat ağacımdı

Seni sit alanı ilan ediyorum

Lütfen

Benden başkası sevmesin

Benden başkasını sevmesin

Diyorum', 'Umutlarına sarıldım Aylarca Yıllarca Hasretini katık yaptım Doğradım tabağıma Kaşıkladım defalarca Bekledim saatlerce Bir elimde çiçek Bir e...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hasretini-katik-yaptim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi bir amelin varsa dostum iyidir o zaman işin', 'i-yi-bir-amelin-varsa-dostum-iyidir-o-zaman-isin-halil-colak-3yk5l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömür kandilinde kardeşim biterse yağın

Terk eder gidersin sevdiğin malın ve mülkün

Bu dünyada varsa faydalı da işin ve evladın

Kapanmaz amel defterin iyidir o zaman işin

Allah kul hakkını kuldan hesap da sorarsa

Allah’ın huzurunda iflas durumuna  düşerse 

Herkes nefsiyle baş başa kalıp telaş başlarsa

İyi bir amelin varsa dostum iyidir o zaman işin

Halil Çolak 10.2.2006 Ankara', 'Ömür kandilinde kardeşim biterse yağın Terk eder gidersin sevdiğin malın ve mülkün Bu dünyada varsa faydalı da işin ve evladın Kapanmaz amel...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iyi-bir-amelin-varsa-dostum-iyidir-o-zaman-isin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir akşam sofrası', 'bir-aksam-sofrasi-elazigli-mustafa-kaya-m9sxh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sofralarımız vardı

üç öğün yere yazılan

en güzel hatıralarımızı

saklayan

eşyalarımız arasında unutulan

hepimizin neşesi.

yıllar öncesi

bir akşam yemeği

ve

annemizin sesi

sofra serilecekti

koşuşurduk hepimiz

ilk ben sererdim sofra bezini

üzerine elek tahtasını

sini gelirdi üzerine sonra

minderler dizerdik

etrafına

yufka ekmeğimiz

kaşıklar 

hazırdı su - maşrapa

kah bağdaş

kah sol ayak üzerine oturulur

sağ diz yukarda

herkes yerini alır

tarhana çorbası 

besmele ile başlanılır

ne varsa nasipte.

her şey sofrada konuşulur

her şey açığa kavuşur

her kes barışıktır

aynı kap kaşıklanır…

Mustafa kaya

10.02.2006 / üsküdar', 'sofralarımız vardı üç öğün yere yazılan en güzel hatıralarımızı saklayan eşyalarımız arasında unutulan hepimizin neşesi. yıllar öncesi bir a...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bir-aksam-sofrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Böylesin', 'sen-boylesin-ufuk-coban-50yyu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen karanlık köşelerimin şarkısı oldun her gece,

Yalnızlığımı sana ağladım sen hiç bilmedin.

Beni gör de istemedim o güzel sesinin uzağında,

Sen güldün ben gözyaşlarımı sildim sen duymadın.

Yüzünü görmedim sen için için ağlarken belli etmedin,

Ne sevdalar dinmiş yüreğinde sen kimseye demedin,

Kimse dinlemedi duvarların kırılmadı sessizdin,

Bir güneşi rüzgardan esirgedin yollarda hep sensizdin.

Sen böylesin biliyor musun kendini aynada aramasan da,

Sen bir gül bahçesinin uzak köşesinde öylece duruyorsun,

Kimse kıyamıyor dokunmaya kırılgan kırmızılığın acımakta,

Sen benim yengeç burcumsun, sen benim gönül dostumsun...

09/02/2005 21:41', 'Sen karanlık köşelerimin şarkısı oldun her gece, Yalnızlığımı sana ağladım sen hiç bilmedin. Beni gör de istemedim o güzel sesinin uzağında,...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-boylesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zordur Özür Dilemek', 'zordur-ozur-dilemek-ufuk-coban-x1yso', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anla beni anladığın her güzellik gibi,

Sev ki, sevdiğin güç sevildiğine can versin,

Bir köşeye atma bir anlık sinir uğruna,

Bir an dur, düşün, nefes al ve devam et hissetmeye.

Kesip atma bir parçanı, belki de yarını,

İnan kolay değil deneme bile.

Yenilmedi hiç kimse bugüne kadar inanmadığı sevgiye,

Sen de unutma seveni ve sevdireni kendini sonsuzluğa.

Bazen aksini düşünsen de,

Benim kadar çok sevmeden anlayamazsın seni nasıl sevdiğimi.

Değerim bir çöpe girecek kadar küçükse,

Dilenmeyen küçük bir özür bile affettiremez beni.

1999', 'Anla beni anladığın her güzellik gibi, Sev ki, sevdiğin güç sevildiğine can versin, Bir köşeye atma bir anlık sinir uğruna, Bir an dur, düşü...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zordur-ozur-dilemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolum', 'anadolum-tulay-i-cen-wzxwh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yiğidin harman  olduğu yerdir,

Anadolu...

Doğusuyla,batısıyla,

Kuzeyiyle,güneyiyle,

Anadoludur benim yurdum.

Anadolu...

Dağlarıyla, ovasıyla,denizleriyle..

Tüm dünyanın gözündedir.

Anadolum...

Yunus emrenin,Pir sultanın,

Mevlananın yaşadığı....

Yiğidin harman olduğu yerdir...

Anadolu...

Doğuyla  batıyı  birleştiren 

köprüdür....

Ana gibi sıcak,ana gibi yar...

Uğrunda can veren 

Şehitlerin  kanıdır rengini veren,

bayrağına Anadolum..

Her karış  toprağın  için dökeriz

Kanımızı...

Veririz canımızı....

Kimse aklından bile gecirmesin.

Yan gözle  bile bakmasın..

Yine  birlik olur.

Yine  tek  yumruk oluruz 

Anadolum...

Altıyla,üstüyle,semasıyla.

Bu topraklar Anadoludur...

Yiğidin harman olduğu yerdir...

Anadolum..

06/02/2006', 'Yiğidin harman  olduğu yerdir, Anadolu... Doğusuyla,batısıyla, Kuzeyiyle,güneyiyle, Anadoludur benim yurdum. Anadolu... Dağlarıyla, ovasıyla...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/anadolum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Denizi', 'huzun-denizi-vedat-koparan-a7tub', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(Altta Kalanın Canı Çıkan

Bir İşleyişin Kurbanlarıyız) 

Bir ağlamak düşer 

İsyanı hıncı volkan olan

Bir gözyaşı düşer

Ağlama deme sakın 

Gözyaşı da ağlar 

İçimizin kırıklarında

Ufuklar 

Uzak uzak göç eden kuşlar

Hey hey bre 

Sevilmeyi beklemeden 

Biz ne çok sevdik 

Tutunduk bir ekmek kabuğuna 

Ne kadar yavan

Off bu pür telaş zaman

Aradım 

Sesim seni aradım

Her coğrafyada bir adım 

Baktım 

Yitip gidenlerin ardında

Hep kanadım 

Karşımdasın

Hayali malul cihan

Sen bir yanda ben bir yanda

Karşındayım 

Savrulan bu yaşamda 

Büyür ha büyür 

Hüzün denizi 

İçimin fısıltılarında

Dikenli bir gül bahçesi 

Hey hayat 

Gül yaprağında kanayan

Vedat Koparan 26.01.2006', '(Altta Kalanın Canı Çıkan Bir İşleyişin Kurbanlarıyız)  Bir ağlamak düşer  İsyanı hıncı volkan olan Bir gözyaşı düşer Ağlama deme sakın  Göz...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/huzun-denizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yudum', 'bir-yudum-vedat-koparan-zwbbh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşam bu 

Her şey bize dedik 

Harcına kardık sevgiyi 

Biraz umut ektik 

Toprağa serpilen tohumun 

Kök salıp filizlenip açmasında

Bekledik 

Sardık özlemin diline türküleri

Limanda sevgiliyi getiren gemiyi

Üşüdüğümüz kış günlerinden 

Baharın gelmesini

Güneşin içimizi ısıtıp gülmesini

Çabaladık 

Harman hasarlarda 

Patosta savrulan kabuklarca

Atölyede, fabrikada

Bir tornavida ucunda

Gevşeyip sıkılan vida

Uyuduk uyandık gün bizde biz günde 

Kanayarak, avuçları nasır tabanı çatlak 

Yaşamı her an ördük ellerimizde

Mutluluk istedik 

Renkleri aynı mavi

Bir yudum içimlik su gibi 

Vedat Koparan 26.01.2006', 'Yaşam bu  Her şey bize dedik  Harcına kardık sevgiyi  Biraz umut ektik  Toprağa serpilen tohumun  Kök salıp filizlenip açmasında Bekledik  S...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-yudum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardaş.', 'gardas-tulay-i-cen-j8siq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni nasıl anlatsam  gardaşım.

Haksızlığın  karşısında,

Adaletin  kılıcıydın..

Saygının  ve dürüstlüğün,

adıydın  gardaş...

Seni  unutanlar utansın

gardaş.

Ekmeğini  paylaştın  yıllarca,

can  dediklerinle..

Canlar  seni  unuttu  gardaş..

Anam  seni anar her gün,

gözünde  yaşlarla.

Neden  der,neden..! 

Kardeşlerin  ağam nerdesin  der..

Bu bacını   yürekten yaraladın

gardaş.

Yürekten.

Ah gardaş,ah  ağabeyim...

Hayattan korkmazdım 

Sen yanımda olduğunda 

Hem arkadaş,hem dost, hem kardeştin.

Neden gardaş  neden.

Yarı yolda bıraktın beni..

Neden? 

Zamansız bıraktın bizi

Gardaş...

03/01/2006', 'Seni nasıl anlatsam  gardaşım. Haksızlığın  karşısında, Adaletin  kılıcıydın.. Saygının  ve dürüstlüğün, adıydın  gardaş... Seni  unutanlar ...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gardas-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Allah İçin Ne Yaptın', 'bugun-allah-i-cin-ne-yaptin-sahin-erturk-a1qc6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şükür mü ettin? 

Namaz mı kıldın? 

Oruç mu tuttun? 

Zekat mı verdin? 

Söyle dostum söyle

Bugün Allah için ne yaptın? 

Sinemaya gittin

Maç seyrettin

Dedikodu ürettin

Yine zamanını boşa geçirdin

Kurtarmaz dostum

Kurtarmaz bunlar seni

Kurtlar vadisi kurtarmaz

Fener,Cimbom kurtarmaz

Dolar,Ero kurtarmaz

Yatlarla,katlarla gidemezsin

Kefenin cebi yok

Dolduramazsın Liralarla? 

Söyle dostum söyle

Bugün Allah için ne yaptın? 

Bir yetimi sevindirdin mi? 

Bir yoksulu doyurdun mu? 

Açta,açıkta kalanları

Gördünmü,giyindirdin mi? 

Hiç düşündünmü? 

Hani neredeler

Dünya güzeliyim

Starım,Şöhretim

Başkanım,Kralım diyenler

Hani neredeler dostum

Mezarlıklar

Vazgeçilmez sanılan

İnsanlarla,şöhretlerle dolu? 

O şöhretlerin,o dahilerin

Artık isimleri dahi bilinmiyor

Boş dostum bu dünya boş

Başını ellerinin arasına al

VE DÜŞÜN

Bir değil,binlerce kez düşün

Bugün ALLAH için ne yaptın? 

(10.02.2006-Yeni)', 'Şükür mü ettin?  Namaz mı kıldın?  Oruç mu tuttun?  Zekat mı verdin?  Söyle dostum söyle Bugün Allah için ne yaptın?  Sinemaya gittin Maç se...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bugun-allah-icin-ne-yaptin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-tulay-i-cen-gez4z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni  sevdim,

Hava gibi  su gibi.

Nefes  aldıkca,

seni hissediyorum içimde.

Su sadıkca  seni içiyorum

Bir parcamsın benim.

bende kopmayan..

U zaktasın biliyorum.

Sana kavuşmak için.,

Seninle olmak için,

Sana koşuyorum...

21/01/2001', 'Seni  sevdim, Hava gibi  su gibi. Nefes  aldıkca, seni hissediyorum içimde. Su sadıkca  seni içiyorum Bir parcamsın benim. bende kopmayan.. ...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Hasretin Öldürür Beni', 'hasretin-oldurur-beni-umut-gul-v0avx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretin Öldürür Beni

Hasretinden türküler yakarım

Gözüm yaşı ile yüzüm yıkarım

Sen gittin gideli sanma yaşarım

Hasretin öldürür beni beni

Dayadım sırtımı yüce dağlara

Gönlümde esiyor boran fırtına

Korkarım eremem gelen bahara

Bu sevda öldürür beni...

Türküler  söylemez böyle bir sevda

Doktordan hekimden bulamam fayda

Ne olur gelseydin haftada ayda

Hasretin öldürür beni...

Her gece öpüp kokladım resmini

Sazımın teline yazdım ismini

Yaşatmaz öldürür bu sevda beni

Unutmak mümkün mü seni...

Tükenir umudum her geçen günle 

Güllerim solar bahar gününde

Sitemim hasretle geçen ömrüme

Yokluğun öldürür beni beni...

...................................................................

Besteleyen ve Okuyan: Hasan DURUŞ

....................................................................', 'Hasretin Öldürür Beni Hasretinden türküler yakarım Gözüm yaşı ile yüzüm yıkarım Sen gittin gideli sanma yaşarım Hasretin öldürür beni beni D...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hasretin-oldurur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna Fetva Verince-"siz hiç ay aşığında ağladınız mı" Kitabından', 'ayna-fetva-verince-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-3sb9l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elâ göz mahmur bakış

Aynaya baktım sabah

Gönlüm bahar sima kış

Dünden eser kalmamış

Ömür geçmiş ben on beş

Baş aşağı kar yağmış

Çisi çisi su sesi

Bakışırken aynayla 

Müthişti ezân sesi

Yıka kirli yüzünü 

Dedi seher vaktinde

Resmetti içyüzümü

Derken gün ışıklandı

Tekrar ayni hengâme 

Mevcudat ayaklandı 

Titredi ayaklarım

Ayna fetva verince 

Buz oldu yataklarım 

Ve silkinip ürperdim

Ayna tufan gibiydi

Keşke''lendim söz verdim

Hûşu bendimi sardı 

Ümit korku muhâbbet 

Bir füsunlu bahardı', 'Elâ göz mahmur bakış Aynaya baktım sabah Gönlüm bahar sima kış Dünden eser kalmamış Ömür geçmiş ben on beş Baş aşağı kar yağmış Çisi çisi su...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ayna-fetva-verince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ım Neden Bu Kadar Sevgi Verdin', 'allah-im-neden-bu-kadar-sevgi-verdin-yusuf-onder-bahceci-wtkok', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüce Allah''ım neden bu kadar sevgi verdin,

Bana bu kadar sevgiyi verdin onu vermedin,

Ben onu rüyalarda bile olsa bir göremedim,

Yüce Allah''ım neden bu kadar sevgi verdin.

Gecelerde herkes uyuyor ben uyumuyorum,

Her güce rüyalar değil kâbuslar görüyorum,

Sevdiğimi de vermiyorlar birden uyanıyorum,

Yüce Allah''ım neden bu kadar sevgi verdin.

Eller gülüp oynuyor ama beni bunlar açmıyor,

Evvel beni çok seven yârim benden kaçıyor,

Birşey anlamadım bundan birşey açıklamıyor,

Yüce Allahım neden bu kadar sevgi verdin...', 'Yüce Allah''ım neden bu kadar sevgi verdin, Bana bu kadar sevgiyi verdin onu vermedin, Ben onu rüyalarda bile olsa bir göremedim, Yüce Allah''...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/allah-im-neden-bu-kadar-sevgi-verdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerden Şere Fırlar', 'serden-sere-firlar-ali-kilic-kakiz-v7oi5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başı havada mağrur, isyan eder nimete.

Şeytan dürter geçer hıyanetten hıyanete.

Manevi körlük,cafcaflı gurur dahası var,

Cereyanı kesildi mi şaşırır, şerden şere fırlar.

Onlar ya mağdubin, ya dâllîn ne farkeder

Gönül gözü,sahte şirketin sahiplerini sezer

Artan öfke, hırs, emel onun malıdır kardeş,

Yalan, benlik, insanın kanında vahşi bir ateş.

Allah sevgisi dışında her eylem,her ilgi sıfıra iner.

Nefis nerede olursa olsun, sonunda yanar biter.

Brüksel / 2001', 'Başı havada mağrur, isyan eder nimete. Şeytan dürter geçer hıyanetten hıyanete. Manevi körlük,cafcaflı gurur dahası var, Cereyanı kesildi mi...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/serden-sere-firlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanın En Zor İşi', 'i-nsanin-en-zor-i-si-banu-savas-w1oi4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yaşam sevgilim 

yaşamdır

ve beklemektir

beklemek bir gün bitebilir

sana saklı bir vadinin

soluksuz kalışı

kibirli olmanın öngörülemez sonuçları

sana bağışlanmanın şerbeti

haklısın tabi

olmak insanın en zor işi

ödünç verdiler seni

beklemenin süslü çiçeği

seni herkese ödünç

bana ömür boyu verdiler…

eksik mi yaptım olmak işini…', 'yaşam sevgilim  yaşamdır ve beklemektir beklemek bir gün bitebilir sana saklı bir vadinin soluksuz kalışı kibirli olmanın öngörülemez sonuçl...', ARRAY['Türk Edebiyatı','Şiir','Banu Savaş']::text[], 8.5, '{"poet":"Banu Savaş","poet_slug":"banu-savas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/insanin-en-zor-isi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-tunahan-ermihan-ofsq5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırıksa kalemim

Ve gülmüyorsa yüzüm

Hatta kelamdan kaçıyorsa dilim

Sensizliğe sitemimden

Gurbetine tavrımdandır', 'Kırıksa kalemim Ve gülmüyorsa yüzüm Hatta kelamdan kaçıyorsa dilim Sensizliğe sitemimden Gurbetine tavrımdandır...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sitem-229-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiraz Yemek', 'kiraz-yemek-ekrem-sama-xzhk5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bedeli ödenmedi

Bağcı değil ki razı,

