INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep hayalimdesin', 'hep-hayalimdesin-i-smail-arslan-lx5fu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökyüzünden yıldız yıldız yağan beyaz karda

Gözyaşlarımdasın nefesimin buharında

Kederimde,heyecanda,yazdığım satırda

Hep hayalimde ve hep gönlümde durursun ya.

Aklım durur canlanır anılar gözlerimde

Düşünceler sabırsız bekleşmekte sırada

Umutlarım yağmur gibi düşerken toprağa

Hep hayalimde ve hep gönlümde durursun ya.

Bir yanımı sevinç bekler bir yanımı keder

Ruhum bunalmış,mahkumlar gibi isyan eder

Güneş bile utanmışta bulutlara girer

Hep hayalimde ve hep gönlümde durursun ya.', 'Gökyüzünden yıldız yıldız yağan beyaz karda Gözyaşlarımdasın nefesimin buharında Kederimde,heyecanda,yazdığım satırda Hep hayalimde ve hep g...', ARRAY['Türk Edebiyatı','Şiir','İsmail Arslan']::text[], 8.5, '{"poet":"İsmail Arslan","poet_slug":"i-smail-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hep-hayalimdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüdüğünü Söyler', 'usudugunu-soyler-rukiye-ozkat-fdj52', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kuşun kanadı narinliğinde yürek,

Nazlı bir çiçek ben.

Ne açmaya,güneşi görmeye cesarat eder,

Ne de bu kapkara yalnızlığa.

Irmak kıyısında küçük kız üşüdüğünü söyler,

Üşüdüğünü söyler,üşüdüğünü söyler...', 'Bir kuşun kanadı narinliğinde yürek, Nazlı bir çiçek ben. Ne açmaya,güneşi görmeye cesarat eder, Ne de bu kapkara yalnızlığa. Irmak kıyısınd...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Özkat']::text[], 8.5, '{"poet":"Rukiye Özkat","poet_slug":"rukiye-ozkat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/usudugunu-soyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağımın Rengidir Çanakkale / Geçilmedi', 'bayragimin-rengidir-canakkale-gecilmedi-orkun-isik-zi4xp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'RUHLARI ŞAD OLSUN.

Tarih Türk''ü sınıyordu, 18 Mart mahşerini hazırlıyordu

Çanakkale''ydi mahşerin adı, miladî bir destan yazılıyordu

Nusret adlı bir gemi, döşedi boğaza mayınları

Seyit Onbaşı''nca Ocean gemisine mezar kazılıyordu…

Bir güneş doğdu Anadolu’dan, dik başlı mavi gözlüydü

Sakınmayacaktı ölümlerden, çünkü O TÜRK özlüydü

Bekliyordu Conkbayırı, böyle bir heybetli komutanı

Anafartalar diyordu, çünkü O TÜRK’e sözlüydü…

Şehit sayısı hasadındaydı, iki yüz bin kefen biçildi

Çılgıncaydı süngüler, şehitlik şerbetleri içildi

Doğacak mıydı O Hürriyet, Ay Yıldızlı Cumhuriyet? 

 ‘Ölüm Emriyle’ ‘Ya İstiklal Ya ölüm’ İlahîsi seçildi …

Gökyüzünde birer birer, çarpışıyordu mermiler

Toprağa düşüyordu, adsızca kahraman şehitler

Her düşen şehit, yüreğimize takılı bir madalyadır

Onlar bugünler için seferiydiler

Ki; Kara kalpaklı ATATÜRK’ün neferiydiler…', 'RUHLARI ŞAD OLSUN. Tarih Türk''ü sınıyordu, 18 Mart mahşerini hazırlıyordu Çanakkale''ydi mahşerin adı, miladî bir destan yazılıyordu Nusret a...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bayragimin-rengidir-canakkale-gecilmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kokusu', 'ask-kokusu-rukiye-ozkat-c7du0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Havada aşk kokusu vardı

Ve kuşlar senin doğduğun günün sabahına doğru uçuyorlardı..', 'Havada aşk kokusu vardı Ve kuşlar senin doğduğun günün sabahına doğru uçuyorlardı.....', ARRAY['Türk Edebiyatı','Şiir','Rukiye Özkat']::text[], 8.5, '{"poet":"Rukiye Özkat","poet_slug":"rukiye-ozkat","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ask-kokusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tortu', 'tortu-baris-aluk-df0vf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.............................Fatmagül Madenci''ye

Işıklar altında

tüm güzelliğiyle bir kadın

ve dilinde anahtar cümle

''Bu yalnızca et! ''

Ey kadın,

kalbimin karanlık köşelerinde

bu küçük adımlarla dolaşan

ruhumu yıkayan bu ses

gözlerdeki anlam

yalnızca bir et yığınına ait olsaydı

bu kadar insan kalabilir miydin? 

- ''Benim tam adımı bilen var mı? ''

O cesetler dünyasında

- kapkara - 

dimdik ayakta durabiliyorsan

ve sorgulayabiliyorsan yerde yatanı

ve bir dokunuşta duâya

kaldırabiliyorsan huzur içinde yatanı

ve tüm yolların sonunda duruyorsan

tanıdım seni.

Adın ölüm! 

Ey kadın,

nasıl oluyor da bunca çığlık içinde

yaşama sevgi parıltıları düşürebiliyorsun

şarabın son yudumunda aşkı cebine koyup

tanrıya bu kadar yaklaşıyorsun

karalar içinde sen

nasıl beyaz kalabildin bu kadar? 

-''Eğer insan kalmak istiyorsan...''

Sus! 

hak etmeyenler var bütün bunları

armağan ettin ya bana

geçmişimde unuttuğum gözyaşlarımı 

zarlar hep düşeş gelir mi bu oyunda? 

-''Yaşamak şakaya gelmez! ''

Sen,

kapat artık perdeleri

oyun devam edecek dışarıda...

(13.02.2006)    İstanbul', '.............................Fatmagül Madenci''ye Işıklar altında tüm güzelliğiyle bir kadın ve dilinde anahtar cümle ''Bu yalnızca et! '' Ey k...', ARRAY['Türk Edebiyatı','Şiir','Barış Aluk']::text[], 8.5, '{"poet":"Barış Aluk","poet_slug":"baris-aluk","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/tortu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizce..', 'sessizce-rukiye-ozkat-ksjs3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen hiçbir sese tahammül edemiyorum.

Kendi sesime bile! 

Bunun için susuyorum,

Bunun için yazıyorum.

İçimden geçenleri sığdırabileceğim hiçbir sayfa,

Hiçbir defter yok! 

Gözyaşlarımı bile içime akıtıyorum

Sessizce..', 'Bazen hiçbir sese tahammül edemiyorum. Kendi sesime bile!  Bunun için susuyorum, Bunun için yazıyorum. İçimden geçenleri sığdırabileceğim hi...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Özkat']::text[], 8.5, '{"poet":"Rukiye Özkat","poet_slug":"rukiye-ozkat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sessizce-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazım', 'nazim-volkan-i-ncel-upbwb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yanda nizam

