INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-fikret-kemal-aslan-zdyh0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne güzeldir karda kıtır kıtır yürümek.

Her taraf ne kadar ak ne kadar temiz.

Ne güzeldir,bir Sibirya soğuğunda üşümek.

Sırtında kalın bir palton varsa,

Bir başlık kafandaysa

Ve de kaymıyorsa; 

Pabuçların ayaklarında.

Değme gitsin keyfine.

Böyle bir kış belki yine görülmez.

Üstelik herkes önüne bakıyorken,

Kimseden kimseye zarar da gelmez.', 'Ne güzeldir karda kıtır kıtır yürümek. Her taraf ne kadar ak ne kadar temiz. Ne güzeldir,bir Sibirya soğuğunda üşümek. Sırtında kalın bir pa...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kemal Aslan']::text[], 8.5, '{"poet":"Fikret Kemal Aslan","poet_slug":"fikret-kemal-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kar-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Desem Ki', 'ne-desem-ki-enver-herguler-i66sb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zevk ve çoğu keder karışımı

Bu anlamsız hayatı yaşamaktan

Nedense eşsiz bir haz alıyorum.

Bu duyguyu ne yazık ki

Biriyle paylaşmak şöyle dursun

İzah edebilecek tek kelime

Dahi bulamıyorum.', 'Zevk ve çoğu keder karışımı Bu anlamsız hayatı yaşamaktan Nedense eşsiz bir haz alıyorum. Bu duyguyu ne yazık ki Biriyle paylaşmak şöyle dur...', ARRAY['Türk Edebiyatı','Şiir','Enver Hergüler']::text[], 8.5, '{"poet":"Enver Hergüler","poet_slug":"enver-herguler","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ne-desem-ki-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Oldu', 'ne-oldu-yasar-tezel-rwhju', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O kadar soğuk ki geceler

Vakitsiz uyandım da ne oldu

Evlenen çiftler,iki kumru

Seni sevdim de ne oldu

Bekledim..sahilde ne gemi göründü

Koca denizde ne  bir yelken derken

Martılar çığlık çığlığa boğdu da ne oldu

Dalgalar sahile vurdu da,ne oldu

Unuttun da,ne oldu güzelim

Aç açıkta kim kalmış yuvasız

Sen yükseklerin dilencisiydin

Dilendin dilendin de ne oldu

Suçlu, benim her zaman

Kalbim yıllar yılı sende

Bu gönül sarayının tahtında

Yaşadın yaşadın da ne oldu

Vakitler geçmiş,hala yazarım

Yıllarca unuttun da ne oldu

Sonu geldi,bütün ayrılıkların

Seni buldum,buldun da ne oldu', 'O kadar soğuk ki geceler Vakitsiz uyandım da ne oldu Evlenen çiftler,iki kumru Seni sevdim de ne oldu Bekledim..sahilde ne gemi göründü Koca...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-oldu-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üryan', 'uryan-mehmet-postalli-tb8sl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ormanı olmayan yurt, anadan üryan insan

Ağaç, yurdun örtüsü olur, iyi korursan', 'Ormanı olmayan yurt, anadan üryan insan Ağaç, yurdun örtüsü olur, iyi korursan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/uryan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Hesap', 'i-nce-hesap-hasan-sakman-heslo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Edebi İfade:

Kırkla çarpınca verdiği zekatı muhteremin,

ortaya çıkacak ederi

ümmetinden sakladığı servetin.

Matematiksel İfade:

y ---> Servet Toplamı,

x ---> Verilen Zekat Miktarı,

1/40 -> Zekat Oranı,

____________________

y * 1/40 = X --> y = 40x', 'Edebi İfade: Kırkla çarpınca verdiği zekatı muhteremin, ortaya çıkacak ederi ümmetinden sakladığı servetin. Matematiksel İfade: y ---> Serve...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sakman']::text[], 8.5, '{"poet":"Hasan Sakman","poet_slug":"hasan-sakman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ince-hesap-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-battal-ozcan-j8w8u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çift gözdü sende ilk gördüğüm,

Karanlığın içerilerinde parlayan.

Ve bir çekingen eldi utana sıkıla uzatılan.

Ya şimdi ne değiştirmişti bunu,

Ne katil yapmıştı parlayan gözleri,

Yahut kim cellat yapmıştı o çekingen elleri? 

Ben olamam bu suçların amili; 

Kalbim olmuş olamaz bir hayatın zalimi

Şimdi sen sorgula kendi kendini

Kalbine sor bakalım ben ne yaptım kendimi?', 'Bir çift gözdü sende ilk gördüğüm, Karanlığın içerilerinde parlayan. Ve bir çekingen eldi utana sıkıla uzatılan. Ya şimdi ne değiştirmişti b...', ARRAY['Türk Edebiyatı','Şiir','Battal Özcan']::text[], 8.5, '{"poet":"Battal Özcan","poet_slug":"battal-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/neden-220-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Eller yukarı: İHANET..!', 'eller-yukari-i-hanet-dilek-egri-zlpq4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'söyle kalabalıklardaki yalnız şehir..

aşkımın sadakati hangi sokağında gizli..? 

söyle lacileri çekmiş asil gökyüzü..

hangi yıldız sevdiğimin gözleri...? 

büyümüş çocukluğum benim..dün tam da yüreğine bakıyordum senin.

başka eller, sözler, isimler geçti gözümün önünden

duraksadım

sen durma..! 

anlat o sonsuz sevgini..

gururum ayaklandı.. yüreğimi işgale geliyor

çek sularımdan ayrılığın askerlerini..sevgime bişey olsun istemiyorum..! 

sevmek, emek vermek ve birden çekip gitmek zor

omuzlarıma ağır bir yük bindi..altında eziliyorum

hani ağlasam, bağırsam, çağırsam, geçer/mi derken

yüküme yük ekleniyor..taşıyamıyorum..

ihanet, yalan, dolan..! 

çekin gidin yüreğimin kapısından

içerisi sevgimle tıklım tıklım...onu uğurlamak istemiyorum...! 

12/02/06

Oba Cafe', 'söyle kalabalıklardaki yalnız şehir.. aşkımın sadakati hangi sokağında gizli..?  söyle lacileri çekmiş asil gökyüzü.. hangi yıldız sevdiğimi...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eller-yukari-ihanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aciziz', 'aciziz-nurhan-gokturk-ylxep', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir o şaşı köpek doğum kusurlu,

Bir ben umutsuz aşık,

O her gece sokak lambasının altında,

Bense Ecir sokağının kuytusunda,

İkimizin de umudu var,

O lambalarda seçebildiği renkleri aramakta,

Bense balkonda belirecek silueti,

İkimizin de cesareti yok,

O gerçeği kabullenmekten,

Ben ifade etmekten aciz.

Nurhan GÖKTÜRK

20.01.2006/Antalya', 'Bir o şaşı köpek doğum kusurlu, Bir ben umutsuz aşık, O her gece sokak lambasının altında, Bense Ecir sokağının kuytusunda, İkimizin de umud...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aciziz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen Öyle Yazıyorum', 'bazen-oyle-yaziyorum-yusuf-onder-bahceci-vbwb1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim yazdığım bazı şiirlerde,

Mecaz anlatımlar var hece ile,

İçerisinde kolay bilmecelerle,

Bazen öyle yazıyorum, öyle.

Ne edeyim duramıyorum be,

İçimde ki iman dürtüyor, bre,

Vatan, Devlet, Sevda iç içe,

Bazen öyle yazıyorum, öyle.

Bilirim Vatan sevgisi, iman,

Elimizde olur, Yüce Kuran,

Varmıdır karşımızda duran,

Bazen öyle yazıyorum öyle.

Allah sevgisi gönülde, bilin,

Birlik olalım hep gelin, gelin,

Fitne, fesatları böyle silelim,

Bazen öyle yazıyorum, öyle.', 'Benim yazdığım bazı şiirlerde, Mecaz anlatımlar var hece ile, İçerisinde kolay bilmecelerle, Bazen öyle yazıyorum, öyle. Ne edeyim duramıyor...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bazen-oyle-yaziyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarsın ve Ağlar Tezene', 'aglarsin-ve-aglar-tezene-gul-yazganarikan-34tnr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu kaçıncı şiir sana yazdığım.

Bağlamanın tellerine takılan kaçıncı türküsün kimbilir...

Bir kanun oluyorsun,çaldıkça çalıyorsun

Eski bir dost gibi Ansızın karşıma çıkıyorsun

Meğer bir ben değilmişim seni yazan....

Kaç kişinin yakmışsın canını, görüyorsun...

Aldanmışlığım, yanılmışlığım, yalnızlığım Çalınan...

Aldanmışlığımız aşka kanmışlığımız mı şu keman

Ve şu ağlatan sözler ve işitiyor musun, hepsi sen gibiler... ve ben gibiler....

Kimi çekip gitmişler senin gibi, 

Kimileri hasreti büyütmekteler, 

Kara bir yılan gibi büyür o gece olunca

Dolandıkça dolanır insanın boynuna,

Ne kadehler ne şu kanun ne de şu keman

Ne şarkılar ne türküler ne şiirler yetmez olur...

Yokluğun sonu gelmez olur...

Azaltmazlar acını ezgiler, hasretin içinde isyanın olur, 

Çırılçıplak kalırsın, gözlerin utançlarından soyunur 

ve ellerin, kendi ellerinle kalbini yerlere atasın gelir

Kaç bela okursun kaderine, ve en ağır küfürleri savurursun kendine

her tele vurduğunda ağlarsın ve ağlar tezene

Ama anlatamazsın...

Ne kelimeler ne şarkılar ne şiirler 

Yazdıkça yazamazsın...

çıkarıp yerinden mühür gibi basasın gelir yüreğini

bir leş gibi kalır avuçlarında yapamazsın

ve ağlarsın her şarkıda

ve her şiirde

ve her türküde

ağlarsın... 

kanun ağlar, keman ağlar, tezene ağlar

sen ağlarsın...

ve anlarsın....

aslında anlatamazsın...', 'Bu kaçıncı şiir sana yazdığım. Bağlamanın tellerine takılan kaçıncı türküsün kimbilir... Bir kanun oluyorsun,çaldıkça çalıyorsun Eski bir do...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/aglarsin-ve-aglar-tezene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-battal-ozcan-rre6g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu sabah yine sensizligime uyandım

Bir yanda saat tıkırtısıbir yanda kahvaltı hazır sesleri

Hepsi de sensizliğimin sıradan cilveleri

Hayat işte naz yapacak ki aşık usanacak

Yanlızlığa ortak olacak kalbimi saf dışı bırakacak

Kolay mı sanıyorlar acaba unutmayı

Yada her türlü meşguliyetle unutturmayı

Alabiliyorsanız alın gözlerimi

Alın her dokunduğu yerde onu arayan ellerimi

Daha da ötesi sökün her anı onu atan kalbimi

Görmüyor musunuz gerçek aşktaki samimiyetini 

İşte böyle bir şeymiş gibi sevmek sevilmek

Bir yanında herkes olsa da

Bir yanının bomboş olduğunu bilmek....', 'Bu sabah yine sensizligime uyandım Bir yanda saat tıkırtısıbir yanda kahvaltı hazır sesleri Hepsi de sensizliğimin sıradan cilveleri Hayat i...', ARRAY['Türk Edebiyatı','Şiir','Battal Özcan']::text[], 8.5, '{"poet":"Battal Özcan","poet_slug":"battal-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unutma-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşlarım', 'gozyaslarim-i-brahim-sarihan-9jkkx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dışarıda, çiseleyen ılık bir yağmur

Ağlarım bende gökle, yüreğim doludur

Sevda selim, hiç durmaz akar durur

Gözyaşlarım, aşkımı anlatır aslında

Çok sevdim diyemem, sevgim tektir

Gönül vermişse bu kalp, candan sevendir

Günü birlik ilişki, aşkıma çok terstir

Gözyaşlarım, aşkımı anlatır aslında

Üzülme dedim, hep yaşlıydı bu gözler

Yalan sevgilerle, insan kendine eder

Taviz verse kalbi, duyguyu hisseder

Gözyaşlarım, aşkımı anlatır aslında

Hayatı boş verme, yaşa umursa doğayı

Rabb''im duygulu yaratmış, kulu insanı

Sev-sevil, aşkı tatmadan bırakma hayatı

Gözyaşlarım, aşkımı anlatır aslında

Kalbi bir güzelin sevseydi kalbimi

Tutku olurdum, bırakamazdı sevgimi

Aşksa; derin yaşanır, çıkamazdı belki

Gözyaşlarım, aşkımı anlatır aslında

Yaşamalısın, bilmem değer mi anlatmaya

Var artık sende korkma, aşkın tadına

Tek bir evetle seninim, bana öyle bakma

Gözyaşlarım, aşkımı anlatır aslında

(Hakkâri, 10 Kasım 2003)', 'Dışarıda, çiseleyen ılık bir yağmur Ağlarım bende gökle, yüreğim doludur Sevda selim, hiç durmaz akar durur Gözyaşlarım, aşkımı anlatır aslı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıhan']::text[], 8.5, '{"poet":"İbrahim Sarıhan","poet_slug":"i-brahim-sarihan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gozyaslarim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kar Ne Zarar', 'ne-kar-ne-zarar-faruk-gokbulut-63fxw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Minik bir serçenin,

Kıpır kıpır yüreği gibiydin.

Masmavi gözlerinle,

Her gece rüyama gelirdin.

Demlenen çayın kokusunda,

Gül kurusunun derin uykusunda,

Hep sen vardın

Yüreğimin köşebaşında; 

Başucumda.

Artık yoksun

Ne kar ne zarar

Önümde yaşanacak,

Koca bir ömür var.

24 AGUSTOS 2003

Saat:  10:40

Ş.URFA', 'Minik bir serçenin, Kıpır kıpır yüreği gibiydin. Masmavi gözlerinle, Her gece rüyama gelirdin. Demlenen çayın kokusunda, Gül kurusunun derin...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-kar-ne-zarar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl Güller', 'kizil-guller-faruk-gokbulut-wol3j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gölgenle ruhum arasında açan kızıl güller

Aşkımızı anlatan en tatlı deliller

Aşk çemberine düşünce gönüller

Dil susar ve lâl olur bülbüller

Kızıl güllerin yaprağında gizlenen esrar

Gül bakışlı yarimde aslını arar

Gül bahçesinden kalma tatlı hatıralar

Kızıl güllerin alev rengiyle içimi yakar

04 MAYIS 1999

Saat:  11:23

İSTANBUL', 'Gölgenle ruhum arasında açan kızıl güller Aşkımızı anlatan en tatlı deliller Aşk çemberine düşünce gönüller Dil susar ve lâl olur bülbüller ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kizil-guller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu savaşlar neden anne?', 'bu-savaslar-neden-anne-yusuf-ziya-leblebici-znv94', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu bombalar neden anne, 

Atılıyor topraklara

Bu savaşlar neden anne, 

Kıyılıyor insanlara

Umudumuz gönlümüzde, 

Güneşimiz gözümüzde

Bu savaşlar neden anne,

Barış varken önümüzde

Çocuklara kıyıyorlar,

Ormanları yakıyorlar

Bu çıkarlar neden anne,

Umutları çalıyorlar

Ne söylesem faydası yok,

Ağlasam da duyanı yok

Bu savaşlar neden anne,

Bunların hiç insafı yok

Afrika’da aç çocuklar

Gözlerime bakıyorlar

Bu sancılar neden anne,

Çamurlarda yatıyorlar

Somali’de ağlıyorlar,

Yüreğimi dağlıyorlar

Bu savaşlar neden anne,

Dünyamızı yıkıyorlar

Benim babam çalışırken,

Bize ekmek getirirken

Bu oyunlar neden anne,

Çalıyorlar emeğinden

Kime kalmış yaşamamız,

İstenmiyor okumamız

Bu savaşlar neden anne,

Bilin bizler yarınlarız', 'Bu bombalar neden anne,  Atılıyor topraklara Bu savaşlar neden anne,  Kıyılıyor insanlara Umudumuz gönlümüzde,  Güneşimiz gözümüzde Bu savaş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bu-savaslar-neden-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzakta', 'uzakta-neyyir-aribas-l3ob5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aynada görür gibi kendimi bakarken

Cemalin göğe, bulutlardan yukarı yükselirken

Uzakta, çok uzaktasın biliyorum

Ellerim çaresiz yüzüme kapanmış....

Albatros kanatlarım süzülen Eylül yaprakları

Akar gider nehirlerde kuru bir dal parçası

Uzaklara, çok uzaklara biliyorum

Ayaklarım gayesiz yollara kapanmış....

Artık şavkı yok kırık bir cam parçasının 

Kayan yıldızlar ayın hilaline doğru aniden

Uzakta, çok uzaktasın biliyorum

Gözlerim fersiz, boşluğa kapanmış....

Hıçkırıklarda boğulan okyanus dalgaları

Eza oldu vücuduma süs tınıları

Uzaklarda, çok uzaklardasın biliyorum

Dudaklarım çaresiz, dualara kapanmış....

Bulutlar getirdi, bulutlar götürdü yağmur gibi

Atlantis diplerinde erişilmeyen bir inci

Uzaklardasın, çok uzaklarda biliyorum

Neyyir Can sevdalı şiirlere kapanmış...', 'Aynada görür gibi kendimi bakarken Cemalin göğe, bulutlardan yukarı yükselirken Uzakta, çok uzaktasın biliyorum Ellerim çaresiz yüzüme kapan...', ARRAY['Türk Edebiyatı','Şiir','Neyyir Arıbaş']::text[], 8.5, '{"poet":"Neyyir Arıbaş","poet_slug":"neyyir-aribas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzakta-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gör artık', 'gor-artik-battal-ozcan-xxn3f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir günmüş ki kışın bile dudaklarının titrediği,

Ayazların yeryüzünde hakimiyetini perçinleştirdiği,

Kimse söylemese gözüm de ayazın işkencelerini görmese

Hissedemeyeceğim bedenimin soguğa karşı hassasiyetini.

Nedenini niçinini nasılını sormayın bu surete

Nerden bileceksiniz ki kalbimin daimi artan hararetini.

İşte bir yangın daha kalbimin duyarlı köşelerinde

Bir volkan daha patlıyor yüreğimin yükseltilerinde

Ne zaman sönecek bu ateş,ne zaman dinecek bu rüzgar,

Yağmur yanıt vermeyecek mi kabimin yakarışlı suallerine? 

Dön artık dönde dindir şu durmak bilmeyen yangınlarımı,

Gör artık görde söndür söndürülemeyen volkanlarımı.

Cevap ver isminin anıldığı kalp atışlarıma,

Geç kalırsan bulamazsın bir yanından tutuşturulmuş hatıraları,

Ve gelmezsen kuramazsın artık bir taht gönül malikanelerinde', 'Bir günmüş ki kışın bile dudaklarının titrediği, Ayazların yeryüzünde hakimiyetini perçinleştirdiği, Kimse söylemese gözüm de ayazın işkence...', ARRAY['Türk Edebiyatı','Şiir','Battal Özcan']::text[], 8.5, '{"poet":"Battal Özcan","poet_slug":"battal-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gor-artik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapinda Sabahladim', 'kapinda-sabahladim-kemal-oguz-duii3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gene gökyüzü bulutlu bu aksam.

Yildizlar görünmüyor hic.

Yildizlar göz kirpmiyor bana bu gece.

Ama ben Senin bazan pencerenin.

Ve bazen sacagin altinda bekliyorum.

Hala Sen elektrik salterini acmiyorsun.

Ampuller aydinlanmiyor evin icinde.

Sonra, pencereden ne olur baksan.

Evet, baksan beni görebilirsin.

Yagmur yagiyor üzerime hafiften.

Arasira simsek cakiyor.

Ve aydinlatiyor etrafimi.

Birden gök gürledi kafamin üzerinde.

Yagmur olanca hiziyla yagiyor.

Hem yagmur ve hemde askindan.

Sirilsiklam oldum sokagin ortasinda.

Gecenin karanliginda, Senin kapinda.

Yagmurdan islanmis elbiselerimle.

Haykiriyorum Sana, nerdesin? diye.

Hic olmazsa yüzünü görseydim.

Sonra evime dönseydim.

Sen yatagina girmeden önce.

Gözlerim kapaniyor.

Elbiselerim islak.

Ama ben! kapindan ayrilamiyorum.

Gecenin ilerleyen saatinde.

Seni daha cok sevdigimi anliyorum.

Uykuya daliyorum sokagin ortasinda.

Dizlerim dermansiz yere yigiliyorum.

Yagmurlu bu havada.

Ve zifiri karanlikta.

Sabahin olmasini bekliyorum.

Askinin sarhoslugu ile ayiktim.

Bu gece ben,

Senin kapinda sabahladim.

(Esslingen, 14 Mayis 1988)', 'Gene gökyüzü bulutlu bu aksam. Yildizlar görünmüyor hic. Yildizlar göz kirpmiyor bana bu gece. Ama ben Senin bazan pencerenin. Ve bazen saca...', ARRAY['Türk Edebiyatı','Şiir','Kemal Oguz']::text[], 8.5, '{"poet":"Kemal Oguz","poet_slug":"kemal-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kapinda-sabahladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabul Edişler', 'kabul-edisler-aytekin-kaya-oyguj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cam kırıkları hüznünde sokaklar 

ve ufak bir çocuğun utangaçlığı......

bir fırtınada atılan yüzük pişmanlığı 

her gelişinle balkonlara taşıyor sevinç.

Mahalle megafonundan belediye ikaz ediyor

''su faturalarının son günü,acele edin! ''

kimse oralı olmuyor,herkes de 

ip atlayan ufak kız çocuklarının duyarsızlığı 

yanlız ben ilgileniyorum

hiç dalından kirazı yiyemediğim gibi

hiç bir faturayı da zamanında yatıramam

çünkü yaşamak cezadır belli bir oranda

Sakin semtlerin mutlu insanları anlamaz beni

sakin sakin gemilerini yüzdürürken

hep fırlayarak uyandım acılardan 

Hüzün denizinde 

salınarak yüzen kuğu kadar alımlıdır acılarım

gönderilmeyecek bir mektubun 

yazılmasındaki saçmalık kadar

saçmadır pişmanlıklarım

Tarihe not düşen bir vakanüvistim

düştüğüm şey başkalarının

bense hiç bir şeyim

hiç bir anlamı olmayan', 'Cam kırıkları hüznünde sokaklar  ve ufak bir çocuğun utangaçlığı...... bir fırtınada atılan yüzük pişmanlığı  her gelişinle balkonlara taşıy...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Kaya']::text[], 8.5, '{"poet":"Aytekin Kaya","poet_slug":"aytekin-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kabul-edisler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
