INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Olsun', 'selam-olsun-faruk-gokbulut-q1sxo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Can otağına dost düştü

Gönül bağına mest düştü

Gül-i zara bülbüller üşüştü

Gülenlere selam olsun

Gönül bahçem aşk büyütür

Sabır taşım dert öğütür

Biz sevdaya saygı duyduk

Bilenlere selam olsun

27 Nisan 2004

Ş.Urfa', 'Can otağına dost düştü Gönül bağına mest düştü Gül-i zara bülbüller üşüştü Gülenlere selam olsun Gönül bahçem aşk büyütür Sabır taşım dert ö...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/selam-olsun-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Bana Sor', 'gel-bana-sor-yusuf-onder-bahceci-bnld6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mecnun çöllerde gezmiş diyorlar,

Kerem Aslı''sı için yanmış diyorlar,

Ferhat ise dağları delmiş diyorlar,

Bunlar da bir şeymi gel bana sor.

Mecnun Leyla''yı çöllerde aramış,

Leyla Leyla diye yanmış ağlamış,

Sonunda birgün Leyla''yı bulmuş,

Bunlar da bir şeymi gel bana sor.

Kerem Aslı için yanmış dayanmış,

Çileleri çekmiş, sonunda yanmış,

Aslı da onun için, çokça ağlamış,

Bunlarda bir şeymi gel bana sor.

Ferhat bu dağları, nasıl delermiş,

Dağları delerken, dualar edermiş,

Allah''ım, Allah''ım kavuştur dermiş,

Bunlarda bir şeymi gel bana sor.

Seni ilk gördüğüm anda sevmişim,

Sevmişim, vallahi gönül vermişim,

Sevdiğim öl dese hemen demişim,

Bunlarda bir şeymi gel bana sor...', 'Mecnun çöllerde gezmiş diyorlar, Kerem Aslı''sı için yanmış diyorlar, Ferhat ise dağları delmiş diyorlar, Bunlar da bir şeymi gel bana sor. M...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-bana-sor-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır Gibi', 'sir-gibi-faruk-gokbulut-s78mt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu aşk yaşanacak gizlice, belki bir sır gibi

Günler aylarımız geçecek, belki bir asır gibi

Serilmişiz yollara selviler nergisler misali

Dertler oturmuş yüreğimize, sanki bir nasır gibi

11 NİSAN 2003

Saat:  21:19

