INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibi', 'gibi-faruk-gokbulut-jvmy8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayâlin hâlime gülümser gibi

Gözlerin ruhumu özümser gibi

O dudaklar ki ballar misâli

Öpmeye kıyamam özletir visâli', 'Hayâlin hâlime gülümser gibi Gözlerin ruhumu özümser gibi O dudaklar ki ballar misâli Öpmeye kıyamam özletir visâli...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gibi-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-faruk-gokbulut-474n4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sol yanım ateşe teslim yanar da yanar

Can özüm, iki gözüm, kumrular seni sorar

Sensiz başım önde, içimde binbir düğüm

Hayalini her gece rüyalarda gördüğüm, gel

17 ŞUBAT 2003

Saat:   03:08

Ş.URFA', 'Sol yanım ateşe teslim yanar da yanar Can özüm, iki gözüm, kumrular seni sorar Sensiz başım önde, içimde binbir düğüm Hayalini her gece rüya...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gel-272-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gece Bu Saatlerde', 'her-gece-bu-saatlerde-erkan-akarcay-kntau', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün batar, Gece vardiyayi teslim aldigi o vakitlerde basliyor hersey,

Kilitleniyor yüreğim, karmakarisik soru isaretleri beliriyor etrafimda,

Neden, nicin, nasillarla oyalaniyorum yalniz bir basima odamda,

Neydim, ne oldumlarla bulandiriyorum kafami, ümitsizlik ekiyorum hayatima.,

Dikkat ettimde bütün bu yazdiklarim, bu saatlerde cikiyor karsima,,

Silip atamadigim, anilarim,acilarim,  isyanlarim..

Sanki aralarinda anlasmislar gibi,bugecede bitiyorlar yanibasimda..

Soruyorum kendi kendime bazi zaman,

Nezaman nadasa terkedilicek bu yüreğim.. nezaman.? 

Biktim artik, usandim, tükendim, bittim.. dedigim anlarda bile..,

Alnimin yazisi gibi, kara bir leke misali, hatta bir gölge gibi pesimde,

Sonu gelmiyecek, ebediyete kadar sürüp gidecekmiscesine,

Korkuyorum artik, eskisi gibi aglayip, sizlayamiyorum hernedense..

Sikintilarini gizlemis, maskesini takmis bir palyaco gibi..,

Artik yapamiyorum, dökemiyorum gözyaslarimi bile gizli..gizli,

Artik kacamiyordum korkularimdan, artik sonu gelmis misali,

Tevkif edilecekmisim gibi, engel olamiyordum artik..

Cünkü sonu gelmis gibiydi....

İletişim: [email protected]', 'Gün batar, Gece vardiyayi teslim aldigi o vakitlerde basliyor hersey, Kilitleniyor yüreğim, karmakarisik soru isaretleri beliriyor etrafimda...', ARRAY['Türk Edebiyatı','Şiir','Erkan Akarçay']::text[], 8.5, '{"poet":"Erkan Akarçay","poet_slug":"erkan-akarcay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/her-gece-bu-saatlerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-i-brahim-sarihan-mzmke', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adı aşk bunun saklama asla, tanıyor herkes

Sil yüreğinden yalnızlığı, dinle aşk bu ses

Haykır susma sende bana sevdiğini, her nefes

İçimde sana karşı duyulan, büyük bir heves

Bir şans eseriydi, merdivende çarpıştık

Önce umursamadık, sonra göz göze bakıştık

O an büyülenmiştik, gözlerimizi ayıramadık

Şimdi kalbim yanıyor bu aşkla, sönmez artık

Dünya küçükmüş derlerdi, inanmazdım buna

Meğerse öyleymiş, rastladım aşkına sonunda

Aradığım, yıllanmış şarap gibi bir aşk ya

İşte, o aşkı içeceğim tek solukta kana kana

Üzmez seni yüreğim, bu aşkı zor buldu çünkü

Hep anlattığı sensin, değerlisin demek ki

Üzerine titretir beni, saçlarının her teli

Uykumda dahi kıyamam sana, düşlerimin sahibi

Senin olayım ben, sen de ebediyen benim

Nasipsiz olamaz kalbim, bundan şimdi eminim

Sen güzeller güzeli, gözümde teksin bebeğim

Çıkartma kalbinden beni, hep orası olsun yerim

(Hakkâri, 19 Kasım 2003)', 'Adı aşk bunun saklama asla, tanıyor herkes Sil yüreğinden yalnızlığı, dinle aşk bu ses Haykır susma sende bana sevdiğini, her nefes İçimde s...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıhan']::text[], 8.5, '{"poet":"İbrahim Sarıhan","poet_slug":"i-brahim-sarihan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-542-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayçam - 2', 'aycam-2-faruk-gokbulut-5dudk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günler aylar geçti hâlâ ağlarsın

Artık yaşlarını sil be Ayçam

O mahzun halinle yürek dağlarsın

Aşkın sembolüsün bil be Ayçam

Bilirim yaranı derindir derin

Bakarsın yüzüme ağlar gözlerin

Kalbimde hep aynıdır senin yerin

Olmasın yaşların sel be Ayçam

Aşkımın hatrına gelirim dize

Ne olur acı bu garip öksüze

Ağyar bile hayransa halimize

Bekletme bu canı gel be Ayçam

07.06.2000

Saat:  23:11

Malatya', 'Günler aylar geçti hâlâ ağlarsın Artık yaşlarını sil be Ayçam O mahzun halinle yürek dağlarsın Aşkın sembolüsün bil be Ayçam Bilirim yaranı ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aycam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
