INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah - u Efganım', 'ah-u-efganim-faruk-gokbulut-tn8q6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tıpkı ocaklar gibi yanar da dururum

Ortalıkta bir tipi ateşim dışa vururum

Ben ağlar isem çağlayanlar utansın

Dertliyim dostlar görenler divâne sansın

Söz etme yardan içime sis saçılır

Haber et bahardan gözüm gönlüm açılır

Çok zaman oldu hatıralar ölüp gitmiş

Aşk, bu candan ayrılalı sanki işim bitmiş

Aşka kemend vurulmuş, sevdadan yok eser

Halim ağyâra sorulmuş, demişki ölüden beter

Başımı taşlara vurdum yandıkça yandım

Kalbimi Allah''a açtım, bu kabustan uyandım

23 AĞUSTOS 2004

Saat:  14:15

Ş.URFA', 'Tıpkı ocaklar gibi yanar da dururum Ortalıkta bir tipi ateşim dışa vururum Ben ağlar isem çağlayanlar utansın Dertliyim dostlar görenler div...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ah-u-efganim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Konuşuyor', 'gozlerin-konusuyor-yusuf-onder-bahceci-srrnz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vallahi birşey anlamadım ben bu işten,

Vallahi birşey anlamadım, bu gidişten,

Bir insan bu kadar mı ketum olur içten,

Senin gözlerin konuşuyor dilin susuyor. 

Susma hakkını mı kullanıyorsun bileyim,

Bana bir şeyler desen ben onu bileyim,

Bari çek git de de buralardan gideyim,

Senin gözlerin konuşuyor dilin susuyor.

Hakim, savcı olsam affederdim vallahi,

Yâ ben seni çok sevmişim inan vallahi,

Yemin etmek iyi değildir derim ki tillahi,

Senin gözlerin konuşuyor dilin susuyor.

Ben sana böyle sitemler ediyorum ama,

Benimde kâlbim konuşuyor diyorum ha,

İkimizde birbirini bulmuş ne olursun anla,

Sen gözlerle ben kâlbiyle konuşuyor ha...', 'Vallahi birşey anlamadım ben bu işten, Vallahi birşey anlamadım, bu gidişten, Bir insan bu kadar mı ketum olur içten, Senin gözlerin konuşuy...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-konusuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorum', 'agliyorum-serkan-karabulut-g53tw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlıyorum,

Bütün  husumetini gece sanki  salmış.

Kalbim sızılar,

Baktıkça resmimize.

Ben senin kolunda sen benim yanımda.

Deniz coşkulu maviydi. 

Donuk şimdi resimlerde.

Ah içmeli

Sarhoş olmalı

Bu gece

Yitirip dünü

Bir de yarına içmeli', 'Ağlıyorum, Bütün  husumetini gece sanki  salmış. Kalbim sızılar, Baktıkça resmimize. Ben senin kolunda sen benim yanımda. Deniz coşkulu mavi...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/agliyorum-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-faruk-gokbulut-q8euo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aynalar, sanmayın sizdeki aksim benim; 

Aşkın büyüsüne kapıldım kelepçelendim! 

Umulmaz bir anda çıktınız karşıma

Zehir kattınız bal sandığım aşıma

Yüreğimde her çizgi ayrı bir imza

Benmişim kendime en büyük ceza

Ey billur güzel, dur, öyle deme

Unutma kurulur birgün yüce mahkeme

Nur topu günlerimin kanına girdin

Yedim kendimi sevdan ile, bitirdim

Biter mi, sevdana indirsem kepenk:

Gözyaşı döksem, seylaplara denk? 

Gelemem zira aynalar yolumu kesti

Bekleme, geldi geçti, o bir hevesti

11 ŞUBAT 2004

Saat:  05:42

Ş.URFA', 'Aynalar, sanmayın sizdeki aksim benim;  Aşkın büyüsüne kapıldım kelepçelendim!  Umulmaz bir anda çıktınız karşıma Zehir kattınız bal sandığı...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aynalar-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Gülüme...', 'sevda-gulume-faruk-gokbulut-lekyu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne de zormuş can çekişmek akrebin kıskacında

Ne büyük zillet unutulmak sevda yamacında

ÖZLEM''e dair ne varsa gitsin rüzgarın kanadında

Ne güzelmiş hayatı yaşamak en güzel tadında

**Cana Kasdeden Sevda Gülüne...**

17 HAZİRAN 2004

Saat:  17:24

Ş.URFA', 'Ne de zormuş can çekişmek akrebin kıskacında Ne büyük zillet unutulmak sevda yamacında ÖZLEM''e dair ne varsa gitsin rüzgarın kanadında Ne gü...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevda-gulume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemim', 'ozlemim-faruk-gokbulut-ex0gm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bağrıma gözyaşın damlıyor şimdi

Sen ağlıyorsun içimde Özlemim

Kalbimde ırmaklar çağlıyor şimdi

Sen akıyorsun içime Özlemim

Esmer gecelere doğan gözlerin

Toroslarıma yağan kar gözlerin

İçimi ısıtır baldan tatlı sözlerin

Kalbimde yerin değişmeyecek senin

**Hasret kokan çiçeğime, ÖZLEM''e dair...**

21 HAZİRAN 2004

Saat:  23:45

Ş.URFA', 'Bağrıma gözyaşın damlıyor şimdi Sen ağlıyorsun içimde Özlemim Kalbimde ırmaklar çağlıyor şimdi Sen akıyorsun içime Özlemim Esmer gecelere do...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlemim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda ateşinden çeken olunca', 'sevda-atesinden-ceken-olunca-mikdat-bal-1nmbc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevda ateşinden çeken olunca

Yolunda dönecek bir kulu bekler

Güller bitiverir diken olunca

Dalında konacak bülbülü bekler

Düşmesin bir seven yârinden ayrı

Hayatın ölümün kalmaz ki hayrı

Dört omuzda gitmek istemez gayri

Salında binecek düldülü bekler

İradesi biter kendini aşar

Bir mecnun misali yollara düşer

Aşkın ateşinde yanar da pişer

Yolunda yanacak bir çölü bekler

Mikdatî der aşka dayanmaz bu can

Sevdaya denk gelmez ne şöhret ne şan

Vuslattan ümidi kesildiği an

Dilinde anacak bir ölü bekler', 'Sevda ateşinden çeken olunca Yolunda dönecek bir kulu bekler Güller bitiverir diken olunca Dalında konacak bülbülü bekler Düşmesin bir seven...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevda-atesinden-ceken-olunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalı Kal Ha!', 'sevdali-kal-ha-faruk-gokbulut-n647l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sıfır insan olmalısın! 

Yani..yani bir adım sonra durmalısın

Durmalısın...

Çünkü eksilerini tamamlamış

Artılara yol alıyor olmalısın

Sonra çocuk olmalısın

Denge ve dengesizliğin kesişiminde

Çocuk olmalısın

Sevdalısın..sevdalı olmalısın

Sonra sevmelisin

Yani kalbini açmalısın

Yani etrafına umut saçmalısın

Kalbinde tüm insanlığa yer bulmalı

Kaybetmekten korkmalı

Kazanan olmalısın

Sevdalısın sevdalı...

Ve sonra yüreğine koşmalısın

Yüreğinin sokaklarını dolaşmalısın

Tüm engellerini aşmalı

Sarmaş dolaş olmalı

Kollarınla tüm güzellikleri sarmalısın

Sen...Sen sevdalısın

Sevdan kor olmalı

Yüreğinde dur olmalı

Ve hep orada kalmalı

Yüreğinin göklerinde yıldızlar olmalı

Ve o Var olana selam salmalı

Ah! Sevdam hep böyle kalmalı

Kalbim! Kalbim sen ağlama

Ne olur gözlerimi dağlama

Ve sonra dehlizlerim

Yüreğimin okyanuslarında

Kabaran dalgaları sakla

Aman ha sen bîkes olma

Hep böyle sevdalı kal ha! ! ! 

18 EKİM 1998

İSTANBUL', 'Sıfır insan olmalısın!  Yani..yani bir adım sonra durmalısın Durmalısın... Çünkü eksilerini tamamlamış Artılara yol alıyor olmalısın Sonra ç...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sevdali-kal-ha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoşuyum Ben', 'sarhosuyum-ben-faruk-gokbulut-tctr3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir âhıyla yandım yarin

Bir bûsesine kandım yarin

Yüreğime düşen o ak korun

Sarhoşuyum ben

Yarin kokusunu andıran yelin 

Eser gelir uzaktan narin ve serin

Kamere rahmet okutan o nurun

Sarhoşuyum ben

Hayalinin fecri ile bîtabım

Hasretinden harabım türabım

Sevda çöllerindeki o serabın

Sarhoşuyum ben

18 MAYIS 2001

Saat:  12:00

MALATYA(Bnd.K.lığı)', 'Bir âhıyla yandım yarin Bir bûsesine kandım yarin Yüreğime düşen o ak korun Sarhoşuyum ben Yarin kokusunu andıran yelin  Eser gelir uzaktan ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Gökbulut']::text[], 8.5, '{"poet":"Faruk Gökbulut","poet_slug":"faruk-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sarhosuyum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama', 'aglama-serkan-sekban-p7pcz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yarim çatma hiç kaşını

Eğme sakın hiç başını

Şu üç günlük dünya için

Dökme sakın gözyaşını

Ne isyan et ne kız bana

Dua et hep yaradana

Dizlerine vura vura

Dökme sakın gözyaşını

08 02 2006', 'Yarim çatma hiç kaşını Eğme sakın hiç başını Şu üç günlük dünya için Dökme sakın gözyaşını Ne isyan et ne kız bana Dua et hep yaradana Dizle...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aglama-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak istiyorum', 'unutmak-istiyorum-mihrican-karaca-vk3o6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bütün geçmişine çizgi çekmek,

İçip içip kendimden geçmek

Doyduğum yerden de göçmek,

Bir anlık olsun unutmak istiyorum.

Öyle yer etmişsinki beynimde,

Unutmak mümkünmü ki söyle.

Gidenler gelmez oldu bundan böyle,

Biranlık olsun,unutmak istiyorum.

Sözlerimiz vardı geleceğe dair,

Sen ettin Mihrican''ı böyle şair.

Bir daha hatırlamamakcasına,

Sonsuza dek unutmak istiyorum.', 'Bütün geçmişine çizgi çekmek, İçip içip kendimden geçmek Doyduğum yerden de göçmek, Bir anlık olsun unutmak istiyorum. Öyle yer etmişsinki b...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutmak-istiyorum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hata Sende Kardeşim', 'hata-sende-kardesim-yusuf-onder-bahceci-melt7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O ben seni sevmiyorum demedi ki,

Hayır sana gelmiyorum demedi ki,

Senin ne çok sevdiğini bilmedi ki,

Hata sende kardeşim hata sende.

Tutacaktın sen öylece ellerinden,

Bakacıktan gözlerine derinlerden,

İşte o zaman görürdüm ben, ben,

Hata sende kardeşim hata sende.

Boşuna uğraşma giden gelmiyor,

Gelse bile yüzü, hiç de gülmüyor,

Suçlu gibi duruyor, evet demiyor,

Hata sende kardeşim hata sende.

Aklın başına çok sonra mı geliyor,

Sen bilmezmisin güller tez soluyor,

Çok sevmişim kâlbim harap oluyor,

Hata sende kardeşim hata sende...', 'O ben seni sevmiyorum demedi ki, Hayır sana gelmiyorum demedi ki, Senin ne çok sevdiğini bilmedi ki, Hata sende kardeşim hata sende. Tutacak...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hata-sende-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaza Dokunamadılar', 'beyaza-dokunamadilar-rukiye-ozkat-ctdct', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasılda çabuk geçiverirdi neşeli günlerimiz,

Tadı kalırdı yüreğimizde; 

Anlayamazdık..

Ve hemen başlayıverirdi fırtınalı günler,

Güneşimizi kıskanır yağan yağmur taneleri

Gözyaşımıza karışırdı birden,

Ağlayamazdık..

Gökkuşağımızı kıskandılar bizden,

Renklerimizi alıp,siyaha boyadılar.

Bilmedilerki beyaz özüydü renklerin

Beyaza dokunamadılar...', 'Nasılda çabuk geçiverirdi neşeli günlerimiz, Tadı kalırdı yüreğimizde;  Anlayamazdık.. Ve hemen başlayıverirdi fırtınalı günler, Güneşimizi ...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Özkat']::text[], 8.5, '{"poet":"Rukiye Özkat","poet_slug":"rukiye-ozkat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/beyaza-dokunamadilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SANTEK - Damlalar..', 'santek-damlalar-mehmet-coban-hjf74', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözüm düşer

Damla, damla

Taşlaşmış,

Tüm yüreklere

Düşüncelere

Yasalara, örflere

Hiç durmadan

Sözüm düşer 

Damla, damla

Taş eriyene

Toz olup ufalanana

Söz yerini bulanana…

13.02.2006-İzmir', 'Sözüm düşer Damla, damla Taşlaşmış, Tüm yüreklere Düşüncelere Yasalara, örflere Hiç durmadan Sözüm düşer  Damla, damla Taş eriyene Toz olup ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/santek-damlalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SANTEK - Kavşak', 'santek-kavsak-mehmet-coban-u627p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dur,

Dön arkana 

Geldiğin yola bak

Yanlışlıkla, 

Aynı yola girmeden

Pişmanlık ateşine düşmeden

Dolapçı beygirine dönmeden

Kavşaktasın,

Geçmişi geleceği hesaplamalısın

Her an yeni bir karardasın! ....

Yürü, 

Eskinin yanlışlarından uzak

Her an yenilenmiş olarak! ....

13.02.2006-İzmir', 'Dur, Dön arkana  Geldiğin yola bak Yanlışlıkla,  Aynı yola girmeden Pişmanlık ateşine düşmeden Dolapçı beygirine dönmeden Kavşaktasın, Geçmi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/santek-kavsak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-rukiye-ozkat-1buk2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pencere kenarı bir şehir,

Mum ışığı,

Yıldızlar yakındı.

Karşımda,hemen elimin uzandığı sen uzaktın.

Dağlar deniz olmuştu.

Aklımda eski bir fotoğraf.

Ve ben salıverdim gözyaşlarımı içime..

Uyudum!', 'Pencere kenarı bir şehir, Mum ışığı, Yıldızlar yakındı. Karşımda,hemen elimin uzandığı sen uzaktın. Dağlar deniz olmuştu. Aklımda eski bir f...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Özkat']::text[], 8.5, '{"poet":"Rukiye Özkat","poet_slug":"rukiye-ozkat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gece-211-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anı,', 'ani-mehmet-coban-rj42r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir anı yaşadım davette

Benliğim hala hayrette

Nazım yazdı, 

En güzel duygularıyla hasreti

Bestekâr besteledi

O güzelim sözleri

Kapitalistler

Müzik ve söz eşliğinde dans etti

Kimse umursamadı

Ne Nazım''ı, ne müziği

Yaşadılar hoyratça zenginliği

13.02.2006-İzmir', 'Bir anı yaşadım davette Benliğim hala hayrette Nazım yazdı,  En güzel duygularıyla hasreti Bestekâr besteledi O güzelim sözleri Kapitalistle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ani-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Dönme Geri', 'git-donme-geri-i-brahim-sarihan-uhujr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'G encecik yaşımda, çürüttün ömrümü

İ stesen de, çiğneyemem verdiğim sözümü

T am seninim derken, incittin şu gönlümü

D üşle gerçeği karıştırmışım sayende

Ö yle mahsun mahsun bakma sakın yüzüme

N asıl olur bırakmak, böyle delice sevip de

M anasız, inancım kalmadı artık sözlerine

E n güzel günlerim, boşa geçmiş seninle

G it, dönme sakın geriye bir daha asla

E llerim boş kalsın, kalmadım yalan aşkına

R iyakarmış sevgin, yeni anladım acırım sana

İ lk kez, sana çılgınca tutulmuştum ben oysa

(Hakkâri, 29 Ekim 2003)', 'G encecik yaşımda, çürüttün ömrümü İ stesen de, çiğneyemem verdiğim sözümü T am seninim derken, incittin şu gönlümü D üşle gerçeği karıştırm...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıhan']::text[], 8.5, '{"poet":"İbrahim Sarıhan","poet_slug":"i-brahim-sarihan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/git-donme-geri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SANTEK - Çöplük...', 'santek-copluk-mehmet-coban-iushq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aldım okudum 

Gördüm duydum

Bir sürü bilgi

Kötüleri iyileri

Doğruları eğrileri

Beynimin hazineleri

Ama arada bir 

Temizlik gerek

Yanlışlardan

Arınmak gerek

Lüzumsuzları 

Atmak gerek

Beynimiz çöplük 

Olmasa gerek! …

13.02.2006-İzmir', 'Aldım okudum  Gördüm duydum Bir sürü bilgi Kötüleri iyileri Doğruları eğrileri Beynimin hazineleri Ama arada bir  Temizlik gerek Yanlışlarda...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/santek-copluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer Günü', 'sevgililer-gunu-i-sa-erkol-tp1xd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gün sevgililer günü

Bu gün felekten bir gün çalacağım

Ve bu gün

Farklı bir gün yaşayacağım

Ne adını anacağım

Ne maziyi hatırlayacağım

Her zaman körkütük sarhoş olduğum meyhaneye uğramayacağım

Son bir kadeh daha içebilmek için hayatımın zehirinden

Meyhaneciyle de dalaşmayacağım

Kendimi sokaklara bırakıp

Zemherinin ayazında,

Isınmak için bir köşe aramayacağım

Ay ışığına karışmayacağım esrarlı sokaklarda

Sabahlara dek hayalini de kucaklamayacağım

Koyup başımı yastığa

Kabusların girdabında çırpınmadan

Derin bir uykuya dalacağım

Şiir de yazmayacağım en derin kelimelerden

Beddualar kirletmeyecek dilimi

Hüzün şairi diyorlar; 

Varsın desinler

Ama bu gün hüzünü de yazmayacağım

Bu gün sevgililer günü

Sevgililer günün kutlu olsun bitanem

Seni hala çok seviyorum.', 'Bu gün sevgililer günü Bu gün felekten bir gün çalacağım Ve bu gün Farklı bir gün yaşayacağım Ne adını anacağım Ne maziyi hatırlayacağım Her...', ARRAY['Türk Edebiyatı','Şiir','İsa Erkol']::text[], 8.5, '{"poet":"İsa Erkol","poet_slug":"i-sa-erkol","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/font-face-tahoma-font-size-4-pt-color-black-sevgililer-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Verselerde firarımı', 'verselerde-firarimi-serkan-sekban-z3dm8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim nazlı güzel yarim 

Bu günde gelmedimi

Bir ay oldu haber yok 

Bir mektup göndermedimi

Yarim başım duman duman 

Sen gelmezsen katlanamam

Sana son sözüm olsun 

Sen gelmezsen ben kaçıcam

Yıkarım bu duvarları

Yakarım ben bu hayatı

Umurumda bile değil

Verselerde firarımı

08 02 2006', 'Benim nazlı güzel yarim  Bu günde gelmedimi Bir ay oldu haber yok  Bir mektup göndermedimi Yarim başım duman duman  Sen gelmezsen katlanamam...', ARRAY['Türk Edebiyatı','Şiir','Serkan Sekban']::text[], 8.5, '{"poet":"Serkan Sekban","poet_slug":"serkan-sekban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/verselerde-firarimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın Adıydın Sen', 'sevdanin-adiydin-sen-figen-akyoler-5k6kh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdanın adıydın SEN

İçimde açan her çiçek

Gökyüzüme doğan güneş

İçimi aydınlatan ses...

Yeniden doğuşumdun

Gülüşüm,paylaşımım

Ezgilerimin nefesiydin

Yaşama atılan her adım...

Sevgiyi koklayışımdın

Yüzüne dokunuşum

Bittiğini her sandığımda

Yeniden varoluşum...

Şimdi bitişim misin? 

Hayatımdan gidişinin sesi

Vurgunların en bitimsizi

Dibe vuruşum musun?', 'Sevdanın adıydın SEN İçimde açan her çiçek Gökyüzüme doğan güneş İçimi aydınlatan ses... Yeniden doğuşumdun Gülüşüm,paylaşımım Ezgilerimin n...', ARRAY['Türk Edebiyatı','Şiir','Figen Akyoler']::text[], 8.5, '{"poet":"Figen Akyoler","poet_slug":"figen-akyoler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdanin-adiydin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur-1', 'yagmur-1-enes-engin-aoq3h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yagmurun inişine saklanan damla,

bir bulutun acisini gömer topraga.

Bin aciyla çatlamiş toprak, bir acıyla susar

bir damlanin sakladiği bulutu soluklar..

Yagmur..dert ortagim.

Ne sen saklayabilirsin içindeki acıyı

ne de ben; seher vaktine kadar akacak bu yaşları..

Biz; birbirine muhtaç iki dost! 

Bir sen dolarsin geceye

bir de ben; senin dolduramadigin yerlere.. 

Bir sen yağarsın amansızca üstüme, 

bir de ben; aman vermediğin zayif yüregime...', 'Yagmurun inişine saklanan damla, bir bulutun acisini gömer topraga. Bin aciyla çatlamiş toprak, bir acıyla susar bir damlanin sakladiği bulu...', ARRAY['Türk Edebiyatı','Şiir','Enes Engin']::text[], 8.5, '{"poet":"Enes Engin","poet_slug":"enes-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmur-1-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla damla', 'damla-damla-levent-i-skenderoglu-6use7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğim; 

Damla damla kan

Ay ışığı

Anka kuşu

Kurbanlık koç

Ala gözlü ceylan

Ve çiçeklerle uçuşup duran

Aklımı başımdan alan

Bir peri kızı

Peri kızı; 

Damla damla yağmur

Akşam alacası

Lacivert gökyüzü

Gökyüzünde yıldızlardan bir saray

Sarayda buzdan alevler

Alevler; 

Damla Damla nefret

Şeytanın gözü

Tırnaksız katırlar

Katırlarda pala pala yük

Yükler ölümle harman

Harman; 

Damla damla umut

Parlayan kaynar kazanda dudak

Dudaklarda buse buse aşk

Aşk; 

Damla damla sevgi

Susayan,çatlayan bir toprak

Toprağın bağrında ben

Yüreğim çürümeye dirençli

Üzerimde buket buket kır çiçekleri

Kır çiçekleri; 

Damla damla sen…….

…………….

2003', 'Yüreğim;  Damla damla kan Ay ışığı Anka kuşu Kurbanlık koç Ala gözlü ceylan Ve çiçeklerle uçuşup duran Aklımı başımdan alan Bir peri kızı Pe...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/damla-damla-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinliyorum İstanbul', 'dinliyorum-i-stanbul-turan-tuncer-jxc5j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'DİNLİYORUM  İSTANBUL

Beni! ! 

Kumkapı''da meyhanelerde,

Anasonlu dost sohbetlerine.

Çamlıca''nın ağaç altlarında,

Rüzgâra sarılan mangal dumanlarına.

............................................................Anlat..

Bana! 

Martıları anlat, çığlık çığlığa,

Gemileri anlat, memur bandıralı

Simit kırıkları peşinde ki,

Güvertenin kaçak yolcularını.

.............................................Anlat...

Yamalı paltosunun deliğinden,

İstanbul''u dinleyen bir garip şairi.

Sahlep üstündeki tarçın kokusunu,

Fatih''in toplarını, ramazan atışlarındaki.

Fıkara çadırında, tok oturup aç kalkanları,

Köprüde insanlara tranvay satanları

Adını bilmedeği birine sarılıpta yatanları

Kaldırımda, balık ekmek yanında rakıyı

...............................................................Anlat...

Arada birde beni anlat, yeni yetme şairlere

Her dizede şarhoş oluşumu, yeni aşklarla

Kandilli''de bir küçük sandalda fasılları

Kalamış''ta, yakamozlarla sevişmelerimizi

Sarayburnu''nun bize tafrasını anlat

Saray çocuğu Topkapı''da üstü açık açlığımızı

Bir şarapla coştuğumuzu dizelerde de

Taş üstünde, baş yar dizinde yattığımızı 

.................................................................Anlat..

Ah be İstanbul, sen ne vefasızmışsın

Adımızı bile unutmuşsun, altı üstü 15 yıl

Gemilerin bile değişmiş, martılar yabancı

El olmak ne zormuş, ah be İstanbul

Unutmak istesemde, unutulmazmışsın

..............................................................Anladım...

13 Şubat 2006 /İst

Alkadraz_Kuşçusu', 'DİNLİYORUM  İSTANBUL Beni! !  Kumkapı''da meyhanelerde, Anasonlu dost sohbetlerine. Çamlıca''nın ağaç altlarında, Rüzgâra sarılan mangal duman...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/dinliyorum-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ü Ekber Dağları', 'allah-u-ekber-daglari-lokman-hamitoglu-894b7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ALLAHÜ EKBER DAĞLARI

		                Hamit Dedemin

			      ve tüm Sarıkamış Şehitlerinin 

                                                                             Anısına

              I

 Dedemin babasıydı

Abileriydi 

Başları dik alınları ak gururla savaşa gidiyorlardı

Rus harbine çok asker lazımdı

Dedemin eli silah tutmadığından orduya almamışlardı

Oysa dedemde gitmek istemiş Sarıkamış’a 

Oooy Sarıkamış

Allahü Ekber dağlarına oooy 

O dağlarda kim donmaya inat edebilirdi? 

Kim donmazda geri dönebilirdi? .. 

Oy havar! oy lımın ! oy lımın! 

Allahü Ekber dağlarında boylarca kar var

Garibim neferler kazık (!)  çakılacaklar

Kimsenin elbisesi yok ki üzerinde 

Isınmak için yiyecek şekerleri olsun ceplerinde

Olsun varsın elbise olmasın

Varsın şekerde olmasın

Onlar vatan demiş... Toprak demiş... 

Onlar şehitlik en büyük şeref demiş

Onlar bazı ecnebi kadınlarına meftun olanları bilmemiş

Onlar vatan için mi? 

Yahut bazı vatan severlerin (!)  altın sevgisi için mi? 

Onlar... Ceddim... Atalarım... 

Ne için kazık kesilmiş? 

Tabi ki vatan (!)  için! .. 

Oooy Bavo! Oooy Bao! Oooy oy

Ba’o’m köyde yalnız kalmış yaşlı anacığıyla

Gözlerini hep kapıya dikmişler

Yollara

Her geçen günle

Güneşli günleri kararmış

Karanlık fırtınalar kopmaya başlamış

Hep bir ışık aramış dedem

Hep iyi bir haber

Ama iyi bir haber yok

Mutluluklar garba uğramış

Mutluluğun yerini 

Hüzünler, elemler, özlemler almış

Köye geri dönmüş bir kaç vatan satar

Seferberlik ertesi

Dedem durumu öğrenince 

Yol gözlemekten vaz geçmiş

Çünkü dedemin abileri ve babası 

VATANSEVERLERDİ

Geçmez olmuş kış mevsiminin kısa günleri

Asırlara dönmüş uzun kış geceleri

Hayalleri ellerinde kalmış dedemin

Ümitleri lalü ebkem olmuş

Ama veren O alacak olanda O ‘dur

“ İnna lillahi ve inna ileyhi raciun

Diyecek dedemle annesi

Çünkü onlar herşeyin Hakk Teâlâ’dan

Olduğuna inanıyorlar...

             II

Rus harbinden dönen yok

Bir kişi olsun dönmez mi? 

Bir eve kaç şehit düşer? 

Bir eve bir gazi düşmez mi? 

Ya Mustafa

Ya dedemin bir büyüğü Mustafa

Namzetli Mustafa

Dilriş Mustafa

Şimdi Mustafa’nın yavuklusu n’olacak? 

O garip 

O bikes

O reben ne olacak? 

Hani o reben düğünde ellerine kına yakacak

Başına yeşil yemeni takacaktı? 

Hani o garip ayağına kırmızı pabuç giyecek

Boynuna bir büyük ziynet takacaktı? 

Hani tüm bunlar olacaktı? ..

Oooy dilfikar nasıl dayanacaksın? 

Hangi mezarın başına gidip ağıt yakacaksın? 

Kimin için o ellerine kına yakabilirsin? 

Yoksa sende Allahü Ekber dağlarına mı çıkacaksın? 

Yoksa sende mi donacaksın? 

Yoksa vurulup şehit mi olacaksın? 

Oooy bikesi oy! ..

Karların bu gazabı unutulur mu? 

Beyazın bu gizli siyahlığı

Gizli kırmızılığı

Gizli düşmanlığı unutulur mu? 

Şimdi bu garip kar görünce nasıl dayanacak? 

Beyaz kar’a nasıl bakacak

Beyaz kar artık hasım! 

beyaz kar artık Rus’un! 

Beyaz kar artık zulüm! 

Diye - diye sabahlara kadar bağıracak

Yahut donmak için gidip karlara uzanacak

Oy reben! reben şimdi ne yapsın

Oy garibi anan öle

Oy garibi düşmanlar güle

Oy bikesi vayu vayu vay sana 

Oy bikesi hadi koş kör kurşuna! .. 

                III

Mahvolmuşum bu hadiseyi duyunca

Gözlerimden ağu - ağu kan akmış

Allahü Ekber dağlarına çıkıp

İki rekat namaz kılmışım

Secdeye saatlerce kapanmışım

Kur’an -ı Azimüşşan’dan Yasin -i Şerif -i okumuşum

Fatiha’lar İhlas’lar okumuşum

Yanaklarım, dudaklarım göz yaşlarımla tuzlanmış

Bedenim ceylanların gözleri gibi titremiş 

Yüreğim cehennem gibi yanmış, yanmış, yanmış! ..

Kaybolmuşum yoğun bir sisin içinde 

Savrulmuşum bir o yana bir bu yana

Sabahın seherinde kendimi bulmuşum

Allahü Ekber Dağlarında ki şehit benim! 

Benim ardım sıra dilharab bir sevda bırakan 

Benim peşimden ağıt yaktıran

İki kaburganın arasında ki özlem benim

Benim toprağını namusu bilen

Şehitlerin elinde ki mavzer benim 

Benim şehitlerin tırnağına halel getirmeyen 

Aç susuz giyeceksiz şekersiz savaşan benim 

Ben o şehit edilen Memed’im

Mustafa’yım

Ahmed’im...

                                        Lokman Hamitoğlu', 'ALLAHÜ EKBER DAĞLARI 		                Hamit Dedemin 			      ve tüm Sarıkamış Şehitlerinin                                                 ...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":125,"source_url":"https://www.antoloji.com/allah-u-ekber-daglari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen Arıyorum', 'kardelen-ariyorum-umut-gungor-o54u9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Keklik inmiş pınar''a,

Seni yazdım çınar''a,

İsterim yüreğinde,

Yazıver bir kenara.

Kardelen arıyorum,

Koşa koşa dağlarda,

Hep seni gözlüyorum,

Gezdiğimiz bağlarda.

Özledim gülüşünü,

Gönlü hasret sarıyor,

Bal dudak öpüşünü,

Yine yanak arıyor.

Seraplar görüyorum,

Uykusuz gecelerde,

Şiir''e örüyorum,

Ağlayıp hecelerde.

Güneş benden aralı,

Mehtapla kavgalıyım,

Yürek derin yaralı,

Kalbimden yaralıyım.

Bir nefes yaşıyorum,

Ayaktayım sevginle,

Yinede koşuyorum,

Yıkılmadan sevginle.', 'Keklik inmiş pınar''a, Seni yazdım çınar''a, İsterim yüreğinde, Yazıver bir kenara. Kardelen arıyorum, Koşa koşa dağlarda, Hep seni gözlüyorum...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kardelen-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın Yeri Bu Dünya', 'yangin-yeri-bu-dunya-tunahan-ermihan-42im2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elinde kalem çiziktiriyorsun aşkı

Gözlerinde utangaç firari bakışlar

Yanaklarında pembe hayallerin aksi

Ben sana sevdalıyım dedikçe sessiz bir gülümseme

İçten bir titreme bedeninde

Ellerin değdiğinde ellerime

Yangın yeri bu dünya

Seviyorum desem ya sana

Sende çiziktirsen ya askı

Yazıp yazıp yırttığın kağıtlara', 'Elinde kalem çiziktiriyorsun aşkı Gözlerinde utangaç firari bakışlar Yanaklarında pembe hayallerin aksi Ben sana sevdalıyım dedikçe sessiz b...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yangin-yeri-bu-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peygamber Sancağı', 'peygamber-sancagi-tunahan-ermihan-o2rk7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yumdum gözlerimi çirkefliklerine yalan dünya

Sözümüz yalan oldu özümüze düşman dünya…

Günbatımında hayran kalırdım her anın seyrine

Makyajıymış leşlerinin, günahlarının gecen dünya…

İyi niyetlerimiz ve düşüncelerimiz vardı yaşanacak

Katledilen Müslümanlar senden değil miydi dünya? 

Ucuza sattın inançlarımızı gözlerimizdeki yaşları

Sende benim gibi fanisin sende sana kalmayacaksın dünya….

Nefes aldıkça her bir beden tarihi sende saklı

Bizi tarihimize düşman ettiren dünya…

Adem’le (AS)  Havva’dan kardeştik birbirimize

Kardeş kanını kardeşe döktüren dünya…

Şimdi derdim söyleyeyim dinle ey zalim dünya

Peygamberime dil uzatanda girecek bir gün o mezara…

Mahşerde bir tutam gölge ararken sana kananlar

Peygamberimin sancağında yer kalmayacak onlara dünya…', 'Yumdum gözlerimi çirkefliklerine yalan dünya Sözümüz yalan oldu özümüze düşman dünya… Günbatımında hayran kalırdım her anın seyrine Makyajıy...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/peygamber-sancagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi''ki Aşk''lar', 'simdi-ki-ask-lar-hasan-uzel-ujovx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevecek yar kalmamış şu koca yeryüzünde

Hayallerde mi sevgili yaratıp sevelim

Ne zaman aşka yelken açsak

Ertesi gün ayrılıklara mı gelelim

Zaten şimdi ki aşklar yalan dolan

Her hafta başka başka heyecan

Aşık olasıda gelmiyor insanın ya

Gönül bu aşk ister can canan

Sormalı aşıklara aşkın anlamını

El ele tutuşunca titrer mi canları

Gözler ağlamayı öğrenir mi acaba

Diller sustuğunda yürekler dillenir mi

Zaten şimdi ki aşklar yalan dolan

Her hafta başka başka heyecan

Sözler yalan yaşlar sahte

Sana bakar başkasını düşünür kahpe

Bu zaman da aşk yatağa kadar mış

Ertesi gün satılan bir mal mış

Bunun adı ne zamandır aşk mış

Ben böyle aşkın ıstırabına', 'Sevecek yar kalmamış şu koca yeryüzünde Hayallerde mi sevgili yaratıp sevelim Ne zaman aşka yelken açsak Ertesi gün ayrılıklara mı gelelim Z...', ARRAY['Türk Edebiyatı','Şiir','Hasan Uzel']::text[], 8.5, '{"poet":"Hasan Uzel","poet_slug":"hasan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/simdi-ki-ask-lar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyimsin', 'herseyimsin-ahmet-dalkiz-07xra', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herşeyimsin

Sana ömrümden ömür

Sen bana heyacan

Ben sana gönlümü verdim

Çaresizliklere direndim

Bütün kavgalara gönüllendim

Herşeyimsin

Bir kedi gigi

Sevdiğine sığınıp

Dağ başında bir evde

Sahipsiz bir geceyi

Paylaşabilmekmiş hayat

Ve gecenin sabahına uyanmakmış

Senin kollarında senin kokunla

Hissedebilmek seninle güzelmiş

Yüregimin derinlerinde 

Kımıl kımıl birşeyleri

Sana ömrümden ömür

Sen bana heyacan

Ben sana gönlümü verdim', 'Herşeyimsin Sana ömrümden ömür Sen bana heyacan Ben sana gönlümü verdim Çaresizliklere direndim Bütün kavgalara gönüllendim Herşeyimsin Bir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Dalkiz']::text[], 8.5, '{"poet":"Ahmet Dalkiz","poet_slug":"ahmet-dalkiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/herseyimsin-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılsın deniz', 'kirilsin-deniz-sefer-yesilyurt-yq43k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir çiğ damlası düşer ansızın 

büyür delicesine bebekler 

kazar toprağı köstebek

bir kelebek olur kozasında larva

şaşırır yolunu şaşkın karınca 

aşkın girdabında 

bir yürek atar yarına 

gel işte 

kırılsın deniz 

küsürat olsun hesaptan kalan 

beni senle yargıla ki 

kararın infaz olsun…', 'bir çiğ damlası düşer ansızın  büyür delicesine bebekler  kazar toprağı köstebek bir kelebek olur kozasında larva şaşırır yolunu şaşkın karı...', ARRAY['Türk Edebiyatı','Şiir','Sefer Yeşilyurt']::text[], 8.5, '{"poet":"Sefer Yeşilyurt","poet_slug":"sefer-yesilyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kirilsin-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi Doğarken Farketmiyorum', 'gunesi-dogarken-farketmiyorum-umut-gungor-w3e2v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkımız yel''e gitti bak ay yüzlüm,

Kardelen''ler küstü bize gelmiyor,

Kırıldı dallar''ımız bak ay yüzlüm,

Yapraklar meyva''yı artık germiyor.

Ruhumu perdeliyor kara bulutlar,

Güneşi doğarken farketmiyorum,

Kafdağı''nı aştı çoktan umutlar,

Yine de yaşarken kahretmiyorum.

Artık mehtapta balkona koşmak yok! ...

Kapattım sıkıca tüm perdeleri,

Şarkı''larda türkü''lerde coşmak yok! ...

Düşürdüm dilimden tüm nağme''leri.', 'Aşkımız yel''e gitti bak ay yüzlüm, Kardelen''ler küstü bize gelmiyor, Kırıldı dallar''ımız bak ay yüzlüm, Yapraklar meyva''yı artık germiyor. R...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunesi-dogarken-farketmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEVDAM ÜsTÜNE', 'sevdam-ustune-levent-i-skenderoglu-bkqxm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tutku ki

Yaraların kanadığı zaman 

Sustuğum

Tutku ki

Bıçak sırtı iniltiler içinde

Geceyi vurduğum

Tutku ki

Her unuttuğumda 

Aklımda kalan

Sofralık zeytine uzandığım

Aldığım 

Kanattığım 

Sardığım

Sevgili üstüne şiir yazdığım

Sapan ardı kuş mezarı kazdığım

Sarılınca dağ olan 

Söndürünce kor

Yalnızlığına sığındığım

Dara her düştüğümde 

İncir çekirdeği kadar 

Nefesinin yettiği

Yanları üstüne devrilen dağların

Mor süslü mavi menekşesi

Hazanım 

Kızgınlığım 

Susamışlığım

Gidince sabır kokan

Yüreğimde

Yıkık bir ev bırakan ki

Ben dağlarla boy ölçüşen 

Bir çuvaldızım

Sen ki….

Tutku ki….

……..

2002', 'Tutku ki Yaraların kanadığı zaman  Sustuğum Tutku ki Bıçak sırtı iniltiler içinde Geceyi vurduğum Tutku ki Her unuttuğumda  Aklımda kalan So...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sevdam-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-ahmet-dalkiz-qdghn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrılık zor demedim

Alışkanlıklarım var benim

Gelişinden gülüşünden vazgeçemem

Vazgeçemem gözlerinden

Korkularım var benim

Issız kalır gecelerim

En zor alışkanlığımsın

Vazgeçemem gözlerinden

Sana git diyemem

Hasretini çeker yüreğim

Sensizlikte zor demedim

Vazgeçemem gözlerinden

Tutkularım var benim

Ne tutkularımdan ne senden

Ben yinede

Vazgeçemem gözlerinden

Sigaramın nikotinisin

Zararlı ama o kadarda hoş

En zor alışkanlığımsın tiryakinim

Vazgeçemem gözlerinden', 'Ayrılık zor demedim Alışkanlıklarım var benim Gelişinden gülüşünden vazgeçemem Vazgeçemem gözlerinden Korkularım var benim Issız kalır gecel...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Dalkiz']::text[], 8.5, '{"poet":"Ahmet Dalkiz","poet_slug":"ahmet-dalkiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozlerin-223-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gören Okuyandan Farklıdır (Düz yazı)', 'goren-okuyandan-farklidir-duz-yazi-ali-kilic-kakiz-41nma', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanoğlu etki alanında kalmaya kabiliyetli ve yetenekli bir varlık.İnsan kendisinde ki duygusal kuvvet ve kudretini bilememektedir. İnsanların psikolojik yapılarını ve anlama kabiliyetlerini dikkate alarak hitap etmeli, yazmalı, halkın fikirlerini yoğurmak harmanlamak gerekir.

          Duygular akıldan daha fazla müyesser olduğu için gezen ve gören, okuyandan farklıdır.... müzik dinlemek, veya görüp gezdikçe insanın duygusallığı artar, Kur''an dinledikçe daha da artar. O zaman insan tabiatın diliyle doğanın simgeleriyle konuşmaya koyulur.

            Duygusallığın kesilmemesi için tekrarın önemi büyüktür.Şiir dünyasın da taklit insanı hiç bir sağlıklı bilgiye ulaştırmaz. İnsan kendi tahmin ve kanaatine dayanarak akıl ve kalpleri hayran bırakan bağış kabul etmeyen ilahi kaynaklı, doğrudan bilgiye dayanarak kendine yol çizmelidir.Meşhur edebiyatçılarımız şairlerimiz vardır.bu konuya onlar daha vakıftırlar,çünkü işi ehline arz etmek aklın ve hikmetin gereğidir.

Lessines / 2000', 'İnsanoğlu etki alanında kalmaya kabiliyetli ve yetenekli bir varlık.İnsan kendisinde ki duygusal kuvvet ve kudretini bilememektedir. İnsanla...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/goren-okuyandan-farklidir-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğuda Bizimdir Batıda Bizim', 'doguda-bizimdir-batida-bizim-seyfet-bozcali-iflo8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayelleri kursağında kalacak,

Doğuda bizimdir,batıda bizim,

Bizler şahlandıkça, onlar üzülecek,

Kuzeyde bizimdir,güneyde bizim...

Bu ülke Türk''ündür öyle kalacak,

Kültür istilası mağlup olacak,

Her köşede mehter marşı çalacak,

Doğuda bizimdir,batıda bizim...

Bu yadigar ülke parçalanamaz,

Omuz omuzadır,Azeri,kürt,laz,

Bu soysuzlar geçmişten hiç ders almaz,

Kuzeyde bizimdir,güneyde bizim...

Kimseye ne uşak ne aletiz biz,

Yediden yetmişe tek yüreğiz biz,

Mozaik kültürle,tek devletiz biz,

Doğuda bizimdir,batıda bizim...

Seyfet der yeni bir güneş doğacak,

Bir çok alçak ülke muhtaç olacak,

Allah''ın izniyle yüzler gülecek,

Kuzeyde bizimdir,güneyde bizim...

    13.02.2006', 'Hayelleri kursağında kalacak, Doğuda bizimdir,batıda bizim, Bizler şahlandıkça, onlar üzülecek, Kuzeyde bizimdir,güneyde bizim... Bu ülke Tü...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/doguda-bizimdir-batida-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Yalnız Ben Yalnız', 'i-stanbul-yalniz-ben-yalniz-hasan-uzel-9694w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerim ellerine gözlerim gözlerine

Öyle muhtaç ki şu günlerde

Sensiz çekilmiyor İstanbul

Öyle yalnızım ki kalabalıklar içinde

Ağlayamam canım ağlayamam bitanem

Sana söz verdim diye

Gülemem bebeğim gülemem dileğim

Sen yanımda yoksun diye

Şimdi yanımda olsan ellerimden tutsan

Yediveren bir buse kondursan en sıcağından

Bak üşüyor ellerim bak titriyor yüreğim

Ben sana ben sevdana öleyim

Sensizlik vurdu beni indim yine sahile

Resmin avuçlarımda karşımda kız kulesi

Ben sevmiyorum artık seni sensiz sevmeyi

Yine ben severim seni sensiz hamam böceği

İki çay söyledim en açığından

Biri altı şekerli diğeri iki

Yine unutmuşum çakmağımı

Kaldı şimdi cigaram da öksüz ben gibi

İstanbul dalga geçti benle

Sende yalnızsın bende diye

Güldüm; Sen nasıl yalnızsın diye

Yüreğinde kız kulesi içinde insanlar cümlesi

Dedi ki gönül vermiştim Fatih''e

O gitti gideli yalnızım işte

O dönmeyecek artık beni feth etsede

Sus dedim artık sus sus sus

Aklıma birden ölüm geldi...

En büyük ayrılık o olsa gerek...

Ölüm nasıl bir yar acaba

İstediğini bir daha bırakmıyor

Kıydı mı nikahı bir kere

Boşanmak asla mümküm olmuyor

      (Bu Şiir Bir Vefasız''a İthaf Edilmiştir.)

                 (31.12.2005 Kız Kulesi)', 'Ellerim ellerine gözlerim gözlerine Öyle muhtaç ki şu günlerde Sensiz çekilmiyor İstanbul Öyle yalnızım ki kalabalıklar içinde Ağlayamam can...', ARRAY['Türk Edebiyatı','Şiir','Hasan Uzel']::text[], 8.5, '{"poet":"Hasan Uzel","poet_slug":"hasan-uzel","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/istanbul-yalniz-ben-yalniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vardır Böyle İnsanlar', 'vardir-boyle-i-nsanlar-seyfet-bozcali-nqe6r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öğle insanlar varki,laf söylersin dinlemez,

Kafası öyle darki,söyleneni anlamaz,

Ne akıl var ne mantık,Hak''kın yoluna gelmez,

Cehalet potasında vardır böyle insanlar...

Ot gibi biter bunlar,her yerde öter bunlar,

Ne laf dinler ne anlar,aldığın satar bunlar,

Sözü daim zehirdir,Ya sapık ya cahildir,

Toplumun Tepesinde vardır böyle insanlar...

Seyfet der bunlar sapmış,aşkı bir ilah yapmış,

Hayvan gibi yaşamış,ense ve göbek yapmış.

Yetimi itmiş kakmış,servete servet katmış,

Ahiretten nasipsiz,vardır böyle insanlar...

         13.02.2006', 'Öğle insanlar varki,laf söylersin dinlemez, Kafası öyle darki,söyleneni anlamaz, Ne akıl var ne mantık,Hak''kın yoluna gelmez, Cehalet potası...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vardir-boyle-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar geçti ama hasret geçmedi', 'yillar-gecti-ama-hasret-gecmedi-mikdat-bal-oh6rb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar geçti ama hasret geçmedi

Kalkıp da gitmezsem, yuh olsun bana

Severek gurbeti kimse seçmedi

Arzumla kaldıysam yuh olsun bana

Olmasaydı geçim derdi başımda

Gurbete düşmezdim o genç yaşımda

Sevenlerim ağlar mıydı peşimde

Daha ağlatırsam yuh olsun bana

Kim terkeder bilmem ana yurdunu

Seven sediğine dönmez sırtını

Hasret yakar şu gediğin ardını

Artık sabredersem yuh olsun bana

Örümcek ağına büründü obam

Nice yıllar geçti tütmedi sobam

Demekki beyhude verdiğim çabam

Daha eğlenirsem yuh olsun bana

Mikdatî’yim bitmez dağ gibi dertler

Çoğu vefat etti bildiğim fertler

Nerde yarenlerim o civan mertler

Gidip de görmezsem yuh olsun bana', 'Yıllar geçti ama hasret geçmedi Kalkıp da gitmezsem, yuh olsun bana Severek gurbeti kimse seçmedi Arzumla kaldıysam yuh olsun bana Olmasaydı...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yillar-gecti-ama-hasret-gecmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Sokaklar', 'garip-sokaklar-serkan-yilmaz-ugurlu-jmn5f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah! Dargın geçiyorum güzelim sokakları,

Düşündükçe el aldı diye al yanakları

Ve bir fırtına kopuyor bilmem ki nedir? 

Saikalar vursa da gönlüm yine sendedir

Ki yağmur yağardı saikaların ardından,

Ki gönlümü sel aldı şimdi göz yaşlarımdan.

Eskisi gibi değildi sokaklar nedense

Belki de maziye ağlıyor her ne dildense

Bu sokaklardan sanki hep kötüler yürümüş,

Kaldırımla evleri kasvet rengi bürümüş.

Oysa ev aynı ev; kaldırım aynı kaldırım

Bir sen varsın aklımda yokluğuyla yandığım.

Yeminler ederken sensizliğin üzerine

Hasret kaldım ben şimdi gözlerinin rengine

Şimdi geceler bir hal aldı ki ölmeye bedel,

Ve yoktur tutsak kalbimde mutluluktan eser

İhtiraslar kurbanısın sen o gecelerde

Heyhat! Yeminler kaldı en kuytu köşelerde.', 'Ah! Dargın geçiyorum güzelim sokakları, Düşündükçe el aldı diye al yanakları Ve bir fırtına kopuyor bilmem ki nedir?  Saikalar vursa da gönl...', ARRAY['Türk Edebiyatı','Şiir','Serkan Yılmaz Uğurlu']::text[], 8.5, '{"poet":"Serkan Yılmaz Uğurlu","poet_slug":"serkan-yilmaz-ugurlu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/garip-sokaklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamet Kapıda', 'kiyamet-kapida-metin-yalti-1lfqe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '............................... '' Hükmedenler sataşırsa halka

................................ Kıyamet kopar o diyarda''

Günün birinde 

Anlamak istediğinde 

Geç kalmamanı dilerim 

Gelmekte. 

Din adamlarınca 

Bilim adamlarınca 

Söylenti bu ya 

Tutuklularca da… 

Kıyametin yaklaştığı söylenmekte… 

Geç kalma sevgilim geç kalma 

Ya birinden biri doğru çıkarsa? 

Umurumda da değil aslında 

Sensiz geçen her gün kıyamet nasılsa… 

Sen gelmemezlik yapma genede 

O gün de gelsen 

Ya kıyameti durduracağız 

Ya da yeni bir dünya kuracağız 

Seninle… 

13.2.06', '............................... '' Hükmedenler sataşırsa halka ................................ Kıyamet kopar o diyarda'' Günün birinde  Anlam...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kiyamet-kapida-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırgın yaşlı sahil..', 'kirgin-yasli-sahil-i-lknur-i-din-eu2c1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sessiz bir fırtınada yaşlı sahil 

Nasıl karşılar dalgaları bilir misin? 

Yıllardır bildiği,özlediği coşkulu çarpmaları 

Limanı eskise de 

Özlemi yenik düşer yaralanmalarına 

Oysa liman mı eskidir 

Geç gelen dalgalar mı hayırsız 

Zaman geçer, 

Kıyı istemez olur artık dalgaları 

Bilir gelip geçicidir dalganın hevesi 

Gidecektir limanı eskiterek 

Dalga da istemez olur sahili 

O da anlar 

Gelen gideni aratır', 'Sessiz bir fırtınada yaşlı sahil  Nasıl karşılar dalgaları bilir misin?  Yıllardır bildiği,özlediği coşkulu çarpmaları  Limanı eskise de  Öz...', ARRAY['Türk Edebiyatı','Şiir','İlknur İdin']::text[], 8.5, '{"poet":"İlknur İdin","poet_slug":"i-lknur-i-din","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirgin-yasli-sahil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parazitler', 'parazitler-sevinc-kavuk-ob8rq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Parazitler omurgasız hayvanlardır

başka canlı hayvanların 

içinde veya derisinde kurulu mekanları 

uzak biyolojik perspektifle bakılırsa

orada-olmak ile var-olmak gibi bir nüansla

bir yaşam savaşı uyumunun negatifliğidir ki

en az bir karşı koyum çizgisine çok yakın

-hep kışkırtıcılığıyla bıktırıcılığa uzanan-

Fırsatçı parazitlerin sürekli parazitlerden farkı

asalak taşıyan kayırıcılarını ev sahibi seçerler

yatağa gizli sokulması ve kan sülüklüğü işiyle

alışıklıkları olarak alacaklarını aldıktan sonra

mekanlarını öyle de terkederler.

Tam olgunluğa erişene kadar

Döl döneminde konaklamazlar

Bir mekandan öbürüne göç ederek

Bağımsız bir yaşam sürerler

Sürekli parazitlerden biri olan kene 

Sondaj sistemli ağız mekanızması

Sanatsal ve ustaca tutunma organlarıyla

Hep aynı kurbanı mesken tutar

En azgın ve en çok bilinen parazitlerdir

Canlı doku ve hücrelerinden beslenir

Tekrar etmeyi seven öğretmenlik huyum var

Nakaratlama gereği doğduğu an duramam

Sanatsal ve ustaca tutunma organlarıyla

Hep aynı kurbanı mesken tutar

En azgın ve en çok bilinen parazitlerdir

Canlı doku ve hücrelerinden beslenir

Canlı doku ve hücrelerinden beslenir

Bölgesel hafif yaralar açarak

Yavaş, ama tüketene, yok edene kadar

Süreklilik etkenlikleridir zararları, yorar.

Pireye kızıp yorgan yakma

Kene gibi yapışma insana 

deyişler bundanmış... 

13.02.2006', 'Parazitler omurgasız hayvanlardır başka canlı hayvanların  içinde veya derisinde kurulu mekanları  uzak biyolojik perspektifle bakılırsa ora...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/parazitler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaptan', 'kaptan-seyit-ahmet-duzen-qd4ro', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eskisinden beter olursun, çabaladıkça

Batan bir geminin kaptaniysan

Faralerde ayni denizde ölür.

Oysa yelken olmak isterdi kaptan.

Rüzgarlarla dans eden.

Hangi denizde rüzgar desen.

Bir yelkenlinin aşkıdır bu

Önce rüzgari sonra denizi kucaklar

Oysa bizim kaptan, koca boslukta

İzler batan gemisini ölürken....

Umuzsuzluk değil bu, batıyorsa gemin.

Ya yolcusundur onlarcası, şaşkın

Ya kaptansındır onuruyla ölümü isteyen

Ben kaptan oldum gülüm,ölüyorum

Ne olur anlat umudu,onlara

Sen sancağa sarıl gülüm.

Batan geminin filikasından uzanır bir yürek

Elini eline değdirir, gözlerinde sevinç

İşte umut bu değilsen kaptan.

Yinede batan geminin ardından

Denizi sevenlerindir ölüm, 

Bir mavi düs olmak umuduyla...

                          

*Sonsuz_Maviyi dileyenlere...', 'Eskisinden beter olursun, çabaladıkça Batan bir geminin kaptaniysan Faralerde ayni denizde ölür. Oysa yelken olmak isterdi kaptan. Rüzgarlar...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kaptan-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pençende Yüreğim.', 'pencende-yuregim-i-shak-ozlu-irdib', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alıcı kuşlar gibi sineme daldın,

Parçaladın yüreğimi söküp aldın.

Gül ve diken yolunun daha başında,

Gülü aldın diken deryasına saldın.

Pençende yüreğim kaçmayı yol seçtin,

Boz bulanık çağlayan dereler geçtin.

Koştum peşinden aşk badesin sunmaya,

Neyleyim ayrılık şerbetini içtin.

Pusuda yatmış bekler zalım avcılar,

Sıkıştırıyor sağdan soldan yancılar.

Her nefes sende gizli bir ah olurken,

Birden bin ah olur bendeki sancılar.', 'Alıcı kuşlar gibi sineme daldın, Parçaladın yüreğimi söküp aldın. Gül ve diken yolunun daha başında, Gülü aldın diken deryasına saldın. Penç...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/pencende-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşarsın Bir Gün', 'sasarsin-bir-gun-seyfet-bozcali-d3p7z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuvetliğim değip zülüm eyleme,

Takatsız bir hale düşersin bir gün.

Başından büyük lafları söyleme,

Tutulur o dilin şaşarsın bir gün...

Emanettir bize,beden de canda,

En küçük tasarruf yoktur elinde,

Akar durur damarlarda kanında,

Durursa o akış düşersin bir gün...

İnsanları hakir görüp,hor bakma,

Doğru yaşa Hak''kın yolundan çıkma,

Onarılması zor gönüller  yıkma,

Korkarımki haddi aşarsın bir gün...

Bozçalı der dünya gelip geçici,

Bir kuş gibi ruh bedenden uçucu,

Gözükmeli orda hayırın ucu,

Yoksa ettiğini çekersin bir gün...

13.02.2006', 'Kuvetliğim değip zülüm eyleme, Takatsız bir hale düşersin bir gün. Başından büyük lafları söyleme, Tutulur o dilin şaşarsın bir gün... Emane...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sasarsin-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ey Sevgili..!', 'ey-sevgili-turgut-gundogmus-mqk6l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyorum ki...

Bir güne sığmayacak kadar değerli sevgin

Onun içindir ki...

Sana hiçbir çiçekçinin buket edemeyeceği,

Hiçbir  ressamın çizemeyeceği,

Hiçbir bilim adamının yapamayacağı

Ve hiçbir sarrafın  tasarlamayacağı,

Tanrının bana bahşettiği  yüreği,

sevgimle sarmalayıp avuçlarına bırakıyorum', 'Biliyorum ki... Bir güne sığmayacak kadar değerli sevgin Onun içindir ki... Sana hiçbir çiçekçinin buket edemeyeceği, Hiçbir  ressamın çizem...', ARRAY['Türk Edebiyatı','Şiir','Turgut Gündoğmuş']::text[], 8.5, '{"poet":"Turgut Gündoğmuş","poet_slug":"turgut-gundogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ey-sevgili-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Hüznün Adı', 'guz-huznun-adi-mehmet-faruk-habiboglu-f6lpa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceye sar gözlerini güz çiçeği

Yıldızlara aç sadece

Ve karanlığa

Ve yalnızlığa yüreğini

Seherde bir şiir dolansın diline

Sevda üstüne 

Ötesiz tutkulara

Salıver gitsin diye

Yine sessiz / ağıtlar yine

Hangi hazanda yitirdik seni

Hangi bulutlara karıştın

Hangi yağmurlar

Ya hangi rüzgarlar aldı seni

Ey güz çiçeği

Ey hüznün çiçeği

Bikes bir telaşla dönsün başın

Sen uykulara karış

Ben çarmıhlara gerileyim

Sırf senin için

Dilinde asılsın baş harfi adımın

Tarlalardan toprak kokusu eserken

Güvercin kanadına sar beni

Uykularına kar beni

Gecenin sessizliğini dinle

Ve bir an

Yıldızlardan sor beni

Ey güz çiçeği

Hüznün çiçeği

Benim ellerim bir güle gebeydi

Ellerimde buldum seni

Amma olmazım benim

Ah hüznümün çiçeği..', 'Geceye sar gözlerini güz çiçeği Yıldızlara aç sadece Ve karanlığa Ve yalnızlığa yüreğini Seherde bir şiir dolansın diline Sevda üstüne  Ötes...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Habiboğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Habiboğlu","poet_slug":"mehmet-faruk-habiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/guz-huznun-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi-sebebim', 'bi-sebebim-mehmet-faruk-habiboglu-4aelg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yani gecenin saat sıfır yirmi ikisi

Gözlerim kan çanağı uzuyor ellerin

Sen uykularının en sıcağında

Rüyalarındaki ben değilim

Kül tablasında boynu kırık izmaritler

Gönlü kırık bir ben değilim elbet

Bir yarasa çığlığı bekleyen yüreğim

Ben gibi biçare kaçtığım uzlet

Masamda yarım kalmış kadeh gibi

Yarım yamalak şiirler

Bi sebebim olmuşsun oy

Gözlerimde ağlıyor yitik şehirler

12/05/05

00:32', 'Yani gecenin saat sıfır yirmi ikisi Gözlerim kan çanağı uzuyor ellerin Sen uykularının en sıcağında Rüyalarındaki ben değilim Kül tablasında...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Habiboğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Habiboğlu","poet_slug":"mehmet-faruk-habiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bi-sebebim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-nevzat-gibey-9v75n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilme ben sana yangın sen benden biçaresin,

Doktorların hastaya yazdığı reçetesin.

Kimler geldi geçti de seni unutamadım,

Senden çok vazgeçtim de,sensiz hiç yapamadım.

Bilirim uzaktasın ve ölüm yakınımda,

Azraile verececek ruhumda yok canımda.

Sende kalmış herşeyim ruhum, canım,sevdiğim,

Hasretiyle yandığım mühür gözlü sevdiğim.

Etme biçare beni bu virane yerlerde,

Evlenmem başkasıyla gezinsemde dillerde.

Hatıradır üç gece üç gündüz hayalime,

Onlarla avunurum gelmesem de kalbine.

Unuttun demiyorum bilirim seviyorsun,

Benimki sitem biraz hala anlamıyorsun.

Kudurdum mu diyeyim kurudum mu diyeyim,

Ahlakım elverse de yanıyorum diyeyim.

Kaçırma uykuları bırak rüya göreyim,

İzin verde rüyamda seni bir kez öpeyim.

Kalmadı hiçbirşeyim gitti güzel ne varsa,

Bir sen kaldın kalbimde senindir orda yaşa.

Bölündü mü seninde uykuların ben gibi

Sarıldın mı yastığa beni sararmış gibi.

Senin sıcaklığını bulamam kimselerde,

Bu yüzden hiç aramam çare sensin bu derde.

Çıkma pencelere söndür ışıklarını,

Derbeder avareyim görme gözyaşlarımı.

Serseri sanma beni geçersem sokağından 

Bu sevdalı öpmüştü seni dudaklarından.

Bir gün ararda beni bulamazsan sen eğer,

Kaderin terkettiği mahsun kıyılara bak.

İnanma kimselere neler söylerler neler,

Sevdiysen beni eğer sevgili kalbine bak.

Saraylardan vazgeçtim viran sanma ki evim

Ne bir ocak tütecek ne de bir dernek,düğün.

Umudu kaybetmedim umut hergün bendedir,

Seni sevdiysem eğer leyla bildiğimdendir.

Mecnun ettin sen beni çöllerde yanıyorum.

Arzda yerim kalmamış arşı göremiyorum.

Lutfet son bir kez olsun göreyim gül yüzünü,

Sonra huzurla ölsem toprak örtse üstümü.', 'Bilme ben sana yangın sen benden biçaresin, Doktorların hastaya yazdığı reçetesin. Kimler geldi geçti de seni unutamadım, Senden çok vazgeçt...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gibey']::text[], 8.5, '{"poet":"Nevzat Gibey","poet_slug":"nevzat-gibey","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sevgiliye-153-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çetrefil Sûal', 'cetrefil-s-al-mehmet-faruk-habiboglu-518ge', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kavi bir yürek sancısıdır

Sonrasızlığın çetrefil suali

Ey gecenin kızı, yürek sarası

Ruhumda taşıdığım Edessa’nın vebali

Sen olma hiç bu şehrin 

Bu yudum yudum içtiğim zehrin

Tılsımlı yortusunda

Bir Bosna acısında yitirdiğimi

Yeniden yaşadım yeniden

Tam orda Felluce’de

Bin azabın çarmıhında

Sen ey gecenin kızı kısrağı

Bir daha aşık olmayacağım! 

Anneler tanıdım sonra 

Kızılca kıyamet coğrafyam

Her kurşuna yürek serdiler

Hani ebabiller gelecekti yeniden

Merhamet hangi Kaf’ta gizli

Hadi biz devam edelim ölmeye

Yeniden ölmeye yeniden

Hep şafak kırılganlığında ziya

Akıyor maskelerden riya

Ben bu şehrin sokaklarındayım da

Akın akın güneşe göç var

Sonrasızlığın çetrefil suali

Ruhumda taşıdığım Edessa’nın vebali

12/05/05', 'Kavi bir yürek sancısıdır Sonrasızlığın çetrefil suali Ey gecenin kızı, yürek sarası Ruhumda taşıdığım Edessa’nın vebali Sen olma hiç bu şeh...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Habiboğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Habiboğlu","poet_slug":"mehmet-faruk-habiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cetrefil-sual-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-nevzat-gibey-680rw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve sabah olmaz artık bende

Karabasanlarla geçer gecem yoksan

Duymuyorsam sesini

Hissetmiyorsam tenini

Sen yoksan ölümden beterdir gülüm

Geceler haramdır bana

Uykular yasak...

Yoksun ya bilemezsin gülüm

seni hiç bensiz bırakmadım 

Ey ömrüm

Ey gönlüm

Duymadım sesini bugün 

Bilmelisin şah damarım kadar

Yakındır ölüm.', 'Ve sabah olmaz artık bende Karabasanlarla geçer gecem yoksan Duymuyorsam sesini Hissetmiyorsam tenini Sen yoksan ölümden beterdir gülüm Gece...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gibey']::text[], 8.5, '{"poet":"Nevzat Gibey","poet_slug":"nevzat-gibey","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gulum-183-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birde Mutlu Gör Beni', 'birde-mutlu-gor-beni-nevzat-gibey-spvi7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani gel dedin de uçurdun ya kalbimi

Şimdi kelebeklerden daha huzurluyum

Sen sonunda yüreğinle sorguladın ya beni

Bin yıl ceza versen de ben yatmaya razıyım.

Hep acı satırlar mı yazarım sanıyorsun

sensin yazdıran bana, niçin anlamıyorsun

zümrüdü anka mısın peşinden dolaştım hep

Kaf dağını buldum da yine de kaçıyorsun

Avcı mı sandın beni ceylan gibi sekersin

Ne kadar koşarım daha neden böyle edersin

Yorulup düşersem bir gün kara toprağa

Mezarıma gelipte çok gözyaşı dökersin

Bu yüzden gel etme eyleme beni deli

Yunus gibi olamam bulamazsam bir veli

Güzel bir kelam gönder biraz gül de yüzüme

Viran dertlerden al da birde mutlu gör beni.', 'Hani gel dedin de uçurdun ya kalbimi Şimdi kelebeklerden daha huzurluyum Sen sonunda yüreğinle sorguladın ya beni Bin yıl ceza versen de ben...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gibey']::text[], 8.5, '{"poet":"Nevzat Gibey","poet_slug":"nevzat-gibey","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birde-mutlu-gor-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Sen Vefasız', 've-sen-vefasiz-nevzat-gibey-7mis1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerindir beni alıp götüren

Ne söylesem yalan olur sevdiğim

Ben değilim seni bende yitiren 

sendin giden kahredipte sevdiğim

Yarın olur,dönüş olmaz geriye

Güzel bakan güzel görür sevdiğim

Faydası yok,çiz yolun ileriye

Bende gemileri yaktım sevdiğim

Haram olsada her lokma dilime

Sensizde bu aş bu ocak tüter sevdiğim

Beş dakika müsade et kalbine

Göreceksin ben haklıyım sevdiğim

İçin için kan ağlarda yüreğim

Çaresi yok mutlu oldur dileğim

Senin için ben çekilmez çileyim

Bize bizden yar olmadı sevdiğim

Nasip kısmet deyip gectikya aşktan

Gurur ettik biz kaybettik en baştan

Çok direttin sandın ki kalbim taştan

Kırılmazdı kırdın ya sen sevdiğim

Ben kimseye sitem etmem böylesi

Yalan ölür gerçek yürür sevdiğim

Rabbim bilir kimsesizler kimsesi

Konar,göçer ruh bedenden sevdiğim

Gözyaşımdır akıttığım kalplerde

Adın vefasızdır gezer dillerde

Ben virane gibi yaban ellerde

Sen mutlu ol saraylarda sevdiğim', 'Gözlerindir beni alıp götüren Ne söylesem yalan olur sevdiğim Ben değilim seni bende yitiren  sendin giden kahredipte sevdiğim Yarın olur,dö...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gibey']::text[], 8.5, '{"poet":"Nevzat Gibey","poet_slug":"nevzat-gibey","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ve-sen-vefasiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gel', 'hadi-gel-nevzat-gibey-9tdih', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'üşüdüm

Üç battaniye attım üstüme 

Bu şiir bitmesin diye

Şiirler yarım kalmasın sevdiğim

Aşklar yarım kalmasın

Hadi gel.

Gece yarısıdır kapımın önünde,

Seni bekleyeceğim gelmesende...

Hadi gel! 

Dağıt yalnızlığımı.

Üşüyorum.

Hadi gel! 

Bir daha bu gece olmayacak

Belki üşümeyeceğim böylesi bir daha

Hadi gel

Sar yalnızlığımı

Isıt gece karanlığını

Ay kıskansın tenini

Aydınlat gecemi

Hadi gel...', 'üşüdüm Üç battaniye attım üstüme  Bu şiir bitmesin diye Şiirler yarım kalmasın sevdiğim Aşklar yarım kalmasın Hadi gel. Gece yarısıdır kapım...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gibey']::text[], 8.5, '{"poet":"Nevzat Gibey","poet_slug":"nevzat-gibey","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hadi-gel-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Dair', 'sana-dair-nevzat-gibey-ntlbj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuytu bir köşedeydim

kimseler bilmezdi beni

gece uyurdu

insanlar uyurdu

kaldırımlar uyurdu

beni uyku tutmaz

isyan geceleriydi

isyanım ki

sen

sevdan

düşmüştüm peşine

kan damlaları yüreğimden sızarken gecede

ellerimle uzanırdım rüyalarına

rüyalarımda dokunurdum 

rüyalarında yoktum

uzundu geceler o zamanlar

bitmezdi isyan ım

canım

ayrılık türküleri dökülürdü dilimden

ayrıldığın zaman yanımdan

iki damla birikirdi kirpiklerimde

görmezdin

geceler uzundu o zamanlar

vahşi köpekler ulurken gece yarılarında

kaçmadım ordaydım dimdik ayakta

gitmezdim ayrılmazdım bıraktığın yerdeydim

işte orada ayak izlerim

git 

bak

gör

sor 

duyacaksın

adını ezberlettiğim kaldırımlar söylecek 

isyanımı

vefasızlığını

adını

adını adımla anacaklar

ağlayacaksın

hissedeceğim

görmeyeceksin

gece uzun git bir uyku düşle

bir hayal kur yine

sonu hüsran bilsende

ütopyalarla süsle odanı

karanlık gelince

üşüyeceksin

titreyeceksin

ve üzüleceksin

göreceğim orda bir yerlerde olacağım hep.

sen bilmeyeceksin.', 'Kuytu bir köşedeydim kimseler bilmezdi beni gece uyurdu insanlar uyurdu kaldırımlar uyurdu beni uyku tutmaz isyan geceleriydi isyanım ki sen...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gibey']::text[], 8.5, '{"poet":"Nevzat Gibey","poet_slug":"nevzat-gibey","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/sana-dair-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Merhaba** (düz yazı 1)', 'merhaba-duz-yazi-1-tulay-i-cen-97x0w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhaba..

Selam olsun tüm  insanlara, seven sevilen  tüm insanlara  selam olsun...Hayatın içinden  gelen yaşama  sevincini içinde  hisseden mutluluğu  yakalayan  acıyı  kendine  bal  eyleyen, acıyla ve sevinçle  yaşayan tüm insanlara  selam olsun...

Evet  yine akşam oldu, aslında  akşam saatleride değil  şuan  gece yarısı  ve ben hiç  cıkmadığım karanlıklardayım.Açtığım her kapıdan karanlık üstüme  geliyor.

Bazen  düşünüyorum ben  körmü oldum, hep  karanlıktayım neden  beynim  ışığı  görmüyor, aydınlık benim için  neden  uzak.

Aydınlık  zamanlara sevgi gibi  ihtiyacım var.Sevgi karşılıksız olmayan bir  sevgi ne zaman,ne zaman.....! 

İlkbahar  geldi,yaz bile  geldi  geçti.Benim ruhumda  halen kara kış hüküm sürüyor...Ben baharları  özledim..

11/07/2001', 'Merhaba.. Selam olsun tüm  insanlara, seven sevilen  tüm insanlara  selam olsun...Hayatın içinden  gelen yaşama  sevincini içinde  hisseden ...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/merhaba-duz-yazi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesken', 'mesken-hidir-altas-90cu9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Asker ocağından dertlenen

Karanavadan yemek yiyen

Nankörlük yapmasınlar

dertlenen yediğinden içtiğinden

Gelibolu onaltı ay meskenimdi

Benim engüzel günlerimdi

Rezil değil vezirdim ben hocam

Çanakkale benim ikinci memleketimdi

Seyrederdim nöbetimi tutarken

Bogazdan gemiler sallanıp giderken

Selam göndrirdim gemilerle

Nöbette sıla türküleri söylerken

Turhaniyem imrenirdim toprağına

Bu toprakta şehit düşen atama

Anlatırdım mektupla Çanakkaleyi

Köyümde yolumu bekleyen anama', 'Asker ocağından dertlenen Karanavadan yemek yiyen Nankörlük yapmasınlar dertlenen yediğinden içtiğinden Gelibolu onaltı ay meskenimdi Benim ...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Altaş']::text[], 8.5, '{"poet":"Hıdır Altaş","poet_slug":"hidir-altas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mesken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Adım Yürüyelim', 'adim-adim-yuruyelim-nevzat-gibey-popct', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki adımlık yoldaydık 

İlk adımlarında düştük

Uzun ve yanlızdı gece 

Tutan olmadı ellerimizden

Aşk yine mahsun kaldı 

Derin kuyularda 

Yusuf gibi 

Sanma ki sahipsiz

Bir ip atan olacak yüreğimize

Göreceksin

Bekle.', 'İki adımlık yoldaydık  İlk adımlarında düştük Uzun ve yanlızdı gece  Tutan olmadı ellerimizden Aşk yine mahsun kaldı  Derin kuyularda  Yusuf...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gibey']::text[], 8.5, '{"poet":"Nevzat Gibey","poet_slug":"nevzat-gibey","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/adim-adim-yuruyelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmelerin...', 'gitmelerin-sinan-aydindag-769y3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '12.Şubat.2006

Aşkım gittin ya bu sokaklar birden yalnızlığa büründü

Sanki insanlar arabalar kayboldu da etraf çöle döndü

Ya sağır oldum ya kör ya da ikisi birden

Hepsi gitmelerinin suçu hepsi gitmelerinden

Şimdi seni diliyorum bu ıssız ve soğuk, şubat gecesinden', '12.Şubat.2006 Aşkım gittin ya bu sokaklar birden yalnızlığa büründü Sanki insanlar arabalar kayboldu da etraf çöle döndü Ya sağır oldum ya k...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gitmelerin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnizlik', 'yalnizlik-kemal-oguz-094d8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir rüya aleminde, yillarim gecti.

Takti bana kafayi, böyle yalnizlik.

Kurtulmaya calistim, gücüm yetmedi.

Pesimden kovaladi, kostu yalnizlik.

Ne dost, ne arkadasim, gercek sevenim.

Derdimi dinleyecek, selam verenim.

Gönülden sevecegim, ne bir sevgilim.

Yakami birakmadi, tuttu yalnizlik.

Merhaba dediklerim, bir dost olmuyor.

Anlatiyor derdini, hic dinlemiyor.

Hep ayni mevzular, baska bilmiyor.

Bencillik dünyasinda, yakti yalnizlik.

(Esslingen, 08 Mayis 1992)', 'Bir rüya aleminde, yillarim gecti. Takti bana kafayi, böyle yalnizlik. Kurtulmaya calistim, gücüm yetmedi. Pesimden kovaladi, kostu yalnizli...', ARRAY['Türk Edebiyatı','Şiir','Kemal Oguz']::text[], 8.5, '{"poet":"Kemal Oguz","poet_slug":"kemal-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizlik-339-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Merhaba*(düz yazı2)', 'merhaba-duz-yazi2-tulay-i-cen-53k6x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Merhaba.

Evet yine yanlız  bir akşam saati.Çevremde  insanlar  cıvıl cıvıl bir  ben  karamsar,bir ben...

Nereye  gidiyorum  yada  nerden  geliyorum, yolun  şuan  tam  orta  yerindeyim.

Nerden  gelip nereye gittiğimi bilmiyorum gözümde büyüyen yollar beni nereye  götürüyor gittiğim yer  önemli  değil geldiğim yerde  öyle.

Her şey  önemini  yitirdi, yitirdiklerimin  yanında.Her  zaman  kendime  söylediğim gibi gercekten  ben  bir  deliyim.

Şuan   gökyüzünde  uçan bir  kuş olmak  özgürce  uçmak isterdim, özgür ve sorunsuz.

Hani  derler  ya  yeter yerlerde  süründüğün  ayağa  kalkta yürü biraz, ama  ne yazıkki ben hala  yerde  sürünüyorum, yürümeyi öğrenemiyeceğim.

Zaman  gercekten bir  bilmece ben hala  bu  bilmeceyi cözmeye çalışıyorum, ömrüm  yetermi bilmem  ama gerçekten zor bilmece.

27/07/2001', 'Merhaba. Evet yine yanlız  bir akşam saati.Çevremde  insanlar  cıvıl cıvıl bir  ben  karamsar,bir ben... Nereye  gidiyorum  yada  nerden  ge...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/merhaba-duz-yazi2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Merhaba *(düz yazı 3)', 'merhaba-duz-yazi-3-tulay-i-cen-dvj7m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhaba...

Su gibi  akıp  giden  zamanın  ardından  Merhaba, yeni  gelicek zamanlara merhaba.

Hayatın  anlamını  anlamadan  göçüp  gidenlere Merhaba..

Zamanın  içinden  sevgiyi  tadmadan  sevmeyi öğrenmeden gidenlere  merhaba..Sevgiyi  sevilmeyi  öğrenenlerede  merhaba..

Hayatın  yada  yaşamanın  anlamı nedir? Bunu  her gün akıp  giden  zaman  içinde  kendime ve  çevremdekilere   defalarca  sordum....Ama  cevap yok.

Bence yaşam tad almak  aldığın tadı  senelerce hissedmek,o tadı  her gün tüm bedeninde ve ruhunda  hissetmek.Hayatta taddığımız  tadlar  bazen  acıda  olabilir  nedense  acıyı  hiç  sevmeyiz  sonuçta  acıda  bir tad dır.Kimsenin  acıyı  tadmasını  istemem ben acının nasıl bir  tad  olduğunu  çok  iyi bilirim.İnsanın  yaşamındaki acılar ve  tadlı olaylar bence  insana  yaşadığını  ayakta  olduğunu  hissetirenlerdir.

Her iki  tadıda  yaşamak gerk  ama  her ikiside  orantılı  olmalı.

Acıyı  bal  eylemeli, sevgiyi  yaşamalı..

ACIYI   GÖMMELİ , GÖNÜL GÖZÜYLE   SEVMELİ..

31/07/2001', 'Merhaba... Su gibi  akıp  giden  zamanın  ardından  Merhaba, yeni  gelicek zamanlara merhaba. Hayatın  anlamını  anlamadan  göçüp  gidenlere...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/merhaba-duz-yazi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşten Ok', 'atesten-ok-timur-i-likan-ij95p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayrılık ateşten 

bir oka benzer

yakar da yakar yüreğimi

derinden tâ derinden

Tutmuşum korlar gibi

sıcak mı sıcak

hasretlerin ellerinden

Umutlarımın yollarını

yakıp yıkar da öylece

arkama bakmadan giderim

o ıssızlaşan gönlünden ben

(13 Şubat 2006/ İstanbul)', 'Ayrılık ateşten  bir oka benzer yakar da yakar yüreğimi derinden tâ derinden Tutmuşum korlar gibi sıcak mı sıcak hasretlerin ellerinden Umut...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/atesten-ok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-i-brahim-sahinoglu-9oa0f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Getir elin koy sinama

Şifadır ellerin güzel

Kesilmez Mevla dan umut

Akıtma sellerin güzel

Bağda gülümü derenim

Canıma canın verenim

Can deyip kurban olanım

Bozma hiç tellerin güzel

Gül kokun burnumdan çıkmaz

Can diğer yanımdan kalkmaz

Sevdiğim yad ele bakmaz

Cinandır yolların güzel

Tedbirini ele alır

Emri ilahiyi bilir

Can diğerim kurban olur

Hayırsız pulların güzel

Hulüs dilin tevhid eder

Bensiz bu dünyayı neder

Beraber muradın gider

Solmasın alların güzel

		Nuri ŞAHİNOĞLU

			Aşık Hulüsi', 'Getir elin koy sinama Şifadır ellerin güzel Kesilmez Mevla dan umut Akıtma sellerin güzel Bağda gülümü derenim Canıma canın verenim Can deyi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Şahinoğlu']::text[], 8.5, '{"poet":"İbrahim Şahinoğlu","poet_slug":"i-brahim-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/guzel-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalandan Sanırım', 'yalandan-sanirim-ian-izoner-c231m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalanlarla kurulu,

Şu yalancı dünyamdan,

Yalancıktan bir intiharla da olsa,

Kurtulabileceğime; 

Yalan da olsa,

Sevinebilirim sanırım.', 'Yalanlarla kurulu, Şu yalancı dünyamdan, Yalancıktan bir intiharla da olsa, Kurtulabileceğime;  Yalan da olsa, Sevinebilirim sanırım....', ARRAY['Türk Edebiyatı','Şiir','Ian Izoner']::text[], 8.5, '{"poet":"Ian Izoner","poet_slug":"ian-izoner","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalandan-sanirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat çemberi', 'hayat-cemberi-ugur-aydin-2-xixf0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kimler geldi geçti  bu hayat çemberinden 

kimler unuttu  kimleri kaldı geçmişten 

kimleri unutmadı ruh  kimleri arzular beden 

unutulmuyor işte unutamamak neden

çaresi zamanmış yara kapanır unutulur izi kalıyor senden 

doğru söylemiş söyleyen dil çaresi zaman 

söylemeye varmamıştır bekleyende kalmamış aman 

unuttum dese de unutulmuyor neden 

yara kapandı unutuldu hatırası izi kalıyor senden 

verilmiş unutulmayana gelmesi için zaman 

unutmuş olmalı ki sevilen kalmadı bekleyen de aman 

vakit yok tükendi eldeki zaman 

yara kapandı unutuldu hatırası izi senden elde kalan', 'kimler geldi geçti  bu hayat çemberinden  kimler unuttu  kimleri kaldı geçmişten  kimleri unutmadı ruh  kimleri arzular beden  unutulmuyor i...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayat-cemberi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşı Yoktur Sevmenin', 'yasi-yoktur-sevmenin-deli-mavi-696t3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gençlikte alevlenir, heyecanla coşarsın 

Zordur sevdanın yolu, yaşı yoktur sevmenin

Bilmez isen sevmeyi, arkasından bakarsın 

Varsa eğer yüreğin, yaşı yoktur sevmenin.......(Ayak Dörtlüğü)  Burhanettin Akdağ 

Ömrünce kovalarsın, havanda su döversin 

Seviyorum sanarak, aynı yerde dönersin 

Olur olmaz kırılır, kendin boşa üzersin 

Nefes almak gibidir, yaşı yoktur sevmenin......Burhanettin Akdağ 

Ömrün sonbaharında, gezdin durdun bağlarda 

Bir bülbül dönmüş güle, sevda söyler dağlarda 

Böyle yürek atışı, olur mu bu çağlarda 

Çarpıyorsa yüreğin, yaşı yoktur sevmenin......Hülya Ekmekçi

İkinci bahar olur yep yeni bir ad ile, 

Depreşir yaraların yeniden gelir dile 

Kemale ermiştir ki yürek tanımaz hile 

Erekte vuslat varsa,yaşı yoktur sevmenin.......Şemsettin DERVİŞOĞLU

Fiziki kuralı yok,sevmek denen erdemin 

Yürek çarpıyor ise,müsaittir her zemin 

Aşk yangını düştümü fayda etmezki yemin 

Konuşursa gözlerin,yaşı yoktur sevmenin........İbrahim COŞAR 

İnsan her yaşta sever sevmek ruhun gıdası 

Adem - Havva''dan miras hiç geçmez ki modası 

Hayatı renklendirir sevgilinin sevdası 

Tadına doyum olmaz yaşı yoktur sevmenin........Mustafa Alpaydın

Yirmili yaşlarında eserse sevda yeli, 

Otuzlarda kırklarda coşkulu yürek seli 

Nefes alan insanlar aşk ile beslenmeli, 

Gıda almak gibidir,yaşı yoktur sevmenin.........İbrahim COŞAR

Seversin hor görülür derler ki kırkta azan 

Ne bilsinler ki kalpte kaynamaktadır kazan 

Ehli dil oluverip yüreğin deli ozan 

Oluyorsa gerçekten,yaşı yoktur sevmenin........Şemsettin DERVİŞOĞLU

Geçer ömür habersiz bir bakmışsın yol bitmiş 

Gençlik hülyaları da seni çoktan terk etmiş 

Dostların hep sinlerde toprağından gül bitmiş 

Yine de diren gönül yaşı yoktur sevmenin.........Cemil Yüksel

her döngüde eskir yüz aynalar buğulanır 

gerçek aşkı arayan diyar diyar dolanır 

bir ışık olur sevgi duygular yalazlanır 

aydınlanan yüreğe yaşı yoktur sevmenin...........murat aydın doma 

Yeter ki sev gönülden, atsalar da sürgüne 

Ayrılık yangınından, uymaz günün gününe 

Suskun olsa da sazlar, dönüp bakma dününe 

İsterse ömrün geçsin, yaşı yoktur sevmenin.......Burhanettin Akdağ

sevda tüter bacadan gökyüzü bulutlanır 

gerçek aşkı arayan yağmurunda ıslanır 

sevginin en güzeli bakışlarda taçlanır 

gönülden sevenlere yaşı yoktur sevmenin.........murat aydın doma

deli gönlüm kah coşar, kah yıllara ağlarsın 

kimi zaman yanarsın, kimi zaman umarsın 

hep beklersin hayali, yar ile kavrulursun 

bulmak varsa kaderde,yaşı yoktur sevmenin.......dilek hokkaömeroğlu

Aynalardan korkmadım, kaçmadım köşe bucak, 

Kaybolsam gözlerinde, beni kim kurtaracak, 

Yakacak bakışların, biliyorum yakacak, 

Gönüllü tutuklunum, yaşı yoktur sevmenin.........Ali ALTINLI 

Sen hazanı yaşarsın sevdan ise sonbahar 

Vakit geç diyemezsin kalbi kırılır ağlar 

Sımsıcak duygularla seni hayata bağlar 

Sevgi sınır tanımaz yaşı yoktur sevmenin........Mustafa Alpaydın

Zaman geçer su gibi sayma olduğun yerde 

Sanmaki senin için durur zaman öylece 

Susturma yüreğini çalsın inceden nağme 

Geç oldu deme sakin yaşı yoktur sevmenin........Fatma Çağlayan

İster kırkında olsun, istersen elli’ye gel, 

Gel de bitsin bu hasret, sevenim belli’ye gel, 

Sazımdasın çalınan, perde’ye, telli’ye gel, 

Sevdanı söylüyorum, yaşı yoktur sevmenin.........Ali ALTINLI 

Yaş elliyi geçince,sevgi de kutsallaşır 

Gönül bir arı gibi, çiçek çiçek dolaşır 

Hasretle geçen ömür,son demine ulaşır 

Beşikten mezara dek, yaşı yoktur sevmenin......Ahmet Sefer Koçer

Yüreğin gürül gürül çağlayarak akarsa 

Nostalji demeyip de yarınlara bakarsa 

Cesareti toplayıp gemileri yakarsa 

Ha onsekiz ha elli yaşı yoktur sevmenin.........Şemsettin DERVİŞOĞLU 

Yaşı ilerleyince, inceden sızı düşer

Gözler yare bakmayı yar elleri tutmayı

Özlem yürekte sızı yarin yüreğinde od

Bahardır ömrün sonu yaşı yoktur sevmenin.......Dilek Hokkaömeroğlu

Vururum tezeneyi,gayri çalmıyor sazım 

Söylerim ''Barak''''Bozlak'',duyulmuyor avazım 

Sevmek söz ile olmaz,sabır ve emek lazım 

Hayatın tuzu sevgi,yaşı yoktur sevmenin..........Ahmet Sefer Koçer

Hasret arık çekilmez bir duruma gelince 

Bir yol uzar gözünde özlem kokar ellerin 

Mutluluktan payına tebessümü düşünce 

Bahar olur sözünde yaşı yoktur sevmenin.........Uğur Kılıç (ER)

İlk duyarsın anneye,yaşın gelir kemale 

Açıldımı gözlerin kanın kaynar güzele 

Hayatın kanunu bu,bu tanrıdan hediye 

Her daim tutulursun,Yaşı yoktur sevmenin..........Uğur Kılıç

Filizlenmişse kalpte sevdanın kor ateşi 

Bülbül olmuşsa yürek şakırsa sevgisini 

Kalmış olsa da yüzde senelerin çizgisi 

Bunları hiç düşünme yaşı yoktur sevmenin..........Fatma Çağlayan

Gönülden arzulayıp harcanır ise emek 

Bağbanı dövmek değil amaçsa üzüm yemek 

Tipi boran misali çağlamamak ne demek 

Diyebilirse yürek yaşı yoktur sevmenin............Şemsettin DERVİŞOĞLU

Kalplere demir attı, Şöhret,koltuk ve para 

Kangrene dönüştü,zor kapanır bu yara 

Sevgiyi yüreklerde,artık mum yak ta ara 

Sevmek adam olmaktır,yaşı yoktur sevmenin.....Ahmet Sefer Koçer 

Sevgide riya olmaz özden gelen bir olgu 

Gönülde pişirilip sözden gelen bir olgu 

İçin kan ağlasa da yüzde gülen bir olgu 

Sevmek kadim olmaktır yaşı yoktur sevmenin.........Şemsettin DERVİŞOĞLU

Şükürler yaratana.özümüz sevgi bizim 

Para elimin kiri,sözümüz sevgi bizim 

Şöhrete kapatmışız,gözümüz sevgi bizim 

Nefse hakim olmaktır,yaşı yoktur sevmenin...........Ahmet Sefer Koçer

İhanetle sarsılır, hayata boş verirsin 

Mecnun olup yanarak, günden güne erirsin 

Gönlüne ateş düşer, tekrar alevlenirsin 

Sevemem artık deme, yaşı yoktur sevmenin............Burhanettin Akdağ

Geçmişine bakar hep, ah çeker gönülleri 

Gözlerinden akar yaş,gülmez ki hiç yüzleri 

Yaş olsun elli iki, susmaz gönül dilleri 

Üzülme sen yaş ne ki,yaşı yoktur sevmenin...........dilek hokkaömeroğlu 

Bugün yarın diyerek, bekledin sevgiliyi 

Baktın ki gerilere, hep kaçırdın sevgiyi 

Bulamamış ta olsan, istediğin ilgiyi 

Vazgeçme tekrar dene, yaşı yoktur sevmenin...........Burhanettin Akdağ

Sevdâ mengenesinden kurtulup,kaçamadım, 

Yarım asır devirdim; şahlandım, uçamadım, 

Gönül yaşımda asla onbeşi geçemedim. 

Kim derse yalan söyler,''yaşı yoktur sevmenin.........İ.Yavuz Bildik

Sen olma vefasız yar, yıkılsan sözlerinden 

Bırakıp gitse bile, yaş dökme gözlerinden 

Yansan da ömür boyu, acıyla en derinden 

Deme olmaz ey gönül, yaşı yoktur sevmenin............Burhanettin Akdağ

Hilkatin mayasında, olur ise muhabbet 

Ekilirse yüreğe, kalkar kalpten adavet 

Ey kurban olduğum, şirin şerbet uhuvvet 

Girsen gayrı bağrıma, yaşı yoktur sevmenin.........Veysel KOŞAR

Hayatın tadı sevmek, kaçma sevdalanmaktan 

Sevincin taşıyorsa, utanma ağlamaktan 

Daim gül sevdiğine, korkma aşık olmaktan 

Kemale erse ömrün, yaşı yoktur sevmenin............Burhanettin Akdağ

Hadi bir de soralım gelin ile güveye 

Aşkı yaslarlar mıydı kapı ardı söveye? 

Koca öküz ölürken,post bırakmış düve''ye 

Bütün mahlûkat bilir,yaşı yoktur sevmenin..........İ.Yavuz Bildik

Gençlik geçip giderken,aşkım da biter miydi? 

Sözlerim tükenirken,şiirler yeter miydi? 

Gözlerim kapanırken,dudaklar öper miydi? 

Sevgi her daim varsa,yaşı yoktur sevmenin..........Emrah Çetinkaya(M@S@l PrEnSi)', 'Gençlikte alevlenir, heyecanla coşarsın  Zordur sevdanın yolu, yaşı yoktur sevmenin Bilmez isen sevmeyi, arkasından bakarsın  Varsa eğer yür...', ARRAY['Türk Edebiyatı','Şiir','Deli Mavi']::text[], 8.5, '{"poet":"Deli Mavi","poet_slug":"deli-mavi","theme":"Türk Şiiri","is_hero":false,"total_lines":148,"source_url":"https://www.antoloji.com/yasi-yoktur-sevmenin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Zevk', 'sadece-zevk-ethem-turan-bzhmu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yonca tarlasından bir tutamdır 

Gelincik bahçesinden bir lale

Bulutlardan bir damla nemdir

Sadece bir anlık zevktir

Irmaktan bir kap sudur

Dağdan bir kaya parçası 

Denizden bir dalga

Sadece bir anlık zevktir

Gül bahçesinden bir gül

Kır çiçeklerinden bir papatya

Ormandan bir ağaçtır

Sadece bir anlık zevktir

Ömürden bir andır

Hayatın güzelliklerinden  biri 

Üremede adımın   ilki 

Sadece bir anlık zevktir

Mertleri bozan

Dostu  düşman eden 

Kadını metaa eden 

Sadece bir anlık zevktir

Bağımlılıkların ilki 

Erkeğin ilk köleliği 

Soyun devamının tek çaresi

Sadece bir anlık zevktir', 'Yonca tarlasından bir tutamdır  Gelincik bahçesinden bir lale Bulutlardan bir damla nemdir Sadece bir anlık zevktir Irmaktan bir kap sudur D...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sadece-zevk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doyamam', 'doyamam-ethem-turan-cvwei', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Irmak olup aksam 

Denize kavuşsam

Kavuşma sevincini yaşarken 

Tuzlu suyunda  dağlansam 

Yelkenli olsam

Üzerinde konaklasam 

Dalganla  sallanıp 

Rüzgarınla  yol alsam 

İçinde yaşayan balık 

Suyuna mahkum,esir 

Ruhla beden gibi bir olsam 

Yinede doyamam sana', 'Irmak olup aksam  Denize kavuşsam Kavuşma sevincini yaşarken  Tuzlu suyunda  dağlansam  Yelkenli olsam Üzerinde konaklasam  Dalganla  sallan...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/doyamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anneler Gününde', 'bir-anneler-gununde-emrah-karakoc-e2tni', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Emlik kuzu ayrılsa anasından

Yaşanan anılar yeter mi ana? 

Bu dünya olup ta yüreğe zindan

Özlenen gözünde tüter mi ana? 

Çabuk geçti ana senli günlerim

Tütüyor gözümde mesut dünlerim

Gözümü kapatır seni dinlerim

Senin halin benden beter mi ana? 

Kör talih yüzüme gülmüyor benim

Yinede artmadı bahtıma kinim

Çok sordum kendime ana ''Ben kimim? ''

''Türk İslam''lık bana yeter mi ana? 

''Oğlum'' derdin okşardın saçlarımı

Görmezden gelirdin hep suçlarımı

Kaybettim hayatın ip uçlarını

Bu kara günlerim biter mi ana? 

Her gün anıyorum ana adını

Sen diye severim ben her kadını

Özlemle yad edip bu evladını

Yüreğin hasretle atar mı ana? 

Kara toprak aldı can gardaşımı

Hasretinden yere vurdum başımı

Evladın unutup arkadaşını

Yüreğinden söküp atar mı ana? 

Emrah''ın diyor ki; canımda cansın

Anam varsın benim yüreğim yansın

Varsın eller beni divane sansın

Bu can AZİZ CAN''ı satar mı ana?', 'Emlik kuzu ayrılsa anasından Yaşanan anılar yeter mi ana?  Bu dünya olup ta yüreğe zindan Özlenen gözünde tüter mi ana?  Çabuk geçti ana sen...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-anneler-gununde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adalet yerini bulmuyor kardeş.', 'adalet-yerini-bulmuyor-kardes-gulnare-leman-hidtp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir  garip hısslarla köklenip kalbim,

Bakdıkca yaşama  artıyor gamim,

Sanki  fırtınaya yol almış gemim..

Dünya mı tersine fırlıyor kardeş? 

Bu gün rast olmuştum bir dilenciye,

Benzettim,belki de yanlıştır diye? 

Gözümden  damladı yaş gile, gile..

Of, öğretmen de dileniyor kardeş.

Ne büyük,ne küçük sayğı kalmadı,

Daha  el öpmeğin ,çağı kalmadı.

Şu gönül dünyamın bağı kalmadı,

Çiçekler açmadan döküyor kardeş.

Allah bir güzellik vermiş herkese,

Ya uzun boylusun,ya boyu beste,

Kadınlar şimdi de düşmüş hevese

Plastik ameliyat  ediyor kardeş.

Şimdi  arabalar düşmüşdür moda,

Almakçın kendisin atıyor oda.

Köylerde tapılmaz daha bir at da,

Fiyatlı markalar taşıyor kardeş.

Hükmüne bir nazar yetir zamanın,

Kıymet koy farkına sen de yamanın,

Peyğemberin resmin çizen adamın

Kendisi dinini satıyor kardeş.

Açtım yüreğimi  ben yaprak,yaprak,

Orda temiz kalbe,taparsın merak,

Hak diye gezsemde elimde çırak,

Adalet yerini bulmuyor kardeş.', 'Bir  garip hısslarla köklenip kalbim, Bakdıkca yaşama  artıyor gamim, Sanki  fırtınaya yol almış gemim.. Dünya mı tersine fırlıyor kardeş?  ...', ARRAY['Türk Edebiyatı','Şiir','Gulnare Leman']::text[], 8.5, '{"poet":"Gulnare Leman","poet_slug":"gulnare-leman","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/adalet-yerini-bulmuyor-kardes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Roman -II-', 'roman-ii-nurten-koroglu-mw9g6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öylesine zor ki 

sineye dönmek

yüreğin,koskoca bir madet oluyor haykırdıkça

bir tek yankılanan sesin  ulaşıyor sana

bakmışsın bütün kapılar kapanmış üstüne

umutların küsüyor önce

sonra,

bir koyu yalnızlık daha

sonra,

narin bir çiçek gibi 

yaprakların eğiliyor

çatlamış toprağının  üzerine.

 Kalemin imdada koşuyor, fakat

 yazılan hiç bir kelime yerini bulmuyor

virgüller uzuyor da,uzuyor

sonu gelmiyor bu sonların

düşünüyorsun kendi kendine

hiçmi insafı yok 

bu noktaların.', 'Öylesine zor ki  sineye dönmek yüreğin,koskoca bir madet oluyor haykırdıkça bir tek yankılanan sesin  ulaşıyor sana bakmışsın bütün kapılar ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/roman-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acımak', 'acimak-nihal-cinar-fnjv3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kafi görünmediyse verdiğin acı

''Şifa niyetine'' der içerim zehirli şarabı

Ölümse ölüm,görmek isterdim seninle

Kısa süren ömre bedel saniyelik rüyayı

Son rüya olmasaydı keşke

Senin le kabuslarımada bu yürek razı

Hayaller süslemiyor artık 

Seninle düşlediğim zamanı

Gözlerim silik resmine razı

Acındırmak için değildi gözyaşları

İzin verseydin sel olup götürürdü belki acıyı

Yeni çiçek açmasada gönül,çöl olmaktan kurtulurdu.', 'Kafi görünmediyse verdiğin acı ''Şifa niyetine'' der içerim zehirli şarabı Ölümse ölüm,görmek isterdim seninle Kısa süren ömre bedel saniyelik...', ARRAY['Türk Edebiyatı','Şiir','Nihal Çınar']::text[], 8.5, '{"poet":"Nihal Çınar","poet_slug":"nihal-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/acimak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenin Ardından', 'gidenin-ardindan-emrah-karakoc-enk2h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüzgar savuramaz derdim

Hasretin savurdu beni

Güneş kavuramaz derdim

Yokluğun kavurdu beni

Hayalimde düşümdesin

Nere gitsem peşimdesin

Hem bahar hem kışımdasın

Bilmezliğin vurdu beni

Yokluğun düşürdü derde

Senin gözlerinde perde

Soruldumda yad ellerce 

Sormayışın yordu beni

Yürek sevdiğine pişman

Dilerim eline düşmen

Senli olan her şey düşman

Sade resmin sordu beni

Layık mı sevdiğin sana

İnan kin beslemem ona

Kurşun senden geldi bana 

Silahlar korurdu beni

Emrah der ki sevilmedim

Sevilen bilmez kıymetim

Üzmek değildi niyetim

Terk etmen doldurdu beni', 'Rüzgar savuramaz derdim Hasretin savurdu beni Güneş kavuramaz derdim Yokluğun kavurdu beni Hayalimde düşümdesin Nere gitsem peşimdesin Hem b...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gidenin-ardindan-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Aşk', 'i-lk-ask-erkan-ucar-h1zqz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgim bu kentin içinde sıkışıp kaldı

Yok muyum var mıyım bilemiyorum

Kendimi tüketiyorum sırf senin için

Ben buna ilk aşkım diyorum

Yalnızlık istiyorum, unutulmak istiyorum

Yokluğumla varlığım bir olsun istiyorum

Zalim bir şekilde parçalanmak

Ama aşkımla yeniden var olmak istiyorum

Hemencecik yaşlanmak, bunamak istiyorum

Her şeyi unutmak istiyorum seninle birlikte

Belki bunu yapacak gücüm yok olsa bile

Geçen zamanın beni sona götürdüğünü biliyorum

Sende beni sever miydin böyle delice

Başını duvarlara vurur muydun kim bilir 

Kendini yiyip bitirirmiydin sessizce

Ağlar mıydın benim gibi her şeye

Ben buna ilk aşkım diyorum

Korkuyorum, hem de çok korkuyorum

Tek olmaktan, tek kalmaktan

Dua ediyorum Allaha, son aşkımı istiyorum…', 'Sevgim bu kentin içinde sıkışıp kaldı Yok muyum var mıyım bilemiyorum Kendimi tüketiyorum sırf senin için Ben buna ilk aşkım diyorum Yalnızl...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ilk-ask-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin Anam', 'nerdesin-anam-mikdat-bal-gov2k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyaya gelmemde sensin vesile

Canıma can kattın nerdesin anam

Yetiştirdin beni bir heves ile

Bambaşka bir tattın nerdesin anam

Hep koşturdun gece gündüz demedin

Yedirdin içirdin kendin yemedin

Yoruldun sabrettin yatak sermedin

Ne dinlenip yattın  nerdesin anam

Şefkatine öyle muhtacım şimdi

İkiye katlanır her acım şimdi

Ancak sensin benim ilacım şimdi

Yüreğime battın nerdesin anam

Ararım her yerde bulamıyorum

Sensiz gurbet elde kalamıyorum

Bu dünyadan bir tat alamıyorum

Beni ele attın nerdesin anam

Yine bahar geldi çiçekler açtı

Doğaya ne güzel kokular saçtı

Beni hatırlayıp iştahın kaçtı

Kaşlarını çattın nerdesin anam

Mikdatî der yaşın silersin ana

Her zaman mutluluk dilersin bana

Çok şükür diyerek gülersin bana

Derdi kime sattın nerdesin anam', 'Dünyaya gelmemde sensin vesile Canıma can kattın nerdesin anam Yetiştirdin beni bir heves ile Bambaşka bir tattın nerdesin anam Hep koşturdu...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nerdesin-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kum Tanesi', 'kum-tanesi-erkan-ucar-u5k6d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çölde bir kum tanesi

Ne kadar küçük 

Ne kadar benzer

Bir o kadar çaresiz

Rüzgarın alıp savurduğu

Tüy gibi hafif

Bir o kadar güçsüz

Sarı bir kum tanesi

Ben çölde bir kum tanesiyim 

Diğerlerinden ayırt edilemesem de

Kendi içinde tek

Bir taneyim

Akıp gidiyorum sessizce

Nereye gittiğimi bilmeden

Bir yol arıyorum kendime

Yolu ben seçmesem de

İşte sonunda diyorum

Bende bir yerdeyim

Bir yerlere gitsem de

Ben hep aynı çöldeyim', 'Çölde bir kum tanesi Ne kadar küçük  Ne kadar benzer Bir o kadar çaresiz Rüzgarın alıp savurduğu Tüy gibi hafif Bir o kadar güçsüz Sarı bir ...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kum-tanesi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz Vak''a', 'umutsuz-vak-a-emrah-karakoc-3rti9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzel olan bütün her şey 

Cem olmuş onun yüzünde

Artık zevk vermez oldu ney

Tek zevkim yatmak dizinde

Melek gibi bir yüzü var

İnanın kibardan kibar

Gülüşü cana can katar

Mutluluk gizli sözünde

Bilmiyorum neredeyim

Yanında var mı değerim

Destur ver gülüm gireyim 

Huzur bulurum özünde

Artık aşka kanmam derken

Çıktın karşıma nereden

Kuş gibiyim yanındayken

Kovmada koşam peşinde

Hiç çıkmıyorsun aklımdan

Daha saklısın saklımdan

Herhal zorum var aklımdan

Olmak isterim düşünde

Ümit var mı bilmem ama

Gel de söz anlat Emrah''a

Sevgimi demedim daha

Belki söylerim düşümde', 'Güzel olan bütün her şey  Cem olmuş onun yüzünde Artık zevk vermez oldu ney Tek zevkim yatmak dizinde Melek gibi bir yüzü var İnanın kibarda...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/umutsuz-vak-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Nehiri', 'ask-nehiri-erkan-ucar-tk2um', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sev sevebildiğin kadar delice

Durma aksın bu aşk nehri

Kapıl deli sulara kaybol

Hisset aşkın sonsuz gücünü

Ne kadar mutlu ve umutlu

Ne kadar heveslisin böyle şeylere

Kapıldın sende hemen

Boş bir hevese

Bu nehirde sana yer yok

Yalnız akılmaz bu sularda

Tutunacak bir dal ister

Sende ise hiçbir şey yok

Nehir büyük sen küçük

Aşkın büyük sen küçük

Sen küçüksün küçücüksün

Yok olursun bu nehirde

Ne kaybettin bu nehirde

Kendini mi aşkını mı

Sorarım sana e adam

Sen aşktan ne anlarsın?', 'Sev sevebildiğin kadar delice Durma aksın bu aşk nehri Kapıl deli sulara kaybol Hisset aşkın sonsuz gücünü Ne kadar mutlu ve umutlu Ne kadar...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-nehiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur Dön / POPÜLER / ŞARKI', 'ne-olur-don-populer-sarki-zafer-ozkay-s08bz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu yaz yine yalnızım,

yine sensiz aylardır hasretim

Ne olur dön.

Sensiz olmuyor,

Geceler uyunmuyor,

Göz yaşlarım dinmiyor

Ne olur dön.

Sevmesende beni,

Özledim seni,

Duymasanda beni,

Ne olur dön bebeğim.

Ceza mı yar,

Sevmenin bedeli,

Hep yalnızlık mı? 

Yıllardır çektiğim 

Azap bitmeyecek mi? 

Ne olur dön.

Bir yanım çöl,

Bir yanım kutup,

Çöllerdeyim yanıyorum,

Kutuptayım üşüyorum,

Haram mısın bana anlamıyorum,

Ne olur dön kır çiçeğim benim.

          Şiir

Git gitmene bişey demem ama.. 

Ama ya ellerim ellerini özlerse.. 

Ya bedenim bedenini yanında isterse.. 

Ya nefesini tenimde duymak istersem.. 

Ya kokunu duymak istersem.. 

Şunu unutma...

Aşkımız bir kar tanesi gibi

beyaz olmadı olmaycak...

Hiç bir zaman sen beni sevmedin...

Oysa,

Ben seni çok sevdim...

sana kavuşamasam da...

Gelmeyeceğini bilsem bile...

Yine de söylüyorum...

Ne olur dön  dön aşkım.

                                           Söz - şiir: Zafer Özkay - 12.02.2006 - Karaman', 'Bu yaz yine yalnızım, yine sensiz aylardır hasretim Ne olur dön. Sensiz olmuyor, Geceler uyunmuyor, Göz yaşlarım dinmiyor Ne olur dön. Sevme...', ARRAY['Türk Edebiyatı','Şiir','Zafer Özkay']::text[], 8.5, '{"poet":"Zafer Özkay","poet_slug":"zafer-ozkay","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ne-olur-don-populer-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-erkan-ucar-1wmgb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buraya kadar mı bu macera

Bitti mi her şey bir anda

Kaçtı mı elimden mutluluk 

Elimde değil yürekte boşluk

Ne var bundan sonra

Tek mi kaldık yoksa

Neyi sevicem

Göremiycem mi seni yoksa

Ben bunu hiç istemezdim

Hiç bitmesin derdim

Son olamazdı asla

Kör aşktı nede olsa

Bu bir başlangıç olmalı

Yeniden hayata atılmalı

Aklımı kaybetmeden

Yeni sulara açılmalı

Sudan çıkmış balık misali

Yeni baştan başlamalı

Bu da geçer elbet

Her sonun bir başlangıcı olmalı', 'Buraya kadar mı bu macera Bitti mi her şey bir anda Kaçtı mı elimden mutluluk  Elimde değil yürekte boşluk Ne var bundan sonra Tek mi kaldık...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-122-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Şehir', 'i-ki-sehir-erkan-ucar-yk3cd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki şehir düşünsen

Biri çok kalabalık

Biri ise bir o kadar küçük

Unutulmuş terkedilmiş

Ben o küçük şehrin insanı

Şehirle birlikte unutulmuş

Hiç anımsanmamış 

Hiç düşünülmemiş

Sadece yol üstü olmuş

Üstünden geçilmiş

İçine girilmiş

Ama hiç özümsenmemiş

Bu şehrin insanları gaddar

Katı ve kuralcı

Ben hiç kuralcı olmadım

Ama hep bu şehirde yaşadım

Bu şehrin insanları birbirine benzer

Ben benzemek istemesem de

Bir parçam olmalı bu şehirde

Budur beni buraya zincirleyen

Zincirlerimi hiç kırmadım ki

Hiç düşünmedim böyle şeyler

Kendimi bile aşamadım

Mutluymuş gibi hep yaşadım

Yine böyle bir hayat mı

Hep monoton ve sıradan

Sıradan olmak kaderimse

Yaşarım bunu da sonuna kadar 

Ben hep korktum yeni şeylerden

Hep kaçındım o büyük şehirden

Bu şehirde bile fark edilemezken

Yok olurum biliyorum o şehirde

Ömür bu sonsuz değil ya

Her şeyin bir sonu varsa

Benim de sonum olacak

Mutlu olmasam da yaşanacak', 'İki şehir düşünsen Biri çok kalabalık Biri ise bir o kadar küçük Unutulmuş terkedilmiş Ben o küçük şehrin insanı Şehirle birlikte unutulmuş ...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/iki-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Sevgililer günü * düz yazı', 'sevgililer-gunu-duz-yazi-tulay-i-cen-qnyaf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Can merhaba..

Sevgililer  günün  kutlu olsun.

Dün dediğim gibi  bu  gün sana  geldim  başında  seni sevdiğimi  söyledim  ama  bana  cevap vermedin, küskünlüğün  hala  devam ediyor  7  sene oldu sen bizlere  küssün  bizimle  konuşmuyorsun.

Can  sana  kavuşana  kadar  ben hep  bunları  söyliyeceğim.

Can  bu gün  sana  daha  farklı  şeyler  söyliyeceğim.

Can  sevgi  paylaşıldığında  tadına  doyulmuyor seni  kelimelerle  anlatılmayacak  kadar  çok  sevdim.

Bunu  seni  kaybedince  daha  cok  anladım.Harika bir eştin,Dostum Sevgilim  benim  seni  hep  sevdim  her zaman  seviceğim.Mutluluğumu  kaybettim yeniden bulabilirmiyim,tekrar  mutlu  günlere  döne bilirmiyim.

Seni  sevmek mutluluk bunu  biliyorum ama   sen olmayınca mutlu  olunmuyor.İnan  seni  çok  özledim sensizlik  bana  çok  ama çok  acı  veriyor.

Sevgisiz  yaşanırmı  bir tanem,

Yaşanmaz elbet  yaşanmaz Sevgilim.

Tut elimden  al beni  yanına.

Sana  muhtacım senin  sevgine muhtaç...

Can seni  seviyorum.

Seni seviyorum.

Sevgililer  günün kutlu olsun.

14/02/2000', 'Can merhaba.. Sevgililer  günün  kutlu olsun. Dün dediğim gibi  bu  gün sana  geldim  başında  seni sevdiğimi  söyledim  ama  bana  cevap ve...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgililer-gunu-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalci', 'hayalci-erkan-ucar-bf564', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen beni hiç görmedin, düşünmedin

Bir kez bile adımı ağzına almadın ki 

Ne var sanki ben zaten yoktum

Belki bir kere senle var olurdum

Belki bir kere var olmak var ya

Hep aynı düzen içindedir bu dünya

Bir kere doğar bir kere ölürüz

Ben  hiç doğmadım ki daha

Tek bir şansım olsa kullanmaz mıydım

Neler yapmazdım var olmak için

Her şey senin elinde ise

Keşke bundan habersiz olmasaydın

Tutsan elimden sıkı sıkıya

Hiç bırakmasan var olana kadar

Sonra ezsen yok etsen

Bir kere var olayım şu dünyada

Ezsen de yok etsen de 

Mutlu bir yürek var artık

Dünyanın düzeni bu karsı konmaz

Buna benim de uymam lazım

Bir anlık mutluluk yetti bana

Bunlar birer hayal olsa da

Hayali bile mutlu ediyorsa

Kur hayalini hiç durma', 'Sen beni hiç görmedin, düşünmedin Bir kez bile adımı ağzına almadın ki  Ne var sanki ben zaten yoktum Belki bir kere senle var olurdum Belki...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hayalci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek', 'melek-erkan-ucar-jj4wh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin ne olduğunu çok düşündüm

Bir çiçek miydin acaba

Belki dedim kendi kendime

Ama sen bir çiçek değildin

Çiçekler güzel ve saftırlar

Sende öyleydin ama

Kalıcıydın benim yüreğimde

Çiçekler solardı her zaman

Sonra anladım senin ne olduğunu

Sen bir melektin benim yüreğimde

Sonsuz yaşamı olan bir melek

Sonsuzluğu benim yüreğimde

Bu melek bana güç verdi

Yaşamak için heves verdi her gün

Melek varlığıyla yanımda olmasa da

Bir parçası hep yüreğimdeydi

Hiç ulaşamadığım bir melektin

Ne kadar uzaktın bana

Ama ben seni hep yanımda düşledim

Düşlerimle hayat buldum şimdiden

Sonra düşündüm yeniden sessizce

Ben neydim bu dünyada

Ben her halde bir çiçektim

İlk defa açmıştım senin elinden

Çiçekler solarlar ya kısadır ömürleri

Benim de ömrüm kısa olacaktı

Bunu biliyordum ama

Açtım bir kere gözlerimi dünyaya

Üzerine yağmurlar yağdı 

Fırtınalar koptu ezercesine

Ama o çiçek hiç solmadı

 Onu yaşatan meleği vardı.', 'Senin ne olduğunu çok düşündüm Bir çiçek miydin acaba Belki dedim kendi kendime Ama sen bir çiçek değildin Çiçekler güzel ve saftırlar Sende...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/melek-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektup', 'sevgiliye-mektup-emrah-karakoc-0qefd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Solmayacak bir gül sanma kendini

Sende solacaksın günün birinde

Hem beni bitirdin hemde kendini

O güzel ellerin elin elinde

Son bahar mevsimi gelince dallar

Rabb''imin hikmeti bir bir solarlar

Sanada sevgilim bir gün sorarlar

Ne oldu da gitti yarin ellere

Ben sana sevgimi haykırdım durdum

Sen bana hep acı hep keder sundun

Buda yetmez gibi ellerin oldun

Bak şimdide düştük elin diline

Aşk kalkan sevgiyse en büyük silah

Her zaman doğru ol yardımcın ALLAH(C.C) 

Sen beni yandırdın yandırmaz günah

Eğer ki düşersem o cehenneme', 'Solmayacak bir gül sanma kendini Sende solacaksın günün birinde Hem beni bitirdin hemde kendini O güzel ellerin elin elinde Son bahar mevsim...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgiliye-mektup-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Habersiz Sevenler', 'habersiz-sevenler-erkan-ucar-okcao', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Habersiz sevenlerin dünyasındanım artık

Biletim kesilmiş girmişim içeri

Burası çok kalabalık olmalıydı

Habersiz olsa da bilinmedik değildi

Kimseyi bulamadım bu dünyada

Kördür insanlar bu karanlıkta

Karanlıkta yolumu ararken

Rastlamadım bir kör aşığa

Nefesim kesildi birden

Boşluğun ortasında kalıverdim aniden

Kalp atışlarımı duyamıyordum

Ben miydim bu boşluğa düşen

Kendimi bir yerde buldum

İrkildim kendi kendime sordum

Ne olmuştu birden bana

Yok mu oluyordum karanlık boşlukta

Orda bir ışık gördüm

Koştum o ışığa durmadan

Işık beyaz kaplı bir defter idi

Aldım elime hiç durmadan

Yazdım o deftere bütün her şeyi

Hiç durmadan onu sevdiğimi

Her şeyi anlattım bir kerede

Bir iz bırakmıştım bu kara delikte

Anladım ki bu dünyanın en sonu

Kimse ulaşamamıştı beyaz deftere

Bir gün biri daha severse böyle

Ulaşır belki karanlıktaki sevgiye

Okur yazdıklarımı bir hevesle

Yalnız olmadığını anlar birdenbire

Ne kadar bilinmeyen varsa sevgide

Hepsi burada habersiz sevgide', 'Habersiz sevenlerin dünyasındanım artık Biletim kesilmiş girmişim içeri Burası çok kalabalık olmalıydı Habersiz olsa da bilinmedik değildi K...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/habersiz-sevenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-zeki-ergin-i4ah3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'karlı bir şubat günüydü

kara haberin

kara bir kış gibi gelmişti

üşümüş donmuştu yüreğim

sızlamıştı burun direğim

ey güzel insan

sen gittin gideli 

özlemle geçti 23 yıl

her düştüğümde dara 

bunaldığımda hayatın girdaplarında

sen vardın yanımda

bana bıraktığın en büyük servet

doğruluk 

ve sevmekti insanları

en zor günlerimde

hayat felsefenle aştım her zaman dağları

_erenköy 13şub06

_dağlara ver sırtını yt:haz09', 'karlı bir şubat günüydü kara haberin kara bir kış gibi gelmişti üşümüş donmuştu yüreğim sızlamıştı burun direğim ey güzel insan sen gittin g...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/baba-338-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalp', 'kalp-erkan-ucar-u35vo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç seninle yüz yüze gelmeden

Hiç konuşmadan, dertleşmeden

Hiçbir şey paylaşmamışken

Nasıl böyle sevebildim ki seni

Çok insan gördüm

Çok şey paylaştım onlarla

Bazılarını sevdim sandım

Seni bilince yanıldığımı anladım

Aşkı hiç yaşamamışken

Hep aşkın var olduğuna inandım

Eski kalp yaralarımın gerçek olmadığını

Ancak seninle anladım

Bu kalpteki yara gerçek ise

Buna bir çare bulmalı

İmkansız olanı istemekle bitse

Çoktan bitmiş olmalıydı

Ama hiçbir şey bitmedi

Bu yara zamanla iyileşmedi

Zaman buna çare değilse

İmkansız çarelerle yaşamayı öğrenmeli

Hala bu kalp atıyorsa

Kanım damarlarımda dolaşıyorsa

Bir çare var mı zanneder

Durmadan akmaya devam eder

Bırakın öyle kalsın

Bir çözüm yolu var sansın

İmkansızı fark edene kadar

Mutlu bir şekilde yaşasın', 'Hiç seninle yüz yüze gelmeden Hiç konuşmadan, dertleşmeden Hiçbir şey paylaşmamışken Nasıl böyle sevebildim ki seni Çok insan gördüm Çok şey...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kalp-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fark', 'fark-erkan-ucar-gqae7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben karların içinde debelenen

Elleri buz tutmuş, yinede gülümseyen

Beline kadar karda zar zor yürüyen

O eski anılardaki çocuğum

O çocuk ki çok sevilen

Sevildikçe yüz bulunup  incitilen

Kötülük nedir bilmeyen

Kalbi kırık o çocuğum

O çocuk içinde olanı yansıttı

Tek istediği mutlu olmaktı

Elinden geleni hep yapardı

Tek derdi diğerlerinden farkıydı

Çocuk bilmezdi neydi farkı

Ama onu tanımadan anlaşılırdı

Tek kelime etmeden

Bir köşeye siner ağlardı

Göz yaşlarının çaresi yok gibiydi

Kan ter içinde uyanırdı geceleri

Nefes almak bile zor gelirdi

Her sabah o cümbüşe  geri dönerdi

Böyle bir hayat yalnızlık getirdi

Korku getirdi ama öfkeli değildi

Kendini mutlu etmeyi kısmen öğrendi

Böylece bu zamana geldi

Böyle farklı olmasaydı

Farksızlar içinde farksızı oynasaydı

Ne olurdu bilinmezdi

Belki böylesi daha iyi

Farklılık ayırt edilme ise

Hiç birine benzemedi senelerce

Hep kendi gibi oldu

Tertemiz kalbini buraya kadar korudu

Bundan sonra yolu açık

Farksızlardan fark edilemiyor artık

Bu bir ödül ise tam zamanı

Yaşamalı nede olsa farkı vardı', 'Ben karların içinde debelenen Elleri buz tutmuş, yinede gülümseyen Beline kadar karda zar zor yürüyen O eski anılardaki çocuğum O çocuk ki ç...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/fark-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetten Sevgiliye', 'gurbetten-sevgiliye-emrah-karakoc-pw9jc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık gecede yıldızlar söndü

İçime ayrılık acısı düştü

Bütün gurbetciler evine döndü

Ben hala hasretim güzel sılama

Ayrılık hasreti vurur kalbime

Sevdiklerim şiir oldu dilimde

Ben ölürsem neyim kalır elinde

Hasrtet tohumunu ektin tarlama

Ağlamak ne çare ağlayamam ki

Ben kalbimi her gün dağlayamam ki

Beni sorarlarsa onlara de ki

''Emrah yatar benim kalp ocağımda''', 'Karanlık gecede yıldızlar söndü İçime ayrılık acısı düştü Bütün gurbetciler evine döndü Ben hala hasretim güzel sılama Ayrılık hasreti vurur...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbetten-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-erkan-ucar-1qet6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün o umut dolu gözlerini yeniden

O güzel gülüşünü, güzel sesini

Nur yüzünü, seni

Evet seni gördüm bugün yeniden

Kalbimdeki acıyı daha derin hissettim

Gece uyku girmedi yaşlı gözlerime

Kapatmaktan korktum gözlerimi

Kaybederim sandım içimdeki şeyleri

Ben bu duygularımı isimlendiremedim

Nedir dedim mutlu muyum senle ben

Yoksa mutsuz mu oluyorum seni görmeden

İki duyguyu da yaşıyorum istemeden

Ne mutlu ne mutsuz oluyorum

Aslında ikisini de beraber yaşıyorum

Seni görmenin sevincini yaşarken

Aradaki mesafe yıkıyor aniden

Bir insan hem mutlu 

Hem de mutsuz olur mu ki

Ben neden böyleyim bilmiyorum

Bu duyguları ayrı ayrı yaşayamıyorum

Mutluluk nedir benim için

Karnı tok, sırtı pek değil elbet

Ben farklı şeylerde mutluluğu arıyorum

Geceleri sırf bu düşüncelerden uyuyamıyorum

Ama sen mutlusun biliyorum

En azından öyle görünüyorsun

Sen mutluysan ben daha ne isterim

Bu yaşama devam ederim

Yaşamak kolay şey, hayat devamlı

Bir ok gibi fırlayıp

Bir yerlerde düşüyor aniden

Sonra her şey bitmiş oluyor istemeden

Bazen bu ok doğru yerde

Mutlu bir kalpte bitiveriyor 

O zaman mutlu bir yaşam var olup

Sonun bir anlamı kalmıyor

Neden varız biz bu dünyada

Ben var olmayı hiç istemedim daha

Ama varsam neyi bekliyorum

Sonunu biliyorsam neden yaşıyorum

Bildiklerim ve bildiğimi zannettiğim her şey

Ne kadar gerçek ve yaşanabilir

Ben mi seçtim bu hayatı demeden

Yaşıyoruz bu dünyada ne sebepten

Benim sebebim sensin cici kız

Seni seviyorum, sana tapıyorum

Sonsuza kadar var olamayacaksam

Sevgimle bir teselli buluyorum

Sen benim yaşama sebebim

Sabah uyandığımda nefes aldığım

Uyuyamadığım gecelerde hep seni düşündüğüm

Yegane tek sebebimsin

Bu koca cüssenin kalbi

Sana sesleniyorum sebebim var

At, hiç durma daha

Yaşanacak güzel günler var

Yalnız çarpan kalbim

Bir gün değerin bilinecek

O gün geldiğinde elbet

Daha mutlu günlerde gelecek', 'Bugün o umut dolu gözlerini yeniden O güzel gülüşünü, güzel sesini Nur yüzünü, seni Evet seni gördüm bugün yeniden Kalbimdeki acıyı daha der...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/o-gun-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki', 'sanki-neyyir-aribas-80zuq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünyada bir sen kaldın mı sanki

Gönlüme girdin, neden sanki

Her gün kapris, ihtiras, ızdırap

Yoluma çıkmış cellatmış sanki

Bir günüm olsun güzel seninle

Çocukça yaşarım bayram ile

Şer mi doldurdun o kalbine

Yalnız günlere kurbanım sanki

Anlaşılmaz duyguların sahibi sensin

Gönlümde yanan alevim sensin

Biraz beni sevmekle dolsun aklın

Boşa çekilen küreklerin sandalıyım sanki.', 'Dünyada bir sen kaldın mı sanki Gönlüme girdin, neden sanki Her gün kapris, ihtiras, ızdırap Yoluma çıkmış cellatmış sanki Bir günüm olsun g...', ARRAY['Türk Edebiyatı','Şiir','Neyyir Arıbaş']::text[], 8.5, '{"poet":"Neyyir Arıbaş","poet_slug":"neyyir-aribas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sanki-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşkın', 'saskin-erkan-ucar-n04f7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elime kalemi her alışımda

Acı çektiğimi daha iyi anlıyorum

Ama yine de elimde kalem

Bir şeyler karalamak istiyorum

Ne yazdığım yada yazacağım 

Önemli olan dışa vurduğum

İçimden o anda attığım

Dert gibi sırtımda taşıdığım

Unutmak için çok çabaladığım

Ama hiç unutamadığım

Aşkım için yazıyorum

Sırf senin için yaşıyorum

Ne yaşam benimki de

Soruyorum kendi kendime

Hiç aşık oldun mu? 

Hiç yaşadın mı böyle şeyler

Hayır, hiç ama hiç

Yaşamadım,yaşamam sanmıştım

Büyük konuşmuş olmalıydım

Nede olsa halim anlatırdı

Aşkım diye bağırsam dışarıya

Ne olur bilmem ama

Sen duyar mıydın sesimi

İşte o zaman haykırırdım

Seni seviyorum! 

Hem de çok, ne çok! 

Çok işte belki sonsuz

Belki de daha öte

Sevginin ölçüsü var mı ki

Nasıl ifade edeyim bilmem

Her şeyi koysam bir kefeye 

Her şeye üstün sevgim bilirim ben

Bu yazdıklarımı okur musun bir gün

Ne demiş bu çocuk dersin

Şiir mi yazmış, ne bu be

Yazık o yazdığın güzel deftere

Belki de seversin ne bileyim

Hoş dersin, sevilmek güzel

Sevsin bakalım, yazsın şiirini

Zararsız aşık takılsın kendince

Belki acırsın, belki nefret eder

Belki sever, belki merak eder

Belki hiç umursamaz

Ezer geçersin hiç düşünmeden

Bilmiyorum ki güzel insan

Sana ilk ne demeli

Kendimi nasıl tanıtmalı

Sana nasıl seslenmeli

Ama ne olursa olsun

Seni çok iyi tanıyorum

Sen güler yüzlü, sevecen

Çok iyisin, daha ne desem

Ama ben iyi miyim senin kadar

Sana arkadaş olmaya layık mıyım? 

Bilmem ama yalnız seni

Evet,seni sevdiğimi bilirim ben', 'Elime kalemi her alışımda Acı çektiğimi daha iyi anlıyorum Ama yine de elimde kalem Bir şeyler karalamak istiyorum Ne yazdığım yada yazacağı...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/saskin-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Varlığım Yokluğumdan İbaret', 'benim-varligim-yoklugumdan-i-baret-muhammed-mehmet-gul-xbcr0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Milatsız bir günde kaybettim başım yok

Unufak olmuş mezarımda taşım yok

Asırlar geçti takvimsizim yaşım yok

***Benim varlığım yokluğumdan ibaret.

Kimseler bilmedi halimi sözüm tok

Bana birşey vaad etmeyin gözüm tok

Haramı görmedim ömrümce özüm tok

****Benim varlığım yokluğumdan ibaret.

Bu devranda yaşamak çok zordu çok

Her önüne gelen sorular sordu çok

Bu muamma sırlarla beni yordu çok

***Benim varlığım yokluğumdan ibaret.', 'Milatsız bir günde kaybettim başım yok Unufak olmuş mezarımda taşım yok Asırlar geçti takvimsizim yaşım yok ***Benim varlığım yokluğumdan ib...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benim-varligim-yoklugumdan-ibaret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Dörtlük', 'dort-dortluk-neyyir-aribas-l2a1y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Havalandırma kuyusundan at beni

Desandreden gel de galeride tut beni

Eğer yorgun argın düştüysen

Gel de serin uzun ayaklarda uyut beni

Vantüp''ün önünde durdum eser seher yeli

Bre zalim yeni geldim başyukarı, sırtım terli

Gözlerim bulut bulut, çisil çisil umut

Çizmemden taşan hangi pompanın seli

Karpit lambamda ayna var, ayna var

Madenci dostum ciğerlerinde kara leke var

Gözlerinden belli kan çanağı sanki,

Sende ince hastalığın izleri var

Gölgem düşmüş önüme, tahkimat düştü sandım

Domuz damında çalış dediler, saray sandım

Yer altına inince baba mı derler adama

Tren gelir hoş gelir dediler de, kandım', 'Havalandırma kuyusundan at beni Desandreden gel de galeride tut beni Eğer yorgun argın düştüysen Gel de serin uzun ayaklarda uyut beni Vantü...', ARRAY['Türk Edebiyatı','Şiir','Neyyir Arıbaş']::text[], 8.5, '{"poet":"Neyyir Arıbaş","poet_slug":"neyyir-aribas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dort-dortluk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlarım', 'yildizlarim-neyyir-aribas-aongh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde yıldızlar pek çoktur

Say deseler sayamam

Uzakta parlayan noktalar

Yıldız desem inanmazlar

Gece gördüğüm ışıltılar

Duygusallığımı hatırlatırlar

Türküler söyleyesim gelir

Henüz daha uyumadan

Oysa olsa gökte yıldızlar

O anda tazelense anılar

Küçük ayı, büyük ayı göz kırpsınlar

Ama bulutlar izin vermez ki! 

İşte böyle gecelerde görürüm yıldızları

Yıldız dedimse parlayan noktaları

O ışıltılar yıldız değil,

Ekskavatör''ün lambaları....', 'Gökyüzünde yıldızlar pek çoktur Say deseler sayamam Uzakta parlayan noktalar Yıldız desem inanmazlar Gece gördüğüm ışıltılar Duygusallığımı ...', ARRAY['Türk Edebiyatı','Şiir','Neyyir Arıbaş']::text[], 8.5, '{"poet":"Neyyir Arıbaş","poet_slug":"neyyir-aribas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yildizlarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adalet Nerde?', 'adalet-nerde-seyfet-bozcali-klkun', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bunca haksızlığı var mı durduran? 

Zalimin zulmüne yok karşı duran,

Gittikçe çoğaldı,hep vuran kıran,

Toplum soyulurken adalet nerde? 

Ümitler kaybolmuş,fertler perişan,

Bu kötü gidişle var mı barışan? 

İyi bir makamda yok ise arkan,

Nerde insan hakkı,adalet nerde? 

Terör,vahşet,kapkaç doldu şehirler,

Eli kolu bağlı kalmış polisler,

Ne zaman dinecek bu yakarışlar? 

Nerde mazlum hakkı,adalet nerde? 

    13.02.2006', 'Bunca haksızlığı var mı durduran?  Zalimin zulmüne yok karşı duran, Gittikçe çoğaldı,hep vuran kıran, Toplum soyulurken adalet nerde?  Ümitl...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/adalet-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ona Yanarım', 'ben-ona-yanarim-mihrican-karaca-umnx7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dokuz canım olsa,birini vermem

Oyuna bir defa gelinir,birdaha gelmem.

Sahipli birini mi asla sevmem,

Ömrüm felak olmuş,ona yanarım.

Ben bu sözleri hiç hak etmedim,

Başının üstüne iki boynuz dikmedim.

Sende çektiğimi,ömrümde çekmedim

Ömrüm felak olmuş,ona yanarım.

Senin kelamınla orospu olmam,

Gül döksende yollarıma,artık kanmam.

Bundan sonra mutlu olacağımı sanmam,

Ömrüm felak olmuş,ona yanarım.', 'Dokuz canım olsa,birini vermem Oyuna bir defa gelinir,birdaha gelmem. Sahipli birini mi asla sevmem, Ömrüm felak olmuş,ona yanarım. Ben bu s...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-ona-yanarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemezsin', 'sevemezsin-neyyir-aribas-rva58', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elleri yanı başındadır

Dokunamazsın

Süzülür manalı gözleri

Bakamazsın

Rüzgarla savrulur saçları

Tutamazsın

Hasreti işlemiştir ruhuna

Koşup öpmek geçer içinden

Gidemezsin

Bir merhaba yasaktır

Selam diyemezsin

Düğümlenir boğazın konuşamazsın

O an ölmek istersin

Ölemezsin

Sahil yolu zindan

Ben mahkum sen gardiyan

Acıya boğar beni sevdan

Dayan yüreğim dayan', 'Elleri yanı başındadır Dokunamazsın Süzülür manalı gözleri Bakamazsın Rüzgarla savrulur saçları Tutamazsın Hasreti işlemiştir ruhuna Koşup ö...', ARRAY['Türk Edebiyatı','Şiir','Neyyir Arıbaş']::text[], 8.5, '{"poet":"Neyyir Arıbaş","poet_slug":"neyyir-aribas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevemezsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakarış', 'yakaris-i-rfan-kayagil-lby18', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnanırsan anlarsın

Yarattığı canlarsın

Bu can sana emanet

Canlara can katansın

Yaratan da o hikmet

Verirse bize nimet

Kıymetini bilelim

Sağlık sıhhat afiyet

Dert verirse devası

Mutluluktur sefası

Girersen bir günaha

Ahrettedir cezası

Hatan olursa İrfan

Yaradan a sığınsan

Affeder elbet seni

Gönülden İnanırsan

(Ankara, 2002)', 'İnanırsan anlarsın Yarattığı canlarsın Bu can sana emanet Canlara can katansın Yaratan da o hikmet Verirse bize nimet Kıymetini bilelim Sağl...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yakaris-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-emrah-karakoc-ro3pj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Taşkın seller gibi akıp gitmeyin

Ne olur günlerim dinlenin biraz

Beni böyle meçhullere itmeyin

Ne olur günlerim dinlenin biraz

Niye bu acele, neden bu sürat

Yetişemez size vallahi kırat

İmkansız mı bana verseniz berat

Ne olur günlerim dinlenin biraz

Merhaba diyorum sana, merhaba

Merhaba de bana, olma ya kaba

Olmaya bu kadar emeğim heba 

Ne olur günlerim dinlenin biraz

Kesin biraz hızı basın firene 

Fırsat verin biraz gülü derene

Tevazu gösterin sevilenlere

Ne olur günlerim dinlenin biraz

Hata sizde değil hata bendeyse

Beni doğruluğa götür öyleyse

Karakoç''un sözü size geçerse

Ne olur günlerim dinlenin biraz', 'Taşkın seller gibi akıp gitmeyin Ne olur günlerim dinlenin biraz Beni böyle meçhullere itmeyin Ne olur günlerim dinlenin biraz Niye bu acele...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/merhaba-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı', 'ayni-neyyir-aribas-n5q39', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçmiyor günlerim 

Hep aynı günde gibiyim

Her gün görüyorum bu yerleri

Yüzler aynı, insanlar aynı

O yatakta yatıyorum hep yalnız

Aynı yatakta görüyorum rüyaları, hep aynı

Dört katın merdivenlerini çıkıyorum

Basamakları aynı.

Geçiyor ayak bileklerime kalın demir halka

Hapishanede yaşıyor gibiyim

Her gün çekiyorum bu zincirleri

Prangalar aynı, parmaklıklar aynı

Koğuşta sabahlıyorum gece yalnız

Yaşamın tekdüzeliği hep aynı

Dört duvar arasında dolaşıyorum

Bekleyen gardiyan aynı.', 'Geçmiyor günlerim  Hep aynı günde gibiyim Her gün görüyorum bu yerleri Yüzler aynı, insanlar aynı O yatakta yatıyorum hep yalnız Aynı yatakt...', ARRAY['Türk Edebiyatı','Şiir','Neyyir Arıbaş']::text[], 8.5, '{"poet":"Neyyir Arıbaş","poet_slug":"neyyir-aribas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayni-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-erkan-ucar-s9a3i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece açılmak istemem gene

Derin sularda boğulmadan

Geçsin isterim bu gece de

Sessiz ve derinden

Çığlık atmak isterim

Duysunlar alsınlar beni artık

Yeter derim içimden sessizce

Korkarım ses vermeden

Geceler beni alır götürür

Sessiz ve ürkek ben

Uçar giderim ellerinde

Bu gece de ben en derinde

Nefesimi tutarım derinden derine

İndim ise en dibe en kötüye

Bir ses ile en güzel yerinde

Uyanırım her şey senin elinde', 'Bu gece açılmak istemem gene Derin sularda boğulmadan Geçsin isterim bu gece de Sessiz ve derinden Çığlık atmak isterim Duysunlar alsınlar b...', ARRAY['Türk Edebiyatı','Şiir','Erkan Uçar']::text[], 8.5, '{"poet":"Erkan Uçar","poet_slug":"erkan-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gece-212-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalıtım', 'kalitim-neyyir-aribas-gu5c8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soyum Karacoğlan''a uzanır bir yandan

Ozanlığım ondandır benim

Bir yandan da Mecnun''a uzanır

Karasevdalılığım ondandır benim

Karacoğlan diyar diyar,

Mecnun çölde aramış Mevla''yı

Ölmüşler, bulamadan Leyla''yı

Bakıyorum da yaşamıma 

Ne fayda soya çekmişim....', 'Soyum Karacoğlan''a uzanır bir yandan Ozanlığım ondandır benim Bir yandan da Mecnun''a uzanır Karasevdalılığım ondandır benim Karacoğlan diyar...', ARRAY['Türk Edebiyatı','Şiir','Neyyir Arıbaş']::text[], 8.5, '{"poet":"Neyyir Arıbaş","poet_slug":"neyyir-aribas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kalitim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz', 'karadeniz-neyyir-aribas-zb03i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir haykırışın dolunayısın yaz günü

Uğuldayan tepelerinde yakamozun

Sabah güneşi gibi doğdun aniden

Ölü canlar yeşerdi topraklardan 

Gözlerin gece mavisi, neylerim

Yolumu bulamam kaybolur giderim.

Türkü tadında sesin, goncaya hapsolan

Yanık ezgilerinde dolaşan bir sazın

Sabah güneşi gibi doğdu nur yüzün

Don nehirler çağladı aniden

Gözlerin gece perisi, neylerim

Yolumu bulamam kaybolur giderim.

Gözleri

           Kara

                   Deniz

                            Çırpınır

                                       Yüreğimde....

Hilal kaşların, eğilmez sancağıma işlenmiş

Uğruna ölünen o yüksek değerlerin

Rüzgar gibi ürperdi içim aniden

Sevda nameleri döküldü dilimden

Gözlerin grafit ışıltısı, neylerim

Yolumu bulamam kaybolur giderim.

Ruhum gölge olmuş sana bedenimden sıyrılan

O benim, o yanındaki senden olan

Rüzgar gibi esti saçların yüzüme

Dudaklarını hissettim aniden

Gözlerin yağmur bulutu, neylerim

Yolumu bulamam kaybolur giderim.

Gözleri

           Kara

                   Deniz

                             Çırpınır 

                                         Yüreğimde....', 'Bir haykırışın dolunayısın yaz günü Uğuldayan tepelerinde yakamozun Sabah güneşi gibi doğdun aniden Ölü canlar yeşerdi topraklardan  Gözleri...', ARRAY['Türk Edebiyatı','Şiir','Neyyir Arıbaş']::text[], 8.5, '{"poet":"Neyyir Arıbaş","poet_slug":"neyyir-aribas","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/karadeniz-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sardı hasretin kolları', 'sardi-hasretin-kollari-fadime-dizdar-z59tz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İblis uykudan uyandı,

Gök kuşağı alev aldı.

Dön de şöyle yarına bak,

Ne namus  ne şeref kaldı.

Bazıların suratında,

Bin bir tane maskesi var! 

O körpecik bedenini,

Kudurmuş kurtlara satar...

Koy başını döşüme,

Sönsün yanan yüreğim.

Saçlarıma karlar yağdı,

Gün doğmadan bebeğim.', 'İblis uykudan uyandı, Gök kuşağı alev aldı. Dön de şöyle yarına bak, Ne namus  ne şeref kaldı. Bazıların suratında, Bin bir tane maskesi var...', ARRAY['Türk Edebiyatı','Şiir','Fadime Dizdar']::text[], 8.5, '{"poet":"Fadime Dizdar","poet_slug":"fadime-dizdar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sardi-hasretin-kollari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakıf', 'vakif-neyyir-aribas-hlcwa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Harman olur buğdayım aş için

Tarlada tohumum uçan bir kuş için

Hangi derde derman olayım çare için

Damlayan sular göl olur vakıf için

Bir elin nesi var? iki el gerek

Önümüze çıkar hep bir engerek

Türlü türlü çıkan sorunlar için,

İmdada yetişen bir vakıf gerek

Ağaç dikilir imece ile orman olur

Dağ başını almış dik yamaçlar duman olur

Her bağın bir bağcısı olur da,

Vakıfsız bir dünya viran olur

Neyyir Can''ım can gelir gayri

Kuruyan damardan kan gelir gayri

Millet el ele birlik olmuşsa eğer,

Düze çıkar dağlar, vakıf olur gayri', 'Harman olur buğdayım aş için Tarlada tohumum uçan bir kuş için Hangi derde derman olayım çare için Damlayan sular göl olur vakıf için Bir el...', ARRAY['Türk Edebiyatı','Şiir','Neyyir Arıbaş']::text[], 8.5, '{"poet":"Neyyir Arıbaş","poet_slug":"neyyir-aribas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vakif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksul Babanın Dramı', 'yoksul-babanin-drami-metin-yuksek-uzo7o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ötmez olmuş kuşlar bir vadide.

Bir yaşlı 55''lik oturuyor kıyısında bir nehrin.

Ayaklarını salmış suya,ot yoluyor sinirinden! 

Göz yaşlarının ezip geçtiği dudaklarıyla

Çekiyor havayı şöyle en derinden...

-Ahh hanım ah,ölecek vakit miydi sanki? 

Oğlumuz iki yaşındaydı daha.

Nasıl özledim seni,olsan da sarılsam,

Kınalı saçlarını koklasam.

Çare bulamadım hastalığına,

Hani iyiydin,birşeyin yoktu,geçecekti..? 

Yükler adamcağız sitemini yüreğine,

''Sus'' der, ''Yapma,isyan etme! ''

-Oğlumuz nasıl büyüdü bir bilsen,

Baksan yüzüne şaşırırsın,aynı sen.

O da kızıyordur bana okutamadım diye! 

Benim oğlum demirci çırağı mı olacaktı? 

''Baba,okul para istiyor,bir ben kaldım,

Parayı veremezsek atacaklar baba! ''

Çıkmıyor oğul o sözlerin aklımdan.

Borç istemediğim kapı mı kaldı oğul? 

Bulamadım o üç kuruş parayı bile,

Affet oğul affet,

Alacağım yoktu ki gidip alayım.

Cepte olan tek şey çorba parasıydı.

İstemezdim yaşıtların okula giderken,

Sen demir dövmeye git,istemezdim oğul..! 

Rüzgar da inat edip soğuk eser,

Kulağına biri fısıldar sanki ahiretten:

''Eşim,kocam,beyim...'' diye.

Firar eder yürek damarı,atar delice.

Hıçkırıklar düğümlenir boğazına,

Gök yüzü gri,suyun sesi masumken...

-Babamın pantolonunu giydim hep,

Sana da benimki nasipmiş oğul.

Cila gibi parladığını göremedim oğul,

Yok oğul para yok,olsaydı keşke de

Mübarek bayramlarda bari başın yerlerde,

Gözlerin vitrinlerde gezdirmeseydim seni.

Ahh oğul ahh..! 

Anılar yağmur damlası gibi yağar aklına,

Kapanır gözleri,dalar mazinin bağrına.

Aklına en son geçirdikleri bayram gelir...

-Unutur muyum oğul o sözlerini:

''Bir elin anamın,bir elin senin olsun,

Kutladığımız bayram anamızın olsun.

Sen üzülme babam canın sağolsun.

Ben mutluyum o nasırlı ellerinle

Okşadıkça yüzümü ben mutluyum baba.

Sen büyüttün beni,bak elim ekmek tutuyor.

Sen kendin bana okul oldun babam,

Sen bana adam olmayı,

Namusumuzla çalışmayı,

Haram lokmayı öğrettin babam.

Üzülme sakın canım babam,ben çok mutluyum,

Ve seni camından çok seviyorum...''

Ahh oğlummm,canımmm,kanımmm..! 

Yıldızlara gelir neredeyse mesayi,

Gideyim der adamcağız,çocuk dönmüştür.

Belki insan pazarında iş tutarım da yarın

Yövmiye ile bir gün daha et alırım çocuğa.

Kalkar ayağa yorgun bedeni,

Herşeye rağmen şükreder Allah''a.

Yıkıklığa,sefalete ve yoksulluğa

Dimdik ve cüretkârca gider adam...', 'Ötmez olmuş kuşlar bir vadide. Bir yaşlı 55''lik oturuyor kıyısında bir nehrin. Ayaklarını salmış suya,ot yoluyor sinirinden!  Göz yaşlarının...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/yoksul-babanin-drami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem Fırtınası', 'ozlem-firtinasi-mehmet-ali-cibikli-c7kwq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen; 

Sevebildiklerimin en fazlası

En derin aşkla

En vazgeçilmez olanı.

Sen; 

Kalbimin biricik sahibi

Benim için ölümsüz olan

Ebedi bir aşkla sevebileceğim.

Gör bak; 

Zaman içinde zaman yaşıyorum.

Geçen bu her zamanda

Hep seni yaşıyorum.

Sensizlik; 

Büyük bir dağ içimde.

Zirvesine ulaşılması güç

Keder yüklü bir dağ.

Hasretlik ise; 

İşte onu bana sorma hiç.

Ne kadar da anlatabilsem

Yine de tam olarak

Tarif edemem ben sana.

Özlem fırtınalarım tutuştu

Önüne geçilmesi imkansız.

Bende her esişinde

Sensizliğimi,özlemimi

Kat kat arttıran fırtına.

Gel; 

Son ver artık bu acılarıma

Sensizliğim bitsin istiyorum

Dindir şu fırtınaları...', 'Sen;  Sevebildiklerimin en fazlası En derin aşkla En vazgeçilmez olanı. Sen;  Kalbimin biricik sahibi Benim için ölümsüz olan Ebedi bir aşkl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ozlem-firtinasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsın Gönül Aşkınla Harab Olsun', 'varsin-gonul-askinla-harab-olsun-metin-yuksek-jstok', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Damla damla ateş düşsün göklerden gecelerime,

Siyaha çalınsın umutlarım,acılar saplansın emellerime.

Zalimse zalim; katilse katil; caniyse cani,neyse ne! 

Gelsin kursun çarmağını,söz geçiremez asi gönlüme.

Bir resmin var elimde,bir de ayrılık türkün dilimde.

Kahrolası zaman akmıyor,her saniyesi yaş gözümde.

İçimde can; içimdeki ruh; içimdeki aşk,neyse ne! 

Katlanıyor ayrılığa,beyaz gelinlikle bekliyorsun diye.

Senin olduğun yerde ben yokum,benimkinde sen.

Ayrılığın çifte acı,yüreğime seni bağladım hep ben.

Iraksa ırak; hasretse hasret; acıysa acı,neyse ne! 

Bin parçaya ayırsalar sökemezler seni içimden.

İstemez gözlerim başka göz,istemez başka dudak.

Ellerim kırılsın başka ellerde,ellerin bana son durak.

Günahsa günah; haramsa haram,nefisse nefis,neyse ne! 

Senden başka beden olsun bana kara toprak.

Olmadığın her gün denizlerimde tayfun olsun.

Seni göremediğim her rüya ölüme imzam olsun.

Izdırapsa ızdırap,sevmişim delice seni,

Varsın gönlüm aşkınla harab olsun..!', 'Damla damla ateş düşsün göklerden gecelerime, Siyaha çalınsın umutlarım,acılar saplansın emellerime. Zalimse zalim; katilse katil; caniyse c...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/varsin-gonul-askinla-harab-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Dostlarıma', 'vefasiz-dostlarima-emrah-karakoc-7y7pj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canından seversin bağlanırsın hep

Dostların''çin yanar dağlanırsın hep

O insanlar bir gün sudan bir sebep

Bulup ta terk edip giderler seni

Canımsın, özümsün, sözümsün dedin

Bu dünyada gören gözümsün dedin

Bunca sevme dedim sen dinlemedin

Vurup ta gittiler gidenler seni

Kalbini onlara hep açık tutun

Yalan sözlerini sah diye yuttun

Onlar bir kargaydı sen kartal yaptın

Bırakıp gittiler gidenler deni

Diyordun dostlarım bir tane benim

Sizi mutlu görmek benim dileğim

Bir tek emelim var sizle öleyim

Unutup gittiler gidenler seni

Yüzün gülücükler saçmıyor artık

Kalbin sevgi ile atmıyor artık

Yüreğin dost için çarpmıyor artık

Aldatıp gittiler gidenler seni

Ey Emrah kardeşim çok dedim sana

Her olur olmaza sırrını açma

Sen sen ol yinede dostluktan kaçma

Nankör yapamadı gidenler seni', 'Canından seversin bağlanırsın hep Dostların''çin yanar dağlanırsın hep O insanlar bir gün sudan bir sebep Bulup ta terk edip giderler seni Ca...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vefasiz-dostlarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Bir Gelinlik', 'siyah-bir-gelinlik-metin-yuksek-pvoo2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayal gibi geliyor şimdi birlikteliğimiz.

Bitmiş,sana göre saçmaymış sevgimiz.

Bu şekilde çıkmamıştık ya bu yola biz,

Evlenip yuva kurmaktı hani tek isteğimiz? 

Yıktın nedensiz yere kurulu hayallerimi,

Çok düşündüm artık yaşasam mı ölsem mi? 

Alınacak bir öc varken öldüremedim kendimi! 

Sana yas tutturacağım,bozmam bu yemini! 

Kendin anlayacaksın zaten yaptığın hatayı.

Harcayamayacaksın sevgiyi satıp aldığın parayı.

Günahlara girdin yaktığın için bu sevdayı.

Haketmemişsin sana yaptırdığım cennet sarayı.

Seni hâla sevdiğimden beddua etmek istemiyorum.

Aslında senin gibi vefasıza yapılmaz bu iyilik.

Seni artık beyazlar içinde görmek istemiyorum,

Senin gibi hayırsıza yakışanı,siyah bir gelinlik!', 'Hayal gibi geliyor şimdi birlikteliğimiz. Bitmiş,sana göre saçmaymış sevgimiz. Bu şekilde çıkmamıştık ya bu yola biz, Evlenip yuva kurmaktı ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siyah-bir-gelinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darbe Yemiş Yüreğim', 'darbe-yemis-yuregim-metin-yuksek-pvffc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar acı acı geçti virane bedenimin üzerinden.

Kahırlar gizlice gelerek ruhumu çaldı bedenimden.

Sımsıkı sarıldım dostlara ve arkadaşlara ama

Değişen birşey olmadı,acım hâla derinden...

Güneş doğsa da,çiçekler açsa da yaşamdan bıktım.

Pembe bulutlar üzerime yağdırdı damlalarını,kaçtım.

Kuşlar şarkı söyledi dallarda,kulaklarımı tıkadım.

Bunların da ardında dertler vardır dedim,inanmadım! 

İyiliğe,güzelliğe inanmaz oldu darbe yemiş yüreğim.

Her defasında sarsıldı insanlara olan güvenim.

Yıkık dökük gönül arsasının yeni sahibiyim,

Mutluluğa başka gözle bakıyorum,şüphecilerdenim!', 'Yıllar acı acı geçti virane bedenimin üzerinden. Kahırlar gizlice gelerek ruhumu çaldı bedenimden. Sımsıkı sarıldım dostlara ve arkadaşlara ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yüksek']::text[], 8.5, '{"poet":"Metin Yüksek","poet_slug":"metin-yuksek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/darbe-yemis-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-mehmet-ali-cibikli-sckl5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yokluğunda  öyle perişanım ki,sorma

Umutlarım yarı sönük,derbeder,

Rahat denen huzur bende yok artık,

Dertler bende,acı bende, bende keder.

Arzularım karşılıksız,dinmiyor sensizliğim

Gayret ediyorum,yokluğuna dayanmak için

Üzüntü yıktı beni,Mecnundan farksızım

Leylama hasretim,sana hasretim ben

Ümitlerim senin elinde,bende sen varsın

Mevsim  geçse,kış gelse,sen bir baharsın.', 'Yokluğunda  öyle perişanım ki,sorma Umutlarım yarı sönük,derbeder, Rahat denen huzur bende yok artık, Dertler bende,acı bende, bende keder. ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevgiliye-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlıksız', 'basliksiz-ses-sis-djhn0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'zaman içinde herkes gibi 

ölmeye müsait bir beden 

bulacaktım bende

ve ölecektim o bedende

apayrı olacaktı ruhlarımız 

bedenlerimiz bir...', 'zaman içinde herkes gibi  ölmeye müsait bir beden  bulacaktım bende ve ölecektim o bedende apayrı olacaktı ruhlarımız  bedenlerimiz bir......', ARRAY['Türk Edebiyatı','Şiir','Ses Sis']::text[], 8.5, '{"poet":"Ses Sis","poet_slug":"ses-sis","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/basliksiz-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Sanmıştım', 'adam-sanmistim-mihrican-karaca-trl4g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ulan ben seni adam sanmıştım,

Meğer ne vicdansız,ne gaddarmışsın.

Bende hala ümit besleyip seni dilendim,

Adam sanmıştım seni,ben yanılmışım.

Ben senin için kör kuyulara atladım,

Eğilip bir kere bile ardımdan bakmadın..

Gelip üstümü lehimle kapladın,

Adam sanmıştım seni,ben yanılmışım.

Uykusuz gecelerde sensiz sabahladım,

Boşuna öfkemden camları yumrukladım.

Bundan böyle kendimi sana yasakladım,

Adam sanmıştım seni,ben yanılmışım.', 'Ulan ben seni adam sanmıştım, Meğer ne vicdansız,ne gaddarmışsın. Bende hala ümit besleyip seni dilendim, Adam sanmıştım seni,ben yanılmışım...', ARRAY['Türk Edebiyatı','Şiir','Mihrican Karaca']::text[], 8.5, '{"poet":"Mihrican Karaca","poet_slug":"mihrican-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adam-sanmistim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgün Üzgün', 'uzgun-uzgun-emrah-karakoc-acxfi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhabalar merhabalar ey gönül

Neredeydin bunca hafta bunca gün

Gönüle kavuştun yürek artık gül

Bundan sonra dolaşma üzgün üzgün

Yine kuzu otlat kırda bayırda

Çocuk ol takla at çimen - çayırda

Eller kadar biraz beni kayırda

Bundan sonra dolaşma üzgün üzgün

Kelebekler kadar özgürsün artık

Ölü yılan kadar düzgünsün artık

Mutsuzluktan yana bezginsin artık

Bundan sonra dolaşma üzgün üzgün

Kıymetini kadrini bilen mi var? 

Sana sorsam şu koskoca dünya dar

Yapma be yüreğim yapma bu kadar

Bundan sonra dolaşma üzgün üzgün

Her kötüde vardır mutlak bir iyi

Bundan sonra dost edin güzelliği

Garip EMRAH''ın senden tek dileği

Bundan sonra dolaşma üzgün üzgün', 'Merhabalar merhabalar ey gönül Neredeydin bunca hafta bunca gün Gönüle kavuştun yürek artık gül Bundan sonra dolaşma üzgün üzgün Yine kuzu o...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzgun-uzgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Efendim', 'canim-efendim-omer-ziya-soyyigit-2mr60', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni bulayım

Canım efendim

Kölen olayım

Canım efendim

Eşin bulunmaz

Sırrın bilinmez

Sana erilmez

Canım efendim

Hasretle yandım

Derde boyandım

Sana dayandım

Canım efendim

Hikmetle baktın

Kalbimi yaktın

Gönlüme aktın

Canım efendim

Bey''atı haktan

Aldım mutlaktan

Uçtum tuzaktan

Canım efendim

''Canım kardeşim

Ömerim'' dedin

Kalmadı derdim

Canım efendim.

19 Nisan 1982', 'Seni bulayım Canım efendim Kölen olayım Canım efendim Eşin bulunmaz Sırrın bilinmez Sana erilmez Canım efendim Hasretle yandım Derde boyandı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/canim-efendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokum', 'yokum-ses-sis-bshra', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerim

  kulaklarım

          ellerim

sanki bi boşluktan ibaretim

bütün şarkılar onun için yazılmış

bütün resimler onun için yapılmış

dokunuyorum

hissedemiyorum

sanki ellerim 

onun için yaratılmış.

kendime bakıyorum

ben yokum

ONU görüyorum...', 'gözlerim   kulaklarım           ellerim sanki bi boşluktan ibaretim bütün şarkılar onun için yazılmış bütün resimler onun için yapılmış doku...', ARRAY['Türk Edebiyatı','Şiir','Ses Sis']::text[], 8.5, '{"poet":"Ses Sis","poet_slug":"ses-sis","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yokum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haliç sırtlarında bir mezar', 'halic-sirtlarinda-bir-mezar-sair-yaman-1pd7d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'haliç sırtlarında bir mezar 

üzerinde taze toprak kokusu 

mezar taşında belli belirsiz bir yazı 

mazinin el yazısına benziyor uzaktan 

yakınlaştıkça koyulaşıyor harfleri 

gecenin gözleri gibi, ölümün kokusu gibi 

bana sesleniyor ta oradan 

ben diyor ben... 

adım NECİP FAZIL 

soyadım KISAKÜREK 

senin diyor bu haline 

ne vicdan dayanır ne yürek, 

ben diyor ben... 

ölümü dost bildim Mevla''yı yar 

seninse diyor, gerdanlık gibi 

boynuna ihaneti astığın bir sevgilin var, 

ben diyor ben... 

davam uğruna yol eyledim 

mahpushaneleri gide gele 

ya sen diyor ya sen 

beni bir ahmak addedip, yaptıklarıma 

gülüp geçerdin belki de, 

ben diyor ben... 

Leyla''mı bir ömre sığdıramadım 

sense iki çift kelama mahkum ettin, 

ben diyor ben... 

kara toprağın altında titriyorum 

sen alazların gölgesinde eğlenirken 

sen,çocuk bir kemik yığınının yüreğini sızlatıyorsun 

dilinin altından seni seviyorum derken, 

kara toprak almıyor çocuk beni 

ters düz oluyorum. 

burası diyor burası... 

sevdası uğruna gökten yağan kurşuna 

dur diyenlerin vatanı 

nolur çocuk nolur 

boncuk tabancasından atılan boncuğa ezdirme sevdamı, 

alık alık bakma öyle mezar taşıma 

bir zamanlar benimdi 

şimdi senin bu dava, 

biliyor musun diyor biliyor musun..? 

Haliç''in sırtında bir mezarım diye 

inadına toprağımı kirletiyorlar, inadına 

İstanbul''u izlerler buradan, yüreğimi eze eze, 

ne anlar İstanbul''dan bomboş gözler? 

İstanbul canlar üstündedir, 

canlıdır İstanbul çocuk, 

ona fer eder mi efsununu kaybetmiş sözler. 

korkma sakın! bir mezar konuşur mu diye 

yüreği bile sızlar, 

hadi çocuk durma buralarda daha fazla 

geç git evine, geç git annene, 

boş durmaz artık gaflet dağında uluşan kurtlar... 

.HÂRÊMÎ.____________', 'haliç sırtlarında bir mezar  üzerinde taze toprak kokusu  mezar taşında belli belirsiz bir yazı  mazinin el yazısına benziyor uzaktan  yakın...', ARRAY['Türk Edebiyatı','Şiir','Şair Yaman']::text[], 8.5, '{"poet":"Şair Yaman","poet_slug":"sair-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/halic-sirtlarinda-bir-mezar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-mehmet-ali-cibikli-nk7u2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnan ki,seni ilk kez gördüğüm o gün,

Kalbime birşey olmuştu,çarpılmıştım.

Belki de bir rüya idi bu gördüğüm,

Mutluluğu doyasıya yaşamıştım.

Bir bebek gibiydim,tutmuştun elimi,

Kırda kelebekleri kovalıyorduk.

Okyanusun ufkundaki gemi gibi,

Mutluluk denizinde yol alıyorduk.

Birdenbire büyük bir fırtına çıktı,

Devirdi acımasızca gemimizi.

Mutluluğu üstümüze yıktı,

Bulamadık sevgide birbirimizi.

İşte büyük fırtınanın etkisiyle,

Şaşırmıştım ben neye uğradığımı.

Bocaladım çaresizlikler içinde,

Bulamadım bir türlü aradığımı.

Ağlıyorum gör bak şimdi ara sıra,

Ya ben o denli seni sevmemeliydim.

Göz pınarlarım akıyor kana kana,

Ya da o rüyayı hiç görmemeliydim.', 'İnan ki,seni ilk kez gördüğüm o gün, Kalbime birşey olmuştu,çarpılmıştım. Belki de bir rüya idi bu gördüğüm, Mutluluğu doyasıya yaşamıştım. ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/firtina-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban Olayım', 'kurban-olayim-omer-ziya-soyyigit-6cpot', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zatınla tecelli eyle

Zatına kurban olayım

Bizleri teselli eyle

Lutfuna kurban olayım

''Lateknetu'' sen buyurdun

Bunu bizlere duyurdun

Aç kullarını doyurdun

Şanına kurban olayım

Rahman ve Rahim olan sen

Müznib ve sekım olan ben

Korkarmıyım sen var iken

Affına kurban olayım

Varis ettin kitabına

Mazhar kıldın hitabına

Yücelt bizi dost katına

Dostuna kurban olayım

Ömer kuldur, sana kuldur

Gerek ağlat gerek güldür

Dilersen mahvedip öldür

Emrine kurban olayım

15 Nisan 1982', 'Zatınla tecelli eyle Zatına kurban olayım Bizleri teselli eyle Lutfuna kurban olayım ''Lateknetu'' sen buyurdun Bunu bizlere duyurdun Aç kulla...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kurban-olayim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muşlu şimdiki zaman ağıtı...!', 'muslu-simdiki-zaman-agiti-musfik-saltik-10vkt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beterin beteri olur mu derdim, oluyormuş

Acının daha acısı olur mu derdim, oluyormuş

Ölümden ötesi olur mu  derdim , oluyormuş

Kurşunsuz, bıçaksız adam vuruluyormuş

Bir tek söz bin silahtan daha kötü yaralıyormuş

Yanı başındayken yok sayılmak  insanı bitiriyormuş

Meğer insan  insanı ne kolay harcayabiliyormuş

Canının parçası seni sıpıtıp atınca paçavra gibi

Her şey bir anda nasıl da değerini yitiriyormuş

Yüreğine akınca göz yaşların nasılda yakıyormuş

İnsan insanı  nasılda kolay defterden siliyormuş

Bu hale gelince insan yaşamak ne zor geliyormuş

                                                  Şubat 2006', 'Beterin beteri olur mu derdim, oluyormuş Acının daha acısı olur mu derdim, oluyormuş Ölümden ötesi olur mu  derdim , oluyormuş Kurşunsuz, bı...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/muslu-simdiki-zaman-agiti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-emrah-karakoc-b6dn1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutluluk saçardı gönlümün sesi

Susturdun ey zalim gelmez nefesi

Sokakta gördüğüm bütün herkesi

Düşmanım bildirdin bana vefasız

Sevgiye inanıp gülüşe kandım

her yüze güleni Can dostum sandım

Hayret yanılmışım sana aldandım

Derbeder eyledin beni vefasız

Şu anda gözümden süzülen yaşı

Silen olmalıydın sildi başkası

Sanmıştım ben seni insanın hası

Eşekten farksızsın inan vefasız

Gülleri soldurdun umudu kırdın

Gönlümü küstürdün kalbi darılttın

Sahte gülüşlerle beni aldattın

Ömrümü çürüttün benim vefasız

Sana yazmayacak artık kalemim

Güzel söz söylemez artık şu dilim

En büyük düşmanım oldun sevgilim

Emelim ölürken gitmen imansız', 'Mutluluk saçardı gönlümün sesi Susturdun ey zalim gelmez nefesi Sokakta gördüğüm bütün herkesi Düşmanım bildirdin bana vefasız Sevgiye inanı...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beddua-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hz. Ebû Ubeyde bin Cerrah (RA)', 'hz-eb-ubeyde-bin-cerrah-ra-abdullah-yasar-erdogan-8y33a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Aşere-i Mübeşşere’nin onuncusu)

 Hz. Ebû Ubeyde bin Cerrah (RA)

Adı; Amir bin Abdullah bin El-Cerrah’tır,

O, Eminü’l-Ûmme lâkabıyla tanınır,

Hakk’a iman eden ilk Müslümanlardandır,

İlk Müslümanlardan olan Ebû Ûbeyde’m.

Kureyş’te Fihr Oğullarından soyu gelir,

Nesebi Fihr’de Hz. Muhammed’le birleşir,

Ubeyde, Aşere-i Mübeşşere’dendir,

Eminü’l- Ûmme lakaplı Ebû Ûbeyde’m.

Osman bin Maz’un’la Bekir’e gitmişti,

Hz. Ebû Bekir davetiyle iman etti,

O, Mekke müşriklerinden çok çile çekti,

Aşere-i Mübeşşere’dendir Cerrah’ım.

İslâm’ı kabul eden onuncu ashaptır,

Mü’min olduğunda otuz bir yaşındadır,

O, okuma yazma bilen  Araplardandır,

İlk Müslümanlardan olan Ebû Ûbeyde’m.

Mü’minler Habeşistan’a hicret eder,

İkinci hicrette Hz. Ûbeyde’de gider,

Böylece kurtulmuştur o zulüm çekenler,

Kahramanlığı ile tanınan Ûbeyde’m.

Bir sene sonra Medine’ye hicret vardır,

Medine’de kardeşlik tesis olmaktadır,

Sa’d bin Muaz ile kardeş sayılmaktadır,

Resûl övgüsüne mazhardır Hz. Ûbeyde’m.

Bedir de kâfir olan çok akraba varmış,

Bedir O’nun için destan yeri denilmiş,

Müşrik olan babasını bizzat öldürmüş,

Eminü’l- Ûmme lakaplı Ebû Ûbeyde’m.

Bedir günü; Hz. Ebû Bekir oğlu ile,

O güzel Mus’ab bin Umeyr kardeşi ile,

Ömer ise, dayısı ile dövüşmekte,

Kâfir babasını öldürendir Ûbeyde’m.

Ûbeyde karşısında babası vardır,

Babasına Hakk adına kılıç kaldırır,

Allah; Kura’an’da bu olayı aydınlatır,

Züht ve takva sahibi Hz. Ebû Ûbeyde’m.

Resûl der: “Her ümmetin bir emini vardır,

Bu ümmetin ki Ebû Ûbeyde Cerrah’tır,”

Bundan “Eminü’l-Ûmme” diye tanınmıştır,

Resûl övgüsüne mazhardır Hz. Ûbeyde’m.

Uhud’ta bir kahramandır Ebû Ûbeyde,

Müşrik İbni Kamia saldırır Resûle,

Miğferin demiri batar Resûl yüzüne,

Dişiyle Resûlü kurtaran Ûbeyde’m.

Ûbeyde gelip bertaraf eder düşmanı,

Dişiyle alır Resûl yüzüne batanı,

İki dişi kırılmış ama, yanmaz canı,

Rasûlullah’a hizmetkârdır Hz. Ûbeyde’m.

Bir grup sahabe Beliy ve Üzre’ye gider,

Resûl; “Onları İslâm’a davet edin” der,

Amr bin El-Âs, Hz. Muhammed’ten yardım ister,

Resûl övgüsüne mazhardır Hz. Ûbeyde’m.

Hz. Ûbeyde komutasında yardım olur,

Ebû Bekir ve Ömer birlikte bulunur,

“Aranızda ihtilaf çıkmasın” tembih olur,

Züht ve takva sahibi Hz. Ebû Ûbeyde’m.

Yardım varınca komuta da ihtilaf var,

Hz. Ûbeyde Resûlullah sözünü hatırlar,

“Sen ne dersen o olacak” deyip onaylar,

Ümmetin Emini sayılan Hz. Ûbeyde’m.

Hz. Ûbeyde, komutada, Amr’dan üstündür,

Amr bin El-Âs’a tabi olmak büyüklüktür,

Böylece ashap arasında dostluk yürür, 

Mukallın ashap denilen Ebû Ûbeyde’m.

Hicri dokuzda Necranlılar cizye verir,

Şart “cizye almaya gelmeli güvenilir,”

Emin adam diye Ûbeyde görevlenir,

Eminü’l- Ûmme lakaplı Ebû Ûbeyde’m.

Ûbeyde, en güzel yüzlülerin üçüncüsü,

Hz. Ebû Bekir bir, Hz. Osman ikincisi,

Resûl vefatında gözden akar incisi,

Rasûlullah’a hizmetkârdır Hz. Ûbeyde’m.

Ûbeyde her savaşta Resûl yanındadır,

O ölünce Ebû Bekir’e bey’attadır,

Ebû Bekir devrinde her harbe katılır,

İslâm ordusu komutanıdır Ûbeyde’m.

Sıddık O’nu halifeliğe aday etmiş,

“Hz. Ömer dururken ben aday olmam” demiş,

Ûbeyde, Hz. Ömer’e bizzat bey’at etmiş,

Züht ve takva sahibi Hz. Ebû Ûbeyde’m.

Hz. Ömer devrinde harplere katılır,

Suriye Fethi’nde ordu komutanıdır,

O dönemdeki savaşlarda hep o vardır,

Savaştan çok sulh yapandır Ebû Ûbeyde’m.

Hicri on üç de olur Ecnâdayn Savaşı,

Zafer kazanır Roma Ordusu’na karşı,

Suriye’nin fethinde üç bin şehit vardı,

Roma Ordusu’nu yenendir Hz. Ûbeyde’m.

Emrindekilere iyiliği emreder O,

Allah’ın emri dışına hiç çıkmazdı O,

Resûle canını fedaya hazırdı O,

Resûl övgüsüne mazhardır Hz. Ûbeyde’m.

Erdem ve fazilet timsali sayılmıştır,

Yufka yürekli, merhametli anılmıştır,

Dünya nimetlerini gaile almamıştır,

İlk Müslümanlardan olan Ebû Ûbeyde’m.

Şam’a Halid bin Velid çarpışarak girmiş,

Ebû Ûbeyde ise sulh yaparak girmiş,

Bizans ordusu Suriye’den temizlenmiş,

Savaştan çok sulh yapandır Ebû Ûbeyde’m.

Hicri on dörtte Fahl savaşı vuku buldu,

Harpten önce elçi gönderir iki ordu,

Romalı elçi Cerrah’ı kral biliyordu,

Aşere-i Mübeşşere’dendir Cerrah’ım.

Elçi, herkesi birbirine benzer görmüş,

Ûbeyde’nin sadeliğine çok şaşırmış,

“Burayı terk edin, size altın var” demiş,

Eminü’l- Ûmme lakaplı Ebû Ûbeyde’m.

Elçinin teklifini reddeder Ûbeyde,

Çarpışıp Romalıları getirmiş dize,

Humus şehri de fethedilmişti böylece,

Kahramanlığı ile tanınan Ûbeyde’m.

Ömer emriyle ordu Humus’a yerleşti,

Hicri on beşte Roma tekrar ordu gönderdi,

Ûbeyde, orduya çekilme emri verdi,

İslâm ordusu komutanıdır Ûbeyde’m.

Ebû Ûbeyde bin Cerrah, bekler Yermûk’ta,

Yardım gelir Amr bin El-Âs komutasında,

Moral doruğa çıkar İslâm Ordusu’nda,

Resûl övgüsüne mazhardır Hz. Ûbeyde’m.

Ebû Ûbeyde Yermûk’ta bir kahramandır,

İki yüz kır bine karşı, kırk bin er vardır,

Ebû Ûbeyde merkezdeki komutandır,

Züht ve takva sahibi Hz. Ebû Ûbeyde’m.

Bizans generali Yorgi, Müslüman olur,

O Bizans’ın ordusu perişan olmuştur,

Yermûk’ta İslâm’ın güneşi pir doğmuştur,

Roma Ordusu’nu yenendir Hz. Ûbeyde’m.

Heraklios “Elveda Suriye” demiş,

Halep ve Antakya İslâm emrine girmiş,

Ebû Ûbeyde tekrar Humus’a yerleşmiş,

Mukıllın ashap denilen Ebû Ûbeyde’m.

Hicri on altı da Kudüs kuşatılmıştı,

Halk karşı koymadan Kudüs’ü teslim etti,

Hz. Ömer Cabiye’de onlarla anlaştı,

Ümmetin Emini sayılan Hz. Ûbeyde’m.

Hicri on yedi yılında baş komutandır,

Halid bin Velid komutadan alınmıştır,

Ûbeyde kendini harplere adamıştır,

Kâfir babasını öldürendir Ûbeyde’m.

Rumlar tekrar saldırdı Ebû Ûbeyde’ye,

Düşman pişman oldu Humus’a geldiğine,

Güzel sahabe taht kurdu düşman gönlüne,

Eminü’l- Ûmme lakaplı Ebû Ûbeyde’m.

Hicri on sekizde Hicaz’da hastalık var,

Hz. Ûbeyde hemen oraya yardım yollar,

Veba salgını yayılmış Humus’a kadar,

Züht ve takva sahibi Hz. Ebû Ûbeyde’m.

Hz. Ömer, Ûbeyde’ye ayrıl demiş Şam’dan,

Hz. Ûbeyde’ye de bulaşır hastalıktan,

O güzel Şam’da kurtulamadı vebadan,

Ömer övgüsüne mazhardır Hz. Ûbeyde’m.

Ûbeyde’nin kabri Suriye, Şam ilinde,

Anta Köyü’nün, Gavr Beysan denilen yerde,

Büyük insan olarak yer alır tarihte,

Savaştan çok sulh yapandır Ebû Ûbeyde’m.

Cesur, savaşçı, züht ve takva sahibidir,

Ümmet Emini, adaletle hükmedendir,

İtaatkâr, kanaatkâr bir sahabedir,

Züht ve takva sahibi Hz. Ebû Ûbeyde’m.

O, Fütuhatta ganimetten pay almazmış,

O, maldan ve mülkten uzak hayat yaşarmış,

Allah’ın kazasından kaderine kaçmış,

Aşere-i Mübeşşere’dendir Cerrah’ım.

Dünya herkesi etkiler, O’nu etkilemez,

Kendisine iltica edeni hiç reddetmez,

O, Sünneti uygularmış, anlatmak istemez,

Mukıllın ashap denilen Ebû Ûbeyde’m.

Orta boylu, zayıf, güzel yüzlü ve zeki,

Resûlden az hadis rivayet eden biri,

O’nun için Mukıllın Ashap denilirdi,

Resûl övgüsüne mazhardır Hz. Ûbeyde’m.

İlk Müslümanlardan olan Ebû Ûbeyde’m.

Aşere-i Mübeşşere’dendir Cerrah’ım.

Eminü’l- Ûmme lakaplı Ebû Ûbeyde’m.

Kahramanlığı ile tanınan Ûbeyde’m.

Resûl övgüsüne mazhardır Hz. Ûbeyde’m.

Kâfir babasını öldürendir Ûbeyde’m.

Dişiyle Resûlü kurtaran Ûbeyde’m.

Rasûlullah’a hizmetkârdır Hz. Ûbeyde’m.

İslâm ordusu komutanıdır Ûbeyde’m.

Roma Ordusu’nu yenendir Hz. Ûbeyde’m.

Savaştan çok sulh yapandır Ebû Ûbeyde’m.

Züht ve takva sahibi Hz. Ebû Ûbeyde’m.

Mukıllın ashap denilen Ebû Ûbeyde’m.

Ümmetin Emini sayılan Hz. Ûbeyde’m.

Ömer övgüsüne mazhardır Hz. Ûbeyde’m.

Allah’ım! Otuz iki dişim feda olsun,

Bin canımız güzel yoluna heba olsun,

Yeter ki güzel ümmet doğru yolu bulsun,

Ey Rehber Hz. Muhammed, sen ne güzel kulsun.

Şair: Abdullah Yaşar Erdoğan.', '(Aşere-i Mübeşşere’nin onuncusu)  Hz. Ebû Ubeyde bin Cerrah (RA) Adı; Amir bin Abdullah bin El-Cerrah’tır, O, Eminü’l-Ûmme lâkabıyla tanınır...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":194,"source_url":"https://www.antoloji.com/hz-ebu-ubeyde-bin-cerrah-ra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kur''an ile Hemdem Olmak', 'kur-an-ile-hemdem-olmak-omer-ziya-soyyigit-enkis', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne devlettir bilenler

Kur''an ile hemdem olmak

Hak yoluna gidenlere

Kur''an ile hemdem olmak

Saadettir hafızlara

Kemalattır aşıklara

Hidayettir sadıklara

Kur''an ile hemdem olmak

Nefse vurulan bir bağdır

İblise karşı bir dağdır

Çelikten örülmüş ağdır

Kur''an ile hemdem olmak

Ziya bil onun  kadrini

Islah eder her derdini

Nur eder elbet kabrini

Kur''an ile hemdem olmak

14 Nisan 1982', 'Ne devlettir bilenler Kur''an ile hemdem olmak Hak yoluna gidenlere Kur''an ile hemdem olmak Saadettir hafızlara Kemalattır aşıklara Hidayetti...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kur-an-ile-hemdem-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımın Değil! Kalbimin İsteğisin…(Güzel Gözlüme 2)', 'aklimin-degil-kalbimin-i-stegisin-guzel-gozlume-2-ali-orhan-gunaydin-qhscr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar önce demiştim sana…

Sen…

Aklımın değil! kalbimin isteğisin…

Zaman geçince değiştim mi? sanıyorsun…

Tekrar duy,güzel gözlüm…

Şimdi daha önemlisin…

Bir tanemsin…

Eşimsin…

Sen de iyi bilirsin…

Sevince ben…

Yıllar geçtikçe…

Deli gibi,ölesiye….

Ölesiye severim….

26/01/2006 06:45', 'Yıllar önce demiştim sana… Sen… Aklımın değil! kalbimin isteğisin… Zaman geçince değiştim mi? sanıyorsun… Tekrar duy,güzel gözlüm… Şimdi dah...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aklimin-degil-kalbimin-istegisin-guzel-gozlume-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanın Bitişi', 'i-nsanin-bitisi-emrah-karakoc-v442w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara günün bitmeyeni 

Bitirir insan oğlunu

Dostun kıymet bilmeyeni

Bitirir insanoğlunu

Beklenenin gelmeyeni

Huzursuzluğun nedeni

Yorgun düşürür bedeni

Bitirir insanoğlunu

Hor görülür zalimlerce

Aldatılır hainlerce

Uykusuzsa gecelerce

Bitirir insanoğlunu

Kader örmüşse ağını

Çıkmıçsa derdin dağını

Koparmışsa dost bağını

Bitirir insanoğlunu

Karakoç daha ne yazsın

Azsın yaraları azsın

Anlarır anlaşılmazsın

Bitirir insanoğlunu', 'Kara günün bitmeyeni  Bitirir insan oğlunu Dostun kıymet bilmeyeni Bitirir insanoğlunu Beklenenin gelmeyeni Huzursuzluğun nedeni Yorgun düşü...', ARRAY['Türk Edebiyatı','Şiir','Emrah Karakoç']::text[], 8.5, '{"poet":"Emrah Karakoç","poet_slug":"emrah-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/insanin-bitisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıklar Kenti', 'yalnizliklar-kenti-mehmet-ali-cibikli-yx32u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine geldim değil mi sana

Yine geldim bu limana

Artık son gelişim olacak bu

Uğramayacağım limanına.

Başka gemiler gelecek artık

Sevda hasret yüklü başka gemiler.

Rıhtım sevdalılarla dolup taşacak

Mutluluklar olacak denizinde.

Bu sevdalılar,

Elemle ayrılacaklar birbirlerinden,

Hasretle kavuşacaklar birbirlerine.

Artık gelmeyecek benim gemim

Uğramayacak kentine.

Sen kendi kentinde olacaksın bundan böyle,

Ben ise,Yalnızlıklar Kentinde.', 'Yine geldim değil mi sana Yine geldim bu limana Artık son gelişim olacak bu Uğramayacağım limanına. Başka gemiler gelecek artık Sevda hasret...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizliklar-kenti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey insanoğlu! ! !', 'ey-insanoglu-halide-selcan-karagul-5si8e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey insanoğlu! ! ! 

Kendine gel kendine! ..

Farkında mısın? 

Karanlığın kâbusu çökmüş üzerine...

Gözlerinde kin, nefret... ateş saçıyor ha bire...

Dillerin çatal çatal... kusuyor alev dolu öfke...

Bilir misin? ! 

İblisin istediğide bu işte! 

Behey insanoğlu! ! ! 

Bir durda düşün? 

Hakikati bilmezsen kötü olur düşüşün.

Elini yüreğinin üstüne koyda öyle düşün.

İşin aslı nedir? Ne değildir? 

Hareket etme düşünmeden hele bir...

24.08.2005', 'Ey insanoğlu! ! !  Kendine gel kendine! .. Farkında mısın?  Karanlığın kâbusu çökmüş üzerine... Gözlerinde kin, nefret... ateş saçıyor ha bi...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ey-insanoglu-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedin', 'gelmedin-mehmet-ali-cibikli-tzg02', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün,

Karanlık gecemin ilk akşamında

Seni bekledim,seni aradım.

Gözledi gözlerim yollarını

Dinledi kulaklarım yolda ayak sesini

İşitmek istedim kapımın tıkırtısını

Ama sen yoktun ortalıklarda.

Hamam böcekleri dahi susmuştu

Seni gelecek diye.

Ne kurbağaların orkestrası

Ne de karafatmaların dansı

Hepsi durmuştu artık.

Çünkü seni karşılayabilmek için

Yorgun olmayacaklardı.

Derken; 

Bir gölge belirdi kapıdan

Sensin dedim,sen sandım

Koştum hemen kapıya

Ve aldandım.

Bütün varlığım sendin

Sendin benim herşeyim.

Bilemedin sana hasret oluşumu

Anlayamadın beni,

Gelmedin...', 'Dün, Karanlık gecemin ilk akşamında Seni bekledim,seni aradım. Gözledi gözlerim yollarını Dinledi kulaklarım yolda ayak sesini İşitmek isted...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gelmedin-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelerin Adamıyım...', 'gecelerin-adamiyim-ali-orhan-gunaydin-vdtib', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben, gecelerin adamıyım...

sahteliklerden kaçar,

gerçekleri yaşarım...

İşte bu yüzden 

ben geceleri yaşarım...

Karanlık bastırıp,gece çıkınca ortaya,

sahte olan ne varsa inine saklanır...

İşte o zaman sahte olan dünyada,

yaşam gerçeğe boyanır...

Sadece gerçekleri konuşur,

gerçekleri yaşarım...

Bu yüzden işte ben,

gecelerin tam kalbinde yaşarım...', 'Ben, gecelerin adamıyım... sahteliklerden kaçar, gerçekleri yaşarım... İşte bu yüzden  ben geceleri yaşarım... Karanlık bastırıp,gece çıkınc...', ARRAY['Türk Edebiyatı','Şiir','Ali Orhan Günaydın']::text[], 8.5, '{"poet":"Ali Orhan Günaydın","poet_slug":"ali-orhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gecelerin-adamiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm gözüm aydınlık', 'gonlum-gozum-aydinlik-mikdat-bal-ycc76', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönlüm gözüm aydınlık, bu günüme ne mutlu

Kalmadı başka derdim, gerisi geçer artık

Allah nasip ederse, umutluyum umutlu

Bahara yaklaşırken, çiçekler açar artık

Cemre toprağa düştü, yolunu seçer artık

Her gün bir ganimettir, kadrini bilmek gerek

Gergin yaşamak azap, arada gülmek gerek

Dost dostu aramalı gidip de gelmek gerek

Seven sevenden ilgi kesmekten kaçar artık

Muhabbetler pekişir, küskünlük geçer artık

Mutluluk içimizde gönül geniş olmalı

Orada herşey mevcut, gerekeni almalı

Her ne olursa olsun soğuk kanlı kalmalı

Sevgi bekleyen insan, sevgiyi saçar artık

Sevgi abıhayattır, dileyen içer artık', 'Gönlüm gözüm aydınlık, bu günüme ne mutlu Kalmadı başka derdim, gerisi geçer artık Allah nasip ederse, umutluyum umutlu Bahara yaklaşırken, ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gonlum-gozum-aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vicdânın Isyânı', 'vicd-nin-isy-ni-mevlut-bicik-zonhk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hurûç etti Dünya arena‘sına bir iki züppe

Kalemiyle Âlem-i Íslâma nâralar savurdu.

Mîzâclariyle münâsip bıraktılar bir habbe

Zâten bunların asılları da cidden gavurdu.

Peygamberine hakâret edilen Müslüman

Yay’dan çıkan bir ok gibi sür’atle fırladı.

Her tarafa yayıldı ateş,alev alev oldu âsuman

Söndürmek için öfke ateşini birileri fırladı.

Lâkin bu yapılan yanlış; bir nabız yoklamasıydı

Beklemedikleri cevâbı çok kısa zamanda aldılar.

Zannettiler ki Âlemi Íslâm uykudadır! eğer tepki olmasaydı

Hiç beklemeden bir yerlere hücûm kararı aldılar.

Ama şunu bilsinler ki Âlem-i Íslâm sabırlıdır

Son radde’ye kadar bekler, gözetler, durur.

Zamânı geldiğinde ise hücûma geçer,tavırlıdır

Peygamberine dil uzatanı nerede bulursa vurur.

Ey Peygamber düşmanları bırakın,dokunmayın bize

Bizler sizin Peygamberinize bir şey dedikmi? 

Durup dururken niye kaşınıyorsunuz,ne oluyor size

Aşınızı, ekmeğinizi önünüzden çalıp’da yedikmi? 

Mevlüt Bicik

13.02.2006  saat  22.08

Esslingen', 'Hurûç etti Dünya arena‘sına bir iki züppe Kalemiyle Âlem-i Íslâma nâralar savurdu. Mîzâclariyle münâsip bıraktılar bir habbe Zâten bunların ...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/vicdanin-isyani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Sensiz', 'yine-sensiz-levent-kapisiz-k8j3t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece ışığa muhtaç oluşundandır öfkeli

Ay hırsızlığında ışık çalmak

Görememek ve sana dokunamamak

Ulaşılmazlığın yıldızlar kadar yakın

Hangi teleskopla baksam sana ulaşmak

Bakışlarının ortasında hilale döner

Kaşların ışıltısında ay karanlığının

Zifte özdeş ışıltısında düşsel karanlık

Yirmibeşinci saatlerin uykusuzluğunda

Süliyetin belirir gece pusunda

Rüyalarda bile kaçamak bakışlar

Gece güneş susuzluğunda buluşmak

Özenilesi ve yaşanası tutkuları taşıyıp

Yılların ötesine aşmak sevda arsızlığında

Utanıp başını eğmek kadar insansı

Düşler sokağına dalmak gece yarısı

Neyana baksam karanlıkta sensin diye

Buharlaşan gölgede kaybolur

Hiçbiri sen değilsin başkası

Ağlasam duyulur

Kimsecikler yok aslında tam sırası

Önüme bakmıyorum

Kırmızı ışıklarda geçiyorum

Bu aşkta ihlali var tüm yazılmış kuralların

Takılan duvakların sana yakışması

Meşguliyetindeyim geziyorum

Şehrin tüm evlilik mağazalarını

Ben senin yerine de seviyorum

Sensiz dünyamda ikimizden

Hayaller kuruyorum sen bilmeden

Ben seviyorum sen susuyorsun

Sonsuzluğunda gece uykusu

Rüyalara dalıyorsun

Her yıl oduğu gibi sevgililer gününde

Beni yine sensiz bırakıyorsun', 'Gece ışığa muhtaç oluşundandır öfkeli Ay hırsızlığında ışık çalmak Görememek ve sana dokunamamak Ulaşılmazlığın yıldızlar kadar yakın Hangi ...', ARRAY['Türk Edebiyatı','Şiir','Levent Kapısız']::text[], 8.5, '{"poet":"Levent Kapısız","poet_slug":"levent-kapisiz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yine-sensiz-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menekşe Kurağı', 'menekse-kuragi-durmus-kaya-45wt7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretin kan olup akar karına

Dağlar geçit vermez yol ince gelir! 

Eremem sılanın baharlarına,

Mektup ince gelir, el ince gelir! 

Beni dizine al koynunda uyut

Ve..  kalksın aradan mesafe, boyut! 

Yalnız sen elimi mahşere dek tut,

Esen bu rüzgara dal ince gelir! 

Gül yüzünde güller hârelenince

Hicrân gecesinin çiçeklerince

Ayrılığa acı gurbet denince

Ömür ince gelir,  yıl ince gelir! 

İzinsiz girilmez yarin bağına

Benliğim takılı kaldı ağına

Mevlam bir renk vermiş ki dudağına

Kırmızı kıskanır al ince gelir! 

Seni sevmek benim ilk ve tek suçum? 

Ben senin gülşeni sevdana açım,

Menekşe kurağı yaşarken içim

Yağmur ince gelir, sel ince gelir!', 'Hasretin kan olup akar karına Dağlar geçit vermez yol ince gelir!  Eremem sılanın baharlarına, Mektup ince gelir, el ince gelir!  Beni dizin...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Kaya']::text[], 8.5, '{"poet":"Durmuş Kaya","poet_slug":"durmus-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/menekse-kuragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer Günü', 'sevgililer-gunu-muzaffer-baskaya-1ut2s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gün sevgililer günü...

Bir gül uzattım yıldızlara,sana versinler.

Bir kahkaha fırlat sonsuzluğa,

seninle olduğumu bilsinler.', 'Bu gün sevgililer günü... Bir gül uzattım yıldızlara,sana versinler. Bir kahkaha fırlat sonsuzluğa, seninle olduğumu bilsinler....', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Başkaya']::text[], 8.5, '{"poet":"Muzaffer Başkaya","poet_slug":"muzaffer-baskaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgililer-gunu-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Künyem', 'kunyem-hidir-cam-228py', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Künyemi sorsanız gayet ezelden

Kerbela çölünde giz oldum geldim

Dönmedim yolumda, vazgeçtim serden

Nesimi’den bu güne iz oldum geldim

Bir zaman Yunus’tum Hak’kı aradım

Dağ, tepe demedim, umman taradım

Ben gökte ararken yerde rastladım

Adem-i çehreye yüz oldum geldim

Bir yanım Karun’du, bir yanım darda

Bir yanım korlarda, bir yanım karda

Bir ömür tükettim kör kuyularda

Yusuf’a zındanda göz oldum geldim

Öfkemle sarsıldı, surlar yerinden

Hiç bir güç sökemez,  köküm derinden

Pir’imi kurtarıp Hınzır şerinden

İdam sehpasında saz oldum geldim

Suyundan beslenip binlerce elin

Kul, kölesi oldum, sevdalı dilin

Dökülüp diline Koca Veysel’in

Kara toprağına toz oldum geldim

Bin yıldır köpürdüm Kızılırmak’ta

Sol yanım aç susuz, hala kurakta

Yüreğim  tutuştu kor Madımak’ta

Türkülerle piştim köz oldum geldim', 'Künyemi sorsanız gayet ezelden Kerbela çölünde giz oldum geldim Dönmedim yolumda, vazgeçtim serden Nesimi’den bu güne iz oldum geldim Bir za...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Çam']::text[], 8.5, '{"poet":"Hıdır Çam","poet_slug":"hidir-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kunyem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanırım', 'kiskanirim-aydin-bastan-k38yi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ruzgar bile dağitmasin saçini

kuşlar bile ötüşmesin derinden

ben duyayim üzüntünü acini

aşkim gitme gönlümdeki yerinden

bir kivilcim aksi vursa tenine

gül bağlari alev aldi sanirim

aynalarda fazla bakma kendine 

seni senden bile ben kıskanırım.', 'ruzgar bile dağitmasin saçini kuşlar bile ötüşmesin derinden ben duyayim üzüntünü acini aşkim gitme gönlümdeki yerinden bir kivilcim aksi vu...', ARRAY['Türk Edebiyatı','Şiir','Aydın Baştan']::text[], 8.5, '{"poet":"Aydın Baştan","poet_slug":"aydin-bastan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kiskanirim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakıp Gitti mi Aşk Sarpa Sarıyor Yaşam', 'birakip-gitti-mi-ask-sarpa-sariyor-yasam-atilla-guler-7j5mw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kınından çekilmişti hançer/geri konulmadı yalnızlık yerine bir daha

kirli bir yakınmalar ateşinde marazi bir suça düştük birlikte…sen ve ben

kanım kızardı/fırsat bulamadan bozarmaya/alaşağı oldu

tepetaklaktı hayat

…dün

dışavurumlu iç güdümsel bir patlama yankılandı koynumda

vurdu mu tam on ikiden/kaç kaçabildiğince…nefes nefese

kaynamadan kanım/kapamalıyım yatağımı aşka

ki beni bir daha aldatmasın/sahte renklere boyalı fahişe

de sana da nasıl karşı durulur bilemem ki

aç yatağını...bugün kollarındayım

…bugün

yarını boş ver…aşk yaşadıkça güzel…anında

…kızıl şehvetine vurulmuş saatleri yudum yudum al

…sonsuz kere…', 'kınından çekilmişti hançer/geri konulmadı yalnızlık yerine bir daha kirli bir yakınmalar ateşinde marazi bir suça düştük birlikte…sen ve ben...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/birakip-gitti-mi-ask-sarpa-sariyor-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Ah memleketim!', 'a-ah-memleketim-mikdat-bal-6mor0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin bağrında aklıma vurdu 

Hasret yetti artık ah memleketim! 

Kalbim bir hoş oldu nefesim durdu 

Sabrım bitti artık ah memleketim! 

Sevda mı tutku mu bilemedim ki 

Ne oldu da sana gelemedim ki 

Katıla, katıla gülemedim ki 

Neşem yitti artık ah memleketim! 

Burada yaşamak mubah olmuyor 

Bundan daha büyük günah olmuyor 

Ezanlara hasret sabah olmuyor 

Yeter, yetti artık ah memleketim! 

Bırakmaz sorunlar peşimi benim

Kâbusa çevirdi düşümü benim! 

Dünyanın işleri başımı benim

Derde itti artık ah memleketim! 

Mikdadî der var mı kaçacak mekân? 

Dönerdim mutlaka bulsaydım imkân 

Bu zalim gurbetten kurtulur çıkan 

Çoğu gitti artık, ah memleketim! 

Ozan Mikdadi', 'Gecenin bağrında aklıma vurdu  Hasret yetti artık ah memleketim!  Kalbim bir hoş oldu nefesim durdu  Sabrım bitti artık ah memleketim!  Sevd...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/a-ah-memleketim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'insanlik', 'insanlik-halide-selcan-karagul-o3tg9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsanlık! ! ! 

Boş laflarla uğraşırken birileri

Aldırmaz, umursamaz kimseleri

Riya ile yalan ile dost dediklerini

Aldatır, yüzlerdedir maskeleri

Rahat etmez sataşmazsa nefisleri

Ortalığa saçmazlarsa içindeki nefretleri

Kötülük batağına dönmüş kalpleri

Vilada da yetmez temizlemeye kirlerini

Kendi kendilerini Aldattıklarını bilmezler ki

İnsan suretinde, insanlıktan almamışlar ki nasiplerini

Ellerini, vicdanlarına koymamışlar ki bir kere dahi

Malayani işlerle uğraşır durur birileri

Geçmişi yok ki, olsun geleceği….

Yapışmış kalmış, üzerinden çıkmaz kötülük izleri…..

06.04.2004', 'İnsanlık! ! !  Boş laflarla uğraşırken birileri Aldırmaz, umursamaz kimseleri Riya ile yalan ile dost dediklerini Aldatır, yüzlerdedir maske...', ARRAY['Türk Edebiyatı','Şiir','Halide Selcan Karagül']::text[], 8.5, '{"poet":"Halide Selcan Karagül","poet_slug":"halide-selcan-karagul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/insanlik-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum', 'erzurum-abdulvahap-ates-whv0w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uçan kuşlar nerden çıkıp geldiniz

paçanızda mor sümbülün harı var

kaç buludu ortasından deldiniz

yüzünüzde hicretin efkarı var

geçtiniz mi palandöken dağından

nene hatun dadaşlık diyarından

tabyalardan pasininden alvardan

her doğan güneşin intizarı var

o diyarda alparslanlar gezindi

göç göç oldu göçler yola dizildi

nicesine nice name ezildi

her taşında emrahın figanı var

toprağı duayla kanla karılmış

dağlar kollarını açmış sarılmış

nefi kamu efe sende barınmış

şair alim tarihin ikrarı var

yakutiye yumruk gibi göklere

çifte minareler nice börklere

kapı oldun kale oldun türklere

ecdadımın her taşta efkarı var

erzurum rahminde doydum büyüdüm

kışında ağladım yazında güldüm

gurbeti koynuma alıp bölündüm

her hücremde senin ahuzarın var

kuşlar gelin konun elimden ötün

sılamın katıksız  dilinden ötün

beni de  götürün alın götürün

yüreğimde her eskinin narı var', 'uçan kuşlar nerden çıkıp geldiniz paçanızda mor sümbülün harı var kaç buludu ortasından deldiniz yüzünüzde hicretin efkarı var geçtiniz mi p...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/erzurum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama Olsun', 'ama-olsun-baris-caglar-v8hxm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Giderim aşkıma doğru

Başım yerde boynum eğri

Sevmem dediğin o yeri

Mezar ettin ama olsun.

Sevmemiştin zaten dünde

Sırt çevirdin iki günde

Evlendiğin o düğünde

Bil ki öldüm ama olsun.

Bitti artık aşık huyum

Sana sağlayamam uyum

Ben böyleyim yani buyum

Beğenmedin ama olsun.

Saf gibi oldum avare

Aşkımı söyledim yare

Doktora gittim bir çare

Veremedi ama olsun.', 'Giderim aşkıma doğru Başım yerde boynum eğri Sevmem dediğin o yeri Mezar ettin ama olsun. Sevmemiştin zaten dünde Sırt çevirdin iki günde Ev...', ARRAY['Türk Edebiyatı','Şiir','Barış Çağlar']::text[], 8.5, '{"poet":"Barış Çağlar","poet_slug":"baris-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ama-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakır Diken Sıcak', 'cakir-diken-sicak-ahmet-hakan-yilmazturk-ot2l4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yanaklarım

kızgın kumda, yalın yanak

yapışmış yüzüme 

çakır diken bir sıcak

rüya bu ya

dilim damağım kurumuş

kum çiğnemişim

ballı hurma niyetine

çakıl yutmuşum da

takılmış yutağıma

keskin köşeleri

yüreğime dokunmuş

sıkıştırıp durur 

biçare zembereği 

pır pır ediyor 

yavru bir kuş

hiç anlam çıkarmayalım

yormayalım

ne hayıra, ne şerre 

çöl rüzgarına savuralım 

yok farzedelim 

hiç mi hiç yok

10-13 Şubat 2006', 'yanaklarım kızgın kumda, yalın yanak yapışmış yüzüme  çakır diken bir sıcak rüya bu ya dilim damağım kurumuş kum çiğnemişim ballı hurma niye...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cakir-diken-sicak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Giderken', 'sen-giderken-ayse-manav-yjqog', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Giderken gülüşlerimi aldım yüzümden,

Giderken hayallerimi sildin zihnimden,

Giderken beni aldın benden,

Giderken düşlerimi çaldım benden,

Bir sen kaldın içimde,

Bir de o deli sevdan.

13.02.2006', 'Giderken gülüşlerimi aldım yüzümden, Giderken hayallerimi sildin zihnimden, Giderken beni aldın benden, Giderken düşlerimi çaldım benden, Bi...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Manav']::text[], 8.5, '{"poet":"Ayşe Manav","poet_slug":"ayse-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-giderken-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mucizeler Kumpanyası', 'mucizeler-kumpanyasi-mujde-soyturk-w4s3w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatırlıyor musun 

Bir kuşun kanadıyla sana gelişimi,

Senin bir buluta binişini,

Bulutun soğuğa yağmur deyişini,

Ezgilerin damla damla yere inişini.

Anlıyor musun

Sevginin emekle işlenişini,

Vermenin kutsal mucizesini.

Paylaşmanın göz bebeğinde görebiliyor musun

İnsan olmanın cilvesini.

Biliyorsun

Tüm bu mucizeleri kendimiz yarattık.

Sonra çocuk olduk onlara kanat taktık,

Bulutlara koyduk dağıttık

Ama yanıldık.

Her göz alışık değildir görmeye

Ya da her kulak duymaya

Bizim yaşamaya olduğumuz kadar.

Kimse anlamaz kimsenin mucizesini

Kendisininki kadar.

Tüm mucizelerden insan başına

Sevgisi kadar düşer.

Mucizeler insanlar tarafından

Anlaşıldığı kadar yaşanır.

İnsan yürekten yaşadığı kadar mucize yaratır.

14.02.2006', 'Hatırlıyor musun  Bir kuşun kanadıyla sana gelişimi, Senin bir buluta binişini, Bulutun soğuğa yağmur deyişini, Ezgilerin damla damla yere i...', ARRAY['Türk Edebiyatı','Şiir','Müjde Soytürk']::text[], 8.5, '{"poet":"Müjde Soytürk","poet_slug":"mujde-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mucizeler-kumpanyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Yanında Olmak Vardı', 'simdi-yaninda-olmak-vardi-hatice-bediroglu-l4vl3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi yanında olmak vardı sevdanın

İçim titrerdi gözlerine bakarken.

Okşardı saçlarını ellerim

Sunardım her teline sonsuz sevgimi.

Çılgınca istekler sararken içimi

Bir kucaklardım ki seni sımsıkı.

Gülümseyen kocaman ağaçlardan

Toplardık ne güzel meyvelerimizi.

Kaybederken yolumu teninde

Dalardık sınırsız düşlere...

Şimdi yanında olmak vardı sevdanın

İçim titrerdi gözlerine bakarken

'' Düş Kuruyor Gece '' adlı kitabımdan - Ocak 2008 -

www.haticebediroglu.net', 'Şimdi yanında olmak vardı sevdanın İçim titrerdi gözlerine bakarken. Okşardı saçlarını ellerim Sunardım her teline sonsuz sevgimi. Çılgınca ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/simdi-yaninda-olmak-vardi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ki Yanarım', 'ben-ki-yanarim-mevlut-yanar-nvdry', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben ki yanarım

Gidişatıma

Çözüm ararım

Karmaşık

Sarmaşık

Çapraşık

Dolaşık Müşkülatıma

Bilirim ki ben

Başkasının hayatı 

Dolanır hayatıma

Virgüller koyamadım

Saçımı apak eden

Ömür safahatıma

Bir türlü küsemedim

Sürekli beni yoran

Gönül meyliyyatıma

Ben ki yanarım

Gidişatıma

         Konya.01.02.2006', 'Ben ki yanarım Gidişatıma Çözüm ararım Karmaşık Sarmaşık Çapraşık Dolaşık Müşkülatıma Bilirim ki ben Başkasının hayatı  Dolanır hayatıma Vir...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Yanar']::text[], 8.5, '{"poet":"Mevlüt Yanar","poet_slug":"mevlut-yanar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-ki-yanarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdeydin Azrail', 'nerdeydin-azrail-suleyman-yavuz-ov1ff', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüm sen benim solmaz gülümsün 

Al bedenimde senin olsun

Ruhumu veremem 

O zaten satıldı şeytana

Geç kaldın beni almakta

Sen gelmeden geldi iblis

Aldı götürdü 

Bıraktı beni geride

Duygusuz hissiz

Umarsız

Geç kaldın azrail

Çok geç 

Ruhsuz bedeni al sende

Ama inan veremez bir 

Kalem hesabını bile

Al götür yinede', 'Ölüm sen benim solmaz gülümsün  Al bedenimde senin olsun Ruhumu veremem  O zaten satıldı şeytana Geç kaldın beni almakta Sen gelmeden geldi ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nerdeydin-azrail-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Demiştim, Gittin', 'git-demistim-gittin-ramazan-ates-zr8rs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Git demiştim bir gün sana,

Artık beni sevmez isen,

Bana gönül vermez isen.

Git demiştim o gün sana.

Ve gittin.

Başın değmiştir göğe.

Arkandan ağlamadım.

Karaları bağlamadım.

Beni istemiyenle işim yok,

Mutlu ol, artık mutlu yaşa.

Bende artık yerin yok,

Sen artık tercihinle yaşa.

Demiştim, sevmem diye.

Geri gel demem diye.

Sen istedin böyle olsun,

Geçti, pişman olsan bile,

Bitti artık, ölsen bile.

Ramazan Ateş/Enschede-18.8.2005', 'Git demiştim bir gün sana, Artık beni sevmez isen, Bana gönül vermez isen. Git demiştim o gün sana. Ve gittin. Başın değmiştir göğe. Arkanda...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/git-demistim-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bekledim', 'seni-bekledim-rahim-recep-akdora-dnxrp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıl boyu sana topladım kırçiçeklerini

Bir bir gizledim onları kitaplarımın arasına

Çiçekleri masama dizip ellerimle kapatacaktım gözlerini

Sonra çiçeklere bakışlarını sürecektim kalbimin yarasına

Şimdi masamda boncuk boncuk çiçeklerin gözyaşı

Doğal renkleriyle doğal kokuları ağlattı beni de

İstemesem de yine isteklerimin üzerinde kaldı ayrılık taşı

Yine gülmedi yüzüm bu sevgililer gününde de

Unutmak tanımaktan, yaşamaktan önce olur güzelim

B iz yaşadık, her anı bir tuğla duvarlar ördük, ev kurduk 

İzlerimiz var bizim o dağların her taşında, gel yine gezelim

Anımsayalım topladığımız çiçeklerle kaç kez rüzgara tuzak kurduk 

Akdora’nın doruğunda rüzgara açmıştın gözlerini

Rüzgar tüm sisleri, şüpheleri silip süpürmüştü gözlerinden

Ben beni gördüm gözlerinde, hissetim nefesimde nefesini

Bir bilmece gibi beni sevdiğin gülümsüyordu sözlerinden

Zaman bizi ayrı kıldı birbirimizi kırmadan

Birbirimizi yaşayarak yaşadık başka yaşadıklarımızı

Her görüşümde ben yine gözlerindeydim görünürdüm uzaktan

Kaç kere yasaklarla sarmaldık kışımızı, yazımızı

Seni bekledim yine umutlarıma inanarak

Gelemedin

Bende kaldı

Çiçekler

Hediyeler

Mumlar eridi bitti kendi kendine yanarak', 'Yıl boyu sana topladım kırçiçeklerini Bir bir gizledim onları kitaplarımın arasına Çiçekleri masama dizip ellerimle kapatacaktım gözlerini S...', ARRAY['Türk Edebiyatı','Şiir','Rahim Recep Akdora']::text[], 8.5, '{"poet":"Rahim Recep Akdora","poet_slug":"rahim-recep-akdora","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-bekledim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başladım', 'basladim-ramazan-ates-ckl7i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlamak istiyorum,

Yalnızken, kimsesizken.

Ağlamak istiyorum,

Tek başıma sensizken.

Göz pınarlarım kuruyuncaya,

Yaşlar beni boğuncaya,

Ta kendimi buluncaya,

Ağlamak istiyorum.

Gönlüme söz geçer belki,

Acılarım diner belki,

Yangınlarım söner belki,

Ağlamak istiyorum.

Ağlamak istiyorum,

Yok olup gidinceye,

Ağlamak istiyorum,

Ta ki bir gün ölünceye,

Ta mezara girinceye.

Ve ağlıyorum....

Ramazan Ateş/Enschede-18.8.2005', 'Ağlamak istiyorum, Yalnızken, kimsesizken. Ağlamak istiyorum, Tek başıma sensizken. Göz pınarlarım kuruyuncaya, Yaşlar beni boğuncaya, Ta ke...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/basladim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbrahim Rugova', 'i-brahim-rugova-mevlut-yanar-bgnp2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ocak yirmi üçtü

Uçtu

İbrahim Rugova

Kosova 

Artık öksüz

Kosovalı ağlamada

İkibinaltı

Kosovanın ümitlerini aldı

Piriştinede  hüzün üstüne 

Karlar yağardı

Ve ağlardı her güzellik

İbrahime ağlardı

Şu baygın yatan fular

Rugova onu

Boynuna bağlardı

Ağlayın Kosovalılar

Sönsün ciğerlerde nar

Daha doğacak güneşler aylar

Analar daha ümitvar

Murat Hüdavendigar

Bilmeyiz nasıl ama

İbrahimi karşılar

Binüçyüzseksendokuzla ikibinaltı arasında

Sadece altıyüzonyedi var

Priştineden Kabeye

Mihraplardan çağıl çağıl akar

Dualar var aminler var

Gönüllerinde müminlerin

Muhammed var

Alemlerin efendisi

Muradlar Rugovalar

Onu candan aziz bilir 

Dillerinden düşürmezdi

Bugün inanıyorum ki

Sancağının altındalar

      24.Ocak.2006', 'Ocak yirmi üçtü Uçtu İbrahim Rugova Kosova  Artık öksüz Kosovalı ağlamada İkibinaltı Kosovanın ümitlerini aldı Piriştinede  hüzün üstüne  Ka...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Yanar']::text[], 8.5, '{"poet":"Mevlüt Yanar","poet_slug":"mevlut-yanar","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ibrahim-rugova-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik şehrin figüranı', 'yitik-sehrin-figurani-sair-sonbahar-u5hhu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sokaklar...

ıssız sessiz sokaklar

sokaklar sahipsiz ve zifir kara sokaklar

yalnızlığım doldurmuş bu boş sokakları

kimsesizliğime kucak açmış

yağmurdan sırılsıklam kaldırımları

gökyüzü örtmüş üstümü böyle suskun gecelede

ve sokaklar sırdaş olmuş bana

bitmeyen derdime olmayan çare

ben giderim yollar uzun

bitmez bir türlü  gece 

ben ağlarım susmaz gözlerim ama heyhat

sesim duyulmaz nafile

sokaklar mı  tesellim

sokaklar mı arkadaş

onlar mı ki gerçek dost

onlar mı tek yoldaş

kimsesizim...

sokaklar gibi sahipsiz

beyhudeyim avareyim

yürüyorum gayesiz

kaybetmişim yolumu

yönüm nere bilemem

kaybetmişim kendimi

neredeyim çözemem

bu şehir viran olmuş

içinde ben de ziyan

unutulmuş bu şehrin sokakları

bende yitik şehirde olmuşum bir figüran', 'sokaklar... ıssız sessiz sokaklar sokaklar sahipsiz ve zifir kara sokaklar yalnızlığım doldurmuş bu boş sokakları kimsesizliğime kucak açmış...', ARRAY['Türk Edebiyatı','Şiir','Şair Sonbahar']::text[], 8.5, '{"poet":"Şair Sonbahar","poet_slug":"sair-sonbahar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yitik-sehrin-figurani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Desem Boş', 'ne-desem-bos-ramazan-ates-1ae8x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ot bile anlıyorken halimden,

Beni anlamadın ya, ona yanarım.

Kuşlar bile sohbet eder benimlen,

Beni dinlemedin ya, ona yanarım.

Ben gel dedim, geri gittin on adım,

Hiç yüzünden, neye çıktı bak adım.

El içinde perişan, başı eğik yaşadım,

Beni kollamadın ya, ona yanarım.

İnsan olmak bana niye yaramaz? 

Neden bilmem, beni kimse anlamaz? 

Ben var idim, kayıp oldum,yokum ben,

Beni aramadın ya, ona yanarım.

Artık dünya benim olsa ne yazar? 

Azrailim sağımda, solumda gezer.

Bu dünyaya bana eydin sen mezar,

Beni güldürmedin ya, onda yanarım.

Ramazan Ateş/Enschede-15.8.2005', 'Ot bile anlıyorken halimden, Beni anlamadın ya, ona yanarım. Kuşlar bile sohbet eder benimlen, Beni dinlemedin ya, ona yanarım. Ben gel dedi...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-desem-bos-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sorarsanız', 'beni-sorarsaniz-ramazan-ates-mqrba', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ham olanın piştiği,

Gönüllere düştüğü,

Bir ocak başkanıyım.

Gençleri azim dolu,

İman adalet yolu,

Bir ocak başkanıyım.

Gönüldaşlar bir olmuş,

Sevgi ile kurulmuş,

Bir ocak başkanıyım.

Sevgi, saygı en önde.

İnsanların gönlünde,

Bir ocak başkanıyım.

Halka hizmet aşkıyla,

Yaşıyorda coşkuyla,

Bir ocak başkanıyım.

İlim, irfan ve sevgi,

Sıcak, sakin şefkatli,

Bir ocak başkanıyım.

Türk-İslam ülküsüne,

İnanmış, kabul etmiş

Bir ocak başkanıyım.

Başbuğ’un mirasıdır,

Her gencin rüyasıdır,

Bir ocak başkanıyım.

Allah yolum ak etsin,

Sevenlerim çok etsin,

Bir ocak başkanıyım.

Ben ocak başkanıyım.

Ramazan Ateş/Enschede-13.2.2006', 'Ham olanın piştiği, Gönüllere düştüğü, Bir ocak başkanıyım. Gençleri azim dolu, İman adalet yolu, Bir ocak başkanıyım. Gönüldaşlar bir olmuş...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/beni-sorarsaniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR BAŞKA DiYARDA...', 'bi-r-baska-diyarda-levent-i-skenderoglu-smurb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabırla yüklenmiş yükler,

Eğri büğrü develere

Yol almakta  şimdi

Böcekler diyarına

Islatmaz gözleri

Sabah bayatı

Çiğ taneleri

Duyulmaz ardından

Şairin

Aşk nağmeleri

Varılacak yerde

Bedenler kokuşmuş 

Yüzlerse soluk

Güneşte yoksa kirpikler de

Biter 

Kör aydınlığa yolculuk', 'Sabırla yüklenmiş yükler, Eğri büğrü develere Yol almakta  şimdi Böcekler diyarına Islatmaz gözleri Sabah bayatı Çiğ taneleri Duyulmaz ardın...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-baska-diyarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Şiirler Biraz İs Kokar', 'butun-siirler-biraz-i-s-kokar-metin-soydeveli-h0b91', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılıkların şairi olmak en kolay 

Paylaştıkça azalırmış acılar

Bunun içindir ki…

Her şairin dilinde, hep acı var

Her ayrılığın ardından

İstense bir kitap yazılır

Her kitabın yazanı 

Şahsına münhasır

Tadı başkaymış aşkın

Tatlıymış, şekerden, baldan

Bunun içindir ki…

Her şairin dilinde, aşk var

Aşk yanar ateş imiş

Yanarmış tutulan

Bunun içindir ki…

Bütün şiirler biraz is kokar', 'Ayrılıkların şairi olmak en kolay  Paylaştıkça azalırmış acılar Bunun içindir ki… Her şairin dilinde, hep acı var Her ayrılığın ardından İst...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/butun-siirler-biraz-is-kokar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Şubart Sevgililer Günü', '14-subart-sevgililer-gunu-yusuf-ter-f2tv8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nasıl bir sevgililer günü bu? 

hangi hediyeyle, 

Karşılama, 

kırmızı güllerle mi olacak? 

Gözlerden uzak 

bir yerlerde akşam yemeği şart.

Masa, önceden hazırlanmış 

çiçeklerle donatılacak. 

İki tane yanan mum 

dudağımdan dökülen kelimeler,

bir de kemancı geceye anlam katacak.

Romantik gecemde

şampanya patlayacak.

Dans edileceğiz,

gecenin geç saatlerine kadar 

Nasıl bir sevgililer günü bu? 

Öfkelere bile tuz basıp

barış içinde sevgiliye söylenecek 

özenle seçilmiş sözcüklerim olacak.

Mutfakta o gün sen ne yapacaksın. 

Bir sürpriz yapmalı! 

Sinemaya mı götürmeli,

ormanda, ağaçlar arasında mı dolaşmalıyız 

Yoksa, çok uzaklara gitmeliyiz.

Evde oturup bu günün dünden

farklı olmadığını mı düşüneceğiz.

Mac seyredip çığlık mı atacağız,

çay demletip yanında kırıntılar

Nasıl bir sevgililer günü bu? 

Her fırsatta çiçekler getirsem de

ayda bir sinemaya, tiyatroya gitsek 

bir hediye ile mutlu etmek.

Ama yinede gün aynı gün, 

Senede bir gün gelen sevgililer günü müydü,

Senden bir kırmızı gül 

dudaklardan dökülecek. 

‘Seni çok seviyorum’u bekler işitmeyi

sevginin ifadesine kulak vermeli, sevgililer gününde

Her gün çiçek olan kadınlar, 

değerlerine kıymet biçilmez,

onlardan vaz geçilmez. 

Onları kimse incitemez, ezemez.

Sevgililer gününde devamlı sevginin, aşkın adı olunur.

Elimde hediyemle, sevgimi sunacağım sevgilime, 

bir bayram yaşamak, sevgiliyle

14 şubat sevgililer günün

kutlu olsun, kutlu olsun sevgilim…..

Yusuf Ter', 'Nasıl bir sevgililer günü bu?  hangi hediyeyle,  Karşılama,  kırmızı güllerle mi olacak?  Gözlerden uzak  bir yerlerde akşam yemeği şart. Ma...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/14-subart-sevgililer-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Şubat...', '14-subat-ercan-akbay-k5lij', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün senle yakın iken uzağız,

   Bunu sakın dert etme sevgilim.

   Özlem yüklü bir kalp,iki dudağız,

   Ondört şubat,kutlu olsun sevgilim.

   Sokaklarda bembeyaz bir gece var,

   Rüyam senle,rüyan benle sevgilim.

   Bir ateş ki,alev alev hep yanar,

   Ondört şubat, kutlu olsun sevgilim..

   Bugün gibi hergün mutlu olalım,

   Paylaşalım sevinçleri sevgilim.

   Şiir,şarkı,türkü,aşk biz olalım,

   Ondört şubat,kutlu olsun sevgilim...

                                         1992', 'Bugün senle yakın iken uzağız,    Bunu sakın dert etme sevgilim.    Özlem yüklü bir kalp,iki dudağız,    Ondört şubat,kutlu olsun sevgilim. ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/14-subat-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Çiçeği-4', 'ates-cicegi-4-adnan-durmaz-mqra9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şalvarının uçkurunu koparttı yırttı çıkarttı

Yırttı çıkarttı güllü fistanını al köyneğini

Kaydı kurtuldu Hatçe / devrildi çırılçıplak

İçinde ne varsa korkulara dayanan

          	bütün setleri yıkıldı

Ay aylası bir dişilik fışkırdı

           	yuvarlanan kalçalarından

           	korkunç yakıcı bir pembelik

Avcının azgınlığı zaptolmaz bir delilikte

Ve diri memeleri yuvarlandı kurbanın

            aklını aldı avcının

Kösnü çıldırtan çığlıklar aklını başında zay etti

Kar’Üseyin çıktı insan olmaktan

Baştan başa şaha kalkmış bir erkeklik kesildi

Yakaladı avını / elini ayağını

            bağladı dört yanına topakevin

Hatçe’yi sımsıkı gerdi

Çığlıklar bir kamçı gibi

Soyundu bir solukta giysilerini

Ve yanaştı avına

Bütün hışmıyla diz gelip

Bütün hışmıyla yekindi

Geceyi bir sancı gibi yırttı kurbanın sesi

Bin renkli kilimin üstüne

           	bir de kan rengi eklendi

Soldu sıtara çiçeği...

Bütün arılıkları dünyanın

          	çıkartmaz kötülüğün kirini

İspirto rengiydi gece

Bedeninin altında bacakları köpek kesildi

Hatçe’nin ruhunu dalayacak yaşadıkça

Bir ölü soykası gibi taşıyacak

            destan güzelliğini bundan sonra

Peri kızı Skylla bozkırlar ortasında

Filik kızı Hatçe oldu o gece

Kim bilir kaçıncı kez

Dirildi acının yazılmayan tarihinde

Bozkırda bir yerlerde...

İşte o gün ağladı Hatçe

Çiğillipınar’ca coştu

Yağdı kırkikindilerce

Yaşanmamış ergenliği içinde

setlerini yıktı taştı

Daha memeleri çıkmamış

Kızım deyi- er  yüzüne bakmamış

Başına da al duvaklar vurunmadan

Eline de al kınalar yakınamadan

Kollarına gümüş cebe

Kulağına altın küpe

Duluğuna dulukbastı takınamadan

Çalgılar çaldıramadan

Okuntu saldıramadan

Yüreği mılcımış canı ezilmiş

Soyka çıkmış güzelliği 

Gayrı kendi eti kendine düşman

Isırır Kar’Üseyin’in etine değen yerler

dalar tüm gövdesini

Kırılmış gökçegülün goncası

Allı turna yaralanmış uçamaz

Böyle görse aklını yer anası

Oturmuş bir utanç gibi

Ağlar da ağlar olmuş Hatçe Kız

            ırmağı kurumuş turaç gibi

Babasız büyümüş omuzu düşük

Doyamamış kokusuna anacığının

Ha yaşamış- ha ölmüş hiç mühimi yok

Ağlar da ağlar olmuş Hatçe Kız

Bir amanı yerde bir amanı gökte

Aklına olmadık bir şeyler düşer

Pencerenin deliğinde ıtır çiçeği

Gayrı susuzluktan kurumuş mudur

Tentenesi garip kalmış sandıkta

Acep mor fistanını kimler giyecek

Ağlar da ağlar olmuş Hatçe Kız

Avazı yayılır yayla yelinde

Duyanın içini oyar da oyar

Ağlaya ağlaya uyur Hatçe Kız

Uyanır ağlaya ağlaya

Gecenin bir yarısı

Alaçığın duldasında

Kıpırtısız dört beş insan

Yıldızlar cohcohlu parlıyor

Suskunluk utanca boğulmuş

Birisi konuştu ansızdan

Sesi yarısı yanmış ağalar gibi

Çok eski bir yarayı sır diye saklar gibi sesi

Dedi ki Arap cephesinde

        	kum ve ateş cehenneminde

Balkanlarda kan içinde

Allahuekber tipisinde

Çanakkale içinde bomba selinde

Hasılı tüm cephelerde savaştık

At bokunda arpa devşirmenin

Ve her ne sebeple olursa yenilmenin

      	öğünecek bir yanı yok

Kimisi kum altında kimi kar

Yeri yurdu belirsiz kaldı kalanlar...

Dünyada bozulmuş ordudan berbat

Ne bir hayvan- ne bir nebat...

Aylarca aç

Ve bilmediği ellerde

          	gidecek yersiz asker

Akıl almaz derecede korkak

Ama on adamı boğabilir tek başına

Hasılı çöl harbinde bozulduk

Döküldük yollara yayan yapıldak

Kimi sayrı- yaralanmış kimisi

Kimi su geçerken kimi donarak

Sinekler gibi öldük

Kalanlar ayak yalın- baş kabak

Hayvan gibi otları avurtlayarak

Bir deri- bir kemik Adana’ya döküldük...

Adana İstasyonu’ nda tren

Say ki bir kara umut

Üstü üste-alt alta yığıldık vagonlara

Kaçıp gitmiş makinistler

Arayıp-sürecek adamlar bulduk

Gördük ki kömür yok yola çıkacak

Baktık ki istasyonun dört bir yanı baraka

Söktük tahtaları kaydık kömür kazanına dehledik

İkinci istasyonda sonra da üçüncüde

Cümle uğrak yerlerinde ne kadar baraka varsa

         	yağmaladık da yaktık dehledik

Tüm memleketi dolaştık

Asker bindi - asker indi

Kimisi dağlara sindi

Kimisi sevk oldu başka cepheye

Nasıl dile dökülür onca acılar

Nasıl unutulur memlekette melûl- mahzun kalanlar

Kar altında- kum altında ölenler

Nasıl anlatılır mecalsiz- silahsız asker...

Ölsem de çıkmaz aklımdan

Tüm bunların hiç birisi

Gayrı bir de kuzular gibi meleyen

        	şu fukara kızın sesi

Adam usulca sustu

Orman usulca sustu

Ay usulca sustu

Hatçe susmuştu...

Çiğillipınar yaylasında alaçıklar

Bir fısıltı kesilmiş Hatçe

Düşmüş yellerin önüne

Önce Karacalar’a iner

Oradan ulaşır kendi köyüne

Derler ki Kar’ Üseyin 

Zorla ilişmiş Hatçe’ye

İp atıp ölmeyi denemiş becerememiş

İlkin topakeve bağlamış

Bir gece- bir gündüz başına çökmüş

O çökmüş Hatçe bağırmış

Kar’ Üseyin dediğin eşkıya başı

Tutuvermiş kolundan kaldırmış dağa

Gece sekiz gündüz dokuz yıkmış altına...

Filik kadın hükümete şikayet etmiş

Aptil Ağa sulhçu gitmiş

Kel Mustafa olmaz demiş

         Hatçe bizim gelinimiz

Hatçe’yi her yıktığı çalı dibine

Kar’ Üseyin üç taş dikmiş

...itmiş

...ditmiş

...şitmiş

...litmiş

...itmiş

...imiş

...mişmiş

...niş

      şşşşşşş...

Bir fısıltı oldu Hatçe

Hüseyinin yanında dolaştı dağdan dağa...

Kayanın kuytusunda uyurken

Tam da kuşluk zamanı

Hatçe uyanıp da kaçmış

O sırada Hatun gelin yün yıkarmış su başında

Hatçe birden çıkıvermiş

Kar’ Üseyin peşimdedir sakın beni deme demiş

Dulukbastısından bir altın yolmuş

     	Hatun’a Anahor vermiş

Az sonra Kar’ Üseyin sorunca Hatun

        başıma çöker sanıp söyleyivermiş

Ormanın içinde bir kovuğa sinmiş

Üseyin şirpeden bulmuş

Geçerken Hatun’un yanından

Altınımı geri ver kız zilli -demiş

Hatçe oturumu üstüne gelemeyince

Kar’ Üseyin dağdan inmiş

...itmiş

...ditmiş

...şitmiş

...litmiş

...itmiş

...imiş

...mişmiş

...niş

      şşşşşşş...

Kel Mustafa usul usul konuştu

İnadından vaz geç Hatçe

Neylesek olanlar oldu

Sen de namlı bir atanın kızıydın

Allah bir gelinimizsin

Sen dile düğünler kuralım

Erkek seldir- kadın büvek

Azıcık da sen uyar ol

Abılalık düşer sana 

Dile kutnu kumaş dile al duvak

Dananın oynaması kazıktan

Bu çetecilik de canıma yetti

Gir aklına Üseyin’in

Belayı kadayı savak

Cayıp bu işlerden varıp gidelim

Kurtulak kargıştan- yazıktan

Başka diyarlarda vatan çatalım

Paraysa para bizde / malsa mal gani

Kar’ Üseyin gecenin geç yarısı

Açıp girdi kapıyı lambayı yaktı

Dışardan Hatçe’nin çığlıkları duyuldu...

Ertesi gün konuştu Kel Mustafa

Haklısın dünyanın bütün dağları kadar

Çiğillipınar’ın akmasından çok

Sıtara çiçeğinin açması kadar

Gayri ne fayda

Gece yarısı girdi Kar’ Üseyin

İçerden çığlıklar duyuldu

Hatçe bir fısıltı oldu

Düştü yellerin önüne

Kel Mustafa konuştu

Memlekette büyük savaş olmakta

Her yanda kan yürümüş meşe selleri gibi

Dünyanın dört bucağında

       	askerler kırılmakta

Bizim asker yenilmez aslında

Açlık sürüleri- bit orduları

Açtırmıyor gözünü ki vuruşsun koçlar gibi

Kar’ Üseyin ağam bu gün 

  	cepheye asker sevketti

Kar’ Üseyinin atlıları

Toz bulutlarından bellidir

Kimisi Çifteler’de kimisi Dişliköy’de

Daydallı’da- Çaykışla’da- Honam’da

Bazan birkaç kişi bazan ellidir

Varır dayanırlar varlının kapısına

Kar’ Üseyin adına vergi toplarlar

Kelep kelep altın gelir yığılır ortalığa

Mecidiye- reşadiye altınlar

         dökülür Gelin’in ayağına

Ve yoksul hanelerde un uçar- kepek kaçar

Tarlalar tohumsuz ocaklar odunsuz kalmış

Gülüşler bile sap sarı

Bakışlarda geri dönmez yolcuların kanayışları

Ülkenin dört yanından kan çığlıkları

Ve başka bir karabasan düşman postalları....

devam edecek', 'Şalvarının uçkurunu koparttı yırttı çıkarttı Yırttı çıkarttı güllü fistanını al köyneğini Kaydı kurtuldu Hatçe / devrildi çırılçıplak İçinde...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":252,"source_url":"https://www.antoloji.com/ates-cicegi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-metin-soydeveli-vcdwz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saklayacaktım seni aklımca 

Kendime, sadece kendime 

Bilemedim 

Çuvala sığmaz bir mızrak olduğunu 

Götürüp Ağrı’nın tepesine 

Saklayacaktım 

Kimseler görmesin diye 

Sadece, sadece kendime 

Gömecektim okyanuslar dibine 

Gizleyecektim 

Taç mahal’in kubbelerine 

Bilmem sığacak mıydın 

Kolay mı saklamak 

Emekte saklı mutluluk 

İçime de sığdıramadım 

Yüzümde ayan beyan', 'Saklayacaktım seni aklımca  Kendime, sadece kendime  Bilemedim  Çuvala sığmaz bir mızrak olduğunu  Götürüp Ağrı’nın tepesine  Saklayacaktım ...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mutluluk-133-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Bir Hüzün Var Sessizliğimde', 'i-nce-bir-huzun-var-sessizligimde-birsen-ates-un3mk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yolunu kaybetmiş martı gibiyim

çığlık çığlığa denizini arayan

yokluğunda üşür benliğim

üstüme yıkılmış koca şehrin 

amaçsız düşlerinde

yürüdüm inadına

avuçlarımda

ihanetin yakıcı nefesin 

ince bir hüzün var sessizliğimde

sevdiğimi söyleyemeden

kayboldum kalabalıklar içinde 

daha dün

sorguladığım

yaşananlar aşk mıydı

yarın yaşanacaklar

ötelerde bahar hissettiğim 

14.02.06', 'yolunu kaybetmiş martı gibiyim çığlık çığlığa denizini arayan yokluğunda üşür benliğim üstüme yıkılmış koca şehrin  amaçsız düşlerinde yürüd...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ince-bir-huzun-var-sessizligimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşlarımın Rengini Bilir misin?', 'gozyaslarimin-rengini-bilir-misin-i-sa-tekin-fy9oi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarımın rengini bilir misin? 

Sevgili...

Çünkü gözlerime bakmıyorsun

Yüreğimdeki sancıyı bilir misin? 

Sensiz kara gecelerimi

Sensiz senli duygularımı

Bilir misin sevgili? 

Gözyaşlarımı, umutlarımı

Umutlarımı bilir misin sevgili? 

Senin için çarpan yüreğimi

Bilirsin sevgili

Umutlarımı, aşkımı

Gözyaşımın rengini değil

Sevdamın rengini 

Sen diye atan nabzımı

Senin için çarpan yüreğimi

Bilirsin sevgilim', 'Gözyaşlarımın rengini bilir misin?  Sevgili... Çünkü gözlerime bakmıyorsun Yüreğimdeki sancıyı bilir misin?  Sensiz kara gecelerimi Sensiz s...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozyaslarimin-rengini-bilir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirler Tuttu Beni', 'siirler-tuttu-beni-nurten-altinok-aksa6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şarkılar tuttu beni

Sarhoşum bu gece

Andım da geçen günleri

Ne sen geldin meclise

Ne senden bir ses geri

Şerefe! 

Bu şiir senin için*

Hadi, dizeleri fon diple

Arabesk olsun, boş ver

Böyle takılalım bu gece

Sarhoşum dedim ya 

Sek içitim de şiirleri

Kıtalar hep senle doldu

Dizeler boşaldı bizimle

Şiirler tuttu beni

Şairler ağlattı sonra

Ah şu şarkıların bir dili olsa...', 'Şarkılar tuttu beni Sarhoşum bu gece Andım da geçen günleri Ne sen geldin meclise Ne senden bir ses geri Şerefe!  Bu şiir senin için* Hadi, ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/siirler-tuttu-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal Cennet', 'hoscakal-cennet-muammer-erturan-0pcja', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ata ata tozunu yolların,

yara yara karanlığı

yakın ettik ırağı...

Karşı yakasında gecenin,

unutulmaya yüz tutmuş renkleri

delikanlılık günlerimin...

Bir Kaplama düğününde gene 

çekeceğiz kafaları...

Yıllanmış dostluklar,

yollanmış umutlar saçılacak

köşe bucak...

Deli Horon oynanacak sıkça...

Arada bir Düz Hava,

Karşılama,

Çiftetelli...

Önce davul sesi...

Ardından klarnet...

Tutmayın beni be heeeyt! ..

Selam sana Kaplama! ..

Selam sana! ..

Şükür kavuşturana...

Dostlar tam kadro hazır...

Kaldırma zamanıdır kadehleri...

Kırlaşan saçlarımıza,

kırışan suratlarımıza,

yakılamayan yağlarımıza

ve hâlâ genç kalan yanlarımıza

ve hâlâ sönmeyen umutlarımıza

içelim hadi! ..

İçelim ve şenlenelim...

Ve şenlendirelim düğünü bir güzel...

Yıldızlar ne kadar parlak...

Ne kadar yakın ay ışığı...

Ya okşayan hışırtısı yaprakların...

Ya sakalım gibi ak şu bardak...

Ayılmak isteyen kim...

Bölmekten yana değilim geceyi 

hiç mi hiç,

hiç kimse kalmasa da masada...

İlahi Adnan abi! 

Unutulmuş falan değilim...

Toprağında uyanmak istedim cennetin

sadece ve sadece,

mesele bundan ibaret...

İşte cennet bu! 

demiyor muydu Kemal...

Al benden de o kadar işte...

İlle de birşeyler yapmak istiyorsan

kardeşine ama

buz gibi bir bira şimdi

çok makbule geçerdi hani...

Düğün alayı da bitti...

Gelini gönderdik,

sıra bizde...

Ata ata tozunu yolların,

yara yara karanlığı

dönme zamanı cehenneme...

Hoşçakal Cennet! ..

(Ağustos ''00)', 'Ata ata tozunu yolların, yara yara karanlığı yakın ettik ırağı... Karşı yakasında gecenin, unutulmaya yüz tutmuş renkleri delikanlılık günle...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/hoscakal-cennet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş...', 'bekleyis-hasan-esat-heptunali-nborz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'beklemeye dair

sözüm var zamana

ki...

o gün kim gelir bilinmez…

bir kara tren geçer içimden…

durur sonunda 

benim olmayan şehrin bi yerinde

ve sen inmezsin…

……………….

Sözün vardı ….

Sen …

İnmedin…', 'beklemeye dair sözüm var zamana ki... o gün kim gelir bilinmez… bir kara tren geçer içimden… durur sonunda  benim olmayan şehrin bi yerinde ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Esat Heptunalı']::text[], 8.5, '{"poet":"Hasan Esat Heptunalı","poet_slug":"hasan-esat-heptunali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekleyis-168-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elde Var Şimdi', 'elde-var-simdi-muammer-erturan-ai0cb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neleri bırakmadın ki

nerelerde

nelerden caymadın ki

neler neler için 

ve nerelere geldin 

nerelerden... 

Değdi ya da değmedi 

ne önemi var 

geçti o zamanlar, 

elde var şimdi... 

(''97)', 'Neleri bırakmadın ki nerelerde nelerden caymadın ki neler neler için  ve nerelere geldin  nerelerden...  Değdi ya da değmedi  ne önemi var  ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/elde-var-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamı Taçlandırıyorum.', 'sevdami-taclandiriyorum-metin-soydeveli-kosbk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne çoraplar öreceksin başıma biliyorum! 

Seni sevdiğimi söylemeye çekiniyorum

Alacaksın özgürlüğümü elimden, kaçacak 

Nafile zorlamam, aşkımı söylemeden  olmayacak.

Ya özgür kalıp uçacağım viraneden viraneye.

Ya da örselenip kapanacağım  altın kafesine.

İkisinin ortası bir  denge yok biliyorum

Özgürlüğü feda edip gönüllü kafesine giriyorum.

Sen beyazlar içinde, elinde peynir çiçekleri,

İnanamıyorum bu yaşadığım gerçek mi? 

Kaleler fethetmiş muzaffer edalar bende,

Koluma girmiş, kuğular gibi süzülüyordun.

Bu gün çok sevinçli, çok şenim.

Sensizliğe veda ediyorum  Nimet’im.

Sevdamı, aşkımı taçlandırıyorum.

Kocan oluyor, bu gün evleniyorum.

Bundan böyle helalim olacaksın.

Sevgiyi, sıcaklığı bende bulacaksın.

Yuvamın bekçisi, çocuğumun anası sen,

Sevgilim, bir tanem daha ne’m olacaksın.

Sırrı çözülemez bir şarap misali

Yıllanacağım seninle, sende.

Bilinmez keramet nasıl kimde

Tadım kalacak küp misali sende.

(14 ŞUBAT 2006  İzmir)', 'Ne çoraplar öreceksin başıma biliyorum!  Seni sevdiğimi söylemeye çekiniyorum Alacaksın özgürlüğümü elimden, kaçacak  Nafile zorlamam, aşkım...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevdami-taclandiriyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ö y le başladı öy k ü...', 'o-y-le-basladi-oy-k-u-zafer-zengin-etnika-0l6px', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.

olan bitenin mükemmele ulaşmadığına,

taşın keskinliğinin icadına dair

yazılı düşünmeler; 

.

öyle başladı öykü

bir silah ele değince

ve yeniden kendine dönünce

icat dedik

ekmek

iç

taş

recm için

saçlar uzun olacak

.

sonra kaç koşma

kaç sızı

doyar tüm hayvan yanı

ıssızlığı

yalnız koca dünya

bizle bir başına

.

ilk ağlamanın

öyküsünü anlatmadım

bilinir sevgi yoktu daha

iç güdü kendini güderdi 

o vahşiliğin ortasında

insan nasılda varıyor 

kendi acısının farkına

acımı buraya getiren kılavuz

acımı en arsız sen anla

.

söyle

ilk neydi baktığın

ilk hangi tanrı

adını bağışladığın

tanrı yapıp taptığın

ağlama ‘yazgı son bulmadı

kabul etmekle kurtulmadın

manası olsun

manası yaşamanın…

03 07 2005

.', '. olan bitenin mükemmele ulaşmadığına, taşın keskinliğinin icadına dair yazılı düşünmeler;  . öyle başladı öykü bir silah ele değince ve yen...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/o-y-le-basladi-oy-k-u-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlanma', 'nazlanma-mehmet-can-ydm34', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'nazlanma güzelim

gelde gezelim..

sitem çare değil

sadede gelelim..', 'nazlanma güzelim gelde gezelim.. sitem çare değil sadede gelelim.....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nazlanma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce Fikir 2', 'dusunce-fikir-2-kamil-at-ogws4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kin ve nefret üzerine kurulu

Bir düşünce

İnanç yada fikir

Tabi ki denilebilirse

En sonunda 

Tarihten silinecek', 'Kin ve nefret üzerine kurulu Bir düşünce İnanç yada fikir Tabi ki denilebilirse En sonunda  Tarihten silinecek...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dusunce-fikir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An Gelir', 'an-gelir-muammer-erturan-koewo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'An gelir

çıkıverir yüze...

Bıkmıştır artık

suda balık olmaktan

ve uçarı bir dalganın kanatlarında

takılır yıldızların peşine...

An gelir

çekiliverir el ayak...

Ne kanat kalır ortada

ne uçarı dalga

ne yıldız...

Yapayalnız ve yaralı

ve bata çıka

vurduğu gün karaya

düştüğü gündür ölümler gayyasına

ecelsiz,

okşadığı gündür

hançer kabzalarını

Brutus''lerin...

Ve kaldırmaya kalmadan

başını şöyle bir

vurgunlar art arda gelir

ihanetler üst üste

acılar iç içe...

An gelir

ölüm de yitirir anlamını

yaşamak gibi tıpkı...

(18 Mayıs ''99)', 'An gelir çıkıverir yüze... Bıkmıştır artık suda balık olmaktan ve uçarı bir dalganın kanatlarında takılır yıldızların peşine... An gelir çek...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/an-gelir-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Ver Be Gılgamış', 'bos-ver-be-gilgamis-muammer-erturan-stfyu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yargılayan yargılayana

asan asana

kesen kesene

biçen biçene,

herkes yargıç kesilmiş

herkes cellat

herkes gardiyan,

kendine özgü tek bir yan

kalmayana dek

sürecek bu kuşatma anlaşılan...

Ve bir pundunu kollayacak

pusularda her daim

kusulmamış kinler alayı,

kimi madrabaz soytarı

kimi düzenbaz yalaka

kimi kırk yıllık dost postunda

çıkacaklar karşına

ve yağlı ip boynunda olacak hep

ve tabutun sırtında her an,

ferman böyle yazılmış...

Al sana ölümsüzlük! ..

Yaşarken ölmüşün ne gam...

Al sana özgürlük! ..

Yalnızlık pahasına illa ki...

Yaşamak bir sevda işi

sevda ise bir kavga,

kavgada yumruk sayılmazmış

boş ver be Gılgamış! ..

(97)', 'Yargılayan yargılayana asan asana kesen kesene biçen biçene, herkes yargıç kesilmiş herkes cellat herkes gardiyan, kendine özgü tek bir yan ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bos-ver-be-gilgamis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçinde', 'i-cinde-muammer-erturan-kl6ay', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sol köşesinde gülücüğünün

asılı kalmış hüzün

uzaklarda bir noktaya

takılmış gözleri...

Diyeyim ki yaş elli

de ki altmış...

Hayli fırtına atlatmış

hayli yağmur yemiş

hayli yangınlara gelmiş besbelli

sözümona durulmuş şimdi...

İçinden geçenleri

bir ben bilirim,

içindeyim çünkü...

(''01)', 'Sol köşesinde gülücüğünün asılı kalmış hüzün uzaklarda bir noktaya takılmış gözleri... Diyeyim ki yaş elli de ki altmış... Hayli fırtına atl...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/icinde-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Geldim', 'hos-geldim-muammer-erturan-fmydx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç zamandır olmadığım denli

iyi günümdeyim bugün...

Sihirli bir asa

dokunuvermiş de sanki

rengi gelmiş yüzümün...

Ne gelen var oysa

ne giden 

ne bir haber...

Kendimle olmak sadece

sadece ve sacece

kendimle beraber

yeter de artarmış meğer...

İyi ki gelmiş bugün

iyi ki bugüne gelmişim...

Kendime hoş geldim! ..

(''97)', 'Kaç zamandır olmadığım denli iyi günümdeyim bugün... Sihirli bir asa dokunuvermiş de sanki rengi gelmiş yüzümün... Ne gelen var oysa ne gide...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hos-geldim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buda Benimkisi…', 'buda-benimkisi-hercen-ce-nx40s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adına şiirler yazarak

Doğmayacak çocuğa ad koymaktı benimkisi…

Bir tebessümün adına bin cefaya katlanarak

Yaprakları son baharda yeşil görmek istemekti benimkisi…

Karanlık gecelerime  ışığım olmanı bekleyerek

Doğuştan ama birinden bir çift göz istemekti benimkisi…

Hayatın silsilelerini öğreterek

Dibi delik testiye su doldurmaktı benimkisi…

Çocuksu düşlerimde ummalı aşklar büyüterek

Olmayacak duaya amin demekti benimkisi…

Asi ruhumdaki maviliğim olmanı isteyerek

Ütopyadan öte geçmeyecek hayal kurmaktı benimkisi…

Aslı olan da buya

Herkesi kendim gibi zannederek

Çöplükte anka kuşu aramaktı benimkisi…! !', 'Adına şiirler yazarak Doğmayacak çocuğa ad koymaktı benimkisi… Bir tebessümün adına bin cefaya katlanarak Yaprakları son baharda yeşil görme...', ARRAY['Türk Edebiyatı','Şiir','Hercen Ce']::text[], 8.5, '{"poet":"Hercen Ce","poet_slug":"hercen-ce","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/buda-benimkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmalısın Kerem gibi', 'yanmalisin-kerem-gibi-seref-ozturk-usta-6cqfq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmem kaç gündür yoksun

Yoksun çaresizliğimi anlatmıyor

Anlatmıyor sana hasretin sancısını

Sancısını bilemezsin hasreti tanımadan

Tanımadan deli divane sevdaları 

Sevdalara emek yürek koymadıysan

Koymadıysan dönüşüme imkan

İmkan yok bilemezsin kavruluşumu

Kavruluşumu anlamak için yanmalısın

Yanmalısın Kerem gibi ben yanarken

Yanarken sen Aslı gibi yüreğinden

Yüreğinden yananları nasıl anlamazsın.', 'Bilmem kaç gündür yoksun Yoksun çaresizliğimi anlatmıyor Anlatmıyor sana hasretin sancısını Sancısını bilemezsin hasreti tanımadan Tanımadan...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanmalisin-kerem-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Çıktığın Evde Otur''M''uyorum II', 'senin-ciktigin-evde-otur-m-uyorum-ii-okan-savci-tci0d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanırım 

Gittiğinin ikinci haftasıydı

Demiştim ya

“Senin Çıktığın Evde Oturuyorum”

Artık boğmaya başladı

Seviştiğimiz dört duvar

Haklıymışsın çekip gitmekle

Yarın sabah ben de taşınıyorum..

Okuyunca hatırlarsın

Bir şiir önce

(Ama aylar önce)    

Kilitlemiştim terasın kapısını? 

Açıyorum giderayak

Battaniye ile döşenmiş yer yatağı

Sanki öylece duruyor karşımda

Ve hala

Yokluğuna çalan bir radyo var

O gece

Başını koyduğun yastığın kenarında…

Şimdi son bir kez

Suluyorum çiçeklerini..

Sana neyi çağrıştırır bilmem

Bazı akşamlar iştahımı tıkayıp duruyordu

O yüzden değiştirdim

Mutfağın yanık perdelerini..

Susturduğun türkülerle barıştım da

Uzlaşamadım düşlerimle…

Kapıdan çıkarken soruyorum

“bu evde ne işim vardı? ”

Yüzünü bekleyişime hapseden 

Duvardaki çerçeveye! 

Ama biliyorum 

Kimse konuşturamaz resimleri

O yüzden 

Bir an sen olup 

Cevap veriyorum bana

Yine de anlamıyorum 

Ne demek istediğini…

O günden bugüne inan 

İlk kez 

Ortaçgil çalıyor bu evde

Döndüğünü sanmış olmalı huysuz komşun..

Son bir kez daha vuruyor 

Kalorifer peteğine..

Nerdesin kim bilir? 

Burada olsaydın da 

Anlatsaydım

Giderken yarım bıraktığın 

Kitabın sonunu…

Hani ayak izine dağılmıştı sayfalar

Topladım! 

Meğer öyküde terk edilen adam

Ciğerine işlemiş sevdiğinin soluğunu..

…….

*Kuş olup uçmak var* demiştin ya? 

Meğer *ağaç olup kök salmışım* bu kente…

Niyetim yalan değildi 

Ama gidemedim İstanbul’a..

(Hala bildiğin yerdeyim..

Haa! 

Unutmadan..

Salonun duvarına astığın o notu yaktım

Sen beni koyup gitmiştin

Ben de o evi BİZ’siz bıraktım..)    

Bakıyorum giderayak..

Evin mavi duvarlarına

Sevgilim 

Şimdi o şehirden kalkıp gelsen 

İnan ki 

Aynı sabah hüküm sürüyor Bursa’da…

Sen

Yalnız geçirdiğin bazı gecelerde

Unuturdun kapıyı kilitlemeyi? 

Bilirsin ne çok kızardım..

Ama olur da özleriz diye birbirimizi

Sokakta kalmasın diye düşler? 

Bütün kapıları açık bıraktım…', 'Sanırım  Gittiğinin ikinci haftasıydı Demiştim ya “Senin Çıktığın Evde Oturuyorum” Artık boğmaya başladı Seviştiğimiz dört duvar Haklıymışsı...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/senin-ciktigin-evde-otur-m-uyorum-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Dilimi', 'zaman-dilimi-sevinc-kavuk-dfpx6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yakılan

Ağıtlardaki kabaran yüreklerinin ifadesi

Işık

içlerde asırlardan sevgisi vardı 

Umutlara

Yorgunluğunda bile huzurlu o bir keyfin

Bu zaman dilimi

Değildi

Sevgiler dudaklarda, buseler kelimelerde

Unutulan

Gökyüzü soluk gözlerde

Soğuk

Camda açılan sayfalar

Gerçekler

Yalnızlığı ağlatıyor hala daha

İsabet ettirdiği yersiz saldırılar

Çocuk

Doğa

Ülkeler

Hâlâ akibeti belirsiz bekleyişler

Yer

Gök

Deniz

Hani aşkımın şahidiydiler? 

Yakılan ışık umutlara

Değildi unutulan soğuk gerçekler

14.02.2006

Saat:_____Yarın bırakılacak tarih

_________Bu günden taşınacak 

_________Bir nefes gibi soluyacak

_________Sığdıracak yüreğine bu yükü

_________Bu zaman dilimini, ki adı meçhul', 'Yakılan Ağıtlardaki kabaran yüreklerinin ifadesi Işık içlerde asırlardan sevgisi vardı  Umutlara Yorgunluğunda bile huzurlu o bir keyfin Bu ...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/zaman-dilimi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey beni beşer', 'ey-beni-beser-mikdat-bal-xa0eg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Medet diye sana geldim ey insan

Sorup beni kırma, ey beni beşer! 

Acısanda benim için bir yansan

Görüp beni kırma ey beni beşer! 

Yüzün göster cemalini göreyim

Hüzün göster kemalini göreyim

Özün göster amalini göreyim

Durup beni kırma ey beni beşer! 

Varlık göster söyle bana çaresin

Muhtacım ben ihtiyacım göresin

Eğer varsa Allah için veresin

Sürüp beni kırma ey beni beşer! 

Muhtaç isem senin payın var bunda

Hile yoktur Hakkın verdiği canda

Benim gibi olmaz mısın bir anda

Yorup beni kırma ey beni beşer! 

Uzaklara sürükleme hüzünle

Yakma beni ateşinle közünle

Sorma bana serme beni sözünle

Serip beni kırma ey beni beşer! 

Meşaleni yak da yürü hedefe

İpeklere yama olmaz kadife

Şimşir tarak benzer mi ki sedefe

Sarıp beni kırma ey beni beşer! 

Mikdatî der koyma beni satıha

İnsanlığa okunmasın fatiha

Layık olsun şahsiyetin metihe

Vurup beni kırma ey beni beşer!', 'Medet diye sana geldim ey insan Sorup beni kırma, ey beni beşer!  Acısanda benim için bir yansan Görüp beni kırma ey beni beşer!  Yüzün göst...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ey-beni-beser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir çal zehir', 'bir-cal-zehir-nazan-i-zmirli-lza9a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''kar, 

kurtları dona bıraktı

çöl ,

yılanı  zamana........''

yılan

süründükçe 

uzalıyor, kısalıyor

kızgın  kum altında

bir çal zehir aranıyor

sivri  dilinin   ucunda 

sustum! 

gömlek değiştirme

zamanına ! ! ! ! ! ! ! ! ! ! ! 

14.02.2006-antalya', '''kar,  kurtları dona bıraktı çöl , yılanı  zamana........'' yılan süründükçe  uzalıyor, kısalıyor kızgın  kum altında bir çal zehir aranıyor ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-cal-zehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zerresel Mezbele', 'zerresel-mezbele-ahmet-ferit-cosan-tliv1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gerçek parçalara ayrılamaz.	

				Cibran

Duyuyorum! 

Zelzelesinde kırık dökük bin tansığı,

Gümbür gümbür yaklaşıyor nöbet.

Yıpranmış paçalarında fosforlu imge izleri,

Güneşli şiirlere bulanmışlığından.

Nöbetim! 

Samimiyetine rızayla miskin boynum uzattığım

O parlak giyotin.

Gecem senle daha uzun,

Gecem yine dilim dilim…

Komiğinde tebessüm gezdiririm,

Peyzajındadır dizboyu sırıtkan otları.

Kemiğinde kalsiyum, çeşit fosfat

Ak düşlerisin cümle geçkin bunakların.

Un ufak seninle tüm iskeletler,

Şiddetin sedef serin, hiddetinse en derin…

“Sus”un kelamıma gebedir boş kağıtlarda,

Saç baş yoldurur, simam darmadağın, 

Ruhum  şeytantersi, seninle yerle yeksan.

Kevgire çevirir  hatıralar dirayet perdesini,

Delik deşik cidarından hücum eyler anılarım….

Tek kullanımlık varlığınla lal demlerin

Atıl, büzüşken, evcil hayvanısın.

Olanca tazyikinle atıl şehvete, 

Sen  tuz-buz eden fırtına! 

Paramparça bulutlar da toplarsın

Gök mavi yarinin kavruk koynunda.

Onu lime lime bırak,

O acınası yırtık pırtık,

Nazarınla alemine damlar tenindeki kamusal pembelik…

Baştan ayağa dingin bir gözyaşıyım, devcileyin…Titreşirim hüzünlü iç çekişlerin acı buğusu yüzeyime dek eriştiğinde…Duman duman acı, katmerim katran…Sözümdür boyutsuzluk, sessizliğin noktasal merkezinde…Bütünüm, tümüm, yeterimce tekim…Darmanduman yekun gerisi…Ardımda, Masivanın  bölük pörçük öbeklerle, rengarenk sanrısı…Önümde sabahın kan kızılı fecri…..', 'Gerçek parçalara ayrılamaz.	 				Cibran Duyuyorum!  Zelzelesinde kırık dökük bin tansığı, Gümbür gümbür yaklaşıyor nöbet. Yıpranmış paçaları...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/zerresel-mezbele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tel tel', 'tel-tel-nazan-i-zmirli-zzf7a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir ak daha 

tel tel saçıma

bir çizgi daha 

alın yazıma

gamzeler küçülüyor

günler  günlerde

halka halka

kavuşma arzusu artıyor

eskitemediğim  yıllara

içinde unutamadığım 

sen varsın ya....

14.02.2006-antalya', 'bir ak daha  tel tel saçıma bir çizgi daha  alın yazıma gamzeler küçülüyor günler  günlerde halka halka kavuşma arzusu artıyor eskitemediğim...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tel-tel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum boşlukta', 'ruhum-boslukta-nazan-i-zmirli-5ze69', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'düşün! 

ruhum

boşlukta

bir  kelebeğin

kanat  çırpışlarına

tutunmakta

yaşamla

yaşamamak

arasında

o ince noktada

14.02.2006-antalya', 'düşün!  ruhum boşlukta bir  kelebeğin kanat  çırpışlarına tutunmakta yaşamla yaşamamak arasında o ince noktada 14.02.2006-antalya...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ruhum-boslukta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin Kara Kışı', 'hasretin-kara-kisi-murat-demir-u206e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamak ne zor imiş dünya denen kayıkta

Havlu attırdı bana üç günlük ayrılıkta

Ne olur tanrım beni ne olur süründürde

O’nu tekrar görmeden beni öldürme, yıkta

Gecelerim ermeden günümün şafağına

Hasret acısı çöker gözlerimin ağına

Ne olur tanrım beni ne olur süründürde

Girmeme engel olma yarin barınağına

Onsuz geçen günlerim dokunuyor arıma

Hasretin karakışı vuruyor baharıma

Ne olur tanrım beni ne olur süründürde

Paralayıpta atma onsuzluğun harına', 'Yaşamak ne zor imiş dünya denen kayıkta Havlu attırdı bana üç günlük ayrılıkta Ne olur tanrım beni ne olur süründürde O’nu tekrar görmeden b...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasretin-kara-kisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Aşkımıza Hayran Kalsın', 'herkes-askimiza-hayran-kalsin-huseyin-erdogan-3tck5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözlerim buğulandı dün gece

sensizliğim aklıma düşünce

bir üşümek aldı ki bedenimi

hasretinin hüznü sardı her yerimi

ben de fotoğraflarında tuttum ellerini

iliklerime kadar sıcacık ısıttın beni

bilmem ki! sen ne yapıyorsun şu anda

belki rengarenk bir düş bahçesi var odanda

belki de derin bir uykudasın yatağında

vallahi havalara zıplardım göklere çıkardım

bilsem ki benimle dopdolusun rüyanda

gün batıp da akşam olunca buralarda

çiçekler bile boynunu bükerler yokluğuna

bil ki sen yaz mevsiminde çıkıp gelsen de

İstanbul''da bahar açacak kırlarda bahçelerde

senin adın yankılanacak dağlarda taşlarda her yerde

ne olursun şiirim geç kalıp da beni düşürme derde

ömrümüzce bu muhteşem aşkımıza çekilmesin perde

sakın ne sana ne de bana sorulsun şairin nerde şiirin nerde? 

seninle birlikte yaşayalım mahşerde bile tek bedende

herkes aşkımıza hayran kalsın dolaşsın dursun dilden dile

                                                                    14.02.2006

                                                                Hüseyin Erdoğan', 'gözlerim buğulandı dün gece sensizliğim aklıma düşünce bir üşümek aldı ki bedenimi hasretinin hüznü sardı her yerimi ben de fotoğraflarında ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/herkes-askimiza-hayran-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim bilir? ? ? ?', 'kim-bilir-nazan-i-zmirli-3zq1u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kim bilir? ? ? ? 

................sensizliğimi

.............................gecelere 

.......................................vurulan

................................................kilitten 

........................................................başka.

14.02.2006-antalya', 'kim bilir? ? ? ?  ................sensizliğimi .............................gecelere  .......................................vurulan ..........', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kim-bilir-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitanem', 'bitanem-omer-kucukkaya-x9xd1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİTANEM

Gözlerine bakmadan uyuduğum kaç gün gördün ki? 

Seni sevmeden içime çektiğim kaç soluk? 

Mutluluğa sensiz güzel dediğim hangi gün? 

Sensiz anlam verdiğim hangi yaşanmışlık? 

Kelimelere ne zaman sensizlikten başkan anlam yükledim? 

Hangi an zamanı sensiz düşledim? 

Kime senden bahsetmeden laf ettiğimi gördün? 

Kim veya ne benim için senden önemli olduki bugüne kadar? 

Bugün 14 Şubat! ...

Unuttum mu ki hiç sevgini bugün unutayım? 

Hiç seni sevmediğim an oldu mu? 

Param olmayabilir ama iki kelimem hep kalbimden, kalbine...

Anlamanı beklemiyorum beni? 

Zaten bir değilmiyiz ki? 

Gözlerine bakamadığında çektiğin acıyı? 

Ben sesini her duyamayışımda çekmiyormuyum ki? 

O kadar soru işareti oldu ki bugün,

Yüreğim sana o kadar doldu ki bugün,

Neyi niçin neden bilmeden,

Sevdim seni tam 1185 gün...

Bugün seninle olduğumuzun 1185 ininci günü...

Her an her saat seninle dolu olduğum,

Her an senin olduğum,

Seni Seviyorum', 'BİTANEM Gözlerine bakmadan uyuduğum kaç gün gördün ki?  Seni sevmeden içime çektiğim kaç soluk?  Mutluluğa sensiz güzel dediğim hangi gün?  ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Küçükkaya']::text[], 8.5, '{"poet":"Ömer Küçükkaya","poet_slug":"omer-kucukkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bitanem-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz''in Kıyısında', 'karadeniz-in-kiyisinda-yusuf-onder-bahceci-c6cz3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karadeniz''in Kıyısında, Karadeniz''e bakıyorum,

Evvel sigara içmezdim şimdi sigara yakıyorum,

Şimdi yanımda yoksun sen Allah''a yakarıyorum,

Karadeniz''in Kıyısında, Karadeniz''e bakıyorum.

Karadeniz''in Kıyısında, Karadeniz''e bakıyorum.

Kara gözlerini düşünüp hep hayallere dalıyorum,

Çekip gittin kaderinle ben buna dayanamıyorum,

Karadeniz''in Kıyısında, Karadeniz''e bakıyorum.

Sen yoksun buralarda, bana ne, göller ve deniz,

Buralar da kalırsam fazlaca sürmez gelir bir kriz,

Baktığım ve gezdiğim yerlerde hep senden bir iz,

Karadeniz''in Kıyısında, Karadeniz''e bakıyorum.

Gözüme daha kara görünüyor dalgalı Karadeniz,

Şimdi her tarafım dört duvar, her yer bana dehliz,

Aman Allah''ım ne kadarda dalgalıymış Karadeniz,

Karadeniz''in Kıyısında, Karadeniz''e bakıyorum.', 'Karadeniz''in Kıyısında, Karadeniz''e bakıyorum, Evvel sigara içmezdim şimdi sigara yakıyorum, Şimdi yanımda yoksun sen Allah''a yakarıyorum, K...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karadeniz-in-kiyisinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün 14 ŞUBAT', 'bugun-14-subat-omer-kucukkaya-0a09r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün 14 ŞUBAT

Yaşam bugün bir başka güzel geliyor bana....

Belki bugün özel olduğundandır? 

Belki de; tüm kalpler aynı anda çarptığından,

Belki de bugün 14 Şubat olduğundan....

Nedenini tarif edemediğim bu duygu sardı her yanımı...

Kim bilir belkide bugün 14 Şubat olduğundan....

Yüreğim bir başka çarpıyor,

Belki de; tüm kalpler aynı anda çarptığından...

Yalnızlığa son merhaba dediğim gün, bugün.

Sevdalara ilk merhaba dediğim gün, bugün.

Gözlerinin içine gömüldüğüm,

Gözlerine öldüğüm gün bugün! 

Hayatın yosunlu basamaklarından kaydığım,

Çamurlu sokaklarda top koşturduğum,

Üniversite yıllarında ilk aşık olduğum,

Hayatımın anlamına özgürlük verdiğim gün, bugün.

Kim bilir yada kim bilebilir...

Nerede nasıl niye sevmek istediğini,

Yada kim hangi kelimeyle dile getirebilir? 

Sevdiğinin değerini....

Yıpranmış aşkların yenilendiği gün bugün,

Yüreksizlerin, yüreklendiği gün bugün,

Bugün her kalbin sevgiyle dolduğu gün,

Bugün gözlerin mutluluk saçtığı gün...

52 Hafta 365 gün 6 saat aşk başkadır....

Her 14 Şubatta sevdiğinle olmak bambaşka! 

Sadece bir demet gül ve 2 kelime

14 Şubatta en büyük hediye...

Kutlu olsun tüm aşkı anlatan serçeler,

Mutlu olsun tüm açan çiçekler,

Sevinsin bütün gönüller...

Bugün 14 Şubat Sevgililer Günü...

Ömer KÜÇÜKKAYA

14 ŞUBAT 2006

08:00', 'Bugün 14 ŞUBAT Yaşam bugün bir başka güzel geliyor bana.... Belki bugün özel olduğundandır?  Belki de; tüm kalpler aynı anda çarptığından, B...', ARRAY['Türk Edebiyatı','Şiir','Ömer Küçükkaya']::text[], 8.5, '{"poet":"Ömer Küçükkaya","poet_slug":"omer-kucukkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bugun-14-subat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Az Kaldı', 'az-kaldi-ozay-karakus-05r8a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'acılarımız bitecek 

gözyaşımız dinecek 

bu beden sana dönecek 

kavuşmamıza az kaldı 

kötü günlerimiz bitecek 

umutlarımız yeşerecek 

dertlerimiz sona erecek 

buluşmamıza az kaldı 

renk gelecek solan gülüme 

yazlar kamp kuracak gönlüme 

beraber gideceğiz ölüme 

koşacağız az kaldı 

bir yeşil bahardan 

baharda açan goncadan 

sevginin sevdalı pınarından 

taşacağız az kaldı

------------', 'acılarımız bitecek  gözyaşımız dinecek  bu beden sana dönecek  kavuşmamıza az kaldı  kötü günlerimiz bitecek  umutlarımız yeşerecek  dertler...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/az-kaldi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Söylemedim', 'sana-soylemedim-ozay-karakus-not6b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'içerimde yara açtılar 

yarama tuz bastılar 

ellerim koynumda astılar 

sen üzülme yarim diye 

sana bir şey söylemedim 

avucuma çivi çaktılar 

kollarıma zincir taktılar 

üzerime yağ döküp yaktılar 

sen üzülme yarim diye 

sana bir şey söylemedim 

yerden yere attılar 

üç kuruşa canım sattılar 

aşıma zehir kattılar 

sen üzülme yarim diye 

sana bir şey söylemedim 

yollarıma engel çıktılar 

bağrıma kurşun sıktılar 

koca bir çınarı yıktılar 

sen üzülme yarim diye 

sana bir şey söylemedim', 'içerimde yara açtılar  yarama tuz bastılar  ellerim koynumda astılar  sen üzülme yarim diye  sana bir şey söylemedim  avucuma çivi çaktılar ...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-soylemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinçli bilinmez bir ======= yol (-1-)', 'bilincli-bilinmez-bir-yol-1-nazan-i-zmirli-4zww3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Farklı   yerler,  farklı  yönler,  farklı  keşiflerin  bilinçli  bilinmez  bir  yolculuğun 

heyecanı  sarar  yüreğinizi  benliğinizi.

İşte  yine   böyle   bir   etkinliğin  hazırlığı   içersinde  zirvelerdeki    özgürlüğü 

yaşamaya   başlarsınız.

Kalbiniz    terkedecek   gibidir   sizi,   yetişmeye    çalıştırırsınız   bedeninizi onun   hızına. An   an bir   kuşun   kanadı   olursunuz    pır  pır  eden,  her

mevsim  adı  değişen  özgürlüğe  yol  alan.....

Uyku   tutmaz   şafakla   kalkarsınız,  son   bir   kez   daha göz  gezdirirsiniz,

kim  kimin  kahrını  çekecek  diye  sorduğunuz  boyunuzca   çantanıza........

Cesur  hırsız  gibi  sırtlanırsınız  can  yoldaşınızı  sessiz,  sessiz   ama  koşar

adımlarla süzülürsünüz  alaca  karanlıkta.......... günün ilk ışıklarına.................

Tekerlekler  dönüp,  kilometreler  katedildikçe,  buharlaşan camlardan  akıp giden  geçmişiniz  gibi  hızlı  hızlı  gelip  geçen  yaşamı  izlersiniz.

Elleriniz yüzünüze uzanır aniden, kendinize dokunmak  varlığınızı  hissetmek

ve  ne  mutlu  ne mutlu  şu an  bu  yolculuktayım  dersiniz.Ardından................

derin bir  iç çekiş  ve  içinizdeki   sessizlikle    bilinmez   bir  yol.........................uzanır  altın  sarısı  buğdayların  sonsuzluğunda............

Birde tabloyu oluşturan, uçsuz  bucaksız  üzüm  bağları ise,  yeşille  kırmızının,

turuncu   ile   sarının,  kahverengi   hazalların   arasında    sonbahar    hüznünü

yaşarken;  kış   ağaçlarının   zümrüt   yeşili   yaprakları  bir  tükenişin ardından

yeniden  doğuşu   anlatır  gibidir.

İçinizdeki   burgu   burgu   hüzünler  dizilirken   boğazınıza,   bu   manzaradan 

sonra, aranızdaki   buğulu   cam   kaybolur, hüzün  yok olur  anında............

Tekrarı   olmayacakmış   gibi,  olsada   farklı   olacağını   bildiğinizden   için,

gözünüzü  kırpmadan   sindirmek  istersiniz  her anı.....bazen  pes eder göz kapakları   ve  o  kısacık  şekerlemenin  tadı...........bozulur  göçmen  kuşların

sıcağa  doğru  süzülüşlerinin şahitliğinde.....

Uçsuz    bucaksız    ovalar,    geçmişin    umutları   gibi   arkamızda   kalınca,

yollar   daralmaya   engebeli   olmaya   ve   de  yalçın   kayaların     arasında kıvrılmaya    başlar........korkudan   çok     heyecan   doruk   noktaya   ulaşır, 

bir  avuç   kadar     ama  cesur    yüreğinizde.

Vadideki  çay   boyunca,    sonbaharla   kavgasını  veren  söğütlerin  boyun eğişlerini   izlerken,   bir  yaprak   bir  yaprak   daha   düşürmek  korkusunu hissedersiniz  kavak yellerinde....ve   yerli   kuşların    türkülerindeki    çağrı   getirir    sizi  kendinize.....

Ne kadar  hoşnut  olmasanızda,  kaptanın  kendini ayık tutmak için  dinlediği 

radyodan   gelen  tınıya  arada  kulak  kabartırsınız.....dilek tutarsınız gizlice....

''her  şeye  rağmen  yaşamak  güzel......'' diye......

Kayalıkların   arasında   sıklıkla   rastlanılan   mezar  taşları,  bir  doğuşu  bin

ölüşü  anlatır.....anlatır.....anlatır........yaşama   daha   çok   sarılma     arzusu 

sarar   içinizi........çok  kısa belli ki..............sizin  için, saliselerin  değeri  bir 

nefes   bin    tebessümde  gizlenir.............................hissedilebilen...............

Bilinçli bilinmez bir ============yolun yolcusu olursunuz vazgeçilemeyen.

14.02.2006-antalya-Doğu toroslar

''bolkar dağlarına ulaşmak üzere çıkılan 

biliçli bilinmez bir yolculuktan duygusal

kesitler.-1-''', 'Farklı   yerler,  farklı  yönler,  farklı  keşiflerin  bilinçli  bilinmez  bir  yolculuğun  heyecanı  sarar  yüreğinizi  benliğinizi. İşte  ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bilincli-bilinmez-bir--yol-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramıyorum-"siz hiç ay aşığında ağladınız mı" Kitabından', 'aramiyorum-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-xtdid', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ümitsiz değilim sineler çorak

Gençliğim yanıyor göremiyorum

Hak hukuk arıyor elinde orak

Kaldırmış çekici soramıyorum 

Bakışlar ümitsiz bakışlar kurak

Ben buna bir akıl veremiyorum

Hikmet-i sual mi tövbelerim hak

Sebepten sebebi aramıyorum', 'Ümitsiz değilim sineler çorak Gençliğim yanıyor göremiyorum Hak hukuk arıyor elinde orak Kaldırmış çekici soramıyorum  Bakışlar ümitsiz bakı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/firak-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-serif-koyan-c54uv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbul

Somutça kıvrılarak,

Teninin sıcaklığını hissederken özlemek seni! 

Deniz dibi akıntısı gözyaşlarım.

Anadolu yakası ayağı kırmızı ışıklı Boğaziçi,

Rumeli’nin pembe elmas hisarları,

Korkuluk hisleriyle birlikte memleket kumruları,

Uzun oturmuş karanlık yakamozlar…..

Naralar demleniyor ıslak sabahların,

Konuyor,gözlerimin üstünde! 

Beyaz çırpar kanat donukluğum.

Kazanılmış terk etmeler,

Her şeyi ile aynı olup benzemeyen birbirine,! 

Kırık çizgili uzay hislerim.

Koyu sessizliği bozan,

Zaman nehrinin ışıltısı! 

Haliç gibi kutsal kokar yürüyüşlerim! 

Unuttuğum ayak izleri…..

Geri döner gibi gitmektedir, 

Aydınlık sonralarım

Telefondaki sesim kalsın! 

Bunu bile ikircikli isterim.

Hızlıca yol alan,

Sadece! Bedenim.

Elveda! , enson memleketim.

                        

ŞERİF KÖYAN

10.04.1991', 'İstanbul Somutça kıvrılarak, Teninin sıcaklığını hissederken özlemek seni!  Deniz dibi akıntısı gözyaşlarım. Anadolu yakası ayağı kırmızı ış...', ARRAY['Türk Edebiyatı','Şiir','Şerif Köyan']::text[], 8.5, '{"poet":"Şerif Köyan","poet_slug":"serif-koyan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/istanbul-387-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma Sakın', 'sanma-sakin-ozay-karakus-6aycg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'mevlam her güzelliği vermiş 

benden güzel kul varmı dermiş 

HAKkın kullarına dudak bükermiş 

güzelliğin sende kalır sanma sakın 

duydumki çok tatlı şekermiş dilin 

bir şahesermiş ince belin 

mis kokarmış senin nefesin 

kara kaşına yanarlar sanma senin 

beyaza dönerse siyah saçların 

ölüm dediğin bilki çok yakın 

imam derse götürün kabre atın 

bu dünya senin oldu sanma sakın 

söylerler ki pamuk gibi ellerin 

görenleri yandırırmış gözlerin 

gidiyorsun işte duyulmazki sözlerin 

bu can bu bedende durur sanma sakın 

çekmemiş olaki dünya zahmeti 

bilmemiş belliki HAKtan yana rahmeti 

Azrail gelir ister emaneti 

ela gözüne yanarlar sanma senin', 'mevlam her güzelliği vermiş  benden güzel kul varmı dermiş  HAKkın kullarına dudak bükermiş  güzelliğin sende kalır sanma sakın  duydumki ço...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sanma-sakin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Kimiz', 'biz-kimiz-yusuf-onder-bahceci-plhiq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni sakın yanlış anlamayın ha,

Ben kendimi övmüyorum daha,

Ben Allah''ın yarattığı, aciz kulu,

O Yiğit Babası Mehmet''in oğlu.

Bu Dünya''de neler gördük biz,

Kendini övenleri çok iyi biliriz,

Sen kimsin be kardeşim keriz,

Övünenleri çokca gördük biz.

Havada uçsan, karada kaçsan,

Güzel güzel belagat parçalasan,

Eşi, dostu bile hiç tanımazsan,

Biz kimiz ki Allah''ın yarattığı kul. 

Biz kimiz ki Allah''ın yarattığı kul,

Doğduğunda elinde yoktu, pul,

Nerede Allah adı duysan sokul,

Biz kimiz ki Allah''ın yarattığı kul.

Önce kendime diyorum...', 'Beni sakın yanlış anlamayın ha, Ben kendimi övmüyorum daha, Ben Allah''ın yarattığı, aciz kulu, O Yiğit Babası Mehmet''in oğlu. Bu Dünya''de ne...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biz-kimiz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel ve Hüküm Sür', 'gel-ve-hukum-sur-banu-savas-jqpfh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gel ve hüküm sür

mülkündür yoksulluğum

kuşları olmayan ülke

nehri olmayan ormanlar

mülkündür

adımımla başlayan topraklar

sütü olmayan meme

kısır kadın

herkesten sakındığım yuva

tebaandır yalnızlığım

ondan üreyen sırtlanlar

kuzgunlar, yılanlar

tebaandır

akrep sokmuş ruh

yeşile dönmüş ten

unutulmuş yazgı

tüm bu kamaşma

aldattık kendimizi yıllarca

zehre dönmüş us

kendini içeri akıta akıta

ve ben haklı değilim artık

bilindiğim hiçbir diyarda

tacındır

etteki yara

ekmekteki kurt

tacındır

bir türlü doğmayan bu çocuk

öyle kararlı ki karnımdaki ağırlık

sanki doğdu doğacak

evrenin körlüğü burada toplanacak

oysa küçük taşıdır ölmenin 

yaşattığım avucumda tuta tuta 

gel ve hüküm sür

koynumdaki boşlukta…', 'gel ve hüküm sür mülkündür yoksulluğum kuşları olmayan ülke nehri olmayan ormanlar mülkündür adımımla başlayan topraklar sütü olmayan meme k...', ARRAY['Türk Edebiyatı','Şiir','Banu Savaş']::text[], 8.5, '{"poet":"Banu Savaş","poet_slug":"banu-savas","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gel-ve-hukum-sur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Var Aramızda', 'kim-var-aramizda-ozay-karakus-iqj1i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'geri dön gitme sevgilim 

tutmuyor ellerim 

olmayınca sen yanımda 

tutuluyor dilim 

ben senden ayrı kalınca 

çarpmıyor yüreğim 

bir an sensiz olunca

yok yaşama gereğim

kalp bağı var aramızda 

aşk ağı var aramızda 

çıkıp gitsin kim varsa aramızda 

olmasın kimse yanımızda 

sen gidince ben yaşamam 

yokluğuna dayanamam 

sen gelince gülerim 

bir daha ağlamam 

çocuk gibi sevinirim 

yerimde duramam 

yanımdayken rahat ederim 

yüreğimi dağlamam 

su sızmazdı aramızdan 

sır çıkmazdı aramızdan 

zalimler girip çıktı aramızdan 

anlamadılar sevdamızdan', 'geri dön gitme sevgilim  tutmuyor ellerim  olmayınca sen yanımda  tutuluyor dilim  ben senden ayrı kalınca  çarpmıyor yüreğim  bir an sensiz...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kim-var-aramizda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyse ki, Yapısı Var ''Aşk''ın...', 'neyse-ki-yapisi-var-ask-in-aynur-uluc-eyono', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmek, hem de öyle çok sevmek ki; dünyanın öbür ucunda olsa dahi, sevdiğinin kokusunu hissetmek. Öyle saf sevmek ki; seninle olmasa bile onun mutluluğunu istemek açıkça.`Seni seviyorum` demese de şüphe etmemek sevdiğinden, seni düşündüğünden.

İşte böylesine özel, böylesine güzel bir şey `aşk`. Bahanelere ihtiyacı yok. Kendi dışındaki dünyadan ona hazır sunulan özel günlere ihtiyaç duymaz aslında. Çünkü o zaten kendisi, karşılaştığı her şeyi kendine yontan, etrafındaki nesneleri bile sevdiğini anımsatmaya bahane kılma ihtiyacında bir yapıya sahip.

O iki kişi arasında kurulu kapalı dünyasında biriktirir, her güzelliği ve acıyı. Kavgasının tadı kendinde, sevişmesinin tadı kendinde yine. Dünyadaki bu kadar çok aşk tarifine inat, anarşist bir yapısı var öte yandan. İki kişi arasında dönen ayrı bir kurgusu, kendisine has dili. 

Sezgilerin konuştuğu bir dil bu. Cümle anlamlarının neredeyse söylenene birebir denk gelmediği bir açıklıkta seyreden. Kısa cümlelerde uzun anlamlar saklayan, uzun cümlelerinse bazen hiç bir şey anlatmadığı özel ve farklı bir durum. Tüm bunlara karşın bu kadar sağlam mı peki yapısı? Pamuk ipliğine bağlı değil mi, bazen de bozulması dengenin? Etkilenime en açık, karışıvermeye en uygun yumak gibi değil mi, bir yanıyla da? Kimyasına `matematik` desek; tümdengelimle değil, tümevarımla işliyor mekanizması. Hal böyle olunca; değil diğer insanların algıladığı şekle uygunlukla bir güne hapsolması, oradan anlamlanması, gerektiğinde tek bir `dakika`yı `yıl`a çeviren bir burgusu var.

Sevgililer gününün çıkışına baktığımızda ise; 270 yılında Roma''da imparatorluk yapan  Aziz Valentine`i, tanrı ve tanrıçaların kraliçesi olan Juno`ya duyulan saygıdan ötürü yapılan tatili ve ertesi günü başlayan Lupercalia bayramını anımsıyoruz ki bu bayram, halkın genç nüfusu için çok önemliymiş o tarihlerde. Çünkü yaşantıları sınırlandırılmış gençler, sadece bu bayram süresince bile olsa birbirlerinin partneri oluyorlar ve bu birliktelikler genellikle bayram sonrasında evlilikle sonuçlanıyormuş. İmparator II. Cladius içinse en büyük sorun, ordusunda savaşacak asker bulamamak. Ona göre bu durumun tek sebebi, Roma`lı erkeklerin aşklarını ve ailelerini bırakmak istememeleri imiş. İşte bu yüzden de Roma`daki tüm nişan ve evlilikleri kaldırmış.

Aziz Valentine ise, bu imparatorun hükümdarlığı zamanında yaşayan bir papaz. Aziz Marius ile birlikte II. Cladius`un yasağına rağmen gizlice çiftleri evlendirmeye devam etmiş. II. Cladius da Valentine`i emirlerine uymadığı ve kendisine baş kaldırdığı için tutuklatıp öldürtmüş. Bu olaydan ikiyüzyirmialtı yıl sonra 496`da Papa Gelasius, Aziz Valentine`i onurlandırmak için on dört şubat tarihini sevgililer günü olarak belirlemiş. Ve Sevgililer günü, 1800`lü yıllardan sonra Esther Howland`ın ilk kartını yollamasından bu yana, günümüzde daha çok sayıda insanın kutladığı toplumsal bir olay haline gelmiş.

O günden sonra sevgiliye `Benim Valentine`im olur musun? ` diye yazan özel kartlar göndermek söz konusu olmuş. Gönderilen bu ilk kartla birlikte günün yüklendiği misyon, sevgiyi dünyaya hatırlatmaya bahane bir güzellik aslında. İnsanların birbirine kavram olarak `aşk`ın altını çizdiği kartlar gönderip `sevgili olma hali`ni kutladığı bir olgu.

Mevcut tüketime dayalı sistem, elindeki her konuyu malzeme olarak görüp, onları kendi amacına yönelik fırsatlara dönüştürdüğü gibi `sevgililer günü` de bu paydadan nasibini aldı zamanla elbette. Paha girdi işin içine. Artık bir hediye almak oldu, söz konusu olan. Erkek ve kadının o güne kadar toplum içinde konumlandığı algılama biçimlerinden bakıldı, konuya da. Bizim toplumumuzda ki bakışa göre; öncelikle erkek, bu günü unutmamalıydı ve kadına hediye almalıydı. Başka bir deyişle; mevcut olmayan bir sorunu önce var edip, sonra çözmek oldu, işin aldığı son hâl. İlişkilerde yerini gittikçe daha sağlam alan `sevgililer günü gerilimi` ile doğru orantılı olarak, güllerin de fiyatı arttı hâliyle. O gün sevgiliye sevgiyi söylemek farz oldu, söylememek sorun. Zorla oldu güzellik. Yalın kalma çabasında olanı da gölgeledi bu durum. Amaçlar unutulup araçlar konuşulur oldu, her yerde. Ancak bu noktada şaşılacak bir durum da yok. Perşembenin gelişi çarşambadan belliydi, şartlara bakılınca. 

Sistem, elbette yapısı gereği elindeki tüm varlıkları, olguları tüketime yöneltmek zorunda. Ve tam da bu noktada `aşk` da yine yapısı gereği direnmek zorunda, kendine dayatma biçimlere...

Aynur Uluç

Evrensel Gazetesi

15 02 2010', 'Sevmek, hem de öyle çok sevmek ki; dünyanın öbür ucunda olsa dahi, sevdiğinin kokusunu hissetmek. Öyle saf sevmek ki; seninle olmasa bile on...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neyse-ki-yapisi-var-ask-in-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Oldu Aşk`a', 'ne-oldu-ask-a-ozay-karakus-72ad9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen gülümün goncası 

sen kalbimin sancısı 

sen aşkın yalancısı 

ihanet ettin bana 

ben derdin çilesi 

ben sevenin sevgisi 

ben alnının çizgisi 

canım feda ettim sana 

biz neler söylemiştik 

biz yeminler etmiştik 

biz sevenler demiştik 

ne oldu söyle aşka', 'sen gülümün goncası  sen kalbimin sancısı  sen aşkın yalancısı  ihanet ettin bana  ben derdin çilesi  ben sevenin sevgisi  ben alnının çizgi...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-oldu-ask-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonuna Kadar', 'sonuna-kadar-ozay-karakus-fu52m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aman hasretim dağlarda 

gözyaşım filizlendi bağlarda 

daha en güzel çağlarda 

aşka düştü yüreğim ağlarda 

kimse duymaz sesimi 

haykırsam sonuna kadar 

kimse bilmez halimi 

anlatsam sonuna kadar 

aman daha çocuk yaşımda 

ak düştü saçlarıma 

binbir türlü bela başımda 

bırakmadı hep yakamda 

unuttum artık adımı 

bulamadım ben tadımı 

kırdılar kolum kanadımı 

ezdiler sonuna kadar', 'aman hasretim dağlarda  gözyaşım filizlendi bağlarda  daha en güzel çağlarda  aşka düştü yüreğim ağlarda  kimse duymaz sesimi  haykırsam son...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonuna-kadar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahı Boynuna', 'gunahi-boynuna-ozay-karakus-nlc6v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yüreğimdeki acıların 

bedenimdeki sancıların 

gözümdeki yaşların 

sebebi sensen günahı boynuna 

bu beyaz saçların 

hüzünlü bakışların 

umutsuz yalvarışların 

sebebi sensen günahı boynuna 

tutmayan ellerimim 

düğümlenen sözlerimin 

karanlıktaki gözlerimin 

sebebi sensen günahı boynuna 

ıstırapla geçen günlerin 

faydası olmayan dünlerin 

harap olmuş yüreğin 

sebebi sensen günahı boynuna', 'yüreğimdeki acıların  bedenimdeki sancıların  gözümdeki yaşların  sebebi sensen günahı boynuna  bu beyaz saçların  hüzünlü bakışların  umuts...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunahi-boynuna-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğin Yanar', 'sevdigin-yanar-ozay-karakus-d3sn5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uzatma elini bana 

ellerin yanar 

bana söz atma 

dillerin yanar 

bakma şu yüze 

yüreğin yanar 

nazar değer o göze 

gözlerin yanar 

bir anlatsam derdimi 

akan kanın donar 

ben kaybetsem kendimi 

inan canın yanar 

boşa teselli verme 

sözlerin yanar 

sen ellere gitme 

sevdiğin yanar 

öpücükler gönderme 

buselerin yanar 

aşk zehrin ikram etme 

kaselerin yanar

------------', 'uzatma elini bana  ellerin yanar  bana söz atma  dillerin yanar  bakma şu yüze  yüreğin yanar  nazar değer o göze  gözlerin yanar  bir anlat...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdigin-yanar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerdan Gibi', 'gerdan-gibi-ozay-karakus-0i3ig', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gerdan gibi tak boynuna 

çocuk gibi al koynuna 

varsam mezarın başına 

vur öldür koy toprağa 

sevdi öldü yazsınlar taşına 

toplanmasın kimse başına 

bilki benim yüreğim 

senin için çarpar atar 

şu gönlümde sevdan 

sımsıcacık durur yatar 

sevmiyorsan de beni yorma 

gönlüm sende hayal kurma 

sorma bana bir şey sorma 

vuracaksan vur hiç durma 

arama beni ister arama 

sarma bağrına sarma', 'gerdan gibi tak boynuna  çocuk gibi al koynuna  varsam mezarın başına  vur öldür koy toprağa  sevdi öldü yazsınlar taşına  toplanmasın kimse...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gerdan-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Çıkmış Sensizliğimin', 'adi-cikmis-sensizligimin-tulay-sustam-o3uky', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.I.

salkım saçak örgüden

kaçan bir çift göz olayım

peşin sıra iki düz, bir ters gideyim

yeter ki! ...

yokluğunu düğümleme boğazıma

..II..

rüzgâr; 

kuru bir tene dokunmaya görsün

yalnızlığın ıslığı çalar

gecenin arka sokaklarında

ve ben üzerime seni çekip

ucunu bırakırım senli düşlerimin

.

sevgi(li)     siz günüm kutlu olsun...

.', '.I. salkım saçak örgüden kaçan bir çift göz olayım peşin sıra iki düz, bir ters gideyim yeter ki! ... yokluğunu düğümleme boğazıma ..II.. rü...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adi-cikmis-sensizligimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmadı', 'kalmadi-ozay-karakus-6eey3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şu gönlümü satacak 

başka eli tutacak 

acı derdi yutacak 

gücüm kalmadı 

damla damla akacak 

pınarları kuruyacak 

artık sana bakacak 

gözüm kalmadı 

gerçekleri gösterecek 

seni yola getirecek 

artık sana diyecek 

sözüm kalmadı 

hep mutlu olacak 

neşe ile dolacak 

artık sana bakacak 

yüzüm kalmadı 

ne gururum ne gençliğim 

ne onurum nede benliğim 

artık değersiz biriyim 

özüm kalmadı 

ALLAH seni yakacak 

azaplara boğacak 

artık senden alacak 

öcüm kalmadı', 'şu gönlümü satacak  başka eli tutacak  acı derdi yutacak  gücüm kalmadı  damla damla akacak  pınarları kuruyacak  artık sana bakacak  gözüm ...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kalmadi-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Dermisin Hâlâ', 'sevdim-dermisin-h-l-derin-oger-u2vp6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kıvılcım kıvılcım

düşlerimi saran kızıl sevda

rüzgâr rüzgâr yayılır dolardın ruhuma

ateşini ışık sanıp aşka

alev alev düşerdim yollarına

sıcağını hayal edinip

çıtırtılarının sesini nabzımda dinlerdim

ve sen benim hergün yeniden doğan yaz güneşim

ben senin o harlı hallerini sevmiştim

şimdi parlak korlar üstünde küllerin güzel', 'kıvılcım kıvılcım düşlerimi saran kızıl sevda rüzgâr rüzgâr yayılır dolardın ruhuma ateşini ışık sanıp aşka alev alev düşerdim yollarına sıc...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevdim-dermisin-hala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşunamı Dizeyim', 'kursunami-dizeyim-ozay-karakus-irtlo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cesaret edip topladım bir an kendimi 

Söyledim sana seni çok sevdiğimi 

Olmaz dedin yapamayız dedin 

Senle biz imkansız dedin 

Oysa bilmedin bu can sensiz 

Olmaz gülüm yaşayamaz 

Sense bilmedin bu kalp sessiz 

Atmaz gülüm çarpamaz 

Kurşuna mı dizeyim kastedeyim bu cana 

Yoksa götüreyim asayımmı dar ağacına 

söyle nasıl kıyayım ben bana 

sensiz tükenirim anlasana', 'Cesaret edip topladım bir an kendimi  Söyledim sana seni çok sevdiğimi  Olmaz dedin yapamayız dedin  Senle biz imkansız dedin  Oysa bilmedin...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kursunami-dizeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim yetmedi', 'yuregim-yetmedi-tevfik-karinca-yo1gm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adını ben koydum umutsuzlukların

Sende kalsın istemediğim yalnızlıkların

yüklendikçe yüklendim kendime

İstedim ki bir sıcaklık kalsın geride

Ellerinde ve yüreğinde

Başaramadım

Hayaller kurmana bile dayanamadım

O kadar masumdu

Bir o kadar temizdi oysa

Duygularımız

Ben fazlasını istedim anlatamadım

Adını ben koydum senin

Hani o bilmediği kimsenin

Nice şafaklarda beklediğim gün

Akşamında oldu sadece hüzün

Ben seni sevmenin ötesindeydim

Yüreğim yetmedi neyleyeyim

Sen koskocaman kal

Ben küçüleyim

Bilirim

Katlanmak zor bana sarı gülüm

Gitme kal başka ne diyeyim', 'Adını ben koydum umutsuzlukların Sende kalsın istemediğim yalnızlıkların yüklendikçe yüklendim kendime İstedim ki bir sıcaklık kalsın geride...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yuregim-yetmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başına', 'bir-basina-ozay-karakus-ifri1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'haykırışım sessiz 

kalp atışım nefessiz 

kalmışım sensiz 

bir başına çaresiz 

bırakmamışsın bir iz 

gidişin esrarengiz 

ararım seni sensiz 

bir başına kimsesiz 

dünyam güneşsiz 

günüm neşesiz 

yarınlar sensiz 

bir başına ümitsiz 

sitemlerim dilsiz 

gözyaşım selsiz 

tükenmişim sensiz 

bir başına sevgisiz', 'haykırışım sessiz  kalp atışım nefessiz  kalmışım sensiz  bir başına çaresiz  bırakmamışsın bir iz  gidişin esrarengiz  ararım seni sensiz  ...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-basina-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarim', 'yarim-ozay-karakus-pnvoe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yüce dağların eteğinde 

hasret rüzgarında sarsıldım yarim 

sevginin sevdanın eşiğinde 

dertler kantarında tartıldım yarim 

takıldım zamanın peşine 

bilemedim bak şu feleğin işine 

beni de düşürdü aşk ateşine 

tutuştum yandım kavruldum yarim 

keremlerin mecnunların ötesinde 

sevdanın türküsünü çaldım yarim 

dünyanın bir kuytu köşesinde 

yerlere yıkıldım kaldım yarim 

çıkarttılar ruhumu gökyüzüne 

yine aşk deryasına daldım yarim 

kandırdılar inandım el sözüne 

muradımı en geç ben aldım yarim', 'yüce dağların eteğinde  hasret rüzgarında sarsıldım yarim  sevginin sevdanın eşiğinde  dertler kantarında tartıldım yarim  takıldım zamanın ...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yarim-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maytaplar Patlamaya Başladı', 'maytaplar-patlamaya-basladi-yusuf-onder-bahceci-vxh8s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Maytaplar patlamaya başladı yine,

Dikkat çocuklara birşey olmasın,

Bu maytabı patlatanlar belli değil,

Şurası belli ki işinde de baya ehil.

Yapmasana diyorlar laf anlamıyor,

İnşallah maytap bir elinde patlıyor,

İnşallah iki gözü birden kör oluyor,

Maytaplar patlamaya başladı yine.

Düğünlerde, magandaları sıkıyor,

Bunlar, misafirlerin cânını sıkıyor,

Millet nefret ederek, buna bakıyor,

Maytaplar patlamaya başladı yine.

Maytapları satan kös dükkancılar,

Birgün maytaplar dükkanda patlar,

Hepsi birden patlar dükkan yanar,

Maytaplar patlamaya başladı yine...', 'Maytaplar patlamaya başladı yine, Dikkat çocuklara birşey olmasın, Bu maytabı patlatanlar belli değil, Şurası belli ki işinde de baya ehil. ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/maytaplar-patlamaya-basladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soluklardan Taşarım', 'soluklardan-tasarim-ozay-karakus-x2x4r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'uykusuz gecelerde 

korkusuz hecelerde 

gönlüm işkencelerde 

zulmü yaşarım oluklardan taşarım 

zehir olsa içerim elinden 

kandırır sevdanı dökerim dilinden 

ne çare kaçmak aşkın selinden 

aşkı yaşarım, sığmam nehirlere, taşarım 

seni benden kim alır söyle 

gitmek varmı habersiz böyle 

severimki seni candan öyle 

hayatı yaşarım,kalbe sığmam soluklardan taşarım', 'uykusuz gecelerde  korkusuz hecelerde  gönlüm işkencelerde  zulmü yaşarım oluklardan taşarım  zehir olsa içerim elinden  kandırır sevdanı dö...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soluklardan-tasarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Ayrıldık', 'neden-ayrildik-ozay-karakus-3lt95', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir defa bakıştık 

hemen sarıldık 

nasıl da yakıştık 

neden darıldık 

önce öpüştük 

delice seviştik 

sonra gülüştük 

neden takıştık 

el ele verdik 

aşığız dedik 

zamanı yedik 

neden bitirdik 

bazen utandık 

bazen yandık 

madem aşıktık 

neden ayrıldık', 'bir defa bakıştık  hemen sarıldık  nasıl da yakıştık  neden darıldık  önce öpüştük  delice seviştik  sonra gülüştük  neden takıştık  el ele ...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neden-ayrildik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtacım Sana', 'muhtacim-sana-ozay-karakus-9qttc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'git sevgilim durma artık 

dayanmıyor kalbim yırtık 

kapıyı suratıma vurda çık 

anıları gözlerime bırak yık 

düşünme beni gider iken 

gülsün sen gül ben diken 

yüreğine acı tohum eken 

ben olurum derdi çeken 

dönme ne olur arkana 

gitme kal diyebilirim 

tutunupta belki hırkana 

ilk defa ağlayabilirim 

dönersen yazık olur bana 

yeniden yanarım anlasana 

yalvarıyorum aşkım sana 

git.git.. git.. me muhtacım sana', 'git sevgilim durma artık  dayanmıyor kalbim yırtık  kapıyı suratıma vurda çık  anıları gözlerime bırak yık  düşünme beni gider iken  gülsün ...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/muhtacim-sana-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serhat''a Mektup-3', 'serhat-a-mektup-3-saim-bastik-hhww6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oğul; buralarda işler çok kötü

Lâkin kimse gıpraşmıyor iyi mi? 

Birleşmiş geliyor dünyanın iti

Lâkin kimse gıpraşmıyor iyi mi? 

Bizimkiler düşmüş kendi derdine

Af çıkıyor her hükümet ferdine

Hadi dedim beygir ile kurduna

Lakin kimse gıpraşmıyor iyi mi? 

Deniz maval anlatıyor millete

Alışmak zor çektiğimiz zillete

Dönün dedik şu sine-i millete

Lâkin kimse gıpraşmıyor iyi mi? 

Tayyip kan kusturdu hepimize kan

Çıkmıyor milletin elinden tutan

Göre göre satılıyor şu vatan

Lâkin kimse gıpraşmıyor iyi mi? 

Mal varlığı moda oldu bu ara

Tayyip gizli deyip atıyor nara

İşine geleni sayıyor sonra

Lâkin kimse gıpraşmıyor iyi mi? 

Kemal abin coştu sığmıyor kaba

İki kaçak villa girdi hesaba

Bir gecede uydurdular kitaba

Lâkin kimse gıpraşmıyor iyi mi? 

Kuş gribi duman etti bizleri

Yaktık bütün tavukları kazları

Yalan çıktı bakanın tüm sözleri

Lâkin kimse gıpraşmıyor iyi mi? 

Şimdi yeter, az beklesin gerisi

Nasır tuttu vatandaşın derisi

Hep ötüyor namussuzun borusu

Lâkin kimse gıpraşmıyor iyi mi? 

13/02/2006', 'Oğul; buralarda işler çok kötü Lâkin kimse gıpraşmıyor iyi mi?  Birleşmiş geliyor dünyanın iti Lâkin kimse gıpraşmıyor iyi mi?  Bizimkiler d...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/serhat-a-mektup-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçersem', 'vazgecersem-ozay-karakus-flltd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gülmeyi sevmeyi unutayım 

ateşler içinde alev alev yanayım 

bir zalimin eline kalayım 

senin aşkından vazgeçersem eğer 

bağrıma kurşunlar bir bir dolsun 

şu gençliğim sararsın solsun 

yaşamak bana haram olsun 

senin aşkından vazgeçersem eğer 

eksik olmasın başımdan karalar 

bedenimi sarsın dermansız yaralar 

üzerime çöksün bütün dağlar 

senin aşkından vazgeçersem eğer 

kaale alınmasın hiç bir sözüm 

görmesin kör olsun şu iki gözüm 

olmasın bunlara ne çare çözüm 

senin aşkından vazgeçersem eğer', 'gülmeyi sevmeyi unutayım  ateşler içinde alev alev yanayım  bir zalimin eline kalayım  senin aşkından vazgeçersem eğer  bağrıma kurşunlar bi...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vazgecersem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oturup Konuşalım', 'oturup-konusalim-ozay-karakus-owg4w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aşk öyle büyük ki ateşi sönmez 

aşık sözünden asla dönmez 

birde seviliyorsa tadından yenmez 

gel buluşalım oturup konuşalım 

sevgidir aşkı ateşleyen 

bir buse gönlü fişekleyen 

yardır kalbe can ekleyen 

gel buluşalım oturup konuşalım 

aşkın fidanı öyle sağlamdırki 

kırılmaz seven su vermişki 

yarda büyümüş filizlenmişki 

gel buluşalım oturup konuşalım 

ben vazgeçemem yardan 

yarı yar yaratmış nurdan 

bahsedelim biz sevdadan 

gel buluşalım oturup konuşalım', 'aşk öyle büyük ki ateşi sönmez  aşık sözünden asla dönmez  birde seviliyorsa tadından yenmez  gel buluşalım oturup konuşalım  sevgidir aşkı ...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oturup-konusalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideli', 'sen-gideli-ozay-karakus-h6whz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gözlerinin esiri olduğum o dehşetengiz gün yanaklarındaki gamze denen koridorlarda yürüttün bakışlarımı 

ellerinle kelepçeleyip ellerimi hapsettin sevgimi avuçlarına 

ve en sonunda kalbinin zindanlarında çürüttün bedenimi 

şimdi benliğim kayıp bürosunda bulunmayı bekliyor her aşkın sonrasında,ruhum çoktan gökyüzüne iltica talebinde mülteci.... 

gururum himalaya sıra dağları gözyaşım muson yağmurlarında kan kırmızı,gönül bahçem mayın tarlası siluetinde,göğüs kafesimde oksijen karbondioksite sitemli 

nefessiz kaldım sevdiğim....... sen gittin gideli.................', 'gözlerinin esiri olduğum o dehşetengiz gün yanaklarındaki gamze denen koridorlarda yürüttün bakışlarımı  ellerinle kelepçeleyip ellerimi hap...', ARRAY['Türk Edebiyatı','Şiir','Özay Karakuş']::text[], 8.5, '{"poet":"Özay Karakuş","poet_slug":"ozay-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-gideli-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiye Koş', 'sevgiye-kos-meral-yagcioglu-ffmpi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlahi gücün 

Sevgiyle yoğurduğu

Bedenlerde 

Bireysel olarak yaşanan

En hassas duygu

Aşk; 

Tutkunun sevgiyle 

Kırıtmasından doğan

Yakan kırmızıyla

Yaşayabiliyorsan eğer

Her an sevgililer gününü 

Şu dünyada

İçen yoktur senden başka 

Mutluluk şerbeti

Yaşamadıysan

Ve yaşayamıyorsan

İşte o zaman

Fırtınalar esen

Bomboş yüreğini

Zaptetmek için bedeninde

Koş, sevginin arkasından 

Koş ki vakit varken

Doyumsuz tadına varasın

Aşkın

Hazların en güzelini 

Yudumla hayat sofrasından

Al eline sevgi anahtarını 

Açılsın kapılar birer birer

Koş

Sevdaya koş

AŞK’a koş

Sevgiyle insana koş

Aç kollarını

Sar sinene

Giy ateşten gömleği

Yansan da koş

Sığın yaratana sev.

14/02/2006

              Sevgililer günü bir güne sığmasın ve her gün yaşansın', 'İlahi gücün  Sevgiyle yoğurduğu Bedenlerde  Bireysel olarak yaşanan En hassas duygu Aşk;  Tutkunun sevgiyle  Kırıtmasından doğan Yakan kırmı...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sevgiye-kos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizce Gittin', 'sessizce-gittin-yusuf-onder-bahceci-ts2sf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu nasıl iştir böyle Gülüm sessizce gittin,

Sen gözlerime baktın ama yine de gittin,

Böyle gittin de sanki çok, çok iyimi ettin,

Bu nasıl iştir böyle Gülüm sessizce gittin.

Elim, kolum bağlandı birşey diyemedim,

Sadece boynunu büktün ve gülümsedin,

Ben de çoçukmuşum bunları bilemedim,

Bu nasıl iştir böyle Gülüm sessizce gittin.

Şimdiki aklım olsaydı gurur yaparmıydım,

İstediğini deseydin senden koparmıydım,

Senden başka bir kimseye saparmıydım,

Bu nasıl iştir böyle Gülüm sessizce gittin.

Sen istediğin kadar bana ne ki deseydin,

Benim yüzüme hiç gülmeyip de gitseydin,

Seni sevmiyorum çek git, git be deseydin,

Bu nasıl iştir böyle Gülüm sessizce gittin...', 'Bu nasıl iştir böyle Gülüm sessizce gittin, Sen gözlerime baktın ama yine de gittin, Böyle gittin de sanki çok, çok iyimi ettin, Bu nasıl iş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sessizce-gittin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürüm', 'olurum-husam-hasret-89n26', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimde bir aşkın hatırası var

O aşk için kalır, yaşar, ölürüm

Gönlümde sağalmaz bir yarası var

Sızdıkça kanımı taşar ölürüm

Bana bağışladı bitmez gamını

Kanla akıttırdı gözüm nemini

Doyamadan, sunudu hicran camını

Uğruna yolları aşar ölürüm

Hiç oldu kıldığım bütün vefam da

Bir cefaya döndü böyle safamda

Ne yapım olmadan akıl kafamda

Düzensiz işimde şaşar ölürüm

Üzülmem aşkıma çoban olursam

Her gün bir diyara mihman olursam

Vefalı aşkıma kurban olursam

Alanında şehit düşer ölürüm', 'İçimde bir aşkın hatırası var O aşk için kalır, yaşar, ölürüm Gönlümde sağalmaz bir yarası var Sızdıkça kanımı taşar ölürüm Bana bağışladı b...', ARRAY['Türk Edebiyatı','Şiir','Husam Hasret']::text[], 8.5, '{"poet":"Husam Hasret","poet_slug":"husam-hasret","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olurum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-i-smail-dogan-9brvy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cennet bahçesinin altın ışığı,

Güneşin değerni bilmez geceler.

Cemali gönlümüm çile aşığı,

Bülbülün gülüne gülmez geceler.

Hasretinle gündüzüm gece gibi,

Hayalin dilimde hep hece gibi,

Hallerim perişan bilmece gibi,

Derdime bir çare bulmaz geceler.

Karartma ışığı görülsün yolum,

Tenha köşelerde korkmasın kulum,

Sessizlik diz boyu sorulmaz halım,

Karanlığa ışık salmaz geceler.

Bir gece ansızın çalsam kapıyı,

İçerden nur aydınlatır yapıyı,  

Sanki düşman diye alır sopayı,

Gir içeri diye almaz geceler.

Dumanlı dağların çalısı olsam,

Erenler yolunun delisi olsam,

Kulumun önderi velisi olsam,

Görmez ışığımı almaz geceler.

DOĞANİ çok arar izi görülmez,

Arşa çıksam yarin yüzü görülmez,

Duruyor hareket gizi görülmez,

Şafak vakti dünyan kalmaz geceler.', 'Cennet bahçesinin altın ışığı, Güneşin değerni bilmez geceler. Cemali gönlümüm çile aşığı, Bülbülün gülüne gülmez geceler. Hasretinle gündüz...', ARRAY['Türk Edebiyatı','Şiir','İsmail Doğan']::text[], 8.5, '{"poet":"İsmail Doğan","poet_slug":"i-smail-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/geceler-141-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş musan', 'hos-musan-mustafa-benkli-ffxru', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(........Memleketimden hoş bir nükte düştü gönlüme......-Anonim-.............)

........Hoş musan.......

Ağam ele hoş musan

Dolu musan boş musan

Ayahların yan basir

Yohsa sen serhoş musan

(Anonim)', '(........Memleketimden hoş bir nükte düştü gönlüme......-Anonim-.............) ........Hoş musan....... Ağam ele hoş musan Dolu musan boş mu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Benkli']::text[], 8.5, '{"poet":"Mustafa Benkli","poet_slug":"mustafa-benkli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hos-musan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-bilal-i-lhami-koksal-2sbj3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğer ille de bir şehrin adı geçecekse bu şiirde

O isim mutlaka istanbul olmalıdır

Şiir güzel olacaksa özlemenin teri kokmalıdır

Ki özlemek yorucu uzun bir yoldur

Ve hiç bir hayra yorulamaz yolun sonunda hiç bir şeye varmayacaksa...

Hatırlayıp ta üzülmüş ve hatta ağlamışsan düne dair

Gözyaşında benim mavimin tonu buğulanmalıdır

Kelimelerin yetmediği

Şarkılara asla sığmayacak olandır aşk; 

Aşk kelimesinin sonunda kesinlikle nokta olmamalıdır

Belki üç noktaya isteklidir umut kelimesi ancak

Yine de  herhangi bir uzatma olmaz

Aşkta noktasız imlasız bir sonsuzluk vardır

Adını söylerken dudaklarımın titremesine hala da bir çare bulabilmiş değilim

Seni unutmaya çalıştığım doğru

Ama unutamaz kalbime kefilim

Yokluğundan beri sen ne dersen de 

Ben kör kütük sefilim

Noktaları biriktirdim açık kahverengilerde

İstanbulda yarım bir şiirim

Eğer ille de terketmenin adı geçecekse bu şiirde

O isim mutlaka öylesine olmalıdır

Aşkta nokta

İstanbula...', 'Eğer ille de bir şehrin adı geçecekse bu şiirde O isim mutlaka istanbul olmalıdır Şiir güzel olacaksa özlemenin teri kokmalıdır Ki özlemek y...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/oylesine-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmaki Gördüğüm Rüya Hayra Yorulur', 'sanmaki-gordugum-ruya-hayra-yorulur-kamil-soylemez-prlw2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni sarıp,sarmalayacak bir yürek gerek

Ne koldur,istediğim,ne de,ballı börek

Bana ah senin sevdam,gönül gözün gerek

Ne direk isterim,ne de direngeç,değnek

Ümit çiçeklerim bir, bir sararp,kurur

Acı yaşamda,sen sevdan aranır durur

Önce gün olur, ömür, sonrada kararır

Sen sevdan yüreğimde ballanır da büyür

Her zaman dilimdedir sevdiğim adın,tat

Yavan gelir bana bir başka kadın,ve ad

Dünyam sensiz olur da yangınlarda kat, kat

Savrulur da külüm,savrulur vahım,hey hat

Sanmaki gördüğüm rüya hayra yorulur

Gönlümdeki tahta bir başkası kurulur

O senindir,ebedi,sen için durur

Sen bozma kalbini,tüten adam söz, durur', 'Beni sarıp,sarmalayacak bir yürek gerek Ne koldur,istediğim,ne de,ballı börek Bana ah senin sevdam,gönül gözün gerek Ne direk isterim,ne de ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sanmaki-gordugum-ruya-hayra-yorulur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Penceresin''den...', 'hasret-penceresin-den-hasan-ayar-7accz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün ben hasretin kucağında kalmışım,

Gurbet denen illete ben buğün alışmışım,

Gözüm karşı dağlarda hayallere dalmışım,

Bu hasretlik canıma tak dediği gündür bu,

Ya geri döneceğim,ya öldüğüm gündür bu,

2006', 'Bugün ben hasretin kucağında kalmışım, Gurbet denen illete ben buğün alışmışım, Gözüm karşı dağlarda hayallere dalmışım, Bu hasretlik canıma...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ayar']::text[], 8.5, '{"poet":"Hasan Ayar","poet_slug":"hasan-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hasret-penceresin-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Yemini(ni)', 'kus-yemini-ni-firat-acikgoz-77wpu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yedi mi desem 

Kuş yemini(ni)  

Metrekarelik yaşam

Göz kararı

Sıkmış seni

Karın yok 

Metresin çok

Tırnakların senin

Karşıyaka’daki yalını satmış torbacının biri

İki yüz gram ceviz içine

Nam-ı değer derdine

Altına yattığın ejderhaları yaz artık

Özgeçmişine

Sektir artık topunu ta Florya’ya kadar

Tutan yok seni

Yedi

Nisan’da 

Kuş yemini(ni)  

13 Şubat, 2006', 'Yedi mi desem  Kuş yemini(ni)   Metrekarelik yaşam Göz kararı Sıkmış seni Karın yok  Metresin çok Tırnakların senin Karşıyaka’daki yalını sa...', ARRAY['Türk Edebiyatı','Şiir','Fırat Açıkgöz']::text[], 8.5, '{"poet":"Fırat Açıkgöz","poet_slug":"firat-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kus-yemini-ni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milletim Ak İle Karayı Seçer', 'milletim-ak-i-le-karayi-secer-yusuf-onder-bahceci-ri6d4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eğer ki bu Dünya''da seni alsaydım,

Her halde şiir yazmazdım yaşardım,

Güzel gözlerine, şiir gibi bakardım,

Eğer ki bu Dünya''da seni alsaydım.

Gözü açık olanlar hep sevdiğini alır,

Bizim gibi ahmaklar, hep yaya kalır,

Çekip giden sevgiliden, şiirler kalır,

Gözü açık olanlar hep sevdiğini alır.

İstediğin kadar güzel şiir yaz ahmak,

En güzel şiir, bil gerçekleri yaşamak,

Benim gibi, sevdasını da yaşatmak,

İstediğin kadar güzel şiir yaz ahmak.

Ne kadar da güzel şiir yazmış derler,

Az bir yanlış görseler dalga geçerler,

Milletim ak ile karayı, güzel seçerler,

Ne kadar da güzel şiir yazmış derler....', 'Eğer ki bu Dünya''da seni alsaydım, Her halde şiir yazmazdım yaşardım, Güzel gözlerine, şiir gibi bakardım, Eğer ki bu Dünya''da seni alsaydım...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/milletim-ak-ile-karayi-secer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Gülleri', 'kar-gulleri-sevim-yakici-39w3w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nicedir hasret kaldı kar güllerine kar taneleri,

Yanar yüreğindeki sevda söndürmez kar taneleri, 

Gözünden dökülen gözyaşı değil de kar taneleri, 

Alır götürür ılık bir Şubat gününe kar taneleri, 

................................

Kaç fasıl geçer gider de, 

ardından ninnisi kalır rüzgarlı gecelerin.

kuru dallardan dökülür, konfeti yerine ey yar; 

kar taneleri, üzerine “kar güllerinin”...

..........kızıla boyar dökülen yapraklar çileyi

..........savrulunca rüzgardan beyaz etekleri, 

..........gök narların ninnisiyle ağlar sevgili,

..........geceleri `kar gülleri` 

serçelerin ürkekliğiyle yağan yağmur

ardındaki feryatları yıldırımların

şükür sızılarıyla inletir gönülleri

bir konçerto duyulur, çok uzaklarda yalnız,

munis bir edayla eğilir secdesine dallar,

beyaza süzülür, gökyüzünden kaygılar,

dökülürken kutsal merasimine gecenin,

.........“ay bir taraftan sahitlik eder sevdasına,

...........bir taraftan da yıldızlar” (*)           

yosunlarıdır gövdelerin, baharlara tutunan, 

uğultusudur yorgunluğun, dallara vuran, 

titreyen ellerimdir, sana uzanamayan, 

tiz bir çığlıktır geceyi bölen, uğursuz, 

.........üşüyen yüreğimdir, sevdasına inanan... 

Dinle; bir beste fısıldıyorlar,

periler güftede kar güllerine: 

..........“kaderimdir tek başına savaşım yücelerde,

...........usul usul inen sancılı gecelerde...`

SUNU:

hisset sevgili, ateşinden içimde yananların, 

Yusuf’un suskusundan Züleyha’ya düşen hüzünlü ah’la, 

azaplı saatlerde duadadır “kar gülleri”…

(*)                (m.y.ayan)                        alıntıdır', 'Nicedir hasret kaldı kar güllerine kar taneleri, Yanar yüreğindeki sevda söndürmez kar taneleri,  Gözünden dökülen gözyaşı değil de kar tane...', ARRAY['Türk Edebiyatı','Şiir','Sevim Yakıcı']::text[], 8.5, '{"poet":"Sevim Yakıcı","poet_slug":"sevim-yakici","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kar-gulleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prenses', 'prenses-umit-tuna-gm1ga', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen şu kalbimin taçsız prensesi,

Sen karanlık gecelerimin tek ışığı,

Sen unutulması imkansız tek insan,

Sen özledikçe çoğalan bir aşk.

Seni sevmek belki de,

Dünyanın en zor şeyi demek,

Seninle olmak,

Mutlu olmak demek.

Peki! Sence ben papatyam,

Ben senin için ne ifade ediyorum,

Benimle mutlu musun? 

Bunu duymak istiyorum.

Ben seninle çok mutluyum,

Artık bunu cümle alem,

Bilsin istiyorum,

Seni seviyorum! ...', 'Sen şu kalbimin taçsız prensesi, Sen karanlık gecelerimin tek ışığı, Sen unutulması imkansız tek insan, Sen özledikçe çoğalan bir aşk. Seni ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/prenses-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rahatsız Etmeyeceğim...', 'rahatsiz-etmeyecegim-umit-tuna-98sj2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Görmek bile istemiyor artık beni,

Beni gördüğü gibi girdi içeri,

Kapattı kapıyı,

Çekti perdeyi,

Görmek bile istemiyor artık beni.

Oysa ne kadar çok sevmiştim,

Çok değer vermiştim,

Bunların hiç birisini ben hak etmemiştim,

Sadece seni sevmiştim.

Niye böyle yapıyorsun bana,

Beni üzüyorsun anlasana,

Ama artık ne yapsan üzülmeyeceğim,

Platonik olarak seveceğim.

Sadece kalbimin sesini dinleyeceğim,

Kimi zaman ağlayıp kimi zaman güleceğim,

Ama söz bundan sonra seni rahatsız etmeyeceğim,

Kapına bir daha gelmeyeceğim,

Söz veriyorum aşkım sana,

Bundan sonra rahatsızlık vermek yok sana! ...', 'Görmek bile istemiyor artık beni, Beni gördüğü gibi girdi içeri, Kapattı kapıyı, Çekti perdeyi, Görmek bile istemiyor artık beni. Oysa ne ka...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/rahatsiz-etmeyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat 5'' te Bekliyorum', 'saat-5-te-bekliyorum-umit-tuna-euq3a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu acılar bitmez,

Bu sevda kalbimden silinmez,

O gözlerin aklımdan gitmez,

Senin yüreğin beş para etmez.

Sana verdiğim değer hiçbir şeyle ölçülmez,

Sana olan sevgim hiçbir şeyle değiştirilmez,

Sen unutulması imkansız bir güzel,

Seni özlemek bile özel.

Her gecenin sabahında,

Her kışın baharında,

Hep sen varsın aklımda,

Cüzdanımda resmin saklı hala.

Gel tekrar yanaş bu limana,

Gidelim seninle ıssız adalara,

Yaşayalım seninle oralarda,

Yanımda sen olduktan sonra,

Neler vermem uğruna.

Bir ömür boyu mutluluk vaat ediyorum sana,

Gel kırma beni evet de en sonunda,

Kaçalım seninle uzak diyarlara,

Aşkın diğer adı oralarda.

Saat beşte bekliyorum seni,

Köşedeki sokak lambasının altında,

Gideceğiz seninle uzak diyarlara,

Bir ömür boyu mutluluk vaat ediyorum sana,

Saat beşte bekliyorum,

Köşedeki sokak lambasını altında! ...', 'Bu acılar bitmez, Bu sevda kalbimden silinmez, O gözlerin aklımdan gitmez, Senin yüreğin beş para etmez. Sana verdiğim değer hiçbir şeyle öl...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/saat-5-te-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Seni Sevdim', 'sadece-seni-sevdim-umit-tuna-31p3s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özledim seni,

Bu gece koynunda uyut beni,

Göğsünde ağlamak istiyorum,

Ben seni seviyorum.

Seninle sadece bir gece beraber olmak,

Sana sarılmak,

Seni koklamak,

Ölene kadar hep seninle olmak.

Dünyada tek dileğim bu oldu benim,

Ben sadece seni,

Hep seni sevdim,

Kaç gece bekledim,

Belki ararsın dedim.

Seni seviyorum derken,

Hep bunu yüreğimde hissettim,

Hala da seviyorum,

Ellerini tutmak istiyorum,

Ben seni aynı yerde,

Aşıklar parkındaki kafede bekliyorum! ...', 'Özledim seni, Bu gece koynunda uyut beni, Göğsünde ağlamak istiyorum, Ben seni seviyorum. Seninle sadece bir gece beraber olmak, Sana sarılm...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sadece-seni-sevdim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benimsin', 'sen-benimsin-umit-tuna-rbr0b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özledim seni,

Duy sesimi,

Yollarını gözlüyorum,

Herkesi sen sanıyorum.

Gözlerini, sözlerini özledim,

Bekledim deli gibi bekledim,

Sevdim çok sevdim,

Çünkü sen birtaneydin.

Bir tane olarak kalacaksın,

Kalbimden çıkıp kaçamayacaksın,

Hiç kimselere yar etmem,

Sen benim olacaksın! ...', 'Özledim seni, Duy sesimi, Yollarını gözlüyorum, Herkesi sen sanıyorum. Gözlerini, sözlerini özledim, Bekledim deli gibi bekledim, Sevdim çok...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-benimsin-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliyle Dans', 'sevgiliyle-dans-murat-polat-2-okpz4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölümle dans etmek benim için

Aynı sevgiliyle yapılan bir vals

Ölüme randevu vermek belkide

Olmayan sevgilimle buluşma yeri

Bizler böyleyiz, başkalarına göre

Herşey var...iş, ev, para, yaşam

Gel gör ki öyle değil...bunlar yalan

Yani nasıl anlaşılmışlığınla ilgili

Yani senin neleri anlatabildiğinle

Ya sonra, ya sonrası...arkası

Bence anlayana yeter bu kadarı 

Ha bir kaç sene, ha bir kaç yüzyıl

Sevmesini bilene, acı çekene

Feda olsun bir ömür...

                           

                               14 Şubat 2006', 'Ölümle dans etmek benim için Aynı sevgiliyle yapılan bir vals Ölüme randevu vermek belkide Olmayan sevgilimle buluşma yeri Bizler böyleyiz, ...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgiliyle-dans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zindan Etme Dünyamı', 'zindan-etme-dunyami-mustafa-bilgili-tpuez', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen:   Kanayan yaralarımı sarmayacaksan,

          Halımı,hatırımı sormayacaksan,

          Düşlerimi hayra yormayacaksan,

          Bırak git haydi,zindan etme dünyamı,

Ben:  Al yerine karalar bağlayacaksam,

          Dertli pınar gibi çağlayacaksam,

          Sen gülerken ben hep ağlayacaksam,

          Bırak git haydi,zindan etme dünyamı.

Sen:   Ellerini elime vermeyeceksen,

          Kalbini yoluma sermeyeceksen,

          Önünden geçerken görmeyeceksen,

          Bırak git haydi,zindan etme dünyamı.

Ben:  Seni hiç koluma takmayacaksam,

         Yüreğini kor gibi yakmayacaksam,

         Dizlerine yatıp,yüzüne bakmayacaksam,

         Bırak git  haydi, zindan etme dünyamı.

Sen:  Gel dediğimde hemen gelmeyeceksen,

         Seni çok sevdiğimi bilmeyeceksen,

         Dertlerime derman bile olmayacaksan,

         Bırak git haydi,zindan etme dünyamı.

Ben: Saçlarını okşayıp,taramayacaksam,

        En zor günümde seni aramayacaksam,

        Göğsümde uyutup,saramayacaksam,

        Bırak git haydi,zindan etme dünyamı.

Sen: Gonca güllerimi solduracaksan,

        Yüreğime göz yaşı dolduracaksan 

        Ecelim gelmeden öldüreceksen,

        Bırak git haydi,zindan etme dünyamı,

Ben: Seni çılgınca sevemeyeceksem,

        Bu canı yoluna veremeyeceksem,

        Rüyalarımda bile göremeyeceksem,

        Bırak git haydi,zindan etme dünyamı.

Sen: Hiç sevmeyip,sadece sevileceksen,

        Her insanın önünde eğileceksen,

        Ben daha koklamadan dağılacaksan,

        Bırak git haydi,zindan etme dünyamı

                                                                20.12.1996', 'Sen:   Kanayan yaralarımı sarmayacaksan,           Halımı,hatırımı sormayacaksan,           Düşlerimi hayra yormayacaksan,           Bırak g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/zindan-etme-dunyami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesela Mesela Dedik', 'mesela-mesela-dedik-yusuf-onder-bahceci-bvv3n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mesela olmaz ya, sana gezelim desem,

Mesela olmaz ya, gel çay içelim desem,

Mesela olmaz ya, güzel gözlerinle gülsen,

Mesela, mesela dedik, sakın telaşlanma.

Mesela diye, diye kendimi kandırmışım,

Hayat meseladan ibaretmiş uyanmışım,

Mesela diye, diye, ben harap olmuşum,

Mesela, mesela dedik ki yok olmuşum.

Mesela ile bir yerlere, varamadım ben,

Mesela dedim, dedim saramadım ben,

Meseladan öteye, yol, bulamadım ben,

Mesela, mesela dedik, yollar bitmedi.

Mesela, şu dağları, bir aşsam dedim,

Mesela, sevdiğime, ulaşsam dedim,

Mesela, mesela dedim hiç bilmedim,

Mesela, mesela dedim çilem bitmedi...', 'Mesela olmaz ya, sana gezelim desem, Mesela olmaz ya, gel çay içelim desem, Mesela olmaz ya, güzel gözlerinle gülsen, Mesela, mesela dedik, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mesela-mesela-dedik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'At nefreti içinden de doldur sevgi neşe ülküsünü', 'at-nefreti-icinden-de-doldur-sevgi-nese-ulkusunu-halil-colak-pxoqn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmek Allah tarafından verilen en büyük mükafat

Seven gönüllerde acı çekse de olmaz kin, husumet

Sevgi kalbe verir benim güzelim huzur ve ulviyet 

Seven kalpte kın,garaz ve nefret bulunmaz canım 

Yaratılanı sev kardeşim yaratandan da  ötürü

Yükle kervanına can her zaman sevgi  yükünü

Taş kalpleri yumuşatır seven insanın tatlı da dili

Savaş yerine sevgidir dost insanlığa veren barışı

Sevgisizlikten dünyayı sarmış barut ta kokusu

Sevmeyen gönüllerde yoktur da  Allah korkusu

İnsanları da sarmışta zalimlik nefrette duygusu

At nefreti içinden de doldur sevgi neşe ülküsünü

Halil ÇOLAK  14.2.2006 Ankara', 'Sevmek Allah tarafından verilen en büyük mükafat Seven gönüllerde acı çekse de olmaz kin, husumet Sevgi kalbe verir benim güzelim huzur ve u...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/at-nefreti-icinden-de-doldur-sevgi-nese-ulkusunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-murat-polat-2-g8xab', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlattın, kırdın, belki unuttun

Sanki sen sondun...

Öyle değil ey sevgili

Sen benim için yoksun...

                      Murat Polat

                    14 Şubat 2006', 'Ağlattın, kırdın, belki unuttun Sanki sen sondun... Öyle değil ey sevgili Sen benim için yoksun...                       Murat Polat        ...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yoksun-140-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimi seçen yalnızlık', 'kalbimi-secen-yalnizlik-elazigli-mustafa-kaya-4bmv2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her bir derdi

dik yamaçlı,

diken dolu 

bir kentte,

bin bir haller

çevrili.

manşetlere çıkar

hüzünlerin miktarı.

kalbimi seçen yalnızlık

kutsal kelimelerle

hayat bulur..

ahh…biliyorum

kalpler ancak,

Allah ‘ı anmakla huzur bulur..

Mustafa kaya

14.02.2006 / üsküdar', 'her bir derdi dik yamaçlı, diken dolu  bir kentte, bin bir haller çevrili. manşetlere çıkar hüzünlerin miktarı. kalbimi seçen yalnızlık kuts...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalbimi-secen-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Şubat', '14-subat-zehra-bulutlar-ac1p2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günaydın öpücüğü,

 Sevgi yüklü sözcükler,

 Yatakda, serpilmiş güller,

 Romantik süpriz  yemek,

 Masada hoş bir paket,

 Mutluluğa kalkan kadeh

 Değişik bir gün diye

 Geçirirken aklımdan; 

 Yorgan düşmüş yerlerde,

 Belli açıkta kalmış gene,

 Uyandım tebessümle

 Hayırlara gelsin diye...! 

Yine unuttum  Tanrım...! 

B u g ü n  neydi  g ü n l e r d e n ...? 

14.02.2006', 'Günaydın öpücüğü,  Sevgi yüklü sözcükler,  Yatakda, serpilmiş güller,  Romantik süpriz  yemek,  Masada hoş bir paket,  Mutluluğa kalkan kade...', ARRAY['Türk Edebiyatı','Şiir','Zehra Bulutlar']::text[], 8.5, '{"poet":"Zehra Bulutlar","poet_slug":"zehra-bulutlar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/14-subat-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairsem Sancılarım Vardır', 'sairsem-sancilarim-vardir-mehmet-faruk-habiboglu-jovxz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kitap’ta uyarıldık:

“görmedin mi, onlar her vadide şaşkın geziyorlar! ”

şairsem sancılarım vardır

yüreğim hüzün 

yüreğim hardır

mostar’ı hatırlarım birden

yedi yaşında bitirilen kız çocuklarının

umutsuz gözlerini

kızıl kana bulanık ellerini kadınların

zulmü görürüm kerbela’da

gökyüzünün başka rengini

gökyüzünün öldüğünü

kudüs bir genç kızdır 

bombalar giyinir / ölmek nedir

bir atımlık taş öbürü tank

tiananmen meydanında

hürriyeti canımla satın alırım

yiğit bir çinli gibi

yumruklar yürekçedir

ahh felluce

yüreğime bin kurşun değer

ölür her dem babalar

sonrası sükut

ateş yağar sonra başıma kabil’de

dağlar kızıl kıyamet

zulüm kah rus olur

kah amerikalı

zulmün adresi nedir

çeçenya’da dudayev olurum

aşk içre ölürüm

sonra şamil

gene ölürüm

bedir

allahu ekber

allahu ekber

melekler söyler türkümü

söz biter

doymaz kana toprak çanakkale’de

ben ölmeye doymam

şehit olurum

arş titrer

şairsem sancılarım vardır

taşlarla ellerimi kırarlar filistinde

her gece ben tükenirim 

sibirya sürgünlerinde

endülüs kan olur 

zindan olur gözlerimin kuytusunda

illa ayaklarıma değil yüreğime atılır dikenler

idam ederler beni afrikada hem şair olarak

can fırınlarında yakılan benim

bütün mazlumların ahını taşır sol yanım

bütün yetimlerin gözyaşı gözlerimden akar

isa yerine çarmıha yeniden gerilirim 

“tanrım beni neden bıraktın? ”

afrikadan koparılmış bir köleyim

arenada parçalanır bedenim

hiroşima’da yeniden ölür yüreğim

ve yeniden 

ve yeniden bak gözlerime

orda bir dolu efkar vardır

yüreğimden yükselen har vardır

intizar vardır

ahu zar vardır

şairsem 

sancılarım vardır', 'kitap’ta uyarıldık: “görmedin mi, onlar her vadide şaşkın geziyorlar! ” şairsem sancılarım vardır yüreğim hüzün  yüreğim hardır mostar’ı hat...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Faruk Habiboğlu']::text[], 8.5, '{"poet":"Mehmet Faruk Habiboğlu","poet_slug":"mehmet-faruk-habiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/sairsem-sancilarim-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arsız Adam', 'arsiz-adam-abdurrahim-karakoc-oc1em', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayıp ne, günah ne, bilmiyor adam

Yüzüne tükürsen silmiyor adam

Memleketi dilim dilim diliyor

Karpuzu yutuyor, dilmiyor adam! .

14.02.2006/Vakit', 'Ayıp ne, günah ne, bilmiyor adam Yüzüne tükürsen silmiyor adam Memleketi dilim dilim diliyor Karpuzu yutuyor, dilmiyor adam! . 14.02.2006/Va...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/arsiz-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Cins Kadin Cismi', 'ne-cins-kadin-cismi-i-brahim-ethem-uzun-vaqz0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben oyle bir sevgiliye muhtacim ki

O sevgili bana beserin butun sarkilarini soyliyecek

O sevgili bana beserin butun siirlerini ezberletecek

Cismin beni cagiriyor

Atesle 

Buzla

Recel olmaya

Efelerin gozleri gibi simsek cakiyor

Saray catal kasiklari gibi isildiyor

Misir carsisi gibi baharat kokuyor

Karli daglar gibi burnunu havaya dikiyor

Cismin Ayasofya muzesi

Mozayiklarla

Seyyahlarla

Ilahi nakislarla

Kubbelerle

Dualarla

Kole terleriyle

Meleklerle dolu

Cismin denizden yeni cikmis uskumru

Parliyor pullarinin uzerindeki su

Koylu kizlarin dantelle isledigi kugu

Ciceklerden kurulmus semaya kopru

Donmek icin nefesimi bekleyen ruzgar gulu

Bir afrika colunde serap golu

Cismin bir senlik meydani

Sarkilarla 

Sanatcilarla

Cocuklarla

Alkislarla 

Isliklarla

Cigliklarla

Genclerle dolu

Cismin bir eylem meydani

Tanklarla

Kanlarla

Sloganlarla

Pankartlarla

Mazlumlarla

Davalarla

Devlet korumalariyla dolu

Cismin selcuklu sikkesi

Basilmis uzerine anadolu daglarinin resmi

Bir daha asla basilamaz  onun gibisi

Hic bir sultanin yetmez basma emri

Cismin degerli taslarla dolu

Incir agaclariyla ceviz agaclariyla dolu

Mukaddes kitaplar gibi haberlerle dolu

Asyayi kucaklayan ipek yolu

Balla sutle yagmurla kanla karismis kuyu

Gunesin butun isigini icmis yavru

Sapsari bir portakal kabugu

Cismin saciyor uzaya dogru

Karanfil kokusu

Sehitlerle islanmis toprak kokusu

Dogar dogmaz cocugun kokusu

Cismin bir osmanli divani

Yazilmis yaldizli hatti kufi

Her sayfanin basi bismillah Allah`in ismi

Altindan Alamut Kalesi

Gelene hos geldin diyor

On bin guvercin sesi

Gidene elvada diyor

On bin bildircin sesi

Cismin bir zeytin agaci

Silkeledikce dallarini

Nazim`in nazimlari

Beyazit meydanina dokuluyor

Suladikca koklerini

Necib`in hece gozyaslari 

Sicak seccadesine dokuluyor

Cismin gizli gunluk defterim

Kaydettim Kuvayyi Milliyye destanini

Kaydettim

Mahkum edilen

Iskence edilen

Taslanan

Asilan siyasilerin isimlerini

Kaydettim altin harflerle

Hurriyet icin 

Cumhuriyet icin

Baris icin 

Ask icin yazilan butun cihan siirlerini

Naksettim elmas harflerle

Vatandasliktan atilan 

Zindanlara tikilan

Siirleri yasaklanan

Koylulesmis siir sitelerinden kovulan

Kelimeleri kelepcelenen sairlerin isimlerini

Cismin ideolojilere davet ediyor

Goguslerin adami sarhos ediyor

Masayi sandalyeyi ranzayi kilimi ucuruyor

Askin mahur sanfonisini haykiriyor

Butun erkeklik hucrelerimi kusatiyor

Cismin tecrubeli yeniceri askeri sanki

En etkili disilik silahlarini sakliyor sanki

En cagdas sicak ve soguk savas

Dunya erkeklerinin tamamini olduruyor

Cismin butun dinlerden vahiyler okuyor

Mumlar yaniyor

Canlar caliyor

Vaftiz yapiliyor

Ezanlar okunuyor

Kurbanlar kesiliyor

Kudus avuc aciyor

Butun dinler sevisiyor

Cismin cennet vatan 

Sahibsiz olulerin vatani

Vatansiz batan gemilerin vatani

Soguktan olen kuslarin vatani

Kar altinda kalan ciceklerin vatani

Vergilerle ezilen vatandaslarin vatani

Dili panzehirli sairlerin vatani

Zulmun siddetinden intihar eden kelimelerin vatani

Cismin celikten kilinc

Yolculuk ediyor raksederek liflerimde

Kesiyor gectigi butun yollari

Dikiyor gectigi butun yolari

Cismin her an tetikte sevgili

Pusuya yatmis dusman gibi

Ormanda sinmis kurnaz tilki

Siirlerimi disbiliyenlerin disleri

Hallac i Mansur`a atilan taslari

Pirsultanin sehpasini cakan civileri

Zeybek Adnan Mendiresin kefen bezi

Cismin her yerden gorunen agac

Her yonden okunan kitap

Yukaridan okunuyor

Asagidan okunuyor

Sagdan okunuyor

Soldan okunuyor

Sabah

Oglen 

Aksam okunuyor

Ayak parmaklarindan okunuyor

Kirpiklerinden okunuyor

Memelerinin sivri uclarindan okunuyor

Kalcalarinin kenarindan okunuyor

Cismin butun dillerle okunuyor

Cismin Osmanli kulturu

Cismin Bizans kulturu

Cismin Avrupa kulturu

Cismin Mezapotamya kulturu

Cismin Afrika kabile kulturu

Cismin dogustan buyucu

Cismin dogustan devrimci

Cismin dogustan veli

Cismin dogustan deli

Cismin dogustan katil

Cismin dogustan sair

Cismin dogustan ilahi disi

Hukuk fakultesinde okuduk

Cismin hukukun girisi

Cismin hukukun cikisi

Dudaklarin memelerin ziynetlerin anayasa kanunlari

Nasil ezberliyecegimi bilmiyorum

Nasil unutacagimi bilmiyorum

Cismin siir okudugu zanman

Butun sairler dilini yutuyor o an', 'Ben oyle bir sevgiliye muhtacim ki O sevgili bana beserin butun sarkilarini soyliyecek O sevgili bana beserin butun siirlerini ezberletecek ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Uzun']::text[], 8.5, '{"poet":"İbrahim Ethem Uzun","poet_slug":"i-brahim-ethem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":159,"source_url":"https://www.antoloji.com/ne-cins-kadin-cismi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi Bize Koymadılar', 'bizi-bize-koymadilar-yusuf-onder-bahceci-1hcra', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bırakıp ta gideni bırak sen dediler,

Ondan sana hayır gelmez, dediler,

Benim gözümle, seni göremediler,

Bizi, bize koymadılar sevdiğim. 

Sen beni bırakıp, çekip gitmedin,

Bilmediğim birşey var, demedin,

Senin için cânı veririm, bilmedin,

Bizi, bize koymadılar sevdiğim.

Tehdit mi ettiler ki bunu demedin,

Keşke deseydin, ben tepelerdim,

Seni ellerinden, alır da giderdim,

Bizi, bize koymadılar sevdiğim.

Kâlbim yalan söylemez, seviyor,

İddia ediyorum, rüyada görüyor,

Seven dostlarına, beni soruyor,

Bizi, bize koymadılar sevdiğim.

Benim aklım başıma yeni geliyor,

Vallahi o da beni seviyor, seviyor,

Elinden birşey gelmiyor, gelmiyor,

Bizi, bize koymadılar sevdiğim...', 'Bırakıp ta gideni bırak sen dediler, Ondan sana hayır gelmez, dediler, Benim gözümle, seni göremediler, Bizi, bize koymadılar sevdiğim.  Sen...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bizi-bize-koymadilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gününe doğmaya Geldim...', 'gunune-dogmaya-geldim-muammer-celik-cbg2a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'uzaklardan sana geliyorum 

çekim alanımın içine alıyorum 

ve günün anlamına 

attığın çığlıkların uğultusunu 

bedenimin titreyişinde duyuyorum... 

çaresiz değilsin, 

artık susma nolur 

bak; 

gölgene bir güneş gibi doğuyorum... 

bilinmeyen tarihten beri bensizliğini 

bugün sevgimle öldürüyorum, 

ve 

tüm imkansızlıklarını 

yedi kat yerin dibine gömüyorum... 

yaşanmış korkularını 

ellerimde kırıyorum 

bak; 

bulutlu gecelerin mehtabındayım 

ve 

umudun tam başladığı noktadayım... 

sevgin için 

dönülmez ölümlerden 

geri dönüyorum 

ve 

hayata seninle 

yeniden giriyorum... 

yüreğinin aynasına bak 

gözlerinde ışıldıyorum 

ve 

karanlık gölgelerinden çıkarıyorum... 

Bu anlamlı gününü yüreğimden kutluyorum

alıp gecenin koynuna seni 

tekrar sonsuza kadar doyuyorum! ... 

...Bugünün Tüm Şiirleri Sana Yazıldı, Biliyorum! ...

BirDeli 

14.02.2006', 'uzaklardan sana geliyorum  çekim alanımın içine alıyorum  ve günün anlamına  attığın çığlıkların uğultusunu  bedenimin titreyişinde duyuyoru...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gunune-dogmaya-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Sevinci', 'bahar-sevinci-rifki-kaymaz-kajrf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soğuk kış günleri elveda dedi

Şimdi bir misafir geliyor:Bahar.

Artık her tarafta yemyeşil örtü

Artık her tarafta bir canlılık var.

Toprakta hareket ağaçta yaprak

Dereler canlanmış, çağıldar sular.

Kuşlar kanat vurmuş mavi göklere,

Yeşile boyanmış artık duygular.

Biz minik bir fidan, küçük bir pınar

Şen şakrak çağlayıp, akar coşarız.

Bahar sevincini herkesten önce

Küçük yüreklerde bizler duyarız.', 'Soğuk kış günleri elveda dedi Şimdi bir misafir geliyor:Bahar. Artık her tarafta yemyeşil örtü Artık her tarafta bir canlılık var. Toprakta ...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bahar-sevinci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '…Peçe…', 'pece-naime-erlacin-h0dio', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir yas peçesiydi yüzüm

eksik 

yanık 

yalnız

eski bir kuda oyunundan kalma

cilası sıyrık tutkuların düşkıran istilâsına

arsızca kondulaşmasına arı duru sevdaların

gece gündüz yozlaşmasına

mecalsiz bir isyan 

bize zimmetli uçurumlarla 

intiharların sancılı hazzı 

bir biz kaldık 

düşerken aşka tutunan

“inecek peçe

iniyor peçe 

ya sabır! ...” 

böyle ünlüyor boşluğa

boyunduruktaki ses

ey gülüme günışığı gibi değerken 

dilimi bağışlayan sevgili! 

sana döndü çıbanları patlayan sırlı yüzüm

günebakan çiçeğinde 

sayısız kederlerin çatıldığı 

yetim haller

indi peçe! 

matemi lâl eden bir duygunun 

sınırsız kudretiyle

çoğalmaktan nasıl yorgunuz şimdi

nasıl da kalabalık delice akmaktan 

yatağını bulmuş 

efsunlu bir masal nehrinde

(*)    Yalnızca 14 Şubat’lar değil, tüm sevenlerin her doğan günü kutlu olsun… 

(14 Şubat 2006)', 'bir yas peçesiydi yüzüm eksik  yanık  yalnız eski bir kuda oyunundan kalma cilası sıyrık tutkuların düşkıran istilâsına arsızca kondulaşması...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/pece-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi Sevgililer Günü', 'hangi-sevgililer-gunu-yusuf-onder-bahceci-oz2cg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hangi sevgili, neyin, kimin sevgilisi,

Ateşiyle yakarak, giden, sevgili mi,

Böylesi eritip de, bitiren sevgili mi,

Hangi sevgili, neyin, kimin sevgilisi.

Ondört Şubat sevgililerin günü imiş,

Hangi sevgili, neyin, kimin sevgilisi,

Hâni nerede şimdi o kimin sevgilisi,

Sevgilim olmalıydı, bir vefa abidesi.

Bırakıp ta böyle gitmeseydi bilirdim,

Yılın her günü, Ondört Şubat derdim,

Şimdi kapandayım, ben nasıl edim,

Hangi sevgili, neyin, kimin sevgilisi.

Ondört Şubat gelince, hüzünlenirim,

Hep kendi, kendime nerede derim,

İşte böyle dostlarım bitmez kederim,

Hangi sevgili, neyin, kimin sevgilisi...', 'Hangi sevgili, neyin, kimin sevgilisi, Ateşiyle yakarak, giden, sevgili mi, Böylesi eritip de, bitiren sevgili mi, Hangi sevgili, neyin, kim...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hangi-sevgililer-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdama Karabulut Yağar', 'sevdama-karabulut-yagar-ayhan-altay-1jdi3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '“Sinop’a nükleer santral yapılacak”

ey benim yosun kokulu kentim

sevdalı düşlerinden uyan da bir bak

asfaltı kemiren yeşil otlarına

güzkuşağı gürgen dallarına 

ve 

bıldırcın düşüren gecelere

son bir kez

belki bir daha görmeyeceksin

kuytularında elikleri

dost eli değil bu yalazgan

yarının 

yitik kitaplarda  yazılmasın diyedir feryadımız

görünmez infazlara mahkum olmayasın 

diyedir

dudaklarından zehir akmasın sevdalınıza

sakat çocuklara gebe kalmayasın

diyedir

bu deniz, bu orman, bu çağlayan su

bu Sinop bizim 

diyedir

seni sevdiğimdendir karabasanım

senin yüzünden bu kavga

inceburun inceburun olalı

olduğuna pişman olmadı

olmasın

ölüm bulutları soluyup

kor ateşler bağlamasın sineni

ey benim kotra inceliği taşıyan kentim

kaldır başını 

güç olsun, geç olmasın

anılarıma

ahmakıslatan bir karayel yağsın da

ölüm bulutları yağmasın', '“Sinop’a nükleer santral yapılacak” ey benim yosun kokulu kentim sevdalı düşlerinden uyan da bir bak asfaltı kemiren yeşil otlarına güzkuşağ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Altay']::text[], 8.5, '{"poet":"Ayhan Altay","poet_slug":"ayhan-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sevdama-karabulut-yagar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Pas Tutmaz', 'umut-pas-tutmaz-babur-pinar-4xe00', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kavuşmaların sevinci bir kırmızı gül

oturur güvercin gövdeme

Eser yanaklarımda ilkyaz dirimi pembe

açılır susuz goncalarım benzi kül

Bir el dokunuşu ararım can kapısında

Bekleyişimde kendine yer bulur

saatleri düşman kılan endişe

Susar gün doğuncaya kadar pencere

susar demir kilit

susar gece

Bir çift dost sözüne fit olur 

konuşkan dudaklarım gözaltında

Umut pas tutmaz

Küçük alabalık olurum sığ ırmakta

kıvrak ele avuca sığmaz akarım

Düşer peşime büyük balıklar

Yazgıma dipnot düşer kara intihar

Dostlar bulurum kendime anıları damıtarak

Bir uzun ömürlü servi ağacı gibi 

seyreder suda cemalimi kanarım

Sarsılır dallarım ılık bir sancıyı tadarak

Umut pas tutmaz

Mavzer önüne düşmüş kekliğe benzer

sıçrar sıçrar ve düşer toprağa ömrüm

kan çanağı olur gözlerim

dönmeyeni bekler

lal düşlerde ölürüm

Umut pas tutmaz

Umut pas tutmaz

Yine ben bıkmaz usanmaz

bir amansız bekleyişle gözlerim ufku

eski bir kahramanlık düşer aklıma

Alıp başımı gitmem

Terk etmem yurdu

Ölümün önsözüdür kurşuni ayaz

bir beni bir kendini vurur makama 

Umut pas tutmaz

Sanki gelip geçen şu devingen günler

karanfil ömrümü soldurmaz gibi

bir uzun türküyü bitirmez gibi

umarsız ve telaşla geçip gider

İnsan sevmek ne zormuş meğer', 'Kavuşmaların sevinci bir kırmızı gül oturur güvercin gövdeme Eser yanaklarımda ilkyaz dirimi pembe açılır susuz goncalarım benzi kül Bir el ...', ARRAY['Türk Edebiyatı','Şiir','Babür Pınar']::text[], 8.5, '{"poet":"Babür Pınar","poet_slug":"babur-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/umut-pas-tutmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben de Seni', 'ben-de-seni-efsun-aydin-1ww4q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sade bir törenle olur bizim ayrılığımız

Durgun bir deniz

Saygıda duran sokak köpekleri

Ve bir kaç bildik dostun tesellisi

Masum iki çift göze vurulan damga

Yaralı iki kalp, dikişsiz ameliyatlar

Yükseğe doğru uçan kuşlar 

Bilirim tekrar seni bulmak zor iki gözüm

Ve yine bilirim ki son sözlerimiz hep iki kelimeden ibarettir.

‘’Ben de Seni’’', 'Sade bir törenle olur bizim ayrılığımız Durgun bir deniz Saygıda duran sokak köpekleri Ve bir kaç bildik dostun tesellisi Masum iki çift göz...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ben-de-seni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Aşk', 'sonsuz-ask-ayhan-isin-m0ijk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimi Gönderiyorum Taaaaa Uzaklara

Al Ellerine Bak Nasil Heyecanla Çarpiyor

Seni Gördüğüm Zaman Dünyalar Benim Olacak

Ellerinden Tutacağim 

Gözlerine Bakacağim Mavi Mavi

Gözlerim Senin Olacak 

Senin Gözlerin Benim! 

Sonsuza Kadar Aşik Olacağim 

Her Gün Tutuğun Yürek Senin İçin Atacak

Her Gün İçimde Bir Sızı

Son Gelmesin Diye

Seninle Bir Dakika Bir Saniye Bir An

Sondan Çalinan Bir Nefes

Senin Adini Anacak 

Ölüm Beni Aldiğinda

Kimselere Vermem Ruhumu

Ne Şeytan, Ne Allah Alamaz Onu

Sana Saklayacağim

Ölüm Kapisinda 

Seni Bekleyeceğim

Kalbim Senin

Ruhumu Hediye Edeceğim 

Kalbimin Durduğu Yere

Güzel Ellerine! 

Sonsuza Uçacagiz Birlikte 

Ruhlarimiz Karişacak

Aşklarimiz Karişacak

Sonsuzlukta 

Aşkimiz Anilacak 

Evrenin Son Anina Kadar! 

14-02-2006    Saat11:45', 'Kalbimi Gönderiyorum Taaaaa Uzaklara Al Ellerine Bak Nasil Heyecanla Çarpiyor Seni Gördüğüm Zaman Dünyalar Benim Olacak Ellerinden Tutacağim...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Işın']::text[], 8.5, '{"poet":"Ayhan Işın","poet_slug":"ayhan-isin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sonsuz-ask-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidip de Geleni Yok Gülüm Bee! ! !', 'gidip-de-geleni-yok-gulum-bee-gul-yazganarikan-pqu30', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unutulmaz yüreğine işlediysen bir kere,

Unutulmaz a canım. Unutulmaz be

Ilgıt ılgıt bir rüzgar olur,

Yüreğinde kor olur da 

Ölemezsin bile...

Öyle keskin bir bıçak olur ki sevda

Sıkıysa uyu hele, kapa gözlerini,

Nerdee..

Ne uyku, ne yemek, ne içmek

Canından geçersin de, ondan geçemezsin yine...

Kuru bir bataklığa döner yüreğin a canım.

Bir kış gününde kuş uçmaz kervan geçmez karlı bir dağa döner...

Kurtlar iner gece olunca, uluyarak gönlüne,

Korkarsın, sinersin yine kendi içine...

Isıtırsın kendini, kendi ellerinle...

Yüzün güler mi a canım, gülmez be

Gülse de acı olur tebessüm,

Oturursun bir aynanın önüne,

Sayarsın çizgileri, koparırsın akları,

Yağarsın yağmur gibi kendi kurak iklimine...

Sen sen değilsindir yabancılaşırsın kendine,

Ve yabancıdır aşklar sevdalar dokunuşlar tenine,

Bir bilinmez zamandır ve dönülmez bir yoldur artık vardığın

Dönemezsin a canım, dönemezsin dününe...

Varacağın yer de bir tek sen kalırsın yine seninle...

Bilinmez bir sondur sonrası gidip de geleni yok gülüm bee! ! ! 

Yaşamayı yaşatmayı bildinse Ölmeyen bir sevda kalır senden geriye,', 'Unutulmaz yüreğine işlediysen bir kere, Unutulmaz a canım. Unutulmaz be Ilgıt ılgıt bir rüzgar olur, Yüreğinde kor olur da  Ölemezsin bile.....', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gidip-de-geleni-yok-gulum-bee-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin', 'ellerin-hakki-karadeniz-ehg3v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasretin bir çığ gibi büyümekte sevgili,

Yokluğunda gündüzlerim 

zifiri karanlıktan başka bir şey değil artık.

Tıpkı bir demet papatyaya benzeyen ellerini özledim,

Ve bu papatyaların başımı döndürüp 

beni benden alan kokusunu...', 'Hasretin bir çığ gibi büyümekte sevgili, Yokluğunda gündüzlerim  zifiri karanlıktan başka bir şey değil artık. Tıpkı bir demet papatyaya ben...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Karadeniz']::text[], 8.5, '{"poet":"Hakkı Karadeniz","poet_slug":"hakki-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ellerin-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenmem', 'dilenmem-mehmet-sait-akkus-ng8h4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evim yıkılır evi yeniden yaparım

Yorgun düşersem, uzanır yatarım

Katığım biterse katık dilerim

Param biterse para dilerim

Aşkımı kaybedersem

Aşkı dilemem

Kaybedersem ölmüşüm ben

çünkü

Ölüler aşk dilenemez.', 'Evim yıkılır evi yeniden yaparım Yorgun düşersem, uzanır yatarım Katığım biterse katık dilerim Param biterse para dilerim Aşkımı kaybedersem...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dilenmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 61', 'guncel-beyitler-61-huseyin-avdic-bu4vm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgililer Günü

Sevgililer Günü, sevgiliyi bilmis ve bulmuslarin günü.

Gercek Yâr''i bulanlar icinse, hergün sevgililerin günü.

Berlin, $ubat 2006.', 'Sevgililer Günü Sevgililer Günü, sevgiliyi bilmis ve bulmuslarin günü. Gercek Yâr''i bulanlar icinse, hergün sevgililerin günü. Berlin, $ubat...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'eS gümü', 'es-gumu-bir-mim-kemal-ertugrul-lwrgn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu papaz Valentin

İşte öyle bir adam

Senede bir; 

Düne erken

Yarına geç kalışları hatırlatan...

______________________________

Salt sevgililere değil,sevgili_sizlere de ithaf olunur... :)', 'Şu papaz Valentin İşte öyle bir adam Senede bir;  Düne erken Yarına geç kalışları hatırlatan... ______________________________ Salt sevgilil...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/es-gumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçin İçin Seviyorum', 'i-cin-i-cin-seviyorum-tulay-eker-n0urn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin ortasına düştüğümde, bir yanık tütsü bağrımda adını heceler durur ne seslensem ses olur sesim ne de batan güneş edasındaki

gözlerim görür sabahı  Damıtırım seni karşımda duran hayaline bilirim ki  ak ellerin silerdi kirpiklerimi iki su damlası halimizi oysa 

öyle zor ki seni sensiz yaşamak...

Sinemden yukarı taşıyor gıdımda takılıp kalıyor şah damarımda atıyorsun ha tutsam ölecek uzanıpta dokunamıyorum serap gibi 

gülümsüyorsun baktığın her yerdeyim diyordun ya heryerdesin işte ta şuramda

Gecemin ortasına düştüğümde, seninle kalırım başbaşa,  heryer susar, yok olur, yok olsun da isterim,

sadece sen ve ben kalalım, yanık ezgi sesi yayılsın duvarlardan avuçlarıma, dökülsün har,narında yanayım yeter ki 

sen ol her anımda. 

Gecemin ortasında sana düştüğümde... Sensizlik işlenir her hücereme özleminle, bıçağın iki ucunda gece bilenir dizlerime,

kapaklanırım, gözlerinde kenetlenir gözlerim düşerim sinene işte o zaman bırakırım kendimi... nefeslenirim.

Gecemin ortasında, baharımda, yazımda, kışımda da olsam, ben''im hep diyecek ki...

Sen ensemdeki soluğum... Sen yaşamımdaki katığım...Sen ölümlerle tanıklığımsın.

Sen yaşamımdaki en büyük hediyesin ya seni hiç görmeseydim yeşerirmiydi böyle fidelerim, her sabah güneşim sızarmıydı 

penceremden kadın yanım tanırmıydı kendini aşkın perçeminde, seninle doğan varlığım   için seviyorum seni...

İhanetsiz ve yalansız bir aşkı avuçlarıma bırakan yanınla,alnımdan öpüp, gözlerimde kendini bıraktığın için

seviyorum seni...

Aradığım,tutunduğum, nefessiz kalışlarımda soluklandığım, sevgiyi çıkarsızca sunan 

yüreğin yüreğim olduğu için seviyorum seni...

Yerine kimseyi koyamadığım her çift gözde seni aradığım, her gülüşte gülüşünün sesini özlediğim,

özlemleri özleten olduğun için seviyorum seni...

Hepimiz biryerlerde yaşarız sarılırız içimizdeki yıldızlara, sen benim sarıldığım sarmalandığım,

gecem ve parıldayan yıldızım olduğun için seni seviyorum seni...

Yokluğun ölümlerden ölüm beğenen yanım olsa da acı ile sancılansa  da ruhum,sevgin 

dermanım olduğu için seviyorum seni...

Yaz kış demeden gönlümde çalan sevda telim, sende tutuklu kalmış göğüs kafesim için seviyorum seni...

Yüreğimin dile gelip sustuğu an, gözlerimden kopup, damarlarımda dolaşan ateş olup dizelerimle yüzümde

şahlandığın için seviyorum seni...

Sende ben olmayı sevdim, bende sen olmanı sevdim.Var mı ötesi? Yok işte! 

Seni 

  İçin 

    İçin 

      Yudum 

         Yudum

            Nefes

               Nefes 

                  Seviyorum! ... İçin için SEVİYORUM...', 'Gecenin ortasına düştüğümde, bir yanık tütsü bağrımda adını heceler durur ne seslensem ses olur sesim ne de batan güneş edasındaki gözlerim ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/icin-icin-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seven Gözlerime Bak', 'seven-gozlerime-bak-yusuf-onder-bahceci-axui6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni seviyormu acaba diye sormaya,

Sormaya gerek varmı gözlerime bak.

İstersen inanmıyorsan bir sigara yak,

Haydi durma, seven gözlerime bak.

Diller söylemese bile gözler söylüyor,

Kâlp ise ateşiyle böyle yanıp duruyor,

Sevenler, neden sevdiğini diyemiyor,

Haydi durma, seven gözlerime bak.

Uzakta duruyor ama kalbini biliyorum,

Kalbin seviyorum diyor onu biliyorum,

Görülen rüyaları da, hayra yoruyorum,

Haydi durma, seven gözlerime bak.

Seven sevdiğini görünce lâlmi oluyor,

Kâlbi çok mu çarpıyor, rengi soluyor,

Önder çok sevmiştir be toprak oluyor,

Haydi durma, seven gözlerime bak.', 'Beni seviyormu acaba diye sormaya, Sormaya gerek varmı gözlerime bak. İstersen inanmıyorsan bir sigara yak, Haydi durma, seven gözlerime bak...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seven-gozlerime-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahdamarım', 'sahdamarim-hakki-karadeniz-nt3rp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Var mıdır insana şahdamarından daha yakın olan; 

İnsanın yaşamasını sağlayan şahdamarından

İşte sen,bana şahdamarımdan bile daha yakınsın

İçimdesin,en derinindesin yüreğimin

Bana hayat verensin,aldığım nefes kadar,içtiğim su kadar

ve beynimi ele geçirensin; her hücresine kadar.', 'Var mıdır insana şahdamarından daha yakın olan;  İnsanın yaşamasını sağlayan şahdamarından İşte sen,bana şahdamarımdan bile daha yakınsın İç...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Karadeniz']::text[], 8.5, '{"poet":"Hakkı Karadeniz","poet_slug":"hakki-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sahdamarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapayanlızım', 'yapayanlizim-i-lknur-er-ewsvy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine düştün aklıma

Zamansız

Ellerim kollarım paydos etti

Kalbim çözüldü zincirlerinden

Aklım kaçtı çok uzaklara

Yine düştün aklıma

Alevler içinde yanıyor bedenim

Yinede kalbim kadar acımıyor tenim

Ellerim hasretin koynunda

Sen çok uzaklarda

Yapayanlızım...', 'Yine düştün aklıma Zamansız Ellerim kollarım paydos etti Kalbim çözüldü zincirlerinden Aklım kaçtı çok uzaklara Yine düştün aklıma Alevler i...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yapayanlizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin', 'bilirmisin-mehmet-sait-akkus-fi1un', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilirmisin seni sevmenin acısını

Bilirmisin aşkına yanmanın acısını

Bilirmisin sevdana yanmanın acısını

Bilirmisin seni öylece beklemenin acısını

Bilirmisin her gün döktüğüm göz yaşlarımı

Bilirmisin özlemin hasretini

Bilirmisin

Bilirmisin sensiz geçen günlerimi

Bilirmisin sensiz doğan güneşi

Bilirmisin sensiz batan güneşi

Bilirmisin sensiz geçen hayat akışını

Bilirmisin

Bir başıma kaldığımı

Sevdanı saklı tutmak için

Yumak yapıp koynuma koyduğumu

Sadece ve sadece

Hep öyle kalsın yıpranmasın diye

Bilmen için 

Bilirlerimi sana yolladım

Biliyormusun', 'Bilirmisin seni sevmenin acısını Bilirmisin aşkına yanmanın acısını Bilirmisin sevdana yanmanın acısını Bilirmisin seni öylece beklemenin ac...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilirmisin-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygularım', 'duygularim-savas-dincbas-gp57e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'az önce yanımdan geçtiler

kanatlı bir ata binmiş

duygularım

arkalarından seslendim

ama nafile

duyuramadım sesimi

rüzgar gibi gidiyorlardı

birden panik yaptım

yitirdiğimi sandım duygularımı

ta ki, sen arayıncaya kadar

iyi ki aradın bir tanem

iyi ki aradın

senin yanında olduklarını

tahmin etmeliydim

sık sık yaptıkları gibi

kaybolmaktan korktukları an

sana sığınıyorlar...', 'az önce yanımdan geçtiler kanatlı bir ata binmiş duygularım arkalarından seslendim ama nafile duyuramadım sesimi rüzgar gibi gidiyorlardı bi...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/duygularim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-cemal-yaman-z4klu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu bir şiir

Belki de sihir

Söz, göz,öz

Gel bilmeceyi çöz

Sözcük oyunu, 

Karamanın koyunu

Birkaç kelime, 

Bütün dünya elime

Kim inanır bu filime? 

Düştü gönül aşka

Ne var ki aşktan başka

Olaydı yar olaydı 

Aşk olmasa kolaydı.

İşte hepsi bu...

Bir dolu tepsi bu.

Ayıkla pirincin taşını

Kırma sonra dişini.

Redif, kafiye

Zehir hafiye

Kendini yorma, 

Sorular sorma.

Bu bir şiir

Belki de sihir...', 'Bu bir şiir Belki de sihir Söz, göz,öz Gel bilmeceyi çöz Sözcük oyunu,  Karamanın koyunu Birkaç kelime,  Bütün dünya elime Kim inanır bu fil...', ARRAY['Türk Edebiyatı','Şiir','Cemal Yaman']::text[], 8.5, '{"poet":"Cemal Yaman","poet_slug":"cemal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/siir-149-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Ve Ölüm', 'sevda-ve-olum-cemal-dursun-qkrjy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SEVDA VE ÖLÜM

Bana koşan tüyde bile bir şekil 

Değil ki aşkın büyüsünde bir tılsım bu

Ama hala kahramanlar kadar asil

Yalnızlığımız; 

Dokunulmaz

Ama farkında değiliz; 

Tüm gururumuza rağmen

Bir gün 

Ölümün önünde eğiliriz.

Ben bir güzel sevdim; 

Buğday tenli

Çam yeşili gözleriyle

İnsanı belaya çekerdi,

Ama 

Bilmem ki

Ölüm mü 

Yoksa 

Gülüm mü 

Beni ilk ezerdi bu karanlığımda 

Acep ölsem kalır mıyım bu sıcaklığımda?', 'SEVDA VE ÖLÜM Bana koşan tüyde bile bir şekil  Değil ki aşkın büyüsünde bir tılsım bu Ama hala kahramanlar kadar asil Yalnızlığımız;  Dokunu...', ARRAY['Türk Edebiyatı','Şiir','Cemal Dursun']::text[], 8.5, '{"poet":"Cemal Dursun","poet_slug":"cemal-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevda-ve-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölünesi Kadınlar', 'olunesi-kadinlar-cemal-dursun-h2u86', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ÖLÜNESİ KADINLAR 

Kirli dudaklar

Yalan koksa

Yine sevdam

Kadınlar

Ben yansam, yansam

Yansam kül olsam

Seyretseler 

Söndürmeseler yüreğimi

Yine de kızamam

Gene severim

Gene sevdam onlar

Ölünesi kadınlar', 'ÖLÜNESİ KADINLAR  Kirli dudaklar Yalan koksa Yine sevdam Kadınlar Ben yansam, yansam Yansam kül olsam Seyretseler  Söndürmeseler yüreğimi Yi...', ARRAY['Türk Edebiyatı','Şiir','Cemal Dursun']::text[], 8.5, '{"poet":"Cemal Dursun","poet_slug":"cemal-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olunesi-kadinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklıklar Kar Etmez Sevdama', 'uzakliklar-kar-etmez-sevdama-baran-demir-rdfsn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yok olmak değil 

Elbet senden ayrı olmak

Sevdasız günlerime dair

Sevda çekerken 

Bu güzelim günde

Seni özledim demek 

Sessizce ayıp değil

Ama buna rağmen 

Sevdiğini karşılıksız sevmek

Sana hasret çekmek 

Seni düşünmek

Güzel şey be sevdiğim

Su an yalnızım belki 

Bir başıma 

Ama bil ki sevdam

Yüreğimde içimdesin

Çıkarsız 

Bir sevda sana olan

Acısıyla hasretiyle

Sen den ayrı kalmak değil

Uzakta olsan bedenimden

Ruhumdasın

Okşarcasına

Su an gönlüme düştüğün gibi

Mesafeler kar etmezcesine

Seninleyim her şeyimle

Sevdim seni 

Hiçbir şey beklemeden

Düşündüm 

Duraksayarak

Ne güzel etmişim dedim

Uzakta olsan

Beni düşünmen 

Benim seni düşündüğüm gibi

Beni özlemen 

Benim seni özlediğim gibi

Yüreğimde yer etmen

Yüreğinde yer ettiğim gibi

Bir vucut olacağımız günlerde 

Yakın 

Bir yürek olduğumuz gibi

Düşün ve gülümse

Asma suratını sakın', 'Yok olmak değil  Elbet senden ayrı olmak Sevdasız günlerime dair Sevda çekerken  Bu güzelim günde Seni özledim demek  Sessizce ayıp değil Am...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/uzakliklar-kar-etmez-sevdama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttur Terkedilmişliğimi', 'unuttur-terkedilmisligimi-gul-yazganarikan-4500x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Isıt içimi, hiç olmazsa bugün ısıt beni,

Bir söz, bir bakış, bir gül 

Öyle muhtacım ki...

Al çıkar beni yalnızlığın koynundan

daha sıkı kavra bedenimi Ondan 

Yoruldu başım koluma dayanmaktan

Bir omuz, sıcacık bir omuz ol bana,

Bırak ağlayayım bugün hiç olmazsa

Ve sen sev beni,  ağladıkça

 Bir gün için de olsa unuttur bana Sevgisizliğimi, 

unuttur kimsesizliğimi

Öyle sev ki öyle sar ki beni

Unuttur terkedilmişliğimi.

Ve terketmişliğini...', 'Isıt içimi, hiç olmazsa bugün ısıt beni, Bir söz, bir bakış, bir gül  Öyle muhtacım ki... Al çıkar beni yalnızlığın koynundan daha sıkı kavr...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unuttur-terkedilmisligimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldüğümü Görmeden Git', 'oldugumu-gormeden-git-sahin-erturk-cx9bq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bitsin artık korkularım

Bitsin artık çektiklerim

Hemen şimdi bitirelim

Git ne olursun hemen git

Zincirlerle bağlayamam

Nazlarına katlanamam

Artık sana yalvaramam

Git ne olursun hemen git

Yandığımı görmeden git

Öldüğümü görmeden git

Git ne olursun hemen git

Öldüğümü görmeden git

(14.02.2006-Yeni)', 'Bitsin artık korkularım Bitsin artık çektiklerim Hemen şimdi bitirelim Git ne olursun hemen git Zincirlerle bağlayamam Nazlarına katlanamam ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/oldugumu-gormeden-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Aşksın', 'sen-asksin-cemal-yaman-qc743', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen yoksun

Belki varsın, ama

Aklımda,gönlümde,

Beynimde yoksun.

Kısacası yoksun...

Su  üstünde sürüklenen

Bir petrol köpüğü kadar

Hafif ve boş 

Hissediyorum kendimi

Sen varsın

Eşsiz gözlerinle,

Erişilmez güzelliğinle

Varsın...

Canımdasın, kanımdasın.

İçimdesin, dışımdasın.

Yazımdasın, kışımdasın.

Ekmeğimde, aşımdasın

Bela gibi başımdasın.

Bilmek mutsuzluktur.

Seni seviyorum

Seni biliyorum

Huyun çile çektirmek

Ağlatmak, inletmek

Sürüm sürüm süründürmek

Biliyorum 

Bile bile seviyorum

Aşkı tarife ne hacet

Sen, sen

Aşkın ta kendisisin

Ve ben

Granit taşlar kadar

Ağırlaşıyorum.', 'Sen yoksun Belki varsın, ama Aklımda,gönlümde, Beynimde yoksun. Kısacası yoksun... Su  üstünde sürüklenen Bir petrol köpüğü kadar Hafif ve b...', ARRAY['Türk Edebiyatı','Şiir','Cemal Yaman']::text[], 8.5, '{"poet":"Cemal Yaman","poet_slug":"cemal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sen-asksin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazanda Şair', 'hazanda-sair-munur-atakul-hjiuu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimde son sürgünde bir hazan

Şairim ben ayrılıkları yazan

Kalemim yürektir mürekkebi kan

Dövündükçe taşım taşım dökülür

Beyaz doruklarda şahin uçurdum

Avcı geldi öz yurdumda vuruldum

Kaçak oldum gönüllerden kovuldum

Övündükçe santim santim sökülür

Ömür kemal gönül hazana erdi

İçimde gergide aşkın kemendi

Gençlik yüreğimde tükenmez dendi

Avundukça yaşım yaşım bükülür

Zamanla yaprağın bitmez savaşı

Hazan dedikleri ömrün yavaşı

Çekilir daraba kapanır çarşı

Öykündükçe inim inim çözülür

Adım münür ben şairim hazanda

hesaplar tutmadı geçen mizanda

İçi yakan bir selada,ezanda

Çağrıldıkça adım adım küçülür

06/12/2005 eski resimlere bakarken', 'Yüreğimde son sürgünde bir hazan Şairim ben ayrılıkları yazan Kalemim yürektir mürekkebi kan Dövündükçe taşım taşım dökülür Beyaz doruklarda...', ARRAY['Türk Edebiyatı','Şiir','Münür Atakul']::text[], 8.5, '{"poet":"Münür Atakul","poet_slug":"munur-atakul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hazanda-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-murat-polat-2-lp2kz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gün madem öyle bir gün

Yani birbirine çiçek filan almalar

Bugün madem sevgili günü

Hani birbirine yalan sözler

Büyük aşklar kimden çıkmış bilirmisin

Büyük aşklar ya kimsesiz, ya derin

Bırak imparatorları, hükümdarı

Onlar sevmeyi hiç bilmediler

Ya herkese ve herşeye sahiptiler

Yada aşk diye nice  canları katlettiler

Onlarmı aşkı tadanlar...

Aşk sipariş edilmeyen

Aşk satın alınmayan

Aşk iadesi imkansız

Aşk ölümcül olmalı

İşte aşk o zaman aşk...

                   

                     14 Şubat 2006', 'Bu gün madem öyle bir gün Yani birbirine çiçek filan almalar Bugün madem sevgili günü Hani birbirine yalan sözler Büyük aşklar kimden çıkmış...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-544-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfil ıı', 'karanfil-ii-samiha-i-kbal-2tl4v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ruhumda filizlenmiş bir küçük karanfil

Anlamıyorum ne diyor konuştuğu hangi dil

Anlamak ne duyamıyorum kulağımda kirli el

Bir kurtulsak olaçağız küfre karşı mütiş sel.

Haydi karanfilim serpil serpilde kurtar beni

Büyü büyüyelim yırtalım şu kefeni

Sende büyü,inanç gibi küçük gelsin alemler

Aynı ritimle çarpsın içimizdeki kalpler.

Allah için gel iki kardeş olalım

Sıkı tut bırakma hep böyle kalalım

Umudum sensin benim küçük karanfilim

Çünkü sen bendesin bende seninle beraberim.', 'Ruhumda filizlenmiş bir küçük karanfil Anlamıyorum ne diyor konuştuğu hangi dil Anlamak ne duyamıyorum kulağımda kirli el Bir kurtulsak olaç...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karanfil-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geriye Şiirlerimi Okumak Kaldı', 'geriye-siirlerimi-okumak-kaldi-yusuf-onder-bahceci-53rdc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok sevdiğim sevdadan ne kaldı,

Geriye bir şiirlerimi okumak kaldı,

Okuyup, okuyup ta ağlamak kaldı,

Geriye bir şiirlerimi okumak kaldı.

Bu nasıl sevdadır be yakıyor hâla,

Nasıl oldu gitti, aklım almadı hâla,

Bizi böyle ayıranların ikiside hala,

Geriye bir şiirlerimi okumak kaldı.

Benim bu şiirlerim seveni yakıyor,

Çok sevenler, hep yollara bakıyor,

Sevdiği el elindeyse, nasıl yapıyor,

Geriye bir şiirlerimi okumak kaldı.

Böyle şiirler yazmasam ne olurdu,

Bilki, Önder çoktan toprak olurdu,

İşte o zaman sevdiğim kahrolurdu,

Geriye bir şiirlerimi okumak kaldı...', 'Çok sevdiğim sevdadan ne kaldı, Geriye bir şiirlerimi okumak kaldı, Okuyup, okuyup ta ağlamak kaldı, Geriye bir şiirlerimi okumak kaldı. Bu ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geriye-siirlerimi-okumak-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-yasar-tezel-a4kkl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç gelmeyeceksin sanırdım,

Ağladım,geliverdin

Geçermiş yıllar,bitirdim

Ağladın,geliverdin

Tutamadım, o ellerinden

Hoşgeldin,diyemedim

Gözlerim,gözlerinle meçhule

Hoşgeldin,diyemedim

Bir haftacık kaldı,gidişine

Şaka yaptın,gülüverdin

Bu aşk yağmuru sırılsıklam

Şaka sandın,gülüverdin', 'Hiç gelmeyeceksin sanırdım, Ağladım,geliverdin Geçermiş yıllar,bitirdim Ağladın,geliverdin Tutamadım, o ellerinden Hoşgeldin,diyemedim Gözle...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-gun-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen beni bırakıp burdan giderken', 'sen-beni-birakip-burdan-giderken-ramazan-kayak-w5ksy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne günlerim anlamsız

Ne de gecelerim karabasan olacak

Yağmurlar ıslatacak bedenimi 

Vücudumda yangınlar küllenecek 

Bitecek ömrümdeki hoyrat sevdalar 

Karanfiller yeniden kokacak 

Güneş dünyama bir başka doğacak 

Bedenimde haramilere yer kalmayacak

Dinecek yüreğime inen sızılar 

Kör kuyularda kalmayacak kırılgan kalbim 

Yeniden..

Yeniden ilkbahar gelecek benim ömrüme 

Sen beni bırakıp buradan giderken

Ruhumu kalbinden azat ederken', 'Ne günlerim anlamsız Ne de gecelerim karabasan olacak Yağmurlar ıslatacak bedenimi  Vücudumda yangınlar küllenecek  Bitecek ömrümdeki hoyrat...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-beni-birakip-burdan-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sevdiğimsin...', 'sevdigimsin-i-brahim-ethem-bingul-8d5kq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İsmin sevinç dilime

Heyecansın kalbime

Susamış yüreğime

Sen su gibi azizsin...

İyi gün, kötü günde

Her sevinçte, kederde

İnandığım kaderde

Aşkım, gök mavilimsin...

Her solukta nefesim

Bana en güzel isim

Sevdim seni her mevsim

Güneşim, sevdiğimsin...

www.iebingul.com', 'İsmin sevinç dilime Heyecansın kalbime Susamış yüreğime Sen su gibi azizsin... İyi gün, kötü günde Her sevinçte, kederde İnandığım kaderde A...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdigimsin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Şubat', '14-subat-ferit-gursoy-5r2lv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne limanlarda

gidene el salladım

Ne de otobüs terminalinde

Gidenin arkasından 

Ağladım

Ne de garlarda hayaliyle 

Sabahladım

Hiç sevenim olmadı 

Gönlüm hiç dolmadı

Aşkta acı,

Aşkta ayrılık,

Aşkta gözyaşı,

Aşkta ihanet,

Var diye hep kaçtım

Ama...

Bugün 14 Şubat

İçimde ürperti vede yalnızlık

Hayatımda ilk defa

Keşke dedim

Keşke...

              Ferit Gürsoy 14.02.2006', 'Ne limanlarda gidene el salladım Ne de otobüs terminalinde Gidenin arkasından  Ağladım Ne de garlarda hayaliyle  Sabahladım Hiç sevenim olma...', ARRAY['Türk Edebiyatı','Şiir','Ferit Gürsoy']::text[], 8.5, '{"poet":"Ferit Gürsoy","poet_slug":"ferit-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/14-subat-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâbil Olma Hâbil Ol', 'k-bil-olma-h-bil-ol-yusuf-onder-bahceci-e5ahx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kâbil, Hâbili öldürmüş bil,

Sen Kâbil olma, ol Hâbil,

Masumlar Cennete gider,

Sen Kâbil olma, ol Hâbil.

Fitne, fesat insanla başlar,

İnsan beşer, şaşar, şaşar,

Allah diyenin, kâlbi yaşar,

Sen Kâbil olma, ol Hâbil.

Dünya''da haram işleyene,

Çaldığı malı gümüşleyene,

İstersen soralım bilenlere,

Sen Kâbil olma, ol Hâbil.

Hâbil masum idi, Cennete,

Kâbil cahil idi Cehenneme,

Hangi tarafsın beni ademe,

Sen Kâbil olma, ol Hâbil....', 'Kâbil, Hâbili öldürmüş bil, Sen Kâbil olma, ol Hâbil, Masumlar Cennete gider, Sen Kâbil olma, ol Hâbil. Fitne, fesat insanla başlar, İnsan b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kabil-olma-habil-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hem kolay hem de zor', 'hem-kolay-hem-de-zor-tevfik-karinca-3qrqg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaçınılmazların

Yaşanacağı gün var muhakkak

Buna kader demek aptallık ancak

En derine girdiğinde o keskin bıçak

Dönülmez yolun sonu geldi demek

Yok bundan kaçmak

En acısı ne biliyormusun

Sorgusuz sualsiz

Hesapsız hatta kitapsız

Katlanmak

Sen alıştırdın beni 

Olmayacak hayalleri kurmaya

Ardından her yaşadığım hüsranda

Saçımı başımı yolmaya

Nerden girdik bu dipsiz kuyuya

En acısı da bu ya

Hesap kapkara bir mizan

Çözmek  zor tutturmak zor

Hüznün neşesi olmaz

Ne yapsak ne etsek

Bu sevda gönül tasını doldurmaz

Gitmek zor bırakmak zor

Dönerken kendince dünya

Oturtmuş oturtan yüce nizama

Suyun yolu akışkan mezra

Tutmak zor döndürmek zor

Seni çok sevmek yetmiyor

İstemekle istenen olmuyor

Gitmek istersen

Sevdiğini bileyim yeter

Gitmek kolay dönmek zor

Seninle çıkmadık mı bu yola

Yorulduk istemesek te

Çaylar şirketten nasıl olsa

Verelim bir mola

Ne şahitler kaldı

Ne nihakımızı kıyan hoca

Sözler verdik 

Tutmamak olmaz dönmek olmaz

Eledim unumu astım eleğimi

Kapadım artık gönül defterimi

Düşümde gördüm azraili

Yaşamak hem güzel hem de zor

Nerden girdik bu dipsiz kuyuya

En acısı da bu ya

Hesap kapkara bir mizan

Çözmek zor tutturmak zor', 'Kaçınılmazların Yaşanacağı gün var muhakkak Buna kader demek aptallık ancak En derine girdiğinde o keskin bıçak Dönülmez yolun sonu geldi de...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/hem-kolay-hem-de-zor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler-39', 'guzel-sozler-39-huseyin-erdogan-rtfmk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Yer yüzünde,en büyük yalancılar ve riyakarlar sevmediği halde seviyorum diyenlerdir...Oysa,kainattaki,en tehlikeli salgın hastalık ise sevgisizliktir...Bu nedenle,sevmek ve sevilmek fiillerini ezberlemek,yüceltmek ve de kıymetini doruklarda bilmek gerekir...''

                                                                                             14.02.2006

                                                                                         Hüseyin Erdoğan

''Seviyorsan eğer,sevdiğini sık,sık söyle...Ancak sevmek fiili bu şekilde bulur değer...Sakın,sonra üzülerek deme ki şair sen haklıymışsın,söylemek gerekirmiş meğer...''

                                                                                        14.02.2006

                                                                                    Hüseyin Erdoğan', '''Yer yüzünde,en büyük yalancılar ve riyakarlar sevmediği halde seviyorum diyenlerdir...Oysa,kainattaki,en tehlikeli salgın hastalık ise sevg...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/guzel-sozler-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'U/Yar/Im', 'u-yar-im-bahri-yildirim-036uf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu değildi

Bu değildi,senden istediğim

Böyle değildi sevda

Ben  senden,seni istedim

Düşlerimi öldürüp,gitmeni değil

Düşlerimi:

Gerçelklere çevirmendi beklediğim

Oysa ne de çabuk

Duman oldu sevdalarım

Yaktığın ateşler sönmez artık

Çaresiz gidiyorum

Yolum uzun

Yolum çetin,biliyorum

Yola çıkmak zamanıdır

Gelivermeden akşam

Belki hiç bir şey kalmaz benden

Sabaha çıkarsam', 'Bu değildi Bu değildi,senden istediğim Böyle değildi sevda Ben  senden,seni istedim Düşlerimi öldürüp,gitmeni değil Düşlerimi: Gerçelklere ç...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/u-yar-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha kaç 14 şubat geçer,', 'daha-kac-14-subat-gecer-husnu-celebi-3jj1s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soğuk bir şubat,

Karın yağdığı,

İçimde sevdiğimin sıcaklığı,

Vazomda yalnız bir orkide,

Bir sen,

Bir sevgin kalbimde…

Hayat kısa,

Yollar uzun olurmuş, 

Seven,

Sevdiğini her an solurmuş, 

Seven insan,

Bir başkası olurmuş, 

Bir sen,

Bir sevgin yüreğimde…

Ben seni bir 14 şubat da değil

Her gün andım,

Her gün hatırladım

Ben sana bir 14 şubat da değil

Her zaman,

Kalbimi mükafat verdim…

Sevgide mükafat olmaz, 

Versen bile seven almaz, 

Senden başka kimse bilmez, 

Kıblem aşktır,

Kâbem sensin benim.

Kim bilir,

Daha kaç 14 şubat geçer,

Sevenler gün gelir

Muradına erer,

Yanında olamamak

Ölümden beter,

Elbet bir gün,

Buda gelir, buda geçer…

Sen keskin nefessin

Vücudumda, 

Sen açan çiçeksin

Issız dağlarımda, 

Sen yağmursun

Göz pınarlarımda, 

Canım Sevgilim,

Bu anlamlı günün kutlu olsun…

14.02.2006   İSTANBUL', 'Soğuk bir şubat, Karın yağdığı, İçimde sevdiğimin sıcaklığı, Vazomda yalnız bir orkide, Bir sen, Bir sevgin kalbimde… Hayat kısa, Yollar uzu...', ARRAY['Türk Edebiyatı','Şiir','Hüsnü Çelebi']::text[], 8.5, '{"poet":"Hüsnü Çelebi","poet_slug":"husnu-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/daha-kac-14-subat-gecer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsana', 'i-nsana-yasar-tezel-9edc9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgiler var

