INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarış', 'yaris-nevzat-ozkan-4334b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'başrollerde favori atlar,

kimi ingiliz kimi arap.

hipodromda gösteriler

padokta başlar.

perdeyle birlikte

elde altılılar,bahisler,ikililer

nefesler tutulur,

kamçılar yavaşça yerlerini bulur.

jokeyler atlara sevdalanır,

farklar boydan boyuna 

boyundan buruna iner.

son dönemeçte

alkışlar yuhlara karışır,

hipodram uğultu ile sarsılır.

kuponlar yırtılır

umutlar bir sonraki yarışa kalır.

burun farkı ile ipi göğüsler,

figüran eküriler.', 'başrollerde favori atlar, kimi ingiliz kimi arap. hipodromda gösteriler padokta başlar. perdeyle birlikte elde altılılar,bahisler,ikililer n...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Özkan']::text[], 8.5, '{"poet":"Nevzat Özkan","poet_slug":"nevzat-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yaris-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 63', 'guncel-beyitler-63-huseyin-avdic-p7vqq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son Bulur O Zaman A$kin Elemi

