INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgelerde güneş olmaz', 'golgelerde-gunes-olmaz-selcen-boyar-yrpeq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollar uzak gelemezsin,

Aşk bir tuzak çekemezsin,

Gölgelerde güneş olmaz,

Güneş gökde değemezsin.

Yaşadığım korkularımı,

Kovsanda gönderemezsin,

Sevgiler bilinmezliğe açmış kollarını,

Sevsen de döndüremezsin.

Aynaya her baktığımda,

Sevgini görüyorum,

Karanlık dehlizlerde,

Her an seninle güne yeniden,

doğuyorum,

Bu imkansız aşkı 

Her gün yeniden,

Yeniden seninle yaşıyorum.', 'Yollar uzak gelemezsin, Aşk bir tuzak çekemezsin, Gölgelerde güneş olmaz, Güneş gökde değemezsin. Yaşadığım korkularımı, Kovsanda gönderemez...', ARRAY['Türk Edebiyatı','Şiir','Selcen Boyar']::text[], 8.5, '{"poet":"Selcen Boyar","poet_slug":"selcen-boyar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/golgelerde-gunes-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 64', 'guncel-beyitler-64-huseyin-avdic-nlidq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sigortasiz A$k

