INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 65', 'guncel-beyitler-65-huseyin-avdic-261tk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevginin Ölcüsü

''Allah icin sevmek''tir, sevginin dogru, gercek ölcüsü.

''Merhametsiz azap cekmek''tir, ölcüsüz sevmenin sonucu.

Berlin, $ubat 2006.', 'Sevginin Ölcüsü ''Allah icin sevmek''tir, sevginin dogru, gercek ölcüsü. ''Merhametsiz azap cekmek''tir, ölcüsüz sevmenin sonucu. Berlin, $ubat ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Sen Değilsin', 'tek-sen-degilsin-mehmet-lutfu-aydin-nk92q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanma ki tek sensin, aşkın esiri

Zincire vurulmuş yürekler sebil

Silinir zamanla, inan tesiri

Yasını gömmeye, kürekler sebil

Zincirin bir ucu uzanır sana

Duyarım sesini ah eden bana

Yaradan ne senden ne benden yana

Ezelden bel veren direkler sebil

Aşığın dağında kar buz erimez

Sevdikçe gözünü nefret bürümez

Mazlumun yanında zalim yürümez

Ustanın ardında çıraklar sebil

Gelecek ne senin ne geçmiş benim

Kararır uğruna bembeyaz tenim

Kırılır kırk  yerden, naçiz bedenim

Sevdanın yolunda duraklar sebil

Derdimin dermanı sensin bilirim

Çağırsan, zinciri kırar gelirim

Desem ki, dilersen hemen ölürüm

Canımı almaya oraklar sebil', 'Sanma ki tek sensin, aşkın esiri Zincire vurulmuş yürekler sebil Silinir zamanla, inan tesiri Yasını gömmeye, kürekler sebil Zincirin bir uc...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tek-sen-degilsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 66', 'guncel-beyitler-66-huseyin-avdic-mh4lk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Gercek A$ki Bulanlarin Slogani) 

Hep birlikte diyelim:

A$k, a$k, a$k! Ya$asin, ya$asin! 

Ya$asin a$k, kahrolmasin! 

Berlin, $ubat 2006.', '(Gercek A$ki Bulanlarin Slogani)  Hep birlikte diyelim: A$k, a$k, a$k! Ya$asin, ya$asin!  Ya$asin a$k, kahrolmasin!  Berlin, $ubat 2006....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/guncel-beyitler-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
