INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ele Veriyor', 'ele-veriyor-zeynal-yaman-1h8a1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ele veriyor ele veriyor

Bu sözler beni ele veriyor

Bâzen akla rehber olur gönül

Bâzen de aklı yele veriyor

Bak şu dünyanın tuhaf işine

Ne işleri ne ele veriyor...

1995', 'Ele veriyor ele veriyor Bu sözler beni ele veriyor Bâzen akla rehber olur gönül Bâzen de aklı yele veriyor Bak şu dünyanın tuhaf işine Ne iş...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ele-veriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâinat', 'k-inat-zeynal-yaman-rbxyc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu kâinatın her zerresini kuşatmış Allah

