INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maya Kaldı', 'maya-kaldi-yasar-tezel-agmdm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Samanlıkta gizli kaldı

Sevdiğimle onun adı

Bu işin ne tadı  kaldı

Ne de tuzu kaldı

Ayrılık bahaneymiş,

Seven gönüle

Sevdası gitti,adı kaldı

Gönül denizim di

Deniz gitti göl kaldı', 'Samanlıkta gizli kaldı Sevdiğimle onun adı Bu işin ne tadı  kaldı Ne de tuzu kaldı Ayrılık bahaneymiş, Seven gönüle Sevdası gitti,adı kaldı ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/maya-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-i-brahim-ugur-toprak-qyhun', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen,

Gitmek için kalmak gerek

Gitmek izteyene yol vererek! ...

10 Şubat 06

İzmir', 'Bazen, Gitmek için kalmak gerek Gitmek izteyene yol vererek! ... 10 Şubat 06 İzmir...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bazen-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeş Olun 1', 'kardes-olun-1-zeynal-yaman-ugeu3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkın odu yakar oldu

Kalpten dile akar oldu

Uymayanlar nâçar oldu

Dövüşmeyin kardeş olun! 

Hakk yaratmış bilin diye

Eserimi sevin diye

Güvenilir emin diye

Dövüşmeyin kardeş olun! 

Soyu sopu böle böle

Tükeniriz öle öle

Yeter artık döndük çöle

Dövüşmeyin kardeş olun! 

Eğil nefret dağı eğil

Yüce Rabbim hoşnut değil

Biter elbet birgün mehil

Dövüşmeyin kardeş olun! 

Zeynel söze ver nihayet

Kardeş olun diyor ayet

Dinlerseniz beni şayet

Dövüşmeyin kardeş olun! 

1996', 'Aşkın odu yakar oldu Kalpten dile akar oldu Uymayanlar nâçar oldu Dövüşmeyin kardeş olun!  Hakk yaratmış bilin diye Eserimi sevin diye Güven...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kardes-olun-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntizar', 'i-ntizar-yasar-tezel-rkf1z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yakma dur

