INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Seviyormusun', 'beni-seviyormusun-adnan-durdagi-0lf2w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönlümün ovasında kur yapıp uçuyorsun

Dalmışsın hülyalara kendinden geçiyorsun

Aşkımın yuvasında badeden içiyorsun

Söyle bana güzelim beni seviyormusun

Manalı bakışların öldürüyor bil beni

Sevginin tımarıyla okşa süpür sil beni

Seversen canım kurban parçalara böl beni

Söyle bana güzelim beni seviyormusun

Sessiz sessiz ağlarım kurudu göz pınarım

Sevgine ben sadığım koskoca bir çınarım

Ateşinle kavruldum içten içe yanarım

Söyle bana güzelim beni seviyormusun

Filizlenip yeşeren bu şarkıda sen varsın

Gönlümdeki sultanım hayalimdeki yarsın

Yalvarırım yok deme ne olur gönlüm sarsın

Söyle bana güzelim beni seviyormusun

Ördün gönül ağını bağladın aşk bağını

Çektiklerim yetmedi yükledin lav dağını

Ateşledin sönmüyor Adnan''ın ocağını

Söyle bana güzelim beni seviyormusun', 'Gönlümün ovasında kur yapıp uçuyorsun Dalmışsın hülyalara kendinden geçiyorsun Aşkımın yuvasında badeden içiyorsun Söyle bana güzelim beni s...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durdağı']::text[], 8.5, '{"poet":"Adnan Durdağı","poet_slug":"adnan-durdagi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beni-seviyormusun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mağrurun Doğuşu', 'magrurun-dogusu-guler-ilgaz-6oeh7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki nehirdik menekşe gözlüm

Birbirimize aktığımızı

Sularımız birleştiğinde anladık

Büyüdük nehir gözlüm

Büyüdük çoğaldık

Çağladık coştuk ve mağruru doğurduk

Birlikte yenilendik yeniden menekşe gözlüm

Okyanusla buluşunca

Özledik pınarı

Hissettik bakınca gözlerimize

İki nehirdik menekşe gözlüm

Birbirimize aktığımızı

Sularımız birleştiğinde anladık

Aynı pınardan fışkıran

İki damla gözyaşıydık aslında', 'İki nehirdik menekşe gözlüm Birbirimize aktığımızı Sularımız birleştiğinde anladık Büyüdük nehir gözlüm Büyüdük çoğaldık Çağladık coştuk ve ...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/magrurun-dogusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
